--
-- Name: commerce_delivery_contact_resolve_v1(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commerce_delivery_contact_resolve_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $_$
  WITH input AS (
    SELECT coalesce(p_input, '{}'::jsonb) AS value
  ), facts AS (
    SELECT
      value,
      coalesce((value->>'frozenContactPresent')::boolean, false) AS frozen_present,
      coalesce((value->>'orderCanonicalPresent')::boolean, false) AS order_canonical_present,
      value->'frozenContact' AS frozen_contact,
      value->'channelOrderSnapshot' AS channel_snapshot,
      coalesce(value->'selectedDeliveryCandidates', '[]'::jsonb) AS selected_delivery_candidates,
      coalesce(value->'recipientCandidates', '[]'::jsonb) AS recipient_candidates,
      coalesce(value->'phoneCandidates', '[]'::jsonb) AS phone_candidates,
      value->>'legacyClientEmail' AS legacy_client_email,
      value->>'line1' AS line1,
      value->>'line2' AS line2,
      value->>'city' AS city,
      value->>'postalCode' AS postal_code,
      value->>'country' AS country,
      value->>'deliveryInstructions' AS delivery_instructions,
      value->>'courierInstructions' AS courier_instructions
    FROM input
  ), choices AS (
    SELECT facts.*,
      (
        SELECT candidate.value
        FROM jsonb_array_elements(facts.selected_delivery_candidates) AS candidate(value)
        WHERE jsonb_typeof(candidate.value) = 'object'
        LIMIT 1
      ) AS selected_delivery,
      (
        SELECT nullif(btrim(candidate.value), '')
        FROM jsonb_array_elements_text(facts.recipient_candidates) AS candidate(value)
        WHERE nullif(btrim(candidate.value), '') IS NOT NULL
        LIMIT 1
      ) AS recipient_name,
      (
        SELECT nullif(btrim(candidate.value), '')
        FROM jsonb_array_elements_text(facts.phone_candidates) AS candidate(value)
        WHERE nullif(btrim(candidate.value), '') IS NOT NULL
        LIMIT 1
      ) AS contact_phone
    FROM facts
  ), contacts AS (
    SELECT choices.*,
      CASE
        WHEN frozen_present THEN frozen_contact
        WHEN jsonb_typeof(channel_snapshot) = 'object' THEN jsonb_build_object(
          'schemaVersion', 1,
          'source', 'channel_order_snapshot',
          'revision', 1,
          'recipientName', nullif(btrim(channel_snapshot #>> '{shipTo,recipientName}'), ''),
          'contactEmail', nullif(btrim(lower(channel_snapshot #>> '{buyer,email}')), ''),
          'contactPhone', coalesce(
            nullif(btrim(channel_snapshot #>> '{shipTo,phone}'), ''),
            nullif(btrim(channel_snapshot #>> '{buyer,phone}'), '')
          ),
          'line1', channel_snapshot #>> '{shipTo,line1}',
          'line2', nullif(btrim(channel_snapshot #>> '{shipTo,line2}'), ''),
          'city', channel_snapshot #>> '{shipTo,city}',
          'postalCode', channel_snapshot #>> '{shipTo,postalCode}',
          'country', upper(channel_snapshot #>> '{shipTo,countryCode}'),
          'selectedDelivery', selected_delivery,
          'deliveryInstructions', NULL,
          'courierInstructions', NULL
        )
        ELSE jsonb_build_object(
          'schemaVersion', 1,
          'source', 'legacy_inferred',
          'revision', 1,
          'recipientName', recipient_name,
          'contactEmail', CASE
            WHEN lower(coalesce(legacy_client_email, '')) LIKE '%.invalid' THEN NULL
            ELSE nullif(btrim(lower(legacy_client_email)), '')
          END,
          'contactPhone', contact_phone,
          'line1', line1,
          'line2', nullif(btrim(line2), ''),
          'city', city,
          'postalCode', postal_code,
          'country', country,
          'selectedDelivery', selected_delivery,
          'deliveryInstructions', delivery_instructions,
          'courierInstructions', courier_instructions
        )
      END AS contact
    FROM choices
  ), evaluated AS (
    SELECT contacts.*,
      jsonb_typeof(contact) = 'object'
        AND contact->>'schemaVersion' = '1'
        AND coalesce(contact->>'revision', '') ~ '^[1-9][0-9]*$'
        AND nullif(btrim(contact->>'source'), '') IS NOT NULL
        AND nullif(btrim(contact->>'line1'), '') IS NOT NULL
        AND nullif(btrim(contact->>'city'), '') IS NOT NULL
        AND nullif(btrim(contact->>'postalCode'), '') IS NOT NULL
        AND nullif(btrim(contact->>'country'), '') IS NOT NULL AS destination_complete,
      jsonb_typeof(contact) = 'object'
        AND nullif(btrim(contact->>'recipientName'), '') IS NOT NULL
        AND nullif(btrim(contact->>'contactPhone'), '') IS NOT NULL AS recipient_and_phone_complete
    FROM contacts
  )
  SELECT jsonb_build_object(
    'resolutionVersion', 1,
    'disposition', CASE
      WHEN frozen_present AND jsonb_typeof(frozen_contact) <> 'object' THEN 'frozen_malformed'
      WHEN frozen_present AND destination_complete AND recipient_and_phone_complete THEN 'frozen_complete'
      WHEN frozen_present THEN 'frozen_incomplete'
      WHEN order_canonical_present THEN 'order_canonical_without_frozen'
      WHEN destination_complete AND recipient_and_phone_complete THEN 'inferred_complete'
      ELSE 'inferred_incomplete'
    END,
    'contact', CASE WHEN jsonb_typeof(contact) = 'object' THEN contact ELSE 'null'::jsonb END,
    'destinationComplete', destination_complete,
    'carrierComplete', destination_complete AND recipient_and_phone_complete
  )
  FROM evaluated;
$_$;


--
-- Name: commerce_fence_promotion_inventory_reservation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commerce_fence_promotion_inventory_reservation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
BEGIN
  IF NEW.order_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders orders
   WHERE orders.id = NEW.order_id
   FOR KEY SHARE;

  IF FOUND
    AND v_order.metadata->>'promotionEngineVersion' = 'promotion-engine.v2'
    AND v_order.status NOT IN ('draft', 'pending_payment', 'paid')
  THEN
    RAISE EXCEPTION 'promotion_inventory_order_not_reservable'
      USING ERRCODE = '40001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_fence_promotion_inventory_reservation(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.commerce_fence_promotion_inventory_reservation() IS 'Serializes v2 promotion inventory insertion against guarded cancellation and rejects a reservation that arrives after the order became terminal.';


--
-- Name: commerce_fulfillment_legacy_command_status(text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commerce_fulfillment_legacy_command_status(p_request_fingerprint text, p_dispatch_status text, p_provider_order_id text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  SELECT CASE
    WHEN p_request_fingerprint !~ '^[a-f0-9]{64}$' THEN 'manual_review'
    WHEN p_dispatch_status='created' AND p_provider_order_id IS NOT NULL THEN 'confirmed'
    WHEN p_dispatch_status='failed' THEN 'manual_review'
    ELSE 'uncertain'
  END
$_$;


