--
-- Name: commerce_fulfillment_provider_command_transition_allowed(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commerce_fulfillment_provider_command_transition_allowed(p_from text, p_to text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT (p_from = 'queued' AND p_to IN ('claimed', 'cancelled'))
      OR (p_from = 'claimed' AND p_to IN ('queued', 'retry_wait', 'cancelled', 'submitting', 'manual_review'))
      OR (p_from = 'submitting' AND p_to IN ('accepted', 'retry_wait', 'uncertain', 'manual_review', 'terminal_rejected'))
      OR (p_from = 'accepted' AND p_to IN ('confirmed', 'uncertain'))
      OR (p_from = 'retry_wait' AND p_to IN ('claimed', 'cancelled'))
      OR (p_from = 'uncertain' AND p_to IN ('accepted', 'confirmed', 'retry_wait', 'manual_review'))
      OR (p_from = 'manual_review' AND p_to IN ('confirmed', 'retry_wait', 'terminal_rejected', 'cancelled'));
$$;


--
-- Name: commerce_promotion_code_claim_checked(uuid, uuid, integer, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commerce_promotion_code_claim_checked(p_code_id uuid, p_order_id uuid, p_expected_revision integer, p_expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval)) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_code public.promotion_codes%ROWTYPE;
  v_claim public.promotion_code_claims%ROWTYPE;
  v_client_id uuid;
  v_global bigint;
  v_customer bigint;
BEGIN
  SELECT orders.* INTO v_order
    FROM public.commerce_orders orders
   WHERE orders.id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'promotion_code_order_not_found' USING ERRCODE = 'P0002';
  END IF;
  v_client_id := v_order.client_id;

  SELECT * INTO v_code
    FROM public.promotion_codes codes
   WHERE codes.id = p_code_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'promotion_code_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF p_expected_revision IS NOT NULL AND v_code.revision <> p_expected_revision THEN
    RAISE EXCEPTION 'promotion_code_definition_changed' USING ERRCODE = '40001';
  END IF;

  SELECT * INTO v_claim
    FROM public.promotion_code_claims claims
   WHERE claims.promotion_code_id = p_code_id
     AND claims.order_id = p_order_id
   FOR UPDATE;
  IF FOUND AND v_claim.client_id IS DISTINCT FROM v_client_id THEN
    RAISE EXCEPTION 'promotion_code_claim_owner_conflict' USING ERRCODE = '23505';
  END IF;
  IF FOUND AND v_claim.status = 'redeemed' THEN
    RETURN jsonb_build_object('claimId', v_claim.id, 'status', v_claim.status, 'idempotent', true);
  END IF;
  IF v_order.status IN ('paid', 'cancelled', 'failed', 'expired', 'refunded',
    'fulfillment_pending', 'fulfilled') THEN
    RAISE EXCEPTION 'promotion_code_order_not_claimable' USING ERRCODE = '40001';
  END IF;
  IF FOUND AND v_claim.status = 'reserved' THEN
    RETURN jsonb_build_object('claimId', v_claim.id, 'status', v_claim.status, 'idempotent', true);
  END IF;

  IF v_code.status <> 'active' OR v_code.valid_from > now()
    OR (v_code.valid_to IS NOT NULL AND v_code.valid_to <= now()) THEN
    RAISE EXCEPTION 'promotion_code_not_active' USING ERRCODE = '40001';
  END IF;
  IF v_code.redemption_limit_per_customer IS NOT NULL AND v_client_id IS NULL THEN
    RAISE EXCEPTION 'promotion_code_client_required' USING ERRCODE = '22023';
  END IF;

  SELECT count(*) INTO v_global
    FROM public.promotion_code_claims claims
   WHERE claims.promotion_code_id = p_code_id
     AND claims.status IN ('reserved', 'redeemed');
  IF v_code.redemption_limit_global IS NOT NULL AND v_global >= v_code.redemption_limit_global THEN
    RAISE EXCEPTION 'promotion_code_global_limit_reached' USING ERRCODE = '40001';
  END IF;

  SELECT count(*) INTO v_customer
    FROM public.promotion_code_claims claims
   WHERE claims.promotion_code_id = p_code_id
     AND claims.client_id = v_client_id
     AND claims.status IN ('reserved', 'redeemed');
  IF v_code.redemption_limit_per_customer IS NOT NULL
    AND v_customer >= v_code.redemption_limit_per_customer THEN
    RAISE EXCEPTION 'promotion_code_customer_limit_reached' USING ERRCODE = '40001';
  END IF;

  IF v_claim.id IS NULL THEN
    INSERT INTO public.promotion_code_claims (
      promotion_code_id, order_id, client_id, status, expires_at
    ) VALUES (
      p_code_id, p_order_id, v_client_id, 'reserved', p_expires_at
    ) RETURNING * INTO v_claim;
  ELSE
    UPDATE public.promotion_code_claims
       SET status = 'reserved', reserved_at = now(), expires_at = p_expires_at,
           redeemed_at = NULL, released_at = NULL, release_reason = NULL,
           updated_at = now()
     WHERE id = v_claim.id
     RETURNING * INTO v_claim;
  END IF;
  RETURN jsonb_build_object('claimId', v_claim.id, 'status', 'reserved', 'idempotent', false);
END;
$$;


--
-- Name: commerce_promotion_definition_fingerprint(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commerce_promotion_definition_fingerprint(p_code_id uuid, p_promotion_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT encode(sha256(convert_to(concat_ws('|',
    'promotion-definition.v2', binding.promotion_code_id::text,
    array_to_string(ARRAY(SELECT scope FROM unnest(code.scopes) scope ORDER BY scope), ','),
    code.minimum_reference_minor::text,
    promotion.id::text, binding.lane, promotion.promotion_engine_version,
    promotion.benefit_lane, promotion.benefit_kind,
    coalesce(promotion.benefit_value_bps::text, ''),
    coalesce(promotion.benefit_value_minor::text, '')
  ), 'UTF8')), 'hex')
    FROM public.promotion_code_bindings binding
    JOIN public.promotion_codes code ON code.id = binding.promotion_code_id
    JOIN public.promotions promotion ON promotion.id = binding.promotion_id
   WHERE binding.promotion_code_id = p_code_id
     AND binding.promotion_id = p_promotion_id
$$;


--
-- Name: email_send_function_base_url(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.email_send_function_base_url() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'pg_catalog'
    AS $_$
DECLARE
  v_base_url text;
  v_is_expected_production boolean := false;
BEGIN
  BEGIN
    v_is_expected_production := private.external_cron_is_enabled();
  EXCEPTION WHEN OTHERS THEN
    v_is_expected_production := false;
  END;

  SELECT NULLIF(BTRIM(functions_base_url), '')
    INTO v_base_url
    FROM private.email_runtime_environment
   WHERE id = true
     AND reward_confirmation_enabled = true;

  IF v_base_url IS NULL THEN
    RETURN NULL;
  END IF;

  v_base_url := regexp_replace(v_base_url, '/+$', '');

  IF NOT v_is_expected_production
     AND v_base_url = 'https://tsrqponmlkjihgfedcba.supabase.co/functions/v1' THEN
    RETURN NULL;
  END IF;

  RETURN v_base_url;
END;
$_$;


--
-- Name: external_cron_is_enabled(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.external_cron_is_enabled() RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'private', 'pg_catalog'
    AS $$
  SELECT COALESCE((
    SELECT
      NULLIF(current_setting('app.openlup_abandoned_cart_runtime_url', true), '') IS NOT NULL
      AND env.expected_abandoned_cart_runtime_url = rtrim(
        current_setting('app.openlup_abandoned_cart_runtime_url', true),
        '/'
      )
    FROM private.platform_cron_environment AS env
    WHERE env.id = true
  ), false);
$$;


--
-- Name: guard_promotion_code_claim_event_append_only(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_promotion_code_claim_event_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF current_setting('openlup.preview_promotion_claim_event_cleanup', true) = 'on'
    AND NOT private.production_database_fingerprint_matches()
  THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'promotion_code_claim_event_append_only' USING ERRCODE = '55000';
END;
$$;


--
-- Name: FUNCTION guard_promotion_code_claim_event_append_only(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.guard_promotion_code_claim_event_append_only() IS 'Rejects UPDATE and DELETE except inside the service-role preview cleanup function on a database that does not match the production fingerprint.';


--
-- Name: inventory_reserved_balance_recount_targets(timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.inventory_reserved_balance_recount_targets(p_now timestamp with time zone) RETURNS TABLE(balance_id uuid, sku_id uuid, location_id uuid, lot_id uuid, on_hand integer, balance_reserved integer, expected_reserved integer, active_reserved integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT
    b.id,
    b.sku_id,
    b.location_id,
    b.lot_id,
    b.on_hand,
    b.reserved,
    coalesce(r.total_reserved, 0),
    coalesce(r.active_reserved, 0)
  FROM public.inventory_balances b
  LEFT JOIN LATERAL (
    SELECT
      coalesce(sum(res.quantity), 0)::integer AS total_reserved,
      coalesce(sum(res.quantity) FILTER (
        WHERE res.expires_at IS NULL OR res.expires_at > p_now
      ), 0)::integer AS active_reserved
    FROM public.inventory_reservations res
    WHERE res.sku_id = b.sku_id
      AND res.location_id = b.location_id
      AND res.lot_key = b.lot_key
      AND res.status = 'reserved'
  ) r ON true
  WHERE b.reserved IS DISTINCT FROM coalesce(r.total_reserved, 0);
$$;


--
-- Name: FUNCTION inventory_reserved_balance_recount_targets(p_now timestamp with time zone); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.inventory_reserved_balance_recount_targets(p_now timestamp with time zone) IS 'Read-only projection of inventory_balances rows whose reserved counter disagrees with the summed quantity of their status=''reserved'' reservations. Reports the conserved total alongside the narrower active (unexpired) sum the drift watchdog compares against.';


--
-- Name: omnipack_supersede_no_effect_provider_commands(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.omnipack_supersede_no_effect_provider_commands(p_fulfillment_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_command public.commerce_fulfillment_provider_commands%ROWTYPE;
  v_from_status text;
  v_blocked_count integer := 0;
  v_superseded_count integer := 0;
BEGIN
  IF p_fulfillment_order_id IS NULL THEN
    RAISE EXCEPTION 'omnipack_dispatch_command_supersession_invalid_input'
      USING ERRCODE = '22023';
  END IF;

  -- Lock and preflight the whole logical command set before mutating any row.
  FOR v_command IN
    SELECT *
      FROM public.commerce_fulfillment_provider_commands AS command
     WHERE command.fulfillment_order_id = p_fulfillment_order_id
       AND command.provider_kind = 'omnipack'
       AND command.command_kind = 'dispatch_create'
     ORDER BY command.id
     FOR UPDATE
  LOOP
    IF (
        v_command.status = 'queued'
        AND v_command.attempt_count = 0
        AND v_command.claim_generation = 0
        AND v_command.last_reason_code = 'command_enqueued'
        AND 1 = (
          SELECT count(*)
            FROM public.commerce_fulfillment_provider_command_transitions AS transition
           WHERE transition.command_id = v_command.id
             AND transition.from_status IS NULL
             AND transition.to_status = 'queued'
             AND transition.reason_code = 'command_enqueued'
             AND transition.attempt_count = 0
             AND coalesce(transition.claim_generation, 0) = 0
        )
        AND 1 = (
          SELECT count(*)
            FROM public.commerce_fulfillment_provider_command_transitions AS transition
           WHERE transition.command_id = v_command.id
        )
      )
      OR (
        v_command.status = 'cancelled'
        AND v_command.last_reason_code = 'superseded_by_direct_dispatch'
      )
    THEN
      CONTINUE;
    END IF;
    v_blocked_count := v_blocked_count + 1;
  END LOOP;

  IF v_blocked_count > 0 THEN
    RETURN jsonb_build_object('supersededCount', 0, 'blockedCount', v_blocked_count);
  END IF;

  FOR v_command IN
    SELECT *
      FROM public.commerce_fulfillment_provider_commands AS command
     WHERE command.fulfillment_order_id = p_fulfillment_order_id
       AND command.provider_kind = 'omnipack'
       AND command.command_kind = 'dispatch_create'
       AND command.status = 'queued'
       AND command.attempt_count = 0
       AND command.claim_generation = 0
       AND command.last_reason_code = 'command_enqueued'
       AND 1 = (
         SELECT count(*)
           FROM public.commerce_fulfillment_provider_command_transitions AS transition
          WHERE transition.command_id = command.id
            AND transition.from_status IS NULL
            AND transition.to_status = 'queued'
            AND transition.reason_code = 'command_enqueued'
            AND transition.attempt_count = 0
            AND coalesce(transition.claim_generation, 0) = 0
       )
       AND 1 = (
         SELECT count(*)
           FROM public.commerce_fulfillment_provider_command_transitions AS transition
          WHERE transition.command_id = command.id
       )
     ORDER BY command.id
     FOR UPDATE
  LOOP
    v_from_status := v_command.status;
    UPDATE public.commerce_fulfillment_provider_commands
       SET status = 'cancelled',
           last_reason_code = 'superseded_by_direct_dispatch',
           finished_at = now(),
           claim_token = NULL,
           claim_owner_fingerprint = NULL,
           claim_expires_at = NULL,
           version = version + 1,
           updated_at = now()
     WHERE id = v_command.id
    RETURNING * INTO v_command;

    INSERT INTO public.commerce_fulfillment_provider_command_transitions (
      command_id, from_status, to_status, reason_code, command_version,
      attempt_count, claim_generation
    ) VALUES (
      v_command.id, v_from_status, 'cancelled',
      'superseded_by_direct_dispatch', v_command.version,
      v_command.attempt_count, v_command.claim_generation
    );
    v_superseded_count := v_superseded_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'supersededCount', v_superseded_count,
    'blockedCount', 0
  );
END;
$$;


--
-- Name: FUNCTION omnipack_supersede_no_effect_provider_commands(p_fulfillment_order_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.omnipack_supersede_no_effect_provider_commands(p_fulfillment_order_id uuid) IS 'Supersedes only pristine queued OmniPack shadow commands with one enqueue transition; every claimed, retried, or effect-bearing history remains fail-closed.';


--
-- Name: outbox_prepare_resend_idempotency(text[], text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.outbox_prepare_resend_idempotency(p_event_types text[], p_aggregate_type text DEFAULT NULL::text, p_aggregate_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
BEGIN
  -- Keep the existing partial-index predicate as an explicit planner proof,
  -- then reject blank legacy ids before treating a ledger row as provider
  -- success. acceptedWithoutProviderId is delayed truth, not recoverable proof.
  WITH candidates AS (
    SELECT event.id
     FROM public.outbox_events event
     WHERE event.event_type = ANY (p_event_types)
       AND event.event_type = ANY (private.outbox_resend_event_types())
       AND event.status IN ('pending', 'failed', 'processing')
       AND event.available_at <= now()
       AND (p_aggregate_type IS NULL OR (
         event.aggregate_type = p_aggregate_type AND event.aggregate_id = p_aggregate_id
       ))
  ), provider_success AS (
    SELECT candidate.id AS event_id, send.email_send_id, send.resend_id,
           send.platform_job_run_id, send.sent_at
      FROM candidates candidate
      CROSS JOIN LATERAL (
        SELECT email_send.id AS email_send_id, email_send.resend_id,
               CASE
                 WHEN coalesce(email_send.provider_response->>'platformJobRunId', '')
                   ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                   THEN (email_send.provider_response->>'platformJobRunId')::uuid
                 ELSE NULL
               END AS platform_job_run_id,
               email_send.sent_at
          FROM public.email_sends email_send
         WHERE email_send.resend_id IS NOT NULL
           AND nullif(btrim(email_send.resend_id), '') IS NOT NULL
           AND email_send.provider_response->>'outboxEventId' = candidate.id::text
         ORDER BY email_send.sent_at DESC NULLS LAST, email_send.created_at DESC, email_send.id DESC
         LIMIT 1
      ) send
  )
  UPDATE public.outbox_events event
     SET status = 'processed',
         processed_at = coalesce(event.processed_at, provider_success.sent_at, now()),
         error = NULL,
         metadata = coalesce(event.metadata, '{}'::jsonb) || jsonb_build_object(
           'resendId', provider_success.resend_id,
           'emailSendId', provider_success.email_send_id,
           'platformJobRunId', provider_success.platform_job_run_id,
           'providerIdempotencyRecoveredAt', now())
    FROM provider_success
   WHERE event.id = provider_success.event_id
     AND event.status IN ('pending', 'failed', 'processing');

  UPDATE public.outbox_events event
     SET status = 'discarded',
         error = left(coalesce(event.error || ' | ', '') ||
           'resend_idempotency_window_expired_manual_review', 2000),
         metadata = coalesce(event.metadata, '{}'::jsonb) || jsonb_build_object(
           'discardReason', 'resend_idempotency_window_expired_manual_review',
           'discardedAt', now(),
           'resendIdempotencyWindowExpiredAt', now())
   WHERE event.event_type = ANY (p_event_types)
     AND event.event_type = ANY (private.outbox_resend_event_types())
     AND event.status IN ('pending', 'failed', 'processing')
     AND (p_aggregate_type IS NULL OR (
       event.aggregate_type = p_aggregate_type AND event.aggregate_id = p_aggregate_id
     ))
     AND private.outbox_try_timestamptz(event.metadata->>'resendIdempotencyStartedAt')
           < now() - interval '23 hours';
END;
$_$;


--
-- Name: FUNCTION outbox_prepare_resend_idempotency(p_event_types text[], p_aggregate_type text, p_aggregate_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.outbox_prepare_resend_idempotency(p_event_types text[], p_aggregate_type text, p_aggregate_id uuid) IS 'Recovers only nonblank durable Resend ids before claim and sends expired ambiguous provider-key attempts to manual review.';


