--
-- Name: production_database_fingerprint_matches(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.production_database_fingerprint_matches() RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'private', 'pg_catalog'
    AS $$
  SELECT coalesce((
    SELECT
      env.expected_system_identifier = (pg_control_system()).system_identifier::text
      AND env.expected_server_addr = inet_server_addr()
      AND env.expected_server_port = inet_server_port()
    FROM private.platform_cron_environment env
    WHERE env.id = true
  ), false);
$$;


--
-- Name: FUNCTION production_database_fingerprint_matches(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.production_database_fingerprint_matches() IS 'Matches the immutable production database fingerprint independently of cron enablement so an operational kill switch cannot open preview cleanup.';


--
-- Name: promotion_order_has_v2_evidence(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.promotion_order_has_v2_evidence(p_metadata jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  SELECT coalesce(
    p_metadata ? 'promotionCodeIds'
    OR p_metadata ? 'promotionProductDiscountMinor'
    OR p_metadata ? 'promotionShippingDiscountMinor'
    OR p_metadata @? '$.quoteSnapshot.quote.discounts[*] ? (@.promotionEngineVersion == "promotion-engine.v2" && @.reasonCode == "promotion_code_v2")',
    false
  );
$_$;


--
-- Name: FUNCTION promotion_order_has_v2_evidence(p_metadata jsonb); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.promotion_order_has_v2_evidence(p_metadata jsonb) IS 'Detects code-specific v2 evidence from frozen promotion-code discounts or code-specific aggregates; the top-level offer-policy engine marker alone is intentionally insufficient.';


--
-- Name: promotion_persisted_money_mismatch_codes(jsonb, integer, integer, integer, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.promotion_persisted_money_mismatch_codes(p_metadata jsonb, p_subtotal_cents integer, p_discount_cents integer, p_shipping_discount_cents integer, p_claim_code_ids text[]) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_codes text[] := ARRAY[]::text[];
  v_product_stored bigint;
  v_shipping_stored bigint;
  v_expected_code_ids text[];
  v_discount_code_ids text[] := ARRAY[]::text[];
  v_discount jsonb;
  v_product_total numeric := 0;
  v_shipping_total numeric := 0;
  v_adjustments_valid boolean := true;
  v_expected_ids_valid boolean := true;
BEGIN
  IF coalesce(p_metadata->>'promotionProductDiscountMinor', '') !~ '^[0-9]{1,16}$'
    OR coalesce(p_metadata->>'promotionShippingDiscountMinor', '') !~ '^[0-9]{1,16}$'
    OR jsonb_typeof(p_metadata->'promotionCodeIds') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_metadata#>'{quoteSnapshot,quote,discounts}') IS DISTINCT FROM 'array'
  THEN
    v_adjustments_valid := false;
  ELSE
    v_product_stored := (p_metadata->>'promotionProductDiscountMinor')::bigint;
    v_shipping_stored := (p_metadata->>'promotionShippingDiscountMinor')::bigint;

    SELECT
      coalesce(bool_and(
        jsonb_typeof(value) = 'string'
        AND (value#>>'{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      ), true),
      coalesce(array_agg(DISTINCT lower(value#>>'{}') ORDER BY lower(value#>>'{}')),
        ARRAY[]::text[])
    INTO v_expected_ids_valid, v_expected_code_ids
    FROM jsonb_array_elements(p_metadata->'promotionCodeIds');

    FOR v_discount IN
      SELECT value
      FROM jsonb_array_elements(p_metadata#>'{quoteSnapshot,quote,discounts}')
      WHERE value->>'promotionEngineVersion' = 'promotion-engine.v2'
        AND value->>'reasonCode' = 'promotion_code_v2'
    LOOP
      IF coalesce(v_discount->>'amountOffMinor', '') !~ '^[1-9][0-9]{0,15}$'
        OR coalesce(v_discount->>'appliesTo', '') NOT IN ('order_total', 'shipping')
        OR coalesce(v_discount->>'promotionCodeId', '') !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      THEN
        v_adjustments_valid := false;
      ELSE
        v_discount_code_ids := array_append(
          v_discount_code_ids,
          lower(v_discount->>'promotionCodeId')
        );
        IF v_discount->>'appliesTo' = 'shipping' THEN
          v_shipping_total := v_shipping_total + (v_discount->>'amountOffMinor')::numeric;
        ELSE
          v_product_total := v_product_total + (v_discount->>'amountOffMinor')::numeric;
        END IF;
      END IF;
    END LOOP;
    SELECT coalesce(array_agg(DISTINCT code_id ORDER BY code_id), ARRAY[]::text[])
      INTO v_discount_code_ids
      FROM unnest(v_discount_code_ids) AS code_id;
    IF v_expected_code_ids IS DISTINCT FROM v_discount_code_ids THEN
      v_adjustments_valid := false;
    END IF;
  END IF;

  IF NOT v_adjustments_valid OR NOT v_expected_ids_valid THEN
    v_codes := array_append(v_codes, 'promotion_adjustments_invalid');
  END IF;
  IF v_product_stored IS NULL OR v_product_total IS DISTINCT FROM v_product_stored::numeric THEN
    v_codes := array_append(v_codes, 'promotion_product_total');
  END IF;
  IF v_shipping_stored IS NULL OR v_shipping_total IS DISTINCT FROM v_shipping_stored::numeric THEN
    v_codes := array_append(v_codes, 'promotion_shipping_total');
  END IF;
  IF v_product_stored IS NULL OR v_product_stored < 0 OR v_product_stored > p_discount_cents THEN
    v_codes := array_append(v_codes, 'promotion_product_discount_bound');
  END IF;
  IF v_shipping_stored IS NULL OR v_shipping_stored < 0
    OR v_shipping_stored > p_shipping_discount_cents
  THEN
    v_codes := array_append(v_codes, 'promotion_shipping_discount_bound');
  END IF;
  IF coalesce(v_product_stored, 0) > 0 AND p_subtotal_cents - p_discount_cents < 100 THEN
    v_codes := array_append(v_codes, 'promotion_product_floor');
  END IF;
  IF NOT v_expected_ids_valid
    OR v_expected_code_ids IS DISTINCT FROM v_discount_code_ids
    OR v_discount_code_ids IS DISTINCT FROM coalesce(p_claim_code_ids, ARRAY[]::text[])
  THEN
    v_codes := array_append(v_codes, 'promotion_claim_ids');
  END IF;
  RETURN v_codes;
END;
$_$;


--
-- Name: FUNCTION promotion_persisted_money_mismatch_codes(p_metadata jsonb, p_subtotal_cents integer, p_discount_cents integer, p_shipping_discount_cents integer, p_claim_code_ids text[]); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.promotion_persisted_money_mismatch_codes(p_metadata jsonb, p_subtotal_cents integer, p_discount_cents integer, p_shipping_discount_cents integer, p_claim_code_ids text[]) IS 'Evaluates only frozen quote adjustment sums, stored promotion aggregates, CODM header bounds, the 1 PLN floor and promotionCodeIds-vs-claims. It never invokes current policy, pricing or allocation.';


--
-- Name: record_promotion_code_claim_event(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_promotion_code_claim_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_transition_kind text;
  v_safe_reason text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_transition_kind := NEW.status;
    v_safe_reason := CASE NEW.status
      WHEN 'reserved' THEN 'claim_reserved'
      WHEN 'redeemed' THEN 'claim_redeemed'
      ELSE 'claim_released'
    END;
  ELSIF OLD.status = 'released' AND NEW.status = 'redeemed' THEN
    v_transition_kind := 'late_paid';
    v_safe_reason := CASE OLD.release_reason
      WHEN 'order_cancelled' THEN 'late_paid_after_order_cancelled'
      WHEN 'order_failed' THEN 'late_paid_after_order_failed'
      WHEN 'order_expired' THEN 'late_paid_after_order_expired'
      ELSE 'late_paid_after_release'
    END;
  ELSIF NEW.status = 'reserved' THEN
    v_transition_kind := 'reserved';
    v_safe_reason := 'claim_re_reserved';
  ELSIF NEW.status = 'redeemed' THEN
    v_transition_kind := 'redeemed';
    v_safe_reason := 'claim_redeemed';
  ELSE
    v_transition_kind := 'released';
    v_safe_reason := CASE NEW.release_reason
      WHEN 'order_cancelled' THEN 'order_cancelled'
      WHEN 'order_failed' THEN 'order_failed'
      WHEN 'order_expired' THEN 'order_expired'
      ELSE 'claim_released'
    END;
  END IF;

  INSERT INTO public.promotion_code_claim_events (
    claim_id,
    code_id,
    order_id,
    transition_kind,
    from_status,
    to_status,
    safe_reason,
    claim_expires_at
  ) VALUES (
    NEW.id,
    NEW.promotion_code_id,
    NEW.order_id,
    v_transition_kind,
    CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.status END,
    NEW.status,
    v_safe_reason,
    NEW.expires_at
  );

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION record_promotion_code_claim_event(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.record_promotion_code_claim_event() IS 'Writes claim transition evidence in the claim transaction without acquiring a business lock. released -> redeemed records late_paid using OLD release state.';


--
-- Name: accounting_build_canonical_invoice_lines(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_build_canonical_invoice_lines(p_order_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH item_positions AS (
    SELECT
      0 AS position_group,
      oi.allocation_ordinal AS position_ordinal,
      oi.created_at AS position_created_at,
      oi.id AS position_id,
      jsonb_build_object(
        'positionKind', 'item',
        'orderItemId', oi.id,
        'allocationOrdinal', oi.allocation_ordinal,
        'name', coalesce(
          oi.product_snapshot->>'title',
          oi.product_snapshot#>>'{quoteLine,title}',
          oi.product_snapshot#>>'{quoteLine,productTitle}',
          oi.product_snapshot#>>'{quoteLine,name}',
          oi.product_snapshot->>'name',
          oi.product_snapshot->>'sku',
          oi.product_snapshot#>>'{quoteLine,sku}',
          oi.product_snapshot->>'productSlug',
          oi.product_snapshot#>>'{quoteLine,productSlug}',
          cs.title,
          cs.sku,
          'openlup product'
        ),
        'quantity', oi.quantity,
        'unitGrossMinor', round(oi.effective_total_cents::numeric / oi.quantity)::integer,
        'totalGrossMinor', oi.effective_total_cents,
        'unitNetMinor', round(oi.effective_net_cents::numeric / oi.quantity)::integer,
        'totalNetMinor', oi.effective_net_cents,
        'vatRate', rtrim(rtrim(to_char(oi.vat_rate_bps::numeric / 100, 'FM990.00'), '0'), '.'),
        'vatRateBps', oi.vat_rate_bps,
        'discountAllocatedMinor', oi.discount_allocated_cents,
        'catalogTotalGrossMinor', oi.total_cents,
        'productSnapshot', oi.product_snapshot
      ) AS position
      FROM public.commerce_order_items oi
      LEFT JOIN public.catalog_skus cs ON cs.id = oi.sku_id
     WHERE oi.order_id = p_order_id
  ), delivery_position AS (
    SELECT
      1 AS position_group,
      NULL::bigint AS position_ordinal,
      orders.created_at AS position_created_at,
      orders.id AS position_id,
      jsonb_build_object(
        'positionKind', 'delivery',
        'orderItemId', NULL,
        'name', 'Dostawa',
        'quantity', 1,
        'unitGrossMinor', orders.shipping_cents - orders.shipping_discount_cents,
        'totalGrossMinor', orders.shipping_cents - orders.shipping_discount_cents,
        'unitNetMinor', round(
          (orders.shipping_cents - orders.shipping_discount_cents)::numeric * 10000
          / (10000 + min(items.vat_rate_bps))
        )::integer,
        'totalNetMinor', round(
          (orders.shipping_cents - orders.shipping_discount_cents)::numeric * 10000
          / (10000 + min(items.vat_rate_bps))
        )::integer,
        'vatRate', rtrim(rtrim(to_char(min(items.vat_rate_bps)::numeric / 100, 'FM990.00'), '0'), '.'),
        'vatRateBps', min(items.vat_rate_bps),
        'shippingGrossMinor', orders.shipping_cents,
        'shippingDiscountMinor', orders.shipping_discount_cents
      ) AS position
      FROM public.commerce_orders orders
      JOIN public.commerce_order_items items ON items.order_id = orders.id
     WHERE orders.id = p_order_id
       AND orders.shipping_cents - orders.shipping_discount_cents > 0
     GROUP BY orders.id, orders.created_at, orders.shipping_cents, orders.shipping_discount_cents
  ), positions AS (
    SELECT * FROM item_positions
    UNION ALL
    SELECT * FROM delivery_position
  )
  SELECT coalesce(
    jsonb_agg(position ORDER BY position_group, position_ordinal NULLS LAST, position_created_at, position_id),
    '[]'::jsonb
  )
    FROM positions;
$$;


--
-- Name: accounting_dedupe_issue_request_operation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_dedupe_issue_request_operation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.operation NOT IN (
    'issue_requested_from_handoff',
    'issue_requested_from_paid_order'
  ) THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'accounting-handoff-issue-operation|'
      || NEW.invoice_id::text,
    0
  ));

  IF EXISTS (
    SELECT 1
      FROM public.accounting_invoice_operations operation
     WHERE operation.invoice_id = NEW.invoice_id
       AND operation.operation IN (
         'issue_requested_from_handoff',
         'issue_requested_from_paid_order'
       )
  ) THEN
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION accounting_dedupe_issue_request_operation(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounting_dedupe_issue_request_operation() IS 'Keeps paid-order and handoff issue-request audit evidence replay-idempotent when inline, webhook, reconciliation, and durable outbox callers converge.';


--
-- Name: accounting_guard_invoice_issue_provider(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_guard_invoice_issue_provider() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_provider_kind text;
BEGIN
  SELECT invoice.provider_kind
    INTO v_provider_kind
    FROM public.accounting_invoices invoice
   WHERE invoice.id = NEW.invoice_id;

  IF v_provider_kind IS NOT NULL
     AND v_provider_kind IS DISTINCT FROM NEW.provider_kind THEN
    RAISE EXCEPTION 'accounting_invoice_provider_mismatch'
      USING ERRCODE = '23514',
            DETAIL = 'The invoice issue provider is immutable after the invoice is created.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION accounting_guard_invoice_issue_provider(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounting_guard_invoice_issue_provider() IS 'Fails closed if a replay attempts to route one accounting invoice to a provider different from the provider pinned on the invoice.';


--
-- Name: accounting_guard_invoice_provider_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_guard_invoice_provider_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF OLD.provider_kind IS NOT NULL
     AND NEW.provider_kind IS DISTINCT FROM OLD.provider_kind THEN
    RAISE EXCEPTION 'accounting_invoice_provider_immutable'
      USING ERRCODE = '23514',
            DETAIL = 'The accounting invoice provider cannot change after it is first assigned.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION accounting_guard_invoice_provider_immutable(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.accounting_guard_invoice_provider_immutable() IS 'Allows first assignment from NULL for legacy invoices, then keeps provider_kind immutable.';


--
-- Name: accounting_invoice_canonical_money_before_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_canonical_money_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_payment jsonb;
  v_lines jsonb;
  v_item_count integer;
  v_gross_sum bigint;
  v_net_sum bigint;
  v_catalog_sum bigint;
  v_allocated_sum bigint;
  v_distinct_vat integer;
  v_code text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- An invoice cannot change identity between base and correction. This must
    -- run before the correction exclusion or a base row could bypass freezing.
    IF NEW.correction_of_invoice_id IS DISTINCT FROM OLD.correction_of_invoice_id THEN
      RAISE EXCEPTION 'accounting_invoice_correction_identity_immutable'
        USING ERRCODE = '55000';
    END IF;

    -- Draft corrections own an editable fiscal snapshot. Once they leave draft,
    -- apply the same fiscal immutability guarantee as issued base invoices.
    IF OLD.correction_of_invoice_id IS NOT NULL THEN
      IF (OLD.status <> 'draft' OR NEW.status <> 'draft') AND (
        NEW.order_id IS DISTINCT FROM OLD.order_id
        OR NEW.currency IS DISTINCT FROM OLD.currency
        OR NEW.buyer_snapshot IS DISTINCT FROM OLD.buyer_snapshot
        OR NEW.document_kind IS DISTINCT FROM OLD.document_kind
        OR NEW.ksef_required IS DISTINCT FROM OLD.ksef_required
        OR NEW.payment_completed_at IS DISTINCT FROM OLD.payment_completed_at
        OR NEW.provider_payment_id IS DISTINCT FROM OLD.provider_payment_id
        OR (
          OLD.provider_invoice_id IS NOT NULL
          AND (
            NEW.provider_invoice_id IS DISTINCT FROM OLD.provider_invoice_id
            OR NEW.provider_invoice_number IS DISTINCT FROM OLD.provider_invoice_number
          )
        )
        OR NEW.total_net_cents IS DISTINCT FROM OLD.total_net_cents
        OR NEW.total_gross_cents IS DISTINCT FROM OLD.total_gross_cents
        OR NEW.lines_snapshot IS DISTINCT FROM OLD.lines_snapshot
        OR NEW.tax_snapshot IS DISTINCT FROM OLD.tax_snapshot
      ) THEN
        RAISE EXCEPTION 'accounting_invoice_correction_money_immutable'
          USING ERRCODE = '55000';
      END IF;
      RETURN NEW;
    END IF;
  END IF;

  -- Corrections preserve their own fiscal snapshot and remain outside this
  -- base-invoice boundary on INSERT.
  IF NEW.correction_of_invoice_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Once canonicalized (or issued by an older path), money is immutable even
  -- if a caller changes metadata.source or status in the same statement.
  IF TG_OP = 'UPDATE' AND (
    coalesce((OLD.metadata->>'canonicalMoneyVersion')::integer, 0) = 1
    OR OLD.provider_invoice_id IS NOT NULL
    OR OLD.status IN ('issued', 'accepted', 'corrected', 'voided')
  ) THEN
    IF OLD.provider_invoice_id IS NOT NULL AND (
      NEW.provider_invoice_id IS DISTINCT FROM OLD.provider_invoice_id
      OR NEW.provider_invoice_number IS DISTINCT FROM OLD.provider_invoice_number
    ) THEN
      RAISE EXCEPTION 'accounting_invoice_provider_identity_immutable'
        USING ERRCODE = '55000';
    END IF;
    IF OLD.provider_invoice_id IS NOT NULL
      AND NEW.status IS DISTINCT FROM OLD.status
      AND ROW(OLD.status, NEW.status) NOT IN (
        ROW('issued', 'accepted'),
        ROW('issued', 'correction_requested'),
        ROW('accepted', 'correction_requested'),
        ROW('correction_requested', 'corrected')
      )
    THEN
      RAISE EXCEPTION 'accounting_invoice_provider_status_transition_invalid'
        USING ERRCODE = '55000';
    END IF;
    IF NEW.order_id IS DISTINCT FROM OLD.order_id
      OR NEW.currency IS DISTINCT FROM OLD.currency
      OR NEW.buyer_snapshot IS DISTINCT FROM OLD.buyer_snapshot
      OR NEW.document_kind IS DISTINCT FROM OLD.document_kind
      OR NEW.ksef_required IS DISTINCT FROM OLD.ksef_required
      OR NEW.payment_completed_at IS DISTINCT FROM OLD.payment_completed_at
      OR NEW.provider_payment_id IS DISTINCT FROM OLD.provider_payment_id
      OR NEW.total_net_cents IS DISTINCT FROM OLD.total_net_cents
      OR NEW.total_gross_cents IS DISTINCT FROM OLD.total_gross_cents
      OR NEW.lines_snapshot IS DISTINCT FROM OLD.lines_snapshot
      OR NEW.tax_snapshot IS DISTINCT FROM OLD.tax_snapshot
      OR coalesce((NEW.metadata->>'canonicalMoneyVersion')::integer, 0) IS DISTINCT FROM
        coalesce((OLD.metadata->>'canonicalMoneyVersion')::integer, 0)
    THEN
      RAISE EXCEPTION 'accounting_invoice_canonical_money_immutable'
        USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.order_id IS NULL OR NEW.status NOT IN ('issue_requested', 'blocked') THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = NEW.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_invoice_order_not_found' USING ERRCODE = '22023';
  END IF;

  v_payment := public.accounting_order_payment_validation(NEW.order_id);
  IF coalesce((v_payment->>'ok')::boolean, false) IS NOT TRUE THEN
    v_code := coalesce(v_payment->>'code', 'accounting_invoice_payment_validation_failed');
    RAISE EXCEPTION '%', v_code USING ERRCODE = '22023', DETAIL = v_payment::text;
  END IF;

  SELECT
    count(*)::integer,
    coalesce(sum(effective_total_cents), 0),
    coalesce(sum(effective_net_cents), 0),
    coalesce(sum(total_cents), 0),
    coalesce(sum(discount_allocated_cents), 0),
    count(DISTINCT vat_rate_bps)::integer
    INTO v_item_count, v_gross_sum, v_net_sum, v_catalog_sum, v_allocated_sum, v_distinct_vat
    FROM public.commerce_order_items
   WHERE order_id = NEW.order_id;

  IF v_item_count = 0 THEN
    RAISE EXCEPTION 'accounting_invoice_canonical_items_missing' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM public.commerce_order_items
     WHERE order_id = NEW.order_id
       AND (
         discount_allocated_cents IS NULL
         OR effective_total_cents IS NULL
         OR effective_net_cents IS NULL
         OR vat_rate_bps IS NULL
         OR effective_total_cents + discount_allocated_cents <> total_cents
         OR effective_net_cents <> round(effective_total_cents::numeric * 10000 / (10000 + vat_rate_bps))::integer
       )
  ) THEN
    RAISE EXCEPTION 'accounting_invoice_canonical_item_money_invalid' USING ERRCODE = '22023';
  END IF;
  IF v_order.shipping_cents - v_order.shipping_discount_cents > 0
    AND v_distinct_vat <> 1
  THEN
    RAISE EXCEPTION 'accounting_invoice_canonical_vat_rates_mixed' USING ERRCODE = '22023';
  END IF;
  IF v_catalog_sum IS DISTINCT FROM v_order.subtotal_cents
    OR v_allocated_sum IS DISTINCT FROM v_order.discount_cents
    OR v_gross_sum IS DISTINCT FROM v_order.subtotal_cents - v_order.discount_cents
  THEN
    RAISE EXCEPTION 'accounting_invoice_canonical_item_totals_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_order.total_cents IS DISTINCT FROM
    v_order.subtotal_cents - v_order.discount_cents + v_order.shipping_cents - v_order.shipping_discount_cents
  THEN
    RAISE EXCEPTION 'accounting_invoice_canonical_header_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_gross_sum + v_order.shipping_cents - v_order.shipping_discount_cents IS DISTINCT FROM v_order.total_cents THEN
    RAISE EXCEPTION 'accounting_invoice_canonical_position_gross_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_net_sum + round(
    (v_order.shipping_cents - v_order.shipping_discount_cents)::numeric * 10000
    / (10000 + (SELECT min(vat_rate_bps) FROM public.commerce_order_items WHERE order_id = NEW.order_id))
  )::integer IS DISTINCT FROM v_order.total_cents - v_order.tax_cents THEN
    RAISE EXCEPTION 'accounting_invoice_canonical_position_net_mismatch' USING ERRCODE = '22023';
  END IF;
  IF NEW.currency IS DISTINCT FROM v_order.currency
    OR NEW.total_gross_cents IS DISTINCT FROM v_order.total_cents
    OR NEW.total_net_cents IS DISTINCT FROM v_order.total_cents - v_order.tax_cents
  THEN
    RAISE EXCEPTION 'accounting_invoice_header_order_money_mismatch' USING ERRCODE = '22023';
  END IF;

  v_lines := public.accounting_build_canonical_invoice_lines(NEW.order_id);
  IF jsonb_typeof(v_lines) IS DISTINCT FROM 'array' OR jsonb_array_length(v_lines) = 0 THEN
    RAISE EXCEPTION 'accounting_invoice_canonical_lines_missing' USING ERRCODE = '22023';
  END IF;

  NEW.lines_snapshot := v_lines;
  NEW.payment_completed_at := (v_payment->>'paymentCompletedAt')::timestamptz;
  NEW.provider_payment_id := v_payment->>'providerPaymentId';
  NEW.tax_snapshot := jsonb_build_object(
    'vatSource', 'commerce_order_canonical_positions',
    'taxCents', v_order.tax_cents
  );
  NEW.metadata := NEW.metadata || jsonb_build_object(
    'canonicalMoneyVersion', 1,
    'paymentIntentId', v_payment->>'intentId',
    'paymentProvider', v_payment->>'provider',
    'localSettlementState', v_payment->>'localSettlementState'
  );
  RETURN NEW;
END;
$$;


--
-- Name: accounting_invoice_correction_outbox_claim(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_correction_outbox_claim(p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_rows jsonb;
BEGIN
  WITH candidates AS (
    SELECT outbox.id
      FROM public.accounting_invoice_correction_outbox outbox
      JOIN public.accounting_invoices invoice ON invoice.id = outbox.invoice_id
     WHERE invoice.status = 'correction_requested'
       AND invoice.provider_invoice_id IS NOT NULL
       AND (
         outbox.status = 'pending'
         OR (outbox.status = 'failed' AND coalesce(outbox.next_attempt_at, outbox.created_at) <= now())
         OR (outbox.status = 'processing' AND outbox.next_attempt_at <= now())
       )
     ORDER BY outbox.created_at
     LIMIT greatest(least(coalesce(p_limit, 10), 50), 1)
     FOR UPDATE SKIP LOCKED
  ),
  claimed AS (
    UPDATE public.accounting_invoice_correction_outbox outbox
       SET status = 'processing',
           attempt_count = outbox.attempt_count + 1,
           next_attempt_at = now() + make_interval(secs => greatest(coalesce(p_lease_seconds, 300), 60)),
           last_error = '{}'::jsonb
      FROM candidates
     WHERE outbox.id = candidates.id
     RETURNING outbox.*
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'outboxId', claimed.id,
    'attemptCount', claimed.attempt_count,
    'providerKind', claimed.provider_kind,
    'invoiceId', invoice.id,
    'providerInvoiceId', invoice.provider_invoice_id,
    'correctionReason', claimed.correction_reason,
    'payload', claimed.payload,
    'invoice', jsonb_build_object(
      'id', invoice.id,
      'orderRef', invoice.order_ref,
      'invoiceRef', invoice.invoice_ref,
      'documentKind', invoice.document_kind,
      'ksefRequired', invoice.ksef_required,
      'currency', invoice.currency,
      'buyerSnapshot', invoice.buyer_snapshot,
      'linesSnapshot', invoice.lines_snapshot,
      'totalGrossCents', invoice.total_gross_cents,
      'providerInvoiceId', invoice.provider_invoice_id,
      'providerInvoiceNumber', invoice.provider_invoice_number
    )
  )), '[]'::jsonb)
    INTO v_rows
    FROM claimed
    JOIN public.accounting_invoices invoice ON invoice.id = claimed.invoice_id;

  RETURN v_rows;
END;
$$;


--
-- Name: accounting_invoice_correction_outbox_fail(uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_correction_outbox_fail(p_outbox_id uuid, p_error jsonb, p_retry_seconds integer DEFAULT 900) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_outbox public.accounting_invoice_correction_outbox%ROWTYPE;
BEGIN
  UPDATE public.accounting_invoice_correction_outbox
     SET status = 'failed',
         last_error = coalesce(p_error, '{}'::jsonb),
         next_attempt_at = now() + make_interval(secs => greatest(coalesce(p_retry_seconds, 900), 60))
   WHERE id = p_outbox_id
  RETURNING * INTO v_outbox;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_correction_outbox_not_found' USING ERRCODE = '22023'; END IF;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
  VALUES (v_outbox.invoice_id, 'correction_failed', v_outbox.provider_kind, coalesce(p_error, '{}'::jsonb));

  RETURN jsonb_build_object('outbox', jsonb_build_object('id', v_outbox.id, 'status', v_outbox.status));
END;
$$;


--
-- Name: accounting_invoice_correction_outbox_succeed(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_correction_outbox_succeed(p_outbox_id uuid, p_provider_invoice_id text, p_provider_invoice_number text, p_provider_raw jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_outbox public.accounting_invoice_correction_outbox%ROWTYPE;
  v_invoice public.accounting_invoices%ROWTYPE;
BEGIN
  SELECT * INTO v_outbox FROM public.accounting_invoice_correction_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_correction_outbox_not_found' USING ERRCODE = '22023'; END IF;

  UPDATE public.accounting_invoice_correction_outbox
     SET status = 'succeeded', processed_at = now(), next_attempt_at = NULL, last_error = '{}'::jsonb
   WHERE id = p_outbox_id;

  UPDATE public.accounting_invoices
     SET status = 'corrected',
         correction_status = 'issued',
         email_status = 'pending',
         metadata = metadata || jsonb_build_object(
           'correctionProviderInvoiceId', p_provider_invoice_id,
           'correctionProviderInvoiceNumber', p_provider_invoice_number,
           'correctionReason', v_outbox.correction_reason
         ),
         updated_at = now()
   WHERE id = v_outbox.invoice_id
  RETURNING * INTO v_invoice;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, provider_ref, payload)
  VALUES (v_invoice.id, 'correction_issued', v_outbox.provider_kind, p_provider_invoice_id, coalesce(p_provider_raw, '{}'::jsonb));

  INSERT INTO public.accounting_invoice_delivery_outbox (invoice_id, provider_kind, delivery_kind, status, metadata)
  VALUES (
    v_invoice.id,
    v_outbox.provider_kind,
    'provider_email',
    'pending',
    jsonb_build_object('source', 'correction_issued', 'providerInvoiceId', p_provider_invoice_id, 'correctionReason', v_outbox.correction_reason)
  )
  ON CONFLICT (invoice_id, provider_kind, delivery_kind) DO UPDATE
    SET status = 'pending',
        processed_at = NULL,
        next_attempt_at = NULL,
        metadata = public.accounting_invoice_delivery_outbox.metadata || EXCLUDED.metadata,
        last_error = '{}'::jsonb;

  RETURN jsonb_build_object('invoice', jsonb_build_object('id', v_invoice.id, 'status', v_invoice.status));
END;
$$;


--
-- Name: accounting_invoice_delivery_outbox_claim(integer, integer, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_delivery_outbox_claim(p_limit integer DEFAULT 25, p_lease_seconds integer DEFAULT 300, p_require_ksef_acceptance_for_b2b boolean DEFAULT true, p_order_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_candidate record;
  v_expired record;
  v_rows jsonb;
  v_provider_invoice_id text;
  v_dedupe_key text;
BEGIN
  -- A lost response may mean Resend accepted the message. Expired work is
  -- therefore evidence for manual review, never permission to send again.
  FOR v_candidate IN
    SELECT outbox.id AS outbox_id, outbox.invoice_id
    FROM public.accounting_invoice_delivery_outbox outbox
    JOIN public.accounting_invoices invoice ON invoice.id = outbox.invoice_id
    WHERE outbox.status = 'processing'
      AND outbox.next_attempt_at <= now()
      AND (p_order_id IS NULL OR invoice.order_id = p_order_id)
    ORDER BY outbox.created_at, outbox.id
    LIMIT greatest(least(coalesce(p_limit, 25), 100), 1)
  LOOP
    -- Match the canonical accounting lock order: invoice, then outbox.
    PERFORM 1
      FROM public.accounting_invoices
     WHERE id = v_candidate.invoice_id
     FOR UPDATE;

    SELECT
      outbox.id AS outbox_id,
      outbox.attempt_count,
      outbox.provider_kind,
      invoice.id AS invoice_id,
      invoice.order_id,
      invoice.provider_invoice_id,
      coalesce(outbox.metadata->>'providerInvoiceId', invoice.provider_invoice_id) AS occurrence_provider_invoice_id,
      invoice.buyer_snapshot->>'email' AS recipient_email,
      orders.client_id
      INTO v_expired
      FROM public.accounting_invoice_delivery_outbox outbox
      JOIN public.accounting_invoices invoice ON invoice.id = outbox.invoice_id
      JOIN public.commerce_orders orders ON orders.id = invoice.order_id
     WHERE outbox.id = v_candidate.outbox_id
       AND outbox.status = 'processing'
       AND outbox.next_attempt_at <= now()
     FOR UPDATE OF outbox;
    CONTINUE WHEN NOT FOUND;

    v_provider_invoice_id := v_expired.occurrence_provider_invoice_id;
    v_dedupe_key := 'accounting-invoice-delivery:' || v_expired.outbox_id::text || ':' || coalesce(v_provider_invoice_id, 'missing-provider-invoice');

    UPDATE public.accounting_invoice_delivery_outbox
       SET status = 'uncertain',
           processed_at = now(),
           next_attempt_at = NULL,
           last_error = jsonb_build_object(
             'code', 'delivery_lease_expired',
             'attemptCount', v_expired.attempt_count,
             'requiresManualReview', true
           ),
           metadata = metadata || jsonb_build_object('idempotencyKey', v_dedupe_key)
     WHERE id = v_expired.outbox_id;

    UPDATE public.accounting_invoices
       SET email_status = 'failed', updated_at = now()
     WHERE id = v_expired.invoice_id;

    INSERT INTO public.accounting_invoice_operations (
      invoice_id, operation, provider_kind, provider_ref, payload
    )
    SELECT
      v_expired.invoice_id,
      'provider_email_failed',
      'resend',
      NULL,
      jsonb_build_object(
        'deliveryOutboxId', v_expired.outbox_id,
        'attemptCount', v_expired.attempt_count,
        'idempotencyKey', v_dedupe_key,
        'code', 'delivery_lease_expired',
        'requiresManualReview', true
      )
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.accounting_invoice_operations operation
      WHERE operation.invoice_id = v_expired.invoice_id
        AND operation.operation = 'provider_email_failed'
        AND operation.payload->>'deliveryOutboxId' = v_expired.outbox_id::text
        AND operation.payload->>'attemptCount' = v_expired.attempt_count::text
    );

    PERFORM public.communication_record_email_delivery(
      p_dedupe_key => v_dedupe_key,
      p_template_slug => 'commerce-invoice-document',
      p_purpose => 'transactional',
      p_trigger_source => 'accounting-invoice-delivery',
      p_trigger_event => 'invoice.document.delivery',
      p_status => 'delivery_delayed',
      p_recipient_email => v_expired.recipient_email,
      p_client_id => v_expired.client_id,
      p_aggregate_type => 'commerce_order',
      p_aggregate_id => v_expired.order_id::text,
      p_provider_kind => 'resend',
      p_last_error_code => 'delivery_lease_expired',
      p_metadata => jsonb_build_object(
        'deliveryOutboxId', v_expired.outbox_id,
        'attemptCount', v_expired.attempt_count,
        'requiresManualReview', true
      )
    );
  END LOOP;

  WITH candidates AS (
    SELECT outbox.id
      FROM public.accounting_invoice_delivery_outbox outbox
      JOIN public.accounting_invoices invoice ON invoice.id = outbox.invoice_id
     WHERE outbox.delivery_kind = 'provider_email'
       AND coalesce(outbox.metadata->>'providerInvoiceId', invoice.provider_invoice_id) IS NOT NULL
       AND (coalesce(invoice.email_status, 'pending') <> 'sent' OR outbox.metadata->>'source' = 'correction_issued')
       AND invoice.status IN ('issued', 'accepted', 'corrected')
       AND (p_order_id IS NULL OR invoice.order_id = p_order_id)
       AND (
         p_require_ksef_acceptance_for_b2b = false
         OR invoice.document_kind <> 'b2b_vat'
         OR invoice.ksef_status = 'accepted'
       )
       AND (
         outbox.status = 'pending'
         OR (outbox.status = 'failed' AND coalesce(outbox.next_attempt_at, outbox.created_at) <= now())
       )
     ORDER BY outbox.created_at, outbox.id
     LIMIT greatest(least(coalesce(p_limit, 25), 100), 1)
     FOR UPDATE SKIP LOCKED
  ),
  claimed AS (
    UPDATE public.accounting_invoice_delivery_outbox outbox
       SET status = 'processing',
           attempt_count = outbox.attempt_count + 1,
           next_attempt_at = now() + make_interval(secs => greatest(coalesce(p_lease_seconds, 300), 60)),
           processed_at = NULL,
           last_error = '{}'::jsonb,
           metadata = outbox.metadata - 'providerMessageId' - 'emailSendId' - 'idempotencyKey'
      FROM candidates
     WHERE outbox.id = candidates.id
     RETURNING outbox.*
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'outboxId', claimed.id,
    'attemptCount', claimed.attempt_count,
    'providerKind', claimed.provider_kind,
    'invoiceId', invoice.id,
    'orderId', invoice.order_id,
    'clientId', orders.client_id,
    'orderRef', invoice.order_ref,
    'invoiceRef', invoice.invoice_ref,
    'providerInvoiceId', coalesce(claimed.metadata->>'providerInvoiceId', invoice.provider_invoice_id),
    'providerInvoiceNumber', CASE
      WHEN claimed.metadata->>'source' = 'correction_issued'
        THEN coalesce(invoice.metadata->>'correctionProviderInvoiceNumber', invoice.provider_invoice_number)
      ELSE invoice.provider_invoice_number
    END,
    'recipientEmail', invoice.buyer_snapshot->>'email',
    'deliverySource', coalesce(claimed.metadata->>'source', 'invoice_issue_succeeded'),
    'idempotencyKey', 'accounting-invoice-delivery:' || claimed.id::text || ':' || coalesce(claimed.metadata->>'providerInvoiceId', invoice.provider_invoice_id)
  ) ORDER BY claimed.created_at), '[]'::jsonb)
    INTO v_rows
    FROM claimed
    JOIN public.accounting_invoices invoice ON invoice.id = claimed.invoice_id
    JOIN public.commerce_orders orders ON orders.id = invoice.order_id;

  RETURN v_rows;
END;
$$;


--
-- Name: accounting_invoice_delivery_outbox_fail(uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_delivery_outbox_fail(p_outbox_id uuid, p_error jsonb, p_retry_seconds integer DEFAULT 900) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_outbox public.accounting_invoice_delivery_outbox%ROWTYPE;
  v_invoice public.accounting_invoices%ROWTYPE;
BEGIN
  SELECT * INTO v_outbox FROM public.accounting_invoice_delivery_outbox WHERE id = p_outbox_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_delivery_outbox_not_found' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_invoice FROM public.accounting_invoices WHERE id = v_outbox.invoice_id;
  RETURN public.accounting_invoice_delivery_outbox_resend_uncertain(
    p_outbox_id,
    v_outbox.attempt_count,
    coalesce(v_outbox.metadata->>'providerInvoiceId', v_invoice.provider_invoice_id),
    jsonb_build_object(
      'code', 'legacy_delivery_failure_without_attempt_boundary',
      'legacyRetrySeconds', p_retry_seconds
    ),
    NULL
  );
END;
$$;


--
-- Name: accounting_invoice_delivery_outbox_resend_fail(uuid, integer, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_delivery_outbox_resend_fail(p_outbox_id uuid, p_attempt_count integer, p_provider_invoice_id text, p_error jsonb, p_retry_seconds integer DEFAULT 900) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_outbox public.accounting_invoice_delivery_outbox%ROWTYPE;
  v_invoice public.accounting_invoices%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_invoice_id uuid;
  v_occurrence_provider_invoice_id text;
  v_dedupe_key text;
BEGIN
  SELECT invoice_id INTO v_invoice_id
    FROM public.accounting_invoice_delivery_outbox
   WHERE id = p_outbox_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_delivery_outbox_not_found' USING ERRCODE = '22023'; END IF;

  SELECT * INTO v_invoice FROM public.accounting_invoices WHERE id = v_invoice_id FOR UPDATE;
  SELECT * INTO v_outbox
    FROM public.accounting_invoice_delivery_outbox
   WHERE id = p_outbox_id
     AND invoice_id = v_invoice.id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_delivery_outbox_not_found' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_order FROM public.commerce_orders WHERE id = v_invoice.order_id;
  v_occurrence_provider_invoice_id := coalesce(v_outbox.metadata->>'providerInvoiceId', v_invoice.provider_invoice_id);
  v_dedupe_key := 'accounting-invoice-delivery:' || v_outbox.id::text || ':' || v_occurrence_provider_invoice_id;

  IF v_outbox.status <> 'processing' OR v_outbox.attempt_count <> p_attempt_count THEN
    RAISE EXCEPTION 'accounting_delivery_resend_stale_attempt' USING ERRCODE = '40001';
  END IF;
  IF v_occurrence_provider_invoice_id IS DISTINCT FROM btrim(p_provider_invoice_id) THEN
    RAISE EXCEPTION 'accounting_delivery_resend_provider_invoice_conflict' USING ERRCODE = '22023';
  END IF;

  UPDATE public.accounting_invoice_delivery_outbox
     SET status = 'failed',
         last_error = coalesce(p_error, '{}'::jsonb),
         next_attempt_at = now() + make_interval(secs => greatest(coalesce(p_retry_seconds, 900), 60))
   WHERE id = v_outbox.id;

  UPDATE public.accounting_invoices
     SET email_status = 'failed', updated_at = now()
   WHERE id = v_invoice.id;

  PERFORM public.communication_record_email_delivery(
    p_dedupe_key => v_dedupe_key,
    p_template_slug => 'commerce-invoice-document',
    p_purpose => 'transactional',
    p_trigger_source => 'accounting-invoice-delivery',
    p_trigger_event => 'invoice.document.delivery',
    p_status => 'failed',
    p_recipient_email => v_invoice.buyer_snapshot->>'email',
    p_client_id => v_order.client_id,
    p_aggregate_type => 'commerce_order',
    p_aggregate_id => v_invoice.order_id::text,
    p_provider_kind => 'resend',
    p_last_error_code => coalesce(nullif(p_error->>'code', ''), 'invoice_pdf_pre_send_failed'),
    p_metadata => jsonb_build_object(
      'deliveryOutboxId', v_outbox.id,
      'attemptCount', p_attempt_count,
      'providerInvoiceId', v_occurrence_provider_invoice_id,
      'retryable', true
    )
  );

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, provider_ref, payload)
  VALUES (
    v_invoice.id,
    'provider_email_failed',
    'resend',
    NULL,
    coalesce(p_error, '{}'::jsonb) || jsonb_build_object(
      'deliveryOutboxId', v_outbox.id,
      'attemptCount', p_attempt_count,
      'idempotencyKey', v_dedupe_key,
      'retryable', true
    )
  );

  RETURN jsonb_build_object('outbox', jsonb_build_object('id', v_outbox.id, 'status', 'failed'));
END;
$$;


--
-- Name: accounting_invoice_delivery_outbox_resend_succeed(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_delivery_outbox_resend_succeed(p_outbox_id uuid, p_attempt_count integer, p_provider_invoice_id text, p_provider_message_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_outbox public.accounting_invoice_delivery_outbox%ROWTYPE;
  v_invoice public.accounting_invoices%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_invoice_id uuid;
  v_occurrence_provider_invoice_id text;
  v_dedupe_key text;
  v_existing_message_id text;
  v_email_send_id uuid;
BEGIN
  IF p_outbox_id IS NULL OR coalesce(p_attempt_count, 0) < 1
    OR btrim(coalesce(p_provider_invoice_id, '')) = ''
    OR btrim(coalesce(p_provider_message_id, '')) = ''
  THEN
    RAISE EXCEPTION 'accounting_delivery_resend_success_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT invoice_id INTO v_invoice_id
    FROM public.accounting_invoice_delivery_outbox
   WHERE id = p_outbox_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_delivery_outbox_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice
    FROM public.accounting_invoices
   WHERE id = v_invoice_id
   FOR UPDATE;
  SELECT * INTO v_outbox
    FROM public.accounting_invoice_delivery_outbox
   WHERE id = p_outbox_id
     AND invoice_id = v_invoice.id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_delivery_outbox_not_found' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_order FROM public.commerce_orders WHERE id = v_invoice.order_id;
  v_occurrence_provider_invoice_id := coalesce(v_outbox.metadata->>'providerInvoiceId', v_invoice.provider_invoice_id);
  v_dedupe_key := 'accounting-invoice-delivery:' || v_outbox.id::text || ':' || v_occurrence_provider_invoice_id;

  IF v_occurrence_provider_invoice_id IS DISTINCT FROM btrim(p_provider_invoice_id) THEN
    RAISE EXCEPTION 'accounting_delivery_resend_provider_invoice_conflict' USING ERRCODE = '22023';
  END IF;

  SELECT operation.provider_ref INTO v_existing_message_id
    FROM public.accounting_invoice_operations operation
   WHERE operation.invoice_id = v_invoice.id
     AND operation.operation = 'provider_email_sent'
     AND operation.payload->>'idempotencyKey' = v_dedupe_key
   ORDER BY operation.created_at
   LIMIT 1;

  IF v_existing_message_id IS NOT NULL THEN
    IF v_existing_message_id IS DISTINCT FROM btrim(p_provider_message_id) THEN
      RAISE EXCEPTION 'accounting_delivery_resend_message_conflict' USING ERRCODE = '22023';
    END IF;
    RETURN jsonb_build_object(
      'outbox', jsonb_build_object('id', v_outbox.id, 'status', v_outbox.status),
      'invoice', jsonb_build_object('id', v_invoice.id, 'emailStatus', v_invoice.email_status),
      'providerMessageId', v_existing_message_id,
      'replayed', true
    );
  END IF;

  IF v_outbox.status <> 'processing' OR v_outbox.attempt_count <> p_attempt_count THEN
    RAISE EXCEPTION 'accounting_delivery_resend_stale_attempt' USING ERRCODE = '40001';
  END IF;

  -- Resend ids have provider-global ownership. Serialize only this id instead
  -- of adding a risky global unique-index/backfill migration.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'accounting-invoice-email:' || btrim(p_provider_message_id),
    0
  ));

  IF EXISTS (
    SELECT 1
      FROM public.email_sends send
     WHERE send.resend_id = btrim(p_provider_message_id)
       AND send.provider_response->>'idempotencyKey' IS DISTINCT FROM v_dedupe_key
  ) THEN
    RAISE EXCEPTION 'accounting_delivery_resend_message_collision' USING ERRCODE = '23505';
  END IF;

  SELECT send.id INTO v_email_send_id
    FROM public.email_sends send
   WHERE send.resend_id = btrim(p_provider_message_id)
     AND send.provider_response->>'idempotencyKey' = v_dedupe_key
   ORDER BY send.created_at, send.id
   LIMIT 1;

  IF v_email_send_id IS NULL THEN
    INSERT INTO public.email_sends (
      template_slug, resend_id, sent_at, status, source, provider_response
    ) VALUES (
      'commerce-invoice-document',
      btrim(p_provider_message_id),
      now(),
      'sent',
      'accounting-invoice-delivery',
      jsonb_build_object(
        'deliveryOutboxId', v_outbox.id,
        'invoiceId', v_invoice.id,
        'providerInvoiceId', v_occurrence_provider_invoice_id,
        'idempotencyKey', v_dedupe_key
      )
    ) RETURNING id INTO v_email_send_id;
  END IF;

  PERFORM public.communication_record_email_delivery(
    p_dedupe_key => v_dedupe_key,
    p_template_slug => 'commerce-invoice-document',
    p_purpose => 'transactional',
    p_trigger_source => 'accounting-invoice-delivery',
    p_trigger_event => 'invoice.document.delivery',
    p_status => 'sent',
    p_recipient_email => v_invoice.buyer_snapshot->>'email',
    p_client_id => v_order.client_id,
    p_aggregate_type => 'commerce_order',
    p_aggregate_id => v_invoice.order_id::text,
    p_email_send_id => v_email_send_id,
    p_provider_kind => 'resend',
    p_provider_message_id => btrim(p_provider_message_id),
    p_metadata => jsonb_build_object(
      'deliveryOutboxId', v_outbox.id,
      'invoiceId', v_invoice.id,
      'providerInvoiceId', v_occurrence_provider_invoice_id,
      'attemptCount', p_attempt_count
    )
  );

  UPDATE public.accounting_invoice_delivery_outbox
     SET status = 'succeeded',
         processed_at = now(),
         next_attempt_at = NULL,
         last_error = '{}'::jsonb,
         metadata = metadata || jsonb_build_object(
           'deliveryProvider', 'resend',
           'providerMessageId', btrim(p_provider_message_id),
           'emailSendId', v_email_send_id,
           'idempotencyKey', v_dedupe_key
         )
   WHERE id = v_outbox.id;

  UPDATE public.accounting_invoices
     SET email_status = 'sent', updated_at = now()
   WHERE id = v_invoice.id
  RETURNING * INTO v_invoice;

  INSERT INTO public.accounting_invoice_operations (
    invoice_id, operation, provider_kind, provider_ref, payload
  ) VALUES (
    v_invoice.id,
    'provider_email_sent',
    'resend',
    btrim(p_provider_message_id),
    jsonb_build_object(
      'deliveryOutboxId', v_outbox.id,
      'attemptCount', p_attempt_count,
      'providerInvoiceId', v_occurrence_provider_invoice_id,
      'emailSendId', v_email_send_id,
      'idempotencyKey', v_dedupe_key
    )
  );

  RETURN jsonb_build_object(
    'outbox', jsonb_build_object('id', v_outbox.id, 'status', 'succeeded'),
    'invoice', jsonb_build_object('id', v_invoice.id, 'emailStatus', v_invoice.email_status),
    'emailSendId', v_email_send_id,
    'providerMessageId', btrim(p_provider_message_id),
    'replayed', false
  );
END;
$$;


--
-- Name: accounting_invoice_delivery_outbox_resend_uncertain(uuid, integer, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_delivery_outbox_resend_uncertain(p_outbox_id uuid, p_attempt_count integer, p_provider_invoice_id text, p_error jsonb, p_provider_message_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_outbox public.accounting_invoice_delivery_outbox%ROWTYPE;
  v_invoice public.accounting_invoices%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_invoice_id uuid;
  v_occurrence_provider_invoice_id text;
  v_dedupe_key text;
  v_stored_message_id text;
  v_provider_message_id text;
  v_email_send_id uuid;
  v_enrich_existing boolean := false;
  v_updated_count integer := 0;
BEGIN
  SELECT invoice_id INTO v_invoice_id
    FROM public.accounting_invoice_delivery_outbox
   WHERE id = p_outbox_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_delivery_outbox_not_found' USING ERRCODE = '22023'; END IF;

  SELECT * INTO v_invoice FROM public.accounting_invoices WHERE id = v_invoice_id FOR UPDATE;
  SELECT * INTO v_outbox
    FROM public.accounting_invoice_delivery_outbox
   WHERE id = p_outbox_id
     AND invoice_id = v_invoice.id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_delivery_outbox_not_found' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_order FROM public.commerce_orders WHERE id = v_invoice.order_id;
  v_occurrence_provider_invoice_id := coalesce(v_outbox.metadata->>'providerInvoiceId', v_invoice.provider_invoice_id);
  v_dedupe_key := 'accounting-invoice-delivery:' || v_outbox.id::text || ':' || v_occurrence_provider_invoice_id;
  v_stored_message_id := nullif(btrim(coalesce(v_outbox.metadata->>'providerMessageId', '')), '');
  v_provider_message_id := nullif(btrim(coalesce(p_provider_message_id, '')), '');

  IF v_occurrence_provider_invoice_id IS DISTINCT FROM btrim(p_provider_invoice_id) THEN
    RAISE EXCEPTION 'accounting_delivery_resend_provider_invoice_conflict' USING ERRCODE = '22023';
  END IF;

  IF v_outbox.status = 'succeeded' THEN
    IF v_provider_message_id IS NOT NULL
      AND v_stored_message_id IS DISTINCT FROM v_provider_message_id
    THEN
      RAISE EXCEPTION 'accounting_delivery_resend_message_conflict' USING ERRCODE = '22023';
    END IF;
    RETURN jsonb_build_object(
      'outbox', jsonb_build_object('id', v_outbox.id, 'status', 'succeeded'),
      'providerMessageId', v_stored_message_id,
      'replayed', true
    );
  END IF;

  IF v_outbox.status = 'uncertain' AND v_outbox.attempt_count = p_attempt_count
    AND v_occurrence_provider_invoice_id IS NOT DISTINCT FROM btrim(p_provider_invoice_id)
  THEN
    IF v_stored_message_id IS NOT NULL
      AND v_provider_message_id IS NOT NULL
      AND v_stored_message_id IS DISTINCT FROM v_provider_message_id
    THEN
      RAISE EXCEPTION 'accounting_delivery_resend_message_conflict' USING ERRCODE = '22023';
    END IF;
    IF v_stored_message_id IS NULL AND v_provider_message_id IS NOT NULL THEN
      v_enrich_existing := true;
    ELSE
      RETURN jsonb_build_object('outbox', jsonb_build_object('id', v_outbox.id, 'status', 'uncertain'), 'replayed', true);
    END IF;
  END IF;
  IF NOT v_enrich_existing
    AND (v_outbox.status <> 'processing' OR v_outbox.attempt_count <> p_attempt_count)
  THEN
    RAISE EXCEPTION 'accounting_delivery_resend_stale_attempt' USING ERRCODE = '40001';
  END IF;

  IF v_provider_message_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'accounting-invoice-email:' || v_provider_message_id,
      0
    ));

    IF EXISTS (
      SELECT 1
        FROM public.email_sends send
       WHERE send.resend_id = v_provider_message_id
         AND send.provider_response->>'idempotencyKey' IS DISTINCT FROM v_dedupe_key
    ) THEN
      RAISE EXCEPTION 'accounting_delivery_resend_message_collision' USING ERRCODE = '23505';
    END IF;

    SELECT send.id INTO v_email_send_id
      FROM public.email_sends send
     WHERE send.resend_id = v_provider_message_id
       AND send.provider_response->>'idempotencyKey' = v_dedupe_key
     ORDER BY send.created_at, send.id
     LIMIT 1;

    IF v_email_send_id IS NULL THEN
      INSERT INTO public.email_sends (
        template_slug, resend_id, sent_at, status, source, provider_response
      ) VALUES (
        'commerce-invoice-document',
        v_provider_message_id,
        now(),
        'sent',
        'accounting-invoice-delivery',
        jsonb_build_object(
          'deliveryOutboxId', v_outbox.id,
          'invoiceId', v_invoice.id,
          'providerInvoiceId', v_occurrence_provider_invoice_id,
          'idempotencyKey', v_dedupe_key
        )
      ) RETURNING id INTO v_email_send_id;
    END IF;
  END IF;

  IF v_enrich_existing THEN
    UPDATE public.accounting_invoice_delivery_outbox
       SET last_error = last_error || coalesce(p_error, '{}'::jsonb),
           metadata = metadata || jsonb_build_object(
             'providerMessageId', v_provider_message_id,
             'emailSendId', v_email_send_id,
             'idempotencyKey', v_dedupe_key
           )
     WHERE id = v_outbox.id;
  ELSE
    UPDATE public.accounting_invoice_delivery_outbox
       SET status = 'uncertain',
           processed_at = now(),
           next_attempt_at = NULL,
           last_error = coalesce(p_error, '{}'::jsonb) || jsonb_build_object('requiresManualReview', true),
           metadata = metadata || jsonb_strip_nulls(jsonb_build_object(
             'idempotencyKey', v_dedupe_key,
             'providerMessageId', v_provider_message_id,
             'emailSendId', v_email_send_id
           ))
     WHERE id = v_outbox.id;
  END IF;

  UPDATE public.accounting_invoices
     SET email_status = 'failed', updated_at = now()
   WHERE id = v_invoice.id;

  PERFORM public.communication_record_email_delivery(
    p_dedupe_key => v_dedupe_key,
    p_template_slug => 'commerce-invoice-document',
    p_purpose => 'transactional',
    p_trigger_source => 'accounting-invoice-delivery',
    p_trigger_event => 'invoice.document.delivery',
    p_status => 'delivery_delayed',
    p_recipient_email => v_invoice.buyer_snapshot->>'email',
    p_client_id => v_order.client_id,
    p_aggregate_type => 'commerce_order',
    p_aggregate_id => v_invoice.order_id::text,
    p_email_send_id => v_email_send_id,
    p_provider_kind => 'resend',
    p_provider_message_id => v_provider_message_id,
    p_last_error_code => coalesce(nullif(p_error->>'code', ''), 'invoice_email_outcome_uncertain'),
    p_metadata => jsonb_build_object(
      'deliveryOutboxId', v_outbox.id,
      'attemptCount', p_attempt_count,
      'providerInvoiceId', v_occurrence_provider_invoice_id,
      'requiresManualReview', true
    )
  );

  IF v_enrich_existing THEN
    UPDATE public.accounting_invoice_operations operation
       SET provider_ref = v_provider_message_id,
           payload = operation.payload || jsonb_build_object(
             'providerMessageId', v_provider_message_id,
             'emailSendId', v_email_send_id
           )
     WHERE operation.invoice_id = v_invoice.id
       AND operation.operation = 'provider_email_failed'
       AND operation.payload->>'deliveryOutboxId' = v_outbox.id::text
       AND operation.payload->>'attemptCount' = p_attempt_count::text;
    GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  END IF;

  IF NOT v_enrich_existing OR v_updated_count = 0 THEN
    INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, provider_ref, payload)
    VALUES (
      v_invoice.id,
      'provider_email_failed',
      'resend',
      v_provider_message_id,
      coalesce(p_error, '{}'::jsonb) || jsonb_build_object(
        'deliveryOutboxId', v_outbox.id,
        'attemptCount', p_attempt_count,
        'idempotencyKey', v_dedupe_key,
        'providerMessageId', v_provider_message_id,
        'emailSendId', v_email_send_id,
        'requiresManualReview', true
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'outbox', jsonb_build_object('id', v_outbox.id, 'status', 'uncertain'),
    'providerMessageId', v_provider_message_id,
    'emailSendId', v_email_send_id,
    'enriched', v_enrich_existing,
    'replayed', false
  );
END;
$$;


--
-- Name: accounting_invoice_delivery_outbox_succeed(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_delivery_outbox_succeed(p_outbox_id uuid, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_outbox public.accounting_invoice_delivery_outbox%ROWTYPE;
  v_invoice public.accounting_invoices%ROWTYPE;
BEGIN
  SELECT * INTO v_outbox FROM public.accounting_invoice_delivery_outbox WHERE id = p_outbox_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_delivery_outbox_not_found' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_invoice FROM public.accounting_invoices WHERE id = v_outbox.invoice_id;
  RETURN public.accounting_invoice_delivery_outbox_resend_uncertain(
    p_outbox_id,
    v_outbox.attempt_count,
    coalesce(v_outbox.metadata->>'providerInvoiceId', v_invoice.provider_invoice_id),
    jsonb_build_object('code', 'legacy_delivery_result_without_resend_evidence'),
    NULL
  );
END;
$$;


--
-- Name: accounting_invoice_issue_block_canonical_mapper(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_block_canonical_mapper(p_invoice_id uuid, p_code text, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_outbox public.accounting_invoice_issue_outbox%ROWTYPE;
  v_canonical_version integer;
BEGIN
  SELECT coalesce((metadata->>'canonicalMoneyVersion')::integer, 0)
    INTO v_canonical_version
    FROM public.accounting_invoices
   WHERE id = p_invoice_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'accounting_invoice_not_found');
  END IF;
  IF v_canonical_version = 1 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'accounting_invoice_issue_claim_fence_required');
  END IF;
  SELECT * INTO v_outbox
    FROM public.accounting_invoice_issue_outbox
   WHERE invoice_id = p_invoice_id
     AND status = 'processing'
   ORDER BY created_at
   LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'accounting_invoice_issue_claim_not_found');
  END IF;
  RETURN public.accounting_invoice_issue_block_canonical_mapper(
    p_invoice_id,
    p_code,
    p_evidence,
    v_outbox.id,
    v_outbox.attempt_count
  );
END;
$$;


--
-- Name: accounting_invoice_issue_block_canonical_mapper(uuid, text, jsonb, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_block_canonical_mapper(p_invoice_id uuid, p_code text, p_evidence jsonb, p_outbox_id uuid, p_claim_attempt_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_invoice public.accounting_invoices%ROWTYPE;
  v_outbox public.accounting_invoice_issue_outbox%ROWTYPE;
  v_fence_code text;
BEGIN
  IF p_code IS NULL OR p_code !~ '^accounting_invoice_canonical_' THEN
    RAISE EXCEPTION 'accounting_invoice_canonical_mapper_block_code_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice
    FROM public.accounting_invoices
   WHERE id = p_invoice_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'accounting_invoice_not_found');
  END IF;

  SELECT * INTO v_outbox
    FROM public.accounting_invoice_issue_outbox
   WHERE id = p_outbox_id
     AND invoice_id = p_invoice_id
   FOR UPDATE;
  IF p_outbox_id IS NULL OR p_claim_attempt_count IS NULL THEN
    v_fence_code := 'accounting_invoice_issue_claim_fence_required';
  ELSIF NOT FOUND THEN
    v_fence_code := 'accounting_invoice_issue_claim_not_found';
  ELSIF v_outbox.attempt_count IS DISTINCT FROM p_claim_attempt_count THEN
    v_fence_code := 'accounting_invoice_issue_claim_generation_mismatch';
  ELSIF v_invoice.status IS DISTINCT FROM 'issue_requested'
    OR v_invoice.blocked_reason IS NOT NULL
    OR v_outbox.status IS DISTINCT FROM 'processing'
    OR v_outbox.next_attempt_at IS NULL
    OR v_outbox.next_attempt_at <= now()
  THEN
    v_fence_code := 'accounting_invoice_issue_claim_inactive';
  END IF;

  IF v_fence_code IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', v_fence_code);
  END IF;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
  VALUES (
    v_invoice.id,
    'canonical_mapper_preflight',
    v_invoice.provider_kind,
    jsonb_build_object('code', p_code) || coalesce(p_evidence, '{}'::jsonb)
  );

  UPDATE public.accounting_invoices
     SET status = 'blocked', blocked_reason = p_code, updated_at = now()
   WHERE id = v_invoice.id;
  UPDATE public.accounting_invoice_issue_outbox
     SET status = 'failed',
         next_attempt_at = NULL,
         last_error = jsonb_build_object('code', p_code, 'message', p_code, 'retryable', false)
   WHERE id = v_outbox.id
     AND status = 'processing'
     AND attempt_count = p_claim_attempt_count;

  RETURN jsonb_build_object('ok', true, 'code', p_code);
END;
$$;


--
-- Name: accounting_invoice_issue_outbox_claim(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_outbox_claim(p_limit integer DEFAULT 10, p_lease_seconds integer DEFAULT 300, p_order_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT public.accounting_invoice_issue_outbox_claim(
    p_limit,
    p_lease_seconds,
    p_order_id,
    'accounting.issue.v1'
  );
$$;


--
-- Name: accounting_invoice_issue_outbox_claim(integer, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_outbox_claim(p_limit integer, p_lease_seconds integer, p_order_id uuid, p_contract_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_rows jsonb;
BEGIN
  IF p_contract_version NOT IN ('accounting.issue.v1', 'accounting.issue.v2') THEN
    RAISE EXCEPTION 'accounting_invoice_issue_claim_contract_unsupported'
      USING ERRCODE = '22023';
  END IF;

  -- Existing legacy obligations that no longer match payment truth are made
  -- terminally visible instead of remaining silently pending.
  WITH invalid AS MATERIALIZED (
    SELECT invoice.id AS invoice_id, validation
      FROM public.accounting_invoices invoice
      CROSS JOIN LATERAL public.accounting_order_payment_validation(invoice.order_id) AS payment(validation)
     WHERE invoice.status = 'issue_requested'
       AND invoice.blocked_reason IS NULL
       AND (
         p_contract_version = 'accounting.issue.v2'
         OR coalesce((invoice.metadata->>'canonicalMoneyVersion')::integer, 0) <> 1
       )
       AND (p_order_id IS NULL OR invoice.order_id = p_order_id)
       AND coalesce((validation->>'ok')::boolean, false) IS NOT TRUE
       AND EXISTS (
         SELECT 1 FROM public.accounting_invoice_issue_outbox outbox
          WHERE outbox.invoice_id = invoice.id
            AND outbox.status IN ('pending', 'processing', 'failed')
       )
  ), blocked AS (
    UPDATE public.accounting_invoices invoice
       SET status = 'blocked',
           blocked_reason = coalesce(invalid.validation->>'code', 'accounting_invoice_payment_validation_failed'),
           updated_at = now()
      FROM invalid
     WHERE invoice.id = invalid.invoice_id
     RETURNING invoice.id, invoice.blocked_reason
  )
  UPDATE public.accounting_invoice_issue_outbox outbox
     SET status = 'failed',
         next_attempt_at = NULL,
         last_error = jsonb_build_object(
           'code', blocked.blocked_reason,
           'message', blocked.blocked_reason,
           'retryable', false
         )
    FROM blocked
   WHERE outbox.invoice_id = blocked.id
     AND outbox.status IN ('pending', 'processing', 'failed');

  WITH scored AS MATERIALIZED (
    SELECT outbox.id, validation
      FROM public.accounting_invoice_issue_outbox outbox
      JOIN public.accounting_invoices invoice ON invoice.id = outbox.invoice_id
      CROSS JOIN LATERAL public.accounting_order_payment_validation(invoice.order_id) AS payment(validation)
     WHERE invoice.status = 'issue_requested'
       AND invoice.blocked_reason IS NULL
       AND (
         p_contract_version = 'accounting.issue.v2'
         OR coalesce((invoice.metadata->>'canonicalMoneyVersion')::integer, 0) <> 1
       )
       AND (p_order_id IS NULL OR invoice.order_id = p_order_id)
       AND coalesce((validation->>'ok')::boolean, false) IS TRUE
       AND (
         outbox.status = 'pending'
         OR (outbox.status = 'failed' AND coalesce(outbox.next_attempt_at, outbox.created_at) <= now())
         OR (outbox.status = 'processing' AND outbox.next_attempt_at <= now())
       )
     ORDER BY outbox.created_at
     LIMIT greatest(least(coalesce(p_limit, 10), 50), 1)
     FOR UPDATE OF outbox SKIP LOCKED
  ), claimed AS (
    UPDATE public.accounting_invoice_issue_outbox outbox
       SET status = 'processing',
           attempt_count = outbox.attempt_count + 1,
           next_attempt_at = now() + make_interval(secs => greatest(coalesce(p_lease_seconds, 300), 60)),
           last_error = '{}'::jsonb
      FROM scored
     WHERE outbox.id = scored.id
     RETURNING outbox.*, scored.validation
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'outboxId', claimed.id,
    'attemptCount', claimed.attempt_count,
    'claimContractVersion', p_contract_version,
    'providerKind', claimed.provider_kind,
    'payment', jsonb_build_object(
      'intentId', claimed.validation->>'intentId',
      'provider', claimed.validation->>'provider',
      'providerPaymentId', claimed.validation->>'providerPaymentId',
      'amountCents', (claimed.validation->>'amountCents')::integer,
      'currency', claimed.validation->>'currency',
      'localSettlementState', claimed.validation->>'localSettlementState'
    ),
    'invoice', jsonb_build_object(
      'id', invoice.id,
      'orderId', invoice.order_id,
      'orderRef', invoice.order_ref,
      'invoiceRef', invoice.invoice_ref,
      'documentKind', invoice.document_kind,
      'ksefRequired', invoice.ksef_required,
      'currency', invoice.currency,
      'buyerSnapshot', invoice.buyer_snapshot,
      'orderSnapshot', invoice.order_snapshot,
      'taxSnapshot', invoice.tax_snapshot,
      'linesSnapshot', invoice.lines_snapshot,
      'totalNetCents', invoice.total_net_cents,
      'totalGrossCents', invoice.total_gross_cents,
      -- v2 canonical snapshots are complete and intentionally omit the legacy
      -- header. An old mapper that receives orderMoney would append a second
      -- residual delivery line after this migration.
      'orderMoney', CASE
        WHEN coalesce((invoice.metadata->>'canonicalMoneyVersion')::integer, 0) = 1 THEN NULL
        WHEN commerce_order.id IS NULL THEN NULL
        ELSE jsonb_build_object(
        'subtotalCents', commerce_order.subtotal_cents,
        'discountCents', commerce_order.discount_cents,
        'shippingCents', commerce_order.shipping_cents,
        'shippingDiscountCents', commerce_order.shipping_discount_cents,
        'totalCents', commerce_order.total_cents
      ) END,
      'paymentCompletedAt', invoice.payment_completed_at,
      'packageShippedAt', invoice.package_shipped_at,
      'providerPaymentId', invoice.provider_payment_id,
      'metadata', invoice.metadata
    )
  ) ORDER BY claimed.created_at), '[]'::jsonb)
    INTO v_rows
    FROM claimed
    JOIN public.accounting_invoices invoice ON invoice.id = claimed.invoice_id
    LEFT JOIN public.commerce_orders commerce_order ON commerce_order.id = invoice.order_id;

  RETURN v_rows;
END;
$$;


--
-- Name: accounting_invoice_issue_outbox_fail(uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_outbox_fail(p_outbox_id uuid, p_error jsonb, p_retry_seconds integer DEFAULT 900) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_outbox public.accounting_invoice_issue_outbox%ROWTYPE;
  v_canonical_version integer;
BEGIN
  SELECT * INTO v_outbox
    FROM public.accounting_invoice_issue_outbox
   WHERE id = p_outbox_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_issue_outbox_not_found' USING ERRCODE = '22023';
  END IF;
  SELECT coalesce((metadata->>'canonicalMoneyVersion')::integer, 0)
    INTO v_canonical_version
    FROM public.accounting_invoices
   WHERE id = v_outbox.invoice_id;
  IF v_canonical_version = 1 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'accounting_invoice_issue_claim_fence_required');
  END IF;
  RETURN public.accounting_invoice_issue_outbox_fail(
    p_outbox_id,
    p_error,
    p_retry_seconds,
    v_outbox.attempt_count
  );
END;
$$;


--
-- Name: accounting_invoice_issue_outbox_fail(uuid, jsonb, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_outbox_fail(p_outbox_id uuid, p_error jsonb, p_retry_seconds integer, p_claim_attempt_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_invoice_id uuid;
  v_invoice public.accounting_invoices%ROWTYPE;
  v_outbox public.accounting_invoice_issue_outbox%ROWTYPE;
  v_code text;
BEGIN
  SELECT invoice_id INTO v_invoice_id
    FROM public.accounting_invoice_issue_outbox
   WHERE id = p_outbox_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_issue_outbox_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice
    FROM public.accounting_invoices
   WHERE id = v_invoice_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_issue_invoice_not_found' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_outbox
    FROM public.accounting_invoice_issue_outbox
   WHERE id = p_outbox_id
     AND invoice_id = v_invoice.id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_issue_outbox_changed' USING ERRCODE = '40001';
  END IF;

  IF p_claim_attempt_count IS NULL THEN
    v_code := 'accounting_invoice_issue_claim_fence_required';
  ELSIF v_outbox.attempt_count IS DISTINCT FROM p_claim_attempt_count THEN
    v_code := 'accounting_invoice_issue_claim_generation_mismatch';
  ELSIF v_invoice.status IS DISTINCT FROM 'issue_requested'
    OR v_invoice.blocked_reason IS NOT NULL
    OR v_outbox.status IS DISTINCT FROM 'processing'
    OR v_outbox.next_attempt_at IS NULL
    OR v_outbox.next_attempt_at <= now()
  THEN
    v_code := 'accounting_invoice_issue_claim_inactive';
  END IF;

  IF v_code IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', v_code,
      'outbox', jsonb_build_object('id', v_outbox.id, 'status', v_outbox.status)
    );
  END IF;

  UPDATE public.accounting_invoice_issue_outbox
     SET status = 'failed',
         last_error = coalesce(p_error, '{}'::jsonb),
         next_attempt_at = now() + make_interval(secs => greatest(coalesce(p_retry_seconds, 900), 60))
   WHERE id = p_outbox_id
  RETURNING * INTO v_outbox;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
  VALUES (
    v_outbox.invoice_id,
    'provider_invoice_failed',
    v_outbox.provider_kind,
    coalesce(p_error, '{}'::jsonb) || jsonb_build_object('claimAttemptCount', p_claim_attempt_count)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'code', NULL,
    'outbox', jsonb_build_object('id', v_outbox.id, 'status', v_outbox.status)
  );
END;
$$;


--
-- Name: accounting_invoice_issue_outbox_succeed(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_outbox_succeed(p_outbox_id uuid, p_provider_invoice_id text, p_provider_invoice_number text, p_provider_raw jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_outbox public.accounting_invoice_issue_outbox%ROWTYPE;
  v_canonical_version integer;
BEGIN
  SELECT outbox.* INTO v_outbox
    FROM public.accounting_invoice_issue_outbox outbox
   WHERE outbox.id = p_outbox_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_issue_outbox_not_found' USING ERRCODE = '22023';
  END IF;
  SELECT coalesce((metadata->>'canonicalMoneyVersion')::integer, 0)
    INTO v_canonical_version
    FROM public.accounting_invoices
   WHERE id = v_outbox.invoice_id;
  IF v_canonical_version = 1 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'accounting_invoice_issue_claim_fence_required',
      'compensated', false
    );
  END IF;
  RETURN public.accounting_invoice_issue_outbox_succeed(
    p_outbox_id,
    p_provider_invoice_id,
    p_provider_invoice_number,
    p_provider_raw,
    v_outbox.attempt_count
  );
END;
$$;


--
-- Name: accounting_invoice_issue_outbox_succeed(uuid, text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_outbox_succeed(p_outbox_id uuid, p_provider_invoice_id text, p_provider_invoice_number text, p_provider_raw jsonb, p_claim_attempt_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_invoice_id uuid;
  v_outbox public.accounting_invoice_issue_outbox%ROWTYPE;
  v_invoice public.accounting_invoices%ROWTYPE;
  v_code text;
  v_reversal_reason text;
BEGIN
  SELECT invoice_id INTO v_invoice_id
    FROM public.accounting_invoice_issue_outbox
   WHERE id = p_outbox_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_issue_outbox_not_found' USING ERRCODE = '22023';
  END IF;

  -- Acquire the same table-level lock modes that the later UPDATE statements
  -- need, in canonical order. SELECT ... FOR UPDATE alone takes ROW SHARE and
  -- would not conflict with the rollout's SHARE ROW EXCLUSIVE barrier.
  LOCK TABLE public.accounting_invoices IN ROW EXCLUSIVE MODE;
  LOCK TABLE public.accounting_invoice_issue_outbox IN ROW EXCLUSIVE MODE;

  SELECT * INTO v_invoice
    FROM public.accounting_invoices
   WHERE id = v_invoice_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_issue_invoice_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_outbox
    FROM public.accounting_invoice_issue_outbox
   WHERE id = p_outbox_id
   FOR UPDATE;
  IF NOT FOUND OR v_outbox.invoice_id IS DISTINCT FROM v_invoice_id THEN
    RAISE EXCEPTION 'accounting_issue_outbox_changed' USING ERRCODE = '40001';
  END IF;

  IF v_invoice.status = 'voided' AND v_outbox.status = 'cancelled' THEN
    -- The provider call crossed a committed order reversal. The remote fiscal
    -- document is real, so keep the issue command cancelled and immediately
    -- make the compensating correction durable. Never leave a provider id on
    -- a locally voided invoice and never resurrect the issue outbox.
    v_reversal_reason := coalesce(v_invoice.metadata->>'reversalReason', 'order_canceled');

    UPDATE public.accounting_invoice_issue_outbox
       SET last_error = jsonb_build_object(
             'code', 'accounting_invoice_provider_created_after_reversal',
             'message', 'accounting_invoice_provider_created_after_reversal',
             'retryable', false,
             'providerInvoiceId', p_provider_invoice_id,
             'claimAttemptCount', p_claim_attempt_count,
             'actualClaimAttemptCount', v_outbox.attempt_count
           ),
           next_attempt_at = NULL
     WHERE id = p_outbox_id;

    UPDATE public.accounting_invoices
       SET provider_invoice_id = p_provider_invoice_id,
           provider_invoice_number = p_provider_invoice_number,
           status = 'correction_requested',
           correction_status = 'requested',
           email_status = 'not_required',
           metadata = metadata || jsonb_build_object(
             'lateProviderIssueAfterReversal', true,
             'lateProviderIssueClaimAttemptCount', p_claim_attempt_count,
             'lateProviderIssueActualClaimAttemptCount', v_outbox.attempt_count
           ),
           updated_at = now()
     WHERE id = v_invoice_id
    RETURNING * INTO v_invoice;

    INSERT INTO public.accounting_invoice_operations (
      invoice_id, operation, provider_kind, provider_ref, payload
    ) VALUES (
      v_invoice.id,
      'provider_invoice_created_after_reversal',
      v_outbox.provider_kind,
      p_provider_invoice_id,
      coalesce(p_provider_raw, '{}'::jsonb) || jsonb_build_object(
        'reversalReason', v_reversal_reason,
        'claimAttemptCount', p_claim_attempt_count,
        'actualClaimAttemptCount', v_outbox.attempt_count,
        'staleClaim', p_claim_attempt_count IS DISTINCT FROM v_outbox.attempt_count
      )
    );

    INSERT INTO public.accounting_invoice_correction_outbox (
      invoice_id, provider_kind, correction_reason, payload
    ) VALUES (
      v_invoice.id,
      v_outbox.provider_kind,
      v_reversal_reason,
      jsonb_build_object(
        'source', 'provider_issue_after_order_status_reversal',
        'providerInvoiceId', p_provider_invoice_id,
        'claimAttemptCount', p_claim_attempt_count,
        'actualClaimAttemptCount', v_outbox.attempt_count,
        'staleClaim', p_claim_attempt_count IS DISTINCT FROM v_outbox.attempt_count
      )
    )
    ON CONFLICT (invoice_id, provider_kind, correction_reason) DO UPDATE
      SET payload = public.accounting_invoice_correction_outbox.payload || EXCLUDED.payload;

    RETURN jsonb_build_object(
      'ok', true,
      'code', 'accounting_invoice_provider_created_after_reversal',
      'compensated', true,
      'invoice', jsonb_build_object('id', v_invoice.id, 'status', v_invoice.status)
    );
  ELSIF p_claim_attempt_count IS NULL
    OR v_outbox.attempt_count IS DISTINCT FROM p_claim_attempt_count
  THEN
    v_code := 'accounting_invoice_issue_claim_generation_mismatch';
  ELSIF v_invoice.status IS DISTINCT FROM 'issue_requested'
    OR v_invoice.blocked_reason IS NOT NULL
    OR v_outbox.status IS DISTINCT FROM 'processing'
    OR v_outbox.next_attempt_at IS NULL
    OR v_outbox.next_attempt_at <= now()
  THEN
    v_code := 'accounting_invoice_issue_claim_inactive';
  END IF;

  IF v_code IS NOT NULL THEN
    INSERT INTO public.accounting_invoice_operations (
      invoice_id, operation, provider_kind, provider_ref, payload
    ) VALUES (
      v_invoice.id,
      'provider_invoice_result_rejected',
      v_outbox.provider_kind,
      p_provider_invoice_id,
      coalesce(p_provider_raw, '{}'::jsonb) || jsonb_build_object(
        'code', v_code,
        'invoiceStatus', v_invoice.status,
        'outboxStatus', v_outbox.status,
        'expectedClaimAttemptCount', p_claim_attempt_count,
        'actualClaimAttemptCount', v_outbox.attempt_count
      )
    );
    RETURN jsonb_build_object(
      'ok', false,
      'code', v_code,
      'compensated', false,
      'invoice', jsonb_build_object('id', v_invoice.id, 'status', v_invoice.status)
    );
  END IF;

  UPDATE public.accounting_invoice_issue_outbox
     SET status = 'succeeded',
         processed_at = now(),
         next_attempt_at = NULL,
         last_error = '{}'::jsonb
   WHERE id = p_outbox_id;

  UPDATE public.accounting_invoices
     SET provider_invoice_id = p_provider_invoice_id,
         provider_invoice_number = p_provider_invoice_number,
         status = CASE WHEN status = 'issue_requested' THEN 'issued' ELSE status END,
         ksef_status = CASE WHEN ksef_required THEN 'pending' ELSE 'not_required' END,
         email_status = CASE
           WHEN document_kind IN ('b2c_named', 'b2b_vat') THEN 'pending'
           ELSE email_status
         END,
         updated_at = now()
   WHERE id = v_invoice_id
  RETURNING * INTO v_invoice;

  INSERT INTO public.accounting_invoice_operations (
    invoice_id, operation, provider_kind, provider_ref, payload
  ) VALUES (
    v_invoice.id,
    'provider_invoice_created',
    v_outbox.provider_kind,
    p_provider_invoice_id,
    coalesce(p_provider_raw, '{}'::jsonb)
  );

  IF v_invoice.document_kind IN ('b2c_named', 'b2b_vat') THEN
    INSERT INTO public.accounting_invoice_delivery_outbox (
      invoice_id, provider_kind, delivery_kind, metadata
    ) VALUES (
      v_invoice.id,
      v_outbox.provider_kind,
      'provider_email',
      jsonb_build_object(
        'source', 'invoice_issue_succeeded',
        'documentKind', v_invoice.document_kind
      )
    )
    ON CONFLICT (invoice_id, provider_kind, delivery_kind) DO UPDATE
      SET metadata = public.accounting_invoice_delivery_outbox.metadata || EXCLUDED.metadata,
          status = CASE
            WHEN public.accounting_invoice_delivery_outbox.status = 'succeeded' THEN 'succeeded'
            ELSE public.accounting_invoice_delivery_outbox.status
          END;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'code', NULL,
    'compensated', false,
    'invoice', jsonb_build_object('id', v_invoice.id, 'status', v_invoice.status)
  );
END;
$$;


--
-- Name: accounting_invoice_issue_payment_preflight(uuid, text, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_payment_preflight(p_invoice_id uuid, p_provider_status text DEFAULT 'unavailable'::text, p_provider_amount_cents integer DEFAULT NULL::integer, p_provider_currency text DEFAULT NULL::text, p_provider_evidence jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT public.accounting_invoice_issue_payment_preflight(
    p_invoice_id,
    p_provider_status,
    p_provider_amount_cents,
    p_provider_currency,
    p_provider_evidence,
    NULL,
    NULL
  );
$$;


--
-- Name: accounting_invoice_issue_payment_preflight(uuid, text, integer, text, jsonb, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_payment_preflight(p_invoice_id uuid, p_provider_status text, p_provider_amount_cents integer, p_provider_currency text, p_provider_evidence jsonb, p_outbox_id uuid, p_claim_attempt_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_invoice public.accounting_invoices%ROWTYPE;
  v_outbox public.accounting_invoice_issue_outbox%ROWTYPE;
  v_validation jsonb;
  v_expected_lines jsonb;
  v_gross_sum bigint;
  v_net_sum bigint;
  v_state text := 'unavailable';
  v_code text;
  v_evidence jsonb;
  v_fence_failure boolean := false;
BEGIN
  SELECT * INTO v_invoice
    FROM public.accounting_invoices
   WHERE id = p_invoice_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'accounting_invoice_not_found', 'providerReadbackState', 'unavailable');
  END IF;

  IF p_outbox_id IS NULL OR p_claim_attempt_count IS NULL THEN
    v_code := 'accounting_invoice_issue_claim_fence_required';
    v_fence_failure := true;
  ELSE
    SELECT * INTO v_outbox
      FROM public.accounting_invoice_issue_outbox
     WHERE id = p_outbox_id
       AND invoice_id = p_invoice_id
     FOR UPDATE;
    IF NOT FOUND THEN
      v_code := 'accounting_invoice_issue_claim_not_found';
      v_fence_failure := true;
    ELSIF v_outbox.attempt_count IS DISTINCT FROM p_claim_attempt_count THEN
      v_code := 'accounting_invoice_issue_claim_generation_mismatch';
      v_fence_failure := true;
    ELSIF v_invoice.status IS DISTINCT FROM 'issue_requested'
      OR v_invoice.blocked_reason IS NOT NULL
      OR v_outbox.status IS DISTINCT FROM 'processing'
      OR v_outbox.next_attempt_at IS NULL
      OR v_outbox.next_attempt_at <= now()
    THEN
      v_code := 'accounting_invoice_issue_claim_inactive';
      v_fence_failure := true;
    END IF;
  END IF;

  IF v_code IS NULL THEN
    v_validation := public.accounting_order_payment_validation(v_invoice.order_id);
    v_expected_lines := public.accounting_build_canonical_invoice_lines(v_invoice.order_id);
  END IF;
  IF v_code IS NULL THEN
    IF coalesce((v_validation->>'ok')::boolean, false) IS NOT TRUE THEN
      v_code := coalesce(v_validation->>'code', 'accounting_invoice_payment_validation_failed');
    ELSIF coalesce((v_invoice.metadata->>'canonicalMoneyVersion')::integer, 0) <> 1 THEN
      v_code := 'accounting_invoice_canonical_money_version_missing';
    ELSIF v_invoice.lines_snapshot IS DISTINCT FROM v_expected_lines THEN
      v_code := 'accounting_invoice_canonical_snapshot_mismatch';
    ELSIF v_invoice.provider_payment_id IS DISTINCT FROM v_validation->>'providerPaymentId' THEN
      v_code := 'accounting_invoice_payment_provider_ref_mismatch';
    ELSIF v_invoice.metadata->>'paymentProvider' IS DISTINCT FROM v_validation->>'provider' THEN
      v_code := 'accounting_invoice_payment_provider_identity_mismatch';
    ELSIF (
        p_provider_evidence->>'source' = 'provider_api'
        OR coalesce(p_provider_status, '') NOT IN ('', 'unavailable')
      )
      AND nullif(p_provider_evidence->>'provider', '') IS DISTINCT FROM v_validation->>'provider'
    THEN
      v_code := 'accounting_invoice_provider_readback_identity_mismatch';
    ELSIF (
        p_provider_evidence->>'source' = 'provider_api'
        OR coalesce(p_provider_status, '') NOT IN ('', 'unavailable')
      )
      AND nullif(p_provider_evidence->>'providerPaymentId', '') IS DISTINCT FROM v_validation->>'providerPaymentId'
    THEN
      v_code := 'accounting_invoice_provider_readback_ref_mismatch';
    ELSIF v_invoice.total_gross_cents IS DISTINCT FROM (v_validation->>'amountCents')::integer
      OR upper(v_invoice.currency) IS DISTINCT FROM upper(v_validation->>'currency')
    THEN
      v_code := 'accounting_invoice_payment_invoice_header_mismatch';
    ELSIF jsonb_typeof(v_invoice.lines_snapshot) IS DISTINCT FROM 'array'
      OR jsonb_array_length(v_invoice.lines_snapshot) = 0
      OR EXISTS (
        SELECT 1
          FROM jsonb_array_elements(v_invoice.lines_snapshot) position
         WHERE coalesce(position->>'positionKind', '') NOT IN ('item', 'delivery')
            OR jsonb_typeof(position->'totalGrossMinor') IS DISTINCT FROM 'number'
            OR jsonb_typeof(position->'totalNetMinor') IS DISTINCT FROM 'number'
            OR jsonb_typeof(position->'vatRateBps') IS DISTINCT FROM 'number'
      )
    THEN
      v_code := 'accounting_invoice_canonical_lines_incomplete';
    ELSE
      SELECT
        coalesce(sum((position->>'totalGrossMinor')::integer), 0),
        coalesce(sum((position->>'totalNetMinor')::integer), 0)
        INTO v_gross_sum, v_net_sum
        FROM jsonb_array_elements(v_invoice.lines_snapshot) position;
      IF v_gross_sum IS DISTINCT FROM v_invoice.total_gross_cents THEN
        v_code := 'accounting_invoice_positions_gross_mismatch';
      ELSIF v_net_sum IS DISTINCT FROM v_invoice.total_net_cents THEN
        v_code := 'accounting_invoice_positions_net_mismatch';
      END IF;
    END IF;
  END IF;

  IF v_code IS NULL THEN
    IF p_provider_status IS NULL OR p_provider_status IN ('', 'unavailable') THEN
      v_state := 'unavailable';
    ELSIF p_provider_status <> 'succeeded' THEN
      v_state := 'mismatch';
      v_code := 'accounting_invoice_provider_settlement_status_mismatch';
    ELSIF p_provider_amount_cents IS NOT NULL
      AND p_provider_amount_cents IS DISTINCT FROM v_invoice.total_gross_cents
    THEN
      v_state := 'mismatch';
      v_code := 'accounting_invoice_provider_settlement_amount_mismatch';
    ELSIF p_provider_currency IS NOT NULL
      AND upper(p_provider_currency) IS DISTINCT FROM upper(v_invoice.currency)
    THEN
      v_state := 'mismatch';
      v_code := 'accounting_invoice_provider_settlement_currency_mismatch';
    ELSIF p_provider_amount_cents IS NULL OR p_provider_currency IS NULL THEN
      v_state := 'unavailable';
    ELSE
      v_state := 'matched';
    END IF;
  END IF;

  v_evidence := jsonb_strip_nulls(jsonb_build_object(
    'readbackSource', p_provider_evidence->>'source',
    'readbackProvider', p_provider_evidence->>'provider',
    'readbackProviderPaymentId', p_provider_evidence->>'providerPaymentId',
    'readbackProviderStatus', p_provider_evidence->>'providerStatus',
    'readbackAmountAvailable', p_provider_evidence->'amountAvailable',
    'readbackCurrencyAvailable', p_provider_evidence->'currencyAvailable',
    'readbackUnavailableReason', p_provider_evidence->>'unavailableReason'
  )) || jsonb_build_object(
    'code', v_code,
    'providerReadbackState', v_state,
    'expectedAmountCents', v_invoice.total_gross_cents,
    'observedAmountCents', p_provider_amount_cents,
    'expectedCurrency', upper(v_invoice.currency),
    'observedCurrency', CASE WHEN p_provider_currency IS NULL THEN NULL ELSE upper(p_provider_currency) END,
    'providerStatus', nullif(p_provider_status, ''),
    'localSettlementState', v_validation->>'localSettlementState',
    'outboxId', p_outbox_id,
    'claimAttemptCount', p_claim_attempt_count,
    'actualClaimAttemptCount', v_outbox.attempt_count
  );

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
  VALUES (
    v_invoice.id,
    'payment_preflight',
    v_invoice.provider_kind,
    v_evidence
  );

  IF v_code IS NOT NULL AND NOT v_fence_failure THEN
    UPDATE public.accounting_invoices
       SET status = 'blocked', blocked_reason = v_code, updated_at = now()
     WHERE id = v_invoice.id;
    UPDATE public.accounting_invoice_issue_outbox
       SET status = 'failed',
           next_attempt_at = NULL,
           last_error = jsonb_build_object('code', v_code, 'message', v_code, 'retryable', false)
     WHERE invoice_id = v_invoice.id
       AND status IN ('pending', 'processing', 'failed');
  END IF;

  RETURN jsonb_build_object(
    'ok', v_code IS NULL,
    'code', v_code,
    'providerReadbackState', v_state,
    'paymentIntentId', v_validation->>'intentId'
  );
END;
$$;


--
-- Name: accounting_invoice_issue_request(text, uuid, text, text, text, jsonb, jsonb, jsonb, jsonb, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_request(p_idempotency_key text, p_order_id uuid, p_order_ref text, p_invoice_ref text, p_currency text, p_buyer_snapshot jsonb, p_order_snapshot jsonb, p_tax_snapshot jsonb, p_lines_snapshot jsonb, p_total_net_cents integer, p_total_gross_cents integer, p_provider_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice public.accounting_invoices%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = ''
    OR p_order_id IS NULL OR p_invoice_ref IS NULL OR btrim(p_invoice_ref) = ''
    OR p_provider_kind IS NULL OR btrim(p_provider_kind) = '' THEN
    RAISE EXCEPTION 'accounting_invoice_issue_invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.accounting_invoices (
    order_id, order_ref, invoice_ref, status, currency, buyer_snapshot,
    order_snapshot, tax_snapshot, lines_snapshot, total_net_cents,
    total_gross_cents, provider_kind
  )
  VALUES (
    p_order_id, p_order_ref, p_invoice_ref, 'issue_requested', p_currency,
    p_buyer_snapshot, p_order_snapshot, p_tax_snapshot, p_lines_snapshot,
    p_total_net_cents, p_total_gross_cents, p_provider_kind
  )
  ON CONFLICT (invoice_ref) DO UPDATE
    SET updated_at = public.accounting_invoices.updated_at
  RETURNING * INTO v_invoice;

  IF v_invoice.status IN ('accepted', 'corrected') THEN
    RAISE EXCEPTION 'accounting_invoice_accepted_requires_correction' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.accounting_invoice_issue_outbox (invoice_id, provider_kind)
  VALUES (v_invoice.id, p_provider_kind)
  ON CONFLICT (invoice_id, provider_kind) DO NOTHING;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
  VALUES (v_invoice.id, 'issue_requested', p_provider_kind, jsonb_build_object('idempotencyKey', p_idempotency_key))
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object('invoice', jsonb_build_object(
    'id', v_invoice.id, 'invoiceRef', v_invoice.invoice_ref,
    'status', v_invoice.status, 'replayed', v_invoice.created_at < now() - interval '1 millisecond'
  ));
END;
$$;


--
-- Name: accounting_invoice_issue_request_from_handoff(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_request_from_handoff(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_kind text DEFAULT 'fakturownia'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_client public.clients%ROWTYPE;
  v_address public.addresses%ROWTYPE;
  v_billing_address public.addresses%ROWTYPE;
  v_orderer public.customer_orderer_profiles%ROWTYPE;
  v_invoice public.accounting_invoices%ROWTYPE;
  v_payment_completed_at timestamptz;
  v_provider_payment_id text;
  v_payment_provider text;
  v_order_ref text;
  v_invoice_ref text;
  v_tax_id text;
  v_tax_id_raw text;
  v_document_kind text;
  v_ksef_required boolean;
  v_email_status text;
  v_buyer_name text;
  v_buyer_display_name text;
  v_buyer_email text;
  v_company_name text;
  v_buyer_address jsonb;
  v_buyer_source text;
  v_address_source text;
  v_metadata_buyer jsonb;
  v_lines jsonb;
  v_blocked_reason text := NULL;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_fulfillment_order_id IS NULL
    OR p_provider_kind IS NULL OR btrim(p_provider_kind) = ''
  THEN
    RAISE EXCEPTION 'accounting_invoice_handoff_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_invoice_handoff_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_fulfillment.status NOT IN ('handed_over', 'in_transit', 'delivered') OR v_fulfillment.handed_over_at IS NULL THEN
    RAISE EXCEPTION 'accounting_invoice_handoff_requires_package_shipped' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order FROM public.commerce_orders WHERE id = v_fulfillment.order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_invoice_order_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_client FROM public.clients WHERE id = v_order.client_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_invoice_client_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_address FROM public.addresses WHERE id = v_fulfillment.shipping_address_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_invoice_address_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_orderer
    FROM public.customer_orderer_profiles
   WHERE client_id = v_order.client_id
   ORDER BY is_default DESC, updated_at DESC, id
   LIMIT 1;

  SELECT * INTO v_billing_address
    FROM public.addresses
   WHERE client_id = v_order.client_id
     AND kind IN ('billing', 'both')
   ORDER BY is_default DESC, updated_at DESC, id
   LIMIT 1;

  SELECT
    pi.updated_at AS payment_completed_at,
    pi.provider_payment_id,
    pay.provider
    INTO v_payment_completed_at, v_provider_payment_id, v_payment_provider
    FROM public.commerce_payment_intents pi
    JOIN public.commerce_payments pay ON pay.id = pi.payment_id
   WHERE pi.order_id = v_order.id
     AND pi.status = 'succeeded'
   ORDER BY pi.updated_at ASC
   LIMIT 1;
  IF v_payment_completed_at IS NULL THEN
    RAISE EXCEPTION 'accounting_invoice_payment_not_succeeded' USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(v_order.metadata->'invoiceBuyerSnapshot') = 'object' THEN
    v_metadata_buyer := v_order.metadata->'invoiceBuyerSnapshot';
    v_buyer_source := coalesce(NULLIF(v_metadata_buyer->>'source', ''), 'commerce_order_metadata.invoiceBuyerSnapshot');
    v_address_source := coalesce(NULLIF(v_metadata_buyer#>>'{address,source}', ''), v_buyer_source);
    v_buyer_display_name := NULLIF(v_metadata_buyer->>'name', '');
    v_buyer_email := coalesce(NULLIF(v_metadata_buyer->>'email', ''), v_client.email);
    v_company_name := NULLIF(v_metadata_buyer->>'companyName', '');
    v_tax_id_raw := NULLIF(v_metadata_buyer->>'taxId', '');
    v_buyer_address := CASE
      WHEN jsonb_typeof(v_metadata_buyer->'address') = 'object' THEN v_metadata_buyer->'address'
      ELSE jsonb_build_object(
        'line1', v_address.line1,
        'line2', v_address.line2,
        'city', v_address.city,
        'postalCode', v_address.postal_code,
        'country', v_address.country,
        'source', 'shipping_address_legacy_fallback'
      )
    END;
  ELSIF v_orderer.id IS NOT NULL OR v_billing_address.id IS NOT NULL THEN
    v_buyer_source := CASE
      WHEN v_orderer.id IS NOT NULL THEN 'customer_orderer_profile'
      ELSE 'customer_billing_address'
    END;
    v_address_source := CASE
      WHEN v_billing_address.id IS NOT NULL THEN 'customer_billing_address'
      ELSE 'shipping_address_legacy_fallback'
    END;
    v_buyer_display_name := coalesce(
      NULLIF(v_orderer.full_name, ''),
      NULLIF(v_billing_address.recipient_name, ''),
      NULLIF(concat_ws(' ', v_client.first_name, v_client.last_name), ''),
      v_client.email
    );
    v_buyer_email := coalesce(NULLIF(v_orderer.email, ''), v_client.email);
    v_company_name := coalesce(NULLIF(v_orderer.company_name, ''), NULLIF(v_billing_address.company_name, ''));
    v_tax_id_raw := coalesce(NULLIF(v_orderer.tax_id, ''), NULLIF(v_billing_address.tax_id, ''));
    v_buyer_address := CASE
      WHEN v_billing_address.id IS NOT NULL THEN jsonb_build_object(
        'addressId', v_billing_address.id,
        'line1', v_billing_address.line1,
        'line2', v_billing_address.line2,
        'city', v_billing_address.city,
        'postalCode', v_billing_address.postal_code,
        'country', v_billing_address.country,
        'source', 'customer_billing_address'
      )
      ELSE jsonb_build_object(
        'addressId', v_address.id,
        'line1', v_address.line1,
        'line2', v_address.line2,
        'city', v_address.city,
        'postalCode', v_address.postal_code,
        'country', v_address.country,
        'source', 'shipping_address_legacy_fallback'
      )
    END;
  ELSE
    v_buyer_source := 'legacy_shipping_address_fallback';
    v_address_source := 'legacy_shipping_address_fallback';
    v_buyer_display_name := coalesce(
      NULLIF(v_address.recipient_name, ''),
      NULLIF(concat_ws(' ', v_client.first_name, v_client.last_name), ''),
      v_client.email
    );
    v_buyer_email := v_client.email;
    v_company_name := NULLIF(v_address.company_name, '');
    v_tax_id_raw := NULLIF(v_address.tax_id, '');
    v_buyer_address := jsonb_build_object(
      'addressId', v_address.id,
      'line1', v_address.line1,
      'line2', v_address.line2,
      'city', v_address.city,
      'postalCode', v_address.postal_code,
      'country', v_address.country,
      'source', 'legacy_shipping_address_fallback'
    );
  END IF;

  v_tax_id := public.accounting_normalize_pl_nip(v_tax_id_raw);
  IF v_tax_id IS NULL THEN
    v_document_kind := 'b2c_named';
    v_ksef_required := false;
    v_email_status := 'pending';
  ELSIF public.accounting_is_valid_pl_nip(v_tax_id) THEN
    v_document_kind := 'b2b_vat';
    v_ksef_required := true;
    v_email_status := 'not_required';
  ELSE
    v_document_kind := NULL;
    v_ksef_required := false;
    v_email_status := 'not_required';
    v_blocked_reason := 'invalid_tax_id';
  END IF;

  v_order_ref := coalesce(v_order.order_number, 'order_' || v_order.id::text);
  v_invoice_ref := v_order_ref || ':base';
  v_buyer_name := coalesce(
    NULLIF(CASE WHEN v_document_kind = 'b2b_vat' THEN v_company_name ELSE NULL END, ''),
    NULLIF(v_buyer_display_name, ''),
    v_client.email
  );

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'orderItemId', oi.id,
    'name', coalesce(oi.product_snapshot->>'title', oi.product_snapshot->>'name', cs.title, cs.sku, 'openlup product'),
    'quantity', oi.quantity,
    'unitGrossMinor', oi.unit_price_cents,
    'totalGrossMinor', oi.total_cents,
    'vatRate', coalesce(oi.product_snapshot->>'vatRate', oi.product_snapshot->>'vat_rate', '8'),
    'productSnapshot', oi.product_snapshot
  ) ORDER BY oi.created_at), '[]'::jsonb)
    INTO v_lines
    FROM public.commerce_order_items oi
    LEFT JOIN public.catalog_skus cs ON cs.id = oi.sku_id
   WHERE oi.order_id = v_order.id;

  INSERT INTO public.accounting_invoices (
    order_id,
    order_ref,
    invoice_ref,
    status,
    currency,
    buyer_snapshot,
    order_snapshot,
    tax_snapshot,
    lines_snapshot,
    total_net_cents,
    total_gross_cents,
    provider_kind,
    ksef_status,
    document_kind,
    ksef_required,
    payment_completed_at,
    package_shipped_at,
    provider_payment_id,
    email_status,
    blocked_reason,
    metadata
  )
  VALUES (
    v_order.id,
    v_order_ref,
    v_invoice_ref,
    CASE WHEN v_blocked_reason IS NULL THEN 'issue_requested' ELSE 'blocked' END,
    v_order.currency,
    jsonb_build_object(
      'name', v_buyer_name,
      'email', v_buyer_email,
      'taxId', v_tax_id,
      'companyName', v_company_name,
      'source', v_buyer_source,
      'addressSource', v_address_source,
      'ordererProfileId', v_orderer.id,
      'billingAddressId', v_billing_address.id,
      'legacyFallback', v_buyer_source = 'legacy_shipping_address_fallback' OR v_address_source LIKE '%legacy_shipping_address_fallback',
      'address', v_buyer_address
    ),
    jsonb_build_object(
      'orderId', v_order.id,
      'orderRef', v_order_ref,
      'fulfillmentOrderId', v_fulfillment.id,
      'fulfillmentStatus', v_fulfillment.status
    ),
    jsonb_build_object(
      'vatSource', 'commerce_order_snapshot',
      'taxCents', v_order.tax_cents
    ),
    v_lines,
    greatest(v_order.total_cents - v_order.tax_cents, 0),
    v_order.total_cents,
    p_provider_kind,
    CASE WHEN v_document_kind = 'b2b_vat' THEN 'pending' WHEN v_document_kind = 'b2c_named' THEN 'not_required' ELSE 'not_submitted' END,
    v_document_kind,
    v_ksef_required,
    v_payment_completed_at,
    v_fulfillment.handed_over_at,
    v_provider_payment_id,
    v_email_status,
    v_blocked_reason,
    jsonb_build_object(
      'idempotencyKey', p_idempotency_key,
      'paymentProvider', v_payment_provider,
      'source', 'commerce.fulfillment.handoff',
      'billingSnapshotSource', v_buyer_source,
      'billingAddressSource', v_address_source,
      'legacyShippingFallback', v_buyer_source = 'legacy_shipping_address_fallback' OR v_address_source LIKE '%legacy_shipping_address_fallback'
    )
  )
  ON CONFLICT (invoice_ref) DO UPDATE
    SET updated_at = public.accounting_invoices.updated_at
  RETURNING * INTO v_invoice;

  IF v_invoice.status = 'blocked' THEN
    INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
    SELECT
      v_invoice.id,
      'issue_blocked',
      p_provider_kind,
      jsonb_build_object(
        'reason', v_invoice.blocked_reason,
        'idempotencyKey', p_idempotency_key,
        'billingSnapshotSource', v_invoice.metadata->>'billingSnapshotSource'
      )
    WHERE NOT EXISTS (
      SELECT 1
        FROM public.accounting_invoice_operations operation
       WHERE operation.invoice_id = v_invoice.id
         AND operation.operation = 'issue_blocked'
         AND operation.provider_kind = p_provider_kind
         AND operation.payload->>'idempotencyKey' = p_idempotency_key
    );

    RETURN jsonb_build_object('invoice', jsonb_build_object(
      'id', v_invoice.id,
      'invoiceRef', v_invoice.invoice_ref,
      'status', v_invoice.status,
      'documentKind', v_invoice.document_kind,
      'blockedReason', v_invoice.blocked_reason,
      'replayed', v_invoice.created_at < now() - interval '1 millisecond'
    ));
  END IF;

  INSERT INTO public.accounting_invoice_issue_outbox (invoice_id, provider_kind)
  VALUES (v_invoice.id, p_provider_kind)
  ON CONFLICT (invoice_id, provider_kind) DO NOTHING;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
  SELECT
    v_invoice.id,
    'issue_requested_from_handoff',
    p_provider_kind,
    jsonb_build_object(
      'idempotencyKey', p_idempotency_key,
      'fulfillmentOrderId', p_fulfillment_order_id,
      'packageShippedAt', v_invoice.package_shipped_at,
      'paymentCompletedAt', v_invoice.payment_completed_at,
      'providerPaymentId', v_invoice.provider_payment_id,
      'billingSnapshotSource', v_invoice.metadata->>'billingSnapshotSource',
      'billingAddressSource', v_invoice.metadata->>'billingAddressSource',
      'legacyShippingFallback', v_invoice.metadata->'legacyShippingFallback'
    )
  WHERE NOT EXISTS (
    SELECT 1
      FROM public.accounting_invoice_operations operation
     WHERE operation.invoice_id = v_invoice.id
       AND operation.operation = 'issue_requested_from_handoff'
       AND operation.provider_kind = p_provider_kind
       AND operation.payload->>'idempotencyKey' = p_idempotency_key
  );

  RETURN jsonb_build_object('invoice', jsonb_build_object(
    'id', v_invoice.id,
    'invoiceRef', v_invoice.invoice_ref,
    'status', v_invoice.status,
    'documentKind', v_invoice.document_kind,
    'ksefRequired', v_invoice.ksef_required,
    'emailStatus', v_invoice.email_status,
    'replayed', v_invoice.created_at < now() - interval '1 millisecond'
  ));
END;
$$;


--
-- Name: accounting_invoice_issue_request_from_paid_order(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_request_from_paid_order(p_idempotency_key text, p_order_id uuid, p_provider_kind text DEFAULT 'fakturownia'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_client public.clients%ROWTYPE;
  v_address public.addresses%ROWTYPE;
  v_billing_address public.addresses%ROWTYPE;
  v_orderer public.customer_orderer_profiles%ROWTYPE;
  v_invoice public.accounting_invoices%ROWTYPE;
  v_payment_completed_at timestamptz;
  v_provider_payment_id text;
  v_payment_provider text;
  v_order_ref text;
  v_invoice_ref text;
  v_tax_id text;
  v_tax_id_raw text;
  v_document_kind text;
  v_ksef_required boolean;
  v_email_status text;
  v_buyer_name text;
  v_buyer_display_name text;
  v_buyer_email text;
  v_company_name text;
  v_buyer_address jsonb;
  v_buyer_source text;
  v_address_source text;
  v_metadata_buyer jsonb;
  v_lines jsonb;
  v_blocked_reason text := NULL;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_order_id IS NULL
    OR p_provider_kind IS NULL OR btrim(p_provider_kind) = ''
  THEN
    RAISE EXCEPTION 'accounting_invoice_paid_order_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order FROM public.commerce_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_order_not_found' USING ERRCODE = '22023'; END IF;
  IF v_order.status NOT IN ('paid', 'fulfillment_pending', 'fulfilled') THEN
    RAISE EXCEPTION 'accounting_invoice_paid_order_status_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_client FROM public.clients WHERE id = v_order.client_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_client_not_found' USING ERRCODE = '22023'; END IF;

  SELECT * INTO v_address FROM public.addresses WHERE id = v_order.shipping_address_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_address_not_found' USING ERRCODE = '22023'; END IF;

  SELECT * INTO v_orderer
    FROM public.customer_orderer_profiles
   WHERE client_id = v_order.client_id
   ORDER BY is_default DESC, updated_at DESC, id
   LIMIT 1;

  SELECT * INTO v_billing_address
    FROM public.addresses
   WHERE client_id = v_order.client_id
     AND kind IN ('billing', 'both')
   ORDER BY is_default DESC, updated_at DESC, id
   LIMIT 1;

  SELECT pi.updated_at, pi.provider_payment_id, pay.provider
    INTO v_payment_completed_at, v_provider_payment_id, v_payment_provider
    FROM public.commerce_payment_intents pi
    JOIN public.commerce_payments pay ON pay.id = pi.payment_id
   WHERE pi.order_id = v_order.id
     AND pi.status = 'succeeded'
   ORDER BY pi.updated_at ASC
   LIMIT 1;
  IF v_payment_completed_at IS NULL THEN
    RAISE EXCEPTION 'accounting_invoice_payment_not_succeeded' USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(v_order.metadata->'invoiceBuyerSnapshot') = 'object' THEN
    v_metadata_buyer := v_order.metadata->'invoiceBuyerSnapshot';
    v_buyer_source := coalesce(NULLIF(v_metadata_buyer->>'source', ''), 'commerce_order_metadata.invoiceBuyerSnapshot');
    v_address_source := coalesce(NULLIF(v_metadata_buyer#>>'{address,source}', ''), v_buyer_source);
    v_buyer_display_name := NULLIF(v_metadata_buyer->>'name', '');
    v_buyer_email := coalesce(NULLIF(v_metadata_buyer->>'email', ''), v_client.email);
    v_company_name := NULLIF(v_metadata_buyer->>'companyName', '');
    v_tax_id_raw := NULLIF(v_metadata_buyer->>'taxId', '');
    v_buyer_address := CASE
      WHEN jsonb_typeof(v_metadata_buyer->'address') = 'object' THEN v_metadata_buyer->'address'
      ELSE jsonb_build_object('line1', v_address.line1, 'line2', v_address.line2, 'city', v_address.city, 'postalCode', v_address.postal_code, 'country', v_address.country, 'source', 'shipping_address_legacy_fallback')
    END;
  ELSIF v_orderer.id IS NOT NULL OR v_billing_address.id IS NOT NULL THEN
    v_buyer_source := CASE WHEN v_orderer.id IS NOT NULL THEN 'customer_orderer_profile' ELSE 'customer_billing_address' END;
    v_address_source := CASE WHEN v_billing_address.id IS NOT NULL THEN 'customer_billing_address' ELSE 'shipping_address_legacy_fallback' END;
    v_buyer_display_name := coalesce(NULLIF(v_orderer.full_name, ''), NULLIF(v_billing_address.recipient_name, ''), NULLIF(concat_ws(' ', v_client.first_name, v_client.last_name), ''), v_client.email);
    v_buyer_email := coalesce(NULLIF(v_orderer.email, ''), v_client.email);
    v_company_name := coalesce(NULLIF(v_orderer.company_name, ''), NULLIF(v_billing_address.company_name, ''));
    v_tax_id_raw := coalesce(NULLIF(v_orderer.tax_id, ''), NULLIF(v_billing_address.tax_id, ''));
    v_buyer_address := CASE
      WHEN v_billing_address.id IS NOT NULL THEN jsonb_build_object('addressId', v_billing_address.id, 'line1', v_billing_address.line1, 'line2', v_billing_address.line2, 'city', v_billing_address.city, 'postalCode', v_billing_address.postal_code, 'country', v_billing_address.country, 'source', 'customer_billing_address')
      ELSE jsonb_build_object('addressId', v_address.id, 'line1', v_address.line1, 'line2', v_address.line2, 'city', v_address.city, 'postalCode', v_address.postal_code, 'country', v_address.country, 'source', 'shipping_address_legacy_fallback')
    END;
  ELSE
    v_buyer_source := 'legacy_shipping_address_fallback';
    v_address_source := 'legacy_shipping_address_fallback';
    v_buyer_display_name := coalesce(NULLIF(v_address.recipient_name, ''), NULLIF(concat_ws(' ', v_client.first_name, v_client.last_name), ''), v_client.email);
    v_buyer_email := v_client.email;
    v_company_name := NULLIF(v_address.company_name, '');
    v_tax_id_raw := NULLIF(v_address.tax_id, '');
    v_buyer_address := jsonb_build_object('addressId', v_address.id, 'line1', v_address.line1, 'line2', v_address.line2, 'city', v_address.city, 'postalCode', v_address.postal_code, 'country', v_address.country, 'source', 'legacy_shipping_address_fallback');
  END IF;

  v_tax_id := public.accounting_normalize_pl_nip(v_tax_id_raw);
  IF v_tax_id IS NULL THEN
    v_document_kind := 'b2c_named';
    v_ksef_required := false;
    v_email_status := 'pending';
  ELSIF public.accounting_is_valid_pl_nip(v_tax_id) THEN
    v_document_kind := 'b2b_vat';
    v_ksef_required := true;
    v_email_status := 'not_required';
  ELSE
    v_document_kind := NULL;
    v_ksef_required := false;
    v_email_status := 'not_required';
    v_blocked_reason := 'invalid_tax_id';
  END IF;

  v_order_ref := coalesce(v_order.order_number, 'order_' || v_order.id::text);
  v_invoice_ref := v_order_ref || ':base';
  v_buyer_name := coalesce(NULLIF(CASE WHEN v_document_kind = 'b2b_vat' THEN v_company_name ELSE NULL END, ''), NULLIF(v_buyer_display_name, ''), v_client.email);

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'orderItemId', oi.id,
    'name', coalesce(oi.product_snapshot->>'title', oi.product_snapshot->>'name', cs.title, cs.sku, 'openlup product'),
    'quantity', oi.quantity,
    'unitGrossMinor', oi.unit_price_cents,
    'totalGrossMinor', oi.total_cents,
    'vatRate', coalesce(oi.product_snapshot->>'vatRate', oi.product_snapshot->>'vat_rate', '8'),
    'productSnapshot', oi.product_snapshot
  ) ORDER BY oi.created_at), '[]'::jsonb)
    INTO v_lines
    FROM public.commerce_order_items oi
    LEFT JOIN public.catalog_skus cs ON cs.id = oi.sku_id
   WHERE oi.order_id = v_order.id;

  INSERT INTO public.accounting_invoices (
    order_id, order_ref, invoice_ref, status, currency, buyer_snapshot,
    order_snapshot, tax_snapshot, lines_snapshot, total_net_cents, total_gross_cents,
    provider_kind, ksef_status, document_kind, ksef_required, payment_completed_at,
    package_shipped_at, provider_payment_id, email_status, blocked_reason, metadata
  )
  VALUES (
    v_order.id, v_order_ref, v_invoice_ref,
    CASE WHEN v_blocked_reason IS NULL THEN 'issue_requested' ELSE 'blocked' END,
    v_order.currency,
    jsonb_build_object(
      'name', v_buyer_name, 'email', v_buyer_email, 'taxId', v_tax_id,
      'companyName', v_company_name, 'source', v_buyer_source,
      'addressSource', v_address_source, 'ordererProfileId', v_orderer.id,
      'billingAddressId', v_billing_address.id,
      'legacyFallback', v_buyer_source = 'legacy_shipping_address_fallback' OR v_address_source LIKE '%legacy_shipping_address_fallback',
      'address', v_buyer_address
    ),
    jsonb_build_object('orderId', v_order.id, 'orderRef', v_order_ref, 'orderStatus', v_order.status),
    jsonb_build_object('vatSource', 'commerce_order_snapshot', 'taxCents', v_order.tax_cents),
    v_lines,
    greatest(v_order.total_cents - v_order.tax_cents, 0),
    v_order.total_cents,
    p_provider_kind,
    CASE WHEN v_document_kind = 'b2b_vat' THEN 'pending' WHEN v_document_kind = 'b2c_named' THEN 'not_required' ELSE 'not_submitted' END,
    v_document_kind,
    v_ksef_required,
    v_payment_completed_at,
    NULL,
    v_provider_payment_id,
    v_email_status,
    v_blocked_reason,
    jsonb_build_object(
      'idempotencyKey', p_idempotency_key,
      'paymentProvider', v_payment_provider,
      'source', 'commerce.order.paid',
      'billingSnapshotSource', v_buyer_source,
      'billingAddressSource', v_address_source,
      'legacyShippingFallback', v_buyer_source = 'legacy_shipping_address_fallback' OR v_address_source LIKE '%legacy_shipping_address_fallback'
    )
  )
  ON CONFLICT (invoice_ref) DO UPDATE
    SET updated_at = public.accounting_invoices.updated_at
  RETURNING * INTO v_invoice;

  IF v_invoice.status = 'blocked' THEN
    INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
    VALUES (v_invoice.id, 'issue_blocked', p_provider_kind, jsonb_build_object('reason', v_invoice.blocked_reason, 'idempotencyKey', p_idempotency_key))
    ON CONFLICT DO NOTHING;
    RETURN jsonb_build_object('invoice', jsonb_build_object('id', v_invoice.id, 'invoiceRef', v_invoice.invoice_ref, 'status', v_invoice.status, 'documentKind', v_invoice.document_kind, 'blockedReason', v_invoice.blocked_reason, 'replayed', v_invoice.created_at < now() - interval '1 millisecond'));
  END IF;

  INSERT INTO public.accounting_invoice_issue_outbox (invoice_id, provider_kind)
  VALUES (v_invoice.id, p_provider_kind)
  ON CONFLICT (invoice_id, provider_kind) DO NOTHING;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
  VALUES (v_invoice.id, 'issue_requested_from_paid_order', p_provider_kind, jsonb_build_object('idempotencyKey', p_idempotency_key, 'paymentCompletedAt', v_invoice.payment_completed_at, 'providerPaymentId', v_invoice.provider_payment_id));

  RETURN jsonb_build_object('invoice', jsonb_build_object(
    'id', v_invoice.id,
    'invoiceRef', v_invoice.invoice_ref,
    'status', v_invoice.status,
    'documentKind', v_invoice.document_kind,
    'ksefRequired', v_invoice.ksef_required,
    'emailStatus', v_invoice.email_status,
    'replayed', v_invoice.created_at < now() - interval '1 millisecond'
  ));
END;
$$;


--
-- Name: accounting_invoice_issue_request_v2(text, uuid, text, text, text, text, text, uuid, jsonb, jsonb, jsonb, jsonb, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_issue_request_v2(p_idempotency_key text, p_order_id uuid, p_invoice_ref text, p_document_type text, p_buyer_kind text, p_ksef_requirement text, p_policy_version text, p_policy_approval_id uuid, p_buyer_snapshot jsonb, p_order_snapshot jsonb, p_tax_snapshot jsonb, p_lines_snapshot jsonb, p_total_net_cents integer, p_total_gross_cents integer, p_provider_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_policy public.accounting_document_policy_approvals%ROWTYPE;
  v_invoice public.accounting_invoices%ROWTYPE;
  v_replayed boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_order_id IS NULL
    OR p_invoice_ref IS NULL OR btrim(p_invoice_ref) = ''
    OR p_provider_kind IS NULL OR btrim(p_provider_kind) = ''
    OR p_total_net_cents IS NULL OR p_total_net_cents < 0
    OR p_total_gross_cents IS NULL OR p_total_gross_cents < p_total_net_cents
  THEN
    RAISE EXCEPTION 'accounting_invoice_issue_v2_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_invoice_issue_order_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_order.status <> 'paid' THEN
    RAISE EXCEPTION 'accounting_invoice_issue_requires_paid_order' USING ERRCODE = '22023';
  END IF;
  IF v_order.total_cents <> p_total_gross_cents OR v_order.currency <> COALESCE(p_order_snapshot->>'currency', v_order.currency) THEN
    RAISE EXCEPTION 'accounting_invoice_issue_order_total_mismatch' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_policy
    FROM public.accounting_document_policy_approvals
   WHERE id = p_policy_approval_id
     AND active = true
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'accounting_invoice_issue_policy_not_approved' USING ERRCODE = '22023';
  END IF;
  IF v_policy.document_type <> p_document_type
    OR v_policy.buyer_kind <> p_buyer_kind
    OR v_policy.ksef_requirement <> p_ksef_requirement
    OR v_policy.policy_version <> p_policy_version
  THEN
    RAISE EXCEPTION 'accounting_invoice_issue_policy_mismatch' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.accounting_invoices (
    order_id,
    order_ref,
    invoice_ref,
    status,
    currency,
    buyer_snapshot,
    order_snapshot,
    tax_snapshot,
    lines_snapshot,
    total_net_cents,
    total_gross_cents,
    provider_kind,
    document_type,
    buyer_kind,
    ksef_requirement,
    policy_version,
    policy_approval_id
  )
  VALUES (
    p_order_id,
    COALESCE(v_order.order_number, 'order_' || v_order.id::text),
    p_invoice_ref,
    'issue_requested',
    v_order.currency,
    COALESCE(p_buyer_snapshot, '{}'::jsonb),
    COALESCE(p_order_snapshot, '{}'::jsonb),
    COALESCE(p_tax_snapshot, '{}'::jsonb),
    COALESCE(p_lines_snapshot, '[]'::jsonb),
    p_total_net_cents,
    p_total_gross_cents,
    p_provider_kind,
    p_document_type,
    p_buyer_kind,
    p_ksef_requirement,
    p_policy_version,
    p_policy_approval_id
  )
  ON CONFLICT (invoice_ref) DO UPDATE
    SET updated_at = public.accounting_invoices.updated_at
  RETURNING * INTO v_invoice;

  v_replayed := v_invoice.created_at < now() - interval '1 millisecond';

  IF v_invoice.order_id IS DISTINCT FROM p_order_id
    OR v_invoice.total_net_cents IS DISTINCT FROM p_total_net_cents
    OR v_invoice.total_gross_cents IS DISTINCT FROM p_total_gross_cents
    OR v_invoice.provider_kind IS DISTINCT FROM p_provider_kind
    OR v_invoice.document_type IS DISTINCT FROM p_document_type
    OR v_invoice.buyer_kind IS DISTINCT FROM p_buyer_kind
    OR v_invoice.ksef_requirement IS DISTINCT FROM p_ksef_requirement
    OR v_invoice.policy_approval_id IS DISTINCT FROM p_policy_approval_id
  THEN
    RAISE EXCEPTION 'accounting_invoice_issue_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  IF v_invoice.status IN ('accepted', 'corrected') THEN
    RAISE EXCEPTION 'accounting_invoice_accepted_requires_correction' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.accounting_invoice_issue_outbox (invoice_id, provider_kind)
  VALUES (v_invoice.id, p_provider_kind)
  ON CONFLICT (invoice_id, provider_kind) DO NOTHING;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
  VALUES (
    v_invoice.id,
    'issue_requested',
    p_provider_kind,
    jsonb_build_object(
      'idempotencyKey', p_idempotency_key,
      'policyApprovalId', p_policy_approval_id,
      'documentType', p_document_type,
      'buyerKind', p_buyer_kind,
      'ksefRequirement', p_ksef_requirement
    )
  );

  RETURN jsonb_build_object(
    'invoice',
    jsonb_build_object(
      'id', v_invoice.id,
      'orderId', v_invoice.order_id,
      'invoiceRef', v_invoice.invoice_ref,
      'status', v_invoice.status,
      'documentType', v_invoice.document_type,
      'buyerKind', v_invoice.buyer_kind,
      'ksefRequirement', v_invoice.ksef_requirement,
      'ksefStatus', v_invoice.ksef_status,
      'providerKind', v_invoice.provider_kind,
      'providerInvoiceId', v_invoice.provider_invoice_id,
      'providerInvoiceNumber', v_invoice.provider_invoice_number,
      'totalGrossMinor', v_invoice.total_gross_cents,
      'currency', v_invoice.currency
    ),
    'replayed', v_replayed
  );
END;
$$;


--
-- Name: accounting_invoice_ksef_poll_candidates(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_ksef_poll_candidates(p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH candidates AS (
    SELECT id, provider_kind, provider_invoice_id, provider_invoice_number, ksef_status, updated_at
      FROM public.accounting_invoices
     WHERE provider_kind = 'fakturownia'
       AND provider_invoice_id IS NOT NULL
       AND ksef_required = true
       AND (
         ksef_status = 'pending'
         OR (ksef_status = 'accepted' AND (provider_xml_ref IS NULL OR provider_upo_ref IS NULL))
       )
     ORDER BY updated_at
     LIMIT greatest(least(coalesce(p_limit, 25), 100), 1)
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'invoiceId', id,
    'providerKind', provider_kind,
    'providerInvoiceId', provider_invoice_id,
    'providerInvoiceNumber', provider_invoice_number,
    'ksefStatus', ksef_status
  ) ORDER BY updated_at), '[]'::jsonb)
    FROM candidates;
$$;


--
-- Name: accounting_invoice_record_email_status(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_record_email_status(p_invoice_id uuid, p_email_status text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_invoice public.accounting_invoices%ROWTYPE;
BEGIN
  IF p_email_status NOT IN ('not_required', 'pending', 'sent', 'failed') THEN
    RAISE EXCEPTION 'accounting_invoice_email_status_invalid' USING ERRCODE = '22023';
  END IF;

  UPDATE public.accounting_invoices
     SET email_status = p_email_status,
         updated_at = now()
   WHERE id = p_invoice_id
  RETURNING * INTO v_invoice;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_not_found' USING ERRCODE = '22023'; END IF;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, payload)
  VALUES (p_invoice_id, 'email_status_recorded', coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('emailStatus', p_email_status));

  RETURN jsonb_build_object('invoice', jsonb_build_object('id', v_invoice.id, 'emailStatus', v_invoice.email_status));
END;
$$;


--
-- Name: accounting_invoice_record_ksef_status(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_record_ksef_status(p_invoice_id uuid, p_ksef_number text, p_ksef_status text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_invoice public.accounting_invoices%ROWTYPE;
BEGIN
  IF p_ksef_status NOT IN ('not_submitted', 'pending', 'accepted', 'rejected', 'not_required') THEN
    RAISE EXCEPTION 'accounting_invoice_ksef_status_invalid' USING ERRCODE = '22023';
  END IF;

  UPDATE public.accounting_invoices
     SET ksef_number = coalesce(p_ksef_number, ksef_number),
         ksef_status = p_ksef_status,
         ksef_updated_at = now(),
         status = CASE WHEN p_ksef_status = 'accepted' THEN 'accepted' ELSE status END,
         email_status = CASE
           WHEN p_ksef_status = 'accepted' AND document_kind = 'b2b_vat' THEN 'pending'
           ELSE email_status
         END,
         updated_at = now()
   WHERE id = p_invoice_id
  RETURNING * INTO v_invoice;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_not_found' USING ERRCODE = '22023'; END IF;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, ksef_status, payload)
  VALUES (p_invoice_id, 'ksef_status_recorded', p_ksef_status, coalesce(p_payload, '{}'::jsonb));

  IF p_ksef_status = 'accepted'
    AND v_invoice.document_kind = 'b2b_vat'
    AND v_invoice.ksef_required = true
    AND v_invoice.provider_kind IS NOT NULL
    AND v_invoice.provider_invoice_id IS NOT NULL
  THEN
    INSERT INTO public.accounting_invoice_delivery_outbox (
      invoice_id, provider_kind, delivery_kind, metadata
    )
    VALUES (
      v_invoice.id,
      v_invoice.provider_kind,
      'provider_email',
      jsonb_build_object('source', 'ksef_accepted', 'documentKind', v_invoice.document_kind)
    )
    ON CONFLICT (invoice_id, provider_kind, delivery_kind) DO UPDATE
      SET metadata = public.accounting_invoice_delivery_outbox.metadata || EXCLUDED.metadata,
          status = CASE
            WHEN public.accounting_invoice_delivery_outbox.status = 'succeeded' THEN 'succeeded'
            ELSE public.accounting_invoice_delivery_outbox.status
          END;
  END IF;

  RETURN jsonb_build_object('invoice', jsonb_build_object(
    'id', v_invoice.id, 'ksefStatus', v_invoice.ksef_status, 'status', v_invoice.status
  ));
END;
$$;


--
-- Name: accounting_invoice_record_provider_ref(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_record_provider_ref(p_invoice_id uuid, p_provider_kind text, p_provider_invoice_id text, p_provider_invoice_number text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice public.accounting_invoices%ROWTYPE;
BEGIN
  UPDATE public.accounting_invoices
     SET provider_kind = p_provider_kind,
         provider_invoice_id = p_provider_invoice_id,
         provider_invoice_number = p_provider_invoice_number,
         status = CASE WHEN status = 'issue_requested' THEN 'issued' ELSE status END,
         updated_at = now()
   WHERE id = p_invoice_id
  RETURNING * INTO v_invoice;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_not_found' USING ERRCODE = '22023'; END IF;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, provider_ref)
  VALUES (p_invoice_id, 'provider_ref_recorded', p_provider_kind, p_provider_invoice_id);

  RETURN jsonb_build_object('invoice', jsonb_build_object('id', v_invoice.id, 'status', v_invoice.status));
END;
$$;


--
-- Name: accounting_invoice_request_correction(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_request_correction(p_invoice_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_invoice public.accounting_invoices%ROWTYPE;
BEGIN
  SELECT * INTO v_invoice FROM public.accounting_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_not_found' USING ERRCODE = '22023'; END IF;
  IF v_invoice.status <> 'accepted' THEN
    RAISE EXCEPTION 'accounting_invoice_correction_requires_accepted_invoice' USING ERRCODE = '22023';
  END IF;

  UPDATE public.accounting_invoices
     SET correction_status = 'requested',
         status = 'correction_requested',
         metadata = metadata || jsonb_build_object('correctionReason', p_reason),
         updated_at = now()
   WHERE id = p_invoice_id;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, payload)
  VALUES (p_invoice_id, 'correction_requested', jsonb_build_object('reason', p_reason));

  RETURN jsonb_build_object('invoice', jsonb_build_object('id', p_invoice_id, 'correctionStatus', 'requested'));
END;
$$;


--
-- Name: accounting_invoice_request_correction_scaffold(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_request_correction_scaffold(p_invoice_id uuid, p_reason text, p_payload jsonb DEFAULT '{}'::jsonb, p_provider_kind text DEFAULT 'fakturownia'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_invoice public.accounting_invoices%ROWTYPE;
  v_outbox public.accounting_invoice_correction_outbox%ROWTYPE;
BEGIN
  IF p_reason IS NULL OR length(btrim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'accounting_correction_reason_required' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice
    FROM public.accounting_invoices
   WHERE id = p_invoice_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'accounting_invoice_not_found' USING ERRCODE = '22023'; END IF;
  IF v_invoice.provider_invoice_id IS NULL OR v_invoice.status NOT IN ('issued', 'accepted') THEN
    RAISE EXCEPTION 'accounting_correction_requires_issued_invoice' USING ERRCODE = '22023';
  END IF;

  UPDATE public.accounting_invoices
     SET correction_status = 'requested',
         status = 'correction_requested',
         metadata = metadata || jsonb_build_object('correctionReason', p_reason),
         updated_at = now()
   WHERE id = p_invoice_id
  RETURNING * INTO v_invoice;

  INSERT INTO public.accounting_invoice_correction_outbox (
    invoice_id, provider_kind, correction_reason, payload
  )
  VALUES (p_invoice_id, p_provider_kind, p_reason, coalesce(p_payload, '{}'::jsonb))
  ON CONFLICT (invoice_id, provider_kind, correction_reason) DO UPDATE
    SET payload = public.accounting_invoice_correction_outbox.payload
  RETURNING * INTO v_outbox;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
  VALUES (p_invoice_id, 'correction_requested_scaffold', p_provider_kind, jsonb_build_object('reason', p_reason));

  RETURN jsonb_build_object('correctionOutbox', jsonb_build_object(
    'id', v_outbox.id,
    'invoiceId', v_outbox.invoice_id,
    'status', v_outbox.status
  ));
END;
$$;


--
-- Name: accounting_invoice_request_reversal_from_order_status(text, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_invoice_request_reversal_from_order_status(p_idempotency_key text, p_order_id uuid, p_reason text, p_payload jsonb DEFAULT '{}'::jsonb, p_provider_kind text DEFAULT 'fakturownia'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_invoice public.accounting_invoices%ROWTYPE;
  v_outbox public.accounting_invoice_correction_outbox%ROWTYPE;
  v_action text;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_order_id IS NULL
    OR p_reason NOT IN ('order_canceled', 'order_refunded')
  THEN
    RAISE EXCEPTION 'accounting_reversal_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice
    FROM public.accounting_invoices
   WHERE order_id = p_order_id
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('invoice', NULL, 'action', 'no_invoice', 'replayed', true);
  END IF;

  IF v_invoice.status IN ('voided', 'corrected') THEN
    RETURN jsonb_build_object('invoice', jsonb_build_object('id', v_invoice.id, 'status', v_invoice.status, 'providerInvoiceId', v_invoice.provider_invoice_id), 'action', v_invoice.status, 'replayed', true);
  END IF;

  IF v_invoice.provider_invoice_id IS NULL THEN
    UPDATE public.accounting_invoice_issue_outbox
       SET status = 'cancelled', processed_at = now(), next_attempt_at = NULL
     WHERE invoice_id = v_invoice.id
       AND status IN ('pending', 'failed', 'processing');
    UPDATE public.accounting_invoice_delivery_outbox
       SET status = 'cancelled', processed_at = now(), next_attempt_at = NULL
     WHERE invoice_id = v_invoice.id
       AND status IN ('pending', 'failed', 'processing');
    UPDATE public.accounting_invoices
       SET status = 'voided',
           email_status = 'not_required',
           metadata = metadata || jsonb_build_object('reversalReason', p_reason, 'reversalIdempotencyKey', p_idempotency_key),
           updated_at = now()
     WHERE id = v_invoice.id
    RETURNING * INTO v_invoice;
    v_action := 'voided';
  ELSE
    UPDATE public.accounting_invoices
       SET status = 'correction_requested',
           correction_status = 'requested',
           metadata = metadata || jsonb_build_object('correctionReason', p_reason, 'reversalIdempotencyKey', p_idempotency_key),
           updated_at = now()
     WHERE id = v_invoice.id
    RETURNING * INTO v_invoice;

    INSERT INTO public.accounting_invoice_correction_outbox (invoice_id, provider_kind, correction_reason, payload)
    VALUES (v_invoice.id, p_provider_kind, p_reason, coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('source', 'order_status_reversal'))
    ON CONFLICT (invoice_id, provider_kind, correction_reason) DO UPDATE
      SET payload = public.accounting_invoice_correction_outbox.payload || EXCLUDED.payload
    RETURNING * INTO v_outbox;
    v_action := 'correction_requested';
  END IF;

  INSERT INTO public.accounting_invoice_operations (invoice_id, operation, provider_kind, payload)
  VALUES (v_invoice.id, 'reversal_requested', p_provider_kind, coalesce(p_payload, '{}'::jsonb) || jsonb_build_object('reason', p_reason, 'action', v_action));

  RETURN jsonb_build_object('invoice', jsonb_build_object('id', v_invoice.id, 'status', v_invoice.status, 'providerInvoiceId', v_invoice.provider_invoice_id), 'action', v_action, 'replayed', false);
END;
$$;


--
-- Name: accounting_is_valid_pl_nip(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_is_valid_pl_nip(p_tax_id text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_digits text := public.accounting_normalize_pl_nip(p_tax_id);
  v_weights integer[] := ARRAY[6,5,7,2,3,4,5,6,7];
  v_sum integer := 0;
  v_index integer;
  v_checksum integer;
BEGIN
  IF v_digits IS NULL OR v_digits !~ '^\d{10}$' THEN
    RETURN false;
  END IF;

  FOR v_index IN 1..9 LOOP
    v_sum := v_sum + substring(v_digits from v_index for 1)::integer * v_weights[v_index];
  END LOOP;

  v_checksum := v_sum % 11;
  RETURN v_checksum <> 10 AND v_checksum = substring(v_digits from 10 for 1)::integer;
END;
$_$;


--
-- Name: accounting_normalize_pl_nip(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_normalize_pl_nip(p_tax_id text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT NULLIF(regexp_replace(coalesce(p_tax_id, ''), '\D', '', 'g'), '');
$$;


--
-- Name: accounting_order_payment_validation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_order_payment_validation(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_payment public.commerce_payments%ROWTYPE;
  v_settlement public.payment_provider_settlement_items%ROWTYPE;
  v_succeeded_count integer;
  v_settlement_count integer := 0;
  v_matched_settlement_count integer := 0;
  v_local_settlement_state text := 'unavailable';
  v_code text;
BEGIN
  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'accounting_invoice_order_not_found');
  END IF;

  SELECT count(*)::integer INTO v_succeeded_count
    FROM public.commerce_payment_intents
   WHERE order_id = p_order_id
     AND status = 'succeeded';
  IF v_succeeded_count <> 1 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', 'accounting_invoice_payment_intent_count_mismatch',
      'succeededIntentCount', v_succeeded_count
    );
  END IF;

  SELECT * INTO STRICT v_intent
    FROM public.commerce_payment_intents
   WHERE order_id = p_order_id
     AND status = 'succeeded';

  SELECT * INTO v_payment
    FROM public.commerce_payments
   WHERE id = v_intent.payment_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'accounting_invoice_payment_record_not_found');
  END IF;

  IF v_intent.amount_cents IS DISTINCT FROM v_order.total_cents THEN
    v_code := 'accounting_invoice_payment_intent_amount_mismatch';
  ELSIF upper(v_intent.currency) IS DISTINCT FROM upper(v_order.currency) THEN
    v_code := 'accounting_invoice_payment_intent_currency_mismatch';
  END IF;
  IF v_code IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'code', v_code,
      'intentId', v_intent.id,
      'orderAmountCents', v_order.total_cents,
      'intentAmountCents', v_intent.amount_cents,
      'orderCurrency', upper(v_order.currency),
      'intentCurrency', upper(v_intent.currency)
    );
  END IF;

  -- Settlement imports are authoritative only for the final provider reference
  -- frozen on the succeeded intent. Old retry references attached to the same
  -- intent are audit history and must not block the final payment. Conversely,
  -- inspect every import for that final reference: a later matched row cannot
  -- hide an earlier confirmed mismatch.
  IF v_intent.provider_payment_id IS NOT NULL THEN
    SELECT settlement.* INTO v_settlement
      FROM public.payment_provider_settlement_items settlement
     WHERE settlement.provider_payment_id = v_intent.provider_payment_id
       AND settlement.provider_kind = v_payment.provider
       AND (
         settlement.gross_cents IS DISTINCT FROM v_order.total_cents
         OR upper(settlement.currency) IS DISTINCT FROM upper(v_order.currency)
         OR settlement.status IN ('mismatch', 'unmatched')
       )
     ORDER BY
       (settlement.gross_cents IS DISTINCT FROM v_order.total_cents) DESC,
       (upper(settlement.currency) IS DISTINCT FROM upper(v_order.currency)) DESC,
       settlement.created_at DESC,
       settlement.id DESC
     LIMIT 1;

    IF FOUND THEN
    IF v_settlement.gross_cents IS DISTINCT FROM v_order.total_cents THEN
      RETURN jsonb_build_object(
        'ok', false,
        'code', 'accounting_invoice_local_settlement_amount_mismatch',
        'intentId', v_intent.id,
        'settlementItemId', v_settlement.id,
        'orderAmountCents', v_order.total_cents,
        'settlementAmountCents', v_settlement.gross_cents
      );
    ELSIF upper(v_settlement.currency) IS DISTINCT FROM upper(v_order.currency) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'code', 'accounting_invoice_local_settlement_currency_mismatch',
        'intentId', v_intent.id,
        'settlementItemId', v_settlement.id,
        'orderCurrency', upper(v_order.currency),
        'settlementCurrency', upper(v_settlement.currency)
      );
    ELSIF v_settlement.status IN ('mismatch', 'unmatched') THEN
      RETURN jsonb_build_object(
        'ok', false,
        'code', 'accounting_invoice_local_settlement_status_mismatch',
        'intentId', v_intent.id,
        'settlementItemId', v_settlement.id,
        'settlementStatus', v_settlement.status
      );
      END IF;
    END IF;

    SELECT
      count(*)::integer,
      count(*) FILTER (WHERE status = 'matched')::integer,
      (array_agg(id ORDER BY created_at DESC, id DESC))[1]
      INTO v_settlement_count, v_matched_settlement_count, v_settlement.id
      FROM public.payment_provider_settlement_items
     WHERE provider_payment_id = v_intent.provider_payment_id
       AND provider_kind = v_payment.provider;

    IF v_settlement_count > 0 AND v_settlement_count = v_matched_settlement_count THEN
      v_local_settlement_state := 'matched';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'code', NULL,
    'intentId', v_intent.id,
    'paymentId', v_intent.payment_id,
    'provider', v_payment.provider,
    'providerPaymentId', v_intent.provider_payment_id,
    'amountCents', v_intent.amount_cents,
    'currency', upper(v_intent.currency),
    'paymentCompletedAt', v_intent.updated_at,
    'localSettlementState', v_local_settlement_state,
    'settlementItemId', v_settlement.id
  );
END;
$$;


--
-- Name: accounting_record_payment_settlement(text, text, text, text, uuid, uuid, uuid, integer, integer, integer, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_record_payment_settlement(p_idempotency_key text, p_provider_kind text, p_provider_batch_id text, p_provider_payment_id text, p_payment_intent_id uuid, p_payment_id uuid, p_invoice_id uuid, p_gross_cents integer, p_fee_cents integer, p_net_cents integer, p_currency text, p_status text, p_bank_received_at timestamp with time zone, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch public.payment_provider_settlement_batches%ROWTYPE;
  v_item public.payment_provider_settlement_items%ROWTYPE;
  v_replayed boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_provider_kind IS NULL OR btrim(p_provider_kind) = ''
    OR p_provider_batch_id IS NULL OR btrim(p_provider_batch_id) = ''
    OR p_provider_payment_id IS NULL OR btrim(p_provider_payment_id) = ''
    OR p_gross_cents IS NULL OR p_gross_cents < 0
    OR p_fee_cents IS NULL OR p_fee_cents < 0
    OR p_net_cents IS NULL OR p_net_cents < 0
    OR p_net_cents <> p_gross_cents - p_fee_cents
    OR p_currency IS NULL OR char_length(p_currency) <> 3
    OR p_status NOT IN ('matched', 'unmatched', 'mismatch', 'bank_pending')
  THEN
    RAISE EXCEPTION 'accounting_settlement_invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.payment_provider_settlement_batches (
    provider_kind,
    provider_batch_id,
    currency,
    status,
    gross_cents,
    fee_cents,
    net_cents,
    bank_received_at,
    evidence
  )
  VALUES (
    p_provider_kind,
    p_provider_batch_id,
    p_currency,
    CASE WHEN p_status = 'bank_pending' THEN 'bank_pending' ELSE 'observed' END,
    0,
    0,
    0,
    p_bank_received_at,
    COALESCE(p_evidence, '{}'::jsonb)
  )
  ON CONFLICT (provider_kind, provider_batch_id) DO UPDATE
    SET updated_at = now(),
        bank_received_at = COALESCE(EXCLUDED.bank_received_at, payment_provider_settlement_batches.bank_received_at),
        evidence = payment_provider_settlement_batches.evidence || EXCLUDED.evidence
  RETURNING * INTO v_batch;

  INSERT INTO public.payment_provider_settlement_items (
    batch_id,
    provider_kind,
    provider_payment_id,
    payment_intent_id,
    payment_id,
    invoice_id,
    gross_cents,
    fee_cents,
    net_cents,
    currency,
    status,
    bank_received_at,
    evidence
  )
  VALUES (
    v_batch.id,
    p_provider_kind,
    p_provider_payment_id,
    p_payment_intent_id,
    p_payment_id,
    p_invoice_id,
    p_gross_cents,
    p_fee_cents,
    p_net_cents,
    p_currency,
    p_status,
    p_bank_received_at,
    COALESCE(p_evidence, '{}'::jsonb) || jsonb_build_object('idempotencyKey', p_idempotency_key)
  )
  ON CONFLICT (batch_id, provider_payment_id) DO NOTHING
  RETURNING * INTO v_item;

  IF NOT FOUND THEN
    v_replayed := true;
    SELECT * INTO v_item
      FROM public.payment_provider_settlement_items
     WHERE batch_id = v_batch.id
       AND provider_payment_id = p_provider_payment_id;
  END IF;

  UPDATE public.payment_provider_settlement_batches
     SET updated_at = now(),
         gross_cents = COALESCE((SELECT SUM(gross_cents) FROM public.payment_provider_settlement_items WHERE batch_id = v_batch.id), 0),
         fee_cents = COALESCE((SELECT SUM(fee_cents) FROM public.payment_provider_settlement_items WHERE batch_id = v_batch.id), 0),
         net_cents = COALESCE((SELECT SUM(net_cents) FROM public.payment_provider_settlement_items WHERE batch_id = v_batch.id), 0),
         status = CASE
           WHEN EXISTS (SELECT 1 FROM public.payment_provider_settlement_items WHERE batch_id = v_batch.id AND status IN ('mismatch', 'unmatched')) THEN 'mismatch'
           WHEN EXISTS (SELECT 1 FROM public.payment_provider_settlement_items WHERE batch_id = v_batch.id AND status = 'bank_pending') THEN 'bank_pending'
           ELSE 'reconciled'
         END
   WHERE id = v_batch.id;

  IF p_payment_intent_id IS NOT NULL THEN
    PERFORM public.commerce_payment_control_record_reconciliation(
      p_idempotency_key || ':payment-reconciliation',
      p_provider_kind,
      p_provider_payment_id,
      p_payment_intent_id,
      NULL,
      COALESCE((SELECT status FROM public.commerce_payment_intents WHERE id = p_payment_intent_id), 'unknown'),
      CASE WHEN p_status = 'matched' THEN 'settled' ELSE p_status END,
      CASE WHEN p_status = 'matched' THEN 'observed' ELSE 'failed' END,
      COALESCE(p_bank_received_at, now()),
      COALESCE(p_evidence, '{}'::jsonb) || jsonb_build_object('settlementItemId', v_item.id)
    );
  END IF;

  RETURN jsonb_build_object('settlementItemId', v_item.id, 'replayed', v_replayed);
END;
$$;


--
-- Name: accounting_record_provider_sync_event(text, uuid, text, text, text, text, text, text, text, text, text, text, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_record_provider_sync_event(p_idempotency_key text, p_invoice_id uuid, p_provider_kind text, p_provider_event_id text, p_event_type text, p_provider_invoice_id text, p_provider_invoice_number text, p_ksef_number text, p_ksef_status text, p_status_source text, p_provider_pdf_ref text, p_provider_xml_ref text, p_observed_at timestamp with time zone, p_payload_hash text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_event public.accounting_provider_sync_events%ROWTYPE;
  v_replayed boolean := false;
  v_next_invoice_status text;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_invoice_id IS NULL
    OR p_provider_kind IS NULL OR btrim(p_provider_kind) = ''
    OR p_provider_event_id IS NULL OR btrim(p_provider_event_id) = ''
    OR p_event_type NOT IN (
      'invoice.created',
      'invoice.updated',
      'invoice.pdf_ready',
      'invoice.xml_ready',
      'ksef.pending',
      'ksef.accepted',
      'ksef.rejected',
      'correction.requested',
      'correction.issued',
      'correction.accepted',
      'provider.mismatch'
    )
    OR p_status_source NOT IN ('provider_api', 'provider_webhook', 'manual_reconciliation')
    OR p_payload_hash IS NULL OR btrim(p_payload_hash) = ''
  THEN
    RAISE EXCEPTION 'accounting_provider_sync_invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.accounting_provider_sync_events (
    invoice_id,
    provider_kind,
    provider_event_id,
    event_type,
    provider_invoice_id,
    provider_invoice_number,
    ksef_number,
    ksef_status,
    status_source,
    provider_pdf_ref,
    provider_xml_ref,
    observed_at,
    payload_hash,
    payload
  )
  VALUES (
    p_invoice_id,
    p_provider_kind,
    p_provider_event_id,
    p_event_type,
    p_provider_invoice_id,
    p_provider_invoice_number,
    p_ksef_number,
    p_ksef_status,
    p_status_source,
    p_provider_pdf_ref,
    p_provider_xml_ref,
    COALESCE(p_observed_at, now()),
    p_payload_hash,
    COALESCE(p_payload, '{}'::jsonb)
  )
  ON CONFLICT (provider_kind, provider_event_id) DO NOTHING
  RETURNING * INTO v_event;

  IF NOT FOUND THEN
    v_replayed := true;
    SELECT * INTO v_event
      FROM public.accounting_provider_sync_events
     WHERE provider_kind = p_provider_kind
       AND provider_event_id = p_provider_event_id;
  END IF;

  v_next_invoice_status := CASE
    WHEN p_event_type = 'ksef.pending' THEN 'ksef_pending'
    WHEN p_event_type = 'ksef.accepted' THEN 'accepted'
    WHEN p_event_type = 'ksef.rejected' THEN 'rejected'
    WHEN p_event_type = 'correction.requested' THEN 'correction_requested'
    WHEN p_event_type = 'correction.accepted' THEN 'corrected'
    WHEN p_event_type = 'invoice.created' THEN 'issued'
    ELSE NULL
  END;

  IF NOT v_replayed THEN
    UPDATE public.accounting_invoices
       SET provider_kind = p_provider_kind,
           provider_invoice_id = COALESCE(p_provider_invoice_id, provider_invoice_id),
           provider_invoice_number = COALESCE(p_provider_invoice_number, provider_invoice_number),
           provider_pdf_ref = COALESCE(p_provider_pdf_ref, provider_pdf_ref),
           provider_xml_ref = COALESCE(p_provider_xml_ref, provider_xml_ref),
           ksef_number = COALESCE(p_ksef_number, ksef_number),
           ksef_status = COALESCE(p_ksef_status, ksef_status),
           ksef_updated_at = CASE WHEN p_ksef_status IS NULL THEN ksef_updated_at ELSE now() END,
           ksef_registration_date = CASE WHEN p_event_type = 'ksef.accepted' THEN COALESCE(p_observed_at, now()) ELSE ksef_registration_date END,
           status = COALESCE(v_next_invoice_status, status),
           updated_at = now()
     WHERE id = p_invoice_id;

    UPDATE public.accounting_provider_sync_events
       SET processed_at = now(),
           processing_status = CASE WHEN p_event_type = 'provider.mismatch' THEN 'quarantined' ELSE 'processed' END
     WHERE id = v_event.id;

    INSERT INTO public.accounting_invoice_operations (
      invoice_id,
      operation,
      provider_kind,
      provider_ref,
      ksef_status,
      payload
    )
    VALUES (
      p_invoice_id,
      'provider_sync_event_recorded',
      p_provider_kind,
      p_provider_invoice_id,
      p_ksef_status,
      jsonb_build_object(
        'idempotencyKey', p_idempotency_key,
        'providerEventId', p_provider_event_id,
        'eventType', p_event_type,
        'statusSource', p_status_source
      )
    );
  END IF;

  RETURN jsonb_build_object('eventId', v_event.id, 'replayed', v_replayed);
END;
$$;


