--
-- Name: admin_activate_bundle(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_activate_bundle(p_actor_id uuid, p_code text, p_mode text DEFAULT 'commit'::text, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_source text DEFAULT 'agent_bundle'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_is_machine boolean;
  v_bundle public.catalog_bundles%ROWTYPE;
  v_components integer;
  v_prices integer;
BEGIN
  IF p_actor_id IS NULL THEN RAISE EXCEPTION 'actor_required' USING ERRCODE='42501'; END IF;
  SELECT is_machine_actor INTO v_is_machine FROM public.admin_users WHERE id = p_actor_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'actor_unknown' USING ERRCODE='42501'; END IF;

  -- PUBLISH GATE: human-only, re-derived from the admin registry and never taken
  -- from the caller. This is the second of the two independent layers; the handler
  -- already refused a machine actor from the spec's allowedActorKinds.
  IF COALESCE(v_is_machine, true) THEN
    RAISE EXCEPTION 'publish_requires_human' USING ERRCODE='42501';
  END IF;

  IF p_idempotency_key IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.admin_audit_events
    WHERE entity_type='catalog_bundle' AND idempotency_key=p_idempotency_key
  ) THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', true, 'dryRun', false);
  END IF;

  SELECT * INTO v_bundle FROM public.catalog_bundles WHERE code = p_code;
  IF NOT FOUND THEN RAISE EXCEPTION 'bundle_not_found' USING ERRCODE='P0002'; END IF;

  -- Only the exploded mode has a runtime. The column admits the pre-packed mode so
  -- it never has to be widened on a populated table; the refusal lives here, where
  -- it can name the reason, rather than in a CHECK that cannot.
  IF v_bundle.fulfillment_mode <> 'virtual' THEN
    RAISE EXCEPTION 'fulfillment_mode_unsupported' USING ERRCODE='P0001';
  END IF;

  SELECT count(*) INTO v_components
  FROM public.catalog_bundle_components WHERE bundle_id = v_bundle.id;
  IF v_components = 0 THEN
    RAISE EXCEPTION 'composition_required_to_sell' USING ERRCODE='P0001';
  END IF;

  SELECT count(*) INTO v_prices
  FROM public.catalog_bundle_prices WHERE bundle_id = v_bundle.id AND active;
  IF v_prices = 0 THEN
    RAISE EXCEPTION 'price_required_to_sell' USING ERRCODE='P0001';
  END IF;

  IF p_mode = 'dry_run' THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', true);
  END IF;

  UPDATE public.catalog_bundles SET status='active', updated_at=now() WHERE id = v_bundle.id;

  PERFORM public.record_admin_audit_event(
    p_actor_id, 'bundle_activate', p_source, 'catalog_bundle', p_code,
    jsonb_build_object('status', v_bundle.status), jsonb_build_object('status', 'active'),
    p_idempotency_key, p_request_id);

  RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', false);
END;
$$;


--
-- Name: admin_activate_catalog_product(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_activate_catalog_product(p_actor_id uuid, p_slug text, p_mode text DEFAULT 'commit'::text, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_source text DEFAULT 'agent_catalog'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'legacy_catalog_mutation_fenced' USING ERRCODE = '42501';
END;
$$;


--
-- Name: admin_archive_bundle(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_archive_bundle(p_actor_id uuid, p_code text, p_mode text DEFAULT 'commit'::text, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_source text DEFAULT 'agent_bundle'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_is_machine boolean;
  v_status text;
BEGIN
  IF p_actor_id IS NULL THEN RAISE EXCEPTION 'actor_required' USING ERRCODE='42501'; END IF;
  SELECT is_machine_actor INTO v_is_machine FROM public.admin_users WHERE id = p_actor_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'actor_unknown' USING ERRCODE='42501'; END IF;

  IF p_idempotency_key IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.admin_audit_events
    WHERE entity_type='catalog_bundle' AND idempotency_key=p_idempotency_key
  ) THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', true, 'dryRun', false);
  END IF;

  SELECT status INTO v_status FROM public.catalog_bundles WHERE code = p_code;
  IF NOT FOUND THEN RAISE EXCEPTION 'bundle_not_found' USING ERRCODE='P0002'; END IF;

  IF p_mode = 'dry_run' THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', true);
  END IF;

  -- Removal is a status flip. A bundle an order or a subscription already refers
  -- to must remain resolvable, so there is no delete path here at all.
  UPDATE public.catalog_bundles SET status='archived', updated_at=now() WHERE code = p_code;

  PERFORM public.record_admin_audit_event(
    p_actor_id, 'bundle_archive', p_source, 'catalog_bundle', p_code,
    jsonb_build_object('status', v_status), jsonb_build_object('status', 'archived'),
    p_idempotency_key, p_request_id);

  RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', false);
END;
$$;


