--
-- Name: admin_client_search_digits(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_client_search_digits(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT regexp_replace(COALESCE(p_value, ''), '[^0-9]+', '', 'g');
$$;


--
-- Name: admin_client_search_normalize(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_client_search_normalize(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT btrim(regexp_replace(
    translate(lower(COALESCE(p_value, '')), 'ąćęłńóśźż', 'acelnoszz'),
    '[^a-z0-9@.+-]+', ' ', 'g'
  ));
$$;


--
-- Name: admin_clients_search_v3(text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_clients_search_v3(p_query text, p_page integer DEFAULT 0, p_page_size integer DEFAULT 20, p_lifecycle_stage text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    SET "pg_trgm.similarity_threshold" TO '0.28'
    AS $$
DECLARE
  v_query text := btrim(COALESCE(p_query, ''));
  v_query_normalized text;
  v_query_digits text;
  v_query_is_email boolean := position('@' IN v_query) > 0;
  v_query_uuid uuid;
  v_page integer := COALESCE(p_page, 0);
  v_page_size integer := LEAST(GREATEST(COALESCE(p_page_size, 20), 1), 50);
  v_result jsonb;
BEGIN
  IF v_query = '' OR char_length(v_query) > 200 THEN
    RAISE EXCEPTION 'admin_clients_search_query_invalid' USING ERRCODE = '22023';
  END IF;
  IF v_page < 0 OR COALESCE(p_lifecycle_stage, 'all') NOT IN (
    'all', 'lead', 'waitlist', 'tester', 'customer', 'inactive'
  ) THEN
    RAISE EXCEPTION 'admin_clients_search_page_invalid' USING ERRCODE = '22023';
  END IF;

  v_query_normalized := public.admin_client_search_normalize(v_query);
  v_query_digits := CASE WHEN v_query_is_email THEN ''
    ELSE public.admin_client_search_digits(v_query) END;
  IF v_query_normalized !~ '[a-z0-9]' THEN
    RAISE EXCEPTION 'admin_clients_search_query_invalid' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_query_uuid := v_query::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_query_uuid := NULL;
  END;

  -- Qualify source identities before relationship/activity enrichment. The
  -- trigram predicates below match the expression indexes above, so fuzzy and
  -- leading-substring searches do not execute lateral aggregates for every
  -- customer in the registry.
  WITH physical_candidate_ids AS MATERIALIZED (
    SELECT client_row.id AS client_id
    FROM public.clients AS client_row
    WHERE client_row.identity_kind = 'customer'
      AND (
        client_row.id = v_query_uuid
        OR public.admin_client_search_normalize(
          COALESCE(client_row.email, '') || ' ' || COALESCE(client_row.first_name, '') || ' ' ||
          COALESCE(client_row.last_name, '') || ' ' || COALESCE(client_row.phone, '')
        ) LIKE '%' || v_query_normalized || '%'
          AND (NOT v_query_is_email OR public.admin_client_search_normalize(client_row.email)
            LIKE '%' || v_query_normalized || '%')
        OR (NOT v_query_is_email AND
          public.admin_client_search_normalize(
            COALESCE(client_row.email, '') || ' ' || COALESCE(client_row.first_name, '') || ' ' ||
            COALESCE(client_row.last_name, '') || ' ' || COALESCE(client_row.phone, '')
          ) OPERATOR(extensions.%) v_query_normalized
          AND similarity(public.admin_client_search_normalize(
            COALESCE(client_row.email, '') || ' ' || COALESCE(client_row.first_name, '') || ' ' ||
            COALESCE(client_row.last_name, '') || ' ' || COALESCE(client_row.phone, '')
          ), v_query_normalized) >= 0.32
        )
        OR (NOT v_query_is_email AND
          public.admin_client_search_normalize(
            COALESCE(client_row.first_name, '') || ' ' || COALESCE(client_row.last_name, '')
          ) OPERATOR(extensions.%) v_query_normalized
          AND similarity(public.admin_client_search_normalize(
            COALESCE(client_row.first_name, '') || ' ' || COALESCE(client_row.last_name, '')
          ), v_query_normalized) >= 0.28
        )
        OR (NOT v_query_is_email AND
          public.admin_client_search_normalize(
            COALESCE(client_row.last_name, '') || ' ' || COALESCE(client_row.first_name, '')
          ) OPERATOR(extensions.%) v_query_normalized
          AND similarity(public.admin_client_search_normalize(
            COALESCE(client_row.last_name, '') || ' ' || COALESCE(client_row.first_name, '')
          ), v_query_normalized) >= 0.28
        )
        OR (v_query_digits <> '' AND public.admin_client_search_digits(client_row.phone)
          LIKE '%' || v_query_digits || '%')
      )
    UNION
    SELECT order_row.client_id
    FROM public.commerce_orders AS order_row
    WHERE order_row.client_id IS NOT NULL AND (
      order_row.id = v_query_uuid
      OR (NOT v_query_is_email AND public.admin_client_search_normalize(order_row.order_number)
        LIKE '%' || v_query_normalized || '%'
      )
    )
    UNION
    SELECT subscription_row.client_id
    FROM public.subscriptions AS subscription_row
    WHERE subscription_row.id = v_query_uuid
  ), physical_base AS (
    SELECT
      'physical_client'::text AS source_kind,
      client_row.id::text AS source_id,
      client_row.id AS client_id,
      NULL::uuid AS tester_id,
      NULL::text AS tester_status,
      NULL::uuid AS waitlist_id,
      NULLIF(btrim(concat_ws(' ', client_row.first_name, client_row.last_name)), '') AS display_name,
      lower(client_row.email) AS email,
      NULLIF(btrim(client_row.phone), '') AS phone,
      client_row.lifecycle_stage,
      jsonb_build_array('physical_client') AS sources,
      latest_order.id AS latest_order_id,
      latest_order.order_number AS latest_order_number,
      latest_order.status AS latest_order_status,
      client_row.created_at,
      GREATEST(client_row.updated_at, latest_order.updated_at,
        subscription_match.last_activity_at) AS last_activity_at,
      public.admin_client_search_normalize(client_row.email) AS normalized_email,
      public.admin_client_search_digits(client_row.phone) AS normalized_phone,
      public.admin_client_search_normalize(
        COALESCE(client_row.first_name, '') || ' ' || COALESCE(client_row.last_name, '')
      ) AS normalized_name,
      public.admin_client_search_normalize(
        COALESCE(client_row.last_name, '') || ' ' || COALESCE(client_row.first_name, '')
      ) AS normalized_reverse_name,
      public.admin_client_search_normalize(
        COALESCE(client_row.email, '') || ' ' || COALESCE(client_row.first_name, '') || ' ' ||
        COALESCE(client_row.last_name, '') || ' ' || COALESCE(client_row.phone, '')
      ) AS search_document,
      (client_row.id::text = v_query) AS subject_exact,
      COALESCE(order_match.exact_match, false) AS order_exact,
      COALESCE(order_match.prefix_match, false) AS order_prefix,
      COALESCE(order_match.text_match, false) AS order_text,
      COALESCE(subscription_match.exact_match, false) AS subscription_exact
    FROM physical_candidate_ids AS candidate_id
    JOIN public.clients AS client_row ON client_row.id = candidate_id.client_id
    LEFT JOIN LATERAL (
      SELECT order_row.id, order_row.order_number, order_row.status, order_row.updated_at
        FROM public.commerce_orders AS order_row
       WHERE order_row.client_id = client_row.id
       ORDER BY order_row.created_at DESC, order_row.id
       LIMIT 1
    ) AS latest_order ON true
    LEFT JOIN LATERAL (
      SELECT
        bool_or(order_row.id::text = v_query OR
          public.admin_client_search_normalize(order_row.order_number) = v_query_normalized) AS exact_match,
        bool_or(public.admin_client_search_normalize(order_row.order_number)
          LIKE v_query_normalized || '%') AS prefix_match,
        bool_or(public.admin_client_search_normalize(order_row.order_number)
          LIKE '%' || v_query_normalized || '%') AS text_match
      FROM public.commerce_orders AS order_row
      WHERE order_row.client_id = client_row.id
    ) AS order_match ON true
    LEFT JOIN LATERAL (
      SELECT bool_or(subscription_row.id::text = v_query) AS exact_match,
        max(subscription_row.updated_at) AS last_activity_at
      FROM public.subscriptions AS subscription_row
      WHERE subscription_row.client_id = client_row.id
    ) AS subscription_match ON true
    WHERE client_row.identity_kind = 'customer'
  ), scored AS (
    SELECT source_row.*,
      similarity(source_row.search_document, v_query_normalized) AS text_similarity,
      GREATEST(
        similarity(source_row.normalized_name, v_query_normalized),
        similarity(source_row.normalized_reverse_name, v_query_normalized)
      ) AS name_similarity,
      CASE
        WHEN source_row.subject_exact OR source_row.normalized_email = v_query_normalized
          OR (v_query_digits <> '' AND source_row.normalized_phone = v_query_digits)
          OR source_row.order_exact OR source_row.subscription_exact THEN 0
        WHEN NOT v_query_is_email AND (source_row.normalized_name = v_query_normalized
          OR source_row.normalized_reverse_name = v_query_normalized) THEN 1
        WHEN source_row.normalized_email LIKE v_query_normalized || '%'
          OR (NOT v_query_is_email AND source_row.normalized_name LIKE v_query_normalized || '%')
          OR (NOT v_query_is_email AND source_row.normalized_reverse_name LIKE v_query_normalized || '%')
          OR (v_query_digits <> '' AND source_row.normalized_phone LIKE v_query_digits || '%')
          OR source_row.order_prefix THEN 2
        WHEN NOT v_query_is_email AND (
          source_row.search_document LIKE '%' || v_query_normalized || '%'
          OR (v_query_digits <> '' AND source_row.normalized_phone LIKE '%' || v_query_digits || '%')
          OR source_row.order_text) THEN 3
        WHEN NOT v_query_is_email AND (
          similarity(source_row.search_document, v_query_normalized) >= 0.32
          OR similarity(source_row.normalized_name, v_query_normalized) >= 0.28
          OR similarity(source_row.normalized_reverse_name, v_query_normalized) >= 0.28) THEN 4
        ELSE NULL
      END AS match_rank,
      CASE
        WHEN source_row.subject_exact THEN 'id'
        WHEN source_row.normalized_email = v_query_normalized
          OR source_row.normalized_email LIKE '%' || v_query_normalized || '%' THEN 'email'
        WHEN v_query_digits <> '' AND source_row.normalized_phone LIKE '%' || v_query_digits || '%' THEN 'phone'
        WHEN source_row.order_exact OR source_row.order_text THEN 'order'
        WHEN source_row.subscription_exact THEN 'subscription'
        WHEN NOT v_query_is_email AND (source_row.normalized_name LIKE '%' || v_query_normalized || '%'
          OR source_row.normalized_reverse_name LIKE '%' || v_query_normalized || '%'
          OR (NOT v_query_is_email AND similarity(source_row.normalized_name, v_query_normalized) >= 0.28)
          OR (NOT v_query_is_email AND similarity(source_row.normalized_reverse_name, v_query_normalized) >= 0.28)) THEN 'name'
        ELSE 'text'
      END AS match_reason
    FROM physical_base AS source_row
  ), eligible AS (
    SELECT * FROM scored
    WHERE match_rank IS NOT NULL
      AND (COALESCE(p_lifecycle_stage, 'all') = 'all' OR lifecycle_stage = p_lifecycle_stage)
  ), bounded AS (
    SELECT * FROM eligible
    ORDER BY match_rank, GREATEST(text_similarity, name_similarity) DESC,
      last_activity_at DESC NULLS LAST, source_kind, source_id
    LIMIT v_page_size OFFSET v_page::bigint * v_page_size::bigint
  )
  SELECT jsonb_build_object(
    'contractVersion', '2026-05-29.app-3a',
    'candidates', COALESCE(jsonb_agg(jsonb_build_object(
      'clientId', bounded.client_id,
      'displayName', bounded.display_name,
      'email', bounded.email,
      'phone', bounded.phone,
      'lifecycleStage', bounded.lifecycle_stage,
      'sources', bounded.sources,
      'testerId', bounded.tester_id,
      'testerStatus', bounded.tester_status,
      'waitlistId', bounded.waitlist_id,
      'latestOrderId', bounded.latest_order_id,
      'latestOrderNumber', bounded.latest_order_number,
      'latestOrderStatus', bounded.latest_order_status,
      'createdAt', bounded.created_at,
      'lastActivityAt', bounded.last_activity_at,
      'matchReason', bounded.match_reason,
      'confidence', CASE WHEN bounded.match_rank <= 1 THEN 'exact'
        WHEN bounded.match_rank <= 3 THEN 'high' ELSE 'medium' END
    ) ORDER BY bounded.match_rank,
      GREATEST(bounded.text_similarity, bounded.name_similarity) DESC,
      bounded.last_activity_at DESC NULLS LAST, bounded.source_kind, bounded.source_id), '[]'::jsonb),
    'totalCount', (SELECT count(*)::integer FROM eligible),
    'page', v_page,
    'pageSize', v_page_size
  ) INTO v_result
  FROM bounded;

  RETURN v_result;
END;
$$;


--
-- Name: admin_deactivate_bundle(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_deactivate_bundle(p_actor_id uuid, p_code text, p_mode text DEFAULT 'commit'::text, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_source text DEFAULT 'agent_bundle'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_is_machine boolean;
  v_status text;
BEGIN
  IF p_actor_id IS NULL THEN RAISE EXCEPTION 'actor_required' USING ERRCODE='42501'; END IF;
  SELECT is_machine_actor INTO v_is_machine FROM public.admin_users WHERE id = p_actor_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'actor_unknown' USING ERRCODE='42501'; END IF;

  -- Unpublish is the same class of transition as publish and carries the same gate.
  IF COALESCE(v_is_machine, true) THEN
    RAISE EXCEPTION 'publish_requires_human' USING ERRCODE='42501';
  END IF;

  IF p_idempotency_key IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.admin_audit_events
    WHERE entity_type='catalog_bundle' AND idempotency_key=p_idempotency_key
  ) THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', true, 'dryRun', false);
  END IF;

  SELECT status INTO v_status FROM public.catalog_bundles WHERE code = p_code;
  IF NOT FOUND THEN RAISE EXCEPTION 'bundle_not_found' USING ERRCODE='P0002'; END IF;
  IF v_status <> 'active' THEN
    RAISE EXCEPTION 'deactivate_requires_active' USING ERRCODE='P0001';
  END IF;

  IF p_mode = 'dry_run' THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', true);
  END IF;

  UPDATE public.catalog_bundles SET status='draft', updated_at=now() WHERE code = p_code;

  PERFORM public.record_admin_audit_event(
    p_actor_id, 'bundle_deactivate', p_source, 'catalog_bundle', p_code,
    jsonb_build_object('status', v_status), jsonb_build_object('status', 'draft'),
    p_idempotency_key, p_request_id);

  RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', false);
END;
$$;


--
-- Name: admin_deactivate_catalog_product(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_deactivate_catalog_product(p_actor_id uuid, p_slug text, p_mode text DEFAULT 'commit'::text, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_source text DEFAULT 'agent_catalog'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'legacy_catalog_mutation_fenced' USING ERRCODE = '42501';
END;
$$;


--
-- Name: admin_oms_preview_cleanup_fixture_admin(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_oms_preview_cleanup_fixture_admin(p_user_id uuid, p_email text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_fixture public.admin_users;
BEGIN
  IF p_user_id IS NULL
     OR p_email IS NULL
     OR p_email !~ '^admin-oms-preview\+[a-z0-9-]+-[a-f0-9]{8}@example\.invalid$' THEN
    RAISE EXCEPTION 'admin_oms_preview_fixture_email_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_fixture
  FROM public.admin_users
  WHERE id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_fixture.email IS DISTINCT FROM p_email THEN
    RAISE EXCEPTION 'admin_oms_preview_fixture_identity_mismatch' USING ERRCODE = '42501';
  END IF;

  IF v_fixture.is_machine_actor IS NOT TRUE
     OR v_fixture.email !~ '^admin-oms-preview\+[a-z0-9-]+-[a-f0-9]{8}@example\.invalid$' THEN
    RAISE EXCEPTION 'admin_oms_preview_fixture_cleanup_forbidden' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.admin_audit_events
  WHERE actor_admin_id = v_fixture.id
     OR target_admin_id = v_fixture.id;

  PERFORM pg_catalog.set_config('app.admin_oms_preview_fixture_cleanup', 'true', true);

  DELETE FROM public.admin_users
  WHERE id = v_fixture.id
    AND email = p_email
    AND is_machine_actor IS TRUE
    AND email ~ '^admin-oms-preview\+[a-z0-9-]+-[a-f0-9]{8}@example\.invalid$';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'admin_oms_preview_fixture_cleanup_lost_target' USING ERRCODE = '42501';
  END IF;
END;
$_$;


--
-- Name: admin_promotion_code_create(uuid, text, text, text, text[], timestamp with time zone, timestamp with time zone, integer, integer, integer, text, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_promotion_code_create(p_actor_id uuid, p_code text, p_name text, p_description text, p_scopes text[], p_valid_from timestamp with time zone, p_valid_to timestamp with time zone, p_minimum_reference_minor integer, p_redemption_limit_global integer, p_redemption_limit_per_customer integer, p_status text, p_benefits jsonb, p_idempotency_key text, p_request_fingerprint text, p_source text DEFAULT 'admin_console'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_code_id uuid;
  v_benefit jsonb;
  v_promotion_id uuid;
  v_response jsonb;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_inserted integer;
  v_kind text;
  v_lane text;
  v_value numeric;
  v_region_code text;
BEGIN
  IF p_actor_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.admin_users au
    WHERE au.id=p_actor_id AND au.role='admin' AND COALESCE(au.is_machine_actor,true)=false
  ) THEN
    RAISE EXCEPTION 'promotion_code_human_required' USING ERRCODE='42501';
  END IF;
  IF p_idempotency_key IS NULL OR char_length(p_idempotency_key) < 8 OR p_request_fingerprint IS NULL THEN
    RAISE EXCEPTION 'promotion_code_invalid_idempotency' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys
    (scope, idempotency_key, request_fingerprint, status, expires_at)
  VALUES ('admin_promotion_code_create', p_idempotency_key, p_request_fingerprint,
          'in_progress', now() + interval '30 days')
  ON CONFLICT (scope, idempotency_key) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted = 0 THEN
    SELECT * INTO v_existing FROM public.commerce_idempotency_keys
    WHERE scope='admin_promotion_code_create' AND idempotency_key=p_idempotency_key FOR UPDATE;
    IF v_existing.request_fingerprint IS DISTINCT FROM p_request_fingerprint THEN
      RAISE EXCEPTION 'promotion_code_idempotency_conflict' USING ERRCODE='23505';
    END IF;
    IF v_existing.status='completed' AND v_existing.response_payload IS NOT NULL THEN
      RETURN v_existing.response_payload || jsonb_build_object('idempotent', true);
    END IF;
    RAISE EXCEPTION 'promotion_code_idempotency_in_progress' USING ERRCODE='55000';
  END IF;

  IF p_status NOT IN ('draft','active') OR p_code IS NULL OR p_name IS NULL
     OR char_length(upper(btrim(p_code))) NOT BETWEEN 3 AND 64
     OR upper(btrim(p_code)) !~ '^[A-Z0-9_-]+$'
     OR p_scopes IS NULL OR cardinality(p_scopes) NOT BETWEEN 1 AND 2
     OR NOT p_scopes <@ ARRAY['one_time','subscription_initial']::text[]
     OR p_valid_from IS NULL OR (p_valid_to IS NOT NULL AND p_valid_to <= p_valid_from)
     OR p_minimum_reference_minor < 0
     OR jsonb_typeof(p_benefits) <> 'array' OR jsonb_array_length(p_benefits) NOT BETWEEN 1 AND 2 THEN
    RAISE EXCEPTION 'promotion_code_invalid_definition' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.promotion_codes (
    code, name, admin_description, scopes, valid_from, valid_to,
    minimum_reference_minor, redemption_limit_global,
    redemption_limit_per_customer, status
  ) VALUES (
    upper(btrim(p_code)), btrim(p_name), nullif(btrim(p_description), ''), p_scopes,
    p_valid_from, p_valid_to, p_minimum_reference_minor,
    p_redemption_limit_global, p_redemption_limit_per_customer, p_status
  ) RETURNING id INTO v_code_id;

  -- The market this code is offered in, read immediately before the loop that writes it
  -- into region_availability. Placed after the definition validation so a malformed
  -- request still returns promotion_code_invalid_definition rather than a configuration
  -- error.
  v_region_code := public.platform_region_code();

  FOR v_benefit IN SELECT value FROM jsonb_array_elements(p_benefits) LOOP
    v_kind := v_benefit->>'kind';
    v_lane := v_benefit->>'lane';
    IF v_lane IS NULL OR v_kind IS NULL
       OR v_lane NOT IN ('product','shipping')
       OR v_kind NOT IN ('target_percentage','percentage','fixed_amount','free_shipping')
       OR (v_lane='product' AND v_kind NOT IN ('target_percentage','fixed_amount'))
       OR (v_lane='shipping' AND v_kind='target_percentage') THEN
      RAISE EXCEPTION 'promotion_code_invalid_benefit' USING ERRCODE='22023';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.promotion_code_bindings pcb
      JOIN public.promotions p ON p.id=pcb.promotion_id
      WHERE pcb.promotion_code_id=v_code_id AND p.benefit_lane=v_lane
    ) THEN
      RAISE EXCEPTION 'promotion_code_duplicate_lane' USING ERRCODE='22023';
    END IF;
    IF v_kind IN ('target_percentage','percentage') THEN
      IF jsonb_typeof(v_benefit->'valueBps') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION 'promotion_code_invalid_benefit_value' USING ERRCODE='22023';
      END IF;
      v_value := (v_benefit->>'valueBps')::numeric;
      IF v_value<>trunc(v_value) OR v_value NOT BETWEEN 1 AND 9999 THEN
        RAISE EXCEPTION 'promotion_code_invalid_benefit_value' USING ERRCODE='22023';
      END IF;
    ELSIF v_kind='fixed_amount' THEN
      IF jsonb_typeof(v_benefit->'valueMinor') IS DISTINCT FROM 'number' THEN
        RAISE EXCEPTION 'promotion_code_invalid_benefit_value' USING ERRCODE='22023';
      END IF;
      v_value := (v_benefit->>'valueMinor')::numeric;
      IF v_value<>trunc(v_value) OR v_value NOT BETWEEN 1 AND 2147483647 THEN
        RAISE EXCEPTION 'promotion_code_invalid_benefit_value' USING ERRCODE='22023';
      END IF;
    END IF;
    INSERT INTO public.promotions (
      code, name, trigger_type, discount_type, discount_value, applies_to_kind,
      stacking_rule, eligibility, valid_from, valid_to, region_availability, status,
      promotion_engine_version, benefit_lane, benefit_kind,
      benefit_value_bps, benefit_value_minor
    ) VALUES (
      'V2:'||v_code_id::text||':'||upper(v_lane), btrim(p_name), 'coupon_code',
      CASE WHEN v_kind IN ('target_percentage','percentage') THEN 'percentage'
           WHEN v_kind='fixed_amount' THEN 'fixed_amount' ELSE 'free_shipping' END,
      CASE WHEN v_kind IN ('target_percentage','percentage') THEN ((v_benefit->>'valueBps')::numeric / 100)
           WHEN v_kind='fixed_amount' THEN (v_benefit->>'valueMinor')::numeric ELSE 0 END,
      'order_total', 'exclusive',
      jsonb_build_object('minimum_reference_minor', p_minimum_reference_minor),
      -- Bind the per-lane v2 promotion to the code's own status, so a code created
      -- 'active' is not silently stranded as a 'draft' benefit with no sanctioned
      -- path to activate it. Runtime still gates on the code's status; this keeps
      -- DB truth honest and lets the staging rollout gate pass without a manual edit.
      p_valid_from, p_valid_to, ARRAY[v_region_code]::text[], p_status,
      'promotion-engine.v2', v_lane, v_kind,
      CASE WHEN v_kind IN ('target_percentage','percentage') THEN (v_benefit->>'valueBps')::numeric END,
      CASE WHEN v_kind='fixed_amount' THEN (v_benefit->>'valueMinor')::numeric END
    ) RETURNING id INTO v_promotion_id;
    INSERT INTO public.promotion_code_bindings (promotion_code_id,promotion_id,lane)
    VALUES (v_code_id,v_promotion_id,v_lane);
  END LOOP;

  v_response := jsonb_build_object('id',v_code_id,'code',upper(btrim(p_code)),
                                   'status',p_status,'revision',1,'idempotent',false);
  PERFORM public.record_admin_audit_event(
    p_actor_id, 'promotion_code_create', p_source, 'promotion_code', v_code_id::text,
    NULL, jsonb_build_object('status',p_status,'scopes',p_scopes,
      'benefit_count',jsonb_array_length(p_benefits)), 'create:'||p_idempotency_key, NULL);
  UPDATE public.commerce_idempotency_keys
    SET status='completed', response_payload=v_response
  WHERE scope='admin_promotion_code_create' AND idempotency_key=p_idempotency_key;
  RETURN v_response;
END;
$_$;


--
-- Name: admin_promotion_code_definition(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_promotion_code_definition(p_actor_id uuid, p_code_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF p_actor_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.admin_users au WHERE au.id=p_actor_id AND au.role='admin'
  ) THEN
    RAISE EXCEPTION 'actor_unknown' USING ERRCODE='42501';
  END IF;
  SELECT jsonb_build_object(
    'scopes',pc.scopes,
    'minimum_reference_minor',pc.minimum_reference_minor,
    'revision',pc.revision,
    'status',pc.status,
    'valid_from',pc.valid_from,
    'valid_to',pc.valid_to,
    'promotion_engine_version',CASE WHEN bool_or(p.promotion_engine_version='promotion-engine.v2')
      THEN 'promotion-engine.v2' ELSE 'promotion-engine.v1' END,
    'benefits',jsonb_agg(
      CASE
        WHEN p.promotion_engine_version='promotion-engine.v1'
          AND (
            (p.benefit_kind='percentage' AND p.benefit_value_bps IS NULL)
            OR (p.benefit_kind='percentage' AND (
              p.benefit_value_bps > 9007199254740991
              OR p.benefit_value_bps <> trunc(p.benefit_value_bps)
            ))
            OR (p.benefit_kind='fixed_amount' AND p.benefit_value_minor IS NULL)
            OR (p.benefit_kind='fixed_amount' AND (
              p.benefit_value_minor > 9007199254740991
              OR p.benefit_value_minor <> trunc(p.benefit_value_minor)
            ))
          )
        THEN jsonb_build_object(
          'lane',p.benefit_lane,'kind',p.benefit_kind,
          'validationState','unsupported_legacy_value'
        )
        ELSE jsonb_strip_nulls(jsonb_build_object(
          'lane',p.benefit_lane,'kind',p.benefit_kind,
          'valueBps',p.benefit_value_bps::bigint,
          'valueMinor',p.benefit_value_minor::bigint
        ))
      END ORDER BY p.benefit_lane
    )
  ) INTO v_result
  FROM public.promotion_codes pc
  JOIN public.promotion_code_bindings pcb ON pcb.promotion_code_id=pc.id
  JOIN public.promotions p ON p.id=pcb.promotion_id
  WHERE pc.id=p_code_id GROUP BY pc.id;
  IF v_result IS NULL THEN RAISE EXCEPTION 'promotion_code_not_found' USING ERRCODE='P0002'; END IF;
  RETURN v_result;
END;
$$;


--
-- Name: admin_promotion_code_update(uuid, uuid, integer, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_promotion_code_update(p_actor_id uuid, p_code_id uuid, p_expected_revision integer, p_updates jsonb, p_idempotency_key text, p_request_fingerprint text, p_source text DEFAULT 'admin_console'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_old public.promotion_codes%ROWTYPE;
  v_new public.promotion_codes%ROWTYPE;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_response jsonb;
  v_inserted integer;
  v_action text;
  v_effective_valid_from timestamptz;
  v_effective_valid_to timestamptz;
  v_expected_v1_ids uuid[];
  v_current_v1_ids uuid[];
BEGIN
  IF p_actor_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.admin_users au
    WHERE au.id=p_actor_id AND au.role='admin' AND COALESCE(au.is_machine_actor,true)=false
  ) THEN
    RAISE EXCEPTION 'promotion_code_human_required' USING ERRCODE='42501';
  END IF;
  INSERT INTO public.commerce_idempotency_keys
    (scope,idempotency_key,request_fingerprint,status,expires_at)
  VALUES ('admin_promotion_code_update',p_idempotency_key,p_request_fingerprint,
          'in_progress',now()+interval '30 days')
  ON CONFLICT (scope,idempotency_key) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;
  IF v_inserted=0 THEN
    SELECT * INTO v_existing FROM public.commerce_idempotency_keys
    WHERE scope='admin_promotion_code_update' AND idempotency_key=p_idempotency_key FOR UPDATE;
    IF v_existing.request_fingerprint IS DISTINCT FROM p_request_fingerprint THEN
      RAISE EXCEPTION 'promotion_code_idempotency_conflict' USING ERRCODE='23505';
    END IF;
    IF v_existing.status='completed' THEN
      RETURN v_existing.response_payload || jsonb_build_object('idempotent',true);
    END IF;
    RAISE EXCEPTION 'promotion_code_idempotency_in_progress' USING ERRCODE='55000';
  END IF;
  -- Legacy editor writes lock promotions first and then reach promotion_codes
  -- through its projection trigger. Use the same order here to avoid a
  -- promotion_codes <-> promotions deadlock. The optimistic-binding fence below
  -- is still scoped to v1 rows: only the live v1 evaluator row races with the
  -- legacy editor, so a v1 binding change is what must force a retry.
  SELECT COALESCE(array_agg(p.id ORDER BY p.id), ARRAY[]::uuid[])
  INTO v_expected_v1_ids
  FROM public.promotions p
  JOIN public.promotion_code_bindings pcb ON pcb.promotion_id=p.id
  WHERE pcb.promotion_code_id=p_code_id
    AND p.promotion_engine_version='promotion-engine.v1';
  PERFORM p.id
  FROM public.promotions p
  JOIN public.promotion_code_bindings pcb ON pcb.promotion_id=p.id
  WHERE pcb.promotion_code_id=p_code_id
    AND p.promotion_engine_version='promotion-engine.v1'
  ORDER BY p.id
  FOR UPDATE OF p;
  SELECT * INTO v_old FROM public.promotion_codes WHERE id=p_code_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'promotion_code_not_found' USING ERRCODE='P0002'; END IF;
  -- Re-read the binding under both locks. A concurrent binding change must
  -- retry rather than updating an unlocked live legacy row.
  SELECT COALESCE(array_agg(p.id ORDER BY p.id), ARRAY[]::uuid[])
  INTO v_current_v1_ids
  FROM public.promotions p
  JOIN public.promotion_code_bindings pcb ON pcb.promotion_id=p.id
  WHERE pcb.promotion_code_id=p_code_id
    AND p.promotion_engine_version='promotion-engine.v1';
  IF v_current_v1_ids IS DISTINCT FROM v_expected_v1_ids THEN
    RAISE EXCEPTION 'promotion_code_binding_changed_retry' USING ERRCODE='40001';
  END IF;
  IF p_expected_revision IS NULL OR p_expected_revision<>v_old.revision THEN
    RAISE EXCEPTION 'promotion_code_revision_conflict' USING ERRCODE='P0001';
  END IF;
  IF p_updates ? 'status' AND p_updates->>'status' NOT IN ('draft','active','paused','archived') THEN
    RAISE EXCEPTION 'promotion_code_invalid_status' USING ERRCODE='22023';
  END IF;
  v_effective_valid_from := CASE WHEN p_updates ? 'validFrom'
    THEN (p_updates->>'validFrom')::timestamptz ELSE v_old.valid_from END;
  v_effective_valid_to := CASE WHEN p_updates ? 'validTo'
    THEN NULLIF(p_updates->>'validTo','')::timestamptz ELSE v_old.valid_to END;
  IF v_effective_valid_to IS NOT NULL AND v_effective_valid_to<=v_effective_valid_from THEN
    RAISE EXCEPTION 'promotion_code_invalid_validity_window' USING ERRCODE='22023';
  END IF;
  UPDATE public.promotion_codes SET
    status=COALESCE(p_updates->>'status',status),
    valid_from=CASE WHEN p_updates ? 'validFrom' THEN (p_updates->>'validFrom')::timestamptz ELSE valid_from END,
    valid_to=CASE WHEN p_updates ? 'validTo' THEN NULLIF(p_updates->>'validTo','')::timestamptz ELSE valid_to END,
    redemption_limit_global=CASE WHEN p_updates ? 'redemptionLimitGlobal' THEN (p_updates->>'redemptionLimitGlobal')::integer ELSE redemption_limit_global END,
    redemption_limit_per_customer=CASE WHEN p_updates ? 'redemptionLimitPerCustomer' THEN (p_updates->>'redemptionLimitPerCustomer')::integer ELSE redemption_limit_per_customer END,
    revision=revision+1, updated_at=now()
  WHERE id=p_code_id RETURNING * INTO v_new;
  -- Keep every bound benefit's evaluator row in lockstep with the code. Both the
  -- live v1 row and the per-lane v2 rows now follow the code's status/validity/
  -- limits: without this a code activated/paused in Code Center would strand its
  -- bound v2 promotion at its create-time status with no sanctioned path to change
  -- it. v2 MIRROR rows carry no promotion_code_bindings, so this bindings-joined
  -- UPDATE can never reach them. The IS DISTINCT FROM guard keeps it a no-op when
  -- nothing changed.
  UPDATE public.promotions p SET
    status=v_new.status,
    valid_from=v_new.valid_from,
    valid_to=v_new.valid_to,
    redemption_limit_global=v_new.redemption_limit_global,
    redemption_limit_per_customer=v_new.redemption_limit_per_customer,
    updated_at=now()
  FROM public.promotion_code_bindings pcb
  WHERE pcb.promotion_code_id=v_new.id AND pcb.promotion_id=p.id
    AND (p.status,p.valid_from,p.valid_to,p.redemption_limit_global,p.redemption_limit_per_customer)
      IS DISTINCT FROM
      (v_new.status,v_new.valid_from,v_new.valid_to,v_new.redemption_limit_global,v_new.redemption_limit_per_customer);
  v_action := CASE WHEN p_updates ? 'status' THEN 'promotion_code_status_change' ELSE 'promotion_code_update' END;
  PERFORM public.record_admin_audit_event(
    p_actor_id,v_action,p_source,'promotion_code',p_code_id::text,
    jsonb_build_object('status',v_old.status,'validFrom',v_old.valid_from,'validTo',v_old.valid_to,
      'redemptionLimitGlobal',v_old.redemption_limit_global,
      'redemptionLimitPerCustomer',v_old.redemption_limit_per_customer),
    jsonb_build_object('status',v_new.status,'validFrom',v_new.valid_from,'validTo',v_new.valid_to,
      'redemptionLimitGlobal',v_new.redemption_limit_global,
      'redemptionLimitPerCustomer',v_new.redemption_limit_per_customer),
    'update:'||p_idempotency_key,NULL);
  v_response:=jsonb_build_object('id',p_code_id,'status',v_new.status,
    'revision',v_new.revision,'idempotent',false);
  UPDATE public.commerce_idempotency_keys SET status='completed',response_payload=v_response
  WHERE scope='admin_promotion_code_update' AND idempotency_key=p_idempotency_key;
  RETURN v_response;
END;
$$;


--
-- Name: admin_promotion_codes_legacy_compatibility(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_promotion_codes_legacy_compatibility(p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_unprojected_count bigint;
  v_collision_group_count bigint;
BEGIN
  IF p_actor_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.admin_users au WHERE au.id=p_actor_id AND au.role='admin'
  ) THEN
    RAISE EXCEPTION 'actor_unknown' USING ERRCODE='42501';
  END IF;

  SELECT count(*) INTO v_unprojected_count
  FROM public.promotions p
  WHERE p.trigger_type='coupon_code'
    AND p.code IS NOT NULL
    AND p.promotion_engine_version='promotion-engine.v1'
    AND NOT EXISTS (
      SELECT 1 FROM public.promotion_code_bindings pcb
      WHERE pcb.promotion_id=p.id
    );

  SELECT count(*) INTO v_collision_group_count
  FROM (
    SELECT upper(btrim(p.code))
    FROM public.promotions p
    WHERE p.trigger_type='coupon_code'
      AND p.code IS NOT NULL
      AND p.promotion_engine_version='promotion-engine.v1'
    GROUP BY upper(btrim(p.code))
    HAVING count(*)>1
  ) collisions;

  RETURN jsonb_build_object(
    'ready',v_unprojected_count=0 AND v_collision_group_count=0,
    'unprojectedCount',v_unprojected_count,
    'collisionGroupCount',v_collision_group_count
  );
END;
$$;


--
-- Name: admin_promotion_codes_list(uuid, text, text, text, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_promotion_codes_list(p_actor_id uuid, p_query text DEFAULT NULL::text, p_status text DEFAULT 'active'::text, p_scope text DEFAULT 'all'::text, p_cursor_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25) RETURNS TABLE(id uuid, code text, name text, admin_description text, benefits jsonb, scopes text[], promotion_engine_version text, status text, effective_status text, valid_from timestamp with time zone, valid_to timestamp with time zone, minimum_reference_minor integer, redemption_limit_global integer, redemption_limit_per_customer integer, redeemed_count bigint, reserved_count bigint, remaining_count bigint, created_at timestamp with time zone, revision integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_actor_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.admin_users au WHERE au.id=p_actor_id AND au.role='admin'
  ) THEN
    RAISE EXCEPTION 'actor_unknown' USING ERRCODE='42501';
  END IF;
  IF p_limit NOT BETWEEN 1 AND 101 THEN RAISE EXCEPTION 'invalid_limit' USING ERRCODE='22023'; END IF;
  RETURN QUERY
  WITH rows AS (
    SELECT pc.*,
      CASE WHEN pc.status='active' AND pc.valid_from>now() THEN 'scheduled'
           WHEN pc.status='active' AND pc.valid_to IS NOT NULL AND pc.valid_to<=now() THEN 'expired'
           ELSE pc.status END AS calculated_status,
      claim_counts.redeemed,
      claim_counts.reserved,
      benefit_data.benefit_rows
    FROM public.promotion_codes pc
    CROSS JOIN LATERAL (
      SELECT jsonb_agg(
        CASE
          WHEN p.promotion_engine_version='promotion-engine.v1'
            AND (
              (p.benefit_kind='percentage' AND p.benefit_value_bps IS NULL)
              OR (p.benefit_kind='percentage' AND (
                p.benefit_value_bps > 9007199254740991
                OR p.benefit_value_bps <> trunc(p.benefit_value_bps)
              ))
              OR (p.benefit_kind='fixed_amount' AND p.benefit_value_minor IS NULL)
              OR (p.benefit_kind='fixed_amount' AND (
                p.benefit_value_minor > 9007199254740991
                OR p.benefit_value_minor <> trunc(p.benefit_value_minor)
              ))
            )
          THEN jsonb_build_object(
            'lane',p.benefit_lane,'kind',p.benefit_kind,
            'validationState','unsupported_legacy_value'
          )
          ELSE jsonb_strip_nulls(jsonb_build_object(
            'lane',p.benefit_lane,'kind',p.benefit_kind,
            'valueBps',p.benefit_value_bps::bigint,
            'valueMinor',p.benefit_value_minor::bigint
          ))
        END ORDER BY p.benefit_lane
      ) AS benefit_rows
      FROM public.promotion_code_bindings pcb
      JOIN public.promotions p ON p.id=pcb.promotion_id
      WHERE pcb.promotion_code_id=pc.id
    ) benefit_data
    CROSS JOIN LATERAL (
      SELECT count(*) FILTER (WHERE pcc.status='redeemed') AS redeemed,
             count(*) FILTER (WHERE pcc.status='reserved') AS reserved
      FROM public.promotion_code_claims pcc WHERE pcc.promotion_code_id=pc.id
    ) claim_counts
    WHERE (p_query IS NULL OR starts_with(pc.code_normalized,upper(btrim(p_query)))
           OR starts_with(lower(pc.name),lower(btrim(p_query))))
      AND (p_cursor_created_at IS NULL OR (pc.created_at,pc.id)<(p_cursor_created_at,p_cursor_id))
      AND (p_scope='all'
        OR (p_scope='both' AND pc.scopes @> ARRAY['one_time','subscription_initial']::text[])
        OR (p_scope IN ('one_time','subscription_initial') AND pc.scopes @> ARRAY[p_scope]::text[])
        OR (p_scope='shipping' AND EXISTS (
          SELECT 1 FROM public.promotion_code_bindings pcb2
          JOIN public.promotions p2 ON p2.id=pcb2.promotion_id
          WHERE pcb2.promotion_code_id=pc.id AND p2.benefit_lane='shipping'
        )))
  )
  SELECT r.id,r.code,r.name,r.admin_description,r.benefit_rows,r.scopes,
    CASE WHEN EXISTS (
      SELECT 1 FROM public.promotion_code_bindings vb
      JOIN public.promotions vp ON vp.id=vb.promotion_id
      WHERE vb.promotion_code_id=r.id AND vp.promotion_engine_version='promotion-engine.v2'
    ) THEN 'promotion-engine.v2' ELSE 'promotion-engine.v1' END,
    r.status,
    r.calculated_status,r.valid_from,r.valid_to,r.minimum_reference_minor,
    r.redemption_limit_global,
    r.redemption_limit_per_customer,r.redeemed,r.reserved,
    CASE WHEN r.redemption_limit_global IS NULL THEN NULL
         ELSE greatest(0,r.redemption_limit_global-r.redeemed-r.reserved) END,
    r.created_at,r.revision
  FROM rows r
  WHERE p_status='all' OR r.calculated_status=p_status
    OR (p_status='expired_or_archived' AND r.calculated_status IN ('expired','archived'))
  ORDER BY r.created_at DESC,r.id DESC LIMIT p_limit;
END;
$$;


--
-- Name: admin_restore_bundle(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_restore_bundle(p_actor_id uuid, p_code text, p_mode text DEFAULT 'commit'::text, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_source text DEFAULT 'agent_bundle'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_is_machine boolean;
  v_status text;
BEGIN
  IF p_actor_id IS NULL THEN RAISE EXCEPTION 'actor_required' USING ERRCODE='42501'; END IF;
  SELECT is_machine_actor INTO v_is_machine FROM public.admin_users WHERE id = p_actor_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'actor_unknown' USING ERRCODE='42501'; END IF;

  IF p_idempotency_key IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.admin_audit_events
    WHERE entity_type='catalog_bundle' AND idempotency_key=p_idempotency_key
  ) THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', true, 'dryRun', false);
  END IF;

  SELECT status INTO v_status FROM public.catalog_bundles WHERE code = p_code;
  IF NOT FOUND THEN RAISE EXCEPTION 'bundle_not_found' USING ERRCODE='P0002'; END IF;
  -- Restore is the exact inverse of archive and nothing else; restoring a live or
  -- draft bundle would be a status change nobody asked for.
  IF v_status <> 'archived' THEN
    RAISE EXCEPTION 'restore_requires_archived' USING ERRCODE='P0001';
  END IF;

  IF p_mode = 'dry_run' THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', true);
  END IF;

  -- The target is draft, never active: a restore makes nothing sellable, which is
  -- why a machine actor is allowed to perform one.
  UPDATE public.catalog_bundles SET status='draft', updated_at=now() WHERE code = p_code;

  PERFORM public.record_admin_audit_event(
    p_actor_id, 'bundle_restore', p_source, 'catalog_bundle', p_code,
    jsonb_build_object('status', v_status), jsonb_build_object('status', 'draft'),
    p_idempotency_key, p_request_id);

  RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', false);
END;
$$;


--
-- Name: admin_restore_catalog_product(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_restore_catalog_product(p_actor_id uuid, p_slug text, p_mode text DEFAULT 'commit'::text, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_source text DEFAULT 'agent_catalog'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  RAISE EXCEPTION 'legacy_catalog_mutation_fenced' USING ERRCODE = '42501';
END;
$$;


--
-- Name: admin_users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.admin_users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    role text DEFAULT 'admin'::text,
    is_machine_actor boolean DEFAULT false NOT NULL,
    membership_state text DEFAULT 'active'::text NOT NULL,
    membership_provenance text DEFAULT 'legacy'::text NOT NULL,
    membership_accepted_at timestamp with time zone DEFAULT now() NOT NULL,
    membership_revoked_at timestamp with time zone,
    membership_revoked_by uuid,
    membership_revocation_reason text,
    CONSTRAINT admin_users_membership_state_check CHECK (((membership_state IS NOT NULL) AND (membership_provenance IS NOT NULL) AND (membership_accepted_at IS NOT NULL) AND (membership_state = ANY (ARRAY['active'::text, 'revoked'::text])) AND (membership_provenance = ANY (ARRAY['legacy'::text, 'invitation'::text])) AND (((membership_state = 'active'::text) AND (membership_revoked_at IS NULL) AND (membership_revoked_by IS NULL) AND (membership_revocation_reason IS NULL)) OR ((membership_state = 'revoked'::text) AND (membership_revoked_at IS NOT NULL) AND (membership_revoked_by IS NOT NULL))) AND ((membership_revoked_by IS NULL) OR (membership_revoked_by <> id)) AND ((membership_revocation_reason IS NULL) OR (char_length(membership_revocation_reason) <= 1000)))),
    CONSTRAINT admin_users_role_check CHECK ((role = ANY (ARRAY['admin'::text, 'distributor'::text])))
);


--
-- Name: COLUMN admin_users.is_machine_actor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.admin_users.is_machine_actor IS 'True for non-human service identities (e.g. the agent operator). The publish/activate gate re-derives this from the row and denies machine actors; flipping it to false (or disabling the row) is the kill-switch for an agent identity.';


--
-- Name: COLUMN admin_users.membership_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.admin_users.membership_state IS 'Current-panel membership state. Only active membership may authorize; revoked rows are retained for history.';


--
-- Name: COLUMN admin_users.membership_provenance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.admin_users.membership_provenance IS 'How this accepted membership entered the current panel. Existing rows are deterministically legacy.';


--
-- Name: COLUMN admin_users.membership_accepted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.admin_users.membership_accepted_at IS 'When the current-panel membership became accepted. Legacy rows preserve created_at when available.';


--
-- Name: COLUMN admin_users.membership_revoked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.admin_users.membership_revoked_at IS 'When current-panel access was withdrawn. NULL while membership remains active.';


--
-- Name: COLUMN admin_users.membership_revoked_by; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.admin_users.membership_revoked_by IS 'Retained actor reference for the administrator who withdrew access.';


--
-- Name: COLUMN admin_users.membership_revocation_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.admin_users.membership_revocation_reason IS 'Optional bounded operator reason retained with the revoked membership.';


--
-- Name: admin_revoke_admin_user(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_revoke_admin_user(p_target uuid, p_reason text DEFAULT NULL::text) RETURNS public.admin_users
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_target public.admin_users;
  v_reason text := NULLIF(btrim(p_reason), '');
  v_revoked_at timestamptz := clock_timestamp();
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_target IS NULL THEN
    RAISE EXCEPTION 'target_required' USING ERRCODE = '22023';
  END IF;

  IF p_target = v_actor THEN
    RAISE EXCEPTION 'self_revoke_forbidden' USING ERRCODE = 'P0001';
  END IF;

  IF v_reason IS NOT NULL AND char_length(v_reason) > 1000 THEN
    RAISE EXCEPTION 'revocation_reason_too_long' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_target
  FROM public.admin_users
  WHERE id = p_target
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_target.is_machine_actor IS TRUE THEN
    RAISE EXCEPTION 'machine_actor_revoke_forbidden' USING ERRCODE = 'P0001';
  END IF;

  -- Row locking plus state is the idempotency key: concurrent/replayed revoke
  -- calls return the retained row and cannot append a second audit event.
  IF v_target.membership_state = 'revoked' THEN
    RETURN v_target;
  END IF;

  PERFORM set_config('app.admin_membership_revoke', 'true', true);

  UPDATE public.admin_users
  SET membership_state = 'revoked',
      membership_revoked_at = v_revoked_at,
      membership_revoked_by = v_actor,
      membership_revocation_reason = v_reason
  WHERE id = p_target
  RETURNING * INTO v_target;

  PERFORM public.record_admin_audit_event(
    v_actor,
    'revoke',
    'admin_ui',
    'admin_user_membership',
    p_target::text,
    jsonb_build_object(
      'membershipState', 'active',
      'role', COALESCE(v_target.role, 'admin')
    ),
    jsonb_build_object(
      'membershipState', 'revoked',
      'revokedAt', v_revoked_at,
      'revokedBy', v_actor,
      'revocationReason', v_reason
    ),
    NULL,
    NULL,
    p_target,
    v_target.email
  );

  RETURN v_target;
END;
$$;


--
-- Name: FUNCTION admin_revoke_admin_user(p_target uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_revoke_admin_user(p_target uuid, p_reason text) IS 'Authenticated current-panel revoke command. Derives actor from auth.uid(), retains target membership and identity, refuses self and machine targets, preserves the last human administrator, and appends exactly one atomic revoke audit event.';


--
-- Name: admin_set_bundle_composition(uuid, text, jsonb, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_bundle_composition(p_actor_id uuid, p_code text, p_components jsonb, p_mode text DEFAULT 'commit'::text, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_source text DEFAULT 'agent_bundle'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_is_machine boolean;
  v_bundle_id uuid;
  v_count integer;
  v_distinct integer;
  v_core integer;
  v_resolved integer;
  v_unsellable integer;
  v_currency text;
  v_mismatched integer;
BEGIN
  IF p_actor_id IS NULL THEN RAISE EXCEPTION 'actor_required' USING ERRCODE='42501'; END IF;
  SELECT is_machine_actor INTO v_is_machine FROM public.admin_users WHERE id = p_actor_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'actor_unknown' USING ERRCODE='42501'; END IF;

  IF p_idempotency_key IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.admin_audit_events
    WHERE entity_type='catalog_bundle' AND idempotency_key=p_idempotency_key
  ) THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', true, 'dryRun', false);
  END IF;

  SELECT id INTO v_bundle_id FROM public.catalog_bundles WHERE code = p_code;
  IF NOT FOUND THEN RAISE EXCEPTION 'bundle_not_found' USING ERRCODE='P0002'; END IF;

  -- The supplied set is read straight out of the argument every time it is needed.
  -- A temp table would be the obvious shortcut and is the wrong one: ON COMMIT DROP
  -- survives until the transaction ends, so a second composition write in the same
  -- transaction, or a retry after a caught exception, would collide with the table
  -- the first call left behind. An inline recordset has no such lifetime.
  SELECT count(*),
         count(DISTINCT entry.sku),
         count(*) FILTER (WHERE NOT COALESCE(entry.is_addon, false)),
         count(unit.id),
         count(*) FILTER (
           WHERE unit.id IS NOT NULL
             AND (unit.status <> 'active' OR unit.sellable_standalone IS NOT TRUE))
    INTO v_count, v_distinct, v_core, v_resolved, v_unsellable
  FROM jsonb_to_recordset(COALESCE(p_components, '[]'::jsonb))
       AS entry(sku text, quantity integer, is_addon boolean, sort_order integer)
  LEFT JOIN public.catalog_skus AS unit ON unit.sku = entry.sku;

  IF v_count = 0 THEN RAISE EXCEPTION 'min_components' USING ERRCODE='P0001'; END IF;
  IF v_distinct <> v_count THEN RAISE EXCEPTION 'duplicate_component' USING ERRCODE='P0001'; END IF;
  IF v_core = 0 THEN RAISE EXCEPTION 'addon_only_composition' USING ERRCODE='P0001'; END IF;
  IF v_resolved <> v_count THEN
    RAISE EXCEPTION 'component_not_found' USING ERRCODE='P0002';
  END IF;
  -- A bundle must not become the only way an unsellable unit reaches a customer.
  IF v_unsellable > 0 THEN
    RAISE EXCEPTION 'component_not_sellable' USING ERRCODE='P0001';
  END IF;

  -- When the bundle already carries a price, every component must be priced in that
  -- same currency: a mixed-currency bill of materials has no single reference total
  -- for the target price to be weighed against.
  SELECT list.currency INTO v_currency
  FROM public.catalog_bundle_prices AS price
  JOIN public.price_lists AS list ON list.id = price.price_list_id
  WHERE price.bundle_id = v_bundle_id AND price.active
  ORDER BY price.valid_from DESC
  LIMIT 1;

  IF v_currency IS NOT NULL THEN
    SELECT count(*) INTO v_mismatched
    FROM jsonb_to_recordset(COALESCE(p_components, '[]'::jsonb))
         AS entry(sku text, quantity integer, is_addon boolean, sort_order integer)
    JOIN public.catalog_skus AS unit ON unit.sku = entry.sku
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.price_entries AS unit_price
      JOIN public.price_lists AS unit_list ON unit_list.id = unit_price.price_list_id
      WHERE unit_price.variant_id = unit.id
        AND unit_price.active
        AND unit_list.currency = v_currency);
    IF v_mismatched > 0 THEN
      RAISE EXCEPTION 'component_currency_mismatch' USING ERRCODE='P0001';
    END IF;
  END IF;

  IF p_mode = 'dry_run' THEN
    RETURN jsonb_build_object('code', p_code, 'componentCount', v_count,
                              'idempotent', false, 'dryRun', true);
  END IF;

  -- Atomic whole-set replace, inside this routine's single transaction.
  DELETE FROM public.catalog_bundle_components WHERE bundle_id = v_bundle_id;
  INSERT INTO public.catalog_bundle_components
    (bundle_id, catalog_sku_id, quantity, is_addon, sort_order)
  SELECT v_bundle_id, unit.id, entry.quantity,
         COALESCE(entry.is_addon, false), COALESCE(entry.sort_order, 0)
  FROM jsonb_to_recordset(COALESCE(p_components, '[]'::jsonb))
       AS entry(sku text, quantity integer, is_addon boolean, sort_order integer)
  JOIN public.catalog_skus AS unit ON unit.sku = entry.sku;

  UPDATE public.catalog_bundles SET updated_at = now() WHERE id = v_bundle_id;

  PERFORM public.record_admin_audit_event(
    p_actor_id, 'bundle_composition_set', p_source, 'catalog_bundle', p_code,
    NULL, jsonb_build_object('componentCount', v_count),
    p_idempotency_key, p_request_id);

  RETURN jsonb_build_object('code', p_code, 'componentCount', v_count,
                            'idempotent', false, 'dryRun', false);
END;
$$;


--
-- Name: FUNCTION admin_set_bundle_composition(p_actor_id uuid, p_code text, p_components jsonb, p_mode text, p_idempotency_key text, p_request_id text, p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_set_bundle_composition(p_actor_id uuid, p_code text, p_components jsonb, p_mode text, p_idempotency_key text, p_request_id text, p_source text) IS 'Replace a bundle bill of materials as a whole set. Refuses an empty set, a duplicated unit, an add-on-only set, an unknown or unsellable unit, and a unit priced outside the bundle currency.';


--
-- Name: admin_set_bundle_target_price(uuid, text, text, integer, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_bundle_target_price(p_actor_id uuid, p_code text, p_price_mode text, p_target_price_minor integer, p_currency text, p_amount_kind text DEFAULT 'gross'::text, p_mode text DEFAULT 'commit'::text, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_source text DEFAULT 'agent_bundle'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_is_machine boolean;
  v_bundle_id uuid;
  v_list_id uuid;
  v_reference_total bigint;
  v_unit_total bigint;
  v_now timestamptz := clock_timestamp();
BEGIN
  IF p_actor_id IS NULL THEN RAISE EXCEPTION 'actor_required' USING ERRCODE='42501'; END IF;
  SELECT is_machine_actor INTO v_is_machine FROM public.admin_users WHERE id = p_actor_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'actor_unknown' USING ERRCODE='42501'; END IF;

  IF p_idempotency_key IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.admin_audit_events
    WHERE entity_type='catalog_bundle' AND idempotency_key=p_idempotency_key
  ) THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', true, 'dryRun', false);
  END IF;

  SELECT id INTO v_bundle_id FROM public.catalog_bundles WHERE code = p_code;
  IF NOT FOUND THEN RAISE EXCEPTION 'bundle_not_found' USING ERRCODE='P0002'; END IF;

  -- The price list is the only statement of currency; it is selected by currency
  -- alone, so no region vocabulary enters this boundary.
  SELECT id INTO v_list_id FROM public.price_lists
  WHERE currency = p_currency AND status = 'active'
  ORDER BY created_at DESC LIMIT 1;
  IF v_list_id IS NULL THEN RAISE EXCEPTION 'no_active_price_list' USING ERRCODE='P0002'; END IF;

  SELECT COALESCE(sum(component.quantity::bigint * unit_price.unit_price_minor), 0),
         COALESCE(sum(component.quantity::bigint), 0)
    INTO v_reference_total, v_unit_total
  FROM public.catalog_bundle_components AS component
  JOIN public.price_entries AS unit_price
    ON unit_price.variant_id = component.catalog_sku_id
   AND unit_price.price_list_id = v_list_id
   AND unit_price.active
  WHERE component.bundle_id = v_bundle_id;

  IF v_reference_total = 0 THEN
    RAISE EXCEPTION 'min_components' USING ERRCODE='P0001';
  END IF;
  -- The same two refusals the pricing kernel's allocator returns, in the same
  -- order: a bundle is never priced above its parts, and the target must be able
  -- to cover the minimum payable amount of every unit it contains.
  IF p_target_price_minor > v_reference_total THEN
    RAISE EXCEPTION 'target_above_component_sum' USING ERRCODE='P0001';
  END IF;
  IF p_target_price_minor < v_unit_total THEN
    RAISE EXCEPTION 'target_below_floor' USING ERRCODE='P0001';
  END IF;

  IF p_mode = 'dry_run' THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', true);
  END IF;

  -- APPEND-ONLY: close the current active row for this (bundle, list, mode) and
  -- insert a fresh one. No stored amount is ever rewritten in place.
  UPDATE public.catalog_bundle_prices
    SET active = false, valid_to = v_now
  WHERE bundle_id = v_bundle_id AND price_list_id = v_list_id AND mode = p_price_mode
    AND active AND valid_from < v_now;

  INSERT INTO public.catalog_bundle_prices
    (bundle_id, price_list_id, mode, target_price_minor, amount_kind, active, valid_from)
  VALUES (v_bundle_id, v_list_id, p_price_mode, p_target_price_minor,
          COALESCE(p_amount_kind, 'gross'), true, v_now);

  PERFORM public.record_admin_audit_event(
    p_actor_id, 'bundle_target_price_set', p_source, 'catalog_bundle', p_code,
    NULL,
    jsonb_build_object('mode', p_price_mode, 'targetPriceMinor', p_target_price_minor,
                       'currency', p_currency, 'referenceTotalMinor', v_reference_total),
    p_idempotency_key, p_request_id);

  RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', false);
END;
$$;


--
-- Name: FUNCTION admin_set_bundle_target_price(p_actor_id uuid, p_code text, p_price_mode text, p_target_price_minor integer, p_currency text, p_amount_kind text, p_mode text, p_idempotency_key text, p_request_id text, p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_set_bundle_target_price(p_actor_id uuid, p_code text, p_price_mode text, p_target_price_minor integer, p_currency text, p_amount_kind text, p_mode text, p_idempotency_key text, p_request_id text, p_source text) IS 'Append an active target price and close the previous one. Refuses a target above the component sum or below the per-unit floor, the same two refusals the pricing kernel allocator returns.';


