--
-- Name: admin_update_admin_user_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_admin_user_role(p_target uuid, p_role text) RETURNS public.admin_users
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_email text;
  v_old_role text;
  v_target_email text;
  v_target_state text;
  v_result public.admin_users;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_role NOT IN ('admin', 'distributor') THEN
    RAISE EXCEPTION 'invalid_role' USING ERRCODE = '22023';
  END IF;

  IF p_target = v_actor THEN
    RAISE EXCEPTION 'self_role_change_forbidden' USING ERRCODE = 'P0001';
  END IF;

  SELECT email INTO v_actor_email
  FROM public.admin_users
  WHERE id = v_actor AND membership_state = 'active';

  SELECT role, email, membership_state
    INTO v_old_role, v_target_email, v_target_state
  FROM public.admin_users
  WHERE id = p_target
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_target_state <> 'active' THEN
    RAISE EXCEPTION 'target_membership_inactive' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.admin_users
  SET role = p_role
  WHERE id = p_target
  RETURNING * INTO v_result;

  INSERT INTO public.admin_audit_events
    (actor_admin_id, actor_email, action, target_admin_id, target_email, old_value, new_value)
  VALUES
    (v_actor, v_actor_email, 'role_change', p_target, v_target_email,
     jsonb_build_object('role', v_old_role),
     jsonb_build_object('role', p_role));

  RETURN v_result;
END;
$$;


--
-- Name: admin_upsert_bundle_draft(uuid, text, text, text, jsonb, jsonb, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_upsert_bundle_draft(p_actor_id uuid, p_code text, p_title text DEFAULT NULL::text, p_fulfillment_mode text DEFAULT NULL::text, p_composition_constraint jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT NULL::jsonb, p_clone_from_code text DEFAULT NULL::text, p_mode text DEFAULT 'commit'::text, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_source text DEFAULT 'agent_bundle'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_is_machine boolean;
  v_bundle_id uuid;
  v_source public.catalog_bundles%ROWTYPE;
BEGIN
  IF p_actor_id IS NULL THEN RAISE EXCEPTION 'actor_required' USING ERRCODE='42501'; END IF;
  SELECT is_machine_actor INTO v_is_machine FROM public.admin_users WHERE id = p_actor_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'actor_unknown' USING ERRCODE='42501'; END IF;

  IF p_idempotency_key IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.admin_audit_events
    WHERE entity_type='catalog_bundle' AND idempotency_key=p_idempotency_key
  ) THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', true, 'dryRun', false);
  END IF;

  SELECT id INTO v_bundle_id FROM public.catalog_bundles WHERE code = p_code;

  IF p_clone_from_code IS NOT NULL THEN
    -- A clone must create a NEW bundle. Writing onto an existing code would edit
    -- it instead of cloning, silently, so the collision is refused loudly.
    IF v_bundle_id IS NOT NULL THEN
      RAISE EXCEPTION 'code_taken' USING ERRCODE='P0001';
    END IF;
    SELECT * INTO v_source FROM public.catalog_bundles WHERE code = p_clone_from_code;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'clone_source_not_found' USING ERRCODE='P0002';
    END IF;
  ELSIF v_bundle_id IS NULL AND (p_title IS NULL OR btrim(p_title) = '') THEN
    -- A create with nothing to name is not an edit of anything.
    RAISE EXCEPTION 'bundle_title_required' USING ERRCODE='P0001';
  END IF;

  IF p_mode = 'dry_run' THEN
    RETURN jsonb_build_object('code', p_code, 'idempotent', false, 'dryRun', true);
  END IF;

  IF p_clone_from_code IS NOT NULL THEN
    INSERT INTO public.catalog_bundles
      (code, title, status, fulfillment_mode, composition_constraint, metadata)
    VALUES (
      p_code,
      COALESCE(p_title, v_source.title),
      'draft',
      v_source.fulfillment_mode,
      v_source.composition_constraint,
      v_source.metadata)
    RETURNING id INTO v_bundle_id;

    -- The bill of materials is the substance of a bundle; a clone without it would
    -- be an empty shell that cannot be activated.
    INSERT INTO public.catalog_bundle_components
      (bundle_id, catalog_sku_id, quantity, is_addon, sort_order)
    SELECT v_bundle_id, component.catalog_sku_id, component.quantity,
           component.is_addon, component.sort_order
    FROM public.catalog_bundle_components AS component
    WHERE component.bundle_id = v_source.id;
  ELSE
    INSERT INTO public.catalog_bundles
      (code, title, status, fulfillment_mode, composition_constraint, metadata)
    VALUES (
      p_code,
      COALESCE(p_title, p_code),
      'draft',
      COALESCE(p_fulfillment_mode, 'virtual'),
      COALESCE(p_composition_constraint, '{}'::jsonb),
      COALESCE(p_metadata, '{}'::jsonb))
    ON CONFLICT (code) DO UPDATE
      SET title = COALESCE(p_title, public.catalog_bundles.title),
          fulfillment_mode = COALESCE(p_fulfillment_mode, public.catalog_bundles.fulfillment_mode),
          composition_constraint =
            COALESCE(p_composition_constraint, public.catalog_bundles.composition_constraint),
          metadata = COALESCE(p_metadata, public.catalog_bundles.metadata),
          updated_at = now()
    RETURNING id INTO v_bundle_id;
  END IF;

  PERFORM public.record_admin_audit_event(
    p_actor_id, 'bundle_draft_upsert', p_source, 'catalog_bundle', p_code,
    NULL,
    jsonb_build_object('title', p_title, 'clonedFrom', p_clone_from_code),
    p_idempotency_key, p_request_id);

  RETURN jsonb_build_object('code', p_code, 'bundleId', v_bundle_id::text,
                            'idempotent', false, 'dryRun', false);
END;
$$;


--
-- Name: FUNCTION admin_upsert_bundle_draft(p_actor_id uuid, p_code text, p_title text, p_fulfillment_mode text, p_composition_constraint jsonb, p_metadata jsonb, p_clone_from_code text, p_mode text, p_idempotency_key text, p_request_id text, p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.admin_upsert_bundle_draft(p_actor_id uuid, p_code text, p_title text, p_fulfillment_mode text, p_composition_constraint jsonb, p_metadata jsonb, p_clone_from_code text, p_mode text, p_idempotency_key text, p_request_id text, p_source text) IS 'Create, edit or clone a DRAFT bundle. Naming a clone source copies the source structural fields and its whole bill of materials into a new code in one transaction, recording the same draft-upsert audit action.';


