--
-- Name: catalog_publication_require_human_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_publication_require_human_admin() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
  v_actor uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'authenticated' OR auth.uid() IS NULL THEN
    RAISE EXCEPTION 'catalog_publication_human_admin_required' USING ERRCODE = '42501';
  END IF;
  SELECT id INTO v_actor FROM public.admin_users
   WHERE id = auth.uid() AND role = 'admin' AND COALESCE(is_machine_actor, true) = false
     AND membership_state = 'active';
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'catalog_publication_human_admin_required' USING ERRCODE = '42501';
  END IF;
  RETURN v_actor;
END;
$$;


--
-- Name: catalog_sku_eans_upsert_pack(text, text, text, text, integer, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.catalog_sku_eans_upsert_pack(p_sku text, p_ean text, p_kind text DEFAULT 'unit'::text, p_label_variant text DEFAULT NULL::text, p_quantity integer DEFAULT 1, p_is_primary boolean DEFAULT false, p_source text DEFAULT 'local'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_catalog_sku_id uuid;
  v_resolved_sku text;
  v_row public.catalog_sku_eans%ROWTYPE;
  v_existing public.catalog_sku_eans%ROWTYPE;
  v_ean text := btrim(coalesce(p_ean, ''));
  v_conflict text := 'none';
  v_replayed boolean := false;
BEGIN
  IF p_sku IS NULL OR btrim(p_sku) = ''
    OR v_ean = ''
    OR p_kind NOT IN ('unit', 'collective')
    OR (p_label_variant IS NOT NULL AND p_label_variant NOT IN ('pl', 'eng'))
    OR p_quantity IS NULL OR p_quantity <= 0
    OR (p_kind = 'collective') <> (p_quantity > 1)
    OR p_source NOT IN ('local', 'omnipack')
  THEN
    RAISE EXCEPTION 'catalog_sku_eans_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- Never auto-create a catalog SKU; the caller must resolve a real catalog SKU first.
  SELECT id, sku INTO v_catalog_sku_id, v_resolved_sku
    FROM public.catalog_skus
   WHERE sku = btrim(p_sku)
   LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_sku_eans_sku_not_found' USING ERRCODE = '22023';
  END IF;

  -- The EAN is already bound to a DIFFERENT SKU — a real catalog conflict; do not steal it.
  IF EXISTS (
    SELECT 1 FROM public.catalog_sku_eans
     WHERE ean = v_ean AND catalog_sku_id <> v_catalog_sku_id
  ) THEN
    RETURN jsonb_build_object(
      'contractVersion', 'catalog.sku_eans.v0',
      'sku', v_resolved_sku,
      'ean', v_ean,
      'source', p_source,
      'conflict', 'ean_owned_by_other_sku',
      'replayed', false
    );
  END IF;

  SELECT * INTO v_existing
    FROM public.catalog_sku_eans
   WHERE catalog_sku_id = v_catalog_sku_id AND ean = v_ean;

  -- Pull must not overwrite a local-owned row: only touch the seen marker + report drift.
  IF FOUND AND v_existing.source = 'local' AND p_source = 'omnipack' THEN
    UPDATE public.catalog_sku_eans
       SET omnipack_seen_at = now(), updated_at = now()
     WHERE id = v_existing.id
     RETURNING * INTO v_row;
    IF v_existing.kind <> p_kind OR v_existing.quantity <> p_quantity THEN
      v_conflict := 'local_locked_mismatch';
    END IF;
    RETURN jsonb_build_object(
      'contractVersion', 'catalog.sku_eans.v0',
      'packId', v_row.id,
      'catalogSkuId', v_row.catalog_sku_id,
      'sku', v_row.sku,
      'ean', v_row.ean,
      'source', v_row.source,
      'conflict', v_conflict,
      'replayed', true
    );
  END IF;

  -- Demote any other primary before (re)asserting this one (partial-unique safety).
  IF p_is_primary THEN
    UPDATE public.catalog_sku_eans
       SET is_primary = false, updated_at = now()
     WHERE catalog_sku_id = v_catalog_sku_id AND is_primary AND ean <> v_ean;
  END IF;

  INSERT INTO public.catalog_sku_eans (
    catalog_sku_id, sku, ean, kind, label_variant, quantity, is_primary, source,
    omnipack_synced_at, omnipack_seen_at
  )
  VALUES (
    v_catalog_sku_id, v_resolved_sku, v_ean, p_kind, p_label_variant, p_quantity, p_is_primary, p_source,
    CASE WHEN p_source = 'local' THEN now() ELSE NULL END,
    CASE WHEN p_source = 'omnipack' THEN now() ELSE NULL END
  )
  ON CONFLICT (catalog_sku_id, ean) DO UPDATE
  SET kind = EXCLUDED.kind,
      label_variant = EXCLUDED.label_variant,
      quantity = EXCLUDED.quantity,
      is_primary = EXCLUDED.is_primary,
      -- A local re-push reclaims ownership; an omnipack upsert of an omnipack row stays omnipack.
      source = CASE WHEN EXCLUDED.source = 'local' THEN 'local' ELSE public.catalog_sku_eans.source END,
      omnipack_synced_at = CASE WHEN EXCLUDED.source = 'local' THEN now() ELSE public.catalog_sku_eans.omnipack_synced_at END,
      omnipack_seen_at = CASE WHEN EXCLUDED.source = 'omnipack' THEN now() ELSE public.catalog_sku_eans.omnipack_seen_at END,
      updated_at = now()
  RETURNING * INTO v_row;

  v_replayed := FOUND AND v_existing.id IS NOT NULL;

  RETURN jsonb_build_object(
    'contractVersion', 'catalog.sku_eans.v0',
    'packId', v_row.id,
    'catalogSkuId', v_row.catalog_sku_id,
    'sku', v_row.sku,
    'ean', v_row.ean,
    'kind', v_row.kind,
    'source', v_row.source,
    'conflict', v_conflict,
    'replayed', v_replayed
  );
END;
$$;


--
-- Name: channel_ingest_advance(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.channel_ingest_advance(p_ledger_id uuid, p_to_status text, p_payment_intent_id uuid DEFAULT NULL::uuid, p_last_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_ledger public.channel_order_ingests%ROWTYPE;
  v_ranks constant text[] := ARRAY[
    'received', 'buyer_ready', 'order_created', 'reserved', 'settled', 'done'
  ];
  v_from_rank integer;
  v_to_rank integer;
BEGIN
  IF p_ledger_id IS NULL OR p_to_status IS NULL THEN
    RAISE EXCEPTION 'channel_ingest_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ledger FROM public.channel_order_ingests WHERE id = p_ledger_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'channel_ingest_ledger_not_found' USING ERRCODE = '22023';
  END IF;

  -- COALESCE(..., 0) is what makes the three off-ramps unranked: entering one is always legal, and
  -- leaving one back into the ordered lane is always forward. That is deliberate. The guard exists
  -- to stop a late REDELIVERY from walking a settled order back to 'received'; it is not what makes
  -- a resume correct. Every step is independently replayable to the same ids, and that -- not this
  -- comparison -- is the resume argument.
  v_from_rank := COALESCE(array_position(v_ranks, v_ledger.status), 0);
  v_to_rank := COALESCE(array_position(v_ranks, p_to_status), 0);

  IF v_to_rank > 0 AND v_to_rank < v_from_rank THEN
    RAISE EXCEPTION 'channel_ingest_status_regression' USING ERRCODE = '22023';
  END IF;

  UPDATE public.channel_order_ingests
     SET status = p_to_status,
         payment_intent_id = COALESCE(p_payment_intent_id, payment_intent_id),
         last_error = CASE WHEN v_to_rank > 0 THEN NULL ELSE left(p_last_error, 2000) END,
         updated_at = now()
   WHERE id = v_ledger.id
   RETURNING * INTO v_ledger;

  RETURN jsonb_build_object(
    'contractVersion', 'channels.ingest.v0',
    'ingest', jsonb_build_object(
      'id', v_ledger.id, 'status', v_ledger.status, 'orderId', v_ledger.order_id,
      'clientId', v_ledger.client_id, 'shippingAddressId', v_ledger.shipping_address_id,
      'paymentIntentId', v_ledger.payment_intent_id,
      'externalOrderRevision', v_ledger.external_order_revision,
      'conflict', NULL, 'eventReplayed', false, 'replayed', false
    )
  );
END;
$$;


--
-- Name: channel_ingest_quarantine(uuid, uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.channel_ingest_quarantine(p_channel_id uuid, p_connection_id uuid, p_provider_event_id text, p_external_order_ref text, p_vocabulary text, p_reason text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_row public.sales_channel_quarantine%ROWTYPE;
BEGIN
  IF p_provider_event_id IS NULL OR btrim(p_provider_event_id) = ''
    OR p_vocabulary IS NULL OR btrim(p_vocabulary) = ''
    OR p_reason IS NULL
  THEN
    RAISE EXCEPTION 'channel_ingest_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- A redelivery of the same broken payload must not stack a second row under the one an operator
  -- is already reading, and must not silently re-open one they have already closed. So the payload
  -- and reason are refreshed, and `status` is left exactly where the operator put it.
  INSERT INTO public.sales_channel_quarantine (
    channel_id, connection_id, provider_event_id, external_order_ref,
    vocabulary, reason, payload
  )
  VALUES (
    p_channel_id, p_connection_id, p_provider_event_id,
    NULLIF(btrim(COALESCE(p_external_order_ref, '')), ''),
    p_vocabulary, p_reason, COALESCE(p_payload, '{}'::jsonb)
  )
  ON CONFLICT ON CONSTRAINT sales_channel_quarantine_event_vocabulary_key DO UPDATE
    SET reason = EXCLUDED.reason,
        payload = EXCLUDED.payload,
        channel_id = COALESCE(EXCLUDED.channel_id, public.sales_channel_quarantine.channel_id),
        updated_at = now()
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'contractVersion', 'channels.ingest.v0',
    'quarantine', jsonb_build_object(
      'id', v_row.id, 'reason', v_row.reason, 'status', v_row.status,
      'vocabulary', v_row.vocabulary
    )
  );
END;
$$;


--
-- Name: channel_ingest_record_inbound_event(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.channel_ingest_record_inbound_event(p_channel_id uuid, p_external_order_ref text, p_external_order_revision text, p_provider_event_id text, p_normalized jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_channel public.sales_channels%ROWTYPE;
  v_provider text;
  v_ledger public.channel_order_ingests%ROWTYPE;
  v_event_replayed boolean := true;
BEGIN
  IF p_channel_id IS NULL
    OR p_external_order_ref IS NULL OR btrim(p_external_order_ref) = ''
    OR p_provider_event_id IS NULL OR btrim(p_provider_event_id) = ''
  THEN
    RAISE EXCEPTION 'channel_ingest_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_channel FROM public.sales_channels WHERE id = p_channel_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'channel_ingest_channel_not_found' USING ERRCODE = '22023';
  END IF;

  -- The inbound event log is shared with every other external adapter, so the provider namespace
  -- has to say which kind of far side this came from. `channel:<slug>` cannot collide with a
  -- payment provider kind, and it stays readable in the log.
  v_provider := 'channel:' || v_channel.slug;

  -- The one line that makes a redelivery free. UNIQUE (provider, provider_event_id) is the shop's
  -- canonical cross-adapter dedupe key; DO NOTHING means the second delivery of the same webhook
  -- writes nothing and reports itself as a replay.
  INSERT INTO public.inbound_provider_events (
    provider, provider_event_id, event_type, processing_status, payload, signature_verified, received_via
  )
  VALUES (
    v_provider, p_provider_event_id, 'channel.order.received', 'received',
    COALESCE(p_normalized, '{}'::jsonb), true, 'channels.ingest.v0'
  )
  ON CONFLICT (provider, provider_event_id) DO NOTHING;
  IF FOUND THEN
    v_event_replayed := false;
  END IF;

  SELECT * INTO v_ledger
    FROM public.channel_order_ingests
   WHERE channel_id = p_channel_id
     AND external_order_ref = p_external_order_ref
   FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.channel_order_ingests (
      channel_id, external_order_ref, external_order_revision, provider_event_id,
      status, attempt_count, normalized
    )
    VALUES (
      p_channel_id, p_external_order_ref, p_external_order_revision, p_provider_event_id,
      'received', 1, COALESCE(p_normalized, '{}'::jsonb)
    )
    RETURNING * INTO v_ledger;

    RETURN jsonb_build_object(
      'contractVersion', 'channels.ingest.v0',
      'ingest', jsonb_build_object(
        'id', v_ledger.id, 'status', v_ledger.status, 'orderId', NULL,
        'clientId', NULL, 'shippingAddressId', NULL, 'paymentIntentId', NULL,
        'externalOrderRevision', v_ledger.external_order_revision,
        'conflict', NULL, 'eventReplayed', v_event_replayed, 'replayed', false
      )
    );
  END IF;

  -- THE REVISION CONFLICT, AND WHY IT MUTATES NOTHING. Once the local order exists, its money is
  -- frozen by the canonical-money triggers and its stock may already be reserved. A far side that
  -- now reports a different revision of the same order is telling us the two no longer agree, and
  -- there is no honest way to reconcile that from inside this transaction. So the ledger is left
  -- exactly as it stands and the caller is handed the conflict to quarantine.
  IF v_ledger.status IN ('order_created', 'reserved', 'settled', 'done')
    AND v_ledger.external_order_revision IS DISTINCT FROM p_external_order_revision
  THEN
    RETURN jsonb_build_object(
      'contractVersion', 'channels.ingest.v0',
      'ingest', jsonb_build_object(
        'id', v_ledger.id, 'status', v_ledger.status, 'orderId', v_ledger.order_id,
        'clientId', v_ledger.client_id, 'shippingAddressId', v_ledger.shipping_address_id,
        'paymentIntentId', v_ledger.payment_intent_id,
        'externalOrderRevision', v_ledger.external_order_revision,
        'conflict', 'revision_conflict', 'eventReplayed', v_event_replayed, 'replayed', true
      )
    );
  END IF;

  -- A resume. The attempt counter is the only thing that moves; the recorded status is where the
  -- previous run got to, and the saga re-enters there.
  UPDATE public.channel_order_ingests
     SET attempt_count = attempt_count + 1,
         external_order_revision = COALESCE(p_external_order_revision, external_order_revision),
         normalized = CASE
           WHEN v_ledger.status IN ('order_created', 'reserved', 'settled', 'done') THEN normalized
           ELSE COALESCE(p_normalized, normalized)
         END,
         updated_at = now()
   WHERE id = v_ledger.id
   RETURNING * INTO v_ledger;

  RETURN jsonb_build_object(
    'contractVersion', 'channels.ingest.v0',
    'ingest', jsonb_build_object(
      'id', v_ledger.id, 'status', v_ledger.status, 'orderId', v_ledger.order_id,
      'clientId', v_ledger.client_id, 'shippingAddressId', v_ledger.shipping_address_id,
      'paymentIntentId', v_ledger.payment_intent_id,
      'externalOrderRevision', v_ledger.external_order_revision,
      'conflict', NULL, 'eventReplayed', v_event_replayed, 'replayed', true
    )
  );
END;
$$;


--
-- Name: channel_ingest_upsert_buyer(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.channel_ingest_upsert_buyer(p_ledger_id uuid, p_buyer jsonb, p_ship_to jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_ledger public.channel_order_ingests%ROWTYPE;
  v_channel public.sales_channels%ROWTYPE;
  v_provider_kind text;
  v_provider_customer_id text;
  v_identity_email text;
  v_buyer_email text;
  v_client_id uuid;
  v_address_id uuid;
  v_replayed boolean := false;
BEGIN
  IF p_ledger_id IS NULL OR p_buyer IS NULL OR p_ship_to IS NULL THEN
    RAISE EXCEPTION 'channel_ingest_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ledger FROM public.channel_order_ingests WHERE id = p_ledger_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'channel_ingest_ledger_not_found' USING ERRCODE = '22023';
  END IF;

  -- Already resolved by an earlier attempt. Returning the recorded ids is what stops a resume from
  -- minting a second client and a second address for the same order.
  IF v_ledger.client_id IS NOT NULL AND v_ledger.shipping_address_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'contractVersion', 'channels.ingest.v0',
      'buyer', jsonb_build_object(
        'clientId', v_ledger.client_id, 'shippingAddressId', v_ledger.shipping_address_id,
        'clientCreated', false, 'replayed', true
      )
    );
  END IF;

  SELECT * INTO v_channel FROM public.sales_channels WHERE id = v_ledger.channel_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'channel_ingest_channel_not_found' USING ERRCODE = '22023';
  END IF;

  v_provider_kind := 'channel:' || v_channel.slug;

  -- THE WHOLE IDENTITY RULE, IN ONE COALESCE. A connector that declares a stable buyer reference
  -- gets a buyer that persists across orders; a connector that declares none (the wire contract's
  -- explicit `externalCustomerRef: null`, meaning "no stable identity exists on this platform")
  -- gets an identity scoped to this one order. Email is NEVER consulted: marketplace relay
  -- addresses are rotated per order on some surfaces and shared across buyers on others, so
  -- matching on one would either fragment a buyer or merge two.
  v_provider_customer_id := COALESCE(
    NULLIF(btrim(COALESCE(p_buyer->>'externalCustomerRef', '')), ''),
    'order:' || v_ledger.external_order_ref
  );

  v_buyer_email := NULLIF(btrim(lower(COALESCE(p_buyer->>'email', ''))), '');

  SELECT client_id INTO v_client_id
    FROM public.customer_external_refs
   WHERE provider_kind = v_provider_kind
     AND provider_customer_id = v_provider_customer_id;

  IF v_client_id IS NOT NULL THEN
    v_replayed := true;
  ELSE
    -- WHY THE CLIENT'S `email` COLUMN IS NOT THE BUYER'S ADDRESS. `clients.email` is NOT NULL and
    -- `lower(email)` is UNIQUE across the whole table. A per-order identity therefore CANNOT store
    -- the buyer's address there: two orders from the same masked relay address would collide on
    -- that index, and a marketplace buyer who also shops the storefront would collide with their
    -- own storefront row. So the column holds a derived, deterministic, undeliverable identity
    -- address -- `.invalid` is reserved by RFC 2606 precisely so that no such address can ever
    -- resolve -- and the buyer's real (possibly relay) address is kept, lowercased, in the client's
    -- metadata and in the order's invoice snapshot. The identity address is a function of the
    -- identity key, so it is unique exactly when the identity is.
    v_identity_email := 'channel-' || md5(v_provider_kind || '|' || v_provider_customer_id)
      || '@channel-buyer.invalid';

    INSERT INTO public.clients (
      email, first_name, last_name, phone, country, lifecycle_stage, acquisition_source, metadata
    )
    VALUES (
      v_identity_email,
      NULLIF(btrim(COALESCE(p_buyer->>'firstName', '')), ''),
      NULLIF(btrim(COALESCE(p_buyer->>'lastName', '')), ''),
      NULLIF(btrim(COALESCE(p_buyer->>'phone', '')), ''),
      NULLIF(btrim(COALESCE(p_ship_to->>'countryCode', '')), ''),
      'customer',
      v_provider_kind,
      jsonb_build_object(
        'source', 'channels.ingest.v0',
        'channelSlug', v_channel.slug,
        'externalCustomerRef', p_buyer->>'externalCustomerRef',
        'buyerEmail', v_buyer_email,
        'buyerEmailIsMasked', COALESCE((p_buyer->>'emailIsMasked')::boolean, false),
        'buyerCommsOwner', v_channel.buyer_comms_owner
      )
    )
    RETURNING id INTO v_client_id;

    INSERT INTO public.customer_external_refs (client_id, provider_kind, provider_customer_id)
    VALUES (v_client_id, v_provider_kind, v_provider_customer_id);
  END IF;

  -- ALWAYS FRESH, and this is not an oversight. A marketplace ships each order to whatever address
  -- that order carried; a returning buyer's second order may go somewhere else entirely. Reusing
  -- the buyer's previous address would silently ship the new order to the old destination. The
  -- address is never marked default, so it cannot displace an address the customer chose
  -- themselves on the storefront.
  INSERT INTO public.addresses (
    client_id, kind, line1, line2, city, postal_code, country,
    recipient_name, contact_phone, company_name, tax_id, is_default, source, metadata
  )
  VALUES (
    v_client_id, 'shipping',
    p_ship_to->>'line1',
    NULLIF(btrim(COALESCE(p_ship_to->>'line2', '')), ''),
    p_ship_to->>'city',
    p_ship_to->>'postalCode',
    p_ship_to->>'countryCode',
    p_ship_to->>'recipientName',
    NULLIF(btrim(COALESCE(p_ship_to->>'phone', '')), ''),
    NULLIF(btrim(COALESCE(p_buyer->>'companyName', '')), ''),
    NULLIF(btrim(COALESCE(p_buyer->>'taxId', '')), ''),
    false, 'checkout',
    jsonb_build_object(
      'source', 'channels.ingest.v0',
      'channelSlug', v_channel.slug,
      'externalOrderRef', v_ledger.external_order_ref,
      'pickupPointRef', p_ship_to->>'pickupPointRef'
    )
  )
  RETURNING id INTO v_address_id;

  UPDATE public.channel_order_ingests
     SET client_id = v_client_id,
         shipping_address_id = v_address_id,
         status = CASE WHEN status = 'received' THEN 'buyer_ready' ELSE status END,
         updated_at = now()
   WHERE id = v_ledger.id;

  RETURN jsonb_build_object(
    'contractVersion', 'channels.ingest.v0',
    'buyer', jsonb_build_object(
      'clientId', v_client_id, 'shippingAddressId', v_address_id,
      'clientCreated', NOT v_replayed, 'replayed', false
    )
  );
END;
$$;


--
-- Name: check_order_feedback_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_order_feedback_token(p_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_submitted_at timestamptz;
BEGIN
  IF p_token IS NULL OR btrim(p_token) = '' THEN
    RAISE EXCEPTION 'order_feedback_invalid_token' USING ERRCODE = '22023';
  END IF;

  SELECT CASE
           WHEN feedback.token = p_token THEN feedback.submitted_at
           ELSE feedback.effect_submitted_at
         END
    INTO v_submitted_at
    FROM public.commerce_order_feedback AS feedback
   WHERE feedback.token = p_token OR feedback.effect_token = p_token
   LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;

  RETURN jsonb_build_object(
    'status', CASE WHEN v_submitted_at IS NULL THEN 'ready' ELSE 'already_submitted' END
  );
END;
$$;


--
-- Name: FUNCTION check_order_feedback_token(p_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_order_feedback_token(p_token text) IS 'Service-role-only read of opaque review token state; returns ready, already_submitted, or not_found without row data.';


--
-- Name: checkout_shipping_address_default_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkout_shipping_address_default_sync() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.kind NOT IN ('shipping', 'both') THEN
    RETURN NEW;
  END IF;

  IF NOT (
    COALESCE(NEW.metadata, '{}'::jsonb) ? 'configuratorIntentIdempotencyKey'
    OR COALESCE(NEW.metadata, '{}'::jsonb) ? 'lastConfiguratorIntentIdempotencyKey'
  ) THEN
    RETURN NEW;
  END IF;

  UPDATE public.addresses
     SET is_default = false,
         updated_at = now()
   WHERE client_id = NEW.client_id
     AND id <> NEW.id
     AND kind IN ('shipping', 'both')
     AND is_default = true;

  UPDATE public.addresses
     SET is_default = true,
         updated_at = now()
   WHERE id = NEW.id
     AND is_default IS DISTINCT FROM true;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION checkout_shipping_address_default_sync(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.checkout_shipping_address_default_sync() IS 'Promotes checkout-persisted shipping addresses to the client default so later account checkout/subscription prefill uses the last selected address.';


--
-- Name: cleanup_preview_promotion_claim_events(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_preview_promotion_claim_events(p_order_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
DECLARE
  v_deleted integer := 0;
BEGIN
  IF p_order_ids IS NULL
    OR cardinality(p_order_ids) NOT BETWEEN 1 AND 500
    OR array_position(p_order_ids, NULL) IS NOT NULL
  THEN
    RAISE EXCEPTION 'preview_promotion_claim_event_cleanup_invalid_order_ids'
      USING ERRCODE = '22023';
  END IF;
  IF private.production_database_fingerprint_matches() THEN
    RAISE EXCEPTION 'preview_promotion_claim_event_cleanup_forbidden_in_production'
      USING ERRCODE = '42501';
  END IF;

  PERFORM set_config('openlup.preview_promotion_claim_event_cleanup', 'on', true);
  DELETE FROM public.promotion_code_claim_events
   WHERE order_id = ANY(p_order_ids);
  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  PERFORM set_config('openlup.preview_promotion_claim_event_cleanup', 'off', true);
  RETURN v_deleted;
END;
$$;


--
-- Name: FUNCTION cleanup_preview_promotion_claim_events(p_order_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_preview_promotion_claim_events(p_order_ids uuid[]) IS 'Deletes append-only claim events for at most 500 explicit preview order ids. Refuses execution on the fingerprinted production database.';


--
-- Name: close_back_in_stock_notification(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_back_in_stock_notification(p_outbox_event_id uuid, p_notification_id uuid DEFAULT NULL::uuid, p_consent_decision_id uuid DEFAULT NULL::uuid, p_closed_reason text DEFAULT 'consent_blocked'::text, p_detail text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_reason text := btrim(coalesce(p_closed_reason, ''));
  v_updated boolean := false;
BEGIN
  IF p_outbox_event_id IS NULL THEN
    RAISE EXCEPTION 'back_in_stock_outbox_event_id_required' USING ERRCODE = '22023';
  END IF;
  IF v_reason <> 'consent_blocked' THEN
    RAISE EXCEPTION 'back_in_stock_close_reason_invalid' USING ERRCODE = '22023';
  END IF;

  UPDATE public.commerce_product_stock_notifications
     SET closed_at = coalesce(closed_at, now()),
         closed_reason = coalesce(closed_reason, v_reason),
         outbox_event_id = coalesce(outbox_event_id, p_outbox_event_id),
         consent_decision_id = coalesce(p_consent_decision_id, consent_decision_id),
         metadata = metadata || jsonb_build_object(
           'closedBy', 'outbox-dispatch',
           'suppressedBy', 'outbox-dispatch',
           'suppressionReason', v_reason,
           'suppressionDetail', p_detail,
           'suppressedOutboxEventId', p_outbox_event_id)
   WHERE closed_at IS NULL
     AND (
       outbox_event_id = p_outbox_event_id
       OR (
         p_notification_id IS NOT NULL
         AND id = p_notification_id
         AND (outbox_event_id IS NULL OR outbox_event_id = p_outbox_event_id)
       )
     )
   RETURNING true INTO v_updated;

  IF coalesce(v_updated, false) THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
      FROM public.commerce_product_stock_notifications
     WHERE closed_at IS NOT NULL
       AND closed_reason = v_reason
       AND (
         outbox_event_id = p_outbox_event_id
         OR (
           p_notification_id IS NOT NULL
           AND id = p_notification_id
           AND (outbox_event_id IS NULL OR outbox_event_id = p_outbox_event_id)
         )
       )
  );
END;
$$;


--
-- Name: commerce_allocate_discount_to_lines(integer[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_allocate_discount_to_lines(p_line_totals integer[], p_discount integer) RETURNS integer[]
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_count integer := cardinality(p_line_totals);
  v_sum numeric := 0;
  v_allocated numeric := 0;
  v_remaining integer;
  v_result integer[];
  v_remainders numeric[];
  v_base numeric;
  v_winner integer;
  i integer;
BEGIN
  IF v_count IS NULL
    OR (v_count > 0 AND array_ndims(p_line_totals) <> 1)
    OR (v_count > 0 AND array_lower(p_line_totals, 1) <> 1)
  THEN
    RAISE EXCEPTION 'commerce_discount_allocation_invalid_lines'
      USING ERRCODE = '22023';
  END IF;

  IF v_count = 0 THEN
    IF p_discount = 0 THEN
      RETURN ARRAY[]::integer[];
    END IF;
    RAISE EXCEPTION 'commerce_discount_allocation_zero_spread'
      USING ERRCODE = '22023';
  END IF;

  IF p_discount < 0 THEN
    RAISE EXCEPTION 'commerce_discount_allocation_negative_target'
      USING ERRCODE = '22023';
  END IF;

  FOR i IN 1..v_count LOOP
    IF p_line_totals[i] IS NULL OR p_line_totals[i] < 0 THEN
      RAISE EXCEPTION 'commerce_discount_allocation_invalid_line'
        USING ERRCODE = '22023';
    END IF;
    v_sum := v_sum + p_line_totals[i]::numeric;
  END LOOP;

  IF p_discount::numeric > v_sum THEN
    RAISE EXCEPTION 'commerce_discount_allocation_target_exceeds_lines'
      USING ERRCODE = '22023';
  END IF;

  IF v_sum = 0 AND p_discount > 0 THEN
    RAISE EXCEPTION 'commerce_discount_allocation_zero_spread'
      USING ERRCODE = '22023';
  END IF;

  v_result := array_fill(0, ARRAY[v_count]);
  v_remainders := array_fill(0::numeric, ARRAY[v_count]);

  IF p_discount = 0 THEN
    RETURN v_result;
  END IF;

  FOR i IN 1..v_count LOOP
    v_base := floor(p_line_totals[i]::numeric * p_discount::numeric / v_sum);
    v_result[i] := v_base::integer;
    v_remainders[i] := p_line_totals[i]::numeric * p_discount::numeric
      - v_base * v_sum;
    v_allocated := v_allocated + v_base;
  END LOOP;

  v_remaining := (p_discount::numeric - v_allocated)::integer;
  FOR i IN 1..v_remaining LOOP
    SELECT ordinal
      INTO v_winner
      FROM unnest(v_remainders) WITH ORDINALITY AS ranked(remainder, ordinal)
     ORDER BY remainder DESC, ordinal ASC
     LIMIT 1;

    v_result[v_winner] := v_result[v_winner] + 1;
    -- The largest-remainder remainder is always smaller than the line count, so
    -- a line receives at most one residual cent. Mark it consumed explicitly.
    v_remainders[v_winner] := -1;
  END LOOP;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION commerce_allocate_discount_to_lines(p_line_totals integer[], p_discount integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_allocate_discount_to_lines(p_line_totals integer[], p_discount integer) IS 'Deterministic largest-remainder allocation. Ties use the stable input ordinal.';


--
-- Name: commerce_cancel_abandoned_checkout(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_cancel_abandoned_checkout(p_idempotency_key text, p_order_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_guard_reason text;
BEGIN
  v_guard_reason := public.commerce_checkout_cancel_lock_guard(p_order_id);
  IF v_guard_reason = 'aggregate_changed' THEN
    RAISE EXCEPTION 'commerce_cancel_abandoned_checkout_aggregate_changed'
      USING ERRCODE = '55000';
  END IF;
  IF v_guard_reason IN (
    'provider_attempt_in_flight', 'payment_already_moved', 'payment_state_unknown'
  ) THEN
    RETURN jsonb_build_object(
      'cancelled', false,
      'reason', v_guard_reason
    );
  END IF;
  RETURN public.commerce_cancel_abandoned_checkout_sealed_v1(
    p_idempotency_key, p_order_id, p_reason
  );
END;
$$;


--
-- Name: commerce_cancel_abandoned_checkout_sealed_v1(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_cancel_abandoned_checkout_sealed_v1(p_idempotency_key text, p_order_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_sub public.subscriptions%ROWTYPE;
  v_has_sub boolean := false;
  v_cycle_id uuid;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
     OR p_order_id IS NULL
     OR p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'commerce_cancel_abandoned_checkout_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('cancelled', false, 'reason', 'order_not_found');
  END IF;

  -- Money was taken (or the order already moved on): never cancel it here.
  IF v_order.status IN ('paid', 'refunded', 'fulfillment_pending', 'fulfilled', 'cancelled', 'expired') THEN
    RETURN jsonb_build_object('cancelled', false, 'reason', 'already_terminal', 'orderStatus', v_order.status);
  END IF;

  UPDATE public.commerce_payment_intents
     SET status = 'cancelled',
         updated_at = now()
   WHERE order_id = v_order.id
     AND status NOT IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed');

  UPDATE public.commerce_payment_attempts
     SET status = 'cancelled',
         updated_at = now()
   WHERE payment_intent_id IN (
           SELECT id FROM public.commerce_payment_intents WHERE order_id = v_order.id
         )
     AND status NOT IN ('succeeded', 'cancelled', 'failed', 'expired');

  UPDATE public.commerce_payments
     SET status = 'cancelled',
         metadata = metadata || jsonb_build_object('paymentStatus', 'cancelled', 'source', 'checkout.stock_conflict_compensation.v0'),
         updated_at = now()
   WHERE order_id = v_order.id
     AND status NOT IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed');

  UPDATE public.commerce_orders
     SET status = 'cancelled',
         metadata = metadata || jsonb_build_object(
           'paymentStatus', 'cancelled',
           'checkoutAbandoned', p_reason,
           'source', 'checkout.stock_conflict_compensation.v0'
         ),
         updated_at = now()
   WHERE id = v_order.id;

  IF v_order.subscription_id IS NOT NULL THEN
    SELECT *
      INTO v_sub
      FROM public.subscriptions
     WHERE id = v_order.subscription_id
       AND status = 'pending_activation'
     FOR UPDATE;
    v_has_sub := FOUND;
  END IF;

  IF v_has_sub THEN
    UPDATE public.subscription_cycles
       SET status = 'cancelled',
           next_retry_at = NULL,
           updated_at = now()
     WHERE subscription_id = v_sub.id
       AND status NOT IN ('paid', 'cancelled');

    UPDATE public.subscriptions
       SET status = 'cancelled',
           updated_at = now()
     WHERE id = v_sub.id;

    SELECT id
      INTO v_cycle_id
      FROM public.subscription_cycles
     WHERE subscription_id = v_sub.id
     ORDER BY cycle_number
     LIMIT 1;

    INSERT INTO public.subscription_events (
      subscription_id,
      cycle_id,
      event_type,
      idempotency_key,
      payload,
      occurred_at
    )
    VALUES (
      v_sub.id,
      v_cycle_id,
      'subscription.activation_abandoned',
      p_idempotency_key,
      jsonb_build_object(
        'orderId', v_order.id,
        'reason', p_reason,
        'source', 'checkout.stock_conflict_compensation.v0'
      ),
      now()
    )
    ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'cancelled', true,
    'orderId', v_order.id,
    'subscriptionId', CASE WHEN v_has_sub THEN v_sub.id ELSE NULL END
  );
END;
$$;


--
-- Name: commerce_cancel_unstarted_promotion_order(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_cancel_unstarted_promotion_order(p_idempotency_key text, p_order_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_key public.commerce_idempotency_keys%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_cancelled jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
     OR p_order_id IS NULL OR p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'promotion_order_cancel_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- Match the canonical writer's lock order: idempotency key, then order. This
  -- prevents a compensation retry from deleting a key that a concurrent draft
  -- replay is still using.
  SELECT * INTO v_key
    FROM public.commerce_idempotency_keys keys
   WHERE keys.scope = 'commerce.order_draft.create'
     AND keys.idempotency_key = p_idempotency_key
   FOR UPDATE;
  IF NOT FOUND OR (
    coalesce(v_key.metadata->>'orderId', v_key.response_payload#>>'{orderDraft,orderId}')
      IS DISTINCT FROM 'order_' || p_order_id::text
  ) THEN
    RETURN false;
  END IF;

  SELECT * INTO v_order FROM public.commerce_orders orders
   WHERE orders.id = p_order_id FOR UPDATE;
  IF NOT FOUND OR v_order.status NOT IN ('draft', 'pending_payment') THEN
    RETURN false;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.promotion_code_claims claims
     WHERE claims.order_id = p_order_id AND claims.status = 'reserved'
  ) OR EXISTS (
    SELECT 1 FROM public.commerce_payment_intents intents WHERE intents.order_id = p_order_id
  ) OR EXISTS (
    SELECT 1 FROM public.commerce_payments payments WHERE payments.order_id = p_order_id
  ) OR EXISTS (
    SELECT 1 FROM public.inventory_reservations reservations
     WHERE reservations.order_id = p_order_id
       AND reservations.status = 'reserved'
  ) THEN
    RETURN false;
  END IF;
  SELECT public.commerce_cancel_abandoned_checkout(
    'promotion-unstarted:' || p_idempotency_key,
    p_order_id,
    left(btrim(p_reason), 120)
  ) INTO v_cancelled;
  IF NOT coalesce((v_cancelled->>'cancelled')::boolean, false) THEN
    RETURN false;
  END IF;

  -- Remove only the provisional order side effect. The configurator intent key
  -- deliberately survives, so client/pet/address identity and the browser's
  -- stable journey key can be reused by the retry.
  DELETE FROM public.outbox_events
   WHERE aggregate_id = p_order_id
     AND event_type = 'commerce.order_draft.created';
  DELETE FROM public.commerce_idempotency_keys
   WHERE id = v_key.id;
  RETURN true;
END;
$$;


--
-- Name: FUNCTION commerce_cancel_unstarted_promotion_order(p_idempotency_key text, p_order_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_cancel_unstarted_promotion_order(p_idempotency_key text, p_order_id uuid, p_reason text) IS 'Cancels only a draft/pending-payment v2 order with a reserved promotion claim, no payment truth and no active inventory reservation. Delegates canonical abandoned-checkout cancellation, including provisional-subscription cleanup; the cancelled transition releases the claim.';


--
-- Name: commerce_capture_offer_policy_v2_legacy_baseline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_capture_offer_policy_v2_legacy_baseline() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_count integer;
  v_fingerprint text;
  v_inserted boolean := false;
  v_baseline public.commerce_offer_policy_rollout_baselines%ROWTYPE;
BEGIN
  SELECT count(*)::integer,
    md5(COALESCE(string_agg(subscription.id::text, '|' ORDER BY subscription.id), ''))
  INTO v_count, v_fingerprint
  FROM public.subscriptions subscription
  WHERE subscription.offer_policy_assignment_state = 'legacy_frozen'
    AND subscription.is_test_fixture = false;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'offer_policy_legacy_baseline_empty' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_offer_policy_rollout_baselines (
    baseline_key, expected_count, expected_fingerprint
  ) VALUES ('legacy_frozen.v1', v_count, v_fingerprint)
  ON CONFLICT (baseline_key) DO NOTHING
  RETURNING * INTO v_baseline;
  v_inserted := FOUND;

  IF NOT v_inserted THEN
    SELECT * INTO STRICT v_baseline
    FROM public.commerce_offer_policy_rollout_baselines
    WHERE baseline_key = 'legacy_frozen.v1'; -- gitleaks:allow -- public schema sentinel, not a credential
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce-offer-policy-v2-legacy-baseline.v1',
    'created', v_inserted,
    'expectedCount', v_baseline.expected_count,
    'expectedFingerprint', v_baseline.expected_fingerprint,
    'capturedAt', v_baseline.captured_at
  );
END;
$$;


--
-- Name: FUNCTION commerce_capture_offer_policy_v2_legacy_baseline(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_capture_offer_policy_v2_legacy_baseline() IS 'Explicit one-time service-role capture of the audited legacy-frozen cohort count and opaque stable-ID fingerprint. Existing baselines are never overwritten.';


--
-- Name: commerce_checkout_cancel_lock_guard(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_checkout_cancel_lock_guard(p_order_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_subscription_hint uuid;
  v_hint_found boolean := false;
  v_locked_subscription_id uuid;
BEGIN
  SELECT checkout_order.subscription_id
    INTO v_subscription_hint
    FROM public.commerce_orders checkout_order
   WHERE checkout_order.id = p_order_id;
  v_hint_found := FOUND;

  IF v_hint_found AND v_subscription_hint IS NOT NULL THEN
    PERFORM 1 FROM public.subscriptions subscription
     WHERE subscription.id = v_subscription_hint FOR UPDATE;
  END IF;

  SELECT checkout_order.subscription_id
    INTO v_locked_subscription_id
    FROM public.commerce_orders checkout_order
   WHERE checkout_order.id = p_order_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN 'order_not_found';
  END IF;
  IF NOT v_hint_found
    OR v_locked_subscription_id IS DISTINCT FROM v_subscription_hint
  THEN
    RETURN 'aggregate_changed';
  END IF;

  PERFORM 1
    FROM public.commerce_payment_intents payment_intent
   WHERE payment_intent.order_id = p_order_id
   ORDER BY payment_intent.id
   FOR UPDATE;

  PERFORM 1
    FROM public.commerce_payment_attempts payment_attempt
    JOIN public.commerce_payment_intents payment_intent
      ON payment_intent.id = payment_attempt.payment_intent_id
   WHERE payment_intent.order_id = p_order_id
   ORDER BY payment_attempt.id
   FOR UPDATE OF payment_attempt;

  -- Child evidence is acquired only after every attempt. The attempt FK lock
  -- also fences a concurrent evidence insert until this decision commits.
  PERFORM 1
    FROM public.inbound_provider_events provider_event
    JOIN public.commerce_payment_attempts payment_attempt
      ON payment_attempt.id = provider_event.payment_attempt_id
    JOIN public.commerce_payment_intents payment_intent
      ON payment_intent.id = payment_attempt.payment_intent_id
   WHERE payment_intent.order_id = p_order_id
   ORDER BY provider_event.id
   FOR UPDATE OF provider_event;

  PERFORM 1
    FROM public.commerce_payment_reconciliation_runs reconciliation
    JOIN public.commerce_payment_attempts payment_attempt
      ON payment_attempt.id = reconciliation.payment_attempt_id
    JOIN public.commerce_payment_intents payment_intent
      ON payment_intent.id = payment_attempt.payment_intent_id
   WHERE payment_intent.order_id = p_order_id
   ORDER BY reconciliation.id
   FOR UPDATE OF reconciliation;

  PERFORM 1 FROM public.commerce_payments payment
   WHERE payment.order_id = p_order_id ORDER BY payment.id FOR UPDATE;

  IF v_locked_subscription_id IS NOT NULL THEN
    PERFORM 1 FROM public.subscription_cycles cycle
     WHERE cycle.subscription_id = v_locked_subscription_id
     ORDER BY cycle.id FOR UPDATE;
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.commerce_payment_attempts payment_attempt
      JOIN public.commerce_payment_intents payment_intent
        ON payment_intent.id = payment_attempt.payment_intent_id
     WHERE payment_intent.order_id = p_order_id
       AND payment_attempt.status IN (
         'created', 'sent_to_provider', 'requires_action', 'processing'
       )
  ) THEN
    RETURN 'provider_attempt_in_flight';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.commerce_payment_attempts payment_attempt
      JOIN public.commerce_payment_intents payment_intent
        ON payment_intent.id = payment_attempt.payment_intent_id
     WHERE payment_intent.order_id = p_order_id
       AND (
         payment_attempt.status = 'succeeded'
         OR EXISTS (
           SELECT 1 FROM public.inbound_provider_events provider_event
            WHERE provider_event.payment_intent_id = payment_attempt.payment_intent_id
              AND provider_event.payment_attempt_id = payment_attempt.id
              AND provider_event.provider = payment_attempt.provider
              AND provider_event.provider_payment_id = payment_attempt.provider_attempt_id
              AND provider_event.signature_verified IS TRUE
              AND provider_event.event_type = 'payment.succeeded'
         )
         OR EXISTS (
           SELECT 1 FROM public.commerce_payment_reconciliation_runs reconciliation
            WHERE reconciliation.payment_intent_id = payment_attempt.payment_intent_id
              AND reconciliation.payment_attempt_id = payment_attempt.id
              AND reconciliation.provider = payment_attempt.provider
              AND reconciliation.provider_payment_id = CASE
                WHEN payment_attempt.provider = 'tpay'
                  THEN payment_attempt.provider_session_id
                ELSE payment_attempt.provider_attempt_id
              END
              AND reconciliation.payload->>'normalizedStatus' = 'succeeded'
         )
       )
  ) OR EXISTS (
    SELECT 1 FROM public.commerce_payment_intents payment_intent
     WHERE payment_intent.order_id = p_order_id
       AND payment_intent.status IN (
         'succeeded', 'refunded', 'partially_refunded', 'disputed'
       )
  ) OR EXISTS (
    SELECT 1 FROM public.commerce_payments payment
     WHERE payment.order_id = p_order_id
       AND payment.status IN (
         'succeeded', 'refunded', 'partially_refunded', 'disputed'
       )
  ) THEN
    RETURN 'payment_already_moved';
  END IF;

  -- Unknown statuses fail closed. Only retryable terminal unpaid attempts may
  -- pass to a cancellation body.
  IF EXISTS (
    SELECT 1
      FROM public.commerce_payment_attempts payment_attempt
      JOIN public.commerce_payment_intents payment_intent
        ON payment_intent.id = payment_attempt.payment_intent_id
     WHERE payment_intent.order_id = p_order_id
       AND payment_attempt.status NOT IN (
         'blocked_preflight', 'failed', 'cancelled', 'expired'
       )
  ) THEN
    RETURN 'payment_state_unknown';
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: commerce_checkout_payment_guidance_snapshot(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_checkout_payment_guidance_snapshot(p_order_id uuid, p_payment_intent_id uuid, p_recovery_token_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
WITH current_state AS MATERIALIZED (
  SELECT o.id AS order_id, o.client_id, o.status AS order_status, o.mode,
         o.subscription_id, i.id AS intent_id, i.payment_id, i.status AS intent_status,
         i.active_attempt_id, i.provider_payment_id, i.updated_at,
         COALESCE(a.failure_reason, i.failure_reason) AS failure_reason,
         a.id AS attempt_id, a.status AS attempt_status, a.provider,
         s.status AS subscription_status, gap.paid_at,
         gap.payment_intent_id IS NOT NULL AS has_exact_gap,
         COALESCE(
           o.metadata #>> '{runtimeFinalize,source}' = 'commerce.runtime.hidden.v0'
           AND o.metadata #>> '{runtimeFinalize,checkoutKind}' = i.metadata->>'checkoutKind'
           AND (i.active_attempt_id IS NULL OR a.id IS NOT NULL)
           AND (
             (o.metadata #>> '{runtimeFinalize,checkoutKind}' = 'one_time'
              AND o.mode = 'one_time' AND i.target_kind = 'one_time_order'
              AND o.subscription_id IS NULL AND o.subscription_cycle_id IS NULL
              AND i.subscription_id IS NULL AND i.subscription_cycle_id IS NULL)
             OR
             (o.metadata #>> '{runtimeFinalize,checkoutKind}' = 'subscription_initial'
              AND o.mode = 'subscription_cycle' AND i.target_kind = 'subscription_cycle'
              AND o.subscription_id = i.subscription_id
              AND o.subscription_cycle_id = i.subscription_cycle_id
              AND c.id = i.subscription_cycle_id AND c.subscription_id = i.subscription_id
              AND c.order_id = o.id AND c.cycle_number = 1
              AND s.client_id = o.client_id)
           ), false
         ) AS eligible,
         EXISTS (
           SELECT 1 FROM public.commerce_checkout_recovery_tokens t
           WHERE t.id = p_recovery_token_id AND t.order_id = o.id
             AND t.client_id = o.client_id AND t.purpose = 'complete_checkout'
             AND t.used_at IS NULL AND t.revoked_at IS NULL
             AND t.expires_at > statement_timestamp() AND o.status = 'pending_payment'
         ) AS token_authorized
  FROM public.commerce_payment_intents i
  JOIN public.commerce_orders o ON o.id = i.order_id
  LEFT JOIN public.commerce_payment_attempts a
    ON a.id = i.active_attempt_id AND a.payment_intent_id = i.id AND a.payment_id = i.payment_id
  LEFT JOIN public.subscription_cycles c ON c.id = o.subscription_cycle_id
  LEFT JOIN public.subscriptions s ON s.id = o.subscription_id
  LEFT JOIN public.subscription_paid_activation_gaps gap ON gap.payment_intent_id = i.id
  WHERE o.id = p_order_id AND i.id = p_payment_intent_id
), observed_success AS MATERIALIZED (
  -- Suppress refusal advice before an already-verified success is applied to
  -- local status. This does not report paid or perform settlement. An older
  -- exactly linked attempt can also have paid this same obligation.
  SELECT EXISTS (
    SELECT 1 FROM public.commerce_payment_attempts a
    JOIN current_state cs ON cs.intent_id = a.payment_intent_id AND cs.payment_id = a.payment_id
    WHERE EXISTS (
      SELECT 1 FROM public.inbound_provider_events e
      WHERE e.payment_intent_id = a.payment_intent_id AND e.payment_attempt_id = a.id
        AND e.provider = a.provider AND e.provider_payment_id = a.provider_attempt_id
        AND e.signature_verified IS TRUE AND e.event_type = 'payment.succeeded'
    ) OR EXISTS (
      SELECT 1 FROM public.commerce_payment_reconciliation_runs r
      WHERE r.payment_intent_id = a.payment_intent_id AND r.payment_attempt_id = a.id
        AND r.provider = a.provider
        AND r.provider_payment_id = CASE WHEN a.provider = 'tpay'
          THEN a.provider_session_id ELSE a.provider_attempt_id END
        AND r.payload->>'normalizedStatus' = 'succeeded'
    )
  ) AS present
), bounded_history AS MATERIALIZED (
  SELECT a.id, a.status, a.provider, a.provider_attempt_id, a.provider_session_id,
         a.payment_intent_id,
         a.request_payload->>'providerFlow' AS provider_flow, a.created_at,
         a.response_payload->'failureEvidence' AS execution_evidence,
         a.payment_id = cs.payment_id AS payment_link_valid
  FROM public.commerce_payment_attempts a
  JOIN current_state cs ON cs.intent_id = a.payment_intent_id
  ORDER BY a.created_at DESC, a.id DESC
  LIMIT 101
), history AS MATERIALIZED (
  SELECT * FROM bounded_history ORDER BY created_at DESC, id DESC LIMIT 100
), projected_history AS (
  SELECT a.id, a.status, a.provider, a.provider_attempt_id, a.provider_session_id,
         a.provider_flow, a.created_at,
         evidence.complete AND a.payment_link_valid AS complete,
         CASE WHEN evidence.complete AND a.payment_link_valid AND NOT success.present
           THEN evidence.items ELSE '[]'::jsonb END AS evidence
  FROM history a
  CROSS JOIN observed_success success
  CROSS JOIN LATERAL (
    SELECT count(*) <= 32 AND COALESCE(bool_and(b.valid IS TRUE), true) AS complete,
           COALESCE(jsonb_agg(b.item ORDER BY b.observed_at DESC, b.source, b.evidence_id)
             FILTER (WHERE b.valid), '[]'::jsonb) AS items
    FROM (
      SELECT jsonb_build_object(
               'version', e.item->'version', 'source', e.item->'source',
               'disposition', e.item->'disposition', 'refusalVerified', e.item->'refusalVerified',
               'providerPaymentId', e.item->'providerPaymentId', 'providerChargeId', e.item->'providerChargeId',
               'code', e.item->'code', 'declineCode', e.item->'declineCode',
               'adviceCode', e.item->'adviceCode', 'adviceOrigin', e.item->'adviceOrigin',
               'operation', e.item->'operation', 'methodSource', e.item->'methodSource',
               'method', CASE WHEN jsonb_typeof(e.item->'method') = 'object' THEN jsonb_build_object(
                 'kind', e.item#>'{method,kind}', 'recoveryMethodKey', e.item#>'{method,recoveryMethodKey}',
                 'interaction', e.item#>'{method,interaction}'
               ) ELSE NULL END
             ) AS item, e.observed_at, e.source, e.evidence_id,
             jsonb_typeof(e.item) = 'object' AND octet_length(e.item::text) <= 8192
               AND CASE
                 WHEN a.provider = 'tpay' AND e.source IN ('execution', 'reconciliation')
                   THEN a.provider_session_id IS NOT NULL
                     AND e.item->>'providerPaymentId' = a.provider_session_id
                 WHEN a.provider = 'tpay' AND e.source = 'event'
                   THEN a.provider_attempt_id IS NOT NULL
                     AND e.item->>'providerPaymentId' = a.provider_attempt_id
                 ELSE (e.source = 'execution' AND a.provider_attempt_id IS NULL)
                   OR e.item->>'providerPaymentId' = a.provider_attempt_id
               END AS valid
      FROM (
        SELECT a.execution_evidence AS item, a.created_at AS observed_at,
               'execution'::text AS source, a.id AS evidence_id
        WHERE a.execution_evidence IS NOT NULL
        UNION ALL
        SELECT e.payload->'failureEvidence', e.created_at, 'event', e.id
        FROM public.inbound_provider_events e
        WHERE e.payment_attempt_id = a.id AND e.payment_intent_id = a.payment_intent_id
          AND e.provider = a.provider AND e.provider_payment_id = a.provider_attempt_id
          AND e.signature_verified IS TRUE AND e.payload ? 'failureEvidence'
        UNION ALL
        SELECT r.payload#>'{providerPayload,failureEvidence}', r.checked_at, 'reconciliation', r.id
        FROM public.commerce_payment_reconciliation_runs r
        WHERE r.payment_attempt_id = a.id AND r.payment_intent_id = a.payment_intent_id
          AND r.provider = a.provider
          AND r.provider_payment_id = CASE WHEN a.provider = 'tpay'
            THEN a.provider_session_id ELSE a.provider_attempt_id END
          AND r.payload#>'{providerPayload,failureEvidence}' IS NOT NULL
      ) e
      ORDER BY e.observed_at DESC, e.source, e.evidence_id
      LIMIT 33
    ) b
  ) evidence
)
SELECT jsonb_build_object(
  'snapshot', jsonb_build_object(
    'orderId', cs.order_id, 'orderStatus', cs.order_status, 'clientId', cs.client_id,
    'paymentIntentId', cs.intent_id, 'intentStatus', cs.intent_status,
    'paymentAttemptId', cs.attempt_id, 'attemptStatus', cs.attempt_status,
    'provider', cs.provider, 'providerPaymentId', cs.provider_payment_id,
    'updatedAt', cs.updated_at, 'failureReason', cs.failure_reason,
    'subscriptionId', cs.subscription_id,
    'orderMode', cs.mode, 'subscriptionStatus', cs.subscription_status,
    'paidAt', cs.paid_at, 'hasExactGap', cs.has_exact_gap
  ),
  'eligible', cs.eligible, 'tokenAuthorized', cs.token_authorized,
  'observedSuccess', success.present,
  'historyComplete', (SELECT count(*) <= 100 FROM bounded_history)
    AND COALESCE((SELECT bool_and(complete) FROM projected_history), true),
  'attempts', COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', h.id, 'status', h.status, 'provider', h.provider,
      'providerPaymentId', h.provider_attempt_id, 'providerFlow', h.provider_flow,
      'createdAt', h.created_at, 'evidence', h.evidence
    ) ORDER BY h.created_at DESC, h.id DESC)
    FROM projected_history h
  ), '[]'::jsonb)
)
FROM current_state cs
CROSS JOIN observed_success success;
$$;


--
-- Name: commerce_checkout_recovery_token_inspect(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_checkout_recovery_token_inspect(p_token_hash text, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(token_id uuid, order_id uuid, client_id uuid, mode text, status text, subscription_id uuid, token_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_token public.commerce_checkout_recovery_tokens%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_order_found boolean := false;
BEGIN
  SELECT * INTO v_token
  FROM public.commerce_checkout_recovery_tokens
  WHERE token_hash = p_token_hash;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT * INTO v_order
  FROM public.commerce_orders
  WHERE id = v_token.order_id;
  v_order_found := FOUND;

  token_id := v_token.id;
  order_id := v_token.order_id;
  client_id := v_token.client_id;
  mode := CASE WHEN v_order_found THEN v_order.mode ELSE NULL END;
  status := CASE WHEN v_order_found THEN v_order.status ELSE NULL END;
  subscription_id := CASE WHEN v_order_found THEN v_order.subscription_id ELSE NULL END;
  token_state := CASE
    WHEN v_token.revoked_at IS NOT NULL THEN 'revoked'
    WHEN v_token.used_at IS NOT NULL THEN 'used'
    WHEN v_token.expires_at <= p_now THEN 'expired'
    WHEN NOT v_order_found THEN 'order_not_found'
    WHEN v_order.status <> 'pending_payment' THEN 'order_not_recoverable'
    ELSE 'active'
  END;
  RETURN NEXT;
END;
$$;


--
-- Name: commerce_checkout_recovery_token_issue(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_checkout_recovery_token_issue(p_order_id uuid, p_token_hash text, p_expires_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_token_id uuid;
BEGIN
  SELECT * INTO v_order FROM public.commerce_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_order.status <> 'pending_payment' THEN
    RAISE EXCEPTION 'order_not_recoverable' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.commerce_checkout_recovery_tokens (order_id, client_id, token_hash, expires_at)
  VALUES (p_order_id, v_order.client_id, p_token_hash, p_expires_at)
  RETURNING id INTO v_token_id;

  RETURN v_token_id;
END;
$$;


--
-- Name: commerce_checkout_recovery_token_validate(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_checkout_recovery_token_validate(p_token_hash text, p_now timestamp with time zone DEFAULT now()) RETURNS TABLE(token_id uuid, order_id uuid, client_id uuid, mode text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_token public.commerce_checkout_recovery_tokens%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
BEGIN
  SELECT * INTO v_token
  FROM public.commerce_checkout_recovery_tokens
  WHERE token_hash = p_token_hash;

  IF NOT FOUND
     OR v_token.revoked_at IS NOT NULL
     OR v_token.used_at IS NOT NULL
     OR v_token.expires_at <= p_now THEN
    RETURN;
  END IF;

  SELECT * INTO v_order FROM public.commerce_orders WHERE id = v_token.order_id;
  IF NOT FOUND OR v_order.status <> 'pending_payment' THEN
    RETURN;
  END IF;

  token_id := v_token.id;
  order_id := v_order.id;
  client_id := v_order.client_id;
  mode := v_order.mode;
  status := v_order.status;
  RETURN NEXT;
END;
$$;


--
-- Name: commerce_checkout_resume_cleanup_expired(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_checkout_resume_cleanup_expired(p_now timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now timestamptz := COALESCE(p_now, now());
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 500), 1), 1000);
  v_deleted_count integer := 0;
BEGIN
  WITH deleted AS (
    DELETE FROM public.commerce_checkout_resume_drafts
    WHERE id IN (
      SELECT id
      FROM public.commerce_checkout_resume_drafts
      WHERE expires_at < v_now
         OR (revoked_at IS NOT NULL AND revoked_at < v_now)
      ORDER BY expires_at ASC NULLS LAST, revoked_at ASC NULLS LAST
      LIMIT v_limit
    )
    RETURNING 1
  )
  SELECT COUNT(*) INTO v_deleted_count FROM deleted;

  RETURN COALESCE(v_deleted_count, 0);
END;
$$;


--
-- Name: FUNCTION commerce_checkout_resume_cleanup_expired(p_now timestamp with time zone, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_checkout_resume_cleanup_expired(p_now timestamp with time zone, p_limit integer) IS 'Manual service-role cleanup for expired/revoked hidden checkout resume drafts. Returns deleted row count only.';


--
-- Name: commerce_claim_order_promotion_codes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_claim_order_promotion_codes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_discount jsonb;
  v_code record;
  v_promotion_id uuid;
  v_code_ids uuid[] := ARRAY[]::uuid[];
  v_snapshot_code_count integer := 0;
  v_product_discount bigint := 0;
  v_shipping_discount bigint := 0;
BEGIN
  IF jsonb_typeof(NEW.metadata#>'{quoteSnapshot,quote,discounts}') IS DISTINCT FROM 'array' THEN
    RETURN NEW;
  END IF;

  FOR v_discount IN
    SELECT value
      FROM jsonb_array_elements(NEW.metadata#>'{quoteSnapshot,quote,discounts}')
     WHERE value->>'promotionEngineVersion' = 'promotion-engine.v2'
       AND value->>'reasonCode' = 'promotion_code_v2'
  LOOP
    IF coalesce(v_discount->>'code', '') = ''
      OR coalesce(v_discount->>'promotionId', '') !~
        '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      OR coalesce(v_discount->>'promotionCodeRevision', '') !~ '^[1-9][0-9]*$'
      OR coalesce(v_discount->>'promotionDefinitionFingerprint', '') !~ '^[0-9a-f]{64}$'
      OR coalesce(v_discount->>'amountOffMinor', '') !~ '^[1-9][0-9]*$'
      OR coalesce(v_discount->>'appliesTo', '') NOT IN ('order_total', 'shipping')
    THEN
      RAISE EXCEPTION 'promotion_code_snapshot_invalid' USING ERRCODE = '22023';
    END IF;
    IF v_discount->>'appliesTo' = 'shipping' THEN
      v_shipping_discount := v_shipping_discount + (v_discount->>'amountOffMinor')::bigint;
    ELSE
      v_product_discount := v_product_discount + (v_discount->>'amountOffMinor')::bigint;
    END IF;
  END LOOP;

  SELECT count(DISTINCT upper(btrim(value->>'code')))::integer
    INTO v_snapshot_code_count
    FROM jsonb_array_elements(NEW.metadata#>'{quoteSnapshot,quote,discounts}')
   WHERE value->>'promotionEngineVersion' = 'promotion-engine.v2'
     AND value->>'reasonCode' = 'promotion_code_v2';

  IF v_product_discount > NEW.discount_cents
    OR v_shipping_discount > NEW.shipping_discount_cents THEN
    RAISE EXCEPTION 'promotion_code_snapshot_money_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_product_discount > 0 AND NEW.subtotal_cents - NEW.discount_cents < 100 THEN
    RAISE EXCEPTION 'promotion_code_product_floor_breached' USING ERRCODE = '22023';
  END IF;

  FOR v_code IN
    SELECT codes.id, codes.revision,
      min((discount->>'promotionCodeRevision')::integer) AS expected_revision,
      max((discount->>'promotionCodeRevision')::integer) AS max_expected_revision
      FROM jsonb_array_elements(NEW.metadata#>'{quoteSnapshot,quote,discounts}') discount
      JOIN public.promotion_codes codes
        ON codes.code_normalized = upper(btrim(discount->>'code'))
     WHERE discount->>'promotionEngineVersion' = 'promotion-engine.v2'
       AND discount->>'reasonCode' = 'promotion_code_v2'
     GROUP BY codes.id, codes.revision
     ORDER BY codes.id
  LOOP
    IF v_code.expected_revision <> v_code.max_expected_revision THEN
      RAISE EXCEPTION 'promotion_code_snapshot_revision_mismatch' USING ERRCODE = '22023';
    END IF;
    PERFORM private.commerce_promotion_code_claim_checked(
      v_code.id, NEW.id, v_code.expected_revision, now() + interval '24 hours'
    );
    v_code_ids := array_append(v_code_ids, v_code.id);

    FOR v_discount IN
      SELECT value
        FROM jsonb_array_elements(NEW.metadata#>'{quoteSnapshot,quote,discounts}')
       WHERE value->>'promotionEngineVersion' = 'promotion-engine.v2'
         AND value->>'reasonCode' = 'promotion_code_v2'
         AND upper(btrim(value->>'code')) = (
           SELECT code_normalized FROM public.promotion_codes WHERE id = v_code.id
         )
    LOOP
      v_promotion_id := (v_discount->>'promotionId')::uuid;
      IF NOT EXISTS (
        SELECT 1
          FROM public.promotion_code_bindings binding
          JOIN public.promotions promotion ON promotion.id = binding.promotion_id
         WHERE binding.promotion_code_id = v_code.id
           AND binding.promotion_id = v_promotion_id
           AND binding.lane = CASE
             WHEN v_discount->>'appliesTo' = 'shipping' THEN 'shipping'
             ELSE 'product'
           END
           AND promotion.promotion_engine_version = 'promotion-engine.v2'
           AND private.commerce_promotion_definition_fingerprint(
             v_code.id, v_promotion_id
           ) = v_discount->>'promotionDefinitionFingerprint'
      ) THEN
        RAISE EXCEPTION 'promotion_code_definition_changed' USING ERRCODE = '40001';
      END IF;
    END LOOP;
  END LOOP;

  IF cardinality(v_code_ids) <> v_snapshot_code_count THEN
    RAISE EXCEPTION 'promotion_code_definition_changed' USING ERRCODE = '40001';
  END IF;

  IF cardinality(v_code_ids) > 0 THEN
    UPDATE public.commerce_orders
       SET metadata = metadata || jsonb_build_object(
         'promotionEngineVersion', 'promotion-engine.v2',
         'promotionCodeIds', to_jsonb(v_code_ids),
         'promotionProductDiscountMinor', v_product_discount,
         'promotionShippingDiscountMinor', v_shipping_discount
       )
     WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: FUNCTION commerce_claim_order_promotion_codes(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_claim_order_promotion_codes() IS 'AFTER INSERT only: atomically claims explicit v2 quote winners inside the canonical order-money transaction. Its metadata UPDATE cannot re-enter this insert-only trigger.';


--
-- Name: commerce_configurator_persist_intent(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_configurator_persist_intent(p_intent jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_scope text := 'commerce_configurator_intent';
  v_key text := p_intent->>'idempotencyKey';
  v_fingerprint text := md5(p_intent::text);
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_response jsonb;
  v_client_id uuid;
  v_pet_id uuid;
  -- CP1-0: map the versioned neutral command without changing legacy selectors.
  v_is_neutral boolean := p_intent->>'version' = 'commerce.checkout_command.v1';
  v_first_name text := CASE WHEN p_intent->>'version' = 'commerce.checkout_command.v1'
    THEN p_intent#>>'{customer,firstName}' ELSE p_intent#>>'{contact,firstName}' END;
  v_last_name text := CASE WHEN p_intent->>'version' = 'commerce.checkout_command.v1'
    THEN p_intent#>>'{customer,lastName}' ELSE p_intent#>>'{contact,lastName}' END;
  v_phone text := CASE WHEN p_intent->>'version' = 'commerce.checkout_command.v1'
    THEN p_intent#>>'{customer,phone}' ELSE p_intent#>>'{contact,phone}' END;
  v_pet_referenced text := NULLIF(btrim(p_intent#>>'{petProfile,petId}'), '');
  v_pet_reused_by_key boolean := false;
  v_address_id uuid;
  v_address_key text;
  v_auth_user_id uuid;
  v_client_auth_user_id uuid;
  v_identity_write_allowed boolean;
  v_recipient_name text;
  v_email text := lower(btrim(CASE WHEN p_intent->>'version' = 'commerce.checkout_command.v1'
    THEN p_intent#>>'{customer,email}' ELSE p_intent#>>'{contact,email}' END));
  v_street text := CASE WHEN p_intent->>'version' = 'commerce.checkout_command.v1'
    THEN p_intent#>>'{shippingAddress,street}' ELSE p_intent#>>'{address,street}' END;
  v_postal_code text := CASE WHEN p_intent->>'version' = 'commerce.checkout_command.v1'
    THEN p_intent#>>'{shippingAddress,postalCode}' ELSE p_intent#>>'{address,postalCode}' END;
  v_city text := CASE WHEN p_intent->>'version' = 'commerce.checkout_command.v1'
    THEN p_intent#>>'{shippingAddress,city}' ELSE p_intent#>>'{address,city}' END;
  v_country text := CASE WHEN p_intent->>'version' = 'commerce.checkout_command.v1'
    THEN p_intent#>>'{shippingAddress,country}' ELSE p_intent#>>'{address,country}' END;
  v_client_match_reason text := 'client_created';
  v_now timestamptz := now();
BEGIN
  IF p_intent->>'version' NOT IN ('commerce.configurator_intent.v1', 'commerce.checkout_command.v1') THEN
    RAISE EXCEPTION 'configurator_intent_invalid_version' USING ERRCODE = '22023';
  END IF;
  IF v_is_neutral AND p_intent ? 'petProfile' THEN
    RAISE EXCEPTION 'configurator_intent_neutral_pet_profile_forbidden' USING ERRCODE = '22023';
  END IF;
  -- The neutral platform command carries its own ISO country; it never inherits
  -- the legacy default below.
  IF v_is_neutral AND coalesce(nullif(btrim(v_country), ''), '') = '' THEN
    RAISE EXCEPTION 'configurator_intent_neutral_country_required' USING ERRCODE = '22023';
  END IF;
  IF v_key IS NULL OR btrim(v_key) = '' OR length(v_key) < 8 THEN
    RAISE EXCEPTION 'configurator_intent_invalid_idempotency_key' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = v_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{replayed}', 'true'::jsonb, false);
    END IF;

    -- Stable journey key with an edited payload (or a prior incomplete attempt):
    -- this is an idempotent identity UPDATE, NOT a conflict. Re-open the key with
    -- the new fingerprint and fall through to the resolution logic below, which
    -- reuses (and refreshes) the client / pet / address already minted for this
    -- key. The SELECT ... FOR UPDATE above holds the row lock, so concurrent
    -- submits of the same key serialize through here.
    UPDATE public.commerce_idempotency_keys
       SET request_fingerprint = v_fingerprint,
           status = 'in_progress',
           response_payload = NULL,
           metadata = metadata || jsonb_build_object(
             'boundary', 'commerce_configurator_persist_intent',
             'reopenedForUpdate', true
           )
     WHERE scope = v_scope
       AND idempotency_key = v_key;
  ELSE
    INSERT INTO public.commerce_idempotency_keys (
      scope, idempotency_key, request_fingerprint, status, metadata
    )
    VALUES (
      v_scope, v_key, v_fingerprint, 'in_progress',
      jsonb_build_object('boundary', 'commerce_configurator_persist_intent')
    );
  END IF;

  -- The subject the ROUTE proved, and nothing else. The browser cannot assert it:
  -- the persistence adapter stamps this key last and unconditionally, so a payload
  -- that carries one has it overwritten before the call.
  --
  -- ⛔ An unparseable value degrades to NULL, i.e. to "guest", ON PURPOSE. That is
  -- the restrictive direction: a guest may not rewrite an account-linked row. The
  -- permissive failure - treating garbage as proof - is the one that must be
  -- impossible, and raising instead would turn a server-side bug into a checkout
  -- outage.
  BEGIN
    v_auth_user_id := nullif(btrim(coalesce(p_intent->>'authenticatedUserId', '')), '')::uuid;
  EXCEPTION WHEN others THEN
    v_auth_user_id := NULL;
  END;

  -- The name this order addresses its parcel to. It is written to the ADDRESS,
  -- which is where a recipient belongs, and it is written whether or not the
  -- identity write below is permitted - otherwise refusing the profile write would
  -- leave the parcel labelled with the stored account name instead of the person
  -- the buyer actually named.
  v_recipient_name := nullif(btrim(concat_ws(' ', v_first_name, v_last_name)), '');

  -- Client resolution: EXACT lowercase email only. A guest typing `base+tag@`
  -- does NOT resolve to the client owning `base@` — it falls through to creating a
  -- fresh client scoped to the literal typed email (no cross-account attach
  -- without authentication). The authenticated flow locks the email to the
  -- account email, so exact match still wins there.
  SELECT id, auth_user_id
    INTO v_client_id, v_client_auth_user_id
    FROM public.clients
   WHERE lower(email) = v_email
   ORDER BY created_at ASC
   LIMIT 1
   FOR UPDATE;

  IF v_client_id IS NOT NULL THEN
    v_client_match_reason := 'client_match_exact_email';
  END IF;

  IF v_client_id IS NULL THEN
    INSERT INTO public.clients (
      email, first_name, last_name, phone, country, lifecycle_stage,
      acquisition_source, metadata
    )
    VALUES (
      v_email,
      v_first_name,
      v_last_name,
      v_phone,
      v_country,
      'lead',
      'hidden_configurator',
      jsonb_build_object('hiddenCommerce', jsonb_build_object(
        'lastIntentIdempotencyKey', v_key,
        'locale', p_intent->>'locale',
        'mode', p_intent->>'mode',
        'clientMatchReason', v_client_match_reason
      ))
    )
    RETURNING id INTO v_client_id;
  ELSE
    -- WHO MAY REWRITE THIS ROW. A row with no `auth_user_id` is a guest/lead row and
    -- keeps today's behaviour, which is the identity-fragmentation case this update
    -- was written for. A row that belongs to an account may be rewritten only by a
    -- request that PROVED that account. Resolving the row by e-mail is fine;
    -- treating a typed e-mail as permission to edit the record it names is not.
    v_identity_write_allowed := (
      v_client_auth_user_id IS NULL
      OR (v_auth_user_id IS NOT NULL AND v_client_auth_user_id = v_auth_user_id)
    );

    -- ⛔ Scoped to four columns, never to the request. The metadata and
    -- `updated_at` writes below are idempotency bookkeeping and always run: a
    -- refusal here must never fail a checkout, only decline an identity write.
    UPDATE public.clients
       SET first_name = CASE WHEN v_identity_write_allowed
                             THEN COALESCE(NULLIF(v_first_name, ''), first_name)
                             ELSE first_name END,
           last_name = CASE WHEN v_identity_write_allowed
                            THEN COALESCE(NULLIF(v_last_name, ''), last_name)
                            ELSE last_name END,
           phone = CASE WHEN v_identity_write_allowed
                        THEN COALESCE(NULLIF(v_phone, ''), phone)
                        ELSE phone END,
           country = CASE WHEN v_identity_write_allowed
                          THEN COALESCE(NULLIF(v_country, ''), country)
                          ELSE country END,
           updated_at = v_now,
           metadata = metadata || jsonb_build_object('hiddenCommerce', jsonb_build_object(
             'lastIntentIdempotencyKey', v_key,
             'locale', p_intent->>'locale',
             'mode', p_intent->>'mode',
             'clientMatchReason', v_client_match_reason
           ))
     WHERE id = v_client_id;
  END IF;

  -- CP1-0: neutral commands never lookup, create, or update a pet. The full
  -- legacy block remains unchanged inside this branch.
  IF NOT v_is_neutral THEN
  -- Reuse the explicitly referenced account pet when it belongs to this client
  -- (account order flow). The owner scope (client_id) means a petId that points at
  -- another client's pet simply does not match and falls through to insert.
  IF v_pet_referenced IS NOT NULL
     AND v_pet_referenced ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  THEN
    SELECT id
      INTO v_pet_id
      FROM public.pets
     WHERE id = v_pet_referenced::uuid
       AND client_id = v_client_id
     FOR UPDATE;
  END IF;

  -- Idempotent reuse: a pet already created by this idempotency key (double submit
  -- OR an edited stable journey key). Reused-by-key pets are refreshed to the
  -- latest pet profile below so the same key returns the same pet, updated.
  IF v_pet_id IS NULL THEN
    SELECT id
      INTO v_pet_id
      FROM public.pets
     WHERE client_id = v_client_id
       AND metadata->>'configuratorIntentIdempotencyKey' = v_key
     FOR UPDATE;
    IF v_pet_id IS NOT NULL THEN
      v_pet_reused_by_key := true;
    END IF;
  END IF;

  IF v_pet_id IS NULL THEN
    INSERT INTO public.pets (
      client_id, pet_type, name, breed, age_label, weight_kg, metadata
    )
    VALUES (
      v_client_id,
      'dog',
      p_intent#>>'{petProfile,name}',
      p_intent#>>'{petProfile,breed}',
      p_intent#>>'{petProfile,ageBand}',
      NULLIF(p_intent#>>'{petProfile,weightKg}', '')::numeric,
      jsonb_build_object(
        'configuratorIntentIdempotencyKey', v_key,
        'activityLevel', p_intent#>>'{petProfile,activityLevel}',
        'bcs', p_intent#>>'{petProfile,bcs}',
        'allergenSlugs', COALESCE(p_intent#>'{petProfile,allergenSlugs}', '[]'::jsonb),
        'dailyKcalOverride', p_intent#>'{petProfile,dailyKcalOverride}'
      )
    )
    RETURNING id INTO v_pet_id;
  ELSIF v_pet_reused_by_key THEN
    -- Refresh the same-key pet to the latest edited profile. Only the pet minted
    -- by THIS idempotency key is touched; owner-scoped account pets (matched via
    -- petProfile.petId) are never overwritten from a checkout intent.
    UPDATE public.pets
       SET name = p_intent#>>'{petProfile,name}',
           breed = p_intent#>>'{petProfile,breed}',
           age_label = p_intent#>>'{petProfile,ageBand}',
           weight_kg = NULLIF(p_intent#>>'{petProfile,weightKg}', '')::numeric,
           updated_at = v_now,
           metadata = metadata || jsonb_build_object(
             'configuratorIntentIdempotencyKey', v_key,
             'activityLevel', p_intent#>>'{petProfile,activityLevel}',
             'bcs', p_intent#>>'{petProfile,bcs}',
             'allergenSlugs', COALESCE(p_intent#>'{petProfile,allergenSlugs}', '[]'::jsonb),
             'dailyKcalOverride', p_intent#>'{petProfile,dailyKcalOverride}'
           )
     WHERE id = v_pet_id;
  END IF;
  END IF;

  v_address_key := lower(
    translate(
      regexp_replace(
        concat_ws('|',
          v_client_id::text,
          'shipping',
          coalesce(nullif(btrim(v_country), ''), 'PL'),
          regexp_replace(btrim(coalesce(v_postal_code, '')), '[\s-]+', '', 'g'),
          regexp_replace(btrim(coalesce(v_city, '')), '\s+', ' ', 'g'),
          regexp_replace(btrim(coalesce(v_street, '')), '\s+', ' ', 'g'),
          ''
        ),
        '^\s+|\s+$',
        '',
        'g'
      ),
      'ąćęłńóśźżĄĆĘŁŃÓŚŹŻ',
      'acelnoszzACELNOSZZ'
    )
  );

  SELECT id
    INTO v_address_id
    FROM public.addresses
   WHERE client_id = v_client_id
     AND canonical_key = v_address_key
   FOR UPDATE;

  IF v_address_id IS NULL THEN
    INSERT INTO public.addresses (
      client_id, kind, label, recipient_name, line1, city, postal_code, country, is_default, last_used_at, canonical_key, metadata
    )
    VALUES (
      v_client_id,
      'shipping',
      NULL,
      v_recipient_name,
      v_street,
      v_city,
      v_postal_code,
      coalesce(nullif(v_country, ''), 'PL'),
      false,
      v_now,
      v_address_key,
      jsonb_build_object(
        'configuratorIntentIdempotencyKey', v_key,
        'selectedDelivery', p_intent->'selectedDelivery'
      )
    )
    RETURNING id INTO v_address_id;
  ELSE
    -- The canonical key is client + kind + country + postal + city + street and
    -- carries no name, so one address row is shared by every order to that place.
    -- A new order may therefore name a different recipient, and must be able to:
    -- the fulfilment row freezes whatever is here when it is created.
    UPDATE public.addresses
       SET recipient_name = COALESCE(v_recipient_name, recipient_name),
           last_used_at = v_now,
           updated_at = v_now,
           metadata = metadata || jsonb_build_object(
             'lastConfiguratorIntentIdempotencyKey', v_key,
             'selectedDelivery', p_intent->'selectedDelivery'
           )
     WHERE id = v_address_id;
  END IF;

  INSERT INTO public.client_consents (client_id, consent_type, granted, source, metadata)
  VALUES
    (v_client_id, 'gdpr', true, 'hidden_configurator', jsonb_build_object('configuratorIntentIdempotencyKey', v_key)),
    (v_client_id, 'terms', true, 'hidden_configurator', jsonb_build_object('configuratorIntentIdempotencyKey', v_key)),
    (v_client_id, 'marketing', COALESCE((p_intent#>>'{consents,marketing}')::boolean, false), 'hidden_configurator', jsonb_build_object('configuratorIntentIdempotencyKey', v_key));

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.configurator_intent_persistence.v1',
    'intentVersion', 'commerce.configurator_intent.v1',
    'idempotencyKey', v_key,
    'clientId', v_client_id,
    'petId', v_pet_id,
    'addressId', v_address_id,
    'clientMatchReason', v_client_match_reason,
    'replayed', false
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object(
           'clientId', v_client_id,
           'petId', v_pet_id,
           'addressId', v_address_id,
           'clientMatchReason', v_client_match_reason
         )
   WHERE scope = v_scope
     AND idempotency_key = v_key;

  RETURN v_response;
END;
$_$;


--
-- Name: FUNCTION commerce_configurator_persist_intent(p_intent jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_configurator_persist_intent(p_intent jsonb) IS 'Hidden configurator intent persistence; a stable journey key is an idempotent identity UPSERT — same key + edited payload reuses and refreshes the same client/pet/address (no 23505 conflict). Reuses referenced account pet (owner-scoped) before idempotency-key reuse; client dedup is EXACT lowercase email only (no plus-normalized fallback) so a guest +alias never folds onto an unrelated existing client (CJ01-AC). Neutral commerce.checkout_command.v1 accepts customer/shippingAddress without petProfile, skips all pet writes, and returns petId null and requires its own country instead of inheriting the legacy default.';


--
-- Name: commerce_create_channel_order(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_create_channel_order(p_idempotency_key text, p_ledger_id uuid, p_expanded_lines jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'channels.order.create';
  v_ledger public.channel_order_ingests%ROWTYPE;
  v_channel public.sales_channels%ROWTYPE;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_request_fingerprint text;
  v_order jsonb;
  v_totals jsonb;
  v_source jsonb;
  v_line jsonb;
  v_resolved jsonb := '[]'::jsonb;
  v_ordinal integer := 0;
  v_sku_code text;
  v_sku_id uuid;
  v_vat_bps integer;
  v_sku_vat_bps integer;
  v_effective integer;
  v_net integer;
  v_lines_gross bigint := 0;
  v_lines_discount bigint := 0;
  v_net_total bigint := 0;
  v_shipping_net integer;
  v_shipping_vat_bps integer;
  v_order_id uuid;
  v_order_number text;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8 OR p_ledger_id IS NULL THEN
    RAISE EXCEPTION 'channel_order_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ledger FROM public.channel_order_ingests WHERE id = p_ledger_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'channel_ingest_ledger_not_found' USING ERRCODE = '22023';
  END IF;

  -- The order this ledger row already produced IS the replay answer, and it is a stronger one than
  -- a stored response payload: it is the live row. The previous wave's partial unique index on
  -- (source_channel_id, source_order_ref) is the second line of defence, for the case where two
  -- callers race past this read.
  IF v_ledger.order_id IS NOT NULL THEN
    SELECT order_number INTO v_order_number FROM public.commerce_orders WHERE id = v_ledger.order_id;
    RETURN jsonb_build_object(
      'contractVersion', 'channels.ingest.v0',
      'channelOrder', jsonb_build_object(
        'orderId', v_ledger.order_id, 'orderRef', v_order_number, 'replayed', true
      )
    );
  END IF;

  IF v_ledger.client_id IS NULL OR v_ledger.shipping_address_id IS NULL THEN
    RAISE EXCEPTION 'channel_order_buyer_not_resolved' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_channel FROM public.sales_channels WHERE id = v_ledger.channel_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'channel_ingest_channel_not_found' USING ERRCODE = '22023';
  END IF;

  v_order := v_ledger.normalized;
  v_totals := v_order->'totals';

  IF v_order->>'contractVersion' IS DISTINCT FROM 'channel.order.v1' THEN
    RAISE EXCEPTION 'channel_order_unsupported_contract_version' USING ERRCODE = '22023';
  END IF;

  -- SETTLEMENT EVIDENCE FIRST, BEFORE ANY MONEY IS READ. An order whose payment reference is blank
  -- has no proof that anybody was ever charged, and this shop must not create a payable row for it.
  IF NULLIF(btrim(COALESCE(v_order#>>'{payment,externalPaymentRef}', '')), '') IS NULL THEN
    RAISE EXCEPTION 'channel_order_missing_settlement_evidence' USING ERRCODE = '22023';
  END IF;

  -- The channel row is the currency authority. Nothing below states a currency code.
  IF v_order->>'currency' IS DISTINCT FROM v_channel.currency THEN
    RAISE EXCEPTION 'channel_order_currency_mismatch' USING ERRCODE = '22023';
  END IF;

  -- THE SURFACE MUST HAVE SAID HOW IT SHIPS, AND IT MUST HAVE SAID SO BEFORE THE ORDER EXISTS.
  -- Everything downstream of a paid order -- which provider is asked for a label, whose stock the
  -- reservation draws against, whether the parcel is ever offered to the provider at all -- is
  -- decided from the selection this line copies. An order written without one is an order that
  -- reaches the fulfilment rail and silently stops inside it, which is the exact defect this
  -- refusal exists to make impossible. It is checked here, next to the currency it most resembles:
  -- both are facts about the SURFACE rather than the order, both are pure configuration, and a
  -- deployment missing either is misconfigured rather than unlucky.
  IF v_channel.delivery_selection IS NULL THEN
    RAISE EXCEPTION 'channel_order_delivery_selection_undeclared' USING ERRCODE = '22023';
  END IF;

  -- The header equation, re-asserted rather than trusted.
  IF (v_totals->>'grandTotalMinor')::bigint <> (
    (v_totals->>'itemsGrossMinor')::bigint - (v_totals->>'itemsDiscountMinor')::bigint
    + (v_totals->>'shippingGrossMinor')::bigint - (v_totals->>'shippingDiscountMinor')::bigint
  ) THEN
    RAISE EXCEPTION 'channel_order_money_equation_mismatch' USING ERRCODE = '22023';
  END IF;

  -- WHICH LINE SET GETS WRITTEN. The expansion when the caller resolved one, the wire lines
  -- otherwise. This is the ONE behavioural fork this migration introduces, and it is deliberately a
  -- fork in the INPUT rather than in the logic: everything below runs identically either way, so a
  -- bundle order and a SKU order cannot drift into two different code paths that age separately.
  -- An expansion that is present but empty is a caller defect, not an order with no lines, and it
  -- is refused by the existing no-lines check below.
  v_source := COALESCE(p_expanded_lines, v_order->'lines');

  -- FIRST PASS: resolve and check every line before a single row is written. This is not a style
  -- choice. `commerce_orders.tax_cents` is one of the columns the canonical-money freeze trigger
  -- refuses to see change after the header exists, so the header cannot be inserted and then
  -- corrected -- the tax figure has to be known before the INSERT, and it is a function of every
  -- line's resolved VAT rate. Resolving here also means an unmappable SKU or an unresolvable rate
  -- refuses the order before it exists, rather than leaving a half-written one behind.
  FOR v_line IN SELECT jsonb_array_elements(v_source) LOOP
    v_ordinal := v_ordinal + 1;
    v_lines_gross := v_lines_gross + (v_line->>'lineGrossMinor')::bigint;
    v_lines_discount := v_lines_discount + (v_line->>'lineDiscountMinor')::bigint;

    -- A wire line names its sellable under `sellable`; an expanded line has already been resolved
    -- to a SKU and names it directly. Both are read here, and a wire line of any kind other than
    -- `sku` that reached this point WITHOUT an expansion is still refused by name -- which is what
    -- makes an unexpanded bundle a loud refusal rather than a silently dropped line.
    IF p_expanded_lines IS NULL AND v_line#>>'{sellable,kind}' IS DISTINCT FROM 'sku' THEN
      RAISE EXCEPTION 'channel_order_unsupported_sellable_kind' USING ERRCODE = '22023';
    END IF;

    v_sku_code := NULLIF(btrim(COALESCE(v_line->>'skuCode', v_line#>>'{sellable,skuCode}', '')), '');
    IF v_sku_code IS NULL THEN
      RAISE EXCEPTION 'channel_order_unmapped_sellable' USING ERRCODE = '22023';
    END IF;

    -- The catalogue must be able to sell it TODAY. A draft or archived SKU would create an order
    -- the fulfilment guards later refuse, after the buyer has already been charged elsewhere.
    SELECT id, NULLIF(btrim(COALESCE(metadata->>'vatRateBps', '')), '')::integer
      INTO v_sku_id, v_sku_vat_bps
      FROM public.catalog_skus
     WHERE sku = v_sku_code AND status = 'active';
    IF v_sku_id IS NULL THEN
      RAISE EXCEPTION 'channel_order_unmapped_sellable' USING ERRCODE = '22023';
    END IF;

    -- THE VAT CHAIN, IN ORDER, WITH A REFUSAL AT THE END. What the far side declared for this
    -- line; else what the catalogue records for this SKU; else what the channel declares as its
    -- default; else nothing, and an order with an unknowable tax rate is not created. Guessing
    -- here would mis-state a tax figure on an invoice, which is the one error that is worse than
    -- refusing the order.
    v_vat_bps := COALESCE(
      NULLIF(btrim(COALESCE(v_line->>'vatRateBps', '')), '')::integer,
      v_sku_vat_bps,
      v_channel.default_vat_rate_bps
    );
    IF v_vat_bps IS NULL THEN
      RAISE EXCEPTION 'channel_order_vat_unresolvable' USING ERRCODE = '22023';
    END IF;

    v_effective := (v_line->>'lineGrossMinor')::integer - (v_line->>'lineDiscountMinor')::integer;
    v_net := round(v_effective::numeric * 10000::numeric / (10000 + v_vat_bps)::numeric)::integer;
    v_net_total := v_net_total + v_net;

    v_resolved := v_resolved || jsonb_build_array(jsonb_build_object(
      'line', v_line, 'skuId', v_sku_id, 'skuCode', v_sku_code,
      'vatRateBps', v_vat_bps, 'effective', v_effective, 'net', v_net, 'ordinal', v_ordinal
    ));
  END LOOP;

  IF v_ordinal = 0 THEN
    RAISE EXCEPTION 'channel_order_no_lines' USING ERRCODE = '22023';
  END IF;

  -- THE EXPANSION'S ONLY LICENCE IS SHAPE, AND THIS IS WHERE THAT IS ENFORCED. The sums are taken
  -- from whichever line set was written and compared against the header the far side sent. A
  -- bundle exploded into components that lost a cent, invented one, or moved money between the
  -- gross and the discount fails here, under the name this schema already uses for a line set that
  -- does not add up to its header.
  IF v_lines_gross <> (v_totals->>'itemsGrossMinor')::bigint
    OR v_lines_discount <> (v_totals->>'itemsDiscountMinor')::bigint
  THEN
    RAISE EXCEPTION 'channel_order_line_sum_mismatch' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope AND idempotency_key = p_idempotency_key
   FOR UPDATE;
  v_request_fingerprint := md5(v_ledger.id::text || '|' || v_ledger.channel_id::text || '|'
    || v_ledger.external_order_ref || '|' || (v_totals->>'grandTotalMinor'));
  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{channelOrder,replayed}', 'true'::jsonb, false);
    END IF;
    RAISE EXCEPTION 'channel_order_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope, idempotency_key, request_fingerprint, status, metadata
  )
  VALUES (
    v_scope, p_idempotency_key, v_request_fingerprint, 'in_progress',
    jsonb_build_object('boundary', 'commerce_create_channel_order', 'ingestId', v_ledger.id)
  );

  -- Shipping VAT follows the same chain as a line, minus the line step: the channel's declared
  -- default, or nothing. A channel that has declared no VAT rate ships its shipping tax-free here,
  -- which is the only honest reading of "this deployment has not told us a rate".
  v_shipping_vat_bps := COALESCE(v_channel.default_vat_rate_bps, 0);
  v_shipping_net := round(
    ((v_totals->>'shippingGrossMinor')::integer - (v_totals->>'shippingDiscountMinor')::integer)::numeric
    * 10000::numeric / (10000 + v_shipping_vat_bps)::numeric
  )::integer;

  INSERT INTO public.commerce_orders (
    client_id, status, currency,
    subtotal_cents, discount_cents, shipping_cents, shipping_discount_cents,
    tax_cents, total_cents, region_code, mode, shipping_address_id,
    source_kind, source_channel_id, source_order_ref, metadata
  )
  VALUES (
    v_ledger.client_id, 'draft', v_channel.currency,
    (v_totals->>'itemsGrossMinor')::integer,
    (v_totals->>'itemsDiscountMinor')::integer,
    (v_totals->>'shippingGrossMinor')::integer,
    (v_totals->>'shippingDiscountMinor')::integer,
    -- `tax_cents` is informational and sits outside the canonical money equation, but every writer
    -- in this schema sets it to total minus net, so this one does too. It is stated at INSERT
    -- because the freeze trigger refuses to see it change afterwards.
    ((v_totals->>'grandTotalMinor')::bigint - v_net_total - v_shipping_net)::integer,
    (v_totals->>'grandTotalMinor')::integer,
    -- The destination country is the region, rather than a stated one: this shop's own default
    -- would be wrong for every cross-border marketplace order.
    v_order#>>'{shipTo,countryCode}',
    'one_time',
    v_ledger.shipping_address_id,
    'marketplace', v_ledger.channel_id, v_ledger.external_order_ref,
    jsonb_build_object(
      'paymentStatus', 'not_started',
      'source', 'channels.ingest.v0',
      'channelSlug', v_channel.slug,
      'buyerCommsOwner', v_channel.buyer_comms_owner,
      'invoicePolicy', v_channel.invoice_policy,
      'channelOrderSnapshot', v_order,
      -- THE SAME KEY A STOREFRONT ORDER CARRIES, READ BY THE SAME RESOLVER, IN THE SAME PLACE.
      -- This is the whole point of the wave: a marketplace order is not routed by a second rail,
      -- it is given the one fact the single existing rail was missing. Copied verbatim from the
      -- surface; nothing here derives, normalizes or repairs it, so what an operator declared is
      -- what an operator can read back off the order.
      'selectedDelivery', v_channel.delivery_selection,
      -- WHAT THE FAR SIDE ASKED FOR, KEPT NEXT TO WHAT WAS CHOSEN. The buyer picked a delivery on
      -- the marketplace, described in the marketplace's own words. Those words are not this shop's
      -- options and are deliberately not translated into them -- but they are also not thrown
      -- away, because the one question an operator will ask about a marketplace parcel is whether
      -- what shipped matches what was bought. Both halves are on the order, so the comparison
      -- needs no second source.
      'channelShippingRequest', jsonb_build_object(
        'methodLabel', v_order#>>'{shipping,methodLabel}',
        'carrierHint', v_order#>>'{shipping,carrierHint}',
        'pickupPointRef', v_order#>>'{shipTo,pickupPointRef}'
      ),
      -- Present only when a bundle was exploded. An operator reading this order can then see the
      -- component set that was actually written next to the wire document that arrived, without
      -- having to re-run the allocator to find out what happened.
      'channelLineExpansion', p_expanded_lines,
      -- The invoice buyer is the human, not the identity row. Everything an invoice needs about
      -- them travels here, including the tax id a business buyer supplied on the far side.
      'invoiceBuyerSnapshot', jsonb_build_object(
        'email', NULLIF(btrim(lower(COALESCE(v_order#>>'{buyer,email}', ''))), ''),
        'emailIsMasked', COALESCE((v_order#>>'{buyer,emailIsMasked}')::boolean, false),
        'firstName', v_order#>>'{buyer,firstName}',
        'lastName', v_order#>>'{buyer,lastName}',
        'companyName', v_order#>>'{buyer,companyName}',
        'taxId', v_order#>>'{buyer,taxId}',
        'phone', v_order#>>'{buyer,phone}',
        'countryCode', v_order#>>'{shipTo,countryCode}'
      )
    )
  )
  RETURNING id, order_number INTO v_order_id, v_order_number;

  -- SECOND PASS: write the lines the first pass already resolved. Nothing is decided here.
  FOR v_line IN SELECT jsonb_array_elements(v_resolved) LOOP
    INSERT INTO public.commerce_order_items (
      order_id, sku_id, quantity, unit_price_cents, total_cents,
      discount_allocated_cents, effective_total_cents, effective_net_cents,
      vat_rate_bps, allocation_ordinal, product_snapshot
    )
    VALUES (
      v_order_id,
      (v_line->>'skuId')::uuid,
      (v_line#>>'{line,quantity}')::integer,
      (v_line#>>'{line,unitGrossMinor}')::integer,
      (v_line#>>'{line,lineGrossMinor}')::integer,
      (v_line#>>'{line,lineDiscountMinor}')::integer,
      (v_line->>'effective')::integer,
      (v_line->>'net')::integer,
      (v_line->>'vatRateBps')::integer,
      -- Stated outright rather than inferred: the wire order's own line order is the allocation
      -- order, and there is no quote snapshot here for the assigning trigger to prove one from.
      (v_line->>'ordinal')::integer,
      jsonb_build_object(
        'sku', v_line->>'skuCode',
        'source', 'channels.ingest.v0',
        'externalLineRef', v_line#>>'{line,externalLineRef}',
        'externalOfferRef', COALESCE(
          v_line#>>'{line,externalOfferRef}', v_line#>>'{line,sellable,externalOfferRef}'
        ),
        -- PROVENANCE, and it is the reason a picker can be told what to put in the box. Null on a
        -- line the marketplace sent as a SKU; on a component line it names the bundle it came out
        -- of and how many of that bundle were bought, so the component quantity on this row can
        -- always be traced back to a number the buyer actually chose.
        'bundleCode', v_line#>>'{line,bundleCode}',
        'bundleQty', v_line#>>'{line,bundleQty}',
        'channelLine', v_line->'line'
      )
    );
  END LOOP;

  -- Emitted in the same transaction that creates the order, so a consumer can never observe one
  -- without the other. Nothing registers a handler for this type yet: the dispatcher's claim
  -- anti-join leaves an unregistered type pending, harmlessly, until one exists.
  INSERT INTO public.outbox_events (
    aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
  )
  VALUES (
    'commerce_order', v_order_id, 'channel.order.ingested', p_idempotency_key || ':ingested',
    jsonb_build_object(
      'contract_version', 'channel.order.ingested.v1',
      'order_id', v_order_id,
      'channel_slug', v_channel.slug,
      'external_order_ref', v_ledger.external_order_ref,
      'ingested_at', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
    ),
    jsonb_build_object('boundary', 'commerce_create_channel_order')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  UPDATE public.channel_order_ingests
     SET order_id = v_order_id,
         status = 'order_created',
         updated_at = now()
   WHERE id = v_ledger.id;

  v_response := jsonb_build_object(
    'contractVersion', 'channels.ingest.v0',
    'channelOrder', jsonb_build_object(
      'orderId', v_order_id, 'orderRef', v_order_number, 'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed', response_payload = v_response,
         metadata = metadata || jsonb_build_object('orderId', v_order_id)
   WHERE scope = v_scope AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: FUNCTION commerce_create_channel_order(p_idempotency_key text, p_ledger_id uuid, p_expanded_lines jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_create_channel_order(p_idempotency_key text, p_ledger_id uuid, p_expanded_lines jsonb) IS 'Creates the local order for one channel ingest ledger row from channel-final money, and copies the selling surface delivery_selection onto it so the order reaches the one dispatch rail every order uses. Refuses channel_order_delivery_selection_undeclared while the surface has declared none. p_expanded_lines carries the component lines an application resolved for bundle lines; when it is NULL the wire lines are written and any non-sku line is refused. Either way the written lines must sum to the header the far side sent.';


--
-- Name: commerce_create_order_draft_with_outbox(text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_create_order_draft_with_outbox(p_idempotency_key text, p_quote_snapshot jsonb, p_order_draft_snapshot jsonb, p_client_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_scope constant text := 'commerce.order_draft.create';
  v_event_type constant text := 'commerce.order_draft.created';
  v_request_fingerprint text;
  v_outbox_idempotency_key text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_order_id uuid;
  v_response jsonb;
  v_totals jsonb;
  v_order_currencies text[];
  v_currency text;
  v_line jsonb;
  v_line_ordinal integer;
  v_line_total bigint;
  v_line_net bigint;
  v_line_vat bigint;
  v_line_rate integer;
  v_line_sum numeric := 0;
  v_line_net_sum numeric := 0;
  v_frozen_rate integer;
  v_quote_expected_net bigint;
  v_expected_net bigint;
  v_line_totals integer[];
  v_allocations integer[];
  v_subtotal bigint;
  v_discount bigint;
  v_shipping bigint;
  v_shipping_discount bigint;
  v_net_total bigint;
  v_tax bigint;
  v_total bigint;
  v_effective integer;
BEGIN
  IF p_idempotency_key IS NULL
    OR btrim(p_idempotency_key) = ''
    OR length(p_idempotency_key) < 8
  THEN
    RAISE EXCEPTION 'commerce_order_draft_invalid_idempotency_key'
      USING ERRCODE = '22023';
  END IF;

  IF p_quote_snapshot IS NULL OR jsonb_typeof(p_quote_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'commerce_order_draft_invalid_quote_snapshot'
      USING ERRCODE = '22023';
  END IF;

  IF p_order_draft_snapshot IS NULL
    OR jsonb_typeof(p_order_draft_snapshot) <> 'object'
    OR p_order_draft_snapshot->>'contractVersion' IS DISTINCT FROM 'commerce.v0'
    OR p_order_draft_snapshot->>'source' IS DISTINCT FROM 'commerce.order_draft.bff.v0'
    OR p_order_draft_snapshot->>'status' IS DISTINCT FROM 'draft'
    OR p_order_draft_snapshot->>'paymentStatus' IS DISTINCT FROM 'not_started'
    OR p_order_draft_snapshot->>'currency' IS NULL
    OR NOT (p_order_draft_snapshot->>'currency') ~ '^[A-Z]{3}$'
    OR p_order_draft_snapshot->>'taxIncluded' IS DISTINCT FROM 'true'
    OR jsonb_typeof(p_order_draft_snapshot->'lines') <> 'array'
    OR jsonb_array_length(p_order_draft_snapshot->'lines') = 0
    OR jsonb_typeof(p_order_draft_snapshot->'totals') <> 'object'
  THEN
    RAISE EXCEPTION 'commerce_order_draft_invalid_snapshot'
      USING ERRCODE = '22023';
  END IF;

  v_totals := p_order_draft_snapshot->'totals';
  v_request_fingerprint := md5(p_quote_snapshot::text || '|' || p_order_draft_snapshot::text);
  v_outbox_idempotency_key := 'order_draft_saved:' || COALESCE(p_client_id::text, 'anonymous') || ':' || v_request_fingerprint;

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{orderDraft,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'commerce_order_draft_idempotency_conflict'
      USING ERRCODE = '23505';
  END IF;

  IF v_totals#>>'{subtotalGross,amountMinor}' IS NULL
    OR NOT (v_totals#>>'{subtotalGross,amountMinor}') ~ '^[0-9]+$'
    OR v_totals#>>'{discountTotalGross,amountMinor}' IS NULL
    OR NOT (v_totals#>>'{discountTotalGross,amountMinor}') ~ '^[0-9]+$'
    OR v_totals#>>'{netTotal,amountMinor}' IS NULL
    OR NOT (v_totals#>>'{netTotal,amountMinor}') ~ '^[0-9]+$'
    OR v_totals#>>'{taxTotal,amountMinor}' IS NULL
    OR NOT (v_totals#>>'{taxTotal,amountMinor}') ~ '^[0-9]+$'
    OR v_totals#>>'{totalGross,amountMinor}' IS NULL
    OR NOT (v_totals#>>'{totalGross,amountMinor}') ~ '^[0-9]+$'
    OR (v_totals ? 'shippingGross'
      AND NOT COALESCE(v_totals#>>'{shippingGross,amountMinor}', '') ~ '^[0-9]+$')
    OR (v_totals ? 'shippingDiscountGross'
      AND NOT COALESCE(v_totals#>>'{shippingDiscountGross,amountMinor}', '') ~ '^[0-9]+$')
  THEN
    RAISE EXCEPTION 'commerce_order_draft_invalid_totals'
      USING ERRCODE = '22023';
  END IF;

  -- INVARIANT 1 of 2 - ONE CURRENCY ACROSS EVERY MONEY NODE OF THE ORDER.
  --
  -- Permanent. This is the rule that blocks a mixed-currency cart, and it is
  -- written to survive Stage 3 unchanged: it never names a currency, it only
  -- counts how many distinct ones the order contains. Widening the set of
  -- currencies this deployment accepts cannot weaken it. Removing it later is
  -- removing a named rule, not tidying a refactor.
  --
  -- Every money node this function is about to trust contributes exactly one
  -- row: the snapshot envelope, the five mandatory totals nodes, the two
  -- shipping nodes only when the snapshot carries them (an absent shipping node
  -- is not a node, and must not be read as a disagreement), and all five money
  -- nodes of every line. A node whose `currency` key is missing yields NULL and
  -- is mapped to the '(absent)' sentinel BEFORE aggregation, so a missing key
  -- becomes a second distinct element on its own terms instead of depending on
  -- how array_agg treats NULL - and the refusal message then says which of the
  -- two problems the caller has.
  --
  -- COLLATE "C" is deliberate: the sorted set is rendered into the refusal
  -- message, so an operator comparing two deployments' logs should see the same
  -- text for the same fault rather than whatever order the server's locale
  -- happens to impose on a punctuated sentinel.
  SELECT array_agg(
           DISTINCT node.currency_code COLLATE "C"
           ORDER BY node.currency_code COLLATE "C"
         )
    INTO v_order_currencies
    FROM (
      SELECT COALESCE(header.currency_code, '(absent)') AS currency_code
        FROM (
          VALUES
            (true, p_order_draft_snapshot->>'currency'),
            (true, v_totals#>>'{subtotalGross,currency}'),
            (true, v_totals#>>'{discountTotalGross,currency}'),
            (true, v_totals#>>'{netTotal,currency}'),
            (true, v_totals#>>'{taxTotal,currency}'),
            (true, v_totals#>>'{totalGross,currency}'),
            (v_totals ? 'shippingGross',
              v_totals#>>'{shippingGross,currency}'),
            (v_totals ? 'shippingDiscountGross',
              v_totals#>>'{shippingDiscountGross,currency}')
        ) AS header(is_present, currency_code)
       WHERE header.is_present
      UNION ALL
      SELECT COALESCE(line_node.currency_code, '(absent)')
        FROM jsonb_array_elements(p_order_draft_snapshot->'lines') AS order_line(value)
        CROSS JOIN LATERAL (
          VALUES
            (order_line.value#>>'{unitPriceGross,currency}'),
            (order_line.value#>>'{lineSubtotalGross,currency}'),
            (order_line.value#>>'{tax,netAmount,currency}'),
            (order_line.value#>>'{tax,vatAmount,currency}'),
            (order_line.value#>>'{tax,grossAmount,currency}')
        ) AS line_node(currency_code)
    ) AS node;

  -- The IS NULL disjunct is load-bearing rather than defensive noise: array_agg
  -- over zero rows returns NULL, array_length(NULL, 1) is NULL, and `NULL <> 1`
  -- is unknown - which IF does not take. Without it this guard would fail OPEN
  -- in exactly the case where it matters most.
  IF v_order_currencies IS NULL
    OR array_length(v_order_currencies, 1) <> 1
  THEN
    RAISE EXCEPTION 'commerce_order_draft_mixed_currency: %',
      array_to_string(v_order_currencies, ', ')
      USING ERRCODE = '22023',
            HINT = 'Every money node of one order must carry the same currency. Requote the cart in a single currency; (absent) marks a money node that carries no currency at all.';
  END IF;

  v_currency := v_order_currencies[1];

  -- INVARIANT 2 of 2 - AND THAT CURRENCY IS ONE THIS DEPLOYMENT SETTLES IN.
  --
  -- Designed to relax. Stage 3 widens the platform to a set of accepted
  -- currencies by rewriting the single IF condition below as
  --   NOT (v_currency = ANY (public.platform_accepted_currencies()))
  -- and changing nothing else in this body. Invariant 1 above is what keeps a
  -- mixed cart refused after that happens, which is the whole reason these are
  -- two separately named checks and not one combined condition.
  --
  -- Neither operand can be NULL: v_currency is the single element of a set
  -- already proven non-empty and sentinel-mapped above, and
  -- platform_settlement_currency() either returns a code or raises 55000. The
  -- comparison therefore has no unknown branch, and a deployment whose
  -- settlement profile is missing refuses the order instead of skipping a check.
  IF v_currency <> public.platform_settlement_currency() THEN
    RAISE EXCEPTION 'commerce_order_draft_currency_not_accepted: %', v_currency
      USING ERRCODE = '22023',
            HINT = 'This deployment settles in the currency recorded in commerce_settings.settlement_currency. Price the order in that currency, or change the settlement profile first.';
  END IF;

  v_subtotal := (v_totals#>>'{subtotalGross,amountMinor}')::bigint;
  v_discount := (v_totals#>>'{discountTotalGross,amountMinor}')::bigint;
  v_shipping := COALESCE((v_totals#>>'{shippingGross,amountMinor}')::bigint, 0);
  v_shipping_discount := COALESCE(
    (v_totals#>>'{shippingDiscountGross,amountMinor}')::bigint,
    0
  );
  v_net_total := (v_totals#>>'{netTotal,amountMinor}')::bigint;
  v_tax := (v_totals#>>'{taxTotal,amountMinor}')::bigint;
  v_total := (v_totals#>>'{totalGross,amountMinor}')::bigint;

  IF v_subtotal > 2147483647
    OR v_discount > 2147483647
    OR v_shipping > 2147483647
    OR v_shipping_discount > 2147483647
    OR v_net_total > 2147483647
    OR v_tax > 2147483647
    OR v_total > 2147483647
  THEN
    RAISE EXCEPTION 'commerce_order_draft_money_overflow'
      USING ERRCODE = '22003';
  END IF;

  IF v_discount > v_subtotal OR v_shipping_discount > v_shipping THEN
    RAISE EXCEPTION 'commerce_order_draft_discount_out_of_range'
      USING ERRCODE = '22023';
  END IF;

  IF v_total <> v_subtotal - v_discount + v_shipping - v_shipping_discount
    OR v_total <> v_net_total + v_tax
  THEN
    RAISE EXCEPTION 'commerce_order_draft_totals_mismatch'
      USING ERRCODE = '22023';
  END IF;

  FOR v_line, v_line_ordinal IN
    SELECT value, ordinality::integer
      FROM jsonb_array_elements(p_order_draft_snapshot->'lines') WITH ORDINALITY
  LOOP
    IF v_line->>'quantity' IS NULL
      OR NOT (v_line->>'quantity') ~ '^[1-9][0-9]*$'
      OR v_line#>>'{unitPriceGross,amountMinor}' IS NULL
      OR NOT (v_line#>>'{unitPriceGross,amountMinor}') ~ '^[0-9]+$'
      OR v_line#>>'{lineSubtotalGross,amountMinor}' IS NULL
      OR NOT (v_line#>>'{lineSubtotalGross,amountMinor}') ~ '^[0-9]+$'
      OR v_line#>>'{tax,vatRateBps}' IS NULL
      OR NOT (v_line#>>'{tax,vatRateBps}') ~ '^[0-9]+$'
      OR v_line#>>'{tax,netAmount,amountMinor}' IS NULL
      OR NOT (v_line#>>'{tax,netAmount,amountMinor}') ~ '^[0-9]+$'
      OR v_line#>>'{tax,vatAmount,amountMinor}' IS NULL
      OR NOT (v_line#>>'{tax,vatAmount,amountMinor}') ~ '^[0-9]+$'
      OR v_line#>>'{tax,grossAmount,amountMinor}' IS NULL
      OR NOT (v_line#>>'{tax,grossAmount,amountMinor}') ~ '^[0-9]+$'
    THEN
      RAISE EXCEPTION 'commerce_order_draft_invalid_line: %', v_line_ordinal
        USING ERRCODE = '22023';
    END IF;

    v_line_total := (v_line#>>'{lineSubtotalGross,amountMinor}')::bigint;
    v_line_net := (v_line#>>'{tax,netAmount,amountMinor}')::bigint;
    v_line_vat := (v_line#>>'{tax,vatAmount,amountMinor}')::bigint;
    v_line_rate := (v_line#>>'{tax,vatRateBps}')::integer;

    IF v_frozen_rate IS NULL THEN
      v_frozen_rate := v_line_rate;
    ELSIF v_frozen_rate <> v_line_rate THEN
      RAISE EXCEPTION 'commerce_order_draft_mixed_vat_rates'
        USING ERRCODE = '22023';
    END IF;

    IF v_line_total > 2147483647
      OR v_line_net > 2147483647
      OR v_line_vat > 2147483647
      OR v_line_rate > 10000
      OR (v_line#>>'{unitPriceGross,amountMinor}')::numeric
        * (v_line->>'quantity')::numeric <> v_line_total::numeric
      OR (v_line#>>'{tax,grossAmount,amountMinor}')::numeric <> v_line_total::numeric
      OR v_line_net + v_line_vat <> v_line_total
      OR v_line_net <> round(
        v_line_total::numeric * 10000::numeric / (10000 + v_line_rate)::numeric
      )::bigint
    THEN
      RAISE EXCEPTION 'commerce_order_draft_line_money_mismatch: %', v_line_ordinal
        USING ERRCODE = '22023';
    END IF;

    v_line_sum := v_line_sum + v_line_total::numeric;
    v_line_net_sum := v_line_net_sum + v_line_net::numeric;
  END LOOP;

  IF v_line_sum <> v_subtotal::numeric THEN
    RAISE EXCEPTION 'commerce_order_draft_line_sum_mismatch'
      USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(
           (value#>>'{lineSubtotalGross,amountMinor}')::integer
           ORDER BY ordinality
         )
    INTO v_line_totals
    FROM jsonb_array_elements(p_order_draft_snapshot->'lines') WITH ORDINALITY;
  v_allocations := public.commerce_allocate_discount_to_lines(
    v_line_totals,
    v_discount::integer
  );

  SELECT COALESCE(sum(round(
           (line_total::bigint - allocated::bigint)::numeric * 10000::numeric
           / (10000 + v_frozen_rate)::numeric
         )), 0)::bigint
    INTO v_expected_net
    FROM unnest(v_line_totals, v_allocations) AS allocation(line_total, allocated);
  v_expected_net := v_expected_net + round(
    (v_shipping - v_shipping_discount)::numeric * 10000::numeric
    / (10000 + v_frozen_rate)::numeric
  )::bigint;
  v_quote_expected_net := v_line_net_sum::bigint
    - round(
      v_discount::numeric * 10000::numeric / (10000 + v_frozen_rate)::numeric
    )::bigint
    + round(
      v_shipping::numeric * 10000::numeric / (10000 + v_frozen_rate)::numeric
    )::bigint
    - round(
      v_shipping_discount::numeric * 10000::numeric
      / (10000 + v_frozen_rate)::numeric
    )::bigint;
  IF v_net_total NOT IN (v_quote_expected_net, v_expected_net)
    OR v_tax <> v_total - v_net_total
  THEN
    RAISE EXCEPTION 'commerce_order_draft_tax_totals_mismatch'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'commerce_create_order_draft_with_outbox')
  );

  INSERT INTO public.commerce_orders (
    client_id,
    status,
    currency,
    subtotal_cents,
    discount_cents,
    shipping_cents,
    shipping_discount_cents,
    tax_cents,
    total_cents,
    metadata
  )
  VALUES (
    p_client_id,
    'draft',
    v_currency,
    v_subtotal::integer,
    v_discount::integer,
    v_shipping::integer,
    v_shipping_discount::integer,
    (v_total - v_expected_net)::integer,
    v_total::integer,
    jsonb_build_object(
      'paymentStatus', 'not_started',
      'quoteSnapshot', p_quote_snapshot,
      'orderDraftSnapshot', p_order_draft_snapshot
    )
  )
  RETURNING id INTO v_order_id;

  FOR v_line, v_line_ordinal IN
    SELECT value, ordinality::integer
      FROM jsonb_array_elements(p_order_draft_snapshot->'lines') WITH ORDINALITY
  LOOP
    v_line_total := (v_line#>>'{lineSubtotalGross,amountMinor}')::integer;
    v_effective := v_line_total::integer - v_allocations[v_line_ordinal];
    INSERT INTO public.commerce_order_items (
      order_id,
      sku_id,
      quantity,
      unit_price_cents,
      total_cents,
      discount_allocated_cents,
      effective_total_cents,
      effective_net_cents,
      vat_rate_bps,
      product_snapshot
    )
    VALUES (
      v_order_id,
      NULL,
      (v_line->>'quantity')::integer,
      (v_line#>>'{unitPriceGross,amountMinor}')::integer,
      v_line_total::integer,
      v_allocations[v_line_ordinal],
      v_effective,
      round(
        v_effective::numeric * 10000::numeric
        / (10000 + (v_line#>>'{tax,vatRateBps}')::integer)::numeric
      )::integer,
      (v_line#>>'{tax,vatRateBps}')::integer,
      jsonb_build_object(
        'sku', v_line->>'sku',
        'productSlug', v_line->>'productSlug',
        'quoteLine', v_line,
        'source', 'commerce.order_draft.bff.v0'
      )
    );
  END LOOP;

  IF (
    SELECT COALESCE(sum(effective_total_cents::numeric), 0)
      FROM public.commerce_order_items
     WHERE order_id = v_order_id
  ) + v_shipping::numeric - v_shipping_discount::numeric <> v_total::numeric THEN
    RAISE EXCEPTION 'commerce_order_draft_effective_sum_mismatch'
      USING ERRCODE = '22023';
  END IF;

  IF (
    SELECT COALESCE(sum(effective_net_cents::numeric), 0)
      FROM public.commerce_order_items
     WHERE order_id = v_order_id
  ) + round(
    (v_shipping - v_shipping_discount)::numeric * 10000::numeric
    / (10000 + v_frozen_rate)::numeric
  ) <> v_expected_net::numeric THEN
    RAISE EXCEPTION 'commerce_order_draft_effective_net_sum_mismatch'
      USING ERRCODE = '22023';
  END IF;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'orderDraft', jsonb_build_object(
      'orderId', 'order_' || v_order_id::text,
      'status', 'draft',
      'paymentStatus', 'not_started',
      'idempotencyKey', p_idempotency_key,
      'quoteSnapshot', p_quote_snapshot,
      'replayed', false
    )
  );

  INSERT INTO public.outbox_events (
    aggregate_type,
    aggregate_id,
    event_type,
    idempotency_key,
    payload,
    metadata
  )
  VALUES (
    'commerce_order',
    v_order_id,
    v_event_type,
    v_outbox_idempotency_key,
    jsonb_build_object(
      'orderId', 'order_' || v_order_id::text,
      'orderUuid', v_order_id,
      'quoteSnapshot', p_quote_snapshot,
      'orderDraftSnapshot', p_order_draft_snapshot,
      'emailIntent', 'order_draft_saved'
    ),
    jsonb_build_object(
      'boundary', 'commerce_create_order_draft_with_outbox',
      'emailIntent', 'order_draft_saved'
    )
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('orderId', 'order_' || v_order_id::text)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$_$;


--
-- Name: commerce_device_first_order_redeemed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_device_first_order_redeemed(p_visitor_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT CASE
    WHEN p_visitor_id IS NULL OR btrim(p_visitor_id) = '' THEN false
    ELSE EXISTS (
      SELECT 1
        FROM public.promotion_redemptions r
        JOIN public.promotions p ON p.id = r.promotion_id
       WHERE r.visitor_id = p_visitor_id
         AND (
           p.eligibility ? 'first_onetime_purchase'
           OR p.eligibility ? 'first_subscription_purchase'
           OR p.eligibility ? 'first_purchase'
         )
    )
  END;
$$;


--
-- Name: commerce_emit_fulfillment_handed_over_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_fulfillment_handed_over_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.handed_over_at IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.handed_over_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.outbox_events (
    aggregate_type,
    aggregate_id,
    event_type,
    idempotency_key,
    payload,
    metadata
  )
  VALUES (
    'commerce_fulfillment_order',
    NEW.id,
    'commerce.fulfillment.handed_over',
    'fulfillment_handed_over:' || NEW.id::text,
    jsonb_build_object(
      'fulfillmentOrderId', NEW.id,
      'orderUuid', NEW.order_id,
      'occurredAt', NEW.handed_over_at
    ),
    jsonb_build_object('source', 'commerce_emit_fulfillment_handed_over_outbox')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_emit_fulfillment_handed_over_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_emit_fulfillment_handed_over_outbox() IS 'Emits commerce.fulfillment.handed_over exactly once when handed_over_at first becomes non-null, including delivered-first rows.';


--
-- Name: commerce_emit_order_canceled_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_order_canceled_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status <> 'cancelled' THEN
    RETURN NEW;
  END IF;

  IF coalesce(NEW.metadata->>'suppressOrderCanceledEmail', 'false') = 'true' THEN
    RETURN NEW;
  END IF;

  IF TG_OP <> 'UPDATE' OR OLD.status NOT IN ('paid', 'fulfillment_pending') THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.outbox_events (
    aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
  ) VALUES (
    'commerce_order', NEW.id, 'commerce.order.canceled',
    'order_canceled:' || NEW.id::text,
    jsonb_build_object(
      'orderId', 'order_' || NEW.id::text,
      'orderUuid', NEW.id,
      'totalCents', NEW.total_cents,
      'currency', NEW.currency,
      'occurredAt', now()
    ),
    jsonb_build_object('source', 'commerce_emit_order_canceled_outbox')
  ) ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_emit_order_canceled_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_emit_order_canceled_outbox() IS 'Emits commerce.order.canceled when a paid/in-fulfillment order is cancelled (exactly-once via order_canceled:<id>), except an explicitly marked no-refund provider-cancellation confirmation. Drives the customer cancellation email; abandoned/pending cancellations do not email.';


--
-- Name: commerce_emit_order_paid_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_order_paid_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status <> 'paid' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  -- Fulfillment event (unchanged).
  INSERT INTO public.outbox_events (
    aggregate_type,
    aggregate_id,
    event_type,
    idempotency_key,
    payload,
    metadata
  )
  VALUES (
    'commerce_order',
    NEW.id,
    'commerce.order.paid',
    'order_paid:' || NEW.id::text,
    jsonb_build_object(
      'orderId', 'order_' || NEW.id::text,
      'orderUuid', NEW.id,
      'mode', NEW.mode,
      'occurredAt', now()
    ),
    jsonb_build_object('source', 'commerce_emit_order_paid_outbox')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  -- Customer paid-confirmation email event (new). Same payload shape; the handler
  -- reads items + totals from commerce_orders / commerce_order_items at send time.
  INSERT INTO public.outbox_events (
    aggregate_type,
    aggregate_id,
    event_type,
    idempotency_key,
    payload,
    metadata
  )
  VALUES (
    'commerce_order',
    NEW.id,
    'commerce.order.paid.email',
    'order_paid_email:' || NEW.id::text,
    jsonb_build_object(
      'orderId', 'order_' || NEW.id::text,
      'orderUuid', NEW.id,
      'mode', NEW.mode,
      'occurredAt', now()
    ),
    jsonb_build_object('source', 'commerce_emit_order_paid_outbox')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_emit_order_paid_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_emit_order_paid_outbox() IS 'Emits commerce.order.paid (fulfillment) and commerce.order.paid.email (customer confirmation) outbox events when an order transitions to paid, each exactly-once via its own idempotency key.';


--
-- Name: commerce_emit_order_refunded_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_order_refunded_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_event_count integer := 0;
  v_currency_count integer := 0;
  v_has_missing_currency boolean := false;
  v_refund_cents bigint := 0;
  v_refund_currency text;
  v_provider_event_ids jsonb := '[]'::jsonb;
BEGIN
  IF NEW.status <> 'refunded' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  IF COALESCE(NEW.metadata->>'source', '') <> 'payment.control.v0' THEN
    RETURN NEW;
  END IF;

  SELECT
    count(*)::integer,
    count(DISTINCT e.currency)::integer,
    COALESCE(bool_or(e.currency IS NULL), false),
    COALESCE(sum(e.amount_cents), 0)::bigint,
    min(e.currency),
    COALESCE(jsonb_agg(e.provider_event_id ORDER BY e.received_at, e.created_at, e.id), '[]'::jsonb)
    INTO
      v_event_count,
      v_currency_count,
      v_has_missing_currency,
      v_refund_cents,
      v_refund_currency,
      v_provider_event_ids
    FROM public.inbound_provider_events e
    JOIN public.commerce_payment_intents pi ON pi.id = e.payment_intent_id
   WHERE pi.order_id = NEW.id
     AND e.event_type = 'payment.refunded'
     AND e.amount_cents IS NOT NULL;

  IF v_event_count = 0
     OR v_has_missing_currency
     OR v_currency_count <> 1
     OR v_refund_currency IS DISTINCT FROM NEW.currency
  THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.outbox_events (
    aggregate_type,
    aggregate_id,
    event_type,
    idempotency_key,
    payload,
    metadata
  )
  VALUES (
    'commerce_order',
    NEW.id,
    'commerce.order.refunded',
    'order_refunded:' || NEW.id::text,
    jsonb_build_object(
      'orderId', 'order_' || NEW.id::text,
      'orderUuid', NEW.id,
      'refundCents', v_refund_cents,
      'currency', v_refund_currency,
      'providerEventIds', v_provider_event_ids,
      'amountSource', 'inbound_provider_events.amount_cents_sum_same_currency',
      'occurredAt', now()
    ),
    jsonb_build_object('source', 'commerce_emit_order_refunded_outbox')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_emit_order_refunded_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_emit_order_refunded_outbox() IS 'Emits commerce.order.refunded only for provider-confirmed refunds with a same-currency provider event amount sum.';


--
-- Name: commerce_emit_payment_failed_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_payment_failed_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_token text;
  v_token_hash text;
  v_expires_at timestamptz := COALESCE(NEW.created_at, now()) + interval '30 days';
  v_token_inserted integer := 0;
BEGIN
  IF NEW.status <> 'expired' OR NEW.mode <> 'one_time' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  IF NEW.client_id IS NOT NULL THEN
    v_token := 'rcv_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
    v_token_hash := encode(sha256(convert_to(v_token, 'UTF8')), 'hex');

    WITH checkout_expired_inserted AS (
      INSERT INTO public.outbox_events (
        aggregate_type,
        aggregate_id,
        event_type,
        idempotency_key,
        payload,
        metadata
      )
      VALUES (
        'commerce_order',
        NEW.id,
        'commerce.checkout.expired',
        'checkout_expired:' || NEW.id::text,
        jsonb_build_object(
          'orderId', 'order_' || NEW.id::text,
          'orderUuid', NEW.id,
          'totalCents', NEW.total_cents,
          'currency', NEW.currency,
          'recoveryToken', v_token,
          'mode', NEW.mode,
          'expiresAt', v_expires_at,
          'occurredAt', now()
        ),
        jsonb_build_object(
          'source', 'commerce_emit_payment_failed_outbox',
          'truthRepair', 'checkout_expired',
          'recoveryToken', 'checkout_recovery_hash_only'
        )
      )
      ON CONFLICT (event_type, idempotency_key) DO NOTHING
      RETURNING aggregate_id
    ),
    checkout_recovery_token_inserted AS (
      INSERT INTO public.commerce_checkout_recovery_tokens (
        order_id,
        client_id,
        token_hash,
        expires_at,
        metadata
      )
      SELECT
        NEW.id,
        NEW.client_id,
        v_token_hash,
        v_expires_at,
        jsonb_build_object(
          'source', 'commerce_emit_payment_failed_outbox',
          'eventType', 'commerce.checkout.expired',
          'outboxIdempotencyKey', 'checkout_expired:' || NEW.id::text
        )
        FROM checkout_expired_inserted
      RETURNING 1
    )
    SELECT count(*)::integer INTO v_token_inserted
      FROM checkout_recovery_token_inserted;
  ELSE
    INSERT INTO public.outbox_events (
      aggregate_type,
      aggregate_id,
      event_type,
      idempotency_key,
      payload,
      metadata
    )
    VALUES (
      'commerce_order',
      NEW.id,
      'commerce.checkout.expired',
      'checkout_expired:' || NEW.id::text,
      jsonb_build_object(
        'orderId', 'order_' || NEW.id::text,
        'orderUuid', NEW.id,
        'totalCents', NEW.total_cents,
        'currency', NEW.currency,
        'occurredAt', now()
      ),
      jsonb_build_object('source', 'commerce_emit_payment_failed_outbox', 'truthRepair', 'checkout_expired')
    )
    ON CONFLICT (event_type, idempotency_key) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_emit_payment_failed_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_emit_payment_failed_outbox() IS 'Emits commerce.payment.failed when a one-time order transitions to failed OR expired (session timeout), exactly-once per order via payment_failed:<id>. Drives the customer payment-failed email.';


--
-- Name: commerce_emit_recoverable_payment_failed_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_recoverable_payment_failed_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_token text;
  v_token_hash text;
  v_expires_at timestamptz := now() + interval '24 hours';
  v_status text := NEW.metadata->>'paymentStatus';
  v_old_status text := COALESCE(OLD.metadata->>'paymentStatus', '');
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RETURN NEW;
  END IF;

  IF NEW.status <> 'pending_payment' THEN
    RETURN NEW;
  END IF;

  IF NEW.mode NOT IN ('one_time', 'subscription_cycle') THEN
    RETURN NEW;
  END IF;

  IF v_status <> 'declined' OR COALESCE((NEW.metadata->>'recoverable')::boolean, false) IS DISTINCT FROM true THEN
    RETURN NEW;
  END IF;

  IF v_old_status = 'declined' AND COALESCE((OLD.metadata->>'recoverable')::boolean, false) IS NOT DISTINCT FROM true THEN
    RETURN NEW;
  END IF;

  IF NEW.client_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_token := 'rcv_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  v_token_hash := encode(sha256(convert_to(v_token, 'UTF8')), 'hex');

  INSERT INTO public.commerce_checkout_recovery_tokens (
    order_id,
    client_id,
    token_hash,
    expires_at,
    metadata
  )
  VALUES (
    NEW.id,
    NEW.client_id,
    v_token_hash,
    v_expires_at,
    jsonb_build_object('source', 'commerce_emit_recoverable_payment_failed_outbox')
  )
  ON CONFLICT (token_hash) DO NOTHING;

  INSERT INTO public.outbox_events (
    aggregate_type,
    aggregate_id,
    event_type,
    idempotency_key,
    available_at,
    payload,
    metadata
  )
  VALUES (
    'commerce_order',
    NEW.id,
    'commerce.payment.failed',
    'payment_failed:' || NEW.id::text,
    -- The delay this migration exists for. See the header.
    now() + interval '3 minutes',
    jsonb_build_object(
      'orderId', 'order_' || NEW.id::text,
      'orderUuid', NEW.id,
      'totalCents', NEW.total_cents,
      'currency', NEW.currency,
      'recoveryToken', v_token,
      'mode', NEW.mode,
      'failureReason', COALESCE(NEW.metadata->>'failureReason', 'payment_declined'),
      'hasSubscriptionContext', NEW.subscription_id IS NOT NULL OR NEW.mode = 'subscription_cycle',
      'expiresAt', v_expires_at,
      'occurredAt', now()
    ),
    jsonb_build_object('source', 'commerce_emit_recoverable_payment_failed_outbox')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: commerce_emit_return_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_return_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- R1 emits only the statuses that have a runtime handler. Everything else returns
  -- without producing an outbox event (keeps the aggregate's claim ordering clean).
  IF NEW.status NOT IN ('approved', 'rejected') THEN
    RETURN NEW;
  END IF;

  -- On UPDATE, only when status actually changed.
  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.outbox_events (
    aggregate_type,
    aggregate_id,
    event_type,
    idempotency_key,
    payload,
    metadata
  )
  VALUES (
    'commerce_return',
    NEW.id,
    CASE NEW.status
      WHEN 'approved' THEN 'commerce.return.approved'
      WHEN 'rejected' THEN 'commerce.return.rejected'
    END,
    'return_' || NEW.status || ':' || NEW.id::text,
    jsonb_build_object(
      'returnRequestId', NEW.id,
      'orderUuid', NEW.order_id,
      'orderId', 'order_' || NEW.order_id::text,
      'status', NEW.status,
      'refundMode', NEW.refund_mode,
      'refundAmountCents', NEW.refund_amount_cents,
      'occurredAt', now()
    ),
    jsonb_build_object('source', 'commerce_emit_return_outbox')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_emit_return_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_emit_return_outbox() IS 'Commerce Returns R1: emits commerce.return.approved / commerce.return.rejected (explicit, claimable literals) on the approve/reject status transitions. Other lifecycle statuses are not emitted until their handlers land in R2+.';


--
-- Name: commerce_emit_shipment_dispatched_on_ref(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_shipment_dispatched_on_ref() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_fulfillment record;
BEGIN
  IF NEW.active IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  FOR v_fulfillment IN
    SELECT id
      FROM public.commerce_fulfillment_orders
     WHERE order_id = NEW.order_id
       AND status IN ('handed_over', 'in_transit')
     ORDER BY created_at ASC, id ASC
  LOOP
    PERFORM public.commerce_emit_shipment_dispatched_outbox(v_fulfillment.id);
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: commerce_emit_shipment_dispatched_outbox(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_shipment_dispatched_outbox(p_fulfillment_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_tracking text;
  v_tracking_refs jsonb;
BEGIN
  SELECT *
    INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id;

  IF NOT FOUND OR v_fulfillment.status NOT IN ('handed_over', 'in_transit') THEN
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.omnipack_status_evidence AS evidence
     WHERE evidence.fulfillment_order_id = p_fulfillment_order_id
       AND lower(btrim(coalesce(evidence.local_status, ''))) = 'delivered'
  ) THEN
    RETURN;
  END IF;

  -- The one clause this replacement adds. The event is keyed per parcel, so its
  -- contents must be the parcel's: without the last line an order carrying a
  -- replacement announces the OLDEST reference it holds, which is the tracking
  -- number of the parcel that was lost. The NULL arm keeps an unattributed
  -- reference visible to every parcel, which is what this read did for all of
  -- them before attribution existed; the only rows it now excludes are the ones
  -- a SIBLING parcel owns.
  SELECT
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'providerKind', ref.provider_kind,
          'carrierKind', ref.carrier_kind,
          'service', ref.service,
          'trackingNumber', ref.provider_tracking_id,
          'trackingUrl', ref.tracking_url
        )
        ORDER BY ref.created_at ASC, ref.id ASC
      ),
      '[]'::jsonb
    ),
    (array_agg(ref.provider_tracking_id ORDER BY ref.created_at ASC, ref.id ASC))[1]
    INTO v_tracking_refs, v_tracking
    FROM public.shipment_external_refs AS ref
   WHERE ref.order_id = v_fulfillment.order_id
     AND ref.active = true
     AND (ref.fulfillment_order_id IS NULL OR ref.fulfillment_order_id = v_fulfillment.id);

  IF jsonb_array_length(v_tracking_refs) = 0 THEN
    RETURN;
  END IF;

  INSERT INTO public.outbox_events (
    aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
  )
  VALUES (
    'commerce_order',
    v_fulfillment.order_id,
    'commerce.shipment.dispatched',
    'shipment_dispatched:' || v_fulfillment.id::text,
    jsonb_build_object(
      'orderId', 'order_' || v_fulfillment.order_id::text,
      'orderUuid', v_fulfillment.order_id,
      'trackingNumber', v_tracking,
      'trackingReferences', v_tracking_refs,
      'occurredAt', now()
    ),
    jsonb_build_object('source', 'commerce_emit_shipment_status_outbox')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;
END;
$$;


--
-- Name: FUNCTION commerce_emit_shipment_dispatched_outbox(p_fulfillment_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_emit_shipment_dispatched_outbox(p_fulfillment_order_id uuid) IS 'Idempotently emits commerce.shipment.dispatched for a handed_over/in_transit fulfillment, quoting the tracking references that parcel owns plus any still unattributed.';


--
-- Name: commerce_emit_shipment_exception_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_shipment_exception_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_source text := NEW.metadata->>'source';
BEGIN
  IF NEW.reason <> 'fulfillment_exception' OR NEW.status <> 'active' THEN
    RETURN NEW;
  END IF;

  -- On UPDATE only fire when the hold actually transitions INTO an active
  -- fulfillment_exception (no-op if it was already active+exception).
  IF TG_OP = 'UPDATE'
     AND OLD.status = 'active'
     AND OLD.reason = 'fulfillment_exception' THEN
    RETURN NEW;
  END IF;

  IF COALESCE(v_source, '') <> 'commerce.fulfillment.omnipack_provider_exception' THEN
    RETURN NEW;
  END IF;

  -- Handoff is durable customer truth. Keep the provider-exception hold for
  -- OMS/manual review, but do not emit a late future-tense customer message.
  -- The delivered fallback protects older rows that predate handed_over_at.
  IF EXISTS (
    SELECT 1
      FROM public.commerce_fulfillment_orders fulfillment
     WHERE fulfillment.order_id = NEW.order_id
       AND (
         fulfillment.handed_over_at IS NOT NULL
         OR fulfillment.status = 'delivered'
       )
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.outbox_events (
    aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
  )
  VALUES (
    'commerce_order',
    NEW.order_id,
    'commerce.shipment.exception',
    'shipment_exception:' || NEW.id::text,
    jsonb_build_object(
      'orderId', 'order_' || NEW.order_id::text,
      'orderUuid', NEW.order_id,
      'occurredAt', now(),
      'customerNotification', 'shipment_exception'
    ),
    jsonb_build_object(
      'source', 'commerce_emit_shipment_exception_outbox',
      'holdSource', v_source,
      'customerNotification', 'shipment_exception'
    )
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_emit_shipment_exception_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_emit_shipment_exception_outbox() IS 'Emits the live Omnipack shipment exception event before handoff; after durable handoff it preserves the OMS hold without sending a contradictory future-tense customer message.';


--
-- Name: commerce_emit_shipment_status_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_emit_shipment_status_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status NOT IN ('handed_over', 'in_transit', 'delivered') THEN
    RETURN NEW;
  END IF;

  IF NEW.status IN ('handed_over', 'in_transit') THEN
    PERFORM public.commerce_emit_shipment_dispatched_outbox(NEW.id);
  END IF;

  IF NEW.status = 'delivered' THEN
    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    VALUES (
      'commerce_order',
      NEW.order_id,
      'commerce.shipment.delivered',
      'shipment_delivered:' || NEW.id::text,
      jsonb_build_object(
        'orderId', 'order_' || NEW.order_id::text,
        'orderUuid', NEW.order_id,
        'occurredAt', now()
      ),
      jsonb_build_object('source', 'commerce_emit_shipment_status_outbox')
    )
    ON CONFLICT (event_type, idempotency_key) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_emit_shipment_status_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_emit_shipment_status_outbox() IS 'State-based shipment outbox emitter. Dispatched is delegated to commerce_emit_shipment_dispatched_outbox; delivered never emits the future-tense dispatched email.';


--
-- Name: commerce_finalize_order_for_checkout(text, uuid, text, uuid, uuid, uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_finalize_order_for_checkout(p_idempotency_key text, p_order_id uuid, p_mode text, p_client_id uuid, p_shipping_address_id uuid, p_pet_id uuid, p_quote_snapshot jsonb, p_order_draft_snapshot jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_scope constant text := 'commerce.checkout_order_finalize';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_completed_order public.commerce_orders%ROWTYPE;
  v_completed_order_id text;
  v_order public.commerce_orders%ROWTYPE;
  v_client public.clients%ROWTYPE;
  v_address public.addresses%ROWTYPE;
  v_pet public.pets%ROWTYPE;
  v_item public.commerce_order_items%ROWTYPE;
  v_sku public.catalog_skus%ROWTYPE;
  v_items jsonb := '[]'::jsonb;
  v_response jsonb;
  -- D10 mode-binding locals.
  v_context_mode text;
  v_expected_context_mode text;
  v_mode_discount_lines integer;
  -- Model B provisional-creation locals.
  v_provisional jsonb;
  v_subscription_id uuid := NULL;
  v_subscription_cycle_id uuid := NULL;
  v_invoice_buyer_snapshot jsonb;
  v_runtime_metadata jsonb;
  -- Neutral-seam discriminator, mirroring v_is_neutral in
  -- commerce_configurator_persist_intent. The neutral checkout command is the
  -- ONLY pet-less subscription producer; it stamps this marker into p_metadata
  -- (commerceCheckoutCommandExecution sets checkoutCommandVersion from the
  -- checkoutCommandV1 version literal), and finalize persists p_metadata under
  -- commerce_orders.metadata.runtimeFinalize, so an expired-checkout recovery of
  -- a neutral order still presents the marker. IS NOT DISTINCT FROM keeps this
  -- fail-closed: a missing/NULL metadata key yields false, never NULL.
  v_is_neutral boolean := (coalesce(p_metadata, '{}'::jsonb) ->> 'checkoutCommandVersion')
    IS NOT DISTINCT FROM 'commerce.checkout_command.v1';
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_order_id IS NULL
    OR p_mode NOT IN ('one_time', 'subscription_cycle')
    OR p_client_id IS NULL
    OR p_shipping_address_id IS NULL
    OR p_quote_snapshot IS NULL
    OR p_order_draft_snapshot IS NULL
  THEN
    RAISE EXCEPTION 'commerce_runtime_finalize_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- Restored invariant, dropped without a marker by 20260728120000. Legacy
  -- configurator subscriptions ALWAYS carry a pet, so a NULL pet on that path is
  -- never intentional: commerce_orders.pet_id is REFERENCES pets(id) ON DELETE
  -- SET NULL, so a customer deleting their pet nulls the column, and the
  -- expired-checkout recovery path then re-finalizes with petId NULL. Without
  -- this guard subscription_create_provisional_for_checkout (which has no pet
  -- check of its own, against a nullable subscriptions.pet_id) mints a pet-less
  -- pending_activation subscription instead of failing closed. Scoped to the
  -- legacy path so the neutral seam keeps its intended NULL pet.
  IF p_mode = 'subscription_cycle' AND p_pet_id IS NULL AND NOT v_is_neutral THEN
    RAISE EXCEPTION 'commerce_runtime_finalize_subscription_requires_pet' USING ERRCODE = '22023';
  END IF;

  -- D10.1: p_mode must match the quote snapshot's context.mode.
  v_expected_context_mode := CASE
    WHEN p_mode = 'subscription_cycle' THEN 'subscription'
    ELSE 'one_time'
  END;
  v_context_mode := p_quote_snapshot #>> '{quote,context,mode}';
  IF v_context_mode IS NULL OR v_context_mode IS DISTINCT FROM v_expected_context_mode THEN
    RAISE EXCEPTION
      'commerce_runtime_finalize_mode_binding_mismatch: p_mode=% context.mode=%',
      p_mode, coalesce(v_context_mode, 'null')
      USING ERRCODE = '22023';
  END IF;

  -- D10.2: a one-time finalize must not see any 'mode_discount' line.
  IF p_mode = 'one_time' THEN
    SELECT count(*)
      INTO v_mode_discount_lines
      FROM jsonb_array_elements(coalesce(p_quote_snapshot #> '{quote,lines}', '[]'::jsonb)) AS line,
           jsonb_array_elements(coalesce(line -> 'pricingComponents', '[]'::jsonb)) AS component
     WHERE component ->> 'componentType' = 'mode_discount';
    IF v_mode_discount_lines > 0 THEN
      RAISE EXCEPTION
        'commerce_runtime_finalize_line_mode_binding_mismatch: p_mode=one_time subscription_lines=%',
        v_mode_discount_lines
        USING ERRCODE = '22023';
    END IF;
  END IF;

  v_request_fingerprint := md5(
    p_order_id::text || '|' ||
    p_mode || '|' ||
    p_client_id::text || '|' ||
    p_shipping_address_id::text || '|' ||
    coalesce(p_pet_id::text, '') || '|' ||
    p_quote_snapshot::text || '|' ||
    p_order_draft_snapshot::text || '|' ||
    -- The ONE operand this migration changes. `deliveryContact` is excluded by
    -- name so a journey that gained it still replays; the object gate keeps
    -- `jsonb - text` off a scalar, which would raise 22023, and leaves every
    -- non-object shape hashing exactly as it does today.
    CASE
      WHEN jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) = 'object'
        THEN (coalesce(p_metadata, '{}'::jsonb) - 'deliveryContact')::text
      ELSE coalesce(p_metadata, '{}'::jsonb)::text
    END
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{finalizedOrder,replayed}', 'true'::jsonb, false);
    END IF;

    IF v_existing.status = 'completed' THEN
      -- Finalize writes this response shape atomically with the completed row.
      -- Metadata is a compatibility fallback for older completed records. Guard
      -- the cast so malformed JSON falls through to the safe generic conflict,
      -- while valid ids keep the primary-key lookup indexed.
      v_completed_order_id := coalesce(
        nullif(v_existing.response_payload #>> '{finalizedOrder,orderId}', ''),
        nullif(v_existing.metadata ->> 'orderId', '')
      );
      IF v_completed_order_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        SELECT original.*
          INTO v_completed_order
          FROM public.commerce_orders original
         WHERE original.id = v_completed_order_id::uuid
         FOR UPDATE;

        -- Explicit allowlist deliberately fails closed for a future order
        -- status. `pending_payment` is recoverable via its existing payment
        -- intent/recovery journey, so it must never authorize client key
        -- rotation and a second order.
        IF FOUND AND v_completed_order.status IN (
          'paid', 'failed', 'expired', 'fulfillment_pending', 'fulfilled',
          'cancelled', 'refunded'
        ) THEN
          RAISE EXCEPTION 'commerce_runtime_finalize_journey_consumed' USING ERRCODE = '23505';
        END IF;
      END IF;
    END IF;

    RAISE EXCEPTION 'commerce_runtime_finalize_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_runtime_finalize_order_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_order.status <> 'draft' THEN
    RAISE EXCEPTION 'commerce_runtime_finalize_order_not_draft' USING ERRCODE = '22023';
  END IF;
  IF v_order.metadata->'quoteSnapshot' IS DISTINCT FROM p_quote_snapshot
    OR v_order.metadata->'orderDraftSnapshot' IS DISTINCT FROM p_order_draft_snapshot
  THEN
    RAISE EXCEPTION 'commerce_runtime_finalize_snapshot_mismatch' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_client
    FROM public.clients
   WHERE id = p_client_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_runtime_finalize_client_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_address
    FROM public.addresses
   WHERE id = p_shipping_address_id
     AND client_id = p_client_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_runtime_finalize_shipping_address_not_owned' USING ERRCODE = '22023';
  END IF;

  IF p_pet_id IS NOT NULL THEN
    SELECT * INTO v_pet
      FROM public.pets
     WHERE id = p_pet_id
       AND client_id = p_client_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'commerce_runtime_finalize_pet_not_owned' USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'commerce_finalize_order_for_checkout')
  );

  FOR v_item IN
    SELECT *
      FROM public.commerce_order_items
     WHERE order_id = p_order_id
     ORDER BY created_at, id
     FOR UPDATE
  LOOP
    SELECT * INTO v_sku
      FROM public.catalog_skus
     WHERE sku = v_item.product_snapshot->>'sku'
       AND status <> 'archived'
     LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'commerce_runtime_finalize_unknown_sku: %', v_item.product_snapshot->>'sku'
        USING ERRCODE = '22023';
    END IF;

    UPDATE public.commerce_order_items
       SET sku_id = v_sku.id,
           mode_at_line = CASE WHEN p_mode = 'subscription_cycle' THEN 'subscription' ELSE 'one_time' END,
           variant_snapshot = jsonb_build_object(
             'skuId', v_sku.id,
             'sku', v_sku.sku,
             'title', v_sku.title,
             'petType', v_sku.pet_type,
             'netWeightG', v_sku.net_weight_g,
             'formatCode', v_sku.format_code,
             'unitFormCode', v_sku.unit_form_code,
             'kcalPerUnit', v_sku.kcal_per_unit,
             'source', 'commerce.runtime.hidden.v0'
           ),
           product_snapshot = product_snapshot || jsonb_build_object(
             'skuId', v_sku.id,
             'source', 'commerce.runtime.hidden.v0'
           )
     WHERE id = v_item.id;

    v_items := v_items || jsonb_build_object(
      'orderItemId', v_item.id,
      'skuId', v_sku.id,
      'sku', v_sku.sku,
      'quantity', v_item.quantity
    );
  END LOOP;

  IF jsonb_array_length(v_items) = 0 THEN
    RAISE EXCEPTION 'commerce_runtime_finalize_missing_order_items' USING ERRCODE = '22023';
  END IF;

  -- Model B: for a subscription_initial finalize, create the provisional
  -- subscription + cycle #1 against THIS draft order (the order items are now
  -- finalized with sku_id set) and link them in the order UPDATE below. The
  -- renewal cycle RPC must never run in the initial path; provisional creation
  -- happens here, exactly once, atomically inside finalize.
  IF p_mode = 'subscription_cycle' AND v_order.subscription_id IS NULL THEN
    v_provisional := public.subscription_create_provisional_for_checkout(
      p_order_id,
      p_client_id,
      p_pet_id,
      p_shipping_address_id,
      p_quote_snapshot
    );
    v_subscription_id := (v_provisional->>'subscriptionId')::uuid;
    v_subscription_cycle_id := (v_provisional->>'subscriptionCycleId')::uuid;
  END IF;

  v_invoice_buyer_snapshot := CASE
    WHEN jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)->'invoiceBuyerSnapshot') = 'object'
      THEN coalesce(p_metadata, '{}'::jsonb)->'invoiceBuyerSnapshot'
    ELSE NULL
  END;
  v_runtime_metadata := (coalesce(p_metadata, '{}'::jsonb) - 'invoiceBuyerSnapshot')
    || jsonb_build_object('source', 'commerce.runtime.hidden.v0');

  UPDATE public.commerce_orders
     SET client_id = p_client_id,
         shipping_address_id = p_shipping_address_id,
         pet_id = p_pet_id,
         mode = p_mode,
         subscription_id = COALESCE(v_subscription_id, subscription_id),
         subscription_cycle_id = COALESCE(v_subscription_cycle_id, subscription_cycle_id),
         metadata = metadata || jsonb_build_object(
           'clientId', p_client_id,
           'shippingAddressId', p_shipping_address_id,
           'petId', p_pet_id,
           'petSnapshot',
             CASE WHEN p_pet_id IS NULL THEN NULL ELSE jsonb_build_object(
               'id', v_pet.id,
               'clientId', v_pet.client_id,
               'petType', v_pet.pet_type,
               'name', v_pet.name,
               'breed', v_pet.breed,
               'ageLabel', v_pet.age_label,
               'weightKg', v_pet.weight_kg,
               'source', 'commerce.runtime.hidden.v0'
             ) END,
           'runtimeFinalize', v_runtime_metadata
         ) || CASE
           WHEN v_invoice_buyer_snapshot IS NULL THEN '{}'::jsonb
           ELSE jsonb_build_object('invoiceBuyerSnapshot', v_invoice_buyer_snapshot)
         END,
         updated_at = now()
   WHERE id = p_order_id
   RETURNING * INTO v_order;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'finalizedOrder', jsonb_build_object(
      'orderId', v_order.id,
      'orderRef', 'order_' || v_order.id::text,
      'mode', v_order.mode,
      'clientId', v_order.client_id,
      'petId', v_order.pet_id,
      'shippingAddressId', v_order.shipping_address_id,
      'subscriptionId', v_order.subscription_id,
      'subscriptionCycleId', v_order.subscription_cycle_id,
      'total', jsonb_build_object('amountMinor', v_order.total_cents, 'currency', v_order.currency),
      'items', v_items,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('orderId', v_order.id)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$_$;


--
-- Name: commerce_fulfillment_apply_command_write_outcome(uuid, uuid, bigint, bigint, text, text, text, timestamp with time zone, text, uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_apply_command_write_outcome(p_command_id uuid, p_claim_token uuid, p_claim_generation bigint, p_expected_version bigint, p_identity_fingerprint text, p_outcome_kind text, p_reason_code text, p_retry_not_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_provider_reference_fingerprint text DEFAULT NULL::text, p_provider_attempt_id uuid DEFAULT NULL::uuid, p_proof_kind text DEFAULT NULL::text, p_proof_fingerprint text DEFAULT NULL::text, p_proof_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_proof_source text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_command public.commerce_fulfillment_provider_commands%ROWTYPE; v_to text;
BEGIN
  v_command := private.commerce_fulfillment_provider_command_fence(p_command_id,p_claim_token,p_claim_generation,p_expected_version);
  IF v_command.status <> 'submitting' THEN RAISE EXCEPTION 'fulfillment_provider_command_not_submitting' USING ERRCODE='22023'; END IF;
  IF p_provider_attempt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.commerce_fulfillment_provider_attempts a WHERE a.id=p_provider_attempt_id AND a.fulfillment_order_id=v_command.fulfillment_order_id AND a.provider_kind=v_command.provider_kind) THEN RAISE EXCEPTION 'fulfillment_provider_command_attempt_mismatch' USING ERRCODE='22023'; END IF;
  IF p_identity_fingerprint !~ '^[a-f0-9]{64}$' OR (p_identity_fingerprint = v_command.command_key_fingerprint OR p_identity_fingerprint = v_command.correlation_fingerprint OR p_identity_fingerprint = v_command.provider_idempotency_key_fingerprint) IS NOT TRUE THEN RAISE EXCEPTION 'fulfillment_provider_command_outcome_identity_invalid' USING ERRCODE='22023'; END IF;
  IF p_outcome_kind='accepted' AND p_reason_code='provider_accepted' AND p_provider_reference_fingerprint ~ '^[a-f0-9]{64}$'
    AND p_proof_kind IS NULL AND p_proof_fingerprint IS NULL AND p_proof_observed_at IS NULL AND p_proof_source IS NULL THEN v_to:='accepted';
  ELSIF p_outcome_kind='uncertain' AND p_reason_code='write_uncertain'
    AND p_proof_kind IS NULL AND p_proof_fingerprint IS NULL AND p_proof_observed_at IS NULL AND p_proof_source IS NULL THEN v_to:='uncertain';
  ELSIF p_outcome_kind='rejected' AND p_reason_code IN ('terminal_rejection','safe_rejection')
    AND p_proof_kind='definitive_provider_rejection' AND p_proof_fingerprint ~ '^[a-f0-9]{64}$'
    AND p_proof_source='provider_response' AND p_proof_observed_at BETWEEN now()-interval '10 minutes' AND now()
  THEN
    IF p_reason_code='safe_rejection' AND v_command.attempt_count < v_command.retry_budget AND p_retry_not_before > now() THEN v_to:='retry_wait';
    ELSIF p_reason_code='safe_rejection' THEN v_to:='manual_review';
    ELSE v_to:='terminal_rejected'; END IF;
  ELSE RAISE EXCEPTION 'fulfillment_provider_command_outcome_invalid' USING ERRCODE='22023'; END IF;
  UPDATE public.commerce_fulfillment_provider_commands SET status=v_to,available_at=COALESCE(p_retry_not_before,available_at),provider_reference_fingerprint=CASE WHEN v_to='accepted' THEN p_provider_reference_fingerprint ELSE provider_reference_fingerprint END,last_provider_attempt_id=COALESCE(p_provider_attempt_id,last_provider_attempt_id),last_reason_code=p_reason_code,accepted_at=CASE WHEN v_to='accepted' THEN now() ELSE accepted_at END,finished_at=CASE WHEN v_to IN ('terminal_rejected','manual_review') THEN now() ELSE finished_at END,claim_token=CASE WHEN v_to='accepted' THEN claim_token ELSE NULL END,claim_owner_fingerprint=CASE WHEN v_to='accepted' THEN claim_owner_fingerprint ELSE NULL END,claim_expires_at=CASE WHEN v_to='accepted' THEN claim_expires_at ELSE NULL END,version=version+1,updated_at=now() WHERE id=p_command_id RETURNING * INTO v_command;
  INSERT INTO public.commerce_fulfillment_provider_command_transitions(command_id,from_status,to_status,reason_code,command_version,attempt_count,claim_token,claim_generation,provider_attempt_id,proof_kind,proof_fingerprint,proof_observed_at,proof_source) VALUES(v_command.id,'submitting',v_to,p_reason_code,v_command.version,v_command.attempt_count,p_claim_token,p_claim_generation,p_provider_attempt_id,p_proof_kind,p_proof_fingerprint,p_proof_observed_at,p_proof_source);
  RETURN private.commerce_fulfillment_provider_command_result(v_command);
END; $_$;


--
-- Name: commerce_fulfillment_cancel_order(text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_cancel_order(p_idempotency_key text, p_fulfillment_order_id uuid, p_reason text, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_existing_operation public.commerce_fulfillment_operations%ROWTYPE;
  v_reservation_id uuid;
  v_released_reservation_ids uuid[] := ARRAY[]::uuid[];
  v_active_dispatch public.omnipack_dispatch_refs%ROWTYPE;
  v_provider_cancelled boolean := false;
BEGIN
  SELECT * INTO v_existing_operation
    FROM public.commerce_fulfillment_operations
   WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing_operation.fulfillment_order_id IS DISTINCT FROM p_fulfillment_order_id
      OR v_existing_operation.payload->>'reason' IS DISTINCT FROM p_reason
    THEN
      RAISE EXCEPTION 'commerce_fulfillment_cancel_idempotency_conflict' USING ERRCODE = '23505';
    END IF;

    SELECT * INTO v_fulfillment
      FROM public.commerce_fulfillment_orders
     WHERE id = v_existing_operation.fulfillment_order_id;
    RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', v_existing_operation.fulfillment_order_id, 'orderId', v_existing_operation.order_id, 'status', v_fulfillment.status, 'replayed', true);
  END IF;

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_fulfillment.status = 'cancelled' THEN
    RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', p_fulfillment_order_id, 'orderId', v_fulfillment.order_id, 'status', 'cancelled', 'replayed', true);
  END IF;

  -- Use only the most recent evidence. An older CANCELLED must not override a
  -- later provider state that says the order resumed or progressed.
  SELECT lower(btrim(evidence.provider_status)) = 'cancelled'
    INTO v_provider_cancelled
    FROM public.omnipack_status_evidence AS evidence
   WHERE evidence.fulfillment_order_id = p_fulfillment_order_id
   ORDER BY evidence.occurred_at DESC NULLS LAST, evidence.created_at DESC, evidence.id DESC
   LIMIT 1;
  v_provider_cancelled := coalesce(v_provider_cancelled, false);

  IF v_fulfillment.status = 'exception' AND v_provider_cancelled THEN
    SELECT * INTO v_order
      FROM public.commerce_orders
     WHERE id = v_fulfillment.order_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'commerce_fulfillment_order_not_found' USING ERRCODE = '22023';
    END IF;

    IF v_order.mode <> 'one_time'
      OR v_order.status NOT IN ('paid', 'fulfillment_pending') THEN
      RAISE EXCEPTION 'commerce_fulfillment_provider_cancel_order_ineligible' USING ERRCODE = '22023';
    END IF;

    -- Order status is not payment proof. Mirror fulfillment creation and the
    -- OmniPack dispatch fence: only a durable succeeded payment intent makes
    -- this paid-order cancellation path eligible.
    IF NOT EXISTS (
      SELECT 1
        FROM public.commerce_payment_intents AS intent
       WHERE intent.order_id = v_order.id
         AND intent.status = 'succeeded'
    ) THEN
      RAISE EXCEPTION 'commerce_fulfillment_provider_cancel_payment_not_succeeded' USING ERRCODE = '22023';
    END IF;

    IF EXISTS (
      SELECT 1
        FROM public.commerce_order_holds AS hold
       WHERE hold.order_id = v_order.id
         AND hold.status = 'active'
    ) THEN
      RAISE EXCEPTION 'commerce_fulfillment_provider_cancel_active_hold' USING ERRCODE = '22023',
        HINT = 'Release all active OMS holds before confirming cancellation.';
    END IF;

    -- Transitioning the parent order owns release of every still-reserved
    -- reservation through trg_commerce_release_reservations_on_cancel. Do not
    -- independently release fulfillment-line reservations here.
    UPDATE public.commerce_orders
       SET status = 'cancelled',
           metadata = metadata || jsonb_build_object(
             'source', 'admin_oms_provider_cancel_confirmed',
             'suppressOrderCanceledEmail', true,
             'providerCancellation', jsonb_build_object(
               'provider', 'omnipack',
               'reason', p_reason,
               'actorUserId', p_actor_user_id,
               'confirmedAt', now()
             )
           ),
           updated_at = now()
     WHERE id = v_order.id;

    UPDATE public.commerce_fulfillment_orders
       SET status = 'cancelled',
           cancelled_at = now(),
           updated_at = now(),
           metadata = metadata || jsonb_build_object(
             'providerCancellationConfirmed', true,
             'provider', 'omnipack'
           )
     WHERE id = p_fulfillment_order_id;

    INSERT INTO public.commerce_order_operations (
      order_id, actor_user_id, operation_type, source, idempotency_key, payload
    ) VALUES (
      v_order.id, p_actor_user_id, 'order_cancelled_manual',
      'commerce.fulfillment.provider_cancel_confirmed', p_idempotency_key || ':order',
      jsonb_build_object(
        'reason', p_reason,
        'metadata', coalesce(p_metadata, '{}'::jsonb),
        'provider', 'omnipack',
        'providerStatus', 'CANCELLED',
        'source', 'admin_oms_provider_cancel_confirmed'
      )
    );

    INSERT INTO public.commerce_fulfillment_operations (
      fulfillment_order_id, order_id, operation_type, idempotency_key, actor_user_id, payload
    ) VALUES (
      p_fulfillment_order_id, v_order.id, 'cancelled', p_idempotency_key, p_actor_user_id,
      jsonb_build_object(
        'reason', p_reason,
        'metadata', coalesce(p_metadata, '{}'::jsonb),
        'providerCancellationConfirmed', true,
        'provider', 'omnipack',
        'releasedReservationIds', '[]'::jsonb,
        'releasedReservationCount', 0
      )
    );

    RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', p_fulfillment_order_id, 'orderId', v_order.id, 'status', 'cancelled', 'replayed', false);
  END IF;

  -- Provider truth first: a live dispatch reference means OmniPack holds this
  -- order and can still ship it. Refuse before touching any reservation.
  SELECT * INTO v_active_dispatch
    FROM public.omnipack_dispatch_refs
   WHERE fulfillment_order_id = p_fulfillment_order_id
     AND provider_kind = 'omnipack'
     AND status NOT IN ('failed', 'cancelled')
   LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_cancel_provider_dispatch_active'
      USING ERRCODE = '22023',
            DETAIL = format(
              'dispatch_ref=%s status=%s provider_order_id=%s',
              v_active_dispatch.id,
              v_active_dispatch.status,
              coalesce(v_active_dispatch.provider_order_id, 'none')
            ),
            HINT = 'Cancel the order in OmniPack first; the provider still holds it.';
  END IF;

  IF v_fulfillment.status NOT IN ('created', 'packed', 'label_pending') THEN
    RAISE EXCEPTION 'commerce_fulfillment_cancel_after_label_forbidden' USING ERRCODE = '22023';
  END IF;

  FOR v_reservation_id IN
    SELECT DISTINCT reservations.reservation_id
      FROM public.commerce_fulfillment_order_lines line
     CROSS JOIN LATERAL unnest(line.inventory_reservation_ids) AS reservations(reservation_id)
     WHERE line.fulfillment_order_id = p_fulfillment_order_id
  LOOP
    PERFORM public.inventory_release_reservation(
      p_idempotency_key || ':reservation:' || v_reservation_id::text,
      v_reservation_id,
      'fulfillment_cancelled',
      jsonb_build_object(
        'fulfillmentOrderId', p_fulfillment_order_id,
        'orderId', v_fulfillment.order_id,
        'reason', p_reason
      )
    );
    v_released_reservation_ids := array_append(v_released_reservation_ids, v_reservation_id);
  END LOOP;

  UPDATE public.commerce_fulfillment_orders
     SET status = 'cancelled',
         cancelled_at = now(),
         updated_at = now(),
         metadata = metadata || jsonb_build_object(
           'releasedReservationIds', to_jsonb(v_released_reservation_ids)
         )
   WHERE id = p_fulfillment_order_id;

  INSERT INTO public.commerce_fulfillment_operations (
    fulfillment_order_id, order_id, operation_type, idempotency_key, actor_user_id, payload
  )
  VALUES (
    p_fulfillment_order_id, v_fulfillment.order_id, 'cancelled',
    p_idempotency_key, p_actor_user_id,
    jsonb_build_object(
      'reason', p_reason,
      'metadata', coalesce(p_metadata, '{}'::jsonb),
      'releasedReservationIds', to_jsonb(v_released_reservation_ids),
      'releasedReservationCount', coalesce(array_length(v_released_reservation_ids, 1), 0)
    )
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', p_fulfillment_order_id, 'orderId', v_fulfillment.order_id, 'status', 'cancelled', 'replayed', false);
END;
$$;


--
-- Name: FUNCTION commerce_fulfillment_cancel_order(p_idempotency_key text, p_fulfillment_order_id uuid, p_reason text, p_actor_user_id uuid, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_fulfillment_cancel_order(p_idempotency_key text, p_fulfillment_order_id uuid, p_reason text, p_actor_user_id uuid, p_metadata jsonb) IS 'Cancels a local fulfillment order. For a one-time paid order in exception, the existing OMS cancel action may also cancel the parent only after the latest OmniPack evidence is CANCELLED and all OMS holds are released; no payment refund or cancellation email is performed.';


--
-- Name: commerce_fulfillment_claim_provider_commands(text, text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_claim_provider_commands(p_provider_kind text, p_command_kind text, p_limit integer, p_claim_owner text, p_lease_seconds integer) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_command public.commerce_fulfillment_provider_commands%ROWTYPE; v_token uuid; v_now timestamptz := now(); v_from text;
BEGIN
  IF p_provider_kind !~ '^[a-z][a-z0-9_-]{0,63}$' OR p_command_kind <> 'dispatch_create'
    OR p_claim_owner !~ '^[a-f0-9]{64}$' OR p_limit NOT BETWEEN 1 AND 100 OR p_lease_seconds NOT BETWEEN 10 AND 900
  THEN RAISE EXCEPTION 'fulfillment_provider_command_claim_invalid_input' USING ERRCODE = '22023'; END IF;
  FOR v_command IN SELECT * FROM public.commerce_fulfillment_provider_commands
    WHERE provider_kind = p_provider_kind AND command_kind = p_command_kind
      AND status IN ('queued', 'retry_wait') AND available_at <= v_now
      AND attempt_count < retry_budget
    ORDER BY available_at, created_at FOR UPDATE SKIP LOCKED LIMIT p_limit
  LOOP
    v_token := gen_random_uuid();
    v_from := v_command.status;
    UPDATE public.commerce_fulfillment_provider_commands SET status='claimed',
      claim_token=v_token, claim_owner_fingerprint=p_claim_owner,
      claim_expires_at=v_now + make_interval(secs => p_lease_seconds), claim_generation=claim_generation+1,
      last_reason_code='claimed', version=version+1, updated_at=v_now WHERE id=v_command.id RETURNING * INTO v_command;
    INSERT INTO public.commerce_fulfillment_provider_command_transitions(command_id, from_status, to_status, reason_code, command_version, attempt_count, claim_token, claim_generation)
      VALUES(v_command.id, v_from, 'claimed', 'claimed', v_command.version, v_command.attempt_count, v_command.claim_token, v_command.claim_generation);
    RETURN NEXT jsonb_build_object('commandId',v_command.id,'fulfillmentOrderId',v_command.fulfillment_order_id,'orderId',v_command.order_id,
      'providerKind',v_command.provider_kind,'commandKind',v_command.command_kind,'contractVersion',v_command.contract_version,'status',v_command.status,'version',v_command.version,
      'commandKeyFingerprint',v_command.command_key_fingerprint,'commandPayloadFingerprint',v_command.command_payload_fingerprint,
      'providerIdempotencyKeyFingerprint',v_command.provider_idempotency_key_fingerprint,'routingFingerprint',v_command.routing_fingerprint,
      'configurationFingerprint',v_command.config_fingerprint,'correlationKeyFingerprint',v_command.correlation_fingerprint,
      'retryBudget',v_command.retry_budget,'retryCount',v_command.attempt_count,'claimToken',v_command.claim_token,
      'claimGeneration',v_command.claim_generation,'leaseExpiresAt',v_command.claim_expires_at);
  END LOOP;
END;
$_$;


--
-- Name: commerce_fulfillment_confirm_provider_command(uuid, uuid, bigint, bigint, text, uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_confirm_provider_command(p_command_id uuid, p_claim_token uuid, p_claim_generation bigint, p_expected_version bigint, p_identity_fingerprint text, p_provider_attempt_id uuid DEFAULT NULL::uuid, p_proof_kind text DEFAULT NULL::text, p_proof_fingerprint text DEFAULT NULL::text, p_proof_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_proof_source text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_command public.commerce_fulfillment_provider_commands%ROWTYPE;
BEGIN
  v_command := private.commerce_fulfillment_provider_command_fence(p_command_id,p_claim_token,p_claim_generation,p_expected_version);
  IF v_command.status <> 'accepted' OR v_command.provider_reference_fingerprint IS NULL THEN RAISE EXCEPTION 'fulfillment_provider_command_confirmation_invalid' USING ERRCODE='22023'; END IF;
  IF p_provider_attempt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.commerce_fulfillment_provider_attempts a WHERE a.id=p_provider_attempt_id AND a.fulfillment_order_id=v_command.fulfillment_order_id AND a.provider_kind=v_command.provider_kind) THEN RAISE EXCEPTION 'fulfillment_provider_command_attempt_mismatch' USING ERRCODE='22023'; END IF;
  IF p_identity_fingerprint !~ '^[a-f0-9]{64}$' OR p_proof_kind NOT IN ('provider_reference','correlation_key','provider_idempotency_key') OR p_proof_fingerprint !~ '^[a-f0-9]{64}$' OR p_proof_source NOT IN ('provider_lookup','provider_webhook','operator_verified') OR p_proof_observed_at > now() OR p_proof_observed_at < now()-interval '24 hours'
    OR (p_identity_fingerprint = v_command.correlation_fingerprint OR p_identity_fingerprint = v_command.provider_idempotency_key_fingerprint) IS NOT TRUE
    OR (p_proof_kind='correlation_key' AND p_identity_fingerprint IS DISTINCT FROM v_command.correlation_fingerprint)
    OR (p_proof_kind='provider_idempotency_key' AND p_identity_fingerprint IS DISTINCT FROM v_command.provider_idempotency_key_fingerprint)
  THEN RAISE EXCEPTION 'fulfillment_provider_command_confirmation_proof_invalid' USING ERRCODE='22023'; END IF;
  UPDATE public.commerce_fulfillment_provider_commands SET status='confirmed',last_provider_attempt_id=COALESCE(p_provider_attempt_id,last_provider_attempt_id),confirmed_at=now(),finished_at=now(),last_reason_code='provider_effect_present',claim_token=NULL,claim_owner_fingerprint=NULL,claim_expires_at=NULL,version=version+1,updated_at=now() WHERE id=p_command_id RETURNING * INTO v_command;
  INSERT INTO public.commerce_fulfillment_provider_command_transitions(command_id,from_status,to_status,reason_code,command_version,attempt_count,claim_token,claim_generation,provider_attempt_id,proof_kind,proof_fingerprint,proof_observed_at,proof_source) VALUES(v_command.id,'accepted','confirmed','provider_effect_present',v_command.version,v_command.attempt_count,p_claim_token,p_claim_generation,p_provider_attempt_id,p_proof_kind,p_proof_fingerprint,p_proof_observed_at,p_proof_source);
  RETURN private.commerce_fulfillment_provider_command_result(v_command);
END; $_$;


--
-- Name: commerce_fulfillment_create_order(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_create_order(p_idempotency_key text, p_order_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_address public.addresses%ROWTYPE;
  v_client public.clients%ROWTYPE;
  v_existing public.commerce_fulfillment_orders%ROWTYPE;
  v_payment_intent_id uuid;
  v_subscription_status text;
  v_fulfillment_id uuid;
  v_delivery_contact jsonb;
  v_contact_resolution jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8 OR p_order_id IS NULL THEN
    RAISE EXCEPTION 'commerce_fulfillment_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing
    FROM public.commerce_fulfillment_orders
   WHERE create_idempotency_key = p_idempotency_key
      OR order_id = p_order_id
   LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.fulfillment.v0',
      'fulfillmentOrderId', v_existing.id,
      'orderId', v_existing.order_id,
      'status', v_existing.status,
      'replayed', true
    );
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_order_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_order.status NOT IN ('paid', 'fulfillment_pending') THEN
    RAISE EXCEPTION 'commerce_fulfillment_order_not_fulfillable' USING ERRCODE = '22023';
  END IF;
  IF v_order.client_id IS NULL THEN
    RAISE EXCEPTION 'commerce_fulfillment_missing_client' USING ERRCODE = '22023';
  END IF;
  IF v_order.shipping_address_id IS NULL THEN
    RAISE EXCEPTION 'commerce_fulfillment_missing_shipping_address' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_address
    FROM public.addresses
   WHERE id = v_order.shipping_address_id
     AND client_id = v_order.client_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_shipping_address_not_found' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_client FROM public.clients WHERE id = v_order.client_id;

  IF NOT (coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride')
    AND NOT (coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact')
    AND coalesce(v_order.metadata, '{}'::jsonb) ? 'channelOrderSnapshot'
    AND jsonb_typeof(v_order.metadata->'channelOrderSnapshot') IS DISTINCT FROM 'object'
  THEN
    RAISE EXCEPTION 'commerce_fulfillment_delivery_contact_invalid' USING ERRCODE = '22023';
  END IF;

  -- Canonical input, channel input, and the historical snapshot all converge
  -- here.  The caller retains validation and the paid-order materialization
  -- fence below; the resolver only reports facts.
  v_contact_resolution := private.commerce_delivery_contact_resolve_v1(jsonb_build_object(
    'frozenContactPresent',
      coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride'
      OR coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact',
    'frozenContact', CASE
      WHEN coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride'
        THEN v_order.metadata->'deliveryContactOverride'
      WHEN coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact'
        THEN v_order.metadata #> '{runtimeFinalize,deliveryContact}'
      ELSE NULL
    END,
    'orderCanonicalPresent', false,
    'channelOrderSnapshot', v_order.metadata->'channelOrderSnapshot',
    'selectedDeliveryCandidates', jsonb_build_array(
      v_order.metadata->'selectedDelivery',
      v_order.metadata #> '{runtimeFinalize,selectedDelivery}',
      v_address.metadata->'selectedDelivery'
    ),
    'recipientCandidates', jsonb_build_array(
      v_address.recipient_name,
      concat_ws(' ', v_client.first_name, v_client.last_name),
      v_address.label
    ),
    'phoneCandidates', jsonb_build_array(v_address.contact_phone, v_client.phone),
    'legacyClientEmail', v_client.email,
    'line1', v_address.line1,
    'line2', v_address.line2,
    'city', v_address.city,
    'postalCode', v_address.postal_code,
    'country', v_address.country,
    'deliveryInstructions', v_address.delivery_notes,
    'courierInstructions', v_address.courier_instructions
  ));
  v_delivery_contact := v_contact_resolution->'contact';

  -- STRUCTURE and DESTINATION are refused here. CARRIER COMPLETENESS is not.
  -- A paid order must be able to materialize its parcel, and a subscription
  -- renewal inherits only `shipping_address_id`, so it always lands in the
  -- legacy branch above and had to satisfy a full contact out of a profile row
  -- whose `phone`, `first_name` and `last_name` are all nullable. A renewal that
  -- cannot create a fulfilment row has been charged for a delivery that can never
  -- exist -- and because no parcel exists, no delivery is late, so the alignment
  -- rail never shifts the cycle either. A missing recipient or phone is a carrier
  -- problem: `omnipack_dispatch_candidate_ids` withholds such a parcel from the
  -- dispatch rail, OMS still ranks it and still offers the correction that repairs
  -- it, and it re-enters dispatch on its own once corrected.
  IF v_delivery_contact->>'schemaVersion' IS DISTINCT FROM '1'
    OR coalesce(v_delivery_contact->>'revision', '') !~ '^[1-9][0-9]*$'
    OR nullif(btrim(v_delivery_contact->>'source'), '') IS NULL
    OR nullif(btrim(v_delivery_contact->>'line1'), '') IS NULL
    OR nullif(btrim(v_delivery_contact->>'city'), '') IS NULL
    OR nullif(btrim(v_delivery_contact->>'postalCode'), '') IS NULL
    OR nullif(btrim(v_delivery_contact->>'country'), '') IS NULL
  THEN
    RAISE EXCEPTION 'commerce_fulfillment_delivery_contact_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_payment_intent_id
    FROM public.commerce_payment_intents
   WHERE order_id = p_order_id AND status = 'succeeded'
   LIMIT 1;
  IF v_payment_intent_id IS NULL THEN
    RAISE EXCEPTION 'commerce_fulfillment_payment_not_succeeded' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.commerce_order_holds WHERE order_id = p_order_id AND status = 'active') THEN
    RAISE EXCEPTION 'commerce_fulfillment_active_hold' USING ERRCODE = '22023';
  END IF;
  IF v_order.mode = 'subscription_cycle' THEN
    SELECT status INTO v_subscription_status FROM public.subscription_cycles WHERE id = v_order.subscription_cycle_id;
    IF v_subscription_status IS DISTINCT FROM 'paid' THEN
      RAISE EXCEPTION 'commerce_fulfillment_subscription_cycle_not_paid' USING ERRCODE = '22023';
    END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.commerce_order_items WHERE order_id = p_order_id) THEN
    RAISE EXCEPTION 'commerce_fulfillment_missing_order_items' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.commerce_order_items oi
    LEFT JOIN public.catalog_skus cs ON cs.id = oi.sku_id
    WHERE oi.order_id = p_order_id AND (oi.sku_id IS NULL OR cs.id IS NULL)
  ) THEN
    RAISE EXCEPTION 'commerce_fulfillment_missing_catalog_sku' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.commerce_order_items oi
    LEFT JOIN (
      SELECT order_item_id, sum(quantity) AS reserved_quantity
      FROM public.inventory_reservations
      WHERE order_id = p_order_id AND status = 'reserved'
      GROUP BY order_item_id
    ) reservations ON reservations.order_item_id = oi.id
    WHERE oi.order_id = p_order_id
      AND coalesce(reservations.reserved_quantity, 0) < oi.quantity
  ) THEN
    RAISE EXCEPTION 'commerce_fulfillment_missing_inventory_reservation' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_fulfillment_orders (
    order_id, client_id, shipping_address_id, create_idempotency_key,
    shipping_address_snapshot, metadata
  ) VALUES (
    p_order_id, v_order.client_id, v_order.shipping_address_id, p_idempotency_key,
    jsonb_build_object(
      'addressId', v_address.id,
      'clientId', v_address.client_id,
      'label', v_address.label,
      'line1', v_delivery_contact->>'line1',
      'line2', v_delivery_contact->>'line2',
      'city', v_delivery_contact->>'city',
      'postalCode', v_delivery_contact->>'postalCode',
      'country', v_delivery_contact->>'country',
      'recipientName', v_delivery_contact->>'recipientName',
      'deliveryContact', v_delivery_contact,
      'selectedDelivery', v_delivery_contact->'selectedDelivery'
    ),
    coalesce(p_metadata, '{}'::jsonb)
  ) RETURNING id INTO v_fulfillment_id;

  INSERT INTO public.commerce_fulfillment_order_lines (
    fulfillment_order_id, order_id, order_item_id, sku_id, sku, title, quantity,
    inventory_reservation_ids, product_snapshot
  )
  SELECT v_fulfillment_id, p_order_id, oi.id, oi.sku_id, cs.sku, cs.title, oi.quantity,
    ARRAY(
      SELECT ir.id FROM public.inventory_reservations ir
      WHERE ir.order_item_id = oi.id AND ir.status = 'reserved'
      ORDER BY ir.created_at
    ),
    oi.product_snapshot
  FROM public.commerce_order_items oi
  JOIN public.catalog_skus cs ON cs.id = oi.sku_id
  WHERE oi.order_id = p_order_id;

  INSERT INTO public.commerce_fulfillment_operations (
    fulfillment_order_id, order_id, operation_type, idempotency_key, actor_user_id, payload
  ) VALUES (
    v_fulfillment_id, p_order_id, 'created', p_idempotency_key || ':created',
    p_actor_user_id, jsonb_build_object('source', 'commerce_fulfillment_create_order')
  );

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.fulfillment.v0',
    'fulfillmentOrderId', v_fulfillment_id,
    'orderId', p_order_id,
    'status', 'created',
    'replayed', false
  );
END;
$_$;


--
-- Name: commerce_fulfillment_enqueue_provider_command(uuid, text, text, text, text, text, text, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_enqueue_provider_command(p_fulfillment_order_id uuid, p_provider_kind text, p_command_kind text, p_contract_version text, p_idempotency_key text, p_command_key_fingerprint text, p_command_payload_fingerprint text, p_provider_idempotency_key_fingerprint text, p_routing_fingerprint text, p_config_fingerprint text, p_correlation_fingerprint text, p_retry_budget integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_command public.commerce_fulfillment_provider_commands%ROWTYPE; v_order_id uuid; v_idempotency_key_fingerprint text;
BEGIN
  IF p_fulfillment_order_id IS NULL OR p_provider_kind !~ '^[a-z][a-z0-9_-]{0,63}$'
    OR p_command_kind <> 'dispatch_create' OR p_contract_version <> '1'
    OR p_idempotency_key !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
    OR p_command_key_fingerprint !~ '^[a-f0-9]{64}$'
    OR p_command_payload_fingerprint !~ '^[a-f0-9]{64}$'
    OR p_routing_fingerprint !~ '^[a-f0-9]{64}$' OR p_config_fingerprint !~ '^[a-f0-9]{64}$'
    OR p_correlation_fingerprint IS NULL OR p_correlation_fingerprint !~ '^[a-f0-9]{64}$'
    OR (p_provider_idempotency_key_fingerprint IS NOT NULL AND p_provider_idempotency_key_fingerprint !~ '^[a-f0-9]{64}$')
    OR p_retry_budget NOT BETWEEN 0 AND 20
  THEN RAISE EXCEPTION 'fulfillment_provider_command_enqueue_invalid_input' USING ERRCODE = '22023'; END IF;
  v_idempotency_key_fingerprint := encode(sha256(convert_to('provider-command-idempotency|' || p_idempotency_key, 'UTF8')), 'hex');
  SELECT * INTO v_command FROM public.commerce_fulfillment_provider_commands WHERE idempotency_key_fingerprint = v_idempotency_key_fingerprint FOR UPDATE;
  IF FOUND THEN
    IF v_command.fulfillment_order_id <> p_fulfillment_order_id OR v_command.provider_kind <> p_provider_kind
      OR v_command.command_kind <> p_command_kind OR v_command.command_key_fingerprint <> p_command_key_fingerprint
      OR v_command.command_payload_fingerprint <> p_command_payload_fingerprint OR v_command.routing_fingerprint <> p_routing_fingerprint
      OR v_command.config_fingerprint <> p_config_fingerprint OR v_command.correlation_fingerprint <> p_correlation_fingerprint
      OR v_command.provider_idempotency_key_fingerprint IS DISTINCT FROM p_provider_idempotency_key_fingerprint
    THEN RAISE EXCEPTION 'fulfillment_provider_command_enqueue_identity_conflict' USING ERRCODE = '23505'; END IF;
    RETURN private.commerce_fulfillment_provider_command_result(v_command);
  END IF;
  SELECT order_id INTO v_order_id FROM public.commerce_fulfillment_orders WHERE id = p_fulfillment_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'fulfillment_provider_command_fulfillment_not_found' USING ERRCODE = '22023'; END IF;
  INSERT INTO public.commerce_fulfillment_provider_commands (
    fulfillment_order_id, order_id, provider_kind, command_kind, contract_version,
    idempotency_key_fingerprint, command_key_fingerprint, command_payload_fingerprint,
    provider_idempotency_key_fingerprint, routing_fingerprint, config_fingerprint,
    correlation_fingerprint, retry_budget
  ) VALUES (p_fulfillment_order_id, v_order_id, p_provider_kind, p_command_kind, p_contract_version,
    v_idempotency_key_fingerprint, p_command_key_fingerprint, p_command_payload_fingerprint,
    p_provider_idempotency_key_fingerprint, p_routing_fingerprint, p_config_fingerprint,
    p_correlation_fingerprint, p_retry_budget) RETURNING * INTO v_command;
  INSERT INTO public.commerce_fulfillment_provider_command_transitions(command_id, from_status, to_status, reason_code, command_version, attempt_count)
    VALUES (v_command.id, NULL, 'queued', 'command_enqueued', v_command.version, v_command.attempt_count);
  RETURN private.commerce_fulfillment_provider_command_result(v_command);
END;
$_$;


--
-- Name: commerce_fulfillment_mark_claimed_command_manual_review(uuid, uuid, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_mark_claimed_command_manual_review(p_command_id uuid, p_claim_token uuid, p_claim_generation bigint, p_expected_version bigint, p_reason_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_command jsonb;
BEGIN
  SELECT to_jsonb(private.commerce_fulfillment_provider_command_fence(
    p_command_id, p_claim_token, p_claim_generation, p_expected_version
  )) INTO v_command;
  IF v_command->>'status' <> 'claimed'
    OR p_reason_code NOT IN ('invalid_contract', 'identity_mismatch')
  THEN
    RAISE EXCEPTION 'fulfillment_provider_command_claimed_manual_review_invalid'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.commerce_fulfillment_provider_commands AS c
     SET status = 'manual_review',
         last_reason_code = p_reason_code,
         claim_token = NULL,
         claim_owner_fingerprint = NULL,
         claim_expires_at = NULL,
         finished_at = now(),
         version = version + 1,
         updated_at = now()
   WHERE id = p_command_id
   RETURNING to_jsonb(c.*) INTO v_command;

  INSERT INTO public.commerce_fulfillment_provider_command_transitions(
    command_id, from_status, to_status, reason_code, command_version,
    attempt_count, claim_token, claim_generation
  ) VALUES (
    (v_command->>'id')::uuid, 'claimed', 'manual_review', p_reason_code,
    (v_command->>'version')::bigint, (v_command->>'attempt_count')::integer,
    p_claim_token, p_claim_generation
  );
  RETURN jsonb_build_object(
    'commandId', (v_command->>'id')::uuid,
    'status', v_command->>'status',
    'version', (v_command->>'version')::bigint,
    'applied', true
  );
END;
$$;


--
-- Name: commerce_fulfillment_mark_command_submitting(uuid, uuid, bigint, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_mark_command_submitting(p_command_id uuid, p_claim_token uuid, p_claim_generation bigint, p_expected_version bigint, p_provider_attempt_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_command public.commerce_fulfillment_provider_commands%ROWTYPE;
BEGIN
  v_command := private.commerce_fulfillment_provider_command_fence(p_command_id,p_claim_token,p_claim_generation,p_expected_version);
  IF v_command.status <> 'claimed' THEN RAISE EXCEPTION 'fulfillment_provider_command_not_claimed' USING ERRCODE='22023'; END IF;
  IF p_provider_attempt_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.commerce_fulfillment_provider_attempts a WHERE a.id=p_provider_attempt_id AND a.fulfillment_order_id=v_command.fulfillment_order_id AND a.provider_kind=v_command.provider_kind) THEN RAISE EXCEPTION 'fulfillment_provider_command_attempt_mismatch' USING ERRCODE='22023'; END IF;
  UPDATE public.commerce_fulfillment_provider_commands SET status='submitting',attempt_count=attempt_count+1,last_provider_attempt_id=p_provider_attempt_id,last_reason_code='submission_started',version=version+1,updated_at=now() WHERE id=p_command_id RETURNING * INTO v_command;
  INSERT INTO public.commerce_fulfillment_provider_command_transitions(command_id,from_status,to_status,reason_code,command_version,attempt_count,claim_token,claim_generation,provider_attempt_id) VALUES(v_command.id,'claimed','submitting','submission_started',v_command.version,v_command.attempt_count,p_claim_token,p_claim_generation,p_provider_attempt_id);
  RETURN private.commerce_fulfillment_provider_command_result(v_command);
END; $$;


--
-- Name: commerce_fulfillment_mark_handed_over(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_mark_handed_over(p_idempotency_key text, p_fulfillment_order_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_reservation_id uuid;
BEGIN
  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_fulfillment.status IN ('handed_over', 'in_transit', 'delivered') THEN
    RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', p_fulfillment_order_id, 'orderId', v_fulfillment.order_id, 'status', v_fulfillment.status, 'replayed', true);
  END IF;
  IF v_fulfillment.status NOT IN ('label_created', 'packed') THEN
    RAISE EXCEPTION 'commerce_fulfillment_handoff_requires_label' USING ERRCODE = '22023';
  END IF;

  FOR v_reservation_id IN
    SELECT DISTINCT unnest(inventory_reservation_ids)
      FROM public.commerce_fulfillment_order_lines
     WHERE fulfillment_order_id = p_fulfillment_order_id
  LOOP
    PERFORM public.inventory_consume_reservation_for_fulfillment(
      p_idempotency_key || ':' || v_reservation_id::text,
      v_reservation_id,
      jsonb_build_object('fulfillmentOrderId', p_fulfillment_order_id)
    );
  END LOOP;

  UPDATE public.commerce_fulfillment_orders
     SET status = 'handed_over',
         handed_over_at = now(),
         updated_at = now()
   WHERE id = p_fulfillment_order_id;

  INSERT INTO public.commerce_fulfillment_operations (
    fulfillment_order_id, order_id, operation_type, idempotency_key, actor_user_id, payload
  )
  VALUES (
    p_fulfillment_order_id, v_fulfillment.order_id, 'handed_over',
    p_idempotency_key || ':operation', p_actor_user_id, coalesce(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', p_fulfillment_order_id, 'orderId', v_fulfillment.order_id, 'status', 'handed_over', 'replayed', false);
END;
$$;


--
-- Name: commerce_fulfillment_mark_provider_stock_consumed(text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_mark_provider_stock_consumed(p_idempotency_key text, p_fulfillment_order_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_existing_operation uuid;
  v_reservation_id uuid;
  v_consumed_count integer := 0;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8 OR p_fulfillment_order_id IS NULL THEN
    RAISE EXCEPTION 'commerce_fulfillment_provider_stock_consumed_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_fulfillment.status IN ('handed_over', 'in_transit', 'delivered') THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.fulfillment.v0',
      'fulfillmentOrderId', p_fulfillment_order_id,
      'orderId', v_fulfillment.order_id,
      'status', v_fulfillment.status,
      'consumedCount', 0,
      'replayed', true
    );
  END IF;
  IF v_fulfillment.status NOT IN ('label_created', 'packed') THEN
    RAISE EXCEPTION 'commerce_fulfillment_provider_stock_consumed_requires_label' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_existing_operation
    FROM public.commerce_fulfillment_operations
   WHERE idempotency_key = p_idempotency_key || ':operation'
   LIMIT 1;
  IF v_existing_operation IS NOT NULL THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.fulfillment.v0',
      'fulfillmentOrderId', p_fulfillment_order_id,
      'orderId', v_fulfillment.order_id,
      'status', v_fulfillment.status,
      'consumedCount', 0,
      'replayed', true
    );
  END IF;

  FOR v_reservation_id IN
    SELECT DISTINCT unnest(inventory_reservation_ids)
      FROM public.commerce_fulfillment_order_lines
     WHERE fulfillment_order_id = p_fulfillment_order_id
  LOOP
    PERFORM public.inventory_consume_reservation_for_fulfillment(
      p_idempotency_key || ':' || v_reservation_id::text,
      v_reservation_id,
      jsonb_build_object('fulfillmentOrderId', p_fulfillment_order_id, 'source', 'provider_stock_consumed')
    );
    v_consumed_count := v_consumed_count + 1;
  END LOOP;

  UPDATE public.commerce_fulfillment_orders
     SET status = 'packed',
         updated_at = now(),
         metadata = metadata || jsonb_build_object('providerStockConsumedAt', now())
   WHERE id = p_fulfillment_order_id
     AND status <> 'packed';

  INSERT INTO public.commerce_fulfillment_operations (
    fulfillment_order_id, order_id, operation_type, idempotency_key, actor_user_id, payload
  )
  VALUES (
    p_fulfillment_order_id,
    v_fulfillment.order_id,
    'packed',
    p_idempotency_key || ':operation',
    p_actor_user_id,
    coalesce(p_metadata, '{}'::jsonb)
      || jsonb_build_object('source', 'provider_stock_consumed', 'consumedCount', v_consumed_count)
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.fulfillment.v0',
    'fulfillmentOrderId', p_fulfillment_order_id,
    'orderId', v_fulfillment.order_id,
    'status', 'packed',
    'consumedCount', v_consumed_count,
    'replayed', false
  );
END;
$$;


--
-- Name: commerce_fulfillment_order_reservation_location_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_order_reservation_location_count(p_order_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT count(DISTINCT ir.location_id)::integer
    FROM public.inventory_reservations ir
   WHERE ir.order_id = p_order_id
     AND ir.status = 'reserved';
$$;


--
-- Name: FUNCTION commerce_fulfillment_order_reservation_location_count(p_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_fulfillment_order_reservation_location_count(p_order_id uuid) IS 'Distinct inventory locations across an order''s reserved reservations. >1 means split shipment is required (unsupported in v1).';


--
-- Name: commerce_fulfillment_preflight_split_shipment(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_preflight_split_shipment(p_idempotency_key text, p_order_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_location_count integer;
  v_hold public.commerce_order_holds%ROWTYPE;
  v_replayed boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8 OR p_order_id IS NULL THEN
    RAISE EXCEPTION 'commerce_fulfillment_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_location_count := public.commerce_fulfillment_order_reservation_location_count(p_order_id);

  -- Single (or zero) location: fulfillable by the normal pipeline. Zero is left
  -- to the create RPC's missing-reservation guard, so we don't flag it here.
  IF COALESCE(v_location_count, 0) <= 1 THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.fulfillment.v0',
      'orderId', p_order_id,
      'splitRequired', false,
      'locationCount', COALESCE(v_location_count, 0)
    );
  END IF;

  -- Split required + unsupported: route to manual review. Lock the order so the
  -- hold attaches to a real, paid order (mirrors create_order's checks).
  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_order_not_found' USING ERRCODE = '22023';
  END IF;

  -- Idempotent active hold. The partial unique index
  -- commerce_order_holds_one_active_reason (order_id, reason) WHERE active and
  -- the unique idempotency_key both make a re-run a no-op; we then return the
  -- existing hold as the durable signal.
  INSERT INTO public.commerce_order_holds (
    order_id, created_by, reason, note, idempotency_key, metadata
  )
  VALUES (
    p_order_id,
    NULL,
    'fulfillment_exception',
    'split_shipment_unsupported: order reservations span multiple inventory locations',
    p_idempotency_key,
    COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'source', 'commerce.fulfillment.split_shipment_preflight',
      'reason', 'split_shipment_unsupported',
      'locationCount', v_location_count
    )
  )
  ON CONFLICT DO NOTHING
  RETURNING * INTO v_hold;

  IF NOT FOUND THEN
    v_replayed := true;
    SELECT * INTO v_hold
      FROM public.commerce_order_holds
     WHERE order_id = p_order_id
       AND reason = 'fulfillment_exception'
       AND status = 'active'
     ORDER BY created_at DESC
     LIMIT 1;
  END IF;

  INSERT INTO public.commerce_order_operations (
    order_id, hold_id, actor_user_id, operation_type, source, idempotency_key, payload
  )
  VALUES (
    p_order_id,
    v_hold.id,
    NULL,
    'hold_created',
    'commerce.fulfillment.split_shipment_preflight',
    p_idempotency_key || ':operation',
    jsonb_build_object(
      'reason', 'split_shipment_unsupported',
      'locationCount', v_location_count
    )
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.fulfillment.v0',
    'orderId', p_order_id,
    'splitRequired', true,
    'locationCount', v_location_count,
    'holdId', v_hold.id,
    'replayed', v_replayed
  );
END;
$$;


--
-- Name: FUNCTION commerce_fulfillment_preflight_split_shipment(p_idempotency_key text, p_order_id uuid, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_fulfillment_preflight_split_shipment(p_idempotency_key text, p_order_id uuid, p_metadata jsonb) IS 'Order-paid fulfillment preflight: when reservations span multiple locations, places an idempotent fulfillment_exception hold (manual review) instead of creating an unfulfillable fulfillment order. Returns splitRequired + holdId.';


--
-- Name: commerce_fulfillment_reconcile_provider_command(uuid, bigint, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_reconcile_provider_command(p_command_id uuid, p_expected_version bigint, p_identity_fingerprint text, p_proof_kind text, p_proof_fingerprint text, p_proof_observed_at timestamp with time zone, p_proof_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_command public.commerce_fulfillment_provider_commands%ROWTYPE; v_from text;
BEGIN
  SELECT * INTO v_command FROM public.commerce_fulfillment_provider_commands WHERE id=p_command_id FOR UPDATE;
  IF NOT FOUND OR v_command.version<>p_expected_version THEN RAISE EXCEPTION 'fulfillment_provider_command_reconcile_conflict' USING ERRCODE='40001'; END IF;
  IF v_command.status NOT IN ('accepted','uncertain','manual_review') OR p_proof_kind NOT IN ('provider_reference','correlation_key','provider_idempotency_key') OR p_identity_fingerprint !~ '^[a-f0-9]{64}$' OR p_proof_fingerprint !~ '^[a-f0-9]{64}$' OR p_proof_source NOT IN ('provider_lookup','provider_webhook','operator_verified') OR p_proof_observed_at > now() OR p_proof_observed_at < now()-interval '24 hours'
    OR (p_identity_fingerprint = v_command.correlation_fingerprint OR p_identity_fingerprint = v_command.provider_idempotency_key_fingerprint) IS NOT TRUE
    OR (p_proof_kind='correlation_key' AND p_identity_fingerprint IS DISTINCT FROM v_command.correlation_fingerprint)
    OR (p_proof_kind='provider_idempotency_key' AND p_identity_fingerprint IS DISTINCT FROM v_command.provider_idempotency_key_fingerprint)
  THEN RAISE EXCEPTION 'fulfillment_provider_command_reconcile_proof_invalid' USING ERRCODE='22023'; END IF;
  v_from := v_command.status;
  UPDATE public.commerce_fulfillment_provider_commands SET status='confirmed',provider_reference_fingerprint=p_proof_fingerprint,confirmed_at=now(),finished_at=now(),last_reason_code='provider_effect_present',claim_token=NULL,claim_owner_fingerprint=NULL,claim_expires_at=NULL,version=version+1,updated_at=now() WHERE id=p_command_id RETURNING * INTO v_command;
  INSERT INTO public.commerce_fulfillment_provider_command_transitions(command_id,from_status,to_status,reason_code,command_version,attempt_count,proof_kind,proof_fingerprint,proof_observed_at,proof_source) VALUES(v_command.id,v_from,'confirmed','provider_effect_present',v_command.version,v_command.attempt_count,p_proof_kind,p_proof_fingerprint,p_proof_observed_at,p_proof_source);
  RETURN private.commerce_fulfillment_provider_command_result(v_command) || jsonb_build_object('proofRecorded',true);
END; $_$;


--
-- Name: commerce_fulfillment_record_label_created(text, uuid, text, text, text, integer, jsonb, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_record_label_created(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_kind text, p_provider_tracking_id text, p_label_url text DEFAULT NULL::text, p_delivery_estimate_days integer DEFAULT NULL::integer, p_raw_provider_payload jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_attempt public.commerce_fulfillment_provider_attempts%ROWTYPE;
  v_existing_ref_order_id uuid;
BEGIN
  SELECT * INTO v_attempt
    FROM public.commerce_fulfillment_provider_attempts
   WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.fulfillment.v0',
      'fulfillmentOrderId', v_attempt.fulfillment_order_id,
      'orderId', v_attempt.order_id,
      'status', (SELECT status FROM public.commerce_fulfillment_orders WHERE id = v_attempt.fulfillment_order_id),
      'replayed', true
    );
  END IF;

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_fulfillment.status IN ('handed_over', 'in_transit', 'delivered', 'cancelled') THEN
    RAISE EXCEPTION 'commerce_fulfillment_label_invalid_status' USING ERRCODE = '22023';
  END IF;

  -- Unchanged, and deliberately still scoped by ORDER: a tracking number that
  -- already belongs to a different order is a correlation conflict. Two parcels
  -- of the SAME order re-presenting one number is not -- the conflict branch
  -- below re-attributes it to the parcel recording it now.
  IF p_provider_tracking_id IS NOT NULL THEN
    SELECT order_id INTO v_existing_ref_order_id
      FROM public.shipment_external_refs
     WHERE provider_kind = p_provider_kind
       AND provider_tracking_id = p_provider_tracking_id;
    IF v_existing_ref_order_id IS NOT NULL AND v_existing_ref_order_id <> v_fulfillment.order_id THEN
      RAISE EXCEPTION 'commerce_fulfillment_tracking_ref_conflict' USING ERRCODE = '23505';
    END IF;
  END IF;

  INSERT INTO public.commerce_fulfillment_provider_attempts (
    fulfillment_order_id, order_id, provider_kind, status, idempotency_key,
    provider_tracking_id, response_payload, metadata
  )
  VALUES (
    p_fulfillment_order_id, v_fulfillment.order_id, p_provider_kind, 'succeeded',
    p_idempotency_key, p_provider_tracking_id,
    jsonb_build_object(
      'labelUrl', p_label_url,
      'deliveryEstimateDays', p_delivery_estimate_days,
      'rawProviderPayload', coalesce(p_raw_provider_payload, '{}'::jsonb)
    ),
    coalesce(p_metadata, '{}'::jsonb)
  );

  IF p_provider_tracking_id IS NOT NULL THEN
    INSERT INTO public.shipment_external_refs (
      order_id, fulfillment_order_id, provider_kind, provider_tracking_id, active
    )
    VALUES (
      v_fulfillment.order_id, p_fulfillment_order_id, p_provider_kind, p_provider_tracking_id, true
    )
    ON CONFLICT (provider_kind, provider_tracking_id)
    DO UPDATE SET
      active = true,
      fulfillment_order_id = EXCLUDED.fulfillment_order_id,
      updated_at = now();
  END IF;

  UPDATE public.commerce_fulfillment_orders
     SET status = 'label_created',
         provider_kind = p_provider_kind,
         updated_at = now()
   WHERE id = p_fulfillment_order_id;

  INSERT INTO public.commerce_fulfillment_operations (
    fulfillment_order_id, order_id, operation_type, idempotency_key, actor_user_id, payload
  )
  VALUES (
    p_fulfillment_order_id, v_fulfillment.order_id, 'label_created',
    p_idempotency_key || ':operation', p_actor_user_id,
    jsonb_build_object(
      'providerKind', p_provider_kind,
      'providerTrackingId', p_provider_tracking_id,
      'labelUrl', p_label_url,
      'customerTrackingDeferred', p_provider_tracking_id IS NULL
    )
  );

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.fulfillment.v0',
    'fulfillmentOrderId', p_fulfillment_order_id,
    'orderId', v_fulfillment.order_id,
    'status', 'label_created',
    'replayed', false
  );
END;
$$;


--
-- Name: FUNCTION commerce_fulfillment_record_label_created(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_kind text, p_provider_tracking_id text, p_label_url text, p_delivery_estimate_days integer, p_raw_provider_payload jsonb, p_actor_user_id uuid, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_fulfillment_record_label_created(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_kind text, p_provider_tracking_id text, p_label_url text, p_delivery_estimate_days integer, p_raw_provider_payload jsonb, p_actor_user_id uuid, p_metadata jsonb) IS 'Records provider label/order acknowledgement and attributes the tracking reference to the parcel it was created for. p_provider_tracking_id may be null when carrier tracking is not yet available; shipment_external_refs remains the only customer-visible tracking source.';


--
-- Name: commerce_fulfillment_record_provider_attempt(text, uuid, text, text, jsonb, jsonb, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_record_provider_attempt(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_kind text, p_status text, p_request_payload jsonb DEFAULT '{}'::jsonb, p_response_payload jsonb DEFAULT '{}'::jsonb, p_error text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_attempt public.commerce_fulfillment_provider_attempts%ROWTYPE;
  v_existing_ref_order_id uuid;
BEGIN
  SELECT * INTO v_attempt
    FROM public.commerce_fulfillment_provider_attempts
   WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', v_attempt.fulfillment_order_id, 'orderId', v_attempt.order_id, 'status', (SELECT status FROM public.commerce_fulfillment_orders WHERE id = v_attempt.fulfillment_order_id), 'replayed', true);
  END IF;

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_not_found' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_fulfillment_provider_attempts (
    fulfillment_order_id, order_id, provider_kind, status, idempotency_key,
    request_payload, response_payload, error, metadata
  )
  VALUES (
    p_fulfillment_order_id, v_fulfillment.order_id, p_provider_kind, p_status,
    p_idempotency_key, coalesce(p_request_payload, '{}'::jsonb),
    coalesce(p_response_payload, '{}'::jsonb), p_error, coalesce(p_metadata, '{}'::jsonb)
  );

  INSERT INTO public.commerce_fulfillment_operations (
    fulfillment_order_id, order_id, operation_type, idempotency_key, actor_user_id, payload
  )
  VALUES (
    p_fulfillment_order_id, v_fulfillment.order_id, 'provider_attempt_recorded',
    p_idempotency_key || ':operation', p_actor_user_id,
    jsonb_build_object('providerKind', p_provider_kind, 'status', p_status)
  );

  RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', p_fulfillment_order_id, 'orderId', v_fulfillment.order_id, 'status', v_fulfillment.status, 'replayed', false);
END;
$$;


--
-- Name: commerce_fulfillment_record_provider_exception(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_record_provider_exception(p_idempotency_key text, p_order_id uuid, p_reason text DEFAULT 'provider_rejected'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_hold public.commerce_order_holds%ROWTYPE;
  v_operation public.commerce_order_operations%ROWTYPE;
  v_replayed boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8 OR p_order_id IS NULL THEN
    RAISE EXCEPTION 'commerce_fulfillment_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_order_not_found' USING ERRCODE = '22023';
  END IF;

  -- Reserve the globally unique occurrence key before creating a hold. A
  -- concurrent insert for another order waits on this unique key; after the
  -- winner commits, the loser reads its operation and fails closed without
  -- creating an orphan hold or customer event. The operation also survives an
  -- audited hold release and remains the durable exact-replay proof.
  INSERT INTO public.commerce_order_operations (
    order_id, hold_id, actor_user_id, operation_type, source, idempotency_key, payload
  )
  VALUES (
    p_order_id,
    NULL,
    NULL,
    'hold_created',
    'commerce.fulfillment.omnipack_provider_exception',
    p_idempotency_key || ':operation',
    jsonb_build_object('reason', COALESCE(NULLIF(btrim(p_reason), ''), 'provider_rejected'))
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING * INTO v_operation;

  IF NOT FOUND THEN
    SELECT * INTO v_operation
      FROM public.commerce_order_operations
     WHERE idempotency_key = p_idempotency_key || ':operation';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'commerce_fulfillment_idempotency_operation_not_found' USING ERRCODE = '22023';
    END IF;

    IF v_operation.order_id <> p_order_id THEN
      RAISE EXCEPTION 'commerce_fulfillment_idempotency_order_mismatch' USING ERRCODE = '22023';
    END IF;
    IF v_operation.source <> 'commerce.fulfillment.omnipack_provider_exception'
      OR v_operation.operation_type <> 'hold_created'
      OR NOT EXISTS (
        SELECT 1
          FROM public.commerce_order_holds
         WHERE id = v_operation.hold_id
           AND order_id = p_order_id
           AND reason = 'fulfillment_exception'
      )
    THEN
      RAISE EXCEPTION 'commerce_fulfillment_idempotency_operation_mismatch' USING ERRCODE = '22023';
    END IF;

    RETURN jsonb_build_object(
      'contractVersion', 'commerce.fulfillment.v0',
      'orderId', p_order_id,
      'holdId', v_operation.hold_id,
      'replayed', true
    );
  END IF;

  INSERT INTO public.commerce_order_holds (
    order_id, created_by, reason, note, idempotency_key, metadata
  )
  VALUES (
    p_order_id,
    NULL,
    'fulfillment_exception',
    'omnipack_provider_exception: ' || COALESCE(NULLIF(btrim(p_reason), ''), 'provider_rejected'),
    p_idempotency_key,
    COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'source', 'commerce.fulfillment.omnipack_provider_exception',
      'reason', COALESCE(NULLIF(btrim(p_reason), ''), 'provider_rejected')
    )
  )
  ON CONFLICT DO NOTHING
  RETURNING * INTO v_hold;

  IF NOT FOUND THEN
    v_replayed := true;
    SELECT * INTO v_hold
      FROM public.commerce_order_holds
     WHERE order_id = p_order_id
       AND reason = 'fulfillment_exception'
       AND status = 'active'
     ORDER BY created_at DESC
     LIMIT 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'commerce_fulfillment_idempotency_hold_mismatch' USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE public.commerce_order_operations
     SET hold_id = v_hold.id
   WHERE id = v_operation.id
  RETURNING * INTO v_operation;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.fulfillment.v0',
    'orderId', p_order_id,
    'holdId', v_operation.hold_id,
    'replayed', v_replayed
  );
END;
$$;


--
-- Name: FUNCTION commerce_fulfillment_record_provider_exception(p_idempotency_key text, p_order_id uuid, p_reason text, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_fulfillment_record_provider_exception(p_idempotency_key text, p_order_id uuid, p_reason text, p_metadata jsonb) IS 'Places an occurrence-idempotent fulfillment_exception hold for an OmniPack rejection/cancellation and replays against its durable hold operation after release.';


--
-- Name: commerce_fulfillment_record_tracking_event(text, uuid, text, text, jsonb, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_record_tracking_event(p_idempotency_key text, p_fulfillment_order_id uuid, p_status text, p_provider_tracking_id text DEFAULT NULL::text, p_raw_event jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_existing_operation public.commerce_fulfillment_operations%ROWTYPE;
  v_provider_delivery_time timestamptz;
  v_raw_occurred_at text := nullif(btrim(p_raw_event->>'occurredAt'), '');
BEGIN
  -- PostgreSQL otherwise accepts timestamps without a zone using the session
  -- timezone. Provider chronology is usable only when the payload is explicit.
  IF p_status = 'delivered'
    AND v_raw_occurred_at ~ '^\d{4}-\d{2}-\d{2}[Tt ]\d{2}:\d{2}:\d{2}(\.\d+)?([Zz]|[+-]\d{2}:\d{2})$'
  THEN
    BEGIN
      v_provider_delivery_time := v_raw_occurred_at::timestamptz;
    EXCEPTION WHEN OTHERS THEN
      v_provider_delivery_time := NULL;
    END;
  END IF;

  -- The idempotency key is the write boundary, not the fulfillment row. Two
  -- requests may otherwise lock different fulfillments, mutate both, and only
  -- discover the shared-key collision at the operation insert.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'commerce-fulfillment-tracking|' || coalesce(p_idempotency_key, ''),
    0
  ));

  SELECT * INTO v_existing_operation
    FROM public.commerce_fulfillment_operations
   WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing_operation.fulfillment_order_id IS DISTINCT FROM p_fulfillment_order_id
      OR v_existing_operation.payload->>'status' IS DISTINCT FROM p_status
      OR coalesce(v_existing_operation.payload->>'providerTrackingId', '') IS DISTINCT FROM coalesce(p_provider_tracking_id, '')
    THEN
      RAISE EXCEPTION 'commerce_fulfillment_tracking_idempotency_conflict' USING ERRCODE = '23505';
    END IF;

    SELECT * INTO v_fulfillment
      FROM public.commerce_fulfillment_orders
     WHERE id = v_existing_operation.fulfillment_order_id
     FOR UPDATE;

    IF p_status = 'delivered'
      AND v_provider_delivery_time IS NOT NULL
      AND (v_fulfillment.delivered_at IS NULL OR v_provider_delivery_time < v_fulfillment.delivered_at)
    THEN
      UPDATE public.commerce_fulfillment_orders
         SET delivered_at = LEAST(coalesce(v_fulfillment.delivered_at, v_provider_delivery_time), v_provider_delivery_time),
             updated_at = now()
       WHERE id = v_existing_operation.fulfillment_order_id
       RETURNING * INTO v_fulfillment;
    END IF;

    RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', v_existing_operation.fulfillment_order_id, 'orderId', v_existing_operation.order_id, 'status', v_fulfillment.status, 'replayed', true);
  END IF;

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_not_found' USING ERRCODE = '22023';
  END IF;
  IF p_status NOT IN ('in_transit', 'delivered', 'exception') THEN
    RAISE EXCEPTION 'commerce_fulfillment_invalid_tracking_status' USING ERRCODE = '22023';
  END IF;

  IF v_fulfillment.status = 'delivered' THEN
    IF p_status = 'delivered' THEN
      IF v_provider_delivery_time IS NOT NULL
        AND (v_fulfillment.delivered_at IS NULL OR v_provider_delivery_time < v_fulfillment.delivered_at)
      THEN
        UPDATE public.commerce_fulfillment_orders
           SET delivered_at = LEAST(coalesce(v_fulfillment.delivered_at, v_provider_delivery_time), v_provider_delivery_time),
               updated_at = now()
         WHERE id = p_fulfillment_order_id;
      END IF;
      RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', p_fulfillment_order_id, 'orderId', v_fulfillment.order_id, 'status', 'delivered', 'replayed', true);
    END IF;
    RAISE EXCEPTION 'commerce_fulfillment_tracking_after_delivered_forbidden' USING ERRCODE = '22023';
  END IF;
  IF p_status IN ('in_transit', 'delivered') AND v_fulfillment.status NOT IN ('handed_over', 'in_transit') THEN
    RAISE EXCEPTION 'commerce_fulfillment_tracking_before_handoff_forbidden' USING ERRCODE = '22023';
  END IF;
  IF p_status = 'exception' AND v_fulfillment.status NOT IN ('label_created', 'handed_over', 'in_transit', 'exception') THEN
    RAISE EXCEPTION 'commerce_fulfillment_tracking_before_label_forbidden' USING ERRCODE = '22023';
  END IF;
  IF p_provider_tracking_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM public.shipment_external_refs
     WHERE order_id = v_fulfillment.order_id
       AND provider_tracking_id = p_provider_tracking_id
       AND active = true
  ) THEN
    RAISE EXCEPTION 'commerce_fulfillment_tracking_ref_not_active' USING ERRCODE = '22023';
  END IF;

  UPDATE public.commerce_fulfillment_orders
     SET status = p_status,
         delivered_at = CASE WHEN p_status = 'delivered' THEN coalesce(v_provider_delivery_time, now()) ELSE delivered_at END,
         updated_at = now()
   WHERE id = p_fulfillment_order_id;

  INSERT INTO public.commerce_fulfillment_operations (
    fulfillment_order_id, order_id, operation_type, idempotency_key, actor_user_id, payload
  )
  VALUES (
    p_fulfillment_order_id, v_fulfillment.order_id, 'tracking_event_recorded',
    p_idempotency_key, p_actor_user_id,
    jsonb_build_object('status', p_status, 'providerTrackingId', p_provider_tracking_id, 'rawEvent', coalesce(p_raw_event, '{}'::jsonb), 'metadata', coalesce(p_metadata, '{}'::jsonb))
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN jsonb_build_object('contractVersion', 'commerce.fulfillment.v0', 'fulfillmentOrderId', p_fulfillment_order_id, 'orderId', v_fulfillment.order_id, 'status', p_status, 'replayed', false);
END;
$_$;


--
-- Name: FUNCTION commerce_fulfillment_record_tracking_event(p_idempotency_key text, p_fulfillment_order_id uuid, p_status text, p_provider_tracking_id text, p_raw_event jsonb, p_actor_user_id uuid, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_fulfillment_record_tracking_event(p_idempotency_key text, p_fulfillment_order_id uuid, p_status text, p_provider_tracking_id text, p_raw_event jsonb, p_actor_user_id uuid, p_metadata jsonb) IS 'Records one fulfillment tracking operation. Delivered chronology uses an explicit-zone rawEvent.occurredAt when valid; replays may correct delivered_at earlier but never move it later.';


--
-- Name: commerce_fulfillment_recover_expired_provider_commands(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_recover_expired_provider_commands(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_command public.commerce_fulfillment_provider_commands%ROWTYPE; v_results jsonb := '[]'::jsonb; v_from text;
BEGIN
  IF p_limit NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'fulfillment_provider_command_recovery_invalid_limit' USING ERRCODE='22023'; END IF;
  FOR v_command IN SELECT * FROM public.commerce_fulfillment_provider_commands WHERE status IN ('claimed','submitting','accepted') AND claim_expires_at <= now() ORDER BY claim_expires_at FOR UPDATE SKIP LOCKED LIMIT p_limit LOOP
    v_from := v_command.status;
    UPDATE public.commerce_fulfillment_provider_commands SET status=CASE WHEN v_command.status IN ('submitting','accepted') THEN 'uncertain' ELSE 'queued' END,last_reason_code=CASE WHEN v_command.status IN ('submitting','accepted') THEN 'lease_expired' ELSE 'command_enqueued' END,claim_token=NULL,claim_owner_fingerprint=NULL,claim_expires_at=NULL,version=version+1,updated_at=now() WHERE id=v_command.id RETURNING * INTO v_command;
    INSERT INTO public.commerce_fulfillment_provider_command_transitions(command_id,from_status,to_status,reason_code,command_version,attempt_count) VALUES(v_command.id,v_from,v_command.status,v_command.last_reason_code,v_command.version,v_command.attempt_count);
    v_results := v_results || private.commerce_fulfillment_provider_command_result(v_command);
  END LOOP;
  RETURN v_results;
END; $$;


--
-- Name: commerce_fulfillment_release_or_cancel_command(uuid, uuid, bigint, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_release_or_cancel_command(p_command_id uuid, p_claim_token uuid, p_claim_generation bigint, p_expected_version bigint, p_action text, p_reason_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_command public.commerce_fulfillment_provider_commands%ROWTYPE; v_to text;
BEGIN
  v_command := private.commerce_fulfillment_provider_command_fence(p_command_id,p_claim_token,p_claim_generation,p_expected_version);
  IF p_action='release' AND v_command.status='claimed' THEN v_to:='queued';
  ELSIF p_action='cancel' AND v_command.status='claimed' AND p_reason_code='operator_cancelled' THEN v_to:='cancelled';
  ELSE RAISE EXCEPTION 'fulfillment_provider_command_release_invalid' USING ERRCODE='22023'; END IF;
  UPDATE public.commerce_fulfillment_provider_commands SET status=v_to,last_reason_code=CASE WHEN v_to='cancelled' THEN 'operator_cancelled' ELSE 'command_enqueued' END,finished_at=CASE WHEN v_to='cancelled' THEN now() ELSE finished_at END,claim_token=NULL,claim_owner_fingerprint=NULL,claim_expires_at=NULL,version=version+1,updated_at=now() WHERE id=p_command_id RETURNING * INTO v_command;
  INSERT INTO public.commerce_fulfillment_provider_command_transitions(command_id,from_status,to_status,reason_code,command_version,attempt_count,claim_token,claim_generation) VALUES(v_command.id,'claimed',v_to,v_command.last_reason_code,v_command.version,v_command.attempt_count,p_claim_token,p_claim_generation);
  RETURN private.commerce_fulfillment_provider_command_result(v_command);
END; $$;


--
-- Name: commerce_fulfillment_resolve_uncertain_command(uuid, bigint, text, text, text, text, text, timestamp with time zone, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_fulfillment_resolve_uncertain_command(p_command_id uuid, p_expected_version bigint, p_identity_fingerprint text, p_decision text, p_reason_code text, p_proof_kind text, p_proof_fingerprint text, p_proof_observed_at timestamp with time zone, p_proof_source text, p_retry_not_before timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_command public.commerce_fulfillment_provider_commands%ROWTYPE; v_to text; v_from text;
BEGIN
  SELECT * INTO v_command FROM public.commerce_fulfillment_provider_commands WHERE id=p_command_id FOR UPDATE;
  IF NOT FOUND OR v_command.version<>p_expected_version OR v_command.status NOT IN ('uncertain','manual_review') THEN RAISE EXCEPTION 'fulfillment_provider_command_resolution_conflict' USING ERRCODE='40001'; END IF;
  IF p_identity_fingerprint !~ '^[a-f0-9]{64}$' OR p_proof_fingerprint !~ '^[a-f0-9]{64}$' OR p_proof_source NOT IN ('provider_lookup','provider_webhook','operator_verified') OR p_proof_observed_at > now() OR p_proof_observed_at < now()-interval '10 minutes'
    OR (p_identity_fingerprint = v_command.correlation_fingerprint OR p_identity_fingerprint = v_command.provider_idempotency_key_fingerprint) IS NOT TRUE
    OR (p_proof_kind='correlation_key' AND p_identity_fingerprint IS DISTINCT FROM v_command.correlation_fingerprint)
    OR (p_proof_kind='provider_idempotency_key' AND p_identity_fingerprint IS DISTINCT FROM v_command.provider_idempotency_key_fingerprint)
    OR (p_proof_kind='authoritative_absence' AND p_proof_fingerprint IS DISTINCT FROM p_identity_fingerprint)
  THEN RAISE EXCEPTION 'fulfillment_provider_command_resolution_proof_invalid' USING ERRCODE='22023'; END IF;
  IF p_decision='manual_review' AND p_reason_code IN ('effect_unknown','identity_mismatch','invalid_contract','unsafe_retry') AND p_proof_kind IN ('provider_reference','correlation_key','provider_idempotency_key') THEN v_to:='manual_review';
  ELSIF p_decision='retry_wait' AND p_reason_code='authoritative_absence' AND p_proof_kind='authoritative_absence' AND p_proof_source='provider_lookup' AND p_retry_not_before > now() THEN v_to:='retry_wait';
  ELSE RAISE EXCEPTION 'fulfillment_provider_command_resolution_unsafe' USING ERRCODE='22023'; END IF;
  v_from := v_command.status;
  UPDATE public.commerce_fulfillment_provider_commands SET status=v_to,available_at=COALESCE(p_retry_not_before,available_at),last_reason_code=p_reason_code,claim_token=NULL,claim_owner_fingerprint=NULL,claim_expires_at=NULL,version=version+1,updated_at=now() WHERE id=p_command_id RETURNING * INTO v_command;
  INSERT INTO public.commerce_fulfillment_provider_command_transitions(command_id,from_status,to_status,reason_code,command_version,attempt_count,proof_kind,proof_fingerprint,proof_observed_at,proof_source) VALUES(v_command.id,v_from,v_to,p_reason_code,v_command.version,v_command.attempt_count,p_proof_kind,p_proof_fingerprint,p_proof_observed_at,p_proof_source);
  RETURN private.commerce_fulfillment_provider_command_result(v_command) || jsonb_build_object('proofRecorded',true);
END; $_$;


--
-- Name: commerce_guard_fulfillment_attempt_provider(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_guard_fulfillment_attempt_provider() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.commerce_validate_fulfillment_provider_kind(NEW.provider_kind, NEW.order_id);
  RETURN NEW;
END;
$$;


--
-- Name: commerce_guard_fulfillment_order_provider(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_guard_fulfillment_order_provider() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.commerce_validate_fulfillment_provider_kind(NEW.provider_kind, NEW.order_id);
  RETURN NEW;
END;
$$;


--
-- Name: commerce_guard_handoff_no_split(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_guard_handoff_no_split() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status = 'handed_over' AND OLD.status IS DISTINCT FROM NEW.status THEN
    PERFORM public.commerce_guard_no_split_fulfillment_order(NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: commerce_guard_no_split_fulfillment_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_guard_no_split_fulfillment_order(p_fulfillment_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_location_count integer;
BEGIN
  SELECT count(DISTINCT ir.location_id)
    INTO v_location_count
    FROM public.commerce_fulfillment_order_lines l
    CROSS JOIN LATERAL unnest(l.inventory_reservation_ids) AS reservation_id
    JOIN public.inventory_reservations ir
      ON ir.id = reservation_id
   WHERE l.fulfillment_order_id = p_fulfillment_order_id;

  IF COALESCE(v_location_count, 0) > 1 THEN
    RAISE EXCEPTION 'split_shipment_unsupported'
      USING
        ERRCODE = '22023',
        DETAIL = 'Fulfillment order reservations span multiple inventory locations.',
        HINT = 'Create separate fulfillment orders only after split shipment policy is supported.';
  END IF;
END;
$$;


--
-- Name: FUNCTION commerce_guard_no_split_fulfillment_order(p_fulfillment_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_guard_no_split_fulfillment_order(p_fulfillment_order_id uuid) IS 'Rejects fulfillment handoff when reservations span multiple inventory locations.';


--
-- Name: commerce_guard_paid_order_shipment_ref(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_guard_paid_order_shipment_ref() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.order_id IS DISTINCT FROM OLD.order_id
      OR NEW.provider_kind IS DISTINCT FROM OLD.provider_kind
      OR NEW.provider_tracking_id IS DISTINCT FROM OLD.provider_tracking_id
    THEN
      RAISE EXCEPTION 'commerce_fulfillment_tracking_ref_conflict'
        USING ERRCODE = '23505';
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.commerce_orders
      LEFT JOIN public.subscription_cycles
        ON subscription_cycles.id = commerce_orders.subscription_cycle_id
     WHERE commerce_orders.id = NEW.order_id
       AND commerce_orders.status IN ('paid', 'fulfillment_pending', 'fulfilled')
       AND (
         commerce_orders.mode <> 'subscription_cycle'
         OR subscription_cycles.status = 'paid'
       )
  ) THEN
    RAISE EXCEPTION 'commerce_shipment_requires_paid_order'
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_guard_paid_order_shipment_ref(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_guard_paid_order_shipment_ref() IS 'Requires paid shipment ownership and freezes the order/provider/tracking identity; active and delivery metadata remain mutable.';


--
-- Name: commerce_heal_provider_exception_hold(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_heal_provider_exception_hold() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_candidate record;
  v_proof text;
BEGIN
  -- Gate 0 — cheap rejection for the ~100% of evidence rows that prove nothing.
  -- 'cancelled' is an audited local cancellation, not a recovery, so it is not
  -- in the accepted set.
  IF NEW.local_status IS NULL
    OR NEW.occurred_at IS NULL
    OR NEW.local_status NOT IN ('provider_received', 'picking', 'packed', 'in_transit', 'delivered')
  THEN
    RETURN NEW;
  END IF;

  -- Gate 1 — scope. Single indexed probe; no candidate is the common case.
  SELECT * INTO v_candidate
    FROM public.commerce_oms_healable_provider_exception_holds(NEW.fulfillment_order_id)
   LIMIT 1;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  -- Gate 2 — chronology. An exception newer than the proof is not healed; this
  -- is what keeps returned_to_sender-after-delivery holds standing.
  IF NEW.occurred_at <= v_candidate.cleared_occurred_at THEN
    RETURN NEW;
  END IF;

  -- Gate 3 — proof class.
  IF NEW.local_status = 'delivered'
    AND v_candidate.cleared_provider_status IN ('suspended', 'shipping_failed')
  THEN
    v_proof := 'delivered';
  ELSIF v_candidate.cleared_provider_status = 'suspended' THEN
    v_proof := 'provider_recovered';
  ELSE
    RETURN NEW;
  END IF;

  PERFORM public.commerce_oms_release_hold_system(
    'commerce-heal:provider-exception:' || v_candidate.hold_id::text,
    v_candidate.hold_id,
    'commerce.fulfillment.omnipack_provider_exception_healed',
    v_proof,
    jsonb_build_object(
      'autoReleaseEvidence', jsonb_build_object(
        'fulfillmentOrderId', NEW.fulfillment_order_id,
        'statusEvidenceId', NEW.id,
        'providerStatus', NEW.provider_status,
        'providerSubStatus', NEW.provider_sub_status,
        'localStatus', NEW.local_status,
        'occurredAt', NEW.occurred_at,
        'evidenceKind', NEW.evidence_kind,
        'clearedStatusEvidenceId', v_candidate.cleared_evidence_id,
        'clearedProviderStatus', v_candidate.cleared_provider_status,
        'clearedProviderSubStatus', v_candidate.cleared_provider_sub_status,
        'clearedOccurredAt', v_candidate.cleared_occurred_at
      )
    )
  );

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_heal_provider_exception_hold(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_heal_provider_exception_hold() IS 'Releases an OmniPack provider-exception hold when newer evidence proves the cause cleared (delivery, or the provider leaving the exception state).';


--
-- Name: commerce_offer_policy_v2_readiness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_offer_policy_v2_readiness() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_now timestamptz := statement_timestamp();
  -- The settlement profile, read from the mirror 20260816152909 installed. Nothing in
  -- this body precedes the first use of either value, so they join v_now as initialisers
  -- rather than as statements. Both readers raise 55000 instead of returning a default,
  -- which is what makes an unconfigured deployment refuse to answer this gate rather than
  -- answer it wrongly; the caller already reads a failed readiness call as not-ready.
  v_region_code text := public.platform_region_code();
  v_settlement_currency text := public.platform_settlement_currency();
  v_reasons text[] := ARRAY[]::text[];
  v_first_legacy_count bigint := 0;
  v_first_pair_count bigint := 0;
  v_first_active_count bigint := 0;
  v_bundle_count bigint := 0;
  v_active_price_list_count bigint := 0;
  v_active_core_skus bigint := 0;
  v_price_mismatch_count bigint := 0;
  v_subscription_policy_count bigint := 0;
  v_subscription_policy_derives_band boolean := false;
  v_legacy_count bigint := 0;
  v_legacy_invalid_count bigint := 0;
  v_legacy_fingerprint text := md5('');
  v_legacy_cohort_fingerprint text := md5('');
  v_legacy_baseline_count integer;
  v_legacy_baseline_fingerprint text;
  v_legacy_baseline_matches boolean := false;
  v_watchdog_ready boolean := false;
  v_claim_sweep_ready boolean := false;
  v_automatic_v2_money_checked_count bigint := 0;
  v_automatic_v2_money_mismatch_count bigint := 0;
BEGIN
  WITH canonical_legacy AS (
    SELECT legacy.*
    FROM public.promotions legacy
    WHERE legacy.promotion_engine_version = 'promotion-engine.v1'
      AND legacy.trigger_type = 'automatic'
      AND legacy.code IS NULL
      AND legacy.discount_type = 'percentage'
      AND legacy.discount_value = 44.404
      AND legacy.applies_to_kind = 'order_total'
      AND legacy.applies_to_payload = '{"cart_mode":"subscription"}'::jsonb
      AND legacy.stacking_rule = 'exclusive'
      AND legacy.eligibility = '{"first_subscription_purchase":true}'::jsonb
      AND legacy.redemption_limit_per_customer = 1
      AND legacy.redemption_limit_global IS NULL
      AND legacy.status = 'active'
      AND v_region_code = ANY(legacy.region_availability)
      AND legacy.valid_from <= v_now
      AND (legacy.valid_to IS NULL OR legacy.valid_to >= v_now)
  ), canonical_pair AS (
    SELECT legacy.id AS legacy_id, mirror.id AS mirror_id,
      mirror.status AS mirror_status,
      mirror.applies_to_payload = legacy.applies_to_payload
        AND mirror.stacking_rule = legacy.stacking_rule
        AND mirror.eligibility = legacy.eligibility
        AND mirror.valid_from IS NOT DISTINCT FROM legacy.valid_from
        AND mirror.valid_to IS NOT DISTINCT FROM legacy.valid_to
        AND mirror.redemption_limit_global IS NOT DISTINCT FROM legacy.redemption_limit_global
        AND mirror.redemption_limit_per_customer IS NOT DISTINCT FROM legacy.redemption_limit_per_customer
        AND mirror.region_availability IS NOT DISTINCT FROM legacy.region_availability
        AS shared_shape_matches
    FROM canonical_legacy legacy
    JOIN public.promotions mirror ON mirror.v2_mirror_of = legacy.id
      AND mirror.promotion_engine_version = 'promotion-engine.v2'
      AND mirror.trigger_type = 'automatic'
      AND mirror.code IS NULL
      AND mirror.discount_type = 'percentage'
      AND mirror.discount_value = 50
      AND mirror.applies_to_kind = 'order_total'
      AND mirror.benefit_lane = 'product'
      AND mirror.benefit_kind = 'target_percentage'
      AND mirror.benefit_value_bps = 5000
      AND mirror.benefit_value_minor IS NULL
  )
  SELECT (SELECT count(*) FROM canonical_legacy), count(*), count(*) FILTER (
    WHERE mirror_status = 'active' AND shared_shape_matches
  ) INTO v_first_legacy_count, v_first_pair_count, v_first_active_count
  FROM canonical_pair;

  IF v_first_legacy_count <> 1 OR v_first_pair_count <> 1 THEN
    v_reasons := array_append(v_reasons, 'first_subscription_pair_invalid');
  ELSIF v_first_active_count <> 1 THEN
    v_reasons := array_append(v_reasons, 'first_subscription_mirror_not_ready');
  END IF;

  SELECT count(*) INTO v_bundle_count
  FROM public.promotions bundle
  WHERE bundle.promotion_engine_version = 'promotion-engine.v1'
    AND bundle.v2_mirror_of IS NULL
    AND bundle.trigger_type = 'automatic'
    AND bundle.code IS NULL
    AND bundle.discount_type = 'percentage'
    AND bundle.discount_value = 5
    AND bundle.applies_to_kind = 'order_total'
    AND bundle.applies_to_payload = '{"cart_mode":"one_time"}'::jsonb
    AND bundle.stacking_rule = 'stackable_with_any'
    AND bundle.eligibility = '{"min_cart_minor":12000}'::jsonb
    AND bundle.status = 'active'
    AND bundle.benefit_lane = 'product'
    AND bundle.benefit_kind = 'percentage'
    AND bundle.benefit_value_bps = 500
    AND bundle.redemption_limit_global IS NULL
    AND bundle.redemption_limit_per_customer IS NULL
    AND v_region_code = ANY(bundle.region_availability)
    AND bundle.valid_from <= v_now
    AND (bundle.valid_to IS NULL OR bundle.valid_to >= v_now);
  IF v_bundle_count <> 1 THEN
    v_reasons := array_append(v_reasons, 'bundle_5_policy_invalid');
  END IF;

  SELECT count(*) INTO v_active_price_list_count
  FROM public.price_lists
  WHERE region_code = v_region_code AND currency = v_settlement_currency AND status = 'active'
    AND valid_from <= v_now AND (valid_to IS NULL OR valid_to > v_now);

  SELECT count(*), COALESCE(bool_or(
      policy.rounding_rule = 'FLOOR_TO_QUANTUM'
      AND policy.digest ~ '^[0-9a-f]{64}$'
      AND ((1490 * (10000 - policy.discount_bps)) / 10000 / policy.rounding_quantum_minor)
        * policy.rounding_quantum_minor = 1340
    ), false)
  INTO v_subscription_policy_count, v_subscription_policy_derives_band
  FROM public.subscription_price_policy_revisions policy
  WHERE policy.price_list_id = (
      SELECT id FROM public.price_lists
      WHERE region_code = v_region_code AND currency = v_settlement_currency AND status = 'active'
        AND valid_from <= v_now AND (valid_to IS NULL OR valid_to > v_now)
      ORDER BY created_at DESC, id DESC LIMIT 1)
    AND policy.region_code = v_region_code
    AND policy.currency = v_settlement_currency
    AND policy.channel = 'D2C'
    AND policy.effective_from <= v_now
    AND policy.effective_to IS NULL;

  WITH active_list AS (
    SELECT id FROM public.price_lists
    WHERE region_code = v_region_code AND currency = v_settlement_currency AND status = 'active'
      AND valid_from <= v_now AND (valid_to IS NULL OR valid_to > v_now)
    ORDER BY created_at DESC, id DESC LIMIT 1
  ), core_skus AS (
    SELECT sku.id
    FROM public.catalog_skus sku
    WHERE sku.status = 'active'
      AND sku.is_addon = false
      AND sku.sellable_standalone = true
      AND sku.sellable_in_subscription = true
  ), price_shape AS (
    SELECT sku.id,
      count(entry.id) FILTER (
        WHERE entry.mode = 'one_time' AND entry.min_qty = 1
          AND entry.unit_price_minor = 1490
          AND entry.amount_kind = 'gross'
      ) AS one_time_matches,
      count(entry.id) FILTER (
        WHERE entry.mode = 'subscription' AND entry.min_qty = 1
          AND entry.unit_price_minor = 1340
          AND entry.amount_kind = 'gross'
      ) AS subscription_matches,
      count(entry.id) FILTER (WHERE entry.mode = 'subscription') AS subscription_entries,
      count(entry.id) FILTER (
        WHERE entry.mode = 'any'
          OR entry.amount_kind <> 'gross'
          OR (entry.mode = 'one_time' AND entry.unit_price_minor <> 1490)
          OR (entry.mode = 'subscription' AND entry.unit_price_minor <> 1340)
      ) AS overriding_or_drifted_entries
    FROM core_skus sku
    CROSS JOIN active_list list
    LEFT JOIN public.price_entries entry
      ON entry.price_list_id = list.id
     AND entry.variant_id = sku.id
     AND entry.active = true
     AND entry.valid_from <= v_now
     AND (entry.valid_to IS NULL OR entry.valid_to > v_now)
     AND entry.mode IN ('one_time', 'subscription', 'any')
    GROUP BY sku.id
  )
  SELECT count(*), count(*) FILTER (
    WHERE NOT (
      (v_subscription_policy_count = 0
        AND one_time_matches = 1
        AND subscription_matches = 1
        AND overriding_or_drifted_entries = 0)
      OR (v_subscription_policy_count = 1
        AND v_subscription_policy_derives_band
        AND one_time_matches = 1
        AND subscription_entries = 0
        AND overriding_or_drifted_entries = 0)
    )
  ) INTO v_active_core_skus, v_price_mismatch_count
  FROM price_shape;

  IF v_active_price_list_count <> 1 OR v_active_core_skus = 0 OR v_price_mismatch_count <> 0 THEN
    v_reasons := array_append(v_reasons, 'catalog_1490_legacy_1340_invalid');
  END IF;

  WITH legacy AS (
    SELECT subscription.id, subscription.currency,
      subscription.offer_policy_version, subscription.promotion_engine_version
    FROM public.subscriptions subscription
    WHERE subscription.offer_policy_assignment_state = 'legacy_frozen'
      AND subscription.is_test_fixture = false
  ), line_evidence AS (
    SELECT legacy.id AS subscription_id, line.id AS line_id, line.qty,
      CASE
        WHEN COALESCE(
          NULLIF(line.line_metadata#>>'{productSnapshot,quoteLine,unitPriceGross,amountMinor}', ''),
          NULLIF(line.line_metadata#>>'{productSnapshot,quoteLine,unitGrossMinor}', '')
        ) ~ '^[0-9]+$'
        THEN COALESCE(
          NULLIF(line.line_metadata#>>'{productSnapshot,quoteLine,unitPriceGross,amountMinor}', ''),
          NULLIF(line.line_metadata#>>'{productSnapshot,quoteLine,unitGrossMinor}', '')
        )::integer
        ELSE NULL
      END AS snapshot_unit_minor,
      CASE WHEN COALESCE(line.line_metadata#>>'{productSnapshot,quoteLine,lineSubtotalGross,amountMinor}', '') ~ '^[0-9]+$'
        THEN (line.line_metadata#>>'{productSnapshot,quoteLine,lineSubtotalGross,amountMinor}')::integer
        ELSE NULL END AS snapshot_subtotal_minor,
      CASE WHEN COALESCE(line.line_metadata#>>'{productSnapshot,quoteLine,quantity}', '') ~ '^[0-9]+$'
        THEN (line.line_metadata#>>'{productSnapshot,quoteLine,quantity}')::integer
        ELSE NULL END AS snapshot_quantity,
      line.line_metadata#>>'{productSnapshot,quoteLine,unitPriceGross,currency}' AS snapshot_currency
    FROM legacy
    LEFT JOIN public.subscription_lines line ON line.subscription_id = legacy.id
  ), agreement_evidence AS (
    SELECT legacy.id AS subscription_id,
      count(agreement.id) FILTER (WHERE agreement.id IS NOT NULL) AS agreement_count,
      count(*) FILTER (WHERE agreement.id IS NOT NULL AND (
        agreement.unit_price_gross_minor IS DISTINCT FROM 1340
        OR agreement.currency IS DISTINCT FROM v_settlement_currency
        OR CASE WHEN COALESCE(agreement.quote_line#>>'{unitPriceGross,amountMinor}', '') ~ '^[0-9]+$'
          THEN (agreement.quote_line#>>'{unitPriceGross,amountMinor}')::integer ELSE NULL END
          IS DISTINCT FROM 1340
        OR CASE WHEN COALESCE(agreement.quote_line#>>'{quantity}', '') ~ '^[0-9]+$'
          THEN (agreement.quote_line#>>'{quantity}')::integer ELSE NULL END IS NULL
        OR CASE WHEN COALESCE(agreement.quote_line#>>'{lineSubtotalGross,amountMinor}', '') ~ '^[0-9]+$'
          THEN (agreement.quote_line#>>'{lineSubtotalGross,amountMinor}')::integer ELSE NULL END
          IS DISTINCT FROM 1340 * CASE WHEN COALESCE(agreement.quote_line#>>'{quantity}', '') ~ '^[0-9]+$'
            THEN (agreement.quote_line#>>'{quantity}')::integer ELSE 0 END
        OR agreement.quote_line#>>'{unitPriceGross,currency}' IS DISTINCT FROM v_settlement_currency
      )) AS invalid_agreement_count,
      md5(COALESCE(string_agg(
        agreement.id::text || ':' || COALESCE(agreement.unit_price_gross_minor::text, 'null') || ':' ||
          COALESCE(agreement.ended_at::text, 'active'),
        '|' ORDER BY agreement.id
      ), '')) AS agreement_fingerprint
    FROM legacy
    LEFT JOIN public.subscription_price_agreements agreement
      ON agreement.subscription_id = legacy.id
    GROUP BY legacy.id
  ), subscription_evidence AS (
    SELECT legacy.id,
      legacy.currency,
      legacy.offer_policy_version,
      legacy.promotion_engine_version,
      count(line.line_id) AS line_count,
      count(*) FILTER (
        WHERE line.line_id IS NOT NULL AND (
          line.snapshot_unit_minor IS DISTINCT FROM 1340
          OR line.snapshot_quantity IS DISTINCT FROM line.qty
          OR line.snapshot_subtotal_minor IS DISTINCT FROM line.qty * 1340
          OR line.snapshot_currency IS DISTINCT FROM v_settlement_currency
        )
      ) AS invalid_line_count,
      md5(COALESCE(string_agg(
        line.line_id::text || ':' || COALESCE(line.snapshot_unit_minor::text, 'null') || ':' ||
          COALESCE(line.snapshot_subtotal_minor::text, 'null') || ':' ||
          COALESCE(line.snapshot_quantity::text, 'null') || ':' || COALESCE(line.snapshot_currency, 'null'),
        '|' ORDER BY line.line_id
      ), '')) AS line_fingerprint,
      max(agreement.invalid_agreement_count) AS invalid_agreement_count,
      max(agreement.agreement_fingerprint) AS agreement_fingerprint
    FROM legacy
    LEFT JOIN line_evidence line ON line.subscription_id = legacy.id
    LEFT JOIN agreement_evidence agreement ON agreement.subscription_id = legacy.id
    GROUP BY legacy.id, legacy.currency, legacy.offer_policy_version,
      legacy.promotion_engine_version
  )
  SELECT count(*), count(*) FILTER (
      WHERE currency <> v_settlement_currency
        OR offer_policy_version <> 'commerce.offer-policy.v1'
        OR promotion_engine_version <> 'promotion-engine.v1'
        OR line_count = 0
        OR invalid_line_count <> 0
        OR invalid_agreement_count <> 0
    ), md5(COALESCE(string_agg(
      id::text || ':' || line_fingerprint || ':' || agreement_fingerprint,
      '|' ORDER BY id
    ), ''))
  INTO v_legacy_count, v_legacy_invalid_count, v_legacy_fingerprint
  FROM subscription_evidence;

  IF v_legacy_count = 0 OR v_legacy_invalid_count <> 0 THEN
    v_reasons := array_append(v_reasons, 'legacy_frozen_records_invalid');
  END IF;

  SELECT md5(COALESCE(string_agg(subscription.id::text, '|'
    ORDER BY subscription.id), ''))
  INTO v_legacy_cohort_fingerprint
  FROM public.subscriptions subscription
  WHERE subscription.offer_policy_assignment_state = 'legacy_frozen'
    AND subscription.is_test_fixture = false;

  SELECT baseline.expected_count, baseline.expected_fingerprint
  INTO v_legacy_baseline_count, v_legacy_baseline_fingerprint
  FROM public.commerce_offer_policy_rollout_baselines baseline
  WHERE baseline.baseline_key = 'legacy_frozen.v1'; -- gitleaks:allow -- public schema sentinel, not a credential
  v_legacy_baseline_matches := COALESCE(
    v_legacy_count = v_legacy_baseline_count
      AND v_legacy_cohort_fingerprint = v_legacy_baseline_fingerprint,
    false
  );
  IF NOT v_legacy_baseline_matches THEN
    v_reasons := array_append(v_reasons, 'legacy_frozen_baseline_mismatch');
  END IF;

  -- The scheduled watchdog owns the expensive full-history promotion/claim
  -- reconciliation. Request-path readiness consumes only its small persisted
  -- heartbeat, and requires the observer + claim-sweep posture to have been
  -- green recently. This prevents a cold request from running an unbounded
  -- health scan while retaining fail-closed operational evidence.
  SELECT COALESCE(
    control.enabled
      AND control.last_status = 'success'
      AND control.last_success_at >= v_now - interval '6 hours'
      AND control.last_success_at <= v_now
      AND control.metadata->>'promotionReady' = 'true',
    false
  ) INTO v_watchdog_ready
  FROM public.platform_job_controls control
  WHERE control.job_name = 'platform-watchdog';
  v_watchdog_ready := COALESCE(v_watchdog_ready, false);

  SELECT COALESCE(
    control.enabled
      AND control.last_status = 'success'
      AND control.last_success_at >= v_now - interval '15 minutes'
      AND control.last_success_at <= v_now,
    false
  ) INTO v_claim_sweep_ready
  FROM public.platform_job_controls control
  WHERE control.job_name = 'promotion-claim-sweep';
  v_claim_sweep_ready := COALESCE(v_claim_sweep_ready, false);

  IF NOT v_watchdog_ready THEN
    v_reasons := array_append(v_reasons, 'promotion_watchdog_not_ready');
  END IF;
  IF NOT v_claim_sweep_ready THEN
    v_reasons := array_append(v_reasons, 'promotion_claim_sweep_not_ready');
  END IF;

  -- The code-health RPC intentionally owns only explicit code-v2 evidence.
  -- Independently reconcile the frozen quote/header of recent orders assigned
  -- to automatic offer-policy v2 so a First Subscription money drift closes
  -- new assignment too. The 24-hour created_at window keeps the runtime probe
  -- bounded; Canonical Order Money remains the write-time invariant.
  WITH automatic_v2_orders AS (
    SELECT orders.id, orders.currency, orders.subtotal_cents,
      orders.discount_cents, orders.shipping_cents,
      orders.shipping_discount_cents, orders.total_cents,
      orders.metadata#>'{quoteSnapshot,quote}' AS quote
    FROM public.commerce_orders orders
    WHERE orders.created_at >= v_now - interval '24 hours'
      AND orders.created_at <= v_now
      AND orders.status IN ('paid', 'fulfillment_pending', 'fulfilled', 'refunded')
      AND orders.metadata#>>'{quoteSnapshot,quote,context,pricingPolicy,promotionEngineVersion}'
        = 'promotion-engine.v2'
  ), extracted AS (
    SELECT automatic_v2_orders.*,
      CASE WHEN COALESCE(quote#>>'{subtotalGross,amountMinor}', '') ~ '^[0-9]{1,16}$'
        THEN (quote#>>'{subtotalGross,amountMinor}')::bigint END AS quote_subtotal,
      CASE WHEN COALESCE(quote#>>'{discountTotalGross,amountMinor}', '') ~ '^[0-9]{1,16}$'
        THEN (quote#>>'{discountTotalGross,amountMinor}')::bigint END AS quote_discount,
      CASE WHEN COALESCE(quote#>>'{shippingGross,amountMinor}', '0') ~ '^[0-9]{1,16}$'
        THEN COALESCE(quote#>>'{shippingGross,amountMinor}', '0')::bigint END AS quote_shipping,
      CASE WHEN COALESCE(quote#>>'{shippingDiscountGross,amountMinor}', '0') ~ '^[0-9]{1,16}$'
        THEN COALESCE(quote#>>'{shippingDiscountGross,amountMinor}', '0')::bigint END
        AS quote_shipping_discount,
      CASE WHEN COALESCE(quote#>>'{totalGross,amountMinor}', '') ~ '^[0-9]{1,16}$'
        THEN (quote#>>'{totalGross,amountMinor}')::bigint END AS quote_total
    FROM automatic_v2_orders
  )
  SELECT count(*), count(*) FILTER (WHERE
    jsonb_typeof(quote) IS DISTINCT FROM 'object'
    OR currency IS DISTINCT FROM v_settlement_currency
    OR quote#>>'{subtotalGross,currency}' IS DISTINCT FROM v_settlement_currency
    OR quote#>>'{discountTotalGross,currency}' IS DISTINCT FROM v_settlement_currency
    OR (quote ? 'shippingGross' AND quote#>>'{shippingGross,currency}' IS DISTINCT FROM v_settlement_currency)
    OR (quote ? 'shippingDiscountGross'
      AND quote#>>'{shippingDiscountGross,currency}' IS DISTINCT FROM v_settlement_currency)
    OR quote#>>'{totalGross,currency}' IS DISTINCT FROM v_settlement_currency
    OR quote_subtotal IS DISTINCT FROM subtotal_cents::bigint
    OR quote_discount IS DISTINCT FROM discount_cents::bigint
    OR quote_shipping IS DISTINCT FROM shipping_cents::bigint
    OR quote_shipping_discount IS DISTINCT FROM shipping_discount_cents::bigint
    OR quote_total IS DISTINCT FROM total_cents::bigint
  ) INTO v_automatic_v2_money_checked_count, v_automatic_v2_money_mismatch_count
  FROM extracted;

  IF v_automatic_v2_money_mismatch_count <> 0 THEN
    v_reasons := array_append(v_reasons, 'automatic_v2_money_invalid');
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce-offer-policy-v2-readiness.v1',
    'ready', cardinality(v_reasons) = 0,
    'checkedAt', v_now,
    'reasons', to_jsonb(v_reasons),
    'evidence', jsonb_build_object(
      'firstSubscriptionPairCount', v_first_pair_count,
      'firstSubscriptionLegacyCount', v_first_legacy_count,
      'firstSubscriptionActiveCount', v_first_active_count,
      'bundlePolicyCount', v_bundle_count,
      'activePriceListCount', v_active_price_list_count,
      'activeCoreSkuCount', v_active_core_skus,
      'priceMismatchCount', v_price_mismatch_count,
      'subscriptionPricePolicyCount', v_subscription_policy_count,
      'subscriptionPricePolicyDerivesBand', v_subscription_policy_derives_band,
      'legacyFrozenCount', v_legacy_count,
      'legacyFrozenInvalidCount', v_legacy_invalid_count,
      'legacyFrozenFingerprint', v_legacy_fingerprint,
      'legacyFrozenBaselineCount', v_legacy_baseline_count,
      'legacyFrozenBaselineMatches', v_legacy_baseline_matches,
      'promotionWatchdogReady', v_watchdog_ready,
      'promotionClaimSweepReady', v_claim_sweep_ready,
      'automaticV2MoneyCheckedCount', v_automatic_v2_money_checked_count,
      'automaticV2MoneyMismatchCount', v_automatic_v2_money_mismatch_count
    )
  );
END;
$_$;


--
-- Name: FUNCTION commerce_offer_policy_v2_readiness(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_offer_policy_v2_readiness() IS 'Service-role-only fail-closed readiness for new offer-policy v2 assignments. Returns aggregate policy, price, health and legacy-frozen evidence without mutating or exposing customer records.';


--
-- Name: commerce_oms_admin_list_queue(integer, integer, text, text, text, text, text, text, text, text, text, boolean, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_admin_list_queue(p_page integer, p_page_size integer, p_search text, p_status text, p_mode text, p_payment_status text, p_fulfillment_status text, p_inventory_status text, p_accounting_status text, p_provider_ops_status text, p_attention_reason text, p_attention_only boolean, p_next_action text, p_from text, p_to text, p_sort text, p_include_withdrawn boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_page integer := greatest(coalesce(p_page, 1), 1);
  v_page_size integer := least(greatest(coalesce(p_page_size, 25), 1), 100);
  v_offset bigint;
  v_from timestamptz := NULL;
  v_to timestamptz := NULL;
  v_search text := NULL;
  v_search_text text := NULL;
  v_search_alnum text := NULL;
  v_search_digits text := NULL;
  v_has_search boolean := false;
  v_currency_count integer := 0;
  v_result jsonb;
BEGIN
  IF p_sort NOT IN ('created_desc', 'created_asc', 'updated_desc', 'updated_asc', 'attention_priority_desc') THEN
    RAISE EXCEPTION 'commerce_oms_queue_invalid_sort' USING ERRCODE = '22023';
  END IF;
  IF p_from IS NOT NULL AND btrim(p_from) <> '' THEN
    v_from := p_from::timestamptz;
  END IF;
  IF p_to IS NOT NULL AND btrim(p_to) <> '' THEN
    v_to := p_to::timestamptz;
  END IF;
  v_search := nullif(btrim(coalesce(p_search, '')), '');
  v_search_text := nullif(public.commerce_oms_normalize_search_text(v_search), '');
  v_search_alnum := nullif(public.commerce_oms_normalize_search_alnum(v_search), '');
  v_search_digits := nullif(public.commerce_oms_normalize_search_digits(v_search), '');
  v_has_search := v_search IS NOT NULL;
  v_offset := (v_page::bigint - 1) * v_page_size::bigint;

  SELECT summary.payload, summary.currency_count
    INTO v_result, v_currency_count
    FROM (
    WITH scoped_orders AS (
      SELECT orders.*
        FROM public.commerce_orders orders
       WHERE (p_status IS NULL OR orders.status = p_status)
         AND (p_mode IS NULL OR orders.mode = p_mode)
         -- Withdrawn checkout rows: the cancelled residue of a journey that was
         -- declined and retried on another method. Scoped here beside status and
         -- mode -- NOT in `filtered` with the eight operational filters -- so the
         -- summary counters, which read FROM operational upstream of `filtered`,
         -- and `totalCount`, which reads FROM filtered, agree about what exists.
         -- FAILS CLOSED: the captured-payment clause means a marker written in
         -- error can never hide an order that took money.
         AND (
           p_include_withdrawn
           OR NOT (
             orders.status = 'cancelled'
             AND (
               orders.metadata ? 'supersededByStableJourneyKey'
               OR orders.metadata ->> 'checkoutAbandoned' = 'checkout_journey_consumed'
             )
             AND NOT EXISTS (
               SELECT 1
                 FROM public.commerce_payments pay
                WHERE pay.order_id = orders.id
                  AND pay.status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed')
             )
           )
         )
    ),
    candidate_orders AS (
      SELECT orders.*,
             coalesce(search_match.score, 0) AS search_rank,
             CASE
               WHEN search_match.field IS NULL THEN NULL
               ELSE jsonb_build_object(
                 'field', search_match.field,
                 'label', search_match.label,
                 'valuePreview', search_match.value_preview
               )
             END AS search_match
        FROM scoped_orders orders
        LEFT JOIN public.clients clients ON clients.id = orders.client_id
        LEFT JOIN public.pets pets ON pets.id = orders.pet_id
        LEFT JOIN public.addresses shipping_addresses ON shipping_addresses.id = orders.shipping_address_id
        LEFT JOIN LATERAL (
          SELECT matches.field, matches.label, matches.value_preview, matches.score
            FROM (
              SELECT 'order_number'::text AS field,
                     'Order number'::text AS label,
                     coalesce(orders.order_number, orders.id::text)::text AS value_preview,
                     100 AS score
               WHERE v_has_search
                 AND v_search_alnum IS NOT NULL
                 AND public.commerce_oms_normalize_search_alnum(orders.order_number) = v_search_alnum

              UNION ALL
              SELECT 'order_number', 'Order number', coalesce(orders.order_number, orders.id::text), 96
               WHERE v_has_search
                 AND v_search_digits IS NOT NULL
                 AND public.commerce_oms_normalize_search_digits(orders.order_number) = v_search_digits

              UNION ALL
              SELECT 'order_number', 'Order number', coalesce(orders.order_number, orders.id::text), 90
               WHERE v_has_search
                 AND length(coalesce(v_search_alnum, '')) >= 2
                 AND public.commerce_oms_normalize_search_alnum(orders.order_number) LIKE v_search_alnum || '%'

              UNION ALL
              SELECT 'order_number', 'Order number', coalesce(orders.order_number, orders.id::text), 86
               WHERE v_has_search
                 AND length(coalesce(v_search_digits, '')) >= 2
                 AND public.commerce_oms_normalize_search_digits(orders.order_number) LIKE '%' || v_search_digits

              UNION ALL
              SELECT 'order_number', 'Order number', coalesce(orders.order_number, orders.id::text), 78
               WHERE v_has_search
                 AND length(coalesce(v_search_alnum, '')) >= 3
                 AND public.commerce_oms_normalize_search_alnum(orders.order_number) LIKE '%' || v_search_alnum || '%'

              UNION ALL
              SELECT 'order_id', 'Order ID', orders.id::text, 72
               WHERE v_has_search
                 AND length(coalesce(v_search_alnum, '')) >= 8
                 AND replace(orders.id::text, '-', '') LIKE v_search_alnum || '%'

              UNION ALL
              SELECT 'tracking', 'Tracking', (
                       SELECT refs.provider_tracking_id
                         FROM public.shipment_external_refs refs
                        WHERE refs.order_id = orders.id
                          AND refs.provider_tracking_id IS NOT NULL
                          AND public.commerce_oms_normalize_search_alnum(refs.provider_tracking_id) LIKE '%' || v_search_alnum || '%'
                        ORDER BY refs.active DESC, refs.updated_at DESC NULLS LAST, refs.created_at DESC NULLS LAST
                        LIMIT 1
                     ), 88
               WHERE v_has_search
                 AND length(coalesce(v_search_alnum, '')) >= 3
                 AND EXISTS (
                   SELECT 1
                     FROM public.shipment_external_refs refs
                    WHERE refs.order_id = orders.id
                      AND refs.provider_tracking_id IS NOT NULL
                      AND public.commerce_oms_normalize_search_alnum(refs.provider_tracking_id) LIKE '%' || v_search_alnum || '%'
                 )

              UNION ALL
              SELECT 'provider_order', 'Provider order', (
                       SELECT refs.provider_order_id
                         FROM public.omnipack_dispatch_refs refs
                        WHERE refs.order_id = orders.id
                          AND refs.provider_order_id IS NOT NULL
                          AND public.commerce_oms_normalize_search_alnum(refs.provider_order_id) LIKE '%' || v_search_alnum || '%'
                        ORDER BY refs.updated_at DESC NULLS LAST, refs.created_at DESC NULLS LAST
                        LIMIT 1
                     ), 87
               WHERE v_has_search
                 AND length(coalesce(v_search_alnum, '')) >= 3
                 AND EXISTS (
                   SELECT 1
                     FROM public.omnipack_dispatch_refs refs
                    WHERE refs.order_id = orders.id
                      AND refs.provider_order_id IS NOT NULL
                      AND public.commerce_oms_normalize_search_alnum(refs.provider_order_id) LIKE '%' || v_search_alnum || '%'
                 )

              UNION ALL
              SELECT 'invoice', 'Invoice', (
                       SELECT coalesce(invoice.invoice_ref, invoice.provider_invoice_number)
                         FROM public.accounting_invoices invoice
                        WHERE invoice.order_id = orders.id
                          AND (
                            public.commerce_oms_normalize_search_alnum(invoice.invoice_ref) LIKE '%' || v_search_alnum || '%'
                            OR public.commerce_oms_normalize_search_alnum(invoice.provider_invoice_number) LIKE '%' || v_search_alnum || '%'
                          )
                        ORDER BY invoice.updated_at DESC, invoice.id DESC
                        LIMIT 1
                     ), 86
               WHERE v_has_search
                 AND length(coalesce(v_search_alnum, '')) >= 3
                 AND EXISTS (
                   SELECT 1
                     FROM public.accounting_invoices invoice
                    WHERE invoice.order_id = orders.id
                      AND (
                        public.commerce_oms_normalize_search_alnum(invoice.invoice_ref) LIKE '%' || v_search_alnum || '%'
                        OR public.commerce_oms_normalize_search_alnum(invoice.provider_invoice_number) LIKE '%' || v_search_alnum || '%'
                      )
                 )

              UNION ALL
              SELECT 'payment', 'Payment', (
                       SELECT coalesce(intent.provider_payment_id, intent.payment_id::text)
                         FROM public.commerce_payment_intents intent
                        WHERE intent.order_id = orders.id
                          AND (
                            public.commerce_oms_normalize_search_alnum(intent.provider_payment_id) LIKE '%' || v_search_alnum || '%'
                            OR replace(intent.payment_id::text, '-', '') LIKE '%' || v_search_alnum || '%'
                          )
                        ORDER BY intent.updated_at DESC, intent.id DESC
                        LIMIT 1
                     ), 84
               WHERE v_has_search
                 AND length(coalesce(v_search_alnum, '')) >= 3
                 AND EXISTS (
                   SELECT 1
                     FROM public.commerce_payment_intents intent
                    WHERE intent.order_id = orders.id
                      AND (
                        public.commerce_oms_normalize_search_alnum(intent.provider_payment_id) LIKE '%' || v_search_alnum || '%'
                        OR replace(intent.payment_id::text, '-', '') LIKE '%' || v_search_alnum || '%'
                      )
                 )

              UNION ALL
              SELECT 'email', 'Email', public.commerce_oms_mask_email(clients.email), 74
               WHERE v_has_search
                 AND length(coalesce(v_search_text, '')) >= 3
                 AND public.commerce_oms_normalize_search_text(clients.email) LIKE '%' || v_search_text || '%'

              UNION ALL
              SELECT 'phone', 'Phone', public.commerce_oms_mask_phone(coalesce(clients.phone, shipping_addresses.contact_phone)), 72
               WHERE v_has_search
                 AND length(coalesce(v_search_digits, '')) >= 3
                 AND (
                   public.commerce_oms_normalize_search_digits(clients.phone) LIKE '%' || v_search_digits || '%'
                   OR public.commerce_oms_normalize_search_digits(shipping_addresses.contact_phone) LIKE '%' || v_search_digits || '%'
                 )

              UNION ALL
              SELECT 'customer', 'Customer', concat_ws(' ', clients.first_name, clients.last_name), 64
               WHERE v_has_search
                 AND length(coalesce(v_search_text, '')) >= 2
                 AND public.commerce_oms_normalize_search_text(concat_ws(' ', clients.first_name, clients.last_name)) LIKE '%' || v_search_text || '%'

              UNION ALL
              SELECT 'pet', 'Pet', pets.name, 58
               WHERE v_has_search
                 AND length(coalesce(v_search_text, '')) >= 2
                 AND public.commerce_oms_normalize_search_text(concat_ws(' ', pets.name, pets.breed, pets.pet_type)) LIKE '%' || v_search_text || '%'

              UNION ALL
              SELECT 'postal_code', 'Postal code', shipping_addresses.postal_code, 54
               WHERE v_has_search
                 AND length(coalesce(v_search_digits, '')) >= 2
                 AND public.commerce_oms_normalize_search_digits(shipping_addresses.postal_code) LIKE '%' || v_search_digits || '%'

              UNION ALL
              SELECT 'address', 'Address', concat_ws(', ', shipping_addresses.city, shipping_addresses.line1), 50
               WHERE v_has_search
                 AND length(coalesce(v_search_text, '')) >= 2
                 AND public.commerce_oms_normalize_search_text(concat_ws(' ', shipping_addresses.city, shipping_addresses.line1, shipping_addresses.line2, shipping_addresses.recipient_name, shipping_addresses.company_name)) LIKE '%' || v_search_text || '%'

              UNION ALL
              SELECT 'sku', 'SKU', (
                       SELECT coalesce(sku.sku, item.product_snapshot->>'sku', item.variant_snapshot->>'sku', item.product_snapshot->>'title', item.product_snapshot->>'name', sku.title, item.sku_id::text)
                         FROM public.commerce_order_items item
                         LEFT JOIN public.catalog_skus sku ON sku.id = item.sku_id
                        WHERE item.order_id = orders.id
                          AND (
                            public.commerce_oms_normalize_search_alnum(coalesce(sku.sku, item.product_snapshot->>'sku', item.variant_snapshot->>'sku', item.sku_id::text)) LIKE '%' || v_search_alnum || '%'
                            OR public.commerce_oms_normalize_search_text(coalesce(item.product_snapshot->>'title', item.product_snapshot->>'name', item.variant_snapshot->>'title', sku.title)) LIKE '%' || v_search_text || '%'
                          )
                        ORDER BY item.created_at ASC, item.id ASC
                        LIMIT 1
                     ), 46
               WHERE v_has_search
                 AND (
                   length(coalesce(v_search_alnum, '')) >= 2
                   OR length(coalesce(v_search_text, '')) >= 2
                 )
                 AND EXISTS (
                   SELECT 1
                     FROM public.commerce_order_items item
                     LEFT JOIN public.catalog_skus sku ON sku.id = item.sku_id
                    WHERE item.order_id = orders.id
                      AND (
                        public.commerce_oms_normalize_search_alnum(coalesce(sku.sku, item.product_snapshot->>'sku', item.variant_snapshot->>'sku', item.sku_id::text)) LIKE '%' || v_search_alnum || '%'
                        OR public.commerce_oms_normalize_search_text(coalesce(item.product_snapshot->>'title', item.product_snapshot->>'name', item.variant_snapshot->>'title', sku.title)) LIKE '%' || v_search_text || '%'
                      )
                 )
            ) matches
           ORDER BY matches.score DESC, matches.field ASC
           LIMIT 1
        ) search_match ON true
       WHERE v_has_search = false
          OR search_match.field IS NOT NULL
    ),
    base_orders AS (
      SELECT candidate_orders.*
        FROM candidate_orders
       WHERE (v_from IS NULL OR candidate_orders.created_at >= v_from)
         AND (v_to IS NULL OR candidate_orders.created_at <= v_to)
    ),
    latest_payment AS (
      SELECT ranked.order_id,
             CASE
               WHEN ranked.status IS NULL THEN 'not_started'
               WHEN ranked.status = 'pending' THEN 'processing'
               WHEN ranked.status = 'paid' THEN 'succeeded'
               ELSE ranked.status
             END AS payment_status
        FROM (
          SELECT payment.order_id,
                 payment.status,
                 row_number() OVER (
                   PARTITION BY payment.order_id
                   ORDER BY payment.updated_at DESC, payment.id DESC
                 ) AS rn
            FROM public.commerce_payment_intents payment
            JOIN base_orders orders ON orders.id = payment.order_id
        ) ranked
       WHERE ranked.rn = 1
    ),
    latest_summary_payment AS (
      SELECT ranked.order_id,
             CASE
               WHEN ranked.status IS NULL THEN 'not_started'
               WHEN ranked.status = 'pending' THEN 'processing'
               WHEN ranked.status = 'paid' THEN 'succeeded'
               ELSE ranked.status
             END AS payment_status,
             ranked.updated_at AS paid_at
        FROM (
          SELECT payment.order_id,
                 payment.status,
                 payment.updated_at,
                 row_number() OVER (
                   PARTITION BY payment.order_id
                   ORDER BY payment.updated_at DESC, payment.id DESC
                 ) AS rn
            FROM public.commerce_payment_intents payment
            JOIN candidate_orders orders ON orders.id = payment.order_id
           WHERE payment.status IN ('succeeded', 'paid')
        ) ranked
       WHERE ranked.rn = 1
    ),
    active_holds AS (
      SELECT hold_rows.order_id, count(*)::integer AS active_hold_count
        FROM public.commerce_order_holds hold_rows
        JOIN base_orders orders ON orders.id = hold_rows.order_id
       WHERE hold_rows.status = 'active'
       GROUP BY hold_rows.order_id
    ),
    item_quantities AS (
      SELECT items.order_id, items.id AS order_item_id, items.quantity
        FROM public.commerce_order_items items
        JOIN base_orders orders ON orders.id = items.order_id
    ),
    reservation_quantities AS (
      SELECT reservations.order_id,
             reservations.order_item_id,
             sum(
               CASE
                 WHEN reservations.status IN ('reserved', 'consumed') THEN reservations.quantity
                 ELSE 0
               END
             )::integer AS covered_quantity
        FROM public.inventory_reservations reservations
        JOIN base_orders orders ON orders.id = reservations.order_id
       GROUP BY reservations.order_id, reservations.order_item_id
    ),
    reservation_rollup AS (
      SELECT reservations.order_id,
             count(*) > 0 AS has_reservation,
             bool_or(reservations.status = 'reserved') AS has_reserved,
             bool_or(reservations.status = 'consumed') AS has_consumed,
             bool_or(reservations.status = 'expired') AS has_expired,
             bool_or(reservations.status = 'released') AS has_released
        FROM public.inventory_reservations reservations
        JOIN base_orders orders ON orders.id = reservations.order_id
       GROUP BY reservations.order_id
    ),
    inventory AS (
      SELECT orders.id AS order_id,
             CASE
               WHEN coalesce(rollup.has_reservation, false) = false THEN 'missing'
               WHEN EXISTS (
                 SELECT 1
                   FROM item_quantities item
                   LEFT JOIN reservation_quantities covered
                     ON covered.order_item_id = item.order_item_id
                    AND covered.order_id = item.order_id
                  WHERE item.order_id = orders.id
                    AND coalesce(covered.covered_quantity, 0) < item.quantity
               ) THEN 'missing'
               WHEN coalesce(rollup.has_consumed, false) = true
                    AND coalesce(rollup.has_reserved, false) = false THEN 'consumed'
               WHEN coalesce(rollup.has_reserved, false) = true THEN 'reserved'
               WHEN coalesce(rollup.has_expired, false) = true THEN 'expired'
               WHEN coalesce(rollup.has_released, false) = true THEN 'released'
               ELSE 'review_required'
             END AS inventory_status
        FROM base_orders orders
        LEFT JOIN reservation_rollup rollup ON rollup.order_id = orders.id
    ),
    latest_fulfillment AS (
      SELECT ranked.order_id,
             ranked.id AS fulfillment_order_id,
             ranked.provider_kind,
             ranked.status AS fulfillment_status
        FROM (
          SELECT fulfillment.order_id,
                 fulfillment.id,
                 fulfillment.provider_kind,
                 fulfillment.status,
                 row_number() OVER (
                   PARTITION BY fulfillment.order_id
                   ORDER BY fulfillment.updated_at DESC, fulfillment.id DESC
                 ) AS rn
            FROM public.commerce_fulfillment_orders fulfillment
            JOIN base_orders orders ON orders.id = fulfillment.order_id
        ) ranked
       WHERE ranked.rn = 1
    ),
    latest_omnipack_dispatch AS (
      SELECT ranked.fulfillment_order_id,
             ranked.provider_order_id,
             ranked.status,
             ranked.created_at,
             ranked.updated_at
        FROM (
          SELECT refs.fulfillment_order_id,
                 refs.provider_order_id,
                 refs.status,
                 refs.created_at,
                 refs.updated_at,
                 row_number() OVER (
                   PARTITION BY refs.fulfillment_order_id
                   ORDER BY refs.updated_at DESC NULLS LAST, refs.created_at DESC NULLS LAST, refs.id DESC
                 ) AS rn
            FROM public.omnipack_dispatch_refs refs
            JOIN latest_fulfillment fulfillment ON fulfillment.fulfillment_order_id = refs.fulfillment_order_id
        ) ranked
       WHERE ranked.rn = 1
    ),
    latest_omnipack_status AS (
      SELECT ranked.fulfillment_order_id,
             ranked.provider_status,
             ranked.local_status,
             ranked.occurred_at,
             ranked.created_at
        FROM (
          SELECT evidence.fulfillment_order_id,
                 evidence.provider_status,
                 evidence.local_status,
                 evidence.occurred_at,
                 evidence.created_at,
                 row_number() OVER (
                   PARTITION BY evidence.fulfillment_order_id
                   ORDER BY evidence.occurred_at DESC NULLS LAST, evidence.created_at DESC NULLS LAST, evidence.id DESC
                 ) AS rn
            FROM public.omnipack_status_evidence evidence
            JOIN latest_fulfillment fulfillment ON fulfillment.fulfillment_order_id = evidence.fulfillment_order_id
        ) ranked
       WHERE ranked.rn = 1
    ),
    provider_ops AS (
      SELECT orders.id AS order_id,
             CASE
               WHEN dispatch.status = 'failed' THEN 'omnipack_dispatch_failed'
               WHEN dispatch.status = 'created'
                    AND dispatch.provider_order_id IS NOT NULL
                    AND (
                      fulfillment.fulfillment_status = 'packed'
                      OR status.local_status = 'packed'
                    )
                    AND coalesce(fulfillment.fulfillment_status, '') NOT IN ('handed_over', 'in_transit', 'delivered')
                    AND coalesce(status.local_status, '') NOT IN ('in_transit', 'delivered')
                 THEN 'omnipack_picked_not_shipped'
               WHEN dispatch.status = 'created'
                    AND dispatch.provider_order_id IS NOT NULL
                    AND coalesce(fulfillment.fulfillment_status, '') NOT IN ('packed', 'handed_over', 'in_transit', 'delivered', 'cancelled', 'exception')
                    AND coalesce(status.local_status, '') NOT IN ('packed', 'in_transit', 'delivered')
                 THEN 'omnipack_dispatched_not_picked'
               ELSE 'none'
             END AS provider_ops_status
        FROM base_orders orders
        LEFT JOIN latest_fulfillment fulfillment ON fulfillment.order_id = orders.id
        LEFT JOIN latest_omnipack_dispatch dispatch ON dispatch.fulfillment_order_id = fulfillment.fulfillment_order_id
        LEFT JOIN latest_omnipack_status status ON status.fulfillment_order_id = fulfillment.fulfillment_order_id
    ),
    latest_invoice AS (
      SELECT ranked.order_id, ranked.id AS invoice_id, ranked.status AS invoice_status, ranked.blocked_reason
        FROM (
          SELECT invoice.order_id,
                 invoice.id,
                 invoice.status,
                 invoice.blocked_reason,
                 row_number() OVER (
                   PARTITION BY invoice.order_id
                   ORDER BY invoice.updated_at DESC, invoice.id DESC
                 ) AS rn
            FROM public.accounting_invoices invoice
            JOIN base_orders orders ON orders.id = invoice.order_id
        ) ranked
       WHERE ranked.rn = 1
    ),
    latest_outbox AS (
      SELECT ranked.invoice_id, ranked.status AS outbox_status
        FROM (
          SELECT outbox.invoice_id,
                 outbox.status,
                 row_number() OVER (
                   PARTITION BY outbox.invoice_id
                   ORDER BY outbox.created_at DESC, outbox.id DESC
                 ) AS rn
            FROM public.accounting_invoice_issue_outbox outbox
            JOIN latest_invoice invoice ON invoice.invoice_id = outbox.invoice_id
        ) ranked
       WHERE ranked.rn = 1
    ),
    accounting AS (
      SELECT orders.id AS order_id,
             CASE
               WHEN invoice.invoice_id IS NULL THEN 'missing'
               WHEN outbox.outbox_status = 'failed' THEN 'outbox_failed'
               WHEN invoice.blocked_reason IS NOT NULL OR invoice.invoice_status = 'blocked' THEN 'blocked'
               WHEN invoice.invoice_status IN (
                 'draft', 'issue_requested', 'issued', 'ksef_pending',
                 'accepted', 'rejected', 'correction_requested', 'corrected',
                 'voided'
               ) THEN invoice.invoice_status
               ELSE 'missing'
             END AS accounting_status
        FROM base_orders orders
        LEFT JOIN latest_invoice invoice ON invoice.order_id = orders.id
        LEFT JOIN latest_outbox outbox ON outbox.invoice_id = invoice.invoice_id
    ),
    derived AS (
      SELECT orders.id,
             orders.status AS order_status,
             orders.created_at,
             orders.updated_at,
             orders.search_rank,
             orders.search_match,
             coalesce(payment.payment_status, 'not_started') AS payment_status,
             coalesce(holds.active_hold_count, 0) AS active_hold_count,
             inventory.inventory_status,
             fulfillment.fulfillment_status,
             accounting.accounting_status,
             coalesce(provider_ops.provider_ops_status, 'none') AS provider_ops_status,
             CASE
               WHEN coalesce(holds.active_hold_count, 0) > 0 THEN false
               WHEN orders.shipping_address_id IS NULL THEN false
               WHEN orders.status NOT IN ('paid', 'fulfillment_pending', 'fulfilled') THEN false
               WHEN coalesce(payment.payment_status, 'not_started') <> 'succeeded' THEN false
               WHEN orders.mode = 'subscription_cycle'
                    AND coalesce(cycles.status, '') <> 'paid' THEN false
               WHEN inventory.inventory_status NOT IN ('reserved', 'consumed') THEN false
               ELSE true
             END AS fulfillment_allowed
        FROM base_orders orders
        LEFT JOIN latest_payment payment ON payment.order_id = orders.id
        LEFT JOIN active_holds holds ON holds.order_id = orders.id
        LEFT JOIN inventory ON inventory.order_id = orders.id
        LEFT JOIN latest_fulfillment fulfillment ON fulfillment.order_id = orders.id
        LEFT JOIN accounting ON accounting.order_id = orders.id
        LEFT JOIN provider_ops ON provider_ops.order_id = orders.id
        LEFT JOIN public.subscription_cycles cycles ON cycles.id = orders.subscription_cycle_id
    ),
    operational AS (
      SELECT derived.*,
             CASE
               WHEN order_status IN ('refunded', 'cancelled') THEN 'none'
               WHEN active_hold_count > 0 THEN 'active_hold'
               WHEN payment_status <> 'succeeded' THEN 'payment_required'
               WHEN EXISTS (
                 SELECT 1 FROM base_orders orders
                  WHERE orders.id = derived.id
                    AND orders.shipping_address_id IS NULL
               ) THEN 'missing_shipping_address'
               WHEN inventory_status NOT IN ('reserved', 'consumed') THEN 'inventory_missing'
               WHEN fulfillment_status IS NULL AND fulfillment_allowed = false THEN 'fulfillment_blocked'
               WHEN fulfillment_status IS NULL THEN 'fulfillment_pending'
               WHEN fulfillment_status IN ('created', 'packed', 'label_pending') THEN 'fulfillment_pending'
               WHEN fulfillment_status = 'label_created' THEN 'fulfillment_pending'
               WHEN fulfillment_status = 'exception' THEN 'fulfillment_exception'
               WHEN accounting_status = 'missing' THEN 'invoice_missing'
               WHEN accounting_status = 'blocked' THEN 'invoice_buyer_data_invalid'
               WHEN accounting_status IN ('rejected', 'outbox_failed') THEN 'invoice_issue_failed'
               ELSE 'none'
             END AS attention_reason,
             CASE
               WHEN order_status IN ('refunded', 'cancelled') THEN 'none'
               WHEN active_hold_count > 0 THEN 'release_hold'
               WHEN payment_status <> 'succeeded' THEN 'review_payment'
               WHEN EXISTS (
                 SELECT 1 FROM base_orders orders
                  WHERE orders.id = derived.id
                    AND orders.shipping_address_id IS NULL
               ) THEN 'review_address'
               WHEN inventory_status NOT IN ('reserved', 'consumed') THEN 'review_inventory'
               WHEN fulfillment_status IS NULL AND fulfillment_allowed = false THEN 'review_fulfillment'
               WHEN fulfillment_status IS NULL THEN 'create_fulfillment'
               WHEN fulfillment_status IN ('created', 'packed', 'label_pending') THEN 'record_label'
               WHEN fulfillment_status = 'label_created' THEN 'hand_off'
               WHEN fulfillment_status = 'exception' THEN 'review_tracking'
               WHEN accounting_status IN ('missing', 'blocked', 'rejected', 'outbox_failed') THEN 'review_invoice'
               ELSE 'none'
             END AS next_action
        FROM derived
    ),
    filtered AS (
      SELECT *
        FROM operational
       WHERE (p_payment_status IS NULL OR payment_status = p_payment_status)
         AND (p_fulfillment_status IS NULL OR fulfillment_status = p_fulfillment_status)
         AND (p_inventory_status IS NULL OR inventory_status = p_inventory_status)
         AND (p_accounting_status IS NULL OR accounting_status = p_accounting_status)
         AND (p_provider_ops_status IS NULL OR provider_ops_status = p_provider_ops_status)
         AND (p_attention_reason IS NULL OR attention_reason = p_attention_reason)
         AND (coalesce(p_attention_only, false) = false OR attention_reason <> 'none')
         AND (p_next_action IS NULL OR next_action = p_next_action)
    ),
    ranked AS (
      SELECT filtered.*,
             row_number() OVER (
               ORDER BY
                 CASE WHEN v_has_search THEN search_rank END DESC NULLS LAST,
                 CASE WHEN p_sort = 'attention_priority_desc' THEN
                   CASE attention_reason
                     WHEN 'active_hold' THEN 1
                     WHEN 'payment_required' THEN 2
                     WHEN 'missing_shipping_address' THEN 3
                     WHEN 'inventory_missing' THEN 4
                     WHEN 'fulfillment_blocked' THEN 5
                     WHEN 'fulfillment_exception' THEN 6
                     WHEN 'invoice_issue_failed' THEN 7
                     WHEN 'invoice_buyer_data_invalid' THEN 8
                     WHEN 'invoice_missing' THEN 9
                     WHEN 'fulfillment_pending' THEN 9
                     ELSE 99
                   END
                 END ASC NULLS LAST,
                 CASE WHEN p_sort = 'attention_priority_desc' THEN updated_at END DESC NULLS LAST,
                 CASE WHEN p_sort = 'created_asc' THEN created_at END ASC NULLS LAST,
                 CASE WHEN p_sort = 'created_desc' THEN created_at END DESC NULLS LAST,
                 CASE WHEN p_sort = 'updated_asc' THEN updated_at END ASC NULLS LAST,
                 CASE WHEN p_sort = 'updated_desc' THEN updated_at END DESC NULLS LAST,
                 id ASC
             ) AS rn
        FROM filtered
    ),
    paged AS (
      SELECT *
        FROM ranked
       WHERE rn > v_offset
         AND rn <= v_offset + v_page_size
       ORDER BY rn
    ),
    paid_summary AS (
      SELECT coalesce(sum(orders.total_cents)::bigint, 0) AS amount_minor,
             count(*)::integer AS order_count,
             count(DISTINCT orders.currency)::integer AS currency_count,
             min(orders.currency) AS currency,
             count(*) FILTER (
               WHERE orders.mode = 'subscription_cycle'
                 AND orders.subscription_id IS NOT NULL
             )::integer AS new_subscription_count
        FROM candidate_orders orders
        JOIN latest_summary_payment payment ON payment.order_id = orders.id
       WHERE payment.payment_status = 'succeeded'
         AND (v_from IS NULL OR payment.paid_at >= v_from)
         AND (v_to IS NULL OR payment.paid_at <= v_to)
    )
    SELECT jsonb_build_object(
      'orderIds',
      coalesce((SELECT jsonb_agg(id ORDER BY rn) FROM paged), '[]'::jsonb),
      'matches',
      coalesce((SELECT jsonb_object_agg(id::text, search_match ORDER BY rn) FROM paged WHERE search_match IS NOT NULL), '{}'::jsonb),
      'totalCount',
      (SELECT count(*) FROM filtered),
      'summaryCounts',
      jsonb_build_object(
        'needsAttention', (SELECT count(*) FROM operational WHERE attention_reason <> 'none'),
        'activeHold', (SELECT count(*) FROM operational WHERE active_hold_count > 0),
        'readyForFulfillment', (SELECT count(*) FROM operational WHERE next_action = 'create_fulfillment'),
        'paymentIssues', (SELECT count(*) FROM operational WHERE attention_reason = 'payment_required'),
        'inventoryRisk', (SELECT count(*) FROM operational WHERE attention_reason = 'inventory_missing'),
        'fulfillmentBlocked', (SELECT count(*) FROM operational WHERE attention_reason = 'fulfillment_blocked'),
        'fulfillmentExceptions', (SELECT count(*) FROM operational WHERE attention_reason = 'fulfillment_exception'),
        'invoiceIssues', (SELECT count(*) FROM operational WHERE next_action = 'review_invoice'),
        'omnipackDispatchedNotPicked', (SELECT count(*) FROM operational WHERE provider_ops_status = 'omnipack_dispatched_not_picked')
      ),
      'summaryTotals',
      jsonb_build_object(
        'gmv', jsonb_build_object(
          'amountMinor', (SELECT amount_minor FROM paid_summary),
          'currency', (SELECT currency FROM paid_summary)
        ),
        'aov', jsonb_build_object(
          'amountMinor',
          CASE
            WHEN (SELECT order_count FROM paid_summary) > 0
              THEN round((SELECT amount_minor FROM paid_summary)::numeric / (SELECT order_count FROM paid_summary))::bigint
            ELSE 0
          END,
          'currency', (SELECT currency FROM paid_summary)
        ),
        'orderCount', (SELECT order_count FROM paid_summary),
        'newSubscriptionCount', (SELECT new_subscription_count FROM paid_summary)
      )
    ) AS payload,
    (SELECT currency_count FROM paid_summary) AS currency_count
  ) AS summary;

  IF v_currency_count > 1 THEN
    RAISE EXCEPTION 'commerce_oms_summary_mixed_currency' USING ERRCODE = '22023';
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: FUNCTION commerce_oms_admin_list_queue(p_page integer, p_page_size integer, p_search text, p_status text, p_mode text, p_payment_status text, p_fulfillment_status text, p_inventory_status text, p_accounting_status text, p_provider_ops_status text, p_attention_reason text, p_attention_only boolean, p_next_action text, p_from text, p_to text, p_sort text, p_include_withdrawn boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_oms_admin_list_queue(p_page integer, p_page_size integer, p_search text, p_status text, p_mode text, p_payment_status text, p_fulfillment_status text, p_inventory_status text, p_accounting_status text, p_provider_ops_status text, p_attention_reason text, p_attention_only boolean, p_next_action text, p_from text, p_to text, p_sort text, p_include_withdrawn boolean) IS 'Admin OMS service-role read model for queue ids, derived filters, provider-ops buckets (classified on canonical local_status + fulfillment_status), ranked normalized search matches, global summary counts, and paid dashboard summary totals. Hides withdrawn checkout rows (cancelled + supersede/journey-consumed marker + no captured payment) in scoped_orders unless p_include_withdrawn, so counters and totalCount agree. Refuses with commerce_oms_summary_mixed_currency when the paid set spans more than one currency; reports a null summary currency for an empty paid set.';


--
-- Name: commerce_oms_cancel_unpaid_order(text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_cancel_unpaid_order(p_idempotency_key text, p_order_id uuid, p_reason text, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_guard_reason text;
BEGIN
  v_guard_reason := public.commerce_checkout_cancel_lock_guard(p_order_id);
  IF v_guard_reason = 'aggregate_changed' THEN
    RAISE EXCEPTION 'commerce_oms_cancel_unpaid_order_aggregate_changed'
      USING ERRCODE = '55000';
  END IF;
  IF v_guard_reason = 'provider_attempt_in_flight' THEN
    RAISE EXCEPTION 'commerce_oms_cancel_unpaid_order_payment_in_flight'
      USING ERRCODE = '23505';
  END IF;
  IF v_guard_reason IN ('payment_already_moved', 'payment_state_unknown') THEN
    RAISE EXCEPTION 'commerce_oms_cancel_unpaid_order_payment_already_moved'
      USING ERRCODE = '23505';
  END IF;
  RETURN public.commerce_oms_cancel_unpaid_order_sealed_v1(
    p_idempotency_key, p_order_id, p_reason, p_actor_user_id, p_metadata
  );
END;
$$;


--
-- Name: commerce_oms_cancel_unpaid_order_sealed_v1(text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_cancel_unpaid_order_sealed_v1(p_idempotency_key text, p_order_id uuid, p_reason text, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_existing_operation public.commerce_order_operations%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
     OR p_order_id IS NULL
     OR p_reason IS NULL OR length(btrim(p_reason)) = 0 THEN
    RAISE EXCEPTION 'commerce_oms_cancel_unpaid_order_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing_operation
    FROM public.commerce_order_operations
   WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing_operation.operation_type <> 'order_cancelled_manual'
      OR v_existing_operation.order_id IS DISTINCT FROM p_order_id
      OR v_existing_operation.payload->>'reason' IS DISTINCT FROM p_reason
    THEN
      RAISE EXCEPTION 'commerce_oms_cancel_unpaid_order_idempotency_conflict' USING ERRCODE = '23505';
    END IF;

    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'orderId', p_order_id,
      'status', 'cancelled',
      'replayed', true
    );
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_oms_cancel_unpaid_order_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_order.status = 'cancelled' THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'orderId', p_order_id,
      'status', 'cancelled',
      'replayed', true
    );
  END IF;

  IF v_order.status <> 'pending_payment' THEN
    RAISE EXCEPTION 'commerce_oms_cancel_unpaid_order_invalid_status' USING ERRCODE = '22023';
  END IF;

  -- Serialize against any concurrent payment application before deciding that
  -- money has not moved. A succeeded/disputed/refunded payment is never OMS
  -- cancellation territory.
  PERFORM 1
    FROM public.commerce_payment_intents
   WHERE order_id = p_order_id
   FOR UPDATE;

  IF EXISTS (
    SELECT 1
      FROM public.commerce_payment_intents
     WHERE order_id = p_order_id
       AND status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed')
  ) OR EXISTS (
    SELECT 1
      FROM public.commerce_payments
     WHERE order_id = p_order_id
       AND status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed')
  ) THEN
    RAISE EXCEPTION 'commerce_oms_cancel_unpaid_order_payment_already_moved' USING ERRCODE = '23505';
  END IF;

  UPDATE public.commerce_payment_intents
     SET status = 'cancelled',
         failure_reason = 'admin_oms_cancelled_unpaid_order',
         metadata = metadata || jsonb_build_object(
           'paymentStatus', 'cancelled',
           'source', 'commerce.oms.v0'
         ),
         updated_at = now()
   WHERE order_id = p_order_id
     AND status NOT IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed');

  UPDATE public.commerce_payment_attempts
     SET status = 'cancelled',
         failure_reason = 'admin_oms_cancelled_unpaid_order',
         updated_at = now()
   WHERE payment_intent_id IN (
     SELECT id FROM public.commerce_payment_intents WHERE order_id = p_order_id
   )
     AND status NOT IN ('succeeded', 'cancelled', 'failed', 'expired');

  UPDATE public.commerce_payments
     SET status = 'cancelled',
         metadata = metadata || jsonb_build_object(
           'paymentStatus', 'cancelled',
           'source', 'commerce.oms.v0'
         ),
         updated_at = now()
   WHERE order_id = p_order_id
     AND status NOT IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed');

  UPDATE public.commerce_orders
     SET status = 'cancelled',
         metadata = metadata || jsonb_build_object(
           'paymentStatus', 'cancelled',
           'source', 'admin_oms_cancel_unpaid_order',
           'manualOrderCancellation', jsonb_build_object(
             'reason', p_reason,
             'actorUserId', p_actor_user_id,
             'cancelledAt', now()
           )
         ),
         updated_at = now()
   WHERE id = p_order_id;

  INSERT INTO public.commerce_order_operations (
    order_id, actor_user_id, operation_type, idempotency_key, payload
  )
  VALUES (
    p_order_id, p_actor_user_id, 'order_cancelled_manual', p_idempotency_key,
    jsonb_build_object(
      'reason', p_reason,
      'metadata', coalesce(p_metadata, '{}'::jsonb),
      'source', 'commerce.oms.v0'
    )
  );

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'orderId', p_order_id,
    'status', 'cancelled',
    'replayed', false
  );
END;
$$;


--
-- Name: commerce_oms_close_holds_on_closed_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_close_holds_on_closed_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_hold public.commerce_order_holds%ROWTYPE;
BEGIN
  FOR v_hold IN
    SELECT * FROM public.commerce_order_holds
     WHERE order_id = NEW.id
       AND status = 'active'
       AND created_by IS NULL
     ORDER BY id
  LOOP
    PERFORM public.commerce_oms_release_hold_closed_order(
      'order-closed:' || v_hold.id::text,
      v_hold.id,
      jsonb_build_object('closedOrderStatus', NEW.status)
    );
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_oms_close_holds_on_closed_order(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_oms_close_holds_on_closed_order() IS 'Trigger body: closes every machine-placed active hold on an order that has just moved to a closed status. One place, so a future closing writer inherits it.';


--
-- Name: commerce_oms_create_hold(text, uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_create_hold(p_idempotency_key text, p_order_id uuid, p_reason text, p_note text, p_actor_user_id uuid, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.oms.hold.create';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_hold public.commerce_order_holds%ROWTYPE;
  v_operation public.commerce_order_operations%ROWTYPE;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_order_id IS NULL
    OR p_actor_user_id IS NULL
    OR p_reason NOT IN (
      'payment_not_succeeded',
      'inventory_review',
      'risk_review',
      'address_review',
      'fulfillment_exception',
      'manual_support'
    )
  THEN
    RAISE EXCEPTION 'commerce_oms_hold_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    p_order_id::text || '|' ||
    p_reason || '|' ||
    COALESCE(p_note, '') || '|' ||
    p_actor_user_id::text || '|' ||
    COALESCE(p_metadata, '{}'::jsonb)::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'commerce_oms_hold_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_oms_hold_order_not_found' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'commerce_oms_create_hold')
  );

  INSERT INTO public.commerce_order_holds (
    order_id,
    created_by,
    reason,
    note,
    idempotency_key,
    metadata
  )
  VALUES (
    p_order_id,
    p_actor_user_id,
    p_reason,
    p_note,
    p_idempotency_key,
    COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('source', 'commerce.oms.v0')
  )
  RETURNING * INTO v_hold;

  INSERT INTO public.commerce_order_operations (
    order_id,
    hold_id,
    actor_user_id,
    operation_type,
    idempotency_key,
    payload
  )
  VALUES (
    p_order_id,
    v_hold.id,
    p_actor_user_id,
    'hold_created',
    p_idempotency_key || ':operation',
    jsonb_build_object(
      'reason', p_reason,
      'note', p_note,
      'source', 'commerce.oms.v0'
    )
  )
  RETURNING * INTO v_operation;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'hold', jsonb_build_object(
      'id', v_hold.id,
      'orderId', v_hold.order_id,
      'status', v_hold.status,
      'reason', v_hold.reason,
      'note', v_hold.note,
      'createdAt', v_hold.created_at,
      'releasedAt', v_hold.released_at
    ),
    'operationId', v_operation.id,
    'replayed', false
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('holdId', v_hold.id, 'operationId', v_operation.id)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: commerce_oms_healable_provider_exception_holds(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_healable_provider_exception_holds(p_fulfillment_order_id uuid DEFAULT NULL::uuid) RETURNS TABLE(hold_id uuid, order_id uuid, fulfillment_order_id uuid, cleared_evidence_id uuid, cleared_provider_status text, cleared_provider_sub_status text, cleared_occurred_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT
    h.id,
    h.order_id,
    f.id,
    e.id,
    regexp_replace(lower(btrim(e.provider_status)), '[\s_-]+', '_', 'g'),
    e.provider_sub_status,
    e.occurred_at
  FROM public.commerce_order_holds h
  JOIN public.commerce_orders o
    ON o.id = h.order_id
  JOIN public.commerce_fulfillment_orders f
    ON f.order_id = h.order_id
  -- Newest exception evidence for this fulfilment order is live truth. The hold's
  -- own stored reason is not: a hold created for 'suspended' can absorb a later
  -- returned_to_sender occurrence and still read 'SUSPENDED'.
  CROSS JOIN LATERAL (
    SELECT ev.id, ev.provider_status, ev.provider_sub_status, ev.occurred_at
      FROM public.omnipack_status_evidence ev
     WHERE ev.fulfillment_order_id = f.id
       AND ev.local_status = 'exception'
     ORDER BY ev.occurred_at DESC NULLS LAST, ev.created_at DESC
     LIMIT 1
  ) e
  WHERE h.status = 'active'
    AND h.reason = 'fulfillment_exception'
    -- The one field that separates this from the split-shipment preflight hold.
    AND h.metadata->>'source' = 'commerce.fulfillment.omnipack_provider_exception'
    -- metadata is caller-supplied and therefore forgeable; created_by is not.
    -- commerce_oms_create_hold hard-requires an actor, so every human hold has a
    -- non-null created_by and can never be caught here.
    AND h.created_by IS NULL
    -- Delivery/recovery proof is semantically inapplicable to a terminal order;
    -- auto-releasing there would assert something that never happened.
    AND o.status NOT IN ('cancelled', 'refunded')
    AND (p_fulfillment_order_id IS NULL OR f.id = p_fulfillment_order_id)
    AND (
      h.metadata->>'fulfillmentOrderId' IS NULL
      OR h.metadata->>'fulfillmentOrderId' = f.id::text
    )
    -- One hold, one candidate. Among the fulfilment rows this hold may speak for
    -- -- which is the single pinned row when its metadata names one, and every
    -- row of the order when it does not -- only the one that currently
    -- represents the order is a candidate. With one row this is that row.
    AND f.id = (
      SELECT x.id
        FROM public.commerce_fulfillment_orders x
       WHERE x.order_id = h.order_id
         AND (p_fulfillment_order_id IS NULL OR x.id = p_fulfillment_order_id)
         AND (
           h.metadata->>'fulfillmentOrderId' IS NULL
           OR h.metadata->>'fulfillmentOrderId' = x.id::text
         )
       ORDER BY x.sequence_no DESC, x.id DESC
       LIMIT 1
    )
    -- An exception we cannot place in time cannot be proven cleared.
    AND e.occurred_at IS NOT NULL
    -- Only these two clear on their own. cancelled / returned_to_sender carry
    -- refund and returns implications -- a human closes those.
    AND regexp_replace(lower(btrim(e.provider_status)), '[\s_-]+', '_', 'g')
        IN ('suspended', 'shipping_failed')
$$;


--
-- Name: FUNCTION commerce_oms_healable_provider_exception_holds(p_fulfillment_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_oms_healable_provider_exception_holds(p_fulfillment_order_id uuid) IS 'Single source of truth for which OmniPack provider-exception holds are eligible for automatic release; consumed by the heal trigger and the backfill script.';


--
-- Name: commerce_oms_mask_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_mask_email(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH parts AS (
    SELECT btrim(coalesce(p_value, '')) AS email
  )
  SELECT CASE
    WHEN email = '' THEN NULL
    WHEN position('@' IN email) <= 1 THEN '[redacted]'
    ELSE left(split_part(email, '@', 1), CASE WHEN length(split_part(email, '@', 1)) > 1 THEN 2 ELSE 1 END)
      || '***@'
      || split_part(email, '@', 2)
  END
  FROM parts;
$$;


--
-- Name: commerce_oms_mask_phone(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_mask_phone(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH digits AS (
    SELECT public.commerce_oms_normalize_search_digits(p_value) AS phone
  )
  SELECT CASE
    WHEN phone = '' THEN NULL
    ELSE '***' || right(phone, least(length(phone), 3))
  END
  FROM digits;
$$;


--
-- Name: commerce_oms_normalize_search_alnum(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_normalize_search_alnum(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT regexp_replace(public.commerce_oms_normalize_search_text(p_value), '[^a-z0-9]+', '', 'g');
$$;


--
-- Name: commerce_oms_normalize_search_digits(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_normalize_search_digits(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT regexp_replace(coalesce(p_value, ''), '[^0-9]+', '', 'g');
$$;


--
-- Name: commerce_oms_normalize_search_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_normalize_search_text(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
  SELECT regexp_replace(
    regexp_replace(
      translate(lower(coalesce(p_value, '')), 'ąćęłńóśźż', 'acelnoszz'),
      '[^a-z0-9]+',
      ' ',
      'g'
    ),
    '^[[:space:]]+|[[:space:]]+$',
    '',
    'g'
  );
$_$;


--
-- Name: commerce_oms_release_hold(text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_release_hold(p_idempotency_key text, p_hold_id uuid, p_note text, p_actor_user_id uuid, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.oms.hold.release';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_hold public.commerce_order_holds%ROWTYPE;
  v_operation public.commerce_order_operations%ROWTYPE;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_hold_id IS NULL
    OR p_actor_user_id IS NULL
  THEN
    RAISE EXCEPTION 'commerce_oms_release_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    p_hold_id::text || '|' ||
    COALESCE(p_note, '') || '|' ||
    p_actor_user_id::text || '|' ||
    COALESCE(p_metadata, '{}'::jsonb)::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'commerce_oms_release_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_hold
    FROM public.commerce_order_holds
   WHERE id = p_hold_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_oms_release_hold_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_hold.status <> 'active' THEN
    RAISE EXCEPTION 'commerce_oms_hold_already_released' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'commerce_oms_release_hold')
  );

  UPDATE public.commerce_order_holds
     SET status = 'released',
         released_at = now(),
         released_by = p_actor_user_id,
         updated_at = now(),
         metadata = metadata || COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('releaseNote', p_note)
   WHERE id = p_hold_id
  RETURNING * INTO v_hold;

  INSERT INTO public.commerce_order_operations (
    order_id,
    hold_id,
    actor_user_id,
    operation_type,
    idempotency_key,
    payload
  )
  VALUES (
    v_hold.order_id,
    v_hold.id,
    p_actor_user_id,
    'hold_released',
    p_idempotency_key || ':operation',
    jsonb_build_object(
      'reason', v_hold.reason,
      'note', p_note,
      'source', 'commerce.oms.v0'
    )
  )
  RETURNING * INTO v_operation;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'hold', jsonb_build_object(
      'id', v_hold.id,
      'orderId', v_hold.order_id,
      'status', v_hold.status,
      'reason', v_hold.reason,
      'note', v_hold.note,
      'createdAt', v_hold.created_at,
      'releasedAt', v_hold.released_at
    ),
    'operationId', v_operation.id,
    'replayed', false
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('holdId', v_hold.id, 'operationId', v_operation.id)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: commerce_oms_release_hold_closed_order(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_release_hold_closed_order(p_idempotency_key text, p_hold_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_hold public.commerce_order_holds%ROWTYPE;
  v_operation public.commerce_order_operations%ROWTYPE;
  v_order_status text;
  v_payload jsonb;
  v_source constant text := 'commerce.order.terminal_closure';
  v_proof constant text := 'order_closed';
BEGIN
  IF p_idempotency_key IS NULL
    OR length(btrim(p_idempotency_key)) < 8
    OR p_hold_id IS NULL
  THEN
    RAISE EXCEPTION 'commerce_oms_closed_order_release_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_hold
    FROM public.commerce_order_holds
   WHERE id = p_hold_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_oms_release_hold_not_found' USING ERRCODE = '22023';
  END IF;

  -- Scope lives HERE, in the body, and no argument can widen it. The order
  -- status is re-read at execution time rather than trusted from a trigger's
  -- NEW row, so a direct service_role call is held to the same three facts.
  SELECT status INTO v_order_status
    FROM public.commerce_orders
   WHERE id = v_hold.order_id;

  IF v_hold.created_by IS NOT NULL
    OR v_order_status IS NULL
    OR v_order_status NOT IN ('cancelled', 'refunded')
  THEN
    RAISE EXCEPTION 'commerce_oms_closed_order_release_scope_forbidden' USING ERRCODE = '22023';
  END IF;

  -- Already released: report a replay rather than raising. This runs inside the
  -- closing transaction and must never abort the cancellation that triggered it.
  IF v_hold.status <> 'active' THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.oms.v0',
      'holdId', v_hold.id,
      'released', false,
      'replayed', true
    );
  END IF;

  v_payload := COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object(
    'autoReleased', true,
    'autoReleaseSource', v_source,
    'autoReleaseProof', v_proof,
    'autoReleasedAt', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );

  -- The operation row is the idempotency ledger and the attribution record.
  -- commerce_idempotency_keys is unusable for a system actor: its fingerprint
  -- folds actor::text, which is NULL here and would disable deduplication.
  INSERT INTO public.commerce_order_operations (
    order_id, hold_id, actor_user_id, operation_type, source, idempotency_key, payload
  )
  VALUES (
    v_hold.order_id,
    v_hold.id,
    NULL,
    'hold_released',
    v_source,
    p_idempotency_key || ':operation',
    v_payload
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING * INTO v_operation;

  IF NOT FOUND THEN
    SELECT * INTO v_operation
      FROM public.commerce_order_operations
     WHERE idempotency_key = p_idempotency_key || ':operation';
    IF NOT FOUND OR v_operation.hold_id IS DISTINCT FROM p_hold_id THEN
      RAISE EXCEPTION 'commerce_oms_closed_order_release_idempotency_mismatch' USING ERRCODE = '22023';
    END IF;
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.oms.v0',
      'holdId', v_hold.id,
      'released', false,
      'replayed', true
    );
  END IF;

  UPDATE public.commerce_order_holds
     SET status = 'released',
         released_at = now(),
         released_by = NULL,
         updated_at = now(),
         metadata = metadata || v_payload
   WHERE id = v_hold.id;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.oms.v0',
    'holdId', v_hold.id,
    'released', true,
    'replayed', false
  );
END;
$$;


--
-- Name: FUNCTION commerce_oms_release_hold_closed_order(p_idempotency_key text, p_hold_id uuid, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_oms_release_hold_closed_order(p_idempotency_key text, p_hold_id uuid, p_metadata jsonb) IS 'Closes a machine-placed hold (created_by NULL) with a system actor once the order it guards is cancelled or refunded; scope is fixed in the body and no argument can widen it, so it can never release a hold a human placed.';


--
-- Name: commerce_oms_release_hold_system(text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_release_hold_system(p_idempotency_key text, p_hold_id uuid, p_source text, p_proof text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_hold public.commerce_order_holds%ROWTYPE;
  v_operation public.commerce_order_operations%ROWTYPE;
  v_payload jsonb;
BEGIN
  IF p_idempotency_key IS NULL
    OR length(btrim(p_idempotency_key)) < 8
    OR p_hold_id IS NULL
  THEN
    RAISE EXCEPTION 'commerce_oms_system_release_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- Fail closed on an allowlist so this never degrades into a generic bypass of
  -- the actor requirement.
  IF p_source IS NULL OR p_source NOT IN (
    'commerce.fulfillment.omnipack_provider_exception_healed',
    'commerce.fulfillment.provider_exception_backfill'
  ) THEN
    RAISE EXCEPTION 'commerce_oms_system_release_source_forbidden' USING ERRCODE = '22023';
  END IF;

  IF p_proof IS NULL OR p_proof NOT IN ('delivered', 'provider_recovered') THEN
    RAISE EXCEPTION 'commerce_oms_system_release_proof_forbidden' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_hold
    FROM public.commerce_order_holds
   WHERE id = p_hold_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_oms_release_hold_not_found' USING ERRCODE = '22023';
  END IF;

  -- Defence in depth: the trigger already filters through the shared predicate,
  -- but a direct service_role call must not be able to reach a human hold.
  -- IS DISTINCT FROM, not <>, so a missing metadata source fails closed.
  IF v_hold.reason IS DISTINCT FROM 'fulfillment_exception'
    OR v_hold.metadata->>'source' IS DISTINCT FROM 'commerce.fulfillment.omnipack_provider_exception'
    OR v_hold.created_by IS NOT NULL
  THEN
    RAISE EXCEPTION 'commerce_oms_system_release_scope_forbidden' USING ERRCODE = '22023';
  END IF;

  -- Already released: report a replay instead of raising. This runs inside the
  -- provider ingestion transaction and must never abort a provider write. This
  -- is also what makes the webhook/reconciliation race a no-op — the loser's
  -- FOR UPDATE returns the already-released row.
  IF v_hold.status <> 'active' THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.oms.v0',
      'holdId', v_hold.id,
      'released', false,
      'replayed', true
    );
  END IF;

  v_payload := COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object(
    'autoReleased', true,
    'autoReleaseSource', p_source,
    'autoReleaseProof', p_proof,
    'autoReleasedAt', to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
  );

  -- The operation row is the idempotency ledger. commerce_idempotency_keys is
  -- unusable here: its fingerprint is md5(... || actor::text ...), which is NULL
  -- for a system actor and would silently disable deduplication.
  INSERT INTO public.commerce_order_operations (
    order_id, hold_id, actor_user_id, operation_type, source, idempotency_key, payload
  )
  VALUES (
    v_hold.order_id,
    v_hold.id,
    NULL,
    'hold_released',
    p_source,
    p_idempotency_key || ':operation',
    v_payload
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING * INTO v_operation;

  IF NOT FOUND THEN
    SELECT * INTO v_operation
      FROM public.commerce_order_operations
     WHERE idempotency_key = p_idempotency_key || ':operation';
    IF NOT FOUND OR v_operation.hold_id IS DISTINCT FROM p_hold_id THEN
      RAISE EXCEPTION 'commerce_oms_system_release_idempotency_mismatch' USING ERRCODE = '22023';
    END IF;
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.oms.v0',
      'holdId', v_hold.id,
      'released', false,
      'replayed', true
    );
  END IF;

  UPDATE public.commerce_order_holds
     SET status = 'released',
         released_at = now(),
         released_by = NULL,
         updated_at = now(),
         metadata = metadata || v_payload
   WHERE id = v_hold.id;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.oms.v0',
    'holdId', v_hold.id,
    'released', true,
    'replayed', false
  );
END;
$$;


--
-- Name: FUNCTION commerce_oms_release_hold_system(p_idempotency_key text, p_hold_id uuid, p_source text, p_proof text, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_oms_release_hold_system(p_idempotency_key text, p_hold_id uuid, p_source text, p_proof text, p_metadata jsonb) IS 'Releases an automatically-created OmniPack provider-exception hold with a system actor (released_by NULL) once its cause is proven cleared; source-allowlisted and scope-guarded so it cannot release human holds.';


--
-- Name: commerce_oms_request_replacement_shipment(text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_request_replacement_shipment(p_idempotency_key text, p_order_id uuid, p_reason text, p_actor_user_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_scope constant text := 'commerce.oms.replacement_shipment.request';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_predecessor public.commerce_fulfillment_orders%ROWTYPE;
  v_client public.clients%ROWTYPE;
  v_address public.addresses%ROWTYPE;
  v_legacy_contact jsonb;
  v_contact_resolution jsonb;
  v_blocking_reason text;
  v_released_hold_ids uuid[] := ARRAY[]::uuid[];
  v_primary_hold_id uuid;
  v_payment_intent_id uuid;
  v_subscription_status text;
  v_provider_kind text;
  v_item record;
  v_reservation_key text;
  v_sequence_no smallint;
  v_fulfillment_id uuid;
  v_latest_fulfillment_id uuid;
  v_operation public.commerce_order_operations%ROWTYPE;
  v_payload jsonb;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = ''
    OR length(p_idempotency_key) < 8 OR p_order_id IS NULL
    OR p_actor_user_id IS NULL OR p_reason IS NULL
    OR p_reason NOT IN ('damaged', 'lost', 'returned_undelivered', 'other')
  THEN
    RAISE EXCEPTION 'commerce_oms_replacement_invalid_input' USING ERRCODE = '22023';
  END IF;
  v_request_fingerprint := md5(
    p_order_id::text || '|' || p_reason || '|' || p_actor_user_id::text || '|' ||
    coalesce(p_metadata, '{}'::jsonb)::text
  );

  SELECT * INTO v_existing FROM public.commerce_idempotency_keys
   WHERE scope = v_scope AND idempotency_key = p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{replayed}', 'true'::jsonb, false);
    END IF;
    RAISE EXCEPTION 'commerce_oms_replacement_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'commerce-order-delivery|' || p_order_id::text,
    0
  ));

  SELECT * INTO v_order FROM public.commerce_orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_oms_replacement_order_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_predecessor FROM public.commerce_fulfillment_orders
   WHERE order_id = p_order_id
   ORDER BY sequence_no DESC, id DESC
   LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_oms_replacement_no_parcel_to_replace' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'omnipack-dispatch|' || v_predecessor.id::text,
    0
  ));
  SELECT * INTO v_predecessor
    FROM public.commerce_fulfillment_orders
   WHERE id = v_predecessor.id
   FOR UPDATE;
  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  SELECT id INTO v_latest_fulfillment_id
    FROM public.commerce_fulfillment_orders
   WHERE order_id = p_order_id
   ORDER BY sequence_no DESC, id DESC
   LIMIT 1;
  IF v_order.id IS NULL
    OR v_predecessor.order_id IS DISTINCT FROM v_order.id
    OR v_latest_fulfillment_id IS DISTINCT FROM v_predecessor.id
  THEN
    RAISE EXCEPTION 'commerce_oms_replacement_stale_parcel' USING ERRCODE = '40001';
  END IF;

  IF v_order.status NOT IN ('paid', 'fulfillment_pending', 'fulfilled') THEN
    RAISE EXCEPTION 'commerce_oms_replacement_order_not_replaceable' USING ERRCODE = '22023';
  END IF;
  IF v_order.client_id IS NULL THEN
    RAISE EXCEPTION 'commerce_oms_replacement_missing_client' USING ERRCODE = '22023';
  END IF;
  IF v_order.shipping_address_id IS NULL THEN
    RAISE EXCEPTION 'commerce_oms_replacement_missing_shipping_address' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_payment_intent_id FROM public.commerce_payment_intents
   WHERE order_id = p_order_id AND status = 'succeeded' LIMIT 1;
  IF v_payment_intent_id IS NULL THEN
    RAISE EXCEPTION 'commerce_oms_replacement_payment_not_succeeded' USING ERRCODE = '22023';
  END IF;
  IF v_order.mode = 'subscription_cycle' THEN
    SELECT status INTO v_subscription_status FROM public.subscription_cycles
     WHERE id = v_order.subscription_cycle_id;
    IF v_subscription_status IS DISTINCT FROM 'paid' THEN
      RAISE EXCEPTION 'commerce_oms_replacement_subscription_cycle_not_paid' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF coalesce(v_predecessor.shipping_address_snapshot, '{}'::jsonb) ? 'deliveryContact' THEN
    IF jsonb_typeof(v_predecessor.shipping_address_snapshot->'deliveryContact') IS DISTINCT FROM 'object'
      OR v_predecessor.shipping_address_snapshot #>> '{deliveryContact,schemaVersion}' IS DISTINCT FROM '1'
      OR coalesce(v_predecessor.shipping_address_snapshot #>> '{deliveryContact,revision}', '') !~ '^[1-9][0-9]*$'
      OR nullif(btrim(v_predecessor.shipping_address_snapshot #>> '{deliveryContact,source}'), '') IS NULL
      OR nullif(btrim(v_predecessor.shipping_address_snapshot #>> '{deliveryContact,recipientName}'), '') IS NULL
      OR nullif(btrim(v_predecessor.shipping_address_snapshot #>> '{deliveryContact,contactPhone}'), '') IS NULL
      OR nullif(btrim(v_predecessor.shipping_address_snapshot #>> '{deliveryContact,line1}'), '') IS NULL
      OR nullif(btrim(v_predecessor.shipping_address_snapshot #>> '{deliveryContact,city}'), '') IS NULL
      OR nullif(btrim(v_predecessor.shipping_address_snapshot #>> '{deliveryContact,postalCode}'), '') IS NULL
      OR nullif(btrim(v_predecessor.shipping_address_snapshot #>> '{deliveryContact,country}'), '') IS NULL
    THEN
      RAISE EXCEPTION 'commerce_oms_replacement_delivery_contact_invalid' USING ERRCODE = '22023';
    END IF;
  ELSE
    -- See `omnipack_record_dispatch_ref_v2` for the same reasoning: the two
    -- new-format markers stay refused, `channelOrderSnapshot` does not. A
    -- marketplace order is not a second-class order, and refusing here left its
    -- parcels not merely undispatchable but unreplaceable.
    IF coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride'
      OR coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact'
    THEN
      RAISE EXCEPTION 'commerce_oms_replacement_delivery_contact_invalid' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_client FROM public.clients WHERE id = v_predecessor.client_id;
    SELECT * INTO v_address FROM public.addresses WHERE id = v_predecessor.shipping_address_id;
    -- The resolver is the only channel/profile inference authority. The
    -- surrounding branch keeps the predecessor lock and named order fences.
    v_contact_resolution := private.commerce_delivery_contact_resolve_v1(jsonb_build_object(
      'frozenContactPresent', false,
      'frozenContact', NULL,
      'orderCanonicalPresent', false,
      'channelOrderSnapshot', v_order.metadata->'channelOrderSnapshot',
      'selectedDeliveryCandidates', jsonb_build_array(
        v_predecessor.metadata->'selectedDelivery',
        v_order.metadata->'selectedDelivery',
        v_order.metadata #> '{runtimeFinalize,selectedDelivery}',
        v_predecessor.shipping_address_snapshot->'selectedDelivery',
        v_address.metadata->'selectedDelivery'
      ),
      'recipientCandidates', jsonb_build_array(
        v_predecessor.shipping_address_snapshot->>'recipientName',
        concat_ws(' ', v_client.first_name, v_client.last_name),
        v_predecessor.shipping_address_snapshot->>'label'
      ),
      'phoneCandidates', jsonb_build_array(
        v_predecessor.shipping_address_snapshot->>'contactPhone',
        v_address.contact_phone,
        v_client.phone
      ),
      'legacyClientEmail', v_client.email,
      'line1', v_predecessor.shipping_address_snapshot->>'line1',
      'line2', v_predecessor.shipping_address_snapshot->>'line2',
      'city', v_predecessor.shipping_address_snapshot->>'city',
      'postalCode', v_predecessor.shipping_address_snapshot->>'postalCode',
      'country', v_predecessor.shipping_address_snapshot->>'country',
      'deliveryInstructions', v_predecessor.shipping_address_snapshot->>'deliveryNotes',
      'courierInstructions', v_predecessor.shipping_address_snapshot->>'courierInstructions'
    ));
    v_legacy_contact := v_contact_resolution->'contact';
    IF NOT coalesce((v_contact_resolution->>'destinationComplete')::boolean, false) THEN
      RAISE EXCEPTION 'commerce_oms_replacement_delivery_contact_invalid' USING ERRCODE = '22023';
    END IF;
    UPDATE public.commerce_fulfillment_orders
       SET shipping_address_snapshot = shipping_address_snapshot || jsonb_build_object(
             'deliveryContact', v_legacy_contact,
             'selectedDelivery', v_legacy_contact->'selectedDelivery'
           ),
           updated_at = now()
     WHERE id = v_predecessor.id
     RETURNING * INTO v_predecessor;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.commerce_fulfillment_orders
     WHERE order_id = p_order_id AND sequence_no > 0
       AND status IN ('created', 'label_pending')
  ) THEN
    RAISE EXCEPTION 'commerce_oms_replacement_undispatched_replacement_exists' USING ERRCODE = '22023';
  END IF;

  SELECT reason INTO v_blocking_reason FROM public.commerce_order_holds
   WHERE order_id = p_order_id AND status = 'active'
     AND reason <> 'fulfillment_exception'
   ORDER BY created_at, id LIMIT 1 FOR UPDATE;
  IF v_blocking_reason IS NOT NULL THEN
    RAISE EXCEPTION 'commerce_oms_replacement_blocked_by_%_hold', v_blocking_reason
      USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.commerce_order_items WHERE order_id = p_order_id) THEN
    RAISE EXCEPTION 'commerce_oms_replacement_missing_order_items' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.commerce_order_items oi
    LEFT JOIN public.catalog_skus cs ON cs.id = oi.sku_id
    WHERE oi.order_id = p_order_id AND (oi.sku_id IS NULL OR cs.id IS NULL)
  ) THEN
    RAISE EXCEPTION 'commerce_oms_replacement_missing_catalog_sku' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope, idempotency_key, request_fingerprint, status, metadata
  ) VALUES (
    v_scope, p_idempotency_key, v_request_fingerprint, 'in_progress',
    jsonb_build_object('boundary', 'commerce_oms_request_replacement_shipment')
  );

  WITH released AS (
    UPDATE public.commerce_order_holds
       SET status = 'released', released_at = now(), released_by = p_actor_user_id,
           updated_at = now(), metadata = metadata || jsonb_build_object(
             'releasedBy', 'commerce_oms_request_replacement_shipment',
             'replacementReason', p_reason
           )
     WHERE order_id = p_order_id AND status = 'active'
       AND reason = 'fulfillment_exception'
    RETURNING id, created_at
  )
  SELECT coalesce(array_agg(id ORDER BY created_at, id), ARRAY[]::uuid[]),
         (array_agg(id ORDER BY created_at, id))[1]
    INTO v_released_hold_ids, v_primary_hold_id FROM released;

  v_provider_kind := lower(nullif(btrim(
    v_predecessor.shipping_address_snapshot #>> '{deliveryContact,selectedDelivery,providerKind}'
  ), ''));
  FOR v_item IN
    SELECT id, sku_id, quantity FROM public.commerce_order_items
     WHERE order_id = p_order_id ORDER BY id
  LOOP
    v_reservation_key := p_idempotency_key || ':reservation:' || v_item.id::text;
    PERFORM public.inventory_reserve_order(
      v_reservation_key, p_order_id, v_item.id, v_order.subscription_cycle_id,
      v_item.sku_id, v_item.quantity, 'manual_ops', 'succeeded', NULL,
      jsonb_build_object(
        'source', 'commerce_oms_request_replacement_shipment',
        'replacesFulfillmentOrderId', v_predecessor.id,
        'replacementReason', p_reason
      ),
      v_provider_kind
    );
    UPDATE public.inventory_reservations
       SET expires_at = NULL, updated_at = now(),
           metadata = metadata || jsonb_build_object('holdKind', 'replacement_parcel_hold')
     WHERE idempotency_key = v_reservation_key AND status = 'reserved';
  END LOOP;

  IF EXISTS (
    SELECT 1 FROM public.commerce_order_items oi
    LEFT JOIN (
      SELECT order_item_id, sum(quantity) AS reserved_quantity
      FROM public.inventory_reservations
      WHERE order_id = p_order_id AND status = 'reserved'
      GROUP BY order_item_id
    ) reservations ON reservations.order_item_id = oi.id
    WHERE oi.order_id = p_order_id
      AND coalesce(reservations.reserved_quantity, 0) < oi.quantity
  ) THEN
    RAISE EXCEPTION 'commerce_oms_replacement_missing_inventory_reservation' USING ERRCODE = '22023';
  END IF;

  SELECT (max(sequence_no) + 1)::smallint INTO v_sequence_no
    FROM public.commerce_fulfillment_orders WHERE order_id = p_order_id;
  INSERT INTO public.commerce_fulfillment_orders (
    order_id, client_id, shipping_address_id, create_idempotency_key,
    shipping_address_snapshot, metadata, sequence_no,
    replaces_fulfillment_order_id, replacement_reason
  ) VALUES (
    p_order_id, v_order.client_id, v_order.shipping_address_id,
    p_idempotency_key || ':fulfillment',
    v_predecessor.shipping_address_snapshot,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'source', 'commerce_oms_request_replacement_shipment',
      'replacementReason', p_reason
    ),
    v_sequence_no, v_predecessor.id, p_reason
  ) RETURNING id INTO v_fulfillment_id;

  INSERT INTO public.commerce_fulfillment_order_lines (
    fulfillment_order_id, order_id, order_item_id, sku_id, sku, title, quantity,
    inventory_reservation_ids, product_snapshot
  )
  SELECT v_fulfillment_id, p_order_id, oi.id, oi.sku_id, cs.sku, cs.title, oi.quantity,
    ARRAY(
      SELECT ir.id FROM public.inventory_reservations ir
      WHERE ir.idempotency_key = p_idempotency_key || ':reservation:' || oi.id::text
        AND ir.status = 'reserved' ORDER BY ir.created_at
    ), oi.product_snapshot
  FROM public.commerce_order_items oi
  JOIN public.catalog_skus cs ON cs.id = oi.sku_id
  WHERE oi.order_id = p_order_id;

  INSERT INTO public.commerce_fulfillment_operations (
    fulfillment_order_id, order_id, operation_type, idempotency_key, actor_user_id, payload
  ) VALUES (
    v_fulfillment_id, p_order_id, 'created', p_idempotency_key || ':created', NULL,
    jsonb_build_object(
      'source', 'commerce_oms_request_replacement_shipment',
      'operatorUserId', p_actor_user_id,
      'sequenceNo', v_sequence_no,
      'replacesFulfillmentOrderId', v_predecessor.id,
      'replacementReason', p_reason
    )
  );
  v_payload := jsonb_build_object(
    'reason', p_reason,
    'sequenceNo', v_sequence_no,
    'fulfillmentOrderId', v_fulfillment_id,
    'replacesFulfillmentOrderId', v_predecessor.id,
    'releasedHoldIds', to_jsonb(v_released_hold_ids),
    'metadata', coalesce(p_metadata, '{}'::jsonb),
    'source', 'commerce.oms.v0'
  );
  INSERT INTO public.commerce_order_operations (
    order_id, hold_id, actor_user_id, operation_type, idempotency_key, payload
  ) VALUES (
    p_order_id, v_primary_hold_id, p_actor_user_id,
    'replacement_shipment_requested', p_idempotency_key || ':operation', v_payload
  ) RETURNING * INTO v_operation;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'operation', jsonb_build_object(
      'id', v_operation.id, 'orderId', v_operation.order_id,
      'type', v_operation.operation_type, 'holdId', v_operation.hold_id,
      'actorUserId', v_operation.actor_user_id,
      'occurredAt', v_operation.occurred_at, 'payload', v_operation.payload
    ),
    'replacement', jsonb_build_object(
      'fulfillmentOrderId', v_fulfillment_id, 'orderId', p_order_id,
      'sequenceNo', v_sequence_no,
      'replacesFulfillmentOrderId', v_predecessor.id,
      'reason', p_reason, 'status', 'created'
    ),
    'releasedHoldIds', to_jsonb(v_released_hold_ids),
    'replayed', false
  );
  UPDATE public.commerce_idempotency_keys
     SET status = 'completed', response_payload = v_response,
         metadata = metadata || jsonb_build_object(
           'operationId', v_operation.id,
           'fulfillmentOrderId', v_fulfillment_id
         )
   WHERE scope = v_scope AND idempotency_key = p_idempotency_key;
  RETURN v_response;
END;
$_$;


--
-- Name: FUNCTION commerce_oms_request_replacement_shipment(p_idempotency_key text, p_order_id uuid, p_reason text, p_actor_user_id uuid, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_oms_request_replacement_shipment(p_idempotency_key text, p_order_id uuid, p_reason text, p_actor_user_id uuid, p_metadata jsonb) IS 'Operator command that creates the replacement parcel for an order whose first parcel was lost, damaged or came back undelivered. Releases active fulfillment_exception holds and refuses by name on any other active hold reason; mints a fresh manual_ops reservation generation; writes the next fulfilment ordinal with its predecessor and reason; audits the request with actor and reason. Creates the parcel, never dispatches it.';


--
-- Name: commerce_oms_resolve_delivery_contact_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_resolve_delivery_contact_v1(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_address public.addresses%ROWTYPE;
  v_client public.clients%ROWTYPE;
  v_resolution jsonb;
  v_contact jsonb;
  v_baseline jsonb;
  v_scope text;
BEGIN
  IF p_order_id IS NULL THEN
    RAISE EXCEPTION 'commerce_oms_delivery_contact_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_oms_shipping_address_order_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE order_id = p_order_id
   ORDER BY sequence_no DESC, id DESC
   LIMIT 1;

  IF v_fulfillment.id IS NOT NULL THEN
    SELECT * INTO v_client FROM public.clients WHERE id = v_fulfillment.client_id;
    SELECT * INTO v_address FROM public.addresses WHERE id = v_fulfillment.shipping_address_id;
  ELSE
    SELECT * INTO v_client FROM public.clients WHERE id = v_order.client_id;
    SELECT * INTO v_address FROM public.addresses WHERE id = v_order.shipping_address_id;
  END IF;

  v_baseline := CASE
    WHEN coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact'
      THEN v_order.metadata #> '{runtimeFinalize,deliveryContact}'
    ELSE NULL
  END;
  v_scope := CASE
    WHEN v_fulfillment.id IS NOT NULL
      AND coalesce(v_fulfillment.shipping_address_snapshot, '{}'::jsonb) ? 'deliveryContact'
      THEN 'parcel'
    -- A keyless parcel is the correction scope, but it is legacy provenance
    -- only when the order itself carries no canonical contact marker.
    WHEN v_fulfillment.id IS NOT NULL
      THEN 'legacy_inferred'
    WHEN coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride'
      THEN 'order_override'
    WHEN coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact'
      THEN 'baseline'
    ELSE 'legacy_inferred'
  END;

  v_resolution := private.commerce_delivery_contact_resolve_v1(jsonb_build_object(
    'frozenContactPresent', v_scope IN ('parcel', 'order_override', 'baseline'),
    'frozenContact', CASE v_scope
      WHEN 'parcel' THEN v_fulfillment.shipping_address_snapshot->'deliveryContact'
      WHEN 'order_override' THEN v_order.metadata->'deliveryContactOverride'
      WHEN 'baseline' THEN v_baseline
      ELSE NULL
    END,
    'orderCanonicalPresent',
      coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride'
      OR coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact',
    'channelOrderSnapshot', v_order.metadata->'channelOrderSnapshot',
    'selectedDeliveryCandidates', jsonb_build_array(
      v_fulfillment.metadata->'selectedDelivery',
      v_order.metadata->'selectedDelivery',
      v_order.metadata #> '{runtimeFinalize,selectedDelivery}',
      v_fulfillment.shipping_address_snapshot->'selectedDelivery',
      v_address.metadata->'selectedDelivery'
    ),
    'recipientCandidates', jsonb_build_array(
      v_fulfillment.shipping_address_snapshot->>'recipientName',
      v_address.recipient_name,
      concat_ws(' ', v_client.first_name, v_client.last_name),
      v_address.label
    ),
    'phoneCandidates', jsonb_build_array(
      v_fulfillment.shipping_address_snapshot->>'contactPhone',
      v_address.contact_phone,
      v_client.phone
    ),
    'legacyClientEmail', v_client.email,
    'line1', coalesce(v_fulfillment.shipping_address_snapshot->>'line1', v_address.line1),
    'line2', coalesce(v_fulfillment.shipping_address_snapshot->>'line2', v_address.line2),
    'city', coalesce(v_fulfillment.shipping_address_snapshot->>'city', v_address.city),
    'postalCode', coalesce(v_fulfillment.shipping_address_snapshot->>'postalCode', v_address.postal_code),
    'country', coalesce(v_fulfillment.shipping_address_snapshot->>'country', v_address.country),
    'deliveryInstructions', v_address.delivery_notes,
    'courierInstructions', v_address.courier_instructions
  ));
  v_contact := v_resolution->'contact';
  IF v_resolution->>'disposition' = 'order_canonical_without_frozen' THEN
    v_contact := NULL;
  END IF;
  IF jsonb_typeof(v_contact) IS DISTINCT FROM 'object'
    OR v_contact->>'schemaVersion' IS DISTINCT FROM '1'
    OR coalesce(v_contact->>'revision', '') !~ '^[1-9][0-9]*$'
    OR nullif(btrim(v_contact->>'source'), '') IS NULL
  THEN
    v_contact := NULL;
  END IF;
  IF jsonb_typeof(v_baseline) IS DISTINCT FROM 'object'
    OR v_baseline->>'schemaVersion' IS DISTINCT FROM '1'
    OR coalesce(v_baseline->>'revision', '') !~ '^[1-9][0-9]*$'
    OR nullif(btrim(v_baseline->>'source'), '') IS NULL
  THEN
    v_baseline := NULL;
  END IF;

  RETURN jsonb_build_object(
    'resolutionVersion', 1,
    'scope', v_scope,
    'baseline', CASE WHEN jsonb_typeof(v_baseline) = 'object' THEN v_baseline ELSE 'null'::jsonb END,
    'contact', CASE WHEN jsonb_typeof(v_contact) = 'object' THEN v_contact ELSE 'null'::jsonb END,
    'contactDigest', CASE WHEN jsonb_typeof(v_contact) = 'object' THEN md5(v_contact::text) ELSE NULL END
  );
END;
$_$;


--
-- Name: commerce_oms_update_shipping_address(text, uuid, jsonb, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_oms_update_shipping_address(p_idempotency_key text, p_order_id uuid, p_address jsonb, p_actor_user_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_scope constant text := 'commerce.oms.shipping_address.update';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_ref public.omnipack_dispatch_refs%ROWTYPE;
  v_operation public.commerce_order_operations%ROWTYPE;
  v_current_contact jsonb;
  v_updated_contact jsonb;
  v_expected_revision integer;
  v_current_revision integer;
  v_expected_contact_digest text;
  v_current_contact_digest text;
  v_latest_fulfillment_id uuid;
  v_scope_applied text;
  v_payload jsonb;
  v_response jsonb;
  v_client public.clients%ROWTYPE;
  v_address public.addresses%ROWTYPE;
  v_contact_resolution jsonb;
BEGIN
  -- Bounded lock wait, restored on return. Every acquisition below - the
  -- idempotency row, the two advisory keys, the parcel, order and reference rows -
  -- waited without limit, so a contended correction returned nothing at all until
  -- the caller gave up. Three seconds is far above this routine's own cost and far
  -- below the 30s function ceiling, so contention now surfaces as a named,
  -- retryable refusal instead of silence. This routine carries a SET clause, so
  -- the setting is unwound at return and binds no other statement.
  SET LOCAL lock_timeout = '3s';

  IF p_idempotency_key IS NULL
    OR btrim(p_idempotency_key) = ''
    OR length(p_idempotency_key) < 8
    OR p_order_id IS NULL
    OR p_actor_user_id IS NULL
    OR p_address IS NULL
    OR jsonb_typeof(p_address) <> 'object'
    OR nullif(btrim(p_address->>'recipientName'), '') IS NULL
    OR nullif(btrim(p_address->>'contactEmail'), '') IS NULL
    OR nullif(btrim(p_address->>'contactPhone'), '') IS NULL
    OR nullif(btrim(p_address->>'line1'), '') IS NULL
    OR nullif(btrim(p_address->>'city'), '') IS NULL
    OR nullif(btrim(p_address->>'postalCode'), '') IS NULL
    OR nullif(btrim(p_address->>'country'), '') IS NULL
    -- An ABSENT expectation means the caller states none, which is exactly what
    -- the still-deployed OMS sends during the apply-before-deploy window. It is
    -- accepted for that one release: production today performs no such check at
    -- all, so tolerating its absence defers a strengthening rather than weakening
    -- anything. A key that IS present must still be well formed.
    OR (
      coalesce(p_metadata, '{}'::jsonb) ? '_deliveryContactExpectedRevision'
      AND coalesce(p_metadata->>'_deliveryContactExpectedRevision', '') !~ '^[1-9][0-9]*$'
    )
    OR (
      coalesce(p_metadata, '{}'::jsonb) ? '_deliveryContactExpectedDigest'
      AND coalesce(p_metadata->>'_deliveryContactExpectedDigest', '') !~ '^[0-9a-f]{32}$'
    )
  THEN
    RAISE EXCEPTION 'commerce_oms_shipping_address_invalid_input' USING ERRCODE = '22023';
  END IF;
  v_expected_revision := (p_metadata->>'_deliveryContactExpectedRevision')::integer;
  v_expected_contact_digest := p_metadata->>'_deliveryContactExpectedDigest';
  v_request_fingerprint := md5(
    p_order_id::text || '|' || p_address::text || '|' ||
    p_actor_user_id::text || '|' || coalesce(p_metadata, '{}'::jsonb)::text
  );

  SELECT * INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope AND idempotency_key = p_idempotency_key
   FOR UPDATE;
  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(
        jsonb_set(v_existing.response_payload, '{replayed}', 'true'::jsonb, false),
        '{result}', '"replayed"'::jsonb, false
      );
    END IF;
    RAISE EXCEPTION 'commerce_oms_shipping_address_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'commerce-order-delivery|' || p_order_id::text,
    0
  ));

  SELECT * INTO v_order FROM public.commerce_orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_oms_shipping_address_order_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE order_id = p_order_id
   ORDER BY sequence_no DESC, id DESC
   LIMIT 1;

  IF v_fulfillment.id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'omnipack-dispatch|' || v_fulfillment.id::text,
      0
    ));
    SELECT * INTO v_fulfillment
      FROM public.commerce_fulfillment_orders
     WHERE id = v_fulfillment.id
     FOR UPDATE;
    SELECT * INTO v_order FROM public.commerce_orders WHERE id = p_order_id FOR UPDATE;
    SELECT id INTO v_latest_fulfillment_id
      FROM public.commerce_fulfillment_orders
     WHERE order_id = p_order_id
     ORDER BY sequence_no DESC, id DESC
     LIMIT 1;
    IF v_order.id IS NULL
      OR v_fulfillment.order_id IS DISTINCT FROM v_order.id
      OR v_latest_fulfillment_id IS DISTINCT FROM v_fulfillment.id
    THEN
      RAISE EXCEPTION 'commerce_oms_delivery_contact_stale_revision' USING ERRCODE = '40001';
    END IF;
    PERFORM 1
      FROM public.omnipack_dispatch_refs
     WHERE fulfillment_order_id = v_fulfillment.id
     ORDER BY id
     FOR UPDATE;
    SELECT * INTO v_ref
      FROM public.omnipack_dispatch_refs
     WHERE fulfillment_order_id = v_fulfillment.id
       AND (provider_order_id IS NOT NULL OR status <> 'draft')
     ORDER BY created_at DESC, id DESC
     LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'commerce_oms_delivery_contact_submission_started' USING ERRCODE = '55000';
    END IF;
    IF v_fulfillment.status NOT IN ('created', 'packed', 'label_pending') THEN
      RAISE EXCEPTION 'commerce_oms_delivery_contact_submission_started' USING ERRCODE = '55000';
    END IF;
    SELECT * INTO v_client FROM public.clients WHERE id = v_fulfillment.client_id;
    SELECT * INTO v_address FROM public.addresses WHERE id = v_fulfillment.shipping_address_id;
    v_scope_applied := 'parcel';
  ELSE
    SELECT * INTO v_order FROM public.commerce_orders WHERE id = p_order_id FOR UPDATE;
    IF EXISTS (
      SELECT 1 FROM public.commerce_fulfillment_orders WHERE order_id = p_order_id
    ) THEN
      RAISE EXCEPTION 'commerce_oms_delivery_contact_stale_revision' USING ERRCODE = '40001';
    END IF;
    SELECT * INTO v_client FROM public.clients WHERE id = v_order.client_id;
    SELECT * INTO v_address FROM public.addresses WHERE id = v_order.shipping_address_id;
    v_scope_applied := 'order';
  END IF;

  -- A keyless parcel may use legacy evidence only when its order has no
  -- canonical contact marker; otherwise the resolver returns the named fence.
  v_contact_resolution := private.commerce_delivery_contact_resolve_v1(jsonb_build_object(
    'frozenContactPresent', CASE
      WHEN v_scope_applied = 'parcel'
        THEN coalesce(v_fulfillment.shipping_address_snapshot, '{}'::jsonb) ? 'deliveryContact'
      ELSE coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride'
        OR coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact'
    END,
    'frozenContact', CASE
      WHEN v_scope_applied = 'parcel'
        THEN v_fulfillment.shipping_address_snapshot->'deliveryContact'
      WHEN coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride'
        THEN v_order.metadata->'deliveryContactOverride'
      WHEN coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact'
        THEN v_order.metadata #> '{runtimeFinalize,deliveryContact}'
      ELSE NULL
    END,
    'orderCanonicalPresent',
      coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride'
      OR coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact',
    'channelOrderSnapshot', v_order.metadata->'channelOrderSnapshot',
    'selectedDeliveryCandidates', jsonb_build_array(
      v_fulfillment.metadata->'selectedDelivery',
      v_order.metadata->'selectedDelivery',
      v_order.metadata #> '{runtimeFinalize,selectedDelivery}',
      v_fulfillment.shipping_address_snapshot->'selectedDelivery',
      v_address.metadata->'selectedDelivery'
    ),
    'recipientCandidates', jsonb_build_array(
      v_fulfillment.shipping_address_snapshot->>'recipientName',
      v_address.recipient_name,
      concat_ws(' ', v_client.first_name, v_client.last_name),
      v_address.label
    ),
    'phoneCandidates', jsonb_build_array(
      v_fulfillment.shipping_address_snapshot->>'contactPhone',
      v_address.contact_phone,
      v_client.phone
    ),
    'legacyClientEmail', v_client.email,
    'line1', coalesce(v_fulfillment.shipping_address_snapshot->>'line1', v_address.line1),
    'line2', coalesce(v_fulfillment.shipping_address_snapshot->>'line2', v_address.line2),
    'city', coalesce(v_fulfillment.shipping_address_snapshot->>'city', v_address.city),
    'postalCode', coalesce(v_fulfillment.shipping_address_snapshot->>'postalCode', v_address.postal_code),
    'country', coalesce(v_fulfillment.shipping_address_snapshot->>'country', v_address.country),
    'deliveryInstructions', v_address.delivery_notes,
    'courierInstructions', v_address.courier_instructions
  ));
  v_current_contact := v_contact_resolution->'contact';

  IF v_contact_resolution->>'disposition' = 'order_canonical_without_frozen'
    OR jsonb_typeof(v_current_contact) IS DISTINCT FROM 'object'
    OR coalesce(v_current_contact->>'revision', '') !~ '^[1-9][0-9]*$'
  THEN
    RAISE EXCEPTION 'commerce_oms_delivery_contact_stale_revision' USING ERRCODE = '40001';
  END IF;
  v_current_revision := (v_current_contact->>'revision')::integer;
  v_current_contact_digest := md5(v_current_contact::text);
  -- NULL is "no expectation", not "expected zero". Every other stale-revision
  -- raise in this routine guards a re-read race and stays unconditional; this one
  -- is the caller's optimistic-concurrency claim and only fires when one was made.
  IF v_expected_revision IS NOT NULL
    AND v_expected_revision IS DISTINCT FROM v_current_revision
  THEN
    RAISE EXCEPTION 'commerce_oms_delivery_contact_stale_revision' USING ERRCODE = '40001';
  END IF;
  -- The migration is applied before the runtime that supplies this digest, so
  -- absence is temporarily compatible. Once supplied, it identifies the exact
  -- resolver output shown in the form and closes the rev-1 legacy ABA window.
  IF v_expected_contact_digest IS NOT NULL
    AND v_expected_contact_digest IS DISTINCT FROM v_current_contact_digest
  THEN
    RAISE EXCEPTION 'commerce_oms_delivery_contact_stale_revision' USING ERRCODE = '40001';
  END IF;

  v_updated_contact := v_current_contact || jsonb_build_object(
    'source', CASE WHEN v_scope_applied = 'parcel' THEN 'oms_parcel_correction' ELSE 'oms_order_override' END,
    'revision', v_current_revision + 1,
    'recipientName', btrim(p_address->>'recipientName'),
    'contactEmail', btrim(lower(p_address->>'contactEmail')),
    'contactPhone', btrim(p_address->>'contactPhone'),
    'line1', btrim(p_address->>'line1'),
    'line2', CASE
      WHEN p_address ? 'line2' THEN nullif(btrim(p_address->>'line2'), '')
      ELSE v_current_contact->>'line2'
    END,
    'city', btrim(p_address->>'city'),
    'postalCode', btrim(p_address->>'postalCode'),
    'country', upper(btrim(p_address->>'country')),
    'deliveryInstructions', CASE
      WHEN p_address ? 'deliveryInstructions' THEN nullif(btrim(p_address->>'deliveryInstructions'), '')
      ELSE v_current_contact->>'deliveryInstructions'
    END,
    'courierInstructions', CASE
      WHEN p_address ? 'courierInstructions' THEN nullif(btrim(p_address->>'courierInstructions'), '')
      ELSE v_current_contact->>'courierInstructions'
    END
  );

  INSERT INTO public.commerce_idempotency_keys (
    scope, idempotency_key, request_fingerprint, status, metadata
  ) VALUES (
    v_scope, p_idempotency_key, v_request_fingerprint, 'in_progress',
    jsonb_build_object('boundary', 'commerce_oms_update_shipping_address')
  );

  IF v_scope_applied = 'parcel' THEN
    UPDATE public.commerce_fulfillment_orders
       SET shipping_address_snapshot = shipping_address_snapshot || jsonb_build_object(
             'line1', v_updated_contact->>'line1',
             'line2', v_updated_contact->>'line2',
             'city', v_updated_contact->>'city',
             'postalCode', v_updated_contact->>'postalCode',
             'country', v_updated_contact->>'country',
             'recipientName', v_updated_contact->>'recipientName',
             'selectedDelivery', v_updated_contact->'selectedDelivery',
             'deliveryContact', v_updated_contact
           ),
           updated_at = now()
     WHERE id = v_fulfillment.id;
  ELSE
    UPDATE public.commerce_orders
       SET metadata = jsonb_set(metadata, '{deliveryContactOverride}', v_updated_contact, true),
           updated_at = now()
     WHERE id = p_order_id;
  END IF;

  v_payload := jsonb_build_object(
    'scope', v_scope_applied,
    'beforeRevision', v_current_revision,
    'afterRevision', v_current_revision + 1,
    'contactDigest', md5(v_updated_contact::text),
    'metadata', coalesce(p_metadata, '{}'::jsonb)
      - '_deliveryContactExpectedRevision'
      - '_deliveryContactExpectedDigest',
    'source', 'commerce.oms.v0'
  );
  INSERT INTO public.commerce_order_operations (
    order_id, actor_user_id, operation_type, idempotency_key, payload
  ) VALUES (
    p_order_id, p_actor_user_id, 'shipping_address_updated',
    p_idempotency_key || ':operation', v_payload
  ) RETURNING * INTO v_operation;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'result', 'applied',
    'scope', v_scope_applied,
    'deliveryContact', v_updated_contact,
    'operation', jsonb_build_object(
      'id', v_operation.id,
      'orderId', v_operation.order_id,
      'type', v_operation.operation_type,
      'holdId', v_operation.hold_id,
      'actorUserId', v_operation.actor_user_id,
      'occurredAt', v_operation.occurred_at,
      'payload', v_operation.payload
    ),
    'address', jsonb_build_object(
      'recipientName', v_updated_contact->>'recipientName',
      'contactEmail', v_updated_contact->>'contactEmail',
      'contactPhone', v_updated_contact->>'contactPhone',
      'line1', v_updated_contact->>'line1',
      'line2', v_updated_contact->>'line2',
      'city', v_updated_contact->>'city',
      'postalCode', v_updated_contact->>'postalCode',
      'country', v_updated_contact->>'country'
    ),
    'replayed', false
  );
  UPDATE public.commerce_idempotency_keys
     SET status = 'completed', response_payload = v_response,
         metadata = metadata || jsonb_build_object('operationId', v_operation.id)
   WHERE scope = v_scope AND idempotency_key = p_idempotency_key;
  RETURN v_response;
END;
$_$;


--
-- Name: commerce_order_item_assign_allocation_ordinal(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_order_item_assign_allocation_ordinal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_lines jsonb;
  v_draft_lines jsonb;
  v_cycle_lines jsonb;
BEGIN
  IF NEW.allocation_ordinal IS NOT NULL THEN
    IF NEW.allocation_ordinal <= 0 THEN
      RAISE EXCEPTION 'commerce_order_item_allocation_ordinal_invalid'
        USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
  END IF;

  SELECT
    metadata#>'{orderDraftSnapshot,lines}',
    metadata#>'{orderSnapshot,lines}'
    INTO v_draft_lines, v_cycle_lines
    FROM public.commerce_orders
   WHERE id = NEW.order_id;

  IF v_draft_lines IS NOT NULL
     AND v_draft_lines <> 'null'::jsonb
     AND jsonb_typeof(v_draft_lines) <> 'array' THEN
    RAISE EXCEPTION 'commerce_order_item_allocation_ordinal_snapshot_malformed'
      USING ERRCODE = '23514';
  END IF;
  IF v_cycle_lines IS NOT NULL
     AND v_cycle_lines <> 'null'::jsonb
     AND jsonb_typeof(v_cycle_lines) <> 'array' THEN
    RAISE EXCEPTION 'commerce_order_item_allocation_ordinal_snapshot_malformed'
      USING ERRCODE = '23514';
  END IF;

  IF jsonb_typeof(v_draft_lines) = 'array' THEN
    v_lines := v_draft_lines;
  ELSIF jsonb_typeof(v_cycle_lines) = 'array' THEN
    v_lines := v_cycle_lines;
  ELSE
    v_lines := NULL;
  END IF;

  IF v_lines IS NULL THEN
    -- Service-role repair/fixture inserts without a quote snapshot still have
    -- one provable order: the serialized row insertion order. Concurrent
    -- inserts race on the UNIQUE constraint and therefore fail closed.
    SELECT coalesce(max(existing.allocation_ordinal), 0) + 1
      INTO NEW.allocation_ordinal
      FROM public.commerce_order_items existing
     WHERE existing.order_id = NEW.order_id;
  ELSE
    SELECT min(line.ordinality)::integer INTO NEW.allocation_ordinal
      FROM jsonb_array_elements(v_lines) WITH ORDINALITY AS line(value, ordinality)
     WHERE line.value = NEW.product_snapshot->'quoteLine'
       AND NOT EXISTS (
         SELECT 1
           FROM public.commerce_order_items existing
          WHERE existing.order_id = NEW.order_id
            AND existing.allocation_ordinal = line.ordinality
       );
  END IF;

  IF NEW.allocation_ordinal IS NULL THEN
    RAISE EXCEPTION 'commerce_order_item_allocation_ordinal_unprovable'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: commerce_order_mark_refunded_manual(text, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_order_mark_refunded_manual(p_idempotency_key text, p_order_id uuid, p_reason text, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_existing_operation public.commerce_order_operations%ROWTYPE;
BEGIN
  SELECT * INTO v_existing_operation
    FROM public.commerce_order_operations
   WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing_operation.order_id IS DISTINCT FROM p_order_id
      OR v_existing_operation.payload->>'reason' IS DISTINCT FROM p_reason
    THEN
      RAISE EXCEPTION 'commerce_order_mark_refunded_idempotency_conflict' USING ERRCODE = '23505';
    END IF;

    SELECT * INTO v_order FROM public.commerce_orders WHERE id = v_existing_operation.order_id;
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'orderId', v_existing_operation.order_id,
      'status', v_order.status,
      'replayed', true
    );
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_order_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_order.status = 'refunded' THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'orderId', p_order_id,
      'status', 'refunded',
      'replayed', true
    );
  END IF;

  IF v_order.status <> 'paid' THEN
    RAISE EXCEPTION 'commerce_order_mark_refunded_invalid_status' USING ERRCODE = '22023';
  END IF;

  UPDATE public.commerce_orders
     SET status = 'refunded',
         metadata = metadata || jsonb_build_object(
           'source', 'admin_manual_refund',
           'manualRefund', jsonb_build_object(
             'reason', p_reason,
             'actorUserId', p_actor_user_id,
             'markedAt', now()
           )
         ),
         updated_at = now()
   WHERE id = p_order_id;

  INSERT INTO public.commerce_order_operations (
    order_id, actor_user_id, operation_type, idempotency_key, payload
  )
  VALUES (
    p_order_id, p_actor_user_id, 'order_marked_refunded', p_idempotency_key,
    jsonb_build_object(
      'reason', p_reason,
      'metadata', coalesce(p_metadata, '{}'::jsonb),
      'source', 'commerce.oms.v0'
    )
  );

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'orderId', p_order_id,
    'status', 'refunded',
    'replayed', false
  );
END;
$$;


--
-- Name: commerce_order_number_from_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_order_number_from_id(p_order_id uuid) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT 'OPENLUP-' || upper(substr(replace(p_order_id::text, '-', ''), 1, 8));
$$;


--
-- Name: commerce_orders_write_redemptions_on_paid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_orders_write_redemptions_on_paid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.commerce_write_order_promotion_redemptions(
    NEW.id,
    COALESCE(NULLIF(NEW.metadata #>> '{paidAt}', '')::timestamptz, now())
  );
  RETURN NEW;
END;
$$;


--
-- Name: commerce_outbox_marketing_quiet_hours(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_outbox_marketing_quiet_hours() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.event_type IN (
    'commerce.order_draft.abandoned.1h',
    'commerce.order_draft.abandoned.24h',
    'commerce.order_draft.abandoned.72h',
    'commerce.order.review_request',
    'commerce.order.review_effects',
    'commerce.order.reorder_reminder',
    'commerce.product.back_in_stock'
  ) THEN
    NEW.available_at := public.communication_marketing_available_at(
      coalesce(NEW.available_at, now())
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: commerce_payment_apply_result_sealed_v1(text, uuid, uuid, text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_apply_result_sealed_v1(p_idempotency_key text, p_payment_intent_id uuid, p_payment_event_id uuid, p_result_status text, p_occurred_at timestamp with time zone, p_failure_reason text, p_failure_class text DEFAULT NULL::text, p_failure_class_decided_by text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_event_intent_id uuid;
  v_event_attempt_id uuid;
  v_subscription_id uuid;
  v_result jsonb;
  v_attempt_id uuid;
BEGIN
  IF p_payment_event_id IS NOT NULL THEN
    SELECT payment_event.payment_intent_id,
           payment_event.payment_attempt_id
      INTO v_event_intent_id,
           v_event_attempt_id
      FROM public.inbound_provider_events payment_event
     WHERE payment_event.id = p_payment_event_id;

    -- Preserve the delegated body's existing event-not-found and wrong-intent
    -- reasons. This guard owns only the newly-forbidden NULL correlation. It
    -- deliberately takes no row lock: the delegated body retains the canonical
    -- subscription -> intent -> attempt -> event order and rechecks populated
    -- attempt identities under those locks.
    IF FOUND
      AND v_event_intent_id = p_payment_intent_id
      AND v_event_attempt_id IS NULL
    THEN
      RAISE EXCEPTION 'payment_control_result_attempt_unresolved'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT payment_intent.subscription_id
    INTO v_subscription_id
    FROM public.commerce_payment_intents payment_intent
   WHERE payment_intent.id = p_payment_intent_id
     AND payment_intent.target_kind = 'subscription_cycle';

  IF v_subscription_id IS NOT NULL THEN
    -- Provider truth must still apply after cancellation; this is serialization,
    -- not a lifecycle rejection.
    PERFORM 1
      FROM public.subscriptions subscription
     WHERE subscription.id = v_subscription_id
     FOR UPDATE;
  END IF;

  -- Named notation keeps future parameter additions fail-closed rather than
  -- shifting values positionally.
  v_result := public.commerce_payment_control_apply_before_sub_lock(
    p_idempotency_key := p_idempotency_key,
    p_payment_intent_id := p_payment_intent_id,
    p_payment_event_id := p_payment_event_id,
    p_result_status := p_result_status,
    p_occurred_at := p_occurred_at,
    p_failure_reason := p_failure_reason,
    p_failure_class := p_failure_class
  );

  -- Retain the existing post-delegation failure-class evidence stamp. Replays
  -- preserve the first decision and callers without a class leave the row as-is.
  IF p_failure_class IS NOT NULL
    AND v_result -> 'paymentResult' ->> 'replayed' IS DISTINCT FROM 'true'
  THEN
    v_attempt_id := NULLIF(v_result -> 'paymentResult' ->> 'paymentAttemptId', '')::uuid;
    IF v_attempt_id IS NOT NULL THEN
      UPDATE public.commerce_payment_attempts payment_attempt
         SET failure_class = p_failure_class,
             response_payload = CASE
               WHEN p_failure_class_decided_by IS NULL THEN payment_attempt.response_payload
               ELSE payment_attempt.response_payload
                 || jsonb_build_object('failureClassDecidedBy', p_failure_class_decided_by)
             END
       WHERE payment_attempt.id = v_attempt_id;
    END IF;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: commerce_payment_control_apply_before_sub_lock(text, uuid, uuid, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_apply_before_sub_lock(p_idempotency_key text, p_payment_intent_id uuid, p_payment_event_id uuid, p_result_status text, p_occurred_at timestamp with time zone, p_failure_reason text, p_failure_class text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.payment_result.apply';
  -- The classes for which this deployment publishes no ladder at all. FILLED by
  -- this migration, with one member. An issuer that answered hard_do_not_retry
  -- refused the INSTRUMENT, not this charge, so the three rungs below cannot
  -- change the answer -- they only spend eleven days telling the customer that
  -- another attempt is coming. Every other class keeps the full cadence:
  -- unlisted, unrecognised, and unclassified NULL alike. Its TypeScript twin is
  -- the terminatingFailureClasses of DEFAULT_CYCLE_RETRY_CADENCE in
  -- packages/core/src/subscription/cycleHardening.ts;
  -- scripts/retry-ladder-terminating-classes.test.ts reads this literal out of
  -- this file and fails if the two sets ever differ.
  v_terminating_classes constant text[] := '{hard_do_not_retry}';
  v_request_fingerprint text;
  v_legacy_request_fingerprint text;
  v_existing_failure_class text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_attempt public.commerce_payment_attempts%ROWTYPE;
  v_event public.inbound_provider_events%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_cycle public.subscription_cycles%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_next_cycle_at timestamptz;
  v_lateness_days integer;
  v_retry_attempt integer;
  v_next_retry_at timestamptz;
  v_cycle_status text;
  v_recoverable boolean := false;
  v_response jsonb;
  v_business_kind text := 'state_changed';
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_payment_intent_id IS NULL
    OR p_result_status NOT IN ('succeeded', 'failed', 'expired', 'refunded', 'partially_refunded', 'disputed')
    OR p_occurred_at IS NULL
  THEN
    RAISE EXCEPTION 'payment_control_result_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_legacy_request_fingerprint := md5(
    p_payment_intent_id::text || '|' ||
    COALESCE(p_payment_event_id::text, '') || '|' ||
    p_result_status || '|' ||
    p_occurred_at::text || '|' ||
    COALESCE(p_failure_reason, '')
  );
  v_request_fingerprint := md5(
    p_payment_intent_id::text || '|' ||
    COALESCE(p_payment_event_id::text, '') || '|' ||
    p_result_status || '|' ||
    p_occurred_at::text || '|' ||
    COALESCE(p_failure_reason, '') ||
    CASE WHEN p_failure_class IS NULL THEN '' ELSE '|failure_class=' || p_failure_class END
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed' AND v_existing.response_payload IS NOT NULL THEN
      IF v_existing.request_fingerprint = v_request_fingerprint THEN
        RETURN jsonb_set(v_existing.response_payload, '{paymentResult,replayed}', 'true'::jsonb, false);
      END IF;

      -- From 20260806120000 until this migration, the wrapper persisted a
      -- non-NULL failure_class on the attempt but the delegated six-argument
      -- body fingerprinted no class. Admit that exact historical replay only
      -- when the old fingerprint and the durable attempt class both match.
      -- New decisions never enter this branch because their stored fingerprint
      -- includes the class suffix; a different class therefore still conflicts.
      IF p_failure_class IS NOT NULL
        AND v_existing.request_fingerprint = v_legacy_request_fingerprint
      THEN
        SELECT attempt.failure_class
          INTO v_existing_failure_class
          FROM public.commerce_payment_attempts attempt
         WHERE attempt.id = NULLIF(v_existing.metadata ->> 'paymentAttemptId', '')::uuid;
        IF FOUND AND v_existing_failure_class IS NOT DISTINCT FROM p_failure_class THEN
          RETURN jsonb_set(v_existing.response_payload, '{paymentResult,replayed}', 'true'::jsonb, false);
        END IF;
      END IF;
    END IF;

    RAISE EXCEPTION 'payment_control_result_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_control_result_intent_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_attempt
    FROM public.commerce_payment_attempts
   WHERE id = v_intent.active_attempt_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_control_result_active_attempt_not_found' USING ERRCODE = '22023';
  END IF;

  IF p_payment_event_id IS NOT NULL THEN
    SELECT *
      INTO v_event
      FROM public.inbound_provider_events
     WHERE id = p_payment_event_id
     FOR UPDATE;
    IF NOT FOUND OR v_event.payment_intent_id IS DISTINCT FROM v_intent.id THEN
      RAISE EXCEPTION 'payment_control_result_event_mismatch' USING ERRCODE = '22023';
    END IF;
    -- The event names its own attempt, and that name wins. `ingest_event`
    -- correlated this row to an attempt by `(provider, provider_attempt_id)`,
    -- so a populated `payment_attempt_id` is the provider's own statement of
    -- which charge this verdict describes. `active_attempt_id` is only the
    -- LATEST charge on the intent, and a delivery that is merely slow is enough
    -- to make the two disagree: attempt one's refusal or capture arriving after
    -- attempt two was recorded would otherwise settle attempt two, silently and
    -- with no anomaly anywhere. A NULL means the correlation found nothing, and
    -- that is left exactly as permissive as it was -- this guard only refuses a
    -- statement the event actually made.
    IF v_event.payment_attempt_id IS NOT NULL
      AND v_event.payment_attempt_id IS DISTINCT FROM v_intent.active_attempt_id
    THEN
      RAISE EXCEPTION 'payment_control_result_attempt_mismatch' USING ERRCODE = '22023';
    END IF;
    -- A provider amount of 0 (or NULL) means "amount not asserted" — most often a
    -- declined/canceled PaymentIntent whose `amount_received` is 0 — and must NOT
    -- be read as a mismatch against the order total, or terminal failures can
    -- never reconcile. Only a POSITIVE provider amount is held to parity.
    IF v_event.amount_cents IS NOT NULL AND v_event.amount_cents > 0
      AND p_result_status NOT IN ('refunded', 'partially_refunded')
      AND v_event.amount_cents <> v_intent.amount_cents
    THEN
      RAISE EXCEPTION 'payment_control_result_amount_mismatch' USING ERRCODE = '22023';
    END IF;
    IF v_event.currency IS NOT NULL AND v_event.currency <> v_intent.currency THEN
      RAISE EXCEPTION 'payment_control_result_currency_mismatch' USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT *
    INTO v_order
    FROM public.commerce_orders
   WHERE id = v_intent.order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_control_result_order_not_found' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'commerce_payment_control_apply_result')
  );

  IF p_result_status = 'succeeded' THEN
    IF v_intent.status IN ('cancelled', 'refunded', 'partially_refunded', 'disputed') THEN
      RAISE EXCEPTION 'payment_control_result_terminal_intent' USING ERRCODE = '22023';
    END IF;

    UPDATE public.commerce_payment_intents
       SET status = 'succeeded',
           provider_payment_id = COALESCE(v_event.provider_payment_id, provider_payment_id),
           failure_reason = NULL,
           updated_at = now()
     WHERE id = v_intent.id;

    UPDATE public.commerce_payment_attempts
       SET status = 'succeeded',
           failure_reason = NULL,
           updated_at = now()
     WHERE id = v_attempt.id;

    UPDATE public.commerce_payments
       SET status = 'succeeded',
           provider_payment_id = COALESCE(v_event.provider_payment_id, provider_payment_id),
           metadata = metadata || jsonb_build_object('paymentStatus', 'succeeded', 'source', 'payment.control.v0'),
           updated_at = now()
     WHERE id = v_intent.payment_id;

    UPDATE public.commerce_orders
       SET status = 'paid',
           metadata = metadata || jsonb_build_object('paymentStatus', 'succeeded', 'paidAt', p_occurred_at, 'source', 'payment.control.v0'),
           updated_at = now()
     WHERE id = v_order.id;

    IF v_order.mode = 'subscription_cycle' THEN
      SELECT *
        INTO v_cycle
        FROM public.subscription_cycles
       WHERE id = v_order.subscription_cycle_id
       FOR UPDATE;
      SELECT *
        INTO v_subscription
        FROM public.subscriptions
       WHERE id = v_order.subscription_id
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'payment_control_result_subscription_not_found' USING ERRCODE = '22023';
      END IF;

      -- Whole days of PAYMENT LATENESS, then one cadence, then clamped so the anchor can
      -- only ever move later. See this migration's header for why each clamp is here.
      v_lateness_days := GREATEST(0, floor(extract(epoch FROM
        (LEAST(p_occurred_at, now()) - v_cycle.scheduled_at)) / 86400.0)::int);
      v_next_cycle_at := GREATEST(
        v_subscription.next_cycle_at,
        v_cycle.scheduled_at + make_interval(days => v_lateness_days + v_subscription.cadence_days)
      );

      UPDATE public.subscription_cycles
         SET status = 'paid',
             paid_at = p_occurred_at,
             payment_id = v_intent.payment_id,
             next_retry_at = NULL,
             failure_reason = NULL,
             updated_at = now()
       WHERE id = v_cycle.id;

      UPDATE public.subscriptions
         SET next_cycle_at = v_next_cycle_at,
             updated_at = now()
       WHERE id = v_subscription.id;

      -- CJ01-P follow-up: a declined renewal cycle can recover via the renewal CRON
      -- retry path (card re-bound, next cron pass charges it) rather than the customer
      -- redeem path. That success lands here; close any OPEN dunning case for the cycle
      -- at the payment terminal — the single source of truth — so it does not linger
      -- `open` with a stale `next_retry_at`. Only 'open' cases transition ('expired' is
      -- terminal, owned by the customer resume flow). Idempotent: a replayed succeeded
      -- apply finds the case already 'recovered' and no-ops.
      UPDATE public.subscription_dunning_cases
         SET status = 'recovered',
             recovered_at = p_occurred_at,
             next_retry_at = NULL,
             last_event_at = p_occurred_at,
             updated_at = now(),
             metadata = metadata || jsonb_build_object(
               'recoveredVia', 'payment.control.apply_result',
               'recoveredPaymentIntentId', v_intent.id
             )
       WHERE cycle_id = v_cycle.id
         AND status = 'open';

      -- The dispatch claim (subscription_dunning_claim_batch) filters only on the
      -- notification's own status + scheduled_at and does NOT join case/cycle status,
      -- so a still-queued or in-flight `payment_failed` notification would be delivered
      -- for the now-paid cycle. Skip it so no spurious decline email is sent post-recovery.
      UPDATE public.subscription_dunning_notifications
         SET status = 'skipped',
             provider_error = COALESCE(provider_error, 'cycle_recovered'),
             updated_at = now()
       WHERE cycle_id = v_cycle.id
         AND status IN ('queued', 'sending');

      INSERT INTO public.subscription_events (
        subscription_id,
        cycle_id,
        event_type,
        idempotency_key,
        payload,
        occurred_at
      )
      VALUES (
        v_subscription.id,
        v_cycle.id,
        'subscription.cycle_paid',
        p_idempotency_key || ':subscription_event',
        jsonb_build_object(
          'paymentIntentId', v_intent.id,
          'paymentAttemptId', v_attempt.id,
          'paymentId', v_intent.payment_id,
          'orderId', v_order.id,
          'nextCycleAt', v_next_cycle_at,
          'basedOnScheduledAt', v_cycle.scheduled_at,
          'basedOnPaidAt', p_occurred_at,
          'shiftedByDays', v_lateness_days,
          'source', 'payment.control.v0'
        ),
        p_occurred_at
      )
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
    END IF;
  ELSIF p_result_status IN ('failed', 'expired') THEN
    IF v_intent.status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed') THEN
      v_business_kind := 'ignored_failure_after_success_or_terminal';
    ELSIF v_intent.status = p_result_status
      AND v_attempt.status = p_result_status
    THEN
      -- Duplicate terminal failure. The intent AND its still-active attempt
      -- already sit at this status, which means nothing has been attempted since
      -- it was recorded: every legitimate ladder step records a FRESH attempt
      -- (that is what stamps active_attempt_id) before applying, so a real retry
      -- can never reach this branch. What does reach it is a second delivery of
      -- the same terminal signal under a different key. Applying it again would
      -- bump retry_attempt a second time for one decline, recompute
      -- next_retry_at off the later instant, and advance the customer's dunning
      -- ladder for an event that already happened. Absorb it exactly the way an
      -- after-success failure is absorbed above: no cycle, dunning, order or
      -- reservation mutation, an 'ignored' stamp on the inbound event, and a
      -- duplicate-marked response the caller can distinguish from a state change.
      --
      -- Deliberately NOT also requiring the failure REASON to match. The whole
      -- point is the cross-writer duplicate, and the writers disagree about
      -- wording for one identical provider event: the renewal cron records its
      -- own classification, the payment webhook applies a generic failed reason,
      -- and reconciliation writes a third. Keying on the reason would let every
      -- real duplicate through and absorb only the case that barely happens.
      -- Status equality is the honest predicate, and it is exactly as safe: a
      -- genuine escalation carries a DIFFERENT status (expired after failed) and
      -- still falls through to be applied.
      v_business_kind := 'ignored_duplicate_terminal_failure';
    ELSE
      -- The provider attempt itself is over either way — record it truthfully on
      -- the attempt, intent, and payment. Whether the ORDER terminalizes is decided
      -- separately below (recoverable decline vs. terminal expiry/renewal-dunning).
      UPDATE public.commerce_payment_intents
         SET status = p_result_status,
             failure_reason = COALESCE(p_failure_reason, p_result_status),
             updated_at = now()
       WHERE id = v_intent.id;

      UPDATE public.commerce_payment_attempts
         SET status = p_result_status,
             failure_reason = COALESCE(p_failure_reason, p_result_status),
             updated_at = now()
       WHERE id = v_attempt.id;

      UPDATE public.commerce_payments
         SET status = CASE WHEN p_result_status = 'expired' THEN 'expired' ELSE 'failed' END,
             metadata = metadata || jsonb_build_object(
               'paymentStatus', p_result_status,
               'failureReason', COALESCE(p_failure_reason, p_result_status),
               'source', 'payment.control.v0'
             ),
             updated_at = now()
       WHERE id = v_intent.payment_id;

      -- Load subscription context up front; recoverability classification needs it,
      -- and both the recoverable and terminal subscription branches reuse it.
      IF v_order.mode = 'subscription_cycle' THEN
        SELECT *
          INTO v_cycle
          FROM public.subscription_cycles
         WHERE id = v_order.subscription_cycle_id
         FOR UPDATE;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'payment_control_result_cycle_not_found' USING ERRCODE = '22023';
        END IF;

        SELECT *
          INTO v_subscription
          FROM public.subscriptions
         WHERE id = v_order.subscription_id
         FOR UPDATE;
        IF NOT FOUND THEN
          RAISE EXCEPTION 'payment_control_result_subscription_not_found' USING ERRCODE = '22023';
        END IF;
      END IF;

      -- A declined ('failed') INTERACTIVE attempt is recoverable: a one-time order,
      -- or a subscription activation while still provisional. Window 'expired' never
      -- is, and active renewals (subscription already past pending_activation) keep
      -- their dunning path. plpgsql short-circuits the OR, so v_subscription is
      -- only read when the order is a subscription_cycle (where it was loaded above).
      v_recoverable := (
        p_result_status = 'failed'
        AND (
          v_order.mode <> 'subscription_cycle'
          OR v_subscription.status = 'pending_activation'
        )
      );

      IF v_recoverable THEN
        -- Keep the order RE-PAYABLE: status stays pending_payment, the checkout
        -- inventory hold is RETAINED, and (for subscriptions) the provisional stays
        -- pending_activation with its activation cycle re-attemptable. No terminal
        -- transition, no reservation release, and no subscription_events row — there
        -- must be no "activation failed" notification for a retryable decline.
        UPDATE public.commerce_orders
           SET metadata = metadata || jsonb_build_object(
                 'paymentStatus', 'declined',
                 'failureReason', COALESCE(p_failure_reason, p_result_status),
                 'lastDeclineAt', p_occurred_at,
                 'recoverable', true,
                 'source', 'payment.control.v0'
               ),
               updated_at = now()
         WHERE id = v_order.id;

        IF v_order.mode = 'subscription_cycle' THEN
          UPDATE public.subscription_cycles
             SET retry_attempt = v_cycle.retry_attempt + 1,
                 next_retry_at = NULL,
                 failure_reason = COALESCE(p_failure_reason, p_result_status),
                 updated_at = now()
           WHERE id = v_cycle.id;
        ELSE
          -- One-time order: the pre-20260709120000 trigger used to fire here (the
          -- order transitioned straight to 'failed'). It structurally cannot fire
          -- any more since the order stays pending_payment, so emit the same
          -- commerce.payment.failed event/idempotency-key inline instead — the
          -- customer still gets the "retry your payment" nudge immediately, and a
          -- later genuine expiry replays harmlessly onto the same key.
          INSERT INTO public.outbox_events (
            aggregate_type,
            aggregate_id,
            event_type,
            idempotency_key,
            payload,
            metadata
          )
          VALUES (
            'commerce_order',
            v_order.id,
            'commerce.payment.failed',
            'payment_failed:' || v_order.id::text,
            jsonb_build_object(
              'orderId', 'order_' || v_order.id::text,
              'orderUuid', v_order.id,
              'totalCents', v_order.total_cents,
              'currency', v_order.currency,
              'occurredAt', p_occurred_at
            ),
            jsonb_build_object('source', 'commerce_payment_control_apply_result_recoverable_decline')
          )
          ON CONFLICT (event_type, idempotency_key) DO NOTHING;
        END IF;

        v_business_kind := 'recoverable_decline';
      ELSIF v_order.mode = 'subscription_cycle' THEN
        IF v_subscription.status = 'pending_activation' THEN
          -- A2 (terminal): an EXPIRED first charge. The provisional subscription
          -- never activated, so there is nothing to renew. Fail the order, release
          -- the checkout inventory hold, terminalize the provisional, and emit NO
          -- dunning/retry (the active-renewal branch below is left untouched).
          UPDATE public.subscription_cycles
             SET status = 'payment_failed',
                 retry_attempt = v_cycle.retry_attempt + 1,
                 next_retry_at = NULL,
                 failure_reason = COALESCE(p_failure_reason, p_result_status),
                 updated_at = now()
           WHERE id = v_cycle.id;

          UPDATE public.subscriptions
             SET status = 'activation_failed',
                 updated_at = now()
           WHERE id = v_subscription.id;

          UPDATE public.commerce_orders
             SET status = p_result_status,
                 metadata = metadata || jsonb_build_object(
                   'paymentStatus', p_result_status,
                   'failureReason', COALESCE(p_failure_reason, p_result_status),
                   'subscriptionActivation', 'activation_failed',
                   'source', 'payment.control.v0'
                 ),
                 updated_at = now()
           WHERE id = v_order.id;

          PERFORM public.commerce_release_order_reservations(v_order.id, 'subscription_activation_failed');

          INSERT INTO public.subscription_events (
            subscription_id,
            cycle_id,
            event_type,
            idempotency_key,
            payload,
            occurred_at
          )
          VALUES (
            v_subscription.id,
            v_cycle.id,
            'subscription.activation_failed',
            p_idempotency_key || ':subscription_event',
            jsonb_build_object(
              'paymentIntentId', v_intent.id,
              'paymentAttemptId', v_attempt.id,
              'paymentId', v_intent.payment_id,
              'orderId', v_order.id,
              'failureReason', COALESCE(p_failure_reason, p_result_status),
              'source', 'payment.control.v0'
            ),
            p_occurred_at
          )
          ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
        ELSE
          -- Active renewal (cycle #2+): the dunning/retry ladder. A refusal whose
          -- class this deployment lists as terminating is given no next charge at
          -- all; every other refusal - an unlisted class, an unrecognised one, and
          -- an unclassified NULL alike - walks exactly the rungs it walked before.
          -- The guard fails OPEN by construction: only an explicit membership can
          -- shorten the ladder, so no absent or unknown class can silently do it.
          v_retry_attempt := v_cycle.retry_attempt + 1;
          v_next_retry_at := CASE
            WHEN p_failure_class IS NOT NULL
              AND p_failure_class = ANY (v_terminating_classes) THEN NULL
            WHEN v_retry_attempt = 1 THEN p_occurred_at + interval '24 hours'
            WHEN v_retry_attempt = 2 THEN p_occurred_at + interval '72 hours'
            WHEN v_retry_attempt = 3 THEN p_occurred_at + interval '168 hours'
            ELSE NULL
          END;
          v_cycle_status := CASE WHEN v_next_retry_at IS NULL THEN 'payment_failed' ELSE 'retry_scheduled' END;

          UPDATE public.subscription_cycles
             SET status = v_cycle_status,
                 retry_attempt = v_retry_attempt,
                 next_retry_at = v_next_retry_at,
                 failure_reason = COALESCE(p_failure_reason, p_result_status),
                 updated_at = now()
           WHERE id = v_cycle.id;

          INSERT INTO public.subscription_events (
            subscription_id,
            cycle_id,
            event_type,
            idempotency_key,
            payload,
            occurred_at
          )
          VALUES (
            v_cycle.subscription_id,
            v_cycle.id,
            CASE WHEN v_next_retry_at IS NULL THEN 'subscription.payment_failed' ELSE 'subscription.retry_scheduled' END,
            p_idempotency_key || ':subscription_event',
            jsonb_build_object(
              'paymentIntentId', v_intent.id,
              'paymentAttemptId', v_attempt.id,
              'paymentId', v_intent.payment_id,
              'failureReason', COALESCE(p_failure_reason, p_result_status),
              'retryAttempt', v_retry_attempt,
              'nextRetryAt', v_next_retry_at,
              'source', 'payment.control.v0'
            ),
            p_occurred_at
          )
          ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
        END IF;
      ELSE
        -- One-time terminal (EXPIRED session). Fail the order and release the
        -- checkout inventory hold inline so stock is not stranded until the expiry
        -- sweep. Idempotent — replays and redeliveries no-op once rows leave
        -- 'reserved'. (A declined one-time order took the recoverable branch above.)
        UPDATE public.commerce_orders
           SET status = p_result_status,
               metadata = metadata || jsonb_build_object(
                 'paymentStatus', p_result_status,
                 'failureReason', COALESCE(p_failure_reason, p_result_status),
                 'source', 'payment.control.v0'
               ),
               updated_at = now()
         WHERE id = v_order.id;

        PERFORM public.commerce_release_order_reservations(v_order.id, 'payment_' || p_result_status);
      END IF;
    END IF;
  ELSIF p_result_status IN ('refunded', 'partially_refunded', 'disputed') THEN
    IF v_intent.status NOT IN ('succeeded', 'partially_refunded', 'refunded', 'disputed') THEN
      RAISE EXCEPTION 'payment_control_result_refund_or_dispute_requires_success' USING ERRCODE = '22023';
    END IF;

    UPDATE public.commerce_payment_intents
       SET status = p_result_status,
           updated_at = now()
     WHERE id = v_intent.id;

    UPDATE public.commerce_payments
       SET status = p_result_status,
           metadata = metadata || jsonb_build_object('paymentStatus', p_result_status, 'source', 'payment.control.v0'),
           updated_at = now()
     WHERE id = v_intent.payment_id;

    IF p_result_status = 'refunded' THEN
      UPDATE public.commerce_orders
         SET status = 'refunded',
             metadata = metadata || jsonb_build_object('paymentStatus', 'refunded', 'source', 'payment.control.v0'),
             updated_at = now()
       WHERE id = v_order.id;

      -- A3: a full refund/chargeback of the ACTIVATING cycle (cycle_number=1)
      -- reverses activation — otherwise a refunded first cycle leaves a live
      -- subscription that bills again. Renewal refunds (cycle #2+) are untouched.
      IF v_order.mode = 'subscription_cycle'
         AND v_order.subscription_cycle_id IS NOT NULL
         AND v_order.subscription_id IS NOT NULL THEN
        SELECT *
          INTO v_cycle
          FROM public.subscription_cycles
         WHERE id = v_order.subscription_cycle_id
         FOR UPDATE;
        SELECT *
          INTO v_subscription
          FROM public.subscriptions
         WHERE id = v_order.subscription_id
         FOR UPDATE;

        IF v_cycle.cycle_number = 1 AND v_subscription.status IN ('active', 'pending_activation') THEN
          UPDATE public.subscription_cycles
             SET status = 'cancelled',
                 paid_at = NULL,
                 next_retry_at = NULL,
                 failure_reason = COALESCE(failure_reason, 'refund_reversed_activation'),
                 updated_at = now()
           WHERE id = v_cycle.id;

          UPDATE public.subscriptions
             SET status = 'cancelled',
                 ended_at = p_occurred_at,
                 updated_at = now()
           WHERE id = v_subscription.id;

          PERFORM public.commerce_release_order_reservations(v_order.id, 'subscription_activation_refunded');

          INSERT INTO public.subscription_events (
            subscription_id,
            cycle_id,
            event_type,
            idempotency_key,
            payload,
            occurred_at
          )
          VALUES (
            v_subscription.id,
            v_cycle.id,
            'subscription.activation_reversed',
            p_idempotency_key || ':subscription_event',
            jsonb_build_object(
              'paymentIntentId', v_intent.id,
              'paymentAttemptId', v_attempt.id,
              'paymentId', v_intent.payment_id,
              'orderId', v_order.id,
              'reason', 'refund_reversed_activation',
              'source', 'payment.control.v0'
            ),
            p_occurred_at
          )
          ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
        END IF;
      END IF;
    END IF;
  END IF;

  IF p_payment_event_id IS NOT NULL THEN
    UPDATE public.inbound_provider_events
       SET processed_at = now(),
           processing_status = CASE WHEN v_business_kind LIKE 'ignored%' THEN 'ignored' ELSE 'processed' END
     WHERE id = p_payment_event_id;
  END IF;

  INSERT INTO public.commerce_payment_state_transitions (
    payment_intent_id,
    payment_attempt_id,
    provider_event_id,
    transition_kind,
    from_status,
    to_status,
    reason,
    idempotency_key,
    occurred_at,
    payload
  )
  VALUES (
    v_intent.id,
    v_attempt.id,
    p_payment_event_id,
    CASE
      WHEN p_result_status IN ('refunded', 'partially_refunded') THEN 'refund'
      WHEN p_result_status = 'disputed' THEN 'dispute'
      ELSE 'business_result'
    END,
    v_intent.status,
    p_result_status,
    v_business_kind,
    p_idempotency_key || ':payment_result',
    p_occurred_at,
    jsonb_build_object('orderId', v_order.id, 'resultStatus', p_result_status, 'source', 'payment.control.v0')
  );

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'paymentResult', jsonb_build_object(
      'paymentIntentId', v_intent.id,
      'paymentAttemptId', v_attempt.id,
      'paymentId', v_intent.payment_id,
      'orderId', v_order.id,
      'status', p_result_status,
      'kind', v_business_kind,
      'idempotencyKey', p_idempotency_key,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('paymentIntentId', v_intent.id, 'paymentAttemptId', v_attempt.id)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: commerce_payment_control_apply_reconciliation_result(text, uuid, uuid, uuid, uuid, text, text, text, text, text, timestamp with time zone, text, timestamp with time zone, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_apply_reconciliation_result(p_idempotency_key text, p_expected_order_id uuid, p_expected_payment_intent_id uuid, p_expected_payment_attempt_id uuid, p_expected_payment_id uuid, p_provider text, p_provider_payment_id text, p_local_status text, p_provider_status text, p_result_status text, p_occurred_at timestamp with time zone, p_failure_reason text, p_checked_at timestamp with time zone, p_payload jsonb, p_failure_class text DEFAULT NULL::text, p_failure_class_decided_by text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_apply jsonb;
  v_payment_result jsonb;
  v_evidence jsonb;
  v_dunning jsonb;
  v_existing_evidence public.commerce_payment_reconciliation_runs%ROWTYPE;
  v_evidence_key text;
  v_evidence_payload jsonb;
  v_kind text;
  v_correction_status text;
  v_applied boolean;
  v_apply_replayed boolean;
  v_evidence_replayed boolean := false;
  v_dunning_replayed boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_expected_order_id IS NULL
    OR p_expected_payment_intent_id IS NULL
    OR p_expected_payment_attempt_id IS NULL
    OR p_expected_payment_id IS NULL
    OR p_provider IS NULL OR btrim(p_provider) = ''
    OR p_provider_payment_id IS NULL OR btrim(p_provider_payment_id) = ''
    OR p_local_status IS NULL OR btrim(p_local_status) = ''
    OR p_provider_status IS NULL OR btrim(p_provider_status) = ''
    OR p_result_status NOT IN ('succeeded', 'failed')
    OR p_occurred_at IS NULL
    OR p_checked_at IS NULL
    OR (p_payload IS NOT NULL AND jsonb_typeof(p_payload) <> 'object')
  THEN
    RAISE EXCEPTION 'payment_reconciliation_apply_invalid_input' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('commerce.payment.reconciliation.apply:' || p_idempotency_key, 0)
  );

  -- Named notation, not positional: this RPC carried six parameters until
  -- 20260806120000 appended two more, and the class must land in the parameter
  -- that bears its name rather than in whatever slot counting happens to reach.
  v_apply := public.commerce_payment_control_apply_result(
    p_idempotency_key => p_idempotency_key,
    p_payment_intent_id => p_expected_payment_intent_id,
    p_payment_event_id => NULL,
    p_result_status => p_result_status,
    p_occurred_at => p_occurred_at,
    p_failure_reason => p_failure_reason,
    p_failure_class => p_failure_class,
    p_failure_class_decided_by => p_failure_class_decided_by
  );
  v_payment_result := v_apply -> 'paymentResult';

  IF v_payment_result IS NULL
    OR v_payment_result ->> 'status' IS DISTINCT FROM p_result_status
    OR NULLIF(btrim(v_payment_result ->> 'kind'), '') IS NULL
    OR (v_payment_result ->> 'paymentIntentId')::uuid IS DISTINCT FROM p_expected_payment_intent_id
    OR (v_payment_result ->> 'paymentAttemptId')::uuid IS DISTINCT FROM p_expected_payment_attempt_id
    OR (v_payment_result ->> 'paymentId')::uuid IS DISTINCT FROM p_expected_payment_id
    OR (v_payment_result ->> 'orderId')::uuid IS DISTINCT FROM p_expected_order_id
  THEN
    RAISE EXCEPTION 'payment_reconciliation_apply_claim_mismatch' USING ERRCODE = '22023';
  END IF;

  v_kind := v_payment_result ->> 'kind';
  v_correction_status := CASE WHEN v_kind LIKE 'ignored%' THEN 'ignored' ELSE 'corrected' END;
  v_applied := v_correction_status = 'corrected';
  v_apply_replayed := COALESCE((v_payment_result ->> 'replayed')::boolean, false);

  IF p_result_status = 'failed' AND v_kind NOT LIKE 'ignored%' THEN
    -- The sixth argument is the whole point of this migration: the case that
    -- opens here now knows WHY the payment was refused, not merely that it was.
    -- Only the class travels; the deciding rule is a diagnostic that belongs on
    -- the attempt's payload, which the apply_result call above already handled.
    v_dunning := public.subscription_open_dunning_from_failed_payment_result(
      p_idempotency_key || ':dunning',
      p_expected_payment_intent_id,
      NULL,
      p_failure_reason,
      p_occurred_at,
      p_failure_class
    );
    v_dunning_replayed := COALESCE(
      (v_dunning #>> '{subscriptionWebhookDunning,replayed}')::boolean,
      false
    );
  END IF;

  v_evidence_key := p_idempotency_key || ':evidence';
  v_evidence_payload := COALESCE(p_payload, '{}'::jsonb) || jsonb_build_object(
    'applied', v_applied,
    'resultStatus', p_result_status,
    'resultKind', v_kind
  );

  SELECT *
    INTO v_existing_evidence
    FROM public.commerce_payment_reconciliation_runs
   WHERE idempotency_key = v_evidence_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing_evidence.provider IS DISTINCT FROM p_provider
      OR v_existing_evidence.provider_payment_id IS DISTINCT FROM p_provider_payment_id
      OR v_existing_evidence.payment_intent_id IS DISTINCT FROM p_expected_payment_intent_id
      OR v_existing_evidence.payment_attempt_id IS DISTINCT FROM p_expected_payment_attempt_id
      OR v_existing_evidence.local_status IS DISTINCT FROM p_local_status
      OR v_existing_evidence.provider_status IS DISTINCT FROM p_provider_status
      OR v_existing_evidence.correction_status IS DISTINCT FROM v_correction_status
      OR v_existing_evidence.checked_at IS DISTINCT FROM p_checked_at
      OR v_existing_evidence.payload IS DISTINCT FROM v_evidence_payload
    THEN
      RAISE EXCEPTION 'payment_reconciliation_apply_evidence_conflict' USING ERRCODE = '23505';
    END IF;
    v_evidence_replayed := true;
  END IF;

  v_evidence := public.commerce_payment_control_record_reconciliation(
    v_evidence_key,
    p_provider,
    p_provider_payment_id,
    p_expected_payment_intent_id,
    p_expected_payment_attempt_id,
    p_local_status,
    p_provider_status,
    v_correction_status,
    p_checked_at,
    v_evidence_payload
  );

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'paymentReconciliationApply', jsonb_build_object(
      'paymentResult', v_payment_result,
      'paymentReconciliation', v_evidence -> 'paymentReconciliation',
      'subscriptionWebhookDunning', v_dunning -> 'subscriptionWebhookDunning',
      'correctionStatus', v_correction_status,
      'applied', v_applied,
      'applyReplayed', v_apply_replayed,
      'evidenceReplayed', v_evidence_replayed,
      'dunningReplayed', v_dunning_replayed,
      'replayed', v_apply_replayed AND v_evidence_replayed
        AND (v_dunning IS NULL OR v_dunning_replayed)
    )
  );
END;
$$;


--
-- Name: commerce_payment_control_apply_result(text, uuid, uuid, text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_apply_result(p_idempotency_key text, p_payment_intent_id uuid, p_payment_event_id uuid, p_result_status text, p_occurred_at timestamp with time zone, p_failure_reason text, p_failure_class text DEFAULT NULL::text, p_failure_class_decided_by text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_hint record;
  v_hint_found boolean := false;
  v_locked_intent record;
BEGIN
  SELECT payment_intent.subscription_id, payment_intent.order_id
    INTO v_hint
    FROM public.commerce_payment_intents payment_intent
   WHERE payment_intent.id = p_payment_intent_id;
  v_hint_found := FOUND;

  IF v_hint_found AND v_hint.subscription_id IS NOT NULL THEN
    PERFORM 1
      FROM public.subscriptions subscription
     WHERE subscription.id = v_hint.subscription_id
     FOR UPDATE;
  END IF;

  IF v_hint_found AND v_hint.order_id IS NOT NULL THEN
    PERFORM 1
      FROM public.commerce_orders checkout_order
     WHERE checkout_order.id = v_hint.order_id
     FOR UPDATE;
  END IF;

  IF v_hint_found THEN
    SELECT payment_intent.subscription_id, payment_intent.order_id
      INTO v_locked_intent
      FROM public.commerce_payment_intents payment_intent
     WHERE payment_intent.id = p_payment_intent_id
     FOR UPDATE;

    IF NOT FOUND
      OR v_locked_intent.subscription_id IS DISTINCT FROM v_hint.subscription_id
      OR v_locked_intent.order_id IS DISTINCT FROM v_hint.order_id
    THEN
      RAISE EXCEPTION 'payment_control_result_aggregate_changed'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  RETURN public.commerce_payment_apply_result_sealed_v1(
    p_idempotency_key,
    p_payment_intent_id,
    p_payment_event_id,
    p_result_status,
    p_occurred_at,
    p_failure_reason,
    p_failure_class,
    p_failure_class_decided_by
  );
END;
$$;


--
-- Name: FUNCTION commerce_payment_control_apply_result(p_idempotency_key text, p_payment_intent_id uuid, p_payment_event_id uuid, p_result_status text, p_occurred_at timestamp with time zone, p_failure_reason text, p_failure_class text, p_failure_class_decided_by text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_control_apply_result(p_idempotency_key text, p_payment_intent_id uuid, p_payment_event_id uuid, p_result_status text, p_occurred_at timestamp with time zone, p_failure_reason text, p_failure_class text, p_failure_class_decided_by text) IS 'Root-first payment result application. Locks linked subscription, order and intent before delegating to the sealed exact-event and failure-class body.';


--
-- Name: commerce_payment_control_create_intent(text, text, uuid, uuid, uuid, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_create_intent(p_idempotency_key text, p_target_kind text, p_order_id uuid, p_subscription_id uuid, p_subscription_cycle_id uuid, p_amount_cents integer, p_currency text, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.payment_intent.create';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_payment public.commerce_payments%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_target_kind NOT IN ('one_time_order', 'subscription_cycle')
    OR p_order_id IS NULL
    OR p_amount_cents IS NULL OR p_amount_cents < 1
    OR p_currency IS NULL OR char_length(p_currency) <> 3
  THEN
    RAISE EXCEPTION 'payment_control_intent_invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_target_kind = 'one_time_order'
    AND (p_subscription_id IS NOT NULL OR p_subscription_cycle_id IS NOT NULL)
  THEN
    RAISE EXCEPTION 'payment_control_intent_invalid_one_time_target' USING ERRCODE = '22023';
  END IF;

  IF p_target_kind = 'subscription_cycle'
    AND (p_subscription_id IS NULL OR p_subscription_cycle_id IS NULL)
  THEN
    RAISE EXCEPTION 'payment_control_intent_invalid_subscription_target' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    p_target_kind || '|' ||
    p_order_id::text || '|' ||
    COALESCE(p_subscription_id::text, '') || '|' ||
    COALESCE(p_subscription_cycle_id::text, '') || '|' ||
    p_amount_cents::text || '|' ||
    p_currency || '|' ||
    COALESCE(p_metadata, '{}'::jsonb)::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{paymentIntent,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'payment_control_intent_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_control_intent_order_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_order.total_cents <> p_amount_cents OR v_order.currency <> p_currency THEN
    RAISE EXCEPTION 'payment_control_intent_order_amount_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_order.status NOT IN ('draft', 'pending_payment') THEN
    RAISE EXCEPTION 'payment_control_intent_order_not_payable' USING ERRCODE = '22023';
  END IF;
  IF p_target_kind = 'subscription_cycle'
    AND (v_order.subscription_id IS DISTINCT FROM p_subscription_id
      OR v_order.subscription_cycle_id IS DISTINCT FROM p_subscription_cycle_id)
  THEN
    RAISE EXCEPTION 'payment_control_intent_subscription_order_mismatch' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (SELECT 1 FROM public.commerce_payment_intents WHERE order_id = p_order_id) THEN
    RAISE EXCEPTION 'payment_control_intent_order_already_has_intent' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'commerce_payment_control_create_intent')
  );

  SELECT *
    INTO v_payment
    FROM public.commerce_payments
   WHERE order_id = p_order_id
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;

  IF FOUND THEN
    IF v_payment.amount_cents <> p_amount_cents OR v_payment.currency <> p_currency THEN
      RAISE EXCEPTION 'payment_control_intent_existing_payment_mismatch' USING ERRCODE = '22023';
    END IF;
  ELSE
    INSERT INTO public.commerce_payments (
      order_id,
      provider,
      status,
      amount_cents,
      currency,
      metadata
    )
    VALUES (
      p_order_id,
      'payment_control',
      'pending',
      p_amount_cents,
      p_currency,
      jsonb_build_object('source', 'payment.control.v0', 'idempotencyKey', p_idempotency_key)
    )
    RETURNING * INTO v_payment;
  END IF;

  INSERT INTO public.commerce_payment_intents (
    target_kind,
    order_id,
    subscription_id,
    subscription_cycle_id,
    payment_id,
    status,
    amount_cents,
    currency,
    metadata
  )
  VALUES (
    p_target_kind,
    p_order_id,
    p_subscription_id,
    p_subscription_cycle_id,
    v_payment.id,
    'created',
    p_amount_cents,
    p_currency,
    COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('source', 'payment.control.v0')
  )
  RETURNING * INTO v_intent;

  UPDATE public.commerce_orders
     SET status = 'pending_payment',
         metadata = metadata || jsonb_build_object('paymentStatus', 'pending', 'paymentIntentId', v_intent.id),
         updated_at = now()
   WHERE id = p_order_id;

  INSERT INTO public.commerce_payment_state_transitions (
    payment_intent_id,
    transition_kind,
    to_status,
    reason,
    idempotency_key,
    payload
  )
  VALUES (
    v_intent.id,
    'intent',
    'created',
    'payment_intent_created',
    p_idempotency_key || ':intent_created',
    jsonb_build_object('targetKind', p_target_kind, 'orderId', p_order_id, 'paymentId', v_payment.id)
  );

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'paymentIntent', jsonb_build_object(
      'id', v_intent.id,
      'paymentId', v_payment.id,
      'orderId', p_order_id,
      'targetKind', p_target_kind,
      'status', v_intent.status,
      'amountCents', p_amount_cents,
      'currency', p_currency,
      'idempotencyKey', p_idempotency_key,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('paymentIntentId', v_intent.id, 'paymentId', v_payment.id)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: commerce_payment_control_finalize_before_sub_lock(text, uuid, uuid, text, text, text, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_finalize_before_sub_lock(p_idempotency_key text, p_payment_intent_id uuid, p_payment_attempt_id uuid, p_provider_idempotency_key text, p_provider_request_fingerprint text, p_provider_attempt_id text, p_provider_session_id text, p_attempt_status text, p_next_action_kind text, p_request_payload jsonb, p_response_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.payment_attempt.finalize_provider';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_attempt public.commerce_payment_attempts%ROWTYPE;
  v_from_status text;
  v_intent_status text;
  v_payment_status text;
  v_request_payload jsonb;
  v_response_payload jsonb;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_payment_intent_id IS NULL
    OR p_payment_attempt_id IS NULL
    OR p_provider_idempotency_key IS NULL OR btrim(p_provider_idempotency_key) = ''
    OR p_provider_request_fingerprint IS NULL OR btrim(p_provider_request_fingerprint) = ''
    OR p_attempt_status NOT IN ('sent_to_provider', 'requires_action', 'processing')
  THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_finalize_invalid_input' USING ERRCODE = '22023';
  END IF;
  IF p_next_action_kind IS NOT NULL
    AND p_next_action_kind NOT IN ('redirect', '3ds_challenge', 'qr_code', 'blik_code_prompt', 'sca_required')
  THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_finalize_invalid_next_action' USING ERRCODE = '22023';
  END IF;

  v_request_payload := COALESCE(p_request_payload, '{}'::jsonb);
  v_response_payload := COALESCE(p_response_payload, '{}'::jsonb);
  v_request_fingerprint := md5(
    p_payment_intent_id::text || '|' ||
    p_payment_attempt_id::text || '|' ||
    p_provider_idempotency_key || '|' ||
    p_provider_request_fingerprint || '|' ||
    COALESCE(p_provider_attempt_id, '') || '|' ||
    COALESCE(p_provider_session_id, '') || '|' ||
    p_attempt_status || '|' ||
    COALESCE(p_next_action_kind, '') || '|' ||
    v_request_payload::text || '|' ||
    v_response_payload::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      SELECT *
        INTO v_attempt
        FROM public.commerce_payment_attempts
       WHERE id = p_payment_attempt_id;

      IF FOUND THEN
        RETURN jsonb_build_object(
          'contractVersion', 'commerce.v0',
          'paymentAttempt', jsonb_build_object(
            'id', v_attempt.id,
            'paymentIntentId', v_attempt.payment_intent_id,
            'status', v_attempt.status,
            'provider', v_attempt.provider,
            'providerAttemptId', v_attempt.provider_attempt_id,
            'providerSessionId', v_attempt.provider_session_id,
            'nextActionKind', v_attempt.next_action_kind,
            'idempotencyKey', p_idempotency_key,
            'replayed', true
          )
        );
      END IF;

      RETURN jsonb_set(v_existing.response_payload, '{paymentAttempt,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'payment_control_provider_attempt_finalize_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_attempt
    FROM public.commerce_payment_attempts
   WHERE id = p_payment_attempt_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_finalize_attempt_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.payment_intent_id IS DISTINCT FROM p_payment_intent_id THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_finalize_intent_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.status <> 'created' THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_finalize_not_prepared' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.request_payload ->> 'providerIdempotencyKey' IS DISTINCT FROM p_provider_idempotency_key
    OR v_attempt.request_payload ->> 'providerRequestFingerprint' IS DISTINCT FROM p_provider_request_fingerprint
  THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_finalize_fingerprint_mismatch' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_finalize_intent_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_intent.active_attempt_id IS DISTINCT FROM v_attempt.id THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_finalize_active_attempt_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_intent.status IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed') THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_finalize_intent_terminal' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'commerce_payment_control_finalize_provider_attempt')
  );

  v_from_status := v_attempt.status;
  UPDATE public.commerce_payment_attempts
     SET provider_attempt_id = p_provider_attempt_id,
         provider_session_id = p_provider_session_id,
         status = p_attempt_status,
         next_action_kind = p_next_action_kind,
         request_payload = request_payload || v_request_payload,
         response_payload = response_payload || v_response_payload || jsonb_build_object('providerCall', true),
         updated_at = now()
   WHERE id = v_attempt.id
   RETURNING * INTO v_attempt;

  v_intent_status := CASE WHEN p_attempt_status = 'requires_action' THEN 'requires_action' ELSE 'processing' END;
  v_payment_status := CASE WHEN p_attempt_status = 'requires_action' THEN 'requires_action' ELSE 'pending' END;

  UPDATE public.commerce_payment_intents
     SET status = v_intent_status,
         updated_at = now()
   WHERE id = v_intent.id;

  UPDATE public.commerce_payments
     SET status = v_payment_status,
         provider = v_attempt.provider,
         provider_payment_id = COALESCE(p_provider_attempt_id, provider_payment_id),
         metadata = metadata || jsonb_build_object(
           'paymentIntentId', v_intent.id,
           'paymentAttemptId', v_attempt.id,
           'source', 'payment.control.v0'
         ),
         updated_at = now()
   WHERE id = v_intent.payment_id;

  INSERT INTO public.outbox_events (
    aggregate_type,
    aggregate_id,
    event_type,
    idempotency_key,
    payload,
    metadata
  )
  VALUES (
    'commerce_payment_intent',
    v_intent.id,
    'commerce.payment_attempt.requested',
    p_idempotency_key,
    jsonb_build_object(
      'paymentIntentId', v_intent.id,
      'paymentAttemptId', v_attempt.id,
      'provider', v_attempt.provider,
      'attemptStatus', p_attempt_status,
      'providerCall', true,
      'amountCents', v_intent.amount_cents,
      'currency', v_intent.currency
    ),
    jsonb_build_object('boundary', 'commerce_payment_control_finalize_provider_attempt')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  INSERT INTO public.commerce_payment_state_transitions (
    payment_intent_id,
    payment_attempt_id,
    transition_kind,
    from_status,
    to_status,
    reason,
    idempotency_key,
    payload
  )
  VALUES (
    v_intent.id,
    v_attempt.id,
    'attempt',
    v_from_status,
    p_attempt_status,
    'provider_attempt_finalized',
    p_idempotency_key || ':attempt_finalized',
    jsonb_build_object(
      'provider', v_attempt.provider,
      'providerAttemptId', p_provider_attempt_id,
      'providerCall', true
    )
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'paymentAttempt', jsonb_build_object(
      'id', v_attempt.id,
      'paymentIntentId', v_intent.id,
      'status', v_attempt.status,
      'provider', v_attempt.provider,
      'providerAttemptId', v_attempt.provider_attempt_id,
      'providerSessionId', v_attempt.provider_session_id,
      'nextActionKind', v_attempt.next_action_kind,
      'idempotencyKey', p_idempotency_key,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('paymentIntentId', v_intent.id, 'paymentAttemptId', v_attempt.id)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: commerce_payment_control_finalize_provider_attempt(text, uuid, uuid, text, text, text, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_finalize_provider_attempt(p_idempotency_key text, p_payment_intent_id uuid, p_payment_attempt_id uuid, p_provider_idempotency_key text, p_provider_request_fingerprint text, p_provider_attempt_id text, p_provider_session_id text, p_attempt_status text, p_next_action_kind text, p_request_payload jsonb, p_response_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_intent_hint record;
  v_intent public.commerce_payment_intents%ROWTYPE;
BEGIN
  SELECT payment_intent.target_kind, payment_intent.subscription_id
    INTO v_intent_hint
    FROM public.commerce_payment_intents payment_intent
   WHERE payment_intent.id = p_payment_intent_id;

  IF NOT FOUND THEN
    RETURN public.commerce_payment_control_finalize_before_sub_lock(
      p_idempotency_key, p_payment_intent_id, p_payment_attempt_id,
      p_provider_idempotency_key, p_provider_request_fingerprint,
      p_provider_attempt_id, p_provider_session_id, p_attempt_status,
      p_next_action_kind, p_request_payload, p_response_payload
    );
  END IF;

  IF v_intent_hint.target_kind = 'subscription_cycle'
    AND v_intent_hint.subscription_id IS NOT NULL
  THEN
    PERFORM 1
      FROM public.subscriptions subscription
     WHERE subscription.id = v_intent_hint.subscription_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'payment_control_provider_attempt_finalize_subscription_mismatch'
        USING ERRCODE = '22023';
    END IF;

    SELECT *
      INTO v_intent
      FROM public.commerce_payment_intents payment_intent
     WHERE payment_intent.id = p_payment_intent_id
     FOR UPDATE;
    IF NOT FOUND
      OR v_intent.target_kind IS DISTINCT FROM 'subscription_cycle'
      OR v_intent.subscription_id IS DISTINCT FROM v_intent_hint.subscription_id
    THEN
      RAISE EXCEPTION 'payment_control_provider_attempt_finalize_subscription_mismatch'
        USING ERRCODE = '22023';
    END IF;
  ELSE
    -- One-time prepare and apply-result already start from the intent. Acquiring
    -- it here before the unchanged inner body takes the attempt removes the
    -- attempt/intent ABBA with a late acknowledgement or absence decision.
    SELECT *
      INTO v_intent
      FROM public.commerce_payment_intents payment_intent
     WHERE payment_intent.id = p_payment_intent_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RETURN public.commerce_payment_control_finalize_before_sub_lock(
        p_idempotency_key, p_payment_intent_id, p_payment_attempt_id,
        p_provider_idempotency_key, p_provider_request_fingerprint,
        p_provider_attempt_id, p_provider_session_id, p_attempt_status,
        p_next_action_kind, p_request_payload, p_response_payload
      );
    END IF;
  END IF;

  RETURN public.commerce_payment_control_finalize_before_sub_lock(
    p_idempotency_key, p_payment_intent_id, p_payment_attempt_id,
    p_provider_idempotency_key, p_provider_request_fingerprint,
    p_provider_attempt_id, p_provider_session_id, p_attempt_status,
    p_next_action_kind, p_request_payload, p_response_payload
  );
END;
$$;


--
-- Name: commerce_payment_control_ingest_event(text, text, text, text, uuid, uuid, integer, text, boolean, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_ingest_event(p_provider text, p_provider_event_id text, p_event_type text, p_provider_payment_id text, p_payment_intent_id uuid, p_payment_attempt_id uuid, p_amount_cents integer, p_currency text, p_signature_verified boolean, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_attempt public.commerce_payment_attempts%ROWTYPE;
  v_payment_intent_id uuid := p_payment_intent_id;
  v_payment_attempt_id uuid := p_payment_attempt_id;
  v_event public.inbound_provider_events%ROWTYPE;
  v_replayed boolean := false;
  v_truth jsonb := p_payload -> '__paymentTruth';
  v_event_fingerprint text := v_truth ->> 'fingerprint';
  v_source_evidence jsonb := COALESCE(v_truth -> 'evidence', '{}'::jsonb);
BEGIN
  IF p_provider IS NULL OR btrim(p_provider) = ''
    OR p_provider_event_id IS NULL OR btrim(p_provider_event_id) = ''
    OR p_event_type NOT IN (
      'payment.requires_action',
      'payment.succeeded',
      'payment.failed',
      'payment.refunded',
      'payment.disputed',
      'setup.succeeded',
      'setup.failed',
      'setup.requires_action'
    )
    OR p_signature_verified IS DISTINCT FROM true
    OR (v_truth IS NOT NULL AND jsonb_typeof(v_truth) <> 'object')
    OR (v_event_fingerprint IS NOT NULL AND v_event_fingerprint !~ '^[0-9a-f]{64}$')
    OR (v_truth IS NOT NULL AND (
      v_event_fingerprint IS NULL
      OR jsonb_typeof(v_source_evidence) <> 'object'
    ))
  THEN
    RAISE EXCEPTION 'payment_control_event_invalid_or_unverified' USING ERRCODE = '22023';
  END IF;

  IF v_payment_attempt_id IS NULL AND p_provider_payment_id IS NOT NULL THEN
    SELECT *
      INTO v_attempt
      FROM public.commerce_payment_attempts
     WHERE provider = p_provider
       AND provider_attempt_id = p_provider_payment_id
     ORDER BY created_at DESC
     LIMIT 1;

    IF FOUND THEN
      v_payment_attempt_id := v_attempt.id;
      v_payment_intent_id := COALESCE(v_payment_intent_id, v_attempt.payment_intent_id);
    END IF;
  END IF;

  INSERT INTO public.inbound_provider_events (
    provider,
    provider_event_id,
    event_type,
    processing_status,
    payload,
    error,
    payment_intent_id,
    payment_attempt_id,
    provider_payment_id,
    amount_cents,
    currency,
    signature_verified,
    received_via,
    event_fingerprint,
    source_evidence
  )
  VALUES (
    p_provider,
    p_provider_event_id,
    p_event_type,
    'received',
    COALESCE(p_payload, '{}'::jsonb) - '__paymentTruth',
    '{}'::jsonb,
    v_payment_intent_id,
    v_payment_attempt_id,
    p_provider_payment_id,
    p_amount_cents,
    p_currency,
    true,
    'payment.control.v0',
    v_event_fingerprint,
    v_source_evidence
  )
  ON CONFLICT (provider, provider_event_id) DO NOTHING
  RETURNING * INTO v_event;

  IF NOT FOUND THEN
    v_replayed := true;
    SELECT *
      INTO v_event
      FROM public.inbound_provider_events
     WHERE provider = p_provider
       AND provider_event_id = p_provider_event_id
     FOR UPDATE;

    IF v_event.event_fingerprint IS NOT NULL
      AND v_event_fingerprint IS NOT NULL
      AND v_event_fingerprint IS DISTINCT FROM v_event.event_fingerprint
    THEN
      RAISE EXCEPTION 'commerce_payment_event_idempotency_conflict'
        USING ERRCODE = '23505';
    END IF;

    IF v_event.event_fingerprint IS NULL AND v_event_fingerprint IS NOT NULL THEN
      UPDATE public.inbound_provider_events
         SET event_fingerprint = v_event_fingerprint,
             source_evidence = v_source_evidence
       WHERE id = v_event.id
       RETURNING * INTO v_event;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'paymentEvent', jsonb_build_object(
      'id', v_event.id,
      'provider', p_provider,
      'providerEventId', p_provider_event_id,
      'eventType', p_event_type,
      'paymentIntentId', v_event.payment_intent_id,
      'paymentAttemptId', v_event.payment_attempt_id,
      'eventFingerprint', v_event.event_fingerprint,
      'replayed', v_replayed
    )
  );
END;
$_$;


--
-- Name: commerce_payment_control_mark_setup_event_processed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_mark_setup_event_processed(p_payment_event_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_updated integer := 0;
BEGIN
  IF p_payment_event_id IS NULL THEN
    RAISE EXCEPTION 'payment_control_mark_setup_event_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- Defense in depth: only a still-open ledger row of a setup event can be
  -- closed. Replays (already processed) and non-setup events fall through to
  -- updated=false instead of raising — mirrors the ingest RPC's replay softness.
  UPDATE public.inbound_provider_events
     SET processed_at = now(),
         processing_status = 'processed'
   WHERE id = p_payment_event_id
     AND processing_status = 'received'
     AND processed_at IS NULL
     AND event_type LIKE 'setup.%';

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'setupEventProcessed', jsonb_build_object('updated', v_updated > 0)
  );
END;
$$;


--
-- Name: FUNCTION commerce_payment_control_mark_setup_event_processed(p_payment_event_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_control_mark_setup_event_processed(p_payment_event_id uuid) IS 'Stamps a still-received setup.* inbound provider event as processed once the webhook setup pipeline (mandate upsert + activation) completed without error.';


--
-- Name: commerce_payment_control_mark_timeout(text, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_mark_timeout(p_idempotency_key text, p_payment_attempt_id uuid, p_expired_at timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_attempt public.commerce_payment_attempts%ROWTYPE;
BEGIN
  SELECT *
    INTO v_attempt
    FROM public.commerce_payment_attempts
   WHERE id = p_payment_attempt_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_control_timeout_attempt_not_found' USING ERRCODE = '22023';
  END IF;

  RETURN public.commerce_payment_control_apply_result(
    p_idempotency_key,
    v_attempt.payment_intent_id,
    NULL,
    'expired',
    p_expired_at,
    COALESCE(p_reason, 'payment_timeout')
  );
END;
$$;


--
-- Name: commerce_payment_control_prepare_attempt_unguarded(text, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_prepare_attempt_unguarded(p_idempotency_key text, p_payment_intent_id uuid, p_provider text, p_provider_idempotency_key text, p_provider_request_fingerprint text, p_provider_flow text, p_payment_method_ref text, p_request_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.payment_attempt.prepare_provider';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_attempt public.commerce_payment_attempts%ROWTYPE;
  v_attempt_id uuid;
  v_request_payload jsonb;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_payment_intent_id IS NULL
    OR p_provider IS NULL OR btrim(p_provider) = ''
    OR p_provider_idempotency_key IS NULL OR btrim(p_provider_idempotency_key) = ''
    OR p_provider_request_fingerprint IS NULL OR btrim(p_provider_request_fingerprint) = ''
    OR p_provider_flow IS NULL OR btrim(p_provider_flow) = ''
  THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_prepare_invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_provider_flow NOT IN (
    'one_time_payment',
    'setup_reusable_method',
    'off_session_payment',
    'blik_one_time',
    'blik_one_click',
    'pbl_one_time',
    'blik_recurring_activation',
    'recurring_charge'
  ) THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_prepare_invalid_flow' USING ERRCODE = '22023';
  END IF;

  v_request_payload := COALESCE(p_request_payload, '{}'::jsonb) || jsonb_build_object(
    'providerIdempotencyKey', p_provider_idempotency_key,
    'providerRequestFingerprint', p_provider_request_fingerprint,
    'providerFlow', p_provider_flow,
    'paymentMethodRef', p_payment_method_ref
  );

  v_request_fingerprint := md5(
    p_payment_intent_id::text || '|' ||
    p_provider || '|' ||
    p_provider_idempotency_key || '|' ||
    p_provider_request_fingerprint || '|' ||
    p_provider_flow || '|' ||
    COALESCE(p_payment_method_ref, '') || '|' ||
    v_request_payload::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      v_attempt_id := (v_existing.response_payload -> 'paymentAttempt' ->> 'id')::uuid;
      SELECT *
        INTO v_attempt
        FROM public.commerce_payment_attempts
       WHERE id = v_attempt_id;

      IF FOUND THEN
        RETURN jsonb_build_object(
          'contractVersion', 'commerce.v0',
          'paymentAttempt', jsonb_build_object(
            'id', v_attempt.id,
            'paymentIntentId', v_attempt.payment_intent_id,
            'status', v_attempt.status,
            'provider', v_attempt.provider,
            'providerAttemptId', v_attempt.provider_attempt_id,
            'providerSessionId', v_attempt.provider_session_id,
            'nextActionKind', v_attempt.next_action_kind,
            'idempotencyKey', p_idempotency_key,
            'replayed', true
          )
        );
      END IF;

      RETURN jsonb_set(v_existing.response_payload, '{paymentAttempt,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'payment_control_provider_attempt_prepare_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_prepare_intent_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_intent.status IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed') THEN
    RAISE EXCEPTION 'payment_control_provider_attempt_prepare_intent_not_retryable' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'commerce_payment_control_prepare_provider_attempt')
  );

  INSERT INTO public.commerce_payment_attempts (
    payment_intent_id,
    payment_id,
    provider,
    provider_attempt_id,
    provider_session_id,
    idempotency_key,
    status,
    amount_cents,
    currency,
    next_action_kind,
    request_payload,
    response_payload
  )
  VALUES (
    v_intent.id,
    v_intent.payment_id,
    p_provider,
    NULL,
    NULL,
    p_idempotency_key,
    'created',
    v_intent.amount_cents,
    v_intent.currency,
    NULL,
    v_request_payload,
    jsonb_build_object('providerCallPlanned', true, 'providerCall', false)
  )
  RETURNING * INTO v_attempt;

  UPDATE public.commerce_payment_intents
     SET active_attempt_id = v_attempt.id,
         status = 'processing',
         updated_at = now()
   WHERE id = v_intent.id;

  UPDATE public.commerce_payments
     SET status = 'pending',
         provider = p_provider,
         metadata = metadata || jsonb_build_object(
           'paymentIntentId', v_intent.id,
           'paymentAttemptId', v_attempt.id,
           'source', 'payment.control.v0'
         ),
         updated_at = now()
   WHERE id = v_intent.payment_id;

  INSERT INTO public.commerce_payment_state_transitions (
    payment_intent_id,
    payment_attempt_id,
    transition_kind,
    from_status,
    to_status,
    reason,
    idempotency_key,
    payload
  )
  VALUES (
    v_intent.id,
    v_attempt.id,
    'attempt',
    'created',
    'created',
    'provider_attempt_prepared',
    p_idempotency_key || ':attempt_prepared',
    jsonb_build_object(
      'provider', p_provider,
      'providerIdempotencyKey', p_provider_idempotency_key,
      'providerRequestFingerprint', p_provider_request_fingerprint,
      'providerFlow', p_provider_flow
    )
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'paymentAttempt', jsonb_build_object(
      'id', v_attempt.id,
      'paymentIntentId', v_intent.id,
      'status', v_attempt.status,
      'provider', v_attempt.provider,
      'providerAttemptId', v_attempt.provider_attempt_id,
      'providerSessionId', v_attempt.provider_session_id,
      'nextActionKind', v_attempt.next_action_kind,
      'idempotencyKey', p_idempotency_key,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('paymentIntentId', v_intent.id, 'paymentAttemptId', v_attempt.id)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: commerce_payment_control_prepare_before_sub_lock(text, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_prepare_before_sub_lock(p_idempotency_key text, p_payment_intent_id uuid, p_provider text, p_provider_idempotency_key text, p_provider_request_fingerprint text, p_provider_flow text, p_payment_method_ref text, p_request_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.payment_attempt.prepare_provider';
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_active_attempt public.commerce_payment_attempts%ROWTYPE;
  v_subscription_status text;
BEGIN
  -- Do not let an already-active attempt turn malformed input into a successful
  -- replay. Delegate invalid input so the applied body remains the error owner.
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_payment_intent_id IS NULL
    OR p_provider IS NULL OR btrim(p_provider) = ''
    OR p_provider_idempotency_key IS NULL OR btrim(p_provider_idempotency_key) = ''
    OR p_provider_request_fingerprint IS NULL OR btrim(p_provider_request_fingerprint) = ''
    OR p_provider_flow IS NULL OR btrim(p_provider_flow) = ''
    OR p_provider_flow NOT IN (
      'one_time_payment',
      'setup_reusable_method',
      'off_session_payment',
      'blik_one_time',
      'blik_one_click',
      'pbl_one_time',
      'blik_recurring_activation',
      'recurring_charge'
    )
  THEN
    RETURN public.commerce_payment_control_prepare_attempt_unguarded(
      p_idempotency_key,
      p_payment_intent_id,
      p_provider,
      p_provider_idempotency_key,
      p_provider_request_fingerprint,
      p_provider_flow,
      p_payment_method_ref,
      p_request_payload
    );
  END IF;

  -- This lock makes admission atomic across different client-generated keys.
  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id
   FOR UPDATE;

  -- Preserve all original validation/error semantics for missing or terminal
  -- intents. The applied body remains the single owner of those contracts.
  IF NOT FOUND
    OR v_intent.status IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed')
  THEN
    RETURN public.commerce_payment_control_prepare_attempt_unguarded(
      p_idempotency_key,
      p_payment_intent_id,
      p_provider,
      p_provider_idempotency_key,
      p_provider_request_fingerprint,
      p_provider_flow,
      p_payment_method_ref,
      p_request_payload
    );
  END IF;

  -- Existing keys still go through the original fingerprint check. Checking
  -- after the intent lock also preserves that behavior for concurrent same-key
  -- requests: the loser observes the winner's completed idempotency record.
  IF EXISTS (
    SELECT 1
      FROM public.commerce_idempotency_keys
     WHERE scope = v_scope
       AND idempotency_key = p_idempotency_key
  ) THEN
    RETURN public.commerce_payment_control_prepare_attempt_unguarded(
      p_idempotency_key,
      p_payment_intent_id,
      p_provider,
      p_provider_idempotency_key,
      p_provider_request_fingerprint,
      p_provider_flow,
      p_payment_method_ref,
      p_request_payload
    );
  END IF;

  IF v_intent.target_kind = 'subscription_cycle' THEN
    -- Share the subscription row as the durable admission fence with customer
    -- cancellation. If cancellation wins this lock, no fresh PSP call may start;
    -- if prepare wins, cancel observes the active attempt and asks the customer
    -- to retry instead of confirming before an in-flight charge can settle.
    SELECT subscription.status
      INTO v_subscription_status
      FROM public.subscriptions subscription
     WHERE subscription.id = v_intent.subscription_id
     FOR UPDATE;

    IF NOT FOUND OR v_subscription_status NOT IN ('pending_activation', 'active') THEN
      RAISE EXCEPTION 'payment_control_subscription_not_chargeable'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF v_intent.active_attempt_id IS NOT NULL THEN
    SELECT *
      INTO v_active_attempt
      FROM public.commerce_payment_attempts
     WHERE id = v_intent.active_attempt_id
     FOR UPDATE;

    -- blocked_preflight/failed/cancelled/expired are explicitly retryable.
    -- Every other status is fail-closed because a provider call may exist.
    IF FOUND AND v_active_attempt.status NOT IN (
      'blocked_preflight', 'failed', 'cancelled', 'expired'
    ) THEN
      RETURN jsonb_build_object(
        'contractVersion', 'commerce.v0',
        'paymentAttempt', jsonb_build_object(
          'id', v_active_attempt.id,
          'paymentIntentId', v_active_attempt.payment_intent_id,
          'status', v_active_attempt.status,
          'provider', v_active_attempt.provider,
          'providerAttemptId', v_active_attempt.provider_attempt_id,
          'providerSessionId', v_active_attempt.provider_session_id,
          'nextActionKind', v_active_attempt.next_action_kind,
          'idempotencyKey', v_active_attempt.idempotency_key,
          'replayed', true
        )
      );
    END IF;
  END IF;

  RETURN public.commerce_payment_control_prepare_attempt_unguarded(
    p_idempotency_key,
    p_payment_intent_id,
    p_provider,
    p_provider_idempotency_key,
    p_provider_request_fingerprint,
    p_provider_flow,
    p_payment_method_ref,
    p_request_payload
  );
END;
$$;


--
-- Name: FUNCTION commerce_payment_control_prepare_before_sub_lock(p_idempotency_key text, p_payment_intent_id uuid, p_provider text, p_provider_idempotency_key text, p_provider_request_fingerprint text, p_provider_flow text, p_payment_method_ref text, p_request_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_control_prepare_before_sub_lock(p_idempotency_key text, p_payment_intent_id uuid, p_provider text, p_provider_idempotency_key text, p_provider_request_fingerprint text, p_provider_flow text, p_payment_method_ref text, p_request_payload jsonb) IS 'Atomically admits one provider attempt per payment intent and delegates retryable or idempotent requests to the durable payment-control body.';


--
-- Name: commerce_payment_control_prepare_provider_attempt(text, uuid, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_prepare_provider_attempt(p_idempotency_key text, p_payment_intent_id uuid, p_provider text, p_provider_idempotency_key text, p_provider_request_fingerprint text, p_provider_flow text, p_payment_method_ref text, p_request_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_scope constant text := 'commerce.payment_attempt.prepare_provider';
  v_intent_hint record;
  v_intent_hint_found boolean := false;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_active_attempt public.commerce_payment_attempts%ROWTYPE;
  v_observed_success_attempt public.commerce_payment_attempts%ROWTYPE;
  v_subscription_status text;
  v_inline_retry boolean := COALESCE(p_request_payload->>'source', '') =
    'commerce.checkout-inline-recovery.prepare.v1';
  v_expected_attempt_id uuid;
  v_inline_purchase_context text;
BEGIN
  IF v_inline_retry THEN
    IF COALESCE(p_request_payload->>'expectedPaymentAttemptId', '') !~
         '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      OR COALESCE(p_request_payload->>'retryRequestId', '') !~
         '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
      OR COALESCE(p_request_payload->>'purchaseContext', '') NOT IN ('one_time', 'subscription_initial')
    THEN
      RAISE EXCEPTION 'payment_control_inline_retry_invalid_context'
        USING ERRCODE = '22023';
    END IF;
    v_expected_attempt_id := (p_request_payload->>'expectedPaymentAttemptId')::uuid;
    v_inline_purchase_context := p_request_payload->>'purchaseContext';
  END IF;

  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_payment_intent_id IS NULL
    OR p_provider IS NULL OR btrim(p_provider) = ''
    OR p_provider_idempotency_key IS NULL OR btrim(p_provider_idempotency_key) = ''
    OR p_provider_request_fingerprint IS NULL OR btrim(p_provider_request_fingerprint) = ''
    OR p_provider_flow IS NULL OR btrim(p_provider_flow) = ''
    OR p_provider_flow NOT IN (
      'one_time_payment', 'setup_reusable_method', 'off_session_payment',
      'blik_one_time', 'blik_one_click', 'pbl_one_time',
      'blik_recurring_activation', 'recurring_charge'
    )
  THEN
    RETURN public.commerce_payment_control_prepare_attempt_unguarded(
      p_idempotency_key, p_payment_intent_id, p_provider,
      p_provider_idempotency_key, p_provider_request_fingerprint,
      p_provider_flow, p_payment_method_ref, p_request_payload
    );
  END IF;

  -- Resolve the aggregate without a row lock, then acquire the aggregate root
  -- before any payment row. The intent is re-read under lock below.
  SELECT payment_intent.target_kind, payment_intent.subscription_id,
         payment_intent.order_id
    INTO v_intent_hint
   FROM public.commerce_payment_intents payment_intent
   WHERE payment_intent.id = p_payment_intent_id;
  v_intent_hint_found := FOUND;

  IF v_intent_hint_found AND v_intent_hint.subscription_id IS NOT NULL THEN
    SELECT subscription.status
      INTO v_subscription_status
      FROM public.subscriptions subscription
     WHERE subscription.id = v_intent_hint.subscription_id
     FOR UPDATE;
  END IF;

  -- Inline admission must prove the order is still payable in the same locked
  -- decision as the predecessor CAS. Acquire it before the intent/attempt so
  -- order-first cancellation cannot form an ABBA cycle with this route.
  IF v_intent_hint_found AND v_intent_hint.order_id IS NOT NULL THEN
    SELECT *
      INTO v_order
      FROM public.commerce_orders checkout_order
     WHERE checkout_order.id = v_intent_hint.order_id
     FOR UPDATE;
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents payment_intent
   WHERE payment_intent.id = p_payment_intent_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN public.commerce_payment_control_prepare_attempt_unguarded(
      p_idempotency_key, p_payment_intent_id, p_provider,
      p_provider_idempotency_key, p_provider_request_fingerprint,
      p_provider_flow, p_payment_method_ref, p_request_payload
    );
  END IF;

  IF v_intent_hint.target_kind IS DISTINCT FROM v_intent.target_kind
    OR v_intent_hint.subscription_id IS DISTINCT FROM v_intent.subscription_id
    OR v_intent_hint.order_id IS DISTINCT FROM v_intent.order_id
  THEN
    RAISE EXCEPTION 'payment_control_intent_aggregate_changed'
      USING ERRCODE = '55000';
  END IF;

  -- Inline cancellation races have a stable winner contract: once the order
  -- root is no longer payable, do not delegate through the legacy terminal-
  -- intent branch and never mint a post-cancel attempt.
  IF v_inline_retry AND (
    v_order.id IS NULL
    OR v_order.status <> 'pending_payment'
    OR COALESCE(v_order.metadata->>'paymentStatus', '') = 'expired'
  ) THEN
    RAISE EXCEPTION 'payment_control_inline_retry_order_not_payable'
      USING ERRCODE = '55000';
  END IF;

  IF v_intent.status IN (
    'succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed'
  ) THEN
    RETURN public.commerce_payment_control_prepare_attempt_unguarded(
      p_idempotency_key, p_payment_intent_id, p_provider,
      p_provider_idempotency_key, p_provider_request_fingerprint,
      p_provider_flow, p_payment_method_ref, p_request_payload
    );
  END IF;

  -- Preserve exact replay/fingerprint behavior after the aggregate fence.
  IF EXISTS (
    SELECT 1
      FROM public.commerce_idempotency_keys
     WHERE scope = v_scope
       AND idempotency_key = p_idempotency_key
  ) THEN
    RETURN public.commerce_payment_control_prepare_attempt_unguarded(
      p_idempotency_key, p_payment_intent_id, p_provider,
      p_provider_idempotency_key, p_provider_request_fingerprint,
      p_provider_flow, p_payment_method_ref, p_request_payload
    );
  END IF;

  -- A verified provider success can be durable before local result application
  -- converges the attempt and intent. Returning that exact attempt as a replay
  -- keeps every caller behind the existing provider_attempt_in_flight boundary
  -- and prevents not-chargeable cleanup from cancelling an already-paid order.
  SELECT payment_attempt.*
    INTO v_observed_success_attempt
    FROM public.commerce_payment_attempts payment_attempt
   WHERE payment_attempt.payment_intent_id = v_intent.id
     AND payment_attempt.payment_id = v_intent.payment_id
     AND (
       EXISTS (
         SELECT 1
           FROM public.inbound_provider_events provider_event
          WHERE provider_event.payment_intent_id = payment_attempt.payment_intent_id
            AND provider_event.payment_attempt_id = payment_attempt.id
            AND provider_event.provider = payment_attempt.provider
            AND provider_event.provider_payment_id = payment_attempt.provider_attempt_id
            AND provider_event.signature_verified IS TRUE
            AND provider_event.event_type = 'payment.succeeded'
       )
       OR EXISTS (
         SELECT 1
           FROM public.commerce_payment_reconciliation_runs reconciliation
          WHERE reconciliation.payment_intent_id = payment_attempt.payment_intent_id
            AND reconciliation.payment_attempt_id = payment_attempt.id
            AND reconciliation.provider = payment_attempt.provider
            AND reconciliation.provider_payment_id = CASE
              WHEN payment_attempt.provider = 'tpay'
                THEN payment_attempt.provider_session_id
              ELSE payment_attempt.provider_attempt_id
            END
            AND reconciliation.payload->>'normalizedStatus' = 'succeeded'
       )
     )
   ORDER BY payment_attempt.created_at DESC, payment_attempt.id DESC
   LIMIT 1
   FOR UPDATE;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'paymentAttempt', jsonb_build_object(
        'id', v_observed_success_attempt.id,
        'paymentIntentId', v_observed_success_attempt.payment_intent_id,
        'status', v_observed_success_attempt.status,
        'provider', v_observed_success_attempt.provider,
        'providerAttemptId', v_observed_success_attempt.provider_attempt_id,
        'providerSessionId', v_observed_success_attempt.provider_session_id,
        'nextActionKind', v_observed_success_attempt.next_action_kind,
        'idempotencyKey', v_observed_success_attempt.idempotency_key,
        'replayed', true
      )
    );
  END IF;

  IF v_inline_retry THEN
    IF v_intent.status <> 'failed'
      OR v_intent.active_attempt_id IS DISTINCT FROM v_expected_attempt_id
      OR v_intent.order_id IS DISTINCT FROM v_intent_hint.order_id
    THEN
      RAISE EXCEPTION 'payment_control_inline_retry_predecessor_mismatch'
        USING ERRCODE = '55000';
    END IF;

    SELECT *
      INTO v_active_attempt
      FROM public.commerce_payment_attempts payment_attempt
     WHERE payment_attempt.id = v_expected_attempt_id
       AND payment_attempt.payment_intent_id = v_intent.id
       AND payment_attempt.payment_id = v_intent.payment_id
     FOR UPDATE;

    IF NOT FOUND OR v_active_attempt.status <> 'failed' THEN
      RAISE EXCEPTION 'payment_control_inline_retry_predecessor_mismatch'
        USING ERRCODE = '55000';
    END IF;

    IF v_inline_purchase_context = 'subscription_initial' THEN
      IF v_intent.target_kind <> 'subscription_cycle'
        OR v_subscription_status IS DISTINCT FROM 'pending_activation'
        OR NOT (
          (p_provider = 'stripe' AND p_provider_flow = 'one_time_payment')
          OR (p_provider = 'tpay' AND p_provider_flow = 'blik_recurring_activation')
        )
      THEN
        RAISE EXCEPTION 'payment_control_inline_retry_context_mismatch'
          USING ERRCODE = '55000';
      END IF;
    ELSIF v_intent.target_kind <> 'one_time_order'
      OR NOT (
        (p_provider = 'stripe' AND p_provider_flow = 'one_time_payment')
        OR (p_provider = 'tpay' AND p_provider_flow = 'blik_one_time')
      )
    THEN
      RAISE EXCEPTION 'payment_control_inline_retry_context_mismatch'
        USING ERRCODE = '55000';
    END IF;
  END IF;

  IF v_intent.target_kind = 'subscription_cycle'
    AND (v_subscription_status IS NULL OR v_subscription_status NOT IN ('pending_activation', 'active'))
  THEN
    -- A pause can win after the cron created local artifacts but before the PSP
    -- boundary. Persist a truthful terminal cleanup, then return a typed marker;
    -- raising would roll the cleanup back. Customer cancellation performs the
    -- same cleanup in its own transaction.
    IF NOT EXISTS (
      SELECT 1
        FROM public.commerce_payment_attempts payment_attempt
       WHERE payment_attempt.payment_intent_id = v_intent.id
         AND payment_attempt.status NOT IN (
           'blocked_preflight', 'failed', 'cancelled', 'expired'
         )
    ) THEN
      UPDATE public.commerce_payment_intents
         SET status = 'cancelled',
             failure_reason = 'subscription_not_chargeable',
             updated_at = now()
       WHERE id = v_intent.id
         AND status IN ('created', 'failed');

      UPDATE public.subscription_cycles
         SET status = 'cancelled',
             next_retry_at = NULL,
             failure_reason = 'subscription_not_chargeable',
             updated_at = now()
       WHERE id = v_intent.subscription_cycle_id
         AND subscription_id = v_intent.subscription_id
         AND status IN ('payment_pending', 'retry_scheduled');

      -- The existing order-cancel trigger releases every reserved hold.
      UPDATE public.commerce_orders
         SET status = 'cancelled',
             metadata = metadata || jsonb_build_object(
               'paymentStatus', 'cancelled',
               'cancelReason', 'subscription_not_chargeable',
               'source', 'payment.control.prepare'
             ),
             updated_at = now()
       WHERE id = v_intent.order_id
         AND status = 'pending_payment';
    END IF;

    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'paymentAttemptAdmission', jsonb_build_object(
        'status', 'skipped_not_chargeable',
        'reason', 'payment_control_subscription_not_chargeable',
        'paymentIntentId', v_intent.id
      )
    );
  END IF;

  IF v_intent.active_attempt_id IS NOT NULL THEN
    SELECT *
      INTO v_active_attempt
      FROM public.commerce_payment_attempts payment_attempt
     WHERE payment_attempt.id = v_intent.active_attempt_id
     FOR UPDATE;

    IF FOUND AND v_active_attempt.status NOT IN (
      'blocked_preflight', 'failed', 'cancelled', 'expired'
    ) THEN
      RETURN jsonb_build_object(
        'contractVersion', 'commerce.v0',
        'paymentAttempt', jsonb_build_object(
          'id', v_active_attempt.id,
          'paymentIntentId', v_active_attempt.payment_intent_id,
          'status', v_active_attempt.status,
          'provider', v_active_attempt.provider,
          'providerAttemptId', v_active_attempt.provider_attempt_id,
          'providerSessionId', v_active_attempt.provider_session_id,
          'nextActionKind', v_active_attempt.next_action_kind,
          'idempotencyKey', v_active_attempt.idempotency_key,
          'replayed', true
        )
      );
    END IF;
  END IF;

  RETURN public.commerce_payment_control_prepare_attempt_unguarded(
    p_idempotency_key, p_payment_intent_id, p_provider,
    p_provider_idempotency_key, p_provider_request_fingerprint,
    p_provider_flow, p_payment_method_ref, p_request_payload
  );
END;
$_$;


--
-- Name: FUNCTION commerce_payment_control_prepare_provider_attempt(p_idempotency_key text, p_payment_intent_id uuid, p_provider text, p_provider_idempotency_key text, p_provider_request_fingerprint text, p_provider_flow text, p_payment_method_ref text, p_request_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_control_prepare_provider_attempt(p_idempotency_key text, p_payment_intent_id uuid, p_provider text, p_provider_idempotency_key text, p_provider_request_fingerprint text, p_provider_flow text, p_payment_method_ref text, p_request_payload jsonb) IS 'Root-first provider admission. Locks linked subscription and order before intent and attempt, refuses a fresh provider object after exact durable success evidence, and returns a typed compensated skip when the aggregate is no longer chargeable.';


--
-- Name: commerce_payment_control_record_attempt(text, uuid, text, text, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_record_attempt(p_idempotency_key text, p_payment_intent_id uuid, p_provider text, p_provider_attempt_id text, p_provider_session_id text, p_attempt_status text, p_next_action_kind text, p_request_payload jsonb, p_response_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.payment_attempt.record';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_attempt public.commerce_payment_attempts%ROWTYPE;
  v_intent_status text;
  v_payment_status text;
  v_provider_call boolean;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_payment_intent_id IS NULL
    OR p_provider IS NULL OR btrim(p_provider) = ''
    OR p_attempt_status NOT IN ('blocked_preflight', 'sent_to_provider', 'requires_action', 'processing')
  THEN
    RAISE EXCEPTION 'payment_control_attempt_invalid_input' USING ERRCODE = '22023';
  END IF;
  IF p_next_action_kind IS NOT NULL
    AND p_next_action_kind NOT IN ('redirect', '3ds_challenge', 'qr_code', 'blik_code_prompt', 'sca_required')
  THEN
    RAISE EXCEPTION 'payment_control_attempt_invalid_next_action' USING ERRCODE = '22023';
  END IF;
  IF p_attempt_status = 'blocked_preflight'
    AND (p_provider_attempt_id IS NOT NULL OR p_provider_session_id IS NOT NULL OR p_next_action_kind IS NOT NULL)
  THEN
    RAISE EXCEPTION 'payment_control_attempt_preflight_provider_facts' USING ERRCODE = '22023';
  END IF;

  v_provider_call := COALESCE((COALESCE(p_response_payload, '{}'::jsonb)->>'providerCall')::boolean, true);
  IF p_attempt_status = 'blocked_preflight' AND v_provider_call IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'payment_control_attempt_preflight_provider_call' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    p_payment_intent_id::text || '|' ||
    p_provider || '|' ||
    COALESCE(p_provider_attempt_id, '') || '|' ||
    COALESCE(p_provider_session_id, '') || '|' ||
    p_attempt_status || '|' ||
    COALESCE(p_next_action_kind, '') || '|' ||
    COALESCE(p_request_payload, '{}'::jsonb)::text || '|' ||
    COALESCE(p_response_payload, '{}'::jsonb)::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{paymentAttempt,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'payment_control_attempt_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_control_attempt_intent_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_intent.status IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed') THEN
    RAISE EXCEPTION 'payment_control_attempt_intent_not_retryable' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'commerce_payment_control_record_attempt')
  );

  INSERT INTO public.commerce_payment_attempts (
    payment_intent_id,
    payment_id,
    provider,
    provider_attempt_id,
    provider_session_id,
    idempotency_key,
    status,
    amount_cents,
    currency,
    next_action_kind,
    request_payload,
    response_payload
  )
  VALUES (
    v_intent.id,
    v_intent.payment_id,
    p_provider,
    p_provider_attempt_id,
    p_provider_session_id,
    p_idempotency_key,
    p_attempt_status,
    v_intent.amount_cents,
    v_intent.currency,
    p_next_action_kind,
    COALESCE(p_request_payload, '{}'::jsonb),
    COALESCE(p_response_payload, '{}'::jsonb)
  )
  RETURNING * INTO v_attempt;

  v_intent_status := CASE WHEN p_attempt_status = 'requires_action' THEN 'requires_action' ELSE 'processing' END;
  v_payment_status := CASE WHEN p_attempt_status = 'requires_action' THEN 'requires_action' ELSE 'pending' END;

  UPDATE public.commerce_payment_intents
     SET active_attempt_id = v_attempt.id,
         status = v_intent_status,
         updated_at = now()
   WHERE id = v_intent.id;

  UPDATE public.commerce_payments
     SET status = v_payment_status,
         provider = p_provider,
         provider_payment_id = COALESCE(p_provider_attempt_id, provider_payment_id),
         metadata = metadata || jsonb_build_object(
           'paymentIntentId', v_intent.id,
           'paymentAttemptId', v_attempt.id,
           'source', 'payment.control.v0'
         ),
         updated_at = now()
   WHERE id = v_intent.payment_id;

  INSERT INTO public.outbox_events (
    aggregate_type,
    aggregate_id,
    event_type,
    idempotency_key,
    payload,
    metadata
  )
  VALUES (
    'commerce_payment_intent',
    v_intent.id,
    'commerce.payment_attempt.requested',
    p_idempotency_key,
    jsonb_build_object(
      'paymentIntentId', v_intent.id,
      'paymentAttemptId', v_attempt.id,
      'provider', p_provider,
      'attemptStatus', p_attempt_status,
      'providerCall', v_provider_call,
      'amountCents', v_intent.amount_cents,
      'currency', v_intent.currency
    ),
    jsonb_build_object('boundary', 'commerce_payment_control_record_attempt')
  );

  INSERT INTO public.commerce_payment_state_transitions (
    payment_intent_id,
    payment_attempt_id,
    transition_kind,
    from_status,
    to_status,
    reason,
    idempotency_key,
    payload
  )
  VALUES (
    v_intent.id,
    v_attempt.id,
    'attempt',
    'created',
    p_attempt_status,
    CASE WHEN p_attempt_status = 'blocked_preflight' THEN 'provider_preflight_blocked' ELSE 'provider_attempt_recorded' END,
    p_idempotency_key || ':attempt_recorded',
    jsonb_build_object('provider', p_provider, 'providerAttemptId', p_provider_attempt_id, 'providerCall', v_provider_call)
  );

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'paymentAttempt', jsonb_build_object(
      'id', v_attempt.id,
      'paymentIntentId', v_intent.id,
      'status', p_attempt_status,
      'provider', p_provider,
      'idempotencyKey', p_idempotency_key,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('paymentIntentId', v_intent.id, 'paymentAttemptId', v_attempt.id)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: commerce_payment_control_record_reconciliation(text, text, text, uuid, uuid, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_record_reconciliation(p_idempotency_key text, p_provider text, p_provider_payment_id text, p_payment_intent_id uuid, p_payment_attempt_id uuid, p_local_status text, p_provider_status text, p_correction_status text, p_checked_at timestamp with time zone, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_run public.commerce_payment_reconciliation_runs%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_provider IS NULL OR btrim(p_provider) = ''
    OR p_local_status IS NULL OR btrim(p_local_status) = ''
    OR p_provider_status IS NULL OR btrim(p_provider_status) = ''
    OR p_correction_status NOT IN ('observed', 'corrected', 'ignored', 'failed')
  THEN
    RAISE EXCEPTION 'payment_control_reconciliation_invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_payment_reconciliation_runs (
    provider,
    provider_payment_id,
    payment_intent_id,
    payment_attempt_id,
    local_status,
    provider_status,
    correction_status,
    idempotency_key,
    checked_at,
    payload
  )
  VALUES (
    p_provider,
    p_provider_payment_id,
    p_payment_intent_id,
    p_payment_attempt_id,
    p_local_status,
    p_provider_status,
    p_correction_status,
    p_idempotency_key,
    COALESCE(p_checked_at, now()),
    COALESCE(p_payload, '{}'::jsonb)
  )
  ON CONFLICT (idempotency_key) DO UPDATE
    SET payload = public.commerce_payment_reconciliation_runs.payload
  RETURNING * INTO v_run;

  IF p_payment_intent_id IS NOT NULL THEN
    INSERT INTO public.commerce_payment_state_transitions (
      payment_intent_id,
      payment_attempt_id,
      transition_kind,
      from_status,
      to_status,
      reason,
      idempotency_key,
      occurred_at,
      payload
    )
    VALUES (
      p_payment_intent_id,
      p_payment_attempt_id,
      'reconciliation',
      p_local_status,
      p_provider_status,
      p_correction_status,
      p_idempotency_key || ':reconciliation',
      COALESCE(p_checked_at, now()),
      COALESCE(p_payload, '{}'::jsonb)
    )
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'paymentReconciliation', jsonb_build_object(
      'id', v_run.id,
      'paymentIntentId', p_payment_intent_id,
      'paymentAttemptId', p_payment_attempt_id,
      'localStatus', p_local_status,
      'providerStatus', p_provider_status,
      'correctionStatus', p_correction_status,
      'idempotencyKey', p_idempotency_key
    )
  );
END;
$$;


--
-- Name: commerce_payment_control_reopen_interactive_prepared_attempt(text, uuid, uuid, uuid, uuid, uuid, text, text, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_reopen_interactive_prepared_attempt(p_idempotency_key text, p_payment_attempt_id uuid, p_expected_payment_intent_id uuid, p_expected_order_id uuid, p_expected_subscription_id uuid, p_expected_subscription_cycle_id uuid, p_reopen_mode text, p_dispatch_state text, p_phase text, p_reason_code text, p_operator_ref text, p_absence_checked_at timestamp with time zone, p_absence_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_hint record;
  v_hint_found boolean := false;
  v_locked_intent record;
BEGIN
  SELECT payment_intent.subscription_id, payment_intent.subscription_cycle_id,
         payment_intent.order_id
    INTO v_hint
    FROM public.commerce_payment_intents payment_intent
   WHERE payment_intent.id = p_expected_payment_intent_id;
  v_hint_found := FOUND;

  IF v_hint_found AND v_hint.subscription_id IS NOT NULL THEN
    PERFORM 1 FROM public.subscriptions subscription
     WHERE subscription.id = v_hint.subscription_id FOR UPDATE;
  END IF;

  IF v_hint_found AND v_hint.order_id IS NOT NULL THEN
    PERFORM 1 FROM public.commerce_orders checkout_order
     WHERE checkout_order.id = v_hint.order_id FOR UPDATE;
  END IF;

  IF v_hint_found THEN
    SELECT payment_intent.subscription_id, payment_intent.subscription_cycle_id,
           payment_intent.order_id
      INTO v_locked_intent
      FROM public.commerce_payment_intents payment_intent
     WHERE payment_intent.id = p_expected_payment_intent_id
     FOR UPDATE;

    IF NOT FOUND
      OR v_locked_intent.subscription_id IS DISTINCT FROM v_hint.subscription_id
      OR v_locked_intent.subscription_cycle_id IS DISTINCT FROM v_hint.subscription_cycle_id
      OR v_locked_intent.order_id IS DISTINCT FROM v_hint.order_id
    THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_expected_ids_mismatch'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN public.commerce_payment_reopen_interactive_sealed_v1(
    p_idempotency_key,
    p_payment_attempt_id,
    p_expected_payment_intent_id,
    p_expected_order_id,
    p_expected_subscription_id,
    p_expected_subscription_cycle_id,
    p_reopen_mode,
    p_dispatch_state,
    p_phase,
    p_reason_code,
    p_operator_ref,
    p_absence_checked_at,
    p_absence_evidence
  );
END;
$$;


--
-- Name: FUNCTION commerce_payment_control_reopen_interactive_prepared_attempt(p_idempotency_key text, p_payment_attempt_id uuid, p_expected_payment_intent_id uuid, p_expected_order_id uuid, p_expected_subscription_id uuid, p_expected_subscription_cycle_id uuid, p_reopen_mode text, p_dispatch_state text, p_phase text, p_reason_code text, p_operator_ref text, p_absence_checked_at timestamp with time zone, p_absence_evidence jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_control_reopen_interactive_prepared_attempt(p_idempotency_key text, p_payment_attempt_id uuid, p_expected_payment_intent_id uuid, p_expected_order_id uuid, p_expected_subscription_id uuid, p_expected_subscription_cycle_id uuid, p_reopen_mode text, p_dispatch_state text, p_phase text, p_reason_code text, p_operator_ref text, p_absence_checked_at timestamp with time zone, p_absence_evidence jsonb) IS 'Root-first interactive Tpay prepared-attempt terminal boundary. It locks the linked subscription and order before the sealed exact-attempt reopen body.';


--
-- Name: commerce_payment_control_reopen_prepared_attempt_after_absence(text, uuid, uuid, uuid, text, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_control_reopen_prepared_attempt_after_absence(p_idempotency_key text, p_payment_attempt_id uuid, p_expected_payment_intent_id uuid, p_expected_subscription_cycle_id uuid, p_operator_ref text, p_absence_checked_at timestamp with time zone, p_next_retry_at timestamp with time zone, p_absence_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.payment_attempt.prepared_absence_reopen';
  v_min_stranded_age constant interval := interval '30 minutes';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_attempt public.commerce_payment_attempts%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_cycle public.subscription_cycles%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_latest_local_write timestamptz;
  v_from_attempt_status text;
  v_next_sequence integer;
  v_response jsonb;
  v_evidence jsonb;
BEGIN
  v_evidence := COALESCE(p_absence_evidence, '{}'::jsonb);

  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_payment_attempt_id IS NULL
    OR p_expected_payment_intent_id IS NULL
    OR p_expected_subscription_cycle_id IS NULL
    OR p_operator_ref IS NULL OR btrim(p_operator_ref) = '' OR length(btrim(p_operator_ref)) > 160
    OR p_absence_checked_at IS NULL
    OR p_next_retry_at IS NULL
    OR jsonb_typeof(v_evidence) <> 'object'
  THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_absence_checked_at > now() + interval '5 minutes' THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_absence_checked_at_in_future' USING ERRCODE = '22023';
  END IF;

  IF NOT (v_evidence @> '{"providerAbsenceConfirmed": true}'::jsonb) THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_requires_provider_absence_proof' USING ERRCODE = '22023';
  END IF;

  IF lower(v_evidence::text) ~ '(paymentmethodref|payment_method_ref|providermethodref|provider_method_ref|providercustomerref|provider_customer_ref|clientsecret|client_secret|recoverytoken|recovery_token|token_hash|blikcode|blik_code|payid|pay_id)' THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_sensitive_evidence' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    p_payment_attempt_id::text || '|' ||
    p_expected_payment_intent_id::text || '|' ||
    p_expected_subscription_cycle_id::text || '|' ||
    btrim(p_operator_ref) || '|' ||
    p_absence_checked_at::text || '|' ||
    p_next_retry_at::text || '|' ||
    v_evidence::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{preparedAttemptReopen,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'prepared_attempt_absence_reopen_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_attempt
    FROM public.commerce_payment_attempts
   WHERE id = p_payment_attempt_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_attempt_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.payment_intent_id IS DISTINCT FROM p_expected_payment_intent_id THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_intent_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.status <> 'created' THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_attempt_not_prepared' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.provider NOT IN ('stripe', 'tpay') THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_provider_not_supported' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.provider_attempt_id IS NOT NULL OR v_attempt.provider_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_provider_ref_exists' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.response_payload @> '{"providerCall": true}'::jsonb THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_provider_call_recorded' USING ERRCODE = '22023';
  END IF;
  IF NOT (v_attempt.request_payload ? 'providerIdempotencyKey')
    OR NOT (v_attempt.request_payload ? 'providerRequestFingerprint')
    OR NOT (v_attempt.request_payload ? 'providerFlow')
  THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_missing_provider_identity' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_expected_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_intent_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_intent.active_attempt_id IS DISTINCT FROM v_attempt.id THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_active_attempt_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_intent.target_kind <> 'subscription_cycle'
    OR v_intent.subscription_cycle_id IS DISTINCT FROM p_expected_subscription_cycle_id
  THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_cycle_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_intent.status NOT IN ('requires_action', 'processing') THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_intent_not_active' USING ERRCODE = '22023';
  END IF;
  IF v_intent.provider_payment_id IS NOT NULL THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_intent_provider_ref_exists' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_cycle
    FROM public.subscription_cycles
   WHERE id = p_expected_subscription_cycle_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_cycle_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_cycle.status <> 'payment_pending' THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_cycle_not_pending' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_order
    FROM public.commerce_orders
   WHERE id = v_intent.order_id
   FOR UPDATE;
  IF NOT FOUND
    OR v_order.mode <> 'subscription_cycle'
    OR v_order.subscription_cycle_id IS DISTINCT FROM v_cycle.id
    OR v_order.subscription_id IS DISTINCT FROM v_cycle.subscription_id
  THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_order_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_order.status <> 'pending_payment' THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_order_not_pending_payment' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.inbound_provider_events AS e
     WHERE e.payment_attempt_id = v_attempt.id
        OR e.payment_intent_id = v_intent.id
  ) THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_provider_event_exists' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.commerce_payment_reconciliation_runs AS r
     WHERE r.payment_attempt_id = v_attempt.id
       AND r.correction_status = 'corrected'
       AND r.provider_status IN ('succeeded', 'failed')
  ) THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_terminal_reconciliation_exists' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.commerce_payment_reconciliation_runs AS r
     WHERE r.payment_attempt_id = v_attempt.id
       AND r.provider_status IN ('prepared_attempt_claiming', 'prepared_without_provider_ack')
       AND r.correction_status IN ('observed', 'failed')
  ) THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_watchdog_evidence_missing' USING ERRCODE = '22023';
  END IF;

  v_latest_local_write := GREATEST(
    v_attempt.created_at,
    v_attempt.updated_at,
    v_intent.created_at,
    v_intent.updated_at
  );
  IF p_absence_checked_at < v_latest_local_write + v_min_stranded_age THEN
    RAISE EXCEPTION 'prepared_attempt_absence_reopen_too_fresh' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'commerce_payment_control_reopen_prepared_attempt_after_absence')
  );

  v_from_attempt_status := v_attempt.status;
  v_next_sequence := v_cycle.provider_attempt_sequence + 1;

  UPDATE public.commerce_payment_attempts
     SET status = 'cancelled',
         failure_reason = 'prepared_without_provider_ack_operator_cleared',
         response_payload = response_payload || jsonb_build_object(
           'providerCall', false,
           'providerAcknowledged', false,
           'operatorAbsenceClearedAt', p_absence_checked_at
         ),
         metadata = metadata || jsonb_build_object(
           'preparedAbsenceReopenedAt', p_absence_checked_at,
           'operatorRef', btrim(p_operator_ref),
           'providerAttemptSequence', v_next_sequence
         ),
         updated_at = now()
   WHERE id = v_attempt.id;

  UPDATE public.subscription_cycles
     SET status = 'retry_scheduled',
         next_retry_at = p_next_retry_at,
         provider_attempt_sequence = v_next_sequence,
         failure_reason = 'prepared_without_provider_ack_operator_cleared',
         updated_at = now()
   WHERE id = v_cycle.id
   RETURNING * INTO v_cycle;

  PERFORM public.commerce_payment_control_record_reconciliation(
    p_idempotency_key || ':provider_absence',
    v_attempt.provider,
    NULL,
    v_intent.id,
    v_attempt.id,
    v_from_attempt_status,
    'prepared_attempt_provider_absent',
    'corrected',
    p_absence_checked_at,
    jsonb_build_object(
      'source', 'payment-provider-reconciliation.prepared-absence-reopen.v0',
      'subscriptionId', v_cycle.subscription_id,
      'subscriptionCycleId', v_cycle.id,
      'orderId', v_order.id,
      'providerAbsenceConfirmed', true,
      'operatorRef', btrim(p_operator_ref),
      'nextRetryAt', p_next_retry_at,
      'retryAttemptPreserved', v_cycle.retry_attempt,
      'providerAttemptSequence', v_next_sequence,
      'evidence', v_evidence
    )
  );

  INSERT INTO public.commerce_payment_state_transitions (
    payment_intent_id,
    payment_attempt_id,
    transition_kind,
    from_status,
    to_status,
    reason,
    idempotency_key,
    occurred_at,
    payload
  )
  VALUES (
    v_intent.id,
    v_attempt.id,
    'attempt',
    v_from_attempt_status,
    'cancelled',
    'prepared_without_provider_ack_operator_cleared',
    p_idempotency_key || ':attempt_cancelled',
    p_absence_checked_at,
    jsonb_build_object(
      'source', 'payment-provider-reconciliation.prepared-absence-reopen.v0',
      'providerAttemptSequence', v_next_sequence,
      'retryAttemptPreserved', v_cycle.retry_attempt
    )
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  INSERT INTO public.subscription_events (
    subscription_id,
    cycle_id,
    event_type,
    idempotency_key,
    payload,
    occurred_at
  )
  VALUES (
    v_cycle.subscription_id,
    v_cycle.id,
    'subscription.retry_scheduled',
    p_idempotency_key || ':subscription_retry_scheduled',
    jsonb_build_object(
      'paymentIntentId', v_intent.id,
      'paymentAttemptId', v_attempt.id,
      'orderId', v_order.id,
      'reason', 'prepared_without_provider_ack_operator_cleared',
      'nextRetryAt', p_next_retry_at,
      'retryAttemptPreserved', v_cycle.retry_attempt,
      'providerAttemptSequence', v_next_sequence,
      'source', 'payment-provider-reconciliation.prepared-absence-reopen.v0'
    ),
    p_absence_checked_at
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'preparedAttemptReopen', jsonb_build_object(
      'paymentAttemptId', v_attempt.id,
      'paymentIntentId', v_intent.id,
      'subscriptionCycleId', v_cycle.id,
      'subscriptionId', v_cycle.subscription_id,
      'orderId', v_order.id,
      'attemptStatus', 'cancelled',
      'cycleStatus', v_cycle.status,
      'retryAttempt', v_cycle.retry_attempt,
      'providerAttemptSequence', v_next_sequence,
      'nextRetryAt', p_next_retry_at,
      'idempotencyKey', p_idempotency_key,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object(
           'paymentIntentId', v_intent.id,
           'paymentAttemptId', v_attempt.id,
           'subscriptionCycleId', v_cycle.id,
           'providerAttemptSequence', v_next_sequence
         )
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: FUNCTION commerce_payment_control_reopen_prepared_attempt_after_absence(p_idempotency_key text, p_payment_attempt_id uuid, p_expected_payment_intent_id uuid, p_expected_subscription_cycle_id uuid, p_operator_ref text, p_absence_checked_at timestamp with time zone, p_next_retry_at timestamp with time zone, p_absence_evidence jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_control_reopen_prepared_attempt_after_absence(p_idempotency_key text, p_payment_attempt_id uuid, p_expected_payment_intent_id uuid, p_expected_subscription_cycle_id uuid, p_operator_ref text, p_absence_checked_at timestamp with time zone, p_next_retry_at timestamp with time zone, p_absence_evidence jsonb) IS 'Service-role-only operator boundary. After provider-readback/absence proof, cancels a stale prepared subscription-cycle payment attempt, records reconciliation evidence, and reopens the existing cycle for cron retry using a fresh provider_attempt_sequence without incrementing customer retry_attempt.';


--
-- Name: commerce_payment_method_ref_deactivate(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_method_ref_deactivate(p_idempotency_key text, p_method_ref_id uuid, p_reason text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ref public.commerce_payment_method_refs%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR p_method_ref_id IS NULL THEN
    RAISE EXCEPTION 'payment_method_ref_deactivate_invalid_input' USING ERRCODE = '22023';
  END IF;

  UPDATE public.commerce_payment_method_refs
     SET active = false,
         status = CASE WHEN status = 'active' THEN 'inactive' ELSE status END,
         deactivated_at = coalesce(deactivated_at, now()),
         metadata = metadata || jsonb_build_object('deactivationReason', coalesce(p_reason, 'unspecified')) || coalesce(p_metadata, '{}'::jsonb),
         updated_at = now()
   WHERE id = p_method_ref_id
  RETURNING * INTO v_ref;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_method_ref_not_found' USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object('paymentMethodRef', jsonb_build_object('id', v_ref.id, 'active', v_ref.active, 'status', v_ref.status));
END;
$$;


--
-- Name: commerce_payment_method_ref_link_subscription_mirror(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_method_ref_link_subscription_mirror(p_idempotency_key text, p_subscription_id uuid, p_method_ref_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ref public.commerce_payment_method_refs%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = ''
    OR p_subscription_id IS NULL OR p_method_ref_id IS NULL THEN
    RAISE EXCEPTION 'payment_method_ref_link_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ref
    FROM public.commerce_payment_method_refs
   WHERE id = p_method_ref_id
     AND status = 'active'
     AND active = true
     AND (expires_at IS NULL OR expires_at > now());

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_method_ref_link_not_active' USING ERRCODE = '22023';
  END IF;

  -- Compatibility mirror only: do not mutate subscription status, cycle state,
  -- cadence, dunning, payment-control, fulfillment, inventory, or invoices.
  UPDATE public.subscriptions
     SET payment_method_ref = v_ref.provider_method_ref,
         payment_method_kind = v_ref.method_kind,
         updated_at = now()
   WHERE id = p_subscription_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_method_ref_subscription_not_found' USING ERRCODE = '22023';
  END IF;

  UPDATE public.commerce_payment_method_refs
     SET subscription_id = p_subscription_id, updated_at = now()
   WHERE id = v_ref.id;

  RETURN jsonb_build_object('subscriptionMirror', jsonb_build_object(
    'subscriptionId', p_subscription_id,
    'paymentMethodRef', v_ref.provider_method_ref,
    'paymentMethodKind', v_ref.method_kind,
    'lifecycleMutated', false
  ));
END;
$$;


--
-- Name: commerce_payment_method_ref_repair_subscription_scope(text, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_method_ref_repair_subscription_scope(p_idempotency_key text, p_subscription_id uuid, p_requested_at timestamp with time zone DEFAULT now(), p_source text DEFAULT 'renewal.pr4.scope_repair'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.payment_method_ref.scope_repair';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_target public.commerce_payment_method_refs%ROWTYPE;
  v_candidate_count integer := 0;
  v_deactivated_count integer := 0;
  v_status text := 'skipped';
  v_reason text;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = ''
    OR p_subscription_id IS NULL
    OR p_requested_at IS NULL
    OR p_source IS NULL OR btrim(p_source) = '' THEN
    RAISE EXCEPTION 'payment_method_ref_scope_repair_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(p_subscription_id::text || '|' || btrim(p_source));

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_fingerprint IS DISTINCT FROM v_request_fingerprint THEN
      RAISE EXCEPTION 'payment_method_ref_scope_repair_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_set(v_existing.response_payload, '{paymentMethodRefScopeRepair,replayed}', 'true'::jsonb, true);
  END IF;

  SELECT *
    INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
   FOR UPDATE;

  IF NOT FOUND THEN
    v_reason := 'subscription_not_found';
  ELSIF v_subscription.status <> 'active' THEN
    v_reason := 'subscription_not_active';
  ELSIF v_subscription.payment_method_ref IS NULL OR btrim(v_subscription.payment_method_ref) = '' THEN
    v_reason := 'subscription_missing_payment_method_ref';
  ELSE
    SELECT count(*)::integer
      INTO v_candidate_count
      FROM public.commerce_payment_method_refs pm
     WHERE pm.client_id = v_subscription.client_id
       AND pm.provider_method_ref = btrim(v_subscription.payment_method_ref)
       AND pm.status = 'active'
       AND pm.active = true
       AND (pm.expires_at IS NULL OR pm.expires_at > p_requested_at)
       AND (
         v_subscription.payment_method_kind IS NULL
         OR btrim(v_subscription.payment_method_kind) = ''
         OR pm.method_kind = btrim(v_subscription.payment_method_kind)
       )
       AND (pm.subscription_id IS NULL OR pm.subscription_id = v_subscription.id);

    IF v_candidate_count = 1 THEN
      SELECT *
        INTO v_target
        FROM public.commerce_payment_method_refs pm
       WHERE pm.client_id = v_subscription.client_id
         AND pm.provider_method_ref = btrim(v_subscription.payment_method_ref)
         AND pm.status = 'active'
         AND pm.active = true
         AND (pm.expires_at IS NULL OR pm.expires_at > p_requested_at)
         AND (
           v_subscription.payment_method_kind IS NULL
           OR btrim(v_subscription.payment_method_kind) = ''
           OR pm.method_kind = btrim(v_subscription.payment_method_kind)
         )
         AND (pm.subscription_id IS NULL OR pm.subscription_id = v_subscription.id)
       ORDER BY (pm.subscription_id = v_subscription.id) DESC, pm.updated_at DESC, pm.created_at DESC
       LIMIT 1
       FOR UPDATE;

      IF NOT FOUND THEN
        v_reason := 'candidate_race';
      ELSIF v_target.subscription_id = v_subscription.id THEN
        v_status := 'no_op';
        v_reason := 'already_subscription_scoped';
      ELSE
        -- CJ01-O posture: deactivate stale active subscription-scoped refs first,
        -- then promote the target. That avoids a transient double-active state.
        UPDATE public.commerce_payment_method_refs
           SET active = false,
               deactivated_at = coalesce(deactivated_at, p_requested_at),
               metadata = metadata || jsonb_build_object(
                 'deactivationReason', 'subscription_scope_repair_replaced',
                 'replacedByPaymentMethodRefId', v_target.id::text
               ),
               updated_at = p_requested_at
         WHERE subscription_id = v_subscription.id
           AND active = true
           AND id <> v_target.id;
        GET DIAGNOSTICS v_deactivated_count = ROW_COUNT;

        UPDATE public.commerce_payment_method_refs
           SET subscription_id = v_subscription.id,
               active = true,
               status = 'active',
               deactivated_at = NULL,
               metadata = metadata || jsonb_build_object(
                 'subscriptionScopeRepair', jsonb_build_object(
                   'source', btrim(p_source),
                   'repairedAt', p_requested_at,
                   'subscriptionId', v_subscription.id
                 )
               ),
               updated_at = p_requested_at
         WHERE id = v_target.id
        RETURNING * INTO v_target;

        UPDATE public.subscriptions
           SET payment_method_ref = v_target.provider_method_ref,
               payment_method_kind = coalesce(NULLIF(btrim(payment_method_kind), ''), v_target.method_kind),
               updated_at = p_requested_at
         WHERE id = v_subscription.id;

        INSERT INTO public.subscription_events (
          subscription_id,
          event_type,
          idempotency_key,
          payload,
          occurred_at
        )
        VALUES (
          v_subscription.id,
          'subscription.payment_method_ref_scope_repaired',
          p_idempotency_key || ':event',
          jsonb_build_object(
            'paymentMethodRefId', v_target.id,
            'providerKind', v_target.provider_kind,
            'methodKind', v_target.method_kind,
            'previousActiveRefsDeactivated', v_deactivated_count,
            'source', btrim(p_source)
          ),
          p_requested_at
        )
        ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

        v_status := 'repaired';
        v_reason := NULL;
      END IF;
    ELSIF v_candidate_count > 1 THEN
      v_reason := 'ambiguous_candidate';
    ELSIF EXISTS (
      SELECT 1
        FROM public.commerce_payment_method_refs pm
       WHERE pm.client_id = v_subscription.client_id
         AND pm.provider_method_ref = btrim(v_subscription.payment_method_ref)
         AND pm.status = 'active'
         AND pm.active = true
         AND (pm.expires_at IS NULL OR pm.expires_at > p_requested_at)
         AND (
           v_subscription.payment_method_kind IS NULL
           OR btrim(v_subscription.payment_method_kind) = ''
           OR pm.method_kind = btrim(v_subscription.payment_method_kind)
         )
         AND pm.subscription_id IS NOT NULL
         AND pm.subscription_id <> v_subscription.id
    ) THEN
      v_reason := 'wrong_subscription_owner';
    ELSIF EXISTS (
      SELECT 1
        FROM public.commerce_payment_method_refs pm
       WHERE pm.client_id <> v_subscription.client_id
         AND pm.provider_method_ref = btrim(v_subscription.payment_method_ref)
    ) THEN
      v_reason := 'cross_client_candidate';
    ELSIF EXISTS (
      SELECT 1
        FROM public.commerce_payment_method_refs pm
       WHERE pm.client_id = v_subscription.client_id
         AND pm.provider_method_ref = btrim(v_subscription.payment_method_ref)
    ) THEN
      v_reason := 'unusable_candidate';
    ELSE
      v_reason := 'no_matching_method_ref';
    END IF;
  END IF;

  v_response := jsonb_build_object(
    'paymentMethodRefScopeRepair', jsonb_build_object(
      'subscriptionId', p_subscription_id,
      'status', v_status,
      'reason', v_reason,
      'paymentMethodRefId', CASE WHEN v_status IN ('repaired', 'no_op') THEN v_target.id ELSE NULL END,
      'previousActiveRefsDeactivated', v_deactivated_count,
      'replayed', false
    )
  );

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    response_payload,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    v_response,
    'completed',
    jsonb_build_object('source', btrim(p_source), 'subscriptionId', p_subscription_id)
  );

  RETURN v_response;
END;
$$;


--
-- Name: FUNCTION commerce_payment_method_ref_repair_subscription_scope(p_idempotency_key text, p_subscription_id uuid, p_requested_at timestamp with time zone, p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_method_ref_repair_subscription_scope(p_idempotency_key text, p_subscription_id uuid, p_requested_at timestamp with time zone, p_source text) IS 'Service-role-only. Repairs one active subscription payment-method ref scope when an existing same-client active reusable method ref unambiguously matches the subscription mirror. No provider calls or lifecycle/charge side effects.';


--
-- Name: commerce_payment_method_ref_repair_subscription_scope_batch(integer, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_method_ref_repair_subscription_scope_batch(p_limit integer DEFAULT 100, p_apply boolean DEFAULT false, p_source text DEFAULT 'renewal.pr4.scope_repair.batch'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope_source text := coalesce(NULLIF(btrim(p_source), ''), 'renewal.pr4.scope_repair.batch');
  v_row record;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_repairable_count integer := 0;
  v_already_scoped_count integer := 0;
  v_ambiguous_count integer := 0;
  v_wrong_owner_count integer := 0;
  v_cross_client_count integer := 0;
  v_unusable_count integer := 0;
  v_no_candidate_count integer := 0;
  v_repaired_count integer := 0;
  v_replayed_count integer := 0;
BEGIN
  IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 500 THEN
    RAISE EXCEPTION 'payment_method_ref_scope_repair_batch_invalid_limit' USING ERRCODE = '22023';
  END IF;

  WITH active_subscriptions AS (
    SELECT s.*
      FROM public.subscriptions s
     WHERE s.status = 'active'
       AND s.payment_method_ref IS NOT NULL
       AND btrim(s.payment_method_ref) <> ''
  ),
  classified AS (
    SELECT
      s.id,
      (
        SELECT count(*)::integer
          FROM public.commerce_payment_method_refs pm
         WHERE pm.client_id = s.client_id
           AND pm.provider_method_ref = btrim(s.payment_method_ref)
           AND pm.status = 'active'
           AND pm.active = true
           AND (pm.expires_at IS NULL OR pm.expires_at > now())
           AND (
             s.payment_method_kind IS NULL
             OR btrim(s.payment_method_kind) = ''
             OR pm.method_kind = btrim(s.payment_method_kind)
           )
           AND (pm.subscription_id IS NULL OR pm.subscription_id = s.id)
      ) AS safe_count,
      EXISTS (
        SELECT 1
          FROM public.commerce_payment_method_refs pm
         WHERE pm.client_id = s.client_id
           AND pm.provider_method_ref = btrim(s.payment_method_ref)
           AND pm.status = 'active'
           AND pm.active = true
           AND (pm.expires_at IS NULL OR pm.expires_at > now())
           AND (
             s.payment_method_kind IS NULL
             OR btrim(s.payment_method_kind) = ''
             OR pm.method_kind = btrim(s.payment_method_kind)
           )
           AND pm.subscription_id IS NULL
      ) AS has_client_scoped_safe,
      EXISTS (
        SELECT 1
          FROM public.commerce_payment_method_refs pm
         WHERE pm.client_id = s.client_id
           AND pm.provider_method_ref = btrim(s.payment_method_ref)
           AND pm.status = 'active'
           AND pm.active = true
           AND (pm.expires_at IS NULL OR pm.expires_at > now())
           AND (
             s.payment_method_kind IS NULL
             OR btrim(s.payment_method_kind) = ''
             OR pm.method_kind = btrim(s.payment_method_kind)
           )
           AND pm.subscription_id = s.id
      ) AS has_subscription_scoped_safe,
      EXISTS (
        SELECT 1
          FROM public.commerce_payment_method_refs pm
         WHERE pm.client_id = s.client_id
           AND pm.provider_method_ref = btrim(s.payment_method_ref)
           AND pm.status = 'active'
           AND pm.active = true
           AND (pm.expires_at IS NULL OR pm.expires_at > now())
           AND (
             s.payment_method_kind IS NULL
             OR btrim(s.payment_method_kind) = ''
             OR pm.method_kind = btrim(s.payment_method_kind)
           )
           AND pm.subscription_id IS NOT NULL
           AND pm.subscription_id <> s.id
      ) AS has_wrong_owner,
      EXISTS (
        SELECT 1
          FROM public.commerce_payment_method_refs pm
         WHERE pm.client_id <> s.client_id
           AND pm.provider_method_ref = btrim(s.payment_method_ref)
      ) AS has_cross_client,
      EXISTS (
        SELECT 1
          FROM public.commerce_payment_method_refs pm
         WHERE pm.client_id = s.client_id
           AND pm.provider_method_ref = btrim(s.payment_method_ref)
      ) AS has_any_same_client
    FROM active_subscriptions s
  )
  SELECT
    count(*) FILTER (WHERE safe_count = 1 AND has_client_scoped_safe)::integer,
    count(*) FILTER (WHERE safe_count = 1 AND has_subscription_scoped_safe AND NOT has_client_scoped_safe)::integer,
    count(*) FILTER (WHERE safe_count > 1)::integer,
    count(*) FILTER (WHERE safe_count = 0 AND has_wrong_owner)::integer,
    count(*) FILTER (WHERE safe_count = 0 AND NOT has_wrong_owner AND has_cross_client)::integer,
    count(*) FILTER (WHERE safe_count = 0 AND NOT has_wrong_owner AND NOT has_cross_client AND has_any_same_client)::integer,
    count(*) FILTER (WHERE safe_count = 0 AND NOT has_wrong_owner AND NOT has_cross_client AND NOT has_any_same_client)::integer
    INTO
      v_repairable_count,
      v_already_scoped_count,
      v_ambiguous_count,
      v_wrong_owner_count,
      v_cross_client_count,
      v_unusable_count,
      v_no_candidate_count
    FROM classified;

  IF p_apply THEN
    FOR v_row IN
      WITH active_subscriptions AS (
        SELECT s.*
          FROM public.subscriptions s
         WHERE s.status = 'active'
           AND s.payment_method_ref IS NOT NULL
           AND btrim(s.payment_method_ref) <> ''
      )
      SELECT s.id
        FROM active_subscriptions s
       WHERE 1 = (
         SELECT count(*)::integer
           FROM public.commerce_payment_method_refs pm
          WHERE pm.client_id = s.client_id
            AND pm.provider_method_ref = btrim(s.payment_method_ref)
            AND pm.status = 'active'
            AND pm.active = true
            AND (pm.expires_at IS NULL OR pm.expires_at > now())
            AND (
              s.payment_method_kind IS NULL
              OR btrim(s.payment_method_kind) = ''
              OR pm.method_kind = btrim(s.payment_method_kind)
            )
            AND (pm.subscription_id IS NULL OR pm.subscription_id = s.id)
       )
       AND EXISTS (
         SELECT 1
           FROM public.commerce_payment_method_refs pm
          WHERE pm.client_id = s.client_id
            AND pm.provider_method_ref = btrim(s.payment_method_ref)
            AND pm.status = 'active'
            AND pm.active = true
            AND (pm.expires_at IS NULL OR pm.expires_at > now())
            AND (
              s.payment_method_kind IS NULL
              OR btrim(s.payment_method_kind) = ''
              OR pm.method_kind = btrim(s.payment_method_kind)
            )
            AND pm.subscription_id IS NULL
       )
       ORDER BY s.updated_at ASC, s.id ASC
       LIMIT p_limit
    LOOP
      SELECT public.commerce_payment_method_ref_repair_subscription_scope(
        'payment-method-ref-scope-repair:' || v_row.id::text,
        v_row.id,
        now(),
        v_scope_source
      ) INTO v_result;

      IF v_result #>> '{paymentMethodRefScopeRepair,status}' = 'repaired' THEN
        v_repaired_count := v_repaired_count + 1;
      END IF;
      IF v_result #>> '{paymentMethodRefScopeRepair,replayed}' = 'true' THEN
        v_replayed_count := v_replayed_count + 1;
      END IF;
      IF jsonb_array_length(v_results) < 20 THEN
        v_results := v_results || jsonb_build_array(v_result -> 'paymentMethodRefScopeRepair');
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'paymentMethodRefScopeRepairBatch', jsonb_build_object(
      'apply', p_apply,
      'limit', p_limit,
      'source', v_scope_source,
      'repairableCount', v_repairable_count,
      'alreadyScopedCount', v_already_scoped_count,
      'skippedCounts', jsonb_build_object(
        'ambiguousCandidate', v_ambiguous_count,
        'wrongSubscriptionOwner', v_wrong_owner_count,
        'crossClientCandidate', v_cross_client_count,
        'unusableCandidate', v_unusable_count,
        'noMatchingMethodRef', v_no_candidate_count
      ),
      'repairedCount', v_repaired_count,
      'replayedCount', v_replayed_count,
      'sampleResults', v_results
    )
  );
END;
$$;


--
-- Name: FUNCTION commerce_payment_method_ref_repair_subscription_scope_batch(p_limit integer, p_apply boolean, p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_method_ref_repair_subscription_scope_batch(p_limit integer, p_apply boolean, p_source text) IS 'Service-role-only. Dry-runs or applies bounded safe historical payment-method-ref scope repairs for renewal readiness; ambiguous rows are counted but not mutated.';


--
-- Name: commerce_payment_method_ref_switch_active(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_method_ref_switch_active(p_idempotency_key text, p_method_ref_id uuid, p_subscription_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ref public.commerce_payment_method_refs%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR p_method_ref_id IS NULL THEN
    RAISE EXCEPTION 'payment_method_ref_switch_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ref
    FROM public.commerce_payment_method_refs
   WHERE id = p_method_ref_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_method_ref_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_ref.status <> 'active' OR (v_ref.expires_at IS NOT NULL AND v_ref.expires_at <= now()) THEN
    RAISE EXCEPTION 'payment_method_ref_cannot_become_active' USING ERRCODE = '22023';
  END IF;

  UPDATE public.commerce_payment_method_refs
     SET active = false, deactivated_at = now(), updated_at = now()
   WHERE id <> v_ref.id
     AND (
       (p_subscription_id IS NOT NULL AND subscription_id = p_subscription_id)
       OR (p_subscription_id IS NULL AND client_id = v_ref.client_id AND subscription_id IS NULL)
     );

  UPDATE public.commerce_payment_method_refs
     SET active = true,
         subscription_id = coalesce(p_subscription_id, subscription_id),
         deactivated_at = NULL,
         updated_at = now()
   WHERE id = v_ref.id
  RETURNING * INTO v_ref;

  RETURN jsonb_build_object('paymentMethodRef', jsonb_build_object(
    'id', v_ref.id, 'subscriptionId', v_ref.subscription_id,
    'providerKind', v_ref.provider_kind, 'methodKind', v_ref.method_kind,
    'providerMethodRef', v_ref.provider_method_ref, 'active', v_ref.active
  ));
END;
$$;


--
-- Name: commerce_payment_method_ref_upsert(text, uuid, uuid, text, text, text, text, text, text, boolean, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_method_ref_upsert(p_idempotency_key text, p_client_id uuid, p_subscription_id uuid, p_provider_kind text, p_method_kind text, p_provider_customer_ref text, p_provider_method_ref text, p_provider_mandate_ref text, p_status text, p_active boolean, p_expires_at timestamp with time zone, p_consent_snapshot jsonb, p_raw_provider_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scope constant text := 'commerce.payment_method_ref.upsert';
  v_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_ref public.commerce_payment_method_refs%ROWTYPE;
  v_target_id uuid;
  v_was_inserted boolean;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = ''
    OR p_client_id IS NULL
    OR p_provider_kind IS NULL OR btrim(p_provider_kind) = ''
    OR p_method_kind NOT IN ('card', 'blik_payid', 'wallet', 'alias')
    OR p_provider_method_ref IS NULL OR btrim(p_provider_method_ref) = ''
    OR p_status NOT IN ('pending_verification', 'active', 'inactive', 'expired', 'revoked') THEN
    RAISE EXCEPTION 'payment_method_ref_invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_active AND p_status <> 'active' THEN
    RAISE EXCEPTION 'payment_method_ref_active_requires_active_status' USING ERRCODE = '22023';
  END IF;

  IF p_active AND p_expires_at IS NOT NULL AND p_expires_at <= now() THEN
    RAISE EXCEPTION 'payment_method_ref_expired_cannot_be_active' USING ERRCODE = '22023';
  END IF;

  v_fingerprint := md5(concat_ws('|',
    p_client_id::text, coalesce(p_subscription_id::text, ''), btrim(p_provider_kind),
    p_method_kind, coalesce(p_provider_customer_ref, ''), btrim(p_provider_method_ref),
    coalesce(p_provider_mandate_ref, ''), p_status, p_active::text, coalesce(p_expires_at::text, '')
  ));

  SELECT * INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.request_fingerprint IS DISTINCT FROM v_fingerprint THEN
      RAISE EXCEPTION 'payment_method_ref_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    -- A genuine idempotency-key replay: the stored payload was minted with
    -- replayed:false on the first call. Stamp it true so the replay reports
    -- honestly. create_if_missing => true defends a payload that somehow
    -- predates the replayed field; for current payloads it is a plain replace.
    RETURN jsonb_set(v_existing.response_payload, '{paymentMethodRef,replayed}', 'true'::jsonb, true);
  END IF;

  -- Deactivate any OTHER active ref in the same scope BEFORE inserting the new
  -- active row. Pre-resolving the target id (null for a brand-new method ref)
  -- lets us exclude the row we are about to activate. Doing this first avoids
  -- the transient "two active rows for one subscription" state that violated
  -- uniq_commerce_payment_method_refs_subscription_active (23505) when the prior
  -- ordering deactivated only AFTER the insert. Same scope/row-set as before —
  -- only the ordering moved.
  IF p_active THEN
    SELECT id INTO v_target_id
      FROM public.commerce_payment_method_refs
     WHERE provider_kind = btrim(p_provider_kind)
       AND provider_method_ref = btrim(p_provider_method_ref);

    UPDATE public.commerce_payment_method_refs
       SET active = false, deactivated_at = now(), updated_at = now()
     WHERE (v_target_id IS NULL OR id <> v_target_id)
       AND (
         (p_subscription_id IS NOT NULL AND subscription_id = p_subscription_id)
         OR (p_subscription_id IS NULL AND client_id = p_client_id AND subscription_id IS NULL)
       );
  END IF;

  INSERT INTO public.commerce_payment_method_refs (
    client_id, subscription_id, provider_kind, method_kind, provider_customer_ref,
    provider_method_ref, provider_mandate_ref, status, active, expires_at,
    consent_snapshot, raw_provider_payload
  )
  VALUES (
    p_client_id, p_subscription_id, btrim(p_provider_kind), p_method_kind, p_provider_customer_ref,
    btrim(p_provider_method_ref), p_provider_mandate_ref, p_status, p_active, p_expires_at,
    coalesce(p_consent_snapshot, '{}'::jsonb), coalesce(p_raw_provider_payload, '{}'::jsonb)
  )
  -- The conflict clause re-asserts the row's identity and its published facts.
  -- `consent_snapshot` is the one column that MERGES rather than replaces: a
  -- caller that knows only its own contribution must not be able to erase
  -- evidence recorded by an earlier writer. `||` is right-biased, so a key the
  -- caller does name still takes the caller's value.
  ON CONFLICT (provider_kind, provider_method_ref) DO UPDATE
    SET client_id = EXCLUDED.client_id,
        subscription_id = EXCLUDED.subscription_id,
        method_kind = EXCLUDED.method_kind,
        provider_customer_ref = EXCLUDED.provider_customer_ref,
        provider_mandate_ref = EXCLUDED.provider_mandate_ref,
        status = EXCLUDED.status,
        active = EXCLUDED.active,
        expires_at = EXCLUDED.expires_at,
        consent_snapshot = public.commerce_payment_method_refs.consent_snapshot || EXCLUDED.consent_snapshot,
        raw_provider_payload = EXCLUDED.raw_provider_payload,
        updated_at = now(),
        deactivated_at = CASE WHEN EXCLUDED.active THEN NULL ELSE public.commerce_payment_method_refs.deactivated_at END
  -- xmax = 0 on the affected row means a fresh INSERT (no prior row version);
  -- a non-zero xmax means the ON CONFLICT branch updated an existing row.
  -- %ROWTYPE cannot capture system columns, so read this flag on its own.
  RETURNING (xmax = 0) INTO v_was_inserted;

  -- Re-read the full row by its unique key for the response (the row is locked by
  -- this transaction, so this sees our own write).
  SELECT * INTO v_ref
    FROM public.commerce_payment_method_refs
   WHERE provider_kind = btrim(p_provider_kind)
     AND provider_method_ref = btrim(p_provider_method_ref);

  v_response := jsonb_build_object(
    'paymentMethodRef', jsonb_build_object(
      'id', v_ref.id,
      'clientId', v_ref.client_id,
      'subscriptionId', v_ref.subscription_id,
      'providerKind', v_ref.provider_kind,
      'methodKind', v_ref.method_kind,
      'providerMethodRef', v_ref.provider_method_ref,
      'status', v_ref.status,
      'active', v_ref.active,
      'replayed', NOT v_was_inserted
    )
  );

  INSERT INTO public.commerce_idempotency_keys (
    scope, idempotency_key, request_fingerprint, response_payload, status
  )
  VALUES (v_scope, p_idempotency_key, v_fingerprint, v_response, 'completed');

  RETURN v_response;
END;
$$;


--
-- Name: commerce_payment_reconciliation_claim_prepared_attempts(timestamp with time zone, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_reconciliation_claim_prepared_attempts(p_now timestamp with time zone DEFAULT now(), p_stale_after_seconds integer DEFAULT 900, p_limit integer DEFAULT 50, p_claim_key text DEFAULT NULL::text) RETURNS TABLE(payment_attempt_id uuid, payment_intent_id uuid, payment_id uuid, order_id uuid, subscription_id uuid, subscription_cycle_id uuid, provider text, provider_payment_id text, provider_attempt_id text, provider_session_id text, attempt_status text, intent_status text, amount_cents integer, currency text, order_mode text, cycle_retry_attempt integer, cycle_next_retry_at timestamp with time zone, local_updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_claim_key text;
  v_cutoff timestamptz;
BEGIN
  IF p_now IS NULL
    OR p_stale_after_seconds IS NULL
    OR p_stale_after_seconds < 60
    OR p_stale_after_seconds > 86400
    OR p_limit IS NULL
    OR p_limit < 1
    OR p_limit > 500
  THEN
    RAISE EXCEPTION 'payment_reconciliation_prepared_claim_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_claim_key := COALESCE(
    NULLIF(btrim(p_claim_key), ''),
    'payment-provider-reconciliation:prepared:' || floor(extract(epoch FROM p_now) / 1800)::bigint::text
  );
  IF length(v_claim_key) < 8 THEN
    RAISE EXCEPTION 'payment_reconciliation_prepared_claim_invalid_key' USING ERRCODE = '22023';
  END IF;

  v_cutoff := p_now - make_interval(secs => p_stale_after_seconds);

  RETURN QUERY
    WITH candidates AS (
      SELECT
        a.id AS payment_attempt_id,
        i.id AS payment_intent_id,
        i.payment_id,
        i.order_id,
        i.subscription_id,
        i.subscription_cycle_id,
        a.provider,
        NULL::text AS provider_payment_id,
        a.provider_attempt_id,
        a.provider_session_id,
        a.status AS attempt_status,
        i.status AS intent_status,
        a.amount_cents,
        a.currency,
        o.mode AS order_mode,
        COALESCE(c.retry_attempt, 0) AS cycle_retry_attempt,
        c.next_retry_at AS cycle_next_retry_at,
        GREATEST(a.updated_at, i.updated_at) AS local_updated_at,
        a.request_payload
      FROM public.commerce_payment_attempts AS a
      JOIN public.commerce_payment_intents AS i
        ON i.id = a.payment_intent_id
       AND i.active_attempt_id = a.id
      JOIN public.commerce_orders AS o
        ON o.id = i.order_id
      LEFT JOIN public.subscription_cycles AS c
        ON c.id = i.subscription_cycle_id
       AND c.subscription_id = i.subscription_id
      LEFT JOIN LATERAL (
        SELECT max(r.checked_at) AS last_checked_at
          FROM public.commerce_payment_reconciliation_runs AS r
         WHERE r.payment_attempt_id = a.id
      ) AS latest_run ON true
      WHERE (
          (
            i.target_kind = 'subscription_cycle'
            AND o.mode = 'subscription_cycle'
            AND i.subscription_id IS NOT NULL
            AND i.subscription_cycle_id IS NOT NULL
            AND o.subscription_id = i.subscription_id
            AND o.subscription_cycle_id = i.subscription_cycle_id
            AND c.status = 'payment_pending'
          )
          OR (
            i.target_kind = 'one_time_order'
            AND o.mode = 'one_time'
            AND i.subscription_id IS NULL
            AND i.subscription_cycle_id IS NULL
            AND o.subscription_id IS NULL
            AND o.subscription_cycle_id IS NULL
          )
        )
        AND i.status IN ('requires_action', 'processing')
        AND a.status = 'created'
        AND a.provider IN ('stripe', 'tpay')
        AND a.provider_attempt_id IS NULL
        AND a.provider_session_id IS NULL
        AND i.provider_payment_id IS NULL
        AND GREATEST(a.updated_at, i.updated_at) <= v_cutoff
        AND NOT EXISTS (
          SELECT 1
            FROM public.commerce_payment_reconciliation_runs AS r
           WHERE r.payment_attempt_id = a.id
             AND r.correction_status = 'corrected'
             AND r.provider_status IN ('succeeded', 'failed')
        )
      ORDER BY latest_run.last_checked_at ASC NULLS FIRST,
               GREATEST(a.updated_at, i.updated_at) ASC,
               a.id ASC
      LIMIT p_limit
      FOR UPDATE OF a SKIP LOCKED
    ),
    claimed AS (
      INSERT INTO public.commerce_payment_reconciliation_runs (
        provider,
        provider_payment_id,
        payment_intent_id,
        payment_attempt_id,
        local_status,
        provider_status,
        correction_status,
        idempotency_key,
        checked_at,
        payload
      )
      SELECT
        candidates.provider,
        NULL::text,
        candidates.payment_intent_id,
        candidates.payment_attempt_id,
        candidates.attempt_status,
        'prepared_attempt_claiming',
        'observed',
        v_claim_key || ':prepared:' || candidates.payment_attempt_id::text,
        p_now,
        jsonb_build_object(
          'source', 'payment-provider-reconciliation.prepared-claim.v0',
          'intentStatus', candidates.intent_status,
          'orderId', candidates.order_id,
          'subscriptionId', candidates.subscription_id,
          'subscriptionCycleId', candidates.subscription_cycle_id,
          'staleAfterSeconds', p_stale_after_seconds,
          'providerFlow', candidates.request_payload ->> 'providerFlow',
          'hasProviderIdempotencyKey', candidates.request_payload ? 'providerIdempotencyKey',
          'hasProviderRequestFingerprint', candidates.request_payload ? 'providerRequestFingerprint',
          'providerCallPlanned', true,
          'providerAcknowledged', false
        )
      FROM candidates
      ON CONFLICT (idempotency_key) DO NOTHING
      RETURNING public.commerce_payment_reconciliation_runs.payment_attempt_id
    )
    SELECT
      candidates.payment_attempt_id,
      candidates.payment_intent_id,
      candidates.payment_id,
      candidates.order_id,
      candidates.subscription_id,
      candidates.subscription_cycle_id,
      candidates.provider,
      candidates.provider_payment_id,
      candidates.provider_attempt_id,
      candidates.provider_session_id,
      candidates.attempt_status,
      candidates.intent_status,
      candidates.amount_cents,
      candidates.currency,
      candidates.order_mode,
      candidates.cycle_retry_attempt,
      candidates.cycle_next_retry_at,
      candidates.local_updated_at
    FROM candidates
    JOIN claimed
      ON claimed.payment_attempt_id = candidates.payment_attempt_id
    ORDER BY candidates.local_updated_at ASC, candidates.payment_attempt_id ASC;
END;
$$;


--
-- Name: FUNCTION commerce_payment_reconciliation_claim_prepared_attempts(p_now timestamp with time zone, p_stale_after_seconds integer, p_limit integer, p_claim_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_reconciliation_claim_prepared_attempts(p_now timestamp with time zone, p_stale_after_seconds integer, p_limit integer, p_claim_key text) IS 'Service-role-only. Claims stale prepared one-time or subscription-cycle provider attempts without provider acknowledgement. Records operator evidence only; does not read providers, apply payment results, open dunning, or retry charges.';


--
-- Name: commerce_payment_reconciliation_claim_stale_attempts(timestamp with time zone, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_reconciliation_claim_stale_attempts(p_now timestamp with time zone DEFAULT now(), p_stale_after_seconds integer DEFAULT 900, p_limit integer DEFAULT 50, p_claim_key text DEFAULT NULL::text) RETURNS TABLE(payment_attempt_id uuid, payment_intent_id uuid, payment_id uuid, order_id uuid, subscription_id uuid, subscription_cycle_id uuid, provider text, provider_payment_id text, provider_attempt_id text, provider_session_id text, attempt_status text, intent_status text, amount_cents integer, currency text, order_mode text, cycle_retry_attempt integer, cycle_next_retry_at timestamp with time zone, local_updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_claim_key text;
  v_cutoff timestamptz;
BEGIN
  IF p_now IS NULL
    OR p_stale_after_seconds IS NULL
    OR p_stale_after_seconds < 60
    OR p_stale_after_seconds > 86400
    OR p_limit IS NULL
    OR p_limit < 1
    OR p_limit > 500
  THEN
    RAISE EXCEPTION 'payment_reconciliation_claim_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_claim_key := COALESCE(
    NULLIF(btrim(p_claim_key), ''),
    'payment-provider-reconciliation:' || floor(extract(epoch FROM p_now) / 1800)::bigint::text
  );
  IF length(v_claim_key) < 8 THEN
    RAISE EXCEPTION 'payment_reconciliation_claim_invalid_key' USING ERRCODE = '22023';
  END IF;

  v_cutoff := p_now - make_interval(secs => p_stale_after_seconds);

  RETURN QUERY
    WITH candidates AS (
      SELECT
        a.id AS payment_attempt_id,
        i.id AS payment_intent_id,
        i.payment_id,
        i.order_id,
        i.subscription_id,
        i.subscription_cycle_id,
        a.provider,
        CASE
          WHEN a.provider = 'tpay' THEN COALESCE(a.provider_session_id, a.provider_attempt_id, i.provider_payment_id)
          ELSE COALESCE(a.provider_attempt_id, i.provider_payment_id, a.provider_session_id)
        END AS provider_payment_id,
        a.provider_attempt_id,
        a.provider_session_id,
        a.status AS attempt_status,
        i.status AS intent_status,
        a.amount_cents,
        a.currency,
        o.mode AS order_mode,
        COALESCE(c.retry_attempt, 0) AS cycle_retry_attempt,
        c.next_retry_at AS cycle_next_retry_at,
        GREATEST(a.updated_at, i.updated_at) AS local_updated_at
      FROM public.commerce_payment_attempts AS a
      JOIN public.commerce_payment_intents AS i
        ON i.id = a.payment_intent_id
       AND i.active_attempt_id = a.id
      JOIN public.commerce_orders AS o
        ON o.id = i.order_id
      LEFT JOIN public.subscription_cycles AS c
        ON c.id = i.subscription_cycle_id
       AND c.subscription_id = i.subscription_id
      LEFT JOIN LATERAL (
        SELECT max(r.checked_at) AS last_checked_at
          FROM public.commerce_payment_reconciliation_runs AS r
         WHERE r.payment_attempt_id = a.id
      ) AS latest_run ON true
      WHERE (
          (
            i.target_kind = 'subscription_cycle'
            AND o.mode = 'subscription_cycle'
            AND i.subscription_id IS NOT NULL
            AND i.subscription_cycle_id IS NOT NULL
            AND o.subscription_id = i.subscription_id
            AND o.subscription_cycle_id = i.subscription_cycle_id
            AND c.id IS NOT NULL
          )
          OR (
            i.target_kind = 'one_time_order'
            AND o.mode = 'one_time'
            AND i.subscription_id IS NULL
            AND i.subscription_cycle_id IS NULL
            AND o.subscription_id IS NULL
            AND o.subscription_cycle_id IS NULL
          )
        )
        AND i.status IN ('requires_action', 'processing')
        AND a.status IN ('sent_to_provider', 'requires_action', 'processing')
        AND a.provider IN ('stripe', 'tpay')
        AND GREATEST(a.updated_at, i.updated_at) <= v_cutoff
        AND (
          a.provider_attempt_id IS NOT NULL
          OR a.provider_session_id IS NOT NULL
          OR i.provider_payment_id IS NOT NULL
        )
        AND NOT EXISTS (
          SELECT 1
            FROM public.commerce_payment_reconciliation_runs AS r
           WHERE r.payment_attempt_id = a.id
             AND r.correction_status = 'corrected'
             AND r.provider_status IN ('succeeded', 'failed')
        )
      ORDER BY latest_run.last_checked_at ASC NULLS FIRST,
               GREATEST(a.updated_at, i.updated_at) ASC,
               a.id ASC
      LIMIT p_limit
      FOR UPDATE OF a SKIP LOCKED
    ),
    claimed AS (
      INSERT INTO public.commerce_payment_reconciliation_runs (
        provider,
        provider_payment_id,
        payment_intent_id,
        payment_attempt_id,
        local_status,
        provider_status,
        correction_status,
        idempotency_key,
        checked_at,
        payload
      )
      SELECT
        candidates.provider,
        candidates.provider_payment_id,
        candidates.payment_intent_id,
        candidates.payment_attempt_id,
        candidates.attempt_status,
        'claiming',
        'observed',
        v_claim_key || ':' || candidates.payment_attempt_id::text,
        p_now,
        jsonb_build_object(
          'source', 'payment-provider-reconciliation.claim.v0',
          'intentStatus', candidates.intent_status,
          'orderId', candidates.order_id,
          'subscriptionId', candidates.subscription_id,
          'subscriptionCycleId', candidates.subscription_cycle_id,
          'staleAfterSeconds', p_stale_after_seconds
        )
      FROM candidates
      ON CONFLICT (idempotency_key) DO NOTHING
      RETURNING public.commerce_payment_reconciliation_runs.payment_attempt_id
    )
    SELECT
      candidates.payment_attempt_id,
      candidates.payment_intent_id,
      candidates.payment_id,
      candidates.order_id,
      candidates.subscription_id,
      candidates.subscription_cycle_id,
      candidates.provider,
      candidates.provider_payment_id,
      candidates.provider_attempt_id,
      candidates.provider_session_id,
      candidates.attempt_status,
      candidates.intent_status,
      candidates.amount_cents,
      candidates.currency,
      candidates.order_mode,
      candidates.cycle_retry_attempt,
      candidates.cycle_next_retry_at,
      candidates.local_updated_at
    FROM candidates
    JOIN claimed
      ON claimed.payment_attempt_id = candidates.payment_attempt_id
    ORDER BY candidates.local_updated_at ASC, candidates.payment_attempt_id ASC;
END;
$$;


--
-- Name: FUNCTION commerce_payment_reconciliation_claim_stale_attempts(p_now timestamp with time zone, p_stale_after_seconds integer, p_limit integer, p_claim_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_reconciliation_claim_stale_attempts(p_now timestamp with time zone, p_stale_after_seconds integer, p_limit integer, p_claim_key text) IS 'Service-role-only. Claims stale active Stripe/Tpay one-time or subscription-cycle payment attempts for provider reconciliation. Records claim evidence but does not apply terminal payment results or retry charges.';


--
-- Name: commerce_payment_reopen_interactive_sealed_v1(text, uuid, uuid, uuid, uuid, uuid, text, text, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_payment_reopen_interactive_sealed_v1(p_idempotency_key text, p_payment_attempt_id uuid, p_expected_payment_intent_id uuid, p_expected_order_id uuid, p_expected_subscription_id uuid, p_expected_subscription_cycle_id uuid, p_reopen_mode text, p_dispatch_state text, p_phase text, p_reason_code text, p_operator_ref text, p_absence_checked_at timestamp with time zone, p_absence_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_scope constant text := 'commerce.payment_attempt.interactive_prepared_reopen';
  v_min_stranded_age constant interval := interval '30 minutes';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_attempt public.commerce_payment_attempts%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_cycle public.subscription_cycles%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_payment public.commerce_payments%ROWTYPE;
  v_evidence jsonb := COALESCE(p_absence_evidence, '{}'::jsonb);
  v_occurred_at timestamptz;
  v_latest_local_write timestamptz;
  v_checkout_kind text;
  v_reconciliation_status text;
  v_audit_payload jsonb;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_payment_attempt_id IS NULL
    OR p_expected_payment_intent_id IS NULL
    OR p_expected_order_id IS NULL
    OR p_reopen_mode IS NULL
    OR p_reopen_mode NOT IN ('trusted_pre_dispatch', 'trusted_provider_refusal', 'manual_provider_absence')
    OR p_dispatch_state IS NULL OR btrim(p_dispatch_state) = ''
    OR p_phase IS NULL OR btrim(p_phase) = ''
    OR p_reason_code IS NULL OR btrim(p_reason_code) = ''
    OR jsonb_typeof(v_evidence) <> 'object'
    OR (p_expected_subscription_id IS NULL) IS DISTINCT FROM (p_expected_subscription_cycle_id IS NULL)
  THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_invalid_input' USING ERRCODE = '22023';
  END IF;

  IF lower(v_evidence::text) ~ '(paymentmethodref|payment_method_ref|providermethodref|provider_method_ref|providercustomerref|provider_customer_ref|clientsecret|client_secret|recoverytoken|recovery_token|token_hash|blikcode|blik_code|blik|payid|pay_id|providerpaymentid|provider_payment_id|providerattemptid|provider_attempt_id|providersessionid|provider_session_id)' THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_sensitive_evidence' USING ERRCODE = '22023';
  END IF;

  IF p_reopen_mode = 'trusted_pre_dispatch' THEN
    IF p_dispatch_state <> 'not_dispatched'
      OR NOT (
        (
          p_phase = 'oauth'
          AND p_reason_code IN ('tpay_oauth_failed', 'tpay_oauth_timeout', 'tpay_oauth_invalid_response')
        )
        OR (
          p_phase = 'transaction_dispatch'
          AND p_reason_code IN ('tpay_request_encode_failed', 'tpay_request_deadline_exhausted')
        )
      )
      OR p_operator_ref IS NOT NULL
      OR p_absence_checked_at IS NOT NULL
      OR v_evidence <> '{}'::jsonb
    THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_invalid_trusted_pre_dispatch_evidence'
        USING ERRCODE = '22023';
    END IF;
    v_occurred_at := now();
    v_reconciliation_status := 'provider_dispatch_not_started';
  ELSIF p_reopen_mode = 'trusted_provider_refusal' THEN
    -- The provider WAS reached and answered by refusing the request document,
    -- so it created no transaction. One tuple only, and it is not the
    -- pre-dispatch tuple: that one asserts the call never happened, which is a
    -- different fact proved by different evidence. Keeping them apart is what
    -- stops either list from being widened by a caller that only has the other.
    IF p_dispatch_state <> 'refused'
      OR p_phase <> 'response_decode'
      OR p_reason_code <> 'tpay_request_refused'
      OR p_operator_ref IS NOT NULL
      OR p_absence_checked_at IS NOT NULL
      OR v_evidence <> '{}'::jsonb
    THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_invalid_provider_refusal_evidence'
        USING ERRCODE = '22023';
    END IF;
    v_occurred_at := now();
    v_reconciliation_status := 'provider_transaction_refused';
  ELSE
    IF p_dispatch_state <> 'provider_absence_confirmed'
      OR p_phase <> 'operator_reconciliation'
      OR p_reason_code NOT IN ('operator_verified_absence', 'operator_documented_absence')
      OR p_operator_ref IS NULL
      OR btrim(p_operator_ref) !~ '^[a-z0-9][a-z0-9._:-]{2,159}$'
      OR p_absence_checked_at IS NULL
      OR p_absence_checked_at > now() + interval '5 minutes'
      OR NOT (v_evidence @> '{"providerAbsenceConfirmed": true, "watchdogEvidence": true}'::jsonb)
      OR (v_evidence->>'evidenceCode') IS DISTINCT FROM p_reason_code
      OR EXISTS (
        SELECT 1
          FROM jsonb_object_keys(v_evidence) AS evidence_key(key)
         WHERE evidence_key.key NOT IN ('providerAbsenceConfirmed', 'watchdogEvidence', 'evidenceCode')
      )
    THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_invalid_manual_absence_evidence'
        USING ERRCODE = '22023';
    END IF;
    v_occurred_at := p_absence_checked_at;
    v_reconciliation_status := 'prepared_attempt_provider_absent';
  END IF;

  v_request_fingerprint := md5(
    p_payment_attempt_id::text || '|' ||
    p_expected_payment_intent_id::text || '|' ||
    p_expected_order_id::text || '|' ||
    COALESCE(p_expected_subscription_id::text, '') || '|' ||
    COALESCE(p_expected_subscription_cycle_id::text, '') || '|' ||
    p_reopen_mode || '|' ||
    p_dispatch_state || '|' ||
    p_phase || '|' ||
    p_reason_code || '|' ||
    COALESCE(btrim(p_operator_ref), '') || '|' ||
    COALESCE(p_absence_checked_at::text, '') || '|' ||
    v_evidence::text
  );

  -- A new exact replay has no receipt row yet. Serialize that first creation
  -- by scope+key before reading it, so the waiter sees the completed receipt
  -- after the aggregate-root lock is released instead of re-evaluating failed
  -- state and turning a safe duplicate into a conflict.
  PERFORM pg_advisory_xact_lock(hashtextextended(v_scope || ':' || p_idempotency_key, 0));

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(
        v_existing.response_payload,
        '{interactivePreparedAttemptReopen,replayed}',
        'true'::jsonb,
        false
      );
    END IF;
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  -- Mirror the live finalizer: subscription -> intent -> attempt for initial
  -- subscriptions and intent -> attempt for one-time checkout. The receipt
  -- above is intentionally checked first because exact replays write nothing.
  IF p_expected_subscription_id IS NOT NULL THEN
    SELECT *
      INTO v_subscription
      FROM public.subscriptions
     WHERE id = p_expected_subscription_id
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_subscription_not_found'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_expected_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_intent_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_intent.active_attempt_id IS DISTINCT FROM p_payment_attempt_id THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_active_attempt_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_intent.order_id IS DISTINCT FROM p_expected_order_id
    OR v_intent.subscription_id IS DISTINCT FROM p_expected_subscription_id
    OR v_intent.subscription_cycle_id IS DISTINCT FROM p_expected_subscription_cycle_id
  THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_expected_ids_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_intent.status NOT IN ('requires_action', 'processing') THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_intent_not_active' USING ERRCODE = '22023';
  END IF;
  IF v_intent.provider_payment_id IS NOT NULL THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_intent_provider_ref_exists' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_attempt
    FROM public.commerce_payment_attempts
   WHERE id = p_payment_attempt_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_attempt_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.payment_intent_id IS DISTINCT FROM v_intent.id THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_intent_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_intent.active_attempt_id IS DISTINCT FROM v_attempt.id THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_active_attempt_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.status <> 'created' THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_attempt_not_prepared' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.provider <> 'tpay' THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_provider_not_supported' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.provider_attempt_id IS NOT NULL OR v_attempt.provider_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_provider_ref_exists' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.response_payload @> '{"providerCall": true}'::jsonb THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_provider_call_recorded' USING ERRCODE = '22023';
  END IF;
  IF v_attempt.request_payload->>'source' IS DISTINCT FROM 'commerce.runtime.provider-attempt.prepare.v0'
    OR NOT (v_attempt.request_payload ? 'providerIdempotencyKey')
    OR NOT (v_attempt.request_payload ? 'providerRequestFingerprint')
    OR NOT (v_attempt.request_payload ? 'providerFlow')
  THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_not_interactive_prepare' USING ERRCODE = '22023';
  END IF;

  IF p_expected_subscription_cycle_id IS NOT NULL THEN
    SELECT *
      INTO v_cycle
      FROM public.subscription_cycles
     WHERE id = p_expected_subscription_cycle_id
     FOR UPDATE;
    IF NOT FOUND
      OR v_cycle.subscription_id IS DISTINCT FROM p_expected_subscription_id
      OR v_cycle.status <> 'payment_pending'
    THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_cycle_not_payment_pending' USING ERRCODE = '22023';
    END IF;
    IF v_subscription.status <> 'pending_activation' THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_subscription_not_pending_activation'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT *
    INTO v_order
    FROM public.commerce_orders
   WHERE id = p_expected_order_id
   FOR UPDATE;
  IF NOT FOUND OR v_order.status <> 'pending_payment' THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_order_not_pending_payment' USING ERRCODE = '22023';
  END IF;

  IF p_expected_subscription_id IS NULL THEN
    v_checkout_kind := 'one_time';
    IF v_intent.target_kind <> 'one_time_order'
      OR v_order.mode <> 'one_time'
      OR v_order.subscription_id IS NOT NULL
      OR v_order.subscription_cycle_id IS NOT NULL
    THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_one_time_context_mismatch' USING ERRCODE = '22023';
    END IF;
  ELSE
    v_checkout_kind := 'subscription_initial';
    IF v_intent.target_kind <> 'subscription_cycle'
      OR v_order.mode <> 'subscription_cycle'
      OR v_order.subscription_id IS DISTINCT FROM p_expected_subscription_id
      OR v_order.subscription_cycle_id IS DISTINCT FROM p_expected_subscription_cycle_id
      OR v_cycle.order_id IS DISTINCT FROM v_order.id
    THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_subscription_context_mismatch' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_intent.metadata->>'checkoutKind' IS DISTINCT FROM v_checkout_kind
    OR v_order.metadata#>>'{runtimeFinalize,checkoutKind}' IS DISTINCT FROM v_checkout_kind
    OR v_order.metadata#>>'{runtimeFinalize,source}' IS DISTINCT FROM 'commerce.runtime.hidden.v0'
  THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_checkout_source_mismatch' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_payment
    FROM public.commerce_payments
   WHERE id = v_intent.payment_id
   FOR UPDATE;
  IF NOT FOUND
    OR v_payment.order_id IS DISTINCT FROM v_order.id
    OR v_payment.status <> 'pending'
    OR v_payment.provider_payment_id IS NOT NULL
  THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_payment_not_pending' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.inbound_provider_events AS event
     WHERE event.payment_attempt_id = v_attempt.id
        OR event.payment_intent_id = v_intent.id
  ) THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_provider_event_exists' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.commerce_payment_reconciliation_runs AS reconciliation
     WHERE reconciliation.payment_attempt_id = v_attempt.id
       AND reconciliation.correction_status = 'corrected'
       AND reconciliation.provider_status IN (
         'succeeded', 'failed', 'cancelled', 'canceled', 'refunded',
         'partially_refunded', 'disputed'
       )
  ) THEN
    RAISE EXCEPTION 'interactive_prepared_attempt_reopen_terminal_reconciliation_exists'
      USING ERRCODE = '22023';
  END IF;

  IF p_reopen_mode = 'manual_provider_absence' THEN
    IF NOT EXISTS (
      SELECT 1
        FROM public.commerce_payment_reconciliation_runs AS reconciliation
       WHERE reconciliation.payment_attempt_id = v_attempt.id
         AND reconciliation.provider_status IN ('prepared_attempt_claiming', 'prepared_without_provider_ack')
         AND reconciliation.correction_status IN ('observed', 'failed')
    ) THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_watchdog_evidence_missing'
        USING ERRCODE = '22023';
    END IF;

    v_latest_local_write := GREATEST(
      v_attempt.created_at,
      v_attempt.updated_at,
      v_intent.created_at,
      v_intent.updated_at
    );
    IF p_absence_checked_at < v_latest_local_write + v_min_stranded_age THEN
      RAISE EXCEPTION 'interactive_prepared_attempt_reopen_too_fresh' USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object(
      'boundary', 'commerce_payment_control_reopen_interactive_prepared_attempt',
      'reopenMode', p_reopen_mode,
      'phase', p_phase,
      'reasonCode', p_reason_code
    )
  );

  v_audit_payload := jsonb_build_object(
    'source', 'payment-control.interactive-prepared-attempt-reopen.v1',
    'reopenMode', p_reopen_mode,
    'dispatchState', p_dispatch_state,
    'phase', p_phase,
    'reasonCode', p_reason_code,
    'operatorRef', CASE WHEN p_reopen_mode = 'manual_provider_absence' THEN btrim(p_operator_ref) ELSE NULL END,
    'providerAbsenceConfirmed', p_reopen_mode = 'manual_provider_absence',
    'watchdogEvidence', p_reopen_mode = 'manual_provider_absence'
  );

  UPDATE public.commerce_payment_attempts
     SET status = 'failed',
         failure_reason = 'interactive_prepared_attempt_reopened',
         response_payload = response_payload || jsonb_build_object(
           -- Truthful per mode: a refusal DID call the provider. Only
           -- `providerAcknowledged` is uniformly false, because no mode here
           -- may run while the provider holds a transaction for this attempt.
           'providerCall', p_reopen_mode = 'trusted_provider_refusal',
           'providerAcknowledged', false,
           'interactiveReopenMode', p_reopen_mode
         ),
         metadata = metadata || jsonb_build_object(
           'interactivePreparedAttemptReopened', v_audit_payload
         ),
         updated_at = now()
   WHERE id = v_attempt.id;

  UPDATE public.commerce_payment_intents
     SET status = 'failed',
         failure_reason = 'interactive_prepared_attempt_reopened',
         metadata = metadata || jsonb_build_object(
           'interactivePreparedAttemptReopened', v_audit_payload
         ),
         updated_at = now()
   WHERE id = v_intent.id;

  UPDATE public.commerce_payments
     SET status = 'failed',
         metadata = metadata || jsonb_build_object(
           'interactivePreparedAttemptReopened', v_audit_payload
         ),
         updated_at = now()
   WHERE id = v_payment.id;

  PERFORM public.commerce_payment_control_record_reconciliation(
    p_idempotency_key || ':reconciliation',
    v_attempt.provider,
    NULL,
    v_intent.id,
    v_attempt.id,
    'created',
    v_reconciliation_status,
    'corrected',
    v_occurred_at,
    v_audit_payload
  );

  INSERT INTO public.commerce_payment_state_transitions (
    payment_intent_id,
    payment_attempt_id,
    transition_kind,
    from_status,
    to_status,
    reason,
    idempotency_key,
    occurred_at,
    payload
  )
  VALUES
    (
      v_intent.id,
      v_attempt.id,
      'attempt',
      'created',
      'failed',
      'interactive_prepared_attempt_reopened',
      p_idempotency_key || ':attempt_failed',
      v_occurred_at,
      v_audit_payload
    ),
    (
      v_intent.id,
      v_attempt.id,
      'intent',
      v_intent.status,
      'failed',
      'interactive_prepared_attempt_reopened',
      p_idempotency_key || ':intent_failed',
      v_occurred_at,
      v_audit_payload
    )
  ON CONFLICT (idempotency_key) DO NOTHING;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'interactivePreparedAttemptReopen', jsonb_build_object(
      'paymentAttemptId', v_attempt.id,
      'paymentIntentId', v_intent.id,
      'paymentAttemptStatus', 'failed',
      'paymentIntentStatus', 'failed',
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object(
           'paymentIntentId', v_intent.id,
           'paymentAttemptId', v_attempt.id,
           'reopenMode', p_reopen_mode
         )
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$_$;


--
-- Name: FUNCTION commerce_payment_reopen_interactive_sealed_v1(p_idempotency_key text, p_payment_attempt_id uuid, p_expected_payment_intent_id uuid, p_expected_order_id uuid, p_expected_subscription_id uuid, p_expected_subscription_cycle_id uuid, p_reopen_mode text, p_dispatch_state text, p_phase text, p_reason_code text, p_operator_ref text, p_absence_checked_at timestamp with time zone, p_absence_evidence jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_payment_reopen_interactive_sealed_v1(p_idempotency_key text, p_payment_attempt_id uuid, p_expected_payment_intent_id uuid, p_expected_order_id uuid, p_expected_subscription_id uuid, p_expected_subscription_cycle_id uuid, p_reopen_mode text, p_dispatch_state text, p_phase text, p_reason_code text, p_operator_ref text, p_absence_checked_at timestamp with time zone, p_absence_evidence jsonb) IS 'Service-role-only interactive Tpay prepared-attempt terminal boundary. It accepts three proofs that the provider holds no transaction - trusted no-dispatch facts, a trusted provider refusal of the request document, or operator/provider absence proof - fails old attempt/intent/payment atomically, preserves pending order/provisional subscription/reservations, and never opens dunning or schedules renewal retry.';


--
-- Name: commerce_pin_paid_order_reservations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_pin_paid_order_reservations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_item record;
  v_provider_kind text;
  v_active_quantity integer;
  v_missing_quantity integer;
  v_has_reservation_history boolean;
BEGIN
  IF NEW.status <> 'paid' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  v_provider_kind := lower(coalesce(
    NEW.metadata #>> '{runtimeFinalize,selectedDelivery,providerKind}',
    NEW.metadata #>> '{selectedDelivery,providerKind}'
  ));

  FOR v_item IN
    SELECT id, sku_id, quantity
      FROM public.commerce_order_items
     WHERE order_id = NEW.id
       AND sku_id IS NOT NULL
     ORDER BY id
     FOR UPDATE
  LOOP
    SELECT coalesce(sum(quantity), 0)
      INTO v_active_quantity
      FROM public.inventory_reservations
     WHERE order_id = NEW.id
       AND (order_item_id = v_item.id OR order_item_id IS NULL)
       AND sku_id = v_item.sku_id
       AND status = 'reserved'
       AND (expires_at IS NULL OR expires_at > now());

    SELECT EXISTS (
      SELECT 1
        FROM public.inventory_reservations
       WHERE order_id = NEW.id
         AND (order_item_id = v_item.id OR order_item_id IS NULL)
         AND sku_id = v_item.sku_id
    )
      INTO v_has_reservation_history;

    v_missing_quantity := v_item.quantity - v_active_quantity;
    IF v_missing_quantity > 0 AND v_has_reservation_history THEN
      PERFORM public.inventory_reserve_order(
        'paid-reacquire:' || NEW.id::text || ':' || v_item.id::text,
        NEW.id,
        v_item.id,
        NEW.subscription_cycle_id,
        v_item.sku_id,
        v_missing_quantity,
        'checkout_payment_window',
        'succeeded',
        now() + interval '5 minutes',
        jsonb_build_object(
          'source', 'commerce_pin_paid_order_reservations',
          'reacquiredAfterLeaseExpiry', true
        ),
        nullif(v_provider_kind, '')
      );
    END IF;
  END LOOP;

  UPDATE public.inventory_reservations
     SET expires_at = NULL,
         updated_at = now(),
         metadata = metadata || jsonb_build_object(
           'holdKind', 'paid_order_hold',
           'pinnedAt', now(),
           'source', 'commerce_pin_paid_order_reservations'
         )
   WHERE order_id = NEW.id
     AND status = 'reserved'
     AND (expires_at IS NULL OR expires_at > now());

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_pin_paid_order_reservations(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_pin_paid_order_reservations() IS 'Pins active paid-order inventory reservations and reacquires stock before pinning when a checkout lease expired before payment success.';


--
-- Name: commerce_prepare_expired_checkout_recovery(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_prepare_expired_checkout_recovery(p_idempotency_key text, p_source_order_id uuid, p_replacement_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_source public.commerce_orders%ROWTYPE;
  v_replacement public.commerce_orders%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_cycle public.subscription_cycles%ROWTYPE;
  v_root_id uuid;
  v_existing_replacement_id uuid;
  v_is_subscription_expiry boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
     OR p_source_order_id IS NULL OR p_replacement_order_id IS NULL
     OR p_source_order_id = p_replacement_order_id THEN
    RAISE EXCEPTION 'commerce_expired_recovery_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_source
    FROM public.commerce_orders
   WHERE id = p_source_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_expired_recovery_source_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_replacement
    FROM public.commerce_orders
   WHERE id = p_replacement_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_expired_recovery_replacement_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_replacement.recreated_from_order_id = v_source.id THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'replacementOrderId', v_replacement.id,
      'replayed', true
    );
  END IF;

  SELECT id INTO v_existing_replacement_id
    FROM public.commerce_orders
   WHERE recreated_from_order_id = v_source.id
     AND id <> v_replacement.id
   LIMIT 1;
  IF v_existing_replacement_id IS NOT NULL THEN
    RAISE EXCEPTION 'commerce_expired_recovery_source_already_recreated' USING ERRCODE = '23505';
  END IF;

  IF v_replacement.status <> 'draft'
     OR v_replacement.client_id IS DISTINCT FROM v_source.client_id THEN
    RAISE EXCEPTION 'commerce_expired_recovery_replacement_invalid' USING ERRCODE = '22023';
  END IF;

  IF v_source.created_at < now() - interval '30 days' THEN
    RAISE EXCEPTION 'commerce_expired_recovery_window_elapsed' USING ERRCODE = '22023';
  END IF;

  v_is_subscription_expiry :=
    v_source.status = 'cancelled'
    AND v_source.mode = 'subscription_cycle'
    AND v_source.subscription_id IS NOT NULL
    AND v_source.subscription_cycle_id IS NOT NULL
    AND v_source.metadata->>'source' = 'subscription.sweep.v0'
    AND EXISTS (
      SELECT 1 FROM public.subscription_events event
       WHERE event.subscription_id = v_source.subscription_id
         AND event.event_type = 'subscription.activation_abandoned'
         AND event.payload->>'orderId' = v_source.id::text
    );

  IF NOT (
    (v_source.status = 'expired'
      AND v_source.metadata->>'paymentStatus' = 'expired'
      AND v_source.metadata->>'source' IN ('commerce.reservation_sweep.v0', 'payment.control.v0'))
    OR v_is_subscription_expiry
  ) THEN
    RAISE EXCEPTION 'commerce_expired_recovery_source_not_eligible' USING ERRCODE = '22023';
  END IF;

  IF v_source.metadata ? 'manualOrderCancellation'
     OR EXISTS (
       SELECT 1 FROM public.commerce_order_operations operation
        WHERE operation.order_id = v_source.id
          AND operation.operation_type = 'order_cancelled_manual'
     ) THEN
    RAISE EXCEPTION 'commerce_expired_recovery_manually_cancelled' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.commerce_payment_intents
   WHERE order_id = v_source.id FOR UPDATE;
  IF EXISTS (
    SELECT 1 FROM public.commerce_payment_intents
     WHERE order_id = v_source.id
       AND status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed')
  ) OR EXISTS (
    SELECT 1 FROM public.commerce_payments
     WHERE order_id = v_source.id
       AND status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed')
  ) THEN
    RAISE EXCEPTION 'commerce_expired_recovery_money_moved' USING ERRCODE = '23505';
  END IF;

  IF (v_source.currency, v_source.subtotal_cents, v_source.discount_cents,
      v_source.shipping_cents, v_source.shipping_discount_cents,
      v_source.tax_cents, v_source.total_cents)
     IS DISTINCT FROM
     (v_replacement.currency, v_replacement.subtotal_cents, v_replacement.discount_cents,
      v_replacement.shipping_cents, v_replacement.shipping_discount_cents,
      v_replacement.tax_cents, v_replacement.total_cents)
     OR EXISTS (
       (SELECT product_snapshot->>'sku', quantity, unit_price_cents, total_cents,
               discount_allocated_cents, effective_total_cents, effective_net_cents, vat_rate_bps
          FROM public.commerce_order_items WHERE order_id = v_source.id
        EXCEPT
        SELECT product_snapshot->>'sku', quantity, unit_price_cents, total_cents,
               discount_allocated_cents, effective_total_cents, effective_net_cents, vat_rate_bps
          FROM public.commerce_order_items WHERE order_id = v_replacement.id)
       UNION ALL
       (SELECT product_snapshot->>'sku', quantity, unit_price_cents, total_cents,
               discount_allocated_cents, effective_total_cents, effective_net_cents, vat_rate_bps
          FROM public.commerce_order_items WHERE order_id = v_replacement.id
        EXCEPT
        SELECT product_snapshot->>'sku', quantity, unit_price_cents, total_cents,
               discount_allocated_cents, effective_total_cents, effective_net_cents, vat_rate_bps
          FROM public.commerce_order_items WHERE order_id = v_source.id)
     ) THEN
    RAISE EXCEPTION 'commerce_expired_recovery_order_changed' USING ERRCODE = '23505';
  END IF;

  v_root_id := COALESCE(v_source.recovery_root_order_id, v_source.id);

  IF v_is_subscription_expiry THEN
    SELECT * INTO v_subscription
      FROM public.subscriptions
     WHERE id = v_source.subscription_id
     FOR UPDATE;
    SELECT * INTO v_cycle
      FROM public.subscription_cycles
     WHERE id = v_source.subscription_cycle_id
     FOR UPDATE;

    IF v_subscription.id IS NULL OR v_cycle.id IS NULL
       OR v_subscription.status <> 'cancelled'
       OR v_cycle.status <> 'cancelled' THEN
      RAISE EXCEPTION 'commerce_expired_recovery_subscription_not_reopenable' USING ERRCODE = '22023';
    END IF;

    UPDATE public.subscriptions
       SET status = 'pending_activation', ended_at = NULL,
           cancellation_reason = NULL, cancellation_source = NULL,
           updated_at = now()
     WHERE id = v_subscription.id;

    UPDATE public.subscription_cycles
       SET status = 'payment_pending', order_id = v_replacement.id,
           payment_id = NULL, payment_method_ref = NULL, paid_at = NULL,
           failure_reason = NULL, next_retry_at = NULL, retry_attempt = 0,
           updated_at = now()
     WHERE id = v_cycle.id;

    -- commerce_orders has a partial UNIQUE(subscription_cycle_id). The expired
    -- source keeps its audit lineage in metadata/events, but the live cycle owner
    -- must become the replacement order.
    UPDATE public.commerce_orders
       SET mode = 'one_time',
           subscription_id = NULL,
           subscription_cycle_id = NULL,
           metadata = metadata || jsonb_build_object(
             'recoveredByOrderId', v_replacement.id,
             'recoveredSubscriptionId', v_subscription.id,
             'recoveredSubscriptionCycleId', v_cycle.id
           ),
           updated_at = now()
     WHERE id = v_source.id;

    UPDATE public.commerce_orders
       SET mode = 'subscription_cycle', subscription_id = v_subscription.id,
           subscription_cycle_id = v_cycle.id
     WHERE id = v_replacement.id;

    INSERT INTO public.subscription_events (
      subscription_id, cycle_id, event_type, idempotency_key, payload, occurred_at
    ) VALUES (
      v_subscription.id, v_cycle.id, 'subscription.checkout_recovery_reopened',
      'subscription-checkout-recovery:' || v_source.id::text,
      jsonb_build_object('sourceOrderId', v_source.id, 'replacementOrderId', v_replacement.id),
      now()
    ) ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
  END IF;

  UPDATE public.commerce_orders
     SET recovery_root_order_id = v_root_id,
         recreated_from_order_id = v_source.id,
         metadata = metadata || jsonb_build_object(
           'recreatedFromOrderId', v_source.id,
           'recoveryRootOrderId', v_root_id,
           'recoveryReason', 'expired_checkout_recreate',
           'recoveryIdempotencyKey', p_idempotency_key
         ),
         updated_at = now()
   WHERE id = v_replacement.id;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'replacementOrderId', v_replacement.id,
    'replayed', false
  );
END;
$$;


--
-- Name: commerce_prevent_frozen_order_money_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_prevent_frozen_order_money_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'commerce_orders' THEN
    IF ROW(
      OLD.currency, OLD.subtotal_cents, OLD.discount_cents,
      OLD.shipping_cents, OLD.shipping_discount_cents, OLD.tax_cents, OLD.total_cents
    ) IS DISTINCT FROM ROW(
      NEW.currency, NEW.subtotal_cents, NEW.discount_cents,
      NEW.shipping_cents, NEW.shipping_discount_cents, NEW.tax_cents, NEW.total_cents
    ) THEN
      RAISE EXCEPTION 'commerce_order_money_frozen: %', OLD.id
        USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'commerce_order_items' THEN
    IF ROW(
      OLD.order_id, OLD.quantity, OLD.unit_price_cents, OLD.total_cents,
      OLD.discount_allocated_cents, OLD.effective_total_cents,
      OLD.effective_net_cents, OLD.vat_rate_bps, OLD.allocation_ordinal
    ) IS DISTINCT FROM ROW(
      NEW.order_id, NEW.quantity, NEW.unit_price_cents, NEW.total_cents,
      NEW.discount_allocated_cents, NEW.effective_total_cents,
      NEW.effective_net_cents, NEW.vat_rate_bps, NEW.allocation_ordinal
    ) THEN
      RAISE EXCEPTION 'commerce_order_item_money_frozen: %', OLD.id
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: commerce_promotion_code_claim(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_promotion_code_claim(p_code_id uuid, p_order_id uuid, p_expires_at timestamp with time zone DEFAULT (now() + '24:00:00'::interval)) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT private.commerce_promotion_code_claim_checked(
    p_code_id, p_order_id, NULL, p_expires_at
  )
$$;


--
-- Name: commerce_promotion_code_redeem(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_promotion_code_redeem(p_order_id uuid, p_redeemed_at timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  UPDATE public.promotion_code_claims SET status='redeemed',redeemed_at=p_redeemed_at,
    released_at=NULL,release_reason=NULL,updated_at=now()
  WHERE order_id=p_order_id AND status='reserved';
  GET DIAGNOSTICS v_count=ROW_COUNT; RETURN v_count;
END;
$$;


--
-- Name: FUNCTION commerce_promotion_code_redeem(p_order_id uuid, p_redeemed_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_promotion_code_redeem(p_order_id uuid, p_redeemed_at timestamp with time zone) IS 'PR4 primitive only: call inside the same order/payment transaction after order->code->claim locks; do not invoke as a sequential checkout step.';


--
-- Name: commerce_promotion_code_release(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_promotion_code_release(p_order_id uuid, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_count integer;
BEGIN
  IF p_reason IS NULL OR btrim(p_reason)='' THEN
    RAISE EXCEPTION 'promotion_code_release_reason_required' USING ERRCODE='22023';
  END IF;
  UPDATE public.promotion_code_claims SET status='released',released_at=now(),
    release_reason=left(btrim(p_reason),120),updated_at=now()
  WHERE order_id=p_order_id AND status='reserved';
  GET DIAGNOSTICS v_count=ROW_COUNT; RETURN v_count;
END;
$$;


--
-- Name: FUNCTION commerce_promotion_code_release(p_order_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_promotion_code_release(p_order_id uuid, p_reason text) IS 'PR4 primitive only: call inside the same order/payment cancellation transaction; do not release merely because reserved.expires_at passed (late PSP callbacks can still win).';


--
-- Name: commerce_promotion_codes_quote_candidates(text[], uuid, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_promotion_codes_quote_candidates(p_codes text[], p_client_id uuid, p_scope text, p_reference_product_minor integer, p_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH submitted_input AS (
    SELECT code AS submitted_code, upper(btrim(code)) AS normalized, ordinality
      FROM unnest(coalesce(p_codes, ARRAY[]::text[])) WITH ORDINALITY AS input(code, ordinality)
     WHERE code IS NOT NULL AND btrim(code) <> ''
  ), submitted AS (
    SELECT normalized,
      (array_agg(submitted_code ORDER BY ordinality))[1] AS submitted_code,
      min(ordinality)::integer AS ordinal
      FROM submitted_input
     GROUP BY normalized
  ), resolved AS (
    SELECT submitted.submitted_code, submitted.normalized, submitted.ordinal,
      pc.id AS code_id, pc.code AS canonical_code, pc.scopes, pc.valid_from,
      pc.valid_to, pc.minimum_reference_minor, pc.redemption_limit_global,
      pc.redemption_limit_per_customer, pc.status, pc.revision,
      EXISTS (
        SELECT 1
          FROM public.promotion_code_bindings binding
          JOIN public.promotions promotion ON promotion.id = binding.promotion_id
         WHERE binding.promotion_code_id = pc.id
           AND promotion.promotion_engine_version = 'promotion-engine.v2'
      ) AS has_v2,
      (SELECT count(*)
         FROM public.promotion_code_claims claim
        WHERE claim.promotion_code_id = pc.id
          AND claim.status IN ('reserved', 'redeemed')) AS capacity_used,
      (SELECT count(*)
         FROM public.promotion_code_claims claim
        WHERE claim.promotion_code_id = pc.id
          AND claim.client_id = p_client_id
          AND claim.status IN ('reserved', 'redeemed')) AS customer_used
      FROM submitted
      LEFT JOIN public.promotion_codes pc ON pc.code_normalized = submitted.normalized
  ), classified AS (
    SELECT resolved.*,
      CASE
        WHEN code_id IS NULL THEN 'not_recognized'
        WHEN NOT has_v2 THEN NULL
        WHEN status <> 'active' THEN 'not_recognized'
        WHEN valid_to IS NOT NULL AND valid_to <= p_at THEN 'expired'
        WHEN valid_from > p_at THEN 'not_eligible'
        WHEN NOT (p_scope = ANY(scopes)) THEN 'not_eligible'
        WHEN p_reference_product_minor < minimum_reference_minor THEN 'not_eligible'
        WHEN redemption_limit_per_customer IS NOT NULL
          AND customer_used >= redemption_limit_per_customer THEN 'already_used'
        WHEN redemption_limit_global IS NOT NULL
          AND capacity_used >= redemption_limit_global THEN 'not_eligible'
        ELSE NULL
      END AS rejection_reason
      FROM resolved
  ), candidates AS (
    SELECT classified.ordinal, binding.lane, promotion.id AS promotion_id,
      jsonb_strip_nulls(jsonb_build_object(
        'promotionId', promotion.id,
        'codeId', classified.code_id,
        'code', classified.canonical_code,
        'codeRevision', classified.revision,
        'definitionFingerprint', private.commerce_promotion_definition_fingerprint(
          classified.code_id, promotion.id
        ),
        'minimumReferenceMinor', classified.minimum_reference_minor,
        'validTo', classified.valid_to,
        'name', promotion.name,
        'source', 'code',
        'scopes', classified.scopes,
        'lane', promotion.benefit_lane,
        'kind', promotion.benefit_kind,
        'valueBps', promotion.benefit_value_bps::integer,
        'valueMinor', promotion.benefit_value_minor::integer
      )) AS candidate
      FROM classified
      JOIN public.promotion_code_bindings binding ON binding.promotion_code_id = classified.code_id
      JOIN public.promotions promotion ON promotion.id = binding.promotion_id
     WHERE classified.has_v2
       AND classified.rejection_reason IS NULL
       AND promotion.promotion_engine_version = 'promotion-engine.v2'
  ), rejections AS (
    SELECT jsonb_build_object('code', submitted_code, 'reason', rejection_reason) AS rejection, ordinal
      FROM classified
     WHERE rejection_reason IS NOT NULL
  )
  SELECT jsonb_build_object(
    'candidates', coalesce((
      SELECT jsonb_agg(candidate ORDER BY ordinal, lane, promotion_id) FROM candidates
    ), '[]'::jsonb),
    'codeRejections', coalesce((
      SELECT jsonb_agg(rejection ORDER BY ordinal) FROM rejections
    ), '[]'::jsonb)
  )
$$;


--
-- Name: commerce_promotion_codes_quote_candidates_v2(text[], uuid, text, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_promotion_codes_quote_candidates_v2(p_codes text[], p_client_id uuid, p_scope text, p_reference_product_minor integer, p_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH submitted_input AS (
    SELECT code AS submitted_code, upper(btrim(code)) AS normalized, ordinality
      FROM unnest(coalesce(p_codes, ARRAY[]::text[])) WITH ORDINALITY AS input(code, ordinality)
     WHERE code IS NOT NULL AND btrim(code) <> ''
  ), submitted AS (
    SELECT normalized,
      (array_agg(submitted_code ORDER BY ordinality))[1] AS submitted_code,
      min(ordinality)::integer AS ordinal
      FROM submitted_input
     GROUP BY normalized
  ), resolved AS (
    SELECT submitted.submitted_code, submitted.normalized, submitted.ordinal,
      pc.id AS code_id, pc.code AS canonical_code, pc.scopes, pc.valid_from,
      pc.valid_to, pc.minimum_reference_minor, pc.redemption_limit_global,
      pc.redemption_limit_per_customer, pc.status, pc.revision,
      EXISTS (
        SELECT 1
          FROM public.promotion_code_bindings binding
          JOIN public.promotions promotion ON promotion.id = binding.promotion_id
         WHERE binding.promotion_code_id = pc.id
           AND promotion.promotion_engine_version = 'promotion-engine.v2'
      ) AS has_v2,
      EXISTS (
        SELECT 1
          FROM public.promotion_code_bindings binding
          JOIN public.promotions promotion ON promotion.id = binding.promotion_id
         WHERE binding.promotion_code_id = pc.id
           AND promotion.promotion_engine_version = 'promotion-engine.v1'
      ) AS has_legacy,
      legacy_scope.allowed_scopes AS legacy_allowed_scopes,
      (SELECT count(*)
         FROM public.promotion_code_claims claim
        WHERE claim.promotion_code_id = pc.id
          AND claim.status IN ('reserved', 'redeemed')) AS capacity_used,
      (SELECT count(*)
         FROM public.promotion_code_claims claim
        WHERE claim.promotion_code_id = pc.id
          AND claim.client_id = p_client_id
          AND claim.status IN ('reserved', 'redeemed')) AS customer_used
      FROM submitted
      LEFT JOIN public.promotion_codes pc ON pc.code_normalized = submitted.normalized
      LEFT JOIN LATERAL (
        -- Legacy projection historically derived scopes from first-order
        -- eligibility and intentionally ignored applies_to_payload.cart_mode.
        -- A v1 code has a customer-safe scope detail only when one bound legacy
        -- promotion supplies an unambiguous supported mode. Collisions/multiple
        -- bindings retain legacy's generic behavior rather than guessing.
        SELECT CASE
          WHEN count(*) <> 1 THEN NULL
          WHEN max(promotion.applies_to_payload->>'cart_mode') = 'one_time' THEN ARRAY['one_time']::text[]
          WHEN max(promotion.applies_to_payload->>'cart_mode') = 'subscription' THEN ARRAY['subscription_initial']::text[]
          WHEN max(promotion.applies_to_payload->>'cart_mode') IS NULL THEN ARRAY['one_time', 'subscription_initial']::text[]
          ELSE NULL
        END AS allowed_scopes
          FROM public.promotion_code_bindings binding
          JOIN public.promotions promotion ON promotion.id = binding.promotion_id
         WHERE binding.promotion_code_id = pc.id
           AND promotion.promotion_engine_version = 'promotion-engine.v1'
      ) legacy_scope ON true
  ), classified AS (
    SELECT resolved.*,
      CASE
        WHEN code_id IS NULL THEN 'not_recognized'
        -- A code identity projected from the legacy promotion is evaluated by
        -- the v1 money path. It has no v2 candidate, but its projection is the
        -- source of truth for safe rejection details in this additive read.
        WHEN NOT has_v2 AND NOT has_legacy THEN NULL
        WHEN status <> 'active' THEN 'not_recognized'
        WHEN valid_to IS NOT NULL AND valid_to <= p_at THEN 'expired'
        WHEN valid_from > p_at THEN 'not_eligible'
        WHEN NOT (p_scope = ANY(CASE
          WHEN has_v2 OR legacy_allowed_scopes IS NULL THEN scopes
          ELSE legacy_allowed_scopes
        END)) THEN 'not_eligible'
        WHEN p_reference_product_minor < minimum_reference_minor THEN 'not_eligible'
        WHEN redemption_limit_per_customer IS NOT NULL
          AND customer_used >= redemption_limit_per_customer THEN 'already_used'
        WHEN redemption_limit_global IS NOT NULL
          AND capacity_used >= redemption_limit_global THEN 'not_eligible'
        ELSE NULL
      END AS rejection_reason,
      CASE
        WHEN code_id IS NULL OR (NOT has_v2 AND NOT has_legacy) OR status <> 'active' THEN NULL
        WHEN has_legacy AND NOT has_v2 AND legacy_allowed_scopes IS NULL THEN NULL
        WHEN valid_to IS NOT NULL AND valid_to <= p_at THEN NULL
        WHEN valid_from > p_at THEN 'not_yet_active'
        WHEN NOT (p_scope = ANY(CASE
          WHEN has_v2 THEN scopes
          ELSE legacy_allowed_scopes
        END)) THEN 'scope_not_applicable'
        WHEN p_reference_product_minor < minimum_reference_minor THEN 'minimum_not_met'
        WHEN redemption_limit_global IS NOT NULL
          AND capacity_used >= redemption_limit_global THEN 'global_limit_reached'
        ELSE NULL
      END AS rejection_detail_reason
      FROM resolved
  ), candidates AS (
    SELECT classified.ordinal, binding.lane, promotion.id AS promotion_id,
      jsonb_strip_nulls(jsonb_build_object(
        'promotionId', promotion.id,
        'codeId', classified.code_id,
        'code', classified.canonical_code,
        'codeRevision', classified.revision,
        'definitionFingerprint', private.commerce_promotion_definition_fingerprint(
          classified.code_id, promotion.id
        ),
        'minimumReferenceMinor', classified.minimum_reference_minor,
        'validTo', classified.valid_to,
        'name', promotion.name,
        'source', 'code',
        'scopes', classified.scopes,
        'lane', promotion.benefit_lane,
        'kind', promotion.benefit_kind,
        'valueBps', promotion.benefit_value_bps::integer,
        'valueMinor', promotion.benefit_value_minor::integer
      )) AS candidate
      FROM classified
      JOIN public.promotion_code_bindings binding ON binding.promotion_code_id = classified.code_id
      JOIN public.promotions promotion ON promotion.id = binding.promotion_id
     WHERE classified.has_v2
       AND classified.rejection_reason IS NULL
       AND promotion.promotion_engine_version = 'promotion-engine.v2'
  ), rejections AS (
    SELECT jsonb_build_object('code', submitted_code, 'reason', rejection_reason) AS rejection, ordinal
      FROM classified
     WHERE rejection_reason IS NOT NULL
  ), rejection_details AS (
    SELECT CASE rejection_detail_reason
      WHEN 'scope_not_applicable' THEN jsonb_build_object(
        'code', submitted_code,
        'reason', rejection_detail_reason,
        'allowedScopes', CASE WHEN has_v2 THEN scopes ELSE legacy_allowed_scopes END
      )
      WHEN 'minimum_not_met' THEN jsonb_build_object(
        'code', submitted_code,
        'reason', rejection_detail_reason,
        'minimumReferenceMinor', minimum_reference_minor
      )
      WHEN 'not_yet_active' THEN jsonb_build_object(
        'code', submitted_code,
        'reason', rejection_detail_reason,
        'validFrom', valid_from
      )
      WHEN 'global_limit_reached' THEN jsonb_build_object(
        'code', submitted_code,
        'reason', rejection_detail_reason
      )
    END AS detail, ordinal
      FROM classified
     WHERE rejection_detail_reason IS NOT NULL
  )
  SELECT jsonb_build_object(
    'candidates', coalesce((
      SELECT jsonb_agg(candidate ORDER BY ordinal, lane, promotion_id) FROM candidates
    ), '[]'::jsonb),
    'codeRejections', coalesce((
      SELECT jsonb_agg(rejection ORDER BY ordinal) FROM rejections
    ), '[]'::jsonb),
    'codeRejectionDetails', coalesce((
      SELECT jsonb_agg(detail ORDER BY ordinal) FROM rejection_details
    ), '[]'::jsonb)
  )
$$;


--
-- Name: commerce_promotion_health_snapshot(timestamp with time zone, timestamp with time zone, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_promotion_health_snapshot(p_since timestamp with time zone, p_stale_before timestamp with time zone, p_evidence_limit integer DEFAULT 25, p_include_health boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_now timestamptz := statement_timestamp();
  v_window_from timestamptz;
  v_reserved bigint := 0;
  v_redeemed bigint := 0;
  v_released bigint := 0;
  v_stale bigint := 0;
  v_stale_blocking_capacity bigint := 0;
  v_configured_limit_codes bigint := 0;
  v_at_limit_codes bigint := 0;
  v_over_limit_codes bigint := 0;
  v_event_reserved bigint := 0;
  v_event_redeemed bigint := 0;
  v_event_released bigint := 0;
  v_event_late_paid bigint := 0;
  v_lifecycle_mismatch bigint := 0;
  v_missing_claim_orders bigint := 0;
  v_orphan_claims bigint := 0;
  v_promotion_money_mismatches bigint := 0;
  v_evidence jsonb := '[]'::jsonb;
  v_money_evidence jsonb := '[]'::jsonb;
BEGIN
  IF p_since IS NULL
    OR p_stale_before IS NULL
    OR p_since > v_now
    OR p_since < v_now - interval '25 hours'
    OR p_stale_before > v_now
    OR p_evidence_limit IS NULL
    OR p_evidence_limit NOT BETWEEN 1 AND 100
    OR p_include_health IS NULL
  THEN
    RAISE EXCEPTION 'promotion_health_snapshot_invalid_bounds' USING ERRCODE = '22023';
  END IF;
  -- The app computes now-24h before network/DB latency. Clamp that harmless
  -- skew at the database boundary so the executed scan is still never wider
  -- than 24 hours; reject only callers more than one hour outside the contract.
  v_window_from := greatest(p_since, v_now - interval '24 hours');

  IF p_include_health THEN
  SELECT
    count(*) FILTER (WHERE status = 'reserved'),
    count(*) FILTER (WHERE status = 'redeemed'),
    count(*) FILTER (WHERE status = 'released'),
    count(*) FILTER (WHERE status = 'reserved' AND expires_at <= p_stale_before AND EXISTS (
      SELECT 1
      FROM public.commerce_orders stale_order
      WHERE stale_order.id = promotion_code_claims.order_id
        AND stale_order.status IN ('draft', 'pending_payment')
    ))
  INTO v_reserved, v_redeemed, v_released, v_stale
  FROM public.promotion_code_claims
  WHERE status IN ('reserved', 'redeemed', 'released');

  WITH active_by_code AS (
    SELECT promotion_code_id, count(*)::bigint AS active_claims
      FROM public.promotion_code_claims
     WHERE status IN ('reserved', 'redeemed')
     GROUP BY promotion_code_id
  ), active_by_customer AS (
    SELECT promotion_code_id, client_id, count(*)::bigint AS active_claims
      FROM public.promotion_code_claims
     WHERE status IN ('reserved', 'redeemed')
       AND client_id IS NOT NULL
     GROUP BY promotion_code_id, client_id
  )
  SELECT count(*)
    INTO v_stale_blocking_capacity
    FROM public.promotion_code_claims stale
    JOIN public.commerce_orders orders ON orders.id = stale.order_id
    JOIN public.promotion_codes codes ON codes.id = stale.promotion_code_id
    LEFT JOIN active_by_code code_capacity
      ON code_capacity.promotion_code_id = stale.promotion_code_id
    LEFT JOIN active_by_customer customer_capacity
      ON customer_capacity.promotion_code_id = stale.promotion_code_id
     AND customer_capacity.client_id = stale.client_id
   WHERE stale.status = 'reserved'
     AND stale.expires_at <= p_stale_before
     AND orders.status IN ('draft', 'pending_payment')
     AND (
       (codes.redemption_limit_global IS NOT NULL
         AND coalesce(code_capacity.active_claims, 0) >= codes.redemption_limit_global)
       OR
       (codes.redemption_limit_per_customer IS NOT NULL
         AND stale.client_id IS NOT NULL
         AND coalesce(customer_capacity.active_claims, 0) >= codes.redemption_limit_per_customer)
     );

  WITH active_by_code AS (
    SELECT claims.promotion_code_id, count(*)::bigint AS active_claims
      FROM public.promotion_code_claims claims
     WHERE claims.status IN ('reserved', 'redeemed')
     GROUP BY claims.promotion_code_id
  ), active_by_customer AS (
    SELECT claims.promotion_code_id, claims.client_id, count(*)::bigint AS active_claims
      FROM public.promotion_code_claims claims
     WHERE claims.status IN ('reserved', 'redeemed')
       AND claims.client_id IS NOT NULL
     GROUP BY claims.promotion_code_id, claims.client_id
  ), code_health AS (
    SELECT codes.id,
      codes.redemption_limit_global,
      codes.redemption_limit_per_customer,
      coalesce(active.active_claims, 0) AS active_claims,
      EXISTS (
        SELECT 1 FROM active_by_customer customer
        WHERE customer.promotion_code_id = codes.id
          AND codes.redemption_limit_per_customer IS NOT NULL
          AND customer.active_claims = codes.redemption_limit_per_customer
      ) AS customer_at_limit,
      EXISTS (
        SELECT 1 FROM active_by_customer customer
        WHERE customer.promotion_code_id = codes.id
          AND codes.redemption_limit_per_customer IS NOT NULL
          AND customer.active_claims > codes.redemption_limit_per_customer
      ) AS customer_over_limit
    FROM public.promotion_codes codes
    LEFT JOIN active_by_code active ON active.promotion_code_id = codes.id
    WHERE codes.redemption_limit_global IS NOT NULL
       OR codes.redemption_limit_per_customer IS NOT NULL
  )
  SELECT
    count(*),
    count(*) FILTER (WHERE
      (redemption_limit_global IS NOT NULL AND active_claims = redemption_limit_global)
      OR customer_at_limit
    ),
    count(*) FILTER (WHERE
      (redemption_limit_global IS NOT NULL AND active_claims > redemption_limit_global)
      OR customer_over_limit
    )
  INTO v_configured_limit_codes, v_at_limit_codes, v_over_limit_codes
  FROM code_health;

  SELECT
    count(*) FILTER (WHERE transition_kind = 'reserved'),
    count(*) FILTER (WHERE transition_kind = 'redeemed'),
    count(*) FILTER (WHERE transition_kind = 'released'),
    count(*) FILTER (WHERE transition_kind = 'late_paid')
  INTO v_event_reserved, v_event_redeemed, v_event_released, v_event_late_paid
  FROM public.promotion_code_claim_events
  WHERE occurred_at >= v_window_from
    AND occurred_at <= v_now;

  SELECT
    count(*) FILTER (WHERE orders.id IS NOT NULL AND (
      (orders.status IN ('paid', 'fulfillment_pending', 'fulfilled', 'refunded')
        AND claims.status <> 'redeemed')
      OR (orders.status IN ('cancelled', 'failed', 'expired')
        AND claims.status IN ('reserved', 'redeemed'))
      OR (orders.status IN ('draft', 'pending_payment') AND claims.status = 'redeemed')
    )),
    count(*) FILTER (WHERE orders.id IS NULL OR codes.id IS NULL)
  INTO v_lifecycle_mismatch, v_orphan_claims
  FROM public.promotion_code_claims claims
  LEFT JOIN public.commerce_orders orders ON orders.id = claims.order_id
  LEFT JOIN public.promotion_codes codes ON codes.id = claims.promotion_code_id;
  END IF;

  WITH v2_orders AS (
    SELECT
      orders.id,
      orders.metadata,
      orders.subtotal_cents,
      orders.discount_cents,
      orders.shipping_discount_cents,
      coalesce(array_agg(DISTINCT claims.promotion_code_id::text
        ORDER BY claims.promotion_code_id::text)
        FILTER (WHERE claims.id IS NOT NULL), ARRAY[]::text[]) AS claim_code_ids
    FROM public.commerce_orders orders
    LEFT JOIN public.promotion_code_claims claims ON claims.order_id = orders.id
    WHERE private.promotion_order_has_v2_evidence(orders.metadata)
      AND orders.status IN ('paid', 'fulfillment_pending', 'fulfilled', 'refunded')
    GROUP BY orders.id
  ), evaluated AS (
    SELECT id AS order_id,
      private.promotion_persisted_money_mismatch_codes(
        metadata, subtotal_cents, discount_cents, shipping_discount_cents, claim_code_ids
      ) AS mismatch_codes
    FROM v2_orders
  )
  SELECT
    count(*) FILTER (WHERE cardinality(mismatch_codes) > 0),
    coalesce(jsonb_agg(jsonb_build_object(
      'orderId', order_id,
      'mismatchCodes', to_jsonb(mismatch_codes)
    ) ORDER BY order_id) FILTER (
      WHERE cardinality(mismatch_codes) > 0 AND ordinal <= p_evidence_limit
    ), '[]'::jsonb)
  INTO v_promotion_money_mismatches, v_money_evidence
  FROM (
    SELECT evaluated.*,
      row_number() OVER (ORDER BY evaluated.order_id) AS ordinal
    FROM evaluated
  ) bounded_money;

  IF p_include_health THEN
  WITH relevant_orders AS (
    SELECT
      orders.id,
      private.promotion_persisted_money_mismatch_codes(
        orders.metadata,
        orders.subtotal_cents,
        orders.discount_cents,
        orders.shipping_discount_cents,
        coalesce(array_agg(DISTINCT claims.promotion_code_id::text
          ORDER BY claims.promotion_code_id::text)
          FILTER (WHERE claims.id IS NOT NULL), ARRAY[]::text[])
      ) AS mismatch_codes
    FROM public.commerce_orders orders
    LEFT JOIN public.promotion_code_claims claims ON claims.order_id = orders.id
    WHERE private.promotion_order_has_v2_evidence(orders.metadata)
      AND (
        orders.status IN ('paid', 'fulfillment_pending', 'fulfilled', 'refunded')
        OR (orders.status IN ('draft', 'pending_payment') AND orders.created_at >= v_window_from)
      )
    GROUP BY orders.id
  )
  SELECT count(*) FILTER (WHERE 'promotion_claim_ids' = ANY(mismatch_codes))
  INTO v_missing_claim_orders
  FROM relevant_orders;

  WITH capacity_evidence AS (
    SELECT
      1 AS priority,
      v_now AS sort_at,
      codes.id AS sort_id,
      jsonb_build_object(
        'kind', 'capacity_exceeded',
        'scope', 'global',
        'promotionCodeId', codes.id,
        'count', count(claims.id),
        'limit', codes.redemption_limit_global,
        'observedAt', v_now
      ) AS evidence
    FROM public.promotion_codes codes
    JOIN public.promotion_code_claims claims
      ON claims.promotion_code_id = codes.id
     AND claims.status IN ('reserved', 'redeemed')
    WHERE codes.redemption_limit_global IS NOT NULL
    GROUP BY codes.id, codes.redemption_limit_global
    HAVING count(claims.id) > codes.redemption_limit_global
    ORDER BY count(claims.id) - codes.redemption_limit_global DESC, codes.id
    LIMIT p_evidence_limit
  ), customer_capacity_evidence AS (
    SELECT
      1 AS priority,
      v_now AS sort_at,
      min(claims.id::text)::uuid AS sort_id,
      jsonb_build_object(
        'kind', 'capacity_exceeded',
        'scope', 'customer',
        'claimId', min(claims.id::text)::uuid,
        'promotionCodeId', codes.id,
        'orderId', min(claims.order_id::text)::uuid,
        'count', count(*),
        'limit', codes.redemption_limit_per_customer,
        'observedAt', v_now
      ) AS evidence
    FROM public.promotion_codes codes
    JOIN public.promotion_code_claims claims
      ON claims.promotion_code_id = codes.id
     AND claims.status IN ('reserved', 'redeemed')
     AND claims.client_id IS NOT NULL
    WHERE codes.redemption_limit_per_customer IS NOT NULL
    GROUP BY codes.id, codes.redemption_limit_per_customer, claims.client_id
    HAVING count(*) > codes.redemption_limit_per_customer
    ORDER BY count(*) - codes.redemption_limit_per_customer DESC, codes.id, min(claims.id::text)
    LIMIT p_evidence_limit
  ), active_code_capacity AS (
    SELECT promotion_code_id, count(*)::bigint AS active_claims
    FROM public.promotion_code_claims
    WHERE status IN ('reserved', 'redeemed')
    GROUP BY promotion_code_id
  ), active_customer_capacity AS (
    SELECT promotion_code_id, client_id, count(*)::bigint AS active_claims
    FROM public.promotion_code_claims
    WHERE status IN ('reserved', 'redeemed')
      AND client_id IS NOT NULL
    GROUP BY promotion_code_id, client_id
  ), stale_evidence AS (
    SELECT
      2 AS priority,
      claims.expires_at AS sort_at,
      claims.id AS sort_id,
      jsonb_build_object(
        'kind', 'stale_reserved',
        'claimId', claims.id,
        'promotionCodeId', claims.promotion_code_id,
        'orderId', claims.order_id,
        'blockingCapacity', (
          (codes.redemption_limit_global IS NOT NULL
            AND coalesce(code_capacity.active_claims, 0) >= codes.redemption_limit_global)
          OR
          (codes.redemption_limit_per_customer IS NOT NULL
            AND claims.client_id IS NOT NULL
            AND coalesce(customer_capacity.active_claims, 0) >= codes.redemption_limit_per_customer)
        ),
        'observedAt', v_now
      ) AS evidence
    FROM public.promotion_code_claims claims
    JOIN public.commerce_orders orders ON orders.id = claims.order_id
    JOIN public.promotion_codes codes ON codes.id = claims.promotion_code_id
    LEFT JOIN active_code_capacity code_capacity
      ON code_capacity.promotion_code_id = claims.promotion_code_id
    LEFT JOIN active_customer_capacity customer_capacity
      ON customer_capacity.promotion_code_id = claims.promotion_code_id
     AND customer_capacity.client_id = claims.client_id
    WHERE claims.status = 'reserved'
      AND claims.expires_at <= p_stale_before
      AND orders.status IN ('draft', 'pending_payment')
    ORDER BY claims.expires_at, claims.id
    LIMIT p_evidence_limit
  ), lifecycle_evidence AS (
    SELECT
      3 AS priority,
      claims.updated_at AS sort_at,
      claims.id AS sort_id,
      jsonb_build_object(
        'kind', 'lifecycle_mismatch',
        'claimId', claims.id,
        'promotionCodeId', claims.promotion_code_id,
        'orderId', claims.order_id,
        'observedAt', v_now
      ) AS evidence
    FROM public.promotion_code_claims claims
    JOIN public.commerce_orders orders ON orders.id = claims.order_id
    WHERE (orders.status IN ('paid', 'fulfillment_pending', 'fulfilled', 'refunded')
        AND claims.status <> 'redeemed')
       OR (orders.status IN ('cancelled', 'failed', 'expired')
        AND claims.status IN ('reserved', 'redeemed'))
       OR (orders.status IN ('draft', 'pending_payment') AND claims.status = 'redeemed')
    ORDER BY claims.updated_at DESC, claims.id DESC
    LIMIT p_evidence_limit
  ), missing_claim_evidence AS (
    SELECT 4 AS priority, orders.created_at AS sort_at, orders.id AS sort_id,
      jsonb_build_object(
        'kind', 'missing_claim', 'orderId', orders.id, 'observedAt', v_now
      ) AS evidence
    FROM public.commerce_orders orders
    LEFT JOIN public.promotion_code_claims claims ON claims.order_id = orders.id
    WHERE private.promotion_order_has_v2_evidence(orders.metadata)
      AND (
        orders.status IN ('paid', 'fulfillment_pending', 'fulfilled', 'refunded')
        OR (orders.status IN ('draft', 'pending_payment') AND orders.created_at >= v_window_from)
      )
    GROUP BY orders.id
    HAVING 'promotion_claim_ids' = ANY(private.promotion_persisted_money_mismatch_codes(
      orders.metadata, orders.subtotal_cents, orders.discount_cents,
      orders.shipping_discount_cents,
      coalesce(array_agg(DISTINCT claims.promotion_code_id::text
        ORDER BY claims.promotion_code_id::text)
        FILTER (WHERE claims.id IS NOT NULL), ARRAY[]::text[])
    ))
    ORDER BY orders.created_at DESC, orders.id DESC
    LIMIT p_evidence_limit
  ), orphan_evidence AS (
    SELECT 5 AS priority, claims.updated_at AS sort_at, claims.id AS sort_id,
      jsonb_build_object(
        'kind', 'orphan_claim',
        'claimId', claims.id,
        'promotionCodeId', claims.promotion_code_id,
        'orderId', claims.order_id,
        'observedAt', v_now
      ) AS evidence
    FROM public.promotion_code_claims claims
    LEFT JOIN public.commerce_orders orders ON orders.id = claims.order_id
    LEFT JOIN public.promotion_codes codes ON codes.id = claims.promotion_code_id
    WHERE orders.id IS NULL OR codes.id IS NULL
    ORDER BY claims.updated_at DESC, claims.id DESC
    LIMIT p_evidence_limit
  ), late_paid_evidence AS (
    SELECT 6 AS priority, events.occurred_at AS sort_at, events.id AS sort_id,
      jsonb_build_object(
        'kind', 'late_paid',
        'claimId', events.claim_id,
        'promotionCodeId', events.code_id,
        'orderId', events.order_id,
        'observedAt', v_now
      ) AS evidence
    FROM public.promotion_code_claim_events events
    WHERE events.occurred_at >= v_window_from AND events.occurred_at <= v_now
      AND events.transition_kind = 'late_paid'
    ORDER BY events.occurred_at DESC, events.id DESC
    LIMIT p_evidence_limit
  ), bounded AS (
    SELECT candidate.evidence
    FROM (
      SELECT * FROM capacity_evidence
      UNION ALL
      SELECT * FROM customer_capacity_evidence
      UNION ALL
      SELECT * FROM stale_evidence
      UNION ALL
      SELECT * FROM lifecycle_evidence
      UNION ALL
      SELECT * FROM missing_claim_evidence
      UNION ALL
      SELECT * FROM orphan_evidence
      UNION ALL
      SELECT * FROM late_paid_evidence
    ) candidate
    ORDER BY candidate.priority, candidate.sort_at DESC, candidate.sort_id DESC
    LIMIT p_evidence_limit
  )
  SELECT coalesce(jsonb_agg(evidence), '[]'::jsonb)
  INTO v_evidence
  FROM bounded;
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'promotion-health.v1',
    'historyCoverage', 'post_migration_only',
    'measuredAt', v_now,
    'windowFrom', v_window_from,
    'staleBefore', p_stale_before,
    'aggregates', jsonb_build_object(
      'claims', jsonb_build_object(
        'reserved', v_reserved,
        'redeemed', v_redeemed,
        'released', v_released,
        'activeCapacity', v_reserved + v_redeemed,
        'staleReserved', v_stale,
        'staleBlockingCapacity', v_stale_blocking_capacity
      ),
      'capacity', jsonb_build_object(
        'definition', 'reserved_plus_redeemed',
        'configuredLimitCodes', v_configured_limit_codes,
        'atLimitCodes', v_at_limit_codes,
        'overLimitCodes', v_over_limit_codes
      ),
      'lifecycleMismatchCount', v_lifecycle_mismatch,
      'missingClaimOrderCount', v_missing_claim_orders,
      'orphanClaimCount', v_orphan_claims,
      'promotionMoneyMismatchCount', v_promotion_money_mismatches
    ),
    'transitionCounts24h', jsonb_build_object(
      'reserved', v_event_reserved,
      'redeemed', v_event_redeemed,
      'released', v_event_released,
      'late_paid', v_event_late_paid
    ),
    'evidence', v_evidence,
    'moneyEvidence', v_money_evidence
  );
END;
$$;


--
-- Name: FUNCTION commerce_promotion_health_snapshot(p_since timestamp with time zone, p_stale_before timestamp with time zone, p_evidence_limit integer, p_include_health boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_promotion_health_snapshot(p_since timestamp with time zone, p_stale_before timestamp with time zone, p_evidence_limit integer, p_include_health boolean) IS 'Service-role-only bounded health projection. Persisted-money equations always run; p_include_health=false skips claim/event/capacity projections. Events use a <=24 hour occurred_at range, evidence and moneyEvidence are each capped at 100, and exact current capacity is reserved + redeemed. It acquires no business lock.';


--
-- Name: commerce_promotion_redemption_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_promotion_redemption_counts(p_client_id uuid DEFAULT NULL::uuid) RETURNS TABLE(promotion_id uuid, global_count bigint, per_customer_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT
    COALESCE(p.v2_mirror_of, r.promotion_id) AS promotion_id,
    count(*) AS global_count,
    count(*) FILTER (
      WHERE p_client_id IS NOT NULL AND r.client_id = p_client_id
    ) AS per_customer_count
  FROM public.promotion_redemptions r
  JOIN public.promotions p ON p.id = r.promotion_id
  GROUP BY COALESCE(p.v2_mirror_of, r.promotion_id);
$$;


--
-- Name: commerce_reconcile_checkout_email_outbox(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_reconcile_checkout_email_outbox(p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 500), 1), 1000);
  v_paid_checked integer := 0;
  v_paid_email_inserted integer := 0;
  v_failed_checked integer := 0;
  v_expired_checked integer := 0;
  v_checkout_expired_inserted integer := 0;
BEGIN
  WITH paid_candidates AS MATERIALIZED (
    SELECT o.id, o.mode
      FROM public.commerce_orders o
     WHERE o.status = 'paid'
       AND NOT EXISTS (
         SELECT 1 FROM public.outbox_events e
          WHERE e.event_type = 'commerce.order.paid.email'
            AND e.idempotency_key = 'order_paid_email:' || o.id::text
       )
     ORDER BY o.updated_at NULLS FIRST, o.created_at NULLS FIRST, o.id
     LIMIT v_limit
  ),
  paid_email_inserted AS (
    INSERT INTO public.outbox_events (aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata)
    SELECT
      'commerce_order',
      c.id,
      'commerce.order.paid.email',
      'order_paid_email:' || c.id::text,
      jsonb_build_object('orderId', 'order_' || c.id::text, 'orderUuid', c.id, 'mode', c.mode, 'occurredAt', now()),
      jsonb_build_object('source', 'commerce_reconcile_checkout_email_outbox')
    FROM paid_candidates c
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING 1
  )
  SELECT (SELECT count(*)::integer FROM paid_candidates), (SELECT count(*)::integer FROM paid_email_inserted)
    INTO v_paid_checked, v_paid_email_inserted;

  SELECT count(*)::integer
    INTO v_failed_checked
    FROM public.commerce_orders o
   WHERE o.status = 'failed'
   LIMIT v_limit;

  WITH expired_candidates AS MATERIALIZED (
    SELECT
      o.id,
      o.client_id,
      o.total_cents,
      o.currency,
      o.mode,
      COALESCE(o.created_at, now()) + interval '30 days' AS expires_at,
      CASE
        WHEN o.client_id IS NOT NULL
        THEN 'rcv_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '')
        ELSE NULL
      END AS recovery_token
      FROM public.commerce_orders o
     WHERE o.status = 'expired'
       AND o.mode = 'one_time'
       AND NOT EXISTS (
         SELECT 1 FROM public.outbox_events e
          WHERE e.event_type = 'commerce.checkout.expired'
            AND e.idempotency_key = 'checkout_expired:' || o.id::text
       )
     ORDER BY o.updated_at NULLS FIRST, o.created_at NULLS FIRST, o.id
     LIMIT v_limit
  ),
  checkout_expired_inserted AS (
    INSERT INTO public.outbox_events (aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata)
    SELECT
      'commerce_order',
      c.id,
      'commerce.checkout.expired',
      'checkout_expired:' || c.id::text,
      jsonb_build_object(
        'orderId', 'order_' || c.id::text,
        'orderUuid', c.id,
        'totalCents', c.total_cents,
        'currency', c.currency,
        'occurredAt', now()
      )
      || CASE
        WHEN c.recovery_token IS NOT NULL THEN jsonb_build_object(
          'recoveryToken', c.recovery_token,
          'mode', c.mode,
          'expiresAt', c.expires_at
        )
        ELSE '{}'::jsonb
      END,
      jsonb_build_object(
        'source', 'commerce_reconcile_checkout_email_outbox',
        'recoveryToken', CASE WHEN c.recovery_token IS NOT NULL THEN 'checkout_recovery_hash_only' ELSE 'absent' END
      )
    FROM expired_candidates c
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING aggregate_id, payload
  ),
  checkout_recovery_token_inserted AS (
    INSERT INTO public.commerce_checkout_recovery_tokens (
      order_id,
      client_id,
      token_hash,
      expires_at,
      metadata
    )
    SELECT
      e.aggregate_id,
      o.client_id,
      encode(sha256(convert_to(e.payload->>'recoveryToken', 'UTF8')), 'hex'),
      (e.payload->>'expiresAt')::timestamptz,
      jsonb_build_object(
        'source', 'commerce_reconcile_checkout_email_outbox',
        'eventType', 'commerce.checkout.expired',
        'outboxIdempotencyKey', 'checkout_expired:' || e.aggregate_id::text
      )
      FROM checkout_expired_inserted e
      JOIN public.commerce_orders o ON o.id = e.aggregate_id
     WHERE e.payload ? 'recoveryToken'
    RETURNING 1
  )
  SELECT
    (SELECT count(*)::integer FROM expired_candidates),
    (SELECT count(*)::integer FROM checkout_expired_inserted)
      + (SELECT count(*)::integer FROM checkout_recovery_token_inserted) * 0
    INTO v_expired_checked, v_checkout_expired_inserted;

  RETURN jsonb_build_object(
    'checked', jsonb_build_object('paid', v_paid_checked, 'failed', v_failed_checked, 'expired', v_expired_checked),
    'inserted', jsonb_build_object(
      'commerceOrderPaid', 0,
      'commerceOrderPaidEmail', v_paid_email_inserted,
      'commercePaymentFailed', 0,
      'commerceCheckoutExpired', v_checkout_expired_inserted
    )
  );
END;
$$;


--
-- Name: FUNCTION commerce_reconcile_checkout_email_outbox(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_reconcile_checkout_email_outbox(p_limit integer) IS 'Idempotently repairs missing checkout email/terminal payment outbox events using the same event types and idempotency keys as the checkout triggers.';


--
-- Name: commerce_record_stock_notify_attempt(text, text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_record_stock_notify_attempt(p_ip_hash text, p_email_hash text, p_sku_hash text, p_window_minutes integer DEFAULT 60, p_max_per_ip integer DEFAULT 20, p_max_per_email_sku integer DEFAULT 3) RETURNS TABLE(allowed boolean, reason text, attempts_by_ip integer, attempts_by_email_sku integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_window_minutes integer := GREATEST(LEAST(COALESCE(p_window_minutes, 60), 720), 1);
  v_max_per_ip integer := GREATEST(LEAST(COALESCE(p_max_per_ip, 20), 500), 1);
  v_max_per_email_sku integer := GREATEST(LEAST(COALESCE(p_max_per_email_sku, 3), 100), 1);
  v_since timestamptz := now() - make_interval(mins => v_window_minutes);
  v_ip_count integer := 0;
  v_email_sku_count integer := 0;
BEGIN
  IF p_ip_hash IS NULL OR length(p_ip_hash) = 0 THEN
    RAISE EXCEPTION 'stock_notify_attempt_missing_ip_hash'
      USING ERRCODE = '22023';
  END IF;

  IF p_email_hash IS NULL OR length(p_email_hash) = 0 THEN
    RAISE EXCEPTION 'stock_notify_attempt_missing_email_hash'
      USING ERRCODE = '22023';
  END IF;

  IF p_sku_hash IS NULL OR length(p_sku_hash) = 0 THEN
    RAISE EXCEPTION 'stock_notify_attempt_missing_sku_hash'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*)
    INTO v_ip_count
    FROM public.commerce_stock_notify_attempts
   WHERE ip_hash = p_ip_hash
     AND created_at >= v_since;

  SELECT count(*)
    INTO v_email_sku_count
    FROM public.commerce_stock_notify_attempts
   WHERE email_hash = p_email_hash
     AND sku_hash = p_sku_hash
     AND created_at >= v_since;

  IF v_ip_count >= v_max_per_ip THEN
    RETURN QUERY SELECT false, 'ip_quota'::text, v_ip_count, v_email_sku_count;
    RETURN;
  END IF;

  IF v_email_sku_count >= v_max_per_email_sku THEN
    RETURN QUERY SELECT false, 'email_sku_quota'::text, v_ip_count, v_email_sku_count;
    RETURN;
  END IF;

  INSERT INTO public.commerce_stock_notify_attempts (ip_hash, email_hash, sku_hash)
  VALUES (p_ip_hash, p_email_hash, p_sku_hash);

  RETURN QUERY SELECT true, NULL::text, v_ip_count + 1, v_email_sku_count + 1;
END;
$$;


--
-- Name: commerce_release_order_reservations(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_release_order_reservations(p_order_id uuid, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_reservation record;
  v_released integer := 0;
BEGIN
  FOR v_reservation IN
    SELECT id
      FROM public.inventory_reservations
     WHERE order_id = p_order_id
       AND status = 'reserved'
     FOR UPDATE
  LOOP
    PERFORM public.inventory_release_reservation(
      'payment-control-release:' || p_order_id::text || ':' || v_reservation.id::text,
      v_reservation.id,
      p_reason,
      jsonb_build_object('source', 'payment.control.v0')
    );
    v_released := v_released + 1;
  END LOOP;
  RETURN v_released;
END;
$$;


--
-- Name: commerce_release_reservations_on_cancel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_release_reservations_on_cancel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status <> 'cancelled' THEN
    RETURN NEW;
  END IF;

  -- Only act on the transition INTO cancelled. A direct INSERT as 'cancelled'
  -- (backfill) has no reservations yet; an UPDATE that was already cancelled is
  -- a no-op we skip to avoid redundant release scans.
  IF TG_OP <> 'UPDATE' OR OLD.status IS NOT DISTINCT FROM 'cancelled' THEN
    RETURN NEW;
  END IF;

  PERFORM public.commerce_release_order_reservations(NEW.id, 'order_cancelled');

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_release_reservations_on_cancel(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_release_reservations_on_cancel() IS 'Releases an order''s reserved inventory (via commerce_release_order_reservations) on the transition into status=cancelled, so cancelled orders stop depressing sellableNow. Idempotent.';


--
-- Name: commerce_return_approve(text, uuid, uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_return_approve(p_idempotency_key text, p_return_request_id uuid, p_approved_by uuid, p_refund_mode text DEFAULT 'full'::text, p_refund_amount_cents integer DEFAULT NULL::integer, p_admin_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_request public.commerce_return_requests%ROWTYPE;
  v_op_key text := btrim(coalesce(p_idempotency_key,'')) || ':approved';
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_return_request_id IS NULL
    OR p_refund_mode NOT IN ('full','partial','none')
    OR (p_refund_mode = 'partial' AND (p_refund_amount_cents IS NULL OR p_refund_amount_cents < 0))
  THEN
    RAISE EXCEPTION 'commerce_return_approve_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_request FROM public.commerce_return_requests WHERE id = p_return_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_return_approve_not_found' USING ERRCODE = '22023';
  END IF;

  -- Idempotent replay: already approved with this operation key.
  IF EXISTS (SELECT 1 FROM public.commerce_return_operations WHERE idempotency_key = v_op_key) THEN
    RETURN jsonb_build_object('contractVersion','commerce.returns.v0','returnRequestId',v_request.id,'status',v_request.status,'replayed',true);
  END IF;
  IF v_request.status <> 'requested' THEN
    RAISE EXCEPTION 'commerce_return_approve_invalid_state' USING ERRCODE = '22023';
  END IF;

  UPDATE public.commerce_return_requests
     SET status = 'approved',
         approved_by = p_approved_by,
         refund_mode = p_refund_mode,
         refund_amount_cents = CASE WHEN p_refund_mode = 'partial' THEN p_refund_amount_cents ELSE refund_amount_cents END,
         admin_note = COALESCE(NULLIF(btrim(coalesce(p_admin_note,'')), ''), admin_note),
         updated_at = now()
   WHERE id = p_return_request_id;

  INSERT INTO public.commerce_return_operations (
    return_request_id, actor_user_id, operation_type, source, idempotency_key, payload
  )
  VALUES (
    p_return_request_id, p_approved_by, 'approved', 'admin', v_op_key,
    jsonb_build_object('refundMode', p_refund_mode)
  );

  RETURN jsonb_build_object('contractVersion','commerce.returns.v0','returnRequestId',p_return_request_id,'status','approved','replayed',false);
END;
$$;


--
-- Name: commerce_return_reject(text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_return_reject(p_idempotency_key text, p_return_request_id uuid, p_approved_by uuid, p_admin_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_request public.commerce_return_requests%ROWTYPE;
  v_op_key text := btrim(coalesce(p_idempotency_key,'')) || ':rejected';
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8 OR p_return_request_id IS NULL THEN
    RAISE EXCEPTION 'commerce_return_reject_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_request FROM public.commerce_return_requests WHERE id = p_return_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_return_reject_not_found' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (SELECT 1 FROM public.commerce_return_operations WHERE idempotency_key = v_op_key) THEN
    RETURN jsonb_build_object('contractVersion','commerce.returns.v0','returnRequestId',v_request.id,'status',v_request.status,'replayed',true);
  END IF;
  IF v_request.status <> 'requested' THEN
    RAISE EXCEPTION 'commerce_return_reject_invalid_state' USING ERRCODE = '22023';
  END IF;

  UPDATE public.commerce_return_requests
     SET status = 'rejected',
         approved_by = p_approved_by,
         admin_note = COALESCE(NULLIF(btrim(coalesce(p_admin_note,'')), ''), admin_note),
         updated_at = now()
   WHERE id = p_return_request_id;

  INSERT INTO public.commerce_return_operations (
    return_request_id, actor_user_id, operation_type, source, idempotency_key, payload
  )
  VALUES (p_return_request_id, p_approved_by, 'rejected', 'admin', v_op_key, '{}'::jsonb);

  RETURN jsonb_build_object('contractVersion','commerce.returns.v0','returnRequestId',p_return_request_id,'status','rejected','replayed',false);
END;
$$;


--
-- Name: commerce_return_request_create(text, uuid, jsonb, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_return_request_create(p_idempotency_key text, p_order_id uuid, p_lines jsonb, p_reason_code text, p_customer_note text DEFAULT NULL::text, p_requested_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_request public.commerce_return_requests%ROWTYPE;
  v_replayed boolean := false;
  v_line jsonb;
  v_item public.commerce_order_items%ROWTYPE;
  v_qty integer;
  v_sku text;
  v_disposition text;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_order_id IS NULL
    OR p_reason_code NOT IN ('damaged','wrong_item','not_as_described','pet_refused','changed_mind','other')
    OR p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0
  THEN
    RAISE EXCEPTION 'commerce_return_request_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- Idempotent replay: return the existing request unchanged.
  SELECT * INTO v_request
    FROM public.commerce_return_requests
   WHERE idempotency_key = btrim(p_idempotency_key);
  IF FOUND THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.returns.v0',
      'returnRequestId', v_request.id,
      'status', v_request.status,
      'replayed', true
    );
  END IF;

  SELECT * INTO v_order FROM public.commerce_orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_return_request_order_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_order.status NOT IN ('paid','fulfilled') THEN
    RAISE EXCEPTION 'commerce_return_request_order_not_returnable' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_return_requests (
    order_id, status, reason_code, customer_note, requested_by, idempotency_key
  )
  VALUES (
    p_order_id, 'requested', p_reason_code, NULLIF(btrim(coalesce(p_customer_note,'')), ''),
    p_requested_by, btrim(p_idempotency_key)
  )
  RETURNING * INTO v_request;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
  LOOP
    v_qty := NULLIF(v_line->>'quantity','')::integer;
    v_sku := btrim(coalesce(v_line->>'sku',''));
    v_disposition := coalesce(NULLIF(btrim(coalesce(v_line->>'restockDisposition','')), ''), 'restock');
    IF v_qty IS NULL OR v_qty <= 0 OR (v_line->>'orderItemId') IS NULL THEN
      RAISE EXCEPTION 'commerce_return_request_invalid_line' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_item
      FROM public.commerce_order_items
     WHERE id = (v_line->>'orderItemId')::uuid
       AND order_id = p_order_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'commerce_return_request_line_not_in_order' USING ERRCODE = '22023';
    END IF;
    IF v_qty > v_item.quantity THEN
      RAISE EXCEPTION 'commerce_return_request_quantity_exceeds_ordered' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.commerce_return_lines (
      return_request_id, order_item_id, sku, quantity, restock_disposition
    )
    VALUES (
      v_request.id, v_item.id,
      coalesce(NULLIF(v_sku,''), coalesce(v_item.product_snapshot->>'sku','unknown')),
      v_qty, v_disposition
    );
  END LOOP;

  INSERT INTO public.commerce_return_operations (
    return_request_id, actor_user_id, operation_type, source, idempotency_key, payload
  )
  VALUES (
    v_request.id, p_requested_by, 'requested', 'customer',
    btrim(p_idempotency_key) || ':requested',
    jsonb_build_object('reasonCode', p_reason_code)
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.returns.v0',
    'returnRequestId', v_request.id,
    'status', v_request.status,
    'replayed', v_replayed
  );
END;
$$;


--
-- Name: commerce_set_order_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_set_order_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF nullif(btrim(coalesce(NEW.order_number, '')), '') IS NULL THEN
    NEW.order_number := public.commerce_unique_order_number_from_id(NEW.id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: commerce_supersede_pre_payment_order_draft(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_supersede_pre_payment_order_draft(p_idempotency_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'commerce.order_draft.create';
  v_finalize_scope constant text := 'commerce.checkout_order_finalize';
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_order_id uuid;
  v_order public.commerce_orders%ROWTYPE;
  v_money_moved boolean;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' THEN
    RETURN false;
  END IF;

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  -- Recover the order id the producer stored on the key metadata ('order_<uuid>').
  -- A key without a recorded order (an incomplete prior attempt) still supersedes:
  -- we drop the key so create can re-run cleanly.
  v_order_id := NULLIF(
    regexp_replace(COALESCE(v_existing.metadata->>'orderId', ''), '^order_', ''),
    ''
  )::uuid;

  IF v_order_id IS NOT NULL THEN
    SELECT *
      INTO v_order
      FROM public.commerce_orders
     WHERE id = v_order_id
     FOR UPDATE;

    IF FOUND THEN
      -- MONEY-MOVED guard: refuse ONLY when funds actually moved. An UNPAID order
      -- (draft or pending_payment) with only failed/pending payment attempts IS the
      -- supersede case (Tomi).
      v_money_moved :=
        v_order.status IN ('paid', 'fulfillment_pending', 'fulfilled', 'refunded')
        OR COALESCE(v_order.metadata->>'paymentStatus', '')
             IN ('succeeded', 'refunded', 'partially_refunded')
        OR EXISTS (
             SELECT 1
               FROM public.commerce_payments p
              WHERE p.order_id = v_order.id
                AND p.status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed')
           );

      IF v_money_moved THEN
        RETURN false;
      END IF;

      -- (1) Silently cancel the linked PROVISIONAL subscription. Pre-seed the
      -- subscription.cancelled outbox row as DISCARDED so the AFTER UPDATE trigger's
      -- own INSERT dedupes (ON CONFLICT DO NOTHING) and no customer email dispatches.
      IF v_order.subscription_id IS NOT NULL THEN
        INSERT INTO public.outbox_events (
          aggregate_type, aggregate_id, event_type, idempotency_key, status, payload, metadata
        )
        SELECT
          'subscription',
          s.id,
          'subscription.cancelled',
          'subscription_cancelled:' || s.id::text,
          'discarded',
          jsonb_build_object(
            'subscriptionId', s.id,
            'clientId', s.client_id,
            'suppressedReason', 'superseded_by_stable_journey_key'
          ),
          jsonb_build_object(
            'source', 'commerce_supersede_pre_payment_order_draft',
            'suppressedCustomerEmail', true
          )
          FROM public.subscriptions s
         WHERE s.id = v_order.subscription_id
           AND s.status = 'pending_activation'
        ON CONFLICT (event_type, idempotency_key) DO NOTHING;

        -- NB: public.subscriptions has no metadata column; provenance is recorded in
        -- cancellation_reason.
        UPDATE public.subscriptions
           SET status = 'cancelled',
               ended_at = now(),
               cancellation_reason = 'superseded_by_stable_journey_key',
               updated_at = now()
         WHERE id = v_order.subscription_id
           AND status = 'pending_activation';
      END IF;

      -- (2) Neutralize any still-LIVE (non-terminal) payment intent / active attempt
      -- / payment so no timeout sweeper or in-flight reader treats them as live.
      -- Already-terminal rows (failed/expired/cancelled) are left truthfully as-is;
      -- captured rows are unreachable here (money-moved refused above).
      UPDATE public.commerce_payment_attempts a
         SET status = 'cancelled',
             updated_at = now()
       WHERE a.status IN ('created', 'sent_to_provider', 'requires_action', 'processing')
         AND a.payment_intent_id IN (
           SELECT i.id FROM public.commerce_payment_intents i WHERE i.order_id = v_order.id
         );

      UPDATE public.commerce_payment_intents
         SET status = 'cancelled',
             updated_at = now()
       WHERE order_id = v_order.id
         AND status IN ('created', 'requires_action', 'processing');

      UPDATE public.commerce_payments
         SET status = 'cancelled',
             metadata = metadata || jsonb_build_object('supersededByStableJourneyKey', true),
             updated_at = now()
       WHERE order_id = v_order.id
         AND status IN ('pending', 'requires_action');

      -- (2b) Free the derived keys this journey wrote into the payment audit
      -- ledger. `commerce_payment_state_transitions.idempotency_key` is UNIQUE,
      -- and its rows are named INSIDE SQL from the caller's key:
      -- `:intent_created` by create_intent, `:attempt_prepared` and
      -- `:attempt_finalized` by the prepared-attempt pair, `:attempt_recorded`
      -- by the recorded one. Left standing, the first of them is the collision
      -- the re-drafted order meets one statement after the key rows below are
      -- gone — as a raw 23505 no caller can classify.
      --
      -- The row keeps its id, its payload and its place in the trail; only the
      -- name it occupied is released. Folding the row id into the new key makes
      -- the rename unique by construction, so superseding the same journey
      -- twice cannot collide with its own earlier rename.
      --
      -- Scope: intents of THIS order, matched on the same `left(...) = key ||
      -- ':'` colon boundary the DELETE below uses, so no other journey's ledger
      -- can move and a merely shared leading substring cannot match.
      UPDATE public.commerce_payment_state_transitions t
         SET idempotency_key = 'superseded:' || t.id::text || ':' || t.idempotency_key
       WHERE left(t.idempotency_key, length(p_idempotency_key) + 1) = p_idempotency_key || ':'
         AND t.payment_intent_id IN (
           SELECT i.id FROM public.commerce_payment_intents i WHERE i.order_id = v_order.id
         );

      -- (3) Cancel the stale UNPAID order. Status/metadata only — money columns are
      -- untouched, so the frozen-money BEFORE UPDATE trigger does not fire, and the
      -- order-canceled email trigger only fires when OLD.status was paid/fulfillment.
      UPDATE public.commerce_orders
         SET status = 'cancelled',
             metadata = metadata || jsonb_build_object(
               'supersededByStableJourneyKey', true,
               'supersededAt', now()
             ),
             updated_at = now()
       WHERE id = v_order.id;

      -- (4) Discard the not-yet-dispatched draft-saved outbox event.
      UPDATE public.outbox_events
         SET status = 'discarded',
             error = 'superseded_by_stable_journey_key_redraft'
       WHERE aggregate_type = 'commerce_order'
         AND aggregate_id = v_order.id
         AND event_type = 'commerce.order_draft.created'
         AND status = 'pending';
    END IF;
  END IF;

  -- (5) Drop every idempotency-key row DERIVED from this journey key, by
  -- construction rather than by enumeration. `startRuntime` derives at least
  -- `:inventory`, `:payment-intent`, `:payment-attempt`, `:inventory-release`,
  -- `:payment-execution` (or `:payment-execution:attempt:<n>`) and, for prepared
  -- providers, `<execution>:prepare-attempt` / `:finalize-attempt`. #3435 cleared
  -- two scopes; an earlier draft of THIS migration added a third and claimed the
  -- set was exactly three. It was not — `:payment-execution:prepare-attempt` is the
  -- live Stripe/Tpay path, whose RPC fingerprints over the intent id and would
  -- raise `payment_control_provider_attempt_prepare_idempotency_conflict` one call
  -- after the intent conflict this migration set out to fix.
  --
  -- ⛔ Matching the derived PREFIX is the point: an enumeration has now been wrong
  -- twice, and every future suffix would need someone to remember this statement.
  -- `left(...) = p_idempotency_key || ':'` is used rather than LIKE so no key
  -- containing `%` or `_` can widen the match.
  --
  -- The exact key stays scoped to the two scopes it legitimately lives in, because
  -- the RAW journey key is also written by `commerce.payment_result.apply` on the
  -- rehearsal branch and is reused as an identity by the configurator intent.
  --
  -- Position is load-bearing and unchanged: only reachable once the money-moved
  -- guard above has declined to refuse, and only after step (2) has cancelled this
  -- order's live payment rows — so a journey that took money keeps every row and
  -- stays un-finalizable, and nothing redeemable is ever dropped.
  DELETE FROM public.commerce_idempotency_keys
   WHERE (scope IN (v_scope, v_finalize_scope) AND idempotency_key = p_idempotency_key)
      OR left(idempotency_key, length(p_idempotency_key) + 1) = p_idempotency_key || ':';

  RETURN true;
END;
$$;


--
-- Name: FUNCTION commerce_supersede_pre_payment_order_draft(p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_supersede_pre_payment_order_draft(p_idempotency_key text) IS 'Supersede a stale UNPAID order draft for a stable journey key: cancels the provisional subscription, neutralizes live payment rows, cancels the order, discards the draft-saved outbox event, renames every payment-ledger row derived from the journey to superseded:<row id>:<old key> so the audit trail survives while the name is released, and drops every idempotency-key row the runtime saga derives from the journey. The re-drafted order therefore finalizes, opens its own intent and prepares its own provider attempt instead of meeting the cancelled order''s names. Refuses (false) the moment funds moved, leaving every key and every ledger row exactly as written.';


--
-- Name: commerce_sweep_expired_reservation_holds(text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_sweep_expired_reservation_holds(p_idempotency_prefix text, p_now timestamp with time zone, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_has_intent boolean;
  v_released integer;
  v_orders_checked integer := 0;
  v_orders_expired integer := 0;
  v_reservations_released integer := 0;
  v_skipped_paid integer := 0;
  v_skipped_terminal integer := 0;
  v_skipped_subscription integer := 0;
  v_swept jsonb := '[]'::jsonb;
BEGIN
  IF p_idempotency_prefix IS NULL OR length(btrim(p_idempotency_prefix)) < 8
     OR p_now IS NULL
     OR p_limit IS NULL OR p_limit < 1 THEN
    RAISE EXCEPTION 'commerce_reservation_sweep_invalid_input' USING ERRCODE = '22023';
  END IF;

  FOR v_order IN
    SELECT orders.*
      FROM public.commerce_orders orders
      JOIN (
        SELECT reservations.order_id, min(reservations.expires_at) AS oldest_expires_at
          FROM public.inventory_reservations reservations
         WHERE reservations.status = 'reserved'
           AND reservations.kind = 'checkout_payment_window'
           AND reservations.expires_at IS NOT NULL
           AND reservations.expires_at <= p_now
         GROUP BY reservations.order_id
      ) candidates ON candidates.order_id = orders.id
     ORDER BY candidates.oldest_expires_at, orders.id
     LIMIT p_limit
     FOR UPDATE OF orders SKIP LOCKED
  LOOP
    v_orders_checked := v_orders_checked + 1;

    IF v_order.status IN ('paid', 'fulfillment_pending', 'fulfilled', 'refunded') THEN
      v_skipped_paid := v_skipped_paid + 1;
      CONTINUE;
    END IF;

    IF v_order.status IN ('failed', 'expired', 'cancelled') THEN
      v_skipped_terminal := v_skipped_terminal + 1;
      CONTINUE;
    END IF;

    IF v_order.status <> 'pending_payment' THEN
      v_skipped_terminal := v_skipped_terminal + 1;
      CONTINUE;
    END IF;

    IF v_order.mode = 'subscription_cycle'
       AND EXISTS (
         SELECT 1
           FROM public.subscriptions subscriptions
          WHERE subscriptions.id = v_order.subscription_id
            AND subscriptions.status = 'pending_activation'
       ) THEN
      v_skipped_subscription := v_skipped_subscription + 1;
      CONTINUE;
    END IF;

    SELECT *
      INTO v_intent
      FROM public.commerce_payment_intents
     WHERE order_id = v_order.id
     FOR UPDATE;
    v_has_intent := FOUND;

    IF v_has_intent AND v_intent.status = 'succeeded' THEN
      v_skipped_paid := v_skipped_paid + 1;
      CONTINUE;
    END IF;

    IF v_has_intent AND v_intent.status IN ('refunded', 'partially_refunded', 'disputed') THEN
      v_skipped_terminal := v_skipped_terminal + 1;
      CONTINUE;
    END IF;

    -- Close the late-success race: `expired` can be recovered by payment-control,
    -- but `cancelled` is terminal for a future succeeded apply_result.
    IF v_has_intent THEN
      UPDATE public.commerce_payment_intents
         SET status = 'cancelled',
             failure_reason = 'reservation_window_elapsed',
             metadata = metadata || jsonb_build_object(
               'paymentStatus', 'expired',
               'reservationSweep', true,
               'source', 'commerce.reservation_sweep.v0'
             ),
             updated_at = now()
       WHERE id = v_intent.id
         AND status NOT IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed');

      UPDATE public.commerce_payment_attempts
         SET status = 'expired',
             failure_reason = 'reservation_window_elapsed',
             updated_at = now()
       WHERE payment_intent_id = v_intent.id
         AND status NOT IN ('succeeded', 'cancelled', 'failed', 'expired');

      UPDATE public.commerce_payments
         SET status = 'expired',
             metadata = metadata || jsonb_build_object(
               'paymentStatus', 'expired',
               'failureReason', 'reservation_window_elapsed',
               'source', 'commerce.reservation_sweep.v0'
             ),
             updated_at = now()
       WHERE id = v_intent.payment_id
         AND status NOT IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed');
    END IF;

    UPDATE public.commerce_orders
       SET status = 'expired',
           metadata = metadata || jsonb_build_object(
             'paymentStatus', 'expired',
             'abandonmentReason', 'reservation_window_elapsed',
             'source', 'commerce.reservation_sweep.v0'
           ),
           updated_at = now()
     WHERE id = v_order.id;

    v_released := public.commerce_release_order_reservations(
      v_order.id,
      'reservation_window_elapsed'
    );

    v_orders_expired := v_orders_expired + 1;
    v_reservations_released := v_reservations_released + v_released;
    v_swept := v_swept || jsonb_build_object(
      'orderId', v_order.id,
      'releasedReservations', v_released
    );
  END LOOP;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'sweep', jsonb_build_object(
      'ordersChecked', v_orders_checked,
      'ordersExpired', v_orders_expired,
      'reservationsReleased', v_reservations_released,
      'skippedPaid', v_skipped_paid,
      'skippedTerminal', v_skipped_terminal,
      'skippedSubscription', v_skipped_subscription,
      'swept', v_swept
    )
  );
END;
$$;


--
-- Name: FUNCTION commerce_sweep_expired_reservation_holds(p_idempotency_prefix text, p_now timestamp with time zone, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_sweep_expired_reservation_holds(p_idempotency_prefix text, p_now timestamp with time zone, p_limit integer) IS 'Product-agnostic sweep for expired checkout reservation holds; terminalizes abandoned unpaid orders and releases inventory through Inventory RPCs.';


--
-- Name: commerce_sweep_expired_retry_holds(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_sweep_expired_retry_holds(p_now timestamp with time zone, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_hold record;
  v_holds_checked integer := 0;
  v_holds_released integer := 0;
  v_skipped_paid integer := 0;
  v_swept jsonb := '[]'::jsonb;
BEGIN
  IF p_now IS NULL OR p_limit IS NULL OR p_limit < 1 THEN
    RAISE EXCEPTION 'commerce_retry_hold_sweep_invalid_input' USING ERRCODE = '22023';
  END IF;

  FOR v_hold IN
    SELECT reservations.id, reservations.order_id
      FROM public.inventory_reservations reservations
     WHERE reservations.status = 'reserved'
       AND reservations.kind = 'subscription_retry_window'
       AND reservations.expires_at IS NOT NULL
       AND reservations.expires_at <= p_now
     ORDER BY reservations.expires_at, reservations.id
     LIMIT p_limit
     FOR UPDATE OF reservations SKIP LOCKED
  LOOP
    v_holds_checked := v_holds_checked + 1;

    -- A paid-family order should have been pinned (expires_at = NULL) by
    -- commerce_pin_paid_order_reservations; an expired row there is an
    -- operator anomaly, not sweep territory.
    IF EXISTS (
      SELECT 1
        FROM public.commerce_orders orders
       WHERE orders.id = v_hold.order_id
         AND orders.status IN ('paid', 'fulfillment_pending', 'fulfilled', 'refunded')
    ) THEN
      v_skipped_paid := v_skipped_paid + 1;
      CONTINUE;
    END IF;

    PERFORM public.inventory_release_reservation(
      'retry-hold-sweep:' || v_hold.id::text,
      v_hold.id,
      'retry_window_elapsed',
      jsonb_build_object('source', 'commerce.retry_hold_sweep.v0')
    );

    v_holds_released := v_holds_released + 1;
    v_swept := v_swept || jsonb_build_object(
      'reservationId', v_hold.id,
      'orderId', v_hold.order_id
    );
  END LOOP;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'retrySweep', jsonb_build_object(
      'holdsChecked', v_holds_checked,
      'holdsReleased', v_holds_released,
      'skippedPaid', v_skipped_paid,
      'swept', v_swept
    )
  );
END;
$$;


--
-- Name: FUNCTION commerce_sweep_expired_retry_holds(p_now timestamp with time zone, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_sweep_expired_retry_holds(p_now timestamp with time zone, p_limit integer) IS 'Release-only hygiene for expired subscription_retry_window holds: frees stock and heals inventory_balances.reserved without touching the cycle order, subscription, or dunning case.';


--
-- Name: commerce_sweep_orphan_payment_events(text, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_sweep_orphan_payment_events(p_idempotency_prefix text, p_now timestamp with time zone, p_grace_minutes integer DEFAULT 1440, p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_ignored integer := 0;
  v_stale_setup integer := 0;
BEGIN
  IF p_idempotency_prefix IS NULL OR length(btrim(p_idempotency_prefix)) < 8
     OR p_now IS NULL
     OR p_grace_minutes IS NULL OR p_grace_minutes < 0
     OR p_limit IS NULL OR p_limit < 1 THEN
    RAISE EXCEPTION 'commerce_orphan_event_sweep_invalid_input' USING ERRCODE = '22023';
  END IF;

  WITH candidates AS (
    SELECT events.id
      FROM public.inbound_provider_events events
     WHERE events.processing_status = 'received'
       AND events.processed_at IS NULL
       AND events.payment_intent_id IS NULL
       AND events.payment_attempt_id IS NULL
       AND events.created_at <= p_now - make_interval(mins => p_grace_minutes)
       AND NOT EXISTS (
         SELECT 1
           FROM public.commerce_payment_attempts attempts
          WHERE attempts.provider = events.provider
            AND attempts.provider_attempt_id = events.provider_payment_id
       )
     ORDER BY events.created_at
     LIMIT p_limit
     FOR UPDATE OF events SKIP LOCKED
  )
  UPDATE public.inbound_provider_events events
     SET processing_status = 'ignored',
         processed_at = p_now,
         -- `error` is a free-text column; record why this was reaped (orphan events
         -- carry no real provider error, so there is nothing meaningful to clobber).
         error = 'orphan_no_local_attempt (commerce.payment_event_sweep.v0)'
    FROM candidates
   WHERE events.id = candidates.id;

  GET DIAGNOSTICS v_ignored = ROW_COUNT;

  -- Count-only anomaly signal: a setup.% ledger row still 'received' past the
  -- grace window means its webhook pipeline never completed (see header).
  SELECT count(*)
    INTO v_stale_setup
    FROM public.inbound_provider_events events
   WHERE events.processing_status = 'received'
     AND events.processed_at IS NULL
     AND events.event_type LIKE 'setup.%'
     AND events.created_at <= p_now - make_interval(mins => p_grace_minutes);

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'orphanEventSweep', jsonb_build_object(
      'eventsIgnored', v_ignored,
      'staleSetupReceived', v_stale_setup
    )
  );
END;
$$;


--
-- Name: FUNCTION commerce_sweep_orphan_payment_events(p_idempotency_prefix text, p_now timestamp with time zone, p_grace_minutes integer, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_sweep_orphan_payment_events(p_idempotency_prefix text, p_now timestamp with time zone, p_grace_minutes integer, p_limit integer) IS 'Marks aged, never-correlated inbound provider events (orphan test/CLI pings) as ignored and reports aged still-received setup.* events as staleSetupReceived.';


--
-- Name: commerce_sweep_stale_promotion_claims(timestamp with time zone, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_sweep_stale_promotion_claims(p_now timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 50, p_claim_lease_minutes integer DEFAULT 15, p_grace_minutes integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_candidate record;
  v_checked integer := 0;
  v_cancelled integer := 0;
  v_skipped integer := 0;
BEGIN
  IF p_now IS NULL OR p_limit < 1 OR p_limit > 200
     OR p_claim_lease_minutes < 1 OR p_grace_minutes < 0 THEN
    RAISE EXCEPTION 'promotion_claim_sweep_invalid_input' USING ERRCODE = '22023';
  END IF;

  FOR v_candidate IN
    SELECT claims.id AS claim_id, claims.order_id, keys.idempotency_key
      FROM public.promotion_code_claims claims
      JOIN public.commerce_orders orders ON orders.id = claims.order_id
      JOIN public.commerce_idempotency_keys keys
        ON keys.scope = 'commerce.order_draft.create'
       AND coalesce(keys.metadata->>'orderId', keys.response_payload#>>'{orderDraft,orderId}')
           = 'order_' || claims.order_id::text
     WHERE claims.status = 'reserved'
       AND claims.expires_at <= p_now - make_interval(mins => p_grace_minutes)
       AND claims.reserved_at <= p_now - make_interval(mins => p_claim_lease_minutes)
       AND orders.status IN ('draft', 'pending_payment')
     ORDER BY claims.expires_at, claims.id
     LIMIT p_limit
  LOOP
    v_checked := v_checked + 1;
    IF public.commerce_cancel_unstarted_promotion_order(
      v_candidate.idempotency_key,
      v_candidate.order_id,
      'stale_promotion_claim_sweep'
    ) THEN
      v_cancelled := v_cancelled + 1;
    ELSE
      v_skipped := v_skipped + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'checked', v_checked,
    'cancelled', v_cancelled,
    'skipped', v_skipped
  );
END;
$$;


--
-- Name: commerce_tpay_alias_method_ref_upsert_guarded(text, uuid, uuid, text, text, text, text, text, text, boolean, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_tpay_alias_method_ref_upsert_guarded(p_idempotency_key text, p_client_id uuid, p_subscription_id uuid, p_provider_kind text, p_method_kind text, p_provider_customer_ref text, p_provider_method_ref text, p_provider_mandate_ref text, p_status text, p_active boolean, p_expires_at timestamp with time zone, p_consent_snapshot jsonb, p_raw_provider_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_subscription public.subscriptions%ROWTYPE;
  v_effective_subscription_id uuid := p_subscription_id;
  v_result jsonb;
  v_binding_skipped boolean := false;
BEGIN
  IF p_provider_kind <> 'tpay' OR p_method_kind <> 'blik_payid' THEN
    RAISE EXCEPTION 'tpay_alias_guard_invalid_method' USING ERRCODE = '22023';
  END IF;

  IF p_subscription_id IS NOT NULL THEN
    SELECT * INTO v_subscription
      FROM public.subscriptions
     WHERE id = p_subscription_id
     FOR UPDATE;
    IF NOT FOUND OR v_subscription.client_id IS DISTINCT FROM p_client_id THEN
      RAISE EXCEPTION 'tpay_alias_guard_subscription_mismatch' USING ERRCODE = '22023';
    END IF;

    IF v_subscription.status = 'active'
       AND v_subscription.payment_method_kind = 'card' THEN
      v_effective_subscription_id := NULL;
      v_binding_skipped := true;
    END IF;
  END IF;

  v_result := public.commerce_payment_method_ref_upsert(
    p_idempotency_key || CASE
      WHEN v_binding_skipped THEN ':client_card_precedence'
      ELSE ':subscription_binding'
    END,
    p_client_id,
    v_effective_subscription_id,
    p_provider_kind,
    p_method_kind,
    p_provider_customer_ref,
    p_provider_method_ref,
    p_provider_mandate_ref,
    p_status,
    p_active,
    p_expires_at,
    p_consent_snapshot,
    p_raw_provider_payload
  );

  RETURN jsonb_set(
    v_result,
    '{paymentMethodRef,subscriptionBindingSkipped}',
    to_jsonb(v_binding_skipped),
    true
  );
END;
$$;


--
-- Name: commerce_transition_order_promotion_claims(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_transition_order_promotion_claims() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_code_id uuid;
  v_paid_at timestamptz;
BEGIN
  IF NEW.status IS NOT DISTINCT FROM OLD.status
    OR NEW.status NOT IN ('paid', 'cancelled', 'failed', 'expired') THEN
    RETURN NEW;
  END IF;
  FOR v_code_id IN
    SELECT DISTINCT claims.promotion_code_id
      FROM public.promotion_code_claims claims
     WHERE claims.order_id = NEW.id
     ORDER BY claims.promotion_code_id
  LOOP
    PERFORM 1 FROM public.promotion_codes codes WHERE codes.id = v_code_id FOR UPDATE;
    PERFORM 1
      FROM public.promotion_code_claims claims
     WHERE claims.order_id = NEW.id AND claims.promotion_code_id = v_code_id
     FOR UPDATE;

    IF NEW.status = 'paid' THEN
      v_paid_at := coalesce((NEW.metadata->>'paidAt')::timestamptz, now());
      UPDATE public.promotion_code_claims
         SET status = 'redeemed', redeemed_at = v_paid_at, released_at = NULL,
             release_reason = NULL, updated_at = now()
       WHERE order_id = NEW.id
         AND promotion_code_id = v_code_id
         AND status IN ('reserved', 'released');
    ELSE
      UPDATE public.promotion_code_claims
         SET status = 'released', released_at = now(),
             release_reason = 'order_' || NEW.status, updated_at = now()
       WHERE order_id = NEW.id
         AND promotion_code_id = v_code_id
         AND status = 'reserved';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION commerce_transition_order_promotion_claims(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_transition_order_promotion_claims() IS 'Runs inside the canonical order-status transaction. Locks order (caller) -> code -> claim; paid redeems even after release, terminal failure releases, refund is intentionally ignored.';


--
-- Name: commerce_unique_order_number_from_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_unique_order_number_from_id(p_order_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_hex text := upper(replace(p_order_id::text, '-', ''));
  v_chars integer := 8;
  v_candidate text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('commerce_order_number:' || substr(v_hex, 1, 8)));

  LOOP
    v_candidate := 'OPENLUP-' || substr(v_hex, 1, v_chars);
    IF NOT EXISTS (
      SELECT 1
        FROM public.commerce_orders
       WHERE order_number = v_candidate
         AND id <> p_order_id
    ) THEN
      RETURN v_candidate;
    END IF;

    IF v_chars >= length(v_hex) THEN
      RETURN 'OPENLUP-' || v_hex || '-' || upper(substr(md5(p_order_id::text), 1, 6));
    END IF;

    v_chars := least(v_chars + 4, length(v_hex));
  END LOOP;
END;
$$;


--
-- Name: commerce_validate_fulfillment_provider_kind(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_validate_fulfillment_provider_kind(p_provider_kind text, p_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_provider public.providers%ROWTYPE;
  v_region text;
BEGIN
  IF p_provider_kind IS NULL OR btrim(p_provider_kind) = '' THEN
    RETURN;
  END IF;

  SELECT *
    INTO v_provider
    FROM public.providers
   WHERE kind = p_provider_kind;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_provider_not_found'
      USING ERRCODE = '22023';
  END IF;

  IF v_provider.capability <> 'fulfillment' THEN
    RAISE EXCEPTION 'commerce_fulfillment_provider_wrong_capability'
      USING ERRCODE = '22023';
  END IF;

  IF v_provider.status NOT IN ('active', 'experimental') THEN
    RAISE EXCEPTION 'commerce_fulfillment_provider_not_available'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(region_code, 'PL')
    INTO v_region
    FROM public.commerce_orders
   WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_fulfillment_provider_order_not_found'
      USING ERRCODE = '22023';
  END IF;

  IF NOT (v_region = ANY(v_provider.enabled_for_region)) THEN
    RAISE EXCEPTION 'commerce_fulfillment_provider_region_unsupported'
      USING ERRCODE = '22023';
  END IF;
END;
$$;


--
-- Name: FUNCTION commerce_validate_fulfillment_provider_kind(p_provider_kind text, p_order_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commerce_validate_fulfillment_provider_kind(p_provider_kind text, p_order_id uuid) IS 'Validates fulfillment provider capability, status, and order region before fulfillment writes.';


--
-- Name: commerce_webhook_confirm_subscription_from_intent(text, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_webhook_confirm_subscription_from_intent(p_idempotency_key text, p_payment_intent_id uuid, p_payment_method_ref text, p_payment_method_kind text, p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_confirmation jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
     OR p_payment_intent_id IS NULL OR p_occurred_at IS NULL THEN
    RAISE EXCEPTION 'commerce_webhook_confirm_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'commerce_webhook_confirm_intent_not_found' USING ERRCODE = '22023';
  END IF;

  -- One-time orders (and any non-subscription intent) are not confirmable here.
  IF v_intent.target_kind <> 'subscription_cycle' OR v_intent.order_id IS NULL THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'webhookSubscriptionConfirm', jsonb_build_object('confirmed', false, 'reason', 'not_subscription_cycle')
    );
  END IF;

  v_confirmation := public.subscription_confirm_provisional_from_paid_cycle(
    p_idempotency_key,
    v_intent.order_id,
    p_payment_intent_id,
    p_payment_method_ref,
    p_payment_method_kind,
    p_occurred_at
  );

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'webhookSubscriptionConfirm', jsonb_build_object(
      'confirmed', true,
      'confirmation', v_confirmation -> 'subscriptionConfirmation'
    )
  );
END;
$$;


--
-- Name: commerce_write_order_promotion_redemptions(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commerce_write_order_promotion_redemptions(p_order_id uuid, p_redeemed_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_discount jsonb;
  v_promotion_id uuid;
  v_amount integer;
  v_visitor_id text;
  v_written integer := 0;
BEGIN
  SELECT * INTO v_order FROM public.commerce_orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  -- Prefer the finalize-time location; fall back to a top-level key for forward-compat.
  v_visitor_id := NULLIF(
    COALESCE(v_order.metadata #>> '{runtimeFinalize,visitorId}', v_order.metadata #>> '{visitorId}'),
    ''
  );

  FOR v_discount IN
    SELECT value
      FROM jsonb_array_elements(
        COALESCE(v_order.metadata #> '{quoteSnapshot,quote,discounts}', '[]'::jsonb)
      ) AS value
  LOOP
    v_promotion_id := NULLIF(v_discount->>'promotionId', '')::uuid;
    v_amount := COALESCE((v_discount->>'amountOffMinor')::integer, 0);
    IF v_promotion_id IS NULL OR v_amount <= 0 THEN
      CONTINUE;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.promotions WHERE id = v_promotion_id) THEN
      CONTINUE;
    END IF;

    INSERT INTO public.promotion_redemptions (
      promotion_id, client_id, order_id, redeemed_at, amount_off_minor, visitor_id
    )
    VALUES (v_promotion_id, v_order.client_id, p_order_id, p_redeemed_at, v_amount, v_visitor_id)
    ON CONFLICT (promotion_id, order_id) DO NOTHING;
    IF FOUND THEN
      v_written := v_written + 1;
    END IF;
  END LOOP;

  RETURN v_written;
END;
$$;


--
-- Name: communication_admin_email_sends_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_admin_email_sends_stats() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT jsonb_build_object(
    'totalSent', send_stats.total_sent,
    'delivered', send_stats.delivered,
    'opened', event_stats.opened,
    'clicked', event_stats.clicked
  )
  FROM (
    SELECT
      count(*) AS total_sent,
      count(*) FILTER (WHERE status = 'delivered') AS delivered
    FROM public.email_sends
  ) AS send_stats
  CROSS JOIN (
    SELECT
      count(*) FILTER (WHERE event_type = 'open') AS opened,
      count(*) FILTER (WHERE event_type = 'click') AS clicked
    FROM public.email_events
  ) AS event_stats;
$$;


--
-- Name: communication_admin_email_template_slugs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_admin_email_template_slugs() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(distinct_slugs.slug), '[]'::jsonb)
  FROM (
    SELECT DISTINCT template_slug COLLATE "C" AS slug
    FROM public.email_sends
    WHERE template_slug IS NOT NULL
      AND template_slug <> ''
  ) AS distinct_slugs;
$$;


--
-- Name: communication_apply_unsubscribe(text, text[], text, uuid, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_apply_unsubscribe(p_email text, p_purposes text[], p_source_table text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb, p_captured_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_email text := public.communication_normalize_email(p_email);
  v_purposes text[];
  v_purpose text;
  v_contact_id uuid;
  v_existing public.communication_permissions%ROWTYPE;
  v_permission_id uuid;
  v_applied_count integer := 0;
  v_suppressed_count integer := 0;
  v_tester_paused boolean := false;
  v_pause_changed boolean := false;
  v_captured_at timestamptz := COALESCE(p_captured_at, now());
  v_trigger_context text;
BEGIN
  SELECT array_agg(purpose ORDER BY purpose)
    INTO v_purposes
    FROM (
      SELECT DISTINCT btrim(value) AS purpose
        FROM unnest(COALESCE(p_purposes, ARRAY[]::text[])) AS requested(value)
    ) normalized;

  IF v_email = ''
    OR position('@' IN v_email) <= 1
    OR cardinality(COALESCE(v_purposes, ARRAY[]::text[])) = 0
    OR EXISTS (
      SELECT 1
        FROM unnest(COALESCE(p_purposes, ARRAY[]::text[])) AS requested(value)
       WHERE value IS NULL
          OR btrim(value) NOT IN (
            'tester_program',
            'marketing_launch_offer',
            'marketing_newsletter'
          )
    )
    OR ((p_source_table IS NULL) <> (p_source_id IS NULL))
    OR (p_source_table IS NOT NULL AND p_source_table <> 'testers')
    OR jsonb_typeof(COALESCE(p_metadata, '{}'::jsonb)) <> 'object'
  THEN
    RAISE EXCEPTION 'communication_unsubscribe_invalid_input' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('communication.unsubscribe:' || v_email, 0)
  );

  IF p_source_table = 'testers' THEN
    SELECT email_sequence_paused
      INTO v_tester_paused
      FROM public.testers
     WHERE id = p_source_id
       AND public.communication_normalize_email(email) = v_email
     FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'communication_unsubscribe_tester_mismatch' USING ERRCODE = '22023';
    END IF;

    v_pause_changed := 'tester_program' = ANY(v_purposes)
      AND v_tester_paused IS DISTINCT FROM true;
  END IF;

  v_contact_id := public.communication_touch_contact(
    v_email,
    NULL,
    NULL,
    'active',
    jsonb_build_object('source', 'unsubscribe_link')
  );

  IF p_source_table = 'testers' THEN
    PERFORM public.communication_link_contact(
      v_contact_id,
      p_source_table,
      p_source_id,
      NULL,
      COALESCE(p_metadata, '{}'::jsonb)
    );
  END IF;

  -- A historical click is evidence about the past, not authority to replace a
  -- later permission decision. Lock every existing requested permission before
  -- changing the legacy pause flag or appending an event.
  FOREACH v_purpose IN ARRAY v_purposes LOOP
    SELECT *
      INTO v_existing
      FROM public.communication_permissions
     WHERE contact_id = v_contact_id
       AND channel = 'email'
       AND purpose = v_purpose
     FOR UPDATE;

    IF FOUND
      AND v_existing.state <> 'suppressed'
      AND v_existing.captured_at >= v_captured_at
    THEN
      RAISE EXCEPTION 'communication_unsubscribe_superseded' USING ERRCODE = '40001';
    END IF;
  END LOOP;

  IF v_pause_changed THEN
    v_trigger_context := pg_current_xact_id()::text || ':' || p_source_id::text;
    PERFORM pg_catalog.set_config(
      'openlup.communication_apply_unsubscribe_tester',
      v_trigger_context,
      true
    );
    UPDATE public.testers
       SET email_sequence_paused = true
     WHERE id = p_source_id;
    PERFORM pg_catalog.set_config(
      'openlup.communication_apply_unsubscribe_tester',
      '',
      true
    );
    v_tester_paused := true;
  END IF;

  FOREACH v_purpose IN ARRAY v_purposes LOOP
    SELECT *
      INTO v_existing
      FROM public.communication_permissions
     WHERE contact_id = v_contact_id
       AND channel = 'email'
       AND purpose = v_purpose
     FOR UPDATE;

    IF FOUND AND v_existing.state = 'suppressed' THEN
      CONTINUE;
    END IF;

    -- Claim the current-state write before appending its event. The conditional
    -- conflict update closes the no-row race with another permission writer;
    -- a newer or equal decision wins and this statement rolls back every
    -- purpose already touched by the request.
    INSERT INTO public.communication_permissions (
      contact_id,
      purpose,
      state,
      source,
      source_ref,
      reason,
      metadata,
      captured_at
    ) VALUES (
      v_contact_id,
      v_purpose,
      'suppressed',
      'unsubscribe_link',
      jsonb_build_object('table', p_source_table, 'id', p_source_id),
      'user_unsubscribe',
      COALESCE(p_metadata, '{}'::jsonb),
      v_captured_at
    )
    ON CONFLICT (contact_id, channel, purpose) DO UPDATE
      SET state = EXCLUDED.state,
          source = EXCLUDED.source,
          source_ref = EXCLUDED.source_ref,
          reason = EXCLUDED.reason,
          metadata = EXCLUDED.metadata,
          captured_at = EXCLUDED.captured_at,
          updated_at = now()
      WHERE public.communication_permissions.captured_at < EXCLUDED.captured_at
    RETURNING id INTO v_permission_id;

    IF NOT FOUND OR v_permission_id IS NULL THEN
      RAISE EXCEPTION 'communication_unsubscribe_superseded' USING ERRCODE = '40001';
    END IF;

    PERFORM public.communication_record_permission_event(
      v_contact_id,
      v_purpose,
      'suppressed',
      'unsubscribe_link',
      jsonb_build_object('table', p_source_table, 'id', p_source_id),
      'user_unsubscribe',
      COALESCE(p_metadata, '{}'::jsonb),
      v_captured_at,
      v_purpose <> 'tester_program'
    );
    v_applied_count := v_applied_count + 1;
  END LOOP;

  SELECT count(*)
    INTO v_suppressed_count
    FROM public.communication_permissions
   WHERE contact_id = v_contact_id
     AND channel = 'email'
     AND purpose = ANY(v_purposes)
     AND state = 'suppressed';

  IF v_suppressed_count <> cardinality(v_purposes) THEN
    RAISE EXCEPTION 'communication_unsubscribe_persistence_mismatch';
  END IF;

  RETURN jsonb_build_object(
    'status', CASE
      WHEN v_pause_changed OR v_applied_count > 0 THEN 'applied'
      ELSE 'already_suppressed'
    END,
    'durablySuppressed', true,
    'requestedPurposeCount', cardinality(v_purposes),
    'suppressedPurposeCount', v_suppressed_count
  );
END;
$$;


--
-- Name: communication_claim_sync_outbox(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_claim_sync_outbox(p_provider_kind text, p_batch_size integer DEFAULT 25, p_visibility_seconds integer DEFAULT 300, p_max_attempts integer DEFAULT 8) RETURNS TABLE(id uuid, claim_token uuid, contact_id uuid, normalized_email text, event_type text, purpose text, payload jsonb, attempt_count integer, origin_provider_kind text, origin_provider_event_id text, remote_profile_id text, remote_list_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_provider_kind text := btrim(coalesce(p_provider_kind, ''));
BEGIN
  IF v_provider_kind = '' THEN
    RAISE EXCEPTION 'communication_invalid_provider_kind' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH candidate AS (
    SELECT
      outbox.id,
      coalesce(existing_delivery.attempt_count, 0) + 1 AS delivery_attempt_count
      FROM public.communication_sync_outbox outbox
      LEFT JOIN public.communication_sync_deliveries existing_delivery
        ON existing_delivery.outbox_event_id = outbox.id
       AND existing_delivery.provider_kind = v_provider_kind
     WHERE outbox.status IN ('queued', 'failed', 'processing', 'sent')
       AND coalesce(existing_delivery.status, 'queued') IN ('queued', 'failed', 'processing')
       AND coalesce(existing_delivery.next_attempt_at, outbox.next_attempt_at) <= now()
       AND coalesce(existing_delivery.attempt_count, 0) < coalesce(p_max_attempts, 8)
       AND (outbox.origin_provider_kind IS NULL OR outbox.origin_provider_kind <> v_provider_kind)
     ORDER BY outbox.created_at
     LIMIT greatest(1, least(coalesce(p_batch_size, 25), 100))
     FOR UPDATE OF outbox SKIP LOCKED
  ),
  claimed AS (
    UPDATE public.communication_sync_outbox outbox
       SET status = 'processing',
           claim_token = gen_random_uuid(),
           attempt_count = outbox.attempt_count + 1,
           next_attempt_at = now() + make_interval(secs => greatest(coalesce(p_visibility_seconds, 300), 60)),
           updated_at = now()
      FROM candidate
     WHERE outbox.id = candidate.id
     RETURNING outbox.*
  ),
  deliveries AS (
    INSERT INTO public.communication_sync_deliveries (
      outbox_event_id, contact_id, provider_kind, status, claim_token,
      attempt_count, next_attempt_at, metadata
    )
    SELECT
      claimed.id,
      claimed.contact_id,
      v_provider_kind,
      'processing',
      claimed.claim_token,
      candidate.delivery_attempt_count,
      claimed.next_attempt_at,
      jsonb_build_object('outboxClaimedAt', now())
    FROM claimed
    JOIN candidate ON candidate.id = claimed.id
    ON CONFLICT (outbox_event_id, provider_kind) DO UPDATE
      SET status = 'processing',
          claim_token = EXCLUDED.claim_token,
          attempt_count = EXCLUDED.attempt_count,
          next_attempt_at = EXCLUDED.next_attempt_at,
          updated_at = now()
  )
  SELECT
    claimed.id,
    claimed.claim_token,
    claimed.contact_id,
    contacts.normalized_email,
    claimed.event_type,
    claimed.purpose,
    claimed.payload,
    candidate.delivery_attempt_count,
    claimed.origin_provider_kind,
    claimed.origin_provider_event_id,
    profile.remote_profile_id,
    profile.remote_list_id
  FROM claimed
  JOIN candidate ON candidate.id = claimed.id
  JOIN public.communication_contacts contacts ON contacts.id = claimed.contact_id
  LEFT JOIN LATERAL (
    SELECT provider_profile.remote_profile_id, provider_profile.remote_list_id
      FROM public.communication_provider_profiles provider_profile
     WHERE provider_profile.contact_id = claimed.contact_id
       AND provider_profile.provider_kind = v_provider_kind
       AND provider_profile.purpose = claimed.purpose
     ORDER BY provider_profile.updated_at DESC
     LIMIT 1
  ) profile ON true;
END;
$$;


--
-- Name: communication_close_email_deliveries_for_outbox(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_close_email_deliveries_for_outbox(p_event_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_count integer := 0;
BEGIN
  WITH event AS (
    SELECT e.*
      FROM public.outbox_events e
     WHERE e.id = p_event_id
       AND e.status IN ('processed', 'failed', 'discarded')
       AND public.communication_email_delivery_template_for_event(e.event_type) IS NOT NULL
  ),
  derived AS (
    SELECT
      e.id,
      e.status AS outbox_status,
      e.processed_at,
      e.error,
      e.metadata,
      coalesce(
        nullif(btrim(e.metadata->>'resendId'), ''),
        nullif(btrim(e.metadata->>'providerMessageId'), '')
      ) AS provider_message_id,
      CASE
        WHEN coalesce(e.metadata->>'emailSendId', '')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (e.metadata->>'emailSendId')::uuid
        ELSE NULL
      END AS email_send_id,
      CASE
        WHEN coalesce(e.metadata->>'platformJobRunId', '')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (e.metadata->>'platformJobRunId')::uuid
        ELSE NULL
      END AS platform_job_run_id,
      public.communication_email_delivery_cleanup_outbox(e.error, e.metadata) AS cleanup_discard,
      CASE
        WHEN e.status = 'processed'
          AND coalesce(
            nullif(btrim(e.metadata->>'resendId'), ''),
            nullif(btrim(e.metadata->>'providerMessageId'), '')
          ) IS NOT NULL
          THEN 'sent'
        WHEN e.status = 'processed'
          AND coalesce(e.metadata->>'acceptedWithoutProviderId', 'false') = 'true'
          THEN 'delivery_delayed'
        WHEN e.status = 'processed'
          THEN 'skipped'
        WHEN e.status = 'discarded'
          AND public.communication_email_delivery_cleanup_outbox(e.error, e.metadata)
          THEN 'skipped'
        WHEN e.status = 'discarded'
          AND public.communication_email_delivery_suppressed_outbox(e.metadata)
          THEN 'skipped'
        ELSE 'failed'
      END AS delivery_status,
      CASE
        WHEN e.status = 'processed'
          AND coalesce(
            nullif(btrim(e.metadata->>'resendId'), ''),
            nullif(btrim(e.metadata->>'providerMessageId'), '')
          ) IS NOT NULL
          THEN NULL
        WHEN e.status = 'processed'
          AND coalesce(e.metadata->>'acceptedWithoutProviderId', 'false') = 'true'
          THEN 'accepted_without_provider_id_awaiting_delivery_truth'
        WHEN e.status = 'processed'
          THEN coalesce(
            nullif(e.metadata->>'skipped', ''),
            nullif(e.metadata->>'dedupe', ''),
            'processed_without_provider_send'
          )
        WHEN e.status = 'discarded'
          AND public.communication_email_delivery_cleanup_outbox(e.error, e.metadata)
          THEN 'discarded_by_test_cleanup'
        WHEN e.status = 'discarded'
          AND public.communication_email_delivery_suppressed_outbox(e.metadata)
          THEN public.communication_email_delivery_reason_code(
            coalesce(nullif(e.payload->>'suppressedReason', ''), 'customer_email_suppressed'),
            'customer_email_suppressed'
          )
        WHEN e.status = 'discarded'
          THEN coalesce(nullif(e.metadata->>'discardReason', ''), 'outbox_discarded')
        ELSE public.communication_email_delivery_reason_code(e.error, 'outbox_failed')
      END AS reason_code
    FROM event e
  ),
  updated AS (
    UPDATE public.communication_email_deliveries d
       SET status = derived.delivery_status,
           updated_at = now(),
           outbox_event_id = coalesce(d.outbox_event_id, derived.id),
           provider_message_id = coalesce(d.provider_message_id, derived.provider_message_id),
           email_send_id = coalesce(d.email_send_id, derived.email_send_id),
           platform_job_run_id = coalesce(d.platform_job_run_id, derived.platform_job_run_id),
           sent_at = CASE
             WHEN derived.delivery_status = 'sent' THEN coalesce(d.sent_at, derived.processed_at, now())
             ELSE d.sent_at
           END,
           terminal_at = CASE
             WHEN derived.delivery_status IN ('skipped', 'failed') THEN coalesce(d.terminal_at, derived.processed_at, now())
             WHEN derived.delivery_status IN ('sent', 'delivery_delayed') THEN NULL
             ELSE d.terminal_at
           END,
           last_error_code = CASE
             WHEN derived.reason_code IS NOT NULL THEN derived.reason_code
             WHEN derived.delivery_status = 'sent' THEN NULL
             ELSE d.last_error_code
           END,
           metadata = d.metadata
             || jsonb_build_object(
               'outboxLifecycleStatus', derived.outbox_status,
               'outboxLifecycleSyncedAt', now(),
               'outboxLifecycleReason', coalesce(derived.reason_code, derived.delivery_status)
             )
             || CASE
               WHEN derived.cleanup_discard THEN jsonb_build_object('cleanupReason', 'discarded_by_test_cleanup')
               ELSE '{}'::jsonb
             END
      FROM derived
     WHERE (
             d.outbox_event_id = derived.id
             OR d.dedupe_key = 'outbox:' || derived.id::text
           )
       AND d.status NOT IN ('delivered', 'bounced', 'complained')
       AND (
         d.status IS DISTINCT FROM derived.delivery_status
         OR d.outbox_event_id IS NULL
         OR (derived.provider_message_id IS NOT NULL AND d.provider_message_id IS DISTINCT FROM derived.provider_message_id)
         OR (derived.email_send_id IS NOT NULL AND d.email_send_id IS DISTINCT FROM derived.email_send_id)
         OR (derived.platform_job_run_id IS NOT NULL AND d.platform_job_run_id IS DISTINCT FROM derived.platform_job_run_id)
         OR (derived.reason_code IS NOT NULL AND d.last_error_code IS DISTINCT FROM derived.reason_code)
         OR (derived.delivery_status = 'sent' AND d.sent_at IS NULL)
         OR (derived.delivery_status IN ('skipped', 'failed') AND d.terminal_at IS NULL)
         OR (derived.delivery_status IN ('sent', 'delivery_delayed') AND d.terminal_at IS NOT NULL)
         OR (derived.delivery_status = 'sent' AND d.last_error_code IS NOT NULL)
       )
     RETURNING d.id
  )
  SELECT count(*) INTO v_count FROM updated;

  RETURN v_count;
END;
$_$;


--
-- Name: FUNCTION communication_close_email_deliveries_for_outbox(p_event_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.communication_close_email_deliveries_for_outbox(p_event_id uuid) IS 'Closes terminal outbox delivery evidence while preserving provider acceptance without a message id as non-terminal delayed truth.';


--
-- Name: communication_email_deliveries_prune(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_email_deliveries_prune(p_stale_before timestamp with time zone DEFAULT (now() - '7 days'::interval), p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 500), 1), 5000);
  v_stale integer := 0;
  v_orphan integer := 0;
BEGIN
  -- Stale never-sent rows that never progressed to a provider send.
  WITH target AS (
    SELECT id
      FROM public.communication_email_deliveries
     WHERE sent_at IS NULL
       AND status IN ('planned', 'blocked', 'skipped', 'missed')
       AND created_at < p_stale_before
     ORDER BY created_at, id
     LIMIT v_limit
     FOR UPDATE SKIP LOCKED
  ),
  deleted AS (
    DELETE FROM public.communication_email_deliveries d
     USING target t
     WHERE d.id = t.id
     RETURNING 1
  )
  SELECT count(*)::integer INTO v_stale FROM deleted;

  -- Orphan 'planned' rows whose commerce order no longer exists (phantoms).
  WITH target AS (
    SELECT d.id
      FROM public.communication_email_deliveries d
     WHERE d.status = 'planned'
       AND d.sent_at IS NULL
       AND d.aggregate_type = 'commerce_order'
       AND d.aggregate_id ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       AND NOT EXISTS (
         SELECT 1 FROM public.commerce_orders o WHERE o.id = d.aggregate_id::uuid
       )
     ORDER BY d.created_at, d.id
     LIMIT v_limit
     FOR UPDATE SKIP LOCKED
  ),
  deleted AS (
    DELETE FROM public.communication_email_deliveries d
     USING target t
     WHERE d.id = t.id
     RETURNING 1
  )
  SELECT count(*)::integer INTO v_orphan FROM deleted;

  RETURN jsonb_build_object(
    'stale_deleted', v_stale,
    'orphan_deleted', v_orphan,
    'limit', v_limit
  );
END;
$_$;


--
-- Name: communication_email_delivery_cleanup_outbox(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_email_delivery_cleanup_outbox(p_error text, p_metadata jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT (
    lower(coalesce(p_error, '')) ~ '(cleanup|smoke_cleanup|test_cleanup)'
    OR lower(coalesce(p_metadata->>'source', '')) ~ '(cleanup|smoke_cleanup|test_cleanup)'
    OR lower(coalesce(p_metadata->>'boundary', '')) ~ '(cleanup|smoke_cleanup|test_cleanup)'
    OR lower(coalesce(p_metadata->>'cleanupActor', '')) <> ''
  );
$$;


--
-- Name: communication_email_delivery_purpose_for_event(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_email_delivery_purpose_for_event(p_event_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE
    WHEN p_event_type = 'tester.feedback.reward_confirmation'
      THEN 'tester_program'
    WHEN p_event_type IN (
      'commerce.order.review_request',
      'commerce.order.review_effects',
      'commerce.product.back_in_stock',
      'commerce.order_draft.abandoned.1h',
      'commerce.order_draft.abandoned.24h',
      'commerce.order_draft.abandoned.72h',
      'commerce.order.reorder_reminder'
    ) THEN 'marketing_newsletter'
    ELSE 'transactional'
  END;
$$;


--
-- Name: communication_email_delivery_reason_code(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_email_delivery_reason_code(p_value text, p_fallback text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
  SELECT coalesce(
    nullif(
      left(
        regexp_replace(
          regexp_replace(lower(coalesce(p_value, '')), '[^a-z0-9]+', '_', 'g'),
          '^_+|_+$',
          '',
          'g'
        ),
        80
      ),
      ''
    ),
    p_fallback
  );
$_$;


--
-- Name: communication_email_delivery_suppressed_outbox(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_email_delivery_suppressed_outbox(p_metadata jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT coalesce(p_metadata->>'suppressedCustomerEmail', '') = 'true';
$$;


--
-- Name: communication_email_delivery_template_for_event(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_email_delivery_template_for_event(p_event_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE p_event_type
    WHEN 'commerce.order_draft.created' THEN 'commerce-order-confirmation'
    WHEN 'commerce.order.paid.email' THEN 'commerce-order-paid'
    WHEN 'commerce.payment.failed' THEN 'commerce-payment-failed'
    WHEN 'commerce.checkout.expired' THEN 'commerce-checkout-expired'
    WHEN 'commerce.order.canceled' THEN 'commerce-order-canceled'
    WHEN 'commerce.order.refunded' THEN 'commerce-order-refunded'
    WHEN 'commerce.shipment.dispatched' THEN 'commerce-shipment-dispatched'
    WHEN 'commerce.shipment.delivered' THEN 'commerce-shipment-delivered'
    WHEN 'commerce.shipment.exception' THEN 'commerce-shipment-exception'
    WHEN 'commerce.checkout_recovery' THEN 'commerce-checkout-recovery'
    WHEN 'commerce.order.review_request' THEN 'commerce-order-review-request'
    WHEN 'commerce.order.review_effects' THEN 'commerce-order-review-effects'
    WHEN 'commerce.product.back_in_stock' THEN 'commerce-back-in-stock'
    WHEN 'commerce.order_draft.abandoned.1h' THEN 'commerce-abandoned-cart-1h'
    WHEN 'commerce.order_draft.abandoned.24h' THEN 'commerce-abandoned-cart-24h'
    WHEN 'commerce.order_draft.abandoned.72h' THEN 'commerce-abandoned-cart-72h'
    WHEN 'commerce.order.reorder_reminder' THEN 'commerce-reorder-reminder'
    WHEN 'subscription.cancelled' THEN 'subscription-cancelled'
    WHEN 'subscription.created' THEN 'subscription-welcome'
    WHEN 'subscription.pause_reminder_due' THEN 'subscription-pause-reminder'
    WHEN 'subscription.paused' THEN 'subscription-paused'
    WHEN 'subscription.resumed' THEN 'subscription-resumed'
    WHEN 'subscription.delivery_rescheduled' THEN 'subscription-delivery-rescheduled'
    WHEN 'subscription.cycle_skipped' THEN 'subscription-cycle-skipped'
    WHEN 'subscription.address_changed' THEN 'subscription-address-changed'
    WHEN 'subscription.package_changed' THEN 'subscription-package-changed'
    WHEN 'subscription.renewal_upcoming' THEN 'subscription-renewal-upcoming'
    WHEN 'tester.feedback.reward_confirmation' THEN 'reward-confirmation'
    ELSE NULL
  END;
$$;


--
-- Name: communication_evaluate_email_policy(text, text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_evaluate_email_policy(p_email text, p_purpose text, p_source text, p_recipient_kind text DEFAULT 'external_contact'::text, p_source_table text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email text := public.communication_normalize_email(p_email);
  v_contact_id uuid;
  v_permission public.communication_permissions%ROWTYPE;
  v_decision text := 'allowed';
  v_reason text := 'allowed';
  v_snapshot jsonb := '{}'::jsonb;
  v_decision_id uuid;
  v_legacy_sequence_paused boolean := coalesce((p_metadata->>'legacySequencePaused')::boolean, false);
  v_admin_recipient_active boolean;
  -- Frequency-cap tunables (industry defaults; tune via a follow-up migration).
  -- The 16h min-gap is the primary anti-spam guard; the per-day cap is a backstop
  -- kept at 2 so a legitimate multi-touch flow (e.g. abandoned-cart 1h then 24h,
  -- ~23h apart) is not throttled to a single touch. Combined with the 16h gap this
  -- still bounds a recipient to ~1-2 spaced marketing emails/day, 4/week.
  v_cap_max_per_day constant integer := 2;
  v_cap_max_per_week constant integer := 4;
  v_cap_min_gap constant interval := interval '16 hours';
  v_count_day integer;
  v_count_week integer;
  v_last_send timestamptz;
BEGIN
  IF v_email = '' OR p_purpose NOT IN ('transactional', 'tester_program', 'marketing_launch_offer', 'marketing_newsletter', 'subscription_dunning', 'admin_notification') THEN
    v_decision := 'blocked';
    v_reason := 'invalid_request';
  ELSE
    v_contact_id := public.communication_touch_contact(v_email, NULL, NULL, 'active', jsonb_build_object('policySource', p_source));

    IF p_source_table IS NOT NULL AND p_source_id IS NOT NULL THEN
      PERFORM public.communication_link_contact(v_contact_id, p_source_table, p_source_id, NULL, coalesce(p_metadata, '{}'::jsonb));
    END IF;

    SELECT * INTO v_permission
      FROM public.communication_permissions
     WHERE contact_id = v_contact_id
       AND channel = 'email'
       AND purpose = p_purpose;

    v_snapshot := jsonb_build_object(
      'permissionState', coalesce(v_permission.state, 'unknown'),
      'permissionSource', v_permission.source,
      'permissionCapturedAt', v_permission.captured_at,
      'legacySequencePaused', v_legacy_sequence_paused
    );

    IF p_purpose IN ('marketing_launch_offer', 'marketing_newsletter') THEN
      IF v_permission.state IS DISTINCT FROM 'granted' THEN
        v_decision := 'blocked';
        v_reason := 'missing_marketing_permission';
      END IF;
    ELSIF p_purpose = 'tester_program' THEN
      IF v_legacy_sequence_paused THEN
        v_decision := 'blocked';
        v_reason := 'sequence_paused';
      ELSIF v_permission.state = 'suppressed' THEN
        v_decision := 'blocked';
        v_reason := 'permission_suppressed';
      ELSIF v_permission.state = 'denied' THEN
        v_decision := 'blocked';
        v_reason := 'permission_denied';
      ELSIF v_permission.state IS DISTINCT FROM 'granted' THEN
        v_decision := 'blocked';
        v_reason := 'missing_tester_program_permission';
      END IF;
    ELSIF p_purpose = 'admin_notification'
      AND p_source_table = 'notification_recipients'
      AND p_source_id IS NOT NULL THEN
      SELECT active INTO v_admin_recipient_active
        FROM public.notification_recipients
       WHERE id = p_source_id;
      IF v_admin_recipient_active IS DISTINCT FROM true THEN
        v_decision := 'blocked';
        v_reason := 'admin_recipient_inactive';
      END IF;
    END IF;

    -- Frequency cap (marketing only): count real deliveries to this contact across
    -- ALL marketing flows. Applied only when consent already passed, so a capped
    -- send surfaces as decision=blocked reason=frequency_cap_* and the handler acks
    -- (drops) it without retry. Never applies to transactional/tester/dunning/admin.
    IF v_decision = 'allowed'
       AND p_purpose IN ('marketing_launch_offer', 'marketing_newsletter')
       AND v_contact_id IS NOT NULL THEN
      SELECT
        count(*) FILTER (WHERE d.sent_at >= now() - interval '24 hours'),
        count(*) FILTER (WHERE d.sent_at >= now() - interval '7 days'),
        max(d.sent_at)
        INTO v_count_day, v_count_week, v_last_send
      FROM public.communication_email_deliveries d
      WHERE d.contact_id = v_contact_id
        AND d.purpose IN ('marketing_launch_offer', 'marketing_newsletter')
        AND d.status IN ('sent', 'delivered')
        AND d.sent_at IS NOT NULL;

      IF v_last_send IS NOT NULL AND v_last_send > now() - v_cap_min_gap THEN
        v_decision := 'blocked';
        v_reason := 'frequency_cap_min_gap';
      ELSIF coalesce(v_count_day, 0) >= v_cap_max_per_day THEN
        v_decision := 'blocked';
        v_reason := 'frequency_cap_day';
      ELSIF coalesce(v_count_week, 0) >= v_cap_max_per_week THEN
        v_decision := 'blocked';
        v_reason := 'frequency_cap_week';
      END IF;

      v_snapshot := v_snapshot || jsonb_build_object(
        'marketingSentLast24h', coalesce(v_count_day, 0),
        'marketingSentLast7d', coalesce(v_count_week, 0),
        'marketingLastSendAt', v_last_send
      );
    END IF;
  END IF;

  INSERT INTO public.communication_send_decisions (
    contact_id, normalized_email, purpose, decision, reason, source, recipient_kind,
    source_ref, permission_snapshot, metadata
  )
  VALUES (
    v_contact_id, nullif(v_email, ''), p_purpose, v_decision, v_reason, coalesce(nullif(btrim(p_source), ''), 'unknown'),
    coalesce(nullif(btrim(p_recipient_kind), ''), 'external_contact'),
    jsonb_build_object('sourceTable', p_source_table, 'sourceId', p_source_id),
    v_snapshot,
    coalesce(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_decision_id;

  RETURN jsonb_build_object(
    'allowed', v_decision = 'allowed',
    'decisionId', v_decision_id,
    'contactId', v_contact_id,
    'reason', v_reason,
    'snapshot', v_snapshot
  );
END;
$$;


--
-- Name: communication_link_contact(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_link_contact(p_contact_id uuid, p_source_table text, p_source_id uuid DEFAULT NULL::uuid, p_source_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_link_id uuid;
BEGIN
  IF p_contact_id IS NULL
    OR p_source_table NOT IN ('testers', 'waitlist', 'clients', 'client_consents', 'b2b_inquiries', 'notification_recipients')
    OR (p_source_id IS NULL AND btrim(coalesce(p_source_key, '')) = '') THEN
    RAISE EXCEPTION 'communication_invalid_contact_link' USING ERRCODE = '22023';
  END IF;

  IF p_source_id IS NOT NULL THEN
    INSERT INTO public.communication_contact_links (
      contact_id, source_table, source_id, source_key, metadata
    )
    VALUES (
      p_contact_id, p_source_table, p_source_id, nullif(btrim(coalesce(p_source_key, '')), ''),
      coalesce(p_metadata, '{}'::jsonb)
    )
    ON CONFLICT (source_system, source_table, source_id) WHERE source_id IS NOT NULL DO UPDATE
      SET contact_id = EXCLUDED.contact_id,
          metadata = public.communication_contact_links.metadata || EXCLUDED.metadata
    RETURNING id INTO v_link_id;
  ELSE
    INSERT INTO public.communication_contact_links (
      contact_id, source_table, source_id, source_key, metadata
    )
    VALUES (
      p_contact_id, p_source_table, NULL, nullif(btrim(coalesce(p_source_key, '')), ''),
      coalesce(p_metadata, '{}'::jsonb)
    )
    ON CONFLICT (source_system, source_table, source_key) WHERE source_id IS NULL AND source_key IS NOT NULL DO UPDATE
      SET contact_id = EXCLUDED.contact_id,
          metadata = public.communication_contact_links.metadata || EXCLUDED.metadata
    RETURNING id INTO v_link_id;
  END IF;

  RETURN v_link_id;
END;
$$;


--
-- Name: communication_link_send_decision(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_link_send_decision(p_decision_id uuid, p_email_send_id uuid, p_provider_message_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_decision_id IS NULL THEN
    RETURN;
  END IF;

  UPDATE public.communication_send_decisions
     SET email_send_id = p_email_send_id,
         provider_message_id = p_provider_message_id
   WHERE id = p_decision_id;
END;
$$;


--
-- Name: communication_mark_overdue_email_deliveries(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_mark_overdue_email_deliveries(p_now timestamp with time zone DEFAULT now(), p_grace_minutes integer DEFAULT 15) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_count integer;
  v_grace interval := make_interval(mins => LEAST(GREATEST(COALESCE(p_grace_minutes, 15), 1), 1440));
BEGIN
  UPDATE public.communication_email_deliveries
     SET status = 'missed',
         terminal_at = coalesce(terminal_at, p_now),
         updated_at = now(),
         last_error_code = coalesce(last_error_code, 'overdue_unrecoverable_no_recipient'),
         metadata = metadata || jsonb_build_object(
           'missedAt', p_now,
           'missedReason', 'unrecoverable_no_durable_recipient'
         )
   WHERE status IN ('planned', 'queued', 'processing')
     AND expected_send_at IS NOT NULL
     AND expected_send_at < p_now - v_grace
     -- Safety invariant: never silently drop a row that can still be addressed.
     -- Only genuinely unrecoverable rows (no contact and no client) are terminal.
     AND contact_id IS NULL
     AND client_id IS NULL;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: communication_mark_provider_event_processed(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_mark_provider_event_processed(p_provider_event_id uuid, p_processing_status text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_provider_event_id IS NULL
    OR p_processing_status NOT IN ('processed', 'ignored', 'failed') THEN
    RAISE EXCEPTION 'communication_invalid_provider_event_status' USING ERRCODE = '22023';
  END IF;

  UPDATE public.communication_provider_events
     SET processing_status = p_processing_status,
         processed_at = now(),
         metadata = metadata || coalesce(p_metadata, '{}'::jsonb)
   WHERE id = p_provider_event_id;

  RETURN FOUND;
END;
$$;


--
-- Name: communication_mark_sync_outbox_failed(uuid, uuid, text, text, boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_mark_sync_outbox_failed(p_outbox_id uuid, p_claim_token uuid, p_provider_kind text, p_error text, p_retry boolean DEFAULT true, p_backoff_seconds integer DEFAULT 300) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_provider_kind text := btrim(coalesce(p_provider_kind, ''));
  v_status text := CASE WHEN p_retry THEN 'queued' ELSE 'failed' END;
  v_next_attempt timestamptz := CASE
    WHEN p_retry THEN now() + make_interval(secs => greatest(coalesce(p_backoff_seconds, 300), 60))
    ELSE now()
  END;
BEGIN
  IF p_outbox_id IS NULL OR p_claim_token IS NULL OR v_provider_kind = '' THEN
    RAISE EXCEPTION 'communication_invalid_sync_mark_failed' USING ERRCODE = '22023';
  END IF;

  UPDATE public.communication_sync_outbox
     SET status = v_status,
         next_attempt_at = v_next_attempt,
         last_error = left(coalesce(p_error, 'communication_sync_failed'), 1000),
         updated_at = now()
   WHERE id = p_outbox_id
     AND claim_token = p_claim_token;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  UPDATE public.communication_sync_deliveries
     SET status = CASE WHEN p_retry THEN 'queued' ELSE 'failed' END,
         next_attempt_at = v_next_attempt,
         last_error = left(coalesce(p_error, 'communication_sync_failed'), 1000),
         updated_at = now()
   WHERE outbox_event_id = p_outbox_id
     AND provider_kind = v_provider_kind
     AND claim_token = p_claim_token;

  RETURN true;
END;
$$;


--
-- Name: communication_mark_sync_outbox_sent(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_mark_sync_outbox_sent(p_outbox_id uuid, p_claim_token uuid, p_provider_kind text, p_remote_profile_id text DEFAULT NULL::text, p_response_summary jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_provider_kind text := btrim(coalesce(p_provider_kind, ''));
BEGIN
  IF p_outbox_id IS NULL OR p_claim_token IS NULL OR v_provider_kind = '' THEN
    RAISE EXCEPTION 'communication_invalid_sync_mark_sent' USING ERRCODE = '22023';
  END IF;

  UPDATE public.communication_sync_outbox
     SET status = 'sent',
         processed_at = now(),
         updated_at = now()
   WHERE id = p_outbox_id
     AND claim_token = p_claim_token;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  UPDATE public.communication_sync_deliveries
     SET status = 'sent',
         remote_profile_id = nullif(btrim(coalesce(p_remote_profile_id, '')), ''),
         response_summary = coalesce(p_response_summary, '{}'::jsonb),
         updated_at = now()
   WHERE outbox_event_id = p_outbox_id
     AND provider_kind = v_provider_kind
     AND claim_token = p_claim_token;

  RETURN true;
END;
$$;


--
-- Name: communication_marketing_available_at(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_marketing_available_at(p_now timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_tz constant text := 'Europe/Warsaw';
  v_start_hour constant integer := 9;   -- window opens 09:00 local (inclusive)
  v_end_hour constant integer := 20;    -- window closes 20:00 local (exclusive)
  v_local timestamp := p_now AT TIME ZONE v_tz;
  v_hour integer := extract(hour from v_local)::integer;
  v_target_local timestamp;
BEGIN
  IF v_hour >= v_start_hour AND v_hour < v_end_hour THEN
    RETURN p_now;
  END IF;
  IF v_hour < v_start_hour THEN
    v_target_local := date_trunc('day', v_local) + make_interval(hours => v_start_hour);
  ELSE
    v_target_local := date_trunc('day', v_local) + interval '1 day' + make_interval(hours => v_start_hour);
  END IF;
  RETURN v_target_local AT TIME ZONE v_tz;
END;
$$;


--
-- Name: communication_normalize_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_normalize_email(p_email text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT lower(btrim(coalesce(p_email, '')));
$$;


--
-- Name: communication_plan_email_delivery_from_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_plan_email_delivery_from_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_template text;
  v_purpose text;
  v_client_id uuid;
  v_payload_client_id text;
  v_contact_id uuid;
BEGIN
  v_template := public.communication_email_delivery_template_for_event(NEW.event_type);
  IF v_template IS NULL THEN
    RETURN NEW;
  END IF;

  v_purpose := public.communication_email_delivery_purpose_for_event(NEW.event_type);

  IF NEW.aggregate_type = 'commerce_order' THEN
    SELECT client_id INTO v_client_id
      FROM public.commerce_orders
     WHERE id = NEW.aggregate_id;
  ELSIF NEW.payload ? 'clientId' THEN
    v_payload_client_id := NULLIF(NEW.payload->>'clientId', '');
    IF v_payload_client_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
      v_client_id := v_payload_client_id::uuid;
    END IF;
  END IF;

  -- Durable, RODO-safe attribution: resolve the consented contact for this client
  -- (no recipient email read). NULL when the client has no contact link yet — the
  -- row stays unattributable exactly as before, never worse.
  IF v_client_id IS NOT NULL THEN
    SELECT contact_id INTO v_contact_id
      FROM public.communication_contact_links
     WHERE source_table = 'clients'
       AND source_id = v_client_id
     ORDER BY created_at DESC
     LIMIT 1;
  END IF;

  PERFORM public.communication_record_email_delivery(
    'outbox:' || NEW.id::text,
    v_template,
    v_purpose,
    coalesce(NULLIF(NEW.metadata->>'source', ''), 'outbox_events'),
    NEW.event_type,
    'planned',
    NULL,
    v_contact_id,
    v_client_id,
    NULL,
    NEW.aggregate_type,
    NEW.aggregate_id::text,
    NEW.id,
    NULL,
    NEW.available_at,
    NEW.available_at + interval '10 minutes',
    NULL,
    NULL,
    'resend',
    NULL,
    NULL,
    jsonb_build_object(
      'outboxEventType', NEW.event_type,
      'outboxIdempotencyKey', NEW.idempotency_key
    )
  );

  RETURN NEW;
END;
$_$;


--
-- Name: communication_record_email_delivery(text, text, text, text, text, text, text, uuid, uuid, uuid, text, text, uuid, uuid, timestamp with time zone, timestamp with time zone, uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_record_email_delivery(p_dedupe_key text, p_template_slug text, p_purpose text, p_trigger_source text, p_trigger_event text, p_status text DEFAULT 'planned'::text, p_recipient_email text DEFAULT NULL::text, p_contact_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_auth_user_id uuid DEFAULT NULL::uuid, p_aggregate_type text DEFAULT NULL::text, p_aggregate_id text DEFAULT NULL::text, p_outbox_event_id uuid DEFAULT NULL::uuid, p_platform_job_run_id uuid DEFAULT NULL::uuid, p_scheduled_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_expected_send_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_decision_id uuid DEFAULT NULL::uuid, p_email_send_id uuid DEFAULT NULL::uuid, p_provider_kind text DEFAULT 'resend'::text, p_provider_message_id text DEFAULT NULL::text, p_last_error_code text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_dedupe_key text := btrim(coalesce(p_dedupe_key, ''));
  v_email text := public.communication_normalize_email(p_recipient_email);
  v_contact_id uuid := p_contact_id;
  v_now timestamptz := now();
  v_delivery_id uuid;
  v_recipient_fingerprint text;
  v_outbox_event_id uuid;
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
BEGIN
  IF v_dedupe_key = ''
    OR btrim(coalesce(p_template_slug, '')) = ''
    OR btrim(coalesce(p_trigger_source, '')) = ''
    OR btrim(coalesce(p_trigger_event, '')) = ''
    OR p_status NOT IN (
      'planned', 'queued', 'blocked', 'skipped', 'processing', 'sent', 'delivered',
      'delivery_delayed', 'bounced', 'complained', 'failed', 'missed', 'legacy_unlinked'
    )
    OR p_purpose NOT IN (
      'transactional', 'tester_program', 'marketing_launch_offer',
      'marketing_newsletter', 'subscription_dunning', 'admin_notification'
    )
  THEN
    RAISE EXCEPTION 'communication_email_delivery_invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_outbox_event_id IS NOT NULL THEN
    SELECT id INTO v_outbox_event_id
    FROM public.outbox_events
    WHERE id = p_outbox_event_id;

    IF v_outbox_event_id IS NULL THEN
      v_metadata := v_metadata || jsonb_build_object('outboxEventIdText', p_outbox_event_id::text);
    END IF;
  END IF;

  IF v_contact_id IS NULL AND v_email <> '' AND position('@' in v_email) > 1 THEN
    v_contact_id := public.communication_touch_contact(
      v_email,
      NULL,
      NULL,
      'active',
      jsonb_build_object('source', 'communication_email_delivery')
    );
  END IF;

  IF v_contact_id IS NOT NULL AND p_client_id IS NOT NULL THEN
    PERFORM public.communication_link_contact(
      v_contact_id,
      'clients',
      p_client_id,
      NULL,
      jsonb_build_object('source', 'communication_email_delivery')
    );
  END IF;

  IF v_email <> '' AND position('@' in v_email) > 1 THEN
    v_recipient_fingerprint := encode(sha256(convert_to(v_email, 'UTF8')), 'hex');
  END IF;

  INSERT INTO public.communication_email_deliveries (
    contact_id, client_id, auth_user_id, recipient_fingerprint, purpose,
    template_slug, trigger_source, trigger_event, aggregate_type, aggregate_id,
    dedupe_key, status, triggered_at, scheduled_due_at, expected_send_at,
    queued_at, first_attempt_at, last_attempt_at, sent_at, delivered_at,
    terminal_at, communication_send_decision_id, outbox_event_id,
    platform_job_run_id, email_send_id, provider_kind, provider_message_id,
    attempt_count, last_error_code, metadata
  )
  VALUES (
    v_contact_id, p_client_id, p_auth_user_id, v_recipient_fingerprint, p_purpose,
    btrim(p_template_slug), btrim(p_trigger_source), btrim(p_trigger_event),
    nullif(btrim(coalesce(p_aggregate_type, '')), ''),
    nullif(btrim(coalesce(p_aggregate_id, '')), ''),
    v_dedupe_key, p_status, v_now, p_scheduled_due_at, p_expected_send_at,
    CASE WHEN p_status IN ('queued', 'processing', 'sent', 'failed', 'delivery_delayed') THEN v_now ELSE NULL END,
    CASE WHEN p_status IN ('processing', 'sent', 'failed', 'delivery_delayed') THEN v_now ELSE NULL END,
    CASE WHEN p_status IN ('processing', 'sent', 'failed', 'delivery_delayed') THEN v_now ELSE NULL END,
    CASE WHEN p_status = 'sent' THEN v_now ELSE NULL END,
    CASE WHEN p_status = 'delivered' THEN v_now ELSE NULL END,
    CASE WHEN p_status IN ('blocked', 'skipped', 'delivered', 'bounced', 'complained', 'failed', 'missed') THEN v_now ELSE NULL END,
    p_decision_id, v_outbox_event_id, p_platform_job_run_id, p_email_send_id,
    nullif(btrim(coalesce(p_provider_kind, '')), ''),
    nullif(btrim(coalesce(p_provider_message_id, '')), ''),
    CASE WHEN p_status IN ('processing', 'sent', 'failed', 'delivery_delayed') THEN 1 ELSE 0 END,
    nullif(btrim(coalesce(p_last_error_code, '')), ''),
    v_metadata
  )
  ON CONFLICT (dedupe_key) DO UPDATE
    SET updated_at = now(),
        contact_id = coalesce(EXCLUDED.contact_id, public.communication_email_deliveries.contact_id),
        client_id = coalesce(EXCLUDED.client_id, public.communication_email_deliveries.client_id),
        auth_user_id = coalesce(EXCLUDED.auth_user_id, public.communication_email_deliveries.auth_user_id),
        recipient_fingerprint = coalesce(EXCLUDED.recipient_fingerprint, public.communication_email_deliveries.recipient_fingerprint),
        purpose = EXCLUDED.purpose,
        template_slug = EXCLUDED.template_slug,
        trigger_source = public.communication_email_deliveries.trigger_source,
        trigger_event = public.communication_email_deliveries.trigger_event,
        aggregate_type = coalesce(EXCLUDED.aggregate_type, public.communication_email_deliveries.aggregate_type),
        aggregate_id = coalesce(EXCLUDED.aggregate_id, public.communication_email_deliveries.aggregate_id),
        status = EXCLUDED.status,
        scheduled_due_at = coalesce(EXCLUDED.scheduled_due_at, public.communication_email_deliveries.scheduled_due_at),
        expected_send_at = coalesce(EXCLUDED.expected_send_at, public.communication_email_deliveries.expected_send_at),
        queued_at = coalesce(public.communication_email_deliveries.queued_at, EXCLUDED.queued_at),
        first_attempt_at = coalesce(public.communication_email_deliveries.first_attempt_at, EXCLUDED.first_attempt_at),
        last_attempt_at = coalesce(EXCLUDED.last_attempt_at, public.communication_email_deliveries.last_attempt_at),
        sent_at = coalesce(public.communication_email_deliveries.sent_at, EXCLUDED.sent_at),
        delivered_at = coalesce(EXCLUDED.delivered_at, public.communication_email_deliveries.delivered_at),
        terminal_at = coalesce(EXCLUDED.terminal_at, public.communication_email_deliveries.terminal_at),
        communication_send_decision_id = coalesce(EXCLUDED.communication_send_decision_id, public.communication_email_deliveries.communication_send_decision_id),
        outbox_event_id = coalesce(EXCLUDED.outbox_event_id, public.communication_email_deliveries.outbox_event_id),
        platform_job_run_id = coalesce(EXCLUDED.platform_job_run_id, public.communication_email_deliveries.platform_job_run_id),
        email_send_id = coalesce(EXCLUDED.email_send_id, public.communication_email_deliveries.email_send_id),
        provider_kind = coalesce(EXCLUDED.provider_kind, public.communication_email_deliveries.provider_kind),
        provider_message_id = coalesce(EXCLUDED.provider_message_id, public.communication_email_deliveries.provider_message_id),
        attempt_count = public.communication_email_deliveries.attempt_count +
          CASE
            WHEN EXCLUDED.status NOT IN ('processing', 'sent', 'failed', 'delivery_delayed') THEN 0
            WHEN public.communication_email_deliveries.status = EXCLUDED.status THEN 0
            WHEN public.communication_email_deliveries.status = 'processing'
              AND EXCLUDED.status IN ('sent', 'failed', 'delivery_delayed') THEN 0
            ELSE 1
          END,
        last_error_code = coalesce(EXCLUDED.last_error_code, public.communication_email_deliveries.last_error_code),
        metadata = public.communication_email_deliveries.metadata || EXCLUDED.metadata
  RETURNING id INTO v_delivery_id;

  RETURN v_delivery_id;
END;
$$;


--
-- Name: FUNCTION communication_record_email_delivery(p_dedupe_key text, p_template_slug text, p_purpose text, p_trigger_source text, p_trigger_event text, p_status text, p_recipient_email text, p_contact_id uuid, p_client_id uuid, p_auth_user_id uuid, p_aggregate_type text, p_aggregate_id text, p_outbox_event_id uuid, p_platform_job_run_id uuid, p_scheduled_due_at timestamp with time zone, p_expected_send_at timestamp with time zone, p_decision_id uuid, p_email_send_id uuid, p_provider_kind text, p_provider_message_id text, p_last_error_code text, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.communication_record_email_delivery(p_dedupe_key text, p_template_slug text, p_purpose text, p_trigger_source text, p_trigger_event text, p_status text, p_recipient_email text, p_contact_id uuid, p_client_id uuid, p_auth_user_id uuid, p_aggregate_type text, p_aggregate_id text, p_outbox_event_id uuid, p_platform_job_run_id uuid, p_scheduled_due_at timestamp with time zone, p_expected_send_at timestamp with time zone, p_decision_id uuid, p_email_send_id uuid, p_provider_kind text, p_provider_message_id text, p_last_error_code text, p_metadata jsonb) IS 'Upserts one customer-facing email delivery timeline row by dedupe key and returns the durable sendAttemptId; outbox_event_id is an optional evidence link and orphan references are preserved as metadata text.';


--
-- Name: communication_record_email_poll_not_found(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_record_email_poll_not_found(p_send_id uuid, p_threshold integer DEFAULT 3) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_was_abandoned boolean;
  v_now_abandoned boolean;
BEGIN
  SELECT poll_abandoned_at IS NOT NULL
    INTO v_was_abandoned
    FROM public.email_sends
   WHERE id = p_send_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  UPDATE public.email_sends
     SET poll_last_attempt_at = now(),
         poll_not_found_count = coalesce(poll_not_found_count, 0) + 1,
         poll_abandoned_at = CASE
           WHEN poll_abandoned_at IS NULL
                AND coalesce(poll_not_found_count, 0) + 1 >= greatest(p_threshold, 1)
             THEN now()
           ELSE poll_abandoned_at
         END
   WHERE id = p_send_id
   RETURNING poll_abandoned_at IS NOT NULL
    INTO v_now_abandoned;

  RETURN v_now_abandoned AND NOT coalesce(v_was_abandoned, false);
END;
$$;


--
-- Name: communication_record_permission_event(uuid, text, text, text, jsonb, text, jsonb, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_record_permission_event(p_contact_id uuid, p_purpose text, p_state text, p_source text, p_source_ref jsonb DEFAULT '{}'::jsonb, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_captured_at timestamp with time zone DEFAULT now(), p_create_sync_event boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing public.communication_permissions%ROWTYPE;
  v_event_id uuid;
  v_outbox_event text;
  v_is_legacy_backfill boolean;
  v_should_update_current boolean;
  v_origin_provider_kind text := nullif(btrim(coalesce(
    p_metadata->>'originProviderKind',
    p_source_ref->>'providerKind',
    ''
  )), '');
  v_origin_provider_event_id text := nullif(btrim(coalesce(
    p_metadata->>'originProviderEventId',
    p_source_ref->>'providerEventId',
    ''
  )), '');
BEGIN
  IF p_contact_id IS NULL
    OR p_purpose NOT IN ('transactional', 'tester_program', 'marketing_launch_offer', 'marketing_newsletter', 'subscription_dunning', 'admin_notification')
    OR p_state NOT IN ('unknown', 'granted', 'denied', 'suppressed')
    OR btrim(coalesce(p_source, '')) = '' THEN
    RAISE EXCEPTION 'communication_invalid_permission_event' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.communication_permission_events (
    contact_id, purpose, state, source, source_ref, reason, metadata, captured_at
  )
  VALUES (
    p_contact_id, p_purpose, p_state, btrim(p_source), coalesce(p_source_ref, '{}'::jsonb),
    p_reason, coalesce(p_metadata, '{}'::jsonb), coalesce(p_captured_at, now())
  )
  RETURNING id INTO v_event_id;

  SELECT * INTO v_existing
    FROM public.communication_permissions
   WHERE contact_id = p_contact_id
     AND channel = 'email'
     AND purpose = p_purpose
   FOR UPDATE;

  v_is_legacy_backfill := p_source IN (
    'legacy_testers_backfill',
    'legacy_waitlist_inferred',
    'legacy_client_consents_backfill'
  );

  v_should_update_current := NOT FOUND
    OR NOT v_is_legacy_backfill
    OR public.communication_state_rank(p_state) >= public.communication_state_rank(v_existing.state);

  IF v_should_update_current THEN
    INSERT INTO public.communication_permissions (
      contact_id, purpose, state, source, source_ref, reason, metadata, captured_at
    )
    VALUES (
      p_contact_id, p_purpose, p_state, btrim(p_source), coalesce(p_source_ref, '{}'::jsonb),
      p_reason, coalesce(p_metadata, '{}'::jsonb), coalesce(p_captured_at, now())
    )
    ON CONFLICT (contact_id, channel, purpose) DO UPDATE
      SET state = EXCLUDED.state,
          source = EXCLUDED.source,
          source_ref = EXCLUDED.source_ref,
          reason = EXCLUDED.reason,
          metadata = EXCLUDED.metadata,
          captured_at = EXCLUDED.captured_at,
          updated_at = now();
  END IF;

  IF p_create_sync_event
    AND p_purpose IN ('marketing_launch_offer', 'marketing_newsletter')
    AND p_state IN ('granted', 'denied', 'suppressed') THEN
    v_outbox_event := CASE
      WHEN p_state = 'granted' THEN 'subscribe'
      WHEN p_state = 'suppressed' THEN 'suppress'
      ELSE 'unsubscribe'
    END;

    INSERT INTO public.communication_sync_outbox (
      contact_id, event_type, purpose, payload, origin_provider_kind, origin_provider_event_id
    )
    VALUES (
      p_contact_id, v_outbox_event, p_purpose,
      jsonb_build_object(
        'permissionEventId', v_event_id,
        'state', p_state,
        'source', p_source,
        'sourceRef', coalesce(p_source_ref, '{}'::jsonb)
      ),
      v_origin_provider_kind,
      v_origin_provider_event_id
    );
  END IF;

  RETURN jsonb_build_object('permissionEventId', v_event_id, 'contactId', p_contact_id);
END;
$$;


--
-- Name: communication_record_provider_event(text, text, text, text, text, text, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_record_provider_event(p_provider_kind text, p_provider_event_id text, p_event_type text, p_email text DEFAULT NULL::text, p_remote_profile_id text DEFAULT NULL::text, p_purpose text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb, p_processing_status text DEFAULT 'received'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email text := nullif(public.communication_normalize_email(p_email), '');
  v_contact_id uuid;
  v_event_id uuid;
  v_inserted boolean := false;
BEGIN
  IF btrim(coalesce(p_provider_kind, '')) = ''
    OR btrim(coalesce(p_provider_event_id, '')) = ''
    OR p_event_type NOT IN ('subscribe', 'unsubscribe', 'suppress', 'complaint', 'bounce', 'email_change', 'profile_update', 'ignored')
    OR (p_purpose IS NOT NULL AND p_purpose NOT IN ('marketing_launch_offer', 'marketing_newsletter'))
    OR (p_state IS NOT NULL AND p_state NOT IN ('unknown', 'granted', 'denied', 'suppressed'))
    OR p_processing_status NOT IN ('received', 'processed', 'ignored', 'failed') THEN
    RAISE EXCEPTION 'communication_invalid_provider_event' USING ERRCODE = '22023';
  END IF;

  IF v_email IS NOT NULL THEN
    v_contact_id := public.communication_touch_contact(
      v_email,
      NULL,
      NULL,
      'active',
      jsonb_build_object('source', 'provider_event', 'providerKind', p_provider_kind)
    );
  ELSIF p_remote_profile_id IS NOT NULL THEN
    SELECT profile.contact_id INTO v_contact_id
      FROM public.communication_provider_profiles profile
     WHERE profile.provider_kind = btrim(p_provider_kind)
       AND profile.remote_profile_id = btrim(p_remote_profile_id)
     ORDER BY profile.updated_at DESC
     LIMIT 1;
  END IF;

  INSERT INTO public.communication_provider_events (
    provider_kind, provider_event_id, event_type, contact_id, normalized_email,
    remote_profile_id, purpose, state, processing_status, raw_payload, metadata
  )
  VALUES (
    btrim(p_provider_kind), btrim(p_provider_event_id), p_event_type, v_contact_id, v_email,
    nullif(btrim(coalesce(p_remote_profile_id, '')), ''), p_purpose, p_state,
    p_processing_status, coalesce(p_payload, '{}'::jsonb), coalesce(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (provider_kind, provider_event_id) DO NOTHING
  RETURNING id INTO v_event_id;

  v_inserted := v_event_id IS NOT NULL;

  IF NOT v_inserted THEN
    SELECT id, contact_id INTO v_event_id, v_contact_id
      FROM public.communication_provider_events
     WHERE provider_kind = btrim(p_provider_kind)
       AND provider_event_id = btrim(p_provider_event_id);
  END IF;

  IF v_inserted AND v_contact_id IS NOT NULL AND p_remote_profile_id IS NOT NULL AND p_purpose IS NOT NULL THEN
    INSERT INTO public.communication_provider_profiles (
      contact_id, provider_kind, purpose, remote_profile_id, remote_email, status, metadata
    )
    VALUES (
      v_contact_id, btrim(p_provider_kind), p_purpose, btrim(p_remote_profile_id), v_email,
      CASE WHEN p_processing_status = 'ignored' THEN 'unknown'
           WHEN p_state = 'suppressed' THEN 'suppressed'
           WHEN p_state = 'denied' THEN 'unsubscribed'
           ELSE 'active' END,
      coalesce(p_metadata, '{}'::jsonb)
    )
    ON CONFLICT (
      provider_kind,
      remote_profile_id,
      purpose,
      (coalesce(remote_list_id, ''))
    ) WHERE remote_profile_id IS NOT NULL DO UPDATE
      SET contact_id = EXCLUDED.contact_id,
          remote_email = EXCLUDED.remote_email,
          status = EXCLUDED.status,
          metadata = public.communication_provider_profiles.metadata || EXCLUDED.metadata,
          updated_at = now();
  END IF;

  RETURN jsonb_build_object(
    'providerEventId', v_event_id,
    'contactId', v_contact_id,
    'inserted', v_inserted
  );
END;
$$;


--
-- Name: communication_repair_email_delivery_outbox_lifecycle(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_repair_email_delivery_outbox_lifecycle(p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 500), 1), 1000);
  v_event_id uuid;
  v_updated integer := 0;
  v_event_count integer := 0;
BEGIN
  FOR v_event_id IN
    SELECT e.id
      FROM public.outbox_events e
      JOIN public.communication_email_deliveries d
        ON d.outbox_event_id = e.id
        OR d.dedupe_key = 'outbox:' || e.id::text
     WHERE e.status IN ('processed', 'failed', 'discarded')
       AND public.communication_email_delivery_template_for_event(e.event_type) IS NOT NULL
       AND d.status IN ('planned', 'queued', 'processing', 'delivery_delayed', 'failed', 'skipped', 'sent')
       AND d.status NOT IN ('delivered', 'bounced', 'complained')
     ORDER BY e.created_at, e.id
     LIMIT v_limit
  LOOP
    v_event_count := v_event_count + 1;
    v_updated := v_updated + public.communication_close_email_deliveries_for_outbox(v_event_id);
  END LOOP;

  RETURN jsonb_build_object(
    'checkedEvents', v_event_count,
    'updatedDeliveries', v_updated
  );
END;
$$;


--
-- Name: FUNCTION communication_repair_email_delivery_outbox_lifecycle(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.communication_repair_email_delivery_outbox_lifecycle(p_limit integer) IS 'Service-role repair for historical communication_email_deliveries rows left planned after their customer-facing outbox event reached processed, failed, or discarded.';


--
-- Name: communication_state_rank(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_state_rank(p_state text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT CASE p_state
    WHEN 'suppressed' THEN 400
    WHEN 'denied' THEN 300
    WHEN 'granted' THEN 200
    WHEN 'unknown' THEN 100
    ELSE 0
  END;
$$;


--
-- Name: communication_sync_client_consent_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_sync_client_consent_permissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_client public.clients%ROWTYPE;
  v_contact_id uuid;
BEGIN
  IF NEW.consent_type <> 'marketing' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_client FROM public.clients WHERE id = NEW.client_id;
  IF NOT FOUND OR btrim(coalesce(v_client.email, '')) = '' THEN
    RETURN NEW;
  END IF;

  v_contact_id := public.communication_touch_contact(
    v_client.email,
    v_client.first_name,
    v_client.last_name,
    'active',
    jsonb_build_object('source', 'client_consents_trigger')
  );
  PERFORM public.communication_link_contact(v_contact_id, 'clients', v_client.id, NULL, jsonb_build_object('source', 'client_consents_trigger'));
  PERFORM public.communication_link_contact(v_contact_id, 'client_consents', NEW.id, NULL, jsonb_build_object('source', 'client_consents_trigger'));
  PERFORM public.communication_record_permission_event(
    v_contact_id,
    'marketing_newsletter',
    CASE WHEN NEW.granted IS TRUE THEN 'granted' ELSE 'denied' END,
    'client_consents_marketing',
    jsonb_build_object('table', 'client_consents', 'id', NEW.id, 'clientId', NEW.client_id),
    NULL,
    jsonb_build_object('consent_type', NEW.consent_type, 'source', NEW.source),
    coalesce(NEW.captured_at, now()),
    true
  );

  RETURN NEW;
END;
$$;


--
-- Name: communication_sync_email_delivery_from_outbox_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_sync_email_delivery_from_outbox_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status IN ('processed', 'failed', 'discarded')
     AND (
       TG_OP = 'INSERT'
       OR OLD.status IS DISTINCT FROM NEW.status
       OR OLD.error IS DISTINCT FROM NEW.error
       OR OLD.metadata IS DISTINCT FROM NEW.metadata
       OR OLD.processed_at IS DISTINCT FROM NEW.processed_at
     )
  THEN
    PERFORM public.communication_close_email_deliveries_for_outbox(NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: communication_sync_tester_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_sync_tester_permissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_contact_id uuid;
  v_ref jsonb;
  v_unsubscribe_context text := current_setting(
    'openlup.communication_apply_unsubscribe_tester',
    true
  );
  v_expected_context text := pg_current_xact_id()::text || ':' || NEW.id::text;
  v_effective_role text := current_setting('role', true);
BEGIN
  -- The scoped unsubscribe RPC owns permission chronology for its pause update.
  -- This bypass is transaction-local, tester-specific, role-restricted, and
  -- valid only when no trigger-owned tester field except the pause changed.
  IF TG_OP = 'UPDATE'
    AND v_unsubscribe_context = v_expected_context
    AND (
      v_effective_role = 'service_role'
      OR (v_effective_role = 'none' AND session_user = 'postgres')
    )
    AND NEW.email_sequence_paused IS DISTINCT FROM OLD.email_sequence_paused
    AND NEW.email IS NOT DISTINCT FROM OLD.email
    AND NEW.first_name IS NOT DISTINCT FROM OLD.first_name
    AND NEW.last_name IS NOT DISTINCT FROM OLD.last_name
    AND NEW.newsletter_consent IS NOT DISTINCT FROM OLD.newsletter_consent
    AND NEW.verification_consent IS NOT DISTINCT FROM OLD.verification_consent
  THEN
    RETURN NEW;
  END IF;

  v_contact_id := public.communication_touch_contact(
    NEW.email,
    NEW.first_name,
    NEW.last_name,
    'active',
    jsonb_build_object('source', 'testers_trigger')
  );
  PERFORM public.communication_link_contact(
    v_contact_id,
    'testers',
    NEW.id,
    NULL,
    jsonb_build_object('source', 'testers_trigger')
  );
  v_ref := jsonb_build_object('table', 'testers', 'id', NEW.id);

  IF TG_OP = 'INSERT'
    OR (TG_OP = 'UPDATE' AND NEW.newsletter_consent IS DISTINCT FROM OLD.newsletter_consent)
  THEN
    PERFORM public.communication_record_permission_event(
      v_contact_id,
      'marketing_newsletter',
      CASE WHEN NEW.newsletter_consent IS TRUE THEN 'granted' ELSE 'denied' END,
      'legacy_testers_newsletter_consent',
      v_ref,
      NULL,
      jsonb_build_object('newsletter_consent', NEW.newsletter_consent),
      COALESCE(NEW.created_at, now()),
      true
    );
  END IF;

  IF (
    TG_OP = 'INSERT'
    OR (TG_OP = 'UPDATE' AND NEW.verification_consent IS DISTINCT FROM OLD.verification_consent)
  ) AND NEW.verification_consent IS TRUE
  THEN
    PERFORM public.communication_record_permission_event(
      v_contact_id,
      'tester_program',
      'granted',
      'legacy_testers_verification_consent',
      v_ref,
      NULL,
      jsonb_build_object('verification_consent', NEW.verification_consent),
      COALESCE(NEW.created_at, now()),
      false
    );
  END IF;

  IF (
    TG_OP = 'INSERT'
    OR (TG_OP = 'UPDATE' AND NEW.email_sequence_paused IS DISTINCT FROM OLD.email_sequence_paused)
  ) AND NEW.email_sequence_paused IS TRUE
  THEN
    PERFORM public.communication_record_permission_event(
      v_contact_id,
      'tester_program',
      'suppressed',
      'legacy_email_sequence_paused',
      v_ref,
      'sequence_paused',
      jsonb_build_object('email_sequence_paused', true),
      now(),
      false
    );
    PERFORM public.communication_record_permission_event(
      v_contact_id,
      'marketing_newsletter',
      'suppressed',
      'legacy_email_sequence_paused',
      v_ref,
      'sequence_paused',
      jsonb_build_object('email_sequence_paused', true),
      now(),
      true
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: communication_sync_waitlist_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_sync_waitlist_permissions() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_contact_id uuid;
  v_ref jsonb;
BEGIN
  v_contact_id := public.communication_touch_contact(NEW.email, NEW.first_name, NEW.last_name, 'active', jsonb_build_object('source', 'waitlist_trigger'));
  PERFORM public.communication_link_contact(v_contact_id, 'waitlist', NEW.id, NULL, jsonb_build_object('source', 'waitlist_trigger'));
  v_ref := jsonb_build_object('table', 'waitlist', 'id', NEW.id);

  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.marketing_launch_offer_consent IS DISTINCT FROM OLD.marketing_launch_offer_consent) THEN
    PERFORM public.communication_record_permission_event(
      v_contact_id,
      'marketing_launch_offer',
      CASE WHEN NEW.marketing_launch_offer_consent IS TRUE THEN 'granted' ELSE 'denied' END,
      'waitlist_launch_offer_consent',
      v_ref,
      NULL,
      jsonb_build_object('marketing_launch_offer_consent', NEW.marketing_launch_offer_consent),
      coalesce(NEW.created_at, now()), true
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: communication_touch_contact(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_touch_contact(p_email text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text, p_status text DEFAULT 'active'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_email text := public.communication_normalize_email(p_email);
  v_contact_id uuid;
BEGIN
  IF v_email = '' OR position('@' in v_email) <= 1 THEN
    RAISE EXCEPTION 'communication_invalid_email' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.communication_contacts (
    normalized_email, display_email, first_name, last_name, status, metadata
  )
  VALUES (
    v_email, btrim(p_email), nullif(btrim(coalesce(p_first_name, '')), ''),
    nullif(btrim(coalesce(p_last_name, '')), ''), coalesce(p_status, 'active'),
    coalesce(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (normalized_email) DO UPDATE
    SET display_email = EXCLUDED.display_email,
        first_name = coalesce(EXCLUDED.first_name, public.communication_contacts.first_name),
        last_name = coalesce(EXCLUDED.last_name, public.communication_contacts.last_name),
        status = CASE
          WHEN public.communication_contacts.status = 'suppressed' THEN public.communication_contacts.status
          ELSE EXCLUDED.status
        END,
        metadata = public.communication_contacts.metadata || EXCLUDED.metadata,
        updated_at = now()
  RETURNING id INTO v_contact_id;

  RETURN v_contact_id;
END;
$$;


--
-- Name: communication_update_email_delivery_from_provider(uuid, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_update_email_delivery_from_provider(p_email_send_id uuid DEFAULT NULL::uuid, p_provider_message_id text DEFAULT NULL::text, p_provider_event_type text DEFAULT NULL::text, p_event_at timestamp with time zone DEFAULT now(), p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_input_provider_type text := btrim(coalesce(p_provider_event_type, ''));
  v_input_event_type text;
  v_event_at timestamptz := coalesce(p_event_at, now());
  v_provider_message_id text := nullif(btrim(coalesce(p_provider_message_id, '')), '');
  v_metadata jsonb := CASE
    WHEN jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) = 'object'
      THEN coalesce(p_metadata, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_provider_event_id text;
  v_source text;
  v_link text;
  v_event_metadata jsonb;
  v_legacy_event_id uuid;
  v_event public.email_events%ROWTYPE;
  v_had_canonical_event boolean := false;
  v_preinsert_send_id uuid;
  v_send public.email_sends%ROWTYPE;
  v_delivery public.communication_email_deliveries%ROWTYPE;
  v_send_id uuid;
  v_canonical_provider_type text;
  v_canonical_send_status text;
  v_canonical_delivery_status text;
  v_canonical_event_id text;
  v_send_watermark timestamptz;
  v_delivery_watermark timestamptz;
  v_watermark_at timestamptz;
  v_apply_status boolean;
  v_apply_watermark boolean;
  v_delivery_count integer := 0;
  v_recipient_email text;
  v_provider_suppression jsonb;
  v_provider_suppression_id uuid;
  v_provider_suppression_source text;
  v_purpose text;
BEGIN
  v_input_event_type := CASE v_input_provider_type
    WHEN 'email.sent' THEN 'sent'
    WHEN 'email.delivered' THEN 'delivered'
    WHEN 'email.delivery_delayed' THEN 'delivery_delayed'
    WHEN 'email.opened' THEN 'open'
    WHEN 'email.clicked' THEN 'click'
    WHEN 'email.bounced' THEN 'bounce'
    WHEN 'email.complained' THEN 'complaint'
    WHEN 'email.failed' THEN 'failed'
    WHEN 'email.suppressed' THEN 'suppressed'
    WHEN 'email.scheduled' THEN 'scheduled'
    ELSE NULL
  END;

  IF v_input_event_type IS NULL THEN
    RETURN 0;
  END IF;

  v_provider_event_id := nullif(btrim(coalesce(v_metadata->>'providerEventId', '')), '');
  v_source := coalesce(
    nullif(btrim(coalesce(v_metadata->>'source', '')), ''),
    'provider'
  );
  v_link := nullif(btrim(coalesce(v_metadata->>'link', '')), '');
  v_event_metadata := CASE
    WHEN jsonb_typeof(v_metadata->'eventMetadata') = 'object'
      THEN v_metadata->'eventMetadata'
    ELSE '{}'::jsonb
  END;
  v_event_metadata := v_event_metadata || jsonb_strip_nulls(jsonb_build_object(
    'source', v_source,
    'providerEventType', v_input_provider_type,
    'providerMessageId', v_provider_message_id,
    'eventTimeSource', nullif(btrim(coalesce(v_metadata->>'eventTimeSource', '')), '')
  ));

  -- Rolling-deploy compatibility: the old webhook inserted email_events first
  -- and passed its row id to this RPC.
  IF nullif(btrim(coalesce(v_metadata->>'email_event_id', '')), '') IS NOT NULL THEN
    BEGIN
      v_legacy_event_id := (v_metadata->>'email_event_id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      v_legacy_event_id := NULL;
    END;
  END IF;

  -- A duplicate provider id owns its already-persisted facts. Replays may fill
  -- legacy NULLs, but may never redirect the event to a different send/type/time.
  IF v_provider_event_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'communication-email-provider-event:' || v_provider_event_id,
      0
    ));

    SELECT event.* INTO v_event
      FROM public.email_events event
     WHERE event.resend_webhook_id = v_provider_event_id
     FOR UPDATE;
  ELSIF v_legacy_event_id IS NOT NULL THEN
    SELECT event.* INTO v_event
      FROM public.email_events event
     WHERE event.id = v_legacy_event_id
     FOR UPDATE;
  END IF;

  v_had_canonical_event := v_event.id IS NOT NULL;

  v_send_id := coalesce(v_event.send_id, p_email_send_id);

  IF v_send_id IS NOT NULL THEN
    SELECT send.* INTO v_send
      FROM public.email_sends send
     WHERE send.id = v_send_id
     FOR UPDATE;
  ELSIF v_provider_message_id IS NOT NULL THEN
    IF (SELECT count(*) FROM public.email_sends send WHERE send.resend_id = v_provider_message_id) > 1 THEN
      RAISE EXCEPTION 'communication_email_provider_message_collision'
        USING ERRCODE = '23505';
    END IF;

    SELECT send.* INTO v_send
      FROM public.email_sends send
     WHERE send.resend_id = v_provider_message_id
     FOR UPDATE;
    v_send_id := v_send.id;
  END IF;

  IF v_send_id IS NULL OR v_send.id IS NULL THEN
    IF v_provider_message_id IS NULL OR NOT EXISTS (
      SELECT 1
        FROM public.communication_email_deliveries delivery
       WHERE delivery.email_send_id IS NULL
         AND delivery.provider_kind = 'resend'
         AND delivery.provider_message_id = v_provider_message_id
    ) THEN
      RETURN 0;
    END IF;
    v_send_id := NULL;
  END IF;
  v_preinsert_send_id := v_send_id;

  -- The old poller inserted an exact event immediately before calling the RPC
  -- but supplied no event id. Reuse that row during a rolling deployment.
  IF v_event.id IS NULL
     AND v_provider_event_id IS NULL
     AND v_legacy_event_id IS NULL
  THEN
    SELECT event.* INTO v_event
      FROM public.email_events event
     WHERE (
       (v_send_id IS NOT NULL AND event.send_id = v_send_id)
       OR (
         v_send_id IS NULL
         AND event.send_id IS NULL
         AND event.metadata->>'providerMessageId' = v_provider_message_id
       )
     )
       AND event.event_type = v_input_event_type
       AND event.timestamp = v_event_at
       AND event.metadata->>'source' = v_source
     ORDER BY event.id
     LIMIT 1
     FOR UPDATE;
  END IF;

  IF v_event.id IS NULL THEN
    INSERT INTO public.email_events AS existing_event (
      send_id,
      event_type,
      link_url,
      timestamp,
      metadata,
      resend_webhook_id
    ) VALUES (
      v_send_id,
      v_input_event_type,
      v_link,
      v_event_at,
      v_event_metadata,
      v_provider_event_id
    )
    ON CONFLICT (resend_webhook_id) DO UPDATE
      SET send_id = coalesce(existing_event.send_id, EXCLUDED.send_id),
          event_type = coalesce(existing_event.event_type, EXCLUDED.event_type),
          link_url = coalesce(existing_event.link_url, EXCLUDED.link_url),
          timestamp = coalesce(existing_event.timestamp, EXCLUDED.timestamp),
          metadata = coalesce(existing_event.metadata, EXCLUDED.metadata)
    RETURNING existing_event.* INTO v_event;
  ELSE
    UPDATE public.email_events event
       SET send_id = coalesce(event.send_id, v_send_id),
           event_type = coalesce(event.event_type, v_input_event_type),
           link_url = coalesce(event.link_url, v_link),
           timestamp = coalesce(event.timestamp, v_event_at),
           metadata = coalesce(event.metadata, v_event_metadata)
     WHERE event.id = v_event.id
    RETURNING event.* INTO v_event;
  END IF;

  -- An ON CONFLICT race can return an event owned by another send. Re-resolve
  -- the canonical owner before touching either projection. The provider-event
  -- advisory lock serializes new callers; this reload also protects a rolling
  -- deployment racing an older writer that does not take that lock.
  IF v_event.send_id IS DISTINCT FROM v_preinsert_send_id THEN
    v_send_id := v_event.send_id;
    IF v_send_id IS NOT NULL THEN
      SELECT send.* INTO v_send
        FROM public.email_sends send
       WHERE send.id = v_send_id
       FOR UPDATE;
      IF v_send.id IS NULL THEN
        RETURN 0;
      END IF;
    END IF;
    v_had_canonical_event := true;
  END IF;

  -- On replay, the stored event/send pair is canonical. A conflicting input
  -- provider message id is ignored rather than rebound to the canonical event.
  IF v_had_canonical_event AND v_event.send_id IS NOT NULL THEN
    v_provider_message_id := v_send.resend_id;
  END IF;

  IF v_provider_message_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'communication-email-provider-message:' || v_provider_message_id,
      0
    ));

    IF v_send_id IS NOT NULL
       AND v_send.resend_id IS NOT NULL
       AND v_send.resend_id <> v_provider_message_id THEN
      RAISE EXCEPTION 'communication_email_provider_message_mismatch'
        USING ERRCODE = '23505';
    END IF;

    IF v_send_id IS NOT NULL AND EXISTS (
      SELECT 1
        FROM public.email_sends other_send
       WHERE other_send.resend_id = v_provider_message_id
         AND other_send.id <> v_send_id
    ) THEN
      RAISE EXCEPTION 'communication_email_provider_message_collision'
        USING ERRCODE = '23505';
    END IF;

    IF v_send_id IS NOT NULL AND v_send.resend_id IS NULL THEN
      UPDATE public.email_sends
         SET resend_id = v_provider_message_id
       WHERE id = v_send_id;
      v_send.resend_id := v_provider_message_id;
    END IF;
  ELSIF v_send_id IS NOT NULL THEN
    v_provider_message_id := v_send.resend_id;
  END IF;

  -- Canonical duplicate facts, not replay input, drive both projections.
  v_event_at := coalesce(v_event.timestamp, v_event_at);
  v_canonical_provider_type := CASE v_event.event_type
    WHEN 'sent' THEN 'email.sent'
    WHEN 'delivered' THEN 'email.delivered'
    WHEN 'delivery_delayed' THEN 'email.delivery_delayed'
    WHEN 'open' THEN 'email.opened'
    WHEN 'click' THEN 'email.clicked'
    WHEN 'bounce' THEN 'email.bounced'
    WHEN 'complaint' THEN 'email.complained'
    WHEN 'failed' THEN 'email.failed'
    WHEN 'suppressed' THEN 'email.suppressed'
    WHEN 'scheduled' THEN 'email.scheduled'
    ELSE NULL
  END;
  v_canonical_event_id := coalesce(
    v_event.resend_webhook_id,
    'email-event:' || v_event.id::text
  );
  v_source := coalesce(
    nullif(btrim(coalesce(v_event.metadata->>'source', '')), ''),
    v_source
  );

  v_canonical_send_status := CASE v_canonical_provider_type
    WHEN 'email.sent' THEN 'sent'
    WHEN 'email.delivered' THEN 'delivered'
    WHEN 'email.bounced' THEN 'bounced'
    WHEN 'email.complained' THEN 'complained'
    WHEN 'email.failed' THEN 'failed'
    WHEN 'email.suppressed' THEN 'failed'
    ELSE NULL
  END;
  v_canonical_delivery_status := CASE v_canonical_provider_type
    WHEN 'email.sent' THEN 'sent'
    WHEN 'email.delivered' THEN 'delivered'
    WHEN 'email.delivery_delayed' THEN 'delivery_delayed'
    WHEN 'email.bounced' THEN 'bounced'
    WHEN 'email.complained' THEN 'complained'
    WHEN 'email.failed' THEN 'failed'
    WHEN 'email.suppressed' THEN 'failed'
    ELSE NULL
  END;

  -- Engagement/scheduling events belong in email_events, but must not advance
  -- the delivery watermark and accidentally hide a later delivery webhook.
  IF v_canonical_delivery_status IS NULL THEN
    RETURN 0;
  END IF;

  IF v_send_id IS NOT NULL THEN
    SELECT send.* INTO v_send
      FROM public.email_sends send
     WHERE send.id = v_send_id
     FOR UPDATE;

  BEGIN
    v_send_watermark := nullif(v_send.provider_response->>'lastProviderEventAt', '')::timestamptz;
  EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
    v_send_watermark := NULL;
  END;

  v_apply_status := v_canonical_send_status IS NOT NULL
    AND v_canonical_send_status <> v_send.status
    AND (
      (
        v_send.status = 'sent'
        AND v_canonical_send_status <> 'sent'
        AND (v_send_watermark IS NULL OR v_event_at >= v_send_watermark)
      )
      OR (
        v_send.status = 'delivered'
        AND v_canonical_send_status IN ('bounced', 'complained', 'failed')
        AND (v_send_watermark IS NULL OR v_event_at >= v_send_watermark)
      )
    );
  v_apply_watermark := (v_send_watermark IS NULL OR v_event_at >= v_send_watermark)
    AND (
      v_apply_status
      OR
      v_canonical_send_status = v_send.status
      OR (
        v_canonical_provider_type = 'email.delivery_delayed'
        AND v_send.status = 'sent'
        AND coalesce(v_send.provider_response->>'lastProviderEventType', 'email.sent')
            IN ('email.sent', 'email.delivery_delayed')
      )
    );

    IF v_apply_status OR v_apply_watermark THEN
    v_watermark_at := CASE
      WHEN v_send_watermark IS NULL THEN v_event_at
      ELSE greatest(v_send_watermark, v_event_at)
    END;

    UPDATE public.email_sends
       SET status = CASE
             WHEN v_apply_status THEN v_canonical_send_status
             ELSE status
           END,
           provider_response = CASE
             WHEN v_apply_watermark THEN coalesce(provider_response, '{}'::jsonb)
               || jsonb_build_object(
                 'lastProviderEventAt', v_watermark_at,
                 'lastProviderEventType', v_canonical_provider_type,
                 'lastProviderEventId', v_canonical_event_id,
                 'lastProviderEventSource', v_source
               )
             ELSE provider_response
           END
     WHERE id = v_send_id;
    END IF;
  END IF;

  FOR v_delivery IN
    SELECT delivery.*
      FROM public.communication_email_deliveries delivery
     WHERE delivery.email_send_id = v_send_id
        OR (
          delivery.email_send_id IS NULL
          AND delivery.provider_kind = 'resend'
          AND v_provider_message_id IS NOT NULL
          AND delivery.provider_message_id = v_provider_message_id
        )
     FOR UPDATE
  LOOP
    v_delivery_count := v_delivery_count + 1;
    BEGIN
      v_delivery_watermark := nullif(v_delivery.metadata->>'lastProviderEventAt', '')::timestamptz;
    EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow THEN
      v_delivery_watermark := NULL;
    END;

    v_apply_status := v_canonical_delivery_status <> v_delivery.status
      AND (
        v_delivery.status NOT IN (
          'sent', 'delivery_delayed', 'delivered', 'bounced', 'complained', 'failed'
        )
        OR (
          v_delivery.status = 'sent'
          AND v_canonical_delivery_status IN (
            'delivery_delayed', 'delivered', 'bounced', 'complained', 'failed'
          )
          AND (v_delivery_watermark IS NULL OR v_event_at >= v_delivery_watermark)
        )
        OR (
          v_delivery.status = 'delivery_delayed'
          AND v_canonical_delivery_status IN ('delivered', 'bounced', 'complained', 'failed')
          AND (v_delivery_watermark IS NULL OR v_event_at >= v_delivery_watermark)
        )
        OR (
          v_delivery.status = 'delivered'
          AND v_canonical_delivery_status IN ('bounced', 'complained', 'failed')
          AND (v_delivery_watermark IS NULL OR v_event_at >= v_delivery_watermark)
        )
      );
    v_apply_watermark := (
      v_canonical_delivery_status = v_delivery.status
      OR v_apply_status
    ) AND (v_delivery_watermark IS NULL OR v_event_at >= v_delivery_watermark);

    IF v_apply_status OR v_apply_watermark THEN
      v_watermark_at := CASE
        WHEN v_delivery_watermark IS NULL THEN v_event_at
        ELSE greatest(v_delivery_watermark, v_event_at)
      END;

      UPDATE public.communication_email_deliveries
         SET status = CASE
               WHEN v_apply_status THEN v_canonical_delivery_status
               ELSE status
             END,
             updated_at = now(),
             email_send_id = coalesce(email_send_id, v_send_id),
             provider_message_id = coalesce(provider_message_id, v_provider_message_id),
             sent_at = CASE
               WHEN v_canonical_delivery_status = 'sent' THEN coalesce(sent_at, v_event_at)
               ELSE sent_at
             END,
             delivered_at = CASE
               WHEN v_canonical_delivery_status = 'delivered'
                 THEN coalesce(delivered_at, v_event_at)
               ELSE delivered_at
             END,
             terminal_at = CASE
               WHEN v_apply_status
                    AND v_canonical_delivery_status IN ('delivered', 'bounced', 'complained', 'failed')
                 THEN v_event_at
               ELSE terminal_at
             END,
             last_error_code = CASE
               WHEN v_apply_status
                    AND v_canonical_delivery_status IN ('bounced', 'complained', 'failed')
                 THEN v_canonical_delivery_status
               ELSE last_error_code
             END,
             metadata = CASE
               WHEN v_apply_watermark THEN coalesce(metadata, '{}'::jsonb)
                 || jsonb_build_object(
                   'lastProviderEventAt', v_watermark_at,
                   'lastProviderEventType', v_canonical_provider_type,
                   'lastProviderEventId', v_canonical_event_id,
                   'lastProviderEventSource', v_source,
                   'emailEventId', v_event.id
                 )
               ELSE metadata
             END
       WHERE id = v_delivery.id;
    END IF;
  END LOOP;

  -- Complaint/suppression is part of the same transaction as delivery
  -- convergence. The existing provider-event ledger is the idempotency gate;
  -- a replay skips permission writes, while any permission error rolls back the
  -- event, projections, and ledger row together.
  IF v_canonical_provider_type IN ('email.complained', 'email.suppressed') THEN
    v_recipient_email := nullif(btrim(coalesce(v_event.metadata->>'email', '')), '');
    IF v_recipient_email IS NULL THEN
      IF jsonb_typeof(v_event.metadata->'to') = 'array' THEN
        v_recipient_email := nullif(btrim(coalesce(v_event.metadata->'to'->>0, '')), '');
      ELSE
        v_recipient_email := nullif(btrim(coalesce(v_event.metadata->>'to', '')), '');
      END IF;
    END IF;
    IF v_recipient_email IS NULL AND v_send_id IS NOT NULL AND v_send.tester_id IS NOT NULL THEN
      SELECT tester.email INTO v_recipient_email
        FROM public.testers tester
       WHERE tester.id = v_send.tester_id;
    END IF;

    v_recipient_email := nullif(public.communication_normalize_email(v_recipient_email), '');
    IF v_recipient_email IS NOT NULL THEN
      v_provider_suppression_source := CASE v_canonical_provider_type
        WHEN 'email.complained' THEN 'provider_complaint'
        ELSE 'provider_suppression'
      END;
      v_provider_suppression := public.communication_record_provider_event(
        'resend',
        v_canonical_event_id,
        CASE v_canonical_provider_type
          WHEN 'email.complained' THEN 'complaint'
          ELSE 'suppress'
        END,
        v_recipient_email,
        NULL,
        NULL,
        'suppressed',
        v_event.metadata,
        jsonb_build_object(
          'emailSendId', v_send_id,
          'providerMessageId', v_provider_message_id
        ),
        'received'
      );

      IF coalesce((v_provider_suppression->>'inserted')::boolean, false) THEN
        v_provider_suppression_id := (v_provider_suppression->>'providerEventId')::uuid;
        FOREACH v_purpose IN ARRAY ARRAY['marketing_launch_offer', 'marketing_newsletter']
        LOOP
          PERFORM public.communication_record_permission_event(
            (v_provider_suppression->>'contactId')::uuid,
            v_purpose,
            'suppressed',
            v_provider_suppression_source,
            jsonb_build_object(
              'providerKind', 'resend',
              'providerEventId', v_canonical_event_id,
              'table', CASE WHEN v_send.tester_id IS NOT NULL THEN 'testers' ELSE NULL END,
              'id', v_send.tester_id
            ),
            v_canonical_provider_type,
            jsonb_build_object(
              'originProviderKind', 'resend',
              'originProviderEventId', v_canonical_event_id,
              'emailSendId', v_send_id,
              'providerMessageId', v_provider_message_id
            ),
            v_event_at,
            true
          );
        END LOOP;
        PERFORM public.communication_mark_provider_event_processed(
          v_provider_suppression_id,
          'processed',
          jsonb_build_object('emailEventId', v_event.id)
        );
      END IF;
    END IF;
  END IF;

  RETURN v_delivery_count;
END;
$$;


--
-- Name: communications_delivery_health(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_delivery_health(p_operator_id uuid) RETURNS TABLE(attempted bigint, accepted bigint, failed bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  RETURN QUERY SELECT
    count(*) FILTER (WHERE transition = 'attempted'),
    count(*) FILTER (WHERE transition = 'accepted'),
    count(*) FILTER (WHERE transition = 'failed')
  FROM public.communication_delivery_events;
END; $$;


--
-- Name: communications_delivery_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_delivery_readiness(p_operator_id uuid) RETURNS TABLE(required_control_count bigint, disabled_control_keys text[])
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  RETURN QUERY SELECT count(*),
    COALESCE(array_agg(control_key ORDER BY control_key) FILTER (WHERE enabled IS FALSE), ARRAY[]::text[])
  FROM public.communication_delivery_controls;
END; $$;


--
-- Name: communication_delivery_controls; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.communication_delivery_controls (
    control_key text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT communication_delivery_controls_key_check CHECK ((control_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$'::text)),
    CONSTRAINT communication_delivery_controls_revision_check CHECK ((revision >= 1))
);


--
-- Name: communications_list_delivery_controls(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_list_delivery_controls(p_operator_id uuid) RETURNS SETOF public.communication_delivery_controls
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  RETURN QUERY SELECT * FROM public.communication_delivery_controls ORDER BY control_key;
END; $$;


--
-- Name: communications_list_delivery_events(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_list_delivery_events(p_operator_id uuid, p_idempotency_key text) RETURNS TABLE(event_id bigint, idempotency_key text, transition text, attempt_count integer, operator_id uuid, occurred_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  RETURN QUERY
  SELECT event_row.event_id, event_row.idempotency_key, event_row.transition,
         event_row.attempt_count, event_row.operator_id, event_row.occurred_at
  FROM public.communication_delivery_events AS event_row
  WHERE event_row.idempotency_key = p_idempotency_key
  ORDER BY event_row.event_id;
END;
$$;


--
-- Name: communications_list_delivery_operations(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_list_delivery_operations(p_operator_id uuid, p_page integer, p_page_size integer) RETURNS TABLE(idempotency_key text, template_reference text, recipient_fingerprint text, state text, delivery_reference text, error_code text, attempt_count integer, created_at timestamp with time zone, updated_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  IF p_page IS NULL OR p_page < 0 OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'communications_page_invalid' USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
  SELECT command_row.idempotency_key, command_row.template_reference,
         command_row.recipient_fingerprint, receipt.state,
         receipt.delivery_reference, receipt.error_code, receipt.attempt_count,
         command_row.created_at, command_row.updated_at, count(*) OVER ()
  FROM public.communication_delivery_commands AS command_row
  JOIN public.transactional_delivery_receipts AS receipt
    ON receipt.idempotency_key = command_row.idempotency_key
  ORDER BY command_row.updated_at DESC, command_row.idempotency_key
  LIMIT p_page_size OFFSET p_page * p_page_size;
END;
$$;


--
-- Name: communication_delivery_templates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.communication_delivery_templates (
    template_reference text NOT NULL,
    control_key text NOT NULL,
    active boolean DEFAULT false NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT communication_delivery_templates_reference_check CHECK ((template_reference ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$'::text)),
    CONSTRAINT communication_delivery_templates_revision_check CHECK ((revision >= 1))
);


--
-- Name: communications_list_delivery_templates(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_list_delivery_templates(p_operator_id uuid) RETURNS SETOF public.communication_delivery_templates
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$ BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  RETURN QUERY SELECT * FROM public.communication_delivery_templates ORDER BY template_reference;
END; $$;


--
-- Name: communications_operator_is_active(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_operator_is_active(p_principal_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT p_principal_id IS NOT NULL
    AND (
      EXISTS (
        SELECT 1
        FROM public.admin_users AS admin_row
        WHERE admin_row.id = p_principal_id
          AND admin_row.membership_state = 'active'
          AND COALESCE(admin_row.role, 'admin') = 'admin'
      )
      OR EXISTS (
        SELECT 1
        FROM public.platform_communication_operators AS operator_row
        WHERE operator_row.principal_id = p_principal_id
          AND operator_row.active IS TRUE
      )
    );
$$;


--
-- Name: FUNCTION communications_operator_is_active(p_principal_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.communications_operator_is_active(p_principal_id uuid) IS 'Operator eligibility for the communications control plane and everything gated on it. TRUE for an active administrator in admin_users, or for an explicit active row in platform_communication_operators. The administrator arm is the platform axis; the table arm is referential truth for the operator ledgers and the only arm a runtime without an admin roster can use.';


--
-- Name: communications_prepare_delivery_command(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_prepare_delivery_command(p_operator_id uuid, p_idempotency_key text, p_command_fingerprint text, p_template_reference text, p_recipient_fingerprint text) RETURNS TABLE(action text, attempt_count integer)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_command public.communication_delivery_commands%ROWTYPE;
  v_preparation public.communication_delivery_preparations%ROWTYPE;
  v_receipt public.transactional_delivery_receipts%ROWTYPE;
  v_control_key text;
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  IF p_idempotency_key IS NULL
     OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$'
     OR p_command_fingerprint IS NULL
     OR p_command_fingerprint !~ '^[a-f0-9]{64}$'
     OR p_template_reference IS NULL
     OR p_template_reference !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$'
     OR p_recipient_fingerprint IS NULL
     OR p_recipient_fingerprint !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'communications_command_invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_idempotency_key, 0));
  SELECT * INTO v_command
  FROM public.communication_delivery_commands
  WHERE idempotency_key = p_idempotency_key
  FOR UPDATE;

  IF FOUND THEN
    IF v_command.command_fingerprint <> p_command_fingerprint
       OR v_command.template_reference <> p_template_reference
       OR v_command.recipient_fingerprint <> p_recipient_fingerprint THEN
      RAISE EXCEPTION 'communications_command_conflict' USING ERRCODE = '23505';
    END IF;
    SELECT * INTO STRICT v_receipt
    FROM public.transactional_delivery_receipts
    WHERE idempotency_key = p_idempotency_key
    FOR UPDATE;
    IF v_receipt.state = 'accepted' THEN
      INSERT INTO public.communication_delivery_events(
        idempotency_key, transition, attempt_count, operator_id
      ) VALUES (p_idempotency_key, 'replayed', v_receipt.attempt_count, p_operator_id);
      RETURN QUERY SELECT 'replayed'::text, v_receipt.attempt_count;
      RETURN;
    END IF;

    -- A durable accepted receipt always replays, even if policy changes later.
    -- A failed command is a new delivery attempt and must re-check current
    -- eligibility before invoking the captured delivery adapter again.
    IF NOT EXISTS (
      SELECT 1
      FROM public.communication_delivery_templates AS template_row
      JOIN public.communication_delivery_controls AS control_row
        ON control_row.control_key = template_row.control_key
      WHERE template_row.template_reference = v_command.template_reference
        AND template_row.active IS TRUE
        AND control_row.enabled IS TRUE
    ) THEN
      RAISE EXCEPTION 'communications_delivery_disabled' USING ERRCODE = '23505';
    END IF;

    INSERT INTO public.communication_delivery_events(
      idempotency_key, transition, attempt_count, operator_id
    ) VALUES (p_idempotency_key, 'attempted', v_receipt.attempt_count + 1, p_operator_id);
    RETURN QUERY SELECT 'proceed'::text, v_receipt.attempt_count + 1;
    RETURN;
  END IF;

  SELECT * INTO v_preparation
  FROM public.communication_delivery_preparations
  WHERE idempotency_key = p_idempotency_key
  FOR UPDATE;
  IF FOUND THEN
    IF v_preparation.command_fingerprint <> p_command_fingerprint
       OR v_preparation.template_reference <> p_template_reference
       OR v_preparation.recipient_fingerprint <> p_recipient_fingerprint
       OR v_preparation.operator_id <> p_operator_id THEN
      RAISE EXCEPTION 'communications_command_conflict' USING ERRCODE = '23505';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.communication_delivery_templates AS template_row
      JOIN public.communication_delivery_controls AS control_row
        ON control_row.control_key = template_row.control_key
      WHERE template_row.template_reference = v_preparation.template_reference
        AND template_row.active IS TRUE
        AND control_row.enabled IS TRUE
    ) THEN
      RAISE EXCEPTION 'communications_delivery_disabled' USING ERRCODE = '23505';
    END IF;
    UPDATE public.communication_delivery_preparations
    SET updated_at = now() WHERE idempotency_key = p_idempotency_key;
    RETURN QUERY SELECT 'proceed'::text, 1;
    RETURN;
  END IF;

  SELECT template_row.control_key INTO v_control_key
  FROM public.communication_delivery_templates AS template_row
  JOIN public.communication_delivery_controls AS control_row
    ON control_row.control_key = template_row.control_key
  WHERE template_row.template_reference = p_template_reference
    AND template_row.active IS TRUE
    AND control_row.enabled IS TRUE
  FOR UPDATE OF template_row, control_row;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'communications_delivery_disabled' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.communication_delivery_preparations(
    idempotency_key, command_fingerprint, template_reference,
    control_key, recipient_fingerprint, operator_id
  ) VALUES (
    p_idempotency_key, p_command_fingerprint, p_template_reference,
    v_control_key, p_recipient_fingerprint, p_operator_id
  );
  RETURN QUERY SELECT 'proceed'::text, 1;
END;
$_$;


--
-- Name: transactional_delivery_receipts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.transactional_delivery_receipts (
    idempotency_key text NOT NULL,
    command_fingerprint text NOT NULL,
    state text NOT NULL,
    delivery_reference text,
    error_code text,
    attempt_count integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_at timestamp with time zone,
    failed_at timestamp with time zone,
    CONSTRAINT transactional_delivery_receipts_attempt_count_check CHECK ((attempt_count >= 1)),
    CONSTRAINT transactional_delivery_receipts_evidence_shape_check CHECK ((((state = 'accepted'::text) AND (delivery_reference IS NOT NULL) AND (error_code IS NULL) AND (accepted_at IS NOT NULL)) OR ((state = 'failed'::text) AND (delivery_reference IS NULL) AND (error_code IS NOT NULL) AND (accepted_at IS NULL) AND (failed_at IS NOT NULL)))),
    CONSTRAINT transactional_delivery_receipts_fingerprint_format_check CHECK ((command_fingerprint ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT transactional_delivery_receipts_idempotency_key_format_check CHECK ((idempotency_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$'::text)),
    CONSTRAINT transactional_delivery_receipts_idempotency_key_nonempty_check CHECK ((btrim(idempotency_key) <> ''::text)),
    CONSTRAINT transactional_delivery_receipts_state_check CHECK ((state = ANY (ARRAY['accepted'::text, 'failed'::text]))),
    CONSTRAINT transactional_delivery_receipts_timestamp_order_check CHECK (((updated_at >= created_at) AND ((accepted_at IS NULL) OR (accepted_at >= created_at)) AND ((failed_at IS NULL) OR (failed_at >= created_at))))
);


--
-- Name: communications_record_delivery_accepted(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_record_delivery_accepted(p_operator_id uuid, p_idempotency_key text, p_command_fingerprint text, p_delivery_reference text) RETURNS SETOF public.transactional_delivery_receipts
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_command public.communication_delivery_commands%ROWTYPE;
  v_preparation public.communication_delivery_preparations%ROWTYPE;
  v_receipt public.transactional_delivery_receipts%ROWTYPE;
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_idempotency_key, 0));
  SELECT * INTO v_command FROM public.communication_delivery_commands
  WHERE idempotency_key = p_idempotency_key FOR UPDATE;
  IF FOUND AND v_command.command_fingerprint <> p_command_fingerprint THEN
    RAISE EXCEPTION 'communications_command_conflict' USING ERRCODE = '23505';
  END IF;
  IF NOT FOUND THEN
    SELECT * INTO v_preparation FROM public.communication_delivery_preparations
    WHERE idempotency_key = p_idempotency_key FOR UPDATE;
    IF NOT FOUND OR v_preparation.command_fingerprint <> p_command_fingerprint
       OR v_preparation.operator_id <> p_operator_id THEN
      RAISE EXCEPTION 'communications_command_conflict' USING ERRCODE = '23505';
    END IF;
  END IF;
  SELECT * INTO v_receipt FROM public.transactional_delivery_record_accepted(
    p_idempotency_key, p_command_fingerprint, p_delivery_reference
  );
  IF v_command.idempotency_key IS NULL THEN
    INSERT INTO public.communication_delivery_commands(
      idempotency_key, command_fingerprint, template_reference,
      control_key, recipient_fingerprint
    ) VALUES (
      v_preparation.idempotency_key, v_preparation.command_fingerprint,
      v_preparation.template_reference, v_preparation.control_key,
      v_preparation.recipient_fingerprint
    );
    INSERT INTO public.communication_delivery_events(
      idempotency_key, transition, attempt_count, operator_id
    ) VALUES (p_idempotency_key, 'attempted', v_receipt.attempt_count, p_operator_id);
    DELETE FROM public.communication_delivery_preparations
    WHERE idempotency_key = p_idempotency_key;
  END IF;
  UPDATE public.communication_delivery_commands
  SET updated_at = now() WHERE idempotency_key = p_idempotency_key;
  INSERT INTO public.communication_delivery_events(
    idempotency_key, transition, attempt_count, operator_id
  ) VALUES (p_idempotency_key, 'accepted', v_receipt.attempt_count, p_operator_id);
  RETURN NEXT v_receipt;
END;
$$;


--
-- Name: communications_record_delivery_failed(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_record_delivery_failed(p_operator_id uuid, p_idempotency_key text, p_command_fingerprint text, p_error_code text) RETURNS SETOF public.transactional_delivery_receipts
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_command public.communication_delivery_commands%ROWTYPE;
  v_preparation public.communication_delivery_preparations%ROWTYPE;
  v_receipt public.transactional_delivery_receipts%ROWTYPE;
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_idempotency_key, 0));
  SELECT * INTO v_command FROM public.communication_delivery_commands
  WHERE idempotency_key = p_idempotency_key FOR UPDATE;
  IF FOUND AND v_command.command_fingerprint <> p_command_fingerprint THEN
    RAISE EXCEPTION 'communications_command_conflict' USING ERRCODE = '23505';
  END IF;
  IF NOT FOUND THEN
    SELECT * INTO v_preparation FROM public.communication_delivery_preparations
    WHERE idempotency_key = p_idempotency_key FOR UPDATE;
    IF NOT FOUND OR v_preparation.command_fingerprint <> p_command_fingerprint
       OR v_preparation.operator_id <> p_operator_id THEN
      RAISE EXCEPTION 'communications_command_conflict' USING ERRCODE = '23505';
    END IF;
  END IF;
  SELECT * INTO v_receipt FROM public.transactional_delivery_record_failed(
    p_idempotency_key, p_command_fingerprint, p_error_code
  );
  IF v_command.idempotency_key IS NULL THEN
    INSERT INTO public.communication_delivery_commands(
      idempotency_key, command_fingerprint, template_reference,
      control_key, recipient_fingerprint
    ) VALUES (
      v_preparation.idempotency_key, v_preparation.command_fingerprint,
      v_preparation.template_reference, v_preparation.control_key,
      v_preparation.recipient_fingerprint
    );
    INSERT INTO public.communication_delivery_events(
      idempotency_key, transition, attempt_count, operator_id
    ) VALUES (p_idempotency_key, 'attempted', v_receipt.attempt_count, p_operator_id);
    DELETE FROM public.communication_delivery_preparations
    WHERE idempotency_key = p_idempotency_key;
  END IF;
  UPDATE public.communication_delivery_commands
  SET updated_at = now() WHERE idempotency_key = p_idempotency_key;
  INSERT INTO public.communication_delivery_events(
    idempotency_key, transition, attempt_count, operator_id
  ) VALUES (p_idempotency_key, 'failed', v_receipt.attempt_count, p_operator_id);
  RETURN NEXT v_receipt;
END;
$$;


--
-- Name: communications_refuse_delivery_event_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_refuse_delivery_event_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  RAISE LOG 'communications_delivery_events_append_only_rejected';
  RAISE EXCEPTION 'communications_delivery_events_append_only' USING ERRCODE = '55000';
END;
$$;


--
-- Name: communications_require_active_operator(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_require_active_operator(p_operator_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF p_operator_id IS NULL OR NOT public.communications_operator_is_active(p_operator_id) THEN
    RAISE EXCEPTION 'communications_operator_inactive' USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: communications_set_delivery_control(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_set_delivery_control(p_operator_id uuid, p_control_key text, p_enabled boolean) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_revision integer;
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  IF p_control_key IS NULL
     OR p_control_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$'
     OR p_enabled IS NULL THEN
    RAISE EXCEPTION 'communications_control_invalid' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.communication_delivery_controls(control_key, enabled)
  VALUES (p_control_key, p_enabled)
  ON CONFLICT (control_key) DO UPDATE
    SET enabled = EXCLUDED.enabled,
        revision = public.communication_delivery_controls.revision + 1,
        updated_at = now()
  RETURNING revision INTO v_revision;
  RETURN v_revision;
END;
$_$;


--
-- Name: communications_set_delivery_template(uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communications_set_delivery_template(p_operator_id uuid, p_template_reference text, p_control_key text, p_active boolean) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_revision integer;
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  IF p_template_reference IS NULL
     OR p_template_reference !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$'
     OR p_control_key IS NULL
     OR p_control_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$'
     OR p_active IS NULL THEN
    RAISE EXCEPTION 'communications_template_invalid' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.communication_delivery_controls
    WHERE control_key = p_control_key
  ) THEN
    RAISE EXCEPTION 'communications_control_not_found' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.communication_delivery_templates(
    template_reference, control_key, active
  ) VALUES (p_template_reference, p_control_key, p_active)
  ON CONFLICT (template_reference) DO UPDATE
    SET control_key = EXCLUDED.control_key,
        active = EXCLUDED.active,
        revision = public.communication_delivery_templates.revision + 1,
        updated_at = now()
  RETURNING revision INTO v_revision;
  RETURN v_revision;
END;
$_$;


--
-- Name: current_client_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_client_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT id FROM public.clients WHERE auth_user_id = auth.uid();
$$;


--
-- Name: FUNCTION current_client_id(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.current_client_id() IS 'Resolves the calling authenticated user (auth.uid()) to the owning clients.id, or NULL if no client is linked. SECURITY DEFINER + STABLE so the lookup runs once per statement with a fixed search_path, bypassing RLS on clients during the lookup itself (the partial unique index guarantees at most one row, so this returns at most one id). Used by every customer-ownership RLS policy.';


--
-- Name: customer_diagnostic_ingest_v1(text, text, uuid, uuid, uuid, uuid, text, text, text, integer, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_diagnostic_ingest_v1(p_presented_credential_hash text, p_issued_credential_hash text, p_principal_id uuid, p_subject_id uuid, p_client_event_key uuid, p_client_action_key uuid, p_action text, p_phase text, p_code text, p_duration_ms integer, p_reported_request_id text, p_ingest_request_id text, p_abuse_key_hash text, p_payload_fingerprint text, p_retention_days integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_segment public.customer_diagnostic_segments%ROWTYPE;
  v_existing public.customer_diagnostic_events%ROWTYPE;
  v_segment_id uuid;
  v_action_id uuid;
  v_disposition text := 'issued';
  v_global_count integer;
  v_bucket_count integer;
BEGIN
  IF p_issued_credential_hash IS NULL
     OR (p_principal_id IS NULL AND p_subject_id IS NOT NULL)
     OR p_client_event_key IS NULL
     OR p_action IS NULL OR p_phase IS NULL OR p_code IS NULL
     OR p_abuse_key_hash IS NULL OR p_payload_fingerprint IS NULL
     OR p_ingest_request_id IS NULL OR p_retention_days IS NULL
     OR p_issued_credential_hash !~ '^[0-9a-f]{64}$'
     OR (p_presented_credential_hash IS NOT NULL AND p_presented_credential_hash !~ '^[0-9a-f]{64}$')
     OR p_abuse_key_hash !~ '^[0-9a-f]{64}$'
     OR p_payload_fingerprint !~ '^[0-9a-f]{64}$'
     OR p_ingest_request_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
     OR (p_reported_request_id IS NOT NULL AND p_reported_request_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$')
     OR p_retention_days NOT BETWEEN 1 AND 90
     OR (p_duration_ms IS NOT NULL AND p_duration_ms NOT BETWEEN 0 AND 600000)
  THEN RAISE EXCEPTION 'customer_diagnostic_ingest_invalid' USING ERRCODE = '22023'; END IF;

  IF p_action NOT IN ('entry_boot','entry_hydration','route_render','configurator_enter','checkout_submit','payment_confirm','payment_status','auth_bootstrap','auth_magic_link','auth_otp','auth_oauth','account_mutation','account_refresh','account_card_setup')
     OR p_phase NOT IN ('entered','attempted','settled','refresh_started','refresh_settled')
     OR p_code NOT IN ('observed','succeeded','rejected','failed','unknown','timeout','transport_uncertain','retryable','hydration_failed','render_failed','session_present','session_absent','profile_unavailable','refresh_failed')
  THEN RAISE EXCEPTION 'customer_diagnostic_ingest_invalid' USING ERRCODE = '22023'; END IF;

  IF NOT (
    (p_action = 'entry_boot' AND ((p_phase = 'entered' AND p_code = 'observed') OR (p_phase = 'settled' AND p_code = 'failed'))) OR
    (p_action = 'configurator_enter' AND p_phase = 'entered' AND p_code = 'observed') OR
    (p_action = 'entry_hydration' AND ((p_phase = 'entered' AND p_code = 'observed') OR (p_phase = 'settled' AND p_code IN ('succeeded','hydration_failed')))) OR
    (p_action = 'route_render' AND p_phase = 'settled' AND p_code = 'render_failed') OR
    (p_action = 'auth_bootstrap' AND p_phase = 'settled' AND p_code IN ('session_present','session_absent','profile_unavailable','unknown','failed','timeout')) OR
    (p_action = 'account_refresh' AND p_client_action_key IS NOT NULL AND ((p_phase = 'refresh_started' AND p_code = 'observed') OR (p_phase = 'refresh_settled' AND p_code IN ('succeeded','refresh_failed')))) OR
    (p_action NOT IN ('entry_boot','entry_hydration','route_render','configurator_enter','auth_bootstrap','account_refresh') AND p_client_action_key IS NOT NULL AND ((p_phase = 'attempted' AND p_code = 'observed') OR (p_phase = 'settled' AND p_code IN ('succeeded','rejected','failed','unknown','timeout','transport_uncertain','retryable'))))
  ) THEN RAISE EXCEPTION 'customer_diagnostic_ingest_invalid' USING ERRCODE = '22023'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('customer-diagnostic-global', 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('customer-diagnostic-bucket:' || p_abuse_key_hash, 0));
  DELETE FROM public.customer_diagnostic_ingress_attempts
   WHERE id IN (SELECT id FROM public.customer_diagnostic_ingress_attempts WHERE occurred_at < v_now - interval '2 minutes' LIMIT 500);
  SELECT count(*) INTO v_global_count FROM public.customer_diagnostic_ingress_attempts WHERE occurred_at >= v_now - interval '1 minute';
  SELECT count(*) INTO v_bucket_count FROM public.customer_diagnostic_ingress_attempts WHERE abuse_key_hash = p_abuse_key_hash AND occurred_at >= v_now - interval '1 minute';
  IF v_global_count >= 3000 OR v_bucket_count >= 120 THEN
    RETURN jsonb_build_object('outcome','rate_limited');
  END IF;
  INSERT INTO public.customer_diagnostic_ingress_attempts(abuse_key_hash, occurred_at) VALUES (p_abuse_key_hash, v_now);

  IF p_presented_credential_hash IS NOT NULL THEN
    SELECT * INTO v_segment FROM public.customer_diagnostic_segments
     WHERE credential_hash = p_presented_credential_hash FOR UPDATE;
  END IF;

  IF v_segment.id IS NOT NULL AND v_segment.closed_at IS NULL AND v_segment.expires_at > v_now
     AND v_segment.principal_id IS NOT DISTINCT FROM p_principal_id
     AND v_segment.subject_id IS NOT DISTINCT FROM p_subject_id THEN
    v_segment_id := v_segment.id;
    v_disposition := 'reused';
  ELSE
    IF v_segment.id IS NOT NULL AND v_segment.closed_at IS NULL THEN
      UPDATE public.customer_diagnostic_segments SET
        closed_at = v_now,
        close_reason = CASE WHEN v_segment.expires_at <= v_now THEN 'expired' WHEN p_principal_id IS NULL THEN 'logout' ELSE 'auth_changed' END
      WHERE id = v_segment.id;
    END IF;
    INSERT INTO public.customer_diagnostic_segments(
      credential_hash, principal_id, subject_id, predecessor_segment_id, predecessor_relation, started_at, last_seen_at, expires_at
    ) VALUES (
      p_issued_credential_hash,
      p_principal_id,
      p_subject_id,
      CASE WHEN v_segment.id IS NOT NULL AND v_segment.closed_at IS NULL AND v_segment.expires_at > v_now AND v_segment.principal_id IS NULL AND p_principal_id IS NOT NULL THEN v_segment.id END,
      CASE WHEN v_segment.id IS NOT NULL AND v_segment.closed_at IS NULL AND v_segment.expires_at > v_now AND v_segment.principal_id IS NULL AND p_principal_id IS NOT NULL THEN 'same_tab_pre_auth_context' END,
      v_now, v_now, v_now + make_interval(days => p_retention_days)
    ) RETURNING id INTO v_segment_id;
  END IF;

  SELECT * INTO v_existing FROM public.customer_diagnostic_events
   WHERE segment_id = v_segment_id AND client_event_key = p_client_event_key FOR UPDATE;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.payload_fingerprint <> p_payload_fingerprint OR v_existing.coverage_version <> 'purchase-auth-account.v1' THEN
      RAISE EXCEPTION 'customer_diagnostic_event_conflict' USING ERRCODE = '23505';
    END IF;
    RETURN jsonb_build_object('outcome','committed','credentialDisposition',v_disposition,
      'deduplicated',true,'segmentId',v_segment_id,'actionId',v_existing.action_id);
  END IF;

  IF (SELECT count(*) FROM public.customer_diagnostic_events WHERE segment_id = v_segment_id AND received_at >= v_now - interval '1 minute') >= 20 THEN
    RETURN jsonb_build_object('outcome','rate_limited');
  END IF;

  IF p_client_action_key IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('customer-diagnostic-action:' || v_segment_id::text || ':' || p_client_action_key::text, 0));
    SELECT action_id INTO v_action_id FROM public.customer_diagnostic_events
     WHERE segment_id = v_segment_id AND client_action_key = p_client_action_key AND action_id IS NOT NULL
     ORDER BY received_at, id LIMIT 1;
    v_action_id := COALESCE(v_action_id, gen_random_uuid());
  END IF;

  INSERT INTO public.customer_diagnostic_events(
    segment_id, action_id, client_event_key, client_action_key, payload_fingerprint,
    action, phase, code, duration_ms, reported_request_id, ingest_request_id, received_at, expires_at
  ) VALUES (
    v_segment_id, v_action_id, p_client_event_key, p_client_action_key, p_payload_fingerprint,
    p_action, p_phase, p_code, p_duration_ms, p_reported_request_id, p_ingest_request_id,
    v_now, v_now + make_interval(days => p_retention_days)
  );
  UPDATE public.customer_diagnostic_segments SET last_seen_at = v_now,
    expires_at = GREATEST(expires_at, v_now + make_interval(days => p_retention_days)) WHERE id = v_segment_id;
  RETURN jsonb_build_object('outcome','committed','credentialDisposition',v_disposition,
    'deduplicated',false,'segmentId',v_segment_id,'actionId',v_action_id);
END;
$_$;


--
-- Name: customer_diagnostic_ingest_v2(text, text, uuid, uuid, uuid, uuid, text, text, text, integer, text, text, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_diagnostic_ingest_v2(p_presented_credential_hash text, p_issued_credential_hash text, p_principal_id uuid, p_subject_id uuid, p_client_event_key uuid, p_client_action_key uuid, p_action text, p_phase text, p_code text, p_duration_ms integer, p_reported_request_id text, p_ingest_request_id text, p_abuse_key_hash text, p_payload_fingerprint text, p_retention_days integer, p_coverage_version text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_segment public.customer_diagnostic_segments%ROWTYPE;
  v_existing public.customer_diagnostic_events%ROWTYPE;
  v_segment_id uuid;
  v_segment_started_at timestamptz;
  v_action_id uuid;
  v_disposition text := 'issued';
  v_global_count integer;
  v_bucket_count integer;
BEGIN
  IF p_issued_credential_hash IS NULL
     OR (p_principal_id IS NULL AND p_subject_id IS NOT NULL)
     OR p_client_event_key IS NULL
     OR p_action IS NULL OR p_phase IS NULL OR p_code IS NULL
     OR p_abuse_key_hash IS NULL OR p_payload_fingerprint IS NULL
     OR p_ingest_request_id IS NULL OR p_retention_days IS NULL
     OR p_coverage_version IS DISTINCT FROM 'purchase-auth-account.v2'
     OR p_issued_credential_hash !~ '^[0-9a-f]{64}$'
     OR (p_presented_credential_hash IS NOT NULL AND p_presented_credential_hash !~ '^[0-9a-f]{64}$')
     OR p_abuse_key_hash !~ '^[0-9a-f]{64}$'
     OR p_payload_fingerprint !~ '^[0-9a-f]{64}$'
     OR p_ingest_request_id !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
     OR (p_reported_request_id IS NOT NULL AND NOT (
          p_reported_request_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
          OR p_reported_request_id ~ '^bff-axiom-canary-[a-z0-9-]{1,96}$'
          OR p_reported_request_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,31}(?:::[A-Za-z0-9._-]{1,32}){1,3}$'))
     OR p_retention_days NOT BETWEEN 1 AND 90
     OR (p_duration_ms IS NOT NULL AND p_duration_ms NOT BETWEEN 0 AND 600000)
  THEN RAISE EXCEPTION 'customer_diagnostic_ingest_invalid' USING ERRCODE = '22023'; END IF;

  IF p_action NOT IN ('entry_boot','entry_hydration','route_render','configurator_enter','checkout_submit','payment_confirm','payment_status','auth_bootstrap','auth_magic_link','auth_otp','auth_oauth','account_mutation','account_refresh','account_card_setup','configurator_gate','checkout_recovery_submit','checkout_recovery_readback','checkout_recovery_hatch','auth_callback','account_subscription_mutation','account_profile_mutation','account_companion_mutation','account_address_mutation','account_billing_mutation','account_delivery_mutation','account_payment_mutation','account_communication_mutation')
     OR p_phase NOT IN ('entered','attempted','settled','refresh_started','refresh_settled')
     OR p_code NOT IN ('observed','succeeded','rejected','failed','unknown','timeout','transport_uncertain','retryable','hydration_failed','render_failed','session_present','session_absent','profile_unavailable','refresh_failed','validation_blocked','quote_unavailable','callback_invalid','callback_expired')
  THEN RAISE EXCEPTION 'customer_diagnostic_ingest_invalid' USING ERRCODE = '22023'; END IF;

  IF NOT (
    (p_action = 'entry_boot' AND ((p_phase = 'entered' AND p_code = 'observed') OR (p_phase = 'settled' AND p_code = 'failed'))) OR
    (p_action = 'configurator_enter' AND p_phase = 'entered' AND p_code = 'observed') OR
    (p_action = 'entry_hydration' AND ((p_phase = 'entered' AND p_code = 'observed') OR (p_phase = 'settled' AND p_code = 'hydration_failed'))) OR
    (p_action = 'route_render' AND p_phase = 'settled' AND p_code = 'render_failed') OR
    (p_action = 'auth_bootstrap' AND p_phase = 'settled' AND p_code IN ('session_present','session_absent','profile_unavailable','unknown','failed','timeout')) OR
    (p_action = 'account_refresh' AND p_client_action_key IS NOT NULL AND ((p_phase = 'refresh_started' AND p_code = 'observed') OR (p_phase = 'refresh_settled' AND p_code IN ('succeeded','refresh_failed')))) OR
    (p_action = 'auth_callback' AND p_phase = 'settled' AND p_code IN ('succeeded','callback_invalid','callback_expired','failed','unknown','timeout','transport_uncertain')) OR
    (p_action NOT IN ('entry_boot','entry_hydration','route_render','configurator_enter','auth_bootstrap','account_refresh','auth_callback') AND p_client_action_key IS NOT NULL AND ((p_phase = 'attempted' AND p_code = 'observed') OR (p_phase = 'settled' AND p_code IN ('succeeded','rejected','failed','unknown','timeout','transport_uncertain','retryable','validation_blocked','quote_unavailable'))))
  ) THEN RAISE EXCEPTION 'customer_diagnostic_ingest_invalid' USING ERRCODE = '22023'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('customer-diagnostic-global', 0));
  PERFORM pg_advisory_xact_lock(hashtextextended('customer-diagnostic-bucket:' || p_abuse_key_hash, 0));
  DELETE FROM public.customer_diagnostic_ingress_attempts
   WHERE id IN (SELECT id FROM public.customer_diagnostic_ingress_attempts WHERE occurred_at < v_now - interval '2 minutes' LIMIT 500);
  SELECT count(*) INTO v_global_count FROM public.customer_diagnostic_ingress_attempts WHERE occurred_at >= v_now - interval '1 minute';
  SELECT count(*) INTO v_bucket_count FROM public.customer_diagnostic_ingress_attempts WHERE abuse_key_hash = p_abuse_key_hash AND occurred_at >= v_now - interval '1 minute';
  IF v_global_count >= 3000 OR v_bucket_count >= 120 THEN RETURN jsonb_build_object('outcome','rate_limited'); END IF;
  INSERT INTO public.customer_diagnostic_ingress_attempts(abuse_key_hash, occurred_at) VALUES (p_abuse_key_hash, v_now);

  IF p_presented_credential_hash IS NOT NULL THEN
    SELECT * INTO v_segment FROM public.customer_diagnostic_segments WHERE credential_hash = p_presented_credential_hash FOR UPDATE;
  END IF;
  IF v_segment.id IS NOT NULL AND v_segment.closed_at IS NULL AND v_segment.expires_at > v_now
     AND v_segment.principal_id IS NOT DISTINCT FROM p_principal_id
     AND v_segment.subject_id IS NOT DISTINCT FROM p_subject_id THEN
    v_segment_id := v_segment.id;
    v_segment_started_at := v_segment.started_at;
    v_disposition := 'reused';
  ELSE
    IF v_segment.id IS NOT NULL AND v_segment.closed_at IS NULL THEN
      UPDATE public.customer_diagnostic_segments SET closed_at = v_now,
        close_reason = CASE WHEN v_segment.expires_at <= v_now THEN 'expired' WHEN p_principal_id IS NULL THEN 'logout' ELSE 'auth_changed' END
      WHERE id = v_segment.id;
    END IF;
    INSERT INTO public.customer_diagnostic_segments(
      credential_hash, principal_id, subject_id, predecessor_segment_id, predecessor_relation, started_at, last_seen_at, expires_at
    ) VALUES (
      p_issued_credential_hash, p_principal_id, p_subject_id,
      CASE WHEN v_segment.id IS NOT NULL AND v_segment.closed_at IS NULL AND v_segment.expires_at > v_now AND v_segment.principal_id IS NULL AND p_principal_id IS NOT NULL THEN v_segment.id END,
      CASE WHEN v_segment.id IS NOT NULL AND v_segment.closed_at IS NULL AND v_segment.expires_at > v_now AND v_segment.principal_id IS NULL AND p_principal_id IS NOT NULL THEN 'same_tab_pre_auth_context' END,
      v_now, v_now, v_now + make_interval(days => p_retention_days)
    ) RETURNING id, started_at INTO v_segment_id, v_segment_started_at;
  END IF;

  SELECT * INTO v_existing FROM public.customer_diagnostic_events
   WHERE segment_id = v_segment_id AND client_event_key = p_client_event_key FOR UPDATE;
  IF v_existing.id IS NOT NULL THEN
    IF v_existing.payload_fingerprint <> p_payload_fingerprint OR v_existing.coverage_version <> p_coverage_version THEN RAISE EXCEPTION 'customer_diagnostic_event_conflict' USING ERRCODE = '23505'; END IF;
    RETURN jsonb_build_object('outcome','committed','credentialDisposition',v_disposition,
      'deduplicated',true,'segmentId',v_segment_id,'actionId',v_existing.action_id);
  END IF;
  IF (SELECT count(*) FROM public.customer_diagnostic_events WHERE segment_id = v_segment_id AND received_at >= v_now - interval '1 minute') >= 20 THEN
    RETURN jsonb_build_object('outcome','rate_limited');
  END IF;
  IF p_client_action_key IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('customer-diagnostic-action:' || v_segment_id::text || ':' || p_client_action_key::text, 0));
    SELECT action_id INTO v_action_id FROM public.customer_diagnostic_events
     WHERE segment_id = v_segment_id AND client_action_key = p_client_action_key AND action_id IS NOT NULL
     ORDER BY received_at, id LIMIT 1;
    v_action_id := COALESCE(v_action_id, gen_random_uuid());
  END IF;
  INSERT INTO public.customer_diagnostic_events(
    segment_id, action_id, client_event_key, client_action_key, payload_fingerprint, coverage_version,
    action, phase, code, duration_ms, reported_request_id, ingest_request_id, received_at, expires_at
  ) VALUES (
    v_segment_id, v_action_id, p_client_event_key, p_client_action_key, p_payload_fingerprint, p_coverage_version,
    p_action, p_phase, p_code, p_duration_ms, p_reported_request_id, p_ingest_request_id,
    v_now, LEAST(v_segment_started_at + make_interval(days => p_retention_days), v_now + make_interval(days => p_retention_days))
  );
  -- One committed, non-duplicate reuse retires the credential the browser presented.
  -- Both early returns above (replay, per-segment limit) leave the live tab's credential
  -- in place, because the reporter only stores a credential the server returned with a 2xx.
  UPDATE public.customer_diagnostic_segments SET last_seen_at = v_now,
    credential_hash = CASE WHEN v_disposition = 'reused' THEN p_issued_credential_hash ELSE credential_hash END,
    expires_at = LEAST(started_at + make_interval(days => p_retention_days),
      GREATEST(expires_at, v_now + make_interval(days => p_retention_days)))
  WHERE id = v_segment_id;
  IF v_disposition = 'reused' THEN v_disposition := 'rotated'; END IF;
  RETURN jsonb_build_object('outcome','committed','credentialDisposition',v_disposition,
    'deduplicated',false,'segmentId',v_segment_id,'actionId',v_action_id);
END;
$_$;


--
-- Name: customer_diagnostic_overview_v2(uuid, timestamp with time zone, timestamp with time zone, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_diagnostic_overview_v2(p_operator_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_page_size integer, p_cursor text, p_retention_days integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_offset integer := 0;
  v_group_total integer;
  v_groups jsonb;
  v_retained_from timestamptz;
  v_retention_boundary timestamptz;
  -- The observation-only actions, declared once. An action belongs here when the
  -- coverage inventory records it as observed with no attempted or refresh-started
  -- lifecycle, so it can never carry an attempted-to-terminal rate.
  v_static_actions text[] := ARRAY[
    'entry_boot','entry_hydration','route_render','configurator_enter',
    'auth_bootstrap','auth_callback','payment_confirm','payment_status'
  ];
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);

  IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from
     OR p_to - p_from > interval '7 days'
     OR p_page_size IS NULL OR p_page_size NOT BETWEEN 1 AND 25
     OR p_retention_days IS NULL OR p_retention_days NOT BETWEEN 1 AND 90
  THEN
    RAISE EXCEPTION 'customer_diagnostic_overview_invalid' USING ERRCODE = '22023';
  END IF;

  IF p_cursor IS NOT NULL THEN
    IF p_cursor !~ '^[0-9]{1,7}$' THEN
      RAISE EXCEPTION 'customer_diagnostic_cursor_invalid' USING ERRCODE = '22023';
    END IF;
    v_offset := p_cursor::integer;
  END IF;

  v_retention_boundary := v_now - make_interval(days => p_retention_days);

  SELECT min(e.received_at)
    INTO v_retained_from
    FROM public.customer_diagnostic_events e
    JOIN public.customer_diagnostic_segments s ON s.id = e.segment_id
   WHERE e.expires_at > v_now
     AND s.expires_at > v_now;

  WITH matching AS MATERIALIZED (
    SELECT e.segment_id, e.action_id, e.coverage_version,
      e.action, e.phase, e.code, e.received_at
      FROM public.customer_diagnostic_events e
      JOIN public.customer_diagnostic_segments s ON s.id = e.segment_id
     WHERE e.received_at >= p_from
       AND e.received_at < p_to
       AND e.expires_at > v_now
       AND s.expires_at > v_now
  ), group_keys AS MATERIALIZED (
    SELECT DISTINCT coverage_version, action
      FROM matching
  ), group_page AS MATERIALIZED (
    SELECT coverage_version, action
      FROM group_keys
     ORDER BY coverage_version, action
     OFFSET v_offset
     LIMIT p_page_size
  ), action_states AS MATERIALIZED (
    SELECT p.coverage_version, p.action, e.action_id,
      (array_agg(e.segment_id::text ORDER BY e.received_at DESC, e.segment_id DESC))[1] AS segment_id,
      max(e.received_at) AS last_seen_at,
      bool_or(e.phase = CASE WHEN p.action = 'account_refresh'
        THEN 'refresh_started' ELSE 'attempted' END) AS has_start,
      count(DISTINCT COALESCE(e.code, 'unknown')) FILTER (
        WHERE e.phase = CASE WHEN p.action = 'account_refresh'
          THEN 'refresh_settled' ELSE 'settled' END
      ) AS terminal_code_count,
      min(COALESCE(e.code, 'unknown')) FILTER (
        WHERE e.phase = CASE WHEN p.action = 'account_refresh'
          THEN 'refresh_settled' ELSE 'settled' END
      ) AS terminal_code
      FROM group_page p
      JOIN matching e
        ON e.coverage_version = p.coverage_version
       AND e.action = p.action
     WHERE p.action <> ALL (v_static_actions)
       AND e.action_id IS NOT NULL
     GROUP BY p.coverage_version, p.action, e.action_id
  ), classified_actions AS MATERIALIZED (
    SELECT coverage_version, action, action_id, segment_id, last_seen_at,
      has_start,
      CASE
        WHEN NOT has_start AND terminal_code_count > 0 THEN 'terminalWithoutStart'
        WHEN has_start AND terminal_code_count = 0 THEN 'observation_gap'
        WHEN has_start AND terminal_code_count > 1 THEN 'conflicting_terminal'
        WHEN has_start AND terminal_code_count = 1 THEN terminal_code
      END AS classification
      FROM action_states
     WHERE has_start OR terminal_code_count > 0
  ), bucket_counts AS MATERIALIZED (
    SELECT coverage_version, action, classification,
      count(*)::integer AS action_count
      FROM classified_actions
     WHERE classification IS NOT NULL
     GROUP BY coverage_version, action, classification
  ), bucket_examples AS MATERIALIZED (
    SELECT coverage_version, action, classification, segment_id,
      max(last_seen_at) AS last_seen_at
      FROM classified_actions
     WHERE classification IS NOT NULL
     GROUP BY coverage_version, action, classification, segment_id
  ), bucket_rows AS MATERIALIZED (
    SELECT b.coverage_version, b.action, b.classification, b.action_count,
      to_jsonb(
        (array_agg(x.segment_id ORDER BY x.last_seen_at DESC, x.segment_id DESC))[1:3]
      ) AS example_segment_ids
      FROM bucket_counts b
      JOIN bucket_examples x
        ON x.coverage_version = b.coverage_version
       AND x.action = b.action
       AND x.classification = b.classification
     GROUP BY b.coverage_version, b.action, b.classification, b.action_count
  ), static_counts AS MATERIALIZED (
    SELECT p.coverage_version, p.action, e.phase, COALESCE(e.code, 'unknown') AS code,
      count(*)::integer AS event_count,
      NULLIF(count(DISTINCT e.action_id), 0)::integer AS action_count
      FROM group_page p
      JOIN matching e
        ON e.coverage_version = p.coverage_version
       AND e.action = p.action
     WHERE p.action = ANY (v_static_actions)
     GROUP BY p.coverage_version, p.action, e.phase, COALESCE(e.code, 'unknown')
  ), static_examples AS MATERIALIZED (
    SELECT p.coverage_version, p.action, e.phase, COALESCE(e.code, 'unknown') AS code,
      e.segment_id::text AS segment_id, max(e.received_at) AS last_seen_at
      FROM group_page p
      JOIN matching e
        ON e.coverage_version = p.coverage_version
       AND e.action = p.action
     WHERE p.action = ANY (v_static_actions)
     GROUP BY p.coverage_version, p.action, e.phase, COALESCE(e.code, 'unknown'), e.segment_id
  ), static_rows AS MATERIALIZED (
    SELECT s.coverage_version, s.action, s.phase, s.code, s.event_count, s.action_count,
      to_jsonb(
        (array_agg(x.segment_id ORDER BY x.last_seen_at DESC, x.segment_id DESC))[1:3]
      ) AS example_segment_ids
      FROM static_counts s
      JOIN static_examples x
        ON x.coverage_version = s.coverage_version
       AND x.action = s.action
       AND x.phase = s.phase
       AND x.code = s.code
     GROUP BY s.coverage_version, s.action, s.phase, s.code, s.event_count, s.action_count
  ), group_rows AS (
    SELECT p.coverage_version, p.action,
      jsonb_build_object(
        'coverageVersion', p.coverage_version,
        'action', p.action,
        'rateApplicability', CASE WHEN p.action = ANY (v_static_actions)
          THEN 'not_applicable' ELSE 'applicable' END,
        'attemptedActionCount', CASE WHEN p.action = ANY (v_static_actions)
          THEN NULL ELSE (
          SELECT count(*)::integer
            FROM action_states a
           WHERE a.coverage_version = p.coverage_version
             AND a.action = p.action
             AND a.has_start
        ) END,
        'terminalOutcomes', CASE WHEN p.action = ANY (v_static_actions)
          THEN '[]'::jsonb ELSE COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'classification', b.classification,
            'actionCount', b.action_count,
            'exampleSegmentIds', b.example_segment_ids
          ) ORDER BY
            CASE b.classification
              WHEN 'observation_gap' THEN 0
              WHEN 'conflicting_terminal' THEN 1
              WHEN 'terminalWithoutStart' THEN 2
              ELSE 3
            END,
            b.classification
          )
            FROM bucket_rows b
           WHERE b.coverage_version = p.coverage_version
             AND b.action = p.action
        ), '[]'::jsonb) END,
        'staticLifecycle', CASE WHEN p.action = ANY (v_static_actions)
          THEN COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'phase', s.phase,
            'code', s.code,
            'eventCount', s.event_count,
            'actionCount', s.action_count,
            'exampleSegmentIds', s.example_segment_ids
          ) ORDER BY s.phase, s.code)
            FROM static_rows s
           WHERE s.coverage_version = p.coverage_version
             AND s.action = p.action
        ), '[]'::jsonb) ELSE '[]'::jsonb END
      ) AS payload
      FROM group_page p
  )
  SELECT
    (SELECT count(*)::integer FROM group_keys),
    COALESCE((SELECT jsonb_agg(payload ORDER BY coverage_version, action) FROM group_rows), '[]'::jsonb)
    INTO v_group_total, v_groups;

  INSERT INTO public.customer_diagnostic_access_events(
    operator_id, operation, filter_from, filter_to, occurred_at, expires_at
  ) VALUES (
    p_operator_id, 'overview', p_from, p_to, v_now,
    v_now + make_interval(days => p_retention_days)
  );

  RETURN jsonb_build_object(
    'contractVersion','customer-diagnostic-history.v2',
    'sourceHealth',jsonb_build_object('read','available','delivery','unknown'),
    'loss',jsonb_build_object('status','unknown','reason','browser_delivery_not_measurable'),
    'windowCoverage',CASE
      WHEN p_to <= v_retention_boundary THEN 'expired'
      WHEN p_from < v_retention_boundary THEN 'partial'
      ELSE 'full'
    END,
    'evidencePresence',CASE WHEN v_group_total = 0 THEN 'empty' ELSE 'observed' END,
    'retainedFrom',v_retained_from,
    'truncated',v_group_total > v_offset + p_page_size,
    'nextCursor',CASE WHEN v_group_total > v_offset + p_page_size
      THEN (v_offset + p_page_size)::text END,
    'groups',v_groups
  );
END;
$_$;


--
-- Name: customer_diagnostic_prune_v1(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_diagnostic_prune_v1(p_batch_size integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_events integer := 0;
  v_segments integer := 0;
  v_limits integer := 0;
  v_access integer := 0;
BEGIN
  IF p_batch_size IS NULL OR p_batch_size NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'customer_diagnostic_prune_invalid' USING ERRCODE = '22023';
  END IF;
  WITH doomed AS (SELECT id FROM public.customer_diagnostic_events WHERE expires_at <= clock_timestamp() ORDER BY expires_at LIMIT p_batch_size),
  deleted AS (DELETE FROM public.customer_diagnostic_events e USING doomed d WHERE e.id = d.id RETURNING 1)
  SELECT count(*) INTO v_events FROM deleted;
  WITH doomed AS (SELECT id FROM public.customer_diagnostic_access_events WHERE expires_at <= clock_timestamp() ORDER BY expires_at LIMIT p_batch_size),
  deleted AS (DELETE FROM public.customer_diagnostic_access_events a USING doomed d WHERE a.id = d.id RETURNING 1)
  SELECT count(*) INTO v_access FROM deleted;
  WITH doomed AS (SELECT id FROM public.customer_diagnostic_ingress_attempts WHERE occurred_at < clock_timestamp() - interval '2 minutes' ORDER BY occurred_at LIMIT p_batch_size),
  deleted AS (DELETE FROM public.customer_diagnostic_ingress_attempts a USING doomed d WHERE a.id = d.id RETURNING 1)
  SELECT count(*) INTO v_limits FROM deleted;
  WITH doomed AS (
    SELECT s.id FROM public.customer_diagnostic_segments s WHERE s.expires_at <= clock_timestamp()
      AND NOT EXISTS (SELECT 1 FROM public.customer_diagnostic_events e WHERE e.segment_id = s.id)
    ORDER BY s.expires_at LIMIT p_batch_size
  ), deleted AS (DELETE FROM public.customer_diagnostic_segments s USING doomed d WHERE s.id = d.id RETURNING 1)
  SELECT count(*) INTO v_segments FROM deleted;
  RETURN jsonb_build_object('eventsDeleted',v_events,'segmentsDeleted',v_segments,
    'limitsDeleted',v_limits,'accessDeleted',v_access);
END;
$$;


--
-- Name: customer_diagnostic_search_v1(uuid, timestamp with time zone, timestamp with time zone, uuid, text, text, text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_diagnostic_search_v1(p_operator_id uuid, p_from timestamp with time zone, p_to timestamp with time zone, p_subject_id uuid, p_action text, p_phase text, p_code text, p_page_size integer, p_cursor text, p_retention_days integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_offset integer := 0;
  v_total integer;
  v_group_total integer;
  v_groups jsonb;
  v_segments jsonb;
  v_retained_from timestamptz;
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);
  IF p_from IS NULL OR p_to IS NULL OR p_to <= p_from OR p_to - p_from > interval '7 days'
     OR p_page_size IS NULL OR p_page_size NOT BETWEEN 1 AND 25
     OR p_retention_days IS NULL OR p_retention_days NOT BETWEEN 1 AND 90
     OR (p_action IS NOT NULL AND p_action NOT IN ('entry_boot','entry_hydration','route_render','configurator_enter','checkout_submit','payment_confirm','payment_status','auth_bootstrap','auth_magic_link','auth_otp','auth_oauth','account_mutation','account_refresh','account_card_setup'))
     OR (p_phase IS NOT NULL AND p_phase NOT IN ('entered','attempted','settled','refresh_started','refresh_settled'))
     OR (p_code IS NOT NULL AND p_code NOT IN ('observed','succeeded','rejected','failed','unknown','timeout','transport_uncertain','retryable','hydration_failed','render_failed','session_present','session_absent','profile_unavailable','refresh_failed'))
  THEN RAISE EXCEPTION 'customer_diagnostic_search_invalid' USING ERRCODE = '22023'; END IF;
  IF p_cursor IS NOT NULL THEN
    IF p_cursor !~ '^[0-9]{1,7}$' THEN RAISE EXCEPTION 'customer_diagnostic_cursor_invalid' USING ERRCODE = '22023'; END IF;
    v_offset := p_cursor::integer;
  END IF;

  WITH matching AS (
    SELECT e.* FROM public.customer_diagnostic_events e
    JOIN public.customer_diagnostic_segments s ON s.id = e.segment_id
    WHERE e.received_at >= p_from AND e.received_at < p_to AND e.expires_at > v_now
      AND s.expires_at > v_now
      AND e.coverage_version = 'purchase-auth-account.v1'
      AND (p_subject_id IS NULL OR s.subject_id = p_subject_id)
      AND (p_action IS NULL OR e.action = p_action)
      AND (p_phase IS NULL OR e.phase = p_phase)
      AND (p_code IS NULL OR e.code = p_code)
  ), grouped AS (
    SELECT action, phase, code, count(*)::integer event_count,
      count(DISTINCT action_id)::integer action_count,
      count(DISTINCT segment_id)::integer segment_count
    FROM matching GROUP BY action, phase, code
  ), top_groups AS (
    SELECT * FROM grouped ORDER BY event_count DESC, action, phase, code NULLS FIRST LIMIT 100
  )
  SELECT (SELECT count(*) FROM grouped), COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'action', action, 'phase', phase, 'code', code, 'eventCount', event_count,
      'actionCount', action_count, 'segmentCount', segment_count
    ) ORDER BY event_count DESC, action, phase, code NULLS FIRST) FROM top_groups), '[]'::jsonb)
  INTO v_group_total, v_groups;

  WITH matching AS (
    SELECT e.* FROM public.customer_diagnostic_events e
    JOIN public.customer_diagnostic_segments s ON s.id = e.segment_id
    WHERE e.received_at >= p_from AND e.received_at < p_to AND e.expires_at > v_now
      AND s.expires_at > v_now
      AND e.coverage_version = 'purchase-auth-account.v1'
      AND (p_subject_id IS NULL OR s.subject_id = p_subject_id)
      AND (p_action IS NULL OR e.action = p_action)
      AND (p_phase IS NULL OR e.phase = p_phase)
      AND (p_code IS NULL OR e.code = p_code)
  ), summaries AS (
    SELECT s.id segment_id, s.principal_id, s.subject_id, min(m.received_at) first_seen_at,
      max(m.received_at) last_seen_at, count(*)::integer event_count,
      count(DISTINCT m.action_id)::integer action_count
    FROM matching m JOIN public.customer_diagnostic_segments s ON s.id = m.segment_id
    GROUP BY s.id, s.principal_id, s.subject_id
  ), page AS (
    SELECT * FROM summaries ORDER BY last_seen_at DESC, segment_id DESC OFFSET v_offset LIMIT p_page_size
  )
  SELECT (SELECT count(*) FROM summaries), COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'segmentId', segment_id, 'attribution', CASE WHEN principal_id IS NULL THEN 'anonymous' ELSE 'account_verified' END,
      'subjectId', subject_id, 'firstSeenAt', first_seen_at, 'lastSeenAt', last_seen_at,
      'eventCount', event_count, 'actionCount', action_count
    ) ORDER BY last_seen_at DESC, segment_id DESC) FROM page), '[]'::jsonb)
  INTO v_total, v_segments;

  SELECT min(received_at) INTO v_retained_from FROM public.customer_diagnostic_events
   WHERE expires_at > v_now AND coverage_version = 'purchase-auth-account.v1';
  INSERT INTO public.customer_diagnostic_access_events(
    operator_id, operation, subject_id, filter_from, filter_to, action, phase, code, occurred_at, expires_at
  ) VALUES (p_operator_id, 'search', p_subject_id, p_from, p_to, p_action, p_phase, p_code,
    v_now, v_now + make_interval(days => p_retention_days));
  RETURN jsonb_build_object(
    'contractVersion','customer-diagnostic-history.v1','coverageVersion','purchase-auth-account.v1',
    'sourceHealth',jsonb_build_object('read','available','delivery','unknown'),
    'loss',jsonb_build_object('status','unknown','reason','browser_delivery_not_measurable'),
    'retainedFrom',v_retained_from,'truncated',(v_total > v_offset + p_page_size OR v_group_total > 100),
    'nextCursor',CASE WHEN v_total > v_offset + p_page_size THEN (v_offset + p_page_size)::text END,
    'groups',v_groups,'segments',v_segments
  );
END;
$_$;


