--
-- Name: customer_self_service_accept_subscription_quote_preview(uuid, uuid, text, text, integer, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_accept_subscription_quote_preview(p_auth_user_id uuid, p_subscription_id uuid, p_action text, p_quote_hash text, p_template_version integer, p_idempotency_key text, p_requested_at timestamp with time zone, p_apply_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_client_id uuid;
  v_subscription public.subscriptions%ROWTYPE;
  v_quote public.subscription_quote_previews%ROWTYPE;
BEGIN
  IF p_action NOT IN ('add_addon', 'remove_addon', 'update_addon_quantity',
                      'swap_recipe', 'update_plan_length', 'update_recipe_mix',
                      'set_portion_mode', 'update_package_template',
                      'update_bundle', 'resize_bundle')
  THEN
    RAISE EXCEPTION 'customer_self_service_invalid_action';
  END IF;
  IF p_quote_hash IS NULL OR p_quote_hash !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'customer_self_service_quote_not_accepted';
  END IF;
  IF p_template_version IS NULL OR p_template_version <= 0 THEN
    RAISE EXCEPTION 'customer_self_service_stale_edit';
  END IF;
  IF p_idempotency_key IS NULL OR char_length(trim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'customer_self_service_invalid_idempotency_key';
  END IF;

  SELECT id INTO v_client_id
    FROM public.clients
   WHERE auth_user_id = p_auth_user_id;
  IF v_client_id IS NULL THEN
    RAISE EXCEPTION 'customer_self_service_not_found';
  END IF;

  SELECT * INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
     AND client_id = v_client_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer_self_service_forbidden';
  END IF;
  IF v_subscription.template_version <> p_template_version THEN
    RAISE EXCEPTION 'customer_self_service_stale_edit';
  END IF;

  SELECT * INTO v_quote
    FROM public.subscription_quote_previews
   WHERE subscription_id = p_subscription_id
     AND client_id = v_client_id
     AND action = p_action
     AND quote_hash = p_quote_hash
     AND template_version = p_template_version
   ORDER BY created_at DESC
   LIMIT 1
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer_self_service_quote_not_accepted';
  END IF;

  IF v_quote.expires_at <= p_requested_at THEN
    RAISE EXCEPTION 'customer_self_service_quote_expired';
  END IF;

  IF v_quote.accepted_at IS NOT NULL THEN
    IF v_quote.accepted_idempotency_key = p_idempotency_key THEN
      RETURN v_quote.id;
    END IF;
    RAISE EXCEPTION 'customer_self_service_quote_already_used';
  END IF;

  PERFORM public.customer_self_service_assert_subscription_quote_payload(
    p_action,
    COALESCE(p_apply_payload, '{}'::jsonb),
    COALESCE(v_quote.request_payload, '{}'::jsonb),
    COALESCE(v_quote.quote_snapshot, '{}'::jsonb),
    COALESCE(v_quote.totals, '{}'::jsonb)
  );

  UPDATE public.subscription_quote_previews
     SET status = 'accepted',
         accepted_at = p_requested_at,
         accepted_idempotency_key = p_idempotency_key,
         updated_at = p_requested_at
   WHERE id = v_quote.id
   RETURNING * INTO v_quote;

  RETURN v_quote.id;
END;
$_$;


--
-- Name: customer_self_service_apply_action_before_address_ownership(uuid, text, uuid, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_apply_action_before_address_ownership(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb, p_requested_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_client_id uuid; v_event_id uuid; v_next_cycle_at timestamptz; v_edit_cutoff timestamptz;
  v_variant_id uuid; v_from_variant_id uuid; v_to_variant_id uuid; v_new_line_id uuid; v_price_line_id uuid;
  v_qty integer; v_unit_price integer; v_plan_days integer; v_current_recipe_total integer; v_desired_total integer;
  v_rs_ord bigint; v_rs_variant uuid; v_rs_qty integer; v_pause_ends_at timestamptz;
  v_shipping_address_id uuid; v_address_kind text;
  v_portion_mode text; v_portion_factor numeric;
  v_quote_preview_id uuid;
  v_subscription public.subscriptions%ROWTYPE;
  v_existing_event public.subscription_events%ROWTYPE;
  v_payload jsonb := COALESCE(p_payload, '{}'::jsonb);
  v_reason text := NULLIF(v_payload->>'reason', '');
  v_repriced jsonb := v_payload->'repricedLines';
  v_recipe_lines jsonb := v_payload->'recipeLines';
  v_core_lines jsonb := v_payload->'coreLines';
  v_selected_core_lines jsonb;
  v_addon_lines jsonb := COALESCE(v_payload->'addonLines', '[]'::jsonb);
  v_composition_constraint jsonb := v_payload->'compositionConstraint';
  v_quote_line jsonb;
  v_rl_elem jsonb;
  v_rs_elem jsonb;
  v_pause_preset text := COALESCE(NULLIF(v_payload->>'pausePreset', ''), 'indefinite');
  v_rewrite_addon_lines boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR char_length(trim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'customer_self_service_invalid_idempotency_key';
  END IF;

  SELECT id INTO v_client_id FROM public.clients WHERE auth_user_id = p_auth_user_id;
  IF v_client_id IS NULL THEN RAISE EXCEPTION 'customer_self_service_not_found'; END IF;

  SELECT * INTO v_subscription FROM public.subscriptions
   WHERE id = p_subscription_id AND client_id = v_client_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'customer_self_service_forbidden'; END IF;

  SELECT * INTO v_existing_event FROM public.subscription_events
   WHERE subscription_id = p_subscription_id AND idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN public.customer_self_service_subscription_action_response(v_subscription, p_action, 'replayed', v_existing_event.id);
  END IF;

  IF p_action <> 'change_shipping_address'
    AND EXISTS (SELECT 1 FROM public.subscription_dunning_cases WHERE subscription_id = p_subscription_id AND status = 'open')
  THEN
    RAISE EXCEPTION 'customer_self_service_payment_blocked';
  END IF;

  IF v_subscription.payment_method_ref IS NULL
    AND p_action IN ('slide_next_cycle','skip_next_cycle','order_now','swap_recipe','add_addon',
                     'remove_addon','update_addon_quantity','update_recipe_mix','update_plan_length',
                     'set_portion_mode','update_package_template','update_bundle','resize_bundle','reactivate')
  THEN
    RAISE EXCEPTION 'customer_self_service_payment_blocked';
  END IF;

  IF p_action IN ('order_now', 'reactivate')
    AND COALESCE(v_payload->'confirmedChargeTiming', 'false'::jsonb) <> 'true'::jsonb
  THEN
    RAISE EXCEPTION 'customer_self_service_charge_timing_not_confirmed';
  END IF;

  IF p_action = 'change_shipping_address' THEN
    v_shipping_address_id := NULLIF(v_payload->>'shippingAddressId', '')::uuid;
    IF v_subscription.status NOT IN ('active', 'paused') OR v_shipping_address_id IS NULL THEN
      RAISE EXCEPTION 'customer_self_service_invalid_address';
    END IF;
    SELECT kind INTO v_address_kind
      FROM public.addresses
     WHERE id = v_shipping_address_id
       AND client_id = v_client_id;
    IF v_address_kind NOT IN ('shipping', 'both') THEN
      RAISE EXCEPTION 'customer_self_service_invalid_address';
    END IF;
    PERFORM public.customer_self_service_assert_no_locked_cycle(p_subscription_id, v_subscription.next_cycle_at);
    UPDATE public.subscriptions
       SET shipping_address_id = v_shipping_address_id,
           updated_at = p_requested_at
     WHERE id = p_subscription_id
     RETURNING * INTO v_subscription;
  ELSIF p_action = 'slide_next_cycle' THEN
    v_next_cycle_at := (v_payload->>'newNextCycleAt')::timestamptz;
    IF v_subscription.status <> 'active' OR v_next_cycle_at IS NULL
       OR v_next_cycle_at < p_requested_at + interval '3 days' OR v_next_cycle_at > p_requested_at + interval '60 days' THEN
      RAISE EXCEPTION 'customer_self_service_invalid_slide';
    END IF;
    PERFORM public.customer_self_service_assert_no_locked_cycle(p_subscription_id, v_subscription.next_cycle_at);
    UPDATE public.subscriptions SET next_cycle_at = v_next_cycle_at, updated_at = p_requested_at
     WHERE id = p_subscription_id RETURNING * INTO v_subscription;
  ELSIF p_action = 'skip_next_cycle' THEN
    IF v_subscription.status <> 'active' OR v_subscription.next_cycle_at IS NULL THEN
      RAISE EXCEPTION 'customer_self_service_invalid_skip';
    END IF;
    PERFORM public.customer_self_service_assert_no_locked_cycle(p_subscription_id, v_subscription.next_cycle_at);
    UPDATE public.subscriptions SET next_cycle_at = v_subscription.next_cycle_at + (v_subscription.cadence_days || ' days')::interval,
           updated_at = p_requested_at
     WHERE id = p_subscription_id RETURNING * INTO v_subscription;
  ELSIF p_action = 'order_now' THEN
    IF v_subscription.status <> 'active' OR v_subscription.next_cycle_at IS NULL THEN
      RAISE EXCEPTION 'customer_self_service_invalid_order_now';
    END IF;
    PERFORM public.customer_self_service_assert_no_locked_cycle(p_subscription_id, v_subscription.next_cycle_at);
    UPDATE public.subscriptions SET next_cycle_at = p_requested_at + interval '5 minutes', updated_at = p_requested_at
     WHERE id = p_subscription_id RETURNING * INTO v_subscription;
  ELSIF p_action = 'pause' THEN
    IF v_subscription.status <> 'active' OR v_pause_preset NOT IN ('2_weeks', '1_month', 'indefinite') THEN
      RAISE EXCEPTION 'customer_self_service_invalid_transition';
    END IF;
    v_pause_ends_at := CASE v_pause_preset WHEN '2_weeks' THEN p_requested_at + interval '14 days'
      WHEN '1_month' THEN p_requested_at + interval '1 month' ELSE NULL END;
    UPDATE public.subscriptions SET status = 'paused', updated_at = p_requested_at
     WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    INSERT INTO public.subscription_pause_windows (subscription_id, pause_preset, starts_at, ends_at, reason, idempotency_key)
    VALUES (p_subscription_id, v_pause_preset, p_requested_at, v_pause_ends_at, v_reason, p_idempotency_key)
    ON CONFLICT (subscription_id, idempotency_key) DO NOTHING;
  ELSIF p_action = 'resume' THEN
    IF v_subscription.status <> 'paused' THEN RAISE EXCEPTION 'customer_self_service_invalid_transition'; END IF;
    v_next_cycle_at := v_subscription.next_cycle_at;
    IF v_next_cycle_at IS NOT NULL AND v_next_cycle_at <= p_requested_at THEN
      v_next_cycle_at := v_next_cycle_at + ((
        floor(extract(epoch FROM (p_requested_at - v_next_cycle_at)) / (v_subscription.cadence_days * 86400.0))::bigint + 1
      ) * v_subscription.cadence_days || ' days')::interval;
    END IF;
    UPDATE public.subscriptions SET status = 'active', next_cycle_at = v_next_cycle_at, updated_at = p_requested_at
     WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    UPDATE public.subscription_pause_windows SET resumed_at = p_requested_at, updated_at = p_requested_at
     WHERE subscription_id = p_subscription_id AND resumed_at IS NULL;
  ELSIF p_action = 'cancel' THEN
    IF v_subscription.status NOT IN ('active', 'paused') THEN RAISE EXCEPTION 'customer_self_service_invalid_transition'; END IF;
    UPDATE public.subscriptions SET status = 'cancelled', ended_at = COALESCE(ended_at, p_requested_at),
           cancellation_reason = COALESCE(NULLIF(v_payload #>> '{survey,reasonCode}', ''), v_reason),
           updated_at = p_requested_at
     WHERE id = p_subscription_id RETURNING * INTO v_subscription;
  ELSIF p_action = 'reactivate' THEN
    IF v_subscription.status <> 'cancelled' THEN RAISE EXCEPTION 'customer_self_service_invalid_transition'; END IF;
    PERFORM public.customer_self_service_assert_no_locked_cycle(p_subscription_id, v_subscription.next_cycle_at);
    UPDATE public.subscriptions
       SET status = 'active',
           ended_at = NULL,
           cancellation_reason = NULL,
           next_cycle_at = p_requested_at + interval '2 days',
           template_version = template_version + 1,
           updated_at = p_requested_at
     WHERE id = p_subscription_id RETURNING * INTO v_subscription;
  ELSE
    v_edit_cutoff := v_subscription.next_cycle_at - ((COALESCE(v_subscription.edit_window_hours, 24) || ' hours')::interval);
    IF v_subscription.status <> 'active' OR v_subscription.next_cycle_at IS NULL OR p_requested_at > v_edit_cutoff THEN
      RAISE EXCEPTION 'customer_self_service_edit_window_closed';
    END IF;
    PERFORM public.customer_self_service_assert_no_locked_cycle(p_subscription_id, v_subscription.next_cycle_at);

    IF p_action IN ('swap_recipe', 'add_addon', 'remove_addon', 'update_addon_quantity',
                    'update_plan_length', 'update_recipe_mix', 'set_portion_mode',
                    'update_package_template', 'update_bundle', 'resize_bundle') THEN
      IF NOT (v_payload ? 'acceptedQuoteHash')
        OR COALESCE(v_payload->>'acceptedQuoteHash', '') !~ '^[a-f0-9]{64}$'
      THEN
        RAISE EXCEPTION 'customer_self_service_quote_not_accepted';
      END IF;
      IF NOT (v_payload ? 'expectedTemplateVersion')
        OR COALESCE(v_payload->>'expectedTemplateVersion', '') !~ '^[0-9]{1,9}$'
      THEN
        RAISE EXCEPTION 'customer_self_service_stale_edit';
      END IF;
      IF (v_payload->>'expectedTemplateVersion')::integer <> v_subscription.template_version THEN
        RAISE EXCEPTION 'customer_self_service_stale_edit';
      END IF;
      v_quote_preview_id := public.customer_self_service_accept_subscription_quote_preview(
        p_auth_user_id,
        p_subscription_id,
        p_action,
        v_payload->>'acceptedQuoteHash',
        (v_payload->>'expectedTemplateVersion')::integer,
        p_idempotency_key,
        p_requested_at,
        v_payload
      );
    END IF;

    v_rewrite_addon_lines := p_action = 'update_package_template'
      OR (p_action = 'update_bundle' AND v_payload ? 'addonLines');

    IF p_action IN ('update_cadence', 'update_package') THEN
      RAISE EXCEPTION 'customer_self_service_unsupported_action';
    ELSIF p_action = 'swap_recipe' THEN
      v_from_variant_id := (v_payload->>'fromVariantId')::uuid;
      v_to_variant_id := (v_payload->>'toVariantId')::uuid;
      IF EXISTS (SELECT 1 FROM public.subscription_lines WHERE subscription_id = p_subscription_id AND variant_id = v_to_variant_id) THEN
        RAISE EXCEPTION 'customer_self_service_conflict_duplicate_line';
      END IF;
      UPDATE public.subscription_lines SET variant_id = v_to_variant_id, template_version = v_subscription.template_version + 1, updated_at = p_requested_at
       WHERE subscription_id = p_subscription_id AND variant_id = v_from_variant_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'customer_self_service_not_found_line'; END IF;
      UPDATE public.subscriptions SET template_version = template_version + 1, updated_at = p_requested_at
       WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    ELSIF p_action = 'add_addon' THEN
      v_variant_id := (v_payload->>'variantId')::uuid;
      v_qty := GREATEST(1, COALESCE((v_payload->>'qty')::integer, 1));
      INSERT INTO public.subscription_lines (subscription_id, variant_id, qty, sort_order, is_addon, template_version)
      VALUES (p_subscription_id, v_variant_id, v_qty, COALESCE((SELECT max(sort_order) + 1 FROM public.subscription_lines WHERE subscription_id = p_subscription_id), 1), true, v_subscription.template_version + 1)
      RETURNING id INTO v_new_line_id;
      UPDATE public.subscriptions SET template_version = template_version + 1, updated_at = p_requested_at
       WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    ELSIF p_action = 'remove_addon' THEN
      v_variant_id := (v_payload->>'variantId')::uuid;
      DELETE FROM public.subscription_lines WHERE subscription_id = p_subscription_id AND variant_id = v_variant_id AND is_addon = true;
      IF NOT FOUND THEN RAISE EXCEPTION 'customer_self_service_not_found_addon'; END IF;
      UPDATE public.subscriptions SET template_version = template_version + 1, updated_at = p_requested_at
       WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    ELSIF p_action = 'update_addon_quantity' THEN
      v_variant_id := (v_payload->>'variantId')::uuid;
      v_qty := (v_payload->>'qty')::integer;
      IF v_qty IS NULL OR v_qty <= 0 THEN RAISE EXCEPTION 'customer_self_service_invalid_addon_qty'; END IF;
      UPDATE public.subscription_lines SET qty = v_qty, template_version = v_subscription.template_version + 1, updated_at = p_requested_at
       WHERE subscription_id = p_subscription_id AND variant_id = v_variant_id AND is_addon = true;
      IF NOT FOUND THEN RAISE EXCEPTION 'customer_self_service_not_found_addon'; END IF;
      UPDATE public.subscriptions SET template_version = template_version + 1, updated_at = p_requested_at
       WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    ELSIF p_action = 'update_plan_length' THEN
      v_plan_days := (v_payload->>'planDays')::integer;
      v_selected_core_lines := v_recipe_lines;
      IF v_plan_days IS NULL OR v_plan_days <= 0 OR v_selected_core_lines IS NULL OR jsonb_typeof(v_selected_core_lines) <> 'array'
         OR jsonb_array_length(v_selected_core_lines) = 0 THEN RAISE EXCEPTION 'customer_self_service_invalid_recipe_set'; END IF;
      UPDATE public.subscriptions SET cadence_days = v_plan_days,
             size_constraint = jsonb_set(COALESCE(size_constraint, '{}'::jsonb), '{value}', to_jsonb(v_plan_days)),
             template_version = template_version + 1, updated_at = p_requested_at
       WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    ELSIF p_action = 'update_recipe_mix' THEN
      v_selected_core_lines := v_recipe_lines;
      IF v_selected_core_lines IS NULL OR jsonb_typeof(v_selected_core_lines) <> 'array' OR jsonb_array_length(v_selected_core_lines) = 0 THEN
        RAISE EXCEPTION 'customer_self_service_invalid_recipe_set';
      END IF;
      SELECT COALESCE(sum(qty), 0) INTO v_current_recipe_total FROM public.subscription_lines
       WHERE subscription_id = p_subscription_id AND is_addon = false;
      SELECT COALESCE(sum((e->>'qty')::integer), 0) INTO v_desired_total FROM jsonb_array_elements(v_selected_core_lines) e;
      IF v_desired_total <> v_current_recipe_total THEN RAISE EXCEPTION 'customer_self_service_recipe_total_mismatch'; END IF;
      UPDATE public.subscriptions SET template_version = template_version + 1, updated_at = p_requested_at
       WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    ELSIF p_action = 'set_portion_mode' THEN
      v_portion_mode := COALESCE(NULLIF(v_payload->>'portionMode', ''), '');
      IF v_portion_mode NOT IN ('full', 'topper') THEN
        RAISE EXCEPTION 'customer_self_service_invalid_portion_mode';
      END IF;
      v_selected_core_lines := v_recipe_lines;
      IF v_selected_core_lines IS NULL OR jsonb_typeof(v_selected_core_lines) <> 'array' OR jsonb_array_length(v_selected_core_lines) = 0 THEN
        RAISE EXCEPTION 'customer_self_service_invalid_recipe_set';
      END IF;
      v_portion_factor := CASE v_portion_mode WHEN 'topper' THEN 0.5 ELSE 1 END;
      UPDATE public.subscriptions SET
             size_constraint = jsonb_set(
               jsonb_set(COALESCE(size_constraint, '{}'::jsonb), '{mode}', to_jsonb(v_portion_mode)),
               '{portionFactor}', to_jsonb(v_portion_factor)),
             template_version = template_version + 1, updated_at = p_requested_at
       WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    ELSIF p_action = 'update_package_template' THEN
      v_plan_days := (v_payload->>'planDays')::integer;
      v_selected_core_lines := v_recipe_lines;
      IF v_plan_days IS NULL OR v_plan_days <= 0 OR v_selected_core_lines IS NULL OR jsonb_typeof(v_selected_core_lines) <> 'array'
         OR jsonb_array_length(v_selected_core_lines) = 0 OR jsonb_typeof(v_addon_lines) <> 'array' THEN
        RAISE EXCEPTION 'customer_self_service_invalid_recipe_set';
      END IF;
      UPDATE public.subscriptions SET cadence_days = v_plan_days,
             size_constraint = jsonb_set(COALESCE(size_constraint, '{}'::jsonb), '{value}', to_jsonb(v_plan_days)),
             template_version = template_version + 1, updated_at = p_requested_at
       WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    ELSIF p_action = 'resize_bundle' THEN
      v_plan_days := NULLIF(v_payload->>'cadenceDays', '')::integer;
      v_selected_core_lines := v_core_lines;
      IF v_composition_constraint IS NULL OR jsonb_typeof(v_composition_constraint) <> 'object'
         OR v_composition_constraint ? 'version' OR v_composition_constraint ? 'data' THEN
        RAISE EXCEPTION 'customer_self_service_invalid_composition_constraint';
      END IF;
      IF v_selected_core_lines IS NULL OR jsonb_typeof(v_selected_core_lines) <> 'array' OR jsonb_array_length(v_selected_core_lines) = 0 THEN
        RAISE EXCEPTION 'customer_self_service_invalid_bundle';
      END IF;
      UPDATE public.subscriptions SET
             cadence_days = COALESCE(v_plan_days, cadence_days),
             size_constraint = v_composition_constraint,
             template_version = template_version + 1,
             updated_at = p_requested_at
       WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    ELSIF p_action = 'update_bundle' THEN
      v_plan_days := NULLIF(v_payload->>'cadenceDays', '')::integer;
      v_selected_core_lines := v_core_lines;
      IF v_composition_constraint IS NULL OR jsonb_typeof(v_composition_constraint) <> 'object'
         OR v_composition_constraint ? 'version' OR v_composition_constraint ? 'data' THEN
        RAISE EXCEPTION 'customer_self_service_invalid_composition_constraint';
      END IF;
      IF v_selected_core_lines IS NULL OR jsonb_typeof(v_selected_core_lines) <> 'array' OR jsonb_array_length(v_selected_core_lines) = 0
         OR jsonb_typeof(v_addon_lines) <> 'array' THEN
        RAISE EXCEPTION 'customer_self_service_invalid_bundle';
      END IF;
      SELECT COALESCE(sum(qty), 0) INTO v_current_recipe_total FROM public.subscription_lines
       WHERE subscription_id = p_subscription_id AND is_addon = false;
      SELECT COALESCE(sum((e->>'qty')::integer), 0) INTO v_desired_total FROM jsonb_array_elements(v_selected_core_lines) e;
      IF v_desired_total <> v_current_recipe_total
         AND COALESCE(v_plan_days, v_subscription.cadence_days) = v_subscription.cadence_days THEN
        RAISE EXCEPTION 'customer_self_service_bundle_total_mismatch';
      END IF;
      UPDATE public.subscriptions SET
             cadence_days = COALESCE(v_plan_days, cadence_days),
             size_constraint = v_composition_constraint,
             template_version = template_version + 1,
             updated_at = p_requested_at
       WHERE id = p_subscription_id RETURNING * INTO v_subscription;
    ELSE
      RAISE EXCEPTION 'customer_self_service_invalid_action';
    END IF;

    IF p_action IN ('update_plan_length', 'update_recipe_mix', 'set_portion_mode', 'update_package_template', 'update_bundle', 'resize_bundle') THEN
      DELETE FROM public.subscription_lines
       WHERE subscription_id = p_subscription_id
         AND (v_rewrite_addon_lines OR is_addon = false);
      FOR v_rs_elem, v_rs_ord IN SELECT value, ordinality FROM jsonb_array_elements(v_selected_core_lines) WITH ORDINALITY LOOP
        v_rs_variant := (v_rs_elem->>'variantId')::uuid;
        v_rs_qty := (v_rs_elem->>'qty')::integer;
        IF v_rs_qty IS NULL OR v_rs_qty <= 0 THEN
          IF p_action IN ('update_bundle', 'resize_bundle') THEN
            RAISE EXCEPTION 'customer_self_service_invalid_bundle_line';
          END IF;
          RAISE EXCEPTION 'customer_self_service_invalid_recipe_qty';
        END IF;
        v_quote_line := COALESCE(v_rs_elem->'quoteLine', '{}'::jsonb);
        INSERT INTO public.subscription_lines (subscription_id, variant_id, qty, sort_order, is_addon, template_version, line_metadata)
        VALUES (p_subscription_id, v_rs_variant, v_rs_qty, v_rs_ord::integer, false, v_subscription.template_version, jsonb_build_object('productSnapshot', jsonb_build_object('quoteLine', v_quote_line)))
        RETURNING id INTO v_price_line_id;
        v_unit_price := CASE
          WHEN (v_quote_line #>> '{unitPriceGross,amountMinor}') ~ '^[0-9]+$' THEN (v_quote_line #>> '{unitPriceGross,amountMinor}')::integer
          WHEN (v_quote_line->>'unitGrossMinor') ~ '^[0-9]+$' THEN (v_quote_line->>'unitGrossMinor')::integer
          ELSE NULL
        END;
        INSERT INTO public.subscription_price_agreements (subscription_id, subscription_line_id, variant_id, currency, unit_price_gross_minor, quote_line, template_version, source_action, idempotency_key, started_at)
        VALUES (p_subscription_id, v_price_line_id, v_rs_variant, v_subscription.currency, v_unit_price, v_quote_line, v_subscription.template_version, p_action, p_idempotency_key, p_requested_at)
        ON CONFLICT DO NOTHING;
      END LOOP;

      IF v_rewrite_addon_lines THEN
        FOR v_rs_elem, v_rs_ord IN SELECT value, ordinality FROM jsonb_array_elements(v_addon_lines) WITH ORDINALITY LOOP
          v_rs_variant := (v_rs_elem->>'variantId')::uuid;
          v_rs_qty := (v_rs_elem->>'qty')::integer;
          IF v_rs_qty IS NULL OR v_rs_qty <= 0 THEN
            IF p_action = 'update_bundle' THEN
              RAISE EXCEPTION 'customer_self_service_invalid_bundle_line';
            END IF;
            RAISE EXCEPTION 'customer_self_service_invalid_addon_qty';
          END IF;
          v_quote_line := COALESCE(v_rs_elem->'quoteLine', '{}'::jsonb);
          INSERT INTO public.subscription_lines (subscription_id, variant_id, qty, sort_order, is_addon, template_version, line_metadata)
          VALUES (p_subscription_id, v_rs_variant, v_rs_qty, jsonb_array_length(v_selected_core_lines) + v_rs_ord::integer, true, v_subscription.template_version, jsonb_build_object('productSnapshot', jsonb_build_object('quoteLine', v_quote_line)))
          RETURNING id INTO v_price_line_id;
          v_unit_price := CASE
            WHEN (v_quote_line #>> '{unitPriceGross,amountMinor}') ~ '^[0-9]+$' THEN (v_quote_line #>> '{unitPriceGross,amountMinor}')::integer
            WHEN (v_quote_line->>'unitGrossMinor') ~ '^[0-9]+$' THEN (v_quote_line->>'unitGrossMinor')::integer
            ELSE NULL
          END;
          INSERT INTO public.subscription_price_agreements (subscription_id, subscription_line_id, variant_id, currency, unit_price_gross_minor, quote_line, template_version, source_action, idempotency_key, started_at)
          VALUES (p_subscription_id, v_price_line_id, v_rs_variant, v_subscription.currency, v_unit_price, v_quote_line, v_subscription.template_version, p_action, p_idempotency_key, p_requested_at)
          ON CONFLICT DO NOTHING;
        END LOOP;
      END IF;
    END IF;

    IF v_repriced IS NOT NULL AND jsonb_typeof(v_repriced) = 'array' THEN
      FOR v_rl_elem IN SELECT * FROM jsonb_array_elements(v_repriced) LOOP
        v_price_line_id := COALESCE(NULLIF(v_rl_elem->>'lineId', '')::uuid, v_new_line_id);
        v_quote_line := COALESCE(v_rl_elem->'quoteLine', '{}'::jsonb);
        UPDATE public.subscription_lines SET line_metadata = COALESCE(line_metadata, '{}'::jsonb)
             || jsonb_build_object('productSnapshot', COALESCE(line_metadata->'productSnapshot', '{}'::jsonb)
             || jsonb_build_object('quoteLine', v_quote_line)), updated_at = p_requested_at
         WHERE subscription_id = p_subscription_id AND id = v_price_line_id;
        v_unit_price := CASE
          WHEN (v_quote_line #>> '{unitPriceGross,amountMinor}') ~ '^[0-9]+$' THEN (v_quote_line #>> '{unitPriceGross,amountMinor}')::integer
          WHEN (v_quote_line->>'unitGrossMinor') ~ '^[0-9]+$' THEN (v_quote_line->>'unitGrossMinor')::integer
          ELSE NULL
        END;
        INSERT INTO public.subscription_price_agreements (subscription_id, subscription_line_id, variant_id, currency, unit_price_gross_minor, quote_line, template_version, source_action, idempotency_key, started_at)
        SELECT p_subscription_id, sl.id, sl.variant_id, v_subscription.currency, v_unit_price,
               v_quote_line, v_subscription.template_version, p_action, p_idempotency_key, p_requested_at
          FROM public.subscription_lines sl
         WHERE sl.subscription_id = p_subscription_id AND sl.id = v_price_line_id
        ON CONFLICT DO NOTHING;
      END LOOP;
    END IF;
  END IF;

  INSERT INTO public.subscription_events (subscription_id, event_type, idempotency_key, payload, occurred_at)
  VALUES (p_subscription_id, CASE p_action
      WHEN 'swap_recipe' THEN 'subscription.customer_self_service.swap_recipe'
      WHEN 'update_recipe_mix' THEN 'subscription.customer_self_service.update_recipe_mix'
      WHEN 'set_portion_mode' THEN 'subscription.customer_self_service.set_portion_mode'
      ELSE 'subscription.customer_self_service.' || p_action
    END, p_idempotency_key,
    jsonb_build_object(
      'action', p_action,
      'payload', CASE
        WHEN p_action IN ('update_bundle', 'resize_bundle') THEN
          ((((((v_payload - 'repricedLines') - 'coreLines') - 'recipeLines') - 'addonLines') - 'expectedTemplateVersion') - 'acceptedQuoteHash')
        ELSE
          (((((v_payload - 'repricedLines') - 'recipeLines') - 'addonLines') - 'expectedTemplateVersion') - 'acceptedQuoteHash')
      END,
      'quotePreviewId', v_quote_preview_id,
      'reason', v_reason,
      'priceAgreementPolicy', jsonb_build_object('kind','lock_until_edit','proration','none','cycleEffect','future_unlocked_cycles_only')
    ),
    p_requested_at)
  RETURNING id INTO v_event_id;

  UPDATE public.subscription_price_agreements SET event_id = v_event_id, updated_at = p_requested_at
   WHERE subscription_id = p_subscription_id AND idempotency_key = p_idempotency_key;
  UPDATE public.subscription_pause_windows SET event_id = v_event_id, updated_at = p_requested_at
   WHERE subscription_id = p_subscription_id AND idempotency_key = p_idempotency_key;

  RETURN jsonb_build_object(
    'contractVersion', 'customer.self_service.v1',
    'subscriptionAction', jsonb_build_object(
      'subscriptionId', p_subscription_id, 'action', p_action, 'status', 'applied',
      'subscriptionStatus', v_subscription.status, 'nextCycleAt', v_subscription.next_cycle_at,
      'templateVersion', v_subscription.template_version, 'eventId', v_event_id
    )
  );
END;
$_$;


--
-- Name: customer_self_service_apply_action_before_anchor_fence(uuid, text, uuid, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_apply_action_before_anchor_fence(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb, p_requested_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_client_id uuid;
  v_subscription public.subscriptions%ROWTYPE;
  v_latest_case_status text;
  v_stale_cycle_id uuid;
BEGIN
  IF p_action IS DISTINCT FROM 'resume' THEN
    RETURN public.customer_self_service_apply_action_before_resume_terminalizes(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  -- The delegate refuses a short or missing key before it reads anything.
  IF p_idempotency_key IS NULL OR char_length(trim(p_idempotency_key)) < 8 THEN
    RETURN public.customer_self_service_apply_action_before_resume_terminalizes(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  SELECT client.id
    INTO v_client_id
    FROM public.clients client
   WHERE client.auth_user_id = p_auth_user_id;

  SELECT *
    INTO v_subscription
    FROM public.subscriptions subscription
   WHERE subscription.id = p_subscription_id
     AND subscription.client_id = v_client_id
   FOR UPDATE;

  -- An unknown client, a foreign subscription, an idempotency replay, a status
  -- that forbids the transition and an open dunning case are the delegate's
  -- refusals and stay word for word its own. The replay test in particular must
  -- run before this wrapper can write: a key that already produced an event
  -- still answers `replayed` and must terminalize nothing.
  IF NOT FOUND
    OR v_subscription.status <> 'paused'
    OR EXISTS (
      SELECT 1
        FROM public.subscription_events event
       WHERE event.subscription_id = p_subscription_id
         AND event.idempotency_key = p_idempotency_key
    )
    OR EXISTS (
      SELECT 1
        FROM public.subscription_dunning_cases dunning_case
       WHERE dunning_case.subscription_id = p_subscription_id
         AND dunning_case.status = 'open'
    )
  THEN
    RETURN public.customer_self_service_apply_action_before_resume_terminalizes(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  SELECT dunning_case.status
    INTO v_latest_case_status
    FROM public.subscription_dunning_cases dunning_case
   WHERE dunning_case.subscription_id = p_subscription_id
   ORDER BY dunning_case.opened_at DESC, dunning_case.id DESC
   LIMIT 1;

  -- 20260809090001 owns the expired case, including its own terminalization,
  -- its charge-timing confirmation and its unattended-charge refusal.
  IF v_latest_case_status IS NOT DISTINCT FROM 'expired' THEN
    RETURN public.customer_self_service_apply_action_before_resume_terminalizes(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.subscription_cycles cycle
     WHERE cycle.subscription_id = p_subscription_id
       AND cycle.status IN ('payment_pending', 'retry_scheduled', 'payment_failed')
  ) THEN
    -- Refuse rather than cancel an order the payer may still be paying. This is
    -- the helper's own in-flight predicate, restated so the two cannot disagree,
    -- asked one step earlier so the customer gets a renderable reason instead of
    -- the helper's raw 55006.
    IF EXISTS (
      SELECT 1
        FROM public.commerce_payment_intents payment_intent
        JOIN public.commerce_payment_attempts payment_attempt
          ON payment_attempt.payment_intent_id = payment_intent.id
       WHERE payment_intent.subscription_id = p_subscription_id
         AND payment_intent.target_kind = 'subscription_cycle'
         AND payment_attempt.status IN (
           'created', 'sent_to_provider', 'requires_action', 'processing'
         )
    ) THEN
      RAISE EXCEPTION 'customer_self_service_payment_blocked_attempt_in_flight';
    END IF;

    FOR v_stale_cycle_id IN
      SELECT cycle.id
        FROM public.subscription_cycles cycle
       WHERE cycle.subscription_id = p_subscription_id
         AND cycle.status IN ('payment_pending', 'retry_scheduled', 'payment_failed')
       ORDER BY cycle.cycle_number, cycle.id
    LOOP
      PERFORM public.subscription_terminalize_unpaid_cycle_artifacts(
        p_subscription_id,
        v_stale_cycle_id,
        p_requested_at,
        'subscription_resumed_with_unpaid_cycle'
      );
    END LOOP;
  END IF;

  RETURN public.customer_self_service_apply_action_before_resume_terminalizes(
    p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
  );
END;
$$;


--
-- Name: FUNCTION customer_self_service_apply_action_before_anchor_fence(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_self_service_apply_action_before_anchor_fence(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone) IS 'Customer subscription self-service wrapper. A resume the expired-dunning rail does not own skips every cycle still holding the subscription out of subscription_list_due_for_renewal, with its unpaid order and intent, and refuses while a provider attempt is in flight; every other request, and every refusal, is delegated unchanged.';


--
-- Name: customer_self_service_apply_action_before_dunning_cancel(uuid, text, uuid, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_apply_action_before_dunning_cancel(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb, p_requested_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_result jsonb;
  v_nominal_plan_days integer;
BEGIN
  v_result := public.customer_self_service_apply_subscription_action_pre_cadence(
    p_auth_user_id,
    p_idempotency_key,
    p_subscription_id,
    p_action,
    p_payload,
    p_requested_at
  );

  IF p_action = 'update_package_template'
    AND v_result #>> '{subscriptionAction,status}' = 'applied'
  THEN
    -- Read the nominal value from the accepted server-written preview, never from
    -- the apply payload. This keeps idempotency replays and tampered payloads from
    -- changing size_constraint outside the accepted quote.
    SELECT CASE
      WHEN q.request_payload->>'nominalPlanDays' ~ '^[1-9][0-9]{0,2}$'
        THEN (q.request_payload->>'nominalPlanDays')::integer
      ELSE NULL
    END
    INTO v_nominal_plan_days
    FROM public.subscription_quote_previews q
    JOIN public.clients c ON c.id = q.client_id
    WHERE q.subscription_id = p_subscription_id
      AND c.auth_user_id = p_auth_user_id
      AND q.action = 'update_package_template'
      AND q.quote_hash = p_payload->>'acceptedQuoteHash'
      AND q.accepted_idempotency_key = p_idempotency_key
      AND q.status = 'accepted'
    ORDER BY q.created_at DESC
    LIMIT 1;

    IF v_nominal_plan_days IS NOT NULL THEN
      UPDATE public.subscriptions s
      SET size_constraint = jsonb_set(
        COALESCE(s.size_constraint, '{}'::jsonb),
        '{value}',
        to_jsonb(v_nominal_plan_days)
      )
      FROM public.clients c
      WHERE s.id = p_subscription_id
        AND c.id = s.client_id
        AND c.auth_user_id = p_auth_user_id;
    END IF;
  END IF;

  RETURN v_result;
END;
$_$;


--
-- Name: FUNCTION customer_self_service_apply_action_before_dunning_cancel(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_self_service_apply_action_before_dunning_cancel(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone) IS 'Customer subscription self-service wrapper. Preserves quote-locked nominal feeding-days size_constraint independently from effective package delivery cadence after legacy update_package_template applies.';


--
-- Name: customer_self_service_apply_action_before_expired_resume(uuid, text, uuid, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_apply_action_before_expired_resume(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb, p_requested_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_requested_units integer;
BEGIN
  IF p_action = 'update_package_template'
    AND jsonb_typeof(p_payload->'recipeLines') = 'array'
  THEN
    -- `recipeLines` is the RPC-boundary key for this action (the BFF's own
    -- `recipes` key never reaches the mutation branch).
    SELECT COALESCE(sum((line->>'qty')::integer), 0)
      INTO v_requested_units
      FROM jsonb_array_elements(p_payload->'recipeLines') AS line;

    IF v_requested_units < 14 THEN
      RAISE EXCEPTION 'customer_self_service_below_minimum_order_units';
    END IF;
  END IF;

  RETURN public.customer_self_service_apply_action_before_moq(
    p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
  );
END;
$$;


--
-- Name: FUNCTION customer_self_service_apply_action_before_expired_resume(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_self_service_apply_action_before_expired_resume(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone) IS 'Customer subscription self-service wrapper. Rejects an update_package_template payload whose requested line quantities total fewer than the 14-unit minimum order quantity, then delegates unchanged.';


--
-- Name: customer_self_service_apply_action_before_moq(uuid, text, uuid, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_apply_action_before_moq(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb, p_requested_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_client_id uuid;
  v_subscription_status text;
  v_closed_case_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_action IS NULL OR p_action NOT IN ('pause', 'cancel') THEN
    RETURN public.customer_self_service_apply_action_before_dunning_cancel(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  SELECT client.id
    INTO v_client_id
    FROM public.clients client
   WHERE client.auth_user_id = p_auth_user_id;

  SELECT subscription.status
    INTO v_subscription_status
    FROM public.subscriptions subscription
   WHERE subscription.id = p_subscription_id
     AND subscription.client_id = v_client_id
   FOR UPDATE;

  IF NOT FOUND
    OR (p_action = 'pause' AND v_subscription_status <> 'active')
    OR (p_action = 'cancel' AND v_subscription_status NOT IN ('active', 'paused'))
    OR EXISTS (
      SELECT 1
        FROM public.subscription_events event
       WHERE event.subscription_id = p_subscription_id
         AND event.idempotency_key = p_idempotency_key
    )
  THEN
    RETURN public.customer_self_service_apply_action_before_dunning_cancel(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.commerce_payment_intents payment_intent
      JOIN public.commerce_payment_attempts payment_attempt
        ON payment_attempt.payment_intent_id = payment_intent.id
     WHERE payment_intent.subscription_id = p_subscription_id
       AND payment_intent.target_kind = 'subscription_cycle'
       AND payment_attempt.status IN (
         'created', 'sent_to_provider', 'requires_action', 'processing'
       )
  ) THEN
    RAISE EXCEPTION 'customer_self_service_payment_blocked';
  END IF;

  -- A provider attempt is admitted in one transaction and executed immediately
  -- afterwards. If admission won the subscription lock, pause must not confirm
  -- in that narrow gap; the customer retries after the attempt is terminal.
  IF p_action = 'pause' THEN
    RETURN public.customer_self_service_apply_action_before_dunning_cancel(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  WITH closed_cases AS (
    UPDATE public.subscription_dunning_cases dunning_case
       SET status = 'cancelled',
           next_retry_at = NULL,
           last_event_at = p_requested_at,
           updated_at = p_requested_at,
           metadata = dunning_case.metadata || jsonb_build_object(
             'closedReason', 'subscription_cancelled',
             'cancelRequestedAt', p_requested_at
           )
     WHERE dunning_case.subscription_id = p_subscription_id
       AND dunning_case.status = 'open'
    RETURNING dunning_case.id
  )
  SELECT COALESCE(array_agg(closed_cases.id), ARRAY[]::uuid[])
    INTO v_closed_case_ids
    FROM closed_cases;

  UPDATE public.subscription_payment_recovery_tokens token
     SET revoked_at = COALESCE(token.revoked_at, p_requested_at),
         updated_at = p_requested_at
   WHERE token.case_id = ANY(v_closed_case_ids)
     AND token.used_at IS NULL
     AND token.revoked_at IS NULL;

  UPDATE public.subscription_dunning_notifications notification
     SET status = 'skipped',
         recovery_url_path = NULL,
         provider_error = 'subscription_cancelled',
         updated_at = p_requested_at
   WHERE notification.case_id = ANY(v_closed_case_ids)
     AND notification.status = 'queued';

  -- No provider call is in flight (guard above), so the unpaid renewal artifacts
  -- are terminalized in the same transaction as the customer's cancellation.
  UPDATE public.commerce_payment_intents payment_intent
     SET status = 'cancelled',
         failure_reason = 'subscription_cancelled',
         updated_at = p_requested_at
   WHERE payment_intent.subscription_id = p_subscription_id
     AND payment_intent.target_kind = 'subscription_cycle'
     AND payment_intent.status IN ('created', 'processing', 'failed')
     AND NOT EXISTS (
       SELECT 1
         FROM public.commerce_payment_attempts payment_attempt
        WHERE payment_attempt.payment_intent_id = payment_intent.id
          AND payment_attempt.status IN ('created', 'sent_to_provider', 'requires_action', 'processing')
     );

  UPDATE public.subscription_cycles cycle
     SET status = 'cancelled',
         next_retry_at = NULL,
         failure_reason = COALESCE(cycle.failure_reason, 'subscription_cancelled'),
         updated_at = p_requested_at
   WHERE cycle.subscription_id = p_subscription_id
     AND cycle.status IN ('payment_pending', 'retry_scheduled');

  -- The cancellation trigger releases reservations for these pending orders.
  UPDATE public.commerce_orders order_row
     SET status = 'cancelled',
         metadata = order_row.metadata || jsonb_build_object(
           'paymentStatus', 'cancelled',
           'cancelReason', 'subscription_cancelled',
           'source', 'customer_self_service.cancel'
         ),
         updated_at = p_requested_at
   WHERE order_row.subscription_id = p_subscription_id
     AND order_row.mode = 'subscription_cycle'
     AND order_row.status = 'pending_payment'
     AND NOT EXISTS (
       SELECT 1
         FROM public.commerce_payment_intents payment_intent
         LEFT JOIN public.commerce_payment_attempts payment_attempt
           ON payment_attempt.payment_intent_id = payment_intent.id
        WHERE payment_intent.order_id = order_row.id
          AND (
            payment_intent.status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed')
            OR payment_attempt.status = 'succeeded'
          )
     )
     AND NOT EXISTS (
       SELECT 1
         FROM public.commerce_payment_intents payment_intent
         JOIN public.commerce_payment_attempts payment_attempt
           ON payment_attempt.payment_intent_id = payment_intent.id
        WHERE payment_intent.order_id = order_row.id
          AND payment_attempt.status IN ('created', 'sent_to_provider', 'requires_action', 'processing')
     );

  RETURN public.customer_self_service_apply_action_before_dunning_cancel(
    p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
  );
END;
$$;


--
-- Name: FUNCTION customer_self_service_apply_action_before_moq(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_self_service_apply_action_before_moq(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone) IS 'Customer subscription self-service wrapper. A cancel atomically closes open dunning, revokes recovery, suppresses queued notices, then delegates the canonical cancellation mutation.';


--
-- Name: customer_self_service_apply_action_before_resume_terminalizes(uuid, text, uuid, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_apply_action_before_resume_terminalizes(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb, p_requested_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_client_id uuid;
  v_subscription public.subscriptions%ROWTYPE;
  v_latest_case_status text;
  v_resume jsonb;
BEGIN
  IF p_action IS DISTINCT FROM 'resume' THEN
    RETURN public.customer_self_service_apply_action_before_expired_resume(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  SELECT client.id
    INTO v_client_id
    FROM public.clients client
   WHERE client.auth_user_id = p_auth_user_id;

  SELECT *
    INTO v_subscription
    FROM public.subscriptions subscription
   WHERE subscription.id = p_subscription_id
     AND subscription.client_id = v_client_id;

  -- Ownership, idempotency replay and the paused-status transition rule are the
  -- delegate's to answer and keep answering; this wrapper only decides whether
  -- the expired-dunning rail applies.
  IF NOT FOUND
    OR v_subscription.status <> 'paused'
    OR EXISTS (
      SELECT 1
        FROM public.subscription_events event
       WHERE event.subscription_id = p_subscription_id
         AND event.idempotency_key = p_idempotency_key
    )
  THEN
    RETURN public.customer_self_service_apply_action_before_expired_resume(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  SELECT dunning_case.status
    INTO v_latest_case_status
    FROM public.subscription_dunning_cases dunning_case
   WHERE dunning_case.subscription_id = p_subscription_id
   ORDER BY dunning_case.opened_at DESC, dunning_case.id DESC
   LIMIT 1;

  IF v_latest_case_status IS DISTINCT FROM 'expired' THEN
    RETURN public.customer_self_service_apply_action_before_expired_resume(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  -- Billing that had stopped starts again here, so the same confirmation
  -- `order_now` and `reactivate` require is required of this resume.
  IF COALESCE(p_payload->'confirmedChargeTiming', 'false'::jsonb) <> 'true'::jsonb THEN
    RAISE EXCEPTION 'customer_self_service_charge_timing_not_confirmed';
  END IF;

  IF NOT public.subscription_method_chargeable_unattended(p_subscription_id, p_requested_at) THEN
    RAISE EXCEPTION 'customer_self_service_payment_method_not_chargeable';
  END IF;

  v_resume := public.subscription_resume_after_expired_dunning(
    p_idempotency_key,
    p_subscription_id,
    NULL,
    NULL,
    p_requested_at,
    'customer_self_service.resume'
  );

  SELECT *
    INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id;

  RETURN public.customer_self_service_subscription_action_response(
    v_subscription,
    p_action,
    'applied',
    (v_resume #>> '{subscriptionResumeAfterExpiredDunning,eventId}')::uuid
  );
END;
$$;


--
-- Name: FUNCTION customer_self_service_apply_action_before_resume_terminalizes(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_self_service_apply_action_before_resume_terminalizes(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone) IS 'Customer subscription self-service wrapper. Routes resume on a paused subscription whose latest dunning case expired through subscription_resume_after_expired_dunning, refusing an unconfirmed charge timing or an unchargeable stored method, and delegates every other request unchanged.';


--
-- Name: customer_self_service_apply_subscription_action(uuid, text, uuid, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_apply_subscription_action(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb, p_requested_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_anchor_before timestamptz;
  v_response jsonb;
BEGIN
  IF p_action NOT IN ('slide_next_cycle', 'skip_next_cycle', 'order_now') THEN
    RETURN public.customer_self_service_apply_action_before_anchor_fence(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  -- Read the anchor under the row lock the delegate is about to take on the
  -- same row and with the delegate's own ownership predicate, so the value
  -- compared afterwards cannot be one a concurrent renewal moved in between,
  -- and so a subscription the caller does not own is never locked here. A miss
  -- leaves `v_anchor_before` NULL and the post-condition below short-circuits;
  -- the delegate answers that request with `customer_self_service_forbidden` or
  -- `customer_self_service_not_found`, exactly as it always has.
  SELECT subscription.next_cycle_at
    INTO v_anchor_before
    FROM public.subscriptions subscription
    JOIN public.clients client ON client.id = subscription.client_id
   WHERE subscription.id = p_subscription_id
     AND client.auth_user_id = p_auth_user_id
   FOR UPDATE OF subscription;

  v_response := public.customer_self_service_apply_action_before_anchor_fence(
    p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
  );

  IF v_anchor_before IS NOT NULL
    AND EXISTS (
      SELECT 1
        FROM public.subscriptions subscription
       WHERE subscription.id = p_subscription_id
         AND subscription.next_cycle_at IS DISTINCT FROM v_anchor_before
    )
    AND EXISTS (
      SELECT 1
        FROM public.subscription_cycles cycle
       WHERE cycle.subscription_id = p_subscription_id
         AND cycle.scheduled_at = v_anchor_before
         AND cycle.status IN ('retry_scheduled', 'payment_failed')
    )
  THEN
    RAISE EXCEPTION 'customer_self_service_payment_blocked';
  END IF;

  RETURN v_response;
END;
$$;


--
-- Name: FUNCTION customer_self_service_apply_subscription_action(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_self_service_apply_subscription_action(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone) IS 'Customer subscription self-service wrapper. A slide, skip or order-now that would move next_cycle_at off a retry_scheduled or payment_failed cycle at that same date is refused with customer_self_service_payment_blocked and rolled back, so the renewal lane is never left excluding a subscription on a cycle nothing points at; every other request, and every refusal, is delegated unchanged.';


--
-- Name: customer_self_service_apply_subscription_action_legacy_wave5(uuid, text, uuid, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_apply_subscription_action_legacy_wave5(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb, p_requested_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_client_id uuid;
  v_subscription_status text;
  v_subscription_found boolean;
  v_shipping_address_id uuid;
BEGIN
  IF p_action IS DISTINCT FROM 'change_shipping_address' THEN
    RETURN public.customer_self_service_apply_action_before_address_ownership(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  -- The delegate refuses a short or missing key before it reads anything.
  IF p_idempotency_key IS NULL OR char_length(trim(p_idempotency_key)) < 8 THEN
    RETURN public.customer_self_service_apply_action_before_address_ownership(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  SELECT client.id
    INTO v_client_id
    FROM public.clients client
   WHERE client.auth_user_id = p_auth_user_id;

  SELECT subscription.status
    INTO v_subscription_status
    FROM public.subscriptions subscription
   WHERE subscription.id = p_subscription_id
     AND subscription.client_id = v_client_id
   FOR UPDATE;
  v_subscription_found := FOUND;

  -- Unknown client, foreign subscription, replay and a status that forbids the
  -- change are the delegate's refusals and stay word for word its own. The
  -- replay test in particular must run before this guard can raise: a key that
  -- already produced an event still answers `replayed`.
  IF NOT v_subscription_found
    OR v_subscription_status NOT IN ('active', 'paused')
    OR EXISTS (
      SELECT 1
        FROM public.subscription_events event
       WHERE event.subscription_id = p_subscription_id
         AND event.idempotency_key = p_idempotency_key
    )
  THEN
    RETURN public.customer_self_service_apply_action_before_address_ownership(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  -- Read the id exactly as the delegate reads it, and at the same point, so a
  -- malformed uuid still raises where it always raised.
  v_shipping_address_id := NULLIF(COALESCE(p_payload, '{}'::jsonb)->>'shippingAddressId', '')::uuid;
  IF v_shipping_address_id IS NULL THEN
    RETURN public.customer_self_service_apply_action_before_address_ownership(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  -- The one test the delegate never made. An id the caller does not own — a
  -- foreign customer's row, or no row at all — is refused with the same code the
  -- delegate raises for a wrong `kind`, so all three invalid-address causes read
  -- identically to the account surface.
  IF NOT EXISTS (
    SELECT 1
      FROM public.addresses address
     WHERE address.id = v_shipping_address_id
       AND address.client_id = v_client_id
  ) THEN
    RAISE EXCEPTION 'customer_self_service_invalid_address';
  END IF;

  RETURN public.customer_self_service_apply_action_before_address_ownership(
    p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
  );
END;
$$;


--
-- Name: FUNCTION customer_self_service_apply_subscription_action_legacy_wave5(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_self_service_apply_subscription_action_legacy_wave5(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone) IS 'Customer self-service apply body, fenced. Refuses change_shipping_address for an address id the calling client does not own with customer_self_service_invalid_address, and delegates every other request, and every other refusal, unchanged to customer_self_service_apply_action_before_address_ownership.';


--
-- Name: customer_self_service_apply_subscription_action_pre_cadence(uuid, text, uuid, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_apply_subscription_action_pre_cadence(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb DEFAULT '{}'::jsonb, p_requested_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_client_id uuid;
  v_subscription public.subscriptions%ROWTYPE;
  v_existing_event public.subscription_events%ROWTYPE;
  v_payload jsonb := COALESCE(p_payload, '{}'::jsonb);
  v_edit_cutoff timestamptz;
  v_noop boolean := false;
  v_variant_id uuid;
  v_from_variant_id uuid;
  v_to_variant_id uuid;
  v_qty integer;
  v_plan_days integer;
  v_recipe_lines jsonb := v_payload->'recipeLines';
  v_addon_lines jsonb := COALESCE(v_payload->'addonLines', '[]'::jsonb);
  v_portion_mode text;
  v_portion_factor numeric;
  v_slide_next_cycle_at timestamptz;
BEGIN
  IF p_action NOT IN (
    'swap_recipe', 'add_addon', 'remove_addon', 'update_addon_quantity',
    'update_plan_length', 'update_recipe_mix', 'set_portion_mode',
    'update_package_template', 'slide_next_cycle'
  ) THEN
    RETURN public.customer_self_service_apply_subscription_action_legacy_wave5(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  IF p_idempotency_key IS NULL OR char_length(trim(p_idempotency_key)) < 8 THEN
    RETURN public.customer_self_service_apply_subscription_action_legacy_wave5(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  SELECT id INTO v_client_id FROM public.clients WHERE auth_user_id = p_auth_user_id;
  SELECT * INTO v_subscription
    FROM public.subscriptions
    WHERE id = p_subscription_id AND client_id = v_client_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RETURN public.customer_self_service_apply_subscription_action_legacy_wave5(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  SELECT * INTO v_existing_event
    FROM public.subscription_events
    WHERE subscription_id = p_subscription_id
      AND idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN public.customer_self_service_subscription_action_response(
      v_subscription, p_action, 'replayed', v_existing_event.id
    );
  END IF;

  -- CJ56-1: a slide onto the current delivery day is a no-op. Compare calendar
  -- days in UTC to match the account modal, which marks "obecny termin" by the
  -- UTC date slice of next_cycle_at. Detect BEFORE the legacy body so no
  -- updated_at bump / subscription_events row / delivery_rescheduled email fires.
  -- (Runs after the idempotency-replay check above so a legitimate slide retried
  -- with the same key still returns `replayed`, not `noop`.)
  IF p_action = 'slide_next_cycle' THEN
    v_slide_next_cycle_at := NULLIF(v_payload->>'newNextCycleAt', '')::timestamptz;
    IF v_subscription.status = 'active'
      AND v_subscription.next_cycle_at IS NOT NULL
      AND v_slide_next_cycle_at IS NOT NULL
      AND (v_slide_next_cycle_at AT TIME ZONE 'UTC')::date
          = (v_subscription.next_cycle_at AT TIME ZONE 'UTC')::date
    THEN
      RETURN public.customer_self_service_subscription_action_response(
        v_subscription, p_action, 'noop', NULL
      );
    END IF;
    RETURN public.customer_self_service_apply_subscription_action_legacy_wave5(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  v_edit_cutoff := v_subscription.next_cycle_at - ((COALESCE(v_subscription.edit_window_hours, 24) || ' hours')::interval);
  IF v_subscription.status <> 'active'
    OR v_subscription.next_cycle_at IS NULL
    OR p_requested_at > v_edit_cutoff
    OR v_subscription.payment_method_ref IS NULL
    OR EXISTS (
      SELECT 1 FROM public.subscription_dunning_cases
      WHERE subscription_id = p_subscription_id AND status = 'open'
    )
    OR NOT (v_payload ? 'acceptedQuoteHash')
    OR COALESCE(v_payload->>'acceptedQuoteHash', '') !~ '^[a-f0-9]{64}$'
    OR NOT (v_payload ? 'expectedTemplateVersion')
    OR COALESCE(v_payload->>'expectedTemplateVersion', '') !~ '^[0-9]{1,9}$'
    OR (v_payload->>'expectedTemplateVersion')::integer <> v_subscription.template_version
  THEN
    RETURN public.customer_self_service_apply_subscription_action_legacy_wave5(
      p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
    );
  END IF;

  IF p_action = 'swap_recipe' THEN
    v_from_variant_id := NULLIF(v_payload->>'fromVariantId', '')::uuid;
    v_to_variant_id := NULLIF(v_payload->>'toVariantId', '')::uuid;
    v_noop := v_from_variant_id IS NOT NULL AND v_from_variant_id = v_to_variant_id;
  ELSIF p_action = 'add_addon' THEN
    v_variant_id := NULLIF(v_payload->>'variantId', '')::uuid;
    v_qty := GREATEST(1, COALESCE((v_payload->>'qty')::integer, 1));
    v_noop := EXISTS (
      SELECT 1 FROM public.subscription_lines
      WHERE subscription_id = p_subscription_id
        AND variant_id = v_variant_id
        AND is_addon = true
        AND qty = v_qty
    );
  ELSIF p_action = 'update_addon_quantity' THEN
    v_variant_id := NULLIF(v_payload->>'variantId', '')::uuid;
    v_qty := (v_payload->>'qty')::integer;
    v_noop := EXISTS (
      SELECT 1 FROM public.subscription_lines
      WHERE subscription_id = p_subscription_id
        AND variant_id = v_variant_id
        AND is_addon = true
        AND qty = v_qty
    );
  ELSIF p_action = 'update_recipe_mix' THEN
    v_noop := public.subscription_self_service_line_set_matches(p_subscription_id, v_recipe_lines, false);
  ELSIF p_action = 'update_plan_length' THEN
    v_plan_days := (v_payload->>'planDays')::integer;
    v_noop := v_plan_days = v_subscription.cadence_days
      AND public.subscription_self_service_line_set_matches(p_subscription_id, v_recipe_lines, false);
  ELSIF p_action = 'set_portion_mode' THEN
    v_portion_mode := COALESCE(NULLIF(v_payload->>'portionMode', ''), '');
    v_portion_factor := CASE v_portion_mode WHEN 'topper' THEN 0.5 WHEN 'full' THEN 1 ELSE NULL END;
    v_noop := v_portion_factor IS NOT NULL
      AND COALESCE(v_subscription.size_constraint->>'mode', 'full') = v_portion_mode
      AND COALESCE((v_subscription.size_constraint->>'portionFactor')::numeric, 1) = v_portion_factor
      AND public.subscription_self_service_line_set_matches(p_subscription_id, v_recipe_lines, false);
  ELSIF p_action = 'update_package_template' THEN
    v_plan_days := (v_payload->>'planDays')::integer;
    v_noop := v_plan_days = v_subscription.cadence_days
      AND public.subscription_self_service_line_set_matches(p_subscription_id, v_recipe_lines, false)
      AND public.subscription_self_service_line_set_matches(p_subscription_id, v_addon_lines, true);
  END IF;

  IF v_noop THEN
    RETURN public.customer_self_service_subscription_action_response(v_subscription, p_action, 'noop', NULL);
  END IF;

  RETURN public.customer_self_service_apply_subscription_action_legacy_wave5(
    p_auth_user_id, p_idempotency_key, p_subscription_id, p_action, p_payload, p_requested_at
  );
END;
$_$;


--
-- Name: FUNCTION customer_self_service_apply_subscription_action_pre_cadence(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_self_service_apply_subscription_action_pre_cadence(p_auth_user_id uuid, p_idempotency_key text, p_subscription_id uuid, p_action text, p_payload jsonb, p_requested_at timestamp with time zone) IS 'Customer subscription self-service action wrapper. Suppresses semantic no-op package edits AND same-calendar-day slide_next_cycle reschedules (CJ56-1) before they bump state / emit subscription.package_changed or subscription.delivery_rescheduled outbox emails; delegates real mutations to the Wave 5 legacy body.';


--
-- Name: customer_self_service_assert_jsonb_equal(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_assert_jsonb_equal(p_left jsonb, p_right jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_left IS NULL OR p_right IS NULL OR p_left <> p_right THEN
    RAISE EXCEPTION 'customer_self_service_quote_drift';
  END IF;
END;
$$;


--
-- Name: customer_self_service_assert_no_locked_cycle(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_assert_no_locked_cycle(p_subscription_id uuid, p_next_cycle_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
      FROM public.subscription_cycles
     WHERE subscription_id = p_subscription_id
       AND scheduled_at = p_next_cycle_at
       AND status IN ('payment_pending', 'paid')
  ) THEN
    RAISE EXCEPTION 'customer_self_service_payment_blocked';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.subscription_cycles AS c
      JOIN public.commerce_orders AS o ON o.subscription_cycle_id = c.id
     WHERE c.subscription_id = p_subscription_id
       AND c.scheduled_at = p_next_cycle_at
       AND o.status IN ('paid', 'fulfillment_pending', 'fulfilled')
  ) THEN
    RAISE EXCEPTION 'customer_self_service_payment_blocked';
  END IF;
END;
$$;


--
-- Name: customer_self_service_assert_subscription_quote_payload(text, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_assert_subscription_quote_payload(p_action text, p_apply_payload jsonb, p_request_payload jsonb, p_quote_snapshot jsonb, p_totals jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_apply jsonb := COALESCE(p_apply_payload, '{}'::jsonb);
  v_request jsonb := COALESCE(p_request_payload, '{}'::jsonb);
  v_snapshot jsonb := COALESCE(p_quote_snapshot, '{}'::jsonb);
  v_totals jsonb := COALESCE(p_totals, '{}'::jsonb);
BEGIN
  IF p_action IN ('add_addon', 'remove_addon', 'update_addon_quantity')
    OR p_action = 'swap_recipe'
  THEN
    IF p_action = 'swap_recipe' AND (
      v_apply->>'fromVariantId' IS DISTINCT FROM v_request->>'fromVariantId'
      OR v_apply->>'toVariantId' IS DISTINCT FROM v_request->>'toVariantId'
    ) THEN
      RAISE EXCEPTION 'customer_self_service_quote_drift';
    ELSIF p_action IN ('add_addon', 'remove_addon', 'update_addon_quantity')
      AND v_apply->>'variantId' IS DISTINCT FROM v_request->>'variantId'
    THEN
      RAISE EXCEPTION 'customer_self_service_quote_drift';
    END IF;

    IF p_action IN ('add_addon', 'update_addon_quantity')
      AND v_apply->>'qty' IS DISTINCT FROM v_request->>'qty'
    THEN
      RAISE EXCEPTION 'customer_self_service_quote_drift';
    END IF;

    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_repriced_lines(v_apply->'repricedLines'),
      public.customer_self_service_quote_repriced_lines(v_snapshot->'repricedLines')
    );
    RETURN;
  END IF;

  IF p_action = 'update_plan_length' THEN
    IF v_apply->>'planDays' IS DISTINCT FROM v_request->>'planDays' THEN
      RAISE EXCEPTION 'customer_self_service_quote_drift';
    END IF;
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_variant_qty_lines(v_apply->'recipeLines'),
      public.customer_self_service_quote_variant_qty_lines(v_snapshot->'recipeLines')
    );
    -- Recipe-set apply payload names unchanged addon price locks `repricedLines`;
    -- the preview ledger stores the same canonical rows as `addonLines`.
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_repriced_lines(v_apply->'repricedLines'),
      public.customer_self_service_quote_repriced_lines(v_snapshot->'addonLines')
    );
    RETURN;
  END IF;

  IF p_action = 'update_recipe_mix' THEN
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_variant_qty_request(v_apply->'recipes'),
      public.customer_self_service_quote_variant_qty_request(v_request->'recipes')
    );
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_variant_qty_lines(v_apply->'recipeLines'),
      public.customer_self_service_quote_variant_qty_lines(v_snapshot->'recipeLines')
    );
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_repriced_lines(v_apply->'repricedLines'),
      public.customer_self_service_quote_repriced_lines(v_snapshot->'addonLines')
    );
    RETURN;
  END IF;

  IF p_action = 'set_portion_mode' THEN
    IF v_apply->>'portionMode' IS DISTINCT FROM v_request->>'portionMode' THEN
      RAISE EXCEPTION 'customer_self_service_quote_drift';
    END IF;
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_variant_qty_lines(v_apply->'recipeLines'),
      public.customer_self_service_quote_variant_qty_lines(v_snapshot->'recipeLines')
    );
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_repriced_lines(v_apply->'repricedLines'),
      public.customer_self_service_quote_repriced_lines(v_snapshot->'addonLines')
    );
    RETURN;
  END IF;

  IF p_action = 'update_package_template' THEN
    IF v_apply->>'planDays' IS DISTINCT FROM v_request->>'planDays' THEN
      RAISE EXCEPTION 'customer_self_service_quote_drift';
    END IF;
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_variant_qty_request(v_apply->'recipes'),
      public.customer_self_service_quote_variant_qty_request(v_request->'recipes')
    );
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_variant_qty_request(v_apply->'addons'),
      public.customer_self_service_quote_variant_qty_request(COALESCE(v_request->'addons', '[]'::jsonb))
    );
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_variant_qty_lines(v_apply->'recipeLines'),
      public.customer_self_service_quote_variant_qty_lines(v_snapshot->'recipeLines')
    );
    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_variant_qty_lines(v_apply->'addonLines'),
      public.customer_self_service_quote_variant_qty_lines(COALESCE(v_snapshot->'addonLines', '[]'::jsonb))
    );
    PERFORM public.customer_self_service_assert_jsonb_equal(v_apply->'currentRecurringPrice', v_totals->'currentRecurringPrice');
    PERFORM public.customer_self_service_assert_jsonb_equal(v_apply->'newRecurringPrice', v_totals->'newRecurringPrice');
    PERFORM public.customer_self_service_assert_jsonb_equal(v_apply->'delta', v_totals->'delta');
    RETURN;
  END IF;

  IF p_action IN ('update_bundle', 'resize_bundle') THEN
    IF v_apply ? 'recipeLines' THEN
      RAISE EXCEPTION 'customer_self_service_quote_drift';
    END IF;
    PERFORM public.customer_self_service_assert_jsonb_equal(
      v_apply->'compositionConstraint',
      v_snapshot->'compositionConstraint'
    );

    IF v_request ? 'compositionConstraint' THEN
      PERFORM public.customer_self_service_assert_jsonb_equal(
        v_apply->'compositionConstraint',
        v_request->'compositionConstraint'
      );
    END IF;

    IF p_action = 'update_bundle' THEN
      PERFORM public.customer_self_service_assert_jsonb_equal(
        public.customer_self_service_quote_variant_qty_request(v_apply->'coreLines'),
        public.customer_self_service_quote_variant_qty_request(v_request->'coreLines')
      );
      IF v_request ? 'addonLines' THEN
        PERFORM public.customer_self_service_assert_jsonb_equal(
          public.customer_self_service_quote_variant_qty_request(v_apply->'addonLines'),
          public.customer_self_service_quote_variant_qty_request(v_request->'addonLines')
        );
      ELSIF v_apply ? 'addonLines' THEN
        RAISE EXCEPTION 'customer_self_service_quote_drift';
      END IF;
      IF v_apply ? 'cadenceDays' THEN
        IF NOT (v_request ? 'cadenceDays') OR v_apply->>'cadenceDays' IS DISTINCT FROM v_request->>'cadenceDays' THEN
          RAISE EXCEPTION 'customer_self_service_quote_drift';
        END IF;
      END IF;
    ELSE
      PERFORM public.customer_self_service_assert_jsonb_equal(v_apply->'resizeLever', v_request->'resizeLever');
      IF v_apply ? 'cadenceDays' THEN
        IF NOT (v_request ? 'cadenceDays') OR v_apply->>'cadenceDays' IS DISTINCT FROM v_request->>'cadenceDays' THEN
          RAISE EXCEPTION 'customer_self_service_quote_drift';
        END IF;
      END IF;
    END IF;

    PERFORM public.customer_self_service_assert_jsonb_equal(
      public.customer_self_service_quote_variant_qty_lines(v_apply->'coreLines'),
      public.customer_self_service_quote_variant_qty_lines(v_snapshot->'recipeLines')
    );
    IF jsonb_typeof(v_apply->'addonLines') = 'array' THEN
      PERFORM public.customer_self_service_assert_jsonb_equal(
        public.customer_self_service_quote_variant_qty_lines(v_apply->'addonLines'),
        public.customer_self_service_quote_variant_qty_lines(COALESCE(v_snapshot->'addonLines', '[]'::jsonb))
      );
    ELSE
      PERFORM public.customer_self_service_assert_jsonb_equal(
        public.customer_self_service_quote_repriced_lines(v_apply->'repricedLines'),
        public.customer_self_service_quote_repriced_lines(COALESCE(v_snapshot->'addonLines', '[]'::jsonb))
      );
    END IF;
    RETURN;
  END IF;
END;
$$;


--
-- Name: customer_self_service_prune_subscription_quote_previews(interval, integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_prune_subscription_quote_previews(p_retention interval DEFAULT '7 days'::interval, p_limit integer DEFAULT 1000, p_pruned_at timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_deleted integer := 0;
BEGIN
  IF p_retention IS NULL OR p_retention < interval '0 seconds' THEN
    RAISE EXCEPTION 'customer_self_service_invalid_quote_preview_retention';
  END IF;
  IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 10000 THEN
    RAISE EXCEPTION 'customer_self_service_invalid_quote_preview_prune_limit';
  END IF;

  WITH doomed AS (
    SELECT id
      FROM public.subscription_quote_previews
     WHERE status = 'previewed'
       AND expires_at < p_pruned_at - p_retention
     ORDER BY expires_at ASC
     LIMIT p_limit
  ),
  deleted AS (
    DELETE FROM public.subscription_quote_previews previews
     USING doomed
     WHERE previews.id = doomed.id
     RETURNING 1
  )
  SELECT count(*)::integer INTO v_deleted FROM deleted;

  RETURN COALESCE(v_deleted, 0);
END;
$$;


--
-- Name: customer_self_service_quote_repriced_lines(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_quote_repriced_lines(p_lines jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
  SELECT CASE
    WHEN jsonb_typeof(p_lines) = 'array' THEN COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'lineId', elem.value->>'lineId',
          'quoteLine', CASE
            WHEN jsonb_typeof(quote_line.value) <> 'object' THEN quote_line.value
            WHEN jsonb_typeof(catalog_facts.value) <> 'object' THEN quote_line.value
            WHEN (
              (
                catalog_facts.value->>'version' = 'catalog_facts_v1'
                AND ARRAY(SELECT key FROM jsonb_object_keys(catalog_facts.value) AS key ORDER BY key) = ARRAY[
                  'atTime', 'basePriceEntryId', 'baseUnitAmountMinor', 'currency', 'documentDigest',
                  'documentRevisionId', 'mode', 'resolvedLineAmountMinor', 'resolvedPriceEntryId',
                  'resolvedUnitAmountMinor', 'skuId', 'version'
                ]::text[]
                AND jsonb_typeof(catalog_facts.value->'resolvedPriceEntryId') = 'string'
                AND char_length(btrim(catalog_facts.value->>'resolvedPriceEntryId', U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'))
                    + regexp_count(btrim(catalog_facts.value->>'resolvedPriceEntryId', U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') COLLATE "C", '[' || chr(65536) || '-' || chr(1114111) || ']') BETWEEN 1 AND 120
                AND catalog_facts.value->>'mode' IN ('one_time', 'subscription')
              )
              OR (
                catalog_facts.value->>'version' = 'catalog_facts_v2'
                AND ARRAY(SELECT key FROM jsonb_object_keys(catalog_facts.value) AS key ORDER BY key) = ARRAY[
                  'atTime', 'basePriceEntryId', 'baseUnitAmountMinor', 'currency', 'documentDigest',
                  'documentRevisionId', 'mode', 'policyDigest', 'policyRevisionId', 'resolvedLineAmountMinor',
                  'resolvedUnitAmountMinor', 'skuId', 'version'
                ]::text[]
                AND jsonb_typeof(catalog_facts.value->'policyRevisionId') = 'string'
                AND (catalog_facts.value->>'policyRevisionId') COLLATE "C" ~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$'
                AND jsonb_typeof(catalog_facts.value->'policyDigest') = 'string'
                AND (catalog_facts.value->>'policyDigest') COLLATE "C" ~* '^[a-f0-9]{64}$'
                AND catalog_facts.value->>'mode' = 'subscription'
              )
            )
            AND jsonb_typeof(catalog_facts.value->'skuId') = 'string'
            AND (catalog_facts.value->>'skuId') COLLATE "C" ~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$'
            AND jsonb_typeof(catalog_facts.value->'documentRevisionId') = 'string'
            AND (catalog_facts.value->>'documentRevisionId') COLLATE "C" ~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$'
            AND jsonb_typeof(catalog_facts.value->'documentDigest') = 'string'
            AND (catalog_facts.value->>'documentDigest') COLLATE "C" ~* '^[a-f0-9]{64}$'
            AND jsonb_typeof(catalog_facts.value->'basePriceEntryId') = 'string'
            AND char_length(btrim(catalog_facts.value->>'basePriceEntryId', U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'))
                + regexp_count(btrim(catalog_facts.value->>'basePriceEntryId', U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') COLLATE "C", '[' || chr(65536) || '-' || chr(1114111) || ']') BETWEEN 1 AND 120
            AND jsonb_typeof(catalog_facts.value->'atTime') = 'string'
            AND (catalog_facts.value->>'atTime') COLLATE "C" ~ '^(([0-9][0-9][2468][048]|[0-9][0-9][13579][26]|[0-9][0-9]0[48]|[02468][048]00|[13579][26]00)-02-29|[0-9]{4}-((0[13578]|1[02])-(0[1-9]|[12][0-9]|3[01])|(0[469]|11)-(0[1-9]|[12][0-9]|30)|(02)-(0[1-9]|1[0-9]|2[0-8])))T([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9](\.[0-9]+)?)?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$'
            AND jsonb_typeof(catalog_facts.value->'currency') = 'string'
            AND (catalog_facts.value->>'currency') COLLATE "C" ~ '^[A-Z]{3}$'
            AND jsonb_typeof(catalog_facts.value->'resolvedUnitAmountMinor') = 'number'
            AND (catalog_facts.value->>'resolvedUnitAmountMinor') COLLATE "C" ~ '^(0|[1-9][0-9]*)(\.0+)?$'
            AND CASE WHEN jsonb_typeof(catalog_facts.value->'resolvedUnitAmountMinor') = 'number' THEN (catalog_facts.value->>'resolvedUnitAmountMinor')::numeric <= 9007199254740991 ELSE FALSE END
            AND jsonb_typeof(catalog_facts.value->'resolvedLineAmountMinor') = 'number'
            AND (catalog_facts.value->>'resolvedLineAmountMinor') COLLATE "C" ~ '^(0|[1-9][0-9]*)(\.0+)?$'
            AND CASE WHEN jsonb_typeof(catalog_facts.value->'resolvedLineAmountMinor') = 'number' THEN (catalog_facts.value->>'resolvedLineAmountMinor')::numeric <= 9007199254740991 ELSE FALSE END
            AND jsonb_typeof(catalog_facts.value->'baseUnitAmountMinor') = 'number'
            AND (catalog_facts.value->>'baseUnitAmountMinor') COLLATE "C" ~ '^(0|[1-9][0-9]*)(\.0+)?$'
            AND CASE WHEN jsonb_typeof(catalog_facts.value->'baseUnitAmountMinor') = 'number' THEN (catalog_facts.value->>'baseUnitAmountMinor')::numeric <= 9007199254740991 ELSE FALSE END
            THEN jsonb_set(quote_line.value, '{catalogFacts}', jsonb_build_object('validObservationTime', true, 'value', catalog_facts.value - 'atTime'))
            ELSE jsonb_set(quote_line.value, '{catalogFacts}', jsonb_build_object('validObservationTime', false, 'value', catalog_facts.value))
          END
        )
        ORDER BY elem.ordinality
      )
      FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS elem(value, ordinality)
      CROSS JOIN LATERAL (SELECT COALESCE(elem.value->'quoteLine', '{}'::jsonb) AS value) AS quote_line
      CROSS JOIN LATERAL (SELECT quote_line.value->'catalogFacts' AS value) AS catalog_facts
    ), '[]'::jsonb)
    ELSE NULL
  END;
$_$;


--
-- Name: customer_self_service_quote_variant_qty_lines(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_quote_variant_qty_lines(p_lines jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
  SELECT CASE
    WHEN jsonb_typeof(p_lines) = 'array' THEN COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'variantId', elem.value->>'variantId',
          'qty', CASE
            WHEN COALESCE(elem.value->>'qty', '') ~ '^-?[0-9]+$' THEN (elem.value->>'qty')::integer
            ELSE NULL
          END,
          'quoteLine', CASE
            WHEN jsonb_typeof(quote_line.value) <> 'object' THEN quote_line.value
            WHEN jsonb_typeof(catalog_facts.value) <> 'object' THEN quote_line.value
            WHEN (
              (
                catalog_facts.value->>'version' = 'catalog_facts_v1'
                AND ARRAY(SELECT key FROM jsonb_object_keys(catalog_facts.value) AS key ORDER BY key) = ARRAY[
                  'atTime', 'basePriceEntryId', 'baseUnitAmountMinor', 'currency', 'documentDigest',
                  'documentRevisionId', 'mode', 'resolvedLineAmountMinor', 'resolvedPriceEntryId',
                  'resolvedUnitAmountMinor', 'skuId', 'version'
                ]::text[]
                AND jsonb_typeof(catalog_facts.value->'resolvedPriceEntryId') = 'string'
                AND char_length(btrim(catalog_facts.value->>'resolvedPriceEntryId', U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'))
                    + regexp_count(btrim(catalog_facts.value->>'resolvedPriceEntryId', U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') COLLATE "C", '[' || chr(65536) || '-' || chr(1114111) || ']') BETWEEN 1 AND 120
                AND catalog_facts.value->>'mode' IN ('one_time', 'subscription')
              )
              OR (
                catalog_facts.value->>'version' = 'catalog_facts_v2'
                AND ARRAY(SELECT key FROM jsonb_object_keys(catalog_facts.value) AS key ORDER BY key) = ARRAY[
                  'atTime', 'basePriceEntryId', 'baseUnitAmountMinor', 'currency', 'documentDigest',
                  'documentRevisionId', 'mode', 'policyDigest', 'policyRevisionId', 'resolvedLineAmountMinor',
                  'resolvedUnitAmountMinor', 'skuId', 'version'
                ]::text[]
                AND jsonb_typeof(catalog_facts.value->'policyRevisionId') = 'string'
                AND (catalog_facts.value->>'policyRevisionId') COLLATE "C" ~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$'
                AND jsonb_typeof(catalog_facts.value->'policyDigest') = 'string'
                AND (catalog_facts.value->>'policyDigest') COLLATE "C" ~* '^[a-f0-9]{64}$'
                AND catalog_facts.value->>'mode' = 'subscription'
              )
            )
            AND jsonb_typeof(catalog_facts.value->'skuId') = 'string'
            AND (catalog_facts.value->>'skuId') COLLATE "C" ~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$'
            AND jsonb_typeof(catalog_facts.value->'documentRevisionId') = 'string'
            AND (catalog_facts.value->>'documentRevisionId') COLLATE "C" ~ '^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$'
            AND jsonb_typeof(catalog_facts.value->'documentDigest') = 'string'
            AND (catalog_facts.value->>'documentDigest') COLLATE "C" ~* '^[a-f0-9]{64}$'
            AND jsonb_typeof(catalog_facts.value->'basePriceEntryId') = 'string'
            AND char_length(btrim(catalog_facts.value->>'basePriceEntryId', U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF'))
                + regexp_count(btrim(catalog_facts.value->>'basePriceEntryId', U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') COLLATE "C", '[' || chr(65536) || '-' || chr(1114111) || ']') BETWEEN 1 AND 120
            AND jsonb_typeof(catalog_facts.value->'atTime') = 'string'
            AND (catalog_facts.value->>'atTime') COLLATE "C" ~ '^(([0-9][0-9][2468][048]|[0-9][0-9][13579][26]|[0-9][0-9]0[48]|[02468][048]00|[13579][26]00)-02-29|[0-9]{4}-((0[13578]|1[02])-(0[1-9]|[12][0-9]|3[01])|(0[469]|11)-(0[1-9]|[12][0-9]|30)|(02)-(0[1-9]|1[0-9]|2[0-8])))T([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9](\.[0-9]+)?)?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$'
            AND jsonb_typeof(catalog_facts.value->'currency') = 'string'
            AND (catalog_facts.value->>'currency') COLLATE "C" ~ '^[A-Z]{3}$'
            AND jsonb_typeof(catalog_facts.value->'resolvedUnitAmountMinor') = 'number'
            AND (catalog_facts.value->>'resolvedUnitAmountMinor') COLLATE "C" ~ '^(0|[1-9][0-9]*)(\.0+)?$'
            AND CASE WHEN jsonb_typeof(catalog_facts.value->'resolvedUnitAmountMinor') = 'number' THEN (catalog_facts.value->>'resolvedUnitAmountMinor')::numeric <= 9007199254740991 ELSE FALSE END
            AND jsonb_typeof(catalog_facts.value->'resolvedLineAmountMinor') = 'number'
            AND (catalog_facts.value->>'resolvedLineAmountMinor') COLLATE "C" ~ '^(0|[1-9][0-9]*)(\.0+)?$'
            AND CASE WHEN jsonb_typeof(catalog_facts.value->'resolvedLineAmountMinor') = 'number' THEN (catalog_facts.value->>'resolvedLineAmountMinor')::numeric <= 9007199254740991 ELSE FALSE END
            AND jsonb_typeof(catalog_facts.value->'baseUnitAmountMinor') = 'number'
            AND (catalog_facts.value->>'baseUnitAmountMinor') COLLATE "C" ~ '^(0|[1-9][0-9]*)(\.0+)?$'
            AND CASE WHEN jsonb_typeof(catalog_facts.value->'baseUnitAmountMinor') = 'number' THEN (catalog_facts.value->>'baseUnitAmountMinor')::numeric <= 9007199254740991 ELSE FALSE END
            THEN jsonb_set(quote_line.value, '{catalogFacts}', jsonb_build_object('validObservationTime', true, 'value', catalog_facts.value - 'atTime'))
            ELSE jsonb_set(quote_line.value, '{catalogFacts}', jsonb_build_object('validObservationTime', false, 'value', catalog_facts.value))
          END
        )
        ORDER BY elem.ordinality
      )
      FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS elem(value, ordinality)
      CROSS JOIN LATERAL (SELECT COALESCE(elem.value->'quoteLine', '{}'::jsonb) AS value) AS quote_line
      CROSS JOIN LATERAL (SELECT quote_line.value->'catalogFacts' AS value) AS catalog_facts
    ), '[]'::jsonb)
    ELSE NULL
  END;
$_$;


--
-- Name: customer_self_service_quote_variant_qty_request(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_quote_variant_qty_request(p_lines jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
  SELECT CASE
    WHEN jsonb_typeof(p_lines) = 'array' THEN COALESCE((
      SELECT jsonb_agg(
        jsonb_build_object(
          'variantId', elem.value->>'variantId',
          'qty', CASE
            WHEN COALESCE(elem.value->>'qty', '') ~ '^-?[0-9]+$' THEN (elem.value->>'qty')::integer
            ELSE NULL
          END
        )
        ORDER BY elem.ordinality
      )
      FROM jsonb_array_elements(p_lines) WITH ORDINALITY AS elem(value, ordinality)
    ), '[]'::jsonb)
    ELSE NULL
  END;
$_$;


--
-- Name: customer_self_service_record_subscription_quote_preview(uuid, uuid, text, text, integer, timestamp with time zone, jsonb, jsonb, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_record_subscription_quote_preview(p_auth_user_id uuid, p_subscription_id uuid, p_action text, p_quote_hash text, p_template_version integer, p_quote_expires_at timestamp with time zone, p_request_payload jsonb DEFAULT '{}'::jsonb, p_quote_snapshot jsonb DEFAULT '{}'::jsonb, p_totals jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb, p_recorded_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_client_id uuid;
  v_subscription public.subscriptions%ROWTYPE;
  v_quote public.subscription_quote_previews%ROWTYPE;
BEGIN
  IF p_action NOT IN ('add_addon', 'remove_addon', 'update_addon_quantity',
                      'swap_recipe', 'update_plan_length', 'update_recipe_mix',
                      'set_portion_mode', 'update_package_template',
                      'update_bundle', 'resize_bundle')
  THEN
    RAISE EXCEPTION 'customer_self_service_invalid_action';
  END IF;
  IF p_quote_hash IS NULL OR p_quote_hash !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'customer_self_service_quote_not_accepted';
  END IF;
  IF p_template_version IS NULL OR p_template_version <= 0 THEN
    RAISE EXCEPTION 'customer_self_service_stale_edit';
  END IF;
  IF p_quote_expires_at IS NULL OR p_quote_expires_at <= p_recorded_at THEN
    RAISE EXCEPTION 'customer_self_service_quote_expired';
  END IF;

  SELECT id INTO v_client_id
    FROM public.clients
   WHERE auth_user_id = p_auth_user_id;
  IF v_client_id IS NULL THEN
    RAISE EXCEPTION 'customer_self_service_not_found';
  END IF;

  SELECT * INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
     AND client_id = v_client_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'customer_self_service_forbidden';
  END IF;
  IF v_subscription.template_version <> p_template_version THEN
    RAISE EXCEPTION 'customer_self_service_stale_edit';
  END IF;

  PERFORM public.customer_self_service_prune_subscription_quote_previews(
    '7 days'::interval,
    500,
    p_recorded_at
  );

  INSERT INTO public.subscription_quote_previews (
    subscription_id,
    client_id,
    created_by_auth_user_id,
    action,
    quote_hash,
    template_version,
    expires_at,
    request_payload,
    quote_snapshot,
    totals,
    metadata,
    created_at,
    updated_at
  ) VALUES (
    p_subscription_id,
    v_client_id,
    p_auth_user_id,
    p_action,
    p_quote_hash,
    p_template_version,
    p_quote_expires_at,
    COALESCE(p_request_payload, '{}'::jsonb),
    COALESCE(p_quote_snapshot, '{}'::jsonb),
    COALESCE(p_totals, '{}'::jsonb),
    COALESCE(p_metadata, '{}'::jsonb),
    p_recorded_at,
    p_recorded_at
  )
  ON CONFLICT (subscription_id, client_id, action, quote_hash, template_version)
    WHERE status = 'previewed'
  DO UPDATE SET
    created_by_auth_user_id = EXCLUDED.created_by_auth_user_id,
    expires_at = EXCLUDED.expires_at,
    request_payload = EXCLUDED.request_payload,
    quote_snapshot = EXCLUDED.quote_snapshot,
    totals = EXCLUDED.totals,
    metadata = EXCLUDED.metadata,
    created_at = EXCLUDED.created_at,
    updated_at = EXCLUDED.updated_at
  RETURNING * INTO v_quote;

  RETURN jsonb_build_object(
    'contractVersion', 'customer.subscription_quote_preview.v1',
    'quotePreview', jsonb_build_object(
      'id', v_quote.id,
      'subscriptionId', v_quote.subscription_id,
      'action', v_quote.action,
      'quoteHash', v_quote.quote_hash,
      'templateVersion', v_quote.template_version,
      'quoteExpiresAt', v_quote.expires_at,
      'status', v_quote.status
    )
  );
END;
$_$;


--
-- Name: subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    pet_id uuid,
    cadence_days integer NOT NULL,
    size_constraint jsonb,
    currency text NOT NULL,
    region_code text DEFAULT 'PL'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    next_cycle_at timestamp with time zone,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    ended_at timestamp with time zone,
    edit_window_hours integer DEFAULT 72,
    shipping_address_id uuid,
    billing_address_id uuid,
    cancellation_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    template_version integer DEFAULT 1 NOT NULL,
    payment_method_ref text,
    payment_method_kind text,
    timezone text DEFAULT 'Europe/Warsaw'::text NOT NULL,
    cancellation_source text,
    offer_policy_version text DEFAULT 'commerce.offer-policy.v1'::text NOT NULL,
    promotion_engine_version text DEFAULT 'promotion-engine.v1'::text NOT NULL,
    offer_policy_assignment_state text DEFAULT 'pending_acquisition'::text NOT NULL,
    is_test_fixture boolean DEFAULT false NOT NULL,
    starter_pack jsonb,
    CONSTRAINT subscriptions_cadence_days_check CHECK ((cadence_days > 0)),
    CONSTRAINT subscriptions_check CHECK (((ended_at IS NULL) OR (ended_at >= started_at))),
    CONSTRAINT subscriptions_currency_check CHECK ((char_length(currency) = 3)),
    CONSTRAINT subscriptions_edit_window_hours_check CHECK (((edit_window_hours IS NULL) OR (edit_window_hours >= 0))),
    CONSTRAINT subscriptions_region_code_check CHECK (((char_length(region_code) >= 2) AND (char_length(region_code) <= 3))),
    CONSTRAINT subscriptions_status_check CHECK ((status = ANY (ARRAY['pending_activation'::text, 'active'::text, 'paused'::text, 'cancelled'::text, 'completed'::text, 'activation_failed'::text]))),
    CONSTRAINT subscriptions_template_version_check CHECK ((template_version > 0))
);


--
-- Name: COLUMN subscriptions.next_cycle_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.next_cycle_at IS 'Operational next renewal time owned by the openlup subscription engine. Hidden runners may use it only after an explicit activation wave; it is no longer a provider mirror field.';


--
-- Name: COLUMN subscriptions.template_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.template_version IS 'Monotonic version of the subscription template. Every default edit increments this value; cycles snapshot the version they were generated from.';


--
-- Name: COLUMN subscriptions.payment_method_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.payment_method_ref IS 'Opaque payment-method token/reference stored by the payment provider. Not a subscription-provider reference.';


--
-- Name: COLUMN subscriptions.cancellation_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.cancellation_source IS 'Positive provenance marker for cancellation emails. The voluntary customer cancellation email sends only after customer_self_service is recorded.';


--
-- Name: COLUMN subscriptions.offer_policy_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.offer_policy_version IS 'Immutable acquisition policy assigned by the backend; renewals never infer a newer policy.';


--
-- Name: COLUMN subscriptions.promotion_engine_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.promotion_engine_version IS 'Immutable promotion engine paired with offer_policy_version at acquisition.';


--
-- Name: COLUMN subscriptions.offer_policy_assignment_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.offer_policy_assignment_state IS 'Acquisition-only seam: pre-migration legacy_frozen, new pending_acquisition, then immutable assigned_acquisition.';


--
-- Name: COLUMN subscriptions.is_test_fixture; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.is_test_fixture IS 'Explicit synthetic-test marker. Only true rows are excluded from the immutable offer-policy legacy customer cohort.';


--
-- Name: COLUMN subscriptions.starter_pack; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscriptions.starter_pack IS 'Immutable acquisition marker for the starter-pack offer, written exactly once by subscription_create_provisional_for_checkout and thereafter only clearable to NULL. The starter PHASE is DERIVED, never stored: delivery-2 = marker present AND subscription_cycles.cycle_number = 2; graduation-due = marker present AND cycle_number >= 3 AND subscriptions.template_version = (starter_pack->>''basisTemplateVersion'')::int. Never add a mutable phase field to this table: it would become a second, corruptible source of truth for something the existing rows already answer.';


--
-- Name: customer_self_service_subscription_action_response(public.subscriptions, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_self_service_subscription_action_response(p_subscription public.subscriptions, p_action text, p_status text, p_event_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'contractVersion', 'customer.self_service.v1',
    'subscriptionAction', jsonb_build_object(
      'subscriptionId', p_subscription.id,
      'action', p_action,
      'status', p_status,
      'subscriptionStatus', p_subscription.status,
      'nextCycleAt', p_subscription.next_cycle_at,
      'templateVersion', p_subscription.template_version,
      'eventId', p_event_id
    )
  );
$$;


--
-- Name: customer_support_absorb_lead_v1(uuid, uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_support_absorb_lead_v1(p_operator_id uuid, p_customer_id uuid, p_lead_id uuid, p_expected_lead_email text, p_idempotency_key text, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_existing public.customer_support_subscription_commands%ROWTYPE;
  v_lead public.clients%ROWTYPE;
  v_customer public.clients%ROWTYPE;
  v_now timestamptz := COALESCE(p_now, now());
  v_expected text := lower(btrim(COALESCE(p_expected_lead_email, '')));
  v_fingerprint text;
  v_refusal_code text;
  v_outcome text;
  v_response jsonb;
  v_referencing record;
  v_blocking text[] := ARRAY[]::text[];
  v_unclassified text[] := ARRAY[]::text[];
  v_named text[] := ARRAY[]::text[];
  v_present bigint;
  v_moved bigint;
  v_carried jsonb := jsonb_build_object(
    'personalization', 0, 'consents', 0, 'sourceLinks', 0, 'deliveries', 0);
  v_carried_by_table jsonb := '{}'::jsonb;
  v_conflict record;
  v_lead_email text;
  v_tombstone text;
  v_subject_id uuid;
BEGIN
  -- The gate answers first, before a single row of customer state is read.
  PERFORM public.communications_require_active_operator(p_operator_id);

  -- And the operator is a person. Re-derived from the administrator roster for the
  -- principal this call was handed, never taken from a claim the caller supplied. A
  -- principal with no administrator row answers NULL here and is unaffected.
  IF COALESCE((
    SELECT admin_row.is_machine_actor
      FROM public.admin_users AS admin_row
     WHERE admin_row.id = p_operator_id
  ), false) THEN
    RAISE EXCEPTION 'customer_support_command_requires_human' USING ERRCODE = '42501';
  END IF;

  IF p_customer_id IS NULL
     OR p_lead_id IS NULL
     OR p_customer_id = p_lead_id
     OR char_length(btrim(COALESCE(p_idempotency_key, ''))) NOT BETWEEN 8 AND 200
     OR char_length(v_expected) NOT BETWEEN 3 AND 320
  THEN
    RAISE EXCEPTION 'customer_support_absorb_lead_invalid' USING ERRCODE = '22023';
  END IF;

  v_fingerprint := encode(
    pg_catalog.sha256(pg_catalog.convert_to(
      'lead_absorption|' || p_customer_id::text || '|' || p_lead_id::text || '|' || v_expected, 'utf8')),
    'hex');

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('customer-support-subscription:' || p_idempotency_key, 0)
  );
  -- Both subjects, in a fixed id order, so two absorptions naming the same pair
  -- from opposite directions serialize instead of deadlocking. Proving the lead
  -- is empty and then emptying it has to be one indivisible act: a concurrent
  -- insert between the two is the only way this routine could destroy data.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('customer-support-subject:'
      || LEAST(p_customer_id, p_lead_id)::text, 0));
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('customer-support-subject:'
      || GREATEST(p_customer_id, p_lead_id)::text, 0));

  SELECT * INTO v_existing
    FROM public.customer_support_subscription_commands AS command_row
   WHERE command_row.idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.payload_fingerprint <> v_fingerprint
       OR v_existing.operator_id <> p_operator_id
       OR v_existing.target_id <> p_lead_id
       OR v_existing.command_kind <> 'lead_absorption'
    THEN
      RAISE EXCEPTION 'customer_support_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    IF v_existing.response->>'outcome' IN ('refused', 'conflict') THEN
      RETURN v_existing.response;
    END IF;
    RETURN jsonb_set(v_existing.response, '{outcome}', '"replayed"'::jsonb, true);
  END IF;

  SELECT * INTO v_lead
    FROM public.clients AS lead_row
   WHERE lead_row.id = p_lead_id
   FOR UPDATE;
  IF NOT FOUND THEN
    v_refusal_code := 'lead_not_found';
  END IF;

  IF v_refusal_code IS NULL THEN
    SELECT * INTO v_customer
      FROM public.clients AS customer_row
     WHERE customer_row.id = p_customer_id
     FOR UPDATE;
    IF NOT FOUND THEN
      v_refusal_code := 'customer_not_found';
    ELSE
      v_subject_id := p_customer_id;
    END IF;
  END IF;

  v_lead_email := v_lead.email;

  -- An already-absorbed pair is a settled fact, not a stale expectation: the
  -- address it is asked about is precisely the one this routine moved away.
  IF v_refusal_code IS NULL
     AND v_lead.metadata #>> '{absorption,absorbedIntoClientId}' = p_customer_id::text
  THEN
    v_outcome := 'noop';
  ELSIF v_refusal_code IS NULL
        AND lower(btrim(COALESCE(v_lead.email, ''))) IS DISTINCT FROM v_expected
  THEN
    -- The operator acted on a snapshot of the holder; a changed address means
    -- the console must be re-read before anything is moved.
    v_refusal_code := 'lead_email_expectation_conflict';
  END IF;

  IF v_refusal_code IS NULL AND v_outcome IS NULL AND v_lead.auth_user_id IS NOT NULL THEN
    v_refusal_code := 'lead_has_identity';
  END IF;

  IF v_refusal_code IS NULL AND v_outcome IS NULL THEN
    -- The live foreign-key set, not a compiled-in list. `conkey`/`confkey` are
    -- walked together so the column is the one that actually points at
    -- clients.id whatever it is called locally.
    FOR v_referencing IN
      SELECT referencing.relname::text AS table_name,
             local_column.attname::text AS column_name,
             policy_row.disposition AS disposition
        FROM pg_catalog.pg_constraint AS fk
        JOIN pg_catalog.pg_class AS referencing ON referencing.oid = fk.conrelid
        JOIN pg_catalog.pg_namespace AS referencing_schema
          ON referencing_schema.oid = referencing.relnamespace
        CROSS JOIN LATERAL unnest(fk.conkey, fk.confkey) AS key_pair(local_attnum, remote_attnum)
        JOIN pg_catalog.pg_attribute AS local_column
          ON local_column.attrelid = fk.conrelid AND local_column.attnum = key_pair.local_attnum
        JOIN pg_catalog.pg_attribute AS remote_column
          ON remote_column.attrelid = fk.confrelid AND remote_column.attnum = key_pair.remote_attnum
        LEFT JOIN public.client_absorption_policy AS policy_row
          ON policy_row.table_name = referencing.relname
       WHERE fk.contype = 'f'
         AND fk.confrelid = 'public.clients'::regclass
         AND referencing_schema.nspname = 'public'
         AND remote_column.attname = 'id'
       ORDER BY 1, 2
    LOOP
      IF v_referencing.disposition IS NULL THEN
        IF NOT (v_referencing.table_name = ANY (v_unclassified)) THEN
          v_unclassified := v_unclassified || v_referencing.table_name;
        END IF;
      ELSIF v_referencing.disposition = 'block' THEN
        EXECUTE format(
          'SELECT count(*) FROM public.%I AS blocking_row WHERE blocking_row.%I = $1',
          v_referencing.table_name, v_referencing.column_name)
          INTO v_present USING p_lead_id;
        IF v_present > 0 AND NOT (v_referencing.table_name = ANY (v_blocking)) THEN
          v_blocking := v_blocking || v_referencing.table_name;
        END IF;
      END IF;
    END LOOP;

    IF array_length(v_unclassified, 1) IS NOT NULL THEN
      -- Fail closed, and say where the answer goes.
      v_refusal_code := 'unclassified_referencing_table';
      v_named := v_unclassified;
    ELSIF array_length(v_blocking, 1) IS NOT NULL THEN
      v_refusal_code := 'lead_has_commercial_footprint';
      v_named := v_blocking;
    END IF;
  END IF;

  IF v_refusal_code IS NULL AND v_outcome IS NULL THEN
    FOR v_referencing IN
      SELECT referencing.relname::text AS table_name,
             local_column.attname::text AS column_name
        FROM pg_catalog.pg_constraint AS fk
        JOIN pg_catalog.pg_class AS referencing ON referencing.oid = fk.conrelid
        JOIN pg_catalog.pg_namespace AS referencing_schema
          ON referencing_schema.oid = referencing.relnamespace
        CROSS JOIN LATERAL unnest(fk.conkey, fk.confkey) AS key_pair(local_attnum, remote_attnum)
        JOIN pg_catalog.pg_attribute AS local_column
          ON local_column.attrelid = fk.conrelid AND local_column.attnum = key_pair.local_attnum
        JOIN pg_catalog.pg_attribute AS remote_column
          ON remote_column.attrelid = fk.confrelid AND remote_column.attnum = key_pair.remote_attnum
        JOIN public.client_absorption_policy AS policy_row
          ON policy_row.table_name = referencing.relname
       WHERE fk.contype = 'f'
         AND fk.confrelid = 'public.clients'::regclass
         AND referencing_schema.nspname = 'public'
         AND remote_column.attname = 'id'
         AND policy_row.disposition = 'carry'
       ORDER BY 1, 2
    LOOP
      BEGIN
        IF v_referencing.table_name = 'client_consents' THEN
          -- The one arbitration the schema cannot express: client_consents has
          -- no uniqueness, so a same-kind collision would otherwise leave the
          -- customer holding two answers to one legal question. The lead's grant
          -- travels only when it is the earlier evidence of its kind; the rest
          -- stay on the archived record and are audited below.
          UPDATE public.client_consents AS lead_consent
             SET client_id = p_customer_id
           WHERE lead_consent.client_id = p_lead_id
             AND NOT EXISTS (
               SELECT 1
                 FROM public.client_consents AS held_consent
                WHERE held_consent.client_id = p_customer_id
                  AND held_consent.consent_type = lead_consent.consent_type
                  AND held_consent.captured_at <= lead_consent.captured_at);
          GET DIAGNOSTICS v_moved = ROW_COUNT;
        ELSE
          EXECUTE format(
            'UPDATE public.%I AS carried_row SET %I = $1 WHERE carried_row.%I = $2',
            v_referencing.table_name, v_referencing.column_name, v_referencing.column_name)
            USING p_customer_id, p_lead_id;
          GET DIAGNOSTICS v_moved = ROW_COUNT;
        END IF;
      EXCEPTION WHEN unique_violation THEN
        -- The customer already occupies this table's own key. Theirs is kept
        -- untouched and the lead's stays on the archived record; overwriting
        -- would be the one destructive act this routine must never perform.
        v_moved := 0;
        INSERT INTO public.customer_support_subscription_audit_events (
          operator_id, subject_id, target_id, command_kind, requested_action,
          idempotency_key, outcome, refusal_code, value_before, value_after, occurred_at
        ) VALUES (
          p_operator_id, v_subject_id, p_lead_id, 'lead_absorption',
          'absorb_lead_carry_conflict', p_idempotency_key, 'noop', NULL,
          v_referencing.table_name, 'retained_by_customer', v_now
        );
      END;
      v_carried_by_table := v_carried_by_table
        || jsonb_build_object(v_referencing.table_name, v_moved);
    END LOOP;

    FOR v_conflict IN
      SELECT lead_consent.consent_type,
             lead_consent.captured_at AS lead_captured_at,
             (SELECT min(held_consent.captured_at)
                FROM public.client_consents AS held_consent
               WHERE held_consent.client_id = p_customer_id
                 AND held_consent.consent_type = lead_consent.consent_type) AS retained_captured_at
        FROM public.client_consents AS lead_consent
       WHERE lead_consent.client_id = p_lead_id
       ORDER BY lead_consent.consent_type, lead_consent.captured_at
    LOOP
      INSERT INTO public.customer_support_subscription_audit_events (
        operator_id, subject_id, target_id, command_kind, requested_action,
        idempotency_key, outcome, refusal_code, value_before, value_after, occurred_at
      ) VALUES (
        p_operator_id, v_subject_id, p_lead_id, 'lead_absorption',
        'absorb_lead_consent_conflict', p_idempotency_key, 'noop', NULL,
        v_conflict.consent_type || '@' || v_conflict.lead_captured_at::text,
        v_conflict.consent_type || '@' || v_conflict.retained_captured_at::text,
        v_now
      );
    END LOOP;

    v_carried := jsonb_build_object(
      'personalization', COALESCE((v_carried_by_table->>'customer_personalization')::int, 0),
      'consents', COALESCE((v_carried_by_table->>'client_consents')::int, 0),
      'sourceLinks', COALESCE((v_carried_by_table->>'client_source_links')::int, 0),
      'deliveries', COALESCE((v_carried_by_table->>'communication_email_deliveries')::int, 0));

    -- The reserved .invalid namespace can never resolve, so the archived row
    -- can hold an address forever without anyone ever mailing it -- and the
    -- real one is now free for the correction that was refused.
    v_tombstone := 'absorbed+' || replace(p_lead_id::text, '-', '') || '@absorbed.invalid';
    UPDATE public.clients AS lead_row
       SET email = v_tombstone,
           metadata = lead_row.metadata || jsonb_build_object(
             'absorption', jsonb_build_object(
               'absorbedIntoClientId', p_customer_id,
               'absorbedAt', v_now,
               'originalEmail', v_lead_email,
               'idempotencyKey', p_idempotency_key,
               'carried', v_carried_by_table)),
           updated_at = v_now
     WHERE lead_row.id = p_lead_id;
  END IF;

  IF v_refusal_code IS NOT NULL THEN
    v_outcome := CASE
      WHEN v_refusal_code = 'lead_email_expectation_conflict' THEN 'conflict'
      ELSE 'refused' END;
    v_response := jsonb_build_object(
      'outcome', v_outcome,
      'action', 'absorb_lead',
      'leadId', p_lead_id,
      'refusalCode', v_refusal_code
    );
    IF v_refusal_code IN ('lead_has_commercial_footprint', 'unclassified_referencing_table') THEN
      v_response := v_response || jsonb_build_object('blockingTables', to_jsonb(v_named));
    END IF;
  ELSE
    v_response := jsonb_build_object(
      'outcome', COALESCE(v_outcome, 'applied'),
      'action', 'absorb_lead',
      'leadId', p_lead_id,
      'customerId', p_customer_id,
      'carried', v_carried
    );
  END IF;

  INSERT INTO public.customer_support_subscription_commands (
    idempotency_key, payload_fingerprint, operator_id, subject_id, target_id,
    command_kind, response, created_at
  ) VALUES (
    p_idempotency_key, v_fingerprint, p_operator_id, v_subject_id, p_lead_id,
    'lead_absorption', v_response, v_now
  );

  INSERT INTO public.customer_support_subscription_audit_events (
    operator_id, subject_id, target_id, command_kind, requested_action,
    idempotency_key, outcome, refusal_code, value_before, value_after, occurred_at
  ) VALUES (
    p_operator_id, v_subject_id, p_lead_id, 'lead_absorption', 'absorb_lead',
    p_idempotency_key, v_response->>'outcome', v_refusal_code,
    v_lead_email,
    CASE WHEN v_refusal_code IS NULL AND v_outcome IS NULL THEN v_tombstone ELSE NULL END,
    v_now
  );

  RETURN v_response;
END;
$_$;


--
-- Name: FUNCTION customer_support_absorb_lead_v1(p_operator_id uuid, p_customer_id uuid, p_lead_id uuid, p_expected_lead_email text, p_idempotency_key text, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_support_absorb_lead_v1(p_operator_id uuid, p_customer_id uuid, p_lead_id uuid, p_expected_lead_email text, p_idempotency_key text, p_now timestamp with time zone) IS 'Operator absorption of a marketing lead into a customer, so a customer whose address is held by a shell can have that address corrected onto them. Refuses by name and mutates nothing when the lead carries an authorization identity, has rows in a block table, or references a table client_absorption_policy does not classify; the refusal names the tables. Carries the classified marketing tables, keeps the earlier grant on a same-kind consent collision, tombstones the lead address in the reserved .invalid namespace instead of deleting the row, and leaves one receipt plus an append-only audit trail for every outcome including refusals.';


--
-- Name: customer_support_apply_subscription_action_v1(uuid, uuid, text, jsonb, integer, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_support_apply_subscription_action_v1(p_operator_id uuid, p_subscription_id uuid, p_action text, p_payload jsonb, p_expected_version integer, p_idempotency_key text, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_existing public.customer_support_subscription_commands%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_subject public.clients%ROWTYPE;
  v_payload jsonb := COALESCE(p_payload, '{}'::jsonb);
  v_delegate_payload jsonb;
  v_now timestamptz := COALESCE(p_now, now());
  v_fingerprint text;
  v_slide_min_days integer := 3;
  v_slide_target timestamptz;
  v_auth_user_id uuid;
  v_refusal_code text;
  v_outcome text;
  v_response jsonb;
  v_delegate jsonb;
  v_event_id uuid;
  v_audit_id uuid := gen_random_uuid();
  v_new_address jsonb;
  v_address_id uuid;
  v_address_before uuid;
  v_address public.addresses%ROWTYPE;
  v_parcel public.commerce_fulfillment_orders%ROWTYPE;
BEGIN
  -- Unknown or deactivated operators fail before any subscriber state is read.
  PERFORM public.communications_require_active_operator(p_operator_id);

  -- And the operator is a person. Re-derived from the administrator roster for the
  -- principal this call was handed, never taken from a claim the caller supplied. A
  -- principal with no administrator row answers NULL here and is unaffected.
  IF COALESCE((
    SELECT admin_row.is_machine_actor
      FROM public.admin_users AS admin_row
     WHERE admin_row.id = p_operator_id
  ), false) THEN
    RAISE EXCEPTION 'customer_support_command_requires_human' USING ERRCODE = '42501';
  END IF;

  IF p_subscription_id IS NULL
     OR COALESCE(p_action, '') NOT IN ('pause', 'resume', 'slide_next_cycle', 'change_shipping_address')
     OR jsonb_typeof(v_payload) <> 'object'
     OR p_expected_version IS NULL OR p_expected_version < 1
     OR char_length(btrim(COALESCE(p_idempotency_key, ''))) NOT BETWEEN 8 AND 200
  THEN
    RAISE EXCEPTION 'customer_support_subscription_command_invalid' USING ERRCODE = '22023';
  END IF;

  -- The operator floor is a payload key so the chain keeps its arity. Range is closed
  -- here: an out-of-range floor is a malformed command, not a business refusal.
  IF v_payload ? 'slideMinDays' THEN
    IF COALESCE(v_payload->>'slideMinDays', '') !~ '^[0-9]{1,2}$' THEN
      RAISE EXCEPTION 'customer_support_subscription_command_invalid' USING ERRCODE = '22023';
    END IF;
    v_slide_min_days := (v_payload->>'slideMinDays')::integer;
    IF v_slide_min_days < 1 OR v_slide_min_days > 60 THEN
      RAISE EXCEPTION 'customer_support_subscription_command_invalid' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- The destination is named exactly one way. Both keys, or neither, is a shape the
  -- console cannot compose and an operator cannot type, so it is a malformed command
  -- rather than a refusal the ledger should record as a business answer. The field
  -- bounds below are the ones `addresses` itself enforces; failing them here means the
  -- operator is told the command was malformed instead of watching an INSERT abort the
  -- whole transaction after the delegate has already written the subscriber's event.
  IF p_action = 'change_shipping_address' THEN
    IF (v_payload ? 'shippingAddressId') = (v_payload ? 'newAddress') THEN
      RAISE EXCEPTION 'customer_support_subscription_command_invalid' USING ERRCODE = '22023';
    END IF;
    IF v_payload ? 'shippingAddressId' THEN
      IF COALESCE(v_payload->>'shippingAddressId', '')
         !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      THEN
        RAISE EXCEPTION 'customer_support_subscription_command_invalid' USING ERRCODE = '22023';
      END IF;
    ELSE
      v_new_address := v_payload->'newAddress';
      IF jsonb_typeof(v_new_address) <> 'object'
         OR char_length(btrim(COALESCE(v_new_address->>'recipientName', ''))) NOT BETWEEN 1 AND 200
         OR char_length(btrim(COALESCE(v_new_address->>'line1', ''))) NOT BETWEEN 1 AND 200
         OR char_length(btrim(COALESCE(v_new_address->>'city', ''))) NOT BETWEEN 1 AND 200
         OR char_length(btrim(COALESCE(v_new_address->>'postalCode', ''))) NOT BETWEEN 1 AND 32
         OR char_length(btrim(COALESCE(v_new_address->>'country', ''))) NOT BETWEEN 2 AND 3
         OR (v_new_address ? 'line2'
             AND char_length(btrim(COALESCE(v_new_address->>'line2', ''))) NOT BETWEEN 1 AND 200)
         OR (v_new_address ? 'contactPhone'
             AND char_length(btrim(COALESCE(v_new_address->>'contactPhone', ''))) NOT BETWEEN 1 AND 64)
      THEN
        RAISE EXCEPTION 'customer_support_subscription_command_invalid' USING ERRCODE = '22023';
      END IF;
    END IF;
  END IF;

  v_fingerprint := encode(
    pg_catalog.sha256(pg_catalog.convert_to(
      'subscription_action|' || p_action || '|' || p_subscription_id::text || '|'
      || p_expected_version::text || '|' || v_payload::text, 'utf8')),
    'hex');

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('customer-support-subscription:' || p_idempotency_key, 0)
  );

  SELECT * INTO v_existing
    FROM public.customer_support_subscription_commands AS command_row
   WHERE command_row.idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.payload_fingerprint <> v_fingerprint
       OR v_existing.operator_id <> p_operator_id
       OR v_existing.target_id <> p_subscription_id
       OR v_existing.command_kind <> 'subscription_action'
    THEN
      RAISE EXCEPTION 'customer_support_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    IF v_existing.response->>'outcome' IN ('refused', 'conflict') THEN
      RETURN v_existing.response;
    END IF;
    RETURN jsonb_set(v_existing.response, '{outcome}', '"replayed"'::jsonb, true);
  END IF;

  SELECT * INTO v_subscription
    FROM public.subscriptions AS subscription_row
   WHERE subscription_row.id = p_subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    v_refusal_code := 'subscription_not_found';
  ELSE
    -- The subscriber's principal is resolved here, from the subscription's own client
    -- row. The caller neither knows it nor passes it; that is the security boundary.
    SELECT * INTO v_subject
      FROM public.clients AS subject_row
     WHERE subject_row.id = v_subscription.client_id;
    IF NOT FOUND THEN
      v_refusal_code := 'subject_not_found';
    ELSIF v_subject.auth_user_id IS NULL THEN
      -- The delegate resolves ownership through auth_user_id, so an unlinked subject has
      -- no self-service identity to act for. Refuse rather than invent one.
      v_refusal_code := 'subject_account_unlinked';
    ELSE
      v_auth_user_id := v_subject.auth_user_id;
    END IF;
  END IF;

  -- Captured before anything can move it, because it is what the ledger has to be able
  -- to read back when a customer asks who changed her address and what it was before.
  v_address_before := v_subscription.shipping_address_id;

  IF v_refusal_code IS NULL AND v_subscription.template_version <> p_expected_version THEN
    v_refusal_code := 'version_conflict';
  END IF;

  -- The one check this surface does not inherit, because the delegate does not make it.
  --
  -- The subscriber path reads the named address with `WHERE id = ... AND client_id =
  -- ...` and then tests `kind NOT IN ('shipping','both')`. When the row is not the
  -- subscriber's - or does not exist - `kind` comes back NULL, `NULL NOT IN (...)` is
  -- NULL, and the guard does not fire: the branch falls through and repoints the
  -- subscription at whatever id was named. Handing an operator's typo, or a stranger's
  -- address id, into that is not something this surface may do, so it is refused here
  -- under the delegate's own name for the same condition. This is a fence in FRONT of
  -- the delegate, not a second copy of a check that works: every check the delegate
  -- does make still runs there and is not restated here.
  IF v_refusal_code IS NULL
     AND p_action = 'change_shipping_address'
     AND v_payload ? 'shippingAddressId'
     AND NOT EXISTS (
       SELECT 1
         FROM public.addresses AS address_row
        WHERE address_row.id = (v_payload->>'shippingAddressId')::uuid
          AND address_row.client_id = v_subscription.client_id
          AND address_row.kind IN ('shipping', 'both')
     )
  THEN
    v_refusal_code := 'invalid_address';
  END IF;

  IF v_refusal_code IS NULL AND p_action = 'slide_next_cycle' THEN
    BEGIN
      v_slide_target := NULLIF(v_payload->>'newNextCycleAt', '')::timestamptz;
    EXCEPTION WHEN others THEN
      v_slide_target := NULL;
    END;

    IF v_slide_target IS NULL THEN
      v_refusal_code := 'slide_target_invalid';
    ELSIF v_subscription.status <> 'active' OR v_subscription.next_cycle_at IS NULL THEN
      v_refusal_code := 'slide_not_available';
    ELSIF v_slide_target < v_now + (v_slide_min_days || ' days')::interval
       OR v_slide_target > v_now + interval '60 days'
    THEN
      v_refusal_code := 'slide_out_of_window';
    ELSIF (v_slide_target AT TIME ZONE 'UTC')::date
        = (v_subscription.next_cycle_at AT TIME ZONE 'UTC')::date
    THEN
      -- The operator gets the subscriber's same-calendar-day no-op, not a bypass of it.
      -- It keeps precedence over the two fences below: a no-op writes nothing, so it
      -- cannot arm a cycle beside a recovery retry or beside a missing method.
      v_outcome := 'noop';
    ELSIF v_slide_target < v_now + interval '3 days' THEN
      -- Below three days the band writes `next_cycle_at` itself instead of delegating,
      -- so these two fences are applied here or they are not applied at all. Scoped to
      -- the band on purpose: on every other target the delegate is still the single
      -- authority for them and must not be second-guessed here.
      IF EXISTS (
        SELECT 1
          FROM public.subscription_dunning_cases AS dunning_case
         WHERE dunning_case.subscription_id = p_subscription_id
           AND dunning_case.status = 'open'
      ) THEN
        -- Recovery retry already owns this subscription's billing. Arming the ordinary
        -- renewal lane beside it is the double-charge shape.
        v_refusal_code := 'payment_blocked';
      ELSIF v_subscription.payment_method_ref IS NULL THEN
        -- The renewal this would arm has nothing to charge, so it can only fail and
        -- open a fresh case.
        v_refusal_code := 'payment_blocked';
      END IF;
    END IF;
  END IF;

  IF v_refusal_code IS NOT NULL THEN
    v_outcome := CASE WHEN v_refusal_code = 'version_conflict' THEN 'conflict' ELSE 'refused' END;
    v_response := jsonb_build_object(
      'outcome', v_outcome,
      'action', p_action,
      'subscriptionId', p_subscription_id,
      'refusalCode', v_refusal_code
    );
  ELSIF v_outcome = 'noop' THEN
    v_response := jsonb_build_object(
      'outcome', 'noop',
      'action', p_action,
      'subscriptionId', p_subscription_id,
      'subscriptionStatus', v_subscription.status,
      'nextCycleAt', v_subscription.next_cycle_at,
      'templateVersion', v_subscription.template_version
    );
  ELSE
    v_delegate_payload := (v_payload - 'slideMinDays')
      || jsonb_build_object('actorKind', 'operator', 'operatorId', p_operator_id);

    -- Everything below that can refuse runs inside one block with an EXCEPTION clause,
    -- which is a real subtransaction: a refusal rolls back the attempted mutation and
    -- leaves the outer transaction free to write the receipt and the audit row at the end
    -- of this function. Without it a raised refusal aborted the whole command and the
    -- ledger recorded nothing - the one case a complaint most needs to be able to read.
    BEGIN
      IF p_action = 'slide_next_cycle'
         AND v_slide_target < v_now + interval '3 days'
      THEN
        -- The one band the delegate cannot accept, because its floor is a literal inside
        -- the deepest legacy body. Same guard, same event type, same response shape.
        PERFORM public.customer_self_service_assert_no_locked_cycle(
          p_subscription_id, v_subscription.next_cycle_at
        );
        UPDATE public.subscriptions AS subscription_row
           SET next_cycle_at = v_slide_target,
               updated_at = v_now
         WHERE subscription_row.id = p_subscription_id
        RETURNING * INTO v_subscription;

        INSERT INTO public.subscription_events (
          subscription_id, event_type, idempotency_key, payload, occurred_at, actor_kind
        ) VALUES (
          p_subscription_id,
          'subscription.customer_self_service.slide_next_cycle',
          p_idempotency_key,
          jsonb_build_object(
            'action', p_action,
            'payload', v_delegate_payload || jsonb_build_object('slideMinDays', v_slide_min_days),
            'quotePreviewId', NULL,
            'reason', NULLIF(v_payload->>'reason', ''),
            'priceAgreementPolicy', jsonb_build_object(
              'kind', 'lock_until_edit', 'proration', 'none',
              'cycleEffect', 'future_unlocked_cycles_only')
          ),
          v_now,
          'operator'
        )
        RETURNING id INTO v_event_id;

        v_response := jsonb_build_object(
          'outcome', 'applied',
          'action', p_action,
          'subscriptionId', p_subscription_id,
          'subscriptionStatus', v_subscription.status,
          'nextCycleAt', v_subscription.next_cycle_at,
          'templateVersion', v_subscription.template_version,
          'eventId', v_event_id,
          'appliedBy', 'operator_reschedule_band'
        );
      ELSE
        IF p_action = 'change_shipping_address' AND v_new_address IS NOT NULL THEN
          -- A new row, never an edit of an existing one. The row the subscription
          -- points at today is also what her delivered orders point at, and possibly
          -- what another subscription points at, so editing it in place would rewrite
          -- history and move somebody else's future cycle. `is_default` stays false
          -- and no configurator key is written, which is what the default-promoting
          -- trigger on this table keys on - a correction taken over the phone must not
          -- silently unseat the address the subscriber chose for herself. It is
          -- written inside this subtransaction so a delegate refusal below rolls it
          -- back and leaves no orphan row behind a command that changed nothing.
          INSERT INTO public.addresses (
            client_id, kind, line1, line2, city, postal_code, country,
            recipient_name, contact_phone, is_default, source
          ) VALUES (
            v_subject.id,
            'shipping',
            btrim(v_new_address->>'line1'),
            NULLIF(btrim(COALESCE(v_new_address->>'line2', '')), ''),
            btrim(v_new_address->>'city'),
            btrim(v_new_address->>'postalCode'),
            upper(btrim(v_new_address->>'country')),
            btrim(v_new_address->>'recipientName'),
            NULLIF(btrim(COALESCE(v_new_address->>'contactPhone', '')), ''),
            false,
            'admin'
          )
          RETURNING id INTO v_address_id;

          -- The delegate reads `shippingAddressId`, so the address it was told to use
          -- is the id just created. The typed-out address itself does not travel on:
          -- the event ledger records which row was chosen, not a second copy of the
          -- subscriber's street address.
          v_delegate_payload := (v_delegate_payload - 'newAddress')
            || jsonb_build_object('shippingAddressId', v_address_id);
        ELSIF p_action = 'change_shipping_address' THEN
          v_address_id := (v_payload->>'shippingAddressId')::uuid;
        END IF;

        v_delegate := public.customer_self_service_apply_subscription_action(
          v_auth_user_id, p_idempotency_key, p_subscription_id, p_action,
          v_delegate_payload, v_now
        );

        -- Stamp the row the delegate just wrote so an operator action stays tellable from
        -- a subscriber action without the delegate having to know an operator exists.
        -- Addressed by the id the delegate returned, and only when the delegate actually
        -- wrote it: on `replayed` that id belongs to whoever acted first, so matching on
        -- (subscription, idempotency key) rewrote a subscriber's own historical event to
        -- `operator` whenever an operator reused a key the subscriber had already used.
        IF COALESCE(v_delegate #>> '{subscriptionAction,status}', 'applied') <> 'replayed' THEN
          UPDATE public.subscription_events AS event_row
             SET actor_kind = 'operator'
           WHERE event_row.id
                 = NULLIF(v_delegate #>> '{subscriptionAction,eventId}', '')::uuid;
        END IF;

        -- The parcel the subscriber is waiting for, when it can still be moved.
        --
        -- The pointer the delegate just changed reaches the NEXT cycle. If the current
        -- cycle's parcel has not been handed to a carrier yet, the operator promised
        -- something about a parcel this command has not touched, so it is repointed
        -- here. Only on `applied`: a `replayed` answer means the write already happened
        -- under a key somebody else spent, and repeating a repair against it would move
        -- rows this command did not author.
        --
        -- BOTH ROWS. The dispatch authority resolves the destination from the fulfilment
        -- row, so repointing the order alone satisfies every read a human performs and
        -- routes nothing. The snapshot is CONCATENATED, not rebuilt: it also carries the
        -- chosen delivery selection for a subscriber who collects from a pickup point,
        -- and rebuilding the object would drop that key and send the parcel to the last
        -- place a lower-precedence source happened to name.
        --
        -- The status is read under `FOR UPDATE` in this transaction, so the dispatch job
        -- cannot move it between the check and the write. Ineligible is a skip, not a
        -- refusal: the subscription really did change, and the honest answer to "did it
        -- work" is yes for every cycle after this one.
        IF p_action = 'change_shipping_address'
           AND COALESCE(v_delegate #>> '{subscriptionAction,status}', 'applied') = 'applied'
        THEN
          SELECT * INTO v_address
            FROM public.addresses AS address_row
           WHERE address_row.id = v_address_id;

          SELECT parcel_row.* INTO v_parcel
            FROM public.commerce_fulfillment_orders AS parcel_row
            JOIN public.commerce_orders AS order_row ON order_row.id = parcel_row.order_id
           WHERE order_row.subscription_id = p_subscription_id
             AND order_row.mode = 'subscription_cycle'
             AND order_row.client_id = v_subject.id
           ORDER BY order_row.created_at DESC, parcel_row.sequence_no DESC, parcel_row.id DESC
           LIMIT 1
           FOR UPDATE OF parcel_row;

          IF FOUND AND v_parcel.status IN ('created', 'packed', 'label_pending') THEN
            UPDATE public.commerce_orders AS order_row
               SET shipping_address_id = v_address_id,
                   updated_at = v_now
             WHERE order_row.id = v_parcel.order_id;

            UPDATE public.commerce_fulfillment_orders AS parcel_row
               SET shipping_address_id = v_address_id,
                   shipping_address_snapshot =
                     COALESCE(parcel_row.shipping_address_snapshot, '{}'::jsonb)
                     || jsonb_build_object(
                          'addressId', v_address.id,
                          'clientId', v_address.client_id,
                          'label', v_address.label,
                          'line1', v_address.line1,
                          'line2', v_address.line2,
                          'city', v_address.city,
                          'postalCode', v_address.postal_code,
                          'country', v_address.country,
                          'recipientName', v_address.recipient_name,
                          'contactPhone', v_address.contact_phone,
                          'companyName', v_address.company_name,
                          'taxId', v_address.tax_id,
                          'deliveryNotes', v_address.delivery_notes,
                          'courierInstructions', v_address.courier_instructions),
                   updated_at = v_now
             WHERE parcel_row.id = v_parcel.id;
          END IF;
        END IF;

        SELECT * INTO v_subscription
          FROM public.subscriptions AS subscription_row
         WHERE subscription_row.id = p_subscription_id;

        v_response := jsonb_build_object(
          'outcome', COALESCE(v_delegate #>> '{subscriptionAction,status}', 'applied'),
          'action', p_action,
          'subscriptionId', p_subscription_id,
          'subscriptionStatus', v_subscription.status,
          'nextCycleAt', v_subscription.next_cycle_at,
          'templateVersion', v_subscription.template_version,
          'eventId', NULLIF(v_delegate #>> '{subscriptionAction,eventId}', '')::uuid,
          'appliedBy', 'customer_self_service_delegate'
        );
      END IF;
    EXCEPTION WHEN raise_exception THEN
      -- Narrow on purpose. `raise_exception` is SQLSTATE P0001, what a bare
      -- `RAISE EXCEPTION '<literal>'` produces, so a unique violation, a serialization
      -- failure or a deadlock never reaches here. Of those, only the self-service refusal
      -- vocabulary is converted; every other P0001 is re-raised unchanged, because
      -- reporting an internal fault as a business refusal would tell the operator to
      -- retry a write that is broken.
      IF NOT starts_with(SQLERRM, 'customer_self_service_') THEN
        RAISE;
      END IF;
      v_refusal_code := substr(SQLERRM, char_length('customer_self_service_') + 1);
      v_outcome := 'refused';
      v_response := jsonb_build_object(
        'outcome', 'refused',
        'action', p_action,
        'subscriptionId', p_subscription_id,
        'refusalCode', v_refusal_code
      );
    END;
  END IF;

  -- Every command that reaches here leaves exactly one receipt and exactly one audit row,
  -- so a restart cannot reinterpret one and a complaint can be read. That now includes
  -- refusals, conflicts and the self-service refusals the block above converts. It does
  -- not include the malformed-command and idempotency-conflict raises before the advisory
  -- lock section, nor any `P0001` outside the `customer_self_service_` vocabulary: those
  -- still abort the command and record nothing.
  INSERT INTO public.customer_support_subscription_commands (
    idempotency_key, payload_fingerprint, operator_id, subject_id, target_id,
    command_kind, response, created_at
  ) VALUES (
    p_idempotency_key, v_fingerprint, p_operator_id,
    COALESCE(v_subject.id, v_subscription.client_id), p_subscription_id,
    'subscription_action', v_response, v_now
  );

  INSERT INTO public.customer_support_subscription_audit_events (
    id, operator_id, subject_id, target_id, command_kind, requested_action,
    idempotency_key, outcome, refusal_code, value_before, value_after, occurred_at
  ) VALUES (
    v_audit_id, p_operator_id,
    COALESCE(v_subject.id, v_subscription.client_id), p_subscription_id,
    'subscription_action', p_action, p_idempotency_key,
    v_response->>'outcome', v_refusal_code,
    -- The ledger records the value this command was about. For a reschedule that is
    -- the cycle date, as it always was; for an address change the two columns would
    -- otherwise hold a date nobody asked to move, and the one question the ledger
    -- exists to answer - what was the address before, and what is it now - would have
    -- no answer at all. `value_after` stays NULL on a refusal, because nothing moved.
    CASE WHEN p_action = 'change_shipping_address'
      THEN v_address_before::text
      ELSE NULLIF(v_payload->>'newNextCycleAt', '') END,
    CASE WHEN p_action = 'change_shipping_address'
      THEN CASE WHEN v_refusal_code IS NULL THEN v_address_id::text ELSE NULL END
      ELSE v_response->>'nextCycleAt' END,
    v_now
  );

  RETURN v_response;
END;
$_$;


--
-- Name: FUNCTION customer_support_apply_subscription_action_v1(p_operator_id uuid, p_subscription_id uuid, p_action text, p_payload jsonb, p_expected_version integer, p_idempotency_key text, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_support_apply_subscription_action_v1(p_operator_id uuid, p_subscription_id uuid, p_action text, p_payload jsonb, p_expected_version integer, p_idempotency_key text, p_now timestamp with time zone) IS 'Operator pause/resume/reschedule/change-of-address on a subscriber subscription. Checks the operator allowlist and then refuses a machine actor, resolves the subscriber principal from the subscription client row, compares template_version, and delegates to customer_self_service_apply_subscription_action except in the narrow sub-three-day reschedule band. An address change may name a saved address or carry a new one, which is INSERTed as a new non-default addresses row with source=admin and never an in-place edit; when the current cycle parcel is still created/packed/label_pending both the order and the fulfilment row are repointed and the fulfilment snapshot is merged rather than rebuilt, so a stored delivery selection survives. Idempotent by key with a locally computed fingerprint, and every outcome that reaches the ledger stage leaves one receipt and one audit row carrying the address before and after.';


--
-- Name: customer_support_correct_subject_email_v1(uuid, uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_support_correct_subject_email_v1(p_operator_id uuid, p_subject_id uuid, p_expected_email text, p_new_email text, p_idempotency_key text, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_existing public.customer_support_subscription_commands%ROWTYPE;
  v_subject public.clients%ROWTYPE;
  v_now timestamptz := COALESCE(p_now, now());
  v_new_email text := lower(btrim(COALESCE(p_new_email, '')));
  v_fingerprint text;
  v_refusal_code text;
  v_outcome text;
  v_response jsonb;
  v_before text;
  v_linked boolean := false;
  v_audit_id uuid := gen_random_uuid();
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);

  -- And the operator is a person. Re-derived from the administrator roster for the
  -- principal this call was handed, never taken from a claim the caller supplied. A
  -- principal with no administrator row answers NULL here and is unaffected.
  IF COALESCE((
    SELECT admin_row.is_machine_actor
      FROM public.admin_users AS admin_row
     WHERE admin_row.id = p_operator_id
  ), false) THEN
    RAISE EXCEPTION 'customer_support_command_requires_human' USING ERRCODE = '42501';
  END IF;

  IF p_subject_id IS NULL
     OR char_length(btrim(COALESCE(p_idempotency_key, ''))) NOT BETWEEN 8 AND 200
     OR char_length(v_new_email) NOT BETWEEN 3 AND 320
     OR v_new_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
  THEN
    RAISE EXCEPTION 'customer_support_email_correction_invalid' USING ERRCODE = '22023';
  END IF;

  v_fingerprint := encode(
    pg_catalog.sha256(pg_catalog.convert_to(
      'email_correction|' || p_subject_id::text || '|' || lower(btrim(COALESCE(p_expected_email, '')))
      || '|' || v_new_email, 'utf8')),
    'hex');

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('customer-support-subscription:' || p_idempotency_key, 0)
  );

  SELECT * INTO v_existing
    FROM public.customer_support_subscription_commands AS command_row
   WHERE command_row.idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.payload_fingerprint <> v_fingerprint
       OR v_existing.operator_id <> p_operator_id
       OR v_existing.target_id <> p_subject_id
       OR v_existing.command_kind <> 'email_correction'
    THEN
      RAISE EXCEPTION 'customer_support_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    IF v_existing.response->>'outcome' IN ('refused', 'conflict') THEN
      RETURN v_existing.response;
    END IF;
    RETURN jsonb_set(v_existing.response, '{outcome}', '"replayed"'::jsonb, true);
  END IF;

  SELECT * INTO v_subject
    FROM public.clients AS subject_row
   WHERE subject_row.id = p_subject_id
   FOR UPDATE;
  IF NOT FOUND THEN
    v_refusal_code := 'subject_not_found';
  ELSIF lower(btrim(COALESCE(v_subject.email, ''))) IS DISTINCT FROM lower(btrim(COALESCE(p_expected_email, ''))) THEN
    -- The operator acted on a snapshot; a changed address means someone else moved
    -- first and the correction must be re-read rather than replayed blind.
    v_refusal_code := 'email_expectation_conflict';
  END IF;

  v_before := v_subject.email;
  v_linked := v_subject.auth_user_id IS NOT NULL;

  IF v_refusal_code IS NULL AND lower(btrim(COALESCE(v_subject.email, ''))) = v_new_email THEN
    v_outcome := 'noop';
  END IF;

  IF v_refusal_code IS NULL AND v_outcome IS NULL THEN
    BEGIN
      UPDATE public.clients AS subject_row
         SET email = v_new_email,
             updated_at = v_now
       WHERE subject_row.id = p_subject_id;
    EXCEPTION WHEN unique_violation THEN
      -- lower(email) is unique. A readable refusal, not a raised 23505 the BFF would
      -- have to guess at.
      v_refusal_code := 'email_already_in_use';
    END;
  END IF;

  IF v_refusal_code IS NOT NULL THEN
    v_outcome := CASE
      WHEN v_refusal_code IN ('email_expectation_conflict', 'email_already_in_use') THEN 'conflict'
      ELSE 'refused' END;
    v_response := jsonb_build_object(
      'outcome', v_outcome,
      'action', 'correct_email',
      'subjectId', p_subject_id,
      'refusalCode', v_refusal_code
    );
  ELSE
    v_response := jsonb_build_object(
      'outcome', COALESCE(v_outcome, 'applied'),
      'action', 'correct_email',
      'subjectId', p_subject_id,
      'authUserLinked', v_linked
    );
  END IF;

  INSERT INTO public.customer_support_subscription_commands (
    idempotency_key, payload_fingerprint, operator_id, subject_id, target_id,
    command_kind, response, created_at
  ) VALUES (
    p_idempotency_key, v_fingerprint, p_operator_id, p_subject_id, p_subject_id,
    'email_correction', v_response, v_now
  );

  INSERT INTO public.customer_support_subscription_audit_events (
    id, operator_id, subject_id, target_id, command_kind, requested_action,
    idempotency_key, outcome, refusal_code, value_before, value_after, occurred_at
  ) VALUES (
    v_audit_id, p_operator_id, p_subject_id, p_subject_id,
    'email_correction', 'correct_email', p_idempotency_key,
    v_response->>'outcome', v_refusal_code,
    v_before,
    CASE WHEN v_refusal_code IS NULL THEN v_new_email ELSE NULL END,
    v_now
  );

  RETURN v_response;
END;
$_$;


--
-- Name: FUNCTION customer_support_correct_subject_email_v1(p_operator_id uuid, p_subject_id uuid, p_expected_email text, p_new_email text, p_idempotency_key text, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_support_correct_subject_email_v1(p_operator_id uuid, p_subject_id uuid, p_expected_email text, p_new_email text, p_idempotency_key text, p_now timestamp with time zone) IS 'Emergency operator correction of clients.email. A linked account is no longer refused: the caller moves the authorization copy of the address first, because that invariant spans the auth service and this function can see only the Postgres half. Refuses a stale expectation and a lower(email) collision by name; audits the value before and after, refusals included, and reports whether an authorization copy was linked.';


--
-- Name: customer_support_correct_subject_phone_v1(uuid, uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_support_correct_subject_phone_v1(p_operator_id uuid, p_subject_id uuid, p_expected_phone text, p_new_phone text, p_idempotency_key text, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_existing public.customer_support_subscription_commands%ROWTYPE;
  v_subject public.clients%ROWTYPE;
  v_now timestamptz := COALESCE(p_now, now());
  v_new_phone text := btrim(COALESCE(p_new_phone, ''));
  v_fingerprint text;
  v_refusal_code text;
  v_outcome text;
  v_response jsonb;
  v_before text;
  v_audit_id uuid := gen_random_uuid();
BEGIN
  PERFORM public.communications_require_active_operator(p_operator_id);

  -- And the operator is a person. Re-derived from the administrator roster for the
  -- principal this call was handed, never taken from a claim the caller supplied. A
  -- principal with no administrator row answers NULL here and is unaffected.
  IF COALESCE((
    SELECT admin_row.is_machine_actor
      FROM public.admin_users AS admin_row
     WHERE admin_row.id = p_operator_id
  ), false) THEN
    RAISE EXCEPTION 'customer_support_command_requires_human' USING ERRCODE = '42501';
  END IF;

  -- E.164 is the shape the fulfillment payload carries, so an operator correction
  -- that stored anything else would reintroduce the defect it exists to fix. The
  -- caller normalizes; this refuses whatever arrived unnormalized.
  IF p_subject_id IS NULL
     OR char_length(btrim(COALESCE(p_idempotency_key, ''))) NOT BETWEEN 8 AND 200
     OR v_new_phone !~ '^\+[1-9][0-9]{7,14}$'
  THEN
    RAISE EXCEPTION 'customer_support_phone_correction_invalid' USING ERRCODE = '22023';
  END IF;

  v_fingerprint := encode(
    pg_catalog.sha256(pg_catalog.convert_to(
      'phone_correction|' || p_subject_id::text || '|' || btrim(COALESCE(p_expected_phone, ''))
      || '|' || v_new_phone, 'utf8')),
    'hex');

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('customer-support-subscription:' || p_idempotency_key, 0)
  );

  SELECT * INTO v_existing
    FROM public.customer_support_subscription_commands AS command_row
   WHERE command_row.idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.payload_fingerprint <> v_fingerprint
       OR v_existing.operator_id <> p_operator_id
       OR v_existing.target_id <> p_subject_id
       OR v_existing.command_kind <> 'phone_correction'
    THEN
      RAISE EXCEPTION 'customer_support_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    IF v_existing.response->>'outcome' IN ('refused', 'conflict') THEN
      RETURN v_existing.response;
    END IF;
    RETURN jsonb_set(v_existing.response, '{outcome}', '"replayed"'::jsonb, true);
  END IF;

  SELECT * INTO v_subject
    FROM public.clients AS subject_row
   WHERE subject_row.id = p_subject_id
   FOR UPDATE;
  IF NOT FOUND THEN
    v_refusal_code := 'subject_not_found';
  ELSIF btrim(COALESCE(v_subject.phone, '')) IS DISTINCT FROM btrim(COALESCE(p_expected_phone, '')) THEN
    v_refusal_code := 'phone_expectation_conflict';
  END IF;

  v_before := v_subject.phone;

  IF v_refusal_code IS NULL AND btrim(COALESCE(v_subject.phone, '')) = v_new_phone THEN
    v_outcome := 'noop';
  END IF;

  IF v_refusal_code IS NULL AND v_outcome IS NULL THEN
    -- No uniqueness on `phone`: two members of one household legitimately share a
    -- number, so unlike the e-mail path there is no collision to refuse.
    UPDATE public.clients AS subject_row
       SET phone = v_new_phone,
           updated_at = v_now
     WHERE subject_row.id = p_subject_id;
  END IF;

  IF v_refusal_code IS NOT NULL THEN
    v_outcome := CASE
      WHEN v_refusal_code = 'phone_expectation_conflict' THEN 'conflict'
      ELSE 'refused' END;
    v_response := jsonb_build_object(
      'outcome', v_outcome,
      'action', 'correct_phone',
      'subjectId', p_subject_id,
      'refusalCode', v_refusal_code
    );
  ELSE
    v_response := jsonb_build_object(
      'outcome', COALESCE(v_outcome, 'applied'),
      'action', 'correct_phone',
      'subjectId', p_subject_id
    );
  END IF;

  INSERT INTO public.customer_support_subscription_commands (
    idempotency_key, payload_fingerprint, operator_id, subject_id, target_id,
    command_kind, response, created_at
  ) VALUES (
    p_idempotency_key, v_fingerprint, p_operator_id, p_subject_id, p_subject_id,
    'phone_correction', v_response, v_now
  );

  INSERT INTO public.customer_support_subscription_audit_events (
    id, operator_id, subject_id, target_id, command_kind, requested_action,
    idempotency_key, outcome, refusal_code, value_before, value_after, occurred_at
  ) VALUES (
    v_audit_id, p_operator_id, p_subject_id, p_subject_id,
    'phone_correction', 'correct_phone', p_idempotency_key,
    v_response->>'outcome', v_refusal_code,
    v_before,
    CASE WHEN v_refusal_code IS NULL THEN v_new_phone ELSE NULL END,
    v_now
  );

  RETURN v_response;
END;
$_$;


--
-- Name: FUNCTION customer_support_correct_subject_phone_v1(p_operator_id uuid, p_subject_id uuid, p_expected_phone text, p_new_phone text, p_idempotency_key text, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.customer_support_correct_subject_phone_v1(p_operator_id uuid, p_subject_id uuid, p_expected_phone text, p_new_phone text, p_idempotency_key text, p_now timestamp with time zone) IS 'Operator correction of clients.phone, the number the fulfillment dispatch payload carries. Requires E.164; refuses a stale expectation; audits the value before and after, refusals included. There is no uniqueness refusal because a shared household number is legitimate.';


--
-- Name: customer_support_issue_recovery(uuid, uuid, uuid, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_support_issue_recovery(p_operator_id uuid, p_subject_id uuid, p_case_id uuid, p_idempotency_key text, p_payload_fingerprint text, p_token_hash text, p_expires_at timestamp with time zone, p_recovery_path text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_existing public.customer_support_recovery_commands%ROWTYPE;
  v_subject public.clients%ROWTYPE;
  v_case public.subscription_dunning_cases%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_source_notice public.subscription_dunning_notifications%ROWTYPE;
  v_audit_id uuid := gen_random_uuid();
  v_recorded_at timestamptz := clock_timestamp();
  v_refusal_code text;
  v_response jsonb;
  v_notice_attempt integer;
BEGIN
  -- Unknown/inactive operators fail before any customer or recovery state is read.
  PERFORM public.communications_require_active_operator(p_operator_id);

  IF p_subject_id IS NULL OR p_case_id IS NULL
     OR char_length(btrim(COALESCE(p_idempotency_key, ''))) NOT BETWEEN 8 AND 200
     OR COALESCE(p_payload_fingerprint, '') !~ '^[0-9a-f]{64}$'
     OR COALESCE(p_token_hash, '') !~ '^[0-9a-f]{64}$'
     OR p_expires_at IS NULL OR p_expires_at <= now()
     OR p_recovery_path IS NULL OR char_length(p_recovery_path) > 1000
     OR p_recovery_path !~ '^/[^[:cntrl:]]+$'
  THEN
    RAISE EXCEPTION 'customer_support_recovery_command_invalid' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('managed-customer-recovery:' || p_idempotency_key, 0)
  );

  SELECT * INTO v_existing
    FROM public.customer_support_recovery_commands AS command_row
   WHERE command_row.idempotency_key = p_idempotency_key;

  IF FOUND THEN
    IF v_existing.payload_fingerprint <> p_payload_fingerprint
       OR v_existing.operator_id <> p_operator_id
       OR v_existing.subject_id <> p_subject_id
       OR v_existing.case_id <> p_case_id
    THEN
      RAISE EXCEPTION 'customer_support_idempotency_conflict' USING ERRCODE = '23505';
    END IF;

    IF v_existing.response->>'outcome' = 'refused' THEN
      RETURN v_existing.response;
    END IF;

    RETURN jsonb_set(v_existing.response, '{outcome}', '"replayed"'::jsonb, true);
  END IF;

  SELECT * INTO v_subject
    FROM public.clients AS subject_row
   WHERE subject_row.id = p_subject_id;
  IF NOT FOUND THEN
    v_refusal_code := 'subject_not_found';
  ELSIF v_subject.lifecycle_stage <> 'customer' THEN
    v_refusal_code := 'lifecycle_not_eligible';
  END IF;

  IF v_refusal_code IS NULL THEN
    SELECT * INTO v_case
      FROM public.subscription_dunning_cases AS case_row
     WHERE case_row.id = p_case_id
     FOR UPDATE;
    IF NOT FOUND OR v_case.client_id <> p_subject_id THEN
      v_refusal_code := 'case_not_found';
    ELSIF v_case.status <> 'open' THEN
      v_refusal_code := 'case_not_open';
    END IF;
  END IF;

  IF v_refusal_code IS NULL THEN
    SELECT * INTO v_order
      FROM public.commerce_orders AS order_row
     WHERE order_row.id = v_case.order_id
       AND order_row.client_id = p_subject_id
       AND order_row.status = 'pending_payment'
     FOR UPDATE;
    IF NOT FOUND THEN
      v_refusal_code := 'recoverable_order_unavailable';
    END IF;
  END IF;

  IF v_refusal_code IS NULL THEN
    SELECT * INTO v_source_notice
      FROM public.subscription_dunning_notifications AS notice_row
     WHERE notice_row.case_id = p_case_id
       AND notice_row.recipient_kind = 'customer'
       AND notice_row.notification_kind = 'payment_failed'
     ORDER BY notice_row.created_at DESC, notice_row.id DESC
     LIMIT 1;
    IF NOT FOUND THEN
      v_refusal_code := 'dunning_authority_unavailable';
    END IF;
  END IF;

  IF v_refusal_code IS NOT NULL THEN
    v_response := jsonb_build_object(
      'outcome', 'refused',
      'refusal_code', v_refusal_code
    );
    INSERT INTO public.customer_support_recovery_commands (
      idempotency_key, payload_fingerprint, operator_id, subject_id, case_id,
      response, created_at
    ) VALUES (
      p_idempotency_key, p_payload_fingerprint, p_operator_id, p_subject_id, p_case_id,
      v_response, v_recorded_at
    );
    INSERT INTO public.customer_support_recovery_audit_events (
      id, operator_id, subject_id, case_id, idempotency_key, outcome,
      refusal_code, occurred_at
    ) VALUES (
      v_audit_id, p_operator_id, p_subject_id, p_case_id, p_idempotency_key,
      'refused', v_refusal_code, v_recorded_at
    );
    RETURN v_response;
  END IF;

  PERFORM public.subscription_rotate_payment_recovery_token(
    p_case_id, p_token_hash, p_expires_at, 'customer_support_recovery'
  );

  SELECT COALESCE(max(notice_row.retry_attempt), 0) + 1 INTO v_notice_attempt
    FROM public.subscription_dunning_notifications AS notice_row
   WHERE notice_row.case_id = p_case_id
     AND notice_row.recipient_kind = 'customer';

  INSERT INTO public.subscription_dunning_notifications (
    case_id, subscription_id, cycle_id, order_id, payment_intent_id,
    recipient_kind, recipient_ref, notification_kind, template_slug,
    retry_attempt, idempotency_key, status, scheduled_at, recovery_url_path,
    payload, created_at, updated_at
  ) VALUES (
    v_case.id, v_case.subscription_id, v_case.cycle_id, v_case.order_id,
    v_case.payment_intent_id, 'customer', v_case.client_id, 'payment_recovery',
    v_source_notice.template_slug, v_notice_attempt,
    'customer-support-recovery:' || p_idempotency_key, 'queued', v_recorded_at,
    p_recovery_path,
    v_source_notice.payload || jsonb_build_object('source', 'customer_support_recovery'),
    v_recorded_at, v_recorded_at
  );

  INSERT INTO public.customer_support_recovery_audit_events (
    id, operator_id, subject_id, case_id, idempotency_key, outcome, occurred_at
  ) VALUES (
    v_audit_id, p_operator_id, p_subject_id, p_case_id, p_idempotency_key,
    'issued', v_recorded_at
  );

  v_response := jsonb_build_object(
    'outcome', 'issued',
    'delivery_status', 'queued',
    'audit_event_id', v_audit_id
  );
  INSERT INTO public.customer_support_recovery_commands (
    idempotency_key, payload_fingerprint, operator_id, subject_id, case_id,
    response, created_at
  ) VALUES (
    p_idempotency_key, p_payload_fingerprint, p_operator_id, p_subject_id, p_case_id,
    v_response, v_recorded_at
  );

  RETURN v_response;
END;
$_$;


--
-- Name: customer_support_refuse_recovery_ledger_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_support_refuse_recovery_ledger_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  RAISE EXCEPTION 'customer_support_recovery_ledger_append_only' USING ERRCODE = '55000';
END;
$$;


--
-- Name: enqueue_abandoned_cart_reminders(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_abandoned_cart_reminders(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_limit constant integer := GREATEST(1, LEAST(COALESCE(p_limit, 200), 1000));
  v_enqueued_1h integer := 0;
  v_enqueued_24h integer := 0;
  v_enqueued_72h integer := 0;
BEGIN
  -- Unspoofable clone guard: only the production Postgres identity passes. Any
  -- clone / preview / branch DB returns false here, so reminders can NEVER be
  -- enqueued off-prod even if the env kill-switch is mistakenly enabled.
  IF NOT private.external_cron_is_enabled() THEN
    RETURN jsonb_build_object(
      'enqueued_1h', 0,
      'enqueued_24h', 0,
      'enqueued_72h', 0,
      'skipped', 'clone_guard'
    );
  END IF;

  -- 1h reminder: draft 1h-24h old, no payment row, not yet enqueued. Bounded to
  -- <24h so it stays the genuine first nudge (older drafts go straight to 24h/72h).
  WITH candidates AS (
    SELECT o.id, o.created_at
    FROM public.commerce_orders o
    WHERE o.status = 'draft'
      AND o.created_at < now() - interval '1 hour'
      AND o.created_at >= now() - interval '24 hours'
      AND NOT EXISTS (
        SELECT 1 FROM public.commerce_payments p WHERE p.order_id = o.id
      )
    ORDER BY o.created_at ASC
    LIMIT v_limit
  ),
  inserted AS (
    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    SELECT
      'commerce_order',
      c.id,
      'commerce.order_draft.abandoned.1h',
      'abandoned_1h:' || c.id::text,
      jsonb_build_object(
        'orderId', 'order_' || c.id::text,
        'orderUuid', c.id::text,
        'reminderHours', 1,
        'createdAt', to_char(c.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
      ),
      jsonb_build_object('source', 'abandoned_cart_cron')
    FROM candidates c
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_enqueued_1h FROM inserted;

  -- 24h reminder: draft 24h-72h old, no payment row, not yet enqueued. The UPPER
  -- bound (>= now()-72h) keeps the tier disjoint from 72h so the two can never fire
  -- in the same run; a draft past 72h is handled by the 72h tier via its existing
  -- abandoned_24h event from an earlier run.
  WITH candidates AS (
    SELECT o.id, o.created_at
    FROM public.commerce_orders o
    WHERE o.status = 'draft'
      AND o.created_at < now() - interval '24 hours'
      AND o.created_at >= now() - interval '72 hours'
      AND NOT EXISTS (
        SELECT 1 FROM public.commerce_payments p WHERE p.order_id = o.id
      )
    ORDER BY o.created_at ASC
    LIMIT v_limit
  ),
  inserted AS (
    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    SELECT
      'commerce_order',
      c.id,
      'commerce.order_draft.abandoned.24h',
      'abandoned_24h:' || c.id::text,
      jsonb_build_object(
        'orderId', 'order_' || c.id::text,
        'orderUuid', c.id::text,
        'reminderHours', 24,
        'createdAt', to_char(c.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
      ),
      jsonb_build_object('source', 'abandoned_cart_cron')
    FROM candidates c
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_enqueued_24h FROM inserted;

  -- 72h reminder: draft older than 72h, no payment row, AND the 24h reminder
  -- event already exists (the first nudge must precede the last nudge). Because the
  -- 24h tier is now bounded to <72h, that event was necessarily enqueued in an
  -- earlier run — never the same run as this 72h insert.
  WITH candidates AS (
    SELECT o.id, o.created_at
    FROM public.commerce_orders o
    WHERE o.status = 'draft'
      AND o.created_at < now() - interval '72 hours'
      AND NOT EXISTS (
        SELECT 1 FROM public.commerce_payments p WHERE p.order_id = o.id
      )
      AND EXISTS (
        SELECT 1 FROM public.outbox_events e
        WHERE e.event_type = 'commerce.order_draft.abandoned.24h'
          AND e.idempotency_key = 'abandoned_24h:' || o.id::text
      )
    ORDER BY o.created_at ASC
    LIMIT v_limit
  ),
  inserted AS (
    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    SELECT
      'commerce_order',
      c.id,
      'commerce.order_draft.abandoned.72h',
      'abandoned_72h:' || c.id::text,
      jsonb_build_object(
        'orderId', 'order_' || c.id::text,
        'orderUuid', c.id::text,
        'reminderHours', 72,
        'createdAt', to_char(c.created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
      ),
      jsonb_build_object('source', 'abandoned_cart_cron')
    FROM candidates c
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_enqueued_72h FROM inserted;

  RETURN jsonb_build_object(
    'enqueued_1h', v_enqueued_1h,
    'enqueued_24h', v_enqueued_24h,
    'enqueued_72h', v_enqueued_72h
  );
END;
$$;


--
-- Name: enqueue_abandoned_cart_reminders_from_vercel(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_abandoned_cart_reminders_from_vercel(p_limit integer, p_runtime_supabase_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- This transaction-local setting cannot be supplied by a copied pg_cron
  -- command. The wrapper is the only supported entrypoint for the Vercel route.
  PERFORM set_config(
    'app.openlup_abandoned_cart_runtime_url',
    rtrim(coalesce(nullif(btrim(p_runtime_supabase_url), ''), ''), '/'),
    true
  );
  RETURN public.enqueue_abandoned_cart_reminders(p_limit);
END;
$$;


--
-- Name: enqueue_back_in_stock(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_back_in_stock(p_sku text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_sku text := btrim(coalesce(p_sku, ''));
  v_sku_id uuid;
  v_available integer;
  v_count integer := 0;
  v_rec record;
  v_event_id uuid;
  v_idempotency_key text;
BEGIN
  IF v_sku = '' THEN
    RAISE EXCEPTION 'stock_notification_invalid_sku' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_sku_id FROM public.catalog_skus WHERE sku = v_sku;
  IF v_sku_id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT coalesce(SUM(greatest(0, b.on_hand - b.reserved - b.unavailable - b.safety_stock)), 0)
    INTO v_available
    FROM public.inventory_balances b
   WHERE b.sku_id = v_sku_id;

  IF coalesce(v_available, 0) <= 0 THEN
    RETURN 0;
  END IF;

  FOR v_rec IN
    SELECT id, email
      FROM public.commerce_product_stock_notifications
     WHERE sku = v_sku
       AND closed_at IS NULL
       AND enqueued_at IS NULL
     FOR UPDATE SKIP LOCKED
  LOOP
    v_event_id := NULL;
    v_idempotency_key := 'back_in_stock:' || v_rec.id::text;

    INSERT INTO public.outbox_events (
      aggregate_type,
      aggregate_id,
      event_type,
      idempotency_key,
      payload,
      metadata
    )
    VALUES (
      'commerce_product',
      v_sku_id,
      'commerce.product.back_in_stock',
      v_idempotency_key,
      jsonb_build_object('sku', v_sku, 'email', v_rec.email),
      jsonb_build_object('boundary', 'enqueue_back_in_stock', 'subscriptionId', v_rec.id)
    )
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING id INTO v_event_id;

    IF v_event_id IS NULL THEN
      SELECT id INTO v_event_id
        FROM public.outbox_events
       WHERE event_type = 'commerce.product.back_in_stock'
         AND idempotency_key = v_idempotency_key;
    END IF;

    UPDATE public.commerce_product_stock_notifications
       SET enqueued_at = coalesce(enqueued_at, now()),
           outbox_event_id = coalesce(outbox_event_id, v_event_id),
           metadata = metadata || jsonb_build_object('enqueuedBy', 'enqueue_back_in_stock')
     WHERE id = v_rec.id
       AND closed_at IS NULL
       AND enqueued_at IS NULL;

    IF FOUND THEN
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: enqueue_checkout_recovery_reminders(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_checkout_recovery_reminders(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_limit constant integer := GREATEST(1, LEAST(COALESCE(p_limit, 200), 1000));
  v_enqueued_1h integer := 0;
  v_enqueued_20h integer := 0;
BEGIN
  -- 1h reminder.
  WITH candidates AS (
    SELECT o.id, o.mode, o.created_at, 'rcv_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '') AS raw_token
    FROM public.commerce_orders o
    WHERE o.status = 'pending_payment'
      AND o.created_at < now() - interval '1 hour'
      AND o.created_at > now() - interval '24 hours'
      AND (
        o.mode = 'one_time'
        OR EXISTS (
          SELECT 1 FROM public.subscriptions s
          WHERE s.id = o.subscription_id AND s.status = 'pending_activation'
        )
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.commerce_payments p
        WHERE p.order_id = o.id AND p.status = 'succeeded'
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.commerce_payments p
        WHERE p.order_id = o.id
          AND p.status IN ('pending', 'requires_action')
          AND p.updated_at > now() - interval '15 minutes'
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.commerce_payment_intents pi
        WHERE pi.order_id = o.id
          AND pi.status IN ('created', 'requires_action', 'processing')
          AND pi.updated_at > now() - interval '15 minutes'
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.commerce_payment_attempts pa
        JOIN public.commerce_payment_intents pi ON pi.id = pa.payment_intent_id
        WHERE pi.order_id = o.id
          AND pa.status IN ('created', 'sent_to_provider', 'requires_action', 'processing')
          AND pa.updated_at > now() - interval '15 minutes'
      )
    ORDER BY o.created_at ASC
    LIMIT v_limit
  ),
  enq AS (
    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    SELECT
      'commerce_order', c.id, 'commerce.checkout_recovery',
      'checkout_recovery:1h:' || c.id::text,
      jsonb_build_object(
        'orderId', c.id::text,
        'mode', c.mode,
        'reminderHours', 1,
        'recoveryToken', c.raw_token,
        'expiresAt', to_char((c.created_at + interval '24 hours') AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
      ),
      jsonb_build_object('source', 'checkout_recovery_cron')
    FROM candidates c
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING aggregate_id, (payload->>'recoveryToken') AS raw_token
  ),
  tok AS (
    INSERT INTO public.commerce_checkout_recovery_tokens (order_id, client_id, token_hash, expires_at)
    SELECT e.aggregate_id, o.client_id,
           encode(sha256(convert_to(e.raw_token, 'UTF8')), 'hex'),
           o.created_at + interval '24 hours'
    FROM enq e JOIN public.commerce_orders o ON o.id = e.aggregate_id
    RETURNING 1
  )
  SELECT count(*) INTO v_enqueued_1h FROM tok;

  -- 20h reminder (final nudge); the 1h reminder must have actually sent.
  WITH candidates AS (
    SELECT o.id, o.mode, o.created_at, 'rcv_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '') AS raw_token
    FROM public.commerce_orders o
    WHERE o.status = 'pending_payment'
      AND o.created_at < now() - interval '20 hours'
      AND o.created_at > now() - interval '24 hours'
      AND (
        o.mode = 'one_time'
        OR EXISTS (
          SELECT 1 FROM public.subscriptions s
          WHERE s.id = o.subscription_id AND s.status = 'pending_activation'
        )
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.commerce_payments p
        WHERE p.order_id = o.id AND p.status = 'succeeded'
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.commerce_payments p
        WHERE p.order_id = o.id
          AND p.status IN ('pending', 'requires_action')
          AND p.updated_at > now() - interval '15 minutes'
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.commerce_payment_intents pi
        WHERE pi.order_id = o.id
          AND pi.status IN ('created', 'requires_action', 'processing')
          AND pi.updated_at > now() - interval '15 minutes'
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.commerce_payment_attempts pa
        JOIN public.commerce_payment_intents pi ON pi.id = pa.payment_intent_id
        WHERE pi.order_id = o.id
          AND pa.status IN ('created', 'sent_to_provider', 'requires_action', 'processing')
          AND pa.updated_at > now() - interval '15 minutes'
      )
      AND EXISTS (
        SELECT 1
        FROM public.outbox_events e
        JOIN public.email_sends es
          ON es.provider_response->>'outboxEventId' = e.id::text
        WHERE e.event_type = 'commerce.checkout_recovery'
          AND e.idempotency_key = 'checkout_recovery:1h:' || o.id::text
          AND es.template_slug = 'commerce-checkout-recovery'
          AND es.status IN ('sent', 'delivered')
      )
    ORDER BY o.created_at ASC
    LIMIT v_limit
  ),
  enq AS (
    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    SELECT
      'commerce_order', c.id, 'commerce.checkout_recovery',
      'checkout_recovery:20h:' || c.id::text,
      jsonb_build_object(
        'orderId', c.id::text,
        'mode', c.mode,
        'reminderHours', 20,
        'recoveryToken', c.raw_token,
        'expiresAt', to_char((c.created_at + interval '24 hours') AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
      ),
      jsonb_build_object('source', 'checkout_recovery_cron')
    FROM candidates c
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING aggregate_id, (payload->>'recoveryToken') AS raw_token
  ),
  tok AS (
    INSERT INTO public.commerce_checkout_recovery_tokens (order_id, client_id, token_hash, expires_at)
    SELECT e.aggregate_id, o.client_id,
           encode(sha256(convert_to(e.raw_token, 'UTF8')), 'hex'),
           o.created_at + interval '24 hours'
    FROM enq e JOIN public.commerce_orders o ON o.id = e.aggregate_id
    RETURNING 1
  )
  SELECT count(*) INTO v_enqueued_20h FROM tok;

  RETURN jsonb_build_object(
    'enqueued_1h', v_enqueued_1h,
    'enqueued_20h', v_enqueued_20h
  );
END;
$$;


--
-- Name: enqueue_reorder_reminders(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_reorder_reminders(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_limit constant integer := GREATEST(1, LEAST(COALESCE(p_limit, 200), 1000));
  v_enqueued integer := 0;
BEGIN
  WITH candidates AS (
    SELECT o.id, f.delivered_at
    FROM public.commerce_orders o
    JOIN public.commerce_fulfillment_orders f ON f.order_id = o.id
    WHERE o.mode = 'one_time'
      AND o.client_id IS NOT NULL
      -- One candidate per order. Without this the join contributes one candidate
      -- per delivered fulfilment row: it burns two of `v_limit`, and the payload
      -- reports whichever delivery sorted first rather than the delivery the
      -- customer is being reminded about.
      AND f.id = (
        SELECT x.id
          FROM public.commerce_fulfillment_orders x
         WHERE x.order_id = o.id
         ORDER BY x.sequence_no DESC, x.id DESC
         LIMIT 1
      )
      AND f.status = 'delivered'
      AND f.delivered_at IS NOT NULL
      AND f.delivered_at < now() - interval '30 days'
      AND f.delivered_at >= now() - interval '60 days'
      AND EXISTS (
        SELECT 1
          FROM public.commerce_fulfillment_operations op
         WHERE op.fulfillment_order_id = f.id
           AND op.operation_type = 'tracking_event_recorded'
           AND op.actor_user_id IS NULL
           AND op.payload->>'status' = 'delivered'
      )
      -- Not reordered: no later non-draft purchase by the same client.
      AND NOT EXISTS (
        SELECT 1 FROM public.commerce_orders o2
        WHERE o2.client_id = o.client_id
          AND o2.id <> o.id
          AND o2.status IN ('paid', 'fulfillment_pending', 'fulfilled')
          AND o2.created_at > o.created_at
      )
      -- Not converted: no live subscription for the same client.
      AND NOT EXISTS (
        SELECT 1 FROM public.subscriptions s
        WHERE s.client_id = o.client_id
          AND s.status IN ('active', 'paused')
      )
    ORDER BY f.delivered_at ASC
    LIMIT v_limit
  ),
  inserted AS (
    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    SELECT
      'commerce_order',
      c.id,
      'commerce.order.reorder_reminder',
      'reorder:' || c.id::text,
      jsonb_build_object(
        'orderId', 'order_' || c.id::text,
        'orderUuid', c.id::text,
        'deliveredAt', to_char(c.delivered_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
      ),
      jsonb_build_object('source', 'reorder_reminder_cron')
    FROM candidates c
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_enqueued FROM inserted;

  RETURN jsonb_build_object('enqueued', v_enqueued);
END;
$$;


--
-- Name: enqueue_review_effects(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_review_effects(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_min_days constant integer := 14;
  v_max_days constant integer := 60;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
  v_count integer := 0;
  v_order record;
  v_token text;
BEGIN
  FOR v_order IN
    SELECT fo.order_id AS order_id
      FROM public.commerce_fulfillment_orders fo
      JOIN public.commerce_orders o
        ON o.id = fo.order_id
       AND o.status NOT IN ('cancelled', 'refunded')
      JOIN public.commerce_order_feedback f ON f.order_id = fo.order_id
     WHERE fo.status = 'delivered'
       -- One row per order. The loop below already refuses to enqueue twice, so
       -- a second delivered row would not duplicate the event -- it would spend a
       -- slot of `v_limit` and open the window from the wrong delivery.
       AND fo.id = (
         SELECT x.id
           FROM public.commerce_fulfillment_orders x
          WHERE x.order_id = fo.order_id
          ORDER BY x.sequence_no DESC, x.id DESC
          LIMIT 1
       )
       AND fo.delivered_at IS NOT NULL
       AND fo.delivered_at <= now() - make_interval(days => v_min_days)
       AND fo.delivered_at >= now() - make_interval(days => v_max_days)
       AND f.effect_token IS NULL
       AND EXISTS (
         SELECT 1
           FROM public.commerce_fulfillment_operations op
          WHERE op.fulfillment_order_id = fo.id
            AND op.operation_type = 'tracking_event_recorded'
            AND op.actor_user_id IS NULL
            AND op.payload->>'status' = 'delivered'
       )
       AND NOT EXISTS (
         SELECT 1
           FROM public.commerce_return_requests r
          WHERE r.order_id = fo.order_id
            AND r.status IN ('requested','approved','label_issued','in_transit','received','restocked','exception')
       )
       AND NOT EXISTS (
         SELECT 1
           FROM public.commerce_order_holds h
          WHERE h.order_id = fo.order_id
            AND h.status = 'active'
            AND h.reason IN ('manual_support','fulfillment_exception')
       )
     ORDER BY fo.delivered_at ASC
     LIMIT v_limit
  LOOP
    v_token := replace(gen_random_uuid()::text, '-', '');

    UPDATE public.commerce_order_feedback
       SET effect_token = v_token
     WHERE order_id = v_order.order_id
       AND effect_token IS NULL;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    VALUES (
      'commerce_order',
      v_order.order_id,
      'commerce.order.review_effects',
      'review_effects:' || v_order.order_id::text,
      jsonb_build_object(
        'orderId', 'order_' || v_order.order_id::text,
        'orderUuid', v_order.order_id,
        'token', v_token
      ),
      jsonb_build_object('source', 'enqueue_review_effects')
    )
    ON CONFLICT (event_type, idempotency_key) DO NOTHING;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION enqueue_review_effects(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_review_effects(p_limit integer) IS 'Service-role scan: enqueue review-effects for provider-confirmed deliveries in [now()-60d, now()-14d] with feedback row, excluding cancelled/refunded/open-return/active-support orders.';


--
-- Name: enqueue_review_requests(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_review_requests(p_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_delay_days constant integer := 3;
  v_max_days constant integer := 30;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
  v_count integer := 0;
  v_order record;
  v_token text;
BEGIN
  FOR v_order IN
    SELECT fo.order_id AS order_id
      FROM public.commerce_fulfillment_orders fo
      JOIN public.commerce_orders o
        ON o.id = fo.order_id
       AND o.status NOT IN ('cancelled', 'refunded')
     WHERE fo.status = 'delivered'
       -- One row per order, for the same reason as the effects sibling: the
       -- feedback row is unique per order, so a second delivered row cannot
       -- duplicate the request -- it can only spend a slot and start the
       -- three-day window from a delivery the replacement has superseded.
       AND fo.id = (
         SELECT x.id
           FROM public.commerce_fulfillment_orders x
          WHERE x.order_id = fo.order_id
          ORDER BY x.sequence_no DESC, x.id DESC
          LIMIT 1
       )
       AND fo.delivered_at IS NOT NULL
       AND fo.delivered_at <= now() - make_interval(days => v_delay_days)
       AND fo.delivered_at >= now() - make_interval(days => v_max_days)
       AND EXISTS (
         SELECT 1
           FROM public.commerce_fulfillment_operations op
          WHERE op.fulfillment_order_id = fo.id
            AND op.operation_type = 'tracking_event_recorded'
            AND op.actor_user_id IS NULL
            AND op.payload->>'status' = 'delivered'
       )
       AND NOT EXISTS (
         SELECT 1 FROM public.commerce_order_feedback f
          WHERE f.order_id = fo.order_id
       )
     ORDER BY fo.delivered_at ASC
     LIMIT v_limit
  LOOP
    v_token := replace(gen_random_uuid()::text, '-', '');

    INSERT INTO public.commerce_order_feedback (order_id, token)
    VALUES (v_order.order_id, v_token)
    ON CONFLICT (order_id) DO NOTHING;

    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    VALUES (
      'commerce_order',
      v_order.order_id,
      'commerce.order.review_request',
      'review_request:' || v_order.order_id::text,
      jsonb_build_object(
        'orderId', 'order_' || v_order.order_id::text,
        'orderUuid', v_order.order_id,
        'token', v_token
      ),
      jsonb_build_object('source', 'enqueue_review_requests')
    )
    ON CONFLICT (event_type, idempotency_key) DO NOTHING;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: FUNCTION enqueue_review_requests(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_review_requests(p_limit integer) IS 'Service-role scan: enqueue a review-request outbox event for provider-confirmed deliveries in [now()-30d, now()-3d] with no feedback row, excluding cancelled/refunded parent orders.';


--
-- Name: enqueue_subscription_renewal_reminders(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_subscription_renewal_reminders(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_limit constant integer := GREATEST(1, LEAST(COALESCE(p_limit, 100), 500));
  v_enqueued integer := 0;
BEGIN
  WITH candidates AS (
    SELECT
      s.id AS subscription_id,
      s.client_id,
      s.next_cycle_at AS renewal_at
    FROM public.subscriptions s
    JOIN public.clients cl
      ON cl.id = s.client_id
    JOIN public.commerce_payment_method_refs m
      ON m.subscription_id = s.id
     AND m.active = true
     AND m.status = 'active'
    WHERE s.status = 'active'
      AND s.next_cycle_at IS NOT NULL
      AND s.next_cycle_at >= now() + interval '3 days'
      AND s.next_cycle_at <= now() + interval '5 days'
      AND s.updated_at < now() - (
        CASE
          WHEN s.starter_pack IS NOT NULL
           AND COALESCE(
                 (SELECT max(c2.cycle_number)
                    FROM public.subscription_cycles c2
                   WHERE c2.subscription_id = s.id),
                 0
               ) + 1 IN (2, 3)
            THEN interval '1 day'
          ELSE interval '5 days'
        END
      )
      AND NOT EXISTS (
        SELECT 1
          FROM public.subscription_cycles c
         WHERE c.subscription_id = s.id
           AND c.status IN ('payment_pending', 'retry_scheduled')
      )
    ORDER BY s.next_cycle_at ASC, s.id ASC
    LIMIT v_limit
    FOR UPDATE OF s SKIP LOCKED
  ),
  shaped AS (
    SELECT
      c.subscription_id,
      c.client_id,
      c.renewal_at,
      c.subscription_id::text || ':' || to_char(c.renewal_at AT TIME ZONE 'UTC', 'YYYY-MM-DD') AS email_dedupe_key
    FROM candidates c
  ),
  inserted AS (
    INSERT INTO public.outbox_events (
      aggregate_type,
      aggregate_id,
      event_type,
      idempotency_key,
      payload,
      metadata
    )
    SELECT
      'subscription',
      s.subscription_id,
      'subscription.renewal_upcoming',
      'subscription_renewal_upcoming:' || s.email_dedupe_key,
      jsonb_build_object(
        'clientId', s.client_id::text,
        'subscriptionId', s.subscription_id::text,
        'renewalAt', to_char(s.renewal_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
        'dedupeKey', s.email_dedupe_key
      ),
      jsonb_build_object('source', 'subscription_renewal_reminder_cron')
    FROM shaped s
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_enqueued FROM inserted;

  RETURN jsonb_build_object('enqueued', v_enqueued);
END;
$$;


--
-- Name: FUNCTION enqueue_subscription_renewal_reminders(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enqueue_subscription_renewal_reminders(p_limit integer) IS 'Service-role-only. Enqueues subscription.renewal_upcoming outbox rows for billable active subscriptions 3-5 days before the renewal charge, requiring an active payment method, no open payment/retry cycle, and no recent customer change within the reminder window. The recent-change window is 5 days, relaxed to 1 day for a starter-pack subscription taking its 2nd or 3rd delivery, whose acquisition interval can be shorter than 5 days.';


--
-- Name: feedback_add_photo_url_by_hash(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feedback_add_photo_url_by_hash(p_hash text, p_storage_key text, p_max_count integer DEFAULT 10) RETURNS TABLE(photo_urls text[], total_count integer, idempotent_replay boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_feedback RECORD;
  v_urls TEXT[];
  v_replay BOOLEAN;
BEGIN
  SELECT f.id, COALESCE(f.photo_urls, ARRAY[]::TEXT[]) AS current_urls, t.id AS tester_id
  INTO v_feedback
  FROM public.feedback f
  JOIN public.testers t ON t.id = f.tester_id
  WHERE f.hash = p_hash
  FOR UPDATE OF f;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Feedback not found';
  END IF;
  IF p_storage_key NOT LIKE v_feedback.tester_id::TEXT || '/c/%' THEN
    RAISE EXCEPTION 'storage_key does not match tester';
  END IF;

  v_replay := p_storage_key = ANY(v_feedback.current_urls);
  IF NOT v_replay AND COALESCE(array_length(v_feedback.current_urls, 1), 0) >= p_max_count THEN
    RAISE EXCEPTION 'feedback media limit exceeded';
  END IF;

  v_urls := CASE
    WHEN v_replay THEN v_feedback.current_urls
    ELSE array_append(v_feedback.current_urls, p_storage_key)
  END;

  UPDATE public.feedback
  SET photo_urls = v_urls, updated_at = now()
  WHERE id = v_feedback.id;

  RETURN QUERY SELECT v_urls, COALESCE(array_length(v_urls, 1), 0), v_replay;
END;
$$;


--
-- Name: feedback_remove_photo_url_by_hash(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.feedback_remove_photo_url_by_hash(p_hash text, p_storage_key text) RETURNS TABLE(photo_urls text[], remaining_count integer, removed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_feedback RECORD;
  v_urls TEXT[];
  v_removed BOOLEAN;
BEGIN
  SELECT f.id, COALESCE(f.photo_urls, ARRAY[]::TEXT[]) AS current_urls, t.id AS tester_id
  INTO v_feedback
  FROM public.feedback f
  JOIN public.testers t ON t.id = f.tester_id
  WHERE f.hash = p_hash
  FOR UPDATE OF f;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Feedback not found';
  END IF;
  IF p_storage_key NOT LIKE v_feedback.tester_id::TEXT || '/c/%' THEN
    RAISE EXCEPTION 'storage_key does not match tester';
  END IF;

  v_removed := p_storage_key = ANY(v_feedback.current_urls);
  IF NOT v_removed THEN
    RAISE EXCEPTION 'storage_key not associated with this feedback';
  END IF;

  SELECT COALESCE(array_agg(key), ARRAY[]::TEXT[])
  INTO v_urls
  FROM unnest(v_feedback.current_urls) AS key
  WHERE key <> p_storage_key;

  UPDATE public.feedback
  SET photo_urls = v_urls, updated_at = now()
  WHERE id = v_feedback.id;

  RETURN QUERY SELECT v_urls, COALESCE(array_length(v_urls, 1), 0), v_removed;
END;
$$;


--
-- Name: fulfillment_provider_upsert_stock_current(text, text, text, integer, integer, integer, timestamp with time zone, timestamp with time zone, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fulfillment_provider_upsert_stock_current(p_idempotency_key text, p_provider_kind text, p_sku text, p_provider_total_quantity integer, p_provider_for_sale_quantity integer, p_provider_reserved_unavailable_quantity integer, p_last_synced_at timestamp with time zone, p_stale_after timestamp with time zone, p_sync_run_id text, p_evidence jsonb DEFAULT '{}'::jsonb, p_inventory_class text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_sku public.catalog_skus%ROWTYPE;
  v_location_id uuid;
  v_balance_id uuid;
  v_existing_run text;
  v_inventory_class text;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
     OR p_provider_kind IS NULL OR btrim(p_provider_kind) = ''
     OR p_sku IS NULL OR btrim(p_sku) = ''
     OR p_last_synced_at IS NULL
     OR p_stale_after IS NULL
     OR p_stale_after <= p_last_synced_at
     OR p_sync_run_id IS NULL OR btrim(p_sync_run_id) = ''
     OR p_provider_total_quantity IS NULL OR p_provider_total_quantity < 0
     OR p_provider_for_sale_quantity IS NULL OR p_provider_for_sale_quantity < 0
     OR p_provider_reserved_unavailable_quantity IS NULL OR p_provider_reserved_unavailable_quantity < 0
     OR (p_inventory_class IS NOT NULL AND p_inventory_class NOT IN ('sellable', 'packaging')) THEN
    RAISE EXCEPTION 'fulfillment_provider_stock_current_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT sync_run_id
    INTO v_existing_run
    FROM public.fulfillment_provider_stock_current
   WHERE provider_kind = btrim(p_provider_kind)
     AND sku = btrim(p_sku);

  SELECT *
    INTO v_sku
    FROM public.catalog_skus
   WHERE sku = btrim(p_sku)
   LIMIT 1;

  v_inventory_class := coalesce(
    p_inventory_class,
    CASE WHEN v_sku.id IS NOT NULL THEN 'sellable' END
  );

  INSERT INTO public.fulfillment_provider_stock_current (
    provider_kind,
    sku,
    catalog_sku_id,
    inventory_class,
    provider_total_quantity,
    provider_for_sale_quantity,
    provider_reserved_unavailable_quantity,
    last_synced_at,
    stale_after,
    sync_run_id,
    evidence
  )
  VALUES (
    btrim(p_provider_kind),
    btrim(p_sku),
    v_sku.id,
    v_inventory_class,
    p_provider_total_quantity,
    p_provider_for_sale_quantity,
    p_provider_reserved_unavailable_quantity,
    p_last_synced_at,
    p_stale_after,
    p_sync_run_id,
    coalesce(p_evidence, '{}'::jsonb)
      || jsonb_build_object('idempotencyKey', p_idempotency_key)
  )
  ON CONFLICT (provider_kind, sku) DO UPDATE SET
    catalog_sku_id = EXCLUDED.catalog_sku_id,
    inventory_class = EXCLUDED.inventory_class,
    provider_total_quantity = EXCLUDED.provider_total_quantity,
    provider_for_sale_quantity = EXCLUDED.provider_for_sale_quantity,
    provider_reserved_unavailable_quantity = EXCLUDED.provider_reserved_unavailable_quantity,
    last_synced_at = EXCLUDED.last_synced_at,
    stale_after = EXCLUDED.stale_after,
    sync_run_id = EXCLUDED.sync_run_id,
    evidence = EXCLUDED.evidence,
    updated_at = now();

  IF btrim(p_provider_kind) = 'omnipack'
     AND v_inventory_class = 'sellable'
     AND v_sku.id IS NOT NULL THEN
    SELECT id INTO v_location_id
      FROM public.inventory_locations
     WHERE code = 'omnipack-stock-master'
     LIMIT 1;

    INSERT INTO public.inventory_balances (sku_id, location_id, lot_id, on_hand)
    VALUES (v_sku.id, v_location_id, NULL, p_provider_for_sale_quantity)
    ON CONFLICT ON CONSTRAINT inventory_balances_unique_stock_key DO NOTHING;

    UPDATE public.inventory_balances
       SET on_hand = greatest(p_provider_for_sale_quantity, reserved),
           unavailable = 0,
           updated_at = now()
     WHERE sku_id = v_sku.id
       AND location_id = v_location_id
       AND lot_id IS NULL
     RETURNING id INTO v_balance_id;
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'fulfillment.provider_stock.v0',
    'providerKind', btrim(p_provider_kind),
    'sku', btrim(p_sku),
    'replayed', coalesce(v_existing_run = p_sync_run_id, false),
    'catalogSkuId', v_sku.id,
    'inventoryClass', v_inventory_class
  );
END;
$$;


--
-- Name: FUNCTION fulfillment_provider_upsert_stock_current(p_idempotency_key text, p_provider_kind text, p_sku text, p_provider_total_quantity integer, p_provider_for_sale_quantity integer, p_provider_reserved_unavailable_quantity integer, p_last_synced_at timestamp with time zone, p_stale_after timestamp with time zone, p_sync_run_id text, p_evidence jsonb, p_inventory_class text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fulfillment_provider_upsert_stock_current(p_idempotency_key text, p_provider_kind text, p_sku text, p_provider_total_quantity integer, p_provider_for_sale_quantity integer, p_provider_reserved_unavailable_quantity integer, p_last_synced_at timestamp with time zone, p_stale_after timestamp with time zone, p_sync_run_id text, p_evidence jsonb, p_inventory_class text) IS 'Upserts raw provider stock with optional SKU classification; only sellable OmniPack catalog SKUs may update the local inventory mirror.';


--
-- Name: get_active_tester_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_tester_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT count(*)::integer FROM public.testers WHERE status != 'rejected';
$$;


--
-- Name: get_feedback_by_hash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_feedback_by_hash(p_hash text) RETURNS TABLE(id uuid, tester_id uuid, hash text, overall_rating smallint, taste_rating smallint, texture_rating smallint, digestion_rating smallint, would_recommend boolean, favorite_flavor text, open_feedback text, photo_urls text[], submitted_at timestamp with time zone, packaging_rating smallint, label_rating smallint, unboxing_rating smallint, instagram_handle text, surprise_text text, current_food_brand text, monthly_food_spend_pln numeric, purchase_drivers jsonb, heard_about_openlup text, section_b_submitted_at timestamp with time zone, section_c_submitted_at timestamp with time zone, calendly_clicked_at timestamp with time zone, nps_rating smallint, created_at timestamp with time zone, updated_at timestamp with time zone, tester_first_name text, tester_dog_name text, tester_dog_breed text, tester_pet_type text, tester_cat_name text, tester_country text, tester_delivered_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    f.id, f.tester_id, f.hash,
    f.overall_rating, f.taste_rating, f.texture_rating, f.digestion_rating,
    f.would_recommend, f.favorite_flavor, f.open_feedback, f.photo_urls,
    f.submitted_at,
    f.packaging_rating, f.label_rating, f.unboxing_rating,
    f.instagram_handle,
    f.surprise_text, f.current_food_brand, f.monthly_food_spend_pln,
    f.purchase_drivers, f.heard_about_openlup, f.section_b_submitted_at,
    f.section_c_submitted_at, f.calendly_clicked_at, f.nps_rating,
    f.created_at, f.updated_at,
    t.first_name AS tester_first_name,
    t.dog_name AS tester_dog_name,
    t.dog_breed AS tester_dog_breed,
    t.pet_type AS tester_pet_type,
    t.cat_name AS tester_cat_name,
    t.country AS tester_country,
    t.delivered_at AS tester_delivered_at
  FROM public.feedback f
  LEFT JOIN public.testers t ON t.id = f.tester_id
  WHERE f.hash = p_hash
  LIMIT 1;
$$;


--
-- Name: inventory_adjust_stock(text, uuid, uuid, uuid, integer, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_adjust_stock(p_idempotency_key text, p_sku_id uuid, p_location_id uuid, p_lot_id uuid, p_quantity_delta integer, p_reason text, p_actor_user_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_existing public.inventory_stock_movements%ROWTYPE;
  v_balance public.inventory_balances%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8 THEN
    RAISE EXCEPTION 'inventory_invalid_idempotency_key' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing
    FROM public.inventory_stock_movements
   WHERE movement_type = 'adjustment'
     AND idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN jsonb_build_object('contractVersion', 'inventory.v0', 'replayed', true);
  END IF;

  INSERT INTO public.inventory_balances (sku_id, location_id, lot_id)
  VALUES (p_sku_id, p_location_id, p_lot_id)
  ON CONFLICT ON CONSTRAINT inventory_balances_unique_stock_key DO NOTHING;

  SELECT * INTO v_balance
    FROM public.inventory_balances
   WHERE sku_id = p_sku_id
     AND location_id = p_location_id
     AND lot_id IS NOT DISTINCT FROM p_lot_id
   FOR UPDATE;

  IF v_balance.on_hand + p_quantity_delta < v_balance.reserved THEN
    RAISE EXCEPTION 'inventory_adjustment_would_break_reserved_stock' USING ERRCODE = '23514';
  END IF;
  IF v_balance.on_hand + p_quantity_delta < 0 THEN
    RAISE EXCEPTION 'inventory_adjustment_negative_on_hand' USING ERRCODE = '23514';
  END IF;

  UPDATE public.inventory_balances
     SET on_hand = on_hand + p_quantity_delta,
         updated_at = now()
   WHERE id = v_balance.id;

  INSERT INTO public.inventory_stock_movements (
    idempotency_key, movement_type, sku_id, location_id, lot_id, quantity_delta,
    actor_user_id, reason, metadata
  )
  VALUES (
    p_idempotency_key, 'adjustment', p_sku_id, p_location_id, p_lot_id,
    p_quantity_delta, p_actor_user_id, p_reason, coalesce(p_metadata, '{}'::jsonb)
  );

  RETURN jsonb_build_object('contractVersion', 'inventory.v0', 'replayed', false);
END;
$$;


--
-- Name: inventory_available_quantity(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_available_quantity(p_sku_id uuid, p_location_id uuid, p_lot_id uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT greatest(0, b.on_hand - b.reserved - b.unavailable - b.safety_stock)
    FROM public.inventory_balances b
   WHERE b.sku_id = p_sku_id
     AND b.location_id = p_location_id
     AND b.lot_id IS NOT DISTINCT FROM p_lot_id;
$$;


--
-- Name: inventory_consume_reservation_for_fulfillment(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_consume_reservation_for_fulfillment(p_idempotency_key text, p_reservation_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_reservation public.inventory_reservations%ROWTYPE;
BEGIN
  SELECT * INTO v_reservation FROM public.inventory_reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'inventory_reservation_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_reservation.status <> 'reserved' THEN
    RETURN jsonb_build_object('contractVersion', 'inventory.v0', 'reservationId', p_reservation_id, 'status', v_reservation.status, 'replayed', true);
  END IF;

  UPDATE public.inventory_reservations
     SET status = 'consumed', consumed_at = now(), updated_at = now()
   WHERE id = p_reservation_id;
  UPDATE public.inventory_balances
     SET reserved = reserved - v_reservation.quantity,
         on_hand = on_hand - v_reservation.quantity,
         updated_at = now()
   WHERE sku_id = v_reservation.sku_id
     AND location_id = v_reservation.location_id
     AND lot_id IS NOT DISTINCT FROM v_reservation.lot_id;
  INSERT INTO public.inventory_stock_movements (
    idempotency_key, movement_type, sku_id, location_id, lot_id, reservation_id,
    quantity_delta, reason, metadata
  )
  VALUES (p_idempotency_key, 'reservation_consumed', v_reservation.sku_id, v_reservation.location_id, v_reservation.lot_id, p_reservation_id, -v_reservation.quantity, 'fulfillment_consumed', coalesce(p_metadata, '{}'::jsonb));

  RETURN jsonb_build_object('contractVersion', 'inventory.v0', 'reservationId', p_reservation_id, 'status', 'consumed', 'replayed', false);
END;
$$;


--
-- Name: inventory_expire_reservations(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_expire_reservations(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_count integer := 0;
  v_reservation record;
BEGIN
  FOR v_reservation IN
    SELECT * FROM public.inventory_reservations
     WHERE status = 'reserved'
       AND expires_at IS NOT NULL
       AND expires_at <= now()
     ORDER BY expires_at
     LIMIT p_limit
     FOR UPDATE
  LOOP
    UPDATE public.inventory_reservations
       SET status = 'expired', released_at = now(), updated_at = now()
     WHERE id = v_reservation.id;
    UPDATE public.inventory_balances
       SET reserved = reserved - v_reservation.quantity, updated_at = now()
     WHERE sku_id = v_reservation.sku_id
       AND location_id = v_reservation.location_id
       AND lot_id IS NOT DISTINCT FROM v_reservation.lot_id;
    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('contractVersion', 'inventory.v0', 'expiredCount', v_count);
END;
$$;


--
-- Name: inventory_guard_consumable_lot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_guard_consumable_lot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_lot public.inventory_lots%ROWTYPE;
BEGIN
  IF NEW.status <> 'consumed' OR NEW.lot_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT *
    INTO v_lot
    FROM public.inventory_lots
   WHERE id = NEW.lot_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'inventory_lot_not_found'
      USING ERRCODE = '22023';
  END IF;

  IF v_lot.status <> 'available' OR (v_lot.expires_at IS NOT NULL AND v_lot.expires_at <= now()) THEN
    RAISE EXCEPTION 'inventory_lot_not_consumable'
      USING
        ERRCODE = '22023',
        DETAIL = 'Reserved lot is not available for fulfillment consumption.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION inventory_guard_consumable_lot(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_guard_consumable_lot() IS 'Service-owned trigger guard for fulfillment consumption; execute is revoked from public runtime roles.';


--
-- Name: inventory_invalidate_lot(text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_invalidate_lot(p_idempotency_key text, p_lot_id uuid, p_next_status text, p_reason text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_lot public.inventory_lots%ROWTYPE;
  v_reservation public.inventory_reservations%ROWTYPE;
  v_count integer := 0;
BEGIN
  IF p_idempotency_key IS NULL
    OR btrim(p_idempotency_key) = ''
    OR length(p_idempotency_key) < 8
    OR p_lot_id IS NULL
    OR p_next_status NOT IN ('expired', 'recalled', 'quarantined')
    OR p_reason IS NULL
    OR btrim(p_reason) = ''
  THEN
    RAISE EXCEPTION 'inventory_lot_invalidation_invalid_input'
      USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_lot
    FROM public.inventory_lots
   WHERE id = p_lot_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'inventory_lot_not_found'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.inventory_lots
     SET status = p_next_status,
         updated_at = now(),
         metadata = metadata || coalesce(p_metadata, '{}'::jsonb)
   WHERE id = p_lot_id;

  FOR v_reservation IN
    SELECT *
      FROM public.inventory_reservations
     WHERE lot_id = p_lot_id
       AND status = 'reserved'
     FOR UPDATE
  LOOP
    UPDATE public.inventory_reservations
       SET status = 'released',
           released_at = now(),
           updated_at = now(),
           metadata = metadata || jsonb_build_object(
             'lotInvalidationStatus', p_next_status,
             'source', 'inventory_invalidate_lot'
           )
     WHERE id = v_reservation.id;

    UPDATE public.inventory_balances
       SET reserved = reserved - v_reservation.quantity,
           updated_at = now()
     WHERE sku_id = v_reservation.sku_id
       AND location_id = v_reservation.location_id
       AND lot_id IS NOT DISTINCT FROM v_reservation.lot_id;

    INSERT INTO public.inventory_stock_movements (
      idempotency_key,
      movement_type,
      sku_id,
      location_id,
      lot_id,
      reservation_id,
      quantity_delta,
      reason,
      metadata
    )
    VALUES (
      p_idempotency_key || ':' || v_reservation.id::text,
      'reservation_released',
      v_reservation.sku_id,
      v_reservation.location_id,
      v_reservation.lot_id,
      v_reservation.id,
      -v_reservation.quantity,
      p_reason,
      coalesce(p_metadata, '{}'::jsonb)
    )
    ON CONFLICT (movement_type, idempotency_key) DO NOTHING;

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'contractVersion', 'inventory.v0',
    'lotId', p_lot_id,
    'status', p_next_status,
    'releasedReservationCount', v_count
  );
END;
$$;


--
-- Name: FUNCTION inventory_invalidate_lot(p_idempotency_key text, p_lot_id uuid, p_next_status text, p_reason text, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_invalidate_lot(p_idempotency_key text, p_lot_id uuid, p_next_status text, p_reason text, p_metadata jsonb) IS 'Service-role-only lot invalidation boundary that releases active reservations for recalled/expired/quarantined lots.';


--
-- Name: inventory_recount_reserved_balances(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_recount_reserved_balances(p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
DECLARE
  v_now constant timestamptz := now();
  v_drifted integer := 0;
  v_targets jsonb := '[]'::jsonb;
  v_evidence jsonb := '[]'::jsonb;
  v_blocked jsonb := '[]'::jsonb;
  v_applied integer := 0;
BEGIN
  IF private.production_database_fingerprint_matches() THEN
    RAISE EXCEPTION 'inventory_recount_reserved_balances_forbidden_in_production'
      USING ERRCODE = '42501';
  END IF;

  -- Apply takes the same lock the reservation path takes: a row lock on
  -- `inventory_balances`, exactly as `inventory_reserve_order` does with
  -- `FOR UPDATE OF b` (20260605113000:295). That row is the serialization point for
  -- every counter movement -- reserve, release, consume and expire all update it --
  -- so holding it is what makes a concurrent reserve WAIT here and then increment
  -- the recounted value, instead of committing between the read and the write and
  -- being silently overwritten by a value computed before it existed. Ordered by id
  -- so two operators cannot deadlock against each other. The dry run takes no lock:
  -- it writes nothing, and a report is allowed to be a moment's snapshot.
  IF p_apply THEN
    PERFORM 1
      FROM public.inventory_balances b
     WHERE b.id IN (SELECT balance_id FROM private.inventory_reserved_balance_recount_targets(v_now))
     ORDER BY b.id
     FOR UPDATE;
  END IF;

  -- Evaluated ONCE, after the lock, into `v_targets`. The blocked check, the
  -- reported evidence and the UPDATE all read that one snapshot, so the report is
  -- the write: re-calling the projection per consumer would let the three disagree.
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'balanceId', t.balance_id,
    'skuId', t.sku_id,
    'locationId', t.location_id,
    'lotId', t.lot_id,
    'onHand', t.on_hand,
    'balanceReserved', t.balance_reserved,
    'expectedReserved', t.expected_reserved,
    'activeReserved', t.active_reserved,
    'delta', t.expected_reserved - t.balance_reserved
  ) ORDER BY t.balance_id), '[]'::jsonb)
  INTO v_targets
  FROM private.inventory_reserved_balance_recount_targets(v_now) t;

  v_drifted := jsonb_array_length(v_targets);
  v_evidence := v_targets;

  SELECT coalesce(jsonb_agg(entry ->> 'balanceId' ORDER BY entry ->> 'balanceId'), '[]'::jsonb)
  INTO v_blocked
  FROM jsonb_array_elements(v_targets) entry
  WHERE (entry ->> 'expectedReserved')::integer > (entry ->> 'onHand')::integer;

  IF p_apply AND jsonb_array_length(v_blocked) > 0 THEN
    RAISE EXCEPTION 'inventory_recount_reserved_balances_would_exceed_on_hand: %', v_blocked::text
      USING ERRCODE = '23514';
  END IF;

  IF p_apply THEN
    UPDATE public.inventory_balances b
       SET reserved = t."expectedReserved",
           updated_at = now()
      FROM jsonb_to_recordset(v_targets)
             AS t("balanceId" uuid, "expectedReserved" integer)
     WHERE b.id = t."balanceId";
    GET DIAGNOSTICS v_applied = ROW_COUNT;
  END IF;

  RETURN jsonb_build_object(
    'applied', p_apply,
    'evaluatedAt', v_now,
    'driftedBalances', v_drifted,
    'updatedBalances', v_applied,
    'blockedBalanceIds', v_blocked,
    'evidence', v_evidence
  );
END;
$$;


--
-- Name: FUNCTION inventory_recount_reserved_balances(p_apply boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_recount_reserved_balances(p_apply boolean) IS 'Service-role operator recount of inventory_balances.reserved from live reservation rows. Defaults to a read-only dry run; p_apply=true writes the conserved total. Refuses execution on the fingerprinted production database, and refuses the whole call rather than clamping when a recount would exceed on_hand. Never scheduled: no cron, job control or rollout step invokes it.';


--
-- Name: inventory_release_reservation(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_release_reservation(p_idempotency_key text, p_reservation_id uuid, p_reason text DEFAULT 'released'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_reservation public.inventory_reservations%ROWTYPE;
BEGIN
  SELECT * INTO v_reservation FROM public.inventory_reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'inventory_reservation_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_reservation.status <> 'reserved' THEN
    RETURN jsonb_build_object('contractVersion', 'inventory.v0', 'reservationId', p_reservation_id, 'status', v_reservation.status, 'replayed', true);
  END IF;

  UPDATE public.inventory_reservations
     SET status = 'released', released_at = now(), updated_at = now()
   WHERE id = p_reservation_id;
  UPDATE public.inventory_balances
     SET reserved = reserved - v_reservation.quantity, updated_at = now()
   WHERE sku_id = v_reservation.sku_id
     AND location_id = v_reservation.location_id
     AND lot_id IS NOT DISTINCT FROM v_reservation.lot_id;
  INSERT INTO public.inventory_stock_movements (
    idempotency_key, movement_type, sku_id, location_id, lot_id, reservation_id,
    quantity_delta, reason, metadata
  )
  VALUES (p_idempotency_key, 'reservation_released', v_reservation.sku_id, v_reservation.location_id, v_reservation.lot_id, p_reservation_id, -v_reservation.quantity, p_reason, coalesce(p_metadata, '{}'::jsonb));

  RETURN jsonb_build_object('contractVersion', 'inventory.v0', 'reservationId', p_reservation_id, 'status', 'released', 'replayed', false);
END;
$$;


--
-- Name: inventory_reserve_order(text, uuid, uuid, uuid, uuid, integer, text, text, timestamp with time zone, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_reserve_order(p_idempotency_key text, p_order_id uuid, p_order_item_id uuid, p_subscription_cycle_id uuid, p_sku_id uuid, p_quantity integer, p_kind text, p_payment_status text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb, p_provider_kind text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_existing jsonb;
  v_balance public.inventory_balances%ROWTYPE;
  v_location_id uuid;
  v_location_code text;
  v_remaining integer;
  v_allocate integer;
  v_reservation_id uuid;
  v_first_reservation_id uuid;
  v_reservation_ids jsonb := '[]'::jsonb;
  v_provider_stock record;
  v_provider_stock_rows integer;
  v_sku text;
  v_open_reserved integer;
  v_safety_stock integer;
  v_provider_available integer;
  v_active_reserved integer;
BEGIN
  IF p_payment_status NOT IN ('created', 'requires_action', 'processing', 'succeeded') THEN
    RAISE EXCEPTION 'inventory_reservation_payment_status_not_reservable' USING ERRCODE = '22023';
  END IF;
  IF p_quantity IS NULL OR p_quantity <= 0 THEN
    RAISE EXCEPTION 'inventory_reservation_invalid_quantity' USING ERRCODE = '22023';
  END IF;

  SELECT jsonb_build_object(
    'contractVersion', 'inventory.v0',
    'reservationId', id,
    'status', status,
    'replayed', true
  )
    INTO v_existing
    FROM public.inventory_reservations
   WHERE idempotency_key = p_idempotency_key
     AND sku_id = p_sku_id
   LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  IF p_provider_kind = 'omnipack' THEN
    SELECT sku INTO v_sku
      FROM public.catalog_skus
     WHERE id = p_sku_id;
    IF v_sku IS NULL THEN
      RAISE EXCEPTION 'inventory_external_provider_sku_not_found' USING ERRCODE = '22023';
    END IF;

    IF to_regclass('public.fulfillment_provider_stock_current') IS NULL THEN
      RAISE EXCEPTION 'inventory_external_provider_stock_missing' USING ERRCODE = '23514';
    END IF;

    EXECUTE
      'SELECT provider_for_sale_quantity, stale_after, last_synced_at
         FROM public.fulfillment_provider_stock_current
        WHERE provider_kind = $1
          AND catalog_sku_id = $2
        FOR UPDATE'
      INTO v_provider_stock
      USING p_provider_kind, p_sku_id;
    GET DIAGNOSTICS v_provider_stock_rows = ROW_COUNT;
    IF v_provider_stock_rows = 0 THEN
      RAISE EXCEPTION 'inventory_external_provider_stock_missing' USING ERRCODE = '23514';
    END IF;
    IF v_provider_stock.stale_after <= now() THEN
      RAISE EXCEPTION 'inventory_external_provider_stock_stale' USING ERRCODE = '23514';
    END IF;

    SELECT coalesce(sum(quantity), 0)
      INTO v_open_reserved
      FROM public.inventory_reservations
     WHERE sku_id = p_sku_id
       AND status = 'reserved'
       AND metadata->>'providerKind' = p_provider_kind
       AND (expires_at IS NULL OR expires_at > now());

    SELECT coalesce(sum(b.safety_stock), 0)
      INTO v_safety_stock
      FROM public.inventory_balances b
      JOIN public.inventory_locations l ON l.id = b.location_id
     WHERE b.sku_id = p_sku_id
       AND l.status = 'active'
       AND l.fulfillable = true;

    v_provider_available := greatest(
      0,
      v_provider_stock.provider_for_sale_quantity - v_open_reserved - v_safety_stock
    );
    IF v_provider_available < p_quantity THEN
      RAISE EXCEPTION 'inventory_external_provider_insufficient_available_stock' USING ERRCODE = '23514';
    END IF;

    SELECT id, code
      INTO v_location_id, v_location_code
      FROM public.inventory_locations
     WHERE code = 'omnipack-stock-master'
       AND status = 'active'
       AND fulfillable = true
     LIMIT 1;
    IF v_location_id IS NULL THEN
      RAISE EXCEPTION 'inventory_external_provider_location_missing' USING ERRCODE = '23514';
    END IF;

    INSERT INTO public.inventory_balances (sku_id, location_id, lot_id, on_hand)
    VALUES (p_sku_id, v_location_id, NULL, v_provider_stock.provider_for_sale_quantity)
    ON CONFLICT ON CONSTRAINT inventory_balances_unique_stock_key DO NOTHING;

    SELECT *
      INTO v_balance
      FROM public.inventory_balances
     WHERE sku_id = p_sku_id
       AND location_id = v_location_id
       AND lot_id IS NULL
     FOR UPDATE;

    UPDATE public.inventory_balances
       SET on_hand = greatest(v_balance.on_hand, v_provider_stock.provider_for_sale_quantity, v_balance.reserved + p_quantity),
           updated_at = now()
     WHERE id = v_balance.id
     RETURNING * INTO v_balance;

    INSERT INTO public.inventory_reservations (
      idempotency_key, order_id, order_item_id, subscription_cycle_id, sku_id,
      location_id, lot_id, quantity, kind, expires_at, metadata
    )
    VALUES (
      p_idempotency_key, p_order_id, p_order_item_id, p_subscription_cycle_id, p_sku_id,
      v_location_id, NULL, p_quantity, p_kind,
      coalesce(
        p_expires_at,
        now() + CASE WHEN p_kind = 'subscription_retry_window' THEN interval '72 hours' ELSE interval '30 minutes' END
      ),
      coalesce(p_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'providerKind', p_provider_kind,
          'stockAuthority', 'external_stock_master_with_local_reservations',
          'providerForSaleAtReservation', v_provider_stock.provider_for_sale_quantity,
          'providerStockSyncedAt', v_provider_stock.last_synced_at
        )
    )
    RETURNING id INTO v_reservation_id;

    UPDATE public.inventory_balances
       SET reserved = reserved + p_quantity,
           updated_at = now()
     WHERE id = v_balance.id;

    INSERT INTO public.inventory_stock_movements (
      idempotency_key, movement_type, sku_id, location_id, lot_id, reservation_id,
      quantity_delta, reason, metadata
    )
    VALUES (
      p_idempotency_key || ':' || v_reservation_id::text,
      'reservation_created',
      p_sku_id,
      v_location_id,
      NULL,
      v_reservation_id,
      p_quantity,
      'order_reserved',
      coalesce(p_metadata, '{}'::jsonb)
        || jsonb_build_object('providerKind', p_provider_kind, 'stockAuthority', 'external_stock_master_with_local_reservations')
    );

    RETURN jsonb_build_object(
      'contractVersion', 'inventory.v0',
      'reservationId', v_reservation_id,
      'reservationIds', jsonb_build_array(v_reservation_id),
      'locationId', v_location_id,
      'locationCode', v_location_code,
      'status', 'reserved',
      'stockAuthority', 'external_stock_master_with_local_reservations',
      'replayed', false
    );
  END IF;

  SELECT b.location_id, min(l.code)
    INTO v_location_id, v_location_code
    FROM public.inventory_balances b
    JOIN public.inventory_locations l ON l.id = b.location_id
    LEFT JOIN public.inventory_lots lot ON lot.id = b.lot_id
   WHERE b.sku_id = p_sku_id
     AND l.status = 'active'
     AND l.fulfillable = true
     AND (lot.id IS NULL OR (lot.status = 'available' AND (lot.expires_at IS NULL OR lot.expires_at > now())))
   GROUP BY b.location_id
  HAVING sum(greatest(
    0,
    b.on_hand
      - b.unavailable
      - b.safety_stock
      - coalesce((
          SELECT sum(r.quantity)
            FROM public.inventory_reservations r
           WHERE r.sku_id = b.sku_id
             AND r.location_id = b.location_id
             AND r.lot_id IS NOT DISTINCT FROM b.lot_id
             AND r.status = 'reserved'
             AND (r.expires_at IS NULL OR r.expires_at > now())
        ), 0)
  )) >= p_quantity
   ORDER BY min(l.code)
   LIMIT 1;

  IF v_location_id IS NULL THEN
    RAISE EXCEPTION 'inventory_reservation_insufficient_available_stock' USING ERRCODE = '23514';
  END IF;

  v_remaining := p_quantity;

  FOR v_balance IN
    SELECT b.*
    FROM public.inventory_balances b
    JOIN public.inventory_locations l ON l.id = b.location_id
    LEFT JOIN public.inventory_lots lot ON lot.id = b.lot_id
   WHERE b.sku_id = p_sku_id
     AND b.location_id = v_location_id
     AND l.status = 'active'
     AND l.fulfillable = true
     AND (lot.id IS NULL OR (lot.status = 'available' AND (lot.expires_at IS NULL OR lot.expires_at > now())))
   ORDER BY lot.expires_at NULLS LAST, l.code
   FOR UPDATE OF b
  LOOP
    EXIT WHEN v_remaining <= 0;

    SELECT coalesce(sum(r.quantity), 0)
      INTO v_active_reserved
      FROM public.inventory_reservations r
     WHERE r.sku_id = v_balance.sku_id
       AND r.location_id = v_balance.location_id
       AND r.lot_id IS NOT DISTINCT FROM v_balance.lot_id
       AND r.status = 'reserved'
       AND (r.expires_at IS NULL OR r.expires_at > now());

    v_allocate := least(
      v_remaining,
      greatest(0, v_balance.on_hand - v_active_reserved - v_balance.unavailable - v_balance.safety_stock)
    );
    CONTINUE WHEN v_allocate <= 0;

    INSERT INTO public.inventory_reservations (
      idempotency_key, order_id, order_item_id, subscription_cycle_id, sku_id,
      location_id, lot_id, quantity, kind, expires_at, metadata
    )
    VALUES (
      p_idempotency_key, p_order_id, p_order_item_id, p_subscription_cycle_id, p_sku_id,
      v_balance.location_id, v_balance.lot_id, v_allocate, p_kind,
      coalesce(
        p_expires_at,
        now() + CASE WHEN p_kind = 'subscription_retry_window' THEN interval '72 hours' ELSE interval '30 minutes' END
      ),
      coalesce(p_metadata, '{}'::jsonb)
    )
    RETURNING id INTO v_reservation_id;

    v_first_reservation_id := coalesce(v_first_reservation_id, v_reservation_id);
    v_reservation_ids := v_reservation_ids || to_jsonb(v_reservation_id);

    UPDATE public.inventory_balances
       SET reserved = reserved + v_allocate,
           updated_at = now()
     WHERE id = v_balance.id;

    INSERT INTO public.inventory_stock_movements (
      idempotency_key, movement_type, sku_id, location_id, lot_id, reservation_id,
      quantity_delta, reason, metadata
    )
    VALUES (
      p_idempotency_key || ':' || v_reservation_id::text, 'reservation_created',
      p_sku_id, v_balance.location_id, v_balance.lot_id, v_reservation_id,
      v_allocate, 'order_reserved', coalesce(p_metadata, '{}'::jsonb)
    );

    v_remaining := v_remaining - v_allocate;
  END LOOP;

  IF v_remaining <> 0 THEN
    RAISE EXCEPTION 'inventory_reservation_allocation_incomplete' USING ERRCODE = '23514';
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'inventory.v0',
    'reservationId', v_first_reservation_id,
    'reservationIds', v_reservation_ids,
    'locationId', v_location_id,
    'locationCode', v_location_code,
    'status', 'reserved',
    'replayed', false
  );
END;
$_$;


--
-- Name: FUNCTION inventory_reserve_order(p_idempotency_key text, p_order_id uuid, p_order_item_id uuid, p_subscription_cycle_id uuid, p_sku_id uuid, p_quantity integer, p_kind text, p_payment_status text, p_expires_at timestamp with time zone, p_metadata jsonb, p_provider_kind text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_reserve_order(p_idempotency_key text, p_order_id uuid, p_order_item_id uuid, p_subscription_cycle_id uuid, p_sku_id uuid, p_quantity integer, p_kind text, p_payment_status text, p_expires_at timestamp with time zone, p_metadata jsonb, p_provider_kind text) IS 'Reserves inventory using active lease semantics: only reserved rows with expires_at NULL or expires_at in the future block new reservations.';


--
-- Name: inventory_reserve_order_items(text, uuid, uuid, jsonb, text, text, timestamp with time zone, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_reserve_order_items(p_idempotency_key text, p_order_id uuid, p_subscription_cycle_id uuid, p_items jsonb, p_kind text, p_payment_status text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb, p_provider_kind text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_item jsonb;
  v_order_item_id uuid;
  v_sku_id uuid;
  v_quantity integer;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'inventory_reservation_items_invalid' USING ERRCODE = '22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_order_item_id := (v_item->>'orderItemId')::uuid;
    v_sku_id := (v_item->>'skuId')::uuid;
    v_quantity := (v_item->>'quantity')::integer;

    IF v_order_item_id IS NULL OR v_sku_id IS NULL OR v_quantity IS NULL OR v_quantity <= 0 THEN
      RAISE EXCEPTION 'inventory_reservation_item_invalid' USING ERRCODE = '22023';
    END IF;

    v_result := public.inventory_reserve_order(
      p_idempotency_key || ':' || v_order_item_id::text,
      p_order_id,
      v_order_item_id,
      p_subscription_cycle_id,
      v_sku_id,
      v_quantity,
      p_kind,
      p_payment_status,
      p_expires_at,
      p_metadata,
      p_provider_kind
    ) || jsonb_build_object('orderItemId', v_order_item_id::text);

    v_results := v_results || jsonb_build_array(v_result);
  END LOOP;

  RETURN jsonb_build_object(
    'contractVersion', 'inventory.v0',
    'status', 'reserved',
    'reservations', v_results,
    'replayed', false
  );
END;
$$;


--
-- Name: FUNCTION inventory_reserve_order_items(p_idempotency_key text, p_order_id uuid, p_subscription_cycle_id uuid, p_items jsonb, p_kind text, p_payment_status text, p_expires_at timestamp with time zone, p_metadata jsonb, p_provider_kind text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.inventory_reserve_order_items(p_idempotency_key text, p_order_id uuid, p_subscription_cycle_id uuid, p_items jsonb, p_kind text, p_payment_status text, p_expires_at timestamp with time zone, p_metadata jsonb, p_provider_kind text) IS 'Atomically reserves all checkout order items in one SQL transaction; any line failure rolls back the full order reservation batch.';


--
-- Name: is_admin_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin_user() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.admin_users
    WHERE admin_users.id = auth.uid()
      AND admin_users.membership_state = 'active'
      AND COALESCE(admin_users.role, 'admin') = 'admin'
  );
$$;


--
-- Name: mark_back_in_stock_notification_notified(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_back_in_stock_notification_notified(p_outbox_event_id uuid, p_notification_id uuid DEFAULT NULL::uuid, p_consent_decision_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_updated boolean := false;
BEGIN
  IF p_outbox_event_id IS NULL THEN
    RAISE EXCEPTION 'back_in_stock_outbox_event_id_required' USING ERRCODE = '22023';
  END IF;

  UPDATE public.commerce_product_stock_notifications
     SET notified_at = coalesce(notified_at, now()),
         closed_at = coalesce(closed_at, now()),
         closed_reason = coalesce(closed_reason, 'notified'),
         outbox_event_id = coalesce(outbox_event_id, p_outbox_event_id),
         consent_decision_id = coalesce(p_consent_decision_id, consent_decision_id),
         metadata = metadata || jsonb_build_object(
           'closedBy', 'outbox-dispatch',
           'notifiedBy', 'outbox-dispatch',
           'notifiedOutboxEventId', p_outbox_event_id)
   WHERE closed_at IS NULL
     AND (
       outbox_event_id = p_outbox_event_id
       OR (
         p_notification_id IS NOT NULL
         AND id = p_notification_id
         AND (outbox_event_id IS NULL OR outbox_event_id = p_outbox_event_id)
       )
     )
   RETURNING true INTO v_updated;

  IF coalesce(v_updated, false) THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
      FROM public.commerce_product_stock_notifications
     WHERE closed_at IS NOT NULL
       AND closed_reason = 'notified'
       AND (
         outbox_event_id = p_outbox_event_id
         OR (
           p_notification_id IS NOT NULL
           AND id = p_notification_id
           AND (outbox_event_id IS NULL OR outbox_event_id = p_outbox_event_id)
         )
       )
  );
END;
$$;


--
-- Name: marketing_rehome_client_lead_v1(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.marketing_rehome_client_lead_v1(p_client_id uuid, p_now timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_client public.clients%ROWTYPE;
  v_now timestamptz := COALESCE(p_now, now());
  v_email text;
  v_contact_id uuid;
  v_placeholder text;
  v_existing_marketing_client_id uuid;
  v_reference record;
  v_present boolean;
  v_blocking text[] := ARRAY[]::text[];
  v_unclassified text[] := ARRAY[]::text[];
BEGIN
  IF p_client_id IS NULL THEN
    RAISE EXCEPTION 'marketing_rehome_client_lead_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_client
    FROM public.clients AS client_row
   WHERE client_row.id = p_client_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'outcome', 'refused',
      'refusalCode', 'client_not_found',
      'clientId', p_client_id
    );
  END IF;

  IF v_client.identity_kind = 'marketing_lead' THEN
    RETURN jsonb_build_object(
      'outcome', 'noop',
      'clientId', p_client_id,
      'contactId', v_client.marketing_contact_id
    );
  END IF;

  IF v_client.acquisition_source IS DISTINCT FROM 'hidden_configurator' THEN
    RETURN jsonb_build_object(
      'outcome', 'refused',
      'refusalCode', 'not_hidden_configurator',
      'clientId', p_client_id
    );
  END IF;

  IF v_client.auth_user_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'outcome', 'refused',
      'refusalCode', 'client_has_identity',
      'clientId', p_client_id
    );
  END IF;

  FOR v_reference IN
    SELECT referencing.relname::text AS table_name,
           local_column.attname::text AS column_name,
           policy_row.disposition
      FROM pg_catalog.pg_constraint AS fk
      JOIN pg_catalog.pg_class AS referencing ON referencing.oid = fk.conrelid
      JOIN pg_catalog.pg_namespace AS referencing_schema
        ON referencing_schema.oid = referencing.relnamespace
      CROSS JOIN LATERAL unnest(fk.conkey, fk.confkey)
        AS key_pair(local_attnum, remote_attnum)
      JOIN pg_catalog.pg_attribute AS local_column
        ON local_column.attrelid = fk.conrelid
       AND local_column.attnum = key_pair.local_attnum
      JOIN pg_catalog.pg_attribute AS remote_column
        ON remote_column.attrelid = fk.confrelid
       AND remote_column.attnum = key_pair.remote_attnum
      LEFT JOIN public.client_absorption_policy AS policy_row
        ON policy_row.table_name = referencing.relname
     WHERE fk.contype = 'f'
       AND fk.confrelid = 'public.clients'::regclass
       AND referencing_schema.nspname = 'public'
       AND remote_column.attname = 'id'
     ORDER BY 1, 2
  LOOP
    IF v_reference.disposition IS NULL THEN
      IF NOT (v_reference.table_name = ANY (v_unclassified)) THEN
        v_unclassified := v_unclassified || v_reference.table_name;
      END IF;
    ELSIF v_reference.disposition = 'block' THEN
      EXECUTE format(
        'SELECT EXISTS (SELECT 1 FROM public.%I AS referenced_row WHERE referenced_row.%I = $1)',
        v_reference.table_name,
        v_reference.column_name
      ) INTO v_present USING p_client_id;
      IF v_present AND NOT (v_reference.table_name = ANY (v_blocking)) THEN
        v_blocking := v_blocking || v_reference.table_name;
      END IF;
    END IF;
  END LOOP;

  IF array_length(v_unclassified, 1) IS NOT NULL THEN
    RETURN jsonb_build_object(
      'outcome', 'refused',
      'refusalCode', 'unclassified_referencing_table',
      'clientId', p_client_id,
      'blockingTables', to_jsonb(v_unclassified)
    );
  END IF;

  IF array_length(v_blocking, 1) IS NOT NULL THEN
    RETURN jsonb_build_object(
      'outcome', 'refused',
      'refusalCode', 'client_has_customer_footprint',
      'clientId', p_client_id,
      'blockingTables', to_jsonb(v_blocking)
    );
  END IF;

  v_email := lower(btrim(COALESCE(v_client.email, '')));
  IF char_length(v_email) NOT BETWEEN 3 AND 320
     OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
  THEN
    RETURN jsonb_build_object(
      'outcome', 'refused',
      'refusalCode', 'client_email_invalid',
      'clientId', p_client_id
    );
  END IF;

  INSERT INTO public.communication_contacts (
    normalized_email, display_email, first_name, last_name, metadata, updated_at
  ) VALUES (
    v_email,
    btrim(v_client.email),
    v_client.first_name,
    v_client.last_name,
    jsonb_build_object(
      'source', 'personalization_lead_namespace_backfill',
      'legacyClientId', p_client_id
    ),
    v_now
  )
  ON CONFLICT (normalized_email) DO UPDATE
    SET updated_at = EXCLUDED.updated_at,
        first_name = COALESCE(public.communication_contacts.first_name, EXCLUDED.first_name),
        last_name = COALESCE(public.communication_contacts.last_name, EXCLUDED.last_name),
        metadata = public.communication_contacts.metadata || EXCLUDED.metadata
  RETURNING id INTO v_contact_id;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'personalization-marketing-contact:' || v_contact_id::text,
      0
    )
  );

  SELECT client_row.id
    INTO v_existing_marketing_client_id
    FROM public.clients AS client_row
   WHERE client_row.identity_kind = 'marketing_lead'
     AND client_row.marketing_contact_id = v_contact_id
     AND client_row.id <> p_client_id
   LIMIT 1;

  IF v_existing_marketing_client_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'outcome', 'refused',
      'refusalCode', 'marketing_contact_already_linked',
      'clientId', p_client_id,
      'existingClientId', v_existing_marketing_client_id
    );
  END IF;

  INSERT INTO public.communication_contact_links (
    contact_id, source_system, source_table, source_id, metadata
  ) VALUES (
    v_contact_id,
    'platform',
    'clients',
    p_client_id,
    jsonb_build_object('identityKind', 'marketing_lead')
  )
  ON CONFLICT (source_system, source_table, source_id)
    WHERE source_id IS NOT NULL
  DO UPDATE
    SET contact_id = EXCLUDED.contact_id,
        metadata = public.communication_contact_links.metadata || EXCLUDED.metadata;

  v_placeholder := 'lead+' || replace(p_client_id::text, '-', '') || '@marketing.invalid';

  UPDATE public.clients AS client_row
     SET email = v_placeholder,
         identity_kind = 'marketing_lead',
         marketing_contact_id = v_contact_id,
         updated_at = v_now,
         metadata = client_row.metadata || jsonb_build_object(
           'marketingLeadNamespace', jsonb_build_object(
             'contactId', v_contact_id,
             'rehomedAt', to_char(v_now AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
             'source', 'personalization_lead'
           )
         )
   WHERE client_row.id = p_client_id;

  RETURN jsonb_build_object(
    'outcome', 'applied',
    'clientId', p_client_id,
    'contactId', v_contact_id
  );
END;
$_$;


--
-- Name: FUNCTION marketing_rehome_client_lead_v1(p_client_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.marketing_rehome_client_lead_v1(p_client_id uuid, p_now timestamp with time zone) IS 'Fail-closed, idempotent separation of one hidden-configurator marketing-only client shell: the real email moves to communication_contacts, the compatibility UUID keeps its attached personalization/history, and the clients row receives a reserved .invalid address. Refuses Auth, commercial footprint and any unclassified clients FK.';


--
-- Name: mcp_authenticate_access_token(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_authenticate_access_token(p_token_hash text, p_environment text) RETURNS TABLE(token_id uuid, owner_email text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF p_token_hash !~ '^[0-9a-f]{64}$'
     OR p_environment NOT IN ('local', 'staging', 'production') THEN
    RETURN;
  END IF;

  RETURN QUERY
  UPDATE private.mcp_access_tokens AS token
     SET last_used_at = clock_timestamp()
   WHERE token.token_hash = p_token_hash
     AND token.environment = p_environment
     AND token.revoked_at IS NULL
     AND token.expires_at > clock_timestamp()
  RETURNING token.id, token.owner_email, token.expires_at;
END;
$_$;


--
-- Name: mcp_record_access_event(uuid, text, text, text, text, integer, integer, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mcp_record_access_event(p_token_id uuid, p_environment text, p_tool_name text, p_request_id text, p_status text, p_duration_ms integer, p_row_count integer DEFAULT NULL::integer, p_truncated boolean DEFAULT false, p_query_hash text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM private.mcp_access_tokens AS token
     WHERE token.id = p_token_id
       AND token.environment = p_environment
  ) THEN
    RAISE EXCEPTION 'mcp_token_environment_mismatch' USING ERRCODE = '42501';
  END IF;

  INSERT INTO private.mcp_access_events (
    token_id,
    environment,
    tool_name,
    request_id,
    status,
    duration_ms,
    row_count,
    truncated,
    query_hash,
    error_code
  ) VALUES (
    p_token_id,
    p_environment,
    p_tool_name,
    p_request_id,
    p_status,
    p_duration_ms,
    p_row_count,
    COALESCE(p_truncated, false),
    p_query_hash,
    p_error_code
  );
END;
$$;


--
-- Name: omnipack_acknowledge_dispatch_acceptance(uuid, text, text, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_acknowledge_dispatch_acceptance(p_dispatch_ref_id uuid, p_provider_order_id text, p_provider_attempt_idempotency_key text, p_label_idempotency_key text, p_sanitized_request jsonb, p_sanitized_response jsonb, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_ref public.omnipack_dispatch_refs%ROWTYPE;
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_attempt public.commerce_fulfillment_provider_attempts%ROWTYPE;
  v_label_attempt public.commerce_fulfillment_provider_attempts%ROWTYPE;
  v_provider_order_id text;
  v_attempt_provider_order_id text;
  v_label_provider_order_id text;
  v_changed boolean := false;
BEGIN
  IF p_dispatch_ref_id IS NULL
    OR p_provider_attempt_idempotency_key IS NULL
    OR length(btrim(p_provider_attempt_idempotency_key)) < 8
    OR p_label_idempotency_key IS NULL
    OR length(btrim(p_label_idempotency_key)) < 8
    OR btrim(p_provider_attempt_idempotency_key) = btrim(p_label_idempotency_key)
  THEN
    RAISE EXCEPTION 'omnipack_dispatch_ack_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ref FROM public.omnipack_dispatch_refs WHERE id = p_dispatch_ref_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'omnipack_dispatch_ref_not_found' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'omnipack-dispatch|' || v_ref.fulfillment_order_id::text,
    0
  ));
  SELECT * INTO v_ref
    FROM public.omnipack_dispatch_refs
   WHERE id = p_dispatch_ref_id
   FOR UPDATE;

  IF EXISTS (
    SELECT 1 FROM public.omnipack_dispatch_refs AS other_ref
     WHERE other_ref.fulfillment_order_id = v_ref.fulfillment_order_id
       AND other_ref.id <> v_ref.id
  ) THEN
    RAISE EXCEPTION 'omnipack_dispatch_ref_fulfillment_conflict' USING ERRCODE = '23505';
  END IF;

  v_provider_order_id := coalesce(
    NULLIF(btrim(coalesce(p_provider_order_id, '')), ''),
    v_ref.provider_order_id
  );
  IF v_provider_order_id IS NULL THEN
    RAISE EXCEPTION 'omnipack_dispatch_ack_provider_order_required' USING ERRCODE = '22023';
  END IF;
  IF v_ref.status NOT IN ('submitting', 'uncertain', 'created') THEN
    RAISE EXCEPTION 'omnipack_dispatch_ack_invalid_status' USING ERRCODE = '22023';
  END IF;
  IF v_ref.provider_order_id IS NOT NULL
    AND v_ref.provider_order_id IS DISTINCT FROM v_provider_order_id
  THEN
    RAISE EXCEPTION 'omnipack_dispatch_provider_order_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = v_ref.fulfillment_order_id
   FOR UPDATE;
  IF NOT FOUND OR v_fulfillment.order_id IS DISTINCT FROM v_ref.order_id THEN
    RAISE EXCEPTION 'omnipack_dispatch_fulfillment_mismatch' USING ERRCODE = '22023';
  END IF;
  IF v_fulfillment.provider_kind IS NOT NULL
    AND lower(btrim(v_fulfillment.provider_kind)) <> 'omnipack'
  THEN
    RAISE EXCEPTION 'omnipack_dispatch_fulfillment_provider_conflict' USING ERRCODE = '23505';
  END IF;

  -- Validate deterministic replay keys before composing the existing RPCs.
  SELECT * INTO v_attempt
    FROM public.commerce_fulfillment_provider_attempts
   WHERE idempotency_key = btrim(p_provider_attempt_idempotency_key)
   FOR UPDATE;
  IF FOUND THEN
    v_attempt_provider_order_id := coalesce(
      NULLIF(v_attempt.response_payload->>'providerOrderId', ''),
      NULLIF(v_attempt.metadata->>'providerOrderId', '')
    );
    IF v_attempt.fulfillment_order_id IS DISTINCT FROM v_ref.fulfillment_order_id
      OR v_attempt.order_id IS DISTINCT FROM v_ref.order_id
      OR v_attempt.provider_kind IS DISTINCT FROM 'omnipack'
      OR v_attempt.status IS DISTINCT FROM 'succeeded'
      OR (
        v_attempt_provider_order_id IS NOT NULL
        AND v_attempt_provider_order_id IS DISTINCT FROM v_provider_order_id
      )
    THEN
      RAISE EXCEPTION 'omnipack_dispatch_provider_attempt_conflict' USING ERRCODE = '23505';
    END IF;
  ELSE
    PERFORM public.commerce_fulfillment_record_provider_attempt(
      btrim(p_provider_attempt_idempotency_key),
      v_ref.fulfillment_order_id,
      'omnipack',
      'succeeded',
      coalesce(p_sanitized_request, v_ref.sanitized_request, '{}'::jsonb),
      coalesce(p_sanitized_response, v_ref.sanitized_response, '{}'::jsonb)
        || jsonb_build_object('providerOrderId', v_provider_order_id),
      NULL,
      NULL,
      coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
        'dispatchRefId', v_ref.id,
        'providerOrderId', v_provider_order_id,
        'evidenceKind', 'provider_acceptance'
      )
    );
    v_changed := true;
  END IF;

  SELECT * INTO v_label_attempt
    FROM public.commerce_fulfillment_provider_attempts
   WHERE idempotency_key = btrim(p_label_idempotency_key)
   FOR UPDATE;
  IF FOUND THEN
    v_label_provider_order_id := NULLIF(v_label_attempt.metadata->>'providerOrderId', '');
    IF v_label_attempt.fulfillment_order_id IS DISTINCT FROM v_ref.fulfillment_order_id
      OR v_label_attempt.order_id IS DISTINCT FROM v_ref.order_id
      OR v_label_attempt.provider_kind IS DISTINCT FROM 'omnipack'
      OR v_label_attempt.status IS DISTINCT FROM 'succeeded'
      OR (
        v_label_provider_order_id IS NOT NULL
        AND v_label_provider_order_id IS DISTINCT FROM v_provider_order_id
      )
    THEN
      RAISE EXCEPTION 'omnipack_dispatch_label_ack_conflict' USING ERRCODE = '23505';
    END IF;
  END IF;

  IF v_fulfillment.status IN ('created', 'label_pending') THEN
    IF v_label_attempt.id IS NULL THEN
      PERFORM public.commerce_fulfillment_record_label_created(
        btrim(p_label_idempotency_key),
        v_ref.fulfillment_order_id,
        'omnipack',
        NULL,
        NULL,
        NULL,
        coalesce(p_sanitized_response, v_ref.sanitized_response, '{}'::jsonb),
        NULL,
        coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
          'dispatchRefId', v_ref.id,
          'providerOrderId', v_provider_order_id,
          'evidenceKind', 'dispatch_label_ack'
        )
      );
      v_changed := true;
    END IF;
    SELECT * INTO v_fulfillment
      FROM public.commerce_fulfillment_orders
     WHERE id = v_ref.fulfillment_order_id;
    IF v_fulfillment.status IS DISTINCT FROM 'label_created' THEN
      RAISE EXCEPTION 'omnipack_dispatch_label_ack_state_conflict' USING ERRCODE = '23505';
    END IF;
  ELSIF v_fulfillment.status NOT IN (
    'label_created', 'packed', 'handed_over', 'in_transit', 'delivered'
  ) THEN
    RAISE EXCEPTION 'omnipack_dispatch_label_ack_invalid_fulfillment_status'
      USING ERRCODE = '22023';
  END IF;

  IF v_ref.status IS DISTINCT FROM 'created'
    OR v_ref.provider_order_id IS DISTINCT FROM v_provider_order_id
  THEN
    v_changed := true;
  END IF;
  UPDATE public.omnipack_dispatch_refs
     SET status = 'created',
         provider_order_id = v_provider_order_id,
         sanitized_request = CASE
           WHEN p_sanitized_request IS NULL OR p_sanitized_request = '{}'::jsonb
             THEN sanitized_request
           ELSE p_sanitized_request
         END,
         sanitized_response = CASE
           WHEN p_sanitized_response IS NULL OR p_sanitized_response = '{}'::jsonb
             THEN sanitized_response
           ELSE p_sanitized_response
         END,
         error = '{}'::jsonb,
         updated_at = CASE WHEN v_changed THEN now() ELSE updated_at END
   WHERE id = v_ref.id
   RETURNING * INTO v_ref;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.evidence.v1',
    'dispatchRefId', v_ref.id,
    'fulfillmentOrderId', v_ref.fulfillment_order_id,
    'orderId', v_ref.order_id,
    'providerOrderId', v_ref.provider_order_id,
    'dispatchStatus', v_ref.status,
    'fulfillmentStatus', v_fulfillment.status,
    'replayed', NOT v_changed
  );
END;
$$;


--
-- Name: FUNCTION omnipack_acknowledge_dispatch_acceptance(p_dispatch_ref_id uuid, p_provider_order_id text, p_provider_attempt_idempotency_key text, p_label_idempotency_key text, p_sanitized_request jsonb, p_sanitized_response jsonb, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.omnipack_acknowledge_dispatch_acceptance(p_dispatch_ref_id uuid, p_provider_order_id text, p_provider_attempt_idempotency_key text, p_label_idempotency_key text, p_sanitized_request jsonb, p_sanitized_response jsonb, p_metadata jsonb) IS 'Atomically records OmniPack acceptance and the existing label-created operation without mutating historical provider-command evidence.';


--
-- Name: omnipack_begin_direct_dispatch_submission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_begin_direct_dispatch_submission(p_dispatch_ref_id uuid, p_request_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_ref public.omnipack_dispatch_refs%ROWTYPE;
  v_other_ref public.omnipack_dispatch_refs%ROWTYPE;
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_selected_provider text;
  v_ineligible_reason text;
  v_ref_revision integer;
  v_current_revision integer;
BEGIN
  IF p_dispatch_ref_id IS NULL
    OR p_request_fingerprint IS NULL OR btrim(p_request_fingerprint) = ''
  THEN
    RAISE EXCEPTION 'omnipack_dispatch_begin_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ref FROM public.omnipack_dispatch_refs WHERE id = p_dispatch_ref_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'omnipack_dispatch_ref_not_found' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'omnipack-dispatch|' || v_ref.fulfillment_order_id::text,
    0
  ));
  SELECT * INTO v_ref
    FROM public.omnipack_dispatch_refs
   WHERE id = p_dispatch_ref_id
   FOR UPDATE;

  IF v_ref.request_fingerprint IS DISTINCT FROM p_request_fingerprint THEN
    RAISE EXCEPTION 'omnipack_dispatch_request_fingerprint_conflict' USING ERRCODE = '23505';
  END IF;

  IF v_ref.status IS DISTINCT FROM 'draft' THEN
    RETURN jsonb_build_object(
      'contractVersion', 'omnipack.evidence.v1',
      'dispatchRefId', v_ref.id,
      'fulfillmentOrderId', v_ref.fulfillment_order_id,
      'orderId', v_ref.order_id,
      'providerOrderId', v_ref.provider_order_id,
      'dispatchMode', v_ref.dispatch_mode,
      'sanitizedRequest', v_ref.sanitized_request,
      'status', v_ref.status,
      'requestIdempotencyKey', v_ref.request_idempotency_key,
      'begun', false,
      'replayed', true
    );
  END IF;

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = v_ref.fulfillment_order_id
   FOR UPDATE;
  IF v_fulfillment.id IS NULL OR v_fulfillment.order_id IS DISTINCT FROM v_ref.order_id THEN
    v_ineligible_reason := 'fulfillment_missing_or_mismatched';
  ELSE
    -- A ref recorded without a stated contact revision carries no expectation to
    -- compare against, so this fence has nothing to say about it. Tolerating that
    -- here is not optional once the recorder tolerates it: a `contact_stale`
    -- return the worker can never satisfy -- the still-deployed caller re-records
    -- the same ref without a revision -- would just move the same window outage
    -- one function later, and the worker's single remap then throws.
    IF coalesce(v_ref.sanitized_request, '{}'::jsonb) ? 'deliveryContactRevision' THEN
      IF coalesce(v_ref.sanitized_request->>'deliveryContactRevision', '') !~ '^[1-9][0-9]*$'
        OR coalesce(v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,revision}', '') !~ '^[1-9][0-9]*$'
      THEN
        RETURN jsonb_build_object(
          'contractVersion', 'omnipack.evidence.v1',
          'retryableReason', 'omnipack_dispatch_contact_stale'
        );
      END IF;
      v_ref_revision := (v_ref.sanitized_request->>'deliveryContactRevision')::integer;
      v_current_revision := (v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,revision}')::integer;
      IF v_ref_revision IS DISTINCT FROM v_current_revision THEN
        RETURN jsonb_build_object(
          'contractVersion', 'omnipack.evidence.v1',
          'retryableReason', 'omnipack_dispatch_contact_stale'
        );
      END IF;
    END IF;
  END IF;

  IF v_ref.dispatch_mode = 'shadow' THEN
    v_ineligible_reason := 'shadow_dispatch';
  ELSIF v_ref.provider_order_id IS NOT NULL THEN
    v_ineligible_reason := 'provider_proof_requires_acknowledgement';
  END IF;

  IF v_ineligible_reason IS NULL THEN
    SELECT * INTO v_other_ref
      FROM public.omnipack_dispatch_refs
     WHERE fulfillment_order_id = v_ref.fulfillment_order_id
       AND id <> v_ref.id
     ORDER BY id
     LIMIT 1
     FOR UPDATE;
    IF FOUND THEN
      v_ineligible_reason := 'other_dispatch_ref_exists';
    END IF;
  END IF;

  IF v_ineligible_reason IS NULL AND EXISTS (
    SELECT 1 FROM public.commerce_fulfillment_provider_attempts AS attempt
     WHERE attempt.fulfillment_order_id = v_ref.fulfillment_order_id
       AND attempt.provider_kind = 'omnipack'
       AND attempt.status = 'succeeded'
  ) THEN
    v_ineligible_reason := 'succeeded_provider_attempt_exists';
  END IF;

  IF v_ineligible_reason IS NULL THEN
    SELECT * INTO v_order
      FROM public.commerce_orders
     WHERE id = v_ref.order_id
     FOR UPDATE;

    IF v_order.id IS NULL THEN
      v_ineligible_reason := 'order_missing';
    ELSE
      v_selected_provider := lower(btrim(
        v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,selectedDelivery,providerKind}'
      ));

      IF v_fulfillment.status NOT IN ('created', 'label_pending') THEN
        v_ineligible_reason := 'fulfillment_status_stale';
      ELSIF v_order.status NOT IN ('paid', 'fulfillment_pending') THEN
        v_ineligible_reason := 'order_status_stale';
      ELSIF EXISTS (
        SELECT 1 FROM public.commerce_order_holds AS hold
         WHERE hold.order_id = v_order.id AND hold.status = 'active'
      ) THEN
        v_ineligible_reason := 'active_order_hold';
      ELSIF (
        v_fulfillment.provider_kind IS NOT NULL
        AND lower(btrim(v_fulfillment.provider_kind)) <> 'omnipack'
      ) OR v_selected_provider IS DISTINCT FROM 'omnipack' THEN
        v_ineligible_reason := 'provider_selection_stale';
      END IF;
    END IF;
  END IF;

  IF v_ineligible_reason IS NOT NULL THEN
    RETURN jsonb_build_object(
      'contractVersion', 'omnipack.evidence.v1',
      'dispatchRefId', v_ref.id,
      'fulfillmentOrderId', v_ref.fulfillment_order_id,
      'orderId', v_ref.order_id,
      'providerOrderId', v_ref.provider_order_id,
      'dispatchMode', v_ref.dispatch_mode,
      'sanitizedRequest', v_ref.sanitized_request,
      'status', v_ref.status,
      'requestIdempotencyKey', v_ref.request_idempotency_key,
      'begun', false,
      'replayed', true,
      'ineligibleReason', v_ineligible_reason
    );
  END IF;

  UPDATE public.omnipack_dispatch_refs
     SET status = 'submitting', error = '{}'::jsonb, updated_at = now()
   WHERE id = v_ref.id;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.evidence.v1',
    'dispatchRefId', v_ref.id,
    'fulfillmentOrderId', v_ref.fulfillment_order_id,
    'orderId', v_ref.order_id,
    'providerOrderId', v_ref.provider_order_id,
    'dispatchMode', v_ref.dispatch_mode,
    'sanitizedRequest', v_ref.sanitized_request,
    'status', 'submitting',
    'requestIdempotencyKey', v_ref.request_idempotency_key,
    'begun', true,
    'replayed', false
  );
END;
$_$;


--
-- Name: FUNCTION omnipack_begin_direct_dispatch_submission(p_dispatch_ref_id uuid, p_request_fingerprint text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.omnipack_begin_direct_dispatch_submission(p_dispatch_ref_id uuid, p_request_fingerprint text) IS 'Final locked pre-effect fence: rechecks the recorded delivery-contact revision before draft becomes submitting.';


--
-- Name: omnipack_begin_dispatch_submission(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_begin_dispatch_submission(p_dispatch_ref_id uuid, p_request_fingerprint text, p_authority_mode text DEFAULT 'legacy'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_authority_mode IS NULL
    OR p_authority_mode NOT IN ('legacy', 'observe', 'provider_command')
  THEN
    RAISE EXCEPTION 'omnipack_dispatch_begin_invalid_input' USING ERRCODE = '22023';
  END IF;

  RETURN public.omnipack_begin_direct_dispatch_submission(
    p_dispatch_ref_id,
    p_request_fingerprint
  );
END;
$$;


--
-- Name: FUNCTION omnipack_begin_dispatch_submission(p_dispatch_ref_id uuid, p_request_fingerprint text, p_authority_mode text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.omnipack_begin_dispatch_submission(p_dispatch_ref_id uuid, p_request_fingerprint text, p_authority_mode text) IS 'Rolling-deploy compatibility wrapper for the direct begin fence. The authority argument is validated but cannot select or mutate the historical provider-command rail.';


--
-- Name: omnipack_dispatch_candidate_ids(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_dispatch_candidate_ids(p_limit integer DEFAULT 25) RETURNS TABLE(fulfillment_order_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_candidate record;
  v_preparation jsonb;
BEGIN
  FOR v_candidate IN
    SELECT fulfillment.id AS id,
      (
        latest_ref.provider_order_id IS NOT NULL
        AND latest_ref.dispatch_mode IN ('stage', 'live')
        AND latest_ref.status IN ('created', 'uncertain')
      ) AS provider_proof
    FROM public.commerce_fulfillment_orders AS fulfillment
    JOIN public.commerce_orders AS order_row
      ON order_row.id = fulfillment.order_id
    LEFT JOIN public.addresses AS address_row
      ON address_row.id = fulfillment.shipping_address_id
     AND address_row.client_id = fulfillment.client_id
    LEFT JOIN public.clients AS client_row
      ON client_row.id = fulfillment.client_id
    CROSS JOIN LATERAL (
      SELECT lower(btrim(CASE
        WHEN jsonb_typeof(fulfillment.metadata->'selectedDelivery') = 'object'
          THEN fulfillment.metadata #>> '{selectedDelivery,providerKind}'
        WHEN jsonb_typeof(order_row.metadata->'selectedDelivery') = 'object'
          THEN order_row.metadata #>> '{selectedDelivery,providerKind}'
        WHEN jsonb_typeof(order_row.metadata #> '{runtimeFinalize,selectedDelivery}') = 'object'
          THEN order_row.metadata #>> '{runtimeFinalize,selectedDelivery,providerKind}'
        WHEN jsonb_typeof(fulfillment.shipping_address_snapshot->'selectedDelivery') = 'object'
          THEN fulfillment.shipping_address_snapshot #>> '{selectedDelivery,providerKind}'
        WHEN jsonb_typeof(address_row.metadata->'selectedDelivery') = 'object'
          THEN address_row.metadata #>> '{selectedDelivery,providerKind}'
        ELSE NULL
      END)) AS provider_kind
    ) AS selection
    CROSS JOIN LATERAL private.commerce_delivery_contact_resolve_v1(jsonb_build_object(
      'frozenContactPresent', coalesce(fulfillment.shipping_address_snapshot, '{}'::jsonb) ? 'deliveryContact',
      'frozenContact', fulfillment.shipping_address_snapshot->'deliveryContact',
      'orderCanonicalPresent',
        coalesce(order_row.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact'
        OR coalesce(order_row.metadata, '{}'::jsonb) ? 'deliveryContactOverride',
      'channelOrderSnapshot', order_row.metadata->'channelOrderSnapshot',
      'selectedDeliveryCandidates', jsonb_build_array(
        fulfillment.metadata->'selectedDelivery',
        order_row.metadata->'selectedDelivery',
        order_row.metadata #> '{runtimeFinalize,selectedDelivery}',
        fulfillment.shipping_address_snapshot->'selectedDelivery',
        address_row.metadata->'selectedDelivery'
      ),
      'recipientCandidates', jsonb_build_array(
        fulfillment.shipping_address_snapshot->>'recipientName',
        concat_ws(' ', client_row.first_name, client_row.last_name),
        fulfillment.shipping_address_snapshot->>'label'
      ),
      'phoneCandidates', jsonb_build_array(
        fulfillment.shipping_address_snapshot->>'contactPhone',
        address_row.contact_phone,
        client_row.phone
      ),
      'legacyClientEmail', client_row.email,
      'line1', fulfillment.shipping_address_snapshot->>'line1',
      'line2', fulfillment.shipping_address_snapshot->>'line2',
      'city', fulfillment.shipping_address_snapshot->>'city',
      'postalCode', fulfillment.shipping_address_snapshot->>'postalCode',
      'country', fulfillment.shipping_address_snapshot->>'country'
    )) AS contact_resolution
    LEFT JOIN LATERAL (
      SELECT ref.id, ref.status, ref.provider_order_id, ref.dispatch_mode
        FROM public.omnipack_dispatch_refs AS ref
       WHERE ref.fulfillment_order_id = fulfillment.id
       ORDER BY ref.created_at DESC, ref.id DESC
       LIMIT 1
    ) AS latest_ref ON true
   WHERE fulfillment.status IN ('created', 'label_pending')
     AND (
       fulfillment.provider_kind IS NULL
       OR lower(btrim(fulfillment.provider_kind)) = 'omnipack'
     )
     AND (
       -- Provider proof is recovery work, not a new payload.  It deliberately
       -- bypasses preparation so acknowledgement recovery cannot write or hide it.
       (
         latest_ref.provider_order_id IS NOT NULL
         AND latest_ref.dispatch_mode IN ('stage', 'live')
         AND latest_ref.status IN ('created', 'uncertain')
       )
       OR (
         selection.provider_kind = 'omnipack'
         AND order_row.status IN ('paid', 'fulfillment_pending')
         AND contact_resolution->>'disposition' IN ('frozen_complete', 'inferred_complete')
         AND EXISTS (
           SELECT 1 FROM public.commerce_payment_intents AS intent
            WHERE intent.order_id = order_row.id
              AND intent.status = 'succeeded'
         )
         AND NOT EXISTS (
           SELECT 1 FROM public.commerce_order_holds AS hold
            WHERE hold.order_id = order_row.id AND hold.status = 'active'
         )
         AND (
           latest_ref.id IS NULL
           OR (latest_ref.status = 'draft' AND latest_ref.provider_order_id IS NULL)
         )
       )
   )
   ORDER BY fulfillment.created_at ASC, fulfillment.id ASC
   LIMIT greatest(1, least(coalesce(p_limit, 25), 100))
  LOOP
    IF v_candidate.provider_proof THEN
      fulfillment_order_id := v_candidate.id;
      RETURN NEXT;
      CONTINUE;
    END IF;

    -- The old worker maps its payload before it records a ref.  Preparation is
    -- therefore intentionally inside selection: a ready legacy row is frozen
    -- under the same dispatch lock before that worker can reread profile data.
    -- `withheld` is quiet and does not write. The provisional resolver gate
    -- already excludes malformed, incomplete, and order-canonical-without-frozen
    -- rows, so one corrupt historical row cannot abort this whole queue pass.
    -- Direct correction/preparation paths retain their named structural fences.
    -- The gate above reads the enumeration cursor's snapshot, but
    -- `omnipack_prepare_dispatch_contact_v1` re-reads the latest committed row
    -- under FOR UPDATE. A commit landing between the two can turn a gated-in row
    -- into one of preparation's four 22023 raises, and an uncaught raise here
    -- aborts the whole selection: `listCandidates` has no try/catch, so the
    -- dispatch job would die before processing a single candidate. Withholding
    -- the one row is exactly what the gate does for every other unpreparable
    -- state, so a raise is treated the same way rather than failing the pass.
    BEGIN
      v_preparation := public.omnipack_prepare_dispatch_contact_v1(v_candidate.id);
    EXCEPTION
      -- Only preparation's own structural refusals; all four raise 22023.
      -- A lock timeout, cancellation or serialization failure still propagates,
      -- because those are not "this row is unpreparable" and must not be hidden.
      WHEN invalid_parameter_value THEN
        v_preparation := jsonb_build_object('disposition', 'withheld_prepare_failed');
    END;
    IF v_preparation->>'disposition' = 'ready' THEN
      fulfillment_order_id := v_candidate.id;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION omnipack_dispatch_candidate_ids(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.omnipack_dispatch_candidate_ids(p_limit integer) IS 'Selects eligible new dispatches plus provider-proof rows needing zero-POST local acknowledgement.';


--
-- Name: omnipack_finalize_dispatch_submission(uuid, boolean, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_finalize_dispatch_submission(p_dispatch_ref_id uuid, p_may_have_succeeded boolean, p_sanitized_response jsonb DEFAULT '{}'::jsonb, p_error jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_ref public.omnipack_dispatch_refs%ROWTYPE;
  v_target_status text;
  v_response_provider_order_id text;
  v_provider_order_id text;
BEGIN
  IF p_dispatch_ref_id IS NULL OR p_may_have_succeeded IS NULL
    OR jsonb_typeof(coalesce(p_sanitized_response, '{}'::jsonb)) <> 'object'
    OR jsonb_typeof(coalesce(p_error, '{}'::jsonb)) <> 'object'
  THEN
    RAISE EXCEPTION 'omnipack_dispatch_finalize_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_ref
    FROM public.omnipack_dispatch_refs
   WHERE id = p_dispatch_ref_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'omnipack_dispatch_ref_not_found' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'omnipack-dispatch|' || v_ref.fulfillment_order_id::text,
    0
  ));
  SELECT * INTO v_ref
    FROM public.omnipack_dispatch_refs
   WHERE id = p_dispatch_ref_id
   FOR UPDATE;

  v_target_status := CASE WHEN p_may_have_succeeded THEN 'uncertain' ELSE 'failed' END;
  v_response_provider_order_id := NULLIF(btrim(coalesce(
    p_sanitized_response->>'providerOrderId', ''
  )), '');
  IF v_ref.provider_order_id IS NOT NULL
    AND v_response_provider_order_id IS NOT NULL
    AND v_ref.provider_order_id IS DISTINCT FROM v_response_provider_order_id
  THEN
    RAISE EXCEPTION 'omnipack_dispatch_provider_order_conflict' USING ERRCODE = '23505';
  END IF;
  v_provider_order_id := coalesce(v_response_provider_order_id, v_ref.provider_order_id);
  IF NOT p_may_have_succeeded AND v_provider_order_id IS NOT NULL THEN
    RAISE EXCEPTION 'omnipack_dispatch_finalize_safe_failure_provider_proof_conflict'
      USING ERRCODE = '22023';
  END IF;

  IF v_ref.status = 'created' OR v_ref.status = v_target_status THEN
    RETURN jsonb_build_object(
      'dispatchRefId', v_ref.id,
      'fulfillmentOrderId', v_ref.fulfillment_order_id,
      'orderId', v_ref.order_id,
      'status', v_ref.status,
      'providerOrderId', v_ref.provider_order_id,
      'dispatchMode', v_ref.dispatch_mode,
      'requestIdempotencyKey', v_ref.request_idempotency_key,
      'sanitizedRequest', v_ref.sanitized_request,
      'applied', false,
      'replayed', true
    );
  END IF;
  IF v_ref.status IS DISTINCT FROM 'submitting' THEN
    RAISE EXCEPTION 'omnipack_dispatch_finalize_state_conflict'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.omnipack_dispatch_refs
     SET status = v_target_status,
         provider_order_id = v_provider_order_id,
         sanitized_response = CASE
           WHEN p_sanitized_response = '{}'::jsonb THEN sanitized_response
           ELSE p_sanitized_response
         END,
         error = coalesce(p_error, '{}'::jsonb),
         updated_at = now()
   WHERE id = v_ref.id
   RETURNING * INTO v_ref;

  RETURN jsonb_build_object(
    'dispatchRefId', v_ref.id,
    'fulfillmentOrderId', v_ref.fulfillment_order_id,
    'orderId', v_ref.order_id,
    'status', v_ref.status,
    'providerOrderId', v_ref.provider_order_id,
    'dispatchMode', v_ref.dispatch_mode,
    'requestIdempotencyKey', v_ref.request_idempotency_key,
    'sanitizedRequest', v_ref.sanitized_request,
    'applied', true,
    'replayed', false
  );
END;
$$;


--
-- Name: FUNCTION omnipack_finalize_dispatch_submission(p_dispatch_ref_id uuid, p_may_have_succeeded boolean, p_sanitized_response jsonb, p_error jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.omnipack_finalize_dispatch_submission(p_dispatch_ref_id uuid, p_may_have_succeeded boolean, p_sanitized_response jsonb, p_error jsonb) IS 'Classifies a submitting provider call as uncertain or safely failed. Neither state authorizes automatic retry.';


--
-- Name: omnipack_mark_stale_dispatch_submissions_uncertain(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_mark_stale_dispatch_submissions_uncertain(p_stale_before timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_marked integer;
BEGIN
  IF p_stale_before IS NULL OR p_stale_before > now() THEN
    RAISE EXCEPTION 'omnipack_dispatch_stale_before_invalid' USING ERRCODE = '22023';
  END IF;

  UPDATE public.omnipack_dispatch_refs
     SET status = 'uncertain',
         error = coalesce(error, '{}'::jsonb) || jsonb_build_object(
           'code', 'submission_outcome_uncertain',
           'markedUncertainAt', now()
         ),
         updated_at = now()
   WHERE status = 'submitting'
     AND updated_at < p_stale_before;
  GET DIAGNOSTICS v_marked = ROW_COUNT;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.evidence.v1',
    'markedUncertain', v_marked,
    'updatedCount', v_marked,
    'staleBefore', p_stale_before
  );
END;
$$;


--
-- Name: FUNCTION omnipack_mark_stale_dispatch_submissions_uncertain(p_stale_before timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.omnipack_mark_stale_dispatch_submissions_uncertain(p_stale_before timestamp with time zone) IS 'Moves stale submitting refs to uncertain so an ambiguous provider POST is never retried blindly.';


--
-- Name: omnipack_prepare_dispatch_contact_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_prepare_dispatch_contact_v1(p_fulfillment_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_address public.addresses%ROWTYPE;
  v_client public.clients%ROWTYPE;
  v_resolution jsonb;
  v_revision integer;
BEGIN
  IF p_fulfillment_order_id IS NULL THEN
    RAISE EXCEPTION 'omnipack_dispatch_ref_invalid_input' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'omnipack-dispatch|' || p_fulfillment_order_id::text, 0
  ));
  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'omnipack_dispatch_ref_fulfillment_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = v_fulfillment.order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'omnipack_dispatch_delivery_contact_missing' USING ERRCODE = '22023';
  END IF;
  PERFORM 1
    FROM public.omnipack_dispatch_refs
   WHERE fulfillment_order_id = v_fulfillment.id
   ORDER BY id
   FOR UPDATE;
  SELECT * INTO v_client FROM public.clients WHERE id = v_fulfillment.client_id;
  SELECT * INTO v_address FROM public.addresses WHERE id = v_fulfillment.shipping_address_id;

  v_resolution := private.commerce_delivery_contact_resolve_v1(jsonb_build_object(
    'frozenContactPresent', coalesce(v_fulfillment.shipping_address_snapshot, '{}'::jsonb) ? 'deliveryContact',
    'frozenContact', v_fulfillment.shipping_address_snapshot->'deliveryContact',
    'orderCanonicalPresent',
      coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact'
      OR coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride',
    'channelOrderSnapshot', v_order.metadata->'channelOrderSnapshot',
    'selectedDeliveryCandidates', jsonb_build_array(
      v_fulfillment.metadata->'selectedDelivery',
      v_order.metadata->'selectedDelivery',
      v_order.metadata #> '{runtimeFinalize,selectedDelivery}',
      v_fulfillment.shipping_address_snapshot->'selectedDelivery',
      v_address.metadata->'selectedDelivery'
    ),
    'recipientCandidates', jsonb_build_array(
      v_fulfillment.shipping_address_snapshot->>'recipientName',
      concat_ws(' ', v_client.first_name, v_client.last_name),
      v_fulfillment.shipping_address_snapshot->>'label'
    ),
    'phoneCandidates', jsonb_build_array(
      v_fulfillment.shipping_address_snapshot->>'contactPhone',
      v_address.contact_phone,
      v_client.phone
    ),
    'legacyClientEmail', v_client.email,
    'line1', v_fulfillment.shipping_address_snapshot->>'line1',
    'line2', NULL,
    'city', v_fulfillment.shipping_address_snapshot->>'city',
    'postalCode', v_fulfillment.shipping_address_snapshot->>'postalCode',
    'country', v_fulfillment.shipping_address_snapshot->>'country'
  ));

  IF v_resolution->>'disposition' IN (
    'frozen_malformed', 'frozen_incomplete', 'order_canonical_without_frozen'
  ) THEN
    RAISE EXCEPTION 'omnipack_dispatch_delivery_contact_missing' USING ERRCODE = '22023';
  END IF;
  IF v_resolution->>'disposition' = 'inferred_incomplete' THEN
    RETURN jsonb_build_object('disposition', 'withheld', 'deliveryContactRevision', NULL);
  END IF;

  v_revision := (v_resolution #>> '{contact,revision}')::integer;
  IF v_resolution->>'disposition' = 'inferred_complete' THEN
    UPDATE public.commerce_fulfillment_orders
       SET shipping_address_snapshot = shipping_address_snapshot || jsonb_build_object(
             'deliveryContact', v_resolution->'contact',
             'selectedDelivery', v_resolution #> '{contact,selectedDelivery}'
           ),
           updated_at = now()
     WHERE id = v_fulfillment.id;
  END IF;
  RETURN jsonb_build_object('disposition', 'ready', 'deliveryContactRevision', v_revision);
END;
$$;


--
-- Name: omnipack_record_dispatch_ref(text, uuid, text, text, text, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_record_dispatch_ref(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_order_id text, p_dispatch_mode text, p_status text, p_request_fingerprint text, p_sanitized_request jsonb DEFAULT '{}'::jsonb, p_sanitized_response jsonb DEFAULT '{}'::jsonb, p_error jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_dispatch_mode IN ('stage', 'live') THEN
    RAISE EXCEPTION 'omnipack_dispatch_ref_submission_fence_required'
      USING ERRCODE = '55000',
            HINT = 'Use omnipack_record_dispatch_ref_v2 and omnipack_begin_dispatch_submission.';
  END IF;

  RETURN public.omnipack_record_dispatch_ref_v2(
    p_idempotency_key, p_fulfillment_order_id, p_provider_order_id,
    p_dispatch_mode, p_status, p_request_fingerprint, p_sanitized_request,
    p_sanitized_response, p_error
  );
END;
$$;


--
-- Name: FUNCTION omnipack_record_dispatch_ref(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_order_id text, p_dispatch_mode text, p_status text, p_request_fingerprint text, p_sanitized_request jsonb, p_sanitized_response jsonb, p_error jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.omnipack_record_dispatch_ref(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_order_id text, p_dispatch_mode text, p_status text, p_request_fingerprint text, p_sanitized_request jsonb, p_sanitized_response jsonb, p_error jsonb) IS 'Rolling-deploy compatibility wrapper: shadow evidence only; executable modes fail before provider I/O.';


--
-- Name: omnipack_record_dispatch_ref_v2(text, uuid, text, text, text, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_record_dispatch_ref_v2(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_order_id text, p_dispatch_mode text, p_status text, p_request_fingerprint text, p_sanitized_request jsonb DEFAULT '{}'::jsonb, p_sanitized_response jsonb DEFAULT '{}'::jsonb, p_error jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_ref public.omnipack_dispatch_refs%ROWTYPE;
  v_replayed boolean := false;
  v_candidate_revision integer;
  v_current_revision integer;
  v_order public.commerce_orders%ROWTYPE;
  v_client public.clients%ROWTYPE;
  v_address public.addresses%ROWTYPE;
  v_legacy_contact jsonb;
  v_contact_resolution jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_fulfillment_order_id IS NULL
    OR p_dispatch_mode NOT IN ('shadow', 'stage', 'live')
    OR p_status IS DISTINCT FROM 'draft'
    OR NULLIF(btrim(coalesce(p_provider_order_id, '')), '') IS NOT NULL
    OR p_request_fingerprint IS NULL OR btrim(p_request_fingerprint) = ''
    OR jsonb_typeof(coalesce(p_sanitized_request, '{}'::jsonb)) <> 'object'
    -- An ABSENT revision means the caller states no opinion about the contact,
    -- which is precisely what the still-deployed worker sends between this
    -- migration applying and the code promote. Refusing it took every OmniPack
    -- dispatch down for that whole window. Production today performs no such
    -- check, so accepting the old caller for one release defers a strengthening
    -- instead of weakening anything; a key that IS present must still be well
    -- formed, and the fence below still runs whenever one was stated.
    OR (
      coalesce(p_sanitized_request, '{}'::jsonb) ? 'deliveryContactRevision'
      AND coalesce(p_sanitized_request->>'deliveryContactRevision', '') !~ '^[1-9][0-9]*$'
    )
  THEN
    RAISE EXCEPTION 'omnipack_dispatch_ref_invalid_input' USING ERRCODE = '22023';
  END IF;
  v_candidate_revision := (p_sanitized_request->>'deliveryContactRevision')::integer;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'omnipack-dispatch|' || p_fulfillment_order_id::text,
    0
  ));

  SELECT * INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'omnipack_dispatch_ref_fulfillment_not_found' USING ERRCODE = '22023';
  END IF;

  IF coalesce(v_fulfillment.shipping_address_snapshot, '{}'::jsonb) ? 'deliveryContact' THEN
    IF jsonb_typeof(v_fulfillment.shipping_address_snapshot->'deliveryContact') IS DISTINCT FROM 'object'
      OR v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,schemaVersion}' IS DISTINCT FROM '1'
      OR coalesce(v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,revision}', '') !~ '^[1-9][0-9]*$'
      OR nullif(btrim(v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,source}'), '') IS NULL
      OR nullif(btrim(v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,recipientName}'), '') IS NULL
      OR nullif(btrim(v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,contactPhone}'), '') IS NULL
      OR nullif(btrim(v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,line1}'), '') IS NULL
      OR nullif(btrim(v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,city}'), '') IS NULL
      OR nullif(btrim(v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,postalCode}'), '') IS NULL
      OR nullif(btrim(v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,country}'), '') IS NULL
    THEN
      RAISE EXCEPTION 'omnipack_dispatch_delivery_contact_missing' USING ERRCODE = '22023';
    END IF;
  ELSE
    PERFORM 1 FROM public.omnipack_dispatch_refs
     WHERE fulfillment_order_id = p_fulfillment_order_id
     ORDER BY id
     FOR UPDATE;
    IF EXISTS (
      SELECT 1 FROM public.omnipack_dispatch_refs
       WHERE fulfillment_order_id = p_fulfillment_order_id
         AND (provider_order_id IS NOT NULL OR status <> 'draft')
    ) THEN
      RAISE EXCEPTION 'omnipack_dispatch_ref_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    SELECT * INTO v_order FROM public.commerce_orders
     WHERE id = v_fulfillment.order_id FOR UPDATE;
    -- The two new-format markers stay refused: an order carrying one, whose parcel
    -- carries no `deliveryContact`, is an inconsistent row this routine must not
    -- paper over. `channelOrderSnapshot` is NOT such a marker. It records where the
    -- order came from, not what format its contact is in, and EVERY marketplace
    -- order ever ingested carries it -- so lumping it in here refused a parcel
    -- whose own order holds a complete, buyer-submitted contact.
    IF coalesce(v_order.metadata->'runtimeFinalize', '{}'::jsonb) ? 'deliveryContact'
      OR coalesce(v_order.metadata, '{}'::jsonb) ? 'deliveryContactOverride'
    THEN
      RAISE EXCEPTION 'omnipack_dispatch_delivery_contact_missing' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO v_client FROM public.clients WHERE id = v_fulfillment.client_id;
    SELECT * INTO v_address FROM public.addresses WHERE id = v_fulfillment.shipping_address_id;
    -- The resolver owns both the channel and profile ladders.  This recorder
    -- keeps only its locking, canonical-marker, and completeness decisions.
    v_contact_resolution := private.commerce_delivery_contact_resolve_v1(jsonb_build_object(
      'frozenContactPresent', false,
      'frozenContact', NULL,
      'orderCanonicalPresent', false,
      'channelOrderSnapshot', v_order.metadata->'channelOrderSnapshot',
      'selectedDeliveryCandidates', jsonb_build_array(
        v_fulfillment.metadata->'selectedDelivery',
        v_order.metadata->'selectedDelivery',
        v_order.metadata #> '{runtimeFinalize,selectedDelivery}',
        v_fulfillment.shipping_address_snapshot->'selectedDelivery',
        v_address.metadata->'selectedDelivery'
      ),
      'recipientCandidates', jsonb_build_array(
        v_fulfillment.shipping_address_snapshot->>'recipientName',
        concat_ws(' ', v_client.first_name, v_client.last_name),
        v_fulfillment.shipping_address_snapshot->>'label'
      ),
      'phoneCandidates', jsonb_build_array(
        v_fulfillment.shipping_address_snapshot->>'contactPhone',
        v_address.contact_phone,
        v_client.phone
      ),
      'legacyClientEmail', v_client.email,
      'line1', v_fulfillment.shipping_address_snapshot->>'line1',
      'line2', NULL,
      'city', v_fulfillment.shipping_address_snapshot->>'city',
      'postalCode', v_fulfillment.shipping_address_snapshot->>'postalCode',
      'country', v_fulfillment.shipping_address_snapshot->>'country'
    ));
    v_legacy_contact := v_contact_resolution->'contact';
    IF v_contact_resolution->>'disposition' <> 'inferred_complete'
      OR nullif(btrim(v_legacy_contact->>'recipientName'), '') IS NULL
      OR nullif(btrim(v_legacy_contact->>'contactPhone'), '') IS NULL
      OR nullif(btrim(v_legacy_contact->>'line1'), '') IS NULL
      OR nullif(btrim(v_legacy_contact->>'city'), '') IS NULL
      OR nullif(btrim(v_legacy_contact->>'postalCode'), '') IS NULL
      OR nullif(btrim(v_legacy_contact->>'country'), '') IS NULL
    THEN
      RAISE EXCEPTION 'omnipack_dispatch_delivery_contact_missing' USING ERRCODE = '22023';
    END IF;
    UPDATE public.commerce_fulfillment_orders
       SET shipping_address_snapshot = shipping_address_snapshot || jsonb_build_object(
             'deliveryContact', v_legacy_contact,
             'selectedDelivery', v_legacy_contact->'selectedDelivery'
           ),
           updated_at = now()
     WHERE id = v_fulfillment.id;
    RETURN jsonb_build_object(
      'contractVersion', 'omnipack.evidence.v1',
      'retryableReason', 'omnipack_dispatch_contact_stale'
    );
  END IF;
  v_current_revision := (v_fulfillment.shipping_address_snapshot #>> '{deliveryContact,revision}')::integer;
  -- NULL is "the caller stated no revision", not "revision zero". See the input
  -- gate above: a stated revision is still compared, byte for byte.
  IF v_candidate_revision IS NOT NULL AND v_candidate_revision IS DISTINCT FROM v_current_revision THEN
    RETURN jsonb_build_object(
      'contractVersion', 'omnipack.evidence.v1',
      'retryableReason', 'omnipack_dispatch_contact_stale'
    );
  END IF;

  SELECT * INTO v_ref
    FROM public.omnipack_dispatch_refs
   WHERE fulfillment_order_id = p_fulfillment_order_id
   ORDER BY created_at DESC, id DESC
   LIMIT 1
   FOR UPDATE;
  IF FOUND AND v_ref.request_idempotency_key IS DISTINCT FROM btrim(p_idempotency_key) THEN
    RAISE EXCEPTION 'omnipack_dispatch_ref_fulfillment_conflict' USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.omnipack_dispatch_refs (
    fulfillment_order_id, order_id, provider_order_id, dispatch_mode, status,
    request_idempotency_key, request_fingerprint, sanitized_request,
    sanitized_response, error
  ) VALUES (
    p_fulfillment_order_id, v_fulfillment.order_id, NULL, p_dispatch_mode,
    'draft', btrim(p_idempotency_key), p_request_fingerprint,
    coalesce(p_sanitized_request, '{}'::jsonb),
    coalesce(p_sanitized_response, '{}'::jsonb),
    coalesce(p_error, '{}'::jsonb)
  )
  ON CONFLICT (request_idempotency_key) DO NOTHING
  RETURNING * INTO v_ref;

  IF NOT FOUND THEN
    v_replayed := true;
    SELECT * INTO v_ref
      FROM public.omnipack_dispatch_refs
     WHERE request_idempotency_key = btrim(p_idempotency_key)
     FOR UPDATE;

    IF v_ref.fulfillment_order_id IS DISTINCT FROM p_fulfillment_order_id THEN
      RAISE EXCEPTION 'omnipack_dispatch_ref_idempotency_conflict' USING ERRCODE = '23505';
    END IF;

    IF v_ref.status = 'draft' AND v_ref.provider_order_id IS NULL THEN
      v_replayed := v_ref.request_fingerprint IS NOT DISTINCT FROM p_request_fingerprint
        AND v_ref.sanitized_request IS NOT DISTINCT FROM coalesce(p_sanitized_request, '{}'::jsonb)
        AND v_ref.sanitized_response IS NOT DISTINCT FROM coalesce(p_sanitized_response, '{}'::jsonb)
        AND v_ref.error IS NOT DISTINCT FROM coalesce(p_error, '{}'::jsonb)
        AND (
          v_ref.dispatch_mode IS NOT DISTINCT FROM p_dispatch_mode
          OR (v_ref.dispatch_mode IN ('stage', 'live') AND p_dispatch_mode = 'shadow')
        );
      UPDATE public.omnipack_dispatch_refs
         SET dispatch_mode = CASE
               WHEN v_ref.dispatch_mode IN ('stage', 'live') AND p_dispatch_mode = 'shadow'
                 THEN v_ref.dispatch_mode
               ELSE p_dispatch_mode
             END,
             request_fingerprint = p_request_fingerprint,
             sanitized_request = coalesce(p_sanitized_request, '{}'::jsonb),
             sanitized_response = coalesce(p_sanitized_response, '{}'::jsonb),
             error = coalesce(p_error, '{}'::jsonb),
             updated_at = CASE WHEN v_replayed THEN updated_at ELSE now() END
       WHERE id = v_ref.id
       RETURNING * INTO v_ref;
    ELSIF v_ref.request_fingerprint IS DISTINCT FROM p_request_fingerprint
      OR v_ref.dispatch_mode IS DISTINCT FROM p_dispatch_mode
    THEN
      RAISE EXCEPTION 'omnipack_dispatch_ref_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.evidence.v1',
    'dispatchRefId', v_ref.id,
    'fulfillmentOrderId', v_ref.fulfillment_order_id,
    'orderId', v_ref.order_id,
    'providerOrderId', v_ref.provider_order_id,
    'status', v_ref.status,
    'replayed', v_replayed
  );
END;
$_$;


--
-- Name: FUNCTION omnipack_record_dispatch_ref_v2(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_order_id text, p_dispatch_mode text, p_status text, p_request_fingerprint text, p_sanitized_request jsonb, p_sanitized_response jsonb, p_error jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.omnipack_record_dispatch_ref_v2(p_idempotency_key text, p_fulfillment_order_id uuid, p_provider_order_id text, p_dispatch_mode text, p_status text, p_request_fingerprint text, p_sanitized_request jsonb, p_sanitized_response jsonb, p_error jsonb) IS 'Records or refreshes one no-effect draft only when its redacted delivery-contact revision matches the locked parcel.';


--
-- Name: omnipack_record_low_stock_evidence(text, text, text, text, integer, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_record_low_stock_evidence(p_idempotency_key text, p_sku text, p_threshold_kind text, p_severity text, p_provider_for_sale_quantity integer DEFAULT NULL::integer, p_local_available_quantity integer DEFAULT NULL::integer, p_forecast_days integer DEFAULT NULL::integer, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_evidence public.omnipack_low_stock_evidence%ROWTYPE;
  v_catalog_sku_id uuid;
  v_replayed boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_sku IS NULL OR btrim(p_sku) = ''
    OR p_threshold_kind NOT IN ('safety_stock', 'forecast', 'provider_mismatch', 'reservation_coverage', 'stale_sync', 'manual')
    OR p_severity NOT IN ('info', 'warning', 'critical')
    OR (p_provider_for_sale_quantity IS NOT NULL AND p_provider_for_sale_quantity < 0)
    OR (p_local_available_quantity IS NOT NULL AND p_local_available_quantity < 0)
    OR (p_forecast_days IS NOT NULL AND p_forecast_days < 0) THEN
    RAISE EXCEPTION 'omnipack_low_stock_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_catalog_sku_id
    FROM public.catalog_skus
   WHERE sku = btrim(p_sku)
   LIMIT 1;

  INSERT INTO public.omnipack_low_stock_evidence (
    sku,
    catalog_sku_id,
    threshold_kind,
    severity,
    status,
    provider_for_sale_quantity,
    local_available_quantity,
    forecast_days,
    idempotency_key,
    evidence
  )
  VALUES (
    btrim(p_sku),
    v_catalog_sku_id,
    p_threshold_kind,
    p_severity,
    'open',
    p_provider_for_sale_quantity,
    p_local_available_quantity,
    p_forecast_days,
    btrim(p_idempotency_key),
    coalesce(p_evidence, '{}'::jsonb)
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING * INTO v_evidence;

  IF NOT FOUND THEN
    v_replayed := true;
    UPDATE public.omnipack_low_stock_evidence
       SET status = 'open',
           severity = p_severity,
           provider_for_sale_quantity = p_provider_for_sale_quantity,
           local_available_quantity = p_local_available_quantity,
           forecast_days = p_forecast_days,
           last_seen_at = clock_timestamp(),
           resolved_at = NULL,
           evidence = coalesce(p_evidence, '{}'::jsonb)
     WHERE idempotency_key = btrim(p_idempotency_key)
     RETURNING * INTO v_evidence;
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.evidence.v1',
    'lowStockEvidenceId', v_evidence.id,
    'sku', v_evidence.sku,
    'status', v_evidence.status,
    'replayed', v_replayed
  );
END;
$$;


--
-- Name: omnipack_record_product_reconciliation_evidence(text, text, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_record_product_reconciliation_evidence(p_idempotency_key text, p_sku text, p_conflict_kind text, p_ean text DEFAULT NULL::text, p_provider_quantity integer DEFAULT NULL::integer, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_row public.omnipack_product_reconciliation_evidence%ROWTYPE;
  v_catalog_sku_id uuid;
  v_replayed boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_sku IS NULL OR btrim(p_sku) = ''
    OR p_conflict_kind NOT IN ('unknown_sku', 'ean_conflict', 'kind_quantity_conflict')
    OR (p_provider_quantity IS NOT NULL AND p_provider_quantity < 0)
  THEN
    RAISE EXCEPTION 'omnipack_product_reconciliation_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- Best-effort SKU resolution; an unknown_sku conflict legitimately leaves this NULL.
  SELECT id INTO v_catalog_sku_id
    FROM public.catalog_skus
   WHERE sku = btrim(p_sku)
   LIMIT 1;

  INSERT INTO public.omnipack_product_reconciliation_evidence (
    sku, catalog_sku_id, ean, conflict_kind, provider_quantity, idempotency_key, evidence
  )
  VALUES (
    btrim(p_sku),
    v_catalog_sku_id,
    NULLIF(btrim(coalesce(p_ean, '')), ''),
    p_conflict_kind,
    p_provider_quantity,
    btrim(p_idempotency_key),
    COALESCE(p_evidence, '{}'::jsonb)
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    v_replayed := true;
    UPDATE public.omnipack_product_reconciliation_evidence
       SET last_seen_at = clock_timestamp(),
           provider_quantity = p_provider_quantity,
           evidence = COALESCE(p_evidence, '{}'::jsonb),
           -- Re-seeing a previously resolved conflict reopens it.
           status = CASE WHEN status = 'resolved' THEN 'open' ELSE status END,
           resolved_at = CASE WHEN status = 'resolved' THEN NULL ELSE resolved_at END
     WHERE idempotency_key = btrim(p_idempotency_key)
     RETURNING * INTO v_row;
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.product_reconciliation.v0',
    'reconciliationEvidenceId', v_row.id,
    'sku', v_row.sku,
    'conflictKind', v_row.conflict_kind,
    'status', v_row.status,
    'replayed', v_replayed
  );
END;
$$;


--
-- Name: omnipack_record_status_evidence(text, uuid, uuid, text, text, text, text, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_record_status_evidence(p_idempotency_key text, p_fulfillment_order_id uuid, p_dispatch_ref_id uuid, p_provider_status text, p_provider_sub_status text, p_local_status text, p_evidence_kind text, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_inbound_provider_event_id uuid DEFAULT NULL::uuid, p_sanitized_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_evidence public.omnipack_status_evidence%ROWTYPE;
  v_replayed boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_fulfillment_order_id IS NULL
    OR p_provider_status IS NULL OR btrim(p_provider_status) = ''
    OR p_evidence_kind NOT IN ('webhook', 'reconciliation', 'manual', 'simulator')
  THEN
    RAISE EXCEPTION 'omnipack_status_evidence_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_fulfillment
    FROM public.commerce_fulfillment_orders
   WHERE id = p_fulfillment_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'omnipack_status_evidence_fulfillment_not_found' USING ERRCODE = '22023';
  END IF;

  IF p_dispatch_ref_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM public.omnipack_dispatch_refs
     WHERE id = p_dispatch_ref_id
       AND fulfillment_order_id = p_fulfillment_order_id
  ) THEN
    RAISE EXCEPTION 'omnipack_status_evidence_dispatch_ref_mismatch' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.omnipack_status_evidence (
    dispatch_ref_id,
    fulfillment_order_id,
    order_id,
    inbound_provider_event_id,
    provider_status,
    provider_sub_status,
    local_status,
    evidence_kind,
    occurred_at,
    idempotency_key,
    sanitized_payload
  )
  VALUES (
    p_dispatch_ref_id,
    p_fulfillment_order_id,
    v_fulfillment.order_id,
    p_inbound_provider_event_id,
    btrim(p_provider_status),
    NULLIF(btrim(coalesce(p_provider_sub_status, '')), ''),
    NULLIF(btrim(coalesce(p_local_status, '')), ''),
    p_evidence_kind,
    p_occurred_at,
    btrim(p_idempotency_key),
    COALESCE(p_sanitized_payload, '{}'::jsonb)
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING * INTO v_evidence;

  IF NOT FOUND THEN
    v_replayed := true;
    SELECT *
      INTO v_evidence
      FROM public.omnipack_status_evidence
     WHERE idempotency_key = btrim(p_idempotency_key);
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.evidence.v0',
    'statusEvidenceId', v_evidence.id,
    'fulfillmentOrderId', v_evidence.fulfillment_order_id,
    'orderId', v_evidence.order_id,
    'providerStatus', v_evidence.provider_status,
    'replayed', v_replayed
  );
END;
$$;


--
-- Name: omnipack_record_stock_snapshot(text, text, integer, integer, integer, integer, integer, integer, integer, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_record_stock_snapshot(p_idempotency_key text, p_sku text, p_provider_total_quantity integer, p_provider_for_sale_quantity integer, p_provider_reserved_unavailable_quantity integer DEFAULT 0, p_local_on_hand integer DEFAULT 0, p_local_reserved integer DEFAULT 0, p_local_unavailable integer DEFAULT 0, p_local_safety_stock integer DEFAULT 0, p_mismatch_kind text DEFAULT 'not_evaluated'::text, p_sync_run_id text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb, p_inventory_class text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_snapshot public.omnipack_stock_snapshots%ROWTYPE;
  v_catalog_sku_id uuid;
  v_inventory_class text;
  v_replayed boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_sku IS NULL OR btrim(p_sku) = ''
    OR p_provider_total_quantity IS NULL OR p_provider_total_quantity < 0
    OR p_provider_for_sale_quantity IS NULL OR p_provider_for_sale_quantity < 0
    OR p_provider_for_sale_quantity > p_provider_total_quantity
    OR coalesce(p_provider_reserved_unavailable_quantity, 0) < 0
    OR coalesce(p_provider_reserved_unavailable_quantity, 0) + p_provider_for_sale_quantity > p_provider_total_quantity
    OR coalesce(p_local_on_hand, 0) < 0
    OR coalesce(p_local_reserved, 0) < 0
    OR coalesce(p_local_unavailable, 0) < 0
    OR coalesce(p_local_safety_stock, 0) < 0
    OR p_mismatch_kind NOT IN ('not_evaluated', 'none', 'provider_lower', 'provider_higher', 'stale_local', 'stale_provider')
    OR (p_inventory_class IS NOT NULL AND p_inventory_class NOT IN ('sellable', 'packaging')) THEN
    RAISE EXCEPTION 'omnipack_stock_snapshot_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_catalog_sku_id
    FROM public.catalog_skus
   WHERE sku = btrim(p_sku)
   LIMIT 1;

  v_inventory_class := coalesce(
    p_inventory_class,
    CASE WHEN v_catalog_sku_id IS NOT NULL THEN 'sellable' END
  );

  INSERT INTO public.omnipack_stock_snapshots (
    sku,
    catalog_sku_id,
    inventory_class,
    provider_total_quantity,
    provider_for_sale_quantity,
    provider_reserved_unavailable_quantity,
    local_on_hand,
    local_reserved,
    local_unavailable,
    local_safety_stock,
    mismatch_kind,
    sync_run_id,
    idempotency_key,
    evidence
  )
  VALUES (
    btrim(p_sku),
    v_catalog_sku_id,
    v_inventory_class,
    p_provider_total_quantity,
    p_provider_for_sale_quantity,
    coalesce(p_provider_reserved_unavailable_quantity, 0),
    coalesce(p_local_on_hand, 0),
    coalesce(p_local_reserved, 0),
    coalesce(p_local_unavailable, 0),
    coalesce(p_local_safety_stock, 0),
    p_mismatch_kind,
    nullif(btrim(coalesce(p_sync_run_id, '')), ''),
    btrim(p_idempotency_key),
    coalesce(p_evidence, '{}'::jsonb)
  )
  ON CONFLICT (idempotency_key) DO NOTHING
  RETURNING * INTO v_snapshot;

  IF NOT FOUND THEN
    v_replayed := true;
    SELECT *
      INTO v_snapshot
      FROM public.omnipack_stock_snapshots
     WHERE idempotency_key = btrim(p_idempotency_key);
  END IF;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.evidence.v0',
    'stockSnapshotId', v_snapshot.id,
    'sku', v_snapshot.sku,
    'inventoryClass', v_snapshot.inventory_class,
    'mismatchKind', v_snapshot.mismatch_kind,
    'replayed', v_replayed
  );
END;
$$;


--
-- Name: FUNCTION omnipack_record_stock_snapshot(p_idempotency_key text, p_sku text, p_provider_total_quantity integer, p_provider_for_sale_quantity integer, p_provider_reserved_unavailable_quantity integer, p_local_on_hand integer, p_local_reserved integer, p_local_unavailable integer, p_local_safety_stock integer, p_mismatch_kind text, p_sync_run_id text, p_evidence jsonb, p_inventory_class text); Type: COMMENT; Schema: public; Owner: -
--

