--
-- Name: omnipack_resolve_low_stock_evidence(text, text[], text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_resolve_low_stock_evidence(p_sku text, p_active_threshold_kinds text[] DEFAULT ARRAY[]::text[], p_sync_run_id text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_resolved integer := 0;
  v_active text[] := coalesce(p_active_threshold_kinds, ARRAY[]::text[]);
BEGIN
  IF p_sku IS NULL OR btrim(p_sku) = '' THEN
    RAISE EXCEPTION 'omnipack_low_stock_resolve_invalid_input' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM unnest(v_active) AS threshold_kind
     WHERE threshold_kind NOT IN ('safety_stock', 'forecast', 'provider_mismatch', 'reservation_coverage', 'stale_sync', 'manual')
  ) THEN
    RAISE EXCEPTION 'omnipack_low_stock_resolve_invalid_threshold' USING ERRCODE = '22023';
  END IF;

  UPDATE public.omnipack_low_stock_evidence
     SET status = 'resolved',
         resolved_at = clock_timestamp(),
         last_seen_at = clock_timestamp(),
         evidence = jsonb_build_object(
           'provider', 'omnipack',
           'source', 'stock_sync',
           'resolvedBy', 'omnipack_resolve_low_stock_evidence',
           'syncRunId', nullif(btrim(coalesce(p_sync_run_id, '')), ''),
           'resolution', coalesce(p_evidence, '{}'::jsonb)
         )
   WHERE sku = btrim(p_sku)
     AND status IN ('open', 'acknowledged')
     AND NOT (threshold_kind = ANY(v_active));

  GET DIAGNOSTICS v_resolved = ROW_COUNT;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.evidence.v1',
    'sku', btrim(p_sku),
    'resolved', v_resolved
  );
END;
$$;


--
-- Name: FUNCTION omnipack_resolve_low_stock_evidence(p_sku text, p_active_threshold_kinds text[], p_sync_run_id text, p_evidence jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.omnipack_resolve_low_stock_evidence(p_sku text, p_active_threshold_kinds text[], p_sync_run_id text, p_evidence jsonb) IS 'Resolves inactive OmniPack low-stock evidence, including reservation coverage; evidence only, no inventory mutation.';


--
-- Name: omnipack_resolve_product_reconciliation_evidence(text, text[], text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_resolve_product_reconciliation_evidence(p_sku text, p_active_conflict_kinds text[] DEFAULT ARRAY[]::text[], p_sync_run_id text DEFAULT NULL::text, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_resolved integer := 0;
  v_active text[] := COALESCE(p_active_conflict_kinds, ARRAY[]::text[]);
BEGIN
  IF p_sku IS NULL OR btrim(p_sku) = '' THEN
    RAISE EXCEPTION 'omnipack_product_reconciliation_resolve_invalid_input' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(v_active) AS conflict_kind
     WHERE conflict_kind NOT IN ('unknown_sku', 'ean_conflict', 'kind_quantity_conflict')
  ) THEN
    RAISE EXCEPTION 'omnipack_product_reconciliation_resolve_invalid_kind' USING ERRCODE = '22023';
  END IF;

  UPDATE public.omnipack_product_reconciliation_evidence
     SET status = 'resolved',
         resolved_at = clock_timestamp(),
         last_seen_at = clock_timestamp(),
         evidence = jsonb_build_object(
           'provider', 'omnipack',
           'source', 'product_sync',
           'resolvedBy', 'omnipack_resolve_product_reconciliation_evidence',
           'syncRunId', NULLIF(btrim(coalesce(p_sync_run_id, '')), ''),
           'resolution', COALESCE(p_evidence, '{}'::jsonb)
         )
   WHERE sku = btrim(p_sku)
     AND status IN ('open', 'acknowledged')
     AND NOT (conflict_kind = ANY(v_active));

  GET DIAGNOSTICS v_resolved = ROW_COUNT;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.product_reconciliation.v0',
    'sku', btrim(p_sku),
    'resolved', v_resolved
  );
END;
$$;


--
-- Name: omnipack_upsert_stock_sync_cursor(text, timestamp with time zone, timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.omnipack_upsert_stock_sync_cursor(p_status text, p_last_stock_synced_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_last_movement_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor jsonb DEFAULT '{}'::jsonb, p_error jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_cursor public.omnipack_stock_sync_cursors%ROWTYPE;
BEGIN
  IF p_status NOT IN ('idle', 'running', 'succeeded', 'failed') THEN
    RAISE EXCEPTION 'omnipack_stock_cursor_invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.omnipack_stock_sync_cursors (
    provider_kind,
    status,
    last_stock_synced_at,
    last_movement_occurred_at,
    cursor,
    error,
    updated_at
  )
  VALUES (
    'omnipack',
    p_status,
    p_last_stock_synced_at,
    p_last_movement_occurred_at,
    COALESCE(p_cursor, '{}'::jsonb),
    COALESCE(p_error, '{}'::jsonb),
    now()
  )
  ON CONFLICT (provider_kind) DO UPDATE
  SET status = EXCLUDED.status,
      last_stock_synced_at = COALESCE(EXCLUDED.last_stock_synced_at, public.omnipack_stock_sync_cursors.last_stock_synced_at),
      last_movement_occurred_at = COALESCE(EXCLUDED.last_movement_occurred_at, public.omnipack_stock_sync_cursors.last_movement_occurred_at),
      cursor = EXCLUDED.cursor,
      error = EXCLUDED.error,
      updated_at = now()
  RETURNING * INTO v_cursor;

  RETURN jsonb_build_object(
    'contractVersion', 'omnipack.evidence.v0',
    'providerKind', v_cursor.provider_kind,
    'status', v_cursor.status,
    'updatedAt', v_cursor.updated_at
  );
END;
$$;


--
-- Name: outbox_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.outbox_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    event_type text NOT NULL,
    idempotency_key text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    payload jsonb NOT NULL,
    error text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT outbox_events_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT outbox_events_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'processed'::text, 'failed'::text, 'discarded'::text])))
);


--
-- Name: outbox_claim_aggregate_batch(text, uuid, text[], integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_claim_aggregate_batch(p_aggregate_type text, p_aggregate_id uuid, p_event_types text[], p_batch_size integer DEFAULT 5, p_visibility_seconds integer DEFAULT 300, p_max_attempts integer DEFAULT 8) RETURNS SETOF public.outbox_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch integer := LEAST(GREATEST(COALESCE(p_batch_size, 5), 1), 10);
  v_visibility integer := LEAST(GREATEST(COALESCE(p_visibility_seconds, 300), 300), 3600);
  v_max integer := LEAST(GREATEST(COALESCE(p_max_attempts, 8), 1), 20);
BEGIN
  IF p_aggregate_type IS NULL OR btrim(p_aggregate_type) = '' OR p_aggregate_id IS NULL THEN
    RAISE EXCEPTION 'outbox_claim_aggregate_scope_required' USING ERRCODE = '22023';
  END IF;
  IF p_event_types IS NULL OR cardinality(p_event_types) = 0 THEN
    RAISE EXCEPTION 'outbox_claim_allowlist_required' USING ERRCODE = '22023';
  END IF;

  PERFORM private.outbox_prepare_resend_idempotency(
    p_event_types,
    p_aggregate_type,
    p_aggregate_id
  );

  WITH sweep AS (
    SELECT event.id
      FROM public.outbox_events event
     WHERE event.aggregate_type = p_aggregate_type
       AND event.aggregate_id = p_aggregate_id
       AND event.event_type = ANY (p_event_types)
       AND event.status IN ('pending', 'failed', 'processing')
       AND event.available_at <= now()
       AND event.attempts >= v_max
     ORDER BY event.created_at, event.id
     LIMIT 10
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.outbox_events event
     SET status = 'discarded',
         error = left(COALESCE(event.error, '') || ' | max_attempts_exhausted_at_aggregate_claim', 2000),
         metadata = event.metadata || jsonb_build_object(
           'discardReason', 'max_attempts',
           'discardedAt', now(),
           'finalAttempts', event.attempts)
    FROM sweep
   WHERE event.id = sweep.id;

  RETURN QUERY
  WITH candidates AS (
    SELECT event.id
      FROM public.outbox_events event
     WHERE event.aggregate_type = p_aggregate_type
       AND event.aggregate_id = p_aggregate_id
       AND event.event_type = ANY (p_event_types)
       AND event.available_at <= now()
       AND event.status IN ('pending', 'failed', 'processing')
       AND event.attempts < v_max
       AND NOT EXISTS (
             SELECT 1
               FROM public.outbox_events prior
              WHERE prior.aggregate_type = event.aggregate_type
                AND prior.aggregate_id = event.aggregate_id
                AND prior.event_type = ANY (p_event_types)
                AND prior.status IN ('pending', 'failed', 'processing')
                AND (prior.created_at, prior.id) < (event.created_at, event.id))
     ORDER BY event.created_at, event.id
     LIMIT v_batch
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.outbox_events event
     SET status = 'processing',
         attempts = event.attempts + 1,
         available_at = now() + make_interval(secs => v_visibility),
         metadata = event.metadata || jsonb_build_object(
           'lastClaimedAt', now(),
           'claimToken', gen_random_uuid()::text,
           'claimScope', 'aggregate_immediate')
           || CASE
                WHEN event.event_type = ANY (private.outbox_resend_event_types())
                 AND NOT event.metadata ? 'resendIdempotencyStartedAt'
                THEN jsonb_build_object('resendIdempotencyStartedAt', now())
                ELSE '{}'::jsonb
              END
    FROM candidates
   WHERE event.id = candidates.id
  RETURNING event.*;
END;
$$;


--
-- Name: FUNCTION outbox_claim_aggregate_batch(p_aggregate_type text, p_aggregate_id uuid, p_event_types text[], p_batch_size integer, p_visibility_seconds integer, p_max_attempts integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.outbox_claim_aggregate_batch(p_aggregate_type text, p_aggregate_id uuid, p_event_types text[], p_batch_size integer, p_visibility_seconds integer, p_max_attempts integer) IS 'Aggregate-scoped immediate outbox claim with the same Resend ledger recovery and immutable provider-idempotency safety window as the global dispatcher.';


--
-- Name: outbox_claim_batch(text[], integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_claim_batch(p_event_types text[], p_batch_size integer DEFAULT 25, p_visibility_seconds integer DEFAULT 300, p_max_attempts integer DEFAULT 8) RETURNS SETOF public.outbox_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch integer := LEAST(GREATEST(COALESCE(p_batch_size, 25), 1), 100);
  -- Visibility floor is 300 s (not 60): it must stay >= 5x the worker's
  -- maxDuration so a still-running handler can never lose its lease.
  v_visibility integer := LEAST(GREATEST(COALESCE(p_visibility_seconds, 300), 300), 3600);
  v_max integer := LEAST(GREATEST(COALESCE(p_max_attempts, 8), 1), 20);
BEGIN
  IF p_event_types IS NULL OR cardinality(p_event_types) = 0 THEN
    RAISE EXCEPTION 'outbox_claim_allowlist_required' USING ERRCODE = '22023';
  END IF;

  -- Poison sweep: rows that exhausted attempts (e.g. crash loops where the
  -- handler dies before mark_failed) are discarded here, at the next claim.
  -- SKIP LOCKED + LIMIT so concurrent claimers never block or deadlock.
  WITH sweep AS (
    SELECT e.id
      FROM public.outbox_events e
     WHERE e.event_type = ANY (p_event_types)
       AND e.status IN ('pending', 'failed', 'processing')
       AND e.available_at <= now()
       AND e.attempts >= v_max
     ORDER BY e.created_at, e.id
     LIMIT 100
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.outbox_events e
     SET status = 'discarded',
         error = left(COALESCE(e.error, '') || ' | max_attempts_exhausted_at_claim', 2000),
         metadata = e.metadata || jsonb_build_object(
           'discardReason', 'max_attempts',
           'discardedAt', now(),
           'finalAttempts', e.attempts)
    FROM sweep s
   WHERE e.id = s.id;

  -- Claim: atomic single statement; row locks release at function end
  -- (PostgREST = one transaction per RPC).
  RETURN QUERY
  WITH candidates AS (
    SELECT e.id
      FROM public.outbox_events e
     WHERE e.event_type = ANY (p_event_types)
       AND e.available_at <= now()                  -- due, OR processing-lease expired
       AND e.status IN ('pending', 'failed', 'processing')
       AND e.attempts < v_max
       AND NOT EXISTS (                              -- one-in-flight-per-aggregate
             SELECT 1
               FROM public.outbox_events prior
              WHERE prior.aggregate_type = e.aggregate_type
                AND prior.aggregate_id = e.aggregate_id
                AND prior.status IN ('pending', 'failed', 'processing')
                AND (prior.created_at, prior.id) < (e.created_at, e.id))
     ORDER BY e.created_at, e.id
     LIMIT v_batch
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.outbox_events e
     SET status = 'processing',
         attempts = e.attempts + 1,
         available_at = now() + make_interval(secs => v_visibility),
         metadata = e.metadata || jsonb_build_object(
           'lastClaimedAt', now(),
           'claimToken', gen_random_uuid()::text)    -- volatile => fresh token per row
    FROM candidates c
   WHERE e.id = c.id
  RETURNING e.*;
END;
$$;


--
-- Name: outbox_claim_batch_v2(text[], integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_claim_batch_v2(p_event_types text[], p_batch_size integer DEFAULT 25, p_visibility_seconds integer DEFAULT 300, p_max_attempts integer DEFAULT 8) RETURNS SETOF public.outbox_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch integer := LEAST(GREATEST(COALESCE(p_batch_size, 25), 1), 100);
  -- Visibility floor is 300 s (not 60): it must stay >= 5x the worker's
  -- maxDuration so a still-running handler can never lose its lease.
  v_visibility integer := LEAST(GREATEST(COALESCE(p_visibility_seconds, 300), 300), 3600);
  v_max integer := LEAST(GREATEST(COALESCE(p_max_attempts, 8), 1), 20);
BEGIN
  IF p_event_types IS NULL OR cardinality(p_event_types) = 0 THEN
    RAISE EXCEPTION 'outbox_claim_allowlist_required' USING ERRCODE = '22023';
  END IF;

  -- Poison sweep is still allowlist-scoped: dormant rows never get discarded
  -- by a dispatcher run that has no handler for them.
  WITH sweep AS (
    SELECT e.id
      FROM public.outbox_events e
     WHERE e.event_type = ANY (p_event_types)
       AND e.status IN ('pending', 'failed', 'processing')
       AND e.available_at <= now()
       AND e.attempts >= v_max
     ORDER BY e.created_at, e.id
     LIMIT 100
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.outbox_events e
     SET status = 'discarded',
         error = left(COALESCE(e.error, '') || ' | max_attempts_exhausted_at_claim', 2000),
         metadata = e.metadata || jsonb_build_object(
           'discardReason', 'max_attempts',
           'discardedAt', now(),
           'finalAttempts', e.attempts)
    FROM sweep s
   WHERE e.id = s.id;

  RETURN QUERY
  WITH candidates AS (
    SELECT e.id
      FROM public.outbox_events e
     WHERE e.event_type = ANY (p_event_types)
       AND e.available_at <= now()
       AND e.status IN ('pending', 'failed', 'processing')
       AND e.attempts < v_max
       AND NOT EXISTS (
             SELECT 1
               FROM public.outbox_events prior
              WHERE prior.aggregate_type = e.aggregate_type
                AND prior.aggregate_id = e.aggregate_id
                AND prior.event_type = ANY (p_event_types)
                AND prior.status IN ('pending', 'failed', 'processing')
                AND (prior.created_at, prior.id) < (e.created_at, e.id))
     ORDER BY e.created_at, e.id
     LIMIT v_batch
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.outbox_events e
     SET status = 'processing',
         attempts = e.attempts + 1,
         available_at = now() + make_interval(secs => v_visibility),
         metadata = e.metadata || jsonb_build_object(
           'lastClaimedAt', now(),
           'claimToken', gen_random_uuid()::text)
    FROM candidates c
   WHERE e.id = c.id
  RETURNING e.*;
END;
$$;


--
-- Name: FUNCTION outbox_claim_batch_v2(p_event_types text[], p_batch_size integer, p_visibility_seconds integer, p_max_attempts integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.outbox_claim_batch_v2(p_event_types text[], p_batch_size integer, p_visibility_seconds integer, p_max_attempts integer) IS 'Claims allowlisted outbox rows; per-aggregate anti-join only considers older rows whose event_type is also in the current allowlist.';


--
-- Name: outbox_claim_batch_v3(text[], text[], integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_claim_batch_v3(p_event_types text[], p_known_event_types text[] DEFAULT ARRAY[]::text[], p_batch_size integer DEFAULT 25, p_visibility_seconds integer DEFAULT 300, p_max_attempts integer DEFAULT 8) RETURNS SETOF public.outbox_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch integer := LEAST(GREATEST(COALESCE(p_batch_size, 25), 1), 100);
  v_visibility integer := LEAST(GREATEST(COALESCE(p_visibility_seconds, 300), 300), 3600);
  v_max integer := LEAST(GREATEST(COALESCE(p_max_attempts, 8), 1), 20);
  v_known_event_types text[];
BEGIN
  IF p_event_types IS NULL OR cardinality(p_event_types) = 0 THEN
    RAISE EXCEPTION 'outbox_claim_allowlist_required' USING ERRCODE = '22023';
  END IF;

  PERFORM private.outbox_prepare_resend_idempotency(p_event_types);

  SELECT array_agg(DISTINCT event_type)
    INTO v_known_event_types
    FROM unnest(coalesce(p_known_event_types, ARRAY[]::text[]) || p_event_types) AS known(event_type)
   WHERE event_type IS NOT NULL AND btrim(event_type) <> '';

  WITH sweep AS (
    SELECT event.id
      FROM public.outbox_events event
     WHERE event.event_type = ANY (p_event_types)
       AND event.metadata->>'claimScope' IS DISTINCT FROM 'preview_matrix'
       AND event.status IN ('pending', 'failed', 'processing')
       AND event.available_at <= now()
       AND event.attempts >= v_max
     ORDER BY event.created_at, event.id
     LIMIT 100
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.outbox_events event
     SET status = 'discarded',
         error = left(COALESCE(event.error, '') || ' | max_attempts_exhausted_at_claim', 2000),
         metadata = event.metadata || jsonb_build_object(
           'discardReason', 'max_attempts',
           'discardedAt', now(),
           'finalAttempts', event.attempts)
    FROM sweep
   WHERE event.id = sweep.id;

  RETURN QUERY
  WITH candidates AS (
    SELECT event.id
      FROM public.outbox_events event
     WHERE event.event_type = ANY (p_event_types)
       AND event.metadata->>'claimScope' IS DISTINCT FROM 'preview_matrix'
       AND event.available_at <= now()
       AND event.status IN ('pending', 'failed', 'processing')
       AND event.attempts < v_max
       AND NOT EXISTS (
             SELECT 1
               FROM public.outbox_events prior
              WHERE prior.aggregate_type = event.aggregate_type
                AND prior.aggregate_id = event.aggregate_id
                AND prior.status IN ('pending', 'failed', 'processing')
                AND prior.metadata->>'claimScope' IS DISTINCT FROM 'preview_matrix'
                AND (prior.created_at, prior.id) < (event.created_at, event.id)
                AND (
                  prior.event_type = ANY (p_event_types)
                  OR (
                    prior.event_type <> ALL (coalesce(v_known_event_types, ARRAY[]::text[]))
                    AND NOT EXISTS (
                      SELECT 1
                        FROM public.outbox_dormant_event_types dormant
                       WHERE dormant.event_type = prior.event_type
                    )
                  )
                ))
     ORDER BY event.created_at, event.id
     LIMIT v_batch
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.outbox_events event
     SET status = 'processing',
         attempts = event.attempts + 1,
         available_at = now() + make_interval(secs => v_visibility),
         metadata = event.metadata || jsonb_build_object(
           'lastClaimedAt', now(),
           'claimToken', gen_random_uuid()::text)
           || CASE
                WHEN event.event_type = ANY (private.outbox_resend_event_types())
                 AND NOT event.metadata ? 'resendIdempotencyStartedAt'
                THEN jsonb_build_object('resendIdempotencyStartedAt', now())
                ELSE '{}'::jsonb
              END
    FROM candidates
   WHERE event.id = candidates.id
  RETURNING event.*;
END;
$$;


--
-- Name: FUNCTION outbox_claim_batch_v3(p_event_types text[], p_known_event_types text[], p_batch_size integer, p_visibility_seconds integer, p_max_attempts integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.outbox_claim_batch_v3(p_event_types text[], p_known_event_types text[], p_batch_size integer, p_visibility_seconds integer, p_max_attempts integer) IS 'Claims allowlisted outbox rows with ordering, durable Resend ledger recovery, and a 23-hour immutable provider-idempotency safety window.';


--
-- Name: outbox_claim_preview_matrix_batch(text, text[], integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_claim_preview_matrix_batch(p_run_id text, p_event_types text[], p_batch_size integer DEFAULT 25, p_visibility_seconds integer DEFAULT 300, p_max_attempts integer DEFAULT 8) RETURNS SETOF public.outbox_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_batch integer := LEAST(GREATEST(COALESCE(p_batch_size, 25), 1), 100);
  v_visibility integer := LEAST(GREATEST(COALESCE(p_visibility_seconds, 300), 300), 3600);
  v_max integer := LEAST(GREATEST(COALESCE(p_max_attempts, 8), 1), 20);
  v_run_id text := btrim(COALESCE(p_run_id, ''));
BEGIN
  IF v_run_id = '' THEN
    RAISE EXCEPTION 'outbox_preview_matrix_run_id_required' USING ERRCODE = '22023';
  END IF;
  IF p_event_types IS NULL OR cardinality(p_event_types) = 0 THEN
    RAISE EXCEPTION 'outbox_claim_allowlist_required' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH candidates AS (
    SELECT e.id
      FROM public.outbox_events e
     WHERE e.event_type = ANY (p_event_types)
       AND e.metadata->>'claimScope' = 'preview_matrix'
       AND e.metadata->>'runId' = v_run_id
       AND e.available_at <= now()
       AND e.status IN ('pending', 'failed', 'processing')
       AND e.attempts < v_max
     ORDER BY e.created_at, e.id
     LIMIT v_batch
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.outbox_events e
     SET status = 'processing',
         attempts = e.attempts + 1,
         available_at = now() + make_interval(secs => v_visibility),
         metadata = e.metadata || jsonb_build_object(
           'lastClaimedAt', now(),
           'claimToken', gen_random_uuid()::text)
    FROM candidates c
   WHERE e.id = c.id
  RETURNING e.*;
END;
$$;


--
-- Name: FUNCTION outbox_claim_preview_matrix_batch(p_run_id text, p_event_types text[], p_batch_size integer, p_visibility_seconds integer, p_max_attempts integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.outbox_claim_preview_matrix_batch(p_run_id text, p_event_types text[], p_batch_size integer, p_visibility_seconds integer, p_max_attempts integer) IS 'Hidden-preview release-gate claim path. Claims only synthetic outbox_events where metadata.claimScope=preview_matrix and metadata.runId matches p_run_id; no poison sweep or global backlog side effects.';


--
-- Name: outbox_mark_failed(uuid, text, text, text, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_mark_failed(p_event_id uuid, p_claim_token text, p_error text, p_outcome text DEFAULT 'retry'::text, p_base_delay_seconds integer DEFAULT 60, p_max_delay_seconds integer DEFAULT 3600, p_max_attempts integer DEFAULT 8, p_snooze_seconds integer DEFAULT 300) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_row public.outbox_events%ROWTYPE;
  v_base integer := LEAST(GREATEST(COALESCE(p_base_delay_seconds, 60), 5), 3600);
  v_cap integer;
  v_max integer := LEAST(GREATEST(COALESCE(p_max_attempts, 8), 1), 20);
  v_snooze integer := LEAST(GREATEST(COALESCE(p_snooze_seconds, 300), 60), 3600);
  v_delay double precision;
BEGIN
  IF p_outcome IS NULL OR p_outcome NOT IN ('retry', 'discard', 'snooze') THEN
    RAISE EXCEPTION 'outbox_mark_failed_invalid_outcome' USING ERRCODE = '22023';
  END IF;

  v_cap := LEAST(GREATEST(v_base, COALESCE(p_max_delay_seconds, 3600)), 86400);

  SELECT *
    INTO v_row
    FROM public.outbox_events
   WHERE id = p_event_id
     AND status = 'processing'
     AND metadata->>'claimToken' = p_claim_token
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN 'missed';  -- stale/zombie mark: logged by the caller, never corruption
  END IF;

  IF p_outcome = 'discard' OR (p_outcome = 'retry' AND v_row.attempts >= v_max) THEN
    UPDATE public.outbox_events
       SET status = 'discarded',
           error = left(p_error, 2000),
           metadata = metadata || jsonb_build_object(
             'discardReason',
             CASE WHEN p_outcome = 'discard' THEN 'permanent_error' ELSE 'max_attempts' END,
             'discardedAt', now(),
             'finalAttempts', v_row.attempts)
     WHERE id = v_row.id;
    RETURN 'discarded';
  END IF;

  IF p_outcome = 'snooze' THEN
    -- Provider outage: refund the attempt so outages never burn the DLQ budget.
    UPDATE public.outbox_events
       SET status = 'failed',
           attempts = GREATEST(v_row.attempts - 1, 0),
           available_at = now() + make_interval(secs => v_snooze),
           error = left(p_error, 2000),
           metadata = metadata || jsonb_build_object(
             'snoozeCount', COALESCE((metadata->>'snoozeCount')::integer, 0) + 1,
             'lastSnoozedAt', now())
     WHERE id = v_row.id;
    RETURN 'snoozed';
  END IF;

  -- retry: exponential backoff with equal jitter in [d/2, d] — kills the
  -- power-of-two retry convoy against the 1-minute cron.
  v_delay := LEAST(
               v_cap::double precision,
               v_base::double precision * power(2, LEAST(GREATEST(v_row.attempts - 1, 0), 16))
             ) * (0.5 + random() * 0.5);

  UPDATE public.outbox_events
     SET status = 'failed',
         available_at = now() + make_interval(secs => v_delay),
         error = left(p_error, 2000)
   WHERE id = v_row.id;
  RETURN 'failed';
END;
$$;


--
-- Name: outbox_mark_processed(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_mark_processed(p_event_id uuid, p_claim_token text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH updated AS (
    UPDATE public.outbox_events
       SET status = 'processed',
           processed_at = now(),
           error = NULL,
           metadata = metadata || COALESCE(p_metadata, '{}'::jsonb)
     WHERE id = p_event_id
       AND status = 'processing'
       AND metadata->>'claimToken' = p_claim_token
     RETURNING id
  )
  SELECT EXISTS (SELECT 1 FROM updated);
$$;


--
-- Name: outbox_prune(timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_prune(p_processed_before timestamp with time zone DEFAULT (now() - '30 days'::interval), p_discarded_before timestamp with time zone DEFAULT (now() - '90 days'::interval), p_limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 500), 1), 5000);
  v_processed integer := 0;
  v_discarded integer := 0;
BEGIN
  WITH target AS (
    SELECT id, status
      FROM public.outbox_events
     WHERE metadata->>'retentionCompactedAt' IS NULL
       AND (
         (
           status = 'processed'
           AND COALESCE(processed_at, created_at) < p_processed_before
         )
         OR (
           status = 'discarded'
           AND private.outbox_try_timestamptz(metadata->>'discardedAt') < p_discarded_before
         )
       )
     ORDER BY created_at, id
     LIMIT v_limit
     FOR UPDATE SKIP LOCKED
  ),
  compacted AS (
    UPDATE public.outbox_events e
       SET payload = '{}'::jsonb,
           error = NULL,
           metadata = e.metadata || jsonb_build_object(
             'retentionCompactedAt', now(),
             'retentionCompactedBy', 'outbox_prune',
             'retentionCompactedStatus', e.status)
      FROM target t
     WHERE e.id = t.id
     RETURNING t.status
  )
  SELECT
    count(*) FILTER (WHERE status = 'processed')::integer,
    count(*) FILTER (WHERE status = 'discarded')::integer
    INTO v_processed, v_discarded
    FROM compacted;

  RETURN jsonb_build_object(
    'compacted', v_processed + v_discarded,
    'processed', v_processed,
    'discarded', v_discarded,
    'limit', v_limit
  );
END;
$$;


--
-- Name: outbox_queue_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_queue_stats() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT jsonb_build_object(
    'pending',    count(*) FILTER (WHERE status = 'pending'),
    'processing', count(*) FILTER (WHERE status = 'processing'),
    'processed',  count(*) FILTER (WHERE status = 'processed'),
    'failed',     count(*) FILTER (WHERE status = 'failed'),
    'discarded',  count(*) FILTER (WHERE status = 'discarded'),
    -- Stall detector: includes expired 'processing' leases on purpose.
    'oldestClaimableSeconds', COALESCE(
      EXTRACT(EPOCH FROM now() - min(available_at) FILTER (
        WHERE status IN ('pending', 'failed', 'processing')
          AND available_at <= now()))::bigint,
      0),
    -- CASE (not AND) guards the cast: AND operand order is not guaranteed,
    -- so a malformed discardedAt must be excluded before casting.
    'discardedLast24h', count(*) FILTER (
      WHERE status = 'discarded'
        AND CASE
              WHEN metadata->>'discardedAt' ~ '^\d{4}-'
                THEN (metadata->>'discardedAt')::timestamptz > now() - interval '24 hours'
              ELSE false
            END)
  )
  FROM public.outbox_events;
$$;


--
-- Name: outbox_release_unprocessed(uuid[], text[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_release_unprocessed(p_event_ids uuid[], p_claim_tokens text[], p_delay_seconds integer DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_delay integer := LEAST(GREATEST(COALESCE(p_delay_seconds, 0), 0), 3600);
  v_count integer;
BEGIN
  IF p_event_ids IS NULL OR p_claim_tokens IS NULL
     OR cardinality(p_event_ids) <> cardinality(p_claim_tokens) THEN
    RAISE EXCEPTION 'outbox_release_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- Handler never ran for released rows: refund the attempt taken at claim.
  UPDATE public.outbox_events e
     SET status = 'pending',
         available_at = now() + make_interval(secs => v_delay),
         attempts = GREATEST(e.attempts - 1, 0)
    FROM unnest(p_event_ids, p_claim_tokens) AS t(id, token)
   WHERE e.id = t.id
     AND e.status = 'processing'
     AND e.metadata->>'claimToken' = t.token;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: outbox_requeue_discarded(uuid[], text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_requeue_discarded(p_event_ids uuid[] DEFAULT NULL::uuid[], p_event_type text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_requeued_by text DEFAULT 'manual_admin'::text, p_reason text DEFAULT NULL::text) RETURNS SETOF public.outbox_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
BEGIN
  IF p_event_ids IS NULL AND p_event_type IS NULL THEN
    RAISE EXCEPTION 'outbox_requeue_filter_required' USING ERRCODE = '22023';
  END IF;

  -- Requeued events re-enter at the FRONT of their aggregate's ordering (they
  -- are the oldest rows — desirable). The NOT EXISTS guard skips aggregates
  -- with a row currently in flight, preserving one-in-flight on replay.
  RETURN QUERY
  WITH target AS (
    SELECT d.id
      FROM public.outbox_events d
     WHERE d.status = 'discarded'
       AND (p_event_ids IS NULL OR d.id = ANY (p_event_ids))
       AND (p_event_type IS NULL OR d.event_type = p_event_type)
       AND NOT EXISTS (
             SELECT 1
               FROM public.outbox_events inflight
              WHERE inflight.aggregate_type = d.aggregate_type
                AND inflight.aggregate_id = d.aggregate_id
                AND inflight.status = 'processing')
     ORDER BY d.created_at, d.id
     LIMIT v_limit
     FOR UPDATE SKIP LOCKED
  )
  UPDATE public.outbox_events e
     SET status = 'pending',
         attempts = 0,
         available_at = now(),
         error = NULL,
         metadata = e.metadata || jsonb_build_object(
           'requeues',
           COALESCE(e.metadata->'requeues', '[]'::jsonb) || jsonb_build_array(
             jsonb_build_object(
               'at', now(),
               'by', p_requeued_by,
               'reason', p_reason,
               'previousAttempts', e.attempts,
               'previousError', e.error)))
    FROM target t
   WHERE e.id = t.id
  RETURNING e.*;
END;
$$;


--
-- Name: personalization_enqueue_declension(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personalization_enqueue_declension(p_client_id uuid, p_input_hash text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  INSERT INTO public.outbox_events (
    aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
  )
  VALUES (
    'client',
    p_client_id,
    'personalization.declension_requested',
    p_client_id::text || ':' || p_input_hash,
    jsonb_build_object('clientId', p_client_id::text, 'inputHash', p_input_hash),
    jsonb_build_object('source', 'configurator_persist')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;
$$;


--
-- Name: FUNCTION personalization_enqueue_declension(p_client_id uuid, p_input_hash text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.personalization_enqueue_declension(p_client_id uuid, p_input_hash text) IS 'Idempotently enqueues the async personalization declension job for a client. Called by the service-role persist-intent path when the deterministic dictionary missed a present name. SECURITY DEFINER + service_role-only EXECUTE.';


--
-- Name: personalization_persist_lead(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personalization_persist_lead(p_email text, p_first_name text, p_last_name text, p_phone text, p_country text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_email text := lower(btrim(p_email));
  v_first text := NULLIF(btrim(coalesce(p_first_name, '')), '');
  v_last text := NULLIF(btrim(coalesce(p_last_name, '')), '');
  v_phone text := NULLIF(btrim(coalesce(p_phone, '')), '');
  v_country text := NULLIF(btrim(coalesce(p_country, '')), '');
  v_contact_id uuid;
  v_client_id uuid;
  v_candidate_client_id uuid;
  v_created boolean := false;
  v_match_reason text := 'marketing_lead_created';
  v_now timestamptz := now();
  v_placeholder text;
BEGIN
  IF v_email IS NULL OR v_email = '' OR position('@' in v_email) = 0 THEN
    RAISE EXCEPTION 'personalization_lead_invalid_email';
  END IF;

  INSERT INTO public.communication_contacts (
    normalized_email, display_email, first_name, last_name, metadata, updated_at
  ) VALUES (
    v_email,
    btrim(p_email),
    v_first,
    v_last,
    jsonb_build_object('source', 'personalization_lead'),
    v_now
  )
  ON CONFLICT (normalized_email) DO UPDATE
    SET updated_at = EXCLUDED.updated_at,
        first_name = COALESCE(public.communication_contacts.first_name, EXCLUDED.first_name),
        last_name = COALESCE(public.communication_contacts.last_name, EXCLUDED.last_name),
        metadata = public.communication_contacts.metadata || EXCLUDED.metadata
  RETURNING id INTO v_contact_id;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'personalization-marketing-contact:' || v_contact_id::text,
      0
    )
  );

  SELECT client_row.id
    INTO v_client_id
    FROM public.clients AS client_row
   WHERE client_row.identity_kind = 'marketing_lead'
     AND client_row.marketing_contact_id = v_contact_id
   FOR UPDATE;

  IF v_client_id IS NULL THEN
    v_candidate_client_id := gen_random_uuid();
    v_placeholder := 'lead+' || replace(v_candidate_client_id::text, '-', '') || '@marketing.invalid';

    INSERT INTO public.clients (
      id, email, first_name, last_name, phone, country, lifecycle_stage,
      acquisition_source, identity_kind, marketing_contact_id, metadata
    ) VALUES (
      v_candidate_client_id,
      v_placeholder,
      v_first,
      v_last,
      v_phone,
      v_country,
      'lead',
      'hidden_configurator',
      'marketing_lead',
      v_contact_id,
      jsonb_build_object('hiddenCommerce', jsonb_build_object(
        'clientMatchReason', v_match_reason,
        'source', 'personalization_lead'
      ))
    )
    ON CONFLICT (marketing_contact_id)
      WHERE identity_kind = 'marketing_lead'
    DO NOTHING
    RETURNING id INTO v_client_id;

    IF v_client_id IS NOT NULL THEN
      v_created := true;
      INSERT INTO public.communication_contact_links (
        contact_id, source_system, source_table, source_id, metadata
      ) VALUES (
        v_contact_id,
        'platform',
        'clients',
        v_client_id,
        jsonb_build_object('identityKind', 'marketing_lead')
      );
    ELSE
      SELECT client_row.id
        INTO STRICT v_client_id
        FROM public.clients AS client_row
       WHERE client_row.identity_kind = 'marketing_lead'
         AND client_row.marketing_contact_id = v_contact_id
       FOR UPDATE;
    END IF;
  END IF;

  IF NOT v_created THEN
    v_match_reason := 'marketing_lead_match_contact';
    UPDATE public.clients AS client_row
       SET first_name = COALESCE(v_first, client_row.first_name),
           last_name = COALESCE(v_last, client_row.last_name),
           phone = COALESCE(v_phone, client_row.phone),
           country = COALESCE(client_row.country, v_country),
           updated_at = v_now,
           metadata = client_row.metadata || jsonb_build_object(
             'hiddenCommerce', jsonb_build_object(
               'clientMatchReason', v_match_reason,
               'lastPersonalizationLeadAt', to_char(
                 v_now AT TIME ZONE 'UTC',
                 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
               )
             )
           )
     WHERE client_row.id = v_client_id;
  END IF;

  RETURN jsonb_build_object(
    'clientId', v_client_id,
    'matchReason', v_match_reason
  );
END;
$$;


--
-- Name: FUNCTION personalization_persist_lead(p_email text, p_first_name text, p_last_name text, p_phone text, p_country text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.personalization_persist_lead(p_email text, p_first_name text, p_last_name text, p_phone text, p_country text) IS 'Idempotent early-personalization marketing subject resolver. The real address belongs to communication_contacts; the compatibility clients row is keyed by marketing_contact_id and stores only a deterministic .invalid address, so it cannot occupy the customer email namespace or update a customer found by email. Returns the unchanged clientId/matchReason shape for cookie and personalization compatibility.';


--
-- Name: platform_begin_job_run(text, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_begin_job_run(p_job_name text, p_trigger_source text, p_lease_owner text DEFAULT NULL::text, p_lease_seconds integer DEFAULT 900, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(acquired boolean, run_id uuid, reason text, lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_control public.platform_job_controls%ROWTYPE;
  v_lease_seconds integer;
  v_run_id uuid;
  v_now timestamptz := now();
  v_metadata jsonb := COALESCE(p_metadata, '{}'::jsonb);
BEGIN
  IF p_job_name IS NULL OR btrim(p_job_name) = '' THEN
    RAISE EXCEPTION 'platform_job_name_required' USING ERRCODE = '22023';
  END IF;

  IF p_trigger_source IS NULL OR btrim(p_trigger_source) = '' THEN
    RAISE EXCEPTION 'platform_job_trigger_source_required' USING ERRCODE = '22023';
  END IF;

  v_lease_seconds := LEAST(GREATEST(COALESCE(p_lease_seconds, 900), 60), 3600);

  INSERT INTO public.platform_job_controls (job_name)
  VALUES (p_job_name)
  ON CONFLICT (job_name) DO NOTHING;

  SELECT *
    INTO v_control
    FROM public.platform_job_controls
   WHERE job_name = p_job_name
   FOR UPDATE;

  IF NOT v_control.enabled THEN
    INSERT INTO public.platform_job_runs (
      job_name,
      status,
      trigger_source,
      lease_owner,
      started_at,
      finished_at,
      error,
      metadata
    )
    VALUES (
      p_job_name,
      'skipped',
      p_trigger_source,
      p_lease_owner,
      v_now,
      v_now,
      'job_disabled',
      v_metadata
    )
    RETURNING id INTO v_run_id;

    UPDATE public.platform_job_controls
       SET updated_at = v_now,
           last_started_at = v_now,
           last_finished_at = v_now,
           last_status = 'skipped',
           last_run_id = v_run_id
     WHERE job_name = p_job_name;

    RETURN QUERY SELECT false, v_run_id, 'job_disabled', NULL::timestamptz;
    RETURN;
  END IF;

  IF v_control.lease_expires_at IS NOT NULL AND v_control.lease_expires_at > v_now THEN
    INSERT INTO public.platform_job_runs (
      job_name,
      status,
      trigger_source,
      lease_owner,
      started_at,
      finished_at,
      lease_expires_at,
      error,
      metadata
    )
    VALUES (
      p_job_name,
      'skipped',
      p_trigger_source,
      p_lease_owner,
      v_now,
      v_now,
      v_control.lease_expires_at,
      'lease_active',
      v_metadata || jsonb_build_object('activeLeaseOwner', v_control.lease_owner)
    )
    RETURNING id INTO v_run_id;

    UPDATE public.platform_job_controls
       SET updated_at = v_now,
           last_started_at = v_now,
           last_finished_at = v_now,
           last_status = 'skipped',
           last_run_id = v_run_id
     WHERE job_name = p_job_name;

    RETURN QUERY SELECT false, v_run_id, 'lease_active', v_control.lease_expires_at;
    RETURN;
  END IF;

  v_run_id := gen_random_uuid();

  UPDATE public.platform_job_controls
     SET updated_at = v_now,
         lease_owner = p_lease_owner,
         lease_token = v_run_id,
         lease_expires_at = v_now + make_interval(secs => v_lease_seconds),
         last_started_at = v_now,
         last_status = 'running',
         last_run_id = v_run_id
   WHERE job_name = p_job_name
   RETURNING * INTO v_control;

  INSERT INTO public.platform_job_runs (
    id,
    job_name,
    status,
    trigger_source,
    lease_owner,
    started_at,
    lease_expires_at,
    metadata
  )
  VALUES (
    v_run_id,
    p_job_name,
    'running',
    p_trigger_source,
    p_lease_owner,
    v_now,
    v_control.lease_expires_at,
    v_metadata
  );

  RETURN QUERY SELECT true, v_run_id, 'acquired', v_control.lease_expires_at;
END;
$$;


--
-- Name: platform_claim_job_run(text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_claim_job_run(p_job_name text, p_driver text, p_lease_seconds integer DEFAULT 900, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(acquired boolean, run_id uuid, reason text, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_control public.platform_job_controls%ROWTYPE;
  v_driver text := COALESCE(NULLIF(btrim(p_driver), ''), 'pg_cron');
  v_lease_seconds integer;
  v_run_id uuid;
  v_now timestamptz := now();
  v_metadata jsonb := COALESCE(p_metadata, '{}'::jsonb);
  v_active_lease_until timestamptz;
BEGIN
  IF p_job_name IS NULL OR btrim(p_job_name) = '' THEN
    RAISE EXCEPTION 'platform_job_name_required' USING ERRCODE = '22023';
  END IF;

  IF v_driver NOT IN ('pg_cron', 'vercel_cron', 'manual_admin', 'worker') THEN
    RAISE EXCEPTION 'platform_job_invalid_driver' USING ERRCODE = '22023';
  END IF;

  v_lease_seconds := LEAST(GREATEST(COALESCE(p_lease_seconds, 900), 60), 3600);

  INSERT INTO public.platform_job_controls (job_name, active_driver)
  VALUES (p_job_name, 'pg_cron')
  ON CONFLICT (job_name) DO NOTHING;

  SELECT *
    INTO v_control
    FROM public.platform_job_controls
   WHERE job_name = p_job_name
   FOR UPDATE;

  IF NOT v_control.enabled THEN
    INSERT INTO public.platform_job_runs (
      job_name,
      status,
      trigger_source,
      driver,
      lease_owner,
      started_at,
      finished_at,
      error,
      metadata
    )
    VALUES (
      p_job_name,
      'skipped',
      v_driver,
      v_driver,
      v_driver,
      v_now,
      v_now,
      'job_disabled',
      v_metadata
    )
    RETURNING id INTO v_run_id;

    UPDATE public.platform_job_controls
       SET updated_at = v_now,
           last_started_at = v_now,
           last_finished_at = v_now,
           last_status = 'skipped',
           last_run_id = v_run_id
     WHERE job_name = p_job_name;

    RETURN QUERY SELECT false, v_run_id, 'job_disabled', NULL::timestamptz;
    RETURN;
  END IF;

  IF v_driver <> 'manual_admin' AND v_control.active_driver <> v_driver THEN
    INSERT INTO public.platform_job_runs (
      job_name,
      status,
      trigger_source,
      driver,
      lease_owner,
      started_at,
      finished_at,
      error,
      metadata
    )
    VALUES (
      p_job_name,
      'skipped',
      v_driver,
      v_driver,
      v_driver,
      v_now,
      v_now,
      'inactive_driver',
      v_metadata || jsonb_build_object('activeDriver', v_control.active_driver)
    )
    RETURNING id INTO v_run_id;

    UPDATE public.platform_job_controls
       SET updated_at = v_now,
           last_started_at = v_now,
           last_finished_at = v_now,
           last_status = 'skipped',
           last_run_id = v_run_id
     WHERE job_name = p_job_name;

    RETURN QUERY SELECT false, v_run_id, 'inactive_driver', NULL::timestamptz;
    RETURN;
  END IF;

  v_active_lease_until := COALESCE(v_control.lease_until, v_control.lease_expires_at);
  IF v_active_lease_until IS NOT NULL AND v_active_lease_until > v_now THEN
    INSERT INTO public.platform_job_runs (
      job_name,
      status,
      trigger_source,
      driver,
      lease_owner,
      started_at,
      finished_at,
      lease_expires_at,
      error,
      metadata
    )
    VALUES (
      p_job_name,
      'skipped',
      v_driver,
      v_driver,
      v_driver,
      v_now,
      v_now,
      v_active_lease_until,
      'lease_active',
      v_metadata || jsonb_build_object('activeLeaseOwner', v_control.lease_owner)
    )
    RETURNING id INTO v_run_id;

    UPDATE public.platform_job_controls
       SET updated_at = v_now,
           last_started_at = v_now,
           last_finished_at = v_now,
           last_status = 'skipped',
           last_run_id = v_run_id
     WHERE job_name = p_job_name;

    RETURN QUERY SELECT false, v_run_id, 'lease_active', v_active_lease_until;
    RETURN;
  END IF;

  v_run_id := gen_random_uuid();

  UPDATE public.platform_job_controls
     SET updated_at = v_now,
         lease_owner = v_driver,
         lease_token = v_run_id,
         lease_until = v_now + make_interval(secs => v_lease_seconds),
         lease_expires_at = v_now + make_interval(secs => v_lease_seconds),
         last_started_at = v_now,
         last_status = 'running',
         last_run_id = v_run_id
   WHERE job_name = p_job_name
   RETURNING * INTO v_control;

  INSERT INTO public.platform_job_runs (
    id,
    job_name,
    status,
    trigger_source,
    driver,
    lease_owner,
    started_at,
    lease_expires_at,
    metadata
  )
  VALUES (
    v_run_id,
    p_job_name,
    'running',
    v_driver,
    v_driver,
    v_driver,
    v_now,
    v_control.lease_until,
    v_metadata
  );

  RETURN QUERY SELECT true, v_run_id, 'acquired', v_control.lease_until;
END;
$$;


--
-- Name: platform_claim_job_run_v3(text, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_claim_job_run_v3(p_job_name text, p_trigger_kind text, p_invocation_source text, p_lease_seconds integer DEFAULT 900, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(acquired boolean, run_id uuid, reason text, lease_until timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_control public.platform_job_controls%ROWTYPE;
  v_trigger_kind text := COALESCE(NULLIF(btrim(p_trigger_kind), ''), '');
  v_invocation_source text := COALESCE(NULLIF(btrim(p_invocation_source), ''), '');
  v_lease_seconds integer;
  v_run_id uuid;
  v_now timestamptz := now();
  v_metadata jsonb := COALESCE(p_metadata, '{}'::jsonb);
  v_active_lease_until timestamptz;
  v_lease_owner text;
BEGIN
  IF p_job_name IS NULL OR btrim(p_job_name) = '' THEN
    RAISE EXCEPTION 'platform_job_name_required' USING ERRCODE = '22023';
  END IF;

  IF v_trigger_kind NOT IN ('worker', 'scheduler', 'operator') THEN
    RAISE EXCEPTION 'platform_job_invalid_trigger_kind' USING ERRCODE = '22023';
  END IF;

  IF v_invocation_source = '' OR length(v_invocation_source) > 128 THEN
    RAISE EXCEPTION 'platform_job_invocation_source_required' USING ERRCODE = '22023';
  END IF;

  v_lease_seconds := LEAST(GREATEST(COALESCE(p_lease_seconds, 900), 60), 3600);
  v_lease_owner := v_trigger_kind || ':' || v_invocation_source;

  SELECT *
    INTO v_control
    FROM public.platform_job_controls
   WHERE job_name = p_job_name
   FOR UPDATE;

  IF NOT FOUND OR v_control.allowed_trigger_kinds IS NULL THEN
    RAISE EXCEPTION 'platform_job_v3_control_not_configured' USING ERRCODE = '22023';
  END IF;

  IF NOT v_control.enabled THEN
    INSERT INTO public.platform_job_runs (
      job_name, status, trigger_source, trigger_kind, invocation_source,
      lease_owner, started_at, finished_at, error, metadata
    ) VALUES (
      p_job_name, 'skipped', v_invocation_source, v_trigger_kind, v_invocation_source,
      v_lease_owner, v_now, v_now, 'job_disabled',
      v_metadata || jsonb_build_object('triggerKind', v_trigger_kind, 'invocationSource', v_invocation_source)
    ) RETURNING id INTO v_run_id;

    UPDATE public.platform_job_controls
       SET updated_at = v_now, last_started_at = v_now, last_finished_at = v_now,
           last_status = 'skipped', last_run_id = v_run_id
     WHERE job_name = p_job_name;

    RETURN QUERY SELECT false, v_run_id, 'job_disabled', NULL::timestamptz;
    RETURN;
  END IF;

  IF NOT (v_trigger_kind = ANY(v_control.allowed_trigger_kinds)) THEN
    INSERT INTO public.platform_job_runs (
      job_name, status, trigger_source, trigger_kind, invocation_source,
      lease_owner, started_at, finished_at, error, metadata
    ) VALUES (
      p_job_name, 'skipped', v_invocation_source, v_trigger_kind, v_invocation_source,
      v_lease_owner, v_now, v_now, 'trigger_kind_not_allowed',
      v_metadata || jsonb_build_object('triggerKind', v_trigger_kind, 'invocationSource', v_invocation_source, 'allowedTriggerKinds', v_control.allowed_trigger_kinds)
    ) RETURNING id INTO v_run_id;

    UPDATE public.platform_job_controls
       SET updated_at = v_now, last_started_at = v_now, last_finished_at = v_now,
           last_status = 'skipped', last_run_id = v_run_id
     WHERE job_name = p_job_name;

    RETURN QUERY SELECT false, v_run_id, 'trigger_kind_not_allowed', NULL::timestamptz;
    RETURN;
  END IF;

  v_active_lease_until := COALESCE(v_control.lease_until, v_control.lease_expires_at);
  IF v_active_lease_until IS NOT NULL AND v_active_lease_until > v_now THEN
    INSERT INTO public.platform_job_runs (
      job_name, status, trigger_source, trigger_kind, invocation_source,
      lease_owner, started_at, finished_at, lease_expires_at, error, metadata
    ) VALUES (
      p_job_name, 'skipped', v_invocation_source, v_trigger_kind, v_invocation_source,
      v_lease_owner, v_now, v_now, v_active_lease_until, 'lease_active',
      v_metadata || jsonb_build_object('triggerKind', v_trigger_kind, 'invocationSource', v_invocation_source, 'activeLeaseOwner', v_control.lease_owner)
    ) RETURNING id INTO v_run_id;

    UPDATE public.platform_job_controls
       SET updated_at = v_now, last_started_at = v_now, last_finished_at = v_now,
           last_status = 'skipped', last_run_id = v_run_id
     WHERE job_name = p_job_name;

    RETURN QUERY SELECT false, v_run_id, 'lease_active', v_active_lease_until;
    RETURN;
  END IF;

  v_run_id := gen_random_uuid();
  UPDATE public.platform_job_controls
     SET updated_at = v_now,
         lease_owner = v_lease_owner,
         lease_token = v_run_id,
         lease_until = v_now + make_interval(secs => v_lease_seconds),
         lease_expires_at = v_now + make_interval(secs => v_lease_seconds),
         last_started_at = v_now,
         last_status = 'running',
         last_run_id = v_run_id
   WHERE job_name = p_job_name
   RETURNING * INTO v_control;

  INSERT INTO public.platform_job_runs (
    id, job_name, status, trigger_source, trigger_kind, invocation_source,
    lease_owner, started_at, lease_expires_at, metadata
  ) VALUES (
    v_run_id, p_job_name, 'running', v_invocation_source, v_trigger_kind, v_invocation_source,
    v_lease_owner, v_now, v_control.lease_until,
    v_metadata || jsonb_build_object('triggerKind', v_trigger_kind, 'invocationSource', v_invocation_source)
  );

  RETURN QUERY SELECT true, v_run_id, 'acquired', v_control.lease_until;
END;
$$;


--
-- Name: platform_control_list_alerts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_control_list_alerts(p_operator_id uuid) RETURNS TABLE(dedupe_key text, severity text, status text, owner text, title text, first_seen_at timestamp with time zone, last_seen_at timestamp with time zone, resolved_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.platform_control_require_operator(p_operator_id);
  RETURN QUERY SELECT row.dedupe_key, row.severity, row.status, row.owner, row.title,
    row.first_seen_at, row.last_seen_at, row.resolved_at
    FROM public.platform_alerts AS row
   ORDER BY row.last_seen_at DESC, row.dedupe_key LIMIT 200;
END;
$$;


--
-- Name: platform_control_list_controls(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_control_list_controls(p_operator_id uuid) RETURNS TABLE(control_key text, enabled boolean, revision integer, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.platform_control_require_operator(p_operator_id);
  RETURN QUERY SELECT row.control_key, row.enabled, row.revision, row.updated_at
    FROM public.platform_operational_controls AS row ORDER BY row.control_key;
END;
$$;


--
-- Name: platform_control_list_jobs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_control_list_jobs(p_operator_id uuid) RETURNS TABLE(job_name text, enabled boolean, active_driver text, last_status text, last_started_at timestamp with time zone, last_finished_at timestamp with time zone, last_success_at timestamp with time zone)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM public.platform_control_require_operator(p_operator_id);
  RETURN QUERY SELECT row.job_name, row.enabled,
    CASE WHEN to_jsonb(row)->>'active_driver' = 'worker' THEN 'worker'
         WHEN COALESCE(to_jsonb(row)->>'active_driver', 'manual_admin') = 'manual_admin' THEN 'operator'
         ELSE 'scheduler' END,
    row.last_status,
    row.last_started_at, row.last_finished_at, row.last_success_at
    FROM public.platform_job_controls AS row ORDER BY row.job_name;
END;
$$;


--
-- Name: platform_control_operator_is_active(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_control_operator_is_active(p_principal_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.platform_control_operators AS operator_row
    WHERE operator_row.principal_id = p_principal_id AND operator_row.active IS TRUE
  );
$$;


--
-- Name: platform_control_record_heartbeat(uuid, text, text, text, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_control_record_heartbeat(p_operator_id uuid, p_idempotency_key text, p_command_fingerprint text, p_health text, p_firing_count integer, p_max_severity text, p_promotion_ready boolean) RETURNS TABLE(action text, replayed boolean, revision integer, recorded_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_existing public.platform_control_operations%ROWTYPE;
  v_recorded_at timestamptz := clock_timestamp();
BEGIN
  PERFORM public.platform_control_require_operator(p_operator_id);
  IF p_health NOT IN ('healthy', 'degraded', 'failed') OR p_firing_count < 0
    OR (p_max_severity IS NOT NULL AND p_max_severity NOT IN ('p0', 'p1', 'p2', 'p3')) THEN
    RAISE EXCEPTION 'platform_control_heartbeat_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_existing FROM public.platform_control_operations
   WHERE idempotency_key = p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    IF v_existing.command_fingerprint <> p_command_fingerprint OR v_existing.action <> 'record-heartbeat' THEN
      RAISE EXCEPTION 'platform_control_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    RETURN QUERY SELECT 'record-heartbeat'::text, true, NULL::integer, v_existing.created_at;
    RETURN;
  END IF;
  INSERT INTO public.platform_job_controls AS job_row
    (job_name, enabled, last_started_at, last_finished_at,
     last_success_at, last_status, metadata, updated_at)
  VALUES ('platform-watchdog', true, v_recorded_at, v_recorded_at,
    v_recorded_at, 'success', jsonb_build_object('health', p_health,
      'firingCount', p_firing_count, 'maxSeverity', p_max_severity,
      'promotionReady', p_promotion_ready), v_recorded_at)
  ON CONFLICT (job_name) DO UPDATE SET
    last_started_at = EXCLUDED.last_started_at,
    last_finished_at = EXCLUDED.last_finished_at,
    last_success_at = EXCLUDED.last_success_at,
    last_status = EXCLUDED.last_status,
    metadata = EXCLUDED.metadata,
    updated_at = EXCLUDED.updated_at;
  INSERT INTO public.platform_control_operations
    (idempotency_key, command_fingerprint, action, operator_id, response, created_at)
  VALUES (p_idempotency_key, p_command_fingerprint, 'record-heartbeat', p_operator_id,
    jsonb_build_object('recordedAt', v_recorded_at), v_recorded_at);
  RETURN QUERY SELECT 'record-heartbeat'::text, false, NULL::integer, v_recorded_at;
END;
$$;


--
-- Name: platform_control_require_operator(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_control_require_operator(p_operator_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF p_operator_id IS NULL OR NOT public.platform_control_operator_is_active(p_operator_id) THEN
    RAISE EXCEPTION 'platform_control_operator_inactive' USING ERRCODE = '42501';
  END IF;
END;
$$;


--
-- Name: platform_control_set_control(uuid, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_control_set_control(p_operator_id uuid, p_idempotency_key text, p_command_fingerprint text, p_control_key text, p_enabled boolean) RETURNS TABLE(action text, replayed boolean, revision integer, recorded_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_existing public.platform_control_operations%ROWTYPE;
  v_revision integer;
  v_recorded_at timestamptz := clock_timestamp();
BEGIN
  PERFORM public.platform_control_require_operator(p_operator_id);
  SELECT * INTO v_existing FROM public.platform_control_operations
   WHERE idempotency_key = p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    IF v_existing.command_fingerprint <> p_command_fingerprint OR v_existing.action <> 'set-control' THEN
      RAISE EXCEPTION 'platform_control_idempotency_conflict' USING ERRCODE = '23505';
    END IF;
    RETURN QUERY SELECT 'set-control'::text, true,
      (v_existing.response->>'revision')::integer, v_existing.created_at;
    RETURN;
  END IF;

  INSERT INTO public.platform_operational_controls AS control_row
    (control_key, enabled, revision, updated_by, updated_at)
  VALUES (p_control_key, p_enabled, 1, p_operator_id, v_recorded_at)
  ON CONFLICT (control_key) DO UPDATE
    SET enabled = EXCLUDED.enabled, revision = control_row.revision + 1,
        updated_by = EXCLUDED.updated_by, updated_at = EXCLUDED.updated_at
  RETURNING control_row.revision INTO v_revision;
  INSERT INTO public.platform_control_operations
    (idempotency_key, command_fingerprint, action, operator_id, response, created_at)
  VALUES (p_idempotency_key, p_command_fingerprint, 'set-control', p_operator_id,
    jsonb_build_object('revision', v_revision, 'recordedAt', v_recorded_at), v_recorded_at);
  RETURN QUERY SELECT 'set-control'::text, false, v_revision, v_recorded_at;
END;
$$;


--
-- Name: platform_external_cron_guard_readback(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_external_cron_guard_readback() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'private', 'pg_catalog'
    AS $$
  SELECT jsonb_build_object(
    'configured', env.id IS NOT NULL,
    'legacyExternalCronConfigured', COALESCE(env.external_cron_enabled, false),
    'abandonedCartRuntimeIdentityConfigured', COALESCE(env.expected_abandoned_cart_runtime_url IS NOT NULL, false),
    'guardEnabled', false
  )
  FROM (SELECT true) AS singleton
  LEFT JOIN private.platform_cron_environment AS env ON true;
$$;


--
-- Name: platform_finish_job_run(text, uuid, text, integer, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_finish_job_run(p_job_name text, p_run_id uuid, p_status text, p_checked_count integer DEFAULT NULL::integer, p_updated_count integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_metadata jsonb := COALESCE(p_metadata, '{}'::jsonb);
  v_released boolean := false;
BEGIN
  IF p_status NOT IN ('success', 'failed') THEN
    RAISE EXCEPTION 'platform_job_invalid_finish_status' USING ERRCODE = '22023';
  END IF;

  UPDATE public.platform_job_runs
     SET status = p_status,
         finished_at = v_now,
         checked_count = p_checked_count,
         updated_count = p_updated_count,
         error = p_error,
         metadata = metadata || v_metadata
   WHERE id = p_run_id
     AND job_name = p_job_name;

  UPDATE public.platform_job_controls
     SET updated_at = v_now,
         lease_owner = NULL,
         lease_token = NULL,
         lease_expires_at = NULL,
         last_finished_at = v_now,
         last_success_at = CASE WHEN p_status = 'success' THEN v_now ELSE last_success_at END,
         last_status = p_status,
         last_run_id = p_run_id
   WHERE job_name = p_job_name
     AND lease_token = p_run_id
   RETURNING true INTO v_released;

  RETURN COALESCE(v_released, false);
END;
$$;


--
-- Name: platform_finish_job_run_v2(text, uuid, text, integer, integer, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_finish_job_run_v2(p_job_name text, p_run_id uuid, p_status text, p_checked integer DEFAULT NULL::integer, p_updated integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text, p_support_code text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
