--
-- Name: platform_finish_job_run_v3(text, uuid, text, integer, integer, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_finish_job_run_v3(p_job_name text, p_run_id uuid, p_status text, p_checked integer DEFAULT NULL::integer, p_updated integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text, p_support_code text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_metadata jsonb := COALESCE(p_metadata, '{}'::jsonb);
