    RAISE EXCEPTION 'platform_job_invalid_finish_status' USING ERRCODE = '22023';
  END IF;

  UPDATE public.platform_job_runs
     SET status = p_status,
         finished_at = v_now,
         checked = p_checked,
         updated = p_updated,
         checked_count = p_checked,
