         lease_expires_at = NULL,
         last_finished_at = v_now,
         last_success_at = CASE WHEN p_status = 'success' THEN v_now ELSE last_success_at END,
         last_status = p_status,
         last_run_id = p_run_id
   WHERE job_name = p_job_name
     AND lease_token = p_run_id
   RETURNING true INTO v_released;

  RETURN COALESCE(v_released, false);
END;
$$;


--
-- Name: platform_region_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.platform_region_code() RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_region text;
BEGIN
  SELECT settings.value_text INTO v_region
    FROM public.commerce_settings AS settings
   WHERE settings.key = 'settlement_region';

  IF v_region IS NULL THEN
    RAISE EXCEPTION 'settlement region is not configured in commerce_settings'
      USING ERRCODE = '55000',
            HINT = 'Insert commerce_settings.settlement_region with the ISO 3166-1 alpha-2 code whose tax and invoicing rules this deployment follows. This function will not assume one.';
  END IF;

  RETURN v_region;
END;
$$;


--
-- Name: FUNCTION platform_region_code(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.platform_region_code() IS 'The ISO 3166-1 alpha-2 code whose tax and invoicing rules this deployment follows, mirrored from configuration into commerce_settings. Raises 55000 when the row is absent or carries no code; it never returns a default.';


