BEGIN
  SELECT settings.value_text INTO v_currency
    FROM public.commerce_settings AS settings
   WHERE settings.key = 'settlement_currency';

  IF v_currency IS NULL THEN
    RAISE EXCEPTION 'settlement currency is not configured in commerce_settings'
      USING ERRCODE = '55000',
            HINT = 'Insert commerce_settings.settlement_currency with the ISO 4217 code this deployment settles in; it must match the settlement currency the application is configured with. This function will not assume one.';
  END IF;

  RETURN v_currency;
