--
-- Name: project_legacy_promotion_code_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_legacy_promotion_code_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_code_id uuid;
  v_subscription_initial boolean;
  v_one_time boolean;
  v_scopes text[];
  v_minimum_reference_minor integer;
BEGIN
  IF NEW.trigger_type<>'coupon_code'
     OR NEW.code IS NULL
     OR NEW.promotion_engine_version<>'promotion-engine.v1' THEN
    RETURN NEW;
  END IF;

  v_subscription_initial := lower(COALESCE(
    NEW.eligibility->>'first_subscription_purchase',''
  )) IN ('true','1');
  v_one_time := lower(COALESCE(
    NEW.eligibility->>'first_onetime_purchase',''
  )) IN ('true','1');
  v_scopes := CASE WHEN v_subscription_initial OR v_one_time THEN array_remove(ARRAY[
    CASE WHEN v_one_time THEN 'one_time' END,
    CASE WHEN v_subscription_initial THEN 'subscription_initial' END
  ]::text[],NULL) ELSE ARRAY['one_time','subscription_initial']::text[] END;
  v_minimum_reference_minor := CASE
    WHEN COALESCE(NEW.eligibility->>'min_cart_minor','') ~ '^\d{1,9}$'
      THEN (NEW.eligibility->>'min_cart_minor')::integer
    ELSE 0 END;

  INSERT INTO public.promotion_codes (
    code,name,scopes,valid_from,valid_to,minimum_reference_minor,
    redemption_limit_global,redemption_limit_per_customer,status,created_at,updated_at
  ) VALUES (
    NEW.code,NEW.name,v_scopes,NEW.valid_from,NEW.valid_to,v_minimum_reference_minor,
    NEW.redemption_limit_global,NEW.redemption_limit_per_customer,NEW.status,
    NEW.created_at,NEW.updated_at
  )
  ON CONFLICT (code_normalized) DO NOTHING
  RETURNING id INTO v_code_id;

  IF v_code_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.promotion_code_bindings (promotion_code_id,promotion_id,lane)
  VALUES (v_code_id,NEW.id,NEW.benefit_lane);
  RETURN NEW;
END;
$_$;


--
-- Name: project_legacy_promotion_redemption_claim(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_legacy_promotion_redemption_claim() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_code_id uuid;
  v_client_id uuid;
BEGIN
  SELECT o.client_id INTO v_client_id
  FROM public.commerce_orders o
  WHERE o.id=NEW.order_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;

  SELECT pcb.promotion_code_id INTO v_code_id
  FROM public.promotion_code_bindings pcb
  JOIN public.promotions p ON p.id=pcb.promotion_id
  JOIN public.promotion_codes pc ON pc.id=pcb.promotion_code_id
  WHERE pcb.promotion_id=NEW.promotion_id
    AND p.promotion_engine_version='promotion-engine.v1'
  FOR UPDATE OF pc;
  IF NOT FOUND THEN RETURN NEW; END IF;

  INSERT INTO public.promotion_code_claims (
    promotion_code_id,order_id,client_id,status,reserved_at,expires_at,
    redeemed_at,created_at,updated_at
  ) VALUES (
    v_code_id,NEW.order_id,v_client_id,'redeemed',NEW.redeemed_at,
    NEW.redeemed_at+interval '1 second',NEW.redeemed_at,NEW.created_at,NEW.created_at
  )
  ON CONFLICT (promotion_code_id,order_id) DO UPDATE SET
    client_id=EXCLUDED.client_id,
    status='redeemed',
    redeemed_at=EXCLUDED.redeemed_at,
    released_at=NULL,
    release_reason=NULL,
    updated_at=now()
  WHERE promotion_code_claims.status IN ('reserved','released');
  RETURN NEW;
END;
$$;


--
-- Name: promotion_codes_backfill_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promotion_codes_backfill_legacy() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
BEGIN
  INSERT INTO public.promotion_codes (
    code, name, scopes, valid_from, valid_to, minimum_reference_minor,
    redemption_limit_global, redemption_limit_per_customer, status, created_at, updated_at
  )
  SELECT p.code, p.name,
    CASE
      WHEN flags.subscription_initial OR flags.one_time THEN array_remove(ARRAY[
        CASE WHEN flags.one_time THEN 'one_time' END,
        CASE WHEN flags.subscription_initial THEN 'subscription_initial' END
      ]::text[], NULL)
      ELSE ARRAY['one_time', 'subscription_initial']::text[]
    END,
    p.valid_from, p.valid_to,
    CASE WHEN COALESCE(p.eligibility->>'min_cart_minor','') ~ '^\d{1,9}$'
      THEN (p.eligibility->>'min_cart_minor')::integer ELSE 0 END,
    p.redemption_limit_global, p.redemption_limit_per_customer, p.status,
    p.created_at, p.updated_at
  FROM public.promotions p
  CROSS JOIN LATERAL (
    SELECT
      lower(COALESCE(p.eligibility->>'first_subscription_purchase','')) IN ('true','1') AS subscription_initial,
      lower(COALESCE(p.eligibility->>'first_onetime_purchase','')) IN ('true','1') AS one_time
  ) flags
  WHERE p.trigger_type='coupon_code' AND p.code IS NOT NULL
    AND p.promotion_engine_version='promotion-engine.v1'
    -- A collision is a compatibility gap, not a migration failure. Leave the
    -- whole normalized group owned by the legacy engine until an operator
    -- resolves it; never choose a winner implicitly.
    AND NOT EXISTS (
      SELECT 1 FROM public.promotions collision
      WHERE collision.trigger_type='coupon_code'
        AND collision.code IS NOT NULL
        AND collision.promotion_engine_version='promotion-engine.v1'
        AND upper(btrim(collision.code))=upper(btrim(p.code))
        AND collision.id<>p.id
    )
  ON CONFLICT (code_normalized) DO NOTHING;

  INSERT INTO public.promotion_code_bindings (promotion_code_id,promotion_id,lane)
  SELECT pc.id,p.id,p.benefit_lane
  FROM public.promotions p
  JOIN public.promotion_codes pc ON pc.code_normalized=upper(btrim(p.code))
  WHERE p.trigger_type='coupon_code' AND p.code IS NOT NULL
    AND p.promotion_engine_version='promotion-engine.v1'
    AND NOT EXISTS (
      SELECT 1 FROM public.promotions collision
      WHERE collision.trigger_type='coupon_code'
        AND collision.code IS NOT NULL
        AND collision.promotion_engine_version='promotion-engine.v1'
        AND upper(btrim(collision.code))=upper(btrim(p.code))
        AND collision.id<>p.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.promotion_code_bindings existing_binding
      JOIN public.promotions existing_promotion ON existing_promotion.id=existing_binding.promotion_id
      WHERE existing_binding.promotion_code_id=pc.id
        AND existing_promotion.promotion_engine_version<>'promotion-engine.v1'
    )
  ON CONFLICT DO NOTHING;

  -- Preserve already-consumed capacity exactly once. A redeemed claim is
  -- historical truth and is never resurrected by refund/retry workflows.
  INSERT INTO public.promotion_code_claims (
    promotion_code_id,order_id,client_id,status,reserved_at,expires_at,
    redeemed_at,created_at,updated_at
  )
  SELECT pcb.promotion_code_id,r.order_id,
    o.client_id,'redeemed',r.redeemed_at,
    r.redeemed_at + interval '1 second',r.redeemed_at,r.created_at,r.created_at
  FROM public.promotion_redemptions r
  JOIN public.promotion_code_bindings pcb ON pcb.promotion_id=r.promotion_id
  JOIN public.commerce_orders o ON o.id=r.order_id
  ON CONFLICT (promotion_code_id,order_id) DO UPDATE SET
    client_id=EXCLUDED.client_id,
    status='redeemed',
    redeemed_at=EXCLUDED.redeemed_at,
    released_at=NULL,
    release_reason=NULL,
    updated_at=now()
  WHERE promotion_code_claims.status IN ('reserved','released');
END;
$_$;


--
-- Name: public_count_customer_magic_link_attempts_global(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_count_customer_magic_link_attempts_global(p_window_minutes integer DEFAULT 60) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT count(*)::integer
    FROM public.customer_magic_link_attempts
   WHERE created_at >= now() - make_interval(mins => GREATEST(LEAST(COALESCE(p_window_minutes, 60), 720), 1));
$$;


--
-- Name: public_record_admin_magic_link_attempt(text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_record_admin_magic_link_attempt(p_ip_hash text, p_email_hash text, p_window_minutes integer DEFAULT 60, p_max_per_ip integer DEFAULT 5, p_max_per_email integer DEFAULT 3) RETURNS TABLE(allowed boolean, reason text, attempts_by_ip integer, attempts_by_email integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_window_minutes integer := GREATEST(LEAST(COALESCE(p_window_minutes, 60), 720), 1);
  v_max_per_ip integer := GREATEST(LEAST(COALESCE(p_max_per_ip, 5), 100), 1);
  v_max_per_email integer := GREATEST(LEAST(COALESCE(p_max_per_email, 3), 100), 1);
  v_since timestamptz := now() - make_interval(mins => v_window_minutes);
  v_ip_count integer := 0;
  v_email_count integer := 0;
  v_lock_a text;
  v_lock_b text;
BEGIN
  IF p_ip_hash IS NULL OR length(p_ip_hash) = 0 THEN
    RAISE EXCEPTION 'admin_magic_link_attempt_missing_ip_hash'
      USING ERRCODE = '22023';
  END IF;

  IF p_email_hash IS NULL OR length(p_email_hash) = 0 THEN
    RAISE EXCEPTION 'admin_magic_link_attempt_missing_email_hash'
      USING ERRCODE = '22023';
  END IF;

  v_lock_a := LEAST('email:' || p_email_hash, 'ip:' || p_ip_hash);
  v_lock_b := GREATEST('email:' || p_email_hash, 'ip:' || p_ip_hash);
  PERFORM pg_advisory_xact_lock(hashtextextended(v_lock_a, 0));
  IF v_lock_b <> v_lock_a THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(v_lock_b, 0));
  END IF;

  DELETE FROM public.admin_magic_link_attempts
   WHERE created_at < now() - interval '24 hours';

  SELECT count(*)
    INTO v_ip_count
    FROM public.admin_magic_link_attempts
   WHERE ip_hash = p_ip_hash
     AND created_at >= v_since;

  SELECT count(*)
    INTO v_email_count
    FROM public.admin_magic_link_attempts
   WHERE email_hash = p_email_hash
     AND created_at >= v_since;

  IF v_ip_count >= v_max_per_ip THEN
    RETURN QUERY SELECT false, 'ip_quota'::text, v_ip_count, v_email_count;
    RETURN;
  END IF;

  IF v_email_count >= v_max_per_email THEN
    RETURN QUERY SELECT false, 'email_quota'::text, v_ip_count, v_email_count;
    RETURN;
  END IF;

  INSERT INTO public.admin_magic_link_attempts (ip_hash, email_hash)
  VALUES (p_ip_hash, p_email_hash);

  RETURN QUERY SELECT true, NULL::text, v_ip_count + 1, v_email_count + 1;
END;
$$;


--
-- Name: public_record_checkout_attempt(text, text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_record_checkout_attempt(p_ip_hash text, p_email_hash text, p_attempt_identity_hash text DEFAULT NULL::text, p_window_minutes integer DEFAULT 60, p_max_per_ip integer DEFAULT 10, p_max_per_email integer DEFAULT 5) RETURNS TABLE(allowed boolean, reason text, attempts_by_ip integer, attempts_by_email integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_window_minutes integer := GREATEST(LEAST(COALESCE(p_window_minutes, 60), 720), 1);
  v_max_per_ip integer := GREATEST(LEAST(COALESCE(p_max_per_ip, 10), 100), 1);
  v_max_per_email integer := GREATEST(LEAST(COALESCE(p_max_per_email, 5), 100), 1);
  v_since timestamptz := now() - make_interval(mins => v_window_minutes);
  v_attempt_identity_hash text;
  v_ip_count integer := 0;
  v_email_count integer := 0;
  v_lock_a text;
  v_lock_b text;
BEGIN
  IF p_ip_hash IS NULL OR p_ip_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'public_checkout_attempt_invalid_ip_hash'
      USING ERRCODE = '22023';
  END IF;

  IF p_email_hash IS NULL OR p_email_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'public_checkout_attempt_invalid_email_hash'
      USING ERRCODE = '22023';
  END IF;

  -- A caller that predates the exact-attempt identity cannot supply one. Give it
  -- a fresh random identity so the call is counted exactly like the five-argument
  -- limiter did and can never match a later attempt. A supplied identity is still
  -- shape-checked; only absence is tolerated.
  IF p_attempt_identity_hash IS NULL THEN
    v_attempt_identity_hash := encode(sha256(convert_to(gen_random_uuid()::text, 'UTF8')), 'hex');
  ELSIF p_attempt_identity_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'public_checkout_attempt_invalid_attempt_identity_hash'
      USING ERRCODE = '22023';
  ELSE
    v_attempt_identity_hash := p_attempt_identity_hash;
  END IF;

  -- A shared exact attempt serializes first, including callers whose IP/email changed.
  -- The second caller sees the committed ledger row and returns without touching
  -- either quota, so concurrent exact replays count exactly once.
  PERFORM pg_advisory_xact_lock(hashtextextended('checkout-attempt:' || v_attempt_identity_hash, 0));

  DELETE FROM public.public_checkout_attempts
   WHERE created_at < now() - interval '24 hours';

  -- Deliberately unbounded by v_since: the unique index on attempt_identity_hash
  -- spans the whole retained ledger, so any surviving row for this identity is a
  -- replay. Bounding this probe by the quota window is what made an out-of-window
  -- row unreachable here yet fatal at the INSERT below.
  IF EXISTS (
    SELECT 1
      FROM public.public_checkout_attempts
     WHERE attempt_identity_hash = v_attempt_identity_hash
  ) THEN
    SELECT count(*)
      INTO v_ip_count
      FROM public.public_checkout_attempts
     WHERE ip_hash = p_ip_hash
       AND created_at >= v_since;

    SELECT count(*)
      INTO v_email_count
      FROM public.public_checkout_attempts
     WHERE email_hash = p_email_hash
       AND created_at >= v_since;

    RETURN QUERY SELECT true, NULL::text, v_ip_count, v_email_count;
    RETURN;
  END IF;

  -- Unique journeys preserve the prior deterministic identity-lock ordering.
  v_lock_a := LEAST('email:' || p_email_hash, 'ip:' || p_ip_hash);
  v_lock_b := GREATEST('email:' || p_email_hash, 'ip:' || p_ip_hash);
  PERFORM pg_advisory_xact_lock(hashtextextended(v_lock_a, 0));
  IF v_lock_b <> v_lock_a THEN
    PERFORM pg_advisory_xact_lock(hashtextextended(v_lock_b, 0));
  END IF;

  SELECT count(*)
    INTO v_ip_count
    FROM public.public_checkout_attempts
   WHERE ip_hash = p_ip_hash
     AND created_at >= v_since;

  SELECT count(*)
    INTO v_email_count
    FROM public.public_checkout_attempts
   WHERE email_hash = p_email_hash
     AND created_at >= v_since;

  IF v_ip_count >= v_max_per_ip THEN
    RETURN QUERY SELECT false, 'ip_quota'::text, v_ip_count, v_email_count;
    RETURN;
  END IF;

  IF v_email_count >= v_max_per_email THEN
    RETURN QUERY SELECT false, 'email_quota'::text, v_ip_count, v_email_count;
    RETURN;
  END IF;

  -- The identity advisory lock above already serializes same-identity callers, so
  -- this conflict clause is unreachable in a single-writer race. It stays as a
  -- structural guarantee that this function can never surface unique_violation to
  -- a fail-closed caller, whatever future path reaches the INSERT.
  INSERT INTO public.public_checkout_attempts (ip_hash, email_hash, attempt_identity_hash)
  VALUES (p_ip_hash, p_email_hash, v_attempt_identity_hash)
  ON CONFLICT (attempt_identity_hash) DO NOTHING;

  RETURN QUERY SELECT true, NULL::text, v_ip_count + 1, v_email_count + 1;
END;
$_$;


