--
-- Name: public_record_signup_attempt(text, text, text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_record_signup_attempt(p_endpoint text, p_ip_hash text, p_email_hash text, p_window_minutes integer DEFAULT 60, p_max_per_ip integer DEFAULT 5, p_max_per_email integer DEFAULT 3) RETURNS TABLE(allowed boolean, reason text, attempts_by_ip integer, attempts_by_email integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_window_minutes integer := GREATEST(LEAST(COALESCE(p_window_minutes, 60), 720), 1);
  v_max_per_ip integer := GREATEST(LEAST(COALESCE(p_max_per_ip, 5), 100), 1);
  v_max_per_email integer := GREATEST(LEAST(COALESCE(p_max_per_email, 3), 100), 1);
  v_since timestamptz := now() - make_interval(mins => v_window_minutes);
  v_ip_count integer := 0;
  v_email_count integer := 0;
BEGIN
  IF p_endpoint NOT IN ('waitlist', 'tester_signup') THEN
    RAISE EXCEPTION 'public_signup_attempt_invalid_endpoint'
      USING ERRCODE = '22023';
  END IF;

  IF p_ip_hash IS NULL OR length(p_ip_hash) = 0 THEN
    RAISE EXCEPTION 'public_signup_attempt_missing_ip_hash'
      USING ERRCODE = '22023';
  END IF;

  IF p_email_hash IS NULL OR length(p_email_hash) = 0 THEN
    RAISE EXCEPTION 'public_signup_attempt_missing_email_hash'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(*)
    INTO v_ip_count
    FROM public.public_signup_attempts
   WHERE endpoint = p_endpoint
     AND ip_hash = p_ip_hash
     AND created_at >= v_since;

  SELECT count(*)
    INTO v_email_count
    FROM public.public_signup_attempts
   WHERE endpoint = p_endpoint
     AND email_hash = p_email_hash
     AND created_at >= v_since;

  IF v_ip_count >= v_max_per_ip THEN
    RETURN QUERY SELECT false, 'ip_quota'::text, v_ip_count, v_email_count;
    RETURN;
  END IF;

  IF v_email_count >= v_max_per_email THEN
    RETURN QUERY SELECT false, 'email_quota'::text, v_ip_count, v_email_count;
    RETURN;
  END IF;

  INSERT INTO public.public_signup_attempts (endpoint, ip_hash, email_hash)
  VALUES (p_endpoint, p_ip_hash, p_email_hash);

  RETURN QUERY SELECT true, NULL::text, v_ip_count + 1, v_email_count + 1;
END;
$$;


--
-- Name: public_submit_b2b_inquiry(text, text, text, text, text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.public_submit_b2b_inquiry(p_ip_hash text, p_company text, p_country text, p_first_name text, p_last_name text, p_business_email text, p_phone text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_window_minutes integer DEFAULT 60, p_max_per_ip integer DEFAULT 3) RETURNS TABLE(allowed boolean, reason text, inquiry_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_window_minutes integer := GREATEST(LEAST(COALESCE(p_window_minutes, 60), 720), 1);
  v_max_per_ip integer := GREATEST(LEAST(COALESCE(p_max_per_ip, 3), 100), 1);
  v_recent_count integer;
  v_inquiry_id uuid;
BEGIN
  IF p_ip_hash IS NULL OR length(btrim(p_ip_hash)) = 0 THEN
    RAISE EXCEPTION 'b2b_inquiry_missing_ip_hash' USING ERRCODE = '22023';
  END IF;

  IF p_company IS NULL OR p_country IS NULL OR p_first_name IS NULL
     OR p_last_name IS NULL OR p_business_email IS NULL THEN
    RAISE EXCEPTION 'b2b_inquiry_missing_required_field' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('b2b-inquiry:' || p_ip_hash, 0));

  SELECT count(*)
    INTO v_recent_count
    FROM public.b2b_inquiries
   WHERE ip_hash = p_ip_hash
     AND created_at >= now() - make_interval(mins => v_window_minutes);

  IF v_recent_count >= v_max_per_ip THEN
    RETURN QUERY SELECT false, 'ip_quota'::text, NULL::uuid;
    RETURN;
  END IF;

  INSERT INTO public.b2b_inquiries (
    company,
    country,
    first_name,
    last_name,
    business_email,
    phone,
    notes,
    ip_hash,
    status
  ) VALUES (
    btrim(p_company),
    p_country,
    btrim(p_first_name),
    btrim(p_last_name),
    lower(btrim(p_business_email)),
    NULLIF(btrim(p_phone), ''),
    NULLIF(btrim(p_notes), ''),
    p_ip_hash,
    'new'
  )
  RETURNING id INTO v_inquiry_id;

  RETURN QUERY SELECT true, NULL::text, v_inquiry_id;
END;
$$;


--
-- Name: record_admin_audit_event(uuid, text, text, text, text, jsonb, jsonb, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_admin_audit_event(p_actor_id uuid, p_action text, p_source text, p_entity_type text, p_entity_id text, p_old jsonb, p_new jsonb, p_idempotency_key text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text, p_target_admin_id uuid DEFAULT NULL::uuid, p_target_email text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor_email text;
  v_is_machine  boolean;
  v_id          uuid;
BEGIN
  -- Invariant 1: actor is explicit, NOT NULL, and a known admin. Never auth.uid().
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION 'audit_actor_required' USING ERRCODE = '42501';
  END IF;

  SELECT email, is_machine_actor
    INTO v_actor_email, v_is_machine
  FROM public.admin_users
  WHERE id = p_actor_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'audit_actor_unknown' USING ERRCODE = '42501';
  END IF;

  -- Cooperate with the fn-only BEFORE-INSERT trigger (lands Wave 4.5). Harmless now.
  PERFORM set_config('app.audit_via_fn', 'true', true);

  INSERT INTO public.admin_audit_events
    (actor_admin_id, actor_email, actor_kind, action, source,
     entity_type, entity_id, target_admin_id, target_email,
     old_value, new_value, idempotency_key, request_id)
  VALUES
    (p_actor_id, v_actor_email,
     CASE WHEN v_is_machine THEN 'machine' ELSE 'human' END,
     p_action, p_source,
     p_entity_type, p_entity_id, p_target_admin_id, p_target_email,
     p_old, p_new, p_idempotency_key, p_request_id)
  ON CONFLICT (entity_type, idempotency_key) WHERE idempotency_key IS NOT NULL
  DO NOTHING
  RETURNING id INTO v_id;

  -- Idempotent replay: conflict short-circuits to the existing row's id.
  IF v_id IS NULL AND p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_id
    FROM public.admin_audit_events
    WHERE entity_type = p_entity_type
      AND idempotency_key = p_idempotency_key;
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: FUNCTION record_admin_audit_event(p_actor_id uuid, p_action text, p_source text, p_entity_type text, p_entity_id text, p_old jsonb, p_new jsonb, p_idempotency_key text, p_request_id text, p_target_admin_id uuid, p_target_email text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_admin_audit_event(p_actor_id uuid, p_action text, p_source text, p_entity_type text, p_entity_id text, p_old jsonb, p_new jsonb, p_idempotency_key text, p_request_id text, p_target_admin_id uuid, p_target_email text) IS 'FROZEN agent-domain audit primitive (Wave 0a). Internal SECURITY DEFINER fn called only by domain RPCs. Validates a NOT-NULL known actor, re-derives actor_kind from admin_users.is_machine_actor, and writes one idempotent audit row. action must satisfy admin_audit_events_action_check (extended per wave).';


--
-- Name: risk_assess_paid_order(text, uuid, uuid, uuid, text, jsonb, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.risk_assess_paid_order(p_idempotency_key text, p_order_id uuid, p_payment_intent_id uuid, p_payment_event_id uuid, p_mode text, p_evaluation jsonb, p_subject_refs jsonb, p_evidence jsonb, p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'risk.assess_paid_order';
  v_request_fingerprint text;
  v_existing public.risk_idempotency_keys%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_assessment public.risk_assessments%ROWTYPE;
  v_case public.risk_manual_review_cases%ROWTYPE;
  v_hold public.commerce_order_holds%ROWTYPE;
  v_decision text := p_evaluation->>'decision';
  v_severity text := COALESCE(p_evaluation->>'severity', 'low');
  v_score integer := COALESCE((p_evaluation->>'score')::integer, 0);
  v_reason_codes text[];
  v_response jsonb;
  v_hold_opened boolean := false;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_order_id IS NULL
    OR p_mode NOT IN ('shadow', 'hold', 'checkout_blocklist')
    OR v_decision NOT IN ('allow', 'manual_review', 'block')
    OR v_severity NOT IN ('low', 'medium', 'high', 'critical')
    OR v_score < 0 OR v_score > 100
    OR p_subject_refs IS NULL OR jsonb_typeof(p_subject_refs) <> 'array'
    OR p_evidence IS NULL OR jsonb_typeof(p_evidence) <> 'object'
  THEN
    RAISE EXCEPTION 'risk_assess_paid_order_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(reason_code), ARRAY[]::text[])
    INTO v_reason_codes
    FROM jsonb_array_elements_text(COALESCE(p_evaluation->'reasonCodes', '[]'::jsonb)) AS reason_codes(reason_code);

  v_request_fingerprint := md5(
    p_order_id::text || '|' ||
    COALESCE(p_payment_intent_id::text, '') || '|' ||
    COALESCE(p_payment_event_id::text, '') || '|' ||
    p_mode || '|' ||
    p_evaluation::text || '|' ||
    p_subject_refs::text || '|' ||
    p_evidence::text || '|' ||
    COALESCE(p_occurred_at::text, '')
  );

  SELECT * INTO v_existing
    FROM public.risk_idempotency_keys
   WHERE scope = v_scope AND idempotency_key = p_idempotency_key
   FOR UPDATE;
  IF FOUND THEN
    IF v_existing.request_fingerprint = v_request_fingerprint AND v_existing.response_payload IS NOT NULL THEN
      RETURN jsonb_set(v_existing.response_payload, '{replayed}', 'true'::jsonb, false);
    END IF;
    RAISE EXCEPTION 'risk_assess_paid_order_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'risk_assess_paid_order_order_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_order.status NOT IN ('paid', 'fulfillment_pending', 'fulfilled') THEN
    RAISE EXCEPTION 'risk_assess_paid_order_not_paid' USING ERRCODE = '22023';
  END IF;

  IF p_payment_intent_id IS NOT NULL THEN
    SELECT * INTO v_intent
      FROM public.commerce_payment_intents
     WHERE id = p_payment_intent_id
       AND order_id = p_order_id
     FOR UPDATE;
  ELSE
    SELECT * INTO v_intent
      FROM public.commerce_payment_intents
     WHERE order_id = p_order_id
       AND status = 'succeeded'
     ORDER BY updated_at DESC
     LIMIT 1
     FOR UPDATE;
  END IF;
  IF NOT FOUND OR v_intent.status <> 'succeeded' THEN
    RAISE EXCEPTION 'risk_assess_paid_order_payment_not_succeeded' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.risk_assessments (
    order_id,
    client_id,
    payment_intent_id,
    payment_event_id,
    source,
    enforcement_mode,
    decision,
    severity,
    risk_score,
    reason_codes,
    subject_refs,
    matched_rules,
    evidence,
    idempotency_key,
    occurred_at
  )
  VALUES (
    p_order_id,
    v_order.client_id,
    v_intent.id,
    p_payment_event_id,
    'paid_order',
    p_mode,
    v_decision,
    v_severity,
    v_score,
    v_reason_codes,
    p_subject_refs,
    COALESCE(p_evaluation->'matchedRules', '[]'::jsonb),
    p_evidence,
    p_idempotency_key,
    COALESCE(p_occurred_at, now())
  )
  RETURNING * INTO v_assessment;

  IF p_mode = 'hold' AND v_decision IN ('manual_review', 'block') THEN
    SELECT * INTO v_hold
      FROM public.commerce_order_holds
     WHERE order_id = p_order_id
       AND reason = 'risk_review'
       AND status = 'active'
     FOR UPDATE;

    IF NOT FOUND THEN
      INSERT INTO public.commerce_order_holds (
        order_id,
        created_by,
        reason,
        note,
        idempotency_key,
        metadata
      )
      VALUES (
        p_order_id,
        NULL,
        'risk_review',
        'Risk review required',
        p_idempotency_key || ':risk-hold',
        jsonb_build_object('source', 'risk.v1', 'assessmentId', v_assessment.id)
      )
      RETURNING * INTO v_hold;
      v_hold_opened := true;

      INSERT INTO public.commerce_order_operations (
        order_id,
        hold_id,
        actor_user_id,
        operation_type,
        source,
        idempotency_key,
        payload
      )
      VALUES (
        p_order_id,
        v_hold.id,
        NULL,
        'hold_created',
        'risk.v1',
        p_idempotency_key || ':risk-hold-operation',
        jsonb_build_object('reason', 'risk_review', 'assessmentId', v_assessment.id)
      )
      ON CONFLICT (idempotency_key) DO NOTHING;
    END IF;

    SELECT * INTO v_case
      FROM public.risk_manual_review_cases
     WHERE order_id = p_order_id
       AND status IN ('open', 'in_review', 'escalated')
     FOR UPDATE;

    IF NOT FOUND THEN
      INSERT INTO public.risk_manual_review_cases (
        assessment_id,
        order_id,
        client_id,
        payment_intent_id,
        hold_id,
        status,
        decision,
        severity,
        risk_score,
        reason_codes,
        metadata
      )
      VALUES (
        v_assessment.id,
        p_order_id,
        v_order.client_id,
        v_intent.id,
        v_hold.id,
        'open',
        v_decision,
        v_severity,
        v_score,
        v_reason_codes,
        jsonb_build_object('source', 'risk.v1')
      )
      RETURNING * INTO v_case;

      INSERT INTO public.risk_case_events (
        case_id,
        event_type,
        actor_user_id,
        note,
        idempotency_key,
        payload
      )
      VALUES (
        v_case.id,
        'case_opened',
        NULL,
        NULL,
        p_idempotency_key || ':case-opened',
        jsonb_build_object('assessmentId', v_assessment.id, 'holdId', v_hold.id)
      );
    ELSE
      UPDATE public.risk_manual_review_cases
         SET assessment_id = v_assessment.id,
             hold_id = COALESCE(hold_id, v_hold.id),
             updated_at = now(),
             risk_score = GREATEST(risk_score, v_score),
             severity = CASE
               WHEN array_position(ARRAY['low','medium','high','critical'], v_severity) >
                    array_position(ARRAY['low','medium','high','critical'], severity)
               THEN v_severity ELSE severity END
       WHERE id = v_case.id
      RETURNING * INTO v_case;
    END IF;
  END IF;

  v_response := jsonb_build_object(
    'assessmentId', v_assessment.id,
    'caseId', CASE WHEN v_case.id IS NULL THEN NULL ELSE v_case.id END,
    'holdId', CASE WHEN v_hold.id IS NULL THEN NULL ELSE v_hold.id END,
    'decision', v_decision,
    'holdOpened', v_hold_opened,
    'replayed', false
  );

  INSERT INTO public.risk_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    response_payload
  )
  VALUES (v_scope, p_idempotency_key, v_request_fingerprint, v_response);

  RETURN v_response;
END;
$$;


--
-- Name: risk_check_exact_blocklist(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.risk_check_exact_blocklist(p_subject_refs jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_matches jsonb;
BEGIN
  IF p_subject_refs IS NULL OR jsonb_typeof(p_subject_refs) <> 'array' THEN
    RAISE EXCEPTION 'risk_blocklist_invalid_subject_refs' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'subjectKind', b.subject_kind,
    'reasonCode', b.reason_code
  ) ORDER BY b.subject_kind), '[]'::jsonb)
    INTO v_matches
    FROM jsonb_to_recordset(p_subject_refs) AS r("subjectKind" text, "subjectHash" text)
    JOIN public.risk_blocklist_entries b
      ON b.subject_kind = r."subjectKind"
     AND b.subject_hash = r."subjectHash"
     AND b.status = 'active'
     AND b.starts_at <= now()
     AND (b.expires_at IS NULL OR b.expires_at > now());

  RETURN jsonb_build_object(
    'blocked', jsonb_array_length(v_matches) > 0,
    'matches', v_matches,
    'reasonCodes', CASE WHEN jsonb_array_length(v_matches) > 0 THEN jsonb_build_array('exact_blocklist_match') ELSE '[]'::jsonb END
  );
END;
$$;


--
-- Name: risk_resolve_manual_review_case(text, uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.risk_resolve_manual_review_case(p_idempotency_key text, p_case_id uuid, p_decision text, p_actor_user_id uuid, p_note text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'risk.case.resolve';
  v_request_fingerprint text;
  v_existing public.risk_idempotency_keys%ROWTYPE;
  v_case public.risk_manual_review_cases%ROWTYPE;
  v_hold public.commerce_order_holds%ROWTYPE;
  v_response jsonb;
  v_event_type text;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_case_id IS NULL
    OR p_actor_user_id IS NULL
    OR p_decision NOT IN ('approve', 'block', 'escalate', 'note')
  THEN
    RAISE EXCEPTION 'risk_case_decision_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    p_case_id::text || '|' || p_decision || '|' || p_actor_user_id::text || '|' ||
    COALESCE(p_note, '') || '|' || COALESCE(p_metadata, '{}'::jsonb)::text
  );

  SELECT * INTO v_existing
    FROM public.risk_idempotency_keys
   WHERE scope = v_scope AND idempotency_key = p_idempotency_key
   FOR UPDATE;
  IF FOUND THEN
    IF v_existing.request_fingerprint = v_request_fingerprint AND v_existing.response_payload IS NOT NULL THEN
      RETURN jsonb_set(v_existing.response_payload, '{replayed}', 'true'::jsonb, false);
    END IF;
    RAISE EXCEPTION 'risk_case_decision_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT * INTO v_case
    FROM public.risk_manual_review_cases
   WHERE id = p_case_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'risk_case_not_found' USING ERRCODE = '22023';
  END IF;

  IF p_decision = 'approve' THEN
    UPDATE public.risk_manual_review_cases
       SET status = 'approved',
           resolution = 'approve',
           resolved_at = now(),
           resolved_by = p_actor_user_id,
           updated_at = now(),
           metadata = metadata || COALESCE(p_metadata, '{}'::jsonb)
     WHERE id = p_case_id
    RETURNING * INTO v_case;
    v_event_type := 'case_approved';

    IF v_case.hold_id IS NOT NULL THEN
      SELECT * INTO v_hold
        FROM public.commerce_order_holds
       WHERE id = v_case.hold_id
       FOR UPDATE;
      IF FOUND AND v_hold.status = 'active' THEN
        UPDATE public.commerce_order_holds
           SET status = 'released',
               released_at = now(),
               released_by = p_actor_user_id,
               updated_at = now(),
               metadata = metadata || jsonb_build_object('riskCaseId', v_case.id, 'riskResolution', 'approve')
         WHERE id = v_hold.id
        RETURNING * INTO v_hold;

        INSERT INTO public.commerce_order_operations (
          order_id, hold_id, actor_user_id, operation_type, source, idempotency_key, payload
        )
        VALUES (
          v_hold.order_id,
          v_hold.id,
          p_actor_user_id,
          'hold_released',
          'risk.v1',
          p_idempotency_key || ':hold-release-operation',
          jsonb_build_object('reason', 'risk_review', 'caseId', v_case.id, 'note', p_note)
        )
        ON CONFLICT (idempotency_key) DO NOTHING;
      END IF;
    END IF;
  ELSIF p_decision = 'block' THEN
    UPDATE public.risk_manual_review_cases
       SET status = 'blocked',
           resolution = 'block',
           resolved_at = now(),
           resolved_by = p_actor_user_id,
           updated_at = now(),
           metadata = metadata || COALESCE(p_metadata, '{}'::jsonb)
     WHERE id = p_case_id
    RETURNING * INTO v_case;
    v_event_type := 'case_blocked';
  ELSIF p_decision = 'escalate' THEN
    UPDATE public.risk_manual_review_cases
       SET status = 'escalated',
           resolution = 'escalate',
           resolved_by = p_actor_user_id,
           updated_at = now(),
           metadata = metadata || COALESCE(p_metadata, '{}'::jsonb)
     WHERE id = p_case_id
    RETURNING * INTO v_case;
    v_event_type := 'case_escalated';
  ELSE
    UPDATE public.risk_manual_review_cases
       SET updated_at = now()
     WHERE id = p_case_id
    RETURNING * INTO v_case;
    v_event_type := 'case_note';
  END IF;

  INSERT INTO public.risk_case_events (
    case_id,
    event_type,
    actor_user_id,
    note,
    idempotency_key,
    payload
  )
  VALUES (
    p_case_id,
    v_event_type,
    p_actor_user_id,
    p_note,
    p_idempotency_key || ':event',
    COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (idempotency_key) DO NOTHING;

  v_response := jsonb_build_object(
    'caseId', v_case.id,
    'status', v_case.status,
    'decision', p_decision,
    'holdId', v_case.hold_id,
    'replayed', false
  );

  INSERT INTO public.risk_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    response_payload
  )
  VALUES (v_scope, p_idempotency_key, v_request_fingerprint, v_response);

  RETURN v_response;
END;
$$;


--
-- Name: submit_feedback_by_hash(text, integer, integer, integer, integer, boolean, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_feedback_by_hash(p_hash text, p_overall_rating integer DEFAULT NULL::integer, p_taste_rating integer DEFAULT NULL::integer, p_texture_rating integer DEFAULT NULL::integer, p_digestion_rating integer DEFAULT NULL::integer, p_would_recommend boolean DEFAULT NULL::boolean, p_favorite_flavor text DEFAULT NULL::text, p_open_feedback text DEFAULT NULL::text, p_photo_urls text[] DEFAULT NULL::text[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  UPDATE public.feedback
  SET 
    overall_rating = COALESCE(p_overall_rating, overall_rating),
    taste_rating = COALESCE(p_taste_rating, taste_rating),
    texture_rating = COALESCE(p_texture_rating, texture_rating),
    digestion_rating = COALESCE(p_digestion_rating, digestion_rating),
    would_recommend = COALESCE(p_would_recommend, would_recommend),
    favorite_flavor = COALESCE(p_favorite_flavor, favorite_flavor),
    open_feedback = COALESCE(p_open_feedback, open_feedback),
    photo_urls = COALESCE(p_photo_urls, photo_urls),
    submitted_at = COALESCE(submitted_at, now()),
    updated_at = now()
  WHERE hash = p_hash;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Feedback not found';
  END IF;

  RETURN 'success';
END;
$$;


