--
-- Name: submit_order_feedback(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_order_feedback(p_token text, p_rating integer, p_comment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_row public.commerce_order_feedback%ROWTYPE;
  v_comment text;
BEGIN
  IF p_token IS NULL OR btrim(p_token) = '' THEN
    RAISE EXCEPTION 'order_feedback_invalid_token' USING ERRCODE = '22023';
  END IF;
  IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN
    RAISE EXCEPTION 'order_feedback_invalid_rating' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_row
    FROM public.commerce_order_feedback
   WHERE token = p_token OR effect_token = p_token
   FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not_found');
  END IF;

  -- Trim + cap the free-text comment; empty becomes NULL.
  v_comment := NULLIF(btrim(COALESCE(p_comment, '')), '');
  IF v_comment IS NOT NULL THEN
    v_comment := left(v_comment, 2000);
  END IF;

  IF v_row.token = p_token THEN
    IF v_row.submitted_at IS NOT NULL THEN
      RETURN jsonb_build_object('status', 'already_submitted');
    END IF;
    UPDATE public.commerce_order_feedback
       SET rating = p_rating, comment = v_comment, submitted_at = now()
     WHERE id = v_row.id;
  ELSE
    IF v_row.effect_submitted_at IS NOT NULL THEN
      RETURN jsonb_build_object('status', 'already_submitted');
    END IF;
    UPDATE public.commerce_order_feedback
       SET effect_rating = p_rating, effect_comment = v_comment, effect_submitted_at = now()
     WHERE id = v_row.id;
  END IF;

  RETURN jsonb_build_object('status', 'submitted');
END;
$$;


--
-- Name: FUNCTION submit_order_feedback(p_token text, p_rating integer, p_comment text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.submit_order_feedback(p_token text, p_rating integer, p_comment text) IS 'Public anon RPC: submit a 1-5 rating + optional comment by review token. Idempotent (no-op once submitted); never exposes the row.';


