--
-- Name: subscribe_product_stock_notification(text, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscribe_product_stock_notification(p_sku text, p_email text, p_contact_id uuid DEFAULT NULL::uuid, p_consent_decision_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_sku text := btrim(coalesce(p_sku, ''));
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_id uuid;
BEGIN
  IF v_sku = '' THEN
    RAISE EXCEPTION 'stock_notification_invalid_sku' USING ERRCODE = '22023';
  END IF;
  IF v_email = '' OR position('@' in v_email) <= 1 THEN
    RAISE EXCEPTION 'stock_notification_invalid_email' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_product_stock_notifications (
    sku, email, contact_id, consent_decision_id, metadata
  )
  VALUES (
    v_sku, v_email, p_contact_id, p_consent_decision_id, coalesce(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (sku, email) WHERE closed_at IS NULL DO UPDATE
    SET contact_id = coalesce(EXCLUDED.contact_id, public.commerce_product_stock_notifications.contact_id),
        consent_decision_id = coalesce(EXCLUDED.consent_decision_id, public.commerce_product_stock_notifications.consent_decision_id),
        metadata = public.commerce_product_stock_notifications.metadata || EXCLUDED.metadata
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


--
-- Name: subscription_activate_from_paid_checkout_order(text, uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_activate_from_paid_checkout_order(p_idempotency_key text, p_order_id uuid, p_payment_intent_id uuid, p_payment_method_ref text, p_payment_method_kind text, p_paid_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'subscription.initial_activation';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_quote_context jsonb;
  v_subscription_id uuid;
  v_cadence_days integer;
  v_size_constraint jsonb;
  v_next_cycle_at timestamptz;
  v_template_lines jsonb;
  v_response jsonb;
  v_line record;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_order_id IS NULL
    OR p_payment_intent_id IS NULL
    OR p_payment_method_ref IS NULL OR btrim(p_payment_method_ref) = ''
    OR p_payment_method_kind IS NULL OR btrim(p_payment_method_kind) = ''
    OR p_paid_at IS NULL
  THEN
    RAISE EXCEPTION 'subscription_activation_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    p_order_id::text || '|' ||
    p_payment_intent_id::text || '|' ||
    p_payment_method_ref || '|' ||
    p_payment_method_kind || '|' ||
    p_paid_at::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{subscriptionActivation,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'subscription_activation_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_activation_order_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_activation_payment_intent_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_intent.order_id IS DISTINCT FROM p_order_id OR v_intent.status <> 'succeeded' THEN
    RAISE EXCEPTION 'subscription_activation_payment_not_succeeded' USING ERRCODE = '22023';
  END IF;

  IF v_intent.target_kind <> 'one_time_order' THEN
    RAISE EXCEPTION 'subscription_activation_invalid_payment_target' USING ERRCODE = '22023';
  END IF;

  IF v_order.status <> 'paid' THEN
    RAISE EXCEPTION 'subscription_activation_order_not_paid' USING ERRCODE = '22023';
  END IF;

  IF v_order.client_id IS NULL OR v_order.pet_id IS NULL OR v_order.shipping_address_id IS NULL THEN
    RAISE EXCEPTION 'subscription_activation_missing_client_pet_or_address' USING ERRCODE = '22023';
  END IF;

  IF v_order.subscription_id IS NOT NULL THEN
    RAISE EXCEPTION 'subscription_activation_order_already_linked' USING ERRCODE = '23505';
  END IF;

  v_quote_context := v_order.metadata#>'{quoteSnapshot,quote,context}';
  IF COALESCE(v_quote_context->>'mode', v_order.metadata->>'checkoutIntent', v_order.metadata#>>'{runtimeFinalize,checkoutIntent}') NOT IN ('subscription', 'subscription_initial') THEN
    RAISE EXCEPTION 'subscription_activation_not_subscription_checkout' USING ERRCODE = '22023';
  END IF;

  v_cadence_days := NULLIF(v_quote_context->>'cadenceDays', '')::integer;
  IF v_cadence_days IS NULL OR v_cadence_days < 1 THEN
    RAISE EXCEPTION 'subscription_activation_missing_cadence' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'variant_id', ranked.sku_id,
        'qty', ranked.quantity,
        'sort_order', ranked.sort_order,
        'is_addon', false
      )
      ORDER BY ranked.sort_order
    ),
    '[]'::jsonb
  )
    INTO v_template_lines
    FROM (
      SELECT
        item.sku_id,
        item.quantity,
        (row_number() OVER (ORDER BY item.created_at, item.id) - 1)::integer AS sort_order
      FROM public.commerce_order_items item
      WHERE item.order_id = v_order.id
        AND item.sku_id IS NOT NULL
    ) ranked;

  IF jsonb_array_length(v_template_lines) = 0 THEN
    RAISE EXCEPTION 'subscription_activation_missing_finalized_lines' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'subscription_activate_from_paid_checkout_order')
  );

  v_next_cycle_at := p_paid_at + (v_cadence_days * interval '1 day');
  v_size_constraint := COALESCE(v_quote_context->'sizeConstraint', v_order.size_constraint);

  INSERT INTO public.subscriptions (
    client_id,
    pet_id,
    cadence_days,
    size_constraint,
    currency,
    region_code,
    status,
    next_cycle_at,
    started_at,
    edit_window_hours,
    shipping_address_id,
    billing_address_id,
    payment_method_ref,
    payment_method_kind,
    timezone
  )
  VALUES (
    v_order.client_id,
    v_order.pet_id,
    v_cadence_days,
    v_size_constraint,
    v_order.currency,
    v_order.region_code,
    'active',
    v_next_cycle_at,
    p_paid_at,
    72,
    v_order.shipping_address_id,
    v_order.shipping_address_id,
    p_payment_method_ref,
    p_payment_method_kind,
    'Europe/Warsaw'
  )
  RETURNING id INTO v_subscription_id;

  FOR v_line IN
    SELECT
      item.id AS order_item_id,
      item.sku_id,
      item.quantity,
      item.product_snapshot,
      (row_number() OVER (ORDER BY item.created_at, item.id) - 1)::integer AS sort_order
    FROM public.commerce_order_items item
    WHERE item.order_id = v_order.id
      AND item.sku_id IS NOT NULL
    ORDER BY item.created_at, item.id
  LOOP
    INSERT INTO public.subscription_lines (
      subscription_id,
      variant_id,
      qty,
      sort_order,
      is_addon,
      line_metadata,
      template_version
    )
    VALUES (
      v_subscription_id,
      v_line.sku_id,
      v_line.quantity,
      v_line.sort_order,
      false,
      jsonb_build_object(
        'initialOrderId', v_order.id,
        'initialOrderItemId', v_line.order_item_id,
        'productSnapshot', v_line.product_snapshot,
        'source', 'subscription.activation.hidden.v0'
      ),
      1
    );

    UPDATE public.commerce_order_items
       SET mode_at_line = 'subscription',
           product_snapshot = product_snapshot || jsonb_build_object('subscriptionId', v_subscription_id)
     WHERE id = v_line.order_item_id;
  END LOOP;

  UPDATE public.commerce_orders
     SET subscription_id = v_subscription_id,
         metadata = metadata || jsonb_build_object(
           'checkoutIntent', 'subscription_initial',
           'subscriptionActivation', jsonb_build_object(
             'subscriptionId', v_subscription_id,
             'paymentIntentId', p_payment_intent_id,
             'paymentMethodKind', p_payment_method_kind,
             'paidAt', p_paid_at,
             'nextCycleAt', v_next_cycle_at,
             'source', 'subscription.activation.hidden.v0'
           )
         ),
         updated_at = now()
   WHERE id = v_order.id;

  INSERT INTO public.subscription_events (
    subscription_id,
    event_type,
    idempotency_key,
    payload,
    occurred_at
  )
  VALUES (
    v_subscription_id,
    'subscription.created',
    p_idempotency_key || ':subscription_created',
    jsonb_build_object(
      'orderId', v_order.id,
      'paymentIntentId', p_payment_intent_id,
      'paymentMethodKind', p_payment_method_kind,
      'template', jsonb_build_object(
        'cadence_days', v_cadence_days,
        'size_constraint', v_size_constraint,
        'currency', v_order.currency,
        'region_code', v_order.region_code,
        'pet_id', v_order.pet_id,
        'edit_window_hours', 72,
        'lines', v_template_lines
      ),
      'nextCycleAt', v_next_cycle_at,
      'source', 'subscription.activation.hidden.v0'
    ),
    p_paid_at
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'subscriptionActivation', jsonb_build_object(
      'subscriptionId', v_subscription_id,
      'orderId', v_order.id,
      'paymentIntentId', p_payment_intent_id,
      'status', 'active',
      'nextCycleAt', v_next_cycle_at,
      'cadenceDays', v_cadence_days,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object(
           'subscriptionId', v_subscription_id,
           'orderId', v_order.id,
           'paymentIntentId', p_payment_intent_id
         )
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: subscription_apply_cycle_order_shipping_address(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_apply_cycle_order_shipping_address() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_shipping_address_id uuid;
BEGIN
  IF NEW.shipping_address_id IS NULL
    AND NEW.subscription_id IS NOT NULL
    AND NEW.mode = 'subscription_cycle'
  THEN
    SELECT shipping_address_id
      INTO v_shipping_address_id
      FROM public.subscriptions
     WHERE id = NEW.subscription_id;
    IF v_shipping_address_id IS NOT NULL THEN
      NEW.shipping_address_id := v_shipping_address_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


