--
-- Name: subscription_apply_starter_graduation(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_apply_starter_graduation(p_subscription_id uuid, p_idempotency_key text, p_mode text DEFAULT 'full'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_subscription public.subscriptions%ROWTYPE;
  v_marker jsonb;
  v_graduation jsonb;
  v_cadence_days integer;
  v_starter_interval integer;
  v_basis_template_version integer;
  v_next_template_version integer;
  v_open_cycles integer;
  v_line jsonb;
  v_line_ordinal integer;
  v_quote_line jsonb;
  v_variant_id uuid;
  v_line_id uuid;
  v_unit_price integer;
  v_event_id uuid;
  v_now constant timestamptz := now();
BEGIN
  IF p_subscription_id IS NULL
    OR p_idempotency_key IS NULL
    OR btrim(p_idempotency_key) = ''
  THEN
    RAISE EXCEPTION 'subscription_starter_graduation_invalid_input' USING ERRCODE = '22023';
  END IF;
  IF p_mode NOT IN ('full', 'cadence_only') THEN
    RAISE EXCEPTION 'subscription_starter_graduation_invalid_mode' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
   FOR UPDATE;

  IF NOT FOUND OR v_subscription.starter_pack IS NULL THEN
    RETURN jsonb_build_object(
      'contractVersion', 'subscription.starter_graduation.v1',
      'starterGraduation', jsonb_build_object(
        'subscriptionId', p_subscription_id, 'mode', p_mode, 'applied', false,
        'reason', 'not_a_starter_subscription',
        'templateVersion', NULL, 'cadenceDays', NULL
      )
    );
  END IF;

  SELECT count(*)::integer INTO v_open_cycles
    FROM public.subscription_cycles
   WHERE subscription_id = p_subscription_id
     AND status IN ('payment_pending', 'retry_scheduled');
  IF v_open_cycles > 0 THEN
    RAISE EXCEPTION 'subscription_starter_graduation_open_cycle'
      USING
        ERRCODE = '22023',
        DETAIL = 'Subscription ' || p_subscription_id::text || ' has ' || v_open_cycles::text
          || ' cycle(s) in payment_pending or retry_scheduled.',
        HINT = 'Settle or terminalize the open cycle before graduating the template.';
  END IF;

  v_marker := v_subscription.starter_pack;
  v_graduation := v_marker->'graduation';
  v_basis_template_version := (v_marker->>'basisTemplateVersion')::integer;
  v_starter_interval := (v_marker->>'starterIntervalDays')::integer;
  v_cadence_days := (v_graduation->>'cadenceDays')::integer;

  IF p_mode = 'cadence_only' THEN
    IF v_subscription.cadence_days IS DISTINCT FROM v_starter_interval
      OR v_subscription.cadence_days IN (14, 21, 28)
    THEN
      RETURN jsonb_build_object(
        'contractVersion', 'subscription.starter_graduation.v1',
        'starterGraduation', jsonb_build_object(
          'subscriptionId', p_subscription_id, 'mode', p_mode, 'applied', false,
          'reason', 'cadence_already_normal',
          'templateVersion', v_subscription.template_version,
          'cadenceDays', v_subscription.cadence_days
        )
      );
    END IF;
    IF v_cadence_days IS NULL OR v_cadence_days NOT IN (14, 28) THEN
      RAISE EXCEPTION 'subscription_starter_graduation_invalid_cadence' USING ERRCODE = '22023';
    END IF;

    UPDATE public.subscriptions
       SET cadence_days = v_cadence_days,
           template_version = template_version + 1,
           updated_at = v_now
     WHERE id = p_subscription_id
     RETURNING * INTO v_subscription;

    INSERT INTO public.subscription_events (
      subscription_id, event_type, idempotency_key, payload, occurred_at
    )
    VALUES (
      p_subscription_id,
      'subscription.starter_cadence_normalized',
      p_idempotency_key,
      jsonb_build_object(
        'mode', p_mode,
        'starterIntervalDays', v_starter_interval,
        'cadenceDays', v_cadence_days,
        'basisTemplateVersion', v_basis_template_version,
        'templateVersion', v_subscription.template_version
      ),
      v_now
    );

    RETURN jsonb_build_object(
      'contractVersion', 'subscription.starter_graduation.v1',
      'starterGraduation', jsonb_build_object(
        'subscriptionId', p_subscription_id, 'mode', p_mode, 'applied', true,
        'reason', 'cadence_normalized',
        'templateVersion', v_subscription.template_version,
        'cadenceDays', v_subscription.cadence_days
      )
    );
  END IF;

  -- p_mode = 'full'
  IF v_subscription.template_version IS DISTINCT FROM v_basis_template_version THEN
    RETURN jsonb_build_object(
      'contractVersion', 'subscription.starter_graduation.v1',
      'starterGraduation', jsonb_build_object(
        'subscriptionId', p_subscription_id, 'mode', p_mode, 'applied', false,
        'reason', 'template_version_moved',
        'templateVersion', v_subscription.template_version,
        'cadenceDays', v_subscription.cadence_days
      )
    );
  END IF;
  IF v_cadence_days IS NULL OR v_cadence_days NOT IN (14, 28) THEN
    RAISE EXCEPTION 'subscription_starter_graduation_invalid_cadence' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_graduation->'lines') <> 'array'
    OR jsonb_array_length(v_graduation->'lines') = 0
  THEN
    RAISE EXCEPTION 'subscription_starter_graduation_invalid_lines' USING ERRCODE = '22023';
  END IF;

  UPDATE public.subscriptions
     SET cadence_days = v_cadence_days,
         size_constraint = CASE
           WHEN jsonb_typeof(v_graduation->'sizeConstraint') = 'object'
             THEN v_graduation->'sizeConstraint'
           ELSE size_constraint
         END,
         template_version = template_version + 1,
         updated_at = v_now
   WHERE id = p_subscription_id
   RETURNING * INTO v_subscription;
  v_next_template_version := v_subscription.template_version;

  DELETE FROM public.subscription_lines
   WHERE subscription_id = p_subscription_id
     AND is_addon = false;

  FOR v_line, v_line_ordinal IN
    SELECT value, ordinality::integer
      FROM jsonb_array_elements(v_graduation->'lines') WITH ORDINALITY
  LOOP
    SELECT id INTO v_variant_id
      FROM public.catalog_skus
     WHERE sku = v_line->>'sku'
     LIMIT 1;
    IF v_variant_id IS NULL THEN
      RAISE EXCEPTION 'subscription_starter_graduation_unknown_sku: %', v_line->>'sku'
        USING ERRCODE = '22023';
    END IF;

    v_quote_line := COALESCE(v_line->'quoteLine', '{}'::jsonb);
    INSERT INTO public.subscription_lines (
      subscription_id, variant_id, qty, sort_order, is_addon, template_version, line_metadata
    )
    VALUES (
      p_subscription_id,
      v_variant_id,
      (v_line->>'qty')::integer,
      COALESCE((v_line->>'sortOrder')::integer, v_line_ordinal - 1),
      COALESCE((v_line->>'isAddon')::boolean, false),
      v_next_template_version,
      jsonb_build_object(
        'productSnapshot', jsonb_build_object('quoteLine', v_quote_line),
        'source', 'starter_graduation'
      )
    )
    RETURNING id INTO v_line_id;

    v_unit_price := CASE
      WHEN (v_quote_line #>> '{unitPriceGross,amountMinor}') ~ '^[0-9]+$'
        THEN (v_quote_line #>> '{unitPriceGross,amountMinor}')::integer
      WHEN (v_quote_line->>'unitGrossMinor') ~ '^[0-9]+$'
        THEN (v_quote_line->>'unitGrossMinor')::integer
      ELSE NULL
    END;
    INSERT INTO public.subscription_price_agreements (
      subscription_id, subscription_line_id, variant_id, currency, unit_price_gross_minor,
      quote_line, template_version, source_action, idempotency_key, started_at
    )
    VALUES (
      p_subscription_id, v_line_id, v_variant_id, v_subscription.currency, v_unit_price,
      v_quote_line, v_next_template_version, 'starter_graduation', p_idempotency_key, v_now
    )
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.subscription_events (
    subscription_id, event_type, idempotency_key, payload, occurred_at
  )
  VALUES (
    p_subscription_id,
    'subscription.starter_graduated',
    p_idempotency_key,
    jsonb_build_object(
      'mode', p_mode,
      'starterIntervalDays', v_starter_interval,
      'cadenceDays', v_cadence_days,
      'basisTemplateVersion', v_basis_template_version,
      'templateVersion', v_next_template_version,
      'lineCount', jsonb_array_length(v_graduation->'lines'),
      'priceAgreementPolicy', jsonb_build_object(
        'kind', 'lock_until_edit', 'proration', 'none',
        'cycleEffect', 'future_unlocked_cycles_only'
      )
    ),
    v_now
  )
  RETURNING id INTO v_event_id;

  UPDATE public.subscription_price_agreements
     SET event_id = v_event_id, updated_at = v_now
   WHERE subscription_id = p_subscription_id
     AND idempotency_key = p_idempotency_key;

  RETURN jsonb_build_object(
    'contractVersion', 'subscription.starter_graduation.v1',
    'starterGraduation', jsonb_build_object(
      'subscriptionId', p_subscription_id, 'mode', p_mode, 'applied', true,
      'reason', 'graduated',
      'templateVersion', v_next_template_version,
      'cadenceDays', v_cadence_days
    )
  );
END;
$_$;


--
-- Name: FUNCTION subscription_apply_starter_graduation(p_subscription_id uuid, p_idempotency_key text, p_mode text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_apply_starter_graduation(p_subscription_id uuid, p_idempotency_key text, p_mode text) IS 'Applies the starter-pack graduation stored in subscriptions.starter_pack. Mode full rewrites the non-addon template lines and flips cadence to the steady value; mode cadence_only normalizes cadence alone. Both modes are idempotent by construction and raise when an open payment cycle would be rewritten underneath.';


--
-- Name: subscription_auto_resume_due(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_auto_resume_due(p_limit integer DEFAULT 100, p_now timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scanned integer := 0;
  v_resumed integer := 0;
  v_skipped integer := 0;
  v_failed integer := 0;
  v_row record;
  v_subscription public.subscriptions%ROWTYPE;
  v_next_cycle_at timestamptz;
  v_event_id uuid;
  v_idempotency_key text;
BEGIN
  FOR v_row IN
    SELECT pw.id AS pause_window_id, pw.subscription_id, pw.pause_preset, pw.ends_at
    FROM public.subscription_pause_windows pw
    JOIN public.subscriptions s ON s.id = pw.subscription_id
    WHERE pw.resumed_at IS NULL
      AND pw.ends_at IS NOT NULL
      AND pw.ends_at <= p_now
      AND s.status = 'paused'
    ORDER BY pw.ends_at, pw.id
    FOR UPDATE OF pw SKIP LOCKED
    LIMIT GREATEST(COALESCE(p_limit, 0), 0)
  LOOP
    v_scanned := v_scanned + 1;
    BEGIN
      SELECT *
      INTO v_subscription
      FROM public.subscriptions
      WHERE id = v_row.subscription_id
      FOR UPDATE;

      IF NOT FOUND
        OR v_subscription.status <> 'paused'
        OR v_subscription.payment_method_kind IS NULL
        OR btrim(COALESCE(v_subscription.payment_method_kind, '')) = ''
        OR v_subscription.payment_method_ref IS NULL
        OR btrim(COALESCE(v_subscription.payment_method_ref, '')) = ''
        OR v_subscription.next_cycle_at IS NULL
        OR COALESCE(v_subscription.cadence_days, 0) <= 0
        OR NOT EXISTS (
          SELECT 1
          FROM public.subscription_lines sl
          WHERE sl.subscription_id = v_row.subscription_id
        )
        OR EXISTS (
          SELECT 1
          FROM public.subscription_dunning_cases dc
          WHERE dc.subscription_id = v_row.subscription_id
            AND dc.status = 'open'
        )
        OR EXISTS (
          SELECT 1
          FROM public.subscription_cycles c
          WHERE c.subscription_id = v_row.subscription_id
            AND c.scheduled_at = v_subscription.next_cycle_at
            AND c.status = 'paid'
        )
        -- Any cycle in the statuses that hide the subscription from
        -- subscription_list_due_for_renewal, at any scheduled_at. Promoting
        -- past one of these produces an `active` row no renewal lane will ever
        -- list.
        OR EXISTS (
          SELECT 1
          FROM public.subscription_cycles c
          WHERE c.subscription_id = v_row.subscription_id
            AND c.status IN ('payment_pending', 'retry_scheduled', 'payment_failed')
        )
        OR EXISTS (
          SELECT 1
          FROM public.commerce_orders o
          LEFT JOIN public.subscription_cycles c ON c.id = o.subscription_cycle_id
          WHERE o.subscription_id = v_row.subscription_id
            AND o.status IN ('paid', 'fulfillment_pending', 'fulfilled')
            AND (
              o.subscription_cycle_id IS NULL
              OR c.scheduled_at = v_subscription.next_cycle_at
              OR c.status IN ('payment_pending', 'paid')
            )
        )
      THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      v_next_cycle_at := v_subscription.next_cycle_at;
      IF v_next_cycle_at <= p_now THEN
        v_next_cycle_at := v_next_cycle_at + ((
          floor(extract(epoch FROM (p_now - v_next_cycle_at)) / (v_subscription.cadence_days * 86400.0))::bigint + 1
        ) * v_subscription.cadence_days || ' days')::interval;
      END IF;

      v_idempotency_key := 'subscription_auto_resume:' || v_row.pause_window_id::text;

      INSERT INTO public.subscription_events (
        subscription_id,
        event_type,
        idempotency_key,
        payload,
        occurred_at
      )
      VALUES (
        v_row.subscription_id,
        'subscription.system.auto_resume',
        v_idempotency_key,
        jsonb_build_object(
          'action', 'auto_resume',
          'pauseWindowId', v_row.pause_window_id,
          'pausePreset', v_row.pause_preset,
          'resumeAt', v_row.ends_at,
          'nextCycleAt', v_next_cycle_at,
          'policy', jsonb_build_object(
            'requiresPaymentMethod', true,
            'blocksOpenDunning', true,
            'blocksLockedUpcomingCycle', true
          )
        ),
        p_now
      )
      ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING
      RETURNING id INTO v_event_id;

      UPDATE public.subscriptions
      SET status = 'active',
          next_cycle_at = v_next_cycle_at,
          updated_at = p_now
      WHERE id = v_row.subscription_id;

      UPDATE public.subscription_pause_windows
      SET resumed_at = p_now,
          updated_at = p_now,
          event_id = COALESCE(v_event_id, event_id)
      WHERE id = v_row.pause_window_id
        AND resumed_at IS NULL;

      v_resumed := v_resumed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', v_failed = 0,
    'scanned', v_scanned,
    'resumed', v_resumed,
    'skipped', v_skipped,
    'failed', v_failed
  );
END;
$$;


--
-- Name: FUNCTION subscription_auto_resume_due(p_limit integer, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_auto_resume_due(p_limit integer, p_now timestamp with time zone) IS 'Auto-resumes due timed pauses only when the subscription is still paused, has at least one subscription line, has a payment method, has no open dunning case, holds no cycle in payment_pending/retry_scheduled/payment_failed at any scheduled_at, and has no paid cycle or paid/fulfilling order on the upcoming date. The cycle-status test is subscription_list_due_for_renewal''s own exclusion, so the cron never promotes a subscription that lane could not list.';


--
-- Name: subscription_confirm_provisional_from_paid_cycle(text, uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_confirm_provisional_from_paid_cycle(p_idempotency_key text, p_order_id uuid, p_payment_intent_id uuid, p_payment_method_ref text, p_payment_method_kind text, p_paid_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_next_cycle_at timestamptz;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
     OR p_order_id IS NULL OR p_payment_intent_id IS NULL OR p_paid_at IS NULL THEN
    RAISE EXCEPTION 'subscription_confirm_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_confirm_order_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_order.mode <> 'subscription_cycle'
     OR v_order.subscription_id IS NULL
     OR v_order.subscription_cycle_id IS NULL THEN
    RAISE EXCEPTION 'subscription_confirm_order_not_subscription_cycle' USING ERRCODE = '22023';
  END IF;
  IF v_order.status <> 'paid' THEN
    RAISE EXCEPTION 'subscription_confirm_order_not_paid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id;
  IF NOT FOUND OR v_intent.order_id IS DISTINCT FROM p_order_id THEN
    RAISE EXCEPTION 'subscription_confirm_payment_intent_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_intent.target_kind <> 'subscription_cycle' OR v_intent.status <> 'succeeded' THEN
    RAISE EXCEPTION 'subscription_confirm_payment_not_succeeded' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_subscription
    FROM public.subscriptions
   WHERE id = v_order.subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_confirm_subscription_not_found' USING ERRCODE = '22023';
  END IF;

  -- Idempotent replay: already confirmed by an earlier (possibly redelivered) event.
  IF v_subscription.status = 'active' THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'subscriptionConfirmation', jsonb_build_object(
        'subscriptionId', v_subscription.id,
        'orderId', p_order_id,
        'status', 'active',
        'nextCycleAt', v_subscription.next_cycle_at,
        'replayed', true
      )
    );
  END IF;

  IF v_subscription.status <> 'pending_activation' THEN
    RAISE EXCEPTION 'subscription_confirm_invalid_status: %', v_subscription.status USING ERRCODE = '22023';
  END IF;

  -- Mandate not yet bound (Stripe reusable method / Tpay PAYID alias may arrive in a
  -- SEPARATE, later webhook than payment.succeeded). Do NOT activate; leave the
  -- subscription provisional so the mandate event re-invokes confirm and completes it.
  -- This is the awaiting_mandate interstitial, expressed without a new status.
  IF p_payment_method_ref IS NULL OR btrim(p_payment_method_ref) = '' THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'subscriptionConfirmation', jsonb_build_object(
        'subscriptionId', v_subscription.id,
        'orderId', p_order_id,
        'status', 'awaiting_mandate',
        'replayed', false
      )
    );
  END IF;

  v_next_cycle_at := p_paid_at + (v_subscription.cadence_days * interval '1 day');

  UPDATE public.subscriptions
     SET status = 'active',
         started_at = p_paid_at,
         payment_method_ref = p_payment_method_ref,
         payment_method_kind = p_payment_method_kind,
         next_cycle_at = v_next_cycle_at,
         updated_at = now()
   WHERE id = v_subscription.id;

  -- OBS-1 / CJ01-T fix: mirror the client-scoped payment_method_ref row (if any)
  -- onto subscription scope now that the subscription is confirmed active.
  -- `provider_method_ref` is UNIQUE per provider (20260606160000), so this can
  -- match at most one row. A miss is silently accepted — activation must not
  -- fail because no matching ref row exists.
  UPDATE public.commerce_payment_method_refs
     SET subscription_id = v_subscription.id,
         updated_at = now()
   WHERE provider_method_ref = p_payment_method_ref
     AND method_kind = p_payment_method_kind
     AND active = true
     AND subscription_id IS NULL;

  INSERT INTO public.subscription_events (
    subscription_id, cycle_id, event_type, idempotency_key, payload, occurred_at
  )
  VALUES (
    v_subscription.id,
    v_order.subscription_cycle_id,
    'subscription.activated',
    p_idempotency_key || ':subscription_activated',
    jsonb_build_object(
      'orderId', p_order_id,
      'paymentIntentId', p_payment_intent_id,
      'paymentMethodRef', p_payment_method_ref,
      'paymentMethodKind', p_payment_method_kind,
      'nextCycleAt', v_next_cycle_at,
      'source', 'subscription.confirm.v0'
    ),
    p_paid_at
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'subscriptionConfirmation', jsonb_build_object(
      'subscriptionId', v_subscription.id,
      'orderId', p_order_id,
      'status', 'active',
      'nextCycleAt', v_next_cycle_at,
      'replayed', false
    )
  );
END;
$$;


--
-- Name: subscription_create_cycle_order_with_outbox(text, uuid, integer, timestamp with time zone, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_create_cycle_order_with_outbox(p_idempotency_key text, p_subscription_id uuid, p_cycle_number integer, p_scheduled_at timestamp with time zone, p_template_snapshot jsonb, p_pricing_snapshot jsonb, p_order_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_scope constant text := 'subscription.cycle_order.create';
  v_payment_event_type constant text := 'commerce.subscription_payment.requested';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_cycle_id uuid;
  v_order_id uuid;
  v_payment_id uuid;
  v_response jsonb;
  v_totals jsonb;
  v_order_currencies text[];
  v_currency text;
  v_line jsonb;
  v_line_ordinal integer;
  v_sku_id uuid;
  v_line_total bigint;
  v_line_net bigint;
  v_line_vat bigint;
  v_line_rate integer;
  v_line_sum numeric := 0;
  v_line_net_sum numeric := 0;
  v_frozen_rate integer;
  v_quote_expected_net bigint;
  v_expected_net bigint;
  v_line_totals integer[];
  v_allocations integer[];
  v_subtotal bigint;
  v_discount bigint;
  v_shipping bigint;
  v_shipping_discount bigint;
  v_net_total bigint;
  v_tax bigint;
  v_total bigint;
  v_effective integer;
BEGIN
  IF p_idempotency_key IS NULL
    OR btrim(p_idempotency_key) = ''
    OR length(p_idempotency_key) < 8
  THEN
    RAISE EXCEPTION 'subscription_cycle_order_invalid_idempotency_key'
      USING ERRCODE = '22023';
  END IF;

  IF p_subscription_id IS NULL
    OR p_cycle_number IS NULL
    OR p_cycle_number < 1
    OR p_scheduled_at IS NULL
  THEN
    RAISE EXCEPTION 'subscription_cycle_order_invalid_identity'
      USING ERRCODE = '22023';
  END IF;

  IF p_template_snapshot IS NULL
    OR jsonb_typeof(p_template_snapshot) <> 'object'
    OR p_template_snapshot->>'cadence_days' IS NULL
    OR (p_template_snapshot->>'cadence_days')::integer < 1
    OR jsonb_typeof(p_template_snapshot->'lines') <> 'array'
    OR jsonb_array_length(p_template_snapshot->'lines') = 0
  THEN
    RAISE EXCEPTION 'subscription_cycle_order_invalid_template_snapshot'
      USING ERRCODE = '22023';
  END IF;

  IF p_pricing_snapshot IS NULL OR jsonb_typeof(p_pricing_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'subscription_cycle_order_invalid_pricing_snapshot'
      USING ERRCODE = '22023';
  END IF;

  IF p_order_snapshot IS NULL
    OR jsonb_typeof(p_order_snapshot) <> 'object'
    OR p_order_snapshot->>'contractVersion' IS DISTINCT FROM 'commerce.v0'
    OR p_order_snapshot->>'source' IS DISTINCT FROM 'subscription.own_engine.v0'
    OR p_order_snapshot->>'status' IS DISTINCT FROM 'pending_payment'
    OR p_order_snapshot->>'paymentStatus' IS DISTINCT FROM 'pending'
    OR p_order_snapshot->>'currency' IS NULL
    OR NOT (p_order_snapshot->>'currency') ~ '^[A-Z]{3}$'
    OR p_order_snapshot->>'taxIncluded' IS DISTINCT FROM 'true'
    OR jsonb_typeof(p_order_snapshot->'lines') <> 'array'
    OR jsonb_array_length(p_order_snapshot->'lines') = 0
    OR jsonb_typeof(p_order_snapshot->'totals') <> 'object'
  THEN
    RAISE EXCEPTION 'subscription_cycle_order_invalid_order_snapshot'
      USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_cycle_order_subscription_not_found'
      USING ERRCODE = '22023';
  END IF;

  IF v_subscription.status <> 'active' THEN
    RAISE EXCEPTION 'subscription_cycle_order_subscription_not_active'
      USING ERRCODE = '22023';
  END IF;

  IF v_subscription.payment_method_ref IS NULL OR btrim(v_subscription.payment_method_ref) = '' THEN
    RAISE EXCEPTION 'subscription_cycle_order_missing_payment_method'
      USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    p_subscription_id::text || '|' ||
    p_cycle_number::text || '|' ||
    p_scheduled_at::text || '|' ||
    p_template_snapshot::text || '|' ||
    p_pricing_snapshot::text || '|' ||
    p_order_snapshot::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(
        v_existing.response_payload,
        '{subscriptionCycleOrder,replayed}',
        'true'::jsonb,
        false
      );
    END IF;

    RAISE EXCEPTION 'subscription_cycle_order_idempotency_conflict'
      USING ERRCODE = '23505';
  END IF;

  v_totals := p_order_snapshot->'totals';
  IF v_totals#>>'{subtotalGross,amountMinor}' IS NULL
    OR NOT (v_totals#>>'{subtotalGross,amountMinor}') ~ '^[0-9]+$'
    OR v_totals#>>'{discountTotalGross,amountMinor}' IS NULL
    OR NOT (v_totals#>>'{discountTotalGross,amountMinor}') ~ '^[0-9]+$'
    OR v_totals#>>'{netTotal,amountMinor}' IS NULL
    OR NOT (v_totals#>>'{netTotal,amountMinor}') ~ '^[0-9]+$'
    OR v_totals#>>'{taxTotal,amountMinor}' IS NULL
    OR NOT (v_totals#>>'{taxTotal,amountMinor}') ~ '^[0-9]+$'
    OR v_totals#>>'{totalGross,amountMinor}' IS NULL
    OR NOT (v_totals#>>'{totalGross,amountMinor}') ~ '^[0-9]+$'
    OR (v_totals ? 'shippingGross'
      AND NOT COALESCE(v_totals#>>'{shippingGross,amountMinor}', '') ~ '^[0-9]+$')
    OR (v_totals ? 'shippingDiscountGross'
      AND NOT COALESCE(v_totals#>>'{shippingDiscountGross,amountMinor}', '') ~ '^[0-9]+$')
  THEN
    RAISE EXCEPTION 'subscription_cycle_order_invalid_totals'
      USING ERRCODE = '22023';
  END IF;

  -- INVARIANT 1 of 2 - ONE CURRENCY ACROSS EVERY MONEY NODE OF THE ORDER.
  --
  -- Permanent. This is the rule that blocks a mixed-currency cart, and it is
  -- written to survive Stage 3 unchanged: it never names a currency, it only
  -- counts how many distinct ones the order contains. Widening the set of
  -- currencies this deployment accepts cannot weaken it. Removing it later is
  -- removing a named rule, not tidying a refactor.
  --
  -- Every money node this function is about to trust contributes exactly one
  -- row: the snapshot envelope, the five mandatory totals nodes, the two
  -- shipping nodes only when the snapshot carries them (an absent shipping node
  -- is not a node, and must not be read as a disagreement), and all five money
  -- nodes of every line. A node whose `currency` key is missing yields NULL and
  -- is mapped to the '(absent)' sentinel BEFORE aggregation, so a missing key
  -- becomes a second distinct element on its own terms instead of depending on
  -- how array_agg treats NULL - and the refusal message then says which of the
  -- two problems the caller has.
  --
  -- COLLATE "C" is deliberate: the sorted set is rendered into the refusal
  -- message, so an operator comparing two deployments' logs should see the same
  -- text for the same fault rather than whatever order the server's locale
  -- happens to impose on a punctuated sentinel.
  SELECT array_agg(
           DISTINCT node.currency_code COLLATE "C"
           ORDER BY node.currency_code COLLATE "C"
         )
    INTO v_order_currencies
    FROM (
      SELECT COALESCE(header.currency_code, '(absent)') AS currency_code
        FROM (
          VALUES
            (true, p_order_snapshot->>'currency'),
            (true, v_totals#>>'{subtotalGross,currency}'),
            (true, v_totals#>>'{discountTotalGross,currency}'),
            (true, v_totals#>>'{netTotal,currency}'),
            (true, v_totals#>>'{taxTotal,currency}'),
            (true, v_totals#>>'{totalGross,currency}'),
            (v_totals ? 'shippingGross',
              v_totals#>>'{shippingGross,currency}'),
            (v_totals ? 'shippingDiscountGross',
              v_totals#>>'{shippingDiscountGross,currency}')
        ) AS header(is_present, currency_code)
       WHERE header.is_present
      UNION ALL
      SELECT COALESCE(line_node.currency_code, '(absent)')
        FROM jsonb_array_elements(p_order_snapshot->'lines') AS order_line(value)
        CROSS JOIN LATERAL (
          VALUES
            (order_line.value#>>'{unitPriceGross,currency}'),
            (order_line.value#>>'{lineSubtotalGross,currency}'),
            (order_line.value#>>'{tax,netAmount,currency}'),
            (order_line.value#>>'{tax,vatAmount,currency}'),
            (order_line.value#>>'{tax,grossAmount,currency}')
        ) AS line_node(currency_code)
    ) AS node;

  -- The IS NULL disjunct is load-bearing rather than defensive noise: array_agg
  -- over zero rows returns NULL, array_length(NULL, 1) is NULL, and `NULL <> 1`
  -- is unknown - which IF does not take. Without it this guard would fail OPEN
  -- in exactly the case where it matters most.
  IF v_order_currencies IS NULL
    OR array_length(v_order_currencies, 1) <> 1
  THEN
    RAISE EXCEPTION 'subscription_cycle_order_mixed_currency: %',
      array_to_string(v_order_currencies, ', ')
      USING ERRCODE = '22023',
            HINT = 'Every money node of one order must carry the same currency. Requote the cart in a single currency; (absent) marks a money node that carries no currency at all.';
  END IF;

  v_currency := v_order_currencies[1];

  -- INVARIANT 2 of 2 - AND THAT CURRENCY IS ONE THIS DEPLOYMENT SETTLES IN.
  --
  -- Designed to relax. Stage 3 widens the platform to a set of accepted
  -- currencies by rewriting the single IF condition below as
  --   NOT (v_currency = ANY (public.platform_accepted_currencies()))
  -- and changing nothing else in this body. Invariant 1 above is what keeps a
  -- mixed cart refused after that happens, which is the whole reason these are
  -- two separately named checks and not one combined condition.
  --
  -- Neither operand can be NULL: v_currency is the single element of a set
  -- already proven non-empty and sentinel-mapped above, and
  -- platform_settlement_currency() either returns a code or raises 55000. The
  -- comparison therefore has no unknown branch, and a deployment whose
  -- settlement profile is missing refuses the order instead of skipping a check.
  IF v_currency <> public.platform_settlement_currency() THEN
    RAISE EXCEPTION 'subscription_cycle_order_currency_not_accepted: %', v_currency
      USING ERRCODE = '22023',
            HINT = 'This deployment settles in the currency recorded in commerce_settings.settlement_currency. Price the order in that currency, or change the settlement profile first.';
  END IF;

  v_subtotal := (v_totals#>>'{subtotalGross,amountMinor}')::bigint;
  v_discount := (v_totals#>>'{discountTotalGross,amountMinor}')::bigint;
  v_shipping := COALESCE((v_totals#>>'{shippingGross,amountMinor}')::bigint, 0);
  v_shipping_discount := COALESCE(
    (v_totals#>>'{shippingDiscountGross,amountMinor}')::bigint,
    0
  );
  v_net_total := (v_totals#>>'{netTotal,amountMinor}')::bigint;
  v_tax := (v_totals#>>'{taxTotal,amountMinor}')::bigint;
  v_total := (v_totals#>>'{totalGross,amountMinor}')::bigint;

  IF v_subtotal > 2147483647
    OR v_discount > 2147483647
    OR v_shipping > 2147483647
    OR v_shipping_discount > 2147483647
    OR v_net_total > 2147483647
    OR v_tax > 2147483647
    OR v_total > 2147483647
  THEN
    RAISE EXCEPTION 'subscription_cycle_order_money_overflow'
      USING ERRCODE = '22003';
  END IF;

  IF v_discount > v_subtotal OR v_shipping_discount > v_shipping THEN
    RAISE EXCEPTION 'subscription_cycle_order_discount_out_of_range'
      USING ERRCODE = '22023';
  END IF;

  IF v_total <> v_subtotal - v_discount + v_shipping - v_shipping_discount
    OR v_total <> v_net_total + v_tax
  THEN
    RAISE EXCEPTION 'subscription_cycle_order_totals_mismatch'
      USING ERRCODE = '22023';
  END IF;

  FOR v_line, v_line_ordinal IN
    SELECT value, ordinality::integer
      FROM jsonb_array_elements(p_order_snapshot->'lines') WITH ORDINALITY
  LOOP
    IF v_line->>'quantity' IS NULL
      OR NOT (v_line->>'quantity') ~ '^[1-9][0-9]*$'
      OR v_line#>>'{unitPriceGross,amountMinor}' IS NULL
      OR NOT (v_line#>>'{unitPriceGross,amountMinor}') ~ '^[0-9]+$'
      OR v_line#>>'{lineSubtotalGross,amountMinor}' IS NULL
      OR NOT (v_line#>>'{lineSubtotalGross,amountMinor}') ~ '^[0-9]+$'
      OR v_line#>>'{tax,vatRateBps}' IS NULL
      OR NOT (v_line#>>'{tax,vatRateBps}') ~ '^[0-9]+$'
      OR v_line#>>'{tax,netAmount,amountMinor}' IS NULL
      OR NOT (v_line#>>'{tax,netAmount,amountMinor}') ~ '^[0-9]+$'
      OR v_line#>>'{tax,vatAmount,amountMinor}' IS NULL
      OR NOT (v_line#>>'{tax,vatAmount,amountMinor}') ~ '^[0-9]+$'
      OR v_line#>>'{tax,grossAmount,amountMinor}' IS NULL
      OR NOT (v_line#>>'{tax,grossAmount,amountMinor}') ~ '^[0-9]+$'
    THEN
      RAISE EXCEPTION 'subscription_cycle_order_invalid_line: %', v_line_ordinal
        USING ERRCODE = '22023';
    END IF;

    v_line_total := (v_line#>>'{lineSubtotalGross,amountMinor}')::bigint;
    v_line_net := (v_line#>>'{tax,netAmount,amountMinor}')::bigint;
    v_line_vat := (v_line#>>'{tax,vatAmount,amountMinor}')::bigint;
    v_line_rate := (v_line#>>'{tax,vatRateBps}')::integer;

    IF v_frozen_rate IS NULL THEN
      v_frozen_rate := v_line_rate;
    ELSIF v_frozen_rate <> v_line_rate THEN
      RAISE EXCEPTION 'subscription_cycle_order_mixed_vat_rates'
        USING ERRCODE = '22023';
    END IF;

    IF v_line_total > 2147483647
      OR v_line_net > 2147483647
      OR v_line_vat > 2147483647
      OR v_line_rate > 10000
      OR (v_line#>>'{unitPriceGross,amountMinor}')::numeric
        * (v_line->>'quantity')::numeric <> v_line_total::numeric
      OR (v_line#>>'{tax,grossAmount,amountMinor}')::numeric <> v_line_total::numeric
      OR v_line_net + v_line_vat <> v_line_total
      OR v_line_net <> round(
        v_line_total::numeric * 10000::numeric / (10000 + v_line_rate)::numeric
      )::bigint
    THEN
      RAISE EXCEPTION 'subscription_cycle_order_line_money_mismatch: %', v_line_ordinal
        USING ERRCODE = '22023';
    END IF;

    v_line_sum := v_line_sum + v_line_total::numeric;
    v_line_net_sum := v_line_net_sum + v_line_net::numeric;
  END LOOP;

  IF v_line_sum <> v_subtotal::numeric THEN
    RAISE EXCEPTION 'subscription_cycle_order_line_sum_mismatch'
      USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(
           (value#>>'{lineSubtotalGross,amountMinor}')::integer
           ORDER BY ordinality
         )
    INTO v_line_totals
    FROM jsonb_array_elements(p_order_snapshot->'lines') WITH ORDINALITY;
  v_allocations := public.commerce_allocate_discount_to_lines(
    v_line_totals,
    v_discount::integer
  );

  SELECT COALESCE(sum(round(
           (line_total::bigint - allocated::bigint)::numeric * 10000::numeric
           / (10000 + v_frozen_rate)::numeric
         )), 0)::bigint
    INTO v_expected_net
    FROM unnest(v_line_totals, v_allocations) AS allocation(line_total, allocated);
  v_expected_net := v_expected_net + round(
    (v_shipping - v_shipping_discount)::numeric * 10000::numeric
    / (10000 + v_frozen_rate)::numeric
  )::bigint;
  v_quote_expected_net := v_line_net_sum::bigint
    - round(
      v_discount::numeric * 10000::numeric / (10000 + v_frozen_rate)::numeric
    )::bigint
    + round(
      v_shipping::numeric * 10000::numeric / (10000 + v_frozen_rate)::numeric
    )::bigint
    - round(
      v_shipping_discount::numeric * 10000::numeric
      / (10000 + v_frozen_rate)::numeric
    )::bigint;
  IF v_net_total NOT IN (v_quote_expected_net, v_expected_net)
    OR v_tax <> v_total - v_net_total
  THEN
    RAISE EXCEPTION 'subscription_cycle_order_tax_totals_mismatch'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'subscription_create_cycle_order_with_outbox')
  );

  INSERT INTO public.subscription_cycles (
    subscription_id,
    cycle_number,
    scheduled_at,
    status,
    template_version,
    template_snapshot,
    pricing_snapshot,
    payment_method_ref,
    engine_idempotency_key
  )
  VALUES (
    p_subscription_id,
    p_cycle_number,
    p_scheduled_at,
    'payment_pending',
    v_subscription.template_version,
    p_template_snapshot,
    p_pricing_snapshot,
    v_subscription.payment_method_ref,
    p_idempotency_key
  )
  RETURNING id INTO v_cycle_id;

  INSERT INTO public.commerce_orders (
    client_id,
    status,
    currency,
    subtotal_cents,
    discount_cents,
    shipping_cents,
    shipping_discount_cents,
    tax_cents,
    total_cents,
    region_code,
    mode,
    size_constraint,
    subscription_id,
    subscription_cycle_id,
    metadata
  )
  VALUES (
    v_subscription.client_id,
    'pending_payment',
    v_currency,
    v_subtotal::integer,
    v_discount::integer,
    v_shipping::integer,
    v_shipping_discount::integer,
    (v_total - v_expected_net)::integer,
    v_total::integer,
    v_subscription.region_code,
    'subscription_cycle',
    v_subscription.size_constraint,
    p_subscription_id,
    v_cycle_id,
    jsonb_build_object(
      'paymentStatus', 'pending',
      'orderSnapshot', p_order_snapshot,
      'pricingSnapshot', p_pricing_snapshot,
      'source', 'subscription.own_engine.v0'
    )
  )
  RETURNING id INTO v_order_id;

  FOR v_line, v_line_ordinal IN
    SELECT value, ordinality::integer
      FROM jsonb_array_elements(p_order_snapshot->'lines') WITH ORDINALITY
  LOOP
    SELECT id
      INTO v_sku_id
      FROM public.catalog_skus
     WHERE sku = v_line->>'sku';

    IF v_sku_id IS NULL THEN
      RAISE EXCEPTION 'subscription_cycle_order_unknown_sku: %', v_line->>'sku'
        USING ERRCODE = '22023';
    END IF;

    v_line_total := (v_line#>>'{lineSubtotalGross,amountMinor}')::integer;
    v_effective := v_line_total::integer - v_allocations[v_line_ordinal];
    INSERT INTO public.commerce_order_items (
      order_id,
      sku_id,
      quantity,
      unit_price_cents,
      total_cents,
      discount_allocated_cents,
      effective_total_cents,
      effective_net_cents,
      mode_at_line,
      variant_snapshot,
      size_constraint_contribution,
      vat_rate_bps,
      product_snapshot
    )
    VALUES (
      v_order_id,
      v_sku_id,
      (v_line->>'quantity')::integer,
      (v_line#>>'{unitPriceGross,amountMinor}')::integer,
      v_line_total::integer,
      v_allocations[v_line_ordinal],
      v_effective,
      round(
        v_effective::numeric * 10000::numeric
        / (10000 + (v_line#>>'{tax,vatRateBps}')::integer)::numeric
      )::integer,
      COALESCE(v_line->>'modeAtLine', 'subscription'),
      COALESCE(v_line->'variantSnapshot', '{}'::jsonb),
      COALESCE((v_line->>'sizeConstraintContribution')::numeric, (v_line->>'quantity')::numeric),
      (v_line#>>'{tax,vatRateBps}')::integer,
      jsonb_build_object(
        'sku', v_line->>'sku',
        'productSlug', v_line->>'productSlug',
        'quoteLine', v_line,
        'source', 'subscription.own_engine.v0'
      )
    );
  END LOOP;

  IF (
    SELECT COALESCE(sum(effective_total_cents::numeric), 0)
      FROM public.commerce_order_items
     WHERE order_id = v_order_id
  ) + v_shipping::numeric - v_shipping_discount::numeric <> v_total::numeric THEN
    RAISE EXCEPTION 'subscription_cycle_order_effective_sum_mismatch'
      USING ERRCODE = '22023';
  END IF;

  IF (
    SELECT COALESCE(sum(effective_net_cents::numeric), 0)
      FROM public.commerce_order_items
     WHERE order_id = v_order_id
  ) + round(
    (v_shipping - v_shipping_discount)::numeric * 10000::numeric
    / (10000 + v_frozen_rate)::numeric
  ) <> v_expected_net::numeric THEN
    RAISE EXCEPTION 'subscription_cycle_order_effective_net_sum_mismatch'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_payments (
    order_id,
    provider,
    status,
    amount_cents,
    currency,
    metadata
  )
  VALUES (
    v_order_id,
    'own_engine_payment',
    'pending',
    v_total::integer,
    v_currency,
    jsonb_build_object(
      'paymentMethodRef', v_subscription.payment_method_ref,
      'subscriptionId', p_subscription_id,
      'subscriptionCycleId', v_cycle_id,
      'idempotencyKey', p_idempotency_key,
      'source', 'subscription.own_engine.v0'
    )
  )
  RETURNING id INTO v_payment_id;

  UPDATE public.subscription_cycles
     SET order_id = v_order_id,
         payment_id = v_payment_id,
         updated_at = now()
   WHERE id = v_cycle_id;

  INSERT INTO public.outbox_events (
    aggregate_type,
    aggregate_id,
    event_type,
    idempotency_key,
    payload,
    metadata
  )
  VALUES (
    'commerce_payment',
    v_payment_id,
    v_payment_event_type,
    p_idempotency_key,
    jsonb_build_object(
      'subscriptionId', p_subscription_id,
      'cycleId', v_cycle_id,
      'cycleNumber', p_cycle_number,
      'orderId', v_order_id,
      'paymentId', v_payment_id,
      'paymentMethodRef', v_subscription.payment_method_ref,
      'amount', jsonb_build_object(
        'amountMinor', v_total::integer,
        'currency', v_currency
      ),
      'source', 'subscription.own_engine.v0'
    ),
    jsonb_build_object('boundary', 'subscription_create_cycle_order_with_outbox')
  );

  INSERT INTO public.subscription_events (
    subscription_id,
    cycle_id,
    event_type,
    idempotency_key,
    payload
  )
  VALUES (
    p_subscription_id,
    v_cycle_id,
    'subscription.payment_requested',
    p_idempotency_key || ':subscription_event',
    jsonb_build_object(
      'orderId', v_order_id,
      'paymentId', v_payment_id,
      'paymentOutboxEventType', v_payment_event_type,
      'source', 'subscription.own_engine.v0'
    )
  );

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'subscriptionCycleOrder', jsonb_build_object(
      'subscriptionId', p_subscription_id,
      'cycleId', v_cycle_id,
      'cycleNumber', p_cycle_number,
      'orderId', 'order_' || v_order_id::text,
      'paymentId', 'payment_' || v_payment_id::text,
      'status', 'payment_pending',
      'outboxEventType', v_payment_event_type,
      'idempotencyKey', p_idempotency_key,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object(
           'subscriptionId', p_subscription_id,
           'cycleId', v_cycle_id,
           'orderId', 'order_' || v_order_id::text,
           'paymentId', 'payment_' || v_payment_id::text
         )
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$_$;


--
-- Name: subscription_create_provisional_for_checkout(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_create_provisional_for_checkout(p_order_id uuid, p_client_id uuid, p_pet_id uuid, p_shipping_address_id uuid, p_quote_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_cadence_days integer;
  v_currency text;
  v_region_code text;
  v_size_constraint jsonb;
  v_subscription_id uuid;
  v_cycle_id uuid;
  v_template_snapshot jsonb;
  v_line_count integer;
  -- Starter-pack locals. All stay NULL when the quote carries no marker.
  v_starter_input jsonb;
  v_starter_marker jsonb;
  v_starter_interval integer;
  v_starter_discount_bps integer;
  v_starter_discount_minor integer;
  v_starter_basis_subtotal integer;
  v_starter_cadence_days integer;
  v_starter_lines jsonb;
  v_starter_graduation jsonb;
  v_starter_line jsonb;
  v_starter_template_version constant integer := 1;
BEGIN
  v_starter_input := p_quote_snapshot #> '{quote,context,starterPack}';
  IF v_starter_input IS NOT NULL AND jsonb_typeof(v_starter_input) <> 'null' THEN
    IF jsonb_typeof(v_starter_input) <> 'object'
      OR v_starter_input->>'schemaVersion' IS DISTINCT FROM '1'
    THEN
      RAISE EXCEPTION 'subscription_starter_pack_invalid_schema' USING ERRCODE = '22023';
    END IF;

    -- starterIntervalDays is the delivery-2 interval and becomes cadence_days.
    IF NOT COALESCE(v_starter_input->>'starterIntervalDays', '') ~ '^[0-9]+$' THEN
      RAISE EXCEPTION 'subscription_starter_pack_invalid_interval' USING ERRCODE = '22023';
    END IF;
    v_starter_interval := (v_starter_input->>'starterIntervalDays')::integer;
    IF v_starter_interval < 7 OR v_starter_interval > 28 THEN
      RAISE EXCEPTION 'subscription_starter_pack_invalid_interval' USING ERRCODE = '22023';
    END IF;

    IF jsonb_typeof(v_starter_input->'delivery2') <> 'object'
      OR NOT COALESCE(v_starter_input #>> '{delivery2,discountBps}', '') ~ '^[0-9]+$'
      OR NOT COALESCE(v_starter_input #>> '{delivery2,discountMinor}', '') ~ '^[0-9]+$'
      OR NOT COALESCE(v_starter_input #>> '{delivery2,basisSubtotalMinor}', '') ~ '^[0-9]+$'
    THEN
      RAISE EXCEPTION 'subscription_starter_pack_invalid_delivery2' USING ERRCODE = '22023';
    END IF;
    v_starter_discount_bps := (v_starter_input #>> '{delivery2,discountBps}')::integer;
    v_starter_discount_minor := (v_starter_input #>> '{delivery2,discountMinor}')::integer;
    v_starter_basis_subtotal := (v_starter_input #>> '{delivery2,basisSubtotalMinor}')::integer;
    IF v_starter_discount_bps > 10000 THEN
      RAISE EXCEPTION 'subscription_starter_pack_invalid_delivery2' USING ERRCODE = '22023';
    END IF;
    IF v_starter_discount_minor > v_starter_basis_subtotal THEN
      RAISE EXCEPTION 'subscription_starter_pack_discount_out_of_range' USING ERRCODE = '22023';
    END IF;
    -- Delivery 2 has to remain a real, chargeable order. A payable below 1 PLN
    -- is a free renewal in disguise and no PSP will honour it as a mandate use.
    IF v_starter_basis_subtotal - v_starter_discount_minor < 100 THEN
      RAISE EXCEPTION 'subscription_starter_pack_payable_below_floor' USING ERRCODE = '22023';
    END IF;

    IF NOT COALESCE(v_starter_input #>> '{graduation,cadenceDays}', '') ~ '^[0-9]+$' THEN
      RAISE EXCEPTION 'subscription_starter_pack_invalid_graduation_cadence' USING ERRCODE = '22023';
    END IF;
    v_starter_cadence_days := (v_starter_input #>> '{graduation,cadenceDays}')::integer;
    IF v_starter_cadence_days NOT IN (14, 28) THEN
      RAISE EXCEPTION 'subscription_starter_pack_invalid_graduation_cadence' USING ERRCODE = '22023';
    END IF;

    v_starter_lines := v_starter_input #> '{graduation,lines}';
    IF v_starter_lines IS NULL
      OR jsonb_typeof(v_starter_lines) <> 'array'
      OR jsonb_array_length(v_starter_lines) = 0
    THEN
      RAISE EXCEPTION 'subscription_starter_pack_invalid_graduation_lines' USING ERRCODE = '22023';
    END IF;

    FOR v_starter_line IN SELECT value FROM jsonb_array_elements(v_starter_lines) LOOP
      IF jsonb_typeof(v_starter_line) <> 'object'
        OR COALESCE(v_starter_line->>'sku', '') = ''
        OR NOT COALESCE(v_starter_line->>'qty', '') ~ '^[1-9][0-9]*$'
        OR NOT COALESCE(v_starter_line->>'sortOrder', '') ~ '^[0-9]+$'
        OR jsonb_typeof(v_starter_line->'isAddon') <> 'boolean'
        OR jsonb_typeof(v_starter_line->'quoteLine') <> 'object'
      THEN
        RAISE EXCEPTION 'subscription_starter_pack_invalid_graduation_lines' USING ERRCODE = '22023';
      END IF;
      -- The frozen quoteLine is replayed verbatim into subscription_lines at
      -- graduation, and the renewal engine parses it back out. A quoteLine
      -- without money on it would pass creation and then fail every renewal
      -- afterwards, so the minimal money shape is enforced here, at the only
      -- boundary that can still refuse the acquisition.
      IF NOT COALESCE(v_starter_line #>> '{quoteLine,unitPriceGross,amountMinor}', '') ~ '^[0-9]+$'
        OR NOT COALESCE(v_starter_line #>> '{quoteLine,lineSubtotalGross,amountMinor}', '') ~ '^[0-9]+$'
      THEN
        RAISE EXCEPTION 'subscription_starter_pack_invalid_graduation_quote_line' USING ERRCODE = '22023';
      END IF;
    END LOOP;

    v_starter_graduation := jsonb_build_object(
      'cadenceDays', v_starter_cadence_days,
      'lines', v_starter_lines
    );
    IF jsonb_typeof(v_starter_input #> '{graduation,sizeConstraint}') = 'object' THEN
      v_starter_graduation := v_starter_graduation || jsonb_build_object(
        'sizeConstraint', v_starter_input #> '{graduation,sizeConstraint}'
      );
    END IF;

    -- Rebuilt from validated fields only. Unknown client keys are dropped and
    -- basisTemplateVersion is the server's own value, never the client's.
    v_starter_marker := jsonb_build_object(
      'schemaVersion', '1',
      'starterIntervalDays', v_starter_interval,
      'basisTemplateVersion', v_starter_template_version,
      'delivery2', jsonb_build_object(
        'discountBps', v_starter_discount_bps,
        'discountMinor', v_starter_discount_minor,
        'basisSubtotalMinor', v_starter_basis_subtotal
      ),
      'graduation', v_starter_graduation
    );
  END IF;

  v_cadence_days := COALESCE(
    v_starter_interval,
    nullif(p_quote_snapshot #>> '{quote,context,cadenceDays}', '')::integer
  );
  IF v_cadence_days IS NULL OR v_cadence_days < 1 THEN
    RAISE EXCEPTION 'subscription_provisional_invalid_cadence' USING ERRCODE = '22023';
  END IF;

  SELECT region_code, currency, COALESCE(size_constraint, '{}'::jsonb)
    INTO v_region_code, v_currency, v_size_constraint
    FROM public.commerce_orders
   WHERE id = p_order_id;

  -- Provisional subscription. status='pending_activation' is admitted by the
  -- status CHECK and is excluded from the active-only renewal due-list, so it
  -- cannot be charged until confirmed.
  INSERT INTO public.subscriptions (
    client_id, pet_id, cadence_days, currency, region_code, status,
    size_constraint, shipping_address_id, billing_address_id,
    next_cycle_at, template_version, timezone, starter_pack
  )
  VALUES (
    p_client_id, p_pet_id, v_cadence_days, v_currency, v_region_code, 'pending_activation',
    v_size_constraint, p_shipping_address_id, p_shipping_address_id,
    NULL, v_starter_template_version, 'Europe/Warsaw', v_starter_marker
  )
  RETURNING id INTO v_subscription_id;

  -- Subscription lines from the finalized order items. The renewal engine reads
  -- these as the standing template; they are stored at the order's line price,
  -- which for the initial cycle is the subscription-band price.
  INSERT INTO public.subscription_lines (
    subscription_id, variant_id, qty, sort_order, is_addon, template_version, line_metadata
  )
  SELECT
    v_subscription_id,
    oi.sku_id,
    oi.quantity,
    (row_number() OVER (ORDER BY oi.created_at, oi.id))::integer - 1,
    false,
    1,
    jsonb_build_object(
      'source', 'commerce.checkout.provisional.v0',
      'orderItemId', oi.id,
      'productSnapshot', oi.product_snapshot
    )
  FROM public.commerce_order_items oi
  WHERE oi.order_id = p_order_id
    AND oi.sku_id IS NOT NULL;

  SELECT count(*) INTO v_line_count
    FROM public.subscription_lines
   WHERE subscription_id = v_subscription_id;
  IF v_line_count = 0 THEN
    RAISE EXCEPTION 'subscription_provisional_no_lines' USING ERRCODE = '22023';
  END IF;

  -- cycle #1.template_snapshot MUST equal the canonical snapshot or the
  -- payment_pending guard (20260605144000) rejects the insert.
  v_template_snapshot := public.subscription_current_template_snapshot(v_subscription_id);

  INSERT INTO public.subscription_cycles (
    subscription_id, cycle_number, scheduled_at, status, template_version,
    template_snapshot, pricing_snapshot, engine_idempotency_key, order_id, retry_attempt
  )
  VALUES (
    v_subscription_id,
    1,
    now(),
    'payment_pending',
    1,
    v_template_snapshot,
    jsonb_build_object('source', 'commerce.checkout.provisional.v0', 'quoteSnapshot', p_quote_snapshot),
    -- Deterministic, distinct namespace; cannot collide with the renewal engine's
    -- 'subscription:<id>:cycle:<scheduledAt>' key space.
    'checkout-initial-cycle:' || p_order_id::text,
    p_order_id,
    0
  )
  RETURNING id INTO v_cycle_id;

  RETURN jsonb_build_object(
    'subscriptionId', v_subscription_id,
    'subscriptionCycleId', v_cycle_id
  );
END;
$_$;


--
-- Name: subscription_current_template_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_current_template_snapshot(p_subscription_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_subscription public.subscriptions%ROWTYPE;
  v_lines jsonb;
BEGIN
  SELECT *
    INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_template_snapshot_subscription_not_found'
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'variant_id', locked_lines.sku,
               'qty', locked_lines.qty,
               'sort_order', locked_lines.sort_order,
               'is_addon', locked_lines.is_addon
             )
             ORDER BY locked_lines.sort_order, locked_lines.id
           ),
           '[]'::jsonb
         )
    INTO v_lines
    FROM (
      SELECT
        sl.id,
        cs.sku,
        sl.qty,
        sl.sort_order,
        sl.is_addon
      FROM public.subscription_lines sl
      JOIN public.catalog_skus cs
        ON cs.id = sl.variant_id
      WHERE sl.subscription_id = p_subscription_id
      ORDER BY sl.sort_order, sl.id
      FOR UPDATE OF sl
    ) AS locked_lines;

  IF jsonb_array_length(v_lines) = 0 THEN
    RAISE EXCEPTION 'subscription_template_snapshot_no_lines'
      USING ERRCODE = '22023';
  END IF;

  RETURN jsonb_build_object(
    'cadence_days', v_subscription.cadence_days,
    'currency', v_subscription.currency,
    'region_code', v_subscription.region_code,
    'edit_window_hours', COALESCE(v_subscription.edit_window_hours, 24),
    'size_constraint', COALESCE(v_subscription.size_constraint, '{}'::jsonb),
    'lines', v_lines
  );
END;
$$;


--
-- Name: FUNCTION subscription_current_template_snapshot(p_subscription_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_current_template_snapshot(p_subscription_id uuid) IS 'Builds the canonical subscription template snapshot from locked subscriptions + subscription_lines.';


--
-- Name: subscription_cycle_inherit_delivery_selection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_cycle_inherit_delivery_selection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_selection jsonb;
  v_subscription_client_id uuid;
BEGIN
  IF NEW.mode <> 'subscription_cycle' OR NEW.subscription_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Respect an explicit selection if one is already present (top-level or runtimeFinalize).
  IF COALESCE(NEW.metadata, '{}'::jsonb) ? 'selectedDelivery'
     OR (COALESCE(NEW.metadata, '{}'::jsonb) #> '{runtimeFinalize,selectedDelivery}') IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT s.client_id
    INTO v_subscription_client_id
    FROM public.subscriptions s
   WHERE s.id = NEW.subscription_id
   LIMIT 1;

  SELECT jsonb_build_object(
           'kind', p.delivery_kind,
           'deliveryKind', p.delivery_kind,
           'providerKind', p.provider_kind,
           'carrierKind', p.carrier_kind,
           'carrierCode', p.carrier_code,
           'serviceCode', p.service_code,
           'pickupPoint',
             CASE
               WHEN p.delivery_kind = 'parcel-locker' THEN jsonb_build_object(
                 'id', p.pickup_point_id,
                 'provider', p.carrier_kind,
                 'name', p.pickup_point_name,
                 'address', p.pickup_point_address
               )
               ELSE 'null'::jsonb
             END
         )
    INTO v_selection
    FROM public.customer_delivery_preferences p
   WHERE p.client_id = COALESCE(v_subscription_client_id, NEW.client_id)
     AND p.scope IN ('subscription', 'any')
     AND (
       p.delivery_kind <> 'parcel-locker'
       OR (
         p.pickup_point_id IS NOT NULL
         AND p.pickup_point_name IS NOT NULL
         AND p.pickup_point_address IS NOT NULL
       )
     )
   ORDER BY CASE p.scope WHEN 'subscription' THEN 0 ELSE 1 END,
            p.last_selected_at DESC,
            p.updated_at DESC
   LIMIT 1;

  IF v_selection IS NULL OR jsonb_typeof(v_selection) <> 'object' THEN
    SELECT COALESCE(o.metadata -> 'selectedDelivery', o.metadata #> '{runtimeFinalize,selectedDelivery}')
      INTO v_selection
      FROM public.commerce_orders o
     WHERE o.subscription_id = NEW.subscription_id
       AND o.id IS DISTINCT FROM NEW.id
       AND (
         o.metadata ? 'selectedDelivery'
         OR (o.metadata #> '{runtimeFinalize,selectedDelivery}') IS NOT NULL
       )
     ORDER BY o.created_at ASC
     LIMIT 1;
  END IF;

  IF v_selection IS NOT NULL AND jsonb_typeof(v_selection) = 'object' THEN
    NEW.metadata = COALESCE(NEW.metadata, '{}'::jsonb)
      || jsonb_build_object('selectedDelivery', v_selection);
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_cycle_inherit_delivery_selection(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_cycle_inherit_delivery_selection() IS 'BEFORE INSERT on commerce_orders: subscription_cycle renewals use the latest saved subscription delivery preference, falling back to the anchor order selectedDelivery. Additive metadata only; no-op for non-cycle orders or explicit selections.';


--
-- Name: subscription_cycle_inherit_offer_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_cycle_inherit_offer_policy() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_offer text;
  v_engine text;
  v_state text;
BEGIN
  SELECT offer_policy_version, promotion_engine_version, offer_policy_assignment_state
    INTO v_offer, v_engine, v_state
    FROM public.subscriptions
   WHERE id = NEW.subscription_id;

  IF v_state = 'pending_acquisition' THEN
    NEW.offer_policy_version := 'commerce.offer-policy.v1';
    NEW.promotion_engine_version := 'promotion-engine.v1';
    NEW.offer_policy_assignment_state := 'pending_acquisition';
  ELSIF v_state = 'assigned_acquisition' THEN
    NEW.offer_policy_version := v_offer;
    NEW.promotion_engine_version := v_engine;
    NEW.offer_policy_assignment_state := 'inherited';
  ELSIF v_state = 'legacy_frozen' THEN
    NEW.offer_policy_version := v_offer;
    NEW.promotion_engine_version := v_engine;
    NEW.offer_policy_assignment_state := 'legacy_frozen';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: subscription_cycle_order_fill_fulfillment_inputs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_cycle_order_fill_fulfillment_inputs() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_subscription public.subscriptions%ROWTYPE;
BEGIN
  IF NEW.mode <> 'subscription_cycle' OR NEW.subscription_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT *
    INTO v_subscription
    FROM public.subscriptions
   WHERE id = NEW.subscription_id;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  NEW.shipping_address_id := COALESCE(NEW.shipping_address_id, v_subscription.shipping_address_id);
  NEW.pet_id := COALESCE(NEW.pet_id, v_subscription.pet_id);
  NEW.metadata := COALESCE(NEW.metadata, '{}'::jsonb)
    || jsonb_build_object(
      'subscriptionFulfillmentInputs', jsonb_build_object(
        'shippingAddressId', NEW.shipping_address_id,
        'petId', NEW.pet_id,
        'source', 'subscription_cycle_order_fill_fulfillment_inputs'
      )
    );

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_cycle_order_fill_fulfillment_inputs(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_cycle_order_fill_fulfillment_inputs() IS 'BEFORE INSERT on commerce_orders: subscription_cycle renewals inherit shipping_address_id and pet_id from subscriptions for OMS/fulfillment readiness.';


--
-- Name: subscription_cycle_order_item_reserve_inventory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_cycle_order_item_reserve_inventory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_provider_kind text;
BEGIN
  SELECT *
    INTO v_order
    FROM public.commerce_orders
   WHERE id = NEW.order_id;

  IF NOT FOUND
     OR v_order.mode <> 'subscription_cycle'
     OR v_order.subscription_cycle_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Cycle orders inherit selectedDelivery from the anchor order when available.
  -- No selection still means the universal OmniPack provider. An explicit
  -- non-OmniPack provider is unsupported for renewal reservations today and
  -- must not fall through to local ATP.
  v_provider_kind := lower(btrim(coalesce(
    v_order.metadata #>> '{runtimeFinalize,selectedDelivery,providerKind}',
    v_order.metadata #>> '{selectedDelivery,providerKind}',
    'omnipack'
  )));

  IF v_provider_kind IS DISTINCT FROM 'omnipack' THEN
    RAISE EXCEPTION 'inventory_external_provider_stock_missing' USING ERRCODE = '23514';
  END IF;

  PERFORM public.inventory_reserve_order(
    'subscription-cycle-reserve:' || NEW.id::text,
    NEW.order_id,
    NEW.id,
    v_order.subscription_cycle_id,
    NEW.sku_id,
    NEW.quantity,
    'subscription_retry_window',
    'created',
    now() + interval '72 hours',
    jsonb_build_object(
      'source', 'subscription_cycle_order_item_reserve_inventory',
      'subscriptionId', v_order.subscription_id,
      'subscriptionCycleId', v_order.subscription_cycle_id
    ),
    v_provider_kind
  );

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_cycle_order_item_reserve_inventory(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_cycle_order_item_reserve_inventory() IS 'AFTER INSERT on commerce_order_items: subscription_cycle renewal items reserve inventory via OmniPack provider-current stock; explicit non-OmniPack renewal providers fail closed before local ATP.';


--
-- Name: subscription_cycle_reservation_preflight(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_cycle_reservation_preflight(p_order_id uuid, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_order public.commerce_orders%ROWTYPE;
  v_item record;
  v_provider_kind text;
  v_active_quantity integer;
  v_missing_quantity integer;
  v_items_checked integer := 0;
  v_reacquired integer := 0;
BEGIN
  IF p_order_id IS NULL OR p_now IS NULL THEN
    RAISE EXCEPTION 'subscription_reservation_preflight_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order FROM public.commerce_orders WHERE id = p_order_id;
  IF NOT FOUND OR v_order.mode <> 'subscription_cycle' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'preflight_order_not_subscription_cycle');
  END IF;

  -- Same provider resolution as the item-reserve trigger: inherited delivery
  -- selection, defaulting to the universal OmniPack provider.
  v_provider_kind := lower(coalesce(
    v_order.metadata #>> '{runtimeFinalize,selectedDelivery,providerKind}',
    v_order.metadata #>> '{selectedDelivery,providerKind}',
    'omnipack'
  ));

  FOR v_item IN
    SELECT id, sku_id, quantity
      FROM public.commerce_order_items
     WHERE order_id = p_order_id
       AND sku_id IS NOT NULL
     ORDER BY id
     FOR UPDATE
  LOOP
    v_items_checked := v_items_checked + 1;

    SELECT coalesce(sum(quantity), 0)
      INTO v_active_quantity
      FROM public.inventory_reservations
     WHERE order_id = p_order_id
       AND (order_item_id = v_item.id OR order_item_id IS NULL)
       AND sku_id = v_item.sku_id
       AND status = 'reserved'
       AND (expires_at IS NULL OR expires_at > p_now);

    v_missing_quantity := v_item.quantity - v_active_quantity;
    IF v_missing_quantity <= 0 THEN
      CONTINUE;
    END IF;

    BEGIN
      -- Hour-bucketed idempotency key: replay-safe within a run, but a fresh
      -- key after an earlier re-acquired hold expired again (a stable key
      -- would replay the released row instead of reserving).
      PERFORM public.inventory_reserve_order(
        'renewal-preflight-reacquire:' || v_item.id::text || ':' || to_char(p_now, 'YYYYMMDDHH24'),
        p_order_id,
        v_item.id,
        v_order.subscription_cycle_id,
        v_item.sku_id,
        v_missing_quantity,
        'subscription_retry_window',
        'created',
        p_now + interval '72 hours',
        jsonb_build_object(
          'source', 'subscription_cycle_reservation_preflight',
          'subscriptionId', v_order.subscription_id,
          'subscriptionCycleId', v_order.subscription_cycle_id,
          'reacquiredBeforeCharge', true
        ),
        nullif(v_provider_kind, '')
      );
      v_reacquired := v_reacquired + 1;
    EXCEPTION WHEN OTHERS THEN
      -- Fail closed: no stock (or a fail-closed provider path) means NO charge.
      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'reservation_preflight_blocked',
        'detail', left(SQLERRM, 200),
        'skuId', v_item.sku_id,
        'missingQuantity', v_missing_quantity
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'itemsChecked', v_items_checked,
    'reacquired', v_reacquired
  );
END;
$$;


--
-- Name: FUNCTION subscription_cycle_reservation_preflight(p_order_id uuid, p_now timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_cycle_reservation_preflight(p_order_id uuid, p_now timestamp with time zone) IS 'Pre-PSP-charge renewal preflight: verifies active inventory holds for the cycle order and re-acquires expired/released ones via inventory_reserve_order (provider stock authority included); returns ok=false (fail-closed, no charge) when stock cannot be secured.';


--
-- Name: subscription_delivery_alignment_admit_renewal(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_delivery_alignment_admit_renewal(p_subscription_id uuid, p_scheduled_at timestamp with time zone, p_as_of timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_subscription public.subscriptions%ROWTYPE;
  v_predecessor public.subscription_cycles%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_mode text;
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_has_fulfillment boolean := false;
  v_has_undelivered boolean := false;
  v_has_paid_predecessor boolean := false;
  v_existing_state text;
  v_ledger_state text;
BEGIN
  IF p_subscription_id IS NULL OR p_scheduled_at IS NULL OR p_as_of IS NULL THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_invalid_admission' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_subscription_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_subscription.status <> 'active' THEN
    RETURN jsonb_build_object('allowed', false, 'state', 'not_active', 'reason', 'subscription_not_active');
  END IF;

  -- retry_scheduled is an already-created recovery authority, not a request to
  -- create a later cycle. It must pass through even if delivery evidence became
  -- protected/manual after the retry was scheduled; no receipt is minted or
  -- consumed for this replay path.
  IF EXISTS (
    SELECT 1 FROM public.subscription_cycles
     WHERE subscription_id = p_subscription_id
       AND status = 'retry_scheduled'
       AND scheduled_at = p_scheduled_at
  ) THEN
    RETURN jsonb_build_object('allowed', true, 'state', 'retry_scheduled', 'reason', 'existing_retry_authority');
  END IF;

  SELECT * INTO v_predecessor
    FROM public.subscription_cycles
   WHERE subscription_id = p_subscription_id
     AND status = 'paid'
     AND cycle_number >= 1
   ORDER BY cycle_number DESC
   LIMIT 1;
  v_has_paid_predecessor := FOUND;

  -- A later paid cycle is authoritative proof that an older collision no
  -- longer controls the next renewal. Release it atomically under the same
  -- subscription lock so a completed retry cannot strand future normal cycles.
  IF v_has_paid_predecessor THEN
    UPDATE public.subscription_delivery_alignment_cases
       SET state = 'released',
           updated_at = now()
     WHERE subscription_id = p_subscription_id
       AND state IN ('protected', 'manual_review')
       AND predecessor_cycle_number < v_predecessor.cycle_number;
  END IF;

  SELECT state INTO v_existing_state
    FROM public.subscription_delivery_alignment_cases
   WHERE subscription_id = p_subscription_id
     AND state IN ('protected', 'manual_review')
     AND (NOT v_has_paid_predecessor OR predecessor_cycle_number >= v_predecessor.cycle_number)
   ORDER BY predecessor_cycle_number DESC, created_at DESC, id DESC
   LIMIT 1;
  IF v_existing_state IS NOT NULL THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'state', v_existing_state,
      'reason', CASE WHEN v_existing_state = 'protected'
        THEN 'delivery_alignment_protected' ELSE 'delivery_alignment_manual_review' END
    );
  END IF;

  SELECT mode INTO v_mode
    FROM public.subscription_delivery_alignment_control
   WHERE singleton = true;
  IF COALESCE(v_mode, 'off') = 'off' THEN
    RETURN jsonb_build_object('allowed', true, 'state', 'off', 'reason', 'mode_off');
  END IF;
  -- Shadow is observation-only. A stale caller is useful telemetry but it must
  -- never turn this rollout mode into an implicit admission gate or rewrite a
  -- case using a schedule we no longer own.
  IF COALESCE(v_mode, 'off') = 'shadow'
     AND v_subscription.next_cycle_at IS DISTINCT FROM p_scheduled_at THEN
    RETURN jsonb_build_object('allowed', true, 'state', 'shadow', 'reason', 'stale_shadow');
  END IF;
  IF v_subscription.next_cycle_at IS DISTINCT FROM p_scheduled_at THEN
    RETURN jsonb_build_object('allowed', false, 'state', 'stale', 'reason', 'stale_next_cycle_at');
  END IF;
  IF p_scheduled_at > p_as_of THEN
    RETURN jsonb_build_object('allowed', true, 'state', 'none', 'reason', 'not_due');
  END IF;

  IF NOT v_has_paid_predecessor OR v_predecessor.order_id IS NULL THEN
    PERFORM public.subscription_delivery_alignment_record_allowed_receipt(
      p_subscription_id, p_scheduled_at, v_subscription.next_cycle_at, 'renewal_admission'
    );
    RETURN jsonb_build_object('allowed', true, 'state', 'none', 'reason', 'no_paid_predecessor');
  END IF;

  SELECT * INTO v_order
   FROM public.commerce_orders
   WHERE id = v_predecessor.order_id;
  IF NOT FOUND OR v_order.mode IS DISTINCT FROM 'subscription_cycle' THEN
    PERFORM public.subscription_delivery_alignment_record_allowed_receipt(
      p_subscription_id, p_scheduled_at, v_subscription.next_cycle_at, 'renewal_admission'
    );
    RETURN jsonb_build_object('allowed', true, 'state', 'none', 'reason', 'predecessor_not_subscription_cycle');
  END IF;

  FOR v_fulfillment IN
    SELECT *
      FROM public.commerce_fulfillment_orders
     WHERE order_id = v_order.id
     ORDER BY created_at ASC, id ASC
  LOOP
    v_has_fulfillment := true;
    -- Superseded parcels do not count. Without this the lost original would
    -- keep this admission answering `protected` long after its replacement
    -- reached the customer, and the subscription would never renew again.
    IF v_fulfillment.delivered_at IS NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.commerce_fulfillment_orders successor
          WHERE successor.replaces_fulfillment_order_id = v_fulfillment.id
       )
    THEN
      v_has_undelivered := true;
    END IF;
  END LOOP;

  -- Do not open a delivery case merely because a normal parcel exists. It is
  -- delay evidence only once the autonomous renewal is actually overdue.
  IF NOT v_has_fulfillment THEN
    PERFORM public.subscription_delivery_alignment_upsert_case(
      NULL, v_order.id, p_subscription_id, v_predecessor.id,
      v_predecessor.cycle_number, v_mode, 'missing_fulfillment',
      v_subscription.next_cycle_at,
      CASE WHEN v_mode = 'shadow' THEN NULL ELSE 'missing_fulfillment' END
    );
    IF v_mode = 'shadow' THEN
      RETURN jsonb_build_object('allowed', true, 'state', 'shadow', 'reason', 'delivery_alignment_shadow');
    END IF;
    RETURN jsonb_build_object('allowed', false, 'state', 'manual_review', 'reason', 'delivery_alignment_manual_review');
  END IF;
  IF NOT v_has_undelivered THEN
    PERFORM public.subscription_delivery_alignment_record_allowed_receipt(
      p_subscription_id, p_scheduled_at, v_subscription.next_cycle_at, 'renewal_admission'
    );
    RETURN jsonb_build_object('allowed', true, 'state', 'none', 'reason', 'predecessor_delivered');
  END IF;

  FOR v_fulfillment IN
    SELECT *
      FROM public.commerce_fulfillment_orders
     WHERE order_id = v_order.id
     ORDER BY created_at ASC, id ASC
  LOOP
    PERFORM public.subscription_delivery_alignment_upsert_case(
      v_fulfillment.id, v_order.id, p_subscription_id, v_predecessor.id,
      v_predecessor.cycle_number, v_mode, 'overdue_renewal',
      v_subscription.next_cycle_at
    );
  END LOOP;

  IF v_mode = 'shadow' THEN
    RETURN jsonb_build_object('allowed', true, 'state', 'shadow', 'reason', 'delivery_alignment_shadow');
  END IF;

  -- The ledger owns this answer. The upsert above preserves a state an operator
  -- or the delivery path already settled, so reading the row is the only way for
  -- the response to agree with it. A blocking state still refuses; a settled one
  -- is admitted and takes the same one-time receipt the other admitted paths
  -- take, because the cycle-insert backstop would otherwise reject a renewal
  -- this call has just declared allowed. A missing row cannot happen here (the
  -- loop above wrote one for every fulfillment) and is treated as blocking.
  SELECT state INTO v_ledger_state
    FROM public.subscription_delivery_alignment_cases
   WHERE subscription_id = p_subscription_id
     AND predecessor_order_id = v_order.id
   ORDER BY (state IN ('protected', 'manual_review')) DESC, updated_at DESC, id DESC
   LIMIT 1;
  v_ledger_state := COALESCE(v_ledger_state, 'protected');
  IF v_ledger_state IN ('protected', 'manual_review') THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'state', v_ledger_state,
      'reason', CASE WHEN v_ledger_state = 'protected'
        THEN 'delivery_alignment_protected' ELSE 'delivery_alignment_manual_review' END
    );
  END IF;
  PERFORM public.subscription_delivery_alignment_record_allowed_receipt(
    p_subscription_id, p_scheduled_at, v_subscription.next_cycle_at, 'renewal_admission'
  );
  RETURN jsonb_build_object(
    'allowed', true,
    'state', v_ledger_state,
    'reason', 'delivery_alignment_case_settled'
  );
END;
$$;


--
-- Name: FUNCTION subscription_delivery_alignment_admit_renewal(p_subscription_id uuid, p_scheduled_at timestamp with time zone, p_as_of timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_delivery_alignment_admit_renewal(p_subscription_id uuid, p_scheduled_at timestamp with time zone, p_as_of timestamp with time zone) IS 'Service-role pre-artifact admission for autonomous renewal. Opens durable delayed-delivery cases only on overdue undelivered predecessor evidence, counting a parcel superseded through replaces_fulfillment_order_id as received; a protected/manual-review ledger state must stop cycle/order/payment creation, while a state an operator or delivery already settled is admitted with a one-time receipt and reported as itself rather than as a literal protected refusal.';


--
-- Name: subscription_delivery_alignment_confirm_replacement(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_delivery_alignment_confirm_replacement(p_case_id uuid, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_case public.subscription_delivery_alignment_cases%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_subscription_id uuid;
  v_target timestamptz;
BEGIN
  IF p_case_id IS NULL OR NULLIF(btrim(p_note), '') IS NULL THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_invalid_replacement' USING ERRCODE = '22023';
  END IF;

  -- Identity first, then the aggregate lock, then the case lock: the same order
  -- admission, delivery and resolution use, so this cannot deadlock against them.
  SELECT subscription_id INTO v_subscription_id
    FROM public.subscription_delivery_alignment_cases
   WHERE id = p_case_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_case_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_subscription
    FROM public.subscriptions
   WHERE id = v_subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_subscription_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_case
    FROM public.subscription_delivery_alignment_cases
   WHERE id = p_case_id
   FOR UPDATE;

  -- A case this call already aligned answers with its stored schedule instead of
  -- shifting again. Without this the second call would add another cadence.
  IF v_case.state = 'aligned' THEN
    RETURN jsonb_build_object(
      'caseId', v_case.id,
      'state', v_case.state,
      'confirmed', true,
      'nextCycleAt', v_case.aligned_next_cycle_at
    );
  END IF;
  IF v_case.state NOT IN ('protected', 'manual_review') THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_case_not_open' USING ERRCODE = '22023';
  END IF;

  -- A non-active subscription has no autonomous renewal to align. Confirming a
  -- replacement there would move a schedule nobody is going to read, and would
  -- hide the case from the operator queue on the strength of a schedule shift
  -- that changes nothing.
  IF v_subscription.status <> 'active' THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_replacement_requires_active_subscription' USING ERRCODE = '22023';
  END IF;

  -- The confirmation instant plus the subscription's own cadence, and never
  -- earlier than the schedule already promised. `GREATEST` is what makes this
  -- monotonic: the same one-way rule the delivery path applies.
  v_target := now() + make_interval(days => v_subscription.cadence_days);
  UPDATE public.subscriptions
     SET next_cycle_at = CASE
           WHEN next_cycle_at IS NULL THEN v_target
           ELSE GREATEST(next_cycle_at, v_target)
         END,
         updated_at = now()
   WHERE id = v_subscription.id
   RETURNING next_cycle_at INTO v_target;

  -- Settle every open case of the same predecessor order, not only the targeted
  -- row. One replacement answers for the whole undelivered order, and a sibling
  -- left open would keep the cycle-insert backstop rejecting the renewal this
  -- confirmation just scheduled. Matches how the delivery path settles siblings.
  UPDATE public.subscription_delivery_alignment_cases
     SET state = 'aligned',
         aligned_next_cycle_at = v_target,
         aligned_at = now(),
         updated_at = now(),
         metadata = metadata || jsonb_build_object(
           'replacementConfirmation',
           jsonb_build_object('note', p_note, 'confirmedAt', now(), 'nextCycleAt', v_target)
         )
   WHERE predecessor_order_id = v_case.predecessor_order_id
     AND state IN ('protected', 'manual_review');

  SELECT * INTO v_case
    FROM public.subscription_delivery_alignment_cases
   WHERE id = v_case.id;

  RETURN jsonb_build_object(
    'caseId', v_case.id,
    'state', v_case.state,
    'confirmed', true,
    'nextCycleAt', v_case.aligned_next_cycle_at
  );
END;
$$;


--
-- Name: FUNCTION subscription_delivery_alignment_confirm_replacement(p_case_id uuid, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_delivery_alignment_confirm_replacement(p_case_id uuid, p_note text) IS 'Service-role operator confirmation that a substitute shipment reached the customer for one open delivery-alignment case. Shifts next_cycle_at one stored cadence past the confirmation instant, never earlier than the promised schedule, settles the predecessor order''s open cases as aligned, and is idempotent on replay. Takes no operator date: an operator-chosen instant could shorten a paid cycle unnoticed.';


--
-- Name: subscription_delivery_alignment_get_mode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_delivery_alignment_get_mode() RETURNS text
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT mode
    FROM public.subscription_delivery_alignment_control
   WHERE singleton = true
$$;


--
-- Name: subscription_delivery_alignment_guard_cycle_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_delivery_alignment_guard_cycle_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_subscription public.subscriptions%ROWTYPE;
  v_mode text;
  v_receipt_id uuid;
BEGIN
  IF NEW.status <> 'payment_pending' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_subscription
    FROM public.subscriptions
   WHERE id = NEW.subscription_id
   FOR UPDATE;
  IF NOT FOUND OR v_subscription.status <> 'active' THEN
    RETURN NEW;
  END IF;

  -- Expired-dunning recovery owns its fresh cycle through a separate tokenized
  -- workflow. It retains its own authority rather than becoming alignment dunning.
  IF EXISTS (
    SELECT 1 FROM public.subscription_dunning_cases
     WHERE subscription_id = NEW.subscription_id
       AND status = 'expired'
  ) THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.subscription_delivery_alignment_cases
     WHERE subscription_id = NEW.subscription_id
       AND state IN ('protected', 'manual_review')
  ) THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_protected' USING ERRCODE = 'P0001';
  END IF;

  SELECT mode INTO v_mode
    FROM public.subscription_delivery_alignment_control
   WHERE singleton = true;

  -- Only enforcing modes own the stale-schedule gate. Shadow observes without
  -- blocking, and an off rollout must be behaviorally inert for new cases.
  IF COALESCE(v_mode, 'off') IN ('off', 'shadow') THEN
    -- Consuming an aligned scheduled instant is a durable lifecycle transition,
    -- even when an operator turned new-case creation off after alignment.
    UPDATE public.subscription_delivery_alignment_cases
       SET state = 'released',
           updated_at = now()
     WHERE subscription_id = NEW.subscription_id
       AND state = 'aligned'
       AND aligned_next_cycle_at = NEW.scheduled_at;
    RETURN NEW;
  END IF;

  IF NEW.scheduled_at IS DISTINCT FROM v_subscription.next_cycle_at THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_stale_schedule' USING ERRCODE = '40001';
  END IF;

  -- Claim exactly one admission proof in the same transaction as the new
  -- cycle. A uniqueness conflict or later failure rolls this consumption back,
  -- allowing the runtime's normal idempotent retry without a second preflight.
  UPDATE public.subscription_delivery_alignment_admission_receipts
     SET consumed_at = now()
   WHERE subscription_id = NEW.subscription_id
     AND scheduled_at = NEW.scheduled_at
     AND observed_next_cycle_at = v_subscription.next_cycle_at
     AND decision = 'allowed'
     AND consumed_at IS NULL
   RETURNING id INTO v_receipt_id;
  IF v_receipt_id IS NULL THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_admission_required' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.subscription_delivery_alignment_cases
     SET state = 'released',
         updated_at = now()
   WHERE subscription_id = NEW.subscription_id
     AND state = 'aligned'
     AND aligned_next_cycle_at = NEW.scheduled_at;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_delivery_alignment_guard_cycle_insert(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_delivery_alignment_guard_cycle_insert() IS 'Atomic backstop before a new active subscription payment_pending cycle is inserted. In protect/auto_align it atomically consumes one current admission receipt, while rejecting stale schedules and protected/manual-review cases without touching dunning or existing cycles.';


--
-- Name: subscription_delivery_alignment_on_delivery(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_delivery_alignment_on_delivery() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_case public.subscription_delivery_alignment_cases%ROWTYPE;
  v_inherited_case_id uuid;
  v_order public.commerce_orders%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_open_dunning boolean;
  v_artifact_reason text;
  v_latest_delivered_at timestamptz;
  v_target timestamptz;
BEGIN
  IF NEW.delivered_at IS NULL
     OR (TG_OP = 'UPDATE' AND OLD.delivered_at IS NOT DISTINCT FROM NEW.delivered_at)
  THEN
    RETURN NEW;
  END IF;

  -- Derive the aggregate from the fulfillment's order, then lock it before
  -- examining its ledger. This fence is required even when there is no case
  -- yet: otherwise delivery could return on an empty lookup while concurrent
  -- admission creates protection from the not-yet-committed delivery.
  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE id = NEW.order_id
     AND mode = 'subscription_cycle'
     AND subscription_id IS NOT NULL;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_subscription
    FROM public.subscriptions
   WHERE id = v_order.subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  -- Admission or exception evidence may have changed the case while this
  -- transaction waited for the aggregate, so take the case lock only now.
  SELECT * INTO v_case
    FROM public.subscription_delivery_alignment_cases
   WHERE fulfillment_order_id = NEW.id
   FOR UPDATE;

  -- A replacement parcel is created after the case was already open, so it never
  -- carries a case of its own. It is the arrival the customer is actually
  -- waiting for, so it settles the case its predecessor opened on the same
  -- order. An open case is preferred because that is the one holding the
  -- renewal. Ordinary parcels never enter this branch: they replace nothing.
  IF NOT FOUND AND NEW.replaces_fulfillment_order_id IS NOT NULL THEN
    SELECT id INTO v_inherited_case_id
      FROM public.subscription_delivery_alignment_cases
     WHERE predecessor_order_id = NEW.order_id
     ORDER BY (state IN ('protected', 'manual_review')) DESC, created_at ASC, id ASC
     LIMIT 1;
    IF v_inherited_case_id IS NOT NULL THEN
      SELECT * INTO v_case
        FROM public.subscription_delivery_alignment_cases
       WHERE id = v_inherited_case_id
       FOR UPDATE;
    END IF;
  END IF;
  IF v_case.id IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE public.subscription_delivery_alignment_cases
     SET delivered_at = LEAST(COALESCE(delivered_at, NEW.delivered_at), NEW.delivered_at),
         updated_at = now()
   WHERE id = v_case.id
   RETURNING * INTO v_case;

  -- Outstanding means the customer is still waiting for it. A parcel that
  -- another row supersedes through replaces_fulfillment_order_id has been
  -- answered by that replacement, and when it was lost its delivered_at stays
  -- null for ever - counting it would hold this case open for ever with it.
  IF EXISTS (
    SELECT 1 FROM public.commerce_fulfillment_orders outstanding
     WHERE outstanding.order_id = v_case.predecessor_order_id
       AND outstanding.delivered_at IS NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.commerce_fulfillment_orders successor
          WHERE successor.replaces_fulfillment_order_id = outstanding.id
       )
  ) THEN
    RETURN NEW;
  END IF;

  IF v_subscription.status <> 'active' THEN
    UPDATE public.subscription_delivery_alignment_cases
       SET state = CASE WHEN state = 'protected' THEN 'released' ELSE state END,
           updated_at = now()
     WHERE predecessor_order_id = v_case.predecessor_order_id;
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.subscription_dunning_cases
     WHERE subscription_id = v_subscription.id
       AND status IN ('open', 'expired')
  ) INTO v_open_dunning;
  IF v_open_dunning THEN
    UPDATE public.subscription_delivery_alignment_cases
       SET state = CASE WHEN state = 'protected' THEN 'manual_review' ELSE state END,
           manual_review_reason = CASE WHEN state = 'protected' THEN 'open_dunning' ELSE manual_review_reason END,
           updated_at = now()
     WHERE predecessor_order_id = v_case.predecessor_order_id;
    RETURN NEW;
  END IF;

  SELECT CASE
    WHEN EXISTS (
      SELECT 1
        FROM public.subscription_cycles successor
        JOIN public.commerce_payment_intents intent ON intent.subscription_cycle_id = successor.id
        JOIN public.commerce_payment_attempts attempt ON attempt.payment_intent_id = intent.id
       WHERE successor.subscription_id = v_subscription.id
         AND successor.cycle_number > v_case.predecessor_cycle_number
    ) THEN 'existing_provider_attempt'
    WHEN EXISTS (
      SELECT 1 FROM public.subscription_cycles successor
       WHERE successor.subscription_id = v_subscription.id
         AND successor.cycle_number > v_case.predecessor_cycle_number
    ) THEN 'renewal_cycle_already_created'
    ELSE NULL
  END INTO v_artifact_reason;

  IF v_artifact_reason IS NOT NULL THEN
    UPDATE public.subscription_delivery_alignment_cases
       SET state = CASE WHEN state = 'protected' THEN 'manual_review' ELSE state END,
           manual_review_reason = CASE WHEN state = 'protected' THEN v_artifact_reason ELSE manual_review_reason END,
           updated_at = now()
     WHERE predecessor_order_id = v_case.predecessor_order_id;
    RETURN NEW;
  END IF;

  IF v_case.state <> 'protected' THEN
    RETURN NEW;
  END IF;
  IF v_case.captured_mode = 'protect' THEN
    UPDATE public.subscription_delivery_alignment_cases
       SET state = CASE WHEN state = 'protected' THEN 'released' ELSE state END,
           updated_at = now()
     WHERE predecessor_order_id = v_case.predecessor_order_id;
    RETURN NEW;
  END IF;
  IF v_case.captured_mode <> 'auto_align' THEN
    RETURN NEW;
  END IF;

  -- With a split shipment, delivery events can arrive in either chronology.
  -- Preserve the interval from the last parcel delivered, not necessarily from
  -- the final webhook processed by this transaction.
  SELECT max(delivered_at) INTO v_latest_delivered_at
    FROM public.commerce_fulfillment_orders
   WHERE order_id = v_case.predecessor_order_id;
  v_target := v_latest_delivered_at + make_interval(days => v_subscription.cadence_days);
  UPDATE public.subscriptions
     SET next_cycle_at = CASE
           WHEN next_cycle_at IS NULL THEN v_target
           ELSE GREATEST(next_cycle_at, v_target)
         END,
         updated_at = now()
   WHERE id = v_subscription.id
   RETURNING next_cycle_at INTO v_target;

  UPDATE public.subscription_delivery_alignment_cases
     SET state = CASE WHEN state = 'protected' THEN 'aligned' ELSE state END,
         aligned_next_cycle_at = CASE WHEN state = 'protected' THEN v_target ELSE aligned_next_cycle_at END,
         aligned_at = CASE WHEN state = 'protected' THEN now() ELSE aligned_at END,
         updated_at = now()
   WHERE predecessor_order_id = v_case.predecessor_order_id;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_delivery_alignment_on_delivery(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_delivery_alignment_on_delivery() IS 'AFTER trigger settling one delivery-alignment case from a durable delivered_at. A replacement parcel carries no case of its own and settles the case its predecessor opened on the same order; a parcel superseded through replaces_fulfillment_order_id is not an obligation and never holds a case open. In auto_align the settlement shifts next_cycle_at one cadence past the order''s latest delivery, GREATEST-clamped so a cycle can only extend.';


--
-- Name: subscription_delivery_alignment_open_exception_case(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_delivery_alignment_open_exception_case() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_mode text;
  v_order public.commerce_orders%ROWTYPE;
  v_cycle public.subscription_cycles%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_fulfillment public.commerce_fulfillment_orders%ROWTYPE;
  v_found boolean := false;
BEGIN
  IF NEW.reason <> 'fulfillment_exception' OR NEW.status <> 'active' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.reason = 'fulfillment_exception' AND OLD.status = 'active' THEN
    RETURN NEW;
  END IF;

  SELECT mode INTO v_mode FROM public.subscription_delivery_alignment_control WHERE singleton = true;
  IF COALESCE(v_mode, 'off') = 'off' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_order FROM public.commerce_orders WHERE id = NEW.order_id;
  IF NOT FOUND OR v_order.mode IS DISTINCT FROM 'subscription_cycle' OR v_order.subscription_cycle_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT * INTO v_cycle FROM public.subscription_cycles WHERE id = v_order.subscription_cycle_id;
  SELECT * INTO v_subscription FROM public.subscriptions WHERE id = v_order.subscription_id FOR UPDATE;
  IF NOT FOUND OR v_subscription.status <> 'active' OR v_cycle.status IS DISTINCT FROM 'paid' THEN
    RETURN NEW;
  END IF;

  FOR v_fulfillment IN
    SELECT * FROM public.commerce_fulfillment_orders
     WHERE order_id = v_order.id
     ORDER BY created_at ASC, id ASC
  LOOP
    v_found := true;
    PERFORM public.subscription_delivery_alignment_upsert_case(
      v_fulfillment.id, v_order.id, v_subscription.id, v_cycle.id,
      v_cycle.cycle_number, v_mode, 'fulfillment_exception', v_subscription.next_cycle_at
    );
  END LOOP;
  IF NOT v_found THEN
    PERFORM public.subscription_delivery_alignment_upsert_case(
      NULL, v_order.id, v_subscription.id, v_cycle.id,
      v_cycle.cycle_number, v_mode, 'missing_fulfillment',
      v_subscription.next_cycle_at,
      CASE WHEN v_mode = 'shadow' THEN NULL ELSE 'fulfillment_exception_without_fulfillment' END
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: subscription_delivery_alignment_record_allowed_receipt(uuid, timestamp with time zone, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_delivery_alignment_record_allowed_receipt(p_subscription_id uuid, p_scheduled_at timestamp with time zone, p_observed_next_cycle_at timestamp with time zone, p_source text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_subscription_id IS NULL
     OR p_scheduled_at IS NULL
     OR p_observed_next_cycle_at IS NULL
     OR p_source <> 'renewal_admission'
  THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_invalid_receipt' USING ERRCODE = '22023';
  END IF;

  -- A subscription can hold at most one future admission token. The caller
  -- already owns the subscription lock, so clearing an obsolete unconsumed
  -- schedule cannot race a valid creator and bounds replay/stale buildup.
  DELETE FROM public.subscription_delivery_alignment_admission_receipts
   WHERE subscription_id = p_subscription_id
     AND consumed_at IS NULL
     AND scheduled_at <> p_scheduled_at;

  INSERT INTO public.subscription_delivery_alignment_admission_receipts (
    subscription_id, scheduled_at, observed_next_cycle_at, source, metadata
  ) VALUES (
    p_subscription_id, p_scheduled_at, p_observed_next_cycle_at, p_source,
    jsonb_build_object('source', 'subscription_delivery_alignment')
  )
  ON CONFLICT (subscription_id, scheduled_at) DO UPDATE
    SET observed_next_cycle_at = EXCLUDED.observed_next_cycle_at,
        source = EXCLUDED.source,
        admitted_at = now(),
        metadata = EXCLUDED.metadata
    WHERE public.subscription_delivery_alignment_admission_receipts.consumed_at IS NULL;
END;
$$;


--
-- Name: subscription_delivery_alignment_resolve_case(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_delivery_alignment_resolve_case(p_case_id uuid, p_resolution text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_case public.subscription_delivery_alignment_cases%ROWTYPE;
  v_subscription_id uuid;
  v_subscription_status text;
BEGIN
  IF p_case_id IS NULL
     OR p_resolution NOT IN ('operator_confirmed', 'retry_succeeded', 'false_positive')
     OR NULLIF(btrim(p_note), '') IS NULL
  THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_invalid_resolution' USING ERRCODE = '22023';
  END IF;

  -- Discover identity without locking the ledger first; all mutable alignment
  -- paths own subscription -> ledger case to avoid delivery/admission deadlock.
  SELECT subscription_id INTO v_subscription_id
    FROM public.subscription_delivery_alignment_cases
   WHERE id = p_case_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_case_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT status INTO v_subscription_status
    FROM public.subscriptions
   WHERE id = v_subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_subscription_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_case
    FROM public.subscription_delivery_alignment_cases
   WHERE id = p_case_id
   FOR UPDATE;
  IF v_case.state NOT IN ('protected', 'manual_review') THEN
    RETURN jsonb_build_object('caseId', v_case.id, 'state', v_case.state, 'resolved', false, 'reason', 'not_open');
  END IF;

  -- Release is now real permission for the next autonomous charge, so it may not
  -- be spent on a shipment that has not arrived. Releasing here would take money
  -- for goods the customer never received and, because every open-case
  -- projection keys on the open states, would take the case off the operator
  -- queue, the overdue counter and the customer banner at the same time. The
  -- honest exits are the durable delivery, a confirmed replacement, or ending
  -- the subscription first. A case with no fulfillment row at all is untouched:
  -- it has no delivery fact to wait for, and operator judgement is the only tool
  -- that corruption case has.
  IF v_subscription_status = 'active'
     AND EXISTS (
       SELECT 1
         FROM public.commerce_fulfillment_orders outstanding
        WHERE outstanding.order_id = v_case.predecessor_order_id
          AND outstanding.delivered_at IS NULL
          AND NOT EXISTS (
            SELECT 1 FROM public.commerce_fulfillment_orders successor
             WHERE successor.replaces_fulfillment_order_id = outstanding.id
          )
     )
  THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_release_would_strand' USING ERRCODE = '22023';
  END IF;

  UPDATE public.subscription_delivery_alignment_cases
     SET state = 'released',
         updated_at = now(),
         metadata = metadata || jsonb_build_object(
           'manualResolution',
           jsonb_build_object('code', p_resolution, 'note', p_note, 'resolvedAt', now())
         )
   WHERE id = v_case.id
   RETURNING * INTO v_case;

  RETURN jsonb_build_object('caseId', v_case.id, 'state', v_case.state, 'resolved', true, 'resolution', p_resolution);
END;
$$;


--
-- Name: FUNCTION subscription_delivery_alignment_resolve_case(p_case_id uuid, p_resolution text, p_note text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_delivery_alignment_resolve_case(p_case_id uuid, p_resolution text, p_note text) IS 'Service-role operational resolution for one protected/manual delivery-alignment case. Requires an explicit code and note; releases only ledger state and appends metadata audit without mutating money or dunning. Refuses to release while the predecessor order still has an undelivered fulfilment row the customer is waiting for - a superseded row does not count - because that release would re-arm a charge for goods that never arrived and silence every open-case projection at once.';


--
-- Name: subscription_delivery_alignment_set_mode(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_delivery_alignment_set_mode(p_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_mode IS NULL OR p_mode NOT IN ('off', 'shadow', 'protect', 'auto_align') THEN
    RAISE EXCEPTION 'subscription_delivery_alignment_invalid_mode' USING ERRCODE = '22023';
  END IF;

  UPDATE public.subscription_delivery_alignment_control
     SET mode = p_mode,
         updated_at = now()
   WHERE singleton = true;

  RETURN jsonb_build_object('mode', p_mode, 'updatedAt', now());
END;
$$;


--
-- Name: subscription_delivery_alignment_upsert_case(uuid, uuid, uuid, uuid, integer, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_delivery_alignment_upsert_case(p_fulfillment_order_id uuid, p_predecessor_order_id uuid, p_subscription_id uuid, p_predecessor_cycle_id uuid, p_predecessor_cycle_number integer, p_mode text, p_evidence_kind text, p_observed_next_cycle_at timestamp with time zone, p_manual_review_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_state text;
BEGIN
  IF p_mode NOT IN ('shadow', 'protect', 'auto_align') THEN
    RETURN;
  END IF;

  v_state := CASE
    WHEN p_manual_review_reason IS NOT NULL THEN 'manual_review'
    WHEN p_mode = 'shadow' THEN 'shadow'
    ELSE 'protected'
  END;

  IF p_fulfillment_order_id IS NULL THEN
    INSERT INTO public.subscription_delivery_alignment_cases (
      fulfillment_order_id, predecessor_order_id, subscription_id,
      predecessor_cycle_id, predecessor_cycle_number, captured_mode, state,
      evidence_kind, observed_next_cycle_at, manual_review_reason, metadata
    ) VALUES (
      NULL, p_predecessor_order_id, p_subscription_id,
      p_predecessor_cycle_id, p_predecessor_cycle_number, p_mode, v_state,
      p_evidence_kind, p_observed_next_cycle_at,
      p_manual_review_reason,
      jsonb_build_object('source', 'subscription_delivery_alignment')
    )
    ON CONFLICT (predecessor_order_id) WHERE fulfillment_order_id IS NULL DO UPDATE
      SET updated_at = now(),
          observed_next_cycle_at = EXCLUDED.observed_next_cycle_at,
          evidence_kind = EXCLUDED.evidence_kind,
          state = CASE
            WHEN public.subscription_delivery_alignment_cases.state IN ('aligned', 'released')
              THEN public.subscription_delivery_alignment_cases.state
            ELSE EXCLUDED.state
          END,
          captured_mode = CASE
            WHEN public.subscription_delivery_alignment_cases.state IN ('aligned', 'released')
              THEN public.subscription_delivery_alignment_cases.captured_mode
            ELSE EXCLUDED.captured_mode
          END,
          manual_review_reason = COALESCE(
            public.subscription_delivery_alignment_cases.manual_review_reason,
            EXCLUDED.manual_review_reason
          );
    RETURN;
  END IF;

  INSERT INTO public.subscription_delivery_alignment_cases (
    fulfillment_order_id, predecessor_order_id, subscription_id,
    predecessor_cycle_id, predecessor_cycle_number, captured_mode, state,
    evidence_kind, observed_next_cycle_at, manual_review_reason, metadata
  ) VALUES (
    p_fulfillment_order_id, p_predecessor_order_id, p_subscription_id,
    p_predecessor_cycle_id, p_predecessor_cycle_number, p_mode, v_state,
    p_evidence_kind, p_observed_next_cycle_at, p_manual_review_reason,
    jsonb_build_object('source', 'subscription_delivery_alignment')
  )
  ON CONFLICT (fulfillment_order_id) WHERE fulfillment_order_id IS NOT NULL DO UPDATE
    SET updated_at = now(),
        observed_next_cycle_at = EXCLUDED.observed_next_cycle_at,
        evidence_kind = EXCLUDED.evidence_kind,
        state = CASE
          WHEN public.subscription_delivery_alignment_cases.state IN ('aligned', 'released')
            THEN public.subscription_delivery_alignment_cases.state
          WHEN EXCLUDED.state = 'manual_review' THEN 'manual_review'
          WHEN EXCLUDED.state = 'protected' THEN 'protected'
          ELSE public.subscription_delivery_alignment_cases.state
        END,
        captured_mode = CASE
          WHEN public.subscription_delivery_alignment_cases.state IN ('aligned', 'released')
            THEN public.subscription_delivery_alignment_cases.captured_mode
          WHEN EXCLUDED.state IN ('protected', 'manual_review') THEN EXCLUDED.captured_mode
          ELSE public.subscription_delivery_alignment_cases.captured_mode
        END,
        manual_review_reason = COALESCE(
          public.subscription_delivery_alignment_cases.manual_review_reason,
          EXCLUDED.manual_review_reason
        );
END;
$$;


--
-- Name: subscription_dispatch_pause_reminders(integer, timestamp with time zone, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_dispatch_pause_reminders(p_limit integer DEFAULT 100, p_now timestamp with time zone DEFAULT now(), p_reminder_window interval DEFAULT '3 days'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scanned integer := 0;
  v_queued integer := 0;
  v_skipped integer := 0;
  v_failed integer := 0;
  v_row record;
  v_inserted integer;
  v_next_delivery_at timestamptz;
BEGIN
  FOR v_row IN
    SELECT
      pw.id AS pause_window_id,
      pw.subscription_id,
      pw.pause_preset,
      pw.starts_at,
      pw.ends_at,
      s.client_id,
      s.next_cycle_at,
      s.cadence_days
    FROM public.subscription_pause_windows pw
    JOIN public.subscriptions s ON s.id = pw.subscription_id
    WHERE pw.resumed_at IS NULL
      AND pw.ends_at IS NOT NULL
      AND pw.ends_at > p_now
      AND pw.ends_at <= p_now + p_reminder_window
      AND s.status = 'paused'
    ORDER BY pw.ends_at, pw.id
    LIMIT GREATEST(COALESCE(p_limit, 0), 0)
  LOOP
    v_scanned := v_scanned + 1;
    BEGIN
      v_next_delivery_at := v_row.next_cycle_at;
      IF v_next_delivery_at IS NOT NULL
         AND v_row.cadence_days IS NOT NULL
         AND v_row.cadence_days > 0
         AND v_next_delivery_at <= v_row.ends_at THEN
        v_next_delivery_at := v_next_delivery_at + ((
          floor(extract(epoch FROM (v_row.ends_at - v_next_delivery_at)) / (v_row.cadence_days * 86400.0))::bigint + 1
        ) * v_row.cadence_days || ' days')::interval;
      END IF;

      INSERT INTO public.outbox_events (
        aggregate_type,
        aggregate_id,
        event_type,
        idempotency_key,
        payload,
        metadata
      )
      VALUES (
        'subscription',
        v_row.subscription_id,
        'subscription.pause_reminder_due',
        'subscription_pause_reminder:' || v_row.pause_window_id::text,
        jsonb_build_object(
          'subscriptionId', v_row.subscription_id,
          'clientId', v_row.client_id,
          'pauseWindowId', v_row.pause_window_id,
          'pausePreset', v_row.pause_preset,
          'pauseEndsAt', v_row.ends_at,
          'nextDeliveryAt', v_next_delivery_at,
          'resumeAt', v_next_delivery_at,
          'occurredAt', p_now
        ),
        jsonb_build_object('source', 'subscription_dispatch_pause_reminders')
      )
      ON CONFLICT (event_type, idempotency_key) DO NOTHING;

      GET DIAGNOSTICS v_inserted = ROW_COUNT;
      IF v_inserted > 0 THEN
        v_queued := v_queued + 1;
      ELSE
        v_skipped := v_skipped + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', v_failed = 0,
    'scanned', v_scanned,
    'queued', v_queued,
    'sent', 0,
    'skipped', v_skipped,
    'failed', v_failed
  );
END;
$$;


--
-- Name: FUNCTION subscription_dispatch_pause_reminders(p_limit integer, p_now timestamp with time zone, p_reminder_window interval); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_dispatch_pause_reminders(p_limit integer, p_now timestamp with time zone, p_reminder_window interval) IS 'Queues idempotent subscription.pause_reminder_due outbox events for timed pauses approaching their resume timestamp.';


--
-- Name: subscription_dunning_apply_intent_amount_payload(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_dunning_apply_intent_amount_payload() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_intent public.commerce_payment_intents%ROWTYPE;
BEGIN
  IF NEW.payment_intent_id IS NULL OR NOT (NEW.payload ? 'amountMinor') THEN
    RETURN NEW;
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = NEW.payment_intent_id;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  NEW.payload := jsonb_set(NEW.payload, '{amountMinor}', to_jsonb(v_intent.amount_cents), true);
  NEW.payload := jsonb_set(NEW.payload, '{currency}', to_jsonb(v_intent.currency), true);
  NEW.payload := jsonb_set(NEW.payload, '{amountSource}', to_jsonb('commerce_payment_intents.amount_cents'::text), true);
  RETURN NEW;
END;
$$;


--
-- Name: subscription_dunning_notifications; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subscription_dunning_notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    case_id uuid NOT NULL,
    subscription_id uuid NOT NULL,
    cycle_id uuid NOT NULL,
    order_id uuid NOT NULL,
    payment_intent_id uuid NOT NULL,
    recipient_kind text NOT NULL,
    recipient_ref uuid,
    notification_kind text NOT NULL,
    template_slug text NOT NULL,
    retry_attempt integer,
    idempotency_key text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    scheduled_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    resend_id text,
    provider_error text,
    recovery_url_path text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    send_attempts integer DEFAULT 0 NOT NULL,
    resend_idempotency_started_at timestamp with time zone,
    CONSTRAINT subscription_dunning_notifications_recipient_kind_check CHECK ((recipient_kind = ANY (ARRAY['customer'::text, 'admin'::text]))),
    CONSTRAINT subscription_dunning_notifications_retry_attempt_check CHECK (((retry_attempt IS NULL) OR (retry_attempt >= 1))),
    CONSTRAINT subscription_dunning_notifications_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'sending'::text, 'sent'::text, 'failed'::text, 'skipped'::text])))
);


--
-- Name: subscription_dunning_claim_batch(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_dunning_claim_batch(p_batch_size integer DEFAULT 25, p_lease_seconds integer DEFAULT 300, p_max_attempts integer DEFAULT 6) RETURNS SETOF public.subscription_dunning_notifications
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Repair only currently-retryable candidates with one indexed lookup per
  -- notification. This avoids scanning/sorting every dunning ledger row.
  WITH repair_candidates AS (
    SELECT notification.id
      FROM public.subscription_dunning_notifications notification
     WHERE notification.recipient_kind = 'customer'
       AND notification.resend_id IS NULL
       AND (
         (notification.status = 'queued' AND notification.scheduled_at <= now())
         OR (notification.status = 'sending'
             AND notification.updated_at < now() - make_interval(secs => p_lease_seconds))
       )
  ), provider_success AS (
    SELECT candidate.id AS notification_id, send.resend_id, send.sent_at
      FROM repair_candidates candidate
      CROSS JOIN LATERAL (
        SELECT email_send.resend_id, email_send.sent_at
          FROM public.email_sends email_send
         WHERE email_send.source = 'subscription-dunning-dispatch'
           AND email_send.resend_id IS NOT NULL
           AND email_send.provider_response->>'notificationId' = candidate.id::text
         ORDER BY email_send.sent_at DESC NULLS LAST, email_send.created_at DESC, email_send.id DESC
         LIMIT 1
      ) send
  )
  UPDATE public.subscription_dunning_notifications notification
     SET status = 'sent',
         sent_at = coalesce(notification.sent_at, provider_success.sent_at, now()),
         resend_id = provider_success.resend_id,
         provider_error = NULL,
         updated_at = now()
    FROM provider_success
   WHERE notification.id = provider_success.notification_id
     AND notification.status IN ('queued', 'sending')
     AND notification.resend_id IS NULL;

  -- Never use updated_at here: reclaiming a lease and requeueing both update it
  -- while the provider key's retention clock keeps advancing.
  UPDATE public.subscription_dunning_notifications notification
     SET status = 'failed',
         provider_error = 'resend_idempotency_window_expired_manual_review',
         updated_at = now()
   WHERE notification.recipient_kind = 'customer'
     AND notification.status IN ('queued', 'sending')
     AND notification.resend_idempotency_started_at < now() - interval '23 hours';

  RETURN QUERY
  WITH claimable AS (
    SELECT notification.id
      FROM public.subscription_dunning_notifications notification
      JOIN public.subscription_dunning_cases dunning_case
        ON dunning_case.id = notification.case_id
       AND dunning_case.status IN ('open', 'expired')
     WHERE notification.recipient_kind = 'customer'
       AND notification.send_attempts < p_max_attempts
       AND (
         (notification.status = 'queued' AND notification.scheduled_at <= now())
         OR (notification.status = 'sending'
             AND notification.updated_at < now() - make_interval(secs => p_lease_seconds))
     )
     ORDER BY notification.scheduled_at
     FOR UPDATE OF notification SKIP LOCKED
     LIMIT GREATEST(p_batch_size, 0)
  )
  UPDATE public.subscription_dunning_notifications notification
     SET status = 'sending',
         send_attempts = notification.send_attempts + 1,
         updated_at = now(),
         resend_idempotency_started_at = coalesce(notification.resend_idempotency_started_at, now())
    FROM claimable
   WHERE notification.id = claimable.id
  RETURNING notification.*;
END;
$$;


--
-- Name: FUNCTION subscription_dunning_claim_batch(p_batch_size integer, p_lease_seconds integer, p_max_attempts integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_dunning_claim_batch(p_batch_size integer, p_lease_seconds integer, p_max_attempts integer) IS 'Repairs a dunning notification from durable Resend evidence before lease reclaim; retries outside the immutable provider idempotency window require manual review.';


--
-- Name: subscription_dunning_mark_result(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_dunning_mark_result(p_id uuid, p_status text, p_error text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT public.subscription_dunning_mark_result(p_id, p_status, p_error, NULL::timestamptz);
$$;


--
-- Name: subscription_dunning_mark_result(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_dunning_mark_result(p_id uuid, p_status text, p_error text, p_reschedule_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_status NOT IN ('queued', 'failed', 'skipped') THEN
    RAISE EXCEPTION 'subscription_dunning_mark_result: invalid status %', p_status
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.subscription_dunning_notifications
     SET status = p_status,
         scheduled_at = CASE
           WHEN p_status = 'queued' AND p_reschedule_at IS NOT NULL
             THEN GREATEST(p_reschedule_at, now())
           ELSE scheduled_at
         END,
         provider_error = left(p_error, 500),
         updated_at = now()
   WHERE id = p_id;
END;
$$;


--
-- Name: subscription_dunning_mark_result(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_dunning_mark_result(p_id uuid, p_claim_token text, p_status text, p_error text, p_reschedule_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_status NOT IN ('queued', 'failed', 'skipped') THEN RAISE EXCEPTION 'subscription_dunning_mark_result: invalid status %', p_status USING ERRCODE = 'check_violation'; END IF;
  IF p_claim_token IS NULL OR btrim(p_claim_token) = '' THEN
    RETURN false;
  END IF;
  PERFORM 1
    FROM public.subscription_dunning_notifications
   WHERE id = p_id
     AND status = 'sending'
     AND payload->>'claimToken' = p_claim_token
     FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  PERFORM set_config('app.subscription_dunning_claim_token', p_claim_token, true);
  PERFORM public.subscription_dunning_mark_result(
    p_id, p_status, p_error, p_reschedule_at
  );
  PERFORM set_config('app.subscription_dunning_claim_token', '', true);
  RETURN true;
END;
$$;


--
-- Name: FUNCTION subscription_dunning_mark_result(p_id uuid, p_claim_token text, p_status text, p_error text, p_reschedule_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_dunning_mark_result(p_id uuid, p_claim_token text, p_status text, p_error text, p_reschedule_at timestamp with time zone) IS 'Applies retry/terminal dunning outcomes only for the current claimToken.';


--
-- Name: subscription_dunning_mark_sent(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_dunning_mark_sent(p_id uuid, p_resend_id text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  UPDATE public.subscription_dunning_notifications
     SET status = 'sent',
         sent_at = now(),
         resend_id = p_resend_id,
         provider_error = NULL,
         updated_at = now()
   WHERE id = p_id;
$$;


--
-- Name: subscription_dunning_mark_sent(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_dunning_mark_sent(p_id uuid, p_claim_token text, p_delivery_id text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_claim_token IS NULL OR btrim(p_claim_token) = '' THEN
    RETURN false;
  END IF;
  PERFORM 1
    FROM public.subscription_dunning_notifications
   WHERE id = p_id
     AND status = 'sending'
     AND payload->>'claimToken' = p_claim_token
     FOR UPDATE;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  PERFORM set_config('app.subscription_dunning_claim_token', p_claim_token, true);
  PERFORM public.subscription_dunning_mark_sent(p_id, p_delivery_id);
  PERFORM set_config('app.subscription_dunning_claim_token', '', true);
  RETURN true;
END;
$$;


--
-- Name: FUNCTION subscription_dunning_mark_sent(p_id uuid, p_claim_token text, p_delivery_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_dunning_mark_sent(p_id uuid, p_claim_token text, p_delivery_id text) IS 'Marks one sending dunning notification sent only for its current claimToken.';


--
-- Name: subscription_dunning_record_email_attempt(text, uuid, text, text, timestamp with time zone, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_dunning_record_email_attempt(p_template_slug text, p_notification_id uuid, p_resend_id text, p_status text, p_sent_at timestamp with time zone, p_provider_error text, p_provider_response jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_existing public.email_sends%ROWTYPE;
  v_response jsonb;
BEGIN
  IF p_notification_id IS NULL OR p_template_slug IS NULL OR btrim(p_template_slug) = '' THEN
    RAISE EXCEPTION 'subscription_dunning_email_attempt_invalid_input' USING ERRCODE = '22023';
  END IF;
  IF p_status IS NULL OR p_status NOT IN ('sent', 'failed') THEN
    RAISE EXCEPTION 'subscription_dunning_email_attempt_invalid_status %', p_status
      USING ERRCODE = 'check_violation';
  END IF;

  v_response := coalesce(p_provider_response, '{}'::jsonb)
    || jsonb_build_object('notificationId', p_notification_id::text);

  -- One lock spans all retry attempts for this durable notification identity.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'subscription-dunning-email-attempt:' || p_notification_id::text,
    0
  ));

  SELECT send.* INTO v_existing
    FROM public.email_sends send
   WHERE send.source = 'subscription-dunning-dispatch'
     AND send.provider_response->>'notificationId' = p_notification_id::text
   ORDER BY send.created_at, send.id
   LIMIT 1
   FOR UPDATE;

  IF v_existing.id IS NULL THEN
    INSERT INTO public.email_sends (
      tester_id,
      template_slug,
      source,
      resend_id,
      status,
      sent_at,
      provider_error,
      provider_response
    ) VALUES (
      NULL,
      p_template_slug,
      'subscription-dunning-dispatch',
      nullif(btrim(p_resend_id), ''),
      p_status,
      p_sent_at,
      left(p_provider_error, 500),
      v_response
    );
    RETURN;
  END IF;

  IF v_existing.resend_id IS NOT NULL
     AND nullif(btrim(p_resend_id), '') IS NOT NULL
     AND v_existing.resend_id <> nullif(btrim(p_resend_id), '')
  THEN
    RAISE EXCEPTION 'subscription_dunning_provider_message_collision'
      USING ERRCODE = '23505';
  END IF;

  UPDATE public.email_sends
     SET template_slug = p_template_slug,
         resend_id = coalesce(v_existing.resend_id, nullif(btrim(p_resend_id), '')),
         status = CASE
           WHEN v_existing.resend_id IS NOT NULL
             OR v_existing.status IN ('sent', 'delivered', 'bounced', 'complained')
             THEN v_existing.status
           ELSE p_status
         END,
         sent_at = coalesce(v_existing.sent_at, p_sent_at),
         provider_error = CASE
           WHEN v_existing.resend_id IS NOT NULL
             OR v_existing.status IN ('sent', 'delivered', 'bounced', 'complained')
             THEN v_existing.provider_error
           ELSE left(p_provider_error, 500)
         END,
         provider_response = coalesce(v_existing.provider_response, '{}'::jsonb) || v_response
   WHERE id = v_existing.id;
END;
$$;


--
-- Name: FUNCTION subscription_dunning_record_email_attempt(p_template_slug text, p_notification_id uuid, p_resend_id text, p_status text, p_sent_at timestamp with time zone, p_provider_error text, p_provider_response jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_dunning_record_email_attempt(p_template_slug text, p_notification_id uuid, p_resend_id text, p_status text, p_sent_at timestamp with time zone, p_provider_error text, p_provider_response jsonb) IS 'Serializes one email_sends identity per subscription dunning notification and rejects conflicting Resend ids.';


--
-- Name: subscription_dunning_stamp_claim_token(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_dunning_stamp_claim_token() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status = 'sending'
     AND (
       OLD.status IS DISTINCT FROM 'sending'
       OR NEW.send_attempts > OLD.send_attempts
     )
  THEN
    NEW.payload := jsonb_set(
      coalesce(NEW.payload, '{}'::jsonb),
      '{claimToken}',
      to_jsonb(gen_random_uuid()::text),
      true
    );
  END IF;
  IF OLD.status = 'sending'
     AND coalesce(OLD.payload, '{}'::jsonb) ? 'claimToken'
     AND NEW.status IS DISTINCT FROM OLD.status
     AND current_setting('app.subscription_dunning_claim_token', true)
       IS DISTINCT FROM OLD.payload->>'claimToken'
     AND NOT (
       NEW.status = 'sent'
       AND EXISTS (
         SELECT 1
          FROM public.email_sends email_send
         WHERE email_send.source = 'subscription-dunning-dispatch'
            AND email_send.resend_id IS NOT NULL
            AND email_send.provider_response->>'notificationId' = OLD.id::text
       )
     )
     -- C1: subscription_dunning_claim_batch routing an attempt outside the
     -- provider's immutable idempotency retention to manual review.
     AND NOT (
       NEW.status = 'failed'
       AND NEW.provider_error
         IS NOT DISTINCT FROM 'resend_idempotency_window_expired_manual_review'
     )
     -- C2: the payment-control recovery branch skipping the pending decline
     -- notification of a cycle that has since been paid. Mirrors the writer's
     -- COALESCE so a row that already carries a provider_error is skipped too.
     AND NOT (
       NEW.status = 'skipped'
       AND NEW.provider_error
         IS NOT DISTINCT FROM coalesce(OLD.provider_error, 'cycle_recovered')
     )
  THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_dunning_stamp_claim_token(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_dunning_stamp_claim_token() IS 'Stamps a fresh payload claimToken only when claim evidence advances, and fences a stale worker out of requeueing or falsely completing a leased row. System terminalizations (manual-review expiry, cycle-recovered skip) pass without a claim token because they send nothing and end the lease.';


--
-- Name: subscription_emit_cancelled_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_emit_cancelled_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_reason text := NULLIF(btrim(COALESCE(NEW.cancellation_reason, '')), '');
  v_source text := 'system_unknown';
BEGIN
  IF NEW.status IS DISTINCT FROM 'cancelled' THEN
    RETURN NEW;
  END IF;
  IF OLD.status IS NOT DISTINCT FROM 'cancelled' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.subscription_cycles sc
     WHERE sc.subscription_id = NEW.id
       AND sc.failure_reason = 'refund_reversed_activation'
  ) THEN
    v_source := 'system_refund_reversal';
    v_reason := 'refund_reversed_activation';
  ELSIF EXISTS (
    SELECT 1
      FROM public.subscription_cycles sc
      JOIN public.commerce_orders co ON co.subscription_cycle_id = sc.id
     WHERE sc.subscription_id = NEW.id
       AND co.metadata->>'source' = 'subscription.sweep.v0'
  ) THEN
    v_source := 'system_provisional_activation_timeout';
    v_reason := 'subscription_activation_abandoned';
  ELSIF NEW.cancellation_source = 'customer_self_service' THEN
    v_source := 'customer';
  END IF;

  INSERT INTO public.outbox_events (
    aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
  )
  VALUES (
    'subscription',
    NEW.id,
    'subscription.cancelled',
    'subscription_cancelled:' || NEW.id::text,
    jsonb_build_object(
      'subscriptionId', NEW.id,
      'clientId', NEW.client_id,
      'cancellationSource', v_source,
      'cancellationReason', COALESCE(v_reason, CASE WHEN v_source = 'customer' THEN 'customer_cancelled' ELSE v_source END),
      'occurredAt', now()
    ),
    jsonb_build_object('source', 'subscription_emit_cancelled_outbox')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_emit_cancelled_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_emit_cancelled_outbox() IS 'Emits subscription.cancelled outbox events fail-closed: customer email sends only after positive customer_self_service provenance.';


--
-- Name: subscription_emit_created_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_emit_created_outbox() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Only the activation moment. Skip the provisional pending_activation INSERT
  -- (pre-payment, next_cycle_at NULL) and any update that doesn't reach active.
  IF NEW.status IS DISTINCT FROM 'active' THEN
    RETURN NEW;
  END IF;

  -- On UPDATE, emit ONLY for the first activation (pending_activation -> active).
  -- This excludes resume/auto-resume (paused -> active) and re-saves (active -> active),
  -- which previously re-fired the welcome email once the outbox dedup row was pruned.
  IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM 'pending_activation' THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.outbox_events (
    aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
  )
  VALUES (
    'subscription',
    NEW.id,
    'subscription.created',
    'subscription_created:' || NEW.id::text,
    jsonb_build_object(
      'subscriptionId', NEW.id,
      'clientId', NEW.client_id,
      'cadenceDays', NEW.cadence_days,
      'nextCycleAt', NEW.next_cycle_at,
      'occurredAt', now()
    ),
    jsonb_build_object('source', 'subscription_emit_created_outbox')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_emit_created_outbox(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_emit_created_outbox() IS 'Emits subscription.created on the FIRST activation only (INSERT-active or pending_activation->active), never on resume/auto-resume. Drives the subscription-welcome email. Idempotent via subscription_created:<id>.';


--
-- Name: subscription_emit_self_service_account_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_emit_self_service_account_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_client_id uuid;
  v_next_cycle_at timestamptz;
  v_account_event_type text;
  v_email_event_type text;
BEGIN
  v_account_event_type := CASE NEW.event_type
    WHEN 'subscription.customer_self_service.pause' THEN 'subscription.paused'
    WHEN 'subscription.customer_self_service.resume' THEN 'subscription.resumed'
    WHEN 'subscription.system.auto_resume' THEN 'subscription.resumed'
    WHEN 'subscription.customer_self_service.reactivate' THEN 'subscription.resumed'
    WHEN 'subscription.customer_self_service.cancel' THEN 'subscription.cancelled'
    WHEN 'subscription.customer_self_service.swap_recipe' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.update_recipe_mix' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.add_addon' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.remove_addon' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.update_addon_quantity' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.update_plan_length' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.set_portion_mode' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.update_package_template' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.update_bundle' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.resize_bundle' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.slide_next_cycle' THEN 'subscription.delivery_rescheduled'
    WHEN 'subscription.customer_self_service.order_now' THEN 'subscription.delivery_rescheduled'
    WHEN 'subscription.customer_self_service.skip_next_cycle' THEN 'subscription.cycle_skipped'
    WHEN 'subscription.customer_self_service.change_shipping_address' THEN 'subscription.address_changed'
    ELSE NULL
  END;

  v_email_event_type := CASE NEW.event_type
    WHEN 'subscription.customer_self_service.pause' THEN 'subscription.paused'
    WHEN 'subscription.customer_self_service.resume' THEN 'subscription.resumed'
    WHEN 'subscription.system.auto_resume' THEN 'subscription.resumed'
    WHEN 'subscription.customer_self_service.swap_recipe' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.update_recipe_mix' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.add_addon' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.remove_addon' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.update_addon_quantity' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.update_plan_length' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.set_portion_mode' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.update_package_template' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.update_bundle' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.resize_bundle' THEN 'subscription.package_changed'
    WHEN 'subscription.customer_self_service.slide_next_cycle' THEN 'subscription.delivery_rescheduled'
    WHEN 'subscription.customer_self_service.skip_next_cycle' THEN 'subscription.cycle_skipped'
    WHEN 'subscription.customer_self_service.change_shipping_address' THEN 'subscription.address_changed'
    ELSE NULL
  END;

  IF v_account_event_type IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT client_id, next_cycle_at
    INTO v_client_id, v_next_cycle_at
    FROM public.subscriptions WHERE id = NEW.subscription_id;
  IF v_client_id IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.customer_account_events (
    client_id, event_type, entity_type, entity_id, payload, occurred_at
  )
  VALUES (
    v_client_id,
    v_account_event_type,
    'subscription',
    NEW.subscription_id,
    jsonb_build_object('action', NEW.payload->>'action', 'sourceEventId', NEW.id),
    NEW.occurred_at
  );

  IF v_email_event_type IS NOT NULL THEN
    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    VALUES (
      'subscription',
      NEW.subscription_id,
      v_email_event_type,
      v_email_event_type || ':' || NEW.id::text,
      jsonb_build_object(
        'clientId', v_client_id,
        'subscriptionId', NEW.subscription_id,
        'action', NEW.payload->>'action',
        'nextCycleAt', v_next_cycle_at,
        'occurredAt', NEW.occurred_at
      ),
      jsonb_build_object('source', 'subscription_emit_self_service_account_event')
    )
    ON CONFLICT (event_type, idempotency_key) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_emit_self_service_account_event(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_emit_self_service_account_event() IS 'Mirrors subscription self-service / auto-resume events into customer_account_events and emits only selected subscription change-confirmation outbox events; order_now/reactivate are account-history only.';


--
-- Name: subscription_guard_active_requires_lines(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_guard_active_requires_lines() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP <> 'UPDATE'
     OR NEW.status <> 'active'
     OR OLD.status IS NOT DISTINCT FROM 'active'
  THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.subscription_lines sl
    WHERE sl.subscription_id = NEW.id
  ) THEN
    RAISE EXCEPTION 'subscription_active_requires_lines'
      USING
        ERRCODE = '22023',
        DETAIL = 'Subscription ' || NEW.id::text || ' has no subscription_lines rows; refusing transition '
          || COALESCE(OLD.status, 'null') || ' -> active.',
        HINT = 'Write the subscription template lines in the same transaction as the activation, or cancel the subscription instead of resuming it.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_guard_active_requires_lines(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_guard_active_requires_lines() IS 'Rejects any UPDATE that transitions a subscription into status=active while it has zero subscription_lines rows. UPDATE-only: the paid-checkout activation RPC inserts status=active before its own guarded line loop.';


--
-- Name: subscription_guard_payment_pending_cycle_template(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_guard_payment_pending_cycle_template() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_expected jsonb;
BEGIN
  IF NEW.status <> 'payment_pending' THEN
    RETURN NEW;
  END IF;

  v_expected := public.subscription_current_template_snapshot(NEW.subscription_id);
  IF NEW.template_snapshot IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'subscription_cycle_order_stale_template_snapshot'
      USING
        ERRCODE = '22023',
        DETAIL = 'subscription_cycles.template_snapshot must match locked subscriptions + subscription_lines',
        HINT = 'Build subscription cycle/order snapshots from the current subscription template rows.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_guard_payment_pending_cycle_template(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_guard_payment_pending_cycle_template() IS 'Rejects payment-pending subscription cycles whose template snapshot is stale or caller-tampered.';


--
-- Name: subscription_guard_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_guard_status_transition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP <> 'UPDATE' OR OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'pending_activation'
     AND NEW.status IN ('active', 'activation_failed', 'cancelled') THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'active' AND NEW.status IN ('paused', 'cancelled', 'completed') THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'paused' AND NEW.status IN ('active', 'cancelled') THEN
    RETURN NEW;
  END IF;

  -- Win-back: a cancelled subscription can be reactivated by its owner.
  IF OLD.status = 'cancelled' AND NEW.status = 'active' THEN
    RETURN NEW;
  END IF;

  -- System expired-checkout recovery: reopen only provisional activations that
  -- were cancelled by the unpaid activation sweep and have durable audit proof.
  IF OLD.status = 'cancelled'
     AND NEW.status = 'pending_activation'
     AND EXISTS (
       SELECT 1
         FROM public.subscription_events event
        WHERE event.subscription_id = NEW.id
          AND event.event_type = 'subscription.activation_abandoned'
     ) THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'subscription_invalid_status_transition'
    USING
      ERRCODE = '22023',
      DETAIL = 'Illegal subscription status transition: ' || OLD.status || ' -> ' || NEW.status,
      HINT = 'Allowed transitions: pending_activation -> active/activation_failed/cancelled; active -> paused/cancelled/completed; paused -> active/cancelled; cancelled -> active; system-abandoned provisional cancelled -> pending_activation; completed/activation_failed are terminal.';
END;
$$;


--
-- Name: FUNCTION subscription_guard_status_transition(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_guard_status_transition() IS 'Enforces the subscription lifecycle transition matrix, including system-abandoned provisional checkout recovery.';


--
-- Name: subscription_handle_payment_failure_dunning(text, uuid, uuid, uuid, uuid, integer, timestamp with time zone, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_handle_payment_failure_dunning(p_idempotency_key text, p_cycle_id uuid, p_subscription_id uuid, p_order_id uuid, p_payment_intent_id uuid, p_retry_attempt integer, p_next_retry_at timestamp with time zone, p_failure_reason text, p_occurred_at timestamp with time zone, p_failure_class text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_subscription_status text;
  v_result jsonb;
BEGIN
  SELECT s.status
    INTO v_subscription_status
    FROM public.subscriptions s
   WHERE s.id = p_subscription_id
   FOR UPDATE;

  IF FOUND AND v_subscription_status = 'cancelled' THEN
    RAISE EXCEPTION 'subscription_dunning_subscription_cancelled'
      USING ERRCODE = '55000';
  END IF;

  v_result := public.subscription_handle_payment_failure_dunning_before_cancel_fence(
    p_idempotency_key,
    p_cycle_id,
    p_subscription_id,
    p_order_id,
    p_payment_intent_id,
    p_retry_attempt,
    p_next_retry_at,
    p_failure_reason,
    p_occurred_at
  );

  -- Same contract as the attempt stamp above: after the canonical body, never
  -- instead of it, and a no-op when the caller classified nothing. One case per
  -- cycle is guaranteed by the UNIQUE (cycle_id) the canonical body upserts on.
  IF p_failure_class IS NOT NULL THEN
    UPDATE public.subscription_dunning_cases dunning_case
       SET failure_class = p_failure_class
     WHERE dunning_case.cycle_id = p_cycle_id;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: subscription_handle_payment_failure_dunning_before_cancel_fence(text, uuid, uuid, uuid, uuid, integer, timestamp with time zone, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_handle_payment_failure_dunning_before_cancel_fence(p_idempotency_key text, p_cycle_id uuid, p_subscription_id uuid, p_order_id uuid, p_payment_intent_id uuid, p_retry_attempt integer, p_next_retry_at timestamp with time zone, p_failure_reason text, p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'subscription.dunning.failure';
  -- The first rung the ladder runs with nothing scheduled after it. The ladder
  -- itself lives in commerce_payment_control_apply_before_sub_lock and is not
  -- touched here; this constant is the boundary that body's CASE already draws.
  v_ladder_exhausted_from constant integer := 4;
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_cycle public.subscription_cycles%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_client public.clients%ROWTYPE;
  v_case public.subscription_dunning_cases%ROWTYPE;
  v_case_status text;
  v_notification_kind text;
  v_customer_slug text;
  v_admin_slug text;
  v_token text;
  v_token_hash text;
  v_token_purpose text;
  v_token_expires_at timestamptz;
  v_recovery_url_path text;
  v_admin_count integer := 0;
  v_customer_inserted integer := 0;
  v_response jsonb;
  v_recipient record;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_cycle_id IS NULL
    OR p_subscription_id IS NULL
    OR p_order_id IS NULL
    OR p_payment_intent_id IS NULL
    OR p_retry_attempt IS NULL OR p_retry_attempt < 1
    OR p_occurred_at IS NULL
  THEN
    RAISE EXCEPTION 'subscription_dunning_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    p_cycle_id::text || '|' ||
    p_subscription_id::text || '|' ||
    p_order_id::text || '|' ||
    p_payment_intent_id::text || '|' ||
    p_retry_attempt::text || '|' ||
    COALESCE(p_next_retry_at::text, '') || '|' ||
    COALESCE(p_failure_reason, '') || '|' ||
    p_occurred_at::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{subscriptionDunning,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'subscription_dunning_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_dunning_subscription_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_cycle
    FROM public.subscription_cycles
   WHERE id = p_cycle_id
   FOR UPDATE;
  IF NOT FOUND OR v_cycle.subscription_id IS DISTINCT FROM p_subscription_id THEN
    RAISE EXCEPTION 'subscription_dunning_cycle_mismatch' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_order
    FROM public.commerce_orders
   WHERE id = p_order_id
   FOR UPDATE;
  IF NOT FOUND
    OR v_order.subscription_id IS DISTINCT FROM p_subscription_id
    OR v_order.subscription_cycle_id IS DISTINCT FROM p_cycle_id
  THEN
    RAISE EXCEPTION 'subscription_dunning_order_mismatch' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND
    OR v_intent.order_id IS DISTINCT FROM p_order_id
    OR v_intent.subscription_id IS DISTINCT FROM p_subscription_id
    OR v_intent.subscription_cycle_id IS DISTINCT FROM p_cycle_id
  THEN
    RAISE EXCEPTION 'subscription_dunning_payment_intent_mismatch' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_client
    FROM public.clients
   WHERE id = v_order.client_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_dunning_client_not_found' USING ERRCODE = '22023';
  END IF;

  IF p_retry_attempt IS DISTINCT FROM v_cycle.retry_attempt THEN
    RAISE EXCEPTION 'subscription_dunning_retry_attempt_stale' USING ERRCODE = '22023';
  END IF;

  -- THE DELTA THIS MIGRATION SHIPS. An absent schedule is not by itself the end
  -- of the ladder: it is the end of the ladder only at or past the rung the
  -- ladder stops scheduling from. Below that rung an absent schedule means the
  -- attempt sequence was cut short on purpose, and a case cut short is OPEN and
  -- recoverable — never expired, and so never a reason to pause.
  v_case_status := CASE
    WHEN p_next_retry_at IS NULL AND p_retry_attempt >= v_ladder_exhausted_from THEN 'expired'
    ELSE 'open'
  END;
  v_notification_kind := CASE WHEN v_case_status = 'expired' THEN 'payment_expired' ELSE 'payment_failed' END;
  v_customer_slug := CASE
    WHEN v_case_status = 'expired' THEN 'subscription-payment-expired'
    WHEN p_retry_attempt = 1 THEN 'subscription-payment-failed-1'
    WHEN p_retry_attempt = 2 THEN 'subscription-payment-failed-2'
    ELSE 'subscription-payment-failed-3'
  END;
  v_admin_slug := CASE
    WHEN v_case_status = 'expired' THEN 'subscription-payment-expired-admin'
    ELSE 'subscription-payment-failed-admin'
  END;
  v_token_purpose := CASE WHEN v_case_status = 'expired' THEN 'resume_subscription' ELSE 'repair_payment' END;
  -- The COALESCE was already here and already does the right thing for an open
  -- case with no schedule: the repair window starts from the refusal itself.
  v_token_expires_at := CASE
    WHEN v_case_status = 'expired' THEN p_occurred_at + interval '30 days'
    ELSE COALESCE(p_next_retry_at, p_occurred_at) + interval '14 days'
  END;
  -- QP-safe sentinel prefix (see 20260709130000): 'rcv_' leads with a non-hex
  -- char so the recovery deep-link's "?token=" separator + the first token char
  -- can never form a valid quoted-printable "=<2 hex>" escape. The whole prefixed
  -- token is hashed below and on the validate side, so the prefix round-trips.
  v_token := 'rcv_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  v_token_hash := encode(sha256(convert_to(v_token, 'UTF8')), 'hex');
  v_recovery_url_path := '/konto/platnosc/napraw?token=' || v_token;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'subscription_handle_payment_failure_dunning')
  );

  INSERT INTO public.subscription_dunning_cases (
    subscription_id,
    cycle_id,
    order_id,
    payment_intent_id,
    client_id,
    pet_id,
    status,
    retry_attempt,
    next_retry_at,
    failure_reason,
    opened_at,
    expired_at,
    last_event_at,
    metadata
  )
  VALUES (
    p_subscription_id,
    p_cycle_id,
    p_order_id,
    p_payment_intent_id,
    v_order.client_id,
    v_order.pet_id,
    v_case_status,
    p_retry_attempt,
    p_next_retry_at,
    COALESCE(p_failure_reason, 'payment_failed'),
    p_occurred_at,
    CASE WHEN v_case_status = 'expired' THEN p_occurred_at ELSE NULL END,
    p_occurred_at,
    jsonb_build_object('source', 'subscription.dunning.hidden.v0')
  )
  ON CONFLICT (cycle_id) DO UPDATE
    SET payment_intent_id = EXCLUDED.payment_intent_id,
        status = CASE
          WHEN public.subscription_dunning_cases.status = 'recovered' THEN public.subscription_dunning_cases.status
          ELSE EXCLUDED.status
        END,
        retry_attempt = GREATEST(public.subscription_dunning_cases.retry_attempt, EXCLUDED.retry_attempt),
        next_retry_at = EXCLUDED.next_retry_at,
        failure_reason = EXCLUDED.failure_reason,
        expired_at = CASE
          WHEN EXCLUDED.status = 'expired' THEN COALESCE(public.subscription_dunning_cases.expired_at, EXCLUDED.expired_at)
          ELSE public.subscription_dunning_cases.expired_at
        END,
        last_event_at = EXCLUDED.last_event_at,
        updated_at = now(),
        metadata = public.subscription_dunning_cases.metadata || jsonb_build_object('lastPaymentIntentId', p_payment_intent_id)
  RETURNING * INTO v_case;

  IF v_case.status = 'recovered' THEN
    RAISE EXCEPTION 'subscription_dunning_case_already_recovered' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.subscription_payment_recovery_tokens (
    case_id,
    subscription_id,
    cycle_id,
    order_id,
    client_id,
    token_hash,
    purpose,
    expires_at,
    metadata
  )
  VALUES (
    v_case.id,
    p_subscription_id,
    p_cycle_id,
    p_order_id,
    v_order.client_id,
    v_token_hash,
    v_token_purpose,
    v_token_expires_at,
    jsonb_build_object('source', 'subscription.dunning.hidden.v0')
  );

  INSERT INTO public.subscription_dunning_notifications (
    case_id,
    subscription_id,
    cycle_id,
    order_id,
    payment_intent_id,
    recipient_kind,
    recipient_ref,
    notification_kind,
    template_slug,
    retry_attempt,
    idempotency_key,
    status,
    scheduled_at,
    recovery_url_path,
    payload
  )
  VALUES (
    v_case.id,
    p_subscription_id,
    p_cycle_id,
    p_order_id,
    p_payment_intent_id,
    'customer',
    v_order.client_id,
    v_notification_kind,
    v_customer_slug,
    p_retry_attempt,
    v_case.id::text || ':customer:' || v_customer_slug || ':' || p_retry_attempt::text,
    'queued',
    now(),
    v_recovery_url_path,
    jsonb_build_object(
      'clientId', v_order.client_id,
      'clientEmail', v_client.email,
      'clientPhonePresent', v_client.phone IS NOT NULL,
      'orderId', p_order_id,
      'subscriptionId', p_subscription_id,
      'cycleId', p_cycle_id,
      'paymentIntentId', p_payment_intent_id,
      'amountMinor', v_order.total_cents,
      'currency', v_order.currency,
      'retryAttempt', p_retry_attempt,
      'nextRetryAt', p_next_retry_at,
      'failureReason', COALESCE(p_failure_reason, 'payment_failed'),
      'source', 'subscription.dunning.hidden.v0'
    )
  )
  ON CONFLICT (idempotency_key) DO NOTHING;
  GET DIAGNOSTICS v_customer_inserted = ROW_COUNT;

  FOR v_recipient IN
    SELECT id
    FROM public.notification_recipients
    WHERE notification_type = 'commerce_payment_critical'
      AND active = true
    ORDER BY created_at, id
  LOOP
    INSERT INTO public.subscription_dunning_notifications (
      case_id,
      subscription_id,
      cycle_id,
      order_id,
      payment_intent_id,
      recipient_kind,
      recipient_ref,
      notification_kind,
      template_slug,
      retry_attempt,
      idempotency_key,
      status,
      scheduled_at,
      recovery_url_path,
      payload
    )
    VALUES (
      v_case.id,
      p_subscription_id,
      p_cycle_id,
      p_order_id,
      p_payment_intent_id,
      'admin',
      v_recipient.id,
      v_notification_kind,
      v_admin_slug,
      p_retry_attempt,
      v_case.id::text || ':admin:' || v_admin_slug || ':' || p_retry_attempt::text || ':' || v_recipient.id::text,
      'queued',
      now(),
      v_recovery_url_path,
      jsonb_build_object(
        'clientId', v_order.client_id,
        'clientEmail', v_client.email,
        'clientPhonePresent', v_client.phone IS NOT NULL,
        'orderId', p_order_id,
        'subscriptionId', p_subscription_id,
        'cycleId', p_cycle_id,
        'paymentIntentId', p_payment_intent_id,
        'amountMinor', v_order.total_cents,
        'currency', v_order.currency,
        'retryAttempt', p_retry_attempt,
        'nextRetryAt', p_next_retry_at,
        'state', v_case_status,
        'recommendedAction', CASE
          WHEN v_case_status = 'expired' THEN 'Call the customer and invite them to resume after updating payment.'
          ELSE 'Call the customer before the next retry if this account is high value.'
        END,
        'source', 'subscription.dunning.hidden.v0'
      )
    )
    ON CONFLICT (idempotency_key) DO NOTHING;
    v_admin_count := v_admin_count + 1;
  END LOOP;

  IF v_admin_count = 0 THEN
    INSERT INTO public.subscription_dunning_notifications (
      case_id,
      subscription_id,
      cycle_id,
      order_id,
      payment_intent_id,
      recipient_kind,
      recipient_ref,
      notification_kind,
      template_slug,
      retry_attempt,
      idempotency_key,
      status,
      scheduled_at,
      provider_error,
      payload
    )
    VALUES (
      v_case.id,
      p_subscription_id,
      p_cycle_id,
      p_order_id,
      p_payment_intent_id,
      'admin',
      NULL,
      v_notification_kind,
      v_admin_slug,
      p_retry_attempt,
      v_case.id::text || ':admin:' || v_admin_slug || ':' || p_retry_attempt::text || ':missing-recipient',
      'skipped',
      now(),
      'missing_commerce_payment_critical_recipient',
      jsonb_build_object(
        'reason', 'missing_commerce_payment_critical_recipient',
        'subscriptionId', p_subscription_id,
        'cycleId', p_cycle_id,
        'orderId', p_order_id,
        'source', 'subscription.dunning.hidden.v0'
      )
    )
    ON CONFLICT (idempotency_key) DO NOTHING;
  END IF;

  -- Reached only by the exhaustion arm above. An early-terminated case is 'open',
  -- so this branch cannot fire for it and the subscription is left alone.
  IF v_case_status = 'expired' AND v_subscription.status = 'active' THEN
    UPDATE public.subscriptions
       SET status = 'paused',
           updated_at = now()
     WHERE id = p_subscription_id;

    INSERT INTO public.subscription_events (
      subscription_id,
      cycle_id,
      event_type,
      idempotency_key,
      payload,
      occurred_at
    )
    VALUES (
      p_subscription_id,
      p_cycle_id,
      'subscription.paused',
      p_idempotency_key || ':subscription_paused',
      jsonb_build_object(
        'reason', 'payment_failed_expired',
        'caseId', v_case.id,
        'paymentIntentId', p_payment_intent_id,
        'source', 'subscription.dunning.hidden.v0'
      ),
      p_occurred_at
    )
    ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
  END IF;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'subscriptionDunning', jsonb_build_object(
      'caseId', v_case.id,
      'subscriptionId', p_subscription_id,
      'cycleId', p_cycle_id,
      'orderId', p_order_id,
      'paymentIntentId', p_payment_intent_id,
      'status', v_case_status,
      'retryAttempt', p_retry_attempt,
      'nextRetryAt', p_next_retry_at,
      'customerNotificationQueued', v_customer_inserted = 1,
      'adminNotificationCount', v_admin_count,
      'recoveryTokenPurpose', v_token_purpose,
      'recoveryUrlPath', v_recovery_url_path,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object(
           'caseId', v_case.id,
           'subscriptionId', p_subscription_id,
           'cycleId', p_cycle_id,
           'orderId', p_order_id
         )
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: subscription_list_due_for_renewal(integer, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_list_due_for_renewal(p_limit integer DEFAULT 50, p_as_of timestamp with time zone DEFAULT now()) RETURNS TABLE(subscription_id uuid, client_id uuid, next_cycle_at timestamp with time zone, cadence_days integer, template_version integer, currency text, region_code text, provider_kind text, provider_customer_ref text, provider_method_ref text, method_kind text, status text, payer_email text, payer_name text, method_status text, method_active boolean, method_expires_at timestamp with time zone, method_client_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 500 THEN
    RAISE EXCEPTION 'subscription_list_due_for_renewal: p_limit must be between 1 and 500'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
    WITH retry_due AS (
      SELECT
        s.id          AS subscription_id,
        s.client_id   AS client_id,
        c.scheduled_at AS next_cycle_at,
        s.cadence_days,
        s.template_version,
        s.currency,
        s.region_code,
        m.provider_kind,
        CASE
          WHEN m.client_id = s.client_id AND m.active = true AND m.status = 'active'
          THEN m.provider_customer_ref
          ELSE NULL
        END AS provider_customer_ref,
        CASE
          WHEN m.client_id = s.client_id AND m.active = true AND m.status = 'active'
          THEN m.provider_method_ref
          ELSE NULL
        END AS provider_method_ref,
        COALESCE(m.method_kind, s.payment_method_kind, '') AS method_kind,
        m.status,
        cl.email AS payer_email,
        NULLIF(btrim(concat_ws(' ', cl.first_name, cl.last_name)), '') AS payer_name,
        m.status AS method_status,
        m.active AS method_active,
        m.expires_at AS method_expires_at,
        m.client_id AS method_client_id
      FROM public.subscriptions s
      JOIN public.clients cl
        ON cl.id = s.client_id
      LEFT JOIN LATERAL (
        SELECT pm.*
          FROM public.commerce_payment_method_refs pm
         WHERE pm.subscription_id = s.id
         ORDER BY
           (pm.active = true AND pm.status = 'active') DESC,
           pm.active DESC,
           pm.updated_at DESC,
           pm.created_at DESC
         LIMIT 1
      ) m ON true
      JOIN public.subscription_cycles c
        ON c.subscription_id = s.id
       AND c.status = 'retry_scheduled'
       AND c.next_retry_at IS NOT NULL
       AND c.next_retry_at <= p_as_of
       -- Quarantine skip (retry lane). A bare timestamp comparison, never a
       -- status: an elapsed value re-admits the row on the very next pass with
       -- no unquarantine write required, so a lost clear cannot strand anyone.
       AND (c.renewal_quarantined_until IS NULL OR c.renewal_quarantined_until <= p_as_of)
      WHERE s.status = 'active'
      ORDER BY c.next_retry_at ASC, s.id ASC
      LIMIT p_limit
      FOR UPDATE OF s SKIP LOCKED
    ),
    normal_due AS (
      SELECT
        s.id          AS subscription_id,
        s.client_id   AS client_id,
        s.next_cycle_at,
        s.cadence_days,
        s.template_version,
        s.currency,
        s.region_code,
        m.provider_kind,
        CASE
          WHEN m.client_id = s.client_id AND m.active = true AND m.status = 'active'
          THEN m.provider_customer_ref
          ELSE NULL
        END,
        CASE
          WHEN m.client_id = s.client_id AND m.active = true AND m.status = 'active'
          THEN m.provider_method_ref
          ELSE NULL
        END AS provider_method_ref,
        COALESCE(m.method_kind, s.payment_method_kind, '') AS method_kind,
        m.status,
        cl.email AS payer_email,
        NULLIF(btrim(concat_ws(' ', cl.first_name, cl.last_name)), '') AS payer_name,
        m.status AS method_status,
        m.active AS method_active,
        m.expires_at AS method_expires_at,
        m.client_id AS method_client_id
      FROM public.subscriptions s
      JOIN public.clients cl
        ON cl.id = s.client_id
      LEFT JOIN LATERAL (
        SELECT pm.*
          FROM public.commerce_payment_method_refs pm
         WHERE pm.subscription_id = s.id
         ORDER BY
           (pm.active = true AND pm.status = 'active') DESC,
           pm.active DESC,
           pm.updated_at DESC,
           pm.created_at DESC
         LIMIT 1
      ) m ON true
      WHERE s.status = 'active'
        AND s.next_cycle_at IS NOT NULL
        AND s.next_cycle_at <= p_as_of
        AND NOT EXISTS (
          SELECT 1
            FROM public.subscription_cycles c
           WHERE c.subscription_id = s.id
             AND c.status IN ('payment_pending', 'retry_scheduled', 'payment_failed')
        )
        -- Quarantine skip (normal lane). The open-cycle guard above already
        -- hides the common case, so this covers the row whose cycle left those
        -- statuses while still quarantined; without it the same failing row
        -- would come straight back through the other lane.
        AND NOT EXISTS (
          SELECT 1
            FROM public.subscription_cycles c
           WHERE c.subscription_id = s.id
             AND c.renewal_quarantined_until > p_as_of
        )
      ORDER BY s.next_cycle_at ASC, s.id ASC
      LIMIT p_limit
      FOR UPDATE OF s SKIP LOCKED
    )
    SELECT *
      FROM (
        SELECT * FROM retry_due
        UNION ALL
        SELECT * FROM normal_due
      ) due
     ORDER BY due.next_cycle_at ASC, due.subscription_id ASC
     LIMIT p_limit;
END;
$$;


--
-- Name: FUNCTION subscription_list_due_for_renewal(p_limit integer, p_as_of timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_list_due_for_renewal(p_limit integer, p_as_of timestamp with time zone) IS 'Service-role-only. Lists due active subscriptions and due retry_scheduled cycles with payment-method lifecycle evidence, including missing/revoked/expired/pending refs. Terminal payment_failed cycles stay blocked from automatic renewal until customer/OMS recovery closes or replaces them. Cycles inside a live renewal quarantine window are skipped in both lanes until that window elapses. p_limit and p_as_of default to 50 and now() so existing production callers keep their one-argument shape.';


--
-- Name: subscription_list_due_for_winback(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_list_due_for_winback(p_limit integer DEFAULT 50) RETURNS TABLE(subscription_id uuid, client_id uuid, ended_at timestamp with time zone, pet_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 500 THEN
    RAISE EXCEPTION 'subscription_list_due_for_winback: p_limit must be between 1 and 500'
      USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
    SELECT
      s.id        AS subscription_id,
      s.client_id AS client_id,
      s.ended_at,
      s.pet_id
    FROM public.subscriptions s
    WHERE s.status = 'cancelled'
      AND s.cancellation_source = 'customer_self_service'
      AND s.ended_at IS NOT NULL
      AND s.ended_at > now() - interval '120 days'
      AND s.ended_at <= now() - interval '14 days'
      AND NOT EXISTS (
        SELECT 1
        FROM public.subscription_events e
        WHERE e.subscription_id = s.id
          AND e.event_type = 'subscription.winback.email_sent'
          AND e.created_at >= s.ended_at
      )
    ORDER BY s.ended_at ASC, s.id ASC
    LIMIT p_limit
    FOR UPDATE OF s SKIP LOCKED;
END;
$$;


--
-- Name: FUNCTION subscription_list_due_for_winback(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_list_due_for_winback(p_limit integer) IS 'Service-role-only. Lists subscriptions cancelled by the customer between 14 and 120 days ago and not yet nudged for the current cancellation episode.';


--
-- Name: subscription_mark_dunning_recovered(text, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_mark_dunning_recovered(p_idempotency_key text, p_case_id uuid, p_payment_intent_id uuid, p_recovered_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'subscription.dunning.recovered';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_case public.subscription_dunning_cases%ROWTYPE;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_case_id IS NULL
    OR p_payment_intent_id IS NULL
    OR p_recovered_at IS NULL
  THEN
    RAISE EXCEPTION 'subscription_dunning_recovered_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(p_case_id::text || '|' || p_payment_intent_id::text || '|' || p_recovered_at::text);

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{subscriptionDunningRecovery,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'subscription_dunning_recovered_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_case
    FROM public.subscription_dunning_cases
   WHERE id = p_case_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_dunning_recovered_case_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND
    OR v_intent.subscription_id IS DISTINCT FROM v_case.subscription_id
    OR v_intent.subscription_cycle_id IS DISTINCT FROM v_case.cycle_id
  THEN
    RAISE EXCEPTION 'subscription_dunning_recovered_payment_mismatch' USING ERRCODE = '22023';
  END IF;

  IF v_intent.status <> 'succeeded' THEN
    RAISE EXCEPTION 'subscription_dunning_recovered_payment_not_succeeded' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'subscription_mark_dunning_recovered')
  );

  UPDATE public.subscription_dunning_cases
     SET status = 'recovered',
         recovered_at = p_recovered_at,
         last_event_at = p_recovered_at,
         updated_at = now(),
         metadata = metadata || jsonb_build_object('recoveredPaymentIntentId', p_payment_intent_id)
   WHERE id = p_case_id
   RETURNING * INTO v_case;

  UPDATE public.subscription_payment_recovery_tokens
     SET revoked_at = COALESCE(revoked_at, p_recovered_at),
         updated_at = now()
   WHERE case_id = p_case_id
     AND used_at IS NULL
     AND revoked_at IS NULL;

  INSERT INTO public.subscription_events (
    subscription_id,
    cycle_id,
    event_type,
    idempotency_key,
    payload,
    occurred_at
  )
  VALUES (
    v_case.subscription_id,
    v_case.cycle_id,
    'subscription.payment_recovered',
    p_idempotency_key || ':subscription_payment_recovered',
    jsonb_build_object(
      'caseId', p_case_id,
      'paymentIntentId', p_payment_intent_id,
      'source', 'subscription.dunning.hidden.v0'
    ),
    p_recovered_at
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'subscriptionDunningRecovery', jsonb_build_object(
      'caseId', v_case.id,
      'subscriptionId', v_case.subscription_id,
      'cycleId', v_case.cycle_id,
      'status', v_case.status,
      'recoveredAt', v_case.recovered_at,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('caseId', p_case_id, 'paymentIntentId', p_payment_intent_id)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: subscription_mark_self_service_cancellation_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_mark_self_service_cancellation_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.event_type = 'subscription.customer_self_service.cancel' THEN
    UPDATE public.subscriptions
       SET cancellation_source = 'customer_self_service'
     WHERE id = NEW.subscription_id
       AND status = 'cancelled';

    UPDATE public.outbox_events oe
       SET payload = jsonb_set(
             jsonb_set(payload, '{cancellationSource}', to_jsonb('customer'::text), true),
             '{cancellationReason}',
             to_jsonb(COALESCE(NULLIF(btrim(s.cancellation_reason), ''), 'customer_cancelled')),
             true
           ),
           metadata = COALESCE(metadata, '{}'::jsonb)
             || jsonb_build_object('cancellationSourceMarker', 'subscription.customer_self_service.cancel')
      FROM public.subscriptions s
     WHERE oe.event_type = 'subscription.cancelled'
       AND oe.aggregate_id = NEW.subscription_id
       AND oe.idempotency_key = 'subscription_cancelled:' || NEW.subscription_id::text
       AND s.id = NEW.subscription_id;
  ELSIF NEW.event_type = 'subscription.customer_self_service.reactivate' THEN
    UPDATE public.subscriptions
       SET cancellation_source = NULL
     WHERE id = NEW.subscription_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: subscription_method_chargeable_unattended(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_method_chargeable_unattended(p_subscription_id uuid, p_as_of timestamp with time zone DEFAULT now()) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM public.commerce_payment_method_refs method_ref
      JOIN public.subscriptions subscription
        ON subscription.id = method_ref.subscription_id
       AND subscription.client_id = method_ref.client_id
     WHERE method_ref.subscription_id = p_subscription_id
       AND method_ref.status = 'active'
       AND method_ref.active = true
       AND (
         method_ref.consent_snapshot ->> 'recurringModel' = 'O'
         OR (
           method_ref.consent_snapshot ->> 'recurringModel' IS NULL
           AND method_ref.method_kind = 'card'
         )
       )
       AND (method_ref.expires_at IS NULL OR method_ref.expires_at > p_as_of)
  );
$$;


--
-- Name: FUNCTION subscription_method_chargeable_unattended(p_subscription_id uuid, p_as_of timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_method_chargeable_unattended(p_subscription_id uuid, p_as_of timestamp with time zone) IS 'True when the subscription has an active stored method whose mandate permits an unattended charge and whose expiry has not passed. An absent autopayment model is permission only on a card credential, never on a stored mandate. Agrees with subscription_method_health on every mandate verdict.';


--
-- Name: subscription_open_dunning_before_sub_lock(text, uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_open_dunning_before_sub_lock(p_idempotency_key text, p_payment_intent_id uuid, p_provider_event_id text DEFAULT NULL::text, p_failure_reason text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT now(), p_failure_class text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_cycle public.subscription_cycles%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR p_payment_intent_id IS NULL THEN
    RAISE EXCEPTION 'subscription_webhook_dunning_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_intent
    FROM public.commerce_payment_intents
   WHERE id = p_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_webhook_dunning_intent_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_intent.subscription_id IS NULL OR v_intent.subscription_cycle_id IS NULL THEN
    RETURN jsonb_build_object('subscriptionWebhookDunning', jsonb_build_object('opened', false, 'replayed', false, 'reason', 'not_subscription_cycle'));
  END IF;

  SELECT * INTO v_order FROM public.commerce_orders WHERE id = v_intent.order_id FOR UPDATE;
  IF NOT FOUND OR v_order.subscription_id IS DISTINCT FROM v_intent.subscription_id THEN
    RAISE EXCEPTION 'subscription_webhook_dunning_order_mismatch' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_cycle FROM public.subscription_cycles WHERE id = v_intent.subscription_cycle_id FOR UPDATE;
  IF NOT FOUND OR v_cycle.subscription_id IS DISTINCT FROM v_intent.subscription_id THEN
    RAISE EXCEPTION 'subscription_webhook_dunning_cycle_mismatch' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_subscription FROM public.subscriptions WHERE id = v_intent.subscription_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_webhook_dunning_subscription_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_subscription.status NOT IN ('active', 'paused')
    OR v_cycle.status NOT IN ('retry_scheduled', 'payment_failed')
    OR COALESCE(v_cycle.retry_attempt, 0) < 1
  THEN
    RETURN jsonb_build_object('subscriptionWebhookDunning', jsonb_build_object('opened', false, 'replayed', false, 'reason', 'not_dunning_eligible'));
  END IF;

  -- The tenth argument is the only change to this call. The canonical dunning
  -- function has owned the case stamp since 20260806120000 and treats a NULL
  -- class as "stamp nothing", so an unclassified caller reaches the identical
  -- write it reached before this migration existed.
  v_response := public.subscription_handle_payment_failure_dunning(
    p_idempotency_key,
    v_cycle.id,
    v_subscription.id,
    v_order.id,
    v_intent.id,
    v_cycle.retry_attempt,
    CASE WHEN v_cycle.status = 'payment_failed' THEN NULL ELSE v_cycle.next_retry_at END,
    COALESCE(p_failure_reason, v_intent.failure_reason, 'provider_webhook_failed'),
    COALESCE(p_occurred_at, now()),
    p_failure_class
  );

  RETURN jsonb_build_object(
    'subscriptionWebhookDunning',
    jsonb_build_object(
      'opened', true,
      'replayed', COALESCE((v_response #>> '{subscriptionDunning,replayed}')::boolean, false),
      'caseId', v_response #>> '{subscriptionDunning,caseId}',
      'subscriptionId', v_subscription.id,
      'cycleId', v_cycle.id,
      'orderId', v_order.id,
      'paymentIntentId', v_intent.id,
      'retryAttempt', v_cycle.retry_attempt,
      'nextRetryAt', v_cycle.next_retry_at
    )
  );
END;
$$;


--
-- Name: subscription_open_dunning_from_failed_payment_result(text, uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_open_dunning_from_failed_payment_result(p_idempotency_key text, p_payment_intent_id uuid, p_provider_event_id text DEFAULT NULL::text, p_failure_reason text DEFAULT NULL::text, p_occurred_at timestamp with time zone DEFAULT now(), p_failure_class text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_intent_hint record;
  v_intent public.commerce_payment_intents%ROWTYPE;
  v_order public.commerce_orders%ROWTYPE;
  v_cycle public.subscription_cycles%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR p_payment_intent_id IS NULL THEN
    RETURN public.subscription_open_dunning_before_sub_lock(
      p_idempotency_key, p_payment_intent_id, p_provider_event_id,
      p_failure_reason, p_occurred_at, p_failure_class
    );
  END IF;

  SELECT payment_intent.subscription_id
    INTO v_intent_hint
    FROM public.commerce_payment_intents payment_intent
   WHERE payment_intent.id = p_payment_intent_id;

  IF NOT FOUND OR v_intent_hint.subscription_id IS NULL THEN
    RETURN public.subscription_open_dunning_before_sub_lock(
      p_idempotency_key, p_payment_intent_id, p_provider_event_id,
      p_failure_reason, p_occurred_at, p_failure_class
    );
  END IF;

  SELECT *
    INTO v_subscription
    FROM public.subscriptions subscription
   WHERE subscription.id = v_intent_hint.subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_webhook_dunning_subscription_not_found'
      USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_intent
    FROM public.commerce_payment_intents payment_intent
   WHERE payment_intent.id = p_payment_intent_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_webhook_dunning_intent_not_found'
      USING ERRCODE = '22023';
  END IF;
  IF v_intent.subscription_id IS DISTINCT FROM v_subscription.id THEN
    RAISE EXCEPTION 'subscription_webhook_dunning_subscription_mismatch'
      USING ERRCODE = '22023';
  END IF;
  IF v_intent.subscription_cycle_id IS NULL THEN
    RETURN jsonb_build_object(
      'subscriptionWebhookDunning',
      jsonb_build_object('opened', false, 'replayed', false, 'reason', 'not_subscription_cycle')
    );
  END IF;

  SELECT *
    INTO v_order
    FROM public.commerce_orders order_row
   WHERE order_row.id = v_intent.order_id
   FOR UPDATE;
  IF NOT FOUND OR v_order.subscription_id IS DISTINCT FROM v_intent.subscription_id THEN
    RAISE EXCEPTION 'subscription_webhook_dunning_order_mismatch'
      USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_cycle
    FROM public.subscription_cycles cycle
   WHERE cycle.id = v_intent.subscription_cycle_id
   FOR UPDATE;
  IF NOT FOUND OR v_cycle.subscription_id IS DISTINCT FROM v_intent.subscription_id THEN
    RAISE EXCEPTION 'subscription_webhook_dunning_cycle_mismatch'
      USING ERRCODE = '22023';
  END IF;

  RETURN public.subscription_open_dunning_before_sub_lock(
    p_idempotency_key, p_payment_intent_id, p_provider_event_id,
    p_failure_reason, p_occurred_at, p_failure_class
  );
END;
$$;


--
-- Name: subscription_prevent_offer_policy_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_prevent_offer_policy_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF (NEW.offer_policy_version, NEW.promotion_engine_version, NEW.offer_policy_assignment_state) IS DISTINCT FROM
     (OLD.offer_policy_version, OLD.promotion_engine_version, OLD.offer_policy_assignment_state) THEN
    -- The only legal mutation is the nested assignment performed by the
    -- commerce-order trigger. Inherited and legacy states are written on INSERT.
    IF pg_trigger_depth() > 1
       AND OLD.offer_policy_assignment_state = 'pending_acquisition'
       AND NEW.offer_policy_assignment_state = 'assigned_acquisition' THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'subscription_offer_policy_immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: subscription_prevent_starter_pack_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_prevent_starter_pack_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  -- Clearing the marker is the one admitted transition: it is how a mis-sold
  -- acquisition is taken out of the starter programme by hand, and it can only
  -- ever make the subscription MORE ordinary. Everything else -- minting a
  -- marker on an existing subscription, or rewriting one -- is rejected,
  -- because both would let a one-shot acquisition offer be replayed.
  IF NEW.starter_pack IS DISTINCT FROM OLD.starter_pack
     AND NEW.starter_pack IS NOT NULL
  THEN
    RAISE EXCEPTION 'subscription_starter_pack_immutable'
      USING
        ERRCODE = '22023',
        DETAIL = 'Subscription ' || NEW.id::text || ' already carries its acquisition-time starter_pack marker.',
        HINT = 'The marker is written once by subscription_create_provisional_for_checkout. Clear it to NULL to remove the subscription from the starter programme.';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION subscription_prevent_starter_pack_update(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_prevent_starter_pack_update() IS 'Rejects any UPDATE that mints or rewrites subscriptions.starter_pack. Only a transition to NULL is admitted.';


--
-- Name: subscription_prevent_test_fixture_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_prevent_test_fixture_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.is_test_fixture IS DISTINCT FROM OLD.is_test_fixture THEN
    RAISE EXCEPTION 'subscription_offer_policy_immutable' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: subscription_price_policy_revisions_guard_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_price_policy_revisions_guard_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'subscription_price_policy_revision_immutable'
      USING ERRCODE = '55000';
  END IF;

  IF OLD.effective_to IS NOT NULL
    OR NEW.effective_to IS NULL
    OR NEW.effective_to <= OLD.effective_from
    OR NEW.id IS DISTINCT FROM OLD.id
    OR NEW.price_list_id IS DISTINCT FROM OLD.price_list_id
    OR NEW.region_code IS DISTINCT FROM OLD.region_code
    OR NEW.currency IS DISTINCT FROM OLD.currency
    OR NEW.channel IS DISTINCT FROM OLD.channel
    OR NEW.revision_no IS DISTINCT FROM OLD.revision_no
    OR NEW.discount_bps IS DISTINCT FROM OLD.discount_bps
    OR NEW.rounding_quantum_minor IS DISTINCT FROM OLD.rounding_quantum_minor
    OR NEW.rounding_rule IS DISTINCT FROM OLD.rounding_rule
    OR NEW.digest IS DISTINCT FROM OLD.digest
    OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
  THEN
    RAISE EXCEPTION 'subscription_price_policy_revision_close_only'
      USING ERRCODE = '55000';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: subscription_price_policy_revisions_prevent_overlap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_price_policy_revisions_prevent_overlap() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_context_key text;
BEGIN
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'subscription_price_policy_revision_overlap_requires_read_committed'
      USING ERRCODE = '0A000';
  END IF;

  v_context_key := concat_ws(
    '|',
    NEW.price_list_id::text,
    NEW.region_code,
    NEW.currency,
    NEW.channel
  );

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_context_key, 0)
  );

  IF EXISTS (
    SELECT 1
      FROM public.subscription_price_policy_revisions AS existing
     WHERE existing.id <> NEW.id
       AND existing.price_list_id = NEW.price_list_id
       AND existing.region_code = NEW.region_code
       AND existing.currency = NEW.currency
       AND existing.channel = NEW.channel
       AND tstzrange(existing.effective_from, existing.effective_to, '[)')
           && tstzrange(NEW.effective_from, NEW.effective_to, '[)')
  ) THEN
    RAISE EXCEPTION 'subscription_price_policy_revision_overlaps'
      USING ERRCODE = '23P01';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: subscription_reconcile_paid_activation_gaps(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_reconcile_paid_activation_gaps(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_limit constant integer := greatest(1, least(coalesce(p_limit, 200), 1000));
  v_enqueued integer := 0;
  v_overdue integer := 0;
BEGIN
  WITH candidates AS (
    SELECT g.*
    FROM public.subscription_paid_activation_gaps g
    WHERE g.paid_at <= now() - interval '30 minutes'
      AND NOT EXISTS (
        SELECT 1
        FROM public.outbox_events e
        WHERE e.event_type = 'subscription.activation_action_required'
          AND e.idempotency_key = 'subscription_activation_action_required:' || g.subscription_id::text
      )
    ORDER BY g.paid_at ASC
    LIMIT v_limit
  ), enqueued AS (
    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
    )
    SELECT
      'subscription',
      c.subscription_id,
      'subscription.activation_action_required',
      'subscription_activation_action_required:' || c.subscription_id::text,
      jsonb_build_object(
        'clientId', c.client_id,
        'subscriptionId', c.subscription_id,
        'orderId', c.order_id,
        'paymentIntentId', c.payment_intent_id,
        'paidAt', c.paid_at
      ),
      jsonb_build_object('source', 'payment-provider-reconciliation')
    FROM candidates c
    ON CONFLICT (event_type, idempotency_key) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_enqueued FROM enqueued;

  SELECT count(*) INTO v_overdue
  FROM public.subscription_paid_activation_gaps
  WHERE paid_at <= now() - interval '4 hours';

  RETURN jsonb_build_object(
    'paidActivationGapReconciliation', jsonb_build_object(
      'enqueued', v_enqueued,
      'overdue', v_overdue
    )
  );
END;
$$;


--
-- Name: subscription_record_missing_payment_method(text, uuid, integer, timestamp with time zone, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_record_missing_payment_method(p_idempotency_key text, p_subscription_id uuid, p_cycle_number integer, p_scheduled_at timestamp with time zone, p_template_snapshot jsonb, p_pricing_snapshot jsonb, p_failed_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'subscription.payment_method.missing';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_subscription public.subscriptions%ROWTYPE;
  v_cycle_id uuid;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL
    OR btrim(p_idempotency_key) = ''
    OR length(p_idempotency_key) < 8
    OR p_subscription_id IS NULL
    OR p_cycle_number IS NULL
    OR p_cycle_number < 1
    OR p_scheduled_at IS NULL
    OR p_failed_at IS NULL
  THEN
    RAISE EXCEPTION 'subscription_missing_payment_method_invalid_input'
      USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    p_subscription_id::text || '|' ||
    p_cycle_number::text || '|' ||
    p_scheduled_at::text || '|' ||
    p_template_snapshot::text || '|' ||
    p_pricing_snapshot::text || '|' ||
    p_failed_at::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{missingPaymentMethod,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'subscription_missing_payment_method_idempotency_conflict'
      USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_missing_payment_method_subscription_not_found'
      USING ERRCODE = '22023';
  END IF;

  IF v_subscription.payment_method_ref IS NOT NULL AND btrim(v_subscription.payment_method_ref) <> '' THEN
    RAISE EXCEPTION 'subscription_missing_payment_method_has_payment_method'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'subscription_record_missing_payment_method')
  );

  INSERT INTO public.subscription_cycles (
    subscription_id,
    cycle_number,
    scheduled_at,
    status,
    template_version,
    template_snapshot,
    pricing_snapshot,
    payment_method_ref,
    retry_attempt,
    next_retry_at,
    failure_reason,
    engine_idempotency_key
  )
  VALUES (
    p_subscription_id,
    p_cycle_number,
    p_scheduled_at,
    'payment_failed',
    v_subscription.template_version,
    COALESCE(p_template_snapshot, '{}'::jsonb),
    COALESCE(p_pricing_snapshot, '{}'::jsonb),
    NULL,
    0,
    NULL,
    'missing_payment_method',
    p_idempotency_key
  )
  RETURNING id INTO v_cycle_id;

  INSERT INTO public.subscription_events (
    subscription_id,
    cycle_id,
    event_type,
    idempotency_key,
    payload,
    occurred_at
  )
  VALUES (
    p_subscription_id,
    v_cycle_id,
    'subscription.payment_failed',
    p_idempotency_key || ':subscription_event',
    jsonb_build_object(
      'failureReason', 'missing_payment_method',
      'source', 'subscription.own_engine.v0'
    ),
    p_failed_at
  );

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'missingPaymentMethod', jsonb_build_object(
      'status', 'payment_failed',
      'subscriptionId', p_subscription_id,
      'cycleId', v_cycle_id,
      'cycleNumber', p_cycle_number,
      'failureReason', 'missing_payment_method',
      'idempotencyKey', p_idempotency_key,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object(
           'subscriptionId', p_subscription_id,
           'cycleId', v_cycle_id
         )
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: subscription_record_payment_recovery_before_expired_resume(text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_record_payment_recovery_before_expired_resume(p_idempotency_key text, p_recovery_token text, p_payment_method_ref text, p_payment_method_kind text, p_requested_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'subscription.payment_recovery.request';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_token_hint record;
  v_token public.subscription_payment_recovery_tokens%ROWTYPE;
  v_case public.subscription_dunning_cases%ROWTYPE;
  v_subscription_status text;
  v_next_action text;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_recovery_token IS NULL OR btrim(p_recovery_token) = ''
    OR p_payment_method_ref IS NULL OR btrim(p_payment_method_ref) = ''
    OR p_payment_method_kind IS NULL OR btrim(p_payment_method_kind) = ''
    OR p_requested_at IS NULL
  THEN
    RAISE EXCEPTION 'subscription_payment_recovery_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    md5(p_recovery_token) || '|' || p_payment_method_ref || '|' ||
    p_payment_method_kind || '|' || p_requested_at::text
  );

  -- Exact replay is read-only and cannot schedule or mutate a cancelled journey.
  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;
  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{subscriptionPaymentRecovery,replayed}', 'true'::jsonb, false);
    END IF;
    RAISE EXCEPTION 'subscription_payment_recovery_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT token.id, token.subscription_id
    INTO v_token_hint
    FROM public.subscription_payment_recovery_tokens token
   WHERE token.token_hash = encode(sha256(convert_to(p_recovery_token, 'UTF8')), 'hex');
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_payment_recovery_token_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT subscription.status
    INTO v_subscription_status
    FROM public.subscriptions subscription
   WHERE subscription.id = v_token_hint.subscription_id
   FOR UPDATE;

  SELECT *
    INTO v_token
    FROM public.subscription_payment_recovery_tokens token
   WHERE token.id = v_token_hint.id
   FOR UPDATE;
  IF NOT FOUND
    OR v_token.used_at IS NOT NULL
    OR v_token.revoked_at IS NOT NULL
    OR v_token.expires_at <= p_requested_at
  THEN
    RAISE EXCEPTION 'subscription_payment_recovery_token_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_case
    FROM public.subscription_dunning_cases dunning_case
   WHERE dunning_case.id = v_token.case_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_payment_recovery_case_not_found' USING ERRCODE = '22023';
  END IF;

  IF v_case.subscription_id IS DISTINCT FROM v_token.subscription_id
    OR v_subscription_status = 'cancelled'
    OR (v_token.purpose = 'repair_payment' AND v_case.status <> 'open')
    OR (v_token.purpose = 'resume_subscription' AND v_case.status <> 'expired')
  THEN
    RAISE EXCEPTION 'subscription_payment_recovery_case_state_mismatch' USING ERRCODE = '22023';
  END IF;

  -- Expired-dunning resume requires fresh pricing, ATP, template and order
  -- snapshots through subscription_resume_from_dunning_with_cycle_order. This
  -- generic payment-method redeem boundary has none of them and its historical
  -- resume_requested outbox command has no runtime handler. Fail closed instead
  -- of consuming the token and emitting a false subscription.resumed event.
  IF v_token.purpose = 'resume_subscription' THEN
    RAISE EXCEPTION 'subscription_payment_recovery_resume_not_available'
      USING ERRCODE = '55000';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope, idempotency_key, request_fingerprint, status, metadata
  )
  VALUES (
    v_scope, p_idempotency_key, v_request_fingerprint, 'in_progress',
    jsonb_build_object('boundary', 'subscription_record_payment_recovery_request')
  );

  UPDATE public.subscriptions
     SET payment_method_ref = p_payment_method_ref,
         payment_method_kind = p_payment_method_kind,
         updated_at = now()
   WHERE id = v_case.subscription_id;

  UPDATE public.subscription_payment_recovery_tokens
     SET used_at = p_requested_at,
         updated_at = now()
   WHERE id = v_token.id;

  v_next_action := 'retry_existing_cycle';

  INSERT INTO public.outbox_events (
    aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
  )
  VALUES (
    'subscription', v_case.subscription_id, 'commerce.subscription_payment.retry_requested', p_idempotency_key,
    jsonb_build_object(
      'caseId', v_case.id,
      'subscriptionId', v_case.subscription_id,
      'cycleId', v_case.cycle_id,
      'orderId', v_case.order_id,
      'paymentIntentId', v_case.payment_intent_id,
      'paymentMethodKind', p_payment_method_kind,
      'nextAction', v_next_action,
      'source', 'subscription.recovery.hidden.v0'
    ),
    jsonb_build_object('boundary', 'subscription_record_payment_recovery_request')
  )
  ON CONFLICT (event_type, idempotency_key) DO NOTHING;

  -- A repair is not a recovered payment. The retry event is emitted only by
  -- subscription_try_schedule_recovery_retry after both redeem and the canonical
  -- method-ref webhook are durable. Actual recovery remains owned by apply_result.
  PERFORM public.subscription_try_schedule_recovery_retry(
    v_case.id, p_payment_method_ref, p_requested_at
  );

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'subscriptionPaymentRecovery', jsonb_build_object(
      'caseId', v_case.id,
      'subscriptionId', v_case.subscription_id,
      'cycleId', v_case.cycle_id,
      'orderId', v_case.order_id,
      'purpose', v_token.purpose,
      'nextAction', v_next_action,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('caseId', v_case.id, 'nextAction', v_next_action)
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: subscription_record_payment_recovery_request(text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_record_payment_recovery_request(p_idempotency_key text, p_recovery_token text, p_payment_method_ref text, p_payment_method_kind text, p_requested_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'subscription.payment_recovery.request';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_token_id uuid;
  v_token_purpose text;
  v_token public.subscription_payment_recovery_tokens%ROWTYPE;
  v_case public.subscription_dunning_cases%ROWTYPE;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_recovery_token IS NULL OR btrim(p_recovery_token) = ''
    OR p_payment_method_ref IS NULL OR btrim(p_payment_method_ref) = ''
    OR p_payment_method_kind IS NULL OR btrim(p_payment_method_kind) = ''
    OR p_requested_at IS NULL
  THEN
    RAISE EXCEPTION 'subscription_payment_recovery_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT token.id, token.purpose
    INTO v_token_id, v_token_purpose
    FROM public.subscription_payment_recovery_tokens token
   WHERE token.token_hash = encode(sha256(convert_to(p_recovery_token, 'UTF8')), 'hex');

  IF NOT FOUND OR v_token_purpose <> 'resume_subscription' THEN
    RETURN public.subscription_record_payment_recovery_before_expired_resume(
      p_idempotency_key, p_recovery_token, p_payment_method_ref, p_payment_method_kind, p_requested_at
    );
  END IF;

  -- The delegate's fingerprint formula and ledger scope, so one key is single
  -- use across both branches and a replay answers from the same row.
  v_request_fingerprint := md5(
    md5(p_recovery_token) || '|' || p_payment_method_ref || '|' ||
    p_payment_method_kind || '|' || p_requested_at::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;
  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{subscriptionPaymentRecovery,replayed}', 'true'::jsonb, false);
    END IF;
    RAISE EXCEPTION 'subscription_payment_recovery_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_token
    FROM public.subscription_payment_recovery_tokens token
   WHERE token.id = v_token_id
   FOR UPDATE;
  IF v_token.used_at IS NOT NULL
    OR v_token.revoked_at IS NOT NULL
    OR v_token.expires_at <= p_requested_at
  THEN
    RAISE EXCEPTION 'subscription_payment_recovery_token_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_case
    FROM public.subscription_dunning_cases dunning_case
   WHERE dunning_case.id = v_token.case_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_payment_recovery_case_not_found' USING ERRCODE = '22023';
  END IF;
  IF v_case.subscription_id IS DISTINCT FROM v_token.subscription_id
    OR v_case.status <> 'expired'
  THEN
    RAISE EXCEPTION 'subscription_payment_recovery_case_state_mismatch' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope, idempotency_key, request_fingerprint, status, metadata
  )
  VALUES (
    v_scope, p_idempotency_key, v_request_fingerprint, 'in_progress',
    jsonb_build_object('boundary', 'subscription_record_payment_recovery_request.expired_resume')
  );

  UPDATE public.subscription_payment_recovery_tokens
     SET used_at = p_requested_at,
         updated_at = p_requested_at
   WHERE id = v_token.id;

  -- Raises rather than resumes when the redeemed method cannot be charged
  -- unattended; the whole redeem, token consumption included, rolls back.
  PERFORM public.subscription_resume_after_expired_dunning(
    p_idempotency_key || ':expired_resume',
    v_case.subscription_id,
    p_payment_method_ref,
    p_payment_method_kind,
    p_requested_at,
    'subscription.recovery.hidden.v0'
  );

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'subscriptionPaymentRecovery', jsonb_build_object(
      'caseId', v_case.id,
      'subscriptionId', v_case.subscription_id,
      'cycleId', v_case.cycle_id,
      'orderId', v_case.order_id,
      'purpose', v_token.purpose,
      'nextAction', 'resume_subscription',
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object('caseId', v_case.id, 'nextAction', 'resume_subscription')
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: FUNCTION subscription_record_payment_recovery_request(p_idempotency_key text, p_recovery_token text, p_payment_method_ref text, p_payment_method_kind text, p_requested_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_record_payment_recovery_request(p_idempotency_key text, p_recovery_token text, p_payment_method_ref text, p_payment_method_kind text, p_requested_at timestamp with time zone) IS 'Payment recovery redeem boundary. A resume_subscription token on an expired case now resumes through subscription_resume_after_expired_dunning instead of failing closed; every other token is delegated unchanged.';


--
-- Name: subscription_recover_paid_activation_with_card(text, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_recover_paid_activation_with_card(p_idempotency_key text, p_subscription_id uuid, p_payment_method_ref text, p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_candidate record;
  v_candidate_count integer;
  v_subscription public.subscriptions%ROWTYPE;
  v_card public.commerce_payment_method_refs%ROWTYPE;
  v_was_pending boolean;
  v_next_cycle_at timestamptz;
  v_existing_event_id uuid;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
     OR p_subscription_id IS NULL
     OR p_payment_method_ref IS NULL OR btrim(p_payment_method_ref) = ''
     OR p_occurred_at IS NULL THEN
    RAISE EXCEPTION 'paid_activation_card_recovery_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- Subscription-first lock: this is the single authority shared with the
  -- guarded late-alias binder. The RPC never mutates payment/order money.
  SELECT * INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'paid_activation_card_recovery_subscription_not_found' USING ERRCODE = '22023';
  END IF;

  SELECT id INTO v_existing_event_id
    FROM public.subscription_events
   WHERE idempotency_key = p_idempotency_key || ':activation_recovered_with_card';
  IF FOUND THEN
    RETURN jsonb_build_object('paidActivationCardRecovery', jsonb_build_object(
      'recovered', true, 'replayed', true, 'subscriptionId', p_subscription_id
    ));
  END IF;

  IF v_subscription.status NOT IN ('pending_activation', 'active') THEN
    RETURN jsonb_build_object('paidActivationCardRecovery', jsonb_build_object(
      'recovered', false, 'replayed', false, 'reason', 'subscription_not_recoverable'
    ));
  END IF;

  SELECT count(*)
    INTO v_candidate_count
    FROM (
      SELECT o.id AS order_id, o.subscription_cycle_id, i.id AS payment_intent_id,
             sc.paid_at
      FROM public.commerce_payment_intents i
      JOIN public.commerce_payment_attempts a
        ON a.id = i.active_attempt_id
       AND a.payment_intent_id = i.id
       AND a.provider = 'tpay'
       AND a.status = 'succeeded'
       AND a.request_payload ->> 'providerFlow' = 'blik_recurring_activation'
       AND a.request_payload ->> 'recurringModel' = 'O'
      JOIN public.commerce_orders o
        ON o.id = i.order_id
       AND o.subscription_id = p_subscription_id
       AND o.mode = 'subscription_cycle'
       AND o.status = 'paid'
      JOIN public.subscription_cycles sc
        ON sc.id = o.subscription_cycle_id
       AND sc.subscription_id = p_subscription_id
       AND sc.cycle_number = 1
       AND sc.status = 'paid'
       AND sc.paid_at IS NOT NULL
      JOIN public.commerce_payments p
        ON p.id = i.payment_id
       AND p.order_id = o.id
       AND p.status = 'succeeded'
      WHERE i.subscription_id = p_subscription_id
        AND i.target_kind = 'subscription_cycle'
        AND i.status = 'succeeded'
    ) c;

  IF v_candidate_count <> 1 THEN
    RETURN jsonb_build_object('paidActivationCardRecovery', jsonb_build_object(
      'recovered', false, 'replayed', false, 'reason', 'exact_initial_payment_not_found'
    ));
  END IF;

  SELECT o.id AS order_id, o.subscription_cycle_id, i.id AS payment_intent_id,
         sc.paid_at
    INTO v_candidate
    FROM public.commerce_payment_intents i
    JOIN public.commerce_payment_attempts a
      ON a.id = i.active_attempt_id
     AND a.payment_intent_id = i.id
     AND a.provider = 'tpay'
     AND a.status = 'succeeded'
     AND a.request_payload ->> 'providerFlow' = 'blik_recurring_activation'
     AND a.request_payload ->> 'recurringModel' = 'O'
    JOIN public.commerce_orders o
      ON o.id = i.order_id
     AND o.subscription_id = p_subscription_id
     AND o.mode = 'subscription_cycle'
     AND o.status = 'paid'
    JOIN public.subscription_cycles sc
      ON sc.id = o.subscription_cycle_id
     AND sc.subscription_id = p_subscription_id
     AND sc.cycle_number = 1
     AND sc.status = 'paid'
     AND sc.paid_at IS NOT NULL
    JOIN public.commerce_payments p
      ON p.id = i.payment_id
     AND p.order_id = o.id
     AND p.status = 'succeeded'
   WHERE i.subscription_id = p_subscription_id
     AND i.target_kind = 'subscription_cycle'
     AND i.status = 'succeeded';

  SELECT * INTO v_card
    FROM public.commerce_payment_method_refs
   WHERE provider_kind = 'stripe'
     AND method_kind = 'card'
     AND provider_method_ref = btrim(p_payment_method_ref)
     AND subscription_id = p_subscription_id
     AND client_id = v_subscription.client_id
     AND status = 'active'
     AND (expires_at IS NULL OR expires_at > now())
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'paid_activation_card_recovery_verified_card_missing' USING ERRCODE = '22023';
  END IF;

  v_was_pending := v_subscription.status = 'pending_activation';
  v_next_cycle_at := CASE
    WHEN v_was_pending THEN (v_candidate.paid_at)::timestamptz + (v_subscription.cadence_days * interval '1 day')
    ELSE v_subscription.next_cycle_at
  END;

  UPDATE public.commerce_payment_method_refs
     SET active = false, deactivated_at = now(), updated_at = now()
   WHERE subscription_id = p_subscription_id
     AND id <> v_card.id
     AND active = true;

  UPDATE public.commerce_payment_method_refs
     SET active = true, status = 'active', deactivated_at = NULL, updated_at = now()
   WHERE id = v_card.id;

  UPDATE public.subscriptions
     SET status = 'active',
         started_at = CASE WHEN v_was_pending THEN (v_candidate.paid_at)::timestamptz ELSE started_at END,
         payment_method_ref = v_card.provider_method_ref,
         payment_method_kind = 'card',
         next_cycle_at = v_next_cycle_at,
         updated_at = now()
   WHERE id = p_subscription_id;

  IF v_was_pending THEN
    INSERT INTO public.subscription_events (
      subscription_id, cycle_id, event_type, idempotency_key, payload, occurred_at
    ) VALUES (
      p_subscription_id,
      (v_candidate.subscription_cycle_id)::uuid,
      'subscription.activated',
      p_idempotency_key || ':subscription_activated',
      jsonb_build_object(
        'orderId', v_candidate.order_id,
        'paymentIntentId', v_candidate.payment_intent_id,
        'paymentMethodRef', v_card.provider_method_ref,
        'paymentMethodKind', 'card',
        'nextCycleAt', v_next_cycle_at,
        'source', 'subscription.paid_activation_card_recovery.v1'
      ),
      (v_candidate.paid_at)::timestamptz
    ) ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
  END IF;

  INSERT INTO public.subscription_events (
    subscription_id, cycle_id, event_type, idempotency_key, payload, occurred_at
  ) VALUES (
    p_subscription_id,
    (v_candidate.subscription_cycle_id)::uuid,
    CASE WHEN v_was_pending
      THEN 'subscription.activation_recovered_with_card'
      ELSE 'subscription.payment_method_changed'
    END,
    p_idempotency_key || ':activation_recovered_with_card',
    jsonb_build_object(
      'orderId', v_candidate.order_id,
      'paymentIntentId', v_candidate.payment_intent_id,
      'paymentMethodKind', 'card',
      'source', 'stripe.setup_intent.succeeded',
      'wasPendingActivation', v_was_pending
    ),
    p_occurred_at
  ) ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  RETURN jsonb_build_object('paidActivationCardRecovery', jsonb_build_object(
    'recovered', true,
    'replayed', false,
    'subscriptionId', p_subscription_id,
    'status', 'active',
    'nextCycleAt', v_next_cycle_at
  ));
END;
$$;


--
-- Name: subscription_renewal_note_row_outcome(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_renewal_note_row_outcome(p_subscription_id uuid, p_scheduled_at timestamp with time zone, p_error_key text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_cycle public.subscription_cycles%ROWTYPE;
  v_key text;
  v_count integer;
  v_until timestamptz;
BEGIN
  IF p_subscription_id IS NULL OR p_scheduled_at IS NULL THEN
    RAISE EXCEPTION 'subscription_renewal_row_outcome_invalid_input' USING ERRCODE = '22023';
  END IF;

  -- A blank key is the same statement as no key: the row made progress.
  v_key := NULLIF(btrim(COALESCE(p_error_key, '')), '');

  SELECT *
    INTO v_cycle
    FROM public.subscription_cycles
   WHERE subscription_id = p_subscription_id
     AND scheduled_at = p_scheduled_at
   ORDER BY cycle_number DESC
   LIMIT 1
   FOR UPDATE;

  -- No cycle yet (the batch can fail before it creates one). Silent no-op
  -- rather than an exception: bookkeeping must never be able to convert a
  -- recoverable row failure into a batch failure.
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'renewalRowOutcome', jsonb_build_object('matched', false)
    );
  END IF;

  IF v_key IS NULL THEN
    -- Clean pass. Clear unconditionally — that is what makes the counter a
    -- measure of CONSECUTIVE failures rather than a lifetime tally, and it is
    -- the primary way a quarantine ends early.
    -- Guarded so the overwhelmingly common case (a healthy row that never
    -- failed) costs no write and no WAL: this runs once per processed row on
    -- every batch pass.
    UPDATE public.subscription_cycles
       SET renewal_row_error_key = NULL,
           renewal_row_error_count = 0,
           renewal_quarantined_until = NULL,
           updated_at = now()
     WHERE id = v_cycle.id
       AND (
         renewal_row_error_key IS NOT NULL
         OR renewal_row_error_count <> 0
         OR renewal_quarantined_until IS NOT NULL
       );

    RETURN jsonb_build_object(
      'contractVersion', 'commerce.v0',
      'renewalRowOutcome', jsonb_build_object(
        'matched', true, 'cycleId', v_cycle.id, 'errorCount', 0, 'quarantinedUntil', NULL
      )
    );
  END IF;

  -- A DIFFERENT key is a different fault, so the streak restarts at 1 instead
  -- of inheriting a quarantine earned by something unrelated.
  v_count := CASE
    WHEN v_cycle.renewal_row_error_key IS NOT DISTINCT FROM v_key
      THEN v_cycle.renewal_row_error_count + 1
    ELSE 1
  END;

  -- The first two failures keep the normal cadence: a transient fault must not
  -- cost a customer a delayed renewal. From the third IDENTICAL one the row is
  -- provably deterministic, so back off 30m, 1h, 2h, 4h and hold at the 6h
  -- ceiling — still at least four attempts a day, so this can never become a
  -- stop. The exponent is clamped before the multiplication so a long-lived
  -- streak cannot overflow the interval on its way into LEAST().
  v_until := CASE
    WHEN v_count < 3 THEN NULL
    ELSE now() + LEAST(
      (2 ^ LEAST(v_count - 2, 8))::integer * interval '15 minutes',
      interval '6 hours'
    )
  END;

  UPDATE public.subscription_cycles
     SET renewal_row_error_key = v_key,
         renewal_row_error_count = v_count,
         renewal_quarantined_until = v_until,
         updated_at = now()
   WHERE id = v_cycle.id;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'renewalRowOutcome', jsonb_build_object(
      'matched', true,
      'cycleId', v_cycle.id,
      'errorKey', v_key,
      'errorCount', v_count,
      'quarantinedUntil', v_until
    )
  );
END;
$$;


--
-- Name: FUNCTION subscription_renewal_note_row_outcome(p_subscription_id uuid, p_scheduled_at timestamp with time zone, p_error_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_renewal_note_row_outcome(p_subscription_id uuid, p_scheduled_at timestamp with time zone, p_error_key text) IS 'Service-role-only. Records or clears one renewal batch row outcome for a cycle and, from the third consecutive identical error key, parks the cycle behind a capped self-expiring quarantine.';


--
-- Name: subscription_resume_after_expired_dunning(text, uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_resume_after_expired_dunning(p_idempotency_key text, p_subscription_id uuid, p_payment_method_ref text, p_payment_method_kind text, p_requested_at timestamp with time zone, p_source text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_subscription public.subscriptions%ROWTYPE;
  v_case public.subscription_dunning_cases%ROWTYPE;
  v_stale_cycle_id uuid;
  v_next_cycle_at timestamptz;
  v_event_id uuid;
BEGIN
  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8
    OR p_subscription_id IS NULL
    OR p_requested_at IS NULL
    OR p_source IS NULL OR btrim(p_source) = ''
  THEN
    RAISE EXCEPTION 'subscription_resume_after_expired_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_subscription
    FROM public.subscriptions
   WHERE id = p_subscription_id
   FOR UPDATE;
  IF NOT FOUND OR v_subscription.status <> 'paused' THEN
    RAISE EXCEPTION 'subscription_resume_after_expired_invalid_transition' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_case
    FROM public.subscription_dunning_cases dunning_case
   WHERE dunning_case.subscription_id = p_subscription_id
   ORDER BY dunning_case.opened_at DESC, dunning_case.id DESC
   LIMIT 1
   FOR UPDATE;
  IF NOT FOUND OR v_case.status <> 'expired' THEN
    RAISE EXCEPTION 'subscription_resume_after_expired_case_not_expired' USING ERRCODE = '22023';
  END IF;

  IF p_payment_method_ref IS NOT NULL AND btrim(p_payment_method_ref) <> '' THEN
    UPDATE public.subscriptions
       SET payment_method_ref = p_payment_method_ref,
           payment_method_kind = COALESCE(NULLIF(btrim(p_payment_method_kind), ''), payment_method_kind),
           updated_at = p_requested_at
     WHERE id = p_subscription_id
     RETURNING * INTO v_subscription;
  END IF;

  IF NOT public.subscription_method_chargeable_unattended(p_subscription_id, p_requested_at) THEN
    RAISE EXCEPTION 'subscription_resume_after_expired_method_not_chargeable' USING ERRCODE = '22023';
  END IF;

  FOR v_stale_cycle_id IN
    SELECT cycle.id
      FROM public.subscription_cycles cycle
     WHERE cycle.subscription_id = p_subscription_id
       AND cycle.status IN ('payment_pending', 'retry_scheduled', 'payment_failed')
     ORDER BY cycle.cycle_number, cycle.id
  LOOP
    PERFORM public.subscription_terminalize_unpaid_cycle_artifacts(
      p_subscription_id,
      v_stale_cycle_id,
      p_requested_at,
      'subscription_resumed_after_expired_dunning'
    );
  END LOOP;

  UPDATE public.subscription_dunning_cases
     SET status = 'resumed_unpaid',
         next_retry_at = NULL,
         last_event_at = p_requested_at,
         updated_at = p_requested_at,
         metadata = metadata || jsonb_build_object(
           'closedReason', 'subscription_resumed_after_expired_dunning',
           'resumedAt', p_requested_at,
           'resumeSource', p_source
         )
   WHERE id = v_case.id
   RETURNING * INTO v_case;

  UPDATE public.subscription_payment_recovery_tokens token
     SET revoked_at = COALESCE(token.revoked_at, p_requested_at),
         updated_at = p_requested_at
   WHERE token.case_id = v_case.id
     AND token.used_at IS NULL
     AND token.revoked_at IS NULL;

  UPDATE public.subscription_dunning_notifications notification
     SET status = 'skipped',
         recovery_url_path = NULL,
         provider_error = COALESCE(notification.provider_error, 'subscription_resumed'),
         updated_at = p_requested_at
   WHERE notification.case_id = v_case.id
     AND notification.status = 'queued';

  v_next_cycle_at := p_requested_at + interval '2 days';

  UPDATE public.subscriptions
     SET status = 'active',
         next_cycle_at = v_next_cycle_at,
         updated_at = p_requested_at
   WHERE id = p_subscription_id
   RETURNING * INTO v_subscription;

  UPDATE public.subscription_pause_windows
     SET resumed_at = p_requested_at,
         updated_at = p_requested_at
   WHERE subscription_id = p_subscription_id
     AND resumed_at IS NULL;

  INSERT INTO public.subscription_events (
    subscription_id, cycle_id, event_type, idempotency_key, payload, occurred_at
  )
  VALUES (
    p_subscription_id,
    v_case.cycle_id,
    'subscription.customer_self_service.resume',
    p_idempotency_key,
    jsonb_build_object(
      'action', 'resume',
      'caseId', v_case.id,
      'skippedCycleId', v_case.cycle_id,
      'resumedAfterExpiredDunning', true,
      'nextCycleAt', v_next_cycle_at,
      'source', p_source
    ),
    p_requested_at
  )
  RETURNING id INTO v_event_id;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'subscriptionResumeAfterExpiredDunning', jsonb_build_object(
      'caseId', v_case.id,
      'subscriptionId', p_subscription_id,
      'skippedCycleId', v_case.cycle_id,
      'orderId', v_case.order_id,
      'nextCycleAt', v_next_cycle_at,
      'eventId', v_event_id
    )
  );
END;
$$;


--
-- Name: FUNCTION subscription_resume_after_expired_dunning(p_idempotency_key text, p_subscription_id uuid, p_payment_method_ref text, p_payment_method_kind text, p_requested_at timestamp with time zone, p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_resume_after_expired_dunning(p_idempotency_key text, p_subscription_id uuid, p_payment_method_ref text, p_payment_method_kind text, p_requested_at timestamp with time zone, p_source text) IS 'Resumes a paused subscription whose latest dunning case expired: refuses an unchargeable stored method, skips every uncollected cycle with its unpaid artifacts, closes the latest case as resumed_unpaid, and re-arms the next cycle two days out.';


--
-- Name: subscription_resume_from_dunning_with_cycle_order(text, text, text, text, integer, timestamp with time zone, jsonb, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_resume_from_dunning_with_cycle_order(p_idempotency_key text, p_recovery_token text, p_payment_method_ref text, p_payment_method_kind text, p_cycle_number integer, p_scheduled_at timestamp with time zone, p_template_snapshot jsonb, p_pricing_snapshot jsonb, p_order_snapshot jsonb, p_requested_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_scope constant text := 'subscription.dunning.resume_cycle_order';
  v_request_fingerprint text;
  v_existing public.commerce_idempotency_keys%ROWTYPE;
  v_token public.subscription_payment_recovery_tokens%ROWTYPE;
  v_case public.subscription_dunning_cases%ROWTYPE;
  v_old_cycle public.subscription_cycles%ROWTYPE;
  v_stale_cycle_id uuid;
  v_cycle_order jsonb;
  v_cycle_order_body jsonb;
  v_response jsonb;
BEGIN
  IF p_idempotency_key IS NULL OR btrim(p_idempotency_key) = '' OR length(p_idempotency_key) < 8
    OR p_recovery_token IS NULL OR btrim(p_recovery_token) = ''
    OR p_payment_method_ref IS NULL OR btrim(p_payment_method_ref) = ''
    OR p_payment_method_kind IS NULL OR btrim(p_payment_method_kind) = ''
    OR p_cycle_number IS NULL OR p_cycle_number < 1
    OR p_scheduled_at IS NULL
    OR p_template_snapshot IS NULL
    OR p_pricing_snapshot IS NULL
    OR p_order_snapshot IS NULL
    OR p_requested_at IS NULL
  THEN
    RAISE EXCEPTION 'subscription_dunning_resume_invalid_input' USING ERRCODE = '22023';
  END IF;

  v_request_fingerprint := md5(
    md5(p_recovery_token) || '|' ||
    p_payment_method_ref || '|' ||
    p_payment_method_kind || '|' ||
    p_cycle_number::text || '|' ||
    p_scheduled_at::text || '|' ||
    p_template_snapshot::text || '|' ||
    p_pricing_snapshot::text || '|' ||
    p_order_snapshot::text || '|' ||
    p_requested_at::text
  );

  SELECT *
    INTO v_existing
    FROM public.commerce_idempotency_keys
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key
   FOR UPDATE;

  IF FOUND THEN
    IF v_existing.status = 'completed'
      AND v_existing.request_fingerprint = v_request_fingerprint
      AND v_existing.response_payload IS NOT NULL
    THEN
      RETURN jsonb_set(v_existing.response_payload, '{subscriptionDunningResume,replayed}', 'true'::jsonb, false);
    END IF;

    RAISE EXCEPTION 'subscription_dunning_resume_idempotency_conflict' USING ERRCODE = '23505';
  END IF;

  SELECT *
    INTO v_token
    FROM public.subscription_payment_recovery_tokens
   WHERE token_hash = encode(sha256(convert_to(p_recovery_token, 'UTF8')), 'hex')
   FOR UPDATE;
  IF NOT FOUND
    OR v_token.purpose <> 'resume_subscription'
    OR v_token.used_at IS NOT NULL
    OR v_token.revoked_at IS NOT NULL
    OR v_token.expires_at <= p_requested_at
  THEN
    RAISE EXCEPTION 'subscription_dunning_resume_token_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_case
    FROM public.subscription_dunning_cases
   WHERE id = v_token.case_id
   FOR UPDATE;
  IF NOT FOUND OR v_case.status <> 'expired' THEN
    RAISE EXCEPTION 'subscription_dunning_resume_case_not_expired' USING ERRCODE = '22023';
  END IF;

  SELECT *
    INTO v_old_cycle
    FROM public.subscription_cycles
   WHERE id = v_case.cycle_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_dunning_resume_cycle_not_found' USING ERRCODE = '22023';
  END IF;

  IF p_cycle_number <= v_old_cycle.cycle_number THEN
    RAISE EXCEPTION 'subscription_dunning_resume_cycle_number_not_fresh' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.commerce_idempotency_keys (
    scope,
    idempotency_key,
    request_fingerprint,
    status,
    metadata
  )
  VALUES (
    v_scope,
    p_idempotency_key,
    v_request_fingerprint,
    'in_progress',
    jsonb_build_object('boundary', 'subscription_resume_from_dunning_with_cycle_order')
  );

  UPDATE public.subscriptions
     SET status = CASE WHEN status = 'paused' THEN 'active' ELSE status END,
         payment_method_ref = p_payment_method_ref,
         payment_method_kind = p_payment_method_kind,
         updated_at = now()
   WHERE id = v_case.subscription_id;

  UPDATE public.subscription_payment_recovery_tokens
     SET used_at = p_requested_at,
         updated_at = now()
   WHERE id = v_token.id;

  FOR v_stale_cycle_id IN
    SELECT cycle.id
      FROM public.subscription_cycles cycle
     WHERE cycle.subscription_id = v_case.subscription_id
       AND cycle.status IN ('payment_pending', 'retry_scheduled', 'payment_failed')
     ORDER BY cycle.cycle_number, cycle.id
  LOOP
    PERFORM public.subscription_terminalize_unpaid_cycle_artifacts(
      v_case.subscription_id,
      v_stale_cycle_id,
      p_requested_at,
      'subscription_resumed_after_expired_dunning'
    );
  END LOOP;

  v_cycle_order := public.subscription_create_cycle_order_with_outbox(
    p_idempotency_key || ':cycle_order',
    v_case.subscription_id,
    p_cycle_number,
    p_scheduled_at,
    p_template_snapshot,
    p_pricing_snapshot,
    p_order_snapshot
  );
  v_cycle_order_body := v_cycle_order->'subscriptionCycleOrder';

  UPDATE public.subscription_dunning_cases
     SET status = 'resumed_unpaid',
         last_event_at = p_requested_at,
         updated_at = now(),
         metadata = metadata || jsonb_build_object(
           'closedReason', 'subscription_resumed_after_expired_dunning',
           'resumedAt', p_requested_at,
           'resumeCycleId', v_cycle_order_body->>'cycleId',
           'resumeOrderId', v_cycle_order_body->>'orderId',
           'source', 'subscription.recovery.hidden.v0'
         )
   WHERE id = v_case.id
   RETURNING * INTO v_case;

  INSERT INTO public.subscription_events (
    subscription_id,
    cycle_id,
    event_type,
    idempotency_key,
    payload,
    occurred_at
  )
  VALUES (
    v_case.subscription_id,
    v_case.cycle_id,
    'subscription.resumed',
    p_idempotency_key || ':subscription_resumed',
    jsonb_build_object(
      'caseId', v_case.id,
      'previousCycleId', v_case.cycle_id,
      'resumeCycleOrder', v_cycle_order_body,
      'source', 'subscription.recovery.hidden.v0'
    ),
    p_requested_at
  )
  ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

  v_response := jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'subscriptionDunningResume', jsonb_build_object(
      'caseId', v_case.id,
      'subscriptionId', v_case.subscription_id,
      'previousCycleId', v_case.cycle_id,
      'cycleOrder', v_cycle_order_body,
      'replayed', false
    )
  );

  UPDATE public.commerce_idempotency_keys
     SET status = 'completed',
         response_payload = v_response,
         metadata = metadata || jsonb_build_object(
           'caseId', v_case.id,
           'subscriptionId', v_case.subscription_id,
           'resumeCycleId', v_cycle_order_body->>'cycleId',
           'resumeOrderId', v_cycle_order_body->>'orderId'
         )
   WHERE scope = v_scope
     AND idempotency_key = p_idempotency_key;

  RETURN v_response;
END;
$$;


--
-- Name: FUNCTION subscription_resume_from_dunning_with_cycle_order(p_idempotency_key text, p_recovery_token text, p_payment_method_ref text, p_payment_method_kind text, p_cycle_number integer, p_scheduled_at timestamp with time zone, p_template_snapshot jsonb, p_pricing_snapshot jsonb, p_order_snapshot jsonb, p_requested_at timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_resume_from_dunning_with_cycle_order(p_idempotency_key text, p_recovery_token text, p_payment_method_ref text, p_payment_method_kind text, p_cycle_number integer, p_scheduled_at timestamp with time zone, p_template_snapshot jsonb, p_pricing_snapshot jsonb, p_order_snapshot jsonb, p_requested_at timestamp with time zone) IS 'Consumes an expired-dunning resume token, skips every pre-existing uncollected cycle with its unpaid artifacts, and creates the explicitly supplied fresh cycle order with durable idempotency.';


--
-- Name: subscription_rotate_payment_recovery_token(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_rotate_payment_recovery_token(p_case_id uuid, p_token_hash text, p_expires_at timestamp with time zone, p_source text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
  v_case public.subscription_dunning_cases%ROWTYPE;
  v_recorded_at timestamptz := clock_timestamp();
  v_token_id uuid;
BEGIN
  IF p_case_id IS NULL
     OR COALESCE(p_token_hash, '') !~ '^[0-9a-f]{64}$'
     OR p_expires_at IS NULL OR p_expires_at <= v_recorded_at
     OR COALESCE(p_source, '') NOT IN ('customer_payment_recovery_start', 'customer_support_recovery')
  THEN
    RAISE EXCEPTION 'subscription_payment_recovery_rotation_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_case
    FROM public.subscription_dunning_cases AS case_row
   WHERE case_row.id = p_case_id
     AND case_row.status = 'open'
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription_payment_recovery_case_not_open' USING ERRCODE = '22023';
  END IF;

  UPDATE public.subscription_payment_recovery_tokens AS recovery_token
     SET revoked_at = v_recorded_at,
         updated_at = v_recorded_at
   WHERE recovery_token.case_id = p_case_id
     AND recovery_token.used_at IS NULL
     AND recovery_token.revoked_at IS NULL
     AND recovery_token.expires_at > v_recorded_at;

  INSERT INTO public.subscription_payment_recovery_tokens (
    case_id, subscription_id, cycle_id, order_id, client_id, token_hash,
    purpose, expires_at, metadata, created_at, updated_at
  ) VALUES (
    v_case.id, v_case.subscription_id, v_case.cycle_id, v_case.order_id,
    v_case.client_id, p_token_hash, 'repair_payment', p_expires_at,
    jsonb_build_object('source', p_source), v_recorded_at, v_recorded_at
  )
  RETURNING id INTO v_token_id;

  RETURN v_token_id;
END;
$_$;


--
-- Name: subscription_self_service_line_set_matches(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_self_service_line_set_matches(p_subscription_id uuid, p_lines jsonb, p_is_addon boolean) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  WITH desired_raw AS (
    SELECT value->>'variantId' AS variant_id_text, value->>'qty' AS qty_text
    FROM jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(COALESCE(p_lines, '[]'::jsonb)) = 'array'
          THEN COALESCE(p_lines, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS value
  ),
  desired_valid AS (
    SELECT variant_id_text::uuid AS variant_id, qty_text::integer AS qty
    FROM desired_raw
    WHERE variant_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND qty_text ~ '^[1-9][0-9]{0,5}$'
  ),
  desired AS (
    SELECT variant_id, sum(qty)::integer AS qty
    FROM desired_valid
    GROUP BY variant_id
  ),
  current AS (
    SELECT variant_id, sum(qty)::integer AS qty
    FROM public.subscription_lines
    WHERE subscription_id = p_subscription_id
      AND is_addon = p_is_addon
    GROUP BY variant_id
  ),
  desired_sig AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('variantId', variant_id, 'qty', qty) ORDER BY variant_id), '[]'::jsonb) AS value
    FROM desired
  ),
  current_sig AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('variantId', variant_id, 'qty', qty) ORDER BY variant_id), '[]'::jsonb) AS value
    FROM current
  )
  SELECT
    jsonb_typeof(COALESCE(p_lines, '[]'::jsonb)) = 'array'
    AND (SELECT count(*) FROM desired_raw) = (SELECT count(*) FROM desired_valid)
    AND (SELECT value FROM desired_sig) = (SELECT value FROM current_sig);
$_$;


--
-- Name: subscription_sweep_unpaid_provisional(text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_sweep_unpaid_provisional(p_idempotency_prefix text, p_older_than timestamp with time zone, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_sub public.subscriptions%ROWTYPE;
  v_recovery_token text;
  v_recovery_token_hash text;
  v_recovery_expires_at timestamptz;
  v_order public.commerce_orders%ROWTYPE;
  v_has_order boolean;
  v_cycle_id uuid;
  v_swept jsonb := '[]'::jsonb;
  v_count integer := 0;
BEGIN
  IF p_idempotency_prefix IS NULL OR length(btrim(p_idempotency_prefix)) < 8
     OR p_older_than IS NULL
     OR p_limit IS NULL OR p_limit < 1 THEN
    RAISE EXCEPTION 'subscription_sweep_invalid_input' USING ERRCODE = '22023';
  END IF;

  FOR v_sub IN
    SELECT candidate.*
      FROM public.subscriptions candidate
      LEFT JOIN LATERAL (
        SELECT checkout_order.id, checkout_order.status
          FROM public.commerce_orders checkout_order
         WHERE checkout_order.subscription_id = candidate.id
           AND checkout_order.mode = 'subscription_cycle'
         ORDER BY checkout_order.created_at, checkout_order.id
         LIMIT 1
      ) candidate_order ON true
     WHERE candidate.status = 'pending_activation'
       AND candidate.created_at < p_older_than
       -- Skip stable refusals before the page limit. Evidence arriving after
       -- this snapshot is still fenced by the unchanged checks after locking.
       AND (
         candidate_order.id IS NULL
         OR (
           candidate_order.status NOT IN ('paid', 'refunded', 'fulfillment_pending', 'fulfilled')
           AND NOT EXISTS (
             SELECT 1
               FROM public.commerce_payment_intents payment_intent
              WHERE payment_intent.order_id = candidate_order.id
                AND (
                  payment_intent.status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed')
                  OR payment_intent.provider_payment_id IS NOT NULL
                  OR EXISTS (
                    SELECT 1
                      FROM public.commerce_payment_attempts payment_attempt
                     WHERE payment_attempt.payment_intent_id = payment_intent.id
                       AND NOT (
                         payment_attempt.status = 'blocked_preflight'
                         AND payment_attempt.provider_attempt_id IS NULL
                         AND payment_attempt.provider_session_id IS NULL
                         AND payment_attempt.next_action_kind IS NULL
                         AND payment_attempt.response_payload->>'providerCall'
                               IS NOT DISTINCT FROM 'false'
                       )
                  )
                  OR EXISTS (
                    SELECT 1
                      FROM public.inbound_provider_events provider_event
                     WHERE provider_event.payment_intent_id = payment_intent.id
                       AND provider_event.signature_verified IS TRUE
                  )
                  OR EXISTS (
                    SELECT 1
                      FROM public.commerce_payment_reconciliation_runs reconciliation
                     WHERE reconciliation.payment_intent_id = payment_intent.id
                  )
                )
           )
           AND NOT EXISTS (
             SELECT 1
               FROM public.commerce_payments payment
              WHERE payment.order_id = candidate_order.id
                AND (
                  payment.status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed')
                  OR payment.provider_payment_id IS NOT NULL
                )
           )
         )
       )
     ORDER BY candidate.created_at, candidate.id
     LIMIT p_limit
     FOR UPDATE OF candidate SKIP LOCKED
  LOOP
    SELECT *
      INTO v_order
      FROM public.commerce_orders
     WHERE subscription_id = v_sub.id
       AND mode = 'subscription_cycle'
     ORDER BY created_at, id
     LIMIT 1
     FOR UPDATE;
    v_has_order := FOUND;

    -- Abandonment requires explicit negative terminal payment truth. Reuse the
    -- existing cancellation lock guard so verified provider/reconciliation
    -- evidence and concurrent evidence inserts are fenced too. Every refusal
    -- happens before the first destructive write in this function.
    IF v_has_order AND (
      v_order.status IN ('paid', 'refunded', 'fulfillment_pending', 'fulfilled')
      OR public.commerce_checkout_cancel_lock_guard(v_order.id) IS NOT NULL
    ) THEN
      CONTINUE;
    END IF;

    -- The shared guard intentionally permits terminal retry states for its other
    -- cancellation callers. This automatic sweep has a stricter proof burden:
    -- only zero attempts or attempts proven to have stopped before any provider
    -- call are abandonment. Intent locks taken by the helper fence concurrent
    -- attempt/event/reconciliation inserts until this decision commits.
    IF v_has_order AND (
      EXISTS (
        SELECT 1
          FROM public.commerce_payment_attempts payment_attempt
          JOIN public.commerce_payment_intents payment_intent
            ON payment_intent.id = payment_attempt.payment_intent_id
         WHERE payment_intent.order_id = v_order.id
           AND NOT (
             payment_attempt.status = 'blocked_preflight'
             AND payment_attempt.provider_attempt_id IS NULL
             AND payment_attempt.provider_session_id IS NULL
             AND payment_attempt.next_action_kind IS NULL
             AND payment_attempt.response_payload->>'providerCall'
                   IS NOT DISTINCT FROM 'false'
           )
      )
      OR EXISTS (
        SELECT 1
          FROM public.commerce_payment_intents payment_intent
         WHERE payment_intent.order_id = v_order.id
           AND payment_intent.provider_payment_id IS NOT NULL
      )
      OR EXISTS (
        SELECT 1
          FROM public.commerce_payments payment
         WHERE payment.order_id = v_order.id
           AND payment.provider_payment_id IS NOT NULL
      )
      OR EXISTS (
        SELECT 1
          FROM public.inbound_provider_events provider_event
          JOIN public.commerce_payment_intents payment_intent
            ON payment_intent.id = provider_event.payment_intent_id
         WHERE payment_intent.order_id = v_order.id
           AND provider_event.signature_verified IS TRUE
      )
      OR EXISTS (
        SELECT 1
          FROM public.commerce_payment_reconciliation_runs reconciliation
          JOIN public.commerce_payment_intents payment_intent
            ON payment_intent.id = reconciliation.payment_intent_id
         WHERE payment_intent.order_id = v_order.id
      )
    ) THEN
      CONTINUE;
    END IF;

    IF v_has_order THEN
      UPDATE public.commerce_payment_intents
         SET status = 'cancelled',
             updated_at = now()
       WHERE order_id = v_order.id
         AND status NOT IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed');

      UPDATE public.commerce_payment_attempts
         SET status = 'cancelled',
             updated_at = now()
       WHERE payment_intent_id IN (
               SELECT id FROM public.commerce_payment_intents WHERE order_id = v_order.id
             )
         AND status NOT IN ('succeeded', 'cancelled', 'failed', 'expired');

      UPDATE public.commerce_payments
         SET status = 'cancelled',
             metadata = metadata || jsonb_build_object('paymentStatus', 'cancelled', 'source', 'subscription.sweep.v0'),
             updated_at = now()
       WHERE order_id = v_order.id
         AND status NOT IN ('succeeded', 'cancelled', 'refunded', 'partially_refunded', 'disputed');

      UPDATE public.commerce_orders
         SET status = 'cancelled',
             metadata = metadata || jsonb_build_object(
               'paymentStatus', 'cancelled',
               'subscriptionActivation', 'abandoned',
               'source', 'subscription.sweep.v0'
             ),
             updated_at = now()
       WHERE id = v_order.id;

      PERFORM public.commerce_release_order_reservations(v_order.id, 'subscription_activation_abandoned');

      -- The buyer hears nothing today: the cancellation email is suppressed
      -- (correctly - they never had a live subscription) and the checkout-expired
      -- trigger cannot see this row, because it requires `expired` AND
      -- `mode = 'one_time'` while the sweep writes `cancelled` on a
      -- `subscription_cycle`. So the one honest message is emitted here instead,
      -- carrying the same 30-day recovery token the one-time rail already mints.
      -- ⛔ Guarded on `client_id`: the token table requires it NOT NULL, and an
      -- unguarded copy would abort the whole sweep for every other buyer in the run.
      IF v_order.client_id IS NOT NULL THEN
        v_recovery_token := 'rcv_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
        v_recovery_token_hash := encode(sha256(convert_to(v_recovery_token, 'UTF8')), 'hex');
        v_recovery_expires_at := COALESCE(v_order.created_at, now()) + interval '30 days';

        WITH sweep_expired_inserted AS (
          INSERT INTO public.outbox_events (
            aggregate_type, aggregate_id, event_type, idempotency_key, payload, metadata
          )
          VALUES (
            'commerce_order',
            v_order.id,
            'commerce.checkout.expired',
            'checkout_expired:' || v_order.id::text,
            jsonb_build_object(
              'orderId', 'order_' || v_order.id::text,
              'orderUuid', v_order.id,
              'totalCents', v_order.total_cents,
              'currency', v_order.currency,
              'recoveryToken', v_recovery_token,
              'mode', v_order.mode,
              'expiresAt', v_recovery_expires_at,
              'occurredAt', now()
            ),
            jsonb_build_object(
              'source', 'subscription_sweep_unpaid_provisional',
              'truthRepair', 'checkout_expired',
              'recoveryToken', 'checkout_recovery_hash_only'
            )
          )
          ON CONFLICT (event_type, idempotency_key) DO NOTHING
          RETURNING aggregate_id
        )
        INSERT INTO public.commerce_checkout_recovery_tokens (
          order_id, client_id, token_hash, expires_at, metadata
        )
        SELECT
          v_order.id,
          v_order.client_id,
          v_recovery_token_hash,
          v_recovery_expires_at,
          jsonb_build_object(
            'source', 'subscription_sweep_unpaid_provisional',
            'eventType', 'commerce.checkout.expired',
            'outboxIdempotencyKey', 'checkout_expired:' || v_order.id::text
          )
          FROM sweep_expired_inserted;
      END IF;
    END IF;

    UPDATE public.subscription_cycles
       SET status = 'cancelled',
           next_retry_at = NULL,
           updated_at = now()
     WHERE subscription_id = v_sub.id
       AND status NOT IN ('paid', 'cancelled');

    -- Suppress the customer cancel-email: pre-seed the trigger's exactly-once outbox
    -- row (subscription_cancelled:<id>) as DISCARDED so the AFTER UPDATE trigger's
    -- own INSERT dedupes (ON CONFLICT DO NOTHING). This is an internal abandonment
    -- sweep of a provisional the customer never activated, not a customer action.
    INSERT INTO public.outbox_events (
      aggregate_type, aggregate_id, event_type, idempotency_key, status, payload, metadata
    )
    VALUES (
      'subscription', v_sub.id, 'subscription.cancelled',
      'subscription_cancelled:' || v_sub.id::text, 'discarded',
      jsonb_build_object('subscriptionId', v_sub.id, 'suppressedReason', 'provisional_activation_abandoned'),
      jsonb_build_object('source', 'subscription_sweep_unpaid_provisional', 'suppressedCustomerEmail', true)
    )
    ON CONFLICT (event_type, idempotency_key) DO NOTHING;

    UPDATE public.subscriptions
       SET status = 'cancelled',
           -- Stated rather than implied. Fail-closed for the customer email:
           -- the cancelled-email handler sends only for source `customer`, so a
           -- system value can never resurrect the notice this sweep suppresses.
           -- Visibility is unchanged: the account read model tests POSITIVELY for
           -- `customer_self_service`, so NULL and this value are both hidden.
           cancellation_source = 'system_provisional_activation_timeout',
           updated_at = now()
     WHERE id = v_sub.id;

    SELECT id
      INTO v_cycle_id
      FROM public.subscription_cycles
     WHERE subscription_id = v_sub.id
     ORDER BY cycle_number
     LIMIT 1;

    INSERT INTO public.subscription_events (
      subscription_id,
      cycle_id,
      event_type,
      idempotency_key,
      payload,
      occurred_at
    )
    VALUES (
      v_sub.id,
      v_cycle_id,
      'subscription.activation_abandoned',
      p_idempotency_prefix || ':' || v_sub.id::text,
      jsonb_build_object(
        'orderId', CASE WHEN v_has_order THEN v_order.id ELSE NULL END,
        'reason', 'provisional_payment_window_elapsed',
        'source', 'subscription.sweep.v0'
      ),
      now()
    )
    ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;

    v_swept := v_swept || jsonb_build_object(
      'subscriptionId', v_sub.id,
      'orderId', CASE WHEN v_has_order THEN v_order.id ELSE NULL END
    );
    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'contractVersion', 'commerce.v0',
    'sweep', jsonb_build_object('count', v_count, 'swept', v_swept)
  );
END;
$$;


--
-- Name: subscription_sync_offer_policy_from_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_sync_offer_policy_from_order() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_offer text := NEW.metadata#>>'{quoteSnapshot,quote,context,pricingPolicy,offerPolicyVersion}';
  v_engine text := NEW.metadata#>>'{quoteSnapshot,quote,context,pricingPolicy,promotionEngineVersion}';
BEGIN
  -- Legacy/no-capability acquisition is frozen explicitly as v1. A later
  -- renewal can never use unrelated order metadata to upgrade the subscription.
  v_offer := COALESCE(v_offer, 'commerce.offer-policy.v1');
  v_engine := COALESCE(v_engine, 'promotion-engine.v1');
  IF NOT ((v_offer = 'commerce.offer-policy.v1' AND v_engine = 'promotion-engine.v1') OR
          (v_offer = 'commerce.offer-policy.v2' AND v_engine = 'promotion-engine.v2')) THEN
    RAISE EXCEPTION 'subscription_offer_policy_pair_invalid' USING ERRCODE = '23514';
  END IF;

  IF NEW.subscription_id IS NOT NULL THEN
    UPDATE public.subscriptions
       SET offer_policy_version = v_offer,
           promotion_engine_version = v_engine,
           offer_policy_assignment_state = 'assigned_acquisition'
     WHERE id = NEW.subscription_id
       AND offer_policy_assignment_state = 'pending_acquisition';
  END IF;
  IF NEW.subscription_cycle_id IS NOT NULL THEN
    UPDATE public.subscription_cycles
       SET offer_policy_version = v_offer,
           promotion_engine_version = v_engine,
           offer_policy_assignment_state = 'assigned_acquisition'
     WHERE id = NEW.subscription_cycle_id
       AND offer_policy_assignment_state = 'pending_acquisition';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: subscription_terminalize_unpaid_cycle_artifacts(uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_terminalize_unpaid_cycle_artifacts(p_subscription_id uuid, p_cycle_id uuid, p_requested_at timestamp with time zone, p_reason text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
      FROM public.commerce_payment_intents payment_intent
      JOIN public.commerce_payment_attempts payment_attempt
        ON payment_attempt.payment_intent_id = payment_intent.id
     WHERE payment_intent.subscription_id = p_subscription_id
       AND payment_intent.target_kind = 'subscription_cycle'
       AND payment_attempt.status IN (
         'created', 'sent_to_provider', 'requires_action', 'processing'
       )
  ) THEN
    RAISE EXCEPTION 'subscription_resume_payment_attempt_in_flight' USING ERRCODE = '55006';
  END IF;

  UPDATE public.commerce_payment_intents payment_intent
     SET status = 'cancelled',
         failure_reason = COALESCE(payment_intent.failure_reason, p_reason),
         updated_at = p_requested_at
   WHERE payment_intent.subscription_id = p_subscription_id
     AND payment_intent.subscription_cycle_id = p_cycle_id
     AND payment_intent.target_kind = 'subscription_cycle'
     AND payment_intent.status IN ('created', 'processing', 'failed');

  UPDATE public.commerce_orders order_row
     SET status = 'cancelled',
         metadata = order_row.metadata || jsonb_build_object(
           'paymentStatus', 'cancelled',
           'cancelReason', p_reason,
           'source', 'subscription.resume_after_expired_dunning'
         ),
         updated_at = p_requested_at
   WHERE order_row.subscription_id = p_subscription_id
     AND order_row.subscription_cycle_id = p_cycle_id
     AND order_row.mode = 'subscription_cycle'
     AND order_row.status = 'pending_payment'
     AND NOT EXISTS (
       SELECT 1
         FROM public.commerce_payment_intents payment_intent
         LEFT JOIN public.commerce_payment_attempts payment_attempt
           ON payment_attempt.payment_intent_id = payment_intent.id
        WHERE payment_intent.order_id = order_row.id
          AND (
            payment_intent.status IN ('succeeded', 'refunded', 'partially_refunded', 'disputed')
            OR payment_attempt.status = 'succeeded'
          )
     );

  UPDATE public.subscription_cycles cycle
     SET status = 'skipped',
         next_retry_at = NULL,
         renewal_quarantined_until = NULL,
         failure_reason = COALESCE(cycle.failure_reason, p_reason),
         updated_at = p_requested_at
   WHERE cycle.id = p_cycle_id
     AND cycle.subscription_id = p_subscription_id
     AND cycle.status IN ('payment_pending', 'retry_scheduled', 'payment_failed');
END;
$$;


--
-- Name: FUNCTION subscription_terminalize_unpaid_cycle_artifacts(p_subscription_id uuid, p_cycle_id uuid, p_requested_at timestamp with time zone, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_terminalize_unpaid_cycle_artifacts(p_subscription_id uuid, p_cycle_id uuid, p_requested_at timestamp with time zone, p_reason text) IS 'Terminalizes one uncollected renewal cycle with its pending order and non-terminal intent, refusing while a provider attempt is in flight. The cycle becomes skipped so the subscription re-enters subscription_list_due_for_renewal.';


--
-- Name: subscription_try_schedule_recovery_retry(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_try_schedule_recovery_retry(p_case_id uuid, p_payment_method_ref text, p_requested_at timestamp with time zone DEFAULT now(), p_entry text DEFAULT 'recovery_redeem'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_case_hint record;
  v_case public.subscription_dunning_cases%ROWTYPE;
  v_subscription_status text;
  v_method public.commerce_payment_method_refs%ROWTYPE;
  v_admitted boolean;
  v_scheduled boolean := false;
BEGIN
  IF p_case_id IS NULL
    OR p_payment_method_ref IS NULL OR btrim(p_payment_method_ref) = ''
    OR p_requested_at IS NULL
    OR p_entry IS NULL OR p_entry NOT IN ('recovery_redeem', 'method_ref_webhook')
  THEN
    RAISE EXCEPTION 'subscription_recovery_retry_invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT dunning_case.subscription_id, dunning_case.cycle_id
    INTO v_case_hint
    FROM public.subscription_dunning_cases dunning_case
   WHERE dunning_case.id = p_case_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('scheduled', false, 'reason', 'case_not_found');
  END IF;

  -- Aggregate root before any dependent row, as everywhere else in this domain.
  SELECT subscription.status
    INTO v_subscription_status
    FROM public.subscriptions subscription
   WHERE subscription.id = v_case_hint.subscription_id
   FOR UPDATE;

  SELECT *
    INTO v_case
    FROM public.subscription_dunning_cases dunning_case
   WHERE dunning_case.id = p_case_id
   FOR UPDATE;

  IF NOT FOUND
    OR v_case.status <> 'open'
    OR v_subscription_status <> 'active'
  THEN
    RETURN jsonb_build_object('scheduled', false, 'reason', 'recovery_not_ready');
  END IF;

  -- The durable evidence both entries require. A row here means a webhook wrote
  -- it; nothing else can. Read, never asserted by the caller.
  SELECT *
    INTO v_method
    FROM public.commerce_payment_method_refs method_ref
   WHERE method_ref.subscription_id = v_case.subscription_id
     AND method_ref.provider_method_ref = btrim(p_payment_method_ref)
     AND method_ref.status = 'active'
     AND method_ref.active = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('scheduled', false, 'reason', 'recovery_not_ready');
  END IF;

  v_admitted := CASE p_entry
    -- The redeem handshake: the customer consumed the repair token AND the
    -- webhook bound the resulting method to this exact case.
    WHEN 'recovery_redeem' THEN
      COALESCE(v_method.consent_snapshot->>'recoveryCaseId' = v_case.id::text, false)
      AND EXISTS (
        SELECT 1
          FROM public.subscription_payment_recovery_tokens token
         WHERE token.case_id = v_case.id
           AND token.purpose = 'repair_payment'
           AND token.used_at IS NOT NULL
           AND token.revoked_at IS NULL
      )
    -- The method-update entry: a usable method the rail confirmed AFTER the
    -- failure that opened this case. A registration and a rotation both qualify
    -- — a reissued credential is a genuinely fresh chance — and a row older than
    -- the failure is the method that failed.
    WHEN 'method_ref_webhook' THEN
      v_method.updated_at >= v_case.opened_at
    ELSE false
  END;

  IF NOT v_admitted THEN
    RETURN jsonb_build_object('scheduled', false, 'reason', 'recovery_not_ready');
  END IF;

  -- Mirror convergence. The redeem rail already wrote these two columns before
  -- it called here, so IS DISTINCT FROM makes this an exact no-op for it; the
  -- account rail never wrote them at all, which is the drift being closed. The
  -- subscription row is already held under the lock taken above.
  UPDATE public.subscriptions subscription
     SET payment_method_ref = v_method.provider_method_ref,
         payment_method_kind = v_method.method_kind,
         updated_at = now()
   WHERE subscription.id = v_case.subscription_id
     AND (subscription.payment_method_ref IS DISTINCT FROM v_method.provider_method_ref
       OR subscription.payment_method_kind IS DISTINCT FROM v_method.method_kind);

  UPDATE public.subscription_cycles cycle
     SET next_retry_at = LEAST(COALESCE(cycle.next_retry_at, now()), now()),
         updated_at = now()
   WHERE cycle.id = v_case.cycle_id
     AND cycle.subscription_id = v_case.subscription_id
     AND cycle.status = 'retry_scheduled';
  v_scheduled := FOUND;

  IF v_scheduled THEN
    INSERT INTO public.subscription_events (
      subscription_id, cycle_id, event_type, idempotency_key, payload, occurred_at
    )
    VALUES (
      v_case.subscription_id,
      v_case.cycle_id,
      'subscription.retry_scheduled',
      'payment-recovery-retry:' || v_case.id::text,
      jsonb_build_object(
        'caseId', v_case.id,
        'source', 'subscription.payment_recovery',
        'reason', 'payment_method_recovered',
        'entry', p_entry
      ),
      p_requested_at
    )
    ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING;
  END IF;

  RETURN jsonb_build_object(
    'scheduled', v_scheduled,
    'entry', p_entry,
    'reason', CASE WHEN v_scheduled THEN 'ready' ELSE 'cycle_not_retryable' END
  );
END;
$$;


--
-- Name: FUNCTION subscription_try_schedule_recovery_retry(p_case_id uuid, p_payment_method_ref text, p_requested_at timestamp with time zone, p_entry text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.subscription_try_schedule_recovery_retry(p_case_id uuid, p_payment_method_ref text, p_requested_at timestamp with time zone, p_entry text) IS 'Makes an already-scheduled dunning retry immediately due once a usable payment method is durable for the case. Two entry conditions, one rail: recovery_redeem (consumed repair token + case-bound method ref) and method_ref_webhook (a method-ref row the rail confirmed at or after the failure that opened the case). Both read the stored row; neither trusts the caller. Also converges subscriptions.payment_method_ref/_kind onto that row.';


--
-- Name: sync_first_subscription_offer_policy_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_first_subscription_offer_policy_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.promotion_engine_version <> 'promotion-engine.v1' THEN
    RETURN NEW;
  END IF;

  -- Fresh databases load the canonical legacy offer from the operator seed after
  -- migrations have run. Create the v2 twin on that INSERT as well as keeping an
  -- existing twin synchronized on UPDATE. An existing link remains authoritative
  -- if an administrator later renames the legacy promotion.
  IF NEW.name <> 'First Subscription 50%'
     AND NOT EXISTS (
       SELECT 1 FROM public.promotions mirror WHERE mirror.v2_mirror_of = NEW.id
     ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.promotions (
    code, name, trigger_type, discount_type, discount_value,
    applies_to_kind, applies_to_payload, stacking_rule, eligibility,
    valid_from, valid_to, redemption_limit_global,
    redemption_limit_per_customer, region_availability, status,
    promotion_engine_version, benefit_lane, benefit_kind,
    benefit_value_bps, benefit_value_minor, v2_mirror_of
  ) VALUES (
    NULL, NEW.name, 'automatic', 'percentage', 50,
    NEW.applies_to_kind, NEW.applies_to_payload, NEW.stacking_rule, NEW.eligibility,
    NEW.valid_from, NEW.valid_to, NEW.redemption_limit_global,
    NEW.redemption_limit_per_customer, NEW.region_availability,
    -- New mirrors are database-dark even when the legacy row is active. The
    -- previous application version cannot distinguish v1 from v2 rows.
    'paused',
    'promotion-engine.v2', 'product', 'target_percentage', 5000, NULL, NEW.id
  )
  ON CONFLICT (v2_mirror_of) WHERE v2_mirror_of IS NOT NULL DO UPDATE SET
    name = EXCLUDED.name,
    applies_to_kind = EXCLUDED.applies_to_kind,
    applies_to_payload = EXCLUDED.applies_to_payload,
    stacking_rule = EXCLUDED.stacking_rule,
    eligibility = EXCLUDED.eligibility,
    valid_from = EXCLUDED.valid_from,
    valid_to = EXCLUDED.valid_to,
    redemption_limit_global = EXCLUDED.redemption_limit_global,
    redemption_limit_per_customer = EXCLUDED.redemption_limit_per_customer,
    region_availability = EXCLUDED.region_availability,
    -- `status = active` on the mirror is the explicit operator activation
    -- latch. Preserve it only while the linked legacy definition remains the
    -- exact canonical shape and active. Once closed, a later legacy edit cannot
    -- silently reactivate v2.
    status = CASE
      WHEN promotions.status = 'active'
        AND NEW.trigger_type = 'automatic'
        AND NEW.discount_type = 'percentage'
        AND NEW.discount_value = 44.404
        AND NEW.applies_to_kind = 'order_total'
        AND NEW.applies_to_payload = '{"cart_mode":"subscription"}'::jsonb
        AND NEW.stacking_rule = 'exclusive'
        AND NEW.eligibility = '{"first_subscription_purchase":true}'::jsonb
        AND NEW.status = 'active'
        THEN 'active'
      ELSE 'paused'
    END,
    promotion_engine_version = 'promotion-engine.v2',
    benefit_lane = 'product',
    benefit_kind = 'target_percentage',
    benefit_value_bps = 5000,
    benefit_value_minor = NULL;
  RETURN NEW;
END;
$$;


--
-- Name: sync_legacy_promotion_benefit_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_legacy_promotion_benefit_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF NEW.trigger_type='coupon_code'
     AND NEW.promotion_engine_version='promotion-engine.v1' THEN
    NEW.benefit_lane := CASE WHEN NEW.discount_type='free_shipping' THEN 'shipping' ELSE 'product' END;
    NEW.benefit_kind := CASE WHEN NEW.discount_type='percentage' THEN 'percentage'
      WHEN NEW.discount_type='fixed_amount' THEN 'fixed_amount' ELSE 'free_shipping' END;
    NEW.benefit_value_bps := CASE
      WHEN NEW.discount_type='percentage'
        AND NEW.discount_value <= 90071992547409.91
        AND NEW.discount_value*100 = trunc(NEW.discount_value*100)
        THEN NEW.discount_value*100
      ELSE NULL END;
    NEW.benefit_value_minor := CASE
      WHEN NEW.discount_type='fixed_amount'
        AND NEW.discount_value <= 9007199254740991
        AND NEW.discount_value = trunc(NEW.discount_value)
        THEN NEW.discount_value
      ELSE NULL END;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_legacy_promotion_code_projection(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_legacy_promotion_code_projection() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_subscription_initial boolean;
  v_one_time boolean;
  v_scopes text[];
  v_minimum_reference_minor integer;
BEGIN
  IF NEW.trigger_type='coupon_code'
     AND NEW.promotion_engine_version='promotion-engine.v1' THEN
    v_subscription_initial := lower(COALESCE(NEW.eligibility->>'first_subscription_purchase','')) IN ('true','1');
    v_one_time := lower(COALESCE(NEW.eligibility->>'first_onetime_purchase','')) IN ('true','1');
    v_scopes := CASE WHEN v_subscription_initial OR v_one_time THEN array_remove(ARRAY[
      CASE WHEN v_one_time THEN 'one_time' END,
      CASE WHEN v_subscription_initial THEN 'subscription_initial' END
    ]::text[],NULL) ELSE ARRAY['one_time','subscription_initial']::text[] END;
    v_minimum_reference_minor := CASE
      WHEN COALESCE(NEW.eligibility->>'min_cart_minor','') ~ '^\d{1,9}$'
        THEN (NEW.eligibility->>'min_cart_minor')::integer
      ELSE 0 END;
    UPDATE public.promotion_codes pc SET
      name=NEW.name,
      scopes=v_scopes,
      minimum_reference_minor=v_minimum_reference_minor,
      valid_from=NEW.valid_from,
      valid_to=NEW.valid_to,
      redemption_limit_global=NEW.redemption_limit_global,
      redemption_limit_per_customer=NEW.redemption_limit_per_customer,
      status=NEW.status,
      revision=pc.revision+1,
      updated_at=now()
    FROM public.promotion_code_bindings pcb
    WHERE pcb.promotion_code_id=pc.id AND pcb.promotion_id=NEW.id
      AND (
        pc.name IS DISTINCT FROM NEW.name
        OR pc.scopes IS DISTINCT FROM v_scopes
        OR pc.minimum_reference_minor IS DISTINCT FROM v_minimum_reference_minor
        OR pc.valid_from IS DISTINCT FROM NEW.valid_from
        OR pc.valid_to IS DISTINCT FROM NEW.valid_to
        OR pc.redemption_limit_global IS DISTINCT FROM NEW.redemption_limit_global
        OR pc.redemption_limit_per_customer IS DISTINCT FROM NEW.redemption_limit_per_customer
        OR pc.status IS DISTINCT FROM NEW.status
        OR OLD.discount_type IS DISTINCT FROM NEW.discount_type
        OR OLD.discount_value IS DISTINCT FROM NEW.discount_value
        OR OLD.benefit_lane IS DISTINCT FROM NEW.benefit_lane
        OR OLD.benefit_kind IS DISTINCT FROM NEW.benefit_kind
        OR OLD.benefit_value_bps IS DISTINCT FROM NEW.benefit_value_bps
        OR OLD.benefit_value_minor IS DISTINCT FROM NEW.benefit_value_minor
      );
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: track_calendly_click_by_hash(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.track_calendly_click_by_hash(p_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  UPDATE public.feedback
  SET 
    calendly_clicked_at = COALESCE(calendly_clicked_at, now()),
    updated_at = now()
  WHERE hash = p_hash;
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Feedback not found';
  END IF;

  RETURN 'success';
END;
$$;


--
-- Name: transactional_delivery_read_receipt(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transactional_delivery_read_receipt(p_idempotency_key text) RETURNS SETOF public.transactional_delivery_receipts
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT receipt.*
    FROM public.transactional_delivery_receipts AS receipt
   WHERE receipt.idempotency_key = p_idempotency_key;
$$;


--
-- Name: transactional_delivery_record_accepted(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transactional_delivery_record_accepted(p_idempotency_key text, p_command_fingerprint text, p_delivery_reference text) RETURNS public.transactional_delivery_receipts
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_receipt public.transactional_delivery_receipts%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL
     OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' THEN
    RAISE EXCEPTION 'transactional_delivery_invalid_idempotency_key' USING ERRCODE = '22023';
  END IF;
  IF p_command_fingerprint IS NULL OR p_command_fingerprint !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'transactional_delivery_invalid_command_fingerprint' USING ERRCODE = '22023';
  END IF;
  IF p_delivery_reference IS NULL
     OR p_delivery_reference !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' THEN
    RAISE EXCEPTION 'transactional_delivery_invalid_delivery_reference' USING ERRCODE = '22023';
  END IF;

  LOOP
    SELECT * INTO v_receipt
      FROM public.transactional_delivery_receipts
     WHERE idempotency_key = p_idempotency_key
     FOR UPDATE;

    IF FOUND THEN
      IF v_receipt.command_fingerprint <> p_command_fingerprint THEN
        RAISE EXCEPTION 'transactional_delivery_command_fingerprint_conflict' USING ERRCODE = '22023';
      END IF;
      IF v_receipt.state = 'accepted' THEN
        RETURN v_receipt;
      END IF;

      UPDATE public.transactional_delivery_receipts
         SET state = 'accepted',
             delivery_reference = p_delivery_reference,
             error_code = NULL,
             attempt_count = attempt_count + 1,
             updated_at = now(),
             accepted_at = now()
       WHERE idempotency_key = p_idempotency_key
       RETURNING * INTO v_receipt;
      RETURN v_receipt;
    END IF;

    INSERT INTO public.transactional_delivery_receipts (
      idempotency_key,
      command_fingerprint,
      state,
      delivery_reference,
      attempt_count,
      accepted_at
    ) VALUES (
      p_idempotency_key,
      p_command_fingerprint,
      'accepted',
      p_delivery_reference,
      1,
      now()
    )
    ON CONFLICT (idempotency_key) DO NOTHING
    RETURNING * INTO v_receipt;

    IF FOUND THEN
      RETURN v_receipt;
    END IF;
  END LOOP;
END;
$_$;


--
-- Name: transactional_delivery_record_failed(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transactional_delivery_record_failed(p_idempotency_key text, p_command_fingerprint text, p_error_code text) RETURNS public.transactional_delivery_receipts
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_receipt public.transactional_delivery_receipts%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL
     OR p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,255}$' THEN
    RAISE EXCEPTION 'transactional_delivery_invalid_idempotency_key' USING ERRCODE = '22023';
  END IF;
  IF p_command_fingerprint IS NULL OR p_command_fingerprint !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'transactional_delivery_invalid_command_fingerprint' USING ERRCODE = '22023';
  END IF;
  IF p_error_code IS NULL OR p_error_code !~ '^[a-z][a-z0-9_.-]{0,127}$' THEN
    RAISE EXCEPTION 'transactional_delivery_invalid_error_code' USING ERRCODE = '22023';
  END IF;

  LOOP
    SELECT * INTO v_receipt
      FROM public.transactional_delivery_receipts
     WHERE idempotency_key = p_idempotency_key
     FOR UPDATE;

    IF FOUND THEN
      IF v_receipt.command_fingerprint <> p_command_fingerprint THEN
        RAISE EXCEPTION 'transactional_delivery_command_fingerprint_conflict' USING ERRCODE = '22023';
      END IF;
      IF v_receipt.state = 'accepted' THEN
        RETURN v_receipt;
      END IF;

      UPDATE public.transactional_delivery_receipts
         SET error_code = p_error_code,
             attempt_count = attempt_count + 1,
             updated_at = now(),
             failed_at = now()
       WHERE idempotency_key = p_idempotency_key
       RETURNING * INTO v_receipt;
      RETURN v_receipt;
    END IF;

    INSERT INTO public.transactional_delivery_receipts (
      idempotency_key,
      command_fingerprint,
      state,
      error_code,
      attempt_count,
      failed_at
    ) VALUES (
      p_idempotency_key,
      p_command_fingerprint,
      'failed',
      p_error_code,
      1,
      now()
    )
    ON CONFLICT (idempotency_key) DO NOTHING
    RETURNING * INTO v_receipt;

    IF FOUND THEN
      RETURN v_receipt;
    END IF;
  END LOOP;
END;
$_$;


