    CONSTRAINT mcp_access_tokens_owner_email_check CHECK (((length(btrim(owner_email)) >= 3) AND (length(btrim(owner_email)) <= 320))),
    CONSTRAINT mcp_access_tokens_token_hash_check CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text))
);


