    CONSTRAINT accounting_invoices_document_type_check CHECK ((document_type = ANY (ARRAY['fiscal_receipt'::text, 'b2c_invoice'::text, 'b2b_invoice'::text, 'correction_invoice'::text]))),
    CONSTRAINT accounting_invoices_email_status_check CHECK ((email_status = ANY (ARRAY['not_required'::text, 'pending'::text, 'sent'::text, 'failed'::text]))),
    CONSTRAINT accounting_invoices_ksef_requirement_check CHECK ((ksef_requirement = ANY (ARRAY['required'::text, 'optional'::text, 'not_applicable'::text]))),
    CONSTRAINT accounting_invoices_ksef_status_check CHECK ((ksef_status = ANY (ARRAY['not_submitted'::text, 'pending'::text, 'accepted'::text, 'rejected'::text, 'not_required'::text]))),
    CONSTRAINT accounting_invoices_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'issue_requested'::text, 'blocked'::text, 'issued'::text, 'ksef_pending'::text, 'accepted'::text, 'rejected'::text, 'correction_requested'::text, 'corrected'::text, 'voided'::text]))),
    CONSTRAINT accounting_invoices_total_gross_cents_check CHECK ((total_gross_cents >= 0)),
    CONSTRAINT accounting_invoices_total_net_cents_check CHECK ((total_net_cents >= 0))
);


