CREATE TABLE public.catalog_product_document_revisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    revision_no integer NOT NULL,
    schema_id text NOT NULL,
    document_ref text NOT NULL,
    source_ref text NOT NULL,
    document_payload jsonb NOT NULL,
    digest text NOT NULL,
    provenance jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT catalog_product_document_revisions_digest_check CHECK ((digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT catalog_product_document_revisions_document_ref_check CHECK ((btrim(document_ref) <> ''::text)),
    CONSTRAINT catalog_product_document_revisions_revision_no_check CHECK ((revision_no > 0)),
    CONSTRAINT catalog_product_document_revisions_schema_id_check CHECK ((btrim(schema_id) <> ''::text)),
    CONSTRAINT catalog_product_document_revisions_source_ref_check CHECK ((btrim(source_ref) <> ''::text))
);


--
-- Name: catalog_products; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalog_products (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    slug text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    name text NOT NULL,
    description text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    ingredients text[] DEFAULT ARRAY[]::text[] NOT NULL,
    allergens text[] DEFAULT ARRAY[]::text[] NOT NULL,
    marketing_content jsonb DEFAULT '{}'::jsonb NOT NULL,
    primary_sku_id uuid,
    current_document_revision_id uuid,
    CONSTRAINT catalog_products_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'archived'::text])))
);


--
-- Name: COLUMN catalog_products.ingredients; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_products.ingredients IS 'Free-text recipe ingredients (label-printed). Snapshotted into order_line.variant_snapshot at sale time.';


--
-- Name: COLUMN catalog_products.allergens; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_products.allergens IS 'Free-text allergens for FEDIAF labeling. Filterable via clients.preferences once registry lands.';


--
-- Name: COLUMN catalog_products.marketing_content; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_products.marketing_content IS 'Hero image url, pet-portrait, claim pills — front-of-house copy.';


--
-- Name: catalog_sku_eans; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalog_sku_eans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    catalog_sku_id uuid NOT NULL,
    sku text NOT NULL,
    ean text NOT NULL,
    kind text DEFAULT 'unit'::text NOT NULL,
    label_variant text,
    quantity integer DEFAULT 1 NOT NULL,
    is_primary boolean DEFAULT false NOT NULL,
    source text DEFAULT 'local'::text NOT NULL,
    omnipack_synced_at timestamp with time zone,
    omnipack_seen_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT catalog_sku_eans_kind_check CHECK ((kind = ANY (ARRAY['unit'::text, 'collective'::text]))),
    CONSTRAINT catalog_sku_eans_kind_quantity_consistent CHECK (((kind = 'collective'::text) = (quantity > 1))),
    CONSTRAINT catalog_sku_eans_label_variant_check CHECK (((label_variant IS NULL) OR (label_variant = ANY (ARRAY['pl'::text, 'eng'::text])))),
    CONSTRAINT catalog_sku_eans_quantity_check CHECK ((quantity > 0)),
    CONSTRAINT catalog_sku_eans_source_check CHECK ((source = ANY (ARRAY['local'::text, 'omnipack'::text])))
);


--
-- Name: TABLE catalog_sku_eans; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.catalog_sku_eans IS 'EAN source of truth (packs): one catalog SKU maps to many EANs (PL can / ENG can / collective carton). Batches (lot+expiry) live in inventory_lots, not here.';


--
-- Name: catalog_skus; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.catalog_skus (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sku text NOT NULL,
    title text NOT NULL,
    pet_type text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    net_weight_g integer NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    format_code text,
    unit_form_code text,
    gtin text,
    kcal_per_unit numeric NOT NULL,
    feeding_grams_per_unit integer,
    is_addon boolean DEFAULT false NOT NULL,
    sellable_standalone boolean DEFAULT true NOT NULL,
    sellable_in_subscription boolean DEFAULT true NOT NULL,
    requires_pet_profile boolean DEFAULT false NOT NULL,
    min_order_qty integer DEFAULT 1 NOT NULL,
    asset_ref text,
    CONSTRAINT catalog_skus_asset_ref_nonempty_check CHECK (((asset_ref IS NULL) OR (btrim(asset_ref) <> ''::text))),
    CONSTRAINT catalog_skus_min_order_qty_check CHECK ((min_order_qty > 0)),
    CONSTRAINT catalog_skus_net_weight_g_check CHECK (((net_weight_g IS NULL) OR (net_weight_g > 0))),
    CONSTRAINT catalog_skus_pet_type_check CHECK ((pet_type = ANY (ARRAY['dog'::text, 'cat'::text, 'other'::text]))),
    CONSTRAINT catalog_skus_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'archived'::text])))
);


--
-- Name: COLUMN catalog_skus.format_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_skus.format_code IS 'Variant axis: physical packaging (registry: variant_formats). v1: can.';


--
-- Name: COLUMN catalog_skus.unit_form_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_skus.unit_form_code IS 'Variant axis: unit form (registry: variant_unit_forms). v1: can.';


--
-- Name: COLUMN catalog_skus.gtin; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_skus.gtin IS 'Dormant. The authoritative per-SKU EAN set lives in public.catalog_sku_eans (packs). Populate this only if a read path needs the single primary unit EAN.';


--
-- Name: COLUMN catalog_skus.kcal_per_unit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_skus.kcal_per_unit IS 'Total kilocalories per purchasable unit. Required for feeding_days size_constraint (W11+). Currently nullable to allow incremental rollout; promoted to NOT NULL in W1.1 follow-up.';


--
-- Name: COLUMN catalog_skus.feeding_grams_per_unit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.catalog_skus.feeding_grams_per_unit IS 'Grams of food per purchasable unit. Equals net_weight_g for cans but split out for variants where one unit_form does not map 1:1 to a single net_weight (future formats).';


--
-- Name: channel_order_ingests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.channel_order_ingests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    channel_id uuid NOT NULL,
    external_order_ref text NOT NULL,
    external_order_revision text,
    provider_event_id text NOT NULL,
    order_id uuid,
    client_id uuid,
    shipping_address_id uuid,
    payment_intent_id uuid,
    status text DEFAULT 'received'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    last_error text,
    normalized jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT channel_order_ingests_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT channel_order_ingests_external_order_ref_check CHECK (((btrim(external_order_ref) <> ''::text) AND (char_length(external_order_ref) <= 128))),
    CONSTRAINT channel_order_ingests_external_order_revision_check CHECK (((external_order_revision IS NULL) OR (char_length(external_order_revision) <= 64))),
    CONSTRAINT channel_order_ingests_last_error_check CHECK (((last_error IS NULL) OR (char_length(last_error) <= 2000))),
    CONSTRAINT channel_order_ingests_provider_event_id_check CHECK (((btrim(provider_event_id) <> ''::text) AND (char_length(provider_event_id) <= 200))),
    CONSTRAINT channel_order_ingests_status_check CHECK ((status = ANY (ARRAY['received'::text, 'buyer_ready'::text, 'order_created'::text, 'reserved'::text, 'settled'::text, 'done'::text, 'blocked_stock'::text, 'quarantined'::text, 'failed'::text])))
);


--
-- Name: TABLE channel_order_ingests; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.channel_order_ingests IS 'One row per external order per channel: the ingest saga resume point, carrying the ids each step minted so a retry reuses them instead of minting a second of anything.';


--
-- Name: client_absorption_policy; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_absorption_policy (
    table_name text NOT NULL,
    disposition text NOT NULL,
    note text,
    CONSTRAINT client_absorption_policy_disposition_check CHECK ((disposition = ANY (ARRAY['block'::text, 'carry'::text, 'retain'::text]))),
    CONSTRAINT client_absorption_policy_table_name_check CHECK ((btrim(table_name) <> ''::text))
);


--
-- Name: TABLE client_absorption_policy; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.client_absorption_policy IS 'Disposition of every table referencing public.clients when a lead is absorbed into a customer: block refuses the absorption while the lead has rows there, carry moves those rows to the customer, retain leaves them on the archived record because they are that record own history. customer_support_absorb_lead_v1 reads the live foreign-key set from pg_constraint and refuses any referencing table missing from this table, so a new table blocks until it is classified here.';


--
-- Name: client_consents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_consents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    consent_type text NOT NULL,
    granted boolean DEFAULT false NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    source text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT client_consents_consent_type_check CHECK ((consent_type = ANY (ARRAY['gdpr'::text, 'marketing'::text, 'verification'::text, 'terms'::text, 'profiling'::text])))
);


--
-- Name: client_source_links; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.client_source_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    source_table text NOT NULL,
    source_id uuid,
    source_key text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT client_source_links_check CHECK (((source_id IS NOT NULL) OR (source_key IS NOT NULL))),
    CONSTRAINT client_source_links_source_table_check CHECK ((source_table = ANY (ARRAY['testers'::text, 'waitlist'::text, 'manual_import'::text])))
);


--
-- Name: clients; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.clients (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    email text NOT NULL,
    first_name text,
    last_name text,
    phone text,
    country text,
    lifecycle_stage text DEFAULT 'lead'::text NOT NULL,
    acquisition_source text,
    external_ref text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    preferences jsonb DEFAULT '{}'::jsonb NOT NULL,
    auth_user_id uuid,
    identity_kind text DEFAULT 'customer'::text NOT NULL,
    marketing_contact_id uuid,
    CONSTRAINT clients_identity_kind_check CHECK ((identity_kind = ANY (ARRAY['customer'::text, 'marketing_lead'::text]))),
    CONSTRAINT clients_marketing_contact_shape_check CHECK ((((identity_kind = 'customer'::text) AND (marketing_contact_id IS NULL)) OR ((identity_kind = 'marketing_lead'::text) AND (marketing_contact_id IS NOT NULL))))
);


--
-- Name: COLUMN clients.preferences; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.preferences IS 'Per-customer preference flags + dietary filters: {no_chicken: true, eco_pack_only: true, delivery_window: ''evening''}. Storefront catalog filter reads this jsonb (no_chicken excludes variants whose snapshot.ingredients contains chicken). Per plan §17.4 this is NOT the place for system feature flags — those live in environment variables.';


--
-- Name: COLUMN clients.auth_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.auth_user_id IS 'Nullable link to the Supabase auth identity that owns this client row. NULL = no customer login yet (admin-created / imported clients). Populated by linkClientAuthUser() during passwordless customer provisioning. Uniqueness is enforced by the partial unique index uq_clients_auth_user_id (created below) plus idempotent linking in linkClientAuthUser().';


--
-- Name: COLUMN clients.identity_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.identity_kind IS 'customer participates in the real customer email namespace; marketing_lead is a compatibility subject for early personalization and stores only a reserved .invalid address.';


--
-- Name: COLUMN clients.marketing_contact_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.clients.marketing_contact_id IS 'For identity_kind=marketing_lead, the communication contact that owns the real marketing endpoint. Customer rows use communication_contact_links instead.';


--
-- Name: commerce_cart_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_cart_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cart_id uuid NOT NULL,
    sku_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    quantity integer NOT NULL,
    unit_price_cents integer,
    currency text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    mode_at_line text DEFAULT 'one_time'::text NOT NULL,
    line_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT commerce_cart_items_currency_check CHECK (((currency IS NULL) OR (char_length(currency) = 3))),
    CONSTRAINT commerce_cart_items_mode_at_line_check CHECK ((mode_at_line = ANY (ARRAY['one_time'::text, 'subscription'::text]))),
    CONSTRAINT commerce_cart_items_quantity_check CHECK ((quantity > 0)),
    CONSTRAINT commerce_cart_items_unit_price_cents_check CHECK (((unit_price_cents IS NULL) OR (unit_price_cents >= 0)))
);


--
-- Name: COLUMN commerce_cart_items.mode_at_line; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_cart_items.mode_at_line IS 'Pricing band for this specific line. Allows ad-hoc one-time add-ons inside a subscription cart (food lines mode_at_line=subscription, addon mode_at_line=one_time). Cart-level cart.mode=''one_time'' invariant: every line must also be ''one_time'' (test cart_mode_consistency.test.ts).';


--
-- Name: commerce_carts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_carts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    currency text DEFAULT 'PLN'::text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    region_code text DEFAULT 'PL'::text NOT NULL,
    mode text DEFAULT 'one_time'::text NOT NULL,
    size_constraint jsonb,
    cadence_days integer,
    bundle_intent_label text,
    pet_id uuid,
    applied_promo_codes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    CONSTRAINT commerce_carts_cadence_days_check CHECK (((cadence_days IS NULL) OR (cadence_days > 0))),
    CONSTRAINT commerce_carts_currency_check CHECK ((char_length(currency) = 3)),
    CONSTRAINT commerce_carts_mode_check CHECK ((mode = ANY (ARRAY['one_time'::text, 'subscription'::text]))),
    CONSTRAINT commerce_carts_region_code_check CHECK (((char_length(region_code) >= 2) AND (char_length(region_code) <= 3))),
    CONSTRAINT commerce_carts_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'checkout'::text, 'converted'::text, 'abandoned'::text, 'expired'::text])))
);


--
-- Name: COLUMN commerce_carts.mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_carts.mode IS 'Primary intent of the cart. Drives size_constraint anchor and cadence_days resolution. Per-line pricing band lives on commerce_cart_items.mode_at_line (mixed-mode carts are allowed for ad-hoc add-ons in a subscription cart).';


--
-- Name: COLUMN commerce_carts.size_constraint; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_carts.size_constraint IS 'Polymorphic bundle/subscription size constraint: { "kind": "unit_count"|"total_weight_g"|"feeding_days", "value": int, "pet_id": uuid?, "daily_kcal_override": int? }. v1 walidator implements unit_count; total_weight_g and feeding_days return not_yet_supported until W11+ (per §8.5).';


--
-- Name: COLUMN commerce_carts.bundle_intent_label; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_carts.bundle_intent_label IS 'Display-only marketing label ("Bundle 14", "Mix-21"). Never queried by walidator/pricing — the size_constraint is the canonical truth.';


--
-- Name: commerce_checkout_recovery_tokens; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_checkout_recovery_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    client_id uuid NOT NULL,
    token_hash text NOT NULL,
    purpose text DEFAULT 'complete_checkout'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    used_at timestamp with time zone,
    revoked_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT commerce_checkout_recovery_tokens_purpose_check CHECK ((purpose = 'complete_checkout'::text))
);


--
-- Name: commerce_checkout_resume_drafts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_checkout_resume_drafts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    token_hash text NOT NULL,
    idempotency_key_hash text,
    client_id uuid,
    configurator_intent_id uuid,
    last_section_id text NOT NULL,
    draft_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    redacted_fields text[] DEFAULT '{}'::text[] NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT commerce_checkout_resume_drafts_last_section_id_check CHECK ((last_section_id = ANY (ARRAY['start'::text, 'pet_profile'::text, 'product_selection'::text, 'cadence'::text, 'account'::text, 'shipping'::text, 'billing'::text, 'payment'::text, 'review'::text]))),
    CONSTRAINT commerce_checkout_resume_future_expiry CHECK ((expires_at > created_at)),
    CONSTRAINT commerce_checkout_resume_idempotency_hash_format CHECK (((idempotency_key_hash IS NULL) OR (idempotency_key_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT commerce_checkout_resume_metadata_object CHECK ((jsonb_typeof(metadata) = 'object'::text)),
    CONSTRAINT commerce_checkout_resume_no_top_level_pii CHECK ((NOT (draft_state ?| ARRAY['name'::text, 'firstName'::text, 'lastName'::text, 'email'::text, 'phone'::text, 'street'::text, 'postalCode'::text, 'city'::text, 'address'::text, 'shippingAddress'::text, 'billingAddress'::text, 'deliveryNotes'::text, 'courierInstructions'::text, 'providerPayload'::text, 'pspReference'::text, 'paymentProvider'::text, 'blik'::text, 'card'::text, 'rawFormPayload'::text]))),
    CONSTRAINT commerce_checkout_resume_redacted_fields_known CHECK ((redacted_fields <@ ARRAY['pet_identity'::text, 'contact'::text, 'shipping_address'::text, 'billing_address'::text, 'delivery_notes'::text, 'courier_instructions'::text, 'payment_provider'::text, 'payment_secret'::text, 'raw_form_payload'::text])),
    CONSTRAINT commerce_checkout_resume_state_object CHECK ((jsonb_typeof(draft_state) = 'object'::text)),
    CONSTRAINT commerce_checkout_resume_token_hash_format CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: TABLE commerce_checkout_resume_drafts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.commerce_checkout_resume_drafts IS 'Hidden server-side checkout resume drafts. Stores token_hash only; never raw URL tokens, raw forms, PSP/card/BLIK data, addresses, or courier notes.';


--
-- Name: COLUMN commerce_checkout_resume_drafts.token_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_checkout_resume_drafts.token_hash IS 'SHA-256 hash of the opaque checkout resume URL token.';


--
-- Name: COLUMN commerce_checkout_resume_drafts.draft_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_checkout_resume_drafts.draft_state IS 'Sanitized navigation and non-identifying selection state validated by commerce.checkout_resume.v1.';


--
-- Name: commerce_checkout_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_checkout_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    cart_id uuid,
    client_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    provider text NOT NULL,
    provider_session_id text,
    status text DEFAULT 'created'::text NOT NULL,
    success_url text,
    cancel_url text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT commerce_checkout_sessions_status_check CHECK ((status = ANY (ARRAY['created'::text, 'pending'::text, 'completed'::text, 'expired'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: commerce_fulfillment_operations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_fulfillment_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    fulfillment_order_id uuid NOT NULL,
    order_id uuid NOT NULL,
    operation_type text NOT NULL,
    idempotency_key text NOT NULL,
    actor_user_id uuid,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT commerce_fulfillment_operations_operation_type_check CHECK ((operation_type = ANY (ARRAY['created'::text, 'packed'::text, 'provider_attempt_recorded'::text, 'label_created'::text, 'handed_over'::text, 'tracking_event_recorded'::text, 'cancelled'::text])))
);


--
-- Name: commerce_fulfillment_order_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_fulfillment_order_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    fulfillment_order_id uuid NOT NULL,
    order_id uuid NOT NULL,
    order_item_id uuid NOT NULL,
    sku_id uuid NOT NULL,
    sku text NOT NULL,
    title text,
