    inventory_reservation_ids uuid[] DEFAULT ARRAY[]::uuid[] NOT NULL,
    product_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT commerce_fulfillment_order_lines_quantity_check CHECK ((quantity > 0))
);


--
-- Name: commerce_fulfillment_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_fulfillment_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    client_id uuid,
    shipping_address_id uuid NOT NULL,
    create_idempotency_key text NOT NULL,
    status text DEFAULT 'created'::text NOT NULL,
    provider_kind text,
    shipping_address_snapshot jsonb NOT NULL,
    handed_over_at timestamp with time zone,
    delivered_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    sequence_no smallint DEFAULT 0 NOT NULL,
    replaces_fulfillment_order_id uuid,
    replacement_reason text,
    CONSTRAINT commerce_fulfillment_orders_status_check CHECK ((status = ANY (ARRAY['created'::text, 'packed'::text, 'label_pending'::text, 'label_created'::text, 'handed_over'::text, 'in_transit'::text, 'delivered'::text, 'exception'::text, 'cancelled'::text])))
);


--
-- Name: COLUMN commerce_fulfillment_orders.sequence_no; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_fulfillment_orders.sequence_no IS 'Ordinal of this fulfilment within its order. 0 is the original parcel; a replacement takes the next free ordinal. The provider order number is derived from it; the customer never sees it.';


--
-- Name: COLUMN commerce_fulfillment_orders.replaces_fulfillment_order_id; Type: COMMENT; Schema: public; Owner: -
--

