);


--
-- Name: commerce_fulfillment_provider_command_transitions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_fulfillment_provider_command_transitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    command_id uuid NOT NULL,
    from_status text,
    to_status text NOT NULL,
    reason_code text NOT NULL,
    command_version bigint NOT NULL,
    attempt_count integer NOT NULL,
    claim_token uuid,
    claim_generation bigint,
    provider_attempt_id uuid,
    proof_kind text,
    proof_fingerprint text,
    proof_observed_at timestamp with time zone,
    proof_source text,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT commerce_fulfillment_provider_command_t_proof_fingerprint_check CHECK ((proof_fingerprint ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT commerce_fulfillment_provider_command_tra_command_version_check CHECK ((command_version > 0)),
    CONSTRAINT commerce_fulfillment_provider_command_trans_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT commerce_fulfillment_provider_command_transi_proof_source_check CHECK ((proof_source = ANY (ARRAY['provider_lookup'::text, 'provider_webhook'::text, 'operator_verified'::text, 'provider_response'::text, 'legacy_backfill'::text]))),
    CONSTRAINT commerce_fulfillment_provider_command_transiti_proof_kind_check CHECK ((proof_kind = ANY (ARRAY['provider_reference'::text, 'correlation_key'::text, 'provider_idempotency_key'::text, 'authoritative_absence'::text, 'definitive_provider_rejection'::text]))),
    CONSTRAINT commerce_fulfillment_provider_command_transitio_to_status_check CHECK ((to_status = ANY (ARRAY['queued'::text, 'claimed'::text, 'submitting'::text, 'accepted'::text, 'confirmed'::text, 'retry_wait'::text, 'uncertain'::text, 'manual_review'::text, 'terminal_rejected'::text, 'cancelled'::text]))),
    CONSTRAINT commerce_fulfillment_provider_command_transitions_check CHECK ((((proof_kind IS NULL) AND (proof_fingerprint IS NULL) AND (proof_observed_at IS NULL) AND (proof_source IS NULL)) OR ((proof_kind IS NOT NULL) AND (proof_fingerprint IS NOT NULL) AND (proof_observed_at IS NOT NULL) AND (proof_source IS NOT NULL)))),
    CONSTRAINT fulfillment_provider_command_transition_reason_check CHECK ((reason_code = ANY (ARRAY['command_enqueued'::text, 'claimed'::text, 'submission_started'::text, 'provider_accepted'::text, 'safe_rejection'::text, 'terminal_rejection'::text, 'write_uncertain'::text, 'lease_expired'::text, 'provider_effect_present'::text, 'authoritative_absence'::text, 'effect_unknown'::text, 'identity_mismatch'::text, 'invalid_contract'::text, 'unsafe_retry'::text, 'operator_cancelled'::text, 'superseded_by_direct_dispatch'::text])))
);


--
