    CONSTRAINT commerce_idempotency_keys_status_check CHECK ((status = ANY (ARRAY['in_progress'::text, 'completed'::text, 'failed'::text])))
);


--
-- Name: commerce_offer_policy_rollout_baselines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_offer_policy_rollout_baselines (
