    expected_count integer NOT NULL,
    expected_fingerprint text NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT commerce_offer_policy_rollout_baseli_expected_fingerprint_check CHECK ((expected_fingerprint ~ '^[0-9a-f]{32}$'::text)),
    CONSTRAINT commerce_offer_policy_rollout_baselines_baseline_key_check CHECK ((baseline_key = 'legacy_frozen.v1'::text)), -- gitleaks:allow -- public schema sentinel, not a credential
    CONSTRAINT commerce_offer_policy_rollout_baselines_expected_count_check CHECK ((expected_count > 0))
);


--
-- Name: commerce_order_feedback; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_order_feedback (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    token text NOT NULL,
    rating integer,
    comment text,
    submitted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    effect_token text,
    effect_rating integer,
    effect_comment text,
    effect_submitted_at timestamp with time zone,
    CONSTRAINT commerce_order_feedback_rating_check CHECK (((rating IS NULL) OR ((rating >= 1) AND (rating <= 5))))
);


--
-- Name: TABLE commerce_order_feedback; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.commerce_order_feedback IS 'Post-delivery review request + customer rating/comment, keyed by an opaque token embedded in the review email link.';


--
-- Name: commerce_order_holds; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_order_holds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    released_at timestamp with time zone,
    created_by uuid,
    released_by uuid,
    status text DEFAULT 'active'::text NOT NULL,
    reason text NOT NULL,
    note text,
    idempotency_key text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT commerce_order_holds_check CHECK ((((status = 'active'::text) AND (released_at IS NULL)) OR ((status = 'released'::text) AND (released_at IS NOT NULL)))),
    CONSTRAINT commerce_order_holds_reason_check CHECK ((reason = ANY (ARRAY['payment_not_succeeded'::text, 'inventory_review'::text, 'risk_review'::text, 'address_review'::text, 'fulfillment_exception'::text, 'manual_support'::text]))),
    CONSTRAINT commerce_order_holds_status_check CHECK ((status = ANY (ARRAY['active'::text, 'released'::text])))
);


--
-- Name: commerce_order_items; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_order_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    sku_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    quantity integer NOT NULL,
    unit_price_cents integer NOT NULL,
    total_cents integer NOT NULL,
    product_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    mode_at_line text DEFAULT 'one_time'::text NOT NULL,
    variant_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    size_constraint_contribution numeric,
    vat_rate_bps integer DEFAULT 800 NOT NULL,
    discount_allocated_cents integer NOT NULL,
    effective_total_cents integer NOT NULL,
    effective_net_cents integer NOT NULL,
    allocation_ordinal integer NOT NULL,
    CONSTRAINT commerce_order_items_allocation_ordinal_positive CHECK (((allocation_ordinal IS NOT NULL) AND (allocation_ordinal > 0))),
    CONSTRAINT commerce_order_items_canonical_money_gross_check CHECK ((((effective_total_cents)::bigint + (discount_allocated_cents)::bigint) = (total_cents)::bigint)),
    CONSTRAINT commerce_order_items_canonical_money_net_check CHECK ((effective_net_cents = (round((((effective_total_cents)::numeric * (10000)::numeric) / ((10000 + vat_rate_bps))::numeric)))::integer)),
    CONSTRAINT commerce_order_items_canonical_money_nonnegative_check CHECK (((discount_allocated_cents >= 0) AND (effective_total_cents >= 0) AND (effective_net_cents >= 0))),
    CONSTRAINT commerce_order_items_mode_at_line_check CHECK ((mode_at_line = ANY (ARRAY['one_time'::text, 'subscription'::text]))),
    CONSTRAINT commerce_order_items_quantity_check CHECK ((quantity > 0)),
    CONSTRAINT commerce_order_items_total_cents_check CHECK ((total_cents >= 0)),
    CONSTRAINT commerce_order_items_unit_price_cents_check CHECK ((unit_price_cents >= 0)),
    CONSTRAINT commerce_order_items_vat_rate_bps_check CHECK (((vat_rate_bps >= 0) AND (vat_rate_bps <= 10000)))
);


--
-- Name: COLUMN commerce_order_items.variant_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_order_items.variant_snapshot IS 'Regulatory-minimum frozen state of the variant at sale time: recipe_name, product_slug, format_code, net_weight_g, unit_form_code, kcal_per_unit, ingredients[], allergens[], barcode, gtin. Populated by the order-finalize handler (lands in W4 pricing breakdown wave). Allows FEDIAF traceability + customer-service "what exactly did the customer buy in January" reconstruction even after the catalog changes.';


--
-- Name: COLUMN commerce_order_items.size_constraint_contribution; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_order_items.size_constraint_contribution IS 'How much this line contributed to the cart-level size_constraint.value at sale time (e.g. unit_count=4 for a 4-pack line, total_weight_g=1600 for 4×400g, feeding_days=2.3 for a 30 kg dog). Lets audit reconstruct what the bundle/sub "size" meant per line.';


--
-- Name: COLUMN commerce_order_items.vat_rate_bps; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_order_items.vat_rate_bps IS 'VAT rate snapshot at sale (basis points: 800 = 8% PL food, 2300 = 23% accessories). PL VAT is inclusive, so resolved_unit_price_minor is gross. Invoice generation derives net via net = gross × 10000 / (10000 + vat_rate_bps).';


--
-- Name: COLUMN commerce_order_items.discount_allocated_cents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_order_items.discount_allocated_cents IS 'Final order-level product discount allocated to this line in minor currency units.';


--
-- Name: COLUMN commerce_order_items.effective_total_cents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_order_items.effective_total_cents IS 'Final gross line amount after allocated product discount; canonical document/ledger amount.';


--
-- Name: COLUMN commerce_order_items.effective_net_cents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_order_items.effective_net_cents IS 'Final tax-exclusive line amount derived from effective_total_cents and the frozen vat_rate_bps.';


--
-- Name: COLUMN commerce_order_items.allocation_ordinal; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_order_items.allocation_ordinal IS 'Stable 1-based quote-line ordinal used as the deterministic largest-remainder tie-break.';


