    idempotency_key text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL
);


--
-- Name: commerce_orders; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid,
    checkout_session_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    order_number text,
    status text DEFAULT 'draft'::text NOT NULL,
    currency text DEFAULT 'PLN'::text NOT NULL,
    subtotal_cents integer DEFAULT 0 NOT NULL,
    discount_cents integer DEFAULT 0 NOT NULL,
    shipping_cents integer DEFAULT 0 NOT NULL,
    tax_cents integer DEFAULT 0 NOT NULL,
    total_cents integer DEFAULT 0 NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    region_code text DEFAULT 'PL'::text NOT NULL,
    mode text DEFAULT 'one_time'::text NOT NULL,
    size_constraint jsonb,
    subscription_id uuid,
    subscription_cycle_id uuid,
    shipping_address_id uuid,
    pet_id uuid,
    shipping_discount_cents integer DEFAULT 0 NOT NULL,
    recovery_root_order_id uuid,
    recreated_from_order_id uuid,
    source_kind text DEFAULT 'storefront'::text NOT NULL,
    source_channel_id uuid,
    source_order_ref text,
    CONSTRAINT commerce_orders_canonical_money_equation_check CHECK (((discount_cents <= subtotal_cents) AND ((total_cents)::bigint = ((((subtotal_cents)::bigint - (discount_cents)::bigint) + (shipping_cents)::bigint) - (shipping_discount_cents)::bigint)))),
    CONSTRAINT commerce_orders_currency_check CHECK ((char_length(currency) = 3)),
    CONSTRAINT commerce_orders_discount_cents_check CHECK ((discount_cents >= 0)),
    CONSTRAINT commerce_orders_mode_check CHECK ((mode = ANY (ARRAY['one_time'::text, 'subscription_cycle'::text]))),
    CONSTRAINT commerce_orders_region_code_check CHECK (((char_length(region_code) >= 2) AND (char_length(region_code) <= 3))),
    CONSTRAINT commerce_orders_shipping_cents_check CHECK ((shipping_cents >= 0)),
    CONSTRAINT commerce_orders_shipping_discount_range_check CHECK (((shipping_discount_cents >= 0) AND (shipping_discount_cents <= shipping_cents))),
    CONSTRAINT commerce_orders_source_kind_check CHECK (((btrim(source_kind) <> ''::text) AND (char_length(source_kind) <= 32))),
    CONSTRAINT commerce_orders_source_order_ref_check CHECK (((source_order_ref IS NULL) OR ((btrim(source_order_ref) <> ''::text) AND (char_length(source_order_ref) <= 128)))),
    CONSTRAINT commerce_orders_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_payment'::text, 'paid'::text, 'failed'::text, 'expired'::text, 'fulfillment_pending'::text, 'fulfilled'::text, 'cancelled'::text, 'refunded'::text]))),
    CONSTRAINT commerce_orders_subscription_cycle_mode_check CHECK (((mode <> 'subscription_cycle'::text) OR ((subscription_id IS NOT NULL) AND (subscription_cycle_id IS NOT NULL)))),
    CONSTRAINT commerce_orders_subtotal_cents_check CHECK ((subtotal_cents >= 0)),
    CONSTRAINT commerce_orders_tax_cents_check CHECK ((tax_cents >= 0)),
    CONSTRAINT commerce_orders_total_cents_check CHECK ((total_cents >= 0))
);


--
-- Name: COLUMN commerce_orders.subscription_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_orders.subscription_id IS 'Loose UUID reference to the openlup-owned subscription. The cycle snapshot is linked via subscription_cycle_id.';


--
-- Name: COLUMN commerce_orders.subscription_cycle_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_orders.subscription_cycle_id IS 'Local own-engine cycle that generated this subscription order.';


--
-- Name: COLUMN commerce_orders.pet_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_orders.pet_id IS 'Optional pet context for one-time orders and required pet context for subscription-cycle orders. Hidden checkout runtime validates pets.client_id ownership and snapshots pet facts in metadata.';


--
-- Name: COLUMN commerce_orders.shipping_discount_cents; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_orders.shipping_discount_cents IS 'Discount allocated only to delivery; total = subtotal - product discount + shipping - shipping discount.';


--
-- Name: COLUMN commerce_orders.recovery_root_order_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_orders.recovery_root_order_id IS 'Root order of an expired-checkout recreation chain. NULL on orders that were never recreated.';


--
-- Name: COLUMN commerce_orders.recreated_from_order_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_orders.recreated_from_order_id IS 'Immediate system-expired predecessor recreated after authoritative quote validation.';


--
-- Name: COLUMN commerce_orders.source_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_orders.source_kind IS 'Which class of selling surface produced this order. Defaults to the storefront, which is what every row predating the channel registry is.';


--
-- Name: COLUMN commerce_orders.source_channel_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_orders.source_channel_id IS 'The registered channel this order came from. NULL exactly when source_kind is the storefront.';


--
-- Name: COLUMN commerce_orders.source_order_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commerce_orders.source_order_ref IS 'The originating surface own identifier for this order. Opaque; never parsed here. Unique within its channel so a repeated import conflicts instead of duplicating.';


