    CONSTRAINT commerce_payment_intents_currency_check CHECK ((char_length(currency) = 3)),
    CONSTRAINT commerce_payment_intents_status_check CHECK ((status = ANY (ARRAY['created'::text, 'requires_action'::text, 'processing'::text, 'succeeded'::text, 'failed'::text, 'expired'::text, 'cancelled'::text, 'refunded'::text, 'partially_refunded'::text, 'disputed'::text]))),
    CONSTRAINT commerce_payment_intents_target_kind_check CHECK ((target_kind = ANY (ARRAY['one_time_order'::text, 'subscription_cycle'::text])))
);


--
-- Name: commerce_payment_method_refs; Type: TABLE; Schema: public; Owner: -
