    CONSTRAINT commerce_payment_method_refs_check CHECK (((active = false) OR (status = 'active'::text))),
    CONSTRAINT commerce_payment_method_refs_method_kind_check CHECK ((method_kind = ANY (ARRAY['card'::text, 'blik_payid'::text, 'wallet'::text, 'alias'::text]))),
    CONSTRAINT commerce_payment_method_refs_provider_kind_check CHECK ((btrim(provider_kind) <> ''::text)),
    CONSTRAINT commerce_payment_method_refs_provider_method_ref_check CHECK ((btrim(provider_method_ref) <> ''::text)),
    CONSTRAINT commerce_payment_method_refs_status_check CHECK ((status = ANY (ARRAY['pending_verification'::text, 'active'::text, 'inactive'::text, 'expired'::text, 'revoked'::text])))
);


