-- Name: commerce_return_lines; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_return_lines (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    return_request_id uuid NOT NULL,
    order_item_id uuid NOT NULL,
    sku text NOT NULL,
    quantity integer NOT NULL,
    restock_disposition text DEFAULT 'restock'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT commerce_return_lines_quantity_check CHECK ((quantity > 0)),
    CONSTRAINT commerce_return_lines_restock_disposition_check CHECK ((restock_disposition = ANY (ARRAY['restock'::text, 'quarantine'::text, 'scrap'::text])))
);


--
-- Name: commerce_return_operations; Type: TABLE; Schema: public; Owner: -
--

