    id uuid DEFAULT gen_random_uuid() NOT NULL,
    return_request_id uuid NOT NULL,
    actor_user_id uuid,
    operation_type text NOT NULL,
    source text DEFAULT 'system'::text NOT NULL,
    idempotency_key text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT commerce_return_operations_operation_type_check CHECK ((operation_type = ANY (ARRAY['requested'::text, 'approved'::text, 'rejected'::text, 'label_issued'::text, 'status_evidence'::text, 'restock_recorded'::text, 'refund_recorded'::text, 'hold_created'::text])))
);


--
-- Name: commerce_return_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_return_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    fulfillment_order_id uuid,
    status text DEFAULT 'requested'::text NOT NULL,
    reason_code text NOT NULL,
    customer_note text,
    admin_note text,
    requested_by uuid,
    approved_by uuid,
    refund_mode text DEFAULT 'full'::text NOT NULL,
    refund_amount_cents integer,
    currency text,
    idempotency_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT commerce_return_requests_reason_code_check CHECK ((reason_code = ANY (ARRAY['damaged'::text, 'wrong_item'::text, 'not_as_described'::text, 'pet_refused'::text, 'changed_mind'::text, 'other'::text]))),
    CONSTRAINT commerce_return_requests_refund_amount_cents_check CHECK (((refund_amount_cents IS NULL) OR (refund_amount_cents >= 0))),
    CONSTRAINT commerce_return_requests_refund_mode_check CHECK ((refund_mode = ANY (ARRAY['full'::text, 'partial'::text, 'none'::text]))),
    CONSTRAINT commerce_return_requests_status_check CHECK ((status = ANY (ARRAY['requested'::text, 'approved'::text, 'rejected'::text, 'label_issued'::text, 'in_transit'::text, 'received'::text, 'restocked'::text, 'refunded'::text, 'cancelled'::text, 'exception'::text])))
);


--
-- Name: commerce_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.commerce_settings (
    key text NOT NULL,
    value_minor integer,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    value_text text,
    CONSTRAINT commerce_settings_min_product_payable_value CHECK (((key <> 'min_product_payable_minor'::text) OR ((value_minor IS NOT NULL) AND (value_minor >= 1)))),
    CONSTRAINT commerce_settings_offer_layout_value CHECK (((key <> 'configurator_offer_layout'::text) OR (value_text = ANY (ARRAY['subscription_first'::text, 'one_time_first'::text, 'starter_first'::text])))),
    CONSTRAINT commerce_settings_settlement_currency_value CHECK (((key <> 'settlement_currency'::text) OR ((value_text IS NOT NULL) AND (value_text ~ '^[A-Z]{3}$'::text)))),
    CONSTRAINT commerce_settings_settlement_region_value CHECK (((key <> 'settlement_region'::text) OR ((value_text IS NOT NULL) AND (value_text ~ '^[A-Z]{2}$'::text)))),
    CONSTRAINT commerce_settings_value_minor_check CHECK ((value_minor >= 0)),
    CONSTRAINT commerce_settings_value_present CHECK (((value_minor IS NOT NULL) OR (value_text IS NOT NULL)))
);


--
-- Name: TABLE commerce_settings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.commerce_settings IS 'Admin-editable commerce config, one row per key. Integer settings use value_minor (minor units); closed-vocabulary and code settings use value_text. Every row carries at least one of the two, and shipping_flat_minor must carry value_minor because the quote path reads a missing amount as free shipping. The settlement_currency, settlement_region and min_product_payable_minor rows are the database-side mirror of the application settlement profile and are read by platform_settlement_currency() and platform_region_code(). Keys: shipping_flat_minor, configurator_offer_layout, settlement_currency, settlement_region, min_product_payable_minor.';


