    CONSTRAINT customer_diagnostic_ingress_hash_check CHECK ((abuse_key_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: customer_diagnostic_segments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_diagnostic_segments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    credential_hash text NOT NULL,
    principal_id uuid,
    subject_id uuid,
    predecessor_segment_id uuid,
    predecessor_relation text,
    started_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    closed_at timestamp with time zone,
    close_reason text,
    CONSTRAINT customer_diagnostic_segments_close_check CHECK ((((closed_at IS NULL) AND (close_reason IS NULL)) OR ((closed_at IS NOT NULL) AND (close_reason = ANY (ARRAY['auth_changed'::text, 'logout'::text, 'expired'::text]))))),
    CONSTRAINT customer_diagnostic_segments_credential_check CHECK ((credential_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT customer_diagnostic_segments_predecessor_check CHECK ((((predecessor_segment_id IS NULL) AND (predecessor_relation IS NULL)) OR ((predecessor_segment_id IS NOT NULL) AND (predecessor_relation = 'same_tab_pre_auth_context'::text)))),
    CONSTRAINT customer_diagnostic_segments_subject_check CHECK (((subject_id IS NULL) OR (principal_id IS NOT NULL)))
);


