-- Name: customer_orderer_profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_orderer_profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    client_id uuid NOT NULL,
    label text,
    full_name text NOT NULL,
    email text NOT NULL,
    phone text,
    company_name text,
    tax_id text,
    is_default boolean DEFAULT false NOT NULL,
    source text DEFAULT 'unknown'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    company_verification_level text,
    company_identity_source text,
    company_identity_evidence_hash text,
    CONSTRAINT customer_orderer_profiles_company_identity_evidence_hash_len CHECK (((company_identity_evidence_hash IS NULL) OR (char_length(company_identity_evidence_hash) <= 160))),
    CONSTRAINT customer_orderer_profiles_company_identity_source_len CHECK (((company_identity_source IS NULL) OR (char_length(company_identity_source) <= 120))),
    CONSTRAINT customer_orderer_profiles_company_name_len CHECK (((company_name IS NULL) OR (char_length(company_name) <= 200))),
    CONSTRAINT customer_orderer_profiles_company_verification_level_check CHECK (((company_verification_level IS NULL) OR (company_verification_level = ANY (ARRAY['registry_verified'::text, 'provider_verified'::text, 'manual_unverified'::text, 'invalid'::text])))),
    CONSTRAINT customer_orderer_profiles_email_len CHECK (((char_length(email) >= 3) AND (char_length(email) <= 320))),
    CONSTRAINT customer_orderer_profiles_full_name_len CHECK (((char_length(full_name) >= 1) AND (char_length(full_name) <= 200))),
    CONSTRAINT customer_orderer_profiles_label_len CHECK (((label IS NULL) OR (char_length(label) <= 120))),
    CONSTRAINT customer_orderer_profiles_phone_len CHECK (((phone IS NULL) OR (char_length(phone) <= 64))),
    CONSTRAINT customer_orderer_profiles_source_check CHECK ((source = ANY (ARRAY['unknown'::text, 'hidden_configurator'::text, 'customer_account'::text, 'checkout'::text, 'admin'::text]))),
    CONSTRAINT customer_orderer_profiles_tax_id_len CHECK (((tax_id IS NULL) OR (char_length(tax_id) <= 64)))
);


--
-- Name: TABLE customer_orderer_profiles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.customer_orderer_profiles IS 'Hidden ordering-person profiles for future checkout defaults. No UI or provider activation.';


--
-- Name: COLUMN customer_orderer_profiles.company_verification_level; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_orderer_profiles.company_verification_level IS 'Provider-neutral verification level for company billing identity captured from account NIP lookup.';


--
-- Name: COLUMN customer_orderer_profiles.company_identity_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_orderer_profiles.company_identity_source IS 'PII-safe provider kind/source for company identity lookup evidence.';


