--

COMMENT ON COLUMN public.customer_payment_preferences.method_kind IS 'UI-safe payment method family only: blik/card/transfer. Provider payment refs are forbidden here.';


--
-- Name: customer_personalization; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_personalization (
    client_id uuid NOT NULL,
    owner_name_raw text,
    owner_cases jsonb,
    owner_conf text,
    primary_pet_id uuid,
    dog_name_raw text,
    dog_gender text,
    dog_cases jsonb,
    dog_conf text,
    source text,
    model_version text,
    input_hash text,
    generated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT customer_personalization_dog_conf_check CHECK ((dog_conf = ANY (ARRAY['high'::text, 'low'::text]))),
    CONSTRAINT customer_personalization_dog_gender_check CHECK ((dog_gender = ANY (ARRAY['masculine'::text, 'feminine'::text, 'neuter'::text, 'unknown'::text]))),
    CONSTRAINT customer_personalization_owner_conf_check CHECK ((owner_conf = ANY (ARRAY['high'::text, 'low'::text]))),
    CONSTRAINT customer_personalization_source_check CHECK ((source = ANY (ARRAY['dictionary'::text, 'llm'::text, 'manual'::text])))
);


--
-- Name: TABLE customer_personalization; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.customer_personalization IS 'Precomputed Polish declension forms for the /v2 personalized hero (owner first name + primary dog name). 1:1 with clients. Written by the service-role persist-intent path / outbox declension worker; read by the personalization BFF endpoint. owner_cases carries NO inferred person gender (v1 copy is gender-neutral); dog_gender is grammatical gender used only for inflection.';


--
-- Name: COLUMN customer_personalization.owner_conf; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_personalization.owner_conf IS 'high => forms safe to render; low => render a neutral (nameless) variant.';


--
-- Name: COLUMN customer_personalization.primary_pet_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_personalization.primary_pet_id IS 'The pet whose name feeds the hero (most-recent pet_type=dog). ON DELETE SET NULL so a removed pet degrades to the neutral variant.';


--
-- Name: COLUMN customer_personalization.dog_gender; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_personalization.dog_gender IS 'GRAMMATICAL gender of the dog name (masculine|feminine|neuter|unknown), used to inflect the name. Not a profile attribute.';


--
-- Name: COLUMN customer_personalization.input_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_personalization.input_hash IS 'hash(owner_name_raw||dog_name_raw); a mismatch on save triggers regeneration.';


