    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tester_id uuid,
    template_id uuid,
    template_slug text,
    resend_id text,
    sent_at timestamp with time zone DEFAULT now(),
    status text DEFAULT 'sent'::text,
    source text,
    provider_error text,
    provider_response jsonb,
    created_at timestamp with time zone DEFAULT now(),
    poll_abandoned_at timestamp with time zone,
    poll_not_found_count integer DEFAULT 0 NOT NULL,
    poll_last_attempt_at timestamp with time zone
);


--
-- Name: COLUMN email_sends.source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.email_sends.source IS 'Internal origin of the send request, e.g. admin or a service workflow name.';


--
-- Name: COLUMN email_sends.provider_error; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.email_sends.provider_error IS 'Short sanitized provider error message. Never stores email body or template payload.';


--
-- Name: COLUMN email_sends.provider_response; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.email_sends.provider_response IS 'Sanitized provider response keys only. Never stores email body or template payload.';


--
-- Name: COLUMN email_sends.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.email_sends.created_at IS 'Row creation time. Set on every send attempt (incl. failures, where sent_at is NULL). The platform watchdog windows failed sends on this column.';


--
-- Name: COLUMN email_sends.poll_abandoned_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.email_sends.poll_abandoned_at IS 'Set by the Resend delivery poller when a send is given up as un-pollable (N consecutive provider 404s). Excludes the row from re-polling; status is left unchanged because delivery outcome is unknown, only that polling is futile.';


--
-- Name: COLUMN email_sends.poll_not_found_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.email_sends.poll_not_found_count IS 'Consecutive provider 404 (not-found) reads by the Resend delivery poller. Advances only on 404; drives poll_abandoned_at at the abandon threshold.';


--
-- Name: COLUMN email_sends.poll_last_attempt_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.email_sends.poll_last_attempt_at IS 'Most recent Resend delivery reconciliation read attempt. Used to rotate frozen sends fairly; it is not delivery evidence.';


