    CONSTRAINT feedback_packaging_rating_check CHECK (((packaging_rating >= 1) AND (packaging_rating <= 5))),
    CONSTRAINT feedback_taste_rating_check CHECK (((taste_rating >= 1) AND (taste_rating <= 5))),
    CONSTRAINT feedback_texture_rating_check CHECK (((texture_rating >= 1) AND (texture_rating <= 5))),
    CONSTRAINT feedback_unboxing_rating_check CHECK (((unboxing_rating >= 1) AND (unboxing_rating <= 5)))
);


