    CONSTRAINT inbound_provider_events_currency_check CHECK (((currency IS NULL) OR (char_length(currency) = 3)))
);


--
-- Name: TABLE inbound_provider_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.inbound_provider_events IS 'Canonical inbound event log for every external adapter (payment, subscription, fulfillment). UNIQUE (provider, provider_event_id) makes the same webhook idempotent across the network. Handlers are pure (event, current_state) → new_state so reconciliation replay is free.';


