--
-- Name: order_line_pricing_breakdown; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.order_line_pricing_breakdown (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    order_line_id uuid,
    sequence integer NOT NULL,
    component_type text NOT NULL,
    amount_minor integer NOT NULL,
    reason_code text,
    reason_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT order_line_pricing_breakdown_sequence_check CHECK ((sequence >= 0))
);


--
-- Name: COLUMN order_line_pricing_breakdown.order_line_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.order_line_pricing_breakdown.order_line_id IS 'NULL for cart-level components (shipping, order-total promo). NOT NULL for line-level components (base_unit, mode_discount, qty_tier, line-scoped promo, loyalty). The cart-level invariant sums *all* components in an order — both line and cart-level.';


--
-- Name: COLUMN order_line_pricing_breakdown.component_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.order_line_pricing_breakdown.component_type IS 'Stable enum that the pricing stack appends in order: base_unit → mode_discount → qty_tier → promo → loyalty → shipping. Sequence column carries the actual chronological order in case a future pricing strategy interleaves differently.';


--
-- Name: COLUMN order_line_pricing_breakdown.amount_minor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.order_line_pricing_breakdown.amount_minor IS 'Signed integer in the order''s currency minor units. base_unit and shipping are positive (or zero for free_shipping promo offset). mode_discount, qty_tier, promo, loyalty are negative (or zero) — they reduce the running total.';


--
-- Name: COLUMN order_line_pricing_breakdown.reason_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.order_line_pricing_breakdown.reason_code IS 'Short stable identifier of why the component landed (e.g. "subscription_band", "qty_tier_14", "promo:WELCOME10", "shipping:one_time_pln_standard"). Support uses it to explain the invoice to a customer without parsing reason_payload.';


--
-- Name: COLUMN order_line_pricing_breakdown.reason_payload; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.order_line_pricing_breakdown.reason_payload IS 'Structured context: promo_id, applied_rule_id, vat_rate_bps (for shipping), matched_tier_min_qty, etc. Schema-flexible because every component type carries a different shape.';


