    CONSTRAINT platform_alert_notifications_channel_check CHECK ((channel = ANY (ARRAY['webhook'::text, 'resend'::text]))),
    CONSTRAINT platform_alert_notifications_status_check CHECK ((status = ANY (ARRAY['sent'::text, 'failed'::text, 'skipped'::text])))
);


--
-- Name: TABLE platform_alert_notifications; Type: COMMENT; Schema: public; Owner: -
