    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    snoozed_until timestamp with time zone,
    last_notification_attempt_at timestamp with time zone,
    last_notification_status text,
    next_notification_attempt_at timestamp with time zone,
    notification_failure_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT platform_alerts_severity_check CHECK ((severity = ANY (ARRAY['p0'::text, 'p1'::text, 'p2'::text, 'p3'::text]))),
    CONSTRAINT platform_alerts_status_check CHECK ((status = ANY (ARRAY['open'::text, 'acknowledged'::text, 'resolved'::text])))
);


--
-- Name: TABLE platform_alerts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.platform_alerts IS 'Durable platform watchdog alert ledger. One stable dedupe_key row represents the active incident state.';


--
-- Name: COLUMN platform_alerts.snoozed_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_alerts.snoozed_until IS 'Operator silence window. When set and in the future, the watchdog records the alert but does not page until this time.';


--
-- Name: COLUMN platform_alerts.last_notification_attempt_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_alerts.last_notification_attempt_at IS 'Timestamp of the most recent watchdog delivery decision, including failed or skipped attempts.';


--
-- Name: COLUMN platform_alerts.last_notification_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_alerts.last_notification_status IS 'Outcome of the most recent watchdog delivery decision: sent, failed, or skipped.';


--
-- Name: COLUMN platform_alerts.next_notification_attempt_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_alerts.next_notification_attempt_at IS 'Earliest time the watchdog may write/send the next delivery attempt for this alert.';


--
-- Name: COLUMN platform_alerts.notification_failure_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_alerts.notification_failure_count IS 'Consecutive failed webhook attempts; reset by sent or skipped outcomes and used for bounded retry backoff.';


