    CONSTRAINT platform_job_controls_last_status_check CHECK ((last_status = ANY (ARRAY['running'::text, 'success'::text, 'failed'::text, 'skipped'::text])))
);


--
-- Name: COLUMN platform_job_controls.allowed_trigger_kinds; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_job_controls.allowed_trigger_kinds IS 'v3-only allowlist of neutral trigger kinds; NULL preserves legacy driver-controlled jobs.';


--
-- Name: platform_job_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_job_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    job_name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    status text DEFAULT 'running'::text NOT NULL,
    trigger_source text NOT NULL,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    checked_count integer,
    updated_count integer,
    error text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    driver text,
    checked integer,
    updated integer,
    support_code text,
    trigger_kind text,
    invocation_source text,
    CONSTRAINT platform_job_runs_checked_check CHECK (((checked IS NULL) OR (checked >= 0))),
    CONSTRAINT platform_job_runs_checked_count_check CHECK (((checked_count IS NULL) OR (checked_count >= 0))),
    CONSTRAINT platform_job_runs_invocation_source_check CHECK (((invocation_source IS NULL) OR ((btrim(invocation_source) <> ''::text) AND (length(invocation_source) <= 128)))),
    CONSTRAINT platform_job_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'success'::text, 'failed'::text, 'skipped'::text]))),
    CONSTRAINT platform_job_runs_trigger_kind_check CHECK (((trigger_kind IS NULL) OR (trigger_kind = ANY (ARRAY['worker'::text, 'scheduler'::text, 'operator'::text])))),
    CONSTRAINT platform_job_runs_updated_check CHECK (((updated IS NULL) OR (updated >= 0))),
    CONSTRAINT platform_job_runs_updated_count_check CHECK (((updated_count IS NULL) OR (updated_count >= 0)))
);


--
-- Name: COLUMN platform_job_runs.trigger_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_job_runs.trigger_kind IS 'v3 neutral execution class: worker, scheduler, or operator.';


--
-- Name: COLUMN platform_job_runs.invocation_source; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.platform_job_runs.invocation_source IS 'v3 observational adapter evidence, never an authorization control.';


--
