    CONSTRAINT platform_operational_controls_key_check CHECK ((control_key ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$'::text)),
    CONSTRAINT platform_operational_controls_revision_check CHECK ((revision >= 1))
);


--
-- Name: price_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.price_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    price_list_id uuid NOT NULL,
    variant_id uuid NOT NULL,
    mode text NOT NULL,
    min_qty integer DEFAULT 1 NOT NULL,
    unit_price_minor integer NOT NULL,
    amount_kind text DEFAULT 'gross'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT price_entries_amount_kind_check CHECK ((amount_kind = ANY (ARRAY['gross'::text, 'net'::text]))),
    CONSTRAINT price_entries_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT price_entries_min_qty_check CHECK ((min_qty > 0)),
    CONSTRAINT price_entries_mode_check CHECK ((mode = ANY (ARRAY['one_time'::text, 'subscription'::text, 'any'::text]))),
    CONSTRAINT price_entries_unit_price_minor_check CHECK ((unit_price_minor >= 0))
);


--
-- Name: COLUMN price_entries.mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.price_entries.mode IS 'Pricing band: ''one_time'' (single-purchase), ''subscription'' (recurring cycle), or ''any'' (fallback used by ad-hoc add-ons that re-price regardless of cart-wide mode).';


--
-- Name: COLUMN price_entries.min_qty; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.price_entries.min_qty IS 'Cart-level eligible quantity threshold (see resolvePrice signature). Tier match uses `eligible_cart_qty >= min_qty` then picks the highest matching tier. Resolver determinism: at most one row per (price_list, variant, mode, min_qty) at any given valid_from. Price changes ship via INSERT new row + deactivate old.';


--
-- Name: price_lists; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.price_lists (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    region_code text NOT NULL,
    currency text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT price_lists_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT price_lists_currency_check CHECK ((char_length(currency) = 3)),
    CONSTRAINT price_lists_region_code_check CHECK (((char_length(region_code) >= 2) AND (char_length(region_code) <= 3))),
    CONSTRAINT price_lists_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'archived'::text])))
);


