);


--
-- Name: promotion_code_claim_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.promotion_code_claim_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    claim_id uuid NOT NULL,
    code_id uuid NOT NULL,
    order_id uuid NOT NULL,
    transition_kind text NOT NULL,
    from_status text,
    to_status text NOT NULL,
    safe_reason text NOT NULL,
    claim_expires_at timestamp with time zone NOT NULL,
    occurred_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    CONSTRAINT promotion_code_claim_events_check CHECK ((((transition_kind = 'reserved'::text) AND (to_status = 'reserved'::text) AND (from_status IS NULL) AND (safe_reason = 'claim_reserved'::text)) OR ((transition_kind = 'reserved'::text) AND (to_status = 'reserved'::text) AND (from_status = 'released'::text) AND (safe_reason = 'claim_re_reserved'::text)) OR ((transition_kind = 'redeemed'::text) AND (to_status = 'redeemed'::text) AND (from_status IS NULL) AND (safe_reason = 'claim_redeemed'::text)) OR ((transition_kind = 'redeemed'::text) AND (to_status = 'redeemed'::text) AND (from_status = 'reserved'::text) AND (safe_reason = 'claim_redeemed'::text)) OR ((transition_kind = 'released'::text) AND (to_status = 'released'::text) AND (from_status IS NULL) AND (safe_reason = 'claim_released'::text)) OR ((transition_kind = 'released'::text) AND (to_status = 'released'::text) AND (from_status = ANY (ARRAY['reserved'::text, 'redeemed'::text])) AND (safe_reason = ANY (ARRAY['claim_released'::text, 'order_cancelled'::text, 'order_failed'::text, 'order_expired'::text]))) OR ((transition_kind = 'late_paid'::text) AND (from_status = 'released'::text) AND (to_status = 'redeemed'::text) AND (safe_reason = ANY (ARRAY['late_paid_after_release'::text, 'late_paid_after_order_cancelled'::text, 'late_paid_after_order_failed'::text, 'late_paid_after_order_expired'::text]))))),
    CONSTRAINT promotion_code_claim_events_from_status_check CHECK ((from_status = ANY (ARRAY['reserved'::text, 'redeemed'::text, 'released'::text]))),
    CONSTRAINT promotion_code_claim_events_safe_reason_check CHECK ((safe_reason = ANY (ARRAY['claim_reserved'::text, 'claim_re_reserved'::text, 'claim_redeemed'::text, 'claim_released'::text, 'order_cancelled'::text, 'order_failed'::text, 'order_expired'::text, 'late_paid_after_release'::text, 'late_paid_after_order_cancelled'::text, 'late_paid_after_order_failed'::text, 'late_paid_after_order_expired'::text]))),
    CONSTRAINT promotion_code_claim_events_to_status_check CHECK ((to_status = ANY (ARRAY['reserved'::text, 'redeemed'::text, 'released'::text]))),
    CONSTRAINT promotion_code_claim_events_transition_kind_check CHECK ((transition_kind = ANY (ARRAY['reserved'::text, 'redeemed'::text, 'released'::text, 'late_paid'::text])))
);


--
-- Name: TABLE promotion_code_claim_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.promotion_code_claim_events IS 'Append-only, no-backfill transition evidence for promotion claims. Contains opaque identifiers and closed safe reasons only; no client id, raw code, PII or money.';


--
-- Name: promotion_code_claims; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.promotion_code_claims (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    promotion_code_id uuid NOT NULL,
    order_id uuid NOT NULL,
    client_id uuid,
    status text NOT NULL,
    reserved_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    redeemed_at timestamp with time zone,
    released_at timestamp with time zone,
    release_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT promotion_code_claims_check CHECK ((expires_at > reserved_at)),
    CONSTRAINT promotion_code_claims_check1 CHECK (((status = 'redeemed'::text) = (redeemed_at IS NOT NULL))),
    CONSTRAINT promotion_code_claims_check2 CHECK (((status = 'released'::text) = (released_at IS NOT NULL))),
    CONSTRAINT promotion_code_claims_status_check CHECK ((status = ANY (ARRAY['reserved'::text, 'redeemed'::text, 'released'::text])))
);


--
-- Name: promotion_codes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.promotion_codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    code_normalized text GENERATED ALWAYS AS (upper(btrim(code))) STORED,
    name text NOT NULL,
    admin_description text,
    scopes text[] NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    minimum_reference_minor integer DEFAULT 0 NOT NULL,
    redemption_limit_global integer,
    redemption_limit_per_customer integer,
    status text DEFAULT 'draft'::text NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT promotion_codes_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT promotion_codes_minimum_reference_minor_check CHECK ((minimum_reference_minor >= 0)),
    CONSTRAINT promotion_codes_redemption_limit_global_check CHECK (((redemption_limit_global IS NULL) OR (redemption_limit_global > 0))),
    CONSTRAINT promotion_codes_redemption_limit_per_customer_check CHECK (((redemption_limit_per_customer IS NULL) OR (redemption_limit_per_customer > 0))),
    CONSTRAINT promotion_codes_revision_check CHECK ((revision > 0)),
    CONSTRAINT promotion_codes_scopes_check CHECK (((cardinality(scopes) >= 1) AND (cardinality(scopes) <= 2))),
    CONSTRAINT promotion_codes_scopes_check1 CHECK ((scopes <@ ARRAY['one_time'::text, 'subscription_initial'::text])),
    CONSTRAINT promotion_codes_scopes_check2 CHECK (((cardinality(scopes) = 1) OR (scopes[1] <> scopes[2]))),
    CONSTRAINT promotion_codes_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'paused'::text, 'archived'::text])))
);


--
-- Name: promotion_redemptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.promotion_redemptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    promotion_id uuid NOT NULL,
    client_id uuid,
