    amount_off_minor integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    visitor_id text,
    CONSTRAINT promotion_redemptions_amount_off_minor_check CHECK ((amount_off_minor >= 0))
);


--
-- Name: COLUMN promotion_redemptions.amount_off_minor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.promotion_redemptions.amount_off_minor IS 'Positive integer: how much the promotion knocked off the order in the order''s currency minor units. Always matches the absolute value of the corresponding promo row in order_line_pricing_breakdown.';


--
-- Name: COLUMN promotion_redemptions.visitor_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.promotion_redemptions.visitor_id IS 'Device visitor id (openlup_vid) captured from the order metadata at paid-time; powers the device first-order guard. NULL for orders placed before the signal existed or without a vid.';


--
-- Name: promotions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.promotions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text,
    name text NOT NULL,
    trigger_type text NOT NULL,
    discount_type text NOT NULL,
    discount_value numeric NOT NULL,
    applies_to_kind text NOT NULL,
    applies_to_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    stacking_rule text DEFAULT 'exclusive'::text NOT NULL,
    eligibility jsonb DEFAULT '{}'::jsonb NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    redemption_limit_global integer,
    redemption_limit_per_customer integer,
    region_availability text[] DEFAULT ARRAY['PL'::text] NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    promotion_engine_version text DEFAULT 'promotion-engine.v1'::text NOT NULL,
    benefit_lane text,
    benefit_kind text,
    benefit_value_bps numeric,
    benefit_value_minor numeric,
    v2_mirror_of uuid,
    CONSTRAINT promotions_applies_to_kind_check CHECK ((applies_to_kind = ANY (ARRAY['order_total'::text, 'line_with_variant'::text, 'line_with_category'::text]))),
    CONSTRAINT promotions_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT promotions_check1 CHECK ((((trigger_type = 'coupon_code'::text) AND (code IS NOT NULL)) OR ((trigger_type = ANY (ARRAY['automatic'::text, 'referral'::text])) AND (code IS NULL)))),
    CONSTRAINT promotions_discount_type_check CHECK ((discount_type = ANY (ARRAY['percentage'::text, 'fixed_amount'::text, 'free_shipping'::text]))),
    CONSTRAINT promotions_discount_value_check CHECK ((discount_value >= (0)::numeric)),
    CONSTRAINT promotions_redemption_limit_global_check CHECK (((redemption_limit_global IS NULL) OR (redemption_limit_global > 0))),
    CONSTRAINT promotions_redemption_limit_per_customer_check CHECK (((redemption_limit_per_customer IS NULL) OR (redemption_limit_per_customer > 0))),
    CONSTRAINT promotions_stacking_rule_check CHECK ((stacking_rule = ANY (ARRAY['exclusive'::text, 'stackable_with_any'::text, 'stackable_with_loyalty'::text]))),
    CONSTRAINT promotions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'paused'::text, 'archived'::text]))),
    CONSTRAINT promotions_trigger_type_check CHECK ((trigger_type = ANY (ARRAY['coupon_code'::text, 'automatic'::text, 'referral'::text])))
);


--
-- Name: COLUMN promotions.code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.promotions.code IS 'NULL for automatic + referral promotions (evaluator picks them up by eligibility), set for coupon_code promotions (customer enters at checkout). Enforced by the table-level CHECK constraint.';


--
-- Name: COLUMN promotions.discount_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.promotions.discount_type IS 'free_shipping zeros the cart-level shipping component (resolver still runs to record the carrier + estimate, then W4 pricing breakdown emits a shipping row with amount=0 and reason_code=shipping:<rule>:free_shipping_promo).';


--
-- Name: COLUMN promotions.stacking_rule; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.promotions.stacking_rule IS 'exclusive (default): one such promotion can land per order. stackable_with_loyalty: pairs with loyalty redemption rows. stackable_with_any: rare, used for additive site-wide campaigns.';


--
-- Name: COLUMN promotions.eligibility; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.promotions.eligibility IS 'Structured criteria. v1 keys: first_purchase (bool), returning_customer (bool), min_cart_minor (int), segment_id (uuid — placeholder until segments land). Evaluator reads this jsonb to gate apply decisions.';


