--
-- Name: risk_assessments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.risk_assessments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    order_id uuid,
    client_id uuid,
    payment_intent_id uuid,
    payment_event_id uuid,
    source text NOT NULL,
    enforcement_mode text NOT NULL,
    decision text NOT NULL,
    severity text NOT NULL,
    risk_score integer NOT NULL,
    reason_codes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    subject_refs jsonb DEFAULT '[]'::jsonb NOT NULL,
    matched_rules jsonb DEFAULT '[]'::jsonb NOT NULL,
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    idempotency_key text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT risk_assessments_decision_check CHECK ((decision = ANY (ARRAY['allow'::text, 'manual_review'::text, 'block'::text]))),
    CONSTRAINT risk_assessments_enforcement_mode_check CHECK ((enforcement_mode = ANY (ARRAY['shadow'::text, 'hold'::text, 'checkout_blocklist'::text]))),
    CONSTRAINT risk_assessments_evidence_check CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT risk_assessments_matched_rules_check CHECK ((jsonb_typeof(matched_rules) = 'array'::text)),
    CONSTRAINT risk_assessments_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 100))),
    CONSTRAINT risk_assessments_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT risk_assessments_source_check CHECK ((source = ANY (ARRAY['checkout'::text, 'paid_order'::text, 'payment_webhook'::text, 'admin_replay'::text]))),
    CONSTRAINT risk_assessments_subject_refs_check CHECK ((jsonb_typeof(subject_refs) = 'array'::text))
);


--
-- Name: risk_blocklist_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.risk_blocklist_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
