    CONSTRAINT risk_blocklist_entries_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text]))),
    CONSTRAINT risk_blocklist_entries_subject_hash_check CHECK (((length(subject_hash) >= 16) AND (length(subject_hash) <= 128))),
    CONSTRAINT risk_blocklist_entries_subject_kind_check CHECK ((subject_kind = ANY (ARRAY['client'::text, 'email'::text, 'phone'::text, 'ip'::text, 'device'::text, 'payment_method'::text, 'shipping_address'::text, 'billing_tax_id'::text, 'identity_cluster'::text])))
);


--
-- Name: risk_case_events; Type: TABLE; Schema: public; Owner: -
--

