    idempotency_key text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT risk_case_events_event_type_check CHECK ((event_type = ANY (ARRAY['case_opened'::text, 'case_approved'::text, 'case_blocked'::text, 'case_escalated'::text, 'case_note'::text])))
);


--
-- Name: risk_idempotency_keys; Type: TABLE; Schema: public; Owner: -
--

