    idempotency_key text NOT NULL,
    request_fingerprint text NOT NULL,
    status text DEFAULT 'completed'::text NOT NULL,
    response_payload jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT risk_idempotency_keys_status_check CHECK ((status = 'completed'::text))
);


--
-- Name: risk_manual_review_cases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.risk_manual_review_cases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    assessment_id uuid NOT NULL,
    order_id uuid,
    client_id uuid,
    payment_intent_id uuid,
    hold_id uuid,
    status text DEFAULT 'open'::text NOT NULL,
    decision text NOT NULL,
    severity text NOT NULL,
    risk_score integer NOT NULL,
    reason_codes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by uuid,
