    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT risk_manual_review_cases_decision_check CHECK ((decision = ANY (ARRAY['manual_review'::text, 'block'::text]))),
    CONSTRAINT risk_manual_review_cases_resolution_check CHECK (((resolution IS NULL) OR (resolution = ANY (ARRAY['approve'::text, 'block'::text, 'escalate'::text, 'closed'::text])))),
    CONSTRAINT risk_manual_review_cases_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 100))),
    CONSTRAINT risk_manual_review_cases_severity_check CHECK ((severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT risk_manual_review_cases_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_review'::text, 'approved'::text, 'blocked'::text, 'escalated'::text, 'closed'::text])))
);


--
-- Name: sales_channel_connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_channel_connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    connector_provider_kind text NOT NULL,
    connector_shape text DEFAULT 'direct'::text NOT NULL,
    display_name text NOT NULL,
    status text DEFAULT 'disabled'::text NOT NULL,
    credential_ref text,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    pull_cursor text,
    pull_watermark_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sales_channel_connections_connector_provider_kind_check CHECK (((btrim(connector_provider_kind) <> ''::text) AND (char_length(connector_provider_kind) <= 64))),
    CONSTRAINT sales_channel_connections_connector_shape_check CHECK ((connector_shape = ANY (ARRAY['direct'::text, 'aggregator'::text]))),
    CONSTRAINT sales_channel_connections_slug_check CHECK (((btrim(slug) <> ''::text) AND (char_length(slug) <= 64))),
    CONSTRAINT sales_channel_connections_status_check CHECK ((status = ANY (ARRAY['disabled'::text, 'testing'::text, 'active'::text, 'sunset'::text])))
);


--
-- Name: TABLE sales_channel_connections; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sales_channel_connections IS 'One credentialed link to one external marketplace, held directly or through an aggregator. credential_ref names a secret; it never stores one.';


--
-- Name: sales_channel_listings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_channel_listings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    channel_id uuid NOT NULL,
    sellable_kind text NOT NULL,
    sellable_sku_id uuid,
    external_offer_ref text,
    status text DEFAULT 'draft'::text NOT NULL,
    last_stock_pushed_qty integer,
    last_price_pushed_minor integer,
    last_sync_at timestamp with time zone,
    last_sync_error text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    sellable_bundle_id uuid,
    CONSTRAINT sales_channel_listings_sellable_kind_check CHECK (((btrim(sellable_kind) <> ''::text) AND (char_length(sellable_kind) <= 32))),
    CONSTRAINT sales_channel_listings_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'linked'::text, 'active'::text, 'paused'::text, 'ended'::text, 'error'::text])))
);


--
-- Name: TABLE sales_channel_listings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sales_channel_listings IS 'One sellable offered on one channel, with the last pushed stock/price so a syncer can tell a no-op from a real change.';


--
-- Name: COLUMN sales_channel_listings.sellable_bundle_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_channel_listings.sellable_bundle_id IS 'The bundle this listing offers, when sellable_kind is bundle. Never read by order ingest, which resolves a wire line by bundle code; this is the operator-facing pointer an outbound syncer pushes from.';


--
-- Name: sales_channel_quarantine; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_channel_quarantine (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    channel_id uuid,
    connection_id uuid,
    provider_event_id text NOT NULL,
    external_order_ref text,
    vocabulary text NOT NULL,
    reason text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    resolution_note text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sales_channel_quarantine_external_order_ref_check CHECK (((external_order_ref IS NULL) OR (char_length(external_order_ref) <= 128))),
    CONSTRAINT sales_channel_quarantine_provider_event_id_check CHECK (((btrim(provider_event_id) <> ''::text) AND (char_length(provider_event_id) <= 200))),
    CONSTRAINT sales_channel_quarantine_reason_check CHECK ((reason = ANY (ARRAY['unmapped_vocabulary'::text, 'unmapped_sellable'::text, 'vat_unresolvable'::text, 'money_mismatch'::text, 'revision_conflict'::text, 'contract_parse_failed'::text]))),
    CONSTRAINT sales_channel_quarantine_resolution_note_check CHECK (((resolution_note IS NULL) OR (char_length(resolution_note) <= 2000))),
    CONSTRAINT sales_channel_quarantine_status_check CHECK ((status = ANY (ARRAY['open'::text, 'resolved'::text, 'dismissed'::text]))),
    CONSTRAINT sales_channel_quarantine_vocabulary_check CHECK (((btrim(vocabulary) <> ''::text) AND (char_length(vocabulary) <= 200)))
);


--
-- Name: TABLE sales_channel_quarantine; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sales_channel_quarantine IS 'Everything the channel ingest refused, with the wire token verbatim so an operator can look it up on the far side. Operator work, not an error log.';


--
-- Name: COLUMN sales_channel_quarantine.vocabulary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_channel_quarantine.vocabulary IS 'The wire token exactly as received from the external surface. Never a panel label and never translated.';


--
-- Name: sales_channels; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_channels (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    connection_id uuid,
    slug text NOT NULL,
    kind text DEFAULT 'marketplace'::text NOT NULL,
    display_name text NOT NULL,
    status text DEFAULT 'disabled'::text NOT NULL,
    channel_external_ref text,
    currency text DEFAULT 'PLN'::text NOT NULL,
    region_code text,
    default_vat_rate_bps integer,
    buyer_comms_owner text DEFAULT 'platform'::text NOT NULL,
    invoice_policy text DEFAULT 'issue'::text NOT NULL,
    settlement_provider_kind text DEFAULT 'channel_settlement'::text NOT NULL,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    delivery_selection jsonb,
    CONSTRAINT sales_channels_buyer_comms_owner_check CHECK ((buyer_comms_owner = ANY (ARRAY['platform'::text, 'channel'::text]))),
    CONSTRAINT sales_channels_connection_required_for_connected_kinds CHECK (((kind <> 'marketplace'::text) OR (connection_id IS NOT NULL))),
    CONSTRAINT sales_channels_currency_check CHECK ((char_length(currency) = 3)),
    CONSTRAINT sales_channels_default_vat_rate_bps_check CHECK (((default_vat_rate_bps IS NULL) OR ((default_vat_rate_bps >= 0) AND (default_vat_rate_bps <= 10000)))),
    CONSTRAINT sales_channels_invoice_policy_check CHECK ((invoice_policy = ANY (ARRAY['issue'::text, 'suppress'::text, 'channel_issues'::text]))),
    CONSTRAINT sales_channels_kind_check CHECK (((btrim(kind) <> ''::text) AND (char_length(kind) <= 32))),
    CONSTRAINT sales_channels_settlement_provider_kind_check CHECK (((btrim(settlement_provider_kind) <> ''::text) AND (char_length(settlement_provider_kind) <= 64))),
    CONSTRAINT sales_channels_slug_check CHECK (((btrim(slug) <> ''::text) AND (char_length(slug) <= 64))),
    CONSTRAINT sales_channels_status_check CHECK ((status = ANY (ARRAY['disabled'::text, 'testing'::text, 'active'::text, 'sunset'::text])))
);


--
-- Name: TABLE sales_channels; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sales_channels IS 'One selling surface an order can originate from, including the storefront itself. Dormant until a later wave gives orders a channel.';


--
-- Name: COLUMN sales_channels.delivery_selection; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.sales_channels.delivery_selection IS 'How parcels sold on this surface ship, in the same object shape an order carries in metadata.selectedDelivery. Copied onto every order this surface ingests; an order is refused while it is NULL, because choosing a carrier silently for a parcel already paid for is not a default this shop is willing to have.';


--
-- Name: sample_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sample_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    pet_type text NOT NULL,
    dog_name text,
    dog_weight numeric,
    dog_weight_unit text DEFAULT 'kg'::text,
    cat_name text,
    cat_weight numeric,
    cat_weight_unit text DEFAULT 'kg'::text,
    first_name text NOT NULL,
    last_name text NOT NULL,
    email text NOT NULL,
    phone text NOT NULL,
    address text NOT NULL,
    postal_code text NOT NULL,
    city text NOT NULL,
    country text DEFAULT 'Poland'::text NOT NULL,
    consent boolean DEFAULT false NOT NULL,
    feedback text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sample_requests_pet_type_check CHECK ((pet_type = ANY (ARRAY['dog'::text, 'cat'::text, 'both'::text])))
);


--
-- Name: settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.settings (
    key text NOT NULL,
    value jsonb NOT NULL
);


--
-- Name: shipment_external_refs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.shipment_external_refs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    provider_kind text NOT NULL,
    provider_tracking_id text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tracking_url text,
    carrier_kind text,
    service text,
    fulfillment_order_id uuid
);


--
-- Name: COLUMN shipment_external_refs.active; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.shipment_external_refs.active IS 'Dual-run flag: an order can carry multiple tracking ids (one per carrier in flight). Carrier migration flips active rather than DROP + INSERT so audit retains the full shipment history.';


--
-- Name: COLUMN shipment_external_refs.tracking_url; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.shipment_external_refs.tracking_url IS 'Customer-safe carrier tracking URL projected into account order history.';


--
-- Name: COLUMN shipment_external_refs.carrier_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.shipment_external_refs.carrier_kind IS 'Customer-safe carrier identifier, for example dhl, inpost, or omnipack.';


--
-- Name: COLUMN shipment_external_refs.service; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.shipment_external_refs.service IS 'Customer-safe delivery service label, for example courier or parcel_locker.';


--
-- Name: COLUMN shipment_external_refs.fulfillment_order_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.shipment_external_refs.fulfillment_order_id IS 'The parcel this tracking reference was created for. NULL means unattributed, which every reader resolves as "belongs to whichever parcel is asking" - the answer readers gave before an order could hold more than one parcel.';


--
-- Name: shipping_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.shipping_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    region_code text NOT NULL,
    currency text NOT NULL,
    mode_at_cart text NOT NULL,
    carrier_kind text NOT NULL,
    free_threshold_minor integer,
    fixed_cost_minor integer,
    weight_threshold_g integer,
    delivery_estimate_days integer,
    priority integer DEFAULT 100 NOT NULL,
    vat_rate_bps integer DEFAULT 800 NOT NULL,
    vat_rate_kind text DEFAULT 'fixed'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT shipping_rules_check CHECK (((valid_to IS NULL) OR (valid_to > valid_from))),
    CONSTRAINT shipping_rules_currency_check CHECK ((char_length(currency) = 3)),
    CONSTRAINT shipping_rules_delivery_estimate_days_check CHECK (((delivery_estimate_days IS NULL) OR (delivery_estimate_days >= 0))),
    CONSTRAINT shipping_rules_fixed_cost_minor_check CHECK (((fixed_cost_minor IS NULL) OR (fixed_cost_minor >= 0))),
    CONSTRAINT shipping_rules_free_threshold_minor_check CHECK (((free_threshold_minor IS NULL) OR (free_threshold_minor >= 0))),
    CONSTRAINT shipping_rules_mode_at_cart_check CHECK ((mode_at_cart = ANY (ARRAY['one_time'::text, 'subscription'::text, 'any'::text]))),
    CONSTRAINT shipping_rules_region_code_check CHECK (((char_length(region_code) >= 2) AND (char_length(region_code) <= 3))),
    CONSTRAINT shipping_rules_vat_rate_bps_check CHECK (((vat_rate_bps >= 0) AND (vat_rate_bps <= 10000))),
    CONSTRAINT shipping_rules_vat_rate_kind_check CHECK ((vat_rate_kind = ANY (ARRAY['fixed'::text, 'inherit_main_goods'::text, 'highest_in_cart'::text]))),
    CONSTRAINT shipping_rules_weight_threshold_g_check CHECK (((weight_threshold_g IS NULL) OR (weight_threshold_g > 0)))
);


--
-- Name: COLUMN shipping_rules.mode_at_cart; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.shipping_rules.mode_at_cart IS '''one_time'' / ''subscription'' / ''any''. The resolver picks the most specific match for the cart''s primary intent — ''any'' is the fallback that catches everything else.';


--
-- Name: COLUMN shipping_rules.free_threshold_minor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.shipping_rules.free_threshold_minor IS 'If cart subtotal_minor >= free_threshold_minor the resolver returns amount=0. NULL means "never free for this rule" — combine with fixed_cost_minor to express ryczałt.';


--
-- Name: COLUMN shipping_rules.vat_rate_bps; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.shipping_rules.vat_rate_bps IS 'VAT rate snapshot the resolver attaches to reason_payload. The W4 breakdown shipping component records it so invoice generation can split shipping into net + VAT identically to product lines.';


--
-- Name: COLUMN shipping_rules.vat_rate_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.shipping_rules.vat_rate_kind IS 'fixed (default, uses vat_rate_bps verbatim), inherit_main_goods (resolver picks the dominant VAT rate from food lines), highest_in_cart (defensive accounting — always pick the highest rate any line carries). v1 ships fixed; the others activate when accessories at 23 percent join the catalog.';


--
-- Name: subscription_cycles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subscription_cycles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subscription_id uuid NOT NULL,
    cycle_number integer NOT NULL,
    scheduled_at timestamp with time zone,
    paid_at timestamp with time zone,
    status text DEFAULT 'planned'::text NOT NULL,
    order_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    template_version integer DEFAULT 1 NOT NULL,
    template_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    pricing_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    payment_id uuid,
    payment_method_ref text,
    retry_attempt integer DEFAULT 0 NOT NULL,
    next_retry_at timestamp with time zone,
    failure_reason text,
    engine_idempotency_key text NOT NULL,
    provider_attempt_sequence integer DEFAULT 0 NOT NULL,
    offer_policy_version text DEFAULT 'commerce.offer-policy.v1'::text NOT NULL,
    promotion_engine_version text DEFAULT 'promotion-engine.v1'::text NOT NULL,
    offer_policy_assignment_state text DEFAULT 'legacy_frozen'::text NOT NULL,
    renewal_row_error_key text,
    renewal_row_error_count integer DEFAULT 0 NOT NULL,
    renewal_quarantined_until timestamp with time zone,
    CONSTRAINT subscription_cycles_cycle_number_check CHECK ((cycle_number >= 0)),
    CONSTRAINT subscription_cycles_paid_at_check CHECK (((paid_at IS NULL) OR (status = 'paid'::text))),
    CONSTRAINT subscription_cycles_provider_attempt_sequence_check CHECK ((provider_attempt_sequence >= 0)),
    CONSTRAINT subscription_cycles_retry_attempt_check CHECK ((retry_attempt >= 0)),
    CONSTRAINT subscription_cycles_retry_state_check CHECK (((next_retry_at IS NULL) OR (status = ANY (ARRAY['payment_failed'::text, 'retry_scheduled'::text])))),
    CONSTRAINT subscription_cycles_status_check CHECK ((status = ANY (ARRAY['planned'::text, 'payment_pending'::text, 'paid'::text, 'payment_failed'::text, 'retry_scheduled'::text, 'skipped'::text, 'cancelled'::text]))),
    CONSTRAINT subscription_cycles_template_version_check CHECK ((template_version > 0))
);


--
-- Name: COLUMN subscription_cycles.template_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscription_cycles.template_snapshot IS 'Immutable subscription template snapshot used for this cycle/order. Future template edits never mutate it.';


--
-- Name: COLUMN subscription_cycles.pricing_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscription_cycles.pricing_snapshot IS 'Immutable pricing/promotion/shipping snapshot resolved at cycle generation time.';


--
-- Name: COLUMN subscription_cycles.engine_idempotency_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscription_cycles.engine_idempotency_key IS 'Engine-generated idempotency key used to prevent duplicate renewal/order/payment-intent creation.';


--
-- Name: COLUMN subscription_cycles.provider_attempt_sequence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscription_cycles.provider_attempt_sequence IS 'Provider execution sequence independent from retry_attempt. Increment only after operator/provider readback proves a prepared renewal attempt never reached Stripe/Tpay, so the next cron retry gets a fresh PSP idempotency key without burning customer dunning retry budget.';


--
-- Name: COLUMN subscription_cycles.renewal_row_error_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscription_cycles.renewal_row_error_key IS 'Last renewal batch row-error key seen for this cycle; NULL once a pass completes without throwing.';


--
-- Name: COLUMN subscription_cycles.renewal_row_error_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscription_cycles.renewal_row_error_count IS 'Consecutive renewal batch failures carrying the identical error key. Reset to 0 by any clean pass.';


--
-- Name: COLUMN subscription_cycles.renewal_quarantined_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.subscription_cycles.renewal_quarantined_until IS 'Renewal lane skips this cycle until this instant. Always a self-expiring TTL, never a terminal state.';


--
-- Name: subscription_delivery_alignment_admission_receipts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subscription_delivery_alignment_admission_receipts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    subscription_id uuid NOT NULL,
    scheduled_at timestamp with time zone NOT NULL,
    observed_next_cycle_at timestamp with time zone NOT NULL,
    decision text DEFAULT 'allowed'::text NOT NULL,
    source text NOT NULL,
    admitted_at timestamp with time zone DEFAULT now() NOT NULL,
    consumed_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT subscription_delivery_alignment_admission_receip_decision_check CHECK ((decision = 'allowed'::text)),
    CONSTRAINT subscription_delivery_alignment_admission_receipts_check CHECK (((consumed_at IS NULL) OR (consumed_at >= admitted_at))),
    CONSTRAINT subscription_delivery_alignment_admission_receipts_source_check CHECK ((source = 'renewal_admission'::text))
);


--
-- Name: TABLE subscription_delivery_alignment_admission_receipts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.subscription_delivery_alignment_admission_receipts IS 'One-time, schedule-bound authorization consumed by a protecting-mode payment_pending cycle insert. Created only by a successful due renewal admission.';


--
-- Name: subscription_delivery_alignment_cases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.subscription_delivery_alignment_cases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    fulfillment_order_id uuid,
    predecessor_order_id uuid NOT NULL,
    subscription_id uuid NOT NULL,
    predecessor_cycle_id uuid NOT NULL,
    predecessor_cycle_number integer NOT NULL,
    captured_mode text NOT NULL,
    state text NOT NULL,
    evidence_kind text NOT NULL,
    observed_next_cycle_at timestamp with time zone,
    delivered_at timestamp with time zone,
    aligned_next_cycle_at timestamp with time zone,
    manual_review_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
