    CONSTRAINT subscription_delivery_alignment__predecessor_cycle_number_check CHECK ((predecessor_cycle_number >= 1)),
    CONSTRAINT subscription_delivery_alignment_cases_captured_mode_check CHECK ((captured_mode = ANY (ARRAY['shadow'::text, 'protect'::text, 'auto_align'::text]))),
    CONSTRAINT subscription_delivery_alignment_cases_check CHECK ((((state = 'manual_review'::text) AND (manual_review_reason IS NOT NULL)) OR (state <> 'manual_review'::text))),
    CONSTRAINT subscription_delivery_alignment_cases_check1 CHECK ((((state = 'aligned'::text) AND (aligned_next_cycle_at IS NOT NULL) AND (aligned_at IS NOT NULL)) OR (state <> 'aligned'::text))),
    CONSTRAINT subscription_delivery_alignment_cases_evidence_kind_check CHECK ((evidence_kind = ANY (ARRAY['fulfillment_exception'::text, 'overdue_renewal'::text, 'missing_fulfillment'::text]))),
    CONSTRAINT subscription_delivery_alignment_cases_state_check CHECK ((state = ANY (ARRAY['shadow'::text, 'protected'::text, 'aligned'::text, 'released'::text, 'manual_review'::text])))
);


