--
-- Name: subscription_paid_activation_gaps; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.subscription_paid_activation_gaps WITH (security_invoker='true') AS
 WITH candidates AS (
         SELECT s.id AS subscription_id,
            s.client_id,
            o.id AS order_id,
            i.id AS payment_intent_id,
            i.active_attempt_id AS payment_attempt_id,
            sc.paid_at,
            count(*) OVER (PARTITION BY s.id) AS candidate_count
           FROM (((((public.subscriptions s
             JOIN public.commerce_payment_intents i ON (((i.subscription_id = s.id) AND (i.target_kind = 'subscription_cycle'::text) AND (i.status = 'succeeded'::text))))
             JOIN public.commerce_payment_attempts a ON (((a.id = i.active_attempt_id) AND (a.payment_intent_id = i.id) AND (a.provider = 'tpay'::text) AND (a.status = 'succeeded'::text) AND ((a.request_payload ->> 'providerFlow'::text) = 'blik_recurring_activation'::text) AND ((a.request_payload ->> 'recurringModel'::text) = 'O'::text))))
             JOIN public.commerce_orders o ON (((o.id = i.order_id) AND (o.subscription_id = s.id) AND (o.mode = 'subscription_cycle'::text) AND (o.status = 'paid'::text))))
             JOIN public.subscription_cycles sc ON (((sc.id = o.subscription_cycle_id) AND (sc.subscription_id = s.id) AND (sc.cycle_number = 1) AND (sc.status = 'paid'::text) AND (sc.paid_at IS NOT NULL))))
             JOIN public.commerce_payments p ON (((p.id = i.payment_id) AND (p.order_id = o.id) AND (p.status = 'succeeded'::text))))
          WHERE ((s.status = 'pending_activation'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM public.commerce_payment_method_refs pm
                  WHERE ((pm.subscription_id = s.id) AND (pm.status = 'active'::text) AND (pm.active = true))))))
        )
 SELECT subscription_id,
    client_id,
    order_id,
    payment_intent_id,
    payment_attempt_id,
    paid_at
   FROM candidates
  WHERE (candidate_count = 1);


--
-- Name: subscription_method_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.subscription_method_health WITH (security_invoker='true') AS
 SELECT s.id AS subscription_id,
    s.client_id,
    s.status AS subscription_status,
    s.next_cycle_at,
    m.id AS payment_method_ref_id,
    m.provider_kind,
    m.method_kind,
    m.expires_at AS method_expires_at,
        CASE
            WHEN ((s.status = 'pending_activation'::text) AND (m.id IS NULL)) THEN 'activation_gap'::text
            WHEN (m.id IS NULL) THEN 'method_missing'::text
            WHEN (((m.consent_snapshot ->> 'recurringModel'::text) IS NOT NULL) AND ((m.consent_snapshot ->> 'recurringModel'::text) <> 'O'::text)) THEN 'mandate_not_chargeable_unattended'::text
            WHEN (((m.consent_snapshot ->> 'recurringModel'::text) IS NULL) AND (m.method_kind <> 'card'::text)) THEN 'mandate_not_chargeable_unattended'::text
            WHEN ((m.expires_at IS NOT NULL) AND (m.expires_at <= (now() + '30 days'::interval))) THEN 'method_expiring'::text
            ELSE 'healthy'::text
        END AS health_state,
    (g.subscription_id IS NOT NULL) AS narrow_activation_gap
   FROM ((public.subscriptions s
     LEFT JOIN public.commerce_payment_method_refs m ON (((m.subscription_id = s.id) AND (m.client_id = s.client_id) AND (m.status = 'active'::text) AND (m.active = true))))
     LEFT JOIN public.subscription_paid_activation_gaps g ON ((g.subscription_id = s.id)))
  WHERE (s.status = ANY (ARRAY['active'::text, 'pending_activation'::text]));


--
-- Name: VIEW subscription_method_health; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.subscription_method_health IS 'Every active and pending_activation subscription in exactly one health state. A stored mandate is chargeable unattended only when it declares the unattended-eligible model; an absent model is unchargeable on a mandate-backed method kind and says nothing on a card.';


