--
-- Name: subscription_retention_outcomes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.subscription_retention_outcomes AS
 SELECT id AS event_id,
    subscription_id,
    event_type,
    occurred_at,
    NULLIF((payload #>> '{payload,survey,reasonCode}'::text[]), ''::text) AS cancel_reason_code,
    NULLIF((payload #>> '{payload,survey,comment}'::text[]), ''::text) AS cancel_comment,
    NULLIF((payload #>> '{payload,survey,acceptedSaveOfferId}'::text[]), ''::text) AS accepted_save_offer_id,
    NULLIF((payload #>> '{payload,saveOffer,offerId}'::text[]), ''::text) AS save_offer_id,
    NULLIF((payload #>> '{payload,saveOffer,kind}'::text[]), ''::text) AS save_offer_kind,
        CASE
            WHEN ((payload #>> '{payload,saveOffer,accepted}'::text[]) = 'true'::text) THEN true
            WHEN ((payload #>> '{payload,saveOffer,accepted}'::text[]) = 'false'::text) THEN false
            ELSE NULL::boolean
        END AS save_offer_accepted,
    NULLIF((payload #>> '{payload,saveOffer,externalOfferRef}'::text[]), ''::text) AS external_offer_ref
   FROM public.subscription_events e
  WHERE ((event_type = ANY (ARRAY['subscription.customer_self_service.cancel'::text, 'subscription.customer_self_service.pause'::text])) AND (((payload #> '{payload,survey}'::text[]) IS NOT NULL) OR ((payload #> '{payload,saveOffer}'::text[]) IS NOT NULL)));


--
-- Name: VIEW subscription_retention_outcomes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.subscription_retention_outcomes IS 'Queryable subscription-owned cancellation survey and retention outcome read model. No promo internals or duplicated subscription state.';


--
-- Name: subscription_save_offer_funnel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.subscription_save_offer_funnel AS
 SELECT COALESCE(save_offer_kind, 'unknown'::text) AS save_offer_kind,
    COALESCE(cancel_reason_code, 'unknown'::text) AS cancel_reason_code,
    count(*) FILTER (WHERE (save_offer_id IS NOT NULL)) AS offered,
    count(*) FILTER (WHERE (save_offer_accepted IS TRUE)) AS accepted,
    count(*) FILTER (WHERE (save_offer_accepted IS FALSE)) AS declined,
    round(((count(*) FILTER (WHERE (save_offer_accepted IS TRUE)))::numeric / (NULLIF(count(*) FILTER (WHERE (save_offer_id IS NOT NULL)), 0))::numeric), 4) AS accept_rate
   FROM public.subscription_retention_outcomes o
  WHERE (save_offer_id IS NOT NULL)
  GROUP BY COALESCE(save_offer_kind, 'unknown'::text), COALESCE(cancel_reason_code, 'unknown'::text);


--
-- Name: VIEW subscription_save_offer_funnel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.subscription_save_offer_funnel IS 'Save-offer funnel per kind/reason (offered/accepted/declined/accept_rate) from subscription_retention_outcomes. Service-role read model; no promo internals.';


--
-- Name: subscription_save_retention_90d; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.subscription_save_retention_90d AS
 SELECT o.event_id,
    o.subscription_id,
    o.occurred_at AS saved_at,
    o.save_offer_kind,
    o.cancel_reason_code,
    s.status AS current_status,
    s.ended_at,
    (now() >= (o.occurred_at + '90 days'::interval)) AS window_elapsed,
        CASE
            WHEN ((s.ended_at IS NOT NULL) AND (s.ended_at <= (o.occurred_at + '90 days'::interval))) THEN false
            WHEN (now() < (o.occurred_at + '90 days'::interval)) THEN NULL::boolean
            ELSE true
        END AS retained_90d
   FROM (public.subscription_retention_outcomes o
     JOIN public.subscriptions s ON ((s.id = o.subscription_id)))
  WHERE (o.save_offer_accepted IS TRUE);


--
-- Name: VIEW subscription_save_retention_90d; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.subscription_save_retention_90d IS 'Per accepted save: 90-day retention outcome (true survived / false churned-in-window / NULL pending). Separates true saves from deferred churn.';


